local function direct_call(fn, ...)
    -- Build 296: production code no longer suppresses runtime errors through direct_call.
    -- Capability checks should happen before calling optional Cherax APIs. A missing
    -- function is reported as unavailable; an error raised by a real function remains
    -- visible instead of being silently swallowed.
    if type(fn) ~= "function" then
        return false, "call target unavailable"
    end
    return true, fn(...)
end

-- Build 325: ClickGUI render guard. Render callbacks are special: one Lua error inside
-- Cherax's tab callback can permanently kill that tab coroutine, after which Cherax logs
-- "cannot resume dead coroutine" every frame. Keep normal runtime errors visible elsewhere,
-- but contain ClickGUI feature-render failures inside the render frame.
startup.render_guard_325 = startup.render_guard_325 or {
    last_error = "",
    last_context = "",
    last_log_ms = 0,
    suppressed = 0,
    last_gui_open = nil,
    recovered = false,
}

function startup.render_feature_guarded_325(feature, context)
    if not ClickGUI or type(ClickGUI.RenderFeature) ~= "function" or feature == nil then return false end
    local ok, result = pcall(ClickGUI.RenderFeature, feature)
    if ok then return true, result end

    local rg = startup.render_guard_325
    rg.suppressed = (tonumber(rg.suppressed or 0) or 0) + 1
    rg.last_error = tostring(result or "unknown ClickGUI.RenderFeature error")
    rg.last_context = tostring(context or feature or "feature")
    local now = 0
    if Time and Time.GetEpocheMs then
        local okNow, value = direct_call(Time.GetEpocheMs)
        if okNow then now = tonumber(value or 0) or 0 end
    end
    if now <= 0 then now = math.floor((os.clock and os.clock() or 0) * 1000) end
    if (now - (tonumber(rg.last_log_ms or 0) or 0)) >= 1000 then
        rg.last_log_ms = now
        if startup.log then
            direct_call(startup.log, "[Startup 325][CLICKGUI_RENDER_FEATURE_RECOVERED] context="..rg.last_context.." error="..rg.last_error)
        end
    end
    return false, result
end

function startup.clickgui_render_allowed_325()
    if GUI and type(GUI.IsOpen) == "function" then
        local ok, isOpen = pcall(GUI.IsOpen)
        if ok then
            local rg = startup.render_guard_325
            rg.last_gui_open = isOpen == true
            -- Cherax may invoke a Lua tab callback during the close transition. Do not touch
            -- ImGui/FeatureMgr once the ClickGUI reports closed.
            if isOpen ~= true then return false end
        end
    end
    return true
end

