function startup.session_activity_snap_native_feed(enabled)
    if not Natives or not Natives.InvokeVoid then return false end
    local value = enabled == true
    local ok = direct_call(function() Natives.InvokeVoid(0xBAE4F9B97CD43B30, value) end) -- THEFEED_SET_SNAP_FEED_ITEM_POSITIONS
    if ok then startup.session_activity.nativeTracker.snapEnabled = value end
    return ok
