function startup.session_activity_read_position_member(object, names)
    if object == nil then return nil end
    for _, name in ipairs(names or {}) do
        local ok, value = direct_call(function() return object[name] end)
        if ok and value ~= nil then
            if type(value) == "function" then
                local callOk, result = direct_call(value, object)
                if callOk and result ~= nil then return tonumber(result) end
            else
                local number = tonumber(value)
                if number ~= nil then return number end
            end
        end
    end
    return nil
end

function startup.session_activity_resolve_live_native_y(position, displayHeight)
    if position == nil then return nil end
    local kind = type(position)
    local y = nil
    if kind == "table" or kind == "userdata" then
        y = startup.session_activity_read_position_member(position, {
            "y", "Y", "top", "Top", "screenY", "ScreenY", "posY", "PosY",
            "GetY", "getY", "GetTop", "getTop", "GetScreenY", "getScreenY"
        })
        if y == nil and kind == "table" then
            y = tonumber(position[2])
            if y == nil and type(position.position) == "table" then
                y = tonumber(position.position.y or position.position.Y or position.position[2])
            end
        end
    elseif kind == "number" then
        -- A bare integer is usually an enum/slot, not a screen coordinate. Accept only
        -- normalized fractional values here; the ordered shadow queue handles slot enums.
        local value = tonumber(position)
        if value and value > 0 and value < 1 and value ~= math.floor(value) then y = value end
    end
    if y == nil then return nil end
    if y > 1 and tonumber(displayHeight or 0) > 0 then y = y / displayHeight end
    if y < 0.01 or y > 0.98 then return nil end
    return y
end

function startup.session_activity_make_unique_anchor_spacer(serial, slotIndex)
    -- Build 164: the stable ID is kept entirely inside Startup. GTA receives only a
    -- normal whitespace row, so internal identifiers such as STARTUP_ANCHOR_* can never
    -- appear on screen. Per-row identity comes from the returned notification handle.
    return " "
end

function startup.session_activity_capture_native_anchor_position(title, message, nativePosition, notificationId)
    local titleRaw = tostring(title or "")
    local messageRaw = tostring(message or "")
    local numericId = tonumber(notificationId)
    local now = startup.now()
    local token = numericId ~= nil and startup.session_activity.nativeAnchorByNotificationId[numericId] or nil

    -- Legacy token lookup remains for old in-memory rows during a hot reload, but Build
    -- 164 no longer sends internal token text to GTA.
    token = token or startup.session_activity.nativeAnchorTokens[titleRaw]
        or startup.session_activity.nativeAnchorTokens[messageRaw]

    local function blankish(value)
        local raw = tostring(value or "")
        raw = raw:gsub("~.-~", ""):gsub("[%s%c]", "")
        return raw == ""
    end

    local pending = startup.session_activity.pendingNativeAnchorTokens or {}
    local kept = {}
    local pendingMatch = nil
    for _, candidate in ipairs(pending) do
        local valid = type(candidate) == "table"
            and type(candidate.entry) == "table"
            and candidate.entry.nativeSlotReleased ~= true
            and (tonumber(candidate.pendingUntilMs or 0) or 0) >= now
        local sameToken = token ~= nil and candidate == token
        if valid and pendingMatch == nil and (sameToken
            or (token == nil
                and now <= (tonumber(startup.session_activity.nativeAnchorArtifactGuardUntilMs or 0) or 0)
                and blankish(titleRaw) and blankish(messageRaw))) then
            pendingMatch = candidate
        elseif valid then
            kept[#kept + 1] = candidate
        end
    end
    startup.session_activity.pendingNativeAnchorTokens = kept
    token = token or pendingMatch

    if type(token) ~= "table" or type(token.entry) ~= "table" then return false end

    local entry = token.entry
    if entry.nativeSlotReleased == true then return false end
    local slot = math.max(1, tonumber(token.slot or 1) or 1)
    local stableId = tostring(token.anchorId or "")

    entry.nativeAnchorPositionObjects = type(entry.nativeAnchorPositionObjects) == "table" and entry.nativeAnchorPositionObjects or {}
    entry.nativeAnchorObservedIds = type(entry.nativeAnchorObservedIds) == "table" and entry.nativeAnchorObservedIds or {}
    entry.nativeAnchorObservedMsBySlot = type(entry.nativeAnchorObservedMsBySlot) == "table" and entry.nativeAnchorObservedMsBySlot or {}
    entry.nativeAnchorStableIds = type(entry.nativeAnchorStableIds) == "table" and entry.nativeAnchorStableIds or {}

    if nativePosition ~= nil then entry.nativeAnchorPositionObjects[slot] = nativePosition end
    if numericId ~= nil then
        entry.nativeAnchorObservedIds[slot] = numericId
        startup.session_activity.nativeAnchorByNotificationId[numericId] = token
    end
    if stableId ~= "" then
        entry.nativeAnchorStableIds[slot] = stableId
        startup.session_activity.nativeAnchorByStableId[stableId] = token
    end
    entry.nativeAnchorObservedMsBySlot[slot] = now

    -- Keep legacy scalar fields for diagnostics and compatibility with older code paths.
    entry.nativeAnchorPositionObject = entry.nativeAnchorPositionObjects[slot] or entry.nativeAnchorPositionObject
    entry.nativeAnchorObservedId = numericId or entry.nativeAnchorObservedId
    entry.nativeAnchorObservedMs = now
    entry.nativeAnchorObservedSlot = slot
    startup.session_activity.nativeTracker.lastExactPositionMs = now
    startup.session_activity.nativeTracker.observedAnchors = (tonumber(startup.session_activity.nativeTracker.observedAnchors or 0) or 0) + 1
    startup.session_activity.nativeTracker.lastMode = "Per-anchor notification ID"
    return true
end

function startup.session_activity_native_slot_height(scale)
    local value = tonumber(scale or startup.s.sessionActivityScale or 0.44) or 0.44
    return startup.clamp_float(value * 0.176, 0.054, 0.082)
end

function startup.session_activity_native_anchor_slot_count(entry)
    if type(entry) ~= "table" then return 1 end
    local secondary = ""
    if startup.session_activity_content then
        local _, resolvedSecondary = startup.session_activity_content(entry)
        secondary = tostring(resolvedSecondary or "")
    end
    return secondary ~= "" and 2 or 1
end

function startup.session_activity_remove_native_item(notificationId)
    local id = tonumber(notificationId)
    if id == nil or id < 0 or not Natives or not Natives.InvokeVoid then return false end
    local ok = direct_call(function() Natives.InvokeVoid(0xBE4390CB40B3E627, id) end)
    return ok
end

function startup.session_activity_release_native_slots(entry)
    if type(entry) ~= "table" or entry.nativeSlotReleased == true then return end
    entry.nativeSlotReleased = true
    local ids = type(entry.nativeSlotIds) == "table" and entry.nativeSlotIds or {}
    entry.nativeSlotIds = {}

    for _, tokenText in ipairs(type(entry.nativeAnchorTokenTexts) == "table" and entry.nativeAnchorTokenTexts or {}) do
        startup.session_activity.nativeAnchorTokens[tokenText] = nil
    end
    entry.nativeAnchorTokenTexts = {}

    local pendingKept = {}
    for _, candidate in ipairs(startup.session_activity.pendingNativeAnchorTokens or {}) do
        if type(candidate) ~= "table" or candidate.entry ~= entry then pendingKept[#pendingKept + 1] = candidate end
    end
    startup.session_activity.pendingNativeAnchorTokens = pendingKept

    for _, stableId in ipairs(type(entry.nativeAnchorStableIds) == "table" and entry.nativeAnchorStableIds or {}) do
        if tostring(stableId or "") ~= "" then startup.session_activity.nativeAnchorByStableId[stableId] = nil end
    end
    entry.nativeAnchorStableIds = {}

    for _, notificationId in ipairs(ids) do
        local id = tonumber(notificationId)
        if id ~= nil then startup.session_activity.nativeAnchorByNotificationId[id] = nil end
    end
    entry.nativeAnchorPositionObjects = {}
    entry.nativeAnchorObservedIds = {}
    entry.nativeAnchorObservedMsBySlot = {}

    if #ids == 0 then return end
    local function remove_all()
        for _, notificationId in ipairs(ids) do startup.session_activity_remove_native_item(notificationId) end
    end
    if Script and Script.QueueJob then Script.QueueJob(remove_all) else remove_all() end
end

function startup.session_activity_clear_native_slots()
    for _, entry in ipairs(startup.session_activity.entries or {}) do
        startup.session_activity_release_native_slots(entry)
    end
    startup.session_activity.nativeAnchorTokens = {}
    startup.session_activity.nativeAnchorByNotificationId = {}
    startup.session_activity.nativeAnchorByStableId = {}
    startup.session_activity.pendingNativeAnchorTokens = {}
    startup.session_activity_snap_native_feed(false)
end

function startup.session_activity_queue_native_slots(entry)
    if type(entry) ~= "table" then return false end
    if startup.session_activity_native_anchor_posts_disabled == true then
        entry.nativeAnchorPending = false
        entry.nativeAnchorReady = false
        entry.nativeAnchorFailed = false
        entry.nativeSlotIds = {}
        return false
    end
    if startup.s.sessionActivityUseNativeFeed ~= false then return false end
    if startup.s.sessionActivityPlacementMode == "Above Session HUD Stack" then return false end
    if startup.s.sessionActivityNativeSlotBridge == false then return false end
    if not Script or not Script.QueueJob or not Natives or not Natives.InvokeVoid or not Natives.InvokeInt then
        entry.nativeAnchorFailed = true
        return false
    end

    startup.session_activity.nativeAnchorSerial = (tonumber(startup.session_activity.nativeAnchorSerial or 0) or 0) + 1
    local serial = startup.session_activity.nativeAnchorSerial
    local slots = startup.session_activity_native_anchor_slot_count(entry)
    entry.nativeAnchorSlots = slots
    entry.nativeAnchorPending = true
    entry.nativeSlotReleased = false
    entry.nativeAnchorOrder = startup.session_activity_next_feed_order()
    entry.nativeAnchorId = string.format("SA-%08d", serial)
    entry.nativeAnchorTokenTexts = {}
    entry.nativeAnchorStableIds = {}
    entry.nativeAnchorPositionObjects = {}
    entry.nativeAnchorObservedIds = {}
    entry.nativeAnchorObservedMsBySlot = {}

    Script.QueueJob(function()
        if entry.nativeSlotReleased == true or (tonumber(entry.expiresMs or 0) or 0) <= startup.now() then
            entry.nativeAnchorPending = false
            return
        end

        -- GTA can display the native join / leave card before Cherax finishes the
        -- notification callback. Wait briefly for that exact card to be hidden before
        -- posting our blank anchor, otherwise a late remove-last call can delete the
        -- blank anchor and leave GTA's original card visible.
        local entryKind = tostring(entry.kind or "")
        if startup.s.hideNativeJoinLeaveNotifications == true
            and (entryKind == "joining" or entryKind == "left")
            and Script and Script.Yield then
            local normalizedName = startup.session_activity_normalize_notification_text(entry.name)
            local deadline = startup.now() + 950
            while startup.now() < deadline do
                local token = startup.session_activity.nativeSuppressTokens[normalizedName]
                local guard = startup.session_activity.nativeRemovalGuards[normalizedName]
                local removalFinished = type(token) == "table" and tonumber(token.removalFinishedAtMs or 0) > 0
                removalFinished = removalFinished or (type(guard) == "table" and tonumber(guard.finishedAtMs or 0) > 0)
                if removalFinished then break end
                Script.Yield(25)
                if entry.nativeSlotReleased == true or (tonumber(entry.expiresMs or 0) or 0) <= startup.now() then
                    entry.nativeAnchorPending = false
                    return
                end
            end
            -- Give GTA one additional frame to retire the removed native card before
            -- creating Startup's visually blank replacement slot.
            if Script.Yield then Script.Yield(45) end
        end

        entry.nativeAnchorCreatedMs = startup.now()
        entry.nativeSlotIds = entry.nativeSlotIds or {}
        if startup.s.sessionActivityTrackNativeSlots ~= false then startup.session_activity_snap_native_feed(true) end
        for slotIndex = 1, slots do
            local notificationId = nil
            local stableId = entry.nativeAnchorId .. ":" .. tostring(slotIndex)
            local spacer = startup.session_activity_make_unique_anchor_spacer(serial, slotIndex)
            local token = { entry = entry, slot = slotIndex, serial = serial, anchorId = stableId }

            entry.nativeAnchorStableIds[slotIndex] = stableId
            startup.session_activity.nativeAnchorByStableId[stableId] = token
            token.pendingUntilMs = startup.now() + 1500
            startup.session_activity.pendingNativeAnchorTokens[#startup.session_activity.pendingNativeAnchorTokens + 1] = token

            startup.session_activity.nativeAnchorArtifactGuardUntilMs = startup.now() + 1500
            local ok = direct_call(function()
                -- Build 164: post a genuinely blank native row. The stable Startup ID is
                -- never placed in the GTA text component; the returned feed handle is the
                -- public/native identity and the pending queue covers synchronous callbacks.
                Natives.InvokeVoid(0x202709F4C58A0424, "STRING")
                Natives.InvokeVoid(0x6C188BE134E074AA, spacer)
                notificationId = Natives.InvokeInt(0x2ED7843F8F801023, false, false)
                Natives.InvokeVoid(0xFDD85225B2DEA55E)
            end)
            -- Always clear next-message parameters even if one native in the post failed.
            direct_call(function() Natives.InvokeVoid(0xFDD85225B2DEA55E) end)
            if ok and tonumber(notificationId) ~= nil and tonumber(notificationId) >= 0 then
                local id = tonumber(notificationId)
                entry.nativeSlotIds[slotIndex] = id
                entry.nativeAnchorObservedIds[slotIndex] = id
                startup.session_activity.nativeAnchorByNotificationId[id] = token
            end
        end
        entry.nativeAnchorPending = false
        entry.nativeAnchorReady = #entry.nativeSlotIds > 0
        entry.nativeAnchorFailed = not entry.nativeAnchorReady
    end)
    return true
end

function startup.session_activity_rebuild_native_slots()
    startup.session_activity_clear_native_slots()
    for _, entry in ipairs(startup.session_activity.entries or {}) do
        entry.nativeSlotReleased = false
        entry.nativeAnchorReady = false
        entry.nativeAnchorFailed = false
        entry.nativeAnchorPending = false
        entry.nativeSlotIds = {}
        startup.session_activity_queue_native_slots(entry)
    end
end

function startup.session_activity_normalize_notification_text(value)
    local text = tostring(value or "")
    text = text:gsub("~.-~", " "):gsub("[\r\n]", " "):gsub("[%c]", " ")
    text = text:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    text = string.lower(text)
    text = text:gsub("[%.%!%?]+$", "")
    return text
end

function startup.session_activity_is_blank_debug_anchor_artifact(title, message)
    if startup.now() > (tonumber(startup.session_activity.nativeAnchorArtifactGuardUntilMs or 0) or 0) then return false end
    local normalizedTitle = startup.session_activity_normalize_notification_text(title)
    local normalizedMessage = startup.session_activity_normalize_notification_text(message)
    return normalizedTitle == "debug" and normalizedMessage == ""
end

function startup.session_activity_safe_notification_member(object, memberNames, invoke)
    if object == nil then return nil end
    for _, memberName in ipairs(memberNames or {}) do
        local ok, value = direct_call(function() return object[memberName] end)
        if ok and value ~= nil then
            if invoke == true and type(value) == "function" then
                local callOk, result = direct_call(value, object)
                if callOk and result ~= nil then return result end
            elseif invoke ~= true and type(value) ~= "function" then
                return value
            end
        end
    end
    return nil
end

function startup.session_activity_unpack_notification(notificationOrTitle, message, duration, position)
    local objectType = type(notificationOrTitle)
    if objectType ~= "table" and objectType ~= "userdata" then
        return notificationOrTitle, message, duration, position, nil, nil
    end

    local object = notificationOrTitle
    local title = startup.session_activity_safe_notification_member(object,
        {"Title", "title", "Header", "header", "Caption", "caption", "Label", "label", "NotificationTitle", "notificationTitle", "Subject", "subject"}, false)
        or startup.session_activity_safe_notification_member(object,
            {"GetTitle", "getTitle", "GetHeader", "getHeader", "GetCaption", "getCaption", "GetLabel", "getLabel", "GetNotificationTitle", "getNotificationTitle", "GetSubject", "getSubject"}, true)
        or ""
    local body = startup.session_activity_safe_notification_member(object,
        {"Text", "text", "Message", "message", "Subtitle", "subtitle", "Body", "body", "Content", "content", "Description", "description", "NotificationText", "notificationText", "MessageText", "messageText"}, false)
        or startup.session_activity_safe_notification_member(object,
            {"GetText", "getText", "GetMessage", "getMessage", "GetSubtitle", "getSubtitle", "GetBody", "getBody", "GetContent", "getContent", "GetDescription", "getDescription", "GetNotificationText", "getNotificationText", "GetMessageText", "getMessageText"}, true)
        or message
        or ""
    local nativeDuration = startup.session_activity_safe_notification_member(object, {"Duration", "duration", "Time", "time"}, false)
        or startup.session_activity_safe_notification_member(object, {"GetDuration", "getDuration", "GetTime", "getTime"}, true)
        or duration
    local nativePosition = startup.session_activity_safe_notification_member(object, {"Position", "position"}, false)
        or startup.session_activity_safe_notification_member(object, {"GetPosition", "getPosition"}, true)
        or position
    local notificationId = startup.session_activity_safe_notification_member(object,
        {"Id", "ID", "id", "NotificationId", "notificationId", "NotificationID", "notificationID", "Handle", "handle", "FeedId", "feedId", "FeedID", "feedID", "Index", "index"}, false)
        or startup.session_activity_safe_notification_member(object,
            {"GetId", "getId", "GetID", "getID", "GetNotificationId", "getNotificationId", "GetNotificationID", "getNotificationID", "GetHandle", "getHandle", "GetFeedId", "getFeedId", "GetFeedID", "getFeedID", "GetIndex", "getIndex"}, true)
    notificationId = tonumber(notificationId)
    return title, body, nativeDuration, nativePosition, object, notificationId
end

function startup.session_activity_hide_notification_object(object)
    if object == nil then return false end
    local hidden = false

    -- Cherax notification wrappers have changed shape across builds. Try the harmless
    -- dismissal names first, then visibility/duration setters and writable properties.
    for _, methodName in ipairs({"Hide", "hide", "Dismiss", "dismiss", "Remove", "remove", "Close", "close", "Cancel", "cancel"}) do
        local ok, method = direct_call(function() return object[methodName] end)
        if ok and type(method) == "function" then
            local callOk = direct_call(method, object)
            if callOk then hidden = true end
        end
    end
    for _, methodName in ipairs({"SetVisible", "setVisible", "SetEnabled", "setEnabled"}) do
        local ok, method = direct_call(function() return object[methodName] end)
        if ok and type(method) == "function" then
            local callOk = direct_call(method, object, false)
            if callOk then hidden = true end
        end
    end
    for _, methodName in ipairs({"SetHidden", "setHidden"}) do
        local ok, method = direct_call(function() return object[methodName] end)
        if ok and type(method) == "function" then
            local callOk = direct_call(method, object, true)
            if callOk then hidden = true end
        end
    end
    for _, methodName in ipairs({"SetDuration", "setDuration", "SetTime", "setTime"}) do
        local ok, method = direct_call(function() return object[methodName] end)
        if ok and type(method) == "function" then
            local callOk = direct_call(method, object, 0)
            if callOk then hidden = true end
        end
    end

    local writes = {
        {"Visible", false}, {"visible", false}, {"Enabled", false}, {"enabled", false},
        {"Hidden", true}, {"hidden", true}, {"Duration", 0}, {"duration", 0},
        {"Time", 0}, {"time", 0}
    }
    for _, write in ipairs(writes) do
        local ok = direct_call(function() object[write[1]] = write[2] end)
        if ok then hidden = true end
    end
    return hidden
end

function startup.session_activity_get_last_shown_feed_item()
    if not Natives or not Natives.InvokeInt then return nil end
    local notificationId = nil
    local ok = direct_call(function()
        notificationId = Natives.InvokeInt(0x82352748437638CA)
    end)
    notificationId = tonumber(notificationId)
    if not ok or notificationId == nil or notificationId < 0 then return nil end
    return notificationId
end

function startup.session_activity_remove_last_shown_feed_item()
    local notificationId = startup.session_activity_get_last_shown_feed_item()
    if notificationId == nil then return false end
    return startup.session_activity_remove_native_item(notificationId)
end

function startup.session_activity_schedule_native_join_leave_removal(kind, name, notificationId)
    -- Build 285 safety: disabled. We do not have a reliable generic GTA joined/left
    -- notification handle from ON_PLAYER_JOIN / ON_PLAYER_LEFT. The previous fallback
    -- used THEFEED_GET_LAST_SHOWN_PHONE_ACTIVATABLE_FEED_ID (0x82352748437638CA),
    -- which is NOT a generic "last feed item" accessor. Passing that result into
    -- THEFEED_REMOVE_ITEM can surface Cherax's empty resizable DEBUG window.
    -- Preserve the normal GTA notice rather than deleting an unrelated/invalid item.
    return false
end

function startup.session_activity_extract_native_join_leave(value)
    local text = startup.session_activity_normalize_notification_text(value)
    if text == "" then return nil, nil end

    local joiningName = text:match("^([%w_%.%-]+) is joining$")
        or text:match("^([%w_%.%-]+) joined$")
        or text:match("^([%w_%.%-]+) has joined$")
        or text:match("^([%w_%.%-]+) joined the session$")
        or text:match("^([%w_%.%-]+) has joined the session$")
    if joiningName ~= nil and #joiningName >= 1 and #joiningName <= 64 then
        return joiningName, "joining"
    end

    local leftName = text:match("^([%w_%.%-]+) left$")
        or text:match("^([%w_%.%-]+) has left$")
        or text:match("^([%w_%.%-]+) left the session$")
        or text:match("^([%w_%.%-]+) has left the session$")
    if leftName ~= nil and #leftName >= 1 and #leftName <= 64 then
        return leftName, "left"
    end
    return nil, nil
end

function startup.session_activity_is_pure_join_leave_sentence(value)
    local name = startup.session_activity_extract_native_join_leave(value)
    return name ~= nil
end

function startup.session_activity_mark_native_join_leave(kind, name)
    local normalizedName = startup.session_activity_normalize_notification_text(name)
    if normalizedName == "" then return end
    local now = startup.now()
    local existing = startup.session_activity.nativeSuppressTokens[normalizedName]
    startup.session_activity.nativeSuppressTokens[normalizedName] = {
        kind = tostring(kind or (type(existing) == "table" and existing.kind) or ""),
        expiresMs = now + 12000,
        suppressedAtMs = type(existing) == "table" and existing.suppressedAtMs or nil,
        notificationId = type(existing) == "table" and existing.notificationId or nil,
        removalFinishedAtMs = type(existing) == "table" and existing.removalFinishedAtMs or nil
    }
end

function startup.session_activity_mark_native_join_leave_suppressed(title, message, notificationId)
    local now = startup.now()
    local matched = false
    local candidates = { title, message }

    for _, value in ipairs(candidates) do
        local normalizedName, kind = startup.session_activity_extract_native_join_leave(value)
        if normalizedName ~= nil then
            local existing = startup.session_activity.nativeSuppressTokens[normalizedName]
            startup.session_activity.nativeSuppressTokens[normalizedName] = {
                kind = tostring(kind or (type(existing) == "table" and existing.kind) or ""),
                expiresMs = now + 12000,
                suppressedAtMs = now,
                notificationId = tonumber(notificationId) or (type(existing) == "table" and existing.notificationId) or nil,
                removalFinishedAtMs = type(existing) == "table" and existing.removalFinishedAtMs or nil
            }
            matched = true
        end
    end

    for normalizedName, token in pairs(startup.session_activity.nativeSuppressTokens or {}) do
        local kind = tostring(type(token) == "table" and token.kind or "")
        for _, value in ipairs(candidates) do
            if startup.session_activity_native_message_matches(kind, normalizedName, value) then
                token.suppressedAtMs = now
                token.notificationId = tonumber(notificationId) or token.notificationId
                token.expiresMs = now + 12000
                matched = true
            end
        end
    end
    return matched
end

function startup.session_activity_prune_native_state()
    local now = startup.now()
    for name, token in pairs(startup.session_activity.nativeSuppressTokens or {}) do
        if type(token) ~= "table" or (tonumber(token.expiresMs or 0) or 0) <= now then
            startup.session_activity.nativeSuppressTokens[name] = nil
        end
    end
    for key, expiresMs in pairs(startup.session_activity.nativePostedByStartup or {}) do
        if (tonumber(expiresMs or 0) or 0) <= now then startup.session_activity.nativePostedByStartup[key] = nil end
    end
    for key, recentMs in pairs(startup.session_activity.nativeRecent or {}) do
        if now - (tonumber(recentMs or 0) or 0) > 3000 then startup.session_activity.nativeRecent[key] = nil end
    end
    for name, guard in pairs(startup.session_activity.nativeRemovalGuards or {}) do
        if type(guard) ~= "table" or (tonumber(guard.expiresMs or 0) or 0) <= now then
            startup.session_activity.nativeRemovalGuards[name] = nil
        end
    end
    local kept = {}
    for _, entry in ipairs(startup.session_activity.nativeReservations or {}) do
        if type(entry) == "table" and (tonumber(entry.expiresMs or 0) or 0) > now then
            kept[#kept + 1] = entry
        end
    end
    startup.session_activity.nativeReservations = kept
end

function startup.session_activity_native_message_matches(kind, normalizedName, value)
    local text = startup.session_activity_normalize_notification_text(value)
    if text == "" or normalizedName == "" then return false end
    if kind == "joining" then
        return text == normalizedName .. " joined"
            or text == normalizedName .. " has joined"
            or text == normalizedName .. " is joining"
            or text == normalizedName .. " joined the session"
            or text == normalizedName .. " has joined the session"
    elseif kind == "left" then
        return text == normalizedName .. " left"
            or text == normalizedName .. " has left"
            or text == normalizedName .. " left the session"
            or text == normalizedName .. " has left the session"
    end
    return false
end

function startup.session_activity_should_hide_native_join_leave(title, message)
    local normalizedTitle = startup.session_activity_normalize_notification_text(title)
    if normalizedTitle == "player joined" or normalizedTitle == "player left" then return true end

    startup.session_activity_prune_native_state()
    local candidates = { title, message }

    -- Cherax can emit the GTA card before ON_PLAYER_JOIN / ON_PLAYER_LEFT. Accept a
    -- strict one-name join/leave sentence even when Startup has not learned the new
    -- player's ID yet. Spaces are intentionally excluded from the name token so
    -- mission, CEO, kill, death, and invitation sentences are not swallowed.
    for _, value in ipairs(candidates) do
        if startup.session_activity_is_pure_join_leave_sentence(value) then return true end
    end

    for normalizedName, token in pairs(startup.session_activity.nativeSuppressTokens or {}) do
        local kind = tostring(type(token) == "table" and token.kind or "")
        for _, value in ipairs(candidates) do
            if startup.session_activity_native_message_matches(kind, normalizedName, value) then return true end
        end
    end

    for _, knownName in pairs(startup.session_activity.knownPlayers or {}) do
        local normalizedName = startup.session_activity_normalize_notification_text(knownName)
        for _, value in ipairs(candidates) do
            if startup.session_activity_native_message_matches("joining", normalizedName, value)
                or startup.session_activity_native_message_matches("left", normalizedName, value) then
                return true
            end
        end
    end
    return false
end

function startup.session_activity_mark_startup_native_post(text)
    local key = startup.session_activity_normalize_notification_text(text)
    if key ~= "" then startup.session_activity.nativePostedByStartup[key] = startup.now() + 4000 end
end

function startup.session_activity_is_startup_native_post(title, message)
    startup.session_activity_prune_native_state()
    local titleKey = startup.session_activity_normalize_notification_text(title)
    local messageKey = startup.session_activity_normalize_notification_text(message)
    return (titleKey ~= "" and startup.session_activity.nativePostedByStartup[titleKey] ~= nil)
        or (messageKey ~= "" and startup.session_activity.nativePostedByStartup[messageKey] ~= nil)
end

function startup.session_activity_estimate_native_card_height(title, message)
    local function visual_lines(value)
        local raw = tostring(value or ""):gsub("~n~", "\n")
        if raw == "" then return 0 end
        local count = 0
        for line in (raw .. "\n"):gmatch("(.-)\n") do
            local plain = line:gsub("~.-~", ""):gsub("[%c]", "")
            local length = string.len(plain)
            count = count + math.max(1, math.ceil(math.max(1, length) / 34))
        end
        return count
    end

    local titleLines = visual_lines(title)
    local messageLines = visual_lines(message)
    local totalLines = math.max(1, titleLines + messageLines)
    local rawMessageLength = string.len(tostring(message or ""))
    local height = 0.024 + (totalLines * 0.043)

    -- Long job/session invitations often contain a portrait/header and a wrapped
    -- description that is much taller than a normal one-line GTA feed card.
    if rawMessageLength >= 80 or totalLines >= 5 then height = height + 0.105 end
    return startup.clamp_float(height, 0.055, 0.72)
end

function startup.session_activity_note_native_notification(title, message, duration, position)
    if startup.s.sessionActivityFollowNativeNotifications ~= true then return end
    if startup.s.sessionActivityUseNativeFeed ~= false then return end
    local normalizedTitle = startup.session_activity_normalize_notification_text(title)
    local normalizedMessage = startup.session_activity_normalize_notification_text(message)
    if normalizedTitle == "" and normalizedMessage == "" then return end

    local now = startup.now()
    local key = normalizedTitle .. "|" .. normalizedMessage
    local rawDuration = tonumber(duration or 0) or 0
    local durationMs
    if rawDuration <= 0 then durationMs = 6000
    elseif rawDuration < 100 then durationMs = rawDuration * 1000
    else durationMs = rawDuration end
    durationMs = startup.clamp_int(durationMs, 2500, 20000)
    local estimatedHeight = startup.session_activity_estimate_native_card_height(title, message)

    -- Some Cherax builds surface the same notification callback more than once.
    -- Extend the existing reservation instead of stacking duplicate phantom cards.
    for _, entry in ipairs(startup.session_activity.nativeReservations or {}) do
        if type(entry) == "table" and entry.key == key then
            entry.height = math.max(tonumber(entry.height or 0) or 0, estimatedHeight)
            entry.expiresMs = math.max(tonumber(entry.expiresMs or 0) or 0, now + durationMs)
            entry.position = position or entry.position
            startup.session_activity.nativeRecent[key] = now
            return
        end
    end

    local last = tonumber(startup.session_activity.nativeRecent[key] or 0) or 0
    if last > 0 and now - last < 350 then return end
    startup.session_activity.nativeRecent[key] = now
    startup.session_activity.nativeReservations[#startup.session_activity.nativeReservations + 1] = {
        key = key,
        height = estimatedHeight,
        position = position,
        orderSerial = startup.session_activity_next_feed_order(),
        createdMs = now,
        expiresMs = now + durationMs
    }
end

function startup.session_activity_native_reserved_height(scale)
    if startup.s.sessionActivityFollowNativeNotifications ~= true then return 0 end
    startup.session_activity_prune_native_state()
    local height = 0
    local count = 0
    for _, entry in ipairs(startup.session_activity.nativeReservations or {}) do
        local entryHeight = tonumber(entry.height or 0) or 0
        if entryHeight <= 0 then
            local legacySlots = math.max(1, tonumber(entry.slots or 1) or 1)
            local slotHeight = math.max(0.048, (tonumber(scale or 0.38) or 0.38) * 0.155)
            entryHeight = legacySlots * slotHeight
        end
        height = height + entryHeight
        count = count + 1
    end
    if count > 1 then height = height + ((count - 1) * 0.006) end
    return startup.clamp_float(height, 0, 0.82)
end

startup.session_activity.classifications = startup.session_activity.classifications or {}
startup.hud_simulation = startup.hud_simulation or { startedMs = 0, stage = 0, cycle = 0 }

startup.session_activity_classification_priority = {
    normal = 1,
    saved_rid = 2,
    startup_peer = 3,
    friend = 4,
    known_modder = 5,
}

function startup.session_activity_classification_color(classification, isLeaving)
    local kind = tostring(classification or "normal")
    if kind == "known_modder" then return {255, 80, 80} end
    if kind == "friend" then return {100, 255, 135} end
    if kind == "startup_peer" then return {195, 120, 255} end
    if kind == "saved_rid" then return {255, 220, 80} end
    if isLeaving == true then return {185, 185, 185} end
    return {100, 200, 255}
end

function startup.session_activity_classification_label(classification)
    local kind = tostring(classification or "normal")
    if kind == "known_modder" then return "Known Modder / Blocked RID" end
    if kind == "friend" then return "Friend" end
    if kind == "startup_peer" then return "Verified Startup User" end
    if kind == "saved_rid" then return "Saved RID" end
    return ""
end

function startup.session_activity_find_rid_entry(playerId)
    if not startup.rid_store or not startup.rid_store.identity then return nil, nil end
    local ident = startup.rid_store.identity(playerId)
    if not ident or not ident.rid then return nil, nil end
    return startup.rid_store.data and startup.rid_store.data[tostring(ident.rid)] or nil, tostring(ident.rid)
end

function startup.session_activity_is_known_modder(playerId, name)
    local wantedId = tonumber(playerId)
    local key = string.lower(tostring(name or ""))
    if startup.modder_hud and startup.modder_hud.entries then
        local direct = key ~= "" and startup.modder_hud.entries[key] or nil
        if direct then return true end
        for _, entry in pairs(startup.modder_hud.entries) do
            if wantedId ~= nil and tonumber(entry and entry.playerId) == wantedId then return true end
        end
    end
    local ridEntry = startup.session_activity_find_rid_entry(wantedId)
    if type(ridEntry) == "table" then
        local flags = type(ridEntry.flags) == "table" and ridEntry.flags or {}
        if ridEntry.blockJoin == true or flags.modder == true or flags.crashAttacker == true
            or flags.kickAttacker == true or flags.battleye == true or flags.blockRidJoin == true then
            return true
        end
    end
    return false
end

function startup.session_activity_classify_player(playerId, name)
    local id = tonumber(playerId)
    if startup.session_activity_is_known_modder(id, name) then return "known_modder" end
    if id ~= nil and startup.is_player_current_friend and startup.is_player_current_friend(id) then return "friend" end
    local ridEntry, rid = startup.session_activity_find_rid_entry(id)
    if startup.presence then
        local byPlayer = startup.presence.verified_by_player and startup.presence.verified_by_player[id] or nil
        local byRid = rid and startup.presence.verified_by_rid and startup.presence.verified_by_rid[rid] or nil
        if byPlayer or byRid then return "startup_peer" end
    end
    if ridEntry then return "saved_rid" end
    return "normal"
end

function startup.session_activity_update_classification(playerId, name, classification)
    local id = tonumber(playerId)
    local nextKind = tostring(classification or "normal")
    local currentKind = id ~= nil and tostring(startup.session_activity.classifications[id] or "normal") or "normal"
    local currentRank = startup.session_activity_classification_priority[currentKind] or 1
    local nextRank = startup.session_activity_classification_priority[nextKind] or 1
    if nextRank < currentRank then nextKind = currentKind end
    if id ~= nil then startup.session_activity.classifications[id] = nextKind end
    local wantedName = string.lower(tostring(name or ""))
    for _, entry in ipairs(startup.session_activity.entries or {}) do
        local matches = id ~= nil and tonumber(entry.playerId) == id
        if not matches and wantedName ~= "" then matches = string.lower(tostring(entry.name or "")) == wantedName end
        if matches then entry.classification = nextKind end
    end
    return nextKind
end

function startup.session_activity_native_text(kind, name, reason)
    name = tostring(name or "Unknown")
    reason = tostring(reason or "")
    if kind == "joining" then
        return name .. " is joining..."
    elseif kind == "blocked" then
        local text = "~r~Blocked " .. name .. " joining...~s~"
        if reason ~= "" then text = text .. "~n~~o~Reason: " .. reason .. "~s~" end
        return text
    elseif kind == "left" then
        return name .. " left."
    elseif kind == "kicking" then
        local text = "~o~Kicking: " .. name .. "~s~"
        if reason ~= "" then text = text .. "~n~~o~Reason: " .. reason .. "~s~" end
        return text
    elseif kind == "kicked" then
        local text = "~r~Kicked " .. name .. "~s~"
        if reason ~= "" then text = text .. "~n~~o~Reason: " .. reason .. "~s~" end
        return text
    end
    return name
end

function startup.post_native_session_feed(kind, name, reason)
    if startup.s.playerModUiEnabled == false then return false end
    if startup.s.sessionActivityUseNativeFeed == false then return false end
    if kind == "left" and startup.s.sessionActivityPostLeave ~= true then return false end
    if not Script or not Script.QueueJob or not Natives or not Natives.InvokeVoid or not Natives.InvokeInt then return false end
    local text = startup.session_activity_native_text(kind, name, reason)
    if text == "" then return false end
    startup.session_activity_mark_startup_native_post(text)
    Script.QueueJob(function()
        Natives.InvokeVoid(0x202709F4C58A0424, "STRING")
        Natives.InvokeVoid(0x6C188BE134E074AA, text)
        Natives.InvokeInt(0x2ED7843F8F801023, false, false)
    end)
    return true
end

function startup.session_activity_is_duplicate(kind, name, reason)
    local now = startup.now()
    local key = string.lower(tostring(kind or "") .. "|" .. tostring(name or "") .. "|" .. tostring(reason or ""))
    local last = tonumber(startup.session_activity.recent[key] or 0) or 0
    startup.session_activity.recent[key] = now
    for recentKey, recentMs in pairs(startup.session_activity.recent) do
        if now - (tonumber(recentMs or 0) or 0) > 10000 then startup.session_activity.recent[recentKey] = nil end
    end
    return last > 0 and (now - last) < 1800
end

function startup.session_activity_record(kind, name, reason, holdMs, metadata)
    name = tostring(name or "Unknown"):gsub("^%s+", ""):gsub("%s+$", "")
    reason = tostring(reason or ""):gsub("^%s+", ""):gsub("%s+$", "")
    metadata = type(metadata) == "table" and metadata or {}
    if name == "" then name = "Unknown" end
    if tostring(kind or "") == "left" and startup.s.sessionActivityPostLeave ~= true then return end
    if startup.session_activity_is_duplicate(kind, name, reason) then return end
    startup.post_native_session_feed(kind, name, reason)
    startup.session_activity.sequence = (startup.session_activity.sequence or 0) + 1
    local now = startup.now()
    local ttl = tonumber(holdMs or startup.s.sessionActivityHoldMs or 7000) or 7000
    local playerId = tonumber(metadata.playerId)
    local classification = tostring(metadata.classification or "")
    if classification == "" and playerId ~= nil then
        classification = tostring(startup.session_activity.classifications[playerId] or startup.session_activity_classify_player(playerId, name))
    end
    if classification == "" then classification = "normal" end
    if playerId ~= nil then startup.session_activity.classifications[playerId] = classification end
    local entry = {
        id = startup.session_activity.sequence,
        kind = tostring(kind or "info"),
        name = name,
        reason = reason,
        playerId = playerId,
        classification = classification,
        createdMs = now,
        expiresMs = now + ttl,
        renderY = nil,
        nativeSlotIds = {}
    }
    startup.session_activity.entries[#startup.session_activity.entries + 1] = entry
    startup.session_activity_queue_native_slots(entry)
    local maxKeep = math.max(0, tonumber(startup.s.sessionActivityMaxEntries or 0) or 0)
    if maxKeep > 0 then
        while #startup.session_activity.entries > maxKeep do
            local removed = table.remove(startup.session_activity.entries, 1)
            startup.session_activity_release_native_slots(removed)
        end
    end
end

function startup.session_activity_prune()
    local now = startup.now()
    local kept = {}
    for _, entry in ipairs(startup.session_activity.entries or {}) do
        if entry and (entry.expiresMs or 0) > now then
            kept[#kept + 1] = entry
        elseif entry then
            startup.session_activity_release_native_slots(entry)
        end
    end
    startup.session_activity.entries = kept
end

function startup.session_activity_player_name(playerId)
    playerId = tonumber(playerId)
    if playerId ~= nil and startup.session_activity.knownPlayers[playerId] then
        return startup.session_activity.knownPlayers[playerId]
    end
    if playerId ~= nil then
        local name = startup.get_player_name_safe(playerId)
        if name and name ~= "" and not string.find(name, "Player ", 1, true) then
            startup.session_activity.knownPlayers[playerId] = name
            return name
        end
    end
    return playerId ~= nil and ("Player " .. tostring(playerId)) or "Unknown player"
end

function startup.session_activity_refresh_known_players()
    if not Players or not Players.Get then return end
    local players = Players.Get(ePlayerListSort.PLAYER_ID, "")
    if not players then return end
    for _, playerId in pairs(players) do
        local id = tonumber(playerId)
        if id ~= nil then
            local name = startup.get_player_name_safe(id)
            if name and name ~= "" then startup.session_activity.knownPlayers[id] = name end
        end
    end
end

function startup.session_activity_content(entry)
    if not entry then return "", "", {185,185,185} end
    if entry.kind == "joining" then
        local classification = tostring(entry.classification or "normal")
        return tostring(entry.name) .. " is joining...", startup.session_activity_classification_label(classification), startup.session_activity_classification_color(classification, false)
    elseif entry.kind == "blocked" then
        return "Blocked " .. tostring(entry.name) .. " joining...", entry.reason ~= "" and ("Reason: " .. tostring(entry.reason)) or "", {255, 90, 90}
    elseif entry.kind == "left" then
        local classification = tostring(entry.classification or "normal")
        return tostring(entry.name) .. " left.", startup.session_activity_classification_label(classification), startup.session_activity_classification_color(classification, true)
    elseif entry.kind == "kicking" then
        return "Kicking: " .. tostring(entry.name), entry.reason ~= "" and ("Reason: " .. tostring(entry.reason)) or "", {255, 185, 80}
    elseif entry.kind == "kicked" then
        return "Kicked " .. tostring(entry.name), entry.reason ~= "" and ("Reason: " .. tostring(entry.reason)) or "", {255, 120, 70}
    end
    return tostring(entry.name), tostring(entry.reason or ""), {220,220,220}
end

function startup.session_activity_lines()
    startup.session_activity_prune()
    local lines = {}
    for _, entry in ipairs(startup.session_activity.entries or {}) do
        local primary, secondary, color = startup.session_activity_content(entry)
        lines[#lines + 1] = { text = primary, color = color }
        if secondary ~= "" then lines[#lines + 1] = { text = secondary, color = {255, 185, 80} } end
    end
    return lines
end

startup.session_activity.rendererModes = startup.session_activity.rendererModes or {
    "Auto (Foreground)",
    "Cherax Foreground",
    "GTA After-Fade",
    "Compatibility"
}
startup.session_activity.rendererRuntime = startup.session_activity.rendererRuntime or {
    foregroundFaulted = false,
    faultLogged = false,
    lastResolved = "Pending",
    lastError = "",
    foregroundLastFrameMs = 0
}

function startup.session_activity_set_gta_draw_order(order)
    if not Natives or not Natives.InvokeVoid then return false end
    local ok = direct_call(function()
        Natives.InvokeVoid(0x61BB1D9B3A95D802, tonumber(order or 0) or 0)
    end)
    return ok
end

function startup.session_activity_foreground_capable()
    if startup.session_activity.rendererRuntime.foregroundFaulted == true then return false end
    if not EventMgr or not eLuaEvent or not eLuaEvent.ON_POST_PRESENT then return false end
    if not ImGui or not ImGui.GetDisplaySize then return false end
    local hasText = ImGui.FgAddText ~= nil or ImGui.AddText ~= nil
    local hasRect = ImGui.FgAddRectFilled ~= nil or ImGui.AddRectFilled ~= nil
    return hasText and hasRect
end

function startup.session_activity_resolve_renderer()
    local mode = tostring(startup.s.sessionActivityRendererMode or "Auto (Foreground)")
    local foregroundCapable = startup.session_activity_foreground_capable()
    local resolved
    if mode == "Compatibility" then
        resolved = "compatibility"
    elseif mode == "GTA After-Fade" then
        resolved = "after_fade"
    elseif mode == "Cherax Foreground" then
        resolved = foregroundCapable and "foreground" or "after_fade"
    else
        resolved = foregroundCapable and "foreground" or "after_fade"
    end
    startup.session_activity.rendererRuntime.lastResolved = resolved
    return resolved
end

function startup.session_activity_foreground_display_size()
    if not ImGui or not ImGui.GetDisplaySize then return nil, nil end
    local ok, width, height = direct_call(ImGui.GetDisplaySize)
    width, height = tonumber(width), tonumber(height)
    if not ok or not width or not height or width <= 0 or height <= 0 then return nil, nil end
    return width, height
end

function startup.session_activity_foreground_rect(displayWidth, displayHeight, x, y, width, height, r, g, b, a)
    local fn = ImGui and (ImGui.FgAddRectFilled or ImGui.AddRectFilled) or nil
    if not fn then return false end
    local x1 = (tonumber(x or 0) or 0) * displayWidth
    local y1 = (tonumber(y or 0) or 0) * displayHeight
    local x2 = x1 + ((tonumber(width or 0) or 0) * displayWidth)
    local y2 = y1 + ((tonumber(height or 0) or 0) * displayHeight)
    local ok = direct_call(fn, x1, y1, x2, y2,
        math.floor(tonumber(r or 0) or 0), math.floor(tonumber(g or 0) or 0),
        math.floor(tonumber(b or 0) or 0), math.floor(tonumber(a or 0) or 0), 0.0, 0)
    return ok
end

function startup.session_activity_foreground_text(displayWidth, displayHeight, text, x, y, scale, r, g, b, a)
    if not ImGui then return false end
    local px = (tonumber(x or 0) or 0) * displayWidth
    local py = (tonumber(y or 0) or 0) * displayHeight
    local visualScale = startup.clamp_float((tonumber(scale or 0.42) or 0.42) / 0.44, 0.55, 1.60)
    local fontScale = startup.clamp_float(1.48 * visualScale, 0.90, 2.10)
    local fontScaleApplied = false
    local content = tostring(text or "")

    -- Apply the actual ImGui font scale first, then measure the exact rendered text.
    -- Build 149 estimated glyph height from GetFontSize, which could place text too high
    -- when Cherax's foreground draw list used a differently scaled active font.
    if ImGui.SetWindowFontScale then
        local okScale = direct_call(ImGui.SetWindowFontScale, fontScale)
        fontScaleApplied = okScale == true
    end

    local baseFontSize = 16.0
    if ImGui.GetFontSize then
        local okSize, value = direct_call(ImGui.GetFontSize)
        if okSize and tonumber(value) then baseFontSize = tonumber(value) end
    end
    local measuredHeight = fontScaleApplied and baseFontSize or (baseFontSize * fontScale)
    if ImGui.CalcTextSize then
        local okMeasure, size = direct_call(ImGui.CalcTextSize, content)
        if okMeasure then
            if type(size) == "table" then
                local candidate = tonumber(size.y or size.Y or size[2])
                if candidate and candidate > 0 then measuredHeight = candidate end
            end
        end
    end

    local rowHeightPx = startup.session_activity_native_slot_height(scale) * displayHeight
    py = py + math.max(0, (rowHeightPx - measuredHeight) * 0.50)

    local alpha = math.max(0, math.min(255, math.floor(tonumber(a or 255) or 255)))
    local shadowAlpha = math.floor(alpha * 0.84)
    local fg = ImGui.FgAddText
    local regular = ImGui.AddText
    local function draw_at(dx, dy, rr, gg, bb, aa)
        if fg then
            return direct_call(fg, px + dx, py + dy, rr, gg, bb, aa, content)
        elseif regular then
            return direct_call(regular, px + dx, py + dy, content, rr, gg, bb, aa)
        end
        return false
    end

    local outline = startup.clamp_float(1.05 * visualScale, 0.85, 1.55)
    draw_at(outline, outline, 0, 0, 0, shadowAlpha)
    draw_at(-outline, outline, 0, 0, 0, shadowAlpha)
    draw_at(outline, -outline, 0, 0, 0, shadowAlpha)
    draw_at(-outline, -outline, 0, 0, 0, shadowAlpha)

    local rr = math.floor(tonumber(r or 255) or 255)
    local gg = math.floor(tonumber(g or 255) or 255)
    local bb = math.floor(tonumber(b or 255) or 255)
    local edge = startup.clamp_float(0.38 * visualScale, 0.25, 0.62)
    local edgeAlpha = math.floor(alpha * 0.88)
    draw_at(-edge, 0, rr, gg, bb, edgeAlpha)
    draw_at(edge, 0, rr, gg, bb, edgeAlpha)
    draw_at(0, -edge, rr, gg, bb, edgeAlpha)
    draw_at(0, edge, rr, gg, bb, edgeAlpha)
    local ok = draw_at(0, 0, rr, gg, bb, alpha)

    if fontScaleApplied then direct_call(ImGui.SetWindowFontScale, 1.0) end
    return ok == true
end

function startup.session_activity_primary_segments(entry)
    if not entry then return nil, nil end
    local name = tostring(entry.name or "Unknown")
    if entry.kind == "joining" then return name, " is joining..." end
    if entry.kind == "left" then return name, " left." end
    return nil, nil
end

function startup.session_activity_foreground_measure_text(displayWidth, text, scale)
    displayWidth = tonumber(displayWidth or 0) or 0
    if displayWidth <= 0 or not ImGui then return 0 end
    local content = tostring(text or "")
    if content == "" then return 0 end
    local visualScale = startup.clamp_float((tonumber(scale or 0.42) or 0.42) / 0.44, 0.55, 1.60)
    local fontScale = startup.clamp_float(1.48 * visualScale, 0.90, 2.10)
    local fontScaleApplied = false
    if ImGui.SetWindowFontScale then
        fontScaleApplied = direct_call(ImGui.SetWindowFontScale, fontScale) == true
    end

    local widthPx = nil
    if ImGui.CalcTextSize then
        local ok, first, second = direct_call(ImGui.CalcTextSize, content)
        if ok then
            if type(first) == "table" then
                widthPx = tonumber(first.x or first.X or first[1])
            elseif type(first) == "userdata" then
                local memberOk, memberValue = direct_call(function() return first.x or first.X or first[1] end)
                if memberOk then widthPx = tonumber(memberValue) end
            else
                widthPx = tonumber(first)
            end
        end
    end
    if fontScaleApplied then direct_call(ImGui.SetWindowFontScale, 1.0) end
    if widthPx == nil or widthPx <= 0 then
        widthPx = math.max(1, string.len(content)) * 8.2 * visualScale
    end
    return widthPx / displayWidth
end

function startup.session_activity_entry_height(entry, scale)
    local _, secondary = startup.session_activity_content(entry)
    local lineGap = math.max(0.020, (tonumber(scale or 0.30) or 0.30) * 0.075)
    if secondary ~= "" then return lineGap * 1.92 end
    return lineGap * 1.20
end

function startup.render_session_activity_feed(x, bottomY, scale, textAlpha, forcedRenderer)
    if not startup.s.showSessionActivityHud then return 0 end
    if startup.s.sessionActivityUseNativeFeed ~= false then return 0 end
    startup.session_activity_prune()
    local entries = startup.session_activity.entries or {}
    if #entries == 0 then return 0 end

    local resolvedRenderer = startup.session_activity_resolve_renderer()
    if forcedRenderer == nil and resolvedRenderer == "foreground" then return 0 end
    if forcedRenderer ~= nil and tostring(forcedRenderer) ~= resolvedRenderer then return 0 end
    local usingForeground = resolvedRenderer == "foreground"
    local usingAfterFade = resolvedRenderer == "after_fade"
    local displayWidth, displayHeight
    if usingForeground then
        displayWidth, displayHeight = startup.session_activity_foreground_display_size()
        if not displayWidth or not displayHeight then return 0 end
    elseif usingAfterFade then
        startup.session_activity_set_gta_draw_order(8)
    end

    local function drawRect(px, py, pw, ph, r, g, b, a)
        if usingForeground then
            return startup.session_activity_foreground_rect(displayWidth, displayHeight, px, py, pw, ph, r, g, b, a)
        end
        return startup.draw_hud_rect(px, py, pw, ph, r, g, b, a)
    end
    local function drawText(text, px, py, pscale, r, g, b, a, font)
        if usingForeground then
            return startup.session_activity_foreground_text(displayWidth, displayHeight, text, px, py, pscale, r, g, b, a)
        end
        return startup.draw_hud_text(text, px, py, pscale, r, g, b, a, font)
    end

    local now = startup.now()
    local renderScale = tonumber(scale or 0.42) or 0.42
    local nativeReservedHeight = startup.session_activity_native_reserved_height(renderScale)
    local baseBottomY = math.max(0.12, tonumber(bottomY or 0.806) or 0.806)
    local enterMs = math.max(100, tonumber(startup.s.sessionActivityEnterMs or 420) or 420)
    local fadeMs = math.max(200, tonumber(startup.s.sessionActivityFadeMs or 900) or 900)
    local boxAlpha = math.max(0, math.min(230, tonumber(startup.s.sessionActivityBoxAlpha or 60) or 60))
    local animated = startup.s.sessionActivityAnimated ~= false
    local horizontalScale = startup.get_hud_horizontal_scale()
    local gap = 0.004
    local targets = {}
    local effectiveBottomY = baseBottomY
    local cursorBottom = effectiveBottomY
    local usingNativeSlotBridge = startup.s.sessionActivityNativeSlotBridge ~= false
        and startup.s.sessionActivityPlacementMode ~= "Above Session HUD Stack"
    local trackingNativeSlots = usingNativeSlotBridge and startup.s.sessionActivityTrackNativeSlots ~= false
    if trackingNativeSlots then startup.session_activity_snap_native_feed(true) end

    if usingNativeSlotBridge then
        -- GTA keeps the feed immediately above the minimap. Build one shared timeline,
        -- anchor its newest edge at the configured native-feed bottom, and place each
        -- custom row over one blank GTA slot. A secondary RID/modder label receives its
        -- own normal-height row instead of stretching the primary card to 2x height.
        local timeline = {}
        if startup.s.sessionActivityFollowNativeNotifications ~= false then
            for index, reservation in ipairs(startup.session_activity.nativeReservations or {}) do
                timeline[#timeline + 1] = {
                    kind = "native",
                    createdMs = tonumber(reservation.createdMs or 0) or 0,
                    orderSerial = tonumber(reservation.orderSerial or 0) or 0,
                    sequence = index,
                    height = tonumber(reservation.height or 0) or 0.060
                }
            end
        end
        for index, entry in ipairs(entries) do
            local slots = math.max(1, tonumber(entry.nativeAnchorSlots or startup.session_activity_native_anchor_slot_count(entry)) or 1)
            local slotHeight = startup.session_activity_native_slot_height(renderScale)
            timeline[#timeline + 1] = {
                kind = "custom",
                createdMs = tonumber(entry.nativeAnchorCreatedMs or entry.createdMs or 0) or 0,
                orderSerial = tonumber(entry.nativeAnchorOrder or 0) or 0,
                sequence = 100000 + (tonumber(entry.id or index) or index),
                index = index,
                slots = slots,
                rowHeight = slotHeight,
                height = (slotHeight * slots) + (gap * math.max(0, slots - 1))
            }
        end
        table.sort(timeline, function(a, b)
            local aOrder = tonumber(a.orderSerial or 0) or 0
            local bOrder = tonumber(b.orderSerial or 0) or 0
            if aOrder > 0 and bOrder > 0 and aOrder ~= bOrder then return aOrder < bOrder end
            if a.createdMs == b.createdMs then return a.sequence < b.sequence end
            return a.createdMs < b.createdMs
        end)

        local totalHeight = 0
        for timelineIndex, item in ipairs(timeline) do
            totalHeight = totalHeight + item.height
            if timelineIndex < #timeline then totalHeight = totalHeight + 0.006 end
        end
        local cursorTop = math.max(0.022, baseBottomY - totalHeight)
        local stackTop = cursorTop
        for _, item in ipairs(timeline) do
            if item.kind == "custom" then
                targets[item.index] = {
                    y = cursorTop,
                    h = item.rowHeight,
                    rowHeight = item.rowHeight,
                    slots = item.slots,
                    totalHeight = item.height
                }
            end
            cursorTop = cursorTop + item.height + 0.006
        end

        -- Resolve each blank GTA row by its own stable Startup anchor ID. Build 152
        -- calibrated the entire stack from the first live position it found, so later
        -- rows could drift after GTA pushed them upward. Build 153 stores one mutable
        -- position object per native row and applies exact movement per entry.
        if trackingNativeSlots then
            local exactAnchors = {}
            local exactByIndex = {}
            local nowExact = startup.now()

            for index, entry in ipairs(entries) do
                local target = targets[index]
                if target ~= nil then
                    local positions = type(entry.nativeAnchorPositionObjects) == "table" and entry.nativeAnchorPositionObjects or {}
                    local slots = math.max(1, tonumber(target.slots or entry.nativeAnchorSlots or 1) or 1)
                    local exactTop = nil
                    local exactSlot = nil

                    for slot = 1, slots do
                        local observedY = startup.session_activity_resolve_live_native_y(positions[slot], displayHeight)
                        if observedY ~= nil then
                            local candidateTop = observedY - ((slot - 1) * ((tonumber(target.rowHeight or target.h) or target.h) + gap))
                            if exactTop == nil or slot == 1 then
                                exactTop = candidateTop
                                exactSlot = slot
                            end
                            if slot == 1 then break end
                        end
                    end

                    -- Compatibility with a Build 152 scalar object while saved runtime
                    -- state is migrating in-place.
                    if exactTop == nil then
                        local observedY = startup.session_activity_resolve_live_native_y(entry.nativeAnchorPositionObject, displayHeight)
                        if observedY ~= nil then
                            local observedSlot = math.max(1, tonumber(entry.nativeAnchorObservedSlot or 1) or 1)
                            exactTop = observedY - ((observedSlot - 1) * ((tonumber(target.rowHeight or target.h) or target.h) + gap))
                            exactSlot = observedSlot
                        end
                    end

                    if exactTop ~= nil and exactTop >= 0.005 and exactTop <= 0.96 then
                        local fallbackY = target.y
                        target.y = exactTop
                        entry.nativeAnchorLastY = exactTop
                        entry.nativeAnchorLastExactY = exactTop
                        entry.nativeAnchorLastExactSlot = exactSlot
                        entry.nativeAnchorObservedMs = nowExact
                        startup.session_activity.nativeTracker.lastExactPositionMs = nowExact
                        exactByIndex[index] = true
                        exactAnchors[#exactAnchors + 1] = {
                            index = index,
                            order = tonumber(entry.nativeAnchorOrder or 0) or 0,
                            delta = exactTop - fallbackY
                        }
                    end
                end
            end

            if #exactAnchors > 0 then
                -- A Cherax build may expose position objects for only some rows. Apply
                -- the movement delta from the nearest identified row to each unmatched
                -- row, preserving feed order without collapsing everything onto the
                -- first anchor.
                for index, entry in ipairs(entries) do
                    local target = targets[index]
                    if target ~= nil and exactByIndex[index] ~= true then
                        local order = tonumber(entry.nativeAnchorOrder or 0) or 0
                        local nearest = nil
                        local nearestDistance = math.huge
                        for _, anchor in ipairs(exactAnchors) do
                            local distance = math.abs(order - anchor.order)
                            if distance < nearestDistance then
                                nearest = anchor
                                nearestDistance = distance
                            end
                        end
                        if nearest ~= nil and math.abs(nearest.delta) <= 0.30 then
                            target.y = target.y + nearest.delta
                        end
                    end
                end
                startup.session_activity.nativeTracker.lastMode = "Per-anchor ID positions + nearest-ID fallback"
            else
                startup.session_activity.nativeTracker.lastMode = "Per-anchor IDs + ordered shadow queue"
            end
        end
        effectiveBottomY = baseBottomY
        cursorBottom = stackTop
    else
        local function calculate_needed_height(testScale, testGap)
            local total = 0
            for _, entry in ipairs(entries) do
                total = total + startup.session_activity_entry_height(entry, testScale) + testGap
            end
            return total
        end

        local neededHeight = calculate_needed_height(renderScale, gap)
        local nativeStartY = 0.045
        local nativeBottomY = nativeReservedHeight > 0 and (nativeStartY + nativeReservedHeight) or 0
        if nativeBottomY > 0 then
            effectiveBottomY = math.max(baseBottomY, nativeBottomY + neededHeight + 0.014)
            effectiveBottomY = math.min(0.95, effectiveBottomY)
        end

        local availableHeight
        if nativeBottomY > 0 then
            availableHeight = math.max(0.08, 0.95 - nativeBottomY - 0.014)
        else
            availableHeight = math.max(0.10, effectiveBottomY - 0.025)
        end
        if neededHeight > availableHeight and neededHeight > 0 then
            local ratio = availableHeight / neededHeight
            renderScale = math.max(0.20, renderScale * ratio)
            gap = math.max(0.001, gap * ratio)
            neededHeight = calculate_needed_height(renderScale, gap)
            if nativeBottomY > 0 then
                effectiveBottomY = math.min(0.95, nativeBottomY + neededHeight + 0.014)
            end
        end

        cursorBottom = effectiveBottomY
        for i = #entries, 1, -1 do
            local entry = entries[i]
            local height = startup.session_activity_entry_height(entry, renderScale)
            local targetTop = cursorBottom - height
            targets[i] = { y = targetTop, h = height }
            cursorBottom = targetTop - gap
        end
    end

    local minBoxWidth = 0.135 * horizontalScale
    local maxBoxWidth = 0.235 * horizontalScale
    local charUnit = (0.0032 + (renderScale * 0.0014)) * horizontalScale

    for i, entry in ipairs(entries) do
        local target = targets[i]
        local age = math.max(0, now - (entry.createdMs or now))
        local remain = math.max(0, (entry.expiresMs or now) - now)
        local enterT = animated and startup.ease_out_cubic(age / enterMs) or 1.0
        local fadeT = remain < fadeMs and startup.clamp01(remain / fadeMs) or 1.0
        if animated and remain < fadeMs then fadeT = 1.0 - startup.ease_in_cubic(1.0 - fadeT) end
        local opacity = math.min(enterT, fadeT)

        if entry.renderY == nil then
            entry.renderY = target.y + (animated and 0.016 or 0.0)
        end
        if animated then
            local delta = target.y - entry.renderY
            if trackingNativeSlots and math.abs(delta) > 0.075 then
                entry.renderY = target.y
            else
                entry.renderY = entry.renderY + (delta * (trackingNativeSlots and 0.48 or 0.16))
            end
        else
            entry.renderY = target.y
        end

        local primary, secondary, color = startup.session_activity_content(entry)
        local longestText = math.max(string.len(primary or ""), string.len(secondary or ""), string.len("Connected Players: 28"))
        local boxWidth = math.max(minBoxWidth, math.min(maxBoxWidth, 0.060 + (longestText * charUnit)))
        local slideX = animated and ((1.0 - enterT) * (-0.012 * horizontalScale)) or 0.0
        if animated and remain < fadeMs then slideX = slideX + ((1.0 - fadeT) * (-0.010 * horizontalScale)) end
        local boxX = x - (0.004 * horizontalScale) + slideX
        local drawAlpha = math.floor((tonumber(textAlpha or 200) or 200) * opacity)
        local bgAlpha = math.floor(boxAlpha * opacity)
        if usingNativeSlotBridge and entry.nativeAnchorReady == true then
            -- The blank native ticker already supplies the GTA background. Foreground
            -- mode draws only Startup's colored sidebar/text so there is no double box.
            bgAlpha = usingForeground and 0 or math.floor(math.min(boxAlpha, 72) * opacity)
        end

        local primaryHeight = tonumber(target.rowHeight or target.h) or target.h
        if bgAlpha > 0 then drawRect(boxX, entry.renderY, boxWidth, primaryHeight, 5, 5, 8, bgAlpha) end
        local accentRatio = startup.clamp_float(tonumber(startup.s.sessionActivityAccentHeightRatio or 1.00) or 1.00, 0.15, 1.00)
        local accentHeight = startup.clamp_float(primaryHeight * accentRatio, 0.010, 0.040)
        local accentInset = math.max(0, (primaryHeight - accentHeight) * 0.50)
        local accentWidth = 0.00135 * horizontalScale
        drawRect(boxX, entry.renderY + accentInset, accentWidth, accentHeight, color[1], color[2], color[3], math.floor(220 * opacity))
        local textYOffset = startup.clamp_float(tonumber(startup.s.sessionActivityTextYOffset or 0.002) or 0.002, -0.030, 0.040)
        local primaryTextX = boxX + (0.008 * horizontalScale)
        local primaryTextY = entry.renderY + textYOffset
        local boldName, regularSuffix = startup.session_activity_primary_segments(entry)
        local primaryDrawn
        if usingForeground and boldName ~= nil then
            local nameDrawn = drawText(boldName, primaryTextX, primaryTextY, renderScale,
                color[1], color[2], color[3], drawAlpha, 4)
            -- Cherax exposes the active foreground font but not a guaranteed bold-font
            -- handle. A sub-pixel second pass gives only the name a convincing heavier
            -- weight while the action suffix remains a single regular draw.
            local boldOffsetX = math.max(0.00018, 0.58 / math.max(1, displayWidth))
            local nameBoldDrawn = drawText(boldName, primaryTextX + boldOffsetX, primaryTextY, renderScale,
                color[1], color[2], color[3], drawAlpha, 4)
            local nameWidth = startup.session_activity_foreground_measure_text(displayWidth, boldName, renderScale)
            local suffixX = primaryTextX + nameWidth + boldOffsetX
            local suffixDrawn = drawText(regularSuffix, suffixX, primaryTextY, renderScale,
                color[1], color[2], color[3], drawAlpha, 4)
            primaryDrawn = (nameDrawn == true or nameBoldDrawn == true) and suffixDrawn == true
        elseif boldName ~= nil then
            -- GTA text commands understand ~h~ as a weight toggle in the compatibility
            -- renderers, so only the player name receives emphasis there as well.
            primaryDrawn = drawText("~h~" .. boldName .. "~h~" .. regularSuffix,
                primaryTextX, primaryTextY, renderScale, color[1], color[2], color[3], drawAlpha, 4)
        else
            primaryDrawn = drawText(primary, primaryTextX, primaryTextY, renderScale,
                color[1], color[2], color[3], drawAlpha, 4)
        end
        if usingForeground and primaryDrawn ~= true then error("Cherax foreground text draw failed") end
        if secondary ~= "" then
            if usingNativeSlotBridge then
                local secondaryY = entry.renderY + primaryHeight + gap
                if bgAlpha > 0 then drawRect(boxX, secondaryY, boxWidth, primaryHeight, 5, 5, 8, bgAlpha) end
                local secondaryAccentHeight = startup.clamp_float(primaryHeight * accentRatio, 0.010, 0.040)
                local secondaryInset = math.max(0, (primaryHeight - secondaryAccentHeight) * 0.50)
                drawRect(boxX, secondaryY + secondaryInset, accentWidth, secondaryAccentHeight, 255, 185, 80, math.floor(220 * opacity))
                local secondaryDrawn = drawText(secondary, boxX + (0.008 * horizontalScale), secondaryY + textYOffset, renderScale * 0.90, 255, 185, 80, drawAlpha, 4)
                if usingForeground and secondaryDrawn ~= true then error("Cherax foreground secondary text draw failed") end
            else
                local lineGap = math.max(0.020, renderScale * 0.075)
                local secondaryDrawn = drawText(secondary, boxX + (0.009 * horizontalScale), entry.renderY + textYOffset + lineGap, renderScale * 0.90, 255, 185, 80, drawAlpha, 4)
                if usingForeground and secondaryDrawn ~= true then error("Cherax foreground secondary text draw failed") end
            end
        end
    end

    if usingAfterFade then startup.session_activity_set_gta_draw_order(0) end
    return math.max(0, effectiveBottomY - cursorBottom)
end


function startup.session_activity_clear_preview()
    startup.stop_hud_simulation()
    startup.session_activity_clear_native_slots()
    startup.session_activity.entries = {}
    startup.session_activity.recent = {}
end

function startup.session_activity_preview_one(kind, name, classification, reason)
    startup.session_activity_clear_preview()
    startup.session_activity_record(kind, name, reason or "", 18000, {
        classification = classification or "normal"
    })
end

function startup.session_activity_post_tracking_test_notice(text, holdMs)
    if not Script or not Script.QueueJob or not Natives or not Natives.InvokeVoid or not Natives.InvokeInt then return false end
    local body = tostring(text or "Startup native push test")
    local ttl = tonumber(holdMs or 6500) or 6500
    startup.session_activity_mark_startup_native_post(body)
    startup.session_activity_note_native_notification("", body, ttl, nil)
    Natives.InvokeVoid(0x202709F4C58A0424, "STRING")
    Natives.InvokeVoid(0x6C188BE134E074AA, body)
    Natives.InvokeInt(0x2ED7843F8F801023, false, false)
    return true
end

function startup.session_activity_preview_native_push_tracking()
    startup.session_activity_clear_preview()
    startup.session_activity_record("joining", "Native_Box_Tracker", "", 18000, { classification = "normal" })
    if not Script or not Script.QueueJob then return end
    Script.QueueJob(function()
        local notices = {
            "Startup push test: native card 1",
            "Startup push test: native card 2",
            "Startup push test: native card 3"
        }
        for _, notice in ipairs(notices) do
            if Script.Yield then Script.Yield(900) end
            startup.session_activity_post_tracking_test_notice(notice, 7000)
        end
    end)
    startup.toast("Native Box Tracker test started. The custom card should move upward with its blank GTA slot.", 4500)
end

function startup.session_activity_preview_all_layouts()
    startup.session_activity_clear_preview()
    local ttl = 22000
    startup.session_activity_record("joining", "Normal_Player_12345", "", ttl, { classification = "normal" })
    startup.session_activity_record("left", "Long_Player_Name_12345", "", ttl, { classification = "normal" })
    startup.session_activity_record("joining", "Friend_Preview", "", ttl, { classification = "friend" })
    startup.session_activity_record("joining", "Saved_RID_300501099", "", ttl, { classification = "saved_rid" })
    startup.session_activity_record("left", "Known_Modder_Test", "", ttl, { classification = "known_modder" })
    startup.toast("Activity Layout Lab: five notification styles are active for 22 seconds.", 3500)
end

function startup.update_hud_simulation()
    if not startup.s.hudSimulationEnabled then return end
    local now = startup.now()
    if (startup.hud_simulation.startedMs or 0) <= 0 then
        startup.hud_simulation.startedMs = now
        startup.hud_simulation.stage = 0
    end

    local elapsed = now - startup.hud_simulation.startedMs
    local cycleMs = 11000 + math.max(3000, tonumber(startup.s.sessionActivityHoldMs or 7000) or 7000) + 1500
    if elapsed >= cycleMs then
        startup.hud_simulation.startedMs = now
        startup.hud_simulation.stage = 0
        startup.hud_simulation.cycle = (startup.hud_simulation.cycle or 0) + 1
        startup.session_activity_clear_native_slots()
        startup.session_activity.entries = {}
        elapsed = 0
    end

    local stages = {
        { at = 450, kind = "joining", name = "Kian_Fischy", reason = "" },
        { at = 2500, kind = "joining", name = "Battleye_User", reason = "" },
        { at = 3900, kind = "blocked", name = "Battleye_User", reason = "Battleye Emulator" },
        { at = 6500, kind = "left", name = "Friendly_Player", reason = "" },
        { at = 8500, kind = "joining", name = "CrashTester", reason = "" },
        { at = 9900, kind = "blocked", name = "CrashTester", reason = "Crash Type V2" }
    }
    while (startup.hud_simulation.stage or 0) < #stages do
        local nextIndex = (startup.hud_simulation.stage or 0) + 1
        local item = stages[nextIndex]
        if elapsed < item.at then break end
        startup.session_activity_record(item.kind, item.name, item.reason, startup.s.sessionActivityHoldMs)
        startup.hud_simulation.stage = nextIndex
    end
end

function startup.run_hud_simulation()
    startup.s.playerModUiEnabled = true
    startup.set_feature_bool_silently(startup.h.PlayerModUiToggle, true)
    startup.s.hudSimulationEnabled = true
    startup.s.sessionInfoHudEnabled = true
    startup.s.showSessionActivityHud = true
    startup.hud_cache.connected = 28
    startup.session_activity.entries = {}
    startup.hud_simulation.startedMs = startup.now()
    startup.hud_simulation.stage = 0
    startup.hud_simulation.cycle = 0
    startup.toast("Notification feed demo started. Custom Startup cards are the default; native mode remains optional.", 5000)
end

function startup.stop_hud_simulation()
    startup.s.hudSimulationEnabled = false
    startup.session_activity.entries = {}
    startup.hud_simulation.startedMs = 0
    startup.hud_simulation.stage = 0
    startup.update_hud_cache(true)
    startup.toast("HUD Simulation disabled. Live session data restored.", 3000)
end

startup.modder_hud = startup.modder_hud or { entries = {}, order = {}, lastPruneMs = 0, leaveGraceMs = 10000 }
startup.modder_hud.leaveGraceMs = 10000

startup.rac_report_reasons = {
    { key = "CODE_TAMPERING", label = "RAC: Code Tampering" },
    { key = "CRC_CODE_CRCS", label = "RAC: CRC Code" },
    { key = "CRC_COMPROMISED", label = "RAC: CRC Compromised" },
    { key = "CRC_EXE_SIZE", label = "RAC: EXE Size" },
    { key = "CRC_NOT_REPLIED", label = "RAC: CRC No Reply" },
    { key = "CRC_REQUEST_FLOOD", label = "RAC: CRC Request Flood" },
    { key = "GAME_SERVER_CASH_BANK", label = "RAC: Cash / Bank" },
    { key = "GAME_SERVER_CASH_WALLET", label = "RAC: Cash / Wallet" },
    { key = "GAME_SERVER_INVENTORY", label = "RAC: Inventory" },
    { key = "GAME_SERVER_SERVER_INTEGRITY", label = "RAC: Server Integrity" },
    { key = "SCRIPT_CHEAT_DETECTION", label = "RAC: Script Cheat Detection" },
    { key = "TELEMETRY_BLOCK", label = "RAC: Telemetry Block" }
}

function startup.modder_hud_merge_reason(currentReason, newReason)
    local current = tostring(currentReason or ""):gsub("^%s+", ""):gsub("%s+$", "")
    local incoming = tostring(newReason or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if incoming == "" or incoming == "Unknown" then return current ~= "" and current or "Unknown" end
    if current == "" or current == "Unknown" or current == "Cherax modder flag" then return incoming end
    if incoming == "Cherax modder flag" then return current end
    if string.find(string.lower(current), string.lower(incoming), 1, true) then return current end
    return current .. " | " .. incoming
end

function startup.modder_hud_record(name, reason, playerId)
    name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    reason = tostring(reason or "Unknown"):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then return end
    if startup.s.ignoreFriendsModder == true and ((tonumber(playerId) ~= nil and startup.is_player_current_friend(playerId)) or startup.is_name_current_friend(name)) then return end
    -- Any enabled/accepted modder reason is stored locally by RID for future Startup checks.
    -- Ignore Friends is evaluated above; noisy/non-modder reasons are filtered before reaching here.
    if tonumber(playerId) ~= nil and startup.rid_store and startup.rid_store.record then
        startup.rid_store.record(playerId, "Modder Detection", reason, "Logged locally", false)
    end
    if reason == "" then reason = "Unknown" end
    local key = string.lower(name)
    local existing = startup.modder_hud.entries[key]
    if not existing then
        startup.modder_hud.order[#startup.modder_hud.order + 1] = key
        existing = { name = name, reason = reason, playerId = tonumber(playerId), firstSeenMs = startup.now() }
    else
        existing.name = name
        existing.reason = startup.modder_hud_merge_reason(existing.reason, reason)
        if tonumber(playerId) ~= nil then existing.playerId = tonumber(playerId) end
    end
    existing.lastSeenMs = startup.now()
    startup.modder_hud.entries[key] = existing
    if startup.session_activity_update_classification then
        startup.session_activity_update_classification(playerId, name, "known_modder")
    end
end

function startup.modder_hud_remove(name, playerId)
    local wantedName = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    local wantedKey = wantedName ~= "" and string.lower(wantedName) or nil
    local wantedId = tonumber(playerId)
    local nextOrder = {}
    for _, key in ipairs(startup.modder_hud.order or {}) do
        local entry = startup.modder_hud.entries[key]
        local remove = false
        if entry then
            if wantedKey and key == wantedKey then remove = true end
            if wantedId ~= nil and tonumber(entry.playerId) == wantedId then remove = true end
        end
        if remove then
            startup.modder_hud.entries[key] = nil
        elseif entry then
            nextOrder[#nextOrder + 1] = key
        end
    end
    startup.modder_hud.order = nextOrder
end

function startup.modder_hud_clear()
    startup.modder_hud.entries = {}
    startup.modder_hud.order = {}
    startup.modder_hud.lastPruneMs = 0
end

function startup.modder_hud_mark_left(name, playerId)
    local wantedName = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    local wantedKey = wantedName ~= "" and string.lower(wantedName) or nil
    local wantedId = tonumber(playerId)
    local now = startup.now()
    for _, key in ipairs(startup.modder_hud.order or {}) do
        local entry = startup.modder_hud.entries[key]
        if entry then
            local matches = wantedKey ~= nil and key == wantedKey
            if wantedId ~= nil and tonumber(entry.playerId) == wantedId then matches = true end
            if matches then
                entry.leftAtMs = now
                entry.leftConfirmed = true
            end
        end
    end
end

function startup.modder_hud_mark_joined(name, playerId)
    local wantedName = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    local wantedKey = wantedName ~= "" and string.lower(wantedName) or nil
    local wantedId = tonumber(playerId)
    for _, key in ipairs(startup.modder_hud.order or {}) do
        local entry = startup.modder_hud.entries[key]
        if entry then
            local matches = wantedKey ~= nil and key == wantedKey
            if wantedId ~= nil and tonumber(entry.playerId) == wantedId then matches = true end
            if matches then
                if wantedName ~= "" then entry.name = wantedName end
                if wantedId ~= nil then entry.playerId = wantedId end
                entry.leftAtMs = nil
                entry.leftConfirmed = false
                entry.lastSeenMs = startup.now()
            end
        end
    end
end


startup.mod_detection = startup.mod_detection or {}


function startup.mod_detection.normalize_flag_name(reason)
    local normalized = string.lower(tostring(reason or ""))
    normalized = normalized:gsub("[_%-]+", " "):gsub("%s+", " ")
    normalized = normalized:gsub("^%s+", ""):gsub("%s+$", "")
    return normalized
end

function startup.mod_detection.make_flag_set(items)
    local out = {}
    for _, item in ipairs(items or {}) do
        out[startup.mod_detection.normalize_flag_name(item)] = true
    end
    return out
end

