function startup.mod_detection.is_non_modder_noise_reason(reason)
    local normalized = startup.mod_detection.normalize_flag_name(reason)
    if normalized == "" then return false end
    local compact = normalized:gsub("[^%a%d]", "")
    -- Build 439: PTFX and Stun Gun detections are protection/diagnostic noise,
    -- not evidence that the attributed player is a modder. Match variants too.
    if string.find(normalized, "ptfx", 1, true) ~= nil then return true end
    if string.find(normalized, "stun gun", 1, true) ~= nil then return true end
    if string.find(compact, "stungun", 1, true) ~= nil then return true end
    return false
end

function startup.mod_detection.classify_reason(reason)
    local normalized = startup.mod_detection.normalize_flag_name(reason)
    if normalized == "" then return "empty", false end
    if startup.mod_detection.is_non_modder_noise_reason(reason) then return "ignored", false end
    local known = startup.mod_detection.known_flag_set[normalized] == true

    if startup.mod_detection.ignored_flag_set[normalized] == true then return "ignored", false end
    if startup.mod_detection.is_rac_reason and startup.mod_detection.is_rac_reason(reason) then return "rac", known end
    if string.find(normalized, "explosion", 1, true) then return "explosion", known end
    if startup.mod_detection.crash_flag_set[normalized] == true or string.find(normalized, "crash", 1, true) then return "crash", known end
    if startup.mod_detection.kick_flag_set[normalized] == true then return "kick", known end
    if string.find(normalized, "battleye", 1, true) or string.find(normalized, "battleeye", 1, true) then return "battleye", known end
    if startup.mod_detection.high_confidence_flag_set[normalized] == true then return "high", known end
    if known then return "low", true end
    return "unknown", false
end

function startup.mod_detection.is_rac_reason(reason)
    local lower = string.lower(tostring(reason or ""))
    if string.find(lower, "rockstar anti cheat", 1, true) then return true end
    if string.find(lower, "rockstar anti-cheat", 1, true) then return true end
    return string.find(lower, "%f[%w]rac%f[%W]") ~= nil
end

function startup.mod_detection.is_drop_kick_doping_reason(reason)
    local lower = string.lower(tostring(reason or ""))
    lower = lower:gsub("[_%-]+", " "):gsub("%s+", " ")
    return string.find(lower, "drop kick doping", 1, true) ~= nil
        or (string.find(lower, "drop kick", 1, true) ~= nil and string.find(lower, "doping", 1, true) ~= nil)
end

function startup.mod_detection.is_invalid_interior_warp_reason(reason)
    local normalized = startup.mod_detection.normalize_flag_name(reason)
    local compact = normalized:gsub("[^%a%d]", "")
    if string.find(compact, "invalidinteriorwarp", 1, true) ~= nil then return true end
    if string.find(compact, "invaidinteriorwarp", 1, true) ~= nil then return true end
    local hasInteriorWarp = string.find(normalized, "interior warp", 1, true) ~= nil
    local hasInvalid = string.find(normalized, "invalid", 1, true) ~= nil
        or string.find(normalized, "invaid", 1, true) ~= nil
    return hasInteriorWarp and hasInvalid
end

function startup.mod_detection.is_crash_attack_reason(reason)
    local lower = string.lower(tostring(reason or ""))
    lower = lower:gsub("[_%-]+", " "):gsub("%s+", " ")
    -- Cherax crash detections have appeared under several names (for example
    -- Auxiliary/Auxillary Crash). A readable Modder Detection reason containing
    -- "crash" is treated as a high-confidence crash signal, not a normal modder flag.
    return string.find(lower, "crash", 1, true) ~= nil
end

function startup.mod_detection.is_standalone_spam_reason(reason)
    return startup.mod_detection.standalone_spam_flag_set[startup.mod_detection.normalize_flag_name(reason)] == true
end

function startup.mod_detection.is_strong_corroborating_reason(reason)
    if startup.mod_detection.is_standalone_spam_reason(reason) then return false end
    if startup.mod_detection.is_drop_kick_doping_reason(reason) then return false end
    if startup.mod_detection.is_invalid_interior_warp_reason(reason) then return false end
    local category, known = startup.mod_detection.classify_reason(reason)
    if category == "crash" or category == "kick" or category == "battleye" or category == "high" then return true end
    return known == true and category ~= "ignored" and category ~= "low" and category ~= "rac" and category ~= "explosion"
end

function startup.mod_detection.should_include_reason(reason)
    local lower = startup.mod_detection.normalize_flag_name(reason)
    if lower == "" or lower == "unknown" or lower == "cherax modder flag" then return false, "empty" end

    local category, known = startup.mod_detection.classify_reason(reason)

    if startup.mod_detection.is_drop_kick_doping_reason(reason) then
        return startup.s.modDetectionIncludeDropKickDoping == true, "drop-kick-doping-optional-likely-false-positive"
    end

    if startup.mod_detection.is_invalid_interior_warp_reason(reason) then
        return startup.s.modDetectionIncludeInvalidInteriorWarp == true, "invalid-interior-warp-optional-likely-false-positive"
    end

    if startup.mod_detection.is_non_modder_noise_reason(reason) then
        return false, "ptfx-stun-gun-non-modder-noise-b439"
    end

    if category == "ignored" then
        return false, "ignored-non-modder-reason"
    end

    if startup.mod_detection.is_standalone_spam_reason(reason) then
        return false, "standalone-ped-vehicle-spam-needs-corroboration"
    end

    -- Exact catalog labels remain modder evidence except the explicitly noisy
    -- cases above. Attack responses still require dedicated confirmation logic.
    if known then
        return true, "confirmed-catalog-" .. tostring(category)
    end

    -- Unlisted RAC-style detections remain optional because they are not part of the
    -- confirmed catalog and can be noisy.
    if category == "rac" then
        return startup.s.modDetectionIncludeRac == true, "unlisted-rac-optional"
    end

    -- Unlisted explosion-style detections remain optional.
    if category == "explosion" then
        return startup.s.modDetectionIncludeExplosions == true, "unlisted-explosion-optional"
    end

    -- Unknown readable detections remain visible for diagnostics.
    return true, "unknown-readable-included"
end

function startup.rac_reasons_for_player(playerId)
    if not Players or not Players.GetById or not eReportReason then return {} end
    local player = Players.GetById(playerId)
    if not player or not player.IsReportBitSet then return {} end
    if player.IsLocalPlayer and player:IsLocalPlayer() then return {} end
    local found = {}
    for _, item in ipairs(startup.rac_report_reasons or {}) do
        local reportReason = eReportReason[item.key]
        if reportReason ~= nil and player:IsReportBitSet(reportReason) then
            found[#found + 1] = item.label
        end
    end
    return found
end

function startup.cherax_modder_reasons_for_player(playerId)
    if not ModderDB or not ModderDB.GetModderDetectionsByPlayerId then return {}, 0 end
    local detections = ModderDB.GetModderDetectionsByPlayerId(playerId)
    if type(detections) ~= "table" then return {}, 0 end

    local rawReasons = {}
    local readableCount = 0
    for _, detection in pairs(detections) do
        local reason = nil
        if type(detection) == "table" then
            reason = detection[1] or detection.name or detection.detection or detection.reason
        elseif type(detection) == "string" then
            reason = detection
        end
        reason = tostring(reason or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if reason ~= "" and reason ~= "Unknown" and reason ~= "Cherax modder flag" then
            readableCount = readableCount + 1
            rawReasons[#rawReasons + 1] = reason
        end
    end

    local hasStrongCorroboration = false
    for _, reason in ipairs(rawReasons) do
        if startup.mod_detection.is_strong_corroborating_reason(reason) then
            hasStrongCorroboration = true
            break
        end
    end

    local found, seen = {}, {}
    for _, reason in ipairs(rawReasons) do
        local include = false
        if startup.mod_detection.is_standalone_spam_reason(reason) then
            include = hasStrongCorroboration
        else
            include = startup.mod_detection.should_include_reason(reason)
        end
        local key = string.lower(reason)
        if include and not seen[key] then
            seen[key] = true
            found[#found + 1] = reason
        end
    end
    return found, readableCount
end

function startup.modder_hud_active_players_snapshot()
    local activeIds = {}
    local activeNames = {}
    if not Players or not Players.Get then return activeIds, activeNames end
    local players = Players.Get(ePlayerListSort.PLAYER_ID, "")
    if not players then return activeIds, activeNames end
    for _, playerId in pairs(players) do
        local id = tonumber(playerId)
        if id ~= nil then
            id = math.floor(id)
            activeIds[id] = true
            local name = startup.nuke_join_kick and startup.nuke_join_kick.get_player_name and startup.nuke_join_kick.get_player_name(id)
                or (Players.GetName and Players.GetName(id) or nil)
            name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if name ~= "" and name ~= "Invalid" then activeNames[string.lower(name)] = true end
        end
    end
    return activeIds, activeNames
end

function startup.modder_hud_prune()
    local now = startup.now()
    if now - (startup.modder_hud.lastPruneMs or 0) < 1000 then return end
    startup.modder_hud.lastPruneMs = now

    local activeIds, activeNames = startup.modder_hud_active_players_snapshot()
    for playerId = 0, 31 do
        if activeIds[playerId] == true then
            local name = startup.nuke_join_kick and startup.nuke_join_kick.get_player_name and startup.nuke_join_kick.get_player_name(playerId)
                or (Players and Players.GetName and Players.GetName(playerId) or nil)
            if name and tostring(name) ~= "" and tostring(name) ~= "Invalid" then
                name = tostring(name)
                startup.session_activity.knownPlayers[playerId] = name
                local key = string.lower(name)
                local cheraxReasons = startup.cherax_modder_reasons_for_player(playerId)
                if #cheraxReasons > 0 then
                    startup.modder_hud_record(name, table.concat(cheraxReasons, " | "), playerId)
                    for _, detectedReason in ipairs(cheraxReasons) do
                        if startup.mod_detection.is_crash_attack_reason(detectedReason)
                            and startup.crash_defense and startup.crash_defense.handle_modder_crash_detection then
                            startup.crash_defense.handle_modder_crash_detection(playerId, name, detectedReason, "ModderDB")
                        end
                    end
                end

                if startup.s.modDetectionIncludeRac == true then
                    local racReasons = startup.rac_reasons_for_player(playerId)
                    if #racReasons > 0 then
                        startup.modder_hud_record(name, table.concat(racReasons, " | "), playerId)
                    end
                end
                if startup.modder_hud.entries[key] and tonumber(startup.modder_hud.entries[key].playerId) == nil then
                    startup.modder_hud.entries[key].playerId = playerId
                end
            end
        end
    end

    local graceMs = tonumber(startup.modder_hud.leaveGraceMs or 10000) or 10000
    local nextOrder = {}
    for _, key in ipairs(startup.modder_hud.order or {}) do
        local entry = startup.modder_hud.entries[key]
        if entry then
            local id = tonumber(entry.playerId)
            local active = (id ~= nil and activeIds[id] == true) or activeNames[key] == true
            if entry.leftConfirmed == true or not active then
                if entry.leftAtMs == nil then entry.leftAtMs = now end
                if now - (tonumber(entry.leftAtMs) or now) >= graceMs then
                    startup.modder_hud.entries[key] = nil
                else
                    nextOrder[#nextOrder + 1] = key
                end
            else
                entry.leftAtMs = nil
                entry.leftConfirmed = false
                nextOrder[#nextOrder + 1] = key
            end
        end
    end
    startup.modder_hud.order = nextOrder
end

function startup.modder_hud_list()
    startup.modder_hud_prune()
    local out = {}
    for _, key in ipairs(startup.modder_hud.order) do if startup.modder_hud.entries[key] then out[#out + 1] = startup.modder_hud.entries[key] end end
    return out
end

function startup.hud_group(groups, key, orderValue, defaultRank, lines)
    if type(groups) ~= "table" then return end
    if type(lines) ~= "table" or #lines == 0 then return end
    groups[#groups + 1] = { key = tostring(key or ""), order = startup.clamp_int(orderValue or defaultRank or 1, 1, 8), rank = tonumber(defaultRank or 1) or 1, lines = lines }
end

function startup.render_singleplayer_ready_hud()
    local x = startup.get_effective_hud_x(startup.s.sessionInfoHudX or 0.169)
    local y = startup.s.sessionInfoHudY or 0.941
    local scale = startup.s.sessionInfoHudScale or 0.30
    local alpha = startup.s.sessionInfoHudAlpha or 200
    local lineGap = math.max(0.024, scale * 0.082)
    local keyName = tostring(startup.s.startSessionHotkeyName or "Pause / Break")
    local keyLabel = string.upper(keyName)

    startup.draw_hud_text("~r~Startup~w~ ready.", x, y - lineGap, scale, 255, 255, 255, alpha, 4)
    if keyName == "Disabled" then
        startup.draw_hud_text("~w~Open Startup and press ~y~START SESSION~w~.", x, y, scale, 255, 255, 255, alpha, 4)
    else
        startup.draw_hud_text("~w~Press ~y~" .. keyLabel .. "~w~ key to start GTA Online.", x, y, scale, 255, 255, 255, alpha, 4)
    end
    startup.s.lastHudStatus = "Singleplayer ready prompt"
end

function startup.enforce_locked_advertise_status_hud()
    startup.s.showAdvertiseStatusHud = true
    startup.s.advertiseStatusHudDefaultVersion = startup.advertise_status_hud_default_version
    startup.s.advertiseStatusHudX = 0.023
    startup.s.advertiseStatusHudY = 0.981
    startup.s.advertiseStatusHudScale = 0.25
    startup.s.advertiseStatusHudAlpha = 200
    startup.s.advertiseStatusHudShadow = true
end

function startup.get_advertise_status_hud_display_count(actualCount)
    local actual = math.max(0, math.floor(tonumber(actualCount or 0) or 0))
    local multiplier = math.max(1, math.floor(tonumber(startup.advertise_status_hud_display_multiplier or 2) or 2))
    return actual * multiplier
end

function startup.sync_native_advertise_count_visual_to_hud(displayValue, source)
    local display = math.max(0, math.min(20, math.floor(tonumber(displayValue or 0) or 0)))
    startup.s.advertiseHudNativeSliderDisplay = display
    if startup.native_advertise_count_visual_set_display then
        return startup.native_advertise_count_visual_set_display(display, source or "Advertise HUD")
    end
    return false
end

function startup.reset_advertise_hud_terminal_state()
    startup.s.advertiseHudTerminalDisplayCount = 0
    startup.s.advertiseHudTerminalSequenceKey = ""
    startup.s.advertiseHudTerminalSequenceSteps = nil
    startup.s.advertiseHudTerminalSequenceStepIndex = 0
    startup.s.advertiseHudTerminalSequenceStepStartedAtMs = 0
    startup.s.advertiseHudTerminalSequenceFinalDisplay = 0
    startup.s.advertiseHudTerminalSequenceSyncedStepIndex = 0
    startup.s.advertiseHudStartupBoostShown = false
    startup.sync_native_advertise_count_visual_to_hud(0, "Advertise HUD reset")
end

function startup.begin_advertise_hud_terminal_sequence(key, steps, finalDisplay)
    if type(steps) ~= "table" or #steps == 0 then return false end
    startup.s.advertiseHudTerminalSequenceKey = tostring(key or "sequence")
    startup.s.advertiseHudTerminalSequenceSteps = steps
    startup.s.advertiseHudTerminalSequenceStepIndex = 1
    startup.s.advertiseHudTerminalSequenceStepStartedAtMs = startup.now()
    startup.s.advertiseHudTerminalSequenceFinalDisplay = math.max(0, math.floor(tonumber(finalDisplay or 0) or 0))
    startup.s.advertiseHudTerminalSequenceSyncedStepIndex = 0
    return true
end

function startup.finish_advertise_hud_terminal_sequence()
    local finalDisplay = math.max(0, math.floor(tonumber(startup.s.advertiseHudTerminalSequenceFinalDisplay or 0) or 0))
    if finalDisplay > 0 then
        startup.s.advertiseHudTerminalDisplayCount = finalDisplay
        startup.sync_native_advertise_count_visual_to_hud(finalDisplay, "Advertise HUD sequence complete")
    end
    startup.s.advertiseHudTerminalSequenceKey = ""
    startup.s.advertiseHudTerminalSequenceSteps = nil
    startup.s.advertiseHudTerminalSequenceStepIndex = 0
    startup.s.advertiseHudTerminalSequenceStepStartedAtMs = 0
    startup.s.advertiseHudTerminalSequenceFinalDisplay = 0
    startup.s.advertiseHudTerminalSequenceSyncedStepIndex = 0
end

function startup.get_advertise_hud_terminal_sequence_line(now)
    local steps = startup.s.advertiseHudTerminalSequenceSteps
    local index = math.max(1, math.floor(tonumber(startup.s.advertiseHudTerminalSequenceStepIndex or 1) or 1))
    if type(steps) ~= "table" or not steps[index] then return nil end

    while steps[index] do
        local step = steps[index]
        local text = tostring(step.text or "")
        local prefix = tostring(step.prefix or "")
        local color = type(step.color) == "table" and step.color or {255, 190, 65}
        local syncDisplay = tonumber(step.syncDisplay)
        if syncDisplay ~= nil and tonumber(startup.s.advertiseHudTerminalSequenceSyncedStepIndex or 0) ~= index then
            startup.sync_native_advertise_count_visual_to_hud(syncDisplay, "Advertise HUD step " .. tostring(index))
            startup.s.advertiseHudTerminalSequenceSyncedStepIndex = index
        end
        local startedAt = tonumber(startup.s.advertiseHudTerminalSequenceStepStartedAtMs or now) or now
        local elapsed = math.max(0, now - startedAt)
        local holdMs = math.max(0, tonumber(step.holdMs or startup.advertise_status_hud_value_hold_ms or 5000) or 5000)

        if step.typed == true then
            local charMs = math.max(15, tonumber(step.charMs or startup.advertise_status_hud_typing_char_ms or 34) or 34)
            local requestedDuration = tonumber(step.typeDurationMs or 0) or 0
            local typingMs = requestedDuration > 0
                and math.max(250, requestedDuration)
                or math.max(charMs, string.len(text) * charMs)

            if elapsed < typingMs then
                local visibleCount = 0
                if string.len(text) > 0 then
                    visibleCount = math.max(0, math.min(string.len(text),
                        math.floor((elapsed / typingMs) * string.len(text))))
                end
                local visibleText = string.sub(text, 1, visibleCount)
                local blinkMs = math.max(80, tonumber(startup.advertise_status_hud_cursor_blink_ms or 180) or 180)
                local cursor = (math.floor(elapsed / blinkMs) % 2 == 0) and "_" or ""
                return prefix .. visibleText .. cursor, color
            end
            if elapsed < (typingMs + holdMs) then
                return prefix .. text, color
            end
        elseif elapsed < holdMs then
            return prefix .. text, color
        end

        index = index + 1
        startup.s.advertiseHudTerminalSequenceStepIndex = index
        startup.s.advertiseHudTerminalSequenceStepStartedAtMs = now
        if not steps[index] then
            startup.finish_advertise_hud_terminal_sequence()
            return nil
        end
    end

    startup.finish_advertise_hud_terminal_sequence()
    return nil
end

function startup.get_advertise_hud_tier_label(displayCount)
    local count = math.max(0, math.floor(tonumber(displayCount or 0) or 0))
    if count <= 5 then return "Low" end
    if count <= 10 then return "Medium" end
    if count < 20 then return "High" end
    return "Max"
end

function startup.get_advertise_hud_tier_line(displayCount)
    return "Advertise Count: " .. startup.get_advertise_hud_tier_label(displayCount)
end

function startup.begin_advertise_hud_startup_boost_sequence()
    if startup.s.advertiseHudStartupBoostShown == true then return false end
    startup.s.advertiseHudStartupBoostShown = true
    local typeMs = math.max(500, tonumber(startup.advertise_status_hud_transition_type_ms or 3000) or 3000)
    return startup.begin_advertise_hud_terminal_sequence("startup-boost", {
        {
            text = "Boosting Advertise Count...",
            typed = true,
            typeDurationMs = typeMs,
            holdMs = 2000,
            color = {255, 190, 65},
            syncDisplay = 0
        }
    }, 0)
end

function startup.begin_advertise_hud_intro_sequence()
    local amber = {255, 190, 65}
    local green = {95, 255, 125}
    local prefix = "Advertise Count: "
    local typeMs = math.max(500, tonumber(startup.advertise_status_hud_transition_type_ms or 3000) or 3000)
    local setHold = math.max(500, tonumber(startup.advertise_status_hud_set_hold_ms or 3000) or 3000)
    local tierHold = math.max(1000, tonumber(startup.advertise_status_hud_tier_hold_ms or 5000) or 5000)

    return startup.begin_advertise_hud_terminal_sequence("intro", {
        { prefix = prefix, text = "1... Setting it to 5!", typed = true, typeDurationMs = typeMs, holdMs = 0, color = amber, syncDisplay = 1 },
        { text = "Advertise Count: 5... set!", holdMs = setHold, color = green, syncDisplay = 5 },
        { text = "Advertise Count: Low", holdMs = tierHold, color = green, syncDisplay = 5 },

        { prefix = prefix, text = "5... Setting it to 10!", typed = true, typeDurationMs = typeMs, holdMs = 0, color = amber, syncDisplay = 5 },
        { text = "Advertise Count: 10... set!", holdMs = setHold, color = green, syncDisplay = 10 },
        { text = "Advertise Count: Medium", holdMs = tierHold, color = green, syncDisplay = 10 },

        { prefix = prefix, text = "10... Setting it to 15!", typed = true, typeDurationMs = typeMs, holdMs = 0, color = amber, syncDisplay = 10 },
        { text = "Advertise Count: 15... set!", holdMs = setHold, color = green, syncDisplay = 15 },
        { text = "Advertise Count: High", holdMs = tierHold, color = green, syncDisplay = 15 },

        { prefix = prefix, text = "15... Setting it to 20!", typed = true, typeDurationMs = typeMs, holdMs = 0, color = amber, syncDisplay = 15 },
        { text = "Advertise Count: 20... set!", holdMs = setHold, color = green, syncDisplay = 20 },
        { text = "Advertise Count: Max", holdMs = tierHold, color = green, syncDisplay = 20 }
    }, 20)
end

function startup.begin_advertise_hud_full_lobby_sequence()
    local typeMs = math.max(500, tonumber(startup.advertise_status_hud_transition_type_ms or 3000) or 3000)
    local setHold = math.max(500, tonumber(startup.advertise_status_hud_set_hold_ms or 3000) or 3000)
    local tierHold = math.max(1000, tonumber(startup.advertise_status_hud_tier_hold_ms or 5000) or 5000)
    return startup.begin_advertise_hud_terminal_sequence("full-lobby", {
        { text = "Max players received! Reducing Advertise Count to 10!", typed = true, typeDurationMs = typeMs, holdMs = 0, color = {255, 190, 65}, syncDisplay = 20 },
        { text = "Advertise Count: 10... set!", holdMs = setHold, color = {95, 255, 125}, syncDisplay = 10 },
        { text = "Advertise Count: Medium", holdMs = tierHold, color = {95, 255, 125}, syncDisplay = 10 }
    }, 10)
end

function startup.begin_advertise_hud_low_players_sequence()
    local typeMs = math.max(500, tonumber(startup.advertise_status_hud_transition_type_ms or 3000) or 3000)
    local setHold = math.max(500, tonumber(startup.advertise_status_hud_set_hold_ms or 3000) or 3000)
    local tierHold = math.max(1000, tonumber(startup.advertise_status_hud_tier_hold_ms or 5000) or 5000)
    return startup.begin_advertise_hud_terminal_sequence("low-players", {
        { text = "Players getting low... Setting Advertise Count to 20!", typed = true, typeDurationMs = typeMs, holdMs = 0, color = {255, 190, 65}, syncDisplay = 10 },
        { text = "Advertise Count: 20... set!", holdMs = setHold, color = {95, 255, 125}, syncDisplay = 20 },
        { text = "Advertise Count: Max", holdMs = tierHold, color = {95, 255, 125}, syncDisplay = 20 }
    }, 20)
end

function startup.get_legacy_advertise_progression_line(actualCount, now)
    local actual = math.max(0, math.floor(tonumber(actualCount or 0) or 0))
    if actual <= 0 then return nil end

    local playerCount = math.max(0, math.floor(tonumber(startup.get_session_player_count() or 0) or 0))
    local highLimit = math.max(1, math.floor(tonumber(startup.s.advertisePlayerTarget or 30) or 30))
    local visualResumeAt = math.max(0, math.floor(tonumber(startup.s.advertiseResumeBelow or 25) or 25))
    local displayCount = math.max(0, math.floor(tonumber(startup.s.advertiseHudTerminalDisplayCount or 0) or 0))
    local sequenceKey = tostring(startup.s.advertiseHudTerminalSequenceKey or "")

    -- Full-lobby reduction has priority and can interrupt the opening animation.
    if playerCount >= highLimit then
        if sequenceKey ~= "full-lobby" and displayCount ~= 10 then
            startup.begin_advertise_hud_full_lobby_sequence()
        end
    elseif displayCount <= 0 and sequenceKey == "" then
        if startup.s.advertiseHudStartupBoostShown ~= true then
            startup.begin_advertise_hud_startup_boost_sequence()
        else
            startup.begin_advertise_hud_intro_sequence()
        end
    elseif playerCount <= visualResumeAt and displayCount == 10 and sequenceKey == "" then
        -- Visual hysteresis returns to 20 at 25 players, while native Cherax logic
        -- remains untouched and continues using the real 5 / 10 values.
        startup.begin_advertise_hud_low_players_sequence()
    end

    local animatedText, animatedColor = startup.get_advertise_hud_terminal_sequence_line(now)
    if animatedText then return animatedText, animatedColor end

    displayCount = math.max(0, math.floor(tonumber(startup.s.advertiseHudTerminalDisplayCount or 0) or 0))
    if displayCount <= 0 then
        displayCount = startup.get_advertise_status_hud_display_count(actual)
        startup.s.advertiseHudTerminalDisplayCount = displayCount
    end
    startup.sync_native_advertise_count_visual_to_hud(displayCount, "Advertise HUD steady state")
    return startup.get_advertise_hud_tier_line(displayCount), {95, 255, 125}
end

function startup.get_advertise_countdown_ellipsis(now)
    local current = tonumber(now or startup.now()) or 0
    local interval = math.max(100, tonumber(startup.advertise_status_hud_countdown_dot_ms or 325) or 325)
    local dotCount = (math.floor(current / interval) % 3) + 1
    return string.rep(".", dotCount)
end

function startup.get_advertise_countdown_line(seconds, now)
    local remaining = math.max(0, math.floor(tonumber(seconds or 0) or 0))
    startup.sync_native_advertise_count_visual_to_hud(0, "Advertise countdown")
    return "Advertise Count: " .. tostring(remaining) .. " seconds before advertising"
        .. startup.get_advertise_countdown_ellipsis(now), {255, 190, 65}
end

function startup.get_advertise_status_hud_line()
    if startup.s.showAdvertiseStatusHud ~= true then return nil end

    local now = startup.now()
    local previewUntil = tonumber(startup.s.advertiseStatusHudPreviewUntilMs or 0) or 0
    if previewUntil > now then
        local seconds = math.max(0, math.ceil((previewUntil - now) / 1000))
        return "Advertise Count: HUD preview | " .. tostring(seconds) .. "s", {95, 205, 255}
    end

    if startup.s.autoAdvertiseSession ~= true then return nil end
    if startup.is_gta_online_session_ready and not startup.is_gta_online_session_ready() then return nil end

    -- Build 160: keep the HUD visible through the optional LuaContent delay. The
    -- advertised time includes both the remaining Lua delay and Startup's normal
    -- two-minute stabilization delay before native advertising begins.
    if startup.s.advertiseRunning ~= true then
        if startup.s.sessionLuaLoadRunning == true then
            local luaEndAt = tonumber(startup.s.sessionLuaLoadEndsAtMs or 0) or 0
            if luaEndAt > now then
                local advertiseEndAt = luaEndAt + (tonumber(startup.s.advertiseDelayAfterSessionMs or 120000) or 120000)
                local seconds = math.max(0, math.ceil((advertiseEndAt - now) / 1000))
                return startup.get_advertise_countdown_line(seconds, now)
            end
            startup.sync_native_advertise_count_visual_to_hud(0, "Preparing Advertising")
            return "Advertise Count: Preparing Advertising" .. startup.get_advertise_countdown_ellipsis(now), {255, 190, 65}
        end

        local changedAt = tonumber(startup.s.lastSessionChangeMs or 0) or 0
        if changedAt > 0 and (now - changedAt) <= 15000 then
            startup.sync_native_advertise_count_visual_to_hud(0, "Preparing Advertising")
            return "Advertise Count: Preparing Advertising" .. startup.get_advertise_countdown_ellipsis(now), {255, 190, 65}
        end
        return nil
    end

    if startup.s.advertiseSmartActive ~= true then
        local endAt = tonumber(startup.s.advertiseCountdownEndsAtMs or 0) or 0
        if endAt > now then
            local seconds = math.max(0, math.ceil((endAt - now) / 1000))
            return startup.get_advertise_countdown_line(seconds, now)
        end

        -- Build 177: once the two-minute wait ends, begin the terminal-style boost
        -- phase immediately. The native advertising workflow continues independently;
        -- this sequence only controls the visual HUD and synchronized cosmetic slider.
        if tostring(startup.s.advertiseHudTerminalSequenceKey or "") == ""
            and startup.s.advertiseHudStartupBoostShown ~= true then
            startup.begin_advertise_hud_startup_boost_sequence()
        end
        local boostingText, boostingColor = startup.get_advertise_hud_terminal_sequence_line(now)
        if boostingText then return boostingText, boostingColor end

        startup.sync_native_advertise_count_visual_to_hud(0, "Boosting Advertise Count")
        return "Boosting Advertise Count" .. startup.get_advertise_countdown_ellipsis(now), {255, 190, 65}
    end

    if startup.is_enhanced_active_edition() then
        local region = tostring(startup.get_advertise_region_label(false) or startup.s.advertiseRegionLabel or "Unknown")
        return "Advertising: Active | Region: " .. region, {95, 255, 125}
    end

    local count = tonumber(startup.s.advertiseCurrentCount or 0) or 0
    if count > 0 then
        local text, color = startup.get_legacy_advertise_progression_line(count, now)
        if text then return text, color end
    end
    if startup.s.advertiseFeatureUnavailable == true then
        startup.sync_native_advertise_count_visual_to_hud(0, "Advertise unavailable")
        return "Advertise Count: Unavailable", {255, 95, 95}
    end
    startup.sync_native_advertise_count_visual_to_hud(0, "Advertise starting")
    return "Advertise Count: Starting...", {255, 190, 65}
end

function startup.render_advertise_status_hud()
    startup.enforce_locked_advertise_status_hud()
    local text, color = startup.get_advertise_status_hud_line()
    if not text then return end
    -- Build 405: legacy status providers are allowed to return text without a
    -- color tuple. Never let that kill the entire HUD frame loop.
    if type(color) ~= "table" then color = {255,255,255} end
    color[1] = tonumber(color[1] or 255) or 255
    color[2] = tonumber(color[2] or 255) or 255
    color[3] = tonumber(color[3] or 255) or 255

    local x = startup.get_effective_hud_x(startup.s.advertiseStatusHudX or 0.023)
    local y = startup.clamp_float(tonumber(startup.s.advertiseStatusHudY or 0.981) or 0.968, 0.70, 0.985)
    local scale = startup.clamp_float(tonumber(startup.s.advertiseStatusHudScale or 0.25) or 0.30, 0.20, 0.55)
    local alpha = startup.clamp_int(tonumber(startup.s.advertiseStatusHudAlpha or 200) or 200, 70, 255)

    -- Build 161: clean Session Info HUD-style text only. No black card or accent bar.
    local timerText = startup.advertise_benchmark_live_text and startup.advertise_benchmark_live_text() or nil
    if timerText then
        local timerY = y - math.max(0.020, scale * 0.080)
        startup.draw_hud_text(timerText, x, timerY, scale, 95, 255, 125, alpha, 4,
            startup.s.advertiseStatusHudShadow ~= false)
    end
    startup.draw_hud_text(text, x, y, scale, color[1], color[2], color[3], alpha, 4,
        startup.s.advertiseStatusHudShadow ~= false)
end

-- Build 389: user-customizable Session HUD palette.
startup.hud_color_defaults = startup.hud_color_defaults or {
    activityJoinBackdrop = {5,5,8},
    activityLeaveBackdrop = {5,5,8},
    connectedPlayers = {255,255,255},
    natOpen = {120,255,150},
    natModerate = {255,215,105},
    natStrict = {255,105,105},
    host = {120,205,255},
    nextHost = {255,220,110},
    friends = {70,255,95},
    trackedPlayers = {255,65,65},
    scriptHost = {190,135,255},
    regionMy = {120,205,255},
    regionOther = {120,205,255}
}
startup.hud_color_targets = startup.hud_color_targets or {
    "Activity Join Backdrop",
    "Activity Leave Backdrop",
    "Connected Players",
    "NAT - Open",
    "NAT - Moderate",
    "NAT - Strict",
    "Host",
    "Next Host",
    "Friends",
    "Tracked Players",
    "Script Host",
    "Region - My Region",
    "Region - Other"
}
startup.hud_color_target_keys = startup.hud_color_target_keys or {
    ["Activity Join Backdrop"]="activityJoinBackdrop",
    ["Activity Leave Backdrop"]="activityLeaveBackdrop",
    ["Connected Players"]="connectedPlayers",
    ["NAT - Open"]="natOpen",
    ["NAT - Moderate"]="natModerate",
    ["NAT - Strict"]="natStrict",
    ["Host"]="host",
    ["Next Host"]="nextHost",
    ["Friends"]="friends",
    ["Tracked Players"]="trackedPlayers",
    ["Script Host"]="scriptHost",
    ["Region - My Region"]="regionMy",
    ["Region - Other"]="regionOther"
}

function startup.hud_color_copy(color, fallback)
    local source = type(color)=="table" and color or fallback or {255,255,255}
    return {
        startup.clamp_int(tonumber(source[1] or source["1"] or source.r or 255) or 255,0,255),
        startup.clamp_int(tonumber(source[2] or source["2"] or source.g or 255) or 255,0,255),
        startup.clamp_int(tonumber(source[3] or source["3"] or source.b or 255) or 255,0,255)
    }
end

function startup.hud_colors_load(saved)
    local merged = {}
    for key, defaultColor in pairs(startup.hud_color_defaults or {}) do
        local candidate = type(saved)=="table" and saved[key] or nil
        merged[key] = startup.hud_color_copy(candidate, defaultColor)
    end
    startup.s.hudColors = merged
    local selected = tostring(startup.s.hudColorTarget or "Connected Players")
    if not startup.hud_color_target_keys[selected] then selected = "Connected Players" end
    startup.s.hudColorTarget = selected
    return merged
end

function startup.hud_color(key, fallback)
    startup.s.hudColors = type(startup.s.hudColors)=="table" and startup.s.hudColors or {}
    local defaultColor = (startup.hud_color_defaults or {})[key] or fallback or {255,255,255}
    local current = startup.s.hudColors[key]
    if type(current)~="table" then
        current = startup.hud_color_copy(defaultColor, defaultColor)
        startup.s.hudColors[key] = current
    end
    return current
end

function startup.hud_color_current_key()
    local selected = tostring(startup.s.hudColorTarget or "Connected Players")
    return startup.hud_color_target_keys[selected] or "connectedPlayers"
end

function startup.hud_color_sync_editor()
    local c = startup.hud_color(startup.hud_color_current_key(), {255,255,255})
    if startup.set_feature_int_silently and startup.h then
        startup.set_feature_int_silently(startup.h.HudColorRed, c[1])
        startup.set_feature_int_silently(startup.h.HudColorGreen, c[2])
        startup.set_feature_int_silently(startup.h.HudColorBlue, c[3])
    end
end

function startup.hud_color_set_channel(channel, value, saveNow)
    local key = startup.hud_color_current_key()
    local c = startup.hud_color(key, {255,255,255})
    local idx = channel=="r" and 1 or (channel=="g" and 2 or 3)
    c[idx] = startup.clamp_int(value or 0,0,255)
    startup.s.hudColors[key] = c
    if saveNow ~= false and startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
end

function startup.hud_colors_reset_defaults(saveNow)
    startup.s.hudColors = {}
    for key, c in pairs(startup.hud_color_defaults or {}) do startup.s.hudColors[key] = startup.hud_color_copy(c,c) end
    startup.hud_color_sync_editor()
    if saveNow ~= false and startup.s.initialized then startup.save_config(false) end
    if startup.toast then startup.toast("HUD colors reset to Startup defaults.",2600) end
end

-- Normalize defaults immediately; load_config will merge saved values later.
startup.hud_colors_load(startup.s.hudColors)

function startup.render_session_info_hud()
    if startup.s.playerModUiEnabled == false then return end
    if not startup.s.sessionInfoHudEnabled then return end
    if startup.is_gta_online_session_ready and not startup.is_gta_online_session_ready() then
        startup.render_singleplayer_ready_hud()
        return
    end
    startup.update_hud_cache(false)
    startup.update_hud_simulation()
    local x = startup.get_effective_hud_x(startup.s.sessionInfoHudX or 0.169)
    local y = startup.s.sessionInfoHudY or 0.941
    local scale = startup.s.sessionInfoHudScale or 0.30
    local alpha = startup.s.sessionInfoHudAlpha or 200
    local lineGap = math.max(0.020, scale * 0.075)
    local groups = {}

    -- Build 223: vote HUD belongs to the render-time HUD group list.
    -- Build 222 accidentally attempted to append it from update_hud_cache(),
    -- where no local `groups` table exists, causing a nil-length loop error.
    if startup.s.browserSessionSafetyEnabled ~= false and startup.browser_vote_hud then
        local vh = startup.browser_vote_hud
        local untilMs = tonumber(vh.until_ms or 0) or 0
        if tostring(vh.text or "") ~= "" and untilMs > startup.now() then
            startup.hud_group(groups, "browser_vote", 1, 0.5, { { text = tostring(vh.text), color = {255,70,70} } })
        elseif untilMs > 0 and untilMs <= startup.now() then
            vh.text = ""; vh.until_ms = 0
        end
    end

    local browserHudRow = nil
    -- Build 213: live Browser HUD follows the *actual current GTA Session Host*,
    -- never a stale row the user previously selected before/after a Browser JOIN.
    -- Simulation keeps the old selected-row behavior for UI testing.
    if startup.browser_get_hud_row then
        browserHudRow = startup.browser_get_hud_row()
    elseif startup.browser_get_selected_row then
        browserHudRow = startup.browser_get_selected_row(true)
    end
    local browserHudActive = browserHudRow ~= nil and (
        (startup.s.showPrimeHostHud == true and startup.s.browserHudShowCheraxHost ~= false) or
        startup.s.browserHudShowCheraxCount ~= false or
        startup.s.browserHudShowCheraxNames ~= false
    )
    if browserHudActive then
        local lines = {}
        local verifiedCheraxNames = type(browserHudRow.cheraxNames)=="table" and browserHudRow.cheraxNames or {}
        local verifiedCheraxCount = #verifiedCheraxNames
        local hasCheraxGroup = verifiedCheraxCount >= 2
        if startup.s.showPrimeHostHud == true and startup.s.browserHudShowCheraxHost ~= false then
            local c = startup.hud_color("host", {120,205,255})
            local hostPrefix = hasCheraxGroup and "Cherax Host: " or "Host: "
            lines[#lines + 1] = { text = hostPrefix .. tostring(browserHudRow.username or "Unknown"), color = c }
        end
        if hasCheraxGroup and startup.s.browserHudShowCheraxCount ~= false then
            lines[#lines + 1] = { text = "Cherax Users: " .. tostring(verifiedCheraxCount), color = startup.hud_color("host", {120,205,255}) }
        end
        if hasCheraxGroup and startup.s.browserHudShowCheraxNames ~= false then
            local cheraxHudNames = {}
            for _, name in ipairs(verifiedCheraxNames) do
                cheraxHudNames[#cheraxHudNames + 1] = tostring(name)
            end
            if #cheraxHudNames > 0 then
                local wrappedCherax = startup.friend_hud_lines and startup.friend_hud_lines(cheraxHudNames) or { table.concat(cheraxHudNames, ", ") }
                for _, cheraxLine in ipairs(wrappedCherax) do
                    lines[#lines + 1] = { text = tostring(cheraxLine), color = startup.hud_color("host", {120,205,255}) }
                end
            end
        end
        startup.hud_group(groups, "host", startup.s.hudOrderHost, 1, lines)
    elseif startup.s.showPrimeHostHud then
        local hostName = startup.s.hudSimulationEnabled and "Public_Urinal" or tostring(startup.hud_cache.hostName or "Unknown")
        startup.hud_group(groups, "host", startup.s.hudOrderHost, 1, { { text = "Host: " .. hostName, color = startup.hud_color("host", {120,205,255}) } })
    end

    if startup.s.showScriptHostHud then
        local scriptHostName = startup.s.hudSimulationEnabled and "Amelia" or tostring(startup.hud_cache.scriptHostName or "Unknown")
        startup.hud_group(groups, "script_host", startup.s.hudOrderScriptHost, 2, { { text = "Script Host: " .. scriptHostName, color = startup.hud_color("scriptHost", {190,135,255}) } })
    end

    if startup.s.showNextHostHud then
        local nextHostName = startup.s.hudSimulationEnabled and "Next_Player" or tostring(startup.hud_cache.nextHostName or "Unknown")
        startup.hud_group(groups, "next_host", startup.s.hudOrderNextHost, 3, { { text = "Next Host: " .. nextHostName, color = startup.hud_color("nextHost", {255,220,110}) } })
    end

    if startup.s.showFriendsHud then
        local names = startup.s.hudSimulationEnabled and { "Friend_One", "Friend_Two" } or (startup.hud_cache.friendNames or {})
        local lines = {}
        for index, text in ipairs(startup.friend_hud_lines(names)) do
            lines[#lines + 1] = { text = (index == 1 and "Friends: " or "         ") .. tostring(text), color = startup.hud_color("friends", {70,255,95}) }
        end
        startup.hud_group(groups, "friends", startup.s.hudOrderFriends, 4, lines)
    end

    if startup.s.showTrackedPlayersHud ~= false then
        local names = startup.s.hudSimulationEnabled and { "Tracked_Player" } or (startup.hud_cache.trackedPlayerNames or {})
        local lines = {}
        for index, text in ipairs(startup.friend_hud_lines(names)) do
            lines[#lines + 1] = { text = (index == 1 and "Tracked: " or "         ") .. tostring(text), color = startup.hud_color("trackedPlayers", {255,65,65}) }
        end
        -- Share Friends' order slot and use the next rank so Tracked always sits directly below Friends.
        startup.hud_group(groups, "tracked_players", startup.s.hudOrderFriends, 4.5, lines)
    end

    if startup.s.showNatTypeHud then
        local natType = startup.s.hudSimulationEnabled and "Moderate" or tostring(startup.hud_cache.natType or "Unknown")
        local natColor = {210,210,210}
        if natType == "Open" then natColor = startup.hud_color("natOpen", {120,255,150})
        elseif natType == "Moderate" then natColor = startup.hud_color("natModerate", {255,215,105})
        elseif natType == "Strict" then natColor = startup.hud_color("natStrict", {255,105,105}) end
        startup.hud_group(groups, "nat", startup.s.hudOrderNat, 5, { { text = "NAT: " .. natType, color = natColor } })
    end

    if startup.s.showAdvertiseRegionHud then
        local regionLabel = startup.s.hudSimulationEnabled and "Europe" or tostring(startup.hud_cache.advertiseRegion or "Unknown")
        local regionColor = regionLabel == "My Region"
            and startup.hud_color("regionMy", {120,205,255})
            or startup.hud_color("regionOther", {120,205,255})
        startup.hud_group(groups, "advertise_region", startup.s.hudOrderRegion, 6,
            { { text = "Region: " .. regionLabel, color = regionColor } })
    end

    if startup.s.showSpeakingPlayersHud then
        local lines = {}
        if startup.s.hudSimulationEnabled then
            lines[#lines + 1] = { text = "MIC: Public_Urinal", color = {80,255,120} }
        else
            startup.update_voice_speakers(false)
            for _, name in ipairs(startup.hud_cache.speakers or {}) do lines[#lines + 1] = { text = "MIC: " .. tostring(name), color = {80,255,120} } end
        end
        startup.hud_group(groups, "speaking", startup.s.hudOrderSpeaking, 7, lines)
    end

    if startup.s.showModdersHud then
        local lines = {}
        if startup.s.hudSimulationEnabled then
            lines[#lines + 1] = { text = "Modder: CrashTester", color = {255,90,90} }
            lines[#lines + 1] = { text = "Reason: Crash Type V2", color = {255,185,80} }
            if startup.s.modDetectionIncludeRac == true then
                lines[#lines + 1] = { text = "Modder: RAC_Test", color = {255,90,90} }
                lines[#lines + 1] = { text = "Reason: RAC: Script Cheat Detection", color = {255,185,80} }
            end
        else
            for _, entry in ipairs(startup.modder_hud_list()) do
                lines[#lines + 1] = { text = "Modder: " .. tostring(entry.name), color = {255,90,90} }
                lines[#lines + 1] = { text = "Reason: " .. tostring(entry.reason), color = {255,185,80} }
            end
        end
        startup.hud_group(groups, "modders", startup.s.hudOrderModders, 8, lines)
    end

    local developerLines = {}
    for _, developerName in ipairs(startup.hud_cache.developerNames or {}) do
        developerLines[#developerLines + 1] = {
            text = "Developer: " .. tostring(developerName),
            color = {190,135,255}
        }
    end
    -- Order 9 is intentionally outside the configurable 1-8 HUD stack. This keeps
    -- Developer presence fixed immediately above Connected Players.
    startup.hud_group(groups, "developers", 9, 9, developerLines)

    table.sort(groups, function(a, b) if a.order == b.order then return a.rank < b.rank end return a.order < b.order end)
    local stableLines = {}
    for _, group in ipairs(groups) do for _, line in ipairs(group.lines or {}) do stableLines[#stableLines + 1] = line end end

    local stableStartY = y - (lineGap * #stableLines)
    startup.hud_layout.x = x
    startup.hud_layout.stackTopY = stableStartY
    startup.hud_layout.stableLineCount = #stableLines
    startup.hud_layout.lineGap = lineGap
    startup.hud_layout.classicActivityBottomY = (#stableLines > 0 and stableStartY or (y - lineGap)) - 0.008
    startup.hud_layout.updatedMs = startup.now()
    for i, item in ipairs(stableLines) do startup.draw_hud_text(item.text, x, stableStartY + ((i - 1) * lineGap), scale, item.color[1], item.color[2], item.color[3], alpha, 4) end

    local activityX, activityBottomY = startup.session_activity_resolve_render_position()
    local activityScale = tonumber(startup.s.sessionActivityScale or 0.42) or 0.42
    startup.render_session_activity_feed(activityX, activityBottomY, activityScale, alpha)

    local connected = startup.s.hudSimulationEnabled and 28 or (startup.hud_cache.connected or 0)
    local connectedColor = startup.hud_color("connectedPlayers", {255,255,255})
    startup.draw_hud_text("Connected Players: " .. tostring(connected), x, y, scale,
        connectedColor[1],connectedColor[2],connectedColor[3],alpha,4)
    startup.s.lastHudStatus = startup.s.hudSimulationEnabled and "Animated feed simulation" or "Rendering safely"
end

function startup.hud_renderer_tick()
    if startup.s.sessionInfoHudEnabled then startup.render_session_info_hud() end
    if startup.s.showAdvertiseStatusHud then startup.render_advertise_status_hud() end
end

function startup.install_safe_hud_loop()
    if startup.s.safeHudLoopInstalled then return end
    startup.s.safeHudLoopInstalled = true
    if Script and Script.RegisterLooped then
        Script.RegisterLooped(function()
            if startup and startup.s and (startup.s.sessionInfoHudEnabled or startup.s.showAdvertiseStatusHud) then
                local diagnosticFrame = startup.boot_diag and startup.boot_diag.firstHudFramesLogged < 3
                if diagnosticFrame then
                    startup.boot_diag.firstHudFramesLogged = startup.boot_diag.firstHudFramesLogged + 1
                    startup.boot_diag_checkpoint("HUD_FRAME_BEGIN", "frame=" .. tostring(startup.boot_diag.firstHudFramesLogged), true)
                end
                if diagnosticFrame then
                    local okHud, errHud = direct_call(startup.hud_renderer_tick)
                    if not okHud then
                        if startup.boot_diag_checkpoint then startup.boot_diag_checkpoint("HUD_FRAME_ERROR", tostring(errHud), true) end
                        if startup.support_log_event_quiet then startup.support_log_event_quiet("HUD_FRAME_ERROR", tostring(errHud)) end
                        startup.s.lastHudStatus = "HUD error: " .. tostring(errHud)
                    else
                        startup.boot_diag_checkpoint("HUD_FRAME_OK", "frame=" .. tostring(startup.boot_diag.firstHudFramesLogged), true)
                    end
                else
                    startup.hud_renderer_tick()
                end
            end
        end)
        if startup.s.verboseStartupLogs then
            startup.log("Session and Advertise HUD safe frame loop installed.")
        end
    else
        startup.log("Script.RegisterLooped unavailable. HUD will not render to avoid flashing.")
    end
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- config persistence
-- note: settings save as a lua-return table with a fallback path.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.serialize(value, indent)
    indent = indent or ""
    if type(value) == "number" then
        return tostring(value)
    elseif type(value) == "boolean" then
        return tostring(value)
    elseif type(value) == "string" then
        return string.format("%q", value)
    elseif type(value) == "table" then
        local nextIndent = indent .. "    "
        local parts = {"{\n"}
        for k, v in pairs(value) do
            local key
            if type(k) == "string" and string.match(k, "^[%a_][%w_]*$") then
                key = k
            else
                key = "[" .. startup.serialize(k, nextIndent) .. "]"
            end
            table.insert(parts, nextIndent .. key .. " = " .. startup.serialize(v, nextIndent) .. ",\n")
        end
        table.insert(parts, indent .. "}")
        return table.concat(parts)
    end
    return "nil"
end

function startup.try_write_file(path, content)
    local ok, wrote = pcall(function()
        local file = io.open(path, "w")
        if not file then return false end
        file:write(content)
        file:close()
        return true
    end)
    return ok == true and wrote == true
end

function startup.save_table(path, value)
    startup.ensure_save_dir()
    local content = "return " .. startup.serialize(value, "") .. "\n"
    if startup.try_write_file(path, content) then
        startup.s.activeConfigFile = path
        return true
    end
    startup.error("Could not save Startup config: " .. tostring(path or startup.config_file))
    return false
end

function startup.load_table(path)
    local chunk = loadfile(path)
    if not chunk then return nil end
    local result = chunk()
    if type(result) == "table" then
        startup.s.activeConfigFile = path
        return result
    end
    return nil
end

