        battleyeAutoBlockUserConfigured = startup.s.battleyeAutoBlockUserConfigured == true,
        battleyeDefaultVersion = startup.s.battleyeDefaultVersion,
        battleyeHostKickFallbackDelayMs = startup.s.battleyeHostKickFallbackDelayMs,
