        kickDefenseDefaultVersion = startup.s.kickDefenseDefaultVersion,
        countryFilterEnabled = startup.s.countryFilterEnabled == true,
        countryFilterPrimeDefaultVersion = tostring(startup.s.countryFilterPrimeDefaultVersion or ""),
        countryFilterUnknownAllowed = startup.s.countryFilterUnknownAllowed ~= false,
        countryFilterOtherAllowed = startup.s.countryFilterOtherAllowed ~= false,
        countryFilterAllowed = startup.s.countryFilterAllowed,
        regionalWarfareEnabled = startup.s.regionalWarfareEnabled == true,
        regionalWarfareMyFaction = tostring(startup.s.regionalWarfareMyFaction or "Auto (Player Language)"),
        regionalWarfareEnemyPolicy = tostring(startup.s.regionalWarfareEnemyPolicy or "All Other Languages"),
        regionalWarfareAutoBounty = startup.s.regionalWarfareAutoBounty ~= false,
        regionalWarfareBountyGapMs = tonumber(startup.s.regionalWarfareBountyGapMs or 60000) or 60000,
        regionalWarfareSelectedEnemies = startup.s.regionalWarfareSelectedEnemies,
        regionalWarfareAssignments = startup.s.regionalWarfareAssignments,
        regionalWarfareSelectedAutoBountyEnabled = startup.s.regionalWarfareSelectedAutoBountyEnabled == true,
        regionalWarfareSelectedAutoBountyPlayerId = tonumber(startup.s.regionalWarfareSelectedAutoBountyPlayerId or -1) or -1,
        regionalWarfareSelectedAutoBountyPlayerRid = tostring(startup.s.regionalWarfareSelectedAutoBountyPlayerRid or ""),
        regionalWarfareSelectedAutoBountyPlayerName = tostring(startup.s.regionalWarfareSelectedAutoBountyPlayerName or ""),
        regionalWarfareColorPlayers = startup.s.regionalWarfareColorPlayers ~= false,
        regionalWarfareLanguageColors = startup.s.regionalWarfareLanguageColors,
        subscribedAutoStartConfirmed = startup.s.subscribedAutoStartConfirmed == true,
        subscribedAutoStartLastFeatureName = tostring(startup.s.subscribedAutoStartLastFeatureName or ""),
        -- force Cheater into config so older saved values cannot keep restoring old reason text.
        nukeJoinKickReason = "Cheater",
        luaFileStates = startup.s.luaFileStates,
        luaFileDelaysMs = startup.s.luaFileDelaysMs,
        luaFileDelayOverrides = startup.s.luaFileDelayOverrides,
        selectedLuaFilePath = startup.s.selectedLuaFilePath,
        themeFileStates = startup.s.themeFileStates
    }
end

function startup.apply_config(data)
    if type(data) ~= "table" then return end
    startup.s.firstRunWelcomeCompleted = data.firstRunWelcomeCompleted == true
    startup.s.firstRunWelcomeCompletedAt = tonumber(data.firstRunWelcomeCompletedAt or 0) or 0
    if data.firstRunInstallPending == true then
        startup.s.firstRunInstallPending = true
    elseif data.firstRunWelcomeCompleted == false
        and tostring(data.onboardingSetupVersion or "") == ""
        and tostring(data.settingsFile or "") == "" then
        -- Recover an interrupted Build 027-style first run whose config file already exists.
        startup.s.firstRunInstallPending = true
    else
        startup.s.firstRunInstallPending = false
    end
    startup.s.onboardingSetupVersion = tostring(data.onboardingSetupVersion or "")
    startup.s.lastAcknowledgedStartupBuild = tostring(data.lastAcknowledgedStartupBuild or "")
    startup.s.settingsProfileSelectionConfirmed = data.settingsProfileSelectionConfirmed == true
    startup.s.verboseStartupLogs = data.verboseStartupLogs == true
    startup.s.muteEventMusicEnabled = data.muteEventMusicEnabled ~= false
    startup.s.eventMusicPulseMs = tonumber(data.eventMusicPulseMs or startup.s.eventMusicPulseMs) or startup.s.eventMusicPulseMs
    startup.s.alwaysDayEnabled = data.alwaysDayEnabled ~= false
    startup.s.alwaysDayTargetHour = startup.clamp_int(data.alwaysDayTargetHour or startup.s.alwaysDayTargetHour, 0, 23)
    startup.s.alwaysDayTargetMinute = startup.clamp_int(data.alwaysDayTargetMinute or startup.s.alwaysDayTargetMinute, 0, 59)
    startup.s.alwaysDayScanMs = startup.clamp_int(data.alwaysDayScanMs or startup.s.alwaysDayScanMs, 1000, 60000)
    startup.s.alwaysNightEnabled = data.alwaysNightEnabled == true
    startup.s.alwaysNightTargetHour = startup.clamp_int(data.alwaysNightTargetHour or startup.s.alwaysNightTargetHour, 0, 23)
    startup.s.alwaysNightTargetMinute = startup.clamp_int(data.alwaysNightTargetMinute or startup.s.alwaysNightTargetMinute, 0, 59)
    if startup.s.alwaysNightEnabled then startup.s.alwaysDayEnabled = false end
    startup.s.settingsFile = data.settingsFile or startup.s.settingsFile
    startup.s.themeFile = data.themeFile or startup.s.themeFile
    startup.s.lastRandomThemeFile = data.lastRandomThemeFile or startup.s.lastRandomThemeFile
    startup.s.sessionType = data.sessionType or startup.s.sessionType
    local routingMode = tostring(data.sessionRoutingMode or "Automatic")
    if routingMode ~= "Automatic" and routingMode ~= "Standard / Premium" and routingMode ~= "Prime" then
        routingMode = "Automatic"
    end
    startup.s.sessionRoutingMode = routingMode
    -- Build 409: default ON even for existing configs that predate this setting.
    -- Once the user changes it, the saved false/true value remains authoritative.
    startup.s.primeHostSessionsEnabled = data.primeHostSessionsEnabled ~= false
    startup.s.autoDetectSessionTypeByTier = true
    startup.s.compactPinnedTabEnabled = data.compactPinnedTabEnabled == true
    startup.s.startSessionHotkeyKeyCode = startup.clamp_int(data.startSessionHotkeyKeyCode or startup.s.startSessionHotkeyKeyCode or 0x13, 0, 255)
    startup.s.startSessionHotkeyName = tostring(data.startSessionHotkeyName or startup.s.startSessionHotkeyName or "Pause / Break")
    startup.s.cancelStartupHopHotkeyKeyCode = startup.clamp_int(data.cancelStartupHopHotkeyKeyCode or startup.s.cancelStartupHopHotkeyKeyCode or 0x77, 0, 255)
    startup.s.cancelStartupHopHotkeyName = tostring(data.cancelStartupHopHotkeyName or startup.s.cancelStartupHopHotkeyName or "F8")
    startup.s.autoLoadSettings = data.autoLoadSettings ~= false
    local saved_theme_automation_default_version = tostring(data.themeAutomationDefaultVersion or "")
    if saved_theme_automation_default_version ~= startup.theme_automation_default_version then
        -- v1.0.7 Alpha one-time migration: disable automatic theme loading and
        -- random theme selection even when an older custom config saved them ON.
        -- After this migration, later manual toggle choices are preserved normally.
        startup.s.autoLoadTheme = false
        startup.s.randomThemeOnStartup = false
    else
        startup.s.autoLoadTheme = data.autoLoadTheme == true
        startup.s.randomThemeOnStartup = data.randomThemeOnStartup == true
    end
    startup.s.themeAutomationDefaultVersion = startup.theme_automation_default_version

    startup.s.autoSelectSessionType = data.autoSelectSessionType ~= false
    local savedAutoAdvertiseUserConfigured = data.autoAdvertiseUserConfigured == true
    startup.s.autoAdvertiseUserConfigured = savedAutoAdvertiseUserConfigured
    if tostring(data.autoAdvertiseDefaultVersion or "") ~= startup.auto_advertise_default_version then
        -- v1.0.14 migration: Auto Advertise Session is the production default and starts ON
        -- for users who have never explicitly changed it. Existing manual choices remain
        -- authoritative, and every later manual change is saved normally.
        if savedAutoAdvertiseUserConfigured then
            startup.s.autoAdvertiseSession = data.autoAdvertiseSession ~= false
        else
            startup.s.autoAdvertiseSession = true
        end
    else
        startup.s.autoAdvertiseSession = data.autoAdvertiseSession ~= false
    end
    startup.s.autoAdvertiseDefaultVersion = startup.auto_advertise_default_version
    startup.s.advertisingMode373 = tostring(data.advertisingMode373 or startup.s.advertisingMode373 or "Smart Adaptive")
    if startup.s.advertisingMode373 ~= "Smart Adaptive" and startup.s.advertisingMode373 ~= "Popularity Rotation" and startup.s.advertisingMode373 ~= "Manual" then startup.s.advertisingMode373 = "Smart Adaptive" end
    startup.s.advertisingTargetPlayers373 = startup.clamp_int(data.advertisingTargetPlayers373 or startup.s.advertisingTargetPlayers373 or 30, 5, 30)
    startup.s.advertisingRegionTestMinutes373 = startup.clamp_int(data.advertisingRegionTestMinutes373 or startup.s.advertisingRegionTestMinutes373 or 3, 2, 10)
    startup.s.advertisingVariant402 = tostring(data.advertisingVariant402 or startup.s.advertisingVariant402 or "Standard Advertise")
    if startup.s.advertisingVariant402 ~= "Standard Advertise"
        and startup.s.advertisingVariant402 ~= "Any Advertise"
        and startup.s.advertisingVariant402 ~= "Region Advertise"
        and startup.s.advertisingVariant402 ~= "Synced Region Advertise" then
        startup.s.advertisingVariant402 = "Standard Advertise"
    end
    startup.s.advertisingVariantRegion402 = startup.b368_region_normalize and startup.b368_region_normalize(data.advertisingVariantRegion402 or startup.s.advertisingVariantRegion402 or "Africa") or tostring(data.advertisingVariantRegion402 or "Africa")
    if startup.s.advertisingVariantRegion402 == "Unknown" or startup.s.advertisingVariantRegion402 == "" then startup.s.advertisingVariantRegion402 = "Africa" end
    startup.s.oldStartupAdvertiseEnabled = data.oldStartupAdvertiseEnabled == true
    startup.s.oldStartupAdvertiseRunning = false
    startup.s.oldStartupAdvertiseSerial = 0
    startup.s.oldStartupAdvertiseStatus = startup.s.oldStartupAdvertiseEnabled and "Ready for next Legacy session" or "OFF"
    startup.s.oldStartupAdvertiseCurrentCount = 0
    startup.s.oldStartupAdvertiseStartedAtMs = 0
    startup.s.oldStartupAdvertiseLastHeartbeatMs = 0
    if startup.s.oldStartupAdvertiseEnabled then
        startup.s.autoAdvertiseSession = false
    end
    local saved_benchmark_default_version = tostring(data.advertiseBenchmarkDefaultVersion or "")
    if saved_benchmark_default_version ~= startup.advertise_benchmark_default_version then
        -- v1.0.14 one-time production migration: the 30-Player Benchmark Timer is OFF
        -- for everyone by default. Once this marker is saved, later manual choices are preserved.
        startup.s.advertiseBenchmarkEnabled = false
    else
        startup.s.advertiseBenchmarkEnabled = data.advertiseBenchmarkEnabled == true
    end
    startup.s.advertiseBenchmarkDefaultVersion = startup.advertise_benchmark_default_version
    startup.s.advertiseBenchmarkTargetPlayers = 30
    startup.s.advertiseBenchmarkHistoryLimit = startup.clamp_int(data.advertiseBenchmarkHistoryLimit or 100, 10, 500)
    startup.s.advertiseBenchmarkHistory = {}
    if type(data.advertiseBenchmarkHistory) == "table" then
        for _, item in ipairs(data.advertiseBenchmarkHistory) do
            if type(item) == "table" then
                startup.s.advertiseBenchmarkHistory[#startup.s.advertiseBenchmarkHistory + 1] = item
                if #startup.s.advertiseBenchmarkHistory >= startup.s.advertiseBenchmarkHistoryLimit then break end
            end
        end
    end
    startup.s.advertiseBenchmarkActive = false
    startup.s.advertiseBenchmarkMode = ""
    startup.s.advertiseBenchmarkReason = ""
    startup.s.advertiseBenchmarkQueuedAtMs = 0
    startup.s.advertiseBenchmarkActivatedAtMs = 0
    startup.s.advertiseBenchmarkStartedAtEpoch = 0
    startup.s.advertiseBenchmarkStartPlayers = 0
    startup.s.advertiseBenchmarkActivationPlayers = 0
    startup.s.advertiseBenchmarkPeakPlayers = 0
    startup.s.advertiseBenchmarkMilestones = {}
    startup.s.advertiseBenchmarkContext = {}
    startup.s.advertiseBenchmarkNextPollMs = 0
    startup.s.advertiseBenchmarkLastHistoryPath = tostring(startup.AdvertiseBenchmarkCsvFile or "")
    local lastTimed = startup.s.advertiseBenchmarkHistory[1]
    startup.s.advertiseBenchmarkLastResult = lastTimed and
        (tostring(lastTimed.mode or "UNKNOWN") .. " | " .. tostring(lastTimed.outcome or "Saved") .. " | " .. tostring(lastTimed.totalText or "--:--"))
        or "No timed advertising results yet"
    startup.s.advertiseBenchmarkLastStatus = "Ready for a 30-player timed run"
    local saved_startup_automation_default_version = tostring(data.startupAutomationDefaultVersion or "")
    if saved_startup_automation_default_version ~= startup.startup_automation_default_version then
        -- Build 109 one-time migration for safer public defaults:
        -- start the Story Mode to Online flow automatically, while keeping local
        -- developer Lua automation disabled unless the user explicitly enables it.
        -- Once this marker is saved, later manual toggle choices are preserved.
        startup.s.autoStartOnlineFromSingleplayer = true
        startup.s.autoRunLuaFiles = false
        startup.s.autoLoadLuaFilesOnSession = false
    else
        startup.s.autoStartOnlineFromSingleplayer = data.autoStartOnlineFromSingleplayer ~= false
        startup.s.autoRunLuaFiles = data.autoRunLuaFiles == true
        startup.s.autoLoadLuaFilesOnSession = data.autoLoadLuaFilesOnSession == true
    end
    startup.s.startupAutomationDefaultVersion = startup.startup_automation_default_version
    startup.s.autoStartOnlineDelayMs = tonumber(data.autoStartOnlineDelayMs or startup.s.autoStartOnlineDelayMs) or startup.s.autoStartOnlineDelayMs
    if tostring(data.sessionRefreshDefaultVersion or "") == startup.session_refresh_default_version then
        startup.s.autoRefreshSessionAfterLuaLoad = data.autoRefreshSessionAfterLuaLoad == true
    else
        -- One-time migration: prevent an automatic second session join after Lua loading.
        startup.s.autoRefreshSessionAfterLuaLoad = false
    end
    startup.s.sessionRefreshDefaultVersion = startup.session_refresh_default_version
    startup.s.sessionLuaLoadDelayMs = tonumber(data.sessionLuaLoadDelayMs or startup.s.sessionLuaLoadDelayMs) or startup.s.sessionLuaLoadDelayMs
    if data.luaDelayV131Migrated == true then
        startup.s.luaDelayBetweenFilesMs = startup.clamp_int(data.luaDelayBetweenFilesMs or startup.s.luaDelayBetweenFilesMs, 0, 300000)
    else
        startup.s.luaDelayBetweenFilesMs = 5000
    end
    startup.s.luaDelayV131Migrated = true
    startup.s.delayAfterAllLuaLoadedMs = tonumber(data.delayAfterAllLuaLoadedMs or startup.s.delayAfterAllLuaLoadedMs) or startup.s.delayAfterAllLuaLoadedMs
    startup.s.sessionChangeDebounceMs = tonumber(data.sessionChangeDebounceMs or startup.s.sessionChangeDebounceMs) or startup.s.sessionChangeDebounceMs
    startup.s.startupPresenceRepliesEnabled = data.startupPresenceRepliesEnabled ~= false
    -- Session hopping never resumes automatically after a Lua/game restart.
    startup.s.startupPresenceFinderEnabled = false
    local savedPresenceTarget = tostring(data.startupPresenceFinderTarget or "Session Host")
    if savedPresenceTarget ~= "Any Startup User" then savedPresenceTarget = "Session Host" end
    startup.s.startupPresenceFinderTarget = savedPresenceTarget
    startup.s.startupPresenceFinderStatus = "Ready"
    startup.s.startupPresenceFinderHopCount = 0
    startup.s.startupPresenceLastFound = "None"
    startup.s.startupPresenceLastFoundCount = 0
    startup.s.cheraxHostFinderEnabled = data.cheraxHostFinderEnabled == true
    startup.s.lobbyFinderFourMinuteHopEnabled = data.lobbyFinderFourMinuteHopEnabled ~= false
    startup.s.lobbyFinderRunHostTestEnabled = data.lobbyFinderRunHostTestEnabled ~= false
    startup.s.lobbyFinderSessionLimitMs = 240000
    startup.s.primeMinimumPlayersThreshold = startup.clamp_int(data.primeMinimumPlayersThreshold or 20, 10, 30)
    startup.s.lobbyFinderWaitMinMs = startup.clamp_int(data.lobbyFinderWaitMinMs or 15000, 15000, 30000)
    startup.s.lobbyFinderWaitMaxMs = startup.clamp_int(data.lobbyFinderWaitMaxMs or 30000, startup.s.lobbyFinderWaitMinMs, 30000)
    local savedPrimeLobbyFilterDefaultVersion = tostring(data.primeMinimumPlayersDefaultVersion or "")
    if startup.is_prime_active_edition() and savedPrimeLobbyFilterDefaultVersion ~= startup.prime_lobby_filter_default_version then
        startup.s.primeMinimumPlayersEnabled = true
        startup.s.primeMinimumPlayersDefaultVersion = startup.prime_lobby_filter_default_version
    else
        startup.s.primeMinimumPlayersEnabled = data.primeMinimumPlayersEnabled ~= false
        startup.s.primeMinimumPlayersDefaultVersion = startup.is_prime_active_edition() and startup.prime_lobby_filter_default_version or savedPrimeLobbyFilterDefaultVersion
    end
    if not startup.is_prime_active_edition() then
        startup.s.primeMinimumPlayersEnabled = data.primeMinimumPlayersEnabled == true
    end
    startup.s.advertiseDelayAfterSessionMs = tonumber(data.advertiseDelayAfterSessionMs or startup.s.advertiseDelayAfterSessionMs) or startup.s.advertiseDelayAfterSessionMs
    startup.s.advertiseCount5DurationMs = tonumber(data.advertiseCount5DurationMs or startup.s.advertiseCount5DurationMs) or startup.s.advertiseCount5DurationMs
    -- Build 118 permanently locks Advertise tuning to Startup's supported defaults.
    -- Any legacy slider values, edited config values, or out-of-range values are ignored.
    local savedAdvertiseTuningLockVersion = tostring(data.advertiseTuningLockVersion or "")
    local legacyAdvertiseTuningChanged =
        tonumber(data.advertisePlayerTarget or 30) ~= 30 or
        tonumber(data.advertiseResumeBelow or 25) ~= 25 or
        tonumber(data.advertiseLowCount or 5) ~= 5 or
        tonumber(data.advertiseHighCount or 10) ~= 10
    startup.s.advertisePlayerTarget = 30
    startup.s.advertiseResumeBelow = 25
    startup.s.advertiseLowCount = 5
    startup.s.advertiseHighCount = 10
    startup.s.advertiseTuningLockVersion = startup.advertise_tuning_lock_version
    if savedAdvertiseTuningLockVersion ~= startup.advertise_tuning_lock_version or legacyAdvertiseTuningChanged then
        startup.s.advertiseTuningResetStatus = "Legacy Advertise tuning reset to 30/25 and 5/10"
        startup.log("[Advertise Settings] Reset legacy tuning to defaults: high=30, resume=25, low=5, high-count=10")
    else
        startup.s.advertiseTuningResetStatus = "Locked to Startup defaults"
    end
    startup.s.advertisePlayerCheckMs = tonumber(data.advertisePlayerCheckMs or startup.s.advertisePlayerCheckMs) or startup.s.advertisePlayerCheckMs
    startup.s.showStatusPanel = data.showStatusPanel ~= false
    startup.s.showTipsPanel = data.showTipsPanel ~= false
    startup.s.playerModUiEnabled = data.playerModUiEnabled ~= false
    startup.s.sessionInfoHudEnabled = data.sessionInfoHudEnabled ~= false
    startup.s.sessionInfoHudShadow = data.sessionInfoHudShadow ~= false
    startup.s.speedHudEnabled = data.speedHudEnabled ~= false
    startup.s.speedHudUnit = tostring(data.speedHudUnit or "MPH"):upper()
    if startup.s.speedHudUnit ~= "MPH" and startup.s.speedHudUnit ~= "KMH" then startup.s.speedHudUnit = "MPH" end
    startup.s.triggerBotEnabled = data.triggerBotEnabled == true
    startup.s.triggerBotReactionDelayMs = startup.clamp_int(tonumber(data.triggerBotReactionDelayMs or 20) or 20, 0, 500)
    startup.s.expandedMinimapHudEnabled = data.expandedMinimapHudEnabled ~= false
    startup.s.expandedMinimapHudOffsetX = startup.clamp_float(tonumber(data.expandedMinimapHudOffsetX or 0.090) or 0.090, 0.040, 0.200)
    startup.s.expandedMinimapHudHoldSeconds = startup.clamp_int(tonumber(data.expandedMinimapHudHoldSeconds or 10) or 10, 5, 20)
    startup.s.expandedMinimapHudModeVersion = tostring(data.expandedMinimapHudModeVersion or "")
    startup.s.browserSimulate = false -- Build 295: production Browser always uses live backend data.
    -- Build 215 policy: Startup always enrolls/authenticates with Public_Urinal online services.
    -- Browser participation is separately gated by the one-time Browser Terms & Data Notice.
    startup.s.browserBackendEnabled = true
    startup.s.browserTermsAcceptedVersion = tostring(data.browserTermsAcceptedVersion or "")
    startup.s.browserMakeRoomForCheraxUser = data.browserMakeRoomForCheraxUser ~= false
    startup.s.browserSessionSafetyEnabled = data.browserSessionSafetyEnabled ~= false
    local browserFilter = tostring(data.browserFilter or "All")
    if browserFilter ~= "All" and browserFilter ~= "Online" and browserFilter ~= "Offline" then browserFilter = "All" end
    startup.s.browserFilter = browserFilter
    local browserSort = tostring(data.browserSort or "Recommended")
    if browserSort ~= "Recommended" and browserSort ~= "Players" and browserSort ~= "Ping" and browserSort ~= "Flag" and browserSort ~= "Reputation" then browserSort = "Recommended" end
    startup.s.browserSort = browserSort
    startup.s.browserHudShowCheraxHost = data.browserHudShowCheraxHost ~= false
    startup.s.browserHudShowCheraxCount = data.browserHudShowCheraxCount ~= false
    startup.s.browserHudShowCheraxNames = data.browserHudShowCheraxNames ~= false
    -- Build 163: Advertise HUD is a locked presentation element, not a user setting.
    -- Ignore older saved visibility/position/style values and always use the confirmed layout.
    startup.enforce_locked_advertise_status_hud()
    local saved_prime_host_default_version = tostring(data.primeHostDefaultVersion or "")
    local saved_hud_expansion_default_version = tostring(data.hudExpansionDefaultVersion or "")
    if saved_hud_expansion_default_version ~= startup.hud_expansion_default_version then
        if startup.is_prime_active_edition() then startup.s.showPrimeHostHud = data.showPrimeHostHud ~= false else startup.s.showPrimeHostHud = false end
        startup.s.showScriptHostHud = false
        startup.s.showNextHostHud = false
        startup.s.showNatTypeHud = data.showNatTypeHud ~= false
        startup.s.showMatchmakingRegionHud = false
        startup.s.showFriendsHud = false
        startup.s.hudOrderHost = 6
        startup.s.hudOrderScriptHost = 4
        startup.s.hudOrderNextHost = 5
        startup.s.hudOrderFriends = 3
        startup.s.hudOrderNat = 7
        startup.s.hudOrderRegion = 8
        startup.s.hudOrderSpeaking = 1
        startup.s.hudOrderModders = 2
    else
        startup.s.showPrimeHostHud = data.showPrimeHostHud == true
        startup.s.showScriptHostHud = data.showScriptHostHud == true
        startup.s.showNextHostHud = data.showNextHostHud == true
        startup.s.showNatTypeHud = data.showNatTypeHud ~= false
    local savedNatOverride = tostring(data.natOverrideMode or "Original")
    if savedNatOverride ~= "Open" and savedNatOverride ~= "Moderate" and savedNatOverride ~= "Strict" then savedNatOverride = "Original" end
    startup.s.natOverrideMode = savedNatOverride
        startup.s.showMatchmakingRegionHud = false
        startup.s.showFriendsHud = data.showFriendsHud == true
        startup.s.hudOrderHost = startup.clamp_int(data.hudOrderHost or 6, 1, 8)
        startup.s.hudOrderScriptHost = startup.clamp_int(data.hudOrderScriptHost or 4, 1, 8)
        startup.s.hudOrderNextHost = startup.clamp_int(data.hudOrderNextHost or 5, 1, 8)
        startup.s.hudOrderFriends = startup.clamp_int(data.hudOrderFriends or 3, 1, 8)
        startup.s.hudOrderNat = startup.clamp_int(data.hudOrderNat or 7, 1, 8)
        startup.s.hudOrderRegion = startup.clamp_int(data.hudOrderRegion or 8, 1, 8)
        startup.s.hudOrderSpeaking = startup.clamp_int(data.hudOrderSpeaking or 1, 1, 8)
        startup.s.hudOrderModders = startup.clamp_int(data.hudOrderModders or 2, 1, 8)
    end
    -- Build 442: Tracked Players HUD is opt-out and defaults ON for older configs.
    startup.s.showTrackedPlayersHud = data.showTrackedPlayersHud ~= false

    local savedHudOrderDefaultVersion = tostring(data.hudOrderDefaultVersion or "")
    if savedHudOrderDefaultVersion ~= startup.hud_order_default_version then
        startup.s.hudOrderSpeaking = 1
        startup.s.hudOrderModders = 2
        startup.s.hudOrderFriends = 3
        startup.s.hudOrderScriptHost = 4
        startup.s.hudOrderNextHost = 5
        startup.s.hudOrderHost = 6
        startup.s.hudOrderNat = 7
        startup.s.hudOrderRegion = 8
    end
    startup.s.hudOrderDefaultVersion = startup.hud_order_default_version
    if startup.s.cheraxHostFinderEnabled then
        startup.s.showPrimeHostHud = true
        startup.s.sessionInfoHudEnabled = true
        startup.s.playerModUiEnabled = true
    end
    -- Build 048: NAT and Friends HUD lines default ON for users who have never
