    startup.s.natHudUserConfigured = data.natHudUserConfigured == true
    if startup.s.natHudUserConfigured then
        startup.s.showNatTypeHud = data.showNatTypeHud == true
    else
        startup.s.showNatTypeHud = true
    end
    local savedPrimeNatHudDefaultVersion = tostring(data.primeNatHudDefaultVersion or "")
    if startup.is_prime_active_edition() and savedPrimeNatHudDefaultVersion ~= startup.prime_nat_hud_default_version then
        -- Build 071 one-time Prime migration: make NAT visible for existing Prime
        -- configs that predate the reliable local-player and online retry paths.
