function startup.save_config(showToast)
    startup.s.nukeJoinKickReason = "Cheater"
    if startup.save_table(startup.config_file, startup.export_config()) then
        if showToast ~= false then
            startup.toast("Startup config saved.", 2500)
        end
        return true
    end
    return false
end

function startup.load_config(showToast)
    local data = startup.load_table(startup.config_file)
    if data then
        startup.s.existingConfigLoaded = true
        startup.apply_config(data)
        if startup.apply_start_session_hotkey then startup.apply_start_session_hotkey(false) end
        -- immediately save back so old reason text gets overwritten.
        startup.save_config(false)
        if showToast ~= false then
            startup.toast("Startup config loaded.", 2500)
        else
            -- Quiet production boot: successful automatic config loading is expected.
        end
        return true
    end
    startup.s.existingConfigLoaded = false
    startup.s.firstRunInstallPending = true
    startup.s.nukeJoinKickReason = "Cheater"
    startup.save_config(false)
    if showToast ~= false then
        startup.toast("No startup config found. Created default config.", 3000)
    else
        -- First-run setup communicates the new default configuration in the UI.
    end
    return false
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- support & diagnostics
-- note: Support ZIP work is deferred out of ClickGUI/ImGui render callbacks.
--       ZIP writing is self-contained pure Lua and does not invoke the OS shell.
-- ═══════════════════════════════════════════════════════════════════════════════════

startup.rid_store = startup.rid_store or { data = {}, seenSession = {}, kickCooldown = {}, recentRecords = {} }

function startup.rid_store.load()
    startup.ensure_save_dir()
    local chunk = loadfile(startup.RidHistoryFile)
    if chunk then
        local ok, data = direct_call(chunk)
        if ok and type(data) == "table" then startup.rid_store.data = data end
    end
    local count = 0; for _ in pairs(startup.rid_store.data or {}) do count = count + 1 end
    startup.s.ridHistoryCount = count
    return true
end

function startup.rid_store.save()
    startup.ensure_save_dir()
    local content = "return " .. startup.serialize(startup.rid_store.data or {}, "") .. "\n"
    local ok = startup.try_write_file(startup.RidHistoryFile, content)
    if ok then
        local count = 0; for _ in pairs(startup.rid_store.data or {}) do count = count + 1 end
        startup.s.ridHistoryCount = count
    end
    return ok
end

function startup.rid_store.append_event(name, rid, eventType, reason, action)
    startup.ensure_save_dir()
    local f = io and io.open and io.open(startup.RidEventLogFile, "a") or nil
    if not f then return false end
    f:write(os.date("%Y-%m-%d %H:%M:%S"), " | ", tostring(name or "Unknown"), " | RID=", tostring(rid or "0"), " | ", tostring(eventType or "Event"), " | Reason=", tostring(reason or "Unknown"), " | Action=", tostring(action or "None"), "\n")
    f:close(); return true
end

function startup.rid_store.identity(playerId)
    playerId = tonumber(playerId)
    if playerId == nil or not Players or not Players.GetById then return nil end
    local okP, player = direct_call(function() return Players.GetById(playerId) end)
    if not okP or not player then return nil end
    local name = startup.get_player_name_safe(playerId)
    local rid = nil
    if player.GetGamerInfo then
        local okI, info = direct_call(function() return player:GetGamerInfo() end)
        if okI and info then
            local okR, raw = direct_call(function() return info.RockstarId end)
            if okR and tonumber(raw) and tonumber(raw) > 0 then rid = string.format("%.0f", tonumber(raw)) end
        end
    end
    if not rid then return nil end
    local ip = "Unknown"
    if Players.GetIPString then local ok, value = direct_call(Players.GetIPString, playerId); if ok and value then ip = tostring(value) end end
    local _, country, code = nil, "Unknown / Hidden", ""
    if startup.country_filter and startup.country_filter.read_player_country then
        local ok, key, label, cc = direct_call(startup.country_filter.read_player_country, playerId)
        if ok then country, code = tostring(label or country), tostring(cc or "") end
    end
    return {playerId=playerId, name=tostring(name or "Unknown"), rid=rid, ip=ip, country=country, countryCode=code}
end

function startup.rid_store.record(playerId, eventType, reason, action, markBlock)
    playerId = tonumber(playerId)
    if playerId == nil then return false end
    local eventText, reasonText, actionText = tostring(eventType or "Event"), tostring(reason or "Unknown"), tostring(action or "None")
    local preKey = tostring(playerId) .. "|" .. tostring(startup.get_player_name_safe(playerId) or "") .. "|" .. eventText .. "|" .. reasonText .. "|" .. actionText
    local nowMs = startup.now()
    if nowMs - (tonumber(startup.rid_store.recentRecords[preKey] or 0) or 0) < 300000 then
        return true
    end
    startup.rid_store.recentRecords[preKey] = nowMs
    local ident = startup.rid_store.identity(playerId)
    if not ident then return false end
    local data = startup.rid_store.data or {}; startup.rid_store.data = data
    local nowEpoch = os.time()
    local nowText = os.date("%Y-%m-%d %H:%M:%S", nowEpoch)
    local entry = data[ident.rid] or { firstSeen=nowEpoch, firstSeenDate=nowText, events={}, reasons={}, flags={} }
    entry.name, entry.ip, entry.country, entry.countryCode = ident.name, ident.ip, ident.country, ident.countryCode
    entry.firstSeen = tonumber(entry.firstSeen or nowEpoch) or nowEpoch
    entry.firstSeenDate = tostring(entry.firstSeenDate or os.date("%Y-%m-%d %H:%M:%S", entry.firstSeen))
    entry.lastSeen = nowEpoch
    entry.lastSeenDate = nowText
    entry.schemaVersion = 2
    entry.reasons = type(entry.reasons) == "table" and entry.reasons or {}
    entry.flags = type(entry.flags) == "table" and entry.flags or {}
    entry.names = type(entry.names) == "table" and entry.names or {}
    entry.ips = type(entry.ips) == "table" and entry.ips or {}
    entry.countries = type(entry.countries) == "table" and entry.countries or {}
    if ident.name ~= "" and ident.name ~= "Unknown" then entry.names[ident.name] = nowText end
    if ident.ip ~= "" and ident.ip ~= "Unknown" then entry.ips[ident.ip] = nowText end
    local countryHistoryKey = ident.countryCode ~= "" and ident.countryCode or ident.country
    if countryHistoryKey ~= "" and countryHistoryKey ~= "Unknown / Hidden" then entry.countries[countryHistoryKey] = { label=ident.country, lastSeenDate=nowText } end
    local nextEvent = tostring(eventType or "Event")
    local nextReason = tostring(reason or "Unknown")
    local nextAction = tostring(action or "None")
    local signature = nextEvent .. "|" .. nextReason .. "|" .. nextAction
    if entry.lastSignature == signature and nowEpoch - (tonumber(entry.lastEventAt or 0) or 0) < 300 then
        if markBlock == true then entry.blockJoin = true end
        return true, ident.rid
    end
    entry.lastSeen = nowEpoch; entry.lastSeenDate = nowText; entry.lastEvent = nextEvent; entry.lastReason = nextReason; entry.lastAction = nextAction
    entry.lastSignature = signature; entry.lastEventAt = nowEpoch; entry.lastEventDate = nowText
    entry.reasons[nextReason] = { lastSeen = nowEpoch, lastSeenDate = nowText, event = nextEvent, action = nextAction }
    local eventLower = string.lower(nextEvent)
    if eventLower:find("modder", 1, true) then entry.flags.modder = true end
    if eventLower:find("crash", 1, true) then entry.flags.crashAttacker = true end
    if eventLower:find("kick", 1, true) then entry.flags.kickAttacker = true end
    if eventLower:find("battleye", 1, true) then entry.flags.battleye = true end
    if eventLower:find("nuke", 1, true) then entry.flags.nuked = true end
    if markBlock == true then entry.blockJoin = true; entry.flags.blockRidJoin = true end
    entry.events = type(entry.events)=="table" and entry.events or {}
    entry.events[#entry.events+1] = { at=nowEpoch, date=nowText, event=entry.lastEvent, reason=entry.lastReason, action=entry.lastAction }
    while #entry.events > 20 do table.remove(entry.events, 1) end
    data[ident.rid] = entry
    startup.rid_store.save()
    startup.rid_store.append_event(ident.name, ident.rid, entry.lastEvent, entry.lastReason, entry.lastAction)
    startup.s.ridHistoryLastStatus = ident.name .. " saved: " .. entry.lastReason
    if startup.support_log_event_quiet then startup.support_log_event_quiet("RID_HISTORY", "player="..ident.name.." rid="..ident.rid.." event="..entry.lastEvent.." reason="..entry.lastReason.." action="..entry.lastAction.." block="..tostring(entry.blockJoin==true)) end
    return true, ident.rid
end

function startup.rid_store.record_known_identity(name, rid, eventType, reason, action, markBlock)
    local cleanName = tostring(name or "Unknown"):gsub("^%s+", ""):gsub("%s+$", "")
    local cleanRid = tostring(rid or ""):gsub("[^%d]", "")
    if cleanRid == "" or cleanRid == "0" then return false end

    local eventText = tostring(eventType or "Event")
    local reasonText = tostring(reason or "Unknown")
    local actionText = tostring(action or "None")
    local preKey = "rid:" .. cleanRid .. "|" .. eventText .. "|" .. reasonText .. "|" .. actionText
    local nowMs = startup.now()
    if nowMs - (tonumber(startup.rid_store.recentRecords[preKey] or 0) or 0) < 300000 then
        if markBlock == true and startup.rid_store.data and startup.rid_store.data[cleanRid] then
            startup.rid_store.data[cleanRid].blockJoin = true
            startup.rid_store.data[cleanRid].flags = startup.rid_store.data[cleanRid].flags or {}
            startup.rid_store.data[cleanRid].flags.blockRidJoin = true
            startup.rid_store.save()
        end
        return true, cleanRid
    end
    startup.rid_store.recentRecords[preKey] = nowMs

    local data = startup.rid_store.data or {}
    startup.rid_store.data = data
    local nowEpoch = os.time()
    local nowText = os.date("%Y-%m-%d %H:%M:%S", nowEpoch)
    local entry = data[cleanRid] or { firstSeen=nowEpoch, firstSeenDate=nowText, events={}, reasons={}, flags={} }
    entry.name = cleanName ~= "" and cleanName or tostring(entry.name or "Unknown")
    entry.firstSeen = tonumber(entry.firstSeen or nowEpoch) or nowEpoch
    entry.firstSeenDate = tostring(entry.firstSeenDate or os.date("%Y-%m-%d %H:%M:%S", entry.firstSeen))
    entry.lastSeen = nowEpoch
    entry.lastSeenDate = nowText
    entry.schemaVersion = 2
    entry.reasons = type(entry.reasons) == "table" and entry.reasons or {}
    entry.flags = type(entry.flags) == "table" and entry.flags or {}
    entry.names = type(entry.names) == "table" and entry.names or {}
    if entry.name ~= "" and entry.name ~= "Unknown" then entry.names[entry.name] = nowText end

    local signature = eventText .. "|" .. reasonText .. "|" .. actionText
    entry.lastEvent = eventText
    entry.lastReason = reasonText
    entry.lastAction = actionText
    entry.lastSignature = signature
    entry.lastEventAt = nowEpoch
    entry.lastEventDate = nowText
    entry.reasons[reasonText] = { lastSeen=nowEpoch, lastSeenDate=nowText, event=eventText, action=actionText }
    local eventLower = string.lower(eventText)
    if string.find(eventLower, "modder", 1, true) then entry.flags.modder = true end
    if string.find(eventLower, "crash", 1, true) then entry.flags.crashAttacker = true end
    if string.find(eventLower, "kick", 1, true) then entry.flags.kickAttacker = true end
    if string.find(eventLower, "battleye", 1, true) then entry.flags.battleye = true end
    if markBlock == true then entry.blockJoin = true; entry.flags.blockRidJoin = true end
    entry.events = type(entry.events) == "table" and entry.events or {}
    entry.events[#entry.events + 1] = { at=nowEpoch, date=nowText, event=eventText, reason=reasonText, action=actionText }
    while #entry.events > 20 do table.remove(entry.events, 1) end
    data[cleanRid] = entry

    startup.rid_store.save()
    startup.rid_store.append_event(entry.name, cleanRid, eventText, reasonText, actionText)
    startup.s.ridHistoryLastStatus = entry.name .. " saved: " .. reasonText
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("RID_HISTORY_KNOWN_IDENTITY",
            "player=" .. entry.name .. " rid=" .. cleanRid .. " event=" .. eventText
            .. " reason=" .. reasonText .. " action=" .. actionText .. " block=" .. tostring(entry.blockJoin == true))
    end
    return true, cleanRid
end

function startup.rid_store.migrate_build157_battleye_host_kick_records()
    local data = startup.rid_store.data or {}
    local changedEntries = 0

    local function is_build157_battleye_host_kick(eventType, reason)
        local eventLower = string.lower(tostring(eventType or ""))
        local reasonLower = string.lower(tostring(reason or ""))
        return eventLower == "confirmed host kick"
            and string.find(reasonLower, "battleye kick", 1, true) ~= nil
    end

    local function has_other_block_evidence(entry)
        if type(entry) ~= "table" then return false end
        local flags = type(entry.flags) == "table" and entry.flags or {}
        if flags.modder == true or flags.crashAttacker == true
            or flags.battleye == true or flags.nuked == true then
            return true
        end
        for _, event in ipairs(type(entry.events) == "table" and entry.events or {}) do
            local eventLower = string.lower(tostring(event.event or ""))
            local reasonLower = string.lower(tostring(event.reason or ""))
            if not is_build157_battleye_host_kick(event.event, event.reason) then
                if string.find(eventLower, "modder", 1, true)
                    or string.find(eventLower, "crash", 1, true)
                    or string.find(eventLower, "kick", 1, true)
                    or string.find(eventLower, "battleye", 1, true)
                    or string.find(eventLower, "nuke", 1, true)
                    or string.find(eventLower, "blocked rid join", 1, true)
                    or string.find(reasonLower, "battleye emulation", 1, true) then
                    return true
                end
            end
        end
        return false
    end

    for _, entry in pairs(data) do
        if type(entry) == "table" then
            local entryChanged = false
            local events = type(entry.events) == "table" and entry.events or {}
            for i = #events, 1, -1 do
                local event = events[i]
                if type(event) == "table" and is_build157_battleye_host_kick(event.event, event.reason) then
                    table.remove(events, i)
                    entryChanged = true
                end
            end
            entry.events = events

            if type(entry.reasons) == "table" then
                for reasonText, reasonInfo in pairs(entry.reasons) do
                    local reasonEvent = type(reasonInfo) == "table" and reasonInfo.event or ""
                    if is_build157_battleye_host_kick(reasonEvent, reasonText) then
                        entry.reasons[reasonText] = nil
                        entryChanged = true
                    end
                end
            end

            if is_build157_battleye_host_kick(entry.lastEvent, entry.lastReason) then
                local last = entry.events[#entry.events]
                if type(last) == "table" then
                    entry.lastEvent = last.event
                    entry.lastReason = last.reason
                    entry.lastAction = last.action
                    entry.lastEventAt = last.at
                    entry.lastEventDate = last.date
                    entry.lastSignature = tostring(last.event or "") .. "|" .. tostring(last.reason or "") .. "|" .. tostring(last.action or "")
                else
                    entry.lastEvent = nil
                    entry.lastReason = nil
                    entry.lastAction = nil
                    entry.lastEventAt = nil
                    entry.lastEventDate = nil
                    entry.lastSignature = nil
                end
                entryChanged = true
            end

            if entryChanged then
                local otherBlockEvidence = has_other_block_evidence(entry)
                local stillHasKickEvidence = false
                for _, event in ipairs(entry.events or {}) do
                    if string.find(string.lower(tostring(event.event or "")), "kick", 1, true) then
                        stillHasKickEvidence = true
                        break
                    end
                end
                entry.flags = type(entry.flags) == "table" and entry.flags or {}
                if not stillHasKickEvidence then entry.flags.kickAttacker = nil end
                if not otherBlockEvidence then
                    entry.blockJoin = nil
                    entry.flags.blockRidJoin = nil
                end
                changedEntries = changedEntries + 1
            end
        end
    end

    startup.rid_store.battleye_host_kick_cleanup_total = changedEntries
    if changedEntries > 0 then
        startup.rid_store.save()
        startup.log("[RID History] Removed mistaken Build 157 BattlEye host-kick evidence from "
            .. tostring(changedEntries) .. " saved RID record(s). Unrelated evidence was preserved.")
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("BATTLEYE_HOST_KICK_MIGRATION",
                "cleaned_records=" .. tostring(changedEntries) .. " classification=informational-only")
        end
    end
    return changedEntries
end

function startup.rid_store.tick()
    if startup.s.blockRidJoinsEnabled ~= true then
        local hasBrowserManualBlock = false
        for _, browserBlockEntry in pairs(startup.rid_store.data or {}) do
            local browserFlags = type(browserBlockEntry) == "table" and type(browserBlockEntry.flags) == "table" and browserBlockEntry.flags or {}
            if browserFlags.browserManualBlock == true then hasBrowserManualBlock = true; break end
        end
        if not hasBrowserManualBlock then return end
    end
    local now = startup.now()
    if now - (tonumber(startup.rid_store.lastTickMs or 0) or 0) < 1500 then return end
    startup.rid_store.lastTickMs = now
    local hostId = -1; local _, hid = startup.get_session_host_name(); hostId = tonumber(hid) or -1
    for _, playerId in ipairs(startup.get_voice_player_ids()) do
        local localPlayer = false
        for _, lid in ipairs(startup.get_local_player_id_candidates()) do if tonumber(lid)==tonumber(playerId) then localPlayer=true break end end
        if not localPlayer then
            local ident = startup.rid_store.identity(playerId)
            local entry = ident and startup.rid_store.data[ident.rid] or nil
            if ident and entry and entry.blockJoin == true then
                local firstSeen = tonumber(startup.rid_store.seenSession[ident.rid] or 0) or 0
                if firstSeen == 0 then startup.rid_store.seenSession[ident.rid] = now; firstSeen = now end
                local browserManualBlock = type(entry.flags)=="table" and entry.flags.browserManualBlock == true
                local friendSkip = (not browserManualBlock) and startup.s.ignoreFriendsRidJoins == true and startup.is_player_current_friend(playerId)
                local hostSkip = browserManualBlock and tonumber(playerId) == hostId or (startup.is_prime_active_edition() and tonumber(playerId) == hostId)
                local verifiedPeerSkip = (not browserManualBlock) and startup.browser_safety and startup.browser_safety.is_verified_peer and startup.browser_safety.is_verified_peer(playerId) == true
                local last = tonumber(startup.rid_store.kickCooldown[ident.rid] or 0) or 0
                if not friendSkip and not hostSkip and not verifiedPeerSkip and now-firstSeen >= 8000 and now-last > 15000 then
                    startup.rid_store.kickCooldown[ident.rid] = now
                    local sent = false
                    local action = "Smart Kick unavailable"
                    if browserManualBlock and startup.nuke_join_kick and startup.nuke_join_kick.run_for_player_id then
                        sent = startup.nuke_join_kick.run_for_player_id(playerId, true, "Browser Manual Block Rejoin", false) == true
                        action = sent and "Nuke Join & Kick" or "Nuke Join & Kick unavailable"
                    else
                        local feature = startup.country_filter.find_player_feature_by_names(playerId, {"Smart Kick","Smart kick","SMART KICK"})
                        sent = feature and startup.country_filter.click_player_feature(feature) == true
                        action = sent and "Smart Kick" or "Smart Kick unavailable"
                    end
                    startup.log("Blocked RID join: "..ident.name.." ["..ident.rid.."] | "..tostring(entry.lastReason or "Saved RID").." | "..action)
                    startup.rid_store.record(playerId, "Blocked RID Join", tostring(entry.lastReason or "Saved RID"), action, true)
                end
            end
        end
    end
end

function startup.support_file_exists(path)
    path = tostring(path or "")
    if path == "" then return false end
    if FileMgr and FileMgr.DoesFileExist then
        local ok, exists = direct_call(function() return FileMgr.DoesFileExist(path) end)
        if ok and exists == true then return true end
    end
    local file = io and io.open and io.open(path, "rb") or nil
    if file then file:close(); return true end
    return false
end

function startup.support_file_size(path)
    local file = io and io.open and io.open(tostring(path or ""), "rb") or nil
    if not file then return 0 end
    local size = file:seek("end") or 0
    file:close()
    return tonumber(size or 0) or 0
end

function startup.copy_to_clipboard(text)
    text = tostring(text or "")
    if text == "" then return false end
    if Utils and Utils.SetClipBoardText then
        local ok = direct_call(function() Utils.SetClipBoardText(text, "") end)
        if ok then return true end
    end
    if Utils and Utils.SetClipboardText then
        local ok = direct_call(function() Utils.SetClipboardText(text) end)
        if ok then return true end
    end
    if ImGui and ImGui.SetClipboardText then
        local ok = direct_call(function() ImGui.SetClipboardText(text) end)
        if ok then return true end
    end
    return false
end


-- ===============================================================================
-- path compatibility and folder access
-- note: resolves redirected Documents/OneDrive roots and exposes the exact path.
-- ===============================================================================

startup.primary_support_dir = startup.primary_support_dir or startup.support_dir
startup.primary_support_zip_path = startup.primary_support_zip_path or startup.SupportZipPath
startup.support_zip_log_tail_limit = tonumber(startup.support_zip_log_tail_limit or 8388608) or 8388608
startup.support_zip_timeout_ms = tonumber(startup.support_zip_timeout_ms or 45000) or 45000

function startup.get_env_path(name)
    if not os or not os.getenv then return "" end
    return tostring(os.getenv(tostring(name or "")) or ""):gsub("/", "\\"):gsub("\\+$", "")
end

function startup.path_join(left, right)
    left = tostring(left or ""):gsub("/", "\\"):gsub("\\+$", "")
    right = tostring(right or ""):gsub("/", "\\"):gsub("^\\+", "")
    if left == "" then return right end
    if right == "" then return left end
    return left .. "\\" .. right
end

function startup.refresh_cherax_log_path()
    local candidates, seen = {}, {}
    local function add(path)
        path = tostring(path or ""):gsub("/", "\\")
        if path == "" then return end
        local key = path:lower()
        if seen[key] then return end
        seen[key] = true
        candidates[#candidates + 1] = path
    end

    add(startup.path_join(startup.menu_root, "Cherax.log"))
    local roots = {
        startup.get_env_path("OneDrive"),
        startup.get_env_path("OneDriveConsumer"),
        startup.get_env_path("OneDriveCommercial"),
        startup.get_env_path("USERPROFILE"),
        startup.get_env_path("HOMEDRIVE") .. startup.get_env_path("HOMEPATH")
    }
    for _, root in ipairs(roots) do
        if root ~= "" then add(startup.path_join(root, "Documents\\Cherax\\Cherax.log")) end
    end

    for _, path in ipairs(candidates) do
        local exists = false
        if FileMgr and FileMgr.DoesFileExist then
            local ok, value = direct_call(FileMgr.DoesFileExist, path)
            exists = ok and value == true
        end
        if not exists and io and io.open then
            local file = io.open(path, "rb")
            if file then file:close(); exists = true end
        end
        if exists then
            startup.CheraxLogPath = path
            startup.s.cheraxLogResolvedPath = path
            return path
        end
    end

    startup.CheraxLogPath = candidates[1] or startup.CheraxLogPath
    startup.s.cheraxLogResolvedPath = tostring(startup.CheraxLogPath or "")
    return startup.CheraxLogPath
end

function startup.directory_is_writable(path)
    path = tostring(path or ""):gsub("/", "\\"):gsub("\\+$", "")
    if path == "" then return false end
    if FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, path) end
    local testPath = path .. "\\.startup_write_test.tmp"
    local file = io and io.open and io.open(testPath, "wb") or nil
    if not file then return false end
    file:write("Startup write test")
    file:close()
    direct_call(os.remove, testPath)
    if FileMgr and FileMgr.DeleteFile then direct_call(FileMgr.DeleteFile, testPath) end
    return true
end

function startup.set_support_output_dir(path, mode)
    path = tostring(path or ""):gsub("/", "\\"):gsub("\\+$", "")
    startup.SupportZipPath = path .. "\\Startup_Support.zip"
    startup.SupportZipTempPath = path .. "\\Startup_Support.tmp"
    startup.SupportZipBackupPath = path .. "\\Startup_Support.previous"
    startup.SupportZipNotesFile = path .. "\\ZIP_NOTES.txt"
    startup.s.supportZipOutputMode = tostring(mode or "Primary Startup folder")
    return path
end

function startup.prepare_support_output_paths()
    local candidates, seen = {}, {}
    local function add(path, mode)
        path = tostring(path or ""):gsub("/", "\\"):gsub("\\+$", "")
        if path == "" then return end
        local key = path:lower()
        if seen[key] then return end
        seen[key] = true
        candidates[#candidates + 1] = { path = path, mode = mode }
    end

    add(startup.primary_support_dir or startup.support_dir, "Primary Startup folder")
    local temp = startup.get_env_path("TEMP")
    local localApp = startup.get_env_path("LOCALAPPDATA")
    if temp ~= "" then add(startup.path_join(temp, "Startup\\Support"), "Windows TEMP fallback") end
    if localApp ~= "" then add(startup.path_join(localApp, "Startup\\Support"), "LocalAppData fallback") end

    for _, candidate in ipairs(candidates) do
        if startup.directory_is_writable(candidate.path) then
            startup.set_support_output_dir(candidate.path, candidate.mode)
            local notes = {
                "Startup Support ZIP Notes",
                "",
                "Output mode: " .. tostring(candidate.mode),
                "Output folder: " .. tostring(candidate.path),
                "Startup folder: " .. tostring(startup.storage_dir or ""),
                "Cherax root: " .. tostring(startup.menu_root or ""),
                "Cherax.log resolved path: " .. tostring(startup.refresh_cherax_log_path() or ""),
                "",
                "For reliability, files are stored without compression.",
                "If Cherax.log is larger than 8 MB, only its newest 8 MB are included.",
                "This prevents large logs from leaving the UI stuck on Creating ZIP."
            }
            local noteFile = io.open(startup.SupportZipNotesFile, "wb")
            if noteFile then noteFile:write(table.concat(notes, "\r\n") .. "\r\n"); noteFile:close() end
            return candidate.path
        end
    end
    return nil
end

function startup.copy_startup_folder_path()
    startup.ensure_save_dir()
    local path = tostring(startup.storage_dir or startup.save_dir or "")
    local copied = startup.copy_to_clipboard(path)
    startup.toast(copied and "Exact Startup folder path copied." or "Could not copy the Startup folder path.", 4000)
    return copied
end

function startup.open_startup_folder()
    startup.ensure_save_dir()
    local path = tostring(startup.storage_dir or startup.save_dir or "")
    if path == "" then return false end
    local safe = path:gsub('"', '')
    local ok, result = direct_call(function()
        if os and os.execute then return os.execute('explorer.exe "' .. safe .. '"') end
        return false
    end)
    if ok and result ~= false and result ~= nil then
        startup.toast("Opening the exact Startup folder.", 3000)
        return true
    end
    startup.copy_startup_folder_path()
    startup.toast("Windows could not open the folder automatically. The exact path was copied instead.", 5000)
    return false
end

function startup.open_url(url)
    url = tostring(url or "")
    if url == "" then return false end
    if Utils and Utils.OpenURL then
        local ok, value = direct_call(function() return Utils.OpenURL(url) end)
        if ok then return value ~= false end
    end
    if Utils and Utils.OpenUrl then
        local ok, value = direct_call(function() return Utils.OpenUrl(url) end)
        if ok then return value ~= false end
    end
    if GUI and GUI.OpenURL then
        local ok, value = direct_call(function() return GUI.OpenURL(url) end)
        if ok then return value ~= false end
    end
    return false
end

function startup.get_local_utc_offset_seconds(epoch)
    local now = tonumber(epoch or os.time()) or os.time()
    local utc_table = os.date("!*t", now)
    if type(utc_table) ~= "table" then return 0 end
    utc_table.isdst = nil
    local utc_interpreted_as_local = os.time(utc_table)
    if not utc_interpreted_as_local then return 0 end
    return math.floor(tonumber(os.difftime(now, utc_interpreted_as_local) or 0) or 0)
end

function startup.format_utc_offset(offset_seconds)
    local total_minutes = math.floor((tonumber(offset_seconds or 0) or 0) / 60)
    local sign = total_minutes >= 0 and "+" or "-"
    total_minutes = math.abs(total_minutes)
    local hours = math.floor(total_minutes / 60)
    local minutes = total_minutes % 60
    return string.format("UTC%s%02d:%02d", sign, hours, minutes)
end

function startup.format_clock_time_12h(hour, minute)
    hour = math.floor(tonumber(hour or 0) or 0) % 24
    minute = math.floor(tonumber(minute or 0) or 0) % 60
    local suffix = hour >= 12 and "PM" or "AM"
    local display_hour = hour % 12
    if display_hour == 0 then display_hour = 12 end
    return string.format("%d:%02d %s", display_hour, minute, suffix)
end

function startup.get_matchmaking_peak_local_info()
    local offset_seconds = startup.get_local_utc_offset_seconds(os.time())
    local offset_minutes = math.floor(offset_seconds / 60)
    local utc_minutes = (tonumber(startup.matchmaking_peak_utc_hour or 14) or 14) * 60
        + (tonumber(startup.matchmaking_peak_utc_minute or 0) or 0)
    local raw_local_minutes = utc_minutes + offset_minutes
    local day_shift = math.floor(raw_local_minutes / 1440)
    local local_minutes = raw_local_minutes % 1440
    if local_minutes < 0 then local_minutes = local_minutes + 1440 end
    local hour = math.floor(local_minutes / 60)
    local minute = local_minutes % 60
    local zone_name = tostring(os.date("%Z") or ""):gsub("^%s+", ""):gsub("%s+$", "")
    local offset_label = startup.format_utc_offset(offset_seconds)
    local zone_label = offset_label
    if zone_name ~= "" and zone_name ~= offset_label then
        zone_label = zone_name .. ", " .. offset_label
    end
    local day_note = ""
    if day_shift < 0 then day_note = " (previous day)"
    elseif day_shift > 0 then day_note = " (next day)" end
    return {
        utc = string.format("%02d:%02d UTC", tonumber(startup.matchmaking_peak_utc_hour or 14) or 14, tonumber(startup.matchmaking_peak_utc_minute or 0) or 0),
        local_time = startup.format_clock_time_12h(hour, minute) .. day_note,
        zone = zone_label,
        offset_seconds = offset_seconds,
        day_shift = day_shift
    }
end

function startup.open_matchmaking_chart(url, label)
    url = tostring(url or "")
    label = tostring(label or "SteamDB")
    local opened = startup.open_url(url)
    if opened then
        startup.toast(label .. " SteamDB chart opened.", 3500)
        return true
    end
    local copied = startup.copy_to_clipboard(url)
    if copied then
        startup.toast("Browser could not open. " .. label .. " chart link copied.", 4500)
    else
        startup.toast("Could not open or copy the " .. label .. " chart link.", 4500)
    end
    return false
end

function startup.support_log_event_quiet(kind, message)
    -- B359: support logging must never open files from Cherax render/event callbacks
    -- during the critical Auto Start window. It becomes available with boot diagnostics.
    if startup.boot_diag and startup.boot_diag.ioWritesEnabled == false then return false end
    startup.ensure_save_dir()
    local line = string.format(
        "%s | %-24s | %s\n",
        os.date("%Y-%m-%d %H:%M:%S"),
        tostring(kind or "SUPPORT"),
        tostring(message or "")
    )
    local ok, wrote = pcall(function()
        local file = io and io.open and io.open(startup.SupportEventsFile, "a") or nil
        if not file then return false end
        file:write(line)
        file:close()
        return true
    end)
    return ok == true and wrote == true
end

function startup.support_log_event(kind, message)
    startup.support_log_event_quiet(kind, message)
    startup.log(tostring(kind or "SUPPORT") .. (message and message ~= "" and (" | " .. tostring(message)) or ""))
end


-- Lightweight crash breadcrumbs.
-- B359 production safety rule: NEVER perform boot-diagnostic file I/O from Cherax's
-- first renderer/event frames. Early checkpoints are memory-only and are flushed only
-- after the renderer has had a 15-second stabilization window. Diagnostics are optional:
-- if the delayed flush fails, Startup keeps running instead of retrying from a render callback.
startup.boot_diag = startup.boot_diag or {
    bootId = "",
    startedAt = 0,
    lastStage = "Not started",
    firstPresentLogged = false,
    firstHudFramesLogged = 0,
    countryTicksLogged = 0,
    healthyMarked = false,
    diagnosticsWindowMs = 20000,
    ioSafeDelayMs = 15000,
    ioWritesEnabled = false,
    ioFlushAttempted = false,
    pendingTrace = {},
    pendingLastLine = "",
    previousStatus = "",
    previousCheckpoint = ""
}

function startup.boot_diag_io_is_enabled_359()
    local diag = startup.boot_diag
    return diag and diag.ioWritesEnabled == true
end

function startup.boot_diag_read_small(path, maxBytes)
    if not startup.boot_diag_io_is_enabled_359() then return "" end
    local file = io and io.open and io.open(tostring(path or ""), "rb") or nil
    if not file then return "" end
    local data = file:read(tonumber(maxBytes or 8192) or 8192) or ""
    file:close()
    return tostring(data or "")
end

function startup.boot_diag_write_small(path, text, append)
    if not startup.boot_diag_io_is_enabled_359() then return false end
    -- Never call FileMgr.CreateDir from a render callback. Directory creation is done
    -- only by boot_diag_try_enable_io_359 from the queued worker after the grace window.
    local mode = append and "a" or "w"
    local file = io and io.open and io.open(tostring(path or ""), mode) or nil
    if not file then return false end
    file:write(tostring(text or ""))
    file:flush()
    file:close()
    return true
end

function startup.boot_diag_checkpoint(stage, detail, appendTrace)
    local diag = startup.boot_diag
    stage = tostring(stage or "UNKNOWN")
    detail = tostring(detail or "")
    diag.lastStage = stage
    local elapsed = 0
    if tonumber(diag.startedAt or 0) > 0 then elapsed = math.max(0, startup.now() - tonumber(diag.startedAt or 0)) end
    local line = string.format(
        "%s | boot=%s | +%dms | %s%s\n",
        os.date("%Y-%m-%d %H:%M:%S"),
        tostring(diag.bootId or "unknown"),
        elapsed,
        stage,
        detail ~= "" and (" | " .. detail) or ""
    )
    diag.pendingLastLine = line
    if appendTrace ~= false then
        diag.pendingTrace = diag.pendingTrace or {}
        diag.pendingTrace[#diag.pendingTrace + 1] = line
        -- Bound memory use even if a user remains in the diagnostic window for a long time.
        if #diag.pendingTrace > 96 then table.remove(diag.pendingTrace, 1) end
    end
    if startup.boot_diag_io_is_enabled_359() then
        startup.boot_diag_write_small(startup.LastCheckpointFile, line, false)
        if appendTrace ~= false then startup.boot_diag_write_small(startup.BootTraceFile, line, true) end
    end
    return true
end

function startup.boot_diag_status(state, detail)
    local diag = startup.boot_diag
    diag.pendingState = tostring(state or "Unknown")
    diag.pendingStateDetail = tostring(detail or "")
    if not startup.boot_diag_io_is_enabled_359() then return true end
    local text = table.concat({
        "Startup boot status",
        "Build: " .. tostring(startup.build_number or "Unknown"),
        "Boot ID: " .. tostring(diag.bootId or "Unknown"),
        "State: " .. tostring(state or "Unknown"),
        "Last stage: " .. tostring(diag.lastStage or "Unknown"),
        "Time: " .. os.date("%Y-%m-%d %H:%M:%S"),
        "Detail: " .. tostring(detail or "")
    }, "\n") .. "\n"
    startup.boot_diag_write_small(startup.BootStatusFile, text, false)
    return true
end

function startup.boot_diag_begin()
    local diag = startup.boot_diag
    -- No FileMgr and no io.open here. This function executes during Lua init while
    -- Cherax may still be bringing up DX12/ImGui.
    diag.startedAt = startup.now()
    diag.bootId = os.date("%Y%m%d-%H%M%S") .. "-" .. tostring(math.floor((diag.startedAt or 0) % 100000))
    diag.firstPresentLogged = false
    diag.firstHudFramesLogged = 0
    diag.countryTicksLogged = 0
    diag.healthyMarked = false
    diag.ioWritesEnabled = false
    diag.ioFlushAttempted = false
    diag.pendingTrace = {}
    diag.pendingLastLine = ""
    diag.previousStatus = ""
    diag.previousCheckpoint = ""
    startup.boot_diag_checkpoint("BOOT_BEGIN", "build=" .. tostring(startup.build_number), true)
    startup.boot_diag_status("BOOTING", "Startup initialization in progress")
end

function startup.boot_diag_try_enable_io_359(force)
    local diag = startup.boot_diag
    if not diag or diag.ioWritesEnabled == true then return true end
    if diag.ioFlushAttempted == true and force ~= true then return false end
    local elapsed = tonumber(diag.startedAt or 0) > 0 and (startup.now() - tonumber(diag.startedAt or 0)) or 0
    local safeDelay = tonumber(diag.ioSafeDelayMs or 15000) or 15000
    if force ~= true and elapsed < safeDelay then return false end

    diag.ioFlushAttempted = true
    -- This is called only from Startup's queued worker, never ON_PRESENT/ON_POST_PRESENT.
    local okDir = true
    if startup.ensure_save_dir then
        local ok, result = direct_call(startup.ensure_save_dir)
        okDir = ok and result ~= false
    end
    if not okDir then return false end

    diag.ioWritesEnabled = true
    -- Read the previous run only after the safe window. Failure is harmless.
    local previousStatus = startup.boot_diag_read_small(startup.BootStatusFile, 8192)
    local previousCheckpoint = startup.boot_diag_read_small(startup.LastCheckpointFile, 8192)
    diag.previousStatus = previousStatus
    diag.previousCheckpoint = previousCheckpoint

    local pending = diag.pendingTrace or {}
    if #pending > 0 then
        local header = string.format("\n-- B359 delayed boot trace flush | boot=%s | safeAfter=%dms --\n", tostring(diag.bootId or "unknown"), safeDelay)
        startup.boot_diag_write_small(startup.BootTraceFile, header .. table.concat(pending), true)
    end
    if tostring(diag.pendingLastLine or "") ~= "" then
        startup.boot_diag_write_small(startup.LastCheckpointFile, diag.pendingLastLine, false)
    end
    startup.boot_diag_status(diag.pendingState or "RUNNING", diag.pendingStateDetail or "Delayed diagnostic I/O enabled")
    diag.pendingTrace = {}

    if previousStatus ~= "" and not string.find(previousStatus, "State: CLEAN_UNLOAD", 1, true) then
        local previousState = previousStatus:gsub("[\r\n]+", " | ")
        local previousLast = tostring(previousCheckpoint or ""):gsub("[\r\n]+", " | ")
        startup.boot_diag_checkpoint("PREVIOUS_RUN_INCOMPLETE", previousState .. " || lastCheckpoint=" .. previousLast, true)
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("PREVIOUS_RUN_INCOMPLETE", previousState .. " || lastCheckpoint=" .. previousLast)
        end
    end
    return true
end

function startup.boot_diag_stage(stage, fn, detail)
    startup.boot_diag_checkpoint(stage .. "_BEGIN", detail or "", true)
    local ok, a, b, c = direct_call(fn)
    if ok then
        startup.boot_diag_checkpoint(stage .. "_OK", detail or "", true)
        return true, a, b, c
    end
    local err = tostring(a or "Unknown error")
    startup.boot_diag_checkpoint(stage .. "_ERROR", err, true)
    startup.boot_diag_status("ERROR", stage .. ": " .. err)
    if startup.support_log_event_quiet then startup.support_log_event_quiet("BOOT_STAGE_ERROR", stage .. " | " .. err) end
    return false, err
end

function startup.boot_diag_is_early_window()
    local diag = startup.boot_diag
    if tonumber(diag.startedAt or 0) <= 0 then return false end
    return (startup.now() - tonumber(diag.startedAt or 0)) <= (tonumber(diag.diagnosticsWindowMs or 20000) or 20000)
end

function startup.boot_diag_mark_healthy()
    if startup.boot_diag.healthyMarked then return end
    startup.boot_diag.healthyMarked = true
    startup.boot_diag_checkpoint("RUNTIME_HEALTHY", "startup survived diagnostic window", true)
    startup.boot_diag_status("HEALTHY", "Runtime loop reached stable state")
    if startup.support_log_event_quiet then startup.support_log_event_quiet("STARTUP_HEALTHY", "build=" .. tostring(startup.build_number)) end
end

function startup.get_support_discord_link()
    local direct = tostring(startup.SupportDiscordLink or "")
    if direct ~= "" then return direct, true end
    local fallback = tostring(startup.discord_link or "")
    return fallback, false
end

function startup.copy_support_zip_path()
    local path = tostring(startup.s.lastSupportZipPath or startup.SupportZipPath or "")
    local copied = startup.copy_to_clipboard(path)
    startup.toast(copied and "Support ZIP path copied." or "Could not copy Support ZIP path.", 3500)
    return copied
end

function startup.copy_support_discord()
    local url, dedicated = startup.get_support_discord_link()
    if url == "" then
        startup.toast("Dedicated support channel not configured yet.", 4000)
        return false
    end
    local copied = startup.copy_to_clipboard(url)
    local name = dedicated and tostring(startup.SupportDiscordName or "Startup Support") or "community Discord"
    startup.toast(copied and (name .. " link copied.") or "Could not copy the support Discord link.", copied and 3500 or 4500)
    if startup.support_log_event then startup.support_log_event("SUPPORT_DISCORD_COPIED", "dedicated=" .. tostring(dedicated) .. " copied=" .. tostring(copied)) end
    return copied
end

function startup.copy_and_open_support_discord()
    local url, dedicated = startup.get_support_discord_link()
    if url == "" then
        startup.toast("Dedicated support channel not configured yet.", 4000)
        return false, false
    end
    local copied = startup.copy_to_clipboard(url)
    local opened = startup.open_url(url)
    local name = dedicated and tostring(startup.SupportDiscordName or "Startup Support") or "community Discord"
    if opened and copied then
        startup.toast(name .. " opened and link copied.", 4000)
    elseif opened then
        startup.toast(name .. " opened.", 3500)
    elseif copied then
        startup.toast(name .. " link copied.", 3500)
    else
        startup.toast("Could not open or copy the support Discord link.", 4500)
    end
    startup.support_log_event("SUPPORT_DISCORD_OPENED", "dedicated=" .. tostring(dedicated) .. " opened=" .. tostring(opened) .. " copied=" .. tostring(copied))
    return copied, opened
end

function startup.get_support_runtime_metadata()
    local editionCode, gameFamily, isPrime, recognized = startup.get_active_edition_info()
    local gtaEdition = "Unknown"
    if tostring(editionCode):sub(1, 2) == "LE" then gtaEdition = "LE" end
    if tostring(editionCode):sub(1, 2) == "EE" then gtaEdition = "EE" end

    local cheraxEdition = tostring(editionCode or "Unknown")
    if recognized and isPrime == true then cheraxEdition = cheraxEdition .. " (Prime)" end

    local cheraxVersion = "Unknown"
    if Cherax and Cherax.GetVersion then
        local ok, value = direct_call(Cherax.GetVersion)
        if ok and value ~= nil and tostring(value) ~= "" then cheraxVersion = tostring(value) end
    end

    local cheraxBuild = "Unknown"
    if Cherax and Cherax.GetBuild then
        local ok, value = direct_call(Cherax.GetBuild)
        if ok and value ~= nil then cheraxBuild = tostring(value) end
    end

    local localPlayerName = "Unknown"
    if startup.get_local_player_id_candidates and startup.get_player_name_safe then
        local ids = startup.get_local_player_id_candidates()
        if type(ids) == "table" and ids[1] ~= nil then
            local ok, value = direct_call(startup.get_player_name_safe, ids[1])
            if ok and value and tostring(value) ~= "" then localPlayerName = tostring(value) end
        end
    end

    return {
        gtaEdition = gtaEdition,
        gameFamily = tostring(gameFamily or "Unknown"),
        cheraxEdition = cheraxEdition,
        cheraxVersion = cheraxVersion,
        cheraxBuild = cheraxBuild,
        isPrime = recognized and isPrime == true,
        localPlayerName = localPlayerName
    }
end

