    startup.ensure_save_dir()
    local meta = startup.get_support_runtime_metadata()
    local supportUrl, dedicated = startup.get_support_discord_link()
    local supportLine = dedicated
        and (tostring(startup.SupportDiscordName or "Startup Support") .. ": " .. tostring(supportUrl))
        or ("Dedicated Startup support channel: not configured.\nCommunity Discord fallback: " .. tostring(supportUrl))
    local lines = {
