    startup.set_feature_float_silently(startup.h.SessionHudScaleSlider, startup.s.sessionInfoHudScale or 0.30)
    startup.set_feature_int_silently(startup.h.SessionHudAlphaSlider, startup.s.sessionInfoHudAlpha or 200)
    startup.set_feature_int_silently(startup.h.SessionActivityHoldSlider, math.floor((startup.s.sessionActivityHoldMs or 7000) / 1000))
    startup.set_feature_int_silently(startup.h.SessionActivityMaxSlider, startup.s.sessionActivityMaxEntries or 0)
    startup.set_feature_int_silently(startup.h.SessionActivityBoxAlphaSlider, startup.s.sessionActivityBoxAlpha or 60)
    startup.set_feature_float_silently(startup.h.SessionActivityXSlider, startup.s.sessionActivityX or 0.027)
    startup.set_feature_float_silently(startup.h.SessionActivityYSlider, startup.s.sessionActivityBottomY or 0.806)
    startup.set_feature_float_silently(startup.h.SessionActivityScaleSlider, startup.s.sessionActivityScale or 0.42)
    startup.set_feature_float_silently(startup.h.SessionActivityBoxScaleSlider, startup.s.sessionActivityBoxWidthScale or 0.75)
    startup.set_feature_float_silently(startup.h.SessionActivityBoxHeightScaleSlider, startup.s.sessionActivityBoxHeightScale or 1.15)
    startup.set_feature_float_silently(startup.h.SessionActivityTextYOffsetSlider, startup.s.sessionActivityTextYOffset or 0.010)
    startup.set_feature_float_silently(startup.h.SessionActivityAccentHeightSlider, startup.s.sessionActivityAccentHeightRatio or 1.00)
    startup.set_feature_bool_silently(startup.h.SessionActivityAutoPosition, startup.s.sessionActivityAutoPosition ~= false)
    startup.set_feature_list_string_silently(startup.h.HudOptionsColorTarget, startup.s.hudColorTarget or "Connected Players")
    startup.hud_color_sync_editor()
    startup.set_feature_int_silently(startup.h.AlwaysDayHourSlider, startup.s.alwaysDayTargetHour or 5)
    startup.set_feature_int_silently(startup.h.AlwaysDayMinuteSlider, startup.s.alwaysDayTargetMinute or 0)
    startup.set_feature_int_silently(startup.h.AlwaysDayScanSlider, math.floor((startup.s.alwaysDayScanMs or 5000) / 1000))
    startup.set_feature_int_silently(startup.h.AlwaysNightHourSlider, startup.s.alwaysNightTargetHour or 22)
    startup.set_feature_int_silently(startup.h.AlwaysNightMinuteSlider, startup.s.alwaysNightTargetMinute or 0)
    startup.set_feature_int_silently(startup.h.BattleyeFallbackDelaySlider, math.floor((startup.s.battleyeHostKickFallbackDelayMs or 6000) / 1000))
    for _, entry in ipairs(startup.s.luaFiles) do
        local feature = FeatureMgr.GetFeature(entry.hash)
        if feature then
            feature:SetBoolValue(startup.s.luaFileStates[entry.path] == true)
        end
    end
    for _, entry in ipairs(startup.s.themeFiles or {}) do
        local feature = FeatureMgr.GetFeature(entry.hash)
        if feature then
            local key = entry.key or entry.name
            feature:SetBoolValue(startup.s.themeFileStates[key] ~= false)
        end
    end
    startup.s.syncingFeatureStates = false
end

function startup.find_int_feature_by_names(names, preferredHash)
    local feature = startup.get_feature_by_hash_safe(preferredHash)
    if feature and (feature.SetIntValue or feature.SetValue) then
        return feature, "hash " .. tostring(preferredHash)
    end
    local matchedName
    feature, matchedName = startup.find_feature_by_possible_names(names)
    if feature and (feature.SetIntValue or feature.SetValue) then return feature, matchedName end
    return nil, nil
end

function startup.set_int_feature_by_names(names, value, preferredHash)
    local feature, matchedName = startup.find_int_feature_by_names(names, preferredHash)
    if not feature then
        startup.s.advertiseCountResolution = "Unavailable"
        startup.s.lastAdvertiseStatus = "Advertise Count unavailable; Advertise Session remains active"
        return false
    end
    local ok = direct_call(function()
        if feature.SetIntValue then feature:SetIntValue(value) elseif feature.SetValue then feature:SetValue(value) end
        if feature.TriggerCallback then feature:TriggerCallback() elseif feature.OnClick then feature:OnClick() end
    end)
    if not ok then
        startup.s.advertiseCountResolution = "Resolved but callback failed"
        return false
    end
    startup.s.advertiseCountFeatureName = matchedName
    startup.s.advertiseCountResolution = tostring(matchedName or "Resolved")
    return true
end

function startup.invoke_feature_action(feature)
    if not feature then return false end
    if feature.OnClick then feature:OnClick(); return true end
    if feature.TriggerCallback then feature:TriggerCallback(); return true end
    if feature.Click then feature:Click(); return true end
    if feature.Execute then feature:Execute(); return true end
    return false
end

function startup.click_start_session_feature()
    -- B360 JOIN safety: never let Startup launch a fresh session on top of an active
    -- Browser RID JOIN. Cancel the Browser state first so no stale JOIN worker can
    -- fire after the new session has already started.
    if startup.browser_join_is_active_b360 and startup.browser_join_is_active_b360() then
        if startup.browser_cancel_join_b360 then startup.browser_cancel_join_b360("START_SESSION_REQUESTED", true) end
        if startup.toast then startup.toast("Browser JOIN cancelled before starting a new session.", 3200) end
        if startup.yield then startup.yield(100) elseif Script and Script.Yield then Script.Yield(100) end
    end
    local hash = startup.feature_hash and startup.feature_hash.START_SESSION or 3364415752
    local feature = startup.get_feature_by_hash_safe(hash)
    if feature then
        local okAction, actionResult = direct_call(startup.invoke_feature_action, feature)
        if okAction and actionResult == true then
            startup.s.lastSessionFlowStatus = "Triggered Cherax Start Session by feature hash"
            startup.toast("Clicked Start Session.", 2500)
            return true
        end
    end
    if FeatureMgr and FeatureMgr.TriggerFeatureCallback then
        local ok, result = direct_call(function() return FeatureMgr.TriggerFeatureCallback(hash) end)
        if ok and result ~= false then
            startup.s.lastSessionFlowStatus = "Triggered Cherax Start Session callback by hash"
            startup.toast("Clicked Start Session.", 2500)
            return true
        end
    end
    local fallbackNames = { "Start New Session", "Session Starter", "Start Session Starter" }
    local fallback, matchedName = startup.find_feature_by_possible_names(fallbackNames)
    if fallback then
        local okAction, actionResult = direct_call(startup.invoke_feature_action, fallback)
        if okAction and actionResult == true then
            startup.s.lastSessionFlowStatus = "Triggered session starter fallback: " .. tostring(matchedName)
            startup.toast("Clicked " .. tostring(matchedName) .. ".", 2500)
            return true
        end
    end
    startup.s.lastSessionFlowStatus = "Cherax Start Session feature unavailable"
    startup.error("Could not trigger Cherax Start Session feature (hash " .. tostring(hash) .. ").")
    return false
end

function startup.click_feature_by_names(names)
    local feature, matchedName = startup.find_feature_by_possible_names(names)
    if not feature then
        startup.error("Could not find button feature. Tried: " .. table.concat(names, ", "))
        return false
    end
    local okAction, actionResult = direct_call(startup.invoke_feature_action, feature)
    if not okAction or actionResult ~= true then
        startup.error("Feature has no callable button action: " .. tostring(matchedName))
        return false
    end
    startup.toast("Clicked " .. matchedName .. ".", 2500)
    return true
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- theme scanner
-- note: recursively discovers clickgui themes and preserves enabled choices.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.get_relative_path(path, root)
    local full = tostring(path or ""):gsub("/", "\\")
    local base = tostring(root or ""):gsub("/", "\\")
    if full == "" or base == "" then
        return startup.get_file_name(full)
    end
    local fullLower = string.lower(full)
    local baseLower = string.lower(base)
    if string.sub(fullLower, 1, #baseLower) == baseLower then
        local rel = string.sub(full, #base + 1):gsub("^[\\/]+", "")
        if rel and rel ~= "" then
            return rel
        end
    end
    return startup.get_file_name(full)
end

function startup.get_theme_meta(path)
    local bestRelative = nil
    for _, root in ipairs(startup.theme_dirs or {}) do
        local rel = startup.get_relative_path(path, root)
        if rel and rel ~= "" and rel ~= startup.get_file_name(path) then
            bestRelative = rel
            break
        end
        bestRelative = bestRelative or rel
    end
    local relative = bestRelative or startup.get_file_name(path)
    local folder = relative:match("^(.*)[/\\][^/\\]+$") or "ClickGUI Root"
    if folder == "" then folder = "ClickGUI Root" end
    return {
        fileName = startup.get_file_name(path),
        relative = relative,
        folder = folder,
        key = string.lower(relative),
        displayName = startup.get_file_name(path),
        loadName = relative
    }
end

function startup.find_theme_files()
    local found = {}
    for _, folderPath in ipairs(startup.theme_dirs or {}) do
        local files = FileMgr.FindFiles(folderPath, ".json", true)
        for _, path in ipairs(files or {}) do
            if not startup.path_exists_in_list(found, path) then found[#found + 1] = path end
        end
    end
    table.sort(found, function(a, b)
        local ma, mb = startup.get_theme_meta(a), startup.get_theme_meta(b)
        return string.lower(ma.relative or ma.fileName) < string.lower(mb.relative or mb.fileName)
    end)
    return found
end

function startup.refresh_theme_file_list()
    local files = startup.find_theme_files()
    startup.s.themeFiles = {}
    startup.theme_list = {}
    for index, path in ipairs(files) do
        local meta = startup.get_theme_meta(path)
        local key = meta.key or string.lower(meta.relative or meta.fileName)
        if startup.s.themeFileStates[key] == nil then
            if startup.s.themeFileStates[meta.fileName] ~= nil then
                startup.s.themeFileStates[key] = startup.s.themeFileStates[meta.fileName]
            else
                startup.s.themeFileStates[key] = true
            end
        end
        local entry = {
            index = index,
            path = path,
            name = meta.fileName,
            fileName = meta.fileName,
            relative = meta.relative,
            folder = meta.folder,
            key = key,
            displayName = meta.displayName,
            loadName = meta.loadName,
            hash = startup.hash("THEME_ON_STARTUP_" .. tostring(key))
        }
        table.insert(startup.s.themeFiles, entry)
        table.insert(startup.theme_list, entry.relative or entry.name)
    end
    if #startup.s.themeFiles > 0 then
        startup.s.lastThemeStatus = "Found " .. tostring(#startup.s.themeFiles) .. " theme file(s), including subfolders"
    else
        startup.s.lastThemeStatus = "No theme .json files found in Theme\\ClickGUI or its subfolders"
    end
end

function startup.count_enabled_themes()
    local count = 0
    for _, entry in ipairs(startup.s.themeFiles or {}) do
        local key = entry.key or entry.name
        if startup.s.themeFileStates[key] ~= false then
            count = count + 1
        end
    end
    return count
end

function startup.get_enabled_theme_files()
    startup.refresh_theme_file_list()
    local enabled = {}
    for _, entry in ipairs(startup.s.themeFiles or {}) do
        local key = entry.key or entry.name
        if startup.s.themeFileStates[key] ~= false then
            table.insert(enabled, entry.loadName or entry.relative or entry.name)
        end
    end
    return enabled
end

function startup.find_theme_entry(themeFile)
    local wanted = tostring(themeFile or "")
    local wantedLower = string.lower(wanted)
    local wantedFile = string.lower(startup.get_file_name(wanted))
    for _, entry in ipairs(startup.s.themeFiles or {}) do
        if string.lower(tostring(entry.loadName or "")) == wantedLower
            or string.lower(tostring(entry.relative or "")) == wantedLower
            or string.lower(tostring(entry.name or "")) == wantedLower
            or string.lower(tostring(entry.key or "")) == wantedLower
            or string.lower(startup.get_file_name(entry.name or "")) == wantedFile then
            return entry
        end
    end
    return nil
end

function startup.get_theme_load_candidates(themeFile)
    local candidates = {}
    local function add(value)
        value = tostring(value or "")
        if value == "" then return end
        for _, existing in ipairs(candidates) do
            if string.lower(existing) == string.lower(value) then
                return
            end
        end
        table.insert(candidates, value)
        local forward = value:gsub("\\", "/")
        if forward ~= value then add(forward) end
        local back = value:gsub("/", "\\")
        if back ~= value then add(back) end
    end
    local entry = startup.find_theme_entry(themeFile)
    add(themeFile)
    if entry then
        add(entry.loadName)
        add(entry.relative)
        add(entry.name)
        add(startup.get_file_name(entry.name))
        add(startup.get_file_name(entry.relative))
    else
        add(startup.get_file_name(themeFile))
    end
    return candidates
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- startup automation
-- note: loads settings, themes, and the selected online session in order.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.find_feature_by_names(names)
    if not FeatureMgr then return nil, nil end

    if FeatureMgr.GetFeatureByName then
        for _, name in ipairs(names or {}) do
            local feature = FeatureMgr.GetFeatureByName(name)
            if feature then return feature, name end
        end
    end

    if not FeatureMgr.GetAllFeatures then return nil, nil end
    local features = FeatureMgr.GetAllFeatures()
    if type(features) ~= "table" then return nil, nil end

    for _, feature in pairs(features) do
        local feature_name = startup.read_feature_name(feature):lower()
        for _, name in ipairs(names or {}) do
            if feature_name:find(tostring(name):lower(), 1, true) then
                return feature, feature_name
            end
        end
    end
    return nil, nil
end

function startup.find_settings_name_feature()
    local feature, name = startup.find_feature_by_names({
        "Settings Name",
        "Setting Name",
        "Settings File Name",
        "Save Settings As",
        "Save Name"
    })
    if feature and (feature.SetStringValue or feature.SetValue) then return feature, name end

    if not FeatureMgr or not FeatureMgr.GetAllFeatures then return nil, nil end
    local features = FeatureMgr.GetAllFeatures()
    if type(features) ~= "table" then return nil, nil end
    for _, candidate in pairs(features) do
        local candidate_name = startup.read_feature_name(candidate):lower()
        local looks_like_name = candidate_name:find("name", 1, true)
            and (candidate_name:find("settings", 1, true) or candidate_name:find("save", 1, true))
        if looks_like_name and candidate.SetStringValue then
            return candidate, candidate_name
        end
    end
    return nil, nil
end

function startup.find_save_settings_feature()
    local feature, name = startup.find_feature_by_names({
        "Save Settings",
        "Save Current Settings",
        "Save Setting"
    })
    if feature and (feature.TriggerCallback or feature.OnClick) then return feature, name end
    return nil, nil
end

function startup.settings_profile_name_from_value(value)
    if type(value) == "table" then
        value = value.name or value.Name or value.label or value.Label or value.value or value.Value or value.file or value.File or value.filename or value.FileName
    end
    local name = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then return "" end
    name = name:gsub("/", "\\")
    name = name:match("([^\\]+)$") or name
    return name
end

function startup.settings_feature_list()
    -- Use Cherax's official hash-based list API for the built-in Settings selector.
    -- This returns the saved profile names without reading native feature userdata,
    -- probing Load Settings, scanning all features, or using protected calls.
    if not FeatureMgr or not FeatureMgr.GetFeatureList then return nil end
    local list = FeatureMgr.GetFeatureList(startup.feature_hash.SETTINGS)
    if type(list) == "table" then return list end
    return nil
end

function startup.settings_profile_names_match(left, right)
    local function normalize(value)
        local name = startup.settings_profile_name_from_value(value):lower()
        if name:sub(-5) == ".json" then name = name:sub(1, -6) end
        return name
    end
    local a, b = normalize(left), normalize(right)
    return a ~= "" and a == b
end

function startup.settings_profile_list_index(list, wanted)
    if type(list) ~= "table" then return nil end
    local zeroBased = list[0] ~= nil
    for key, value in pairs(list) do
        if startup.settings_profile_names_match(value, wanted) then
            local numericKey = tonumber(key)
            if numericKey == nil then return nil end
            return zeroBased and numericKey or (numericKey - 1)
        end
    end
    return nil
end

function startup.settings_profile_table_stats(value)
    local stats = {
        valueType = type(value),
        total = 0,
        numeric = 0,
        stringKeys = 0,
        minNumeric = nil,
        maxNumeric = nil,
        sample = {}
    }
    if value == nil then return stats end

    -- FileMgr.FindFiles is documented as a table, but current Cherax builds expose
    -- a native userdata wrapper that still supports ordinary ipairs iteration.
    -- Keep this decoder limited strictly to FileMgr results. Do not inspect fields,
    -- methods, or arbitrary feature userdata.
    local index = 0
    for _, item in ipairs(value) do
        index = index + 1
        stats.total = stats.total + 1
        stats.numeric = stats.numeric + 1
        if stats.minNumeric == nil then stats.minNumeric = 1 end
        stats.maxNumeric = index
        if #stats.sample < 4 then
            stats.sample[#stats.sample + 1] = tostring(item or "")
        end
    end
    return stats
end

function startup.settings_profile_path_is_under_settings(path, settingsDir)
    local full = tostring(path or ""):gsub("/", "\\")
    local dir = tostring(settingsDir or ""):gsub("/", "\\"):gsub("\\+$", "")
    if full == "" or dir == "" then return false end
    local lowerFull = full:lower()
    local lowerDir = dir:lower()
    return lowerFull:sub(1, #lowerDir + 1) == lowerDir .. "\\"
        or lowerFull == lowerDir
end

function startup.build_settings_profile_probe_plan()
    local root = tostring(startup.menu_root or ""):gsub("/", "\\"):gsub("\\+$", "")
    local exact = tostring(startup.cherax_settings_dir or (root .. "\\Settings")):gsub("/", "\\"):gsub("\\+$", "")
    local userProfile = os and os.getenv and tostring(os.getenv("USERPROFILE") or "") or ""
    local oneDrive = os and os.getenv and tostring(os.getenv("OneDrive") or "") or ""
    local oneDriveConsumer = os and os.getenv and tostring(os.getenv("OneDriveConsumer") or "") or ""
    local oneDriveCommercial = os and os.getenv and tostring(os.getenv("OneDriveCommercial") or "") or ""
    local homeDrive = os and os.getenv and tostring(os.getenv("HOMEDRIVE") or "") or ""
    local homePath = os and os.getenv and tostring(os.getenv("HOMEPATH") or "") or ""
    local home = homeDrive .. homePath

    return {
        { "Exact .json nonrecursive", exact, ".json", false, false },
        { "Exact .json recursive", exact, ".json", true, false },
        { "Exact json nonrecursive", exact, "json", false, false },
        { "Exact json recursive", exact, "json", true, false },
        { "Exact wildcard nonrecursive", exact, "*.json", false, false },
        { "Exact wildcard recursive", exact, "*.json", true, false },
        { "Exact uppercase nonrecursive", exact, ".JSON", false, false },
        { "Exact uppercase recursive", exact, ".JSON", true, false },
        { "Exact all-files nonrecursive", exact, "", false, false },
        { "Exact all-files recursive", exact, "", true, false },
        { "Exact trailing slash nonrecursive", exact .. "\\", ".json", false, false },
        { "Exact trailing slash recursive", exact .. "\\", ".json", true, false },
        { "Exact forward slash nonrecursive", exact:gsub("\\", "/"), ".json", false, false },
        { "Exact forward slash recursive", exact:gsub("\\", "/"), ".json", true, false },
        { "Menu root .json recursive", root, ".json", true, true },
        { "Menu root json recursive", root, "json", true, true },
        { "Menu root wildcard recursive", root, "*.json", true, true },
        { "Menu root all-files recursive", root, "", true, true },
        { "Root Settings .json nonrecursive", root .. "\\Settings", ".json", false, false },
        { "Root Settings .json recursive", root .. "\\Settings", ".json", true, false },
        { "Settings Profiles nonrecursive", root .. "\\Settings\\Profiles", ".json", false, false },
        { "Settings Profiles recursive", root .. "\\Settings\\Profiles", ".json", true, false },
        { "Settings Saved nonrecursive", root .. "\\Settings\\Saved", ".json", false, false },
        { "Settings Saved recursive", root .. "\\Settings\\Saved", ".json", true, false },
        { "Root Profiles recursive", root .. "\\Profiles", ".json", true, false },
        { "Root Profile recursive", root .. "\\Profile", ".json", true, false },
        { "Root Setting recursive", root .. "\\Setting", ".json", true, false },
        { "USERPROFILE Documents candidate", userProfile ~= "" and (userProfile .. "\\Documents\\Cherax\\Settings") or "", ".json", true, false },
        { "OneDrive Documents candidate", oneDrive ~= "" and (oneDrive .. "\\Documents\\Cherax\\Settings") or "", ".json", true, false },
        { "OneDriveConsumer Documents candidate", oneDriveConsumer ~= "" and (oneDriveConsumer .. "\\Documents\\Cherax\\Settings") or "", ".json", true, false },
        { "OneDriveCommercial Documents candidate", oneDriveCommercial ~= "" and (oneDriveCommercial .. "\\Documents\\Cherax\\Settings") or "", ".json", true, false },
        { "HOMEDRIVE HOMEPATH candidate", home ~= "" and (home .. "\\Documents\\Cherax\\Settings") or "", ".json", true, false }
    }
end

function startup.refresh_settings_profiles(runDeepDiagnostics)
    local profiles, seen, sources = {}, {}, {}
    local diagnosticLines = {}
    local exactSettingsDir = tostring(startup.cherax_settings_dir or ""):gsub("/", "\\"):gsub("\\+$", "")

    local function diagnostic(line)
        diagnosticLines[#diagnosticLines + 1] = tostring(line or "")
    end

    local function add(value, source, allowNoExtension)
        local name = startup.settings_profile_name_from_value(value)
        if name == "" then return false end
        local lower = name:lower()
        local isJson = lower:sub(-5) == ".json"
        if not isJson and allowNoExtension ~= true then return false end
        if not isJson and allowNoExtension == true and lower:find("%.") then return false end
        if not seen[lower] then
            seen[lower] = true
            profiles[#profiles + 1] = name
            if source and source ~= "" then sources[source] = true end
            return true
        end
        return false
    end

    local function add_files(files, source, settingsOnly)
        if files == nil then return 0, 0 end
        local raw, accepted = 0, 0

        -- Current Cherax returns FileMgr.FindFiles as userdata even though the API
        -- documents a table. The wrapper is safely iterable with ipairs, exactly as
        -- Startup's working theme scanner already does. This avoids the old dangerous
        -- generic userdata decoder that caused blank Cherax menu labels.
        for _, path in ipairs(files) do
            raw = raw + 1
            if settingsOnly ~= true or startup.settings_profile_path_is_under_settings(path, exactSettingsDir) then
                if add(path, source, false) then accepted = accepted + 1 end
            end
        end
        return raw, accepted
    end

    local function run_probe(index, probe, emitLine)
        local label, dir, extension, recursive, settingsOnly = probe[1], probe[2], probe[3], probe[4], probe[5]
        dir = tostring(dir or "")
        if dir == "" or not FileMgr or not FileMgr.FindFiles then
            if emitLine then diagnostic(string.format("%02d/30 %s | skipped | dir=%s", index, label, dir ~= "" and dir or "<empty>")) end
            return
        end
        local before = #profiles
        local files = FileMgr.FindFiles(dir, extension, recursive == true)
        local stats = startup.settings_profile_table_stats(files)
        local raw, accepted = add_files(files, "probe:" .. label, settingsOnly == true)
        if emitLine then
            local sample = #stats.sample > 0 and table.concat(stats.sample, " || ") or "<none>"
            diagnostic(string.format(
                "%02d/30 %s | type=%s raw=%d accepted=%d new=%d keys=%d numeric=%d range=%s..%s dir=%s ext=%s recursive=%s sample=%s",
                index, label, stats.valueType, raw, accepted, #profiles - before, stats.total, stats.numeric,
                tostring(stats.minNumeric), tostring(stats.maxNumeric), dir, extension == "" and "<empty>" or extension,
                tostring(recursive == true), sample))
        end
    end

    -- Cherax selector is retained only as an additional source. It must never stop
    -- filesystem discovery because some builds expose only the current profile here.
    local settingsList = startup.settings_feature_list()
    if type(settingsList) == "table" then
        for _, value in pairs(settingsList) do add(value, "settings-selector", true) end
    end
    if FeatureMgr and FeatureMgr.GetCurrentFeatureListString then
        add(FeatureMgr.GetCurrentFeatureListString(startup.feature_hash.SETTINGS), "settings-current", true)
    end

    -- Core probes run on every refresh. The menu-root recursive probe is important:
    -- some Cherax builds do not enumerate correctly when FindFiles receives the
    -- Settings directory directly, but do return every JSON from the menu root.
    local plan = startup.build_settings_profile_probe_plan()
    local coreIndexes = { 1, 2, 3, 5, 11, 13, 15, 20, 22, 24 }
    local coreDone = {}
    for _, index in ipairs(coreIndexes) do
        coreDone[index] = true
        run_probe(index, plan[index], runDeepDiagnostics == true)
    end

    -- A manual refresh requests the complete path-probe report. These probes also
    -- contribute any additional JSON files they find.
    if runDeepDiagnostics == true then
        for index, probe in ipairs(plan) do
            if not coreDone[index] then run_probe(index, probe, true) end
        end
    end

    -- Windows directory enumeration is a second independent source. It is always
    -- merged, even when the Cherax selector already returned default.json.
    if io and io.popen and exactSettingsDir ~= "" then
        local commands = {
            { "DIR JSON recursive", 'dir /b /s /a-d "' .. exactSettingsDir .. '\\*.json" 2>nul' },
            { "DIR all recursive", 'dir /b /s /a-d "' .. exactSettingsDir .. '\\*" 2>nul' },
            { "WHERE JSON recursive", 'where /r "' .. exactSettingsDir .. '" *.json 2>nul' }
        }
        for commandIndex, command in ipairs(commands) do
            local before = #profiles
            local raw = 0
            local pipe = io.popen(command[2])
            if pipe then
                for line in pipe:lines() do
                    raw = raw + 1
                    add(line, "shell:" .. command[1], commandIndex == 2)
                end
                pipe:close()
            end
            if runDeepDiagnostics == true then
                diagnostic("Shell " .. tostring(commandIndex) .. "/3 " .. command[1] .. " | raw=" .. tostring(raw) .. " new=" .. tostring(#profiles - before) .. " | command=" .. command[2])
            end
        end
    elseif runDeepDiagnostics == true then
        diagnostic("Shell 0/3 | io.popen unavailable or Settings path empty")
    end

    table.sort(profiles, function(a, b) return string.lower(a) < string.lower(b) end)
    startup.s.settingsProfiles = profiles
    startup.s.settingsProfilesLastRefreshMs = startup.now()

    local sourceNames = {}
    for source in pairs(sources) do sourceNames[#sourceNames + 1] = source end
    table.sort(sourceNames)
    if #profiles > 0 then
        startup.s.settingsProfilesStatus = tostring(#profiles) .. " saved profile" .. (#profiles == 1 and "" or "s") .. " found."
    else
        startup.s.settingsProfilesStatus = "No saved settings profiles found."
    end

    if runDeepDiagnostics == true then
        startup.log("[Settings Debug] BEGIN path-probe report")
        startup.log("[Settings Debug] edition=" .. tostring(startup.get_active_edition_info()) .. " | menuRoot=" .. tostring(startup.menu_root or "") .. " | settingsDir=" .. exactSettingsDir)
        startup.log("[Settings Debug] FileMgr=" .. tostring(type(FileMgr)) .. " | FindFiles=" .. tostring(FileMgr and type(FileMgr.FindFiles) or "nil") .. " | io.popen=" .. tostring(io and type(io.popen) or "nil"))
        for _, line in ipairs(diagnosticLines) do startup.log("[Settings Debug] " .. line) end
        startup.log("[Settings Debug] profiles=" .. tostring(#profiles) .. " | names=" .. (#profiles > 0 and table.concat(profiles, ", ") or "<none>"))
        startup.log("[Settings Debug] sources=" .. (#sourceNames > 0 and table.concat(sourceNames, ", ") or "<none>"))
        startup.log("[Settings Debug] END path-probe report")
        startup.s.settingsProfilesLastDiagnostic = table.concat(diagnosticLines, "\n")
    elseif startup.s.verboseStartupLogs then
        startup.log("Settings profiles refreshed | count=" .. tostring(#profiles) .. " | sources=" .. (#sourceNames > 0 and table.concat(sourceNames, ",") or "none"))
    end

    if startup.popup_flow and startup.popup_flow.active and startup.popup_flow.stage == "setup" then
        local wanted = tostring(startup.popup_flow.settingsFile or "")
        local valid = false
        for _, name in ipairs(profiles) do
            if startup.settings_profile_names_match(name, wanted) then valid = true break end
        end
        if not valid then
            local current = tostring(startup.s.settingsFile or "")
            for _, name in ipairs(profiles) do
                if startup.settings_profile_names_match(name, current) then
                    startup.popup_flow.settingsFile = name
                    valid = true
                    break
                end
            end
        end
        if not valid and #profiles == 1 then startup.popup_flow.settingsFile = profiles[1] end
    end
    return profiles
end

function startup.queue_settings_profile_refresh(showToast, runDebug)
    local manual = showToast == true
    local debugRequested = runDebug == true
    if startup.s.pendingSettingsProfileRefresh == true then
        if debugRequested then startup.s.settingsProfilesDebugRequested = true end
        if manual then startup.s.settingsProfilesRefreshToastPending = true end
        startup.s.settingsProfilesStatus = "Saved-settings refresh already queued..."
        return false
    end

    startup.s.pendingSettingsProfileRefresh = true
    startup.s.settingsProfilesDebugRequested = debugRequested
    startup.s.settingsProfilesRefreshToastPending = manual
    startup.s.settingsProfilesRefreshQueuedAtMs = startup.now()
    startup.s.settingsProfilesStatus = "Refreshing saved Cherax settings..."
    if manual then
        -- Log once instead of stacking identical GUI toasts such as "(7)".
        startup.log("Refreshing saved Cherax settings...")
    end
    return true
end

function startup.process_pending_settings_profile_refresh()
    if startup.s.pendingSettingsProfileRefresh ~= true then return end
    startup.s.pendingSettingsProfileRefresh = false
    local runDebug = startup.s.settingsProfilesDebugRequested == true
    startup.s.settingsProfilesDebugRequested = false
    local profiles = startup.refresh_settings_profiles(runDebug)
    local elapsed = startup.now() - (tonumber(startup.s.settingsProfilesRefreshQueuedAtMs or 0) or 0)
    startup.s.settingsProfilesRefreshQueuedAtMs = 0

    if startup.s.settingsProfilesRefreshToastPending == true then
        startup.s.settingsProfilesRefreshToastPending = false
        startup.toast("Saved settings refreshed: " .. tostring(#profiles) .. " profile" .. (#profiles == 1 and "" or "s") .. " found.", 3500)
    elseif startup.s.verboseStartupLogs then
        startup.log("Settings profile refresh complete | count=" .. tostring(#profiles) .. " | elapsedMs=" .. tostring(elapsed))
    end
end

function startup.settings_profile_exists(name)
    if tostring(name or "") == "" then return false end
    for _, profile in ipairs(startup.s.settingsProfiles or {}) do
        if startup.settings_profile_names_match(profile, name) then return true end
    end
    return false
end

function startup.select_settings_profile(name, saveNow)
    name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then return false end
    startup.s.settingsFile = name
    startup.s.settingsProfileSelectionConfirmed = true
    if saveNow and startup.s.initialized then startup.s.pendingSettingsSelectionSave = true end
    return true
end

function startup.process_pending_settings_selection_save()
    if startup.s.pendingSettingsSelectionSave ~= true then return end
    startup.s.pendingSettingsSelectionSave = false
    startup.save_config(false)
end

function startup.apply_settings_file(forceWhileOnline)
    local forceOnline = forceWhileOnline == true
    if not startup.s.autoLoadSettings and not forceOnline then
        startup.s.lastStatus = "Auto-Load Settings is OFF."
        return false
    end

    local onlineActive = startup.is_gta_online_session_ready and startup.is_gta_online_session_ready() == true
    if onlineActive and not forceOnline then
        startup.s.lastStatus = "Settings Safety: skipped automatic profile load because GTA Online is already active."
        startup.toast_quiet("Settings load skipped online to protect your character and Lua state.", 4500)
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("SETTINGS_LOAD_SKIPPED_ONLINE", "profile=" .. tostring(startup.s.settingsFile or ""))
        end
        return false
    end

    if onlineActive and forceOnline then
        startup.log_verbose("[Settings Safety] Manual online settings load requested.", "warning")
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("SETTINGS_LOAD_FORCED_ONLINE", "profile=" .. tostring(startup.s.settingsFile or ""))
        end
    end

    local selected = tostring(startup.s.settingsFile or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if selected == "" then
        startup.s.lastStatus = "No Cherax settings profile selected."
        return false
    end

    local settingsList = startup.settings_feature_list()
    local settingsIndex = startup.settings_profile_list_index(settingsList, selected)
    if settingsIndex ~= nil and FeatureMgr and FeatureMgr.SetFeatureListIndex then
        FeatureMgr.SetFeatureListIndex(startup.feature_hash.SETTINGS, settingsIndex)
    elseif #(startup.s.settingsProfiles or {}) > 0 and not startup.settings_profile_exists(selected) then
        startup.s.lastStatus = "Selected Cherax settings profile was not found: " .. selected
        startup.error("Could not find saved settings profile: " .. selected)
        return false
    end

    if not FeatureMgr or not FeatureMgr.LoadSettings then
        startup.error("Cherax LoadSettings is unavailable.")
        return false
    end
    local desiredNatHudState = startup.s.showNatTypeHud ~= false
    local desiredNatHudConfigured = startup.s.natHudUserConfigured == true
    local desiredRegionHudState = startup.s.showAdvertiseRegionHud == true
    local desiredRegionHudConfigured = startup.s.advertiseRegionHudUserConfigured == true
    local wasSyncing = startup.s.syncingFeatureStates == true
    startup.s.syncingFeatureStates = true
    local okCall, ok = direct_call(function() return FeatureMgr.LoadSettings(selected) end)
    startup.s.syncingFeatureStates = wasSyncing
    startup.s.showNatTypeHud = desiredNatHudState
    startup.s.natHudUserConfigured = desiredNatHudConfigured
    startup.s.showAdvertiseRegionHud = desiredRegionHudState
    startup.s.advertiseRegionHudUserConfigured = desiredRegionHudConfigured
    if okCall and ok ~= nil and ok ~= false then
        startup.s.lastStatus = "Loaded settings: " .. selected
        startup.toast_colored("Loaded settings: " .. selected, 3000, "success")
        startup.s.pendingNatHudRestore = true
        return true
    end
    if not okCall then
        startup.s.lastStatus = "Could not load settings safely: " .. selected
        startup.error("Could not load settings safely: " .. selected)
    else
        startup.error("Could not load settings: " .. selected)
    end
    return false
end

function startup.apply_settings_file_manual()
    return startup.apply_settings_file(true)
end

function startup.get_random_theme_file()
    local themes = startup.get_enabled_theme_files()
    if #themes <= 0 then
        startup.s.lastThemeStatus = "No startup themes enabled"
        return startup.s.themeFile or startup.s.lastRandomThemeFile or "Old_Original.json"
    end
    local seed = startup.now() + os.time() + math.floor(os.clock() * 100000)
    math.randomseed(seed)
    local selected = themes[math.random(1, #themes)] or themes[1]
    -- if possible, avoid picking the exact same theme twice in a row.
    if #themes > 1 and selected == startup.s.lastRandomThemeFile then
        for _ = 1, 6 do
            local retry = themes[math.random(1, #themes)] or selected
            if retry ~= startup.s.lastRandomThemeFile then
                selected = retry
                break
            end
        end
    end
    return selected
end

function startup.set_theme_file(themeFile, saveNow)
    startup.s.themeFile = tostring(themeFile or "Old_Original.json")
    startup.s.lastRandomThemeFile = startup.s.themeFile
    if saveNow and startup.s.initialized then
        startup.save_config(false)
    end
end

-- Manual theme buttons are rendered inside Cherax ClickGUI / ImGui callbacks.
-- Those callbacks must never yield or invoke a theme reload mid-frame. They only set
-- this request; Startup's main scripting worker performs the actual load safely.
startup.pendingThemeLoad = false
startup.pendingThemeLoadManual = false
startup.pendingThemeLoadReason = ""

function startup.queue_theme_load(manual_request, reason)
    startup.pendingThemeLoad = true
    startup.pendingThemeLoadManual = manual_request == true
    startup.pendingThemeLoadReason = tostring(reason or (manual_request == true and "manual request" or "automatic request"))
    startup.s.lastThemeStatus = "Theme load queued: " .. tostring(startup.s.themeFile or "Not selected")
    return true
end

function startup.apply_theme_file(manual_request)
    startup.refresh_theme_file_list()
    if not startup.s.autoLoadTheme and manual_request ~= true then
        startup.s.lastThemeStatus = "Auto-Load Theme OFF"
        return false
    end
    if startup.s.randomThemeOnStartup then
        startup.set_theme_file(startup.get_random_theme_file(), false)
    elseif not startup.s.themeFile or startup.s.themeFile == "" then
        startup.set_theme_file("Old_Original.json", false)
    end
    local themeFeature = FeatureMgr.GetFeature(startup.feature_hash.THEMES)
    if not themeFeature then
        startup.error("Themes feature not found.")
        startup.s.lastThemeStatus = "Themes feature not found"
        return false
    end
    local selectedTheme = nil
    local index = nil
    for _, candidate in ipairs(startup.get_theme_load_candidates(startup.s.themeFile)) do
        index = themeFeature:GetListIndexByString(candidate)
        if index ~= nil then
            selectedTheme = candidate
            break
        end
    end
    if index == nil or not selectedTheme then
        startup.error("Theme option not found: " .. tostring(startup.s.themeFile))
        startup.s.lastThemeStatus = "Theme not found: " .. tostring(startup.s.themeFile)
        return false
    end
    themeFeature:SetListIndexByString(selectedTheme)
    startup.s.themeFile = selectedTheme
    startup.yield(250)
    local loadThemeFeature = FeatureMgr.GetFeature(startup.feature_hash.LOAD_THEME)
    if loadThemeFeature then
        if loadThemeFeature.OnClick then
            loadThemeFeature:OnClick()
        elseif loadThemeFeature.TriggerCallback then
            loadThemeFeature:TriggerCallback()
        end
    else
        startup.error("Load Theme feature not found.")
        startup.s.lastThemeStatus = "Load Theme feature not found"
        return false
    end
    startup.s.lastThemeStatus = "Loaded theme: " .. startup.s.themeFile
    startup.save_config(false)
    startup.toast_quiet("Loaded theme: " .. startup.s.themeFile, 3000)
    return true
end

function startup.process_pending_theme_load()
    if startup.pendingThemeLoad ~= true then return end

    local manual_request = startup.pendingThemeLoadManual == true
    local reason = tostring(startup.pendingThemeLoadReason or "queued request")
    startup.pendingThemeLoad = false
    startup.pendingThemeLoadManual = false
    startup.pendingThemeLoadReason = ""

    local ok, result = direct_call(function()
        return startup.apply_theme_file(manual_request)
    end)
    if not ok then
        startup.s.lastThemeStatus = "Theme load failed: " .. tostring(result)
        startup.error("Queued theme load failed: " .. tostring(result))
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("THEME_LOAD_ERROR", "reason=" .. reason .. " | error=" .. tostring(result))
        end
        return false
    end

    if startup.support_log_event_quiet then
        startup.support_log_event_quiet(
            result == true and "THEME_LOAD_OK" or "THEME_LOAD_SKIPPED",
            "reason=" .. reason .. " | theme=" .. tostring(startup.s.themeFile or "") .. " | status=" .. tostring(startup.s.lastThemeStatus or "")
        )
    end
    return result == true
end

function startup.get_feature_list_safe(feature)
    if not feature or not feature.GetList then return nil end
    local list = feature:GetList()
    return type(list) == "table" and list or nil
end

function startup.list_contains_text(list, wanted)
    if type(list) ~= "table" then return false end
    local target = string.lower(tostring(wanted or ""))
    for _, value in ipairs(list) do
        if string.lower(tostring(value or "")) == target then
            return true
        end
    end
    return false
end

function startup.get_current_feature_list_string_safe(hash)
    local value = nil
    if FeatureMgr and FeatureMgr.GetCurrentFeatureListString then
    value = FeatureMgr.GetCurrentFeatureListString(hash)
    end
    if value ~= nil and tostring(value) ~= "" then
        return tostring(value)
    end
    local feature = FeatureMgr and FeatureMgr.GetFeature and FeatureMgr.GetFeature(hash) or nil
    if not feature then return nil end
    local list = startup.get_feature_list_safe(feature)
    local index = nil
    if feature.GetListIndex then index = feature:GetListIndex() end
    if type(list) == "table" and type(index) == "number" then
        return list[index + 1]
    end
    return nil
end

function startup.read_cherax_game_edition()
    local edition = startup.get_active_edition_info()
    startup.s.detectedCheraxGameEdition = edition
    return edition
end

function startup.parse_cherax_game_edition(edition)
    local normalized = startup.normalize_edition_code(edition)

    if normalized == "LE" then return "Legacy", false, true end
    if normalized == "EE" then return "Enhanced", false, true end
    if normalized == "LE BE" then return "Legacy", true, true end
    if normalized == "EE BE" then return "Enhanced", true, true end

    return "Unknown", nil, false
end

function startup.detect_session_route_fallback()
    local sessionFeature = FeatureMgr and FeatureMgr.GetFeature and FeatureMgr.GetFeature(startup.feature_hash.SESSION_TYPE) or nil
    local list = startup.get_feature_list_safe(sessionFeature)
    local current = startup.get_current_feature_list_string_safe(startup.feature_hash.SESSION_TYPE)

    if not sessionFeature then
        startup.s.detectedCheraxTier = "Unknown"
        startup.s.detectedSessionTypeConfidence = 0
        startup.s.detectedSessionTypeReason = "Cherax edition was not recognized and Session Type is unavailable; preserving the configured route"
        return "Unknown", startup.s.sessionType or "New Public Session"
    end

    local hasNewPublic = startup.list_contains_text(list, "New Public Session")
    local hasJoinPublic = startup.list_contains_text(list, "Join Public Session")
    if hasNewPublic and not hasJoinPublic then
        startup.s.detectedCheraxTier = "Standard / Premium (fallback)"
        startup.s.detectedSessionTypeConfidence = 85
        startup.s.detectedSessionTypeReason = "Edition was unrecognized; Session Type exposes New Public Session only"
        return startup.s.detectedCheraxTier, "New Public Session"
    end
    if hasJoinPublic and not hasNewPublic then
        startup.s.detectedCheraxTier = "Prime (fallback)"
        startup.s.detectedSessionTypeConfidence = 85
        startup.s.detectedSessionTypeReason = "Edition was unrecognized; Session Type exposes Join Public Session only"
        return startup.s.detectedCheraxTier, "Join Public Session"
    end
    if hasNewPublic and hasJoinPublic then
        startup.s.detectedCheraxTier = "Standard / Premium (safe fallback)"
        startup.s.detectedSessionTypeConfidence = 70
        startup.s.detectedSessionTypeReason = "Edition was unrecognized and both routes exist; using safe non-BattlEye routing"
        return startup.s.detectedCheraxTier, "New Public Session"
    end
    if current == "New Public Session" or current == "Join Public Session" then
        local tier = current == "Join Public Session" and "Prime (current route)" or "Standard / Premium (current route)"
        startup.s.detectedCheraxTier = tier
        startup.s.detectedSessionTypeConfidence = 55
        startup.s.detectedSessionTypeReason = "Edition was unrecognized; preserving the current public-session route"
        return tier, current
    end

    startup.s.detectedCheraxTier = "Standard / Premium fallback"
    startup.s.detectedSessionTypeConfidence = 40
    startup.s.detectedSessionTypeReason = "Edition and route were unrecognized; using New Public Session as the safe fallback"
    return startup.s.detectedCheraxTier, "New Public Session"
end

function startup.detect_cherax_session_tier()
    local edition = startup.read_cherax_game_edition()
    local gameFamily, battleyeEnabled, recognized = startup.parse_cherax_game_edition(edition)
    startup.s.detectedCheraxGameFamily = gameFamily
    startup.s.detectedBattleyeMode = battleyeEnabled == true and "ON" or (battleyeEnabled == false and "OFF" or "Unknown")

    if recognized then
        if battleyeEnabled then
            startup.s.detectedCheraxTier = "Prime"
            startup.s.detectedSessionTypeConfidence = 100
            if startup.s.primeHostSessionsEnabled ~= false then
                startup.s.detectedSessionTypeReason = "Active Cherax edition is " .. tostring(edition) .. "; Prime hosting is enabled, keeping New Public Session"
                return "Prime", "New Public Session"
            end
            startup.s.detectedSessionTypeReason = "Active Cherax edition is " .. tostring(edition) .. "; Prime hosting is disabled, using Join Public Session"
            return "Prime", "Join Public Session"
        end
        startup.s.detectedCheraxTier = "Standard / Premium"
        startup.s.detectedSessionTypeConfidence = 100
        startup.s.detectedSessionTypeReason = "Active Cherax edition is " .. tostring(edition) .. "; non-BattlEye routing uses New Public Session"
        return startup.s.detectedCheraxTier, "New Public Session"
    end

    return startup.detect_session_route_fallback()
end

function startup.resolve_session_type()
    if startup.s.cheraxHostFinderEnabled == true then
        local edition = startup.read_cherax_game_edition()
        local gameFamily, battleyeEnabled = startup.parse_cherax_game_edition(edition)
        startup.s.detectedCheraxGameFamily = gameFamily
        startup.s.detectedBattleyeMode = battleyeEnabled == true and "ON" or (battleyeEnabled == false and "OFF" or "Unknown")
        startup.s.detectedCheraxTier = startup.is_prime_active_edition() and "Prime" or "Standard / Premium"
        startup.s.detectedSessionTypeConfidence = 100
        startup.s.detectedSessionTypeReason = "Cherax Host Finder forces Join Public Session"
        startup.s.sessionType = "Join Public Session"
        return startup.s.sessionType
    end
    local mode = tostring(startup.s.sessionRoutingMode or "Automatic")
    if mode == "Prime" then
        local edition = startup.read_cherax_game_edition()
        local gameFamily, battleyeEnabled = startup.parse_cherax_game_edition(edition)
        startup.s.detectedCheraxGameFamily = gameFamily
        startup.s.detectedBattleyeMode = battleyeEnabled == true and "ON" or (battleyeEnabled == false and "OFF" or "Unknown")
        startup.s.detectedCheraxTier = "Prime (manual override)"
        startup.s.detectedSessionTypeConfidence = 100
        if startup.s.primeHostSessionsEnabled ~= false then
            startup.s.detectedSessionTypeReason = "Session Routing is manually forced to Prime; Prime hosting is enabled"
            startup.s.sessionType = "New Public Session"
        else
            startup.s.detectedSessionTypeReason = "Session Routing is manually forced to Prime; Prime hosting is disabled"
            startup.s.sessionType = "Join Public Session"
        end
    elseif mode == "Standard / Premium" then
        local edition = startup.read_cherax_game_edition()
        local gameFamily, battleyeEnabled = startup.parse_cherax_game_edition(edition)
        startup.s.detectedCheraxGameFamily = gameFamily
        startup.s.detectedBattleyeMode = battleyeEnabled == true and "ON" or (battleyeEnabled == false and "OFF" or "Unknown")
        startup.s.detectedCheraxTier = "Standard / Premium (manual override)"
        startup.s.detectedSessionTypeConfidence = 100
        startup.s.detectedSessionTypeReason = "Session Routing is manually forced to Standard / Premium"
        startup.s.sessionType = "New Public Session"
    else
        startup.s.sessionRoutingMode = "Automatic"
        local _, detectedType = startup.detect_cherax_session_tier()
        startup.s.sessionType = detectedType or "New Public Session"
    end
    return startup.s.sessionType
end

function startup.apply_session_type()
    if not startup.s.autoSelectSessionType then
        startup.toast("Auto-Select Session Type is OFF.", 2000)
        return false
    end
    local sessionFeature = FeatureMgr.GetFeature(startup.feature_hash.SESSION_TYPE)
    if not sessionFeature then
        startup.error("Session Type feature not found.")
        return false
    end
    local targetType = startup.resolve_session_type()
    local index = sessionFeature:GetListIndexByString(targetType)
    if index == nil then
        local list = startup.get_feature_list_safe(sessionFeature)
        if startup.s.cheraxHostFinderEnabled == true then
            if startup.list_contains_text(list, "Join Public Session") then
                targetType = "Join Public Session"
                index = sessionFeature:GetListIndexByString(targetType)
            end
        else
            if startup.list_contains_text(list, "New Public Session") then
                targetType = "New Public Session"
            elseif startup.list_contains_text(list, "Join Public Session") then
                targetType = "Join Public Session"
            end
            index = sessionFeature:GetListIndexByString(targetType)
        end
    end
    if index == nil then
        local current = startup.get_current_feature_list_string_safe(startup.feature_hash.SESSION_TYPE)
        if startup.s.cheraxHostFinderEnabled == true and tostring(current or "") ~= "Join Public Session" then
            startup.s.lastSessionFlowStatus = "Lobby Finder requires Join Public Session, but Cherax did not expose it."
            startup.error(startup.s.lastSessionFlowStatus)
            return false
        end
        if current and tostring(current) ~= "" then
            startup.s.sessionType = tostring(current)
            startup.s.detectedSessionTypeReason = "Requested route unavailable; preserved current Session Type: " .. tostring(current)
            startup.s.lastSessionFlowStatus = startup.s.detectedSessionTypeReason
            return true
        end
        startup.s.lastSessionFlowStatus = "Session Type option unavailable on this Cherax layout: " .. tostring(targetType)
        return false
    end
    startup.s.sessionType = targetType
    sessionFeature:SetListIndexByString(targetType)
    if ClickGUI and ClickTab then
        ClickGUI.SetActiveMenuTab(ClickTab.Session)
    end
    startup.toast_quiet("Session Type selected: " .. tostring(targetType), 3500)
    return true
end

function startup.start_session(skipSessionTypeApply)
    if startup.regionProductionHidden ~= true and startup.regionExperimentLock == true and startup.regionExperimentInternalStart ~= true then
        startup.s.lastSessionFlowStatus = "Session start deferred while a Legacy Region experiment is running."
        if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_REQUEST_SESSION_DEFERRED", "source=start_session") end
        return false
    end
    if skipSessionTypeApply ~= true and not startup.apply_session_type() then return false end
    return startup.click_start_session_feature()
end

function startup.run_startup_online_launch()
    if startup.s.startupOnlineAttempted then
        startup.s.lastOnlineStartStatus = "Skipped: already attempted this startup"
        return
    end
    if not startup.s.autoStartOnlineFromSingleplayer then
        startup.s.lastOnlineStartStatus = "Auto Start Online OFF"
        return
    end
    startup.s.startupOnlineAttempted = true
    Script.QueueJob(function()
        local targetType = startup.resolve_session_type()
        startup.s.lastOnlineStartStatus = "Waiting 1 minute before starting " .. tostring(targetType)
        startup.toast_quiet("Auto Start Online is ON. Waiting 1 minute before starting " .. tostring(targetType) .. ".", 5000)
        startup.yield(startup.s.autoStartOnlineDelayMs)
        while startup.regionExperimentLock == true or startup.regionRescanJobQueued == true do
            startup.s.lastOnlineStartStatus = "Waiting for the Legacy Region experiment to finish"
            startup.yield(500)
        end
        if startup.regionExperimentSessionStarted == true then
            startup.s.lastOnlineStartStatus = "Skipped: a Region experiment already started a controlled session"
            return
        end
        targetType = startup.resolve_session_type()
        startup.s.lastOnlineStartStatus = "Applying " .. tostring(targetType)
        startup.apply_session_type()
        startup.yield(1000)
        startup.s.lastOnlineStartStatus = "Starting " .. tostring(targetType)
        startup.toast_quiet("Starting " .. tostring(targetType) .. " from startup flow.", 4000)
        startup.start_session(true)
    end)
end

