-- self diagnostics alpha - Build 185
-- note: one-button, read-only account/network/matchmaking diagnostic. It never
-- writes GTA stats. It temporarily visits public sessions, then restores the
-- user's original Startup choices and returns Standard/Premium users to hosting.
-- ===============================================================================

startup.self_diag_dir = startup.diagnostics_dir .. "\\SelfDiagnostics"
startup.SelfDiagHistoryFile = startup.self_diag_dir .. "\\self_diagnostics_history.csv"
startup.self_diag = startup.self_diag or {}
local sd = startup.self_diag
sd.active = sd.active == true
sd.popupOpen = sd.popupOpen == true
sd.phase = tostring(sd.phase or "Idle")
sd.status = tostring(sd.status or "Ready")
sd.serial = tonumber(sd.serial or 0) or 0
sd.hopTarget = tonumber(sd.hopTarget or 3) or 3
sd.hopWindowMs = tonumber(sd.hopWindowMs or 240000) or 240000
sd.hostWindowMs = tonumber(sd.hostWindowMs or 600000) or 600000
sd.currentHop = tonumber(sd.currentHop or 0) or 0
sd.hops = sd.hops or {}
sd.account = sd.account or {}
sd.network = sd.network or {}
sd.findings = sd.findings or {}
sd.saved = sd.saved or {}
sd.startedAtMs = tonumber(sd.startedAtMs or 0) or 0
sd.startedAtEpoch = tonumber(sd.startedAtEpoch or 0) or 0
sd.runId = tostring(sd.runId or "")
sd.latestReportPath = tostring(sd.latestReportPath or "")
sd.latestSnapshotPath = tostring(sd.latestSnapshotPath or "")
sd.historyPath = tostring(sd.historyPath or startup.SelfDiagHistoryFile)
sd.hostObservation = sd.hostObservation or nil
sd.nodeState = sd.nodeState or {}
sd.workerQueued = sd.workerQueued == true
sd.lastSessionMarker = tonumber(sd.lastSessionMarker or 0) or 0
sd.pendingSessionSerial = tonumber(sd.pendingSessionSerial or 0) or 0

function startup.self_diag.ensure_dir()
    startup.ensure_save_dir()
    if FileMgr and FileMgr.CreateDir then direct_call(function() FileMgr.CreateDir(startup.self_diag_dir) end) end
end

function startup.self_diag.log(eventName, detail)
    eventName=tostring(eventName or "EVENT")
    -- Build 291: BUILDxxx_OVERRIDES_READY banners are static startup breadcrumbs and
    -- were dominating normal Cherax logs. Keep them only in explicit verbose mode.
    if eventName:find("OVERRIDES_READY",1,true) and not (startup.s and startup.s.verboseLogs==true) then return end
    local line = "[SelfDiag] " .. eventName .. " | " .. tostring(detail or "")
    startup.log(line)
    if startup.support_log_event_quiet then startup.support_log_event_quiet("SELF_DIAG_" .. eventName, tostring(detail or "")) end
end

function startup.self_diag.format_ms(ms)
    ms = math.max(0, tonumber(ms or 0) or 0)
    local total = math.floor(ms / 1000)
    return string.format("%02d:%02d", math.floor(total / 60), total % 60)
end

function startup.self_diag.safe_filename(value)
    local s = tostring(value or "UNKNOWN"):gsub('[\\/:*?"<>|]', "_"):gsub("%s+", "_"):gsub("[^%w%._%-]", "_")
    return s ~= "" and s or "UNKNOWN"
end

function startup.self_diag.append(path, line)
    local f = io and io.open and io.open(tostring(path or ""), "a") or nil
    if not f then return false end
    f:write(tostring(line or ""), "\n")
    f:close()
    return true
end

function startup.self_diag.csv(value)
    local s = tostring(value == nil and "" or value):gsub('"', '""')
    return '"' .. s .. '"'
end

function startup.self_diag.joaat(name)
    if Utils and Utils.sJoaat then
        local ok, value = direct_call(Utils.sJoaat, tostring(name or ""))
        if ok and value ~= nil then return value end
    end
    if Utils and Utils.Joaat then
        local ok, value = direct_call(Utils.Joaat, tostring(name or ""))
        if ok and value ~= nil then return value end
    end
    return nil
end

function startup.self_diag.read_stat(realName, expected)
    if not Stats then return false, nil, "Stats API unavailable" end
    local hash = startup.self_diag.joaat(realName)
    if hash == nil then return false, nil, "hash unavailable" end
    expected = tostring(expected or "int"):lower()
    local function call(method)
        if type(method) ~= "function" then return false, nil end
        local okCall, okRead, value = direct_call(method, hash)
        if okCall and okRead == true then return true, value end
        return false, nil
    end
    local ok, value
    if expected == "float" then
        ok, value = call(Stats.GetFloat); if ok then return true, tonumber(value) or 0, "float" end
        ok, value = call(Stats.GetInt); if ok then return true, tonumber(value) or 0, "int_fallback" end
    elseif expected == "bool" then
        ok, value = call(Stats.GetBool); if ok then return true, value == true or tonumber(value or 0) ~= 0, "bool" end
        ok, value = call(Stats.GetInt); if ok then return true, tonumber(value or 0) ~= 0, "int_fallback" end
    else
        ok, value = call(Stats.GetInt); if ok then return true, tonumber(value) or 0, "int" end
        ok, value = call(Stats.GetFloat); if ok then return true, tonumber(value) or 0, "float_fallback" end
    end
    return false, nil, "unreadable"
end

function startup.self_diag.detect_slot()
    local ok, value = startup.self_diag.read_stat("MPPLY_LAST_MP_CHAR", "int")
    if ok and (tonumber(value) == 0 or tonumber(value) == 1) then return tonumber(value) end
    return 0
end

function startup.self_diag.real_stat_name(key, slot)
    key = tostring(key or "")
    if key:sub(1, 4) == "MPX_" then return "MP" .. tostring(slot or 0) .. "_" .. key:sub(5) end
    return key
end

function startup.self_diag.near_repair(value, repair)
    if type(value) ~= "number" or type(repair) ~= "number" then return value == repair end
    if value == repair then return true end
    local tolerance = math.max(5.0, math.abs(repair) * 0.02)
    return math.abs(value - repair) <= tolerance
end

function startup.self_diag.add_finding(severity, code, text, weight)
    sd.findings[#sd.findings + 1] = {
        severity = tostring(severity or "INFO"), code = tostring(code or ""), text = tostring(text or ""), weight = tonumber(weight or 0) or 0
    }
end

function startup.self_diag.value(key)
    return sd.account and sd.account.values and sd.account.values[key] or nil
end

function startup.self_diag.analyze_account()
    local a = sd.account or {}
    sd.findings = {}
    local score = 0
    local function issue(sev, code, msg, weight)
        weight = tonumber(weight or 0) or 0
        score = score + weight
        startup.self_diag.add_finding(sev, code, msg, weight)
    end
    local hours = tonumber(a.playHours or 0) or 0
    local kills = tonumber(startup.self_diag.value("MPX_KILLS") or 0) or 0
    local pvp = tonumber(startup.self_diag.value("MPX_KILLS_PLAYERS") or 0) or 0
    local pvpProfile = tonumber(startup.self_diag.value("MPPLY_KILLS_PLAYERS") or 0) or 0
    local pvpDeaths = tonumber(startup.self_diag.value("MPX_DEATHS_PLAYER") or 0) or 0
    local pvpDeathsProfile = tonumber(startup.self_diag.value("MPPLY_DEATHS_PLAYER") or 0) or 0
    local jobsEarned = tonumber(startup.self_diag.value("MPX_MONEY_EARN_JOBS") or 0) or 0
    local races = (tonumber(startup.self_diag.value("MPX_RACES_WON") or 0) or 0) + (tonumber(startup.self_diag.value("MPX_RACES_LOST") or 0) or 0)

    if hours > 0 then
        local kph = kills / hours
        local pvph = pvp / hours
        local mph = jobsEarned / hours
        a.killsPerHour, a.pvpKillsPerHour, a.jobMoneyPerHour = kph, pvph, mph
        if kph > 500 then issue("SEVERE", "KILLS_PER_HOUR", string.format("Total kills imply %.1f kills/hour across all recorded playtime.", kph), 25)
        elseif kph > 200 then issue("HIGH", "KILLS_PER_HOUR", string.format("Total kills imply %.1f kills/hour across all recorded playtime.", kph), 14) end
        if pvph > 100 then issue("SEVERE", "PVP_PER_HOUR", string.format("Player kills imply %.1f PvP kills/hour across all recorded playtime.", pvph), 25)
        elseif pvph > 50 then issue("HIGH", "PVP_PER_HOUR", string.format("Player kills imply %.1f PvP kills/hour across all recorded playtime.", pvph), 14) end
        if mph > 50000000 then issue("SEVERE", "JOB_MONEY_RATE", string.format("Job earnings imply $%.1fM/hour across all recorded playtime.", mph / 1000000), 20)
        elseif mph > 15000000 then issue("HIGH", "JOB_MONEY_RATE", string.format("Job earnings imply $%.1fM/hour across all recorded playtime.", mph / 1000000), 12) end
        if hours < 10 and races > 250 then issue("HIGH", "RACES_VS_AGE", "Hundreds of completed races are recorded on an account with under 10 hours of playtime.", 16) end
        if hours < 10 and kills > 10000 then issue("SEVERE", "KILLS_VS_AGE", "More than 10,000 total kills are recorded on an account with under 10 hours of playtime.", 24) end
        if hours < 10 and jobsEarned > 100000000 then issue("HIGH", "MONEY_VS_AGE", "More than $100M in job earnings are recorded on an account with under 10 hours of playtime.", 16) end
    end

    if math.max(pvp, pvpProfile) >= 100 and math.min(pvp, pvpProfile) == 0 then
        issue("MEDIUM", "PVP_SCOPE_MISMATCH", "Character/player-kill scope and MPPLY profile scope strongly disagree.", 8)
    end
    if math.max(pvpDeaths, pvpDeathsProfile) >= 100 and math.min(pvpDeaths, pvpDeathsProfile) == 0 then
        issue("MEDIUM", "PVP_DEATH_SCOPE_MISMATCH", "Character/player-death scope and MPPLY profile scope strongly disagree.", 8)
    end

    local weaponPrefixes = {}
    for _, row in ipairs(startup.self_diag_repair_templates.Weapons or {}) do
        local p = tostring(row.key):match("^(MPX_.+)_SHOTS$")
        if p then weaponPrefixes[p] = true end
    end
    local weaponViolations = 0
    for prefix in pairs(weaponPrefixes) do
        local shots = tonumber(startup.self_diag.value(prefix .. "_SHOTS"))
        local hits = tonumber(startup.self_diag.value(prefix .. "_HITS"))
        local killsW = tonumber(startup.self_diag.value(prefix .. "_KILLS"))
        local heads = tonumber(startup.self_diag.value(prefix .. "_HEADSHOTS"))
        local enemies = tonumber(startup.self_diag.value(prefix .. "_ENEMY_KILLS"))
        if shots and hits and hits > shots * 1.05 + 5 then weaponViolations = weaponViolations + 1 end
        if killsW and heads and heads > killsW * 1.05 + 3 then weaponViolations = weaponViolations + 1 end
        if killsW and enemies and enemies > killsW * 1.05 + 3 then weaponViolations = weaponViolations + 1 end
    end
    a.weaponRelationshipViolations = weaponViolations
    if weaponViolations >= 4 then issue("HIGH", "WEAPON_RELATIONSHIPS", tostring(weaponViolations) .. " readable weapon histories violate basic shots/hits/kills relationships.", 16)
    elseif weaponViolations > 0 then issue("MEDIUM", "WEAPON_RELATIONSHIPS", tostring(weaponViolations) .. " readable weapon histories violate basic shots/hits/kills relationships.", 6) end

    local businessPairs = {
        {"MPX_LIFETIME_BUY_COMPLETE","MPX_LIFETIME_BUY_UNDERTAKEN"},
        {"MPX_LIFETIME_SELL_COMPLETE","MPX_LIFETIME_SELL_UNDERTAKEN"},
        {"MPX_LFETIME_HANGAR_BUY_COMPLET","MPX_LFETIME_HANGAR_BUY_UNDETAK"},
        {"MPX_LFETIME_HANGAR_SEL_COMPLET","MPX_LFETIME_HANGAR_SEL_UNDETAK"},
        {"MPX_LFETIME_IE_EXPORT_COMPLETED","MPX_LFETIME_IE_EXPORT_STARTED"},
        {"MPX_LIFETIME_BIKER_BUY_COMPLET","MPX_LIFETIME_BIKER_BUY_UNDERTA"},
        {"MPX_LIFETIME_BIKER_SELL_COMPLET","MPX_LIFETIME_BIKER_SELL_UNDERTA"},
    }
    for i=1,6 do
        businessPairs[#businessPairs+1] = {"MPX_LFETIME_BIKER_BUY_COMPLET"..i,"MPX_LFETIME_BIKER_BUY_UNDERTA"..i}
        businessPairs[#businessPairs+1] = {"MPX_LFETIME_BIKER_SELL_COMPLET"..i,"MPX_LFETIME_BIKER_SELL_UNDERTA"..i}
    end
    local businessViolations = 0
    for _, pair in ipairs(businessPairs) do
        local complete = tonumber(startup.self_diag.value(pair[1]))
        local started = tonumber(startup.self_diag.value(pair[2]))
        if complete and started and complete > started then businessViolations = businessViolations + 1 end
    end
    a.businessRelationshipViolations = businessViolations
    if businessViolations >= 3 then issue("HIGH", "BUSINESS_RELATIONSHIPS", tostring(businessViolations) .. " business completion counters exceed their undertaken/started counters.", 15)
    elseif businessViolations > 0 then issue("MEDIUM", "BUSINESS_RELATIONSHIPS", tostring(businessViolations) .. " business completion counter(s) exceed undertaken/started counters.", 6) end

    local extras = a.extra or {}
    local suicides = tonumber(extras.suicides)
    if hours > 0 and suicides and suicides >= 500 then
        local suicidesPerHour = suicides / hours
        a.suicidesPerHour = suicidesPerHour
        if suicidesPerHour > 50 then
            issue("SEVERE", "SUICIDES_PER_HOUR", string.format("Recorded suicides imply %.1f suicides/hour across all playtime.", suicidesPerHour), 20)
        elseif suicidesPerHour > 20 then
            issue("HIGH", "SUICIDES_PER_HOUR", string.format("Recorded suicides imply %.1f suicides/hour across all playtime.", suicidesPerHour), 12)
        elseif suicidesPerHour > 8 then
            issue("MEDIUM", "SUICIDES_PER_HOUR", string.format("Recorded suicides imply %.1f suicides/hour across all playtime.", suicidesPerHour), 6)
        end
    end
    if extras.nativeBadSport == true then
        issue("HIGH", "BAD_SPORT_STATE", "Rockstar native reports the local player in Bad Sport state; this can place the account in a different matchmaking pool.", 0)
    end
    if extras.nativeCheater == true then
        issue("HIGH", "CHEATER_STATE", "Rockstar native reports the local player in Cheater state. Record this separately from stat-modification scoring.", 0)
    end

    local coherencePenalty = math.min(100, weaponViolations * 6 + businessViolations * 8
        + ((math.max(pvp, pvpProfile) >= 100 and math.min(pvp, pvpProfile) == 0) and 15 or 0)
        + ((math.max(pvpDeaths, pvpDeathsProfile) >= 100 and math.min(pvpDeaths, pvpDeathsProfile) == 0) and 15 or 0))
    a.organicPlausibility = math.max(0, 100 - math.min(100, score))
    a.profileCoherence = math.max(0, 100 - coherencePenalty)

    if tonumber(a.repairNearPct or 0) >= 60 then
        a.classification = "Known repaired-profile signature"
        a.anomalyScore = math.min(100, score)
        startup.self_diag.add_finding("INFO", "KNOWN_REPAIR", string.format("%.1f%% of readable repair-template fields still match or remain within 2%% of the known 503-stat repair profile.", tonumber(a.repairNearPct or 0)), 0)
    elseif score >= 55 then
        a.classification = "Strongly abnormal / likely modified"
        a.anomalyScore = math.min(100, score)
    elseif score >= 30 then
        a.classification = "Abnormal / modification indicators present"
        a.anomalyScore = math.min(100, score)
    elseif hours > 0 and hours < 25 then
        a.classification = "Young / sparse profile; no strong abnormality"
        a.anomalyScore = math.min(100, score)
    else
        a.classification = "No strong modification signature from readable fields"
        a.anomalyScore = math.min(100, score)
    end
    sd.account = a
end

function startup.self_diag.scan_account()
    sd.phase = "ACCOUNT_SCAN"
    sd.status = "Scanning 503 account-history stats (read-only)..."
    startup.self_diag.log("ACCOUNT_SCAN_BEGIN", "503 known repair fields")
    local slot = startup.self_diag.detect_slot()
    local result = { values = {}, sources = {}, groups = {}, slot = slot, total = 0, readable = 0, failed = 0, exact = 0, near = 0, nonzero = 0 }
    local processed = 0
    for _, group in ipairs({"Profile","Weapons","Businesses"}) do
        local g = { total=0, readable=0, failed=0, exact=0, near=0, nonzero=0 }
        result.groups[group] = g
        for _, row in ipairs(startup.self_diag_repair_templates[group] or {}) do
            result.total, g.total = result.total + 1, g.total + 1
            local realName = startup.self_diag.real_stat_name(row.key, slot)
            local ok, value, source = startup.self_diag.read_stat(realName, row.expected)
            if ok and tostring(row.expected) == "int" and tonumber(value) and tonumber(value) < 0 and tonumber(row.repair) and tonumber(row.repair) >= 0 then
                -- GTA counters can expose unsigned 32-bit values through a signed int read.
                -- Normalize the bit-equivalent value so e.g. 4,200,000,000 ms does not
                -- appear as a negative counter and falsely miss the known repair profile.
                value = tonumber(value) + 4294967296
                source = tostring(source or "int") .. "_u32_normalized"
            end
            if ok then
                result.readable, g.readable = result.readable + 1, g.readable + 1
                result.values[row.key] = value
                result.sources[row.key] = source
                if tonumber(value) ~= 0 then result.nonzero, g.nonzero = result.nonzero + 1, g.nonzero + 1 end
                if value == row.repair then result.exact, g.exact = result.exact + 1, g.exact + 1 end
                if startup.self_diag.near_repair(tonumber(value), tonumber(row.repair)) then result.near, g.near = result.near + 1, g.near + 1 end
            else
                result.failed, g.failed = result.failed + 1, g.failed + 1
            end
            processed = processed + 1
            if processed % 12 == 0 then
                sd.status = "Account scan " .. tostring(processed) .. "/503..."
                startup.yield(0)
            end
        end
    end

    local extras = {
        rank = {"MP"..slot.."_CHAR_RANK_FM","int"},
        xp = {"MP"..slot.."_CHAR_XP_FM","int"},
        globalXp = {"MPPLY_GLOBALXP","int"},
        suicides = {"MP"..slot.."_SUICIDES","int"},
        mentalState = {"MP"..slot.."_PLAYER_MENTAL_STATE","float"},
        reportStrength = {"MPPLY_REPORT_STRENGTH","int"},
        commendStrength = {"MPPLY_COMMEND_STRENGTH","int"},
        gameExploits = {"MPPLY_GAME_EXPLOITS","int"},
    }
    result.extra = {}
    for label, spec in pairs(extras) do
        local ok, value = startup.self_diag.read_stat(spec[1], spec[2])
        if ok then result.extra[label] = value end
    end
    if Natives and Natives.InvokeBool then
        local okBad, bad = direct_call(Natives.InvokeBool, 0x19D8DA0E5A68045A)
        local okCheat, cheat = direct_call(Natives.InvokeBool, 0x655B91F1495A9090)
        if okBad then result.extra.nativeBadSport = bad == true end
        if okCheat then result.extra.nativeCheater = cheat == true end
    end

    local playing = tonumber(result.values.MP_PLAYING_TIME or result.values.MPX_TOTAL_PLAYING_TIME or 0) or 0
    result.playHours = playing / 3600000.0
    result.repairExactPct = result.readable > 0 and (result.exact / result.readable * 100) or 0
    result.repairNearPct = result.readable > 0 and (result.near / result.readable * 100) or 0
    result.completenessPct = result.readable > 0 and (result.nonzero / result.readable * 100) or 0
    sd.account = result
    startup.self_diag.analyze_account()
    startup.self_diag.log("ACCOUNT_SCAN_END", "readable="..result.readable.." failed="..result.failed.." nearRepair="..string.format("%.1f",result.repairNearPct).." class="..tostring(sd.account.classification))
    return result
end

function startup.self_diag.write_account_snapshot()
    startup.self_diag.ensure_dir()
    if not sd.account or not sd.account.values then return false end
    local runId = sd.runId ~= "" and sd.runId or ("ACCOUNT_" .. os.date("%Y_%m_%d_%H%M%S"))
    local path = startup.self_diag_dir .. "\\" .. runId .. "_Account_503_Diff.csv"
    local f = io.open(path, "w")
    if not f then return false end
    f:write("group,template_key,real_stat_name,expected_type,read_status,current_value,repair_reference,exact_match,near_match_2pct,read_source\n")
    local slot = tonumber(sd.account.slot or 0) or 0
    for _, group in ipairs({"Profile","Weapons","Businesses"}) do
        for _, row in ipairs(startup.self_diag_repair_templates[group] or {}) do
            local current = sd.account.values[row.key]
            local readable = current ~= nil
            local exact = readable and current == row.repair or false
            local near = readable and startup.self_diag.near_repair(tonumber(current), tonumber(row.repair)) or false
            local vals = {
                group, row.key, startup.self_diag.real_stat_name(row.key, slot), row.expected,
                readable and "READABLE" or "UNREADABLE", readable and current or "", row.repair,
                exact, near, readable and tostring(sd.account.sources[row.key] or "") or ""
            }
            for i,v in ipairs(vals) do vals[i] = startup.self_diag.csv(v) end
            f:write(table.concat(vals, ","), "\n")
        end
    end
    f:close()
    sd.latestSnapshotPath = path
    startup.s.selfDiagLastSnapshotPath = path
    startup.self_diag.log("ACCOUNT_SNAPSHOT", path)
    return true
end

function startup.self_diag.local_player_id()
    local ids = startup.get_local_player_id_candidates and startup.get_local_player_id_candidates() or {}
    return tonumber(ids[1])
end

function startup.self_diag.is_local_id(playerId)
    local id = tonumber(playerId)
    for _, localId in ipairs(startup.get_local_player_id_candidates and startup.get_local_player_id_candidates() or {}) do
        if id ~= nil and id == tonumber(localId) then return true end
    end
    return false
end

function startup.self_diag.net_type_name(playerId)
    local raw = nil
    if Players and Players.GetNetAddress then
        local ok, address = direct_call(Players.GetNetAddress, playerId)
        if ok and address then
            local okType, value = direct_call(function() return address.Type end)
            if okType then raw = value end
        end
    end
    local function compare_enum(tbl, name)
        return type(tbl) == "table" and tbl[name] ~= nil and raw == tbl[name]
    end
    if compare_enum(NetAddressType, "DIRECT") or compare_enum(eNetAddressType, "DIRECT") then return "DIRECT" end
    if compare_enum(NetAddressType, "PEER_RELAY") or compare_enum(eNetAddressType, "PEER_RELAY") then return "PEER_RELAY" end
    if compare_enum(NetAddressType, "RELAY_SERVER") or compare_enum(eNetAddressType, "RELAY_SERVER") then return "RELAY_SERVER" end
    if compare_enum(NetAddressType, "INVALID") or compare_enum(eNetAddressType, "INVALID") then return "INVALID" end
    local txt = tostring(raw or ""):upper()
    if txt:find("PEER_RELAY",1,true) then return "PEER_RELAY" end
    if txt:find("RELAY_SERVER",1,true) then return "RELAY_SERVER" end
    if txt:find("DIRECT",1,true) then return "DIRECT" end
    if Players and Players.GetIPString then
        local ok, ipText = direct_call(Players.GetIPString, playerId)
        local safe = ok and tostring(ipText or ""):upper() or ""
        if safe:find("PEER_RELAY",1,true) then return "PEER_RELAY" end
        if safe:find("RELAY_SERVER",1,true) or safe:find("RELAY",1,true) then return "RELAY_SERVER" end
        if safe:find("DIRECT",1,true) then return "DIRECT" end
    end
    return raw ~= nil and ("TYPE_" .. tostring(raw)) or "UNKNOWN"
end

function startup.self_diag.public_ip_metadata()
    local meta = { country="Unknown", countryCode="", region="", city="", isp="", asn="", provider="", vpn="Unknown", proxy="Unknown" }
    if not Players or not Players.GetIPInfo then return meta end
    local info = nil
    for _, candidate in ipairs(startup.get_local_player_id_candidates and startup.get_local_player_id_candidates() or {}) do
        local id = tonumber(candidate)
        if id ~= nil then
            local ok, value = direct_call(Players.GetIPInfo, id)
            if ok and type(value) == "table" then info = value; break end
        end
    end
    if type(info) ~= "table" then return meta end
    local function pick(...)
        for i=1,select("#", ...) do
            local key = select(i, ...)
            local value = info[key]
            if value ~= nil and tostring(value) ~= "" then return tostring(value) end
        end
        return ""
    end
    meta.country = pick("country","countryName","country_name"); if meta.country == "" then meta.country="Unknown" end
    meta.countryCode = pick("countryCode","country_code","cc")
    meta.region = pick("region","regionName","region_name","state")
    meta.city = pick("city")
    meta.isp = pick("isp","ISP","org","organization")
    meta.asn = pick("asn","ASN","as","asNumber","as_number")
    meta.provider = pick("provider","network","carrier")
    local vpn = pick("vpn","isVpn","is_vpn"); if vpn ~= "" then meta.vpn = vpn end
    local proxy = pick("proxy","isProxy","is_proxy"); if proxy ~= "" then meta.proxy = proxy end
    return meta
end

function startup.self_diag.capture_preflight()
    local n = {}
    n.nat = tostring(startup.get_local_nat_type and startup.get_local_nat_type() or "Unknown")
    n.ip = startup.self_diag.public_ip_metadata()
    local meta = startup.get_support_runtime_metadata and startup.get_support_runtime_metadata() or {}
    n.gtaEdition = tostring(meta.gtaEdition or startup.s.detectedCheraxGameEdition or "Unknown")
    n.cheraxEdition = tostring(meta.cheraxEdition or startup.s.detectedCheraxTier or "Unknown")
    n.cheraxVersion = tostring(meta.cheraxVersion or "Unknown")
    n.sessionType = tostring(startup.s.sessionType or "Unknown")
    local hName, hId = "Unknown", -1
    if startup.get_session_host_name then
        local okHost, nameValue, idValue = direct_call(startup.get_session_host_name)
        if okHost then hName, hId = nameValue or "Unknown", tonumber(idValue or -1) or -1 end
    end
    n.hostName, n.hostId = tostring(hName or "Unknown"), tonumber(hId or -1) or -1
    n.isSessionHost = startup.self_diag.is_local_id(n.hostId)
    n.cgnat = "Unknown - Cherax cannot compare router WAN IPv4 with Internet-observed IPv4"
    local providerText = (tostring(n.ip.isp or "") .. " " .. tostring(n.ip.provider or "")):lower()
    if providerText:find("mobile",1,true) or providerText:find("wireless",1,true) or providerText:find("cellular",1,true) or providerText:find("satellite",1,true)
        or providerText:find("starlink",1,true) or providerText:find("t%-mobile") or providerText:find("lte",1,true) or providerText:find("5g",1,true) then
        n.sharedAddressRisk = "Elevated heuristic - mobile/fixed-wireless/satellite provider wording detected"
    else
        n.sharedAddressRisk = providerText:gsub("%s+","") ~= "" and "Unknown / no strong provider-type signal" or "Unknown - ISP/provider metadata unavailable"
    end
    sd.network = n
    startup.self_diag.log("PREFLIGHT", "nat="..n.nat.." country="..tostring(n.ip.country).." city="..tostring(n.ip.city).." isp="..tostring(n.ip.isp).." host="..tostring(n.isSessionHost))
    return n
end

function startup.self_diag.snapshot_user_settings()
    sd.saved = {
        sessionRoutingMode = startup.s.sessionRoutingMode,
        sessionType = startup.s.sessionType,
        autoAdvertiseSession = startup.s.autoAdvertiseSession == true,
        oldStartupAdvertiseEnabled = startup.s.oldStartupAdvertiseEnabled == true,
        superAdvertiseEnabled = startup.s.superAdvertiseEnabled == true,
        cheraxHostFinderEnabled = startup.s.cheraxHostFinderEnabled == true,
        startupPresenceFinderEnabled = startup.s.startupPresenceFinderEnabled == true,
        primeMinimumPlayersEnabled = startup.s.primeMinimumPlayersEnabled == true,
        autoSelectSessionType = startup.s.autoSelectSessionType ~= false,
    }
end

function startup.self_diag.suspend_normal_automation()
    startup.s.cheraxHostFinderEnabled = false
    startup.s.startupPresenceFinderEnabled = false
    startup.s.primeMinimumPlayersEnabled = false
    startup.lobby_filter.cancel("Self Diagnostics owns session routing")
    startup.s.advertiseFlowSerial = (tonumber(startup.s.advertiseFlowSerial or 0) or 0) + 1
    startup.s.oldStartupAdvertiseSerial = (tonumber(startup.s.oldStartupAdvertiseSerial or 0) or 0) + 1
    startup.s.superAdvertiseSerial = (tonumber(startup.s.superAdvertiseSerial or 0) or 0) + 1
    startup.s.advertiseRunning = false
    startup.s.oldStartupAdvertiseRunning = false
    startup.s.superAdvertiseRunning = false
    startup.s.advertiseSmartActive = false
    startup.set_advertise_session(false, true)
end

function startup.self_diag.restore_user_settings(preserveActiveSessionType)
    local s = sd.saved or {}
    local activeSessionType = startup.s.sessionType
    startup.s.sessionRoutingMode = s.sessionRoutingMode or startup.s.sessionRoutingMode
    startup.s.sessionType = preserveActiveSessionType == true and activeSessionType or (s.sessionType or startup.s.sessionType)
    startup.s.autoAdvertiseSession = s.autoAdvertiseSession == true
    startup.s.oldStartupAdvertiseEnabled = s.oldStartupAdvertiseEnabled == true
    startup.s.superAdvertiseEnabled = s.superAdvertiseEnabled == true
    startup.s.cheraxHostFinderEnabled = s.cheraxHostFinderEnabled == true
    startup.s.startupPresenceFinderEnabled = s.startupPresenceFinderEnabled == true
    startup.s.primeMinimumPlayersEnabled = s.primeMinimumPlayersEnabled == true
    startup.s.autoSelectSessionType = s.autoSelectSessionType ~= false
    startup.set_feature_bool_silently(startup.h.AutoAdvertiseSession, startup.s.autoAdvertiseSession)
    startup.set_feature_bool_silently(startup.h.OldStartupAdvertise, startup.s.oldStartupAdvertiseEnabled)
    startup.set_feature_bool_silently(startup.h.SuperAdvertise, startup.s.superAdvertiseEnabled)
    startup.set_feature_bool_silently(startup.h.FindCheraxHostLobbies, startup.s.cheraxHostFinderEnabled)
    startup.set_feature_bool_silently(startup.h.StartupPresenceSessionFinder, startup.s.startupPresenceFinderEnabled)
    startup.set_feature_bool_silently(startup.h.PrimeMinimumPlayersEnabled, startup.s.primeMinimumPlayersEnabled)
end

function startup.self_diag.set_session_type_exact(label)
    -- Build 185: use Startup's already-proven list setter rather than calling
    -- Cherax's GetListIndexByString/SetListIndexByString pair directly. The first
    -- Build 184 live run hard-crashed in the handoff immediately after the account
    -- snapshot and before SESSION_REQUEST was logged, making this feature mutation
    -- the narrowest unsafe boundary. Breadcrumbs intentionally surround each native
    -- feature access so a future hard crash can be located to one operation.
    if not FeatureMgr or not startup.feature_hash or not startup.feature_hash.SESSION_TYPE then
        startup.self_diag.log("ROUTE_FEATURE_UNAVAILABLE", "label="..tostring(label))
        return false, "Session Type feature unavailable"
    end

    startup.self_diag.log("ROUTE_RESOLVE_BEGIN", "label="..tostring(label))
    local feature = startup.get_feature_by_hash_safe(startup.feature_hash.SESSION_TYPE)
    if not feature then
        startup.self_diag.log("ROUTE_RESOLVE_FAILED", "feature not found")
        return false, "Session Type feature not found"
    end

    local okList, list = direct_call(startup.get_feature_list_safe, feature)
    if not okList or type(list) ~= "table" then
        startup.self_diag.log("ROUTE_LIST_FAILED", "label="..tostring(label))
        return false, "Session Type list unavailable"
    end

    local found = false
    for _, value in ipairs(list) do
        if tostring(value) == tostring(label) then found = true break end
    end
    startup.self_diag.log("ROUTE_LIST_OK", "label="..tostring(label).." found="..tostring(found).." options="..tostring(#list))
    if not found then return false, tostring(label) .. " is unavailable on this Cherax layout" end

    startup.self_diag.log("ROUTE_SET_BEGIN", "label="..tostring(label))
    local okSet, setResult = direct_call(startup.set_feature_list_string_silently, feature, tostring(label))
    if not okSet or setResult ~= true then
        startup.self_diag.log("ROUTE_SET_FAILED", "label="..tostring(label).." result="..tostring(setResult))
        return false, "Could not select " .. tostring(label)
    end
    startup.s.sessionType = tostring(label)
    startup.self_diag.log("ROUTE_SET_OK", "label="..tostring(label))
    return true
end

function startup.self_diag.start_session_request(label, purpose)
    startup.self_diag.log("SESSION_REQUEST_BEGIN", "type="..tostring(label).." purpose="..tostring(purpose))
    local okType, err = startup.self_diag.set_session_type_exact(label)
    if not okType then
        sd.status = "Session routing failed: " .. tostring(err)
        startup.self_diag.log("SESSION_ROUTE_FAILED", tostring(err))
        return false
    end
    startup.self_diag.log("SESSION_ROUTE_SETTLE", "500ms before Start Session")
    startup.yield(500)
    if sd.active ~= true then return false end
    startup.self_diag.log("SESSION_CLICK_BEGIN", "type="..tostring(label))
    local ok = startup.click_start_session_feature()
    startup.self_diag.log("SESSION_CLICK_END", "type="..tostring(label).." ok="..tostring(ok))
    startup.self_diag.log("SESSION_REQUEST", "type="..tostring(label).." purpose="..tostring(purpose).." ok="..tostring(ok))
    return ok == true
end

function startup.self_diag.new_hop(index)
    return {
        index=index, startedAtMs=0, finishedAtMs=0, startPlayers=0, endPlayers=0, peakPlayers=0, minPlayers=99,
        joinEvents=0, leaveEvents=0, peerTypes={}, direct=0, peerRelay=0, relayServer=0, unknown=0,
        firstHost="Unknown", firstHostId=-1, hostChanges=0, lastHostId=nil, milestones={}, sessionLoaded=false, failed=false, failReason=""
    }
end

function startup.self_diag.sample_hop(hop)
    local count = startup.get_session_player_count()
    hop.peakPlayers = math.max(tonumber(hop.peakPlayers or 0) or 0, count)
    hop.minPlayers = math.min(tonumber(hop.minPlayers or 99) or 99, count)
    local elapsed = startup.now() - (tonumber(hop.startedAtMs or startup.now()) or startup.now())
    for _, target in ipairs({10,20,25,30}) do if count >= target and hop.milestones[target] == nil then hop.milestones[target] = elapsed end end
    local hostName, hostId = startup.get_session_host_name()
    hostId = tonumber(hostId or -1) or -1
    if hop.lastHostId == nil then
        hop.lastHostId = hostId; hop.firstHostId = hostId; hop.firstHost = tostring(hostName or "Unknown")
    elseif hostId >= 0 and hop.lastHostId >= 0 and hostId ~= hop.lastHostId then
        hop.hostChanges = (tonumber(hop.hostChanges or 0) or 0) + 1; hop.lastHostId = hostId
    end
    local ids = startup.get_voice_player_ids and startup.get_voice_player_ids() or {}
    for _, pid in ipairs(ids) do
        if not startup.self_diag.is_local_id(pid) then
            local name = startup.get_player_name_safe(pid)
            local key = tostring(pid) .. ":" .. tostring(name)
            hop.peerTypes[key] = startup.self_diag.net_type_name(pid)
        end
    end
end

function startup.self_diag.finalize_peer_counts(record)
    record.direct, record.peerRelay, record.relayServer, record.unknown = 0,0,0,0
    for _, typ in pairs(record.peerTypes or {}) do
        if typ == "DIRECT" then record.direct = record.direct + 1
        elseif typ == "PEER_RELAY" then record.peerRelay = record.peerRelay + 1
        elseif typ == "RELAY_SERVER" then record.relayServer = record.relayServer + 1
        else record.unknown = record.unknown + 1 end
    end
    local known = record.direct + record.peerRelay + record.relayServer
    record.directRatio = known > 0 and (record.direct / known * 100) or nil
end

function startup.self_diag.request_join_hop(index)
    if sd.active ~= true then return false end
    -- Keep the Self Diagnosis popup out of the frame in which Cherax changes the
    -- Session Type / starts the next session. It is restored after load.
    sd.popupOpen = false
    sd.currentHop = index
    sd.phase = "JOINING_SESSION"
    sd.status = "Starting public-session hop " .. tostring(index) .. "/" .. tostring(sd.hopTarget) .. "..."
    sd.hops[index] = startup.self_diag.new_hop(index)
    sd.pendingSessionSerial = (tonumber(sd.pendingSessionSerial or 0) or 0) + 1
    local requestSerial = sd.pendingSessionSerial
    local marker = tonumber(startup.s.lastSessionChangeMs or 0) or 0
    local ok = startup.self_diag.start_session_request("Join Public Session", "Self Diagnostics hop "..tostring(index))
    if not ok then
        sd.hops[index].failed=true; sd.hops[index].failReason="Could not start Join Public Session"
        if index < sd.hopTarget then return startup.self_diag.request_join_hop(index+1) end
        return startup.self_diag.return_to_host("join request failed")
    end
    Script.QueueJob(function()
        startup.yield(60000)
        if sd.active == true and sd.phase == "JOINING_SESSION" and requestSerial == sd.pendingSessionSerial
            and (tonumber(startup.s.lastSessionChangeMs or 0) or 0) <= marker then
            local hop=sd.hops[index]; if hop then hop.failed=true; hop.failReason="No session-change event within 60 seconds" end
            startup.self_diag.log("HOP_TIMEOUT", "index="..tostring(index))
            if index < sd.hopTarget then startup.self_diag.request_join_hop(index+1) else startup.self_diag.return_to_host("hop timeout") end
        end
    end)
    return true
end

function startup.self_diag.run_hop(index)
    local hop = sd.hops[index]
    if not hop or sd.active ~= true then return end
    hop.sessionLoaded = true
    hop.startedAtMs = startup.now()
    hop.startPlayers = startup.get_session_player_count()
    hop.peakPlayers = hop.startPlayers
    hop.minPlayers = hop.startPlayers
    sd.phase = "HOP_OBSERVE"
    startup.self_diag.log("HOP_BEGIN", "index="..index.." players="..hop.startPlayers)
    local deadline = hop.startedAtMs + sd.hopWindowMs
    while sd.active == true and sd.phase == "HOP_OBSERVE" and sd.currentHop == index and startup.now() < deadline do
        startup.self_diag.sample_hop(hop)
        local remain = math.max(0, deadline - startup.now())
        sd.status = "Hop "..index.."/"..sd.hopTarget.." | "..startup.self_diag.format_ms(remain).." left | players="..tostring(startup.get_session_player_count())
        startup.yield(math.min(5000, math.max(250, remain)))
    end
    if sd.active ~= true or sd.currentHop ~= index then return end
    startup.self_diag.sample_hop(hop)
    hop.finishedAtMs = startup.now()
    hop.endPlayers = startup.get_session_player_count()
    startup.self_diag.finalize_peer_counts(hop)
    startup.self_diag.log("HOP_END", "index="..index.." start="..hop.startPlayers.." end="..hop.endPlayers.." peak="..hop.peakPlayers.." joins="..hop.joinEvents.." direct="..hop.direct.." relay="..(hop.peerRelay+hop.relayServer))
    if index < sd.hopTarget then
        startup.self_diag.request_join_hop(index + 1)
    else
        startup.self_diag.return_to_host("three hop windows complete")
    end
end

function startup.self_diag.restore_host_route()
    startup.self_diag.restore_user_settings(false)
    -- Host-first design: return to New Public Session after temporary JOIN hops.
    -- Prime does the same while Prime hosting is enabled; turning that Config toggle
    -- OFF restores Prime's Join Public Session return route.
    local target = (startup.is_prime_active_edition() and startup.s.primeHostSessionsEnabled == false) and "Join Public Session" or "New Public Session"
    local ok, err = startup.self_diag.set_session_type_exact(target)
    if not ok then
        startup.self_diag.log("RETURN_HOST_ROUTE_FALLBACK", tostring(err or "exact route unavailable"))
        ok = startup.apply_session_type()
    else
        startup.s.sessionType = target
    end
    return ok == true
end

function startup.self_diag.return_to_host(reason)
    if sd.active ~= true then return false end
    sd.popupOpen = false
    sd.phase = "RETURNING_HOST"
    sd.status = "Returning to hosting..."
    startup.self_diag.log("RETURN_HOST_BEGIN", tostring(reason or "diagnostic complete"))
    startup.self_diag.restore_host_route()
    startup.yield(750)
    local ok = startup.click_start_session_feature()
    if not ok then
        startup.self_diag.log("RETURN_HOST_FAILED", "Could not start host session")
        startup.self_diag.finish("Host return request failed")
        return false
    end
    return true
end

function startup.self_diag.new_host_observation()
    return { startedAtMs=startup.now(), startPlayers=startup.get_session_player_count(), peakPlayers=startup.get_session_player_count(), endPlayers=0,
        joinEvents=0, leaveEvents=0, peerTypes={}, direct=0, peerRelay=0, relayServer=0, unknown=0, milestones={}, hostName="Unknown", hostId=-1, isLocalHost=false,
        advertiser="NONE", advertiseTriggered=false, advertiseEndStatus="" }
end

function startup.self_diag.run_host_observation()
    if sd.active ~= true then return end
    sd.phase = "HOST_SETTLE"
    sd.status = "Fresh host session loaded. Waiting 10 seconds to stabilize..."
    startup.yield(10000)
    if sd.active ~= true then return end
    local host = startup.self_diag.new_host_observation()
    local hName,hId = startup.get_session_host_name(); host.hostName=tostring(hName or "Unknown"); host.hostId=tonumber(hId or -1) or -1; host.isLocalHost=startup.self_diag.is_local_id(host.hostId)
    sd.hostObservation = host
    sd.phase = "HOST_OBSERVE"
    if startup.s.superAdvertiseEnabled == true then
        host.advertiser = "SUPER"; host.advertiseTriggered = true
        startup.run_super_advertise()
    elseif startup.s.oldStartupAdvertiseEnabled == true then
        host.advertiser = "OLD_V103"; host.advertiseTriggered = true
        startup.run_selected_advertise_flow("Self Diagnostics host observation")
    elseif startup.s.autoAdvertiseSession == true then
        host.advertiser = "CURRENT"; host.advertiseTriggered = true
        startup.run_selected_advertise_flow("Self Diagnostics host observation")
    end
    startup.self_diag.log("HOST_OBSERVE_BEGIN", "host="..tostring(host.hostName).." localHost="..tostring(host.isLocalHost).." startPlayers="..host.startPlayers)
    local deadline = host.startedAtMs + sd.hostWindowMs
    while sd.active == true and sd.phase == "HOST_OBSERVE" and startup.now() < deadline do
        local count = startup.get_session_player_count()
        host.peakPlayers = math.max(host.peakPlayers, count)
        local elapsed = startup.now() - host.startedAtMs
        for _, target in ipairs({5,10,15,20,25,30}) do if count >= target and host.milestones[target] == nil then host.milestones[target] = elapsed end end
        local ids = startup.get_voice_player_ids and startup.get_voice_player_ids() or {}
        for _, pid in ipairs(ids) do if not startup.self_diag.is_local_id(pid) then host.peerTypes[tostring(pid)..":"..startup.get_player_name_safe(pid)] = startup.self_diag.net_type_name(pid) end end
        sd.status = "Host observation | "..startup.self_diag.format_ms(math.max(0,deadline-startup.now())).." left | players="..tostring(count).." | joins="..tostring(host.joinEvents)
        if count >= 30 then break end
        startup.yield(5000)
    end
    if sd.active ~= true then return end
    host.endPlayers = startup.get_session_player_count()
    host.advertiseEndStatus = tostring(startup.s.lastAdvertiseStatus or "")
    startup.self_diag.finalize_peer_counts(host)
    startup.self_diag.log("HOST_OBSERVE_END", "start="..host.startPlayers.." end="..host.endPlayers.." peak="..host.peakPlayers.." joins="..host.joinEvents.." direct="..host.direct.." relay="..(host.peerRelay+host.relayServer))
    startup.self_diag.finish("Completed")
end

function startup.self_diag.on_session_loaded()
    if sd.active ~= true then return false end
    sd.pendingSessionSerial = (tonumber(sd.pendingSessionSerial or 0) or 0) + 1
    if sd.phase == "JOINING_SESSION" then
        local index = sd.currentHop
        sd.status = "Public session "..tostring(index).." loaded; beginning 4-minute observation."
        Script.QueueJob(function()
            startup.yield(1500)
            if sd.active ~= true then return end
            sd.popupOpen = true
            startup.self_diag.log("POPUP_RESUME", "hop="..tostring(index))
            if index == 1 then startup.self_diag.capture_preflight() end
            startup.self_diag.run_hop(index)
        end)
        return true
    elseif sd.phase == "RETURNING_HOST" then
        sd.status = "Host session loaded; beginning final host observation."
        Script.QueueJob(function()
            startup.yield(1000)
            if sd.active ~= true then return end
            sd.popupOpen = true
            startup.self_diag.log("POPUP_RESUME", "fresh host observation")
            startup.self_diag.run_host_observation()
        end)
        return true
    elseif sd.phase == "HOP_OBSERVE" then
        local index = sd.currentHop
        local hop = sd.hops[index]
        if hop then
            hop.failed = true
            hop.failReason = "Session changed unexpectedly during the 4-minute observation window"
            hop.finishedAtMs = startup.now()
            hop.endPlayers = startup.get_session_player_count()
            startup.self_diag.finalize_peer_counts(hop)
        end
        sd.phase = "HOP_INTERRUPTED"
        startup.self_diag.log("HOP_INTERRUPTED", "index="..tostring(index))
        Script.QueueJob(function()
            startup.yield(1500)
            if sd.active ~= true then return end
            if index < sd.hopTarget then startup.self_diag.request_join_hop(index + 1) else startup.self_diag.return_to_host("hop interrupted") end
        end)
        return true
    elseif sd.phase == "HOST_OBSERVE" or sd.phase == "HOST_SETTLE" then
        if sd.hostObservation then sd.hostObservation.interrupted = true end
        sd.phase = "HOST_INTERRUPTED"
        sd.status = "Fresh host observation was interrupted by a session change; returning to a fresh host session."
        startup.self_diag.log("HOST_INTERRUPTED", "session changed during final observation")
        Script.QueueJob(function()
            startup.yield(1500)
            if sd.active == true then startup.self_diag.return_to_host("host observation interrupted") end
        end)
        return true
    end
    return true
end

function startup.self_diag.on_player_join(playerId)
    if sd.active ~= true or startup.self_diag.is_local_id(playerId) then return end
    if sd.phase == "HOP_OBSERVE" then
        local hop = sd.hops[sd.currentHop]; if hop then hop.joinEvents = (tonumber(hop.joinEvents or 0) or 0) + 1 end
    elseif sd.phase == "HOST_OBSERVE" and sd.hostObservation then
        sd.hostObservation.joinEvents = (tonumber(sd.hostObservation.joinEvents or 0) or 0) + 1
    end
end

function startup.self_diag.on_player_left(playerId)
    if sd.active ~= true or startup.self_diag.is_local_id(playerId) then return end
    if sd.phase == "HOP_OBSERVE" then
        local hop = sd.hops[sd.currentHop]; if hop then hop.leaveEvents = (tonumber(hop.leaveEvents or 0) or 0) + 1 end
    elseif sd.phase == "HOST_OBSERVE" and sd.hostObservation then
        sd.hostObservation.leaveEvents = (tonumber(sd.hostObservation.leaveEvents or 0) or 0) + 1
    end
end

function startup.self_diag.synthesize()
    local result = { likely = {}, overall = "Inconclusive" }
    local nat = tostring(sd.network and sd.network.nat or "Unknown"):upper()
    if nat:find("STRICT",1,true) then result.likely[#result.likely+1] = {"VERY HIGH","Strict NAT can sharply reduce compatible P2P peers."}
    elseif nat:find("MODERATE",1,true) then result.likely[#result.likely+1] = {"MEDIUM","Moderate NAT can reduce the compatible peer pool."} end
    local directKnown, relayKnown = 0,0
    for _, hop in ipairs(sd.hops or {}) do directKnown=directKnown+(tonumber(hop.direct or 0) or 0); relayKnown=relayKnown+(tonumber(hop.peerRelay or 0) or 0)+(tonumber(hop.relayServer or 0) or 0) end
    if directKnown + relayKnown >= 5 then
        local ratio = directKnown/(directKnown+relayKnown)*100
        result.directRatio = ratio
        if ratio < 20 then result.likely[#result.likely+1] = {"HIGH",string.format("Only %.1f%% of classified observed peers were DIRECT; relay dependency was heavy.",ratio)}
        elseif ratio < 50 then result.likely[#result.likely+1] = {"MEDIUM",string.format("DIRECT peer ratio was %.1f%%; relay use was substantial.",ratio)} end
    end
    local host=sd.hostObservation
    if host then
        if not startup.is_prime_active_edition() and host.isLocalHost ~= true then
            result.likely[#result.likely+1] = {"HIGH", "Standard/Premium fresh-host route loaded, but the local player was not detected as Session Host."}
        end
        if host.advertiser == "NONE" then
            result.likely[#result.likely+1] = {"INFO", "No advertising mode was enabled before the diagnostic; the fresh-host observation measured unadvertised matchmaking."}
        end
        if (tonumber(host.joinEvents or 0) or 0) == 0 and (tonumber(host.startPlayers or 0) or 0) <= 3 then
            result.likely[#result.likely+1] = {"HIGH","Fresh hosted session received zero join callbacks during the 10-minute observation."}
        elseif (tonumber(host.joinEvents or 0) or 0) <= 3 then
            result.likely[#result.likely+1] = {"MEDIUM","Fresh hosted session received only a handful of join callbacks during the observation."}
        end
        local hopHealthy = 0
        for _, hop in ipairs(sd.hops or {}) do if hop.failed ~= true and (tonumber(hop.peakPlayers or 0) or 0) >= 15 then hopHealthy=hopHealthy+1 end end
        if hopHealthy >= 2 and (tonumber(host.joinEvents or 0) or 0) == 0 then
            result.likely[#result.likely+1] = {"HIGH","Joined public sessions were populated, but the fresh hosted session received no joins; hosting/advertising/inbound reachability deserves priority."}
        end
    end
    local extra = sd.account and sd.account.extra or {}
    if extra.nativeBadSport == true then
        result.likely[#result.likely+1] = {"VERY HIGH", "Native Bad Sport state is active; the account may be restricted to a different matchmaking pool."}
    end
    if extra.nativeCheater == true then
        result.likely[#result.likely+1] = {"HIGH", "Native Cheater state is active; account/session restrictions deserve immediate attention."}
    end
    local node = sd.nodeState or {}
    if node.inTutorial == true or node.pendingTutorialSessionChange == true then
        result.likely[#result.likely+1] = {"HIGH", "Tutorial/session-split state was observed on the local player sync data; this can isolate matchmaking behavior."}
    end
    if sd.account and tonumber(sd.account.anomalyScore or 0) >= 55 then
        result.likely[#result.likely+1] = {"RESEARCH", "Account-history statistics are strongly abnormal. Matchmaking impact is not proven; keep this as a correlation signal."}
    elseif sd.account and tonumber(sd.account.anomalyScore or 0) >= 30 then
        result.likely[#result.likely+1] = {"RESEARCH", "Account-history statistics contain modification indicators. Treat this as correlation evidence, not a proven matchmaking cause."}
    end
    if sd.account and tonumber(sd.account.repairNearPct or 0) >= 60 then
        result.likely[#result.likely+1] = {"INFO", "Account strongly resembles the known 503-stat repaired profile."}
    end
    if sd.network and tostring(sd.network.sharedAddressRisk or ""):find("Elevated",1,true) then
        result.likely[#result.likely+1] = {"MEDIUM","Provider metadata suggests mobile/fixed-wireless/satellite-style access; shared-addressing/CGNAT risk is elevated, but not proven."}
    end
    if #result.likely == 0 then result.likely[#result.likely+1] = {"INFO","No single strong cause was proven automatically. Review the saved hop, account, NAT, and host-observation evidence."} end
    result.overall = (#result.likely > 0 and result.likely[1][1] or "Inconclusive")
    sd.synthesis = result
    return result
end

function startup.self_diag.synthesize()
    local out={likely={}}
    local function add(sev,msg) out.likely[#out.likely+1]={sev,msg} end
    local nat=tostring(sd187.network and sd187.network.nat or "Unknown"):upper()
    if nat:find("STRICT",1,true) then add("VERY HIGH","Strict NAT was reported by Cherax and can sharply reduce compatible P2P peers.")
    elseif nat:find("MODERATE",1,true) then add("MEDIUM","Moderate NAT was reported; compatible-peer reachability may be reduced.") end
    local h1,h2=sd187.testRecords[1],sd187.testRecords[3]; local j1,j2=sd187.testRecords[2],sd187.testRecords[4]
    local hostJoins,hostN,hostLocal=0,0,0
    for _,r in ipairs({h1,h2}) do if r and r.loaded then hostN=hostN+1; hostJoins=hostJoins+(tonumber(r.joinEvents or 0) or 0); if r.isLocalHost then hostLocal=hostLocal+1 end end end
    local joinPeak,joinN,direct,relay=0,0,0,0
    for _,r in ipairs({j1,j2}) do if r and r.loaded then joinN=joinN+1; joinPeak=joinPeak+(tonumber(r.peakPlayers or 0) or 0); direct=direct+(tonumber(r.direct or 0) or 0); relay=relay+(tonumber(r.peerRelay or 0) or 0)+(tonumber(r.relayServer or 0) or 0) end end
    if hostN>0 and hostLocal<hostN then add("HIGH","At least one Fresh Host stage did not detect the local player as Session Host.") end
    if direct+relay>=5 then local pct=direct/(direct+relay)*100; out.directRatio=pct; if pct<20 then add("HIGH",string.format("Only %.1f%% of observed joined-session peers were DIRECT.",pct)) elseif pct<50 then add("MEDIUM",string.format("Joined-session DIRECT ratio was %.1f%%; relay use was substantial.",pct)) else add("INFO",string.format("Joined-session peer connectivity looked healthy at %.1f%% DIRECT.",pct)) end end
    if joinN>0 and hostN>0 then local avgJoinPeak=joinPeak/joinN; local avgHostJoins=hostJoins/hostN; if avgJoinPeak>=15 and avgHostJoins<1 then add("HIGH",string.format("Joined sessions averaged %.1f players, but hosted sessions averaged only %.1f incoming joins in four minutes; prioritize hosting/advertising/inbound reachability.",avgJoinPeak,avgHostJoins)) elseif avgJoinPeak<8 and avgHostJoins<2 then add("MEDIUM","Both joined and hosted sessions were small/slow; broader matchmaking-pool, routing, region, ISP, or account-state factors deserve attention.") end end
    local extra=sd187.account and sd187.account.extra or {}; if extra.nativeBadSport==true then add("VERY HIGH","Native Bad Sport state is active and may place the account in a separate matchmaking pool.") end; if extra.nativeCheater==true then add("HIGH","Native Cheater state is active.") end
    local node=sd187.nodeState or {}; if node.inTutorial==true or node.pendingTutorialSessionChange==true then add("HIGH","Tutorial/session-segmentation state was observed active.") end
    if tostring(sd187.account.classification or ""):find("Known repaired",1,true) then add("INFO","Account strongly resembles the known 503-stat repaired profile; this is correlation evidence, not a proven matchmaking cause.") elseif tonumber(sd187.account.anomalyScore or 0)>50 then add("RESEARCH","Account-stat relationships are substantially abnormal; keep this as a correlation variable until more runs establish an effect.") end
    if #out.likely==0 then add("INFO","No single cause was proven in this run; compare repeated alternating runs and networking metadata.") end
    sd187.synthesis=out; return out
end

function startup.self_diag.write_report(reason)
    startup.self_diag.ensure_dir()
    local accountName = startup.self_diag.safe_filename((startup.get_support_runtime_metadata and startup.get_support_runtime_metadata().localPlayerName) or "ACCOUNT")
    local runId = sd.runId ~= "" and sd.runId or (accountName .. "_" .. os.date("%Y_%m_%d_%H%M%S"))
    local path = startup.self_diag_dir .. "\\" .. runId .. "_Self_Diagnosis.txt"
    local f = io.open(path,"w")
    if not f then return false end
    local function w(s) f:write(tostring(s or ""),"\n") end
    local synthesis = startup.self_diag.synthesize()
    w("STARTUP SELF DIAGNOSTICS")
    w("========================")
    w("Build: "..tostring(startup.build_number)); w("Run: "..runId); w("Finished: "..os.date("%Y-%m-%d %H:%M:%S")); w("Reason: "..tostring(reason or "Completed")); w("")
    w("ACCOUNT")
    w("-------")
    w("Character slot: MP"..tostring(sd.account.slot or 0))
    w(string.format("Playtime: %.2f hours",tonumber(sd.account.playHours or 0) or 0))
    w("Rank: "..tostring(sd.account.extra and sd.account.extra.rank or "Unknown"))
    w("XP: "..tostring(sd.account.extra and sd.account.extra.xp or "Unknown"))
    w("Readable repair-template stats: "..tostring(sd.account.readable or 0).." / 503")
    for _, groupName in ipairs({"Profile","Weapons","Businesses"}) do
        local g = sd.account.groups and sd.account.groups[groupName] or nil
        if g then w(string.format("  %s: %d/%d readable | exact=%d | near=%d | nonzero=%d", groupName, tonumber(g.readable or 0), tonumber(g.total or 0), tonumber(g.exact or 0), tonumber(g.near or 0), tonumber(g.nonzero or 0))) end
    end
    w(string.format("Known repair exact similarity: %.2f%%",tonumber(sd.account.repairExactPct or 0) or 0))
    w(string.format("Known repair near similarity (2%%): %.2f%%",tonumber(sd.account.repairNearPct or 0) or 0))
    w(string.format("Readable non-zero density: %.2f%%",tonumber(sd.account.completenessPct or 0) or 0))
    w("Account classification: "..tostring(sd.account.classification or "Unknown"))
    w("Organic plausibility: "..tostring(sd.account.organicPlausibility or "Unknown").." / 100")
    w("Profile coherence: "..tostring(sd.account.profileCoherence or "Unknown").." / 100")
    w("Account anomaly score: "..tostring(sd.account.anomalyScore or 0).." / 100")
    w("Detailed 503-stat diff: "..tostring(sd.latestSnapshotPath or "Not saved"))
    if sd.account.extra then
        w("Native Bad Sport: "..tostring(sd.account.extra.nativeBadSport)); w("Native Cheater: "..tostring(sd.account.extra.nativeCheater))
        w("Suicides: "..tostring(sd.account.extra.suicides or "Unknown")); w("Mental state: "..tostring(sd.account.extra.mentalState or "Unknown"))
    end
    local nodeState = sd.nodeState or {}
    w("Tutorial inTutorial: "..tostring(nodeState.inTutorial ~= nil and nodeState.inTutorial or "Not observed"))
    w("Tutorial pending session change: "..tostring(nodeState.pendingTutorialSessionChange ~= nil and nodeState.pendingTutorialSessionChange or "Not observed"))
    w("Tutorial index: "..tostring(nodeState.tutorialIndex ~= nil and nodeState.tutorialIndex or "Not observed"))
    w("Tutorial instance ID: "..tostring(nodeState.tutorialInstanceId ~= nil and nodeState.tutorialInstanceId or "Not observed"))
    w(""); w("ACCOUNT FINDINGS")
    for _, item in ipairs(sd.findings or {}) do w("["..item.severity.."] "..item.code.." - "..item.text) end

    w(""); w("NETWORK / LOCATION")
    w("------------------")
    w("NAT: "..tostring(sd.network.nat or "Unknown")); w("CGNAT: "..tostring(sd.network.cgnat or "Unknown"))
    local ip=sd.network.ip or {}; w("Country: "..tostring(ip.country or "Unknown").." "..tostring(ip.countryCode or "")); w("Region: "..tostring(ip.region or "")); w("Approximate city: "..tostring(ip.city or "")); w("ISP/Org: "..tostring(ip.isp or "")); w("ASN: "..tostring(ip.asn or "")); w("Provider/network: "..tostring(ip.provider or "")); w("VPN metadata: "..tostring(ip.vpn or "Unknown")); w("Proxy metadata: "..tostring(ip.proxy or "Unknown")); w("Shared-address risk: "..tostring(sd.network.sharedAddressRisk or "Unknown"))
    w("Note: raw public IP is intentionally not stored in this report.")
    w(""); w("AUTOMATION COVERAGE")
    w("-------------------")
    w("Automated now: NAT label, approximate IP metadata, ISP/ASN metadata when Cherax exposes it, DIRECT/relay mix, 503-stat account scan, Bad Sport/Cheater natives, opportunistic tutorial-state observation, three public-session hops, and fresh-host join observation.")
    w("Heuristic only: shared-address/provider risk and account-stat matchmaking correlation.")
    w("Not directly proven in this alpha: CGNAT, router WAN/public-IP mismatch, UDP port reachability, UPnP mappings, firewall rules, MTU/fragmentation, DNS filtering, ISP P2P policy, or router double-NAT topology. These require external/router-side probes and are never guessed as confirmed.")

    w(""); w("4-MINUTE PUBLIC SESSION HOPS")
    w("----------------------------")
    for _, hop in ipairs(sd.hops or {}) do
        w(string.format("Hop %d: loaded=%s failed=%s start=%d end=%d peak=%d joins=%d leaves=%d hostChanges=%d DIRECT=%d PEER_RELAY=%d RELAY_SERVER=%d unknown=%d directRatio=%s",
            tonumber(hop.index or 0) or 0,tostring(hop.sessionLoaded==true),tostring(hop.failed==true),tonumber(hop.startPlayers or 0) or 0,tonumber(hop.endPlayers or 0) or 0,tonumber(hop.peakPlayers or 0) or 0,tonumber(hop.joinEvents or 0) or 0,tonumber(hop.leaveEvents or 0) or 0,tonumber(hop.hostChanges or 0) or 0,tonumber(hop.direct or 0) or 0,tonumber(hop.peerRelay or 0) or 0,tonumber(hop.relayServer or 0) or 0,tonumber(hop.unknown or 0) or 0,hop.directRatio and string.format("%.1f%%",hop.directRatio) or "Unknown"))
        if hop.failReason and hop.failReason ~= "" then w("  Failure: "..hop.failReason) end
    end

    w(""); w("FRESH HOST OBSERVATION")
    w("----------------------")
    local host=sd.hostObservation
    if host then
        w("Session Host: "..tostring(host.hostName).." | localHost="..tostring(host.isLocalHost))
        w("Advertiser: "..tostring(host.advertiser or "NONE").." | triggered="..tostring(host.advertiseTriggered==true).." | endStatus="..tostring(host.advertiseEndStatus or ""))
        w("Players: "..tostring(host.startPlayers).." -> "..tostring(host.endPlayers).." | peak="..tostring(host.peakPlayers))
        w("Join callbacks: "..tostring(host.joinEvents).." | Leave callbacks: "..tostring(host.leaveEvents))
        w("DIRECT="..tostring(host.direct).." PEER_RELAY="..tostring(host.peerRelay).." RELAY_SERVER="..tostring(host.relayServer).." unknown="..tostring(host.unknown).." directRatio="..tostring(host.directRatio and string.format("%.1f%%",host.directRatio) or "Unknown"))
        for _, target in ipairs({5,10,15,20,25,30}) do if host.milestones and host.milestones[target] then w("Time to "..target.." players: "..startup.self_diag.format_ms(host.milestones[target])) end end
    else w("Not completed.") end

    w(""); w("LIKELY CAUSES / NEXT PRIORITIES")
    w("------------------------------")
    for i,item in ipairs(synthesis.likely or {}) do w(tostring(i)..". ["..tostring(item[1]).."] "..tostring(item[2])) end
    w(""); w("Interpretation rule: account modification, CGNAT, ISP restrictions, or relay use are not declared causal unless the diagnostic directly proves the condition. Account abnormalities are correlation evidence only.")
    f:close()
    sd.latestReportPath=path; startup.s.selfDiagLastReportPath=path
    return true
end

function startup.self_diag.write_history(reason)
    startup.self_diag.ensure_dir()
    local path=startup.SelfDiagHistoryFile
    local exists=startup.support_file_exists(path)
    local f=io.open(path,"a"); if not f then return false end
    if not exists then
        f:write("run_id,finished,reason,account_class,anomaly_score,repair_near_pct,play_hours,nat,country,isp,hops_completed,avg_hop_peak,avg_direct_ratio,host_start,host_end,host_peak,host_joins,host_local,report_path\n")
    end
    local hopsCompleted,peakSum,directSum,directN=0,0,0,0
    for _,hop in ipairs(sd.hops or {}) do if hop.sessionLoaded then hopsCompleted=hopsCompleted+1; peakSum=peakSum+(tonumber(hop.peakPlayers or 0) or 0); if hop.directRatio then directSum=directSum+hop.directRatio; directN=directN+1 end end end
    local host=sd.hostObservation or {}; local ip=sd.network.ip or {}
    local vals={sd.runId,os.date("%Y-%m-%d %H:%M:%S"),reason or "Completed",sd.account.classification or "Unknown",sd.account.anomalyScore or 0,string.format("%.2f",tonumber(sd.account.repairNearPct or 0) or 0),string.format("%.2f",tonumber(sd.account.playHours or 0) or 0),sd.network.nat or "Unknown",ip.country or "Unknown",ip.isp or "",hopsCompleted,hopsCompleted>0 and string.format("%.2f",peakSum/hopsCompleted) or "",directN>0 and string.format("%.2f",directSum/directN) or "",host.startPlayers or "",host.endPlayers or "",host.peakPlayers or "",host.joinEvents or "",host.isLocalHost,sd.latestReportPath}
    for i,v in ipairs(vals) do vals[i]=startup.self_diag.csv(v) end
    f:write(table.concat(vals,","),"\n"); f:close(); sd.historyPath=path; startup.s.selfDiagHistoryPath=path; return true
end

function startup.self_diag.finish(reason)
    if sd.phase == "COMPLETE" then return end
    sd.active=false; sd.workerQueued=false; sd.phase="COMPLETE"; sd.status="Self Diagnosis complete - hosting session left running."
    startup.self_diag.restore_user_settings(true)
    if startup.s.initialized and startup.save_config then startup.save_config(false) end
    startup.self_diag.write_report(reason or "Completed")
    startup.self_diag.write_history(reason or "Completed")
    startup.self_diag.log("COMPLETE", "reason="..tostring(reason).." report="..tostring(sd.latestReportPath))
    startup.toast("Self Diagnosis complete. Report saved; hosting session remains active.",7000)
end

function startup.self_diag.abort_and_return(reason)
    if sd.active ~= true then sd.popupOpen=true; return false end
    sd.serial=sd.serial+1; sd.status="Stopping diagnostic and returning to hosting..."; sd.phase="ABORTING"
    startup.self_diag.log("ABORT",tostring(reason or "user"))
    startup.self_diag.restore_host_route(); startup.yield(500); startup.click_start_session_feature()
    sd.active=false; sd.phase="COMPLETE"; sd.status="Stopped early. Host session requested."
    if startup.s.initialized and startup.save_config then startup.save_config(false) end
    startup.self_diag.write_report("Stopped early: "..tostring(reason or "user")); startup.self_diag.write_history("Stopped early")
    return true
end

function startup.self_diag.begin_hop_stage(serial)
    if sd.active ~= true or serial ~= sd.serial then return false end
    sd.phase = "PREPARE_HOPS"
    sd.status = "Account scan complete. Preparing isolated session-hop stage..."
    startup.self_diag.log("HOP_HANDOFF_BEGIN", "serial="..tostring(serial))
    -- Do not render the dedicated popup while Cherax Session Type is being mutated.
    -- The window reopens after the session-loaded callback. This removes UI/native
    -- feature mutation overlap from the exact Build 183 crash boundary.
    sd.popupOpen = false
    startup.self_diag.log("POPUP_SUSPEND", "session transition isolation")
    -- Let the 503-stat worker fully unwind before touching Cherax Session Type.
    -- This deliberately separates the scanner and FeatureMgr/native session mutation
    -- into different queued jobs and different frames.
    startup.yield(2000)
    if sd.active ~= true or serial ~= sd.serial then return false end
    startup.self_diag.log("HOP_HANDOFF_READY", "starting hop 1 after isolated delay")
    return startup.self_diag.request_join_hop(1)
end

function startup.self_diag.start()
    sd.popupOpen=true
    if sd.active == true then startup.toast("Self Diagnosis is already running.",3000); return false end
    startup.self_diag.ensure_dir()
    sd.serial=sd.serial+1; sd.active=true; sd.workerQueued=true; sd.phase="PREFLIGHT"; sd.status="Starting one-button Self Diagnosis..."; sd.currentHop=0; sd.hops={}; sd.hostObservation=nil; sd.nodeState={}; sd.findings={}; sd.startedAtMs=startup.now(); sd.startedAtEpoch=os.time(); sd.pendingSessionSerial=0
    local runSerial = sd.serial
    local meta=startup.get_support_runtime_metadata and startup.get_support_runtime_metadata() or {}; local account=startup.self_diag.safe_filename(meta.localPlayerName or "ACCOUNT")
    sd.runId=account.."_"..os.date("%Y_%m_%d_%H%M%S")
    startup.self_diag.snapshot_user_settings(); startup.self_diag.suspend_normal_automation(); startup.self_diag.log("START","run="..sd.runId.." build="..tostring(startup.build_number))
    Script.QueueJob(function()
        local ok,err=direct_call(function()
            startup.self_diag.capture_preflight()
            startup.self_diag.scan_account()
            startup.self_diag.write_account_snapshot()
            if sd.active == true and runSerial == sd.serial then
                sd.phase = "ACCOUNT_COMPLETE"
                sd.status = "Account scan complete. Session-hop stage will start safely in a separate job."
                startup.self_diag.log("ACCOUNT_STAGE_COMPLETE", "scanner worker exiting before session routing")
            end
        end)
        sd.workerQueued=false
        if not ok and sd.active then
            sd.status="Diagnostic error: "..tostring(err); startup.self_diag.log("ERROR",tostring(err)); startup.self_diag.abort_and_return("internal error")
            return
        end
        if sd.active == true and runSerial == sd.serial then
            Script.QueueJob(function()
                local hopOk, hopErr = direct_call(function() startup.self_diag.begin_hop_stage(runSerial) end)
                if not hopOk and sd.active == true and runSerial == sd.serial then
                    sd.status = "Session-hop handoff error: "..tostring(hopErr)
                    startup.self_diag.log("HOP_HANDOFF_ERROR", tostring(hopErr))
                    startup.self_diag.abort_and_return("hop handoff error")
                end
            end)
        end
    end)
    return true
end


-- Build 185 state-machine override -------------------------------------------------
-- Live Build 184 evidence showed ACCOUNT_STAGE_COMPLETE followed by a hard process
-- exit before HOP_HANDOFF_BEGIN. Self Diagnostics therefore creates no queued jobs
-- after Start. The permanent Startup 500-ms worker advances every diagnostic stage.
-- This avoids nested Script.QueueJob handoffs and also removes QueueJob use from the
-- session-loaded continuation path.

sd.nextActionMs = tonumber(sd.nextActionMs or 0) or 0
sd.nextSampleMs = tonumber(sd.nextSampleMs or 0) or 0
sd.sessionRequestAtMs = tonumber(sd.sessionRequestAtMs or 0) or 0
sd.sessionRequestMarkerMs = tonumber(sd.sessionRequestMarkerMs or 0) or 0
sd.abortRequested = sd.abortRequested == true
sd.abortReason = tostring(sd.abortReason or "")

function startup.self_diag.request_abort(reason)
    if sd.active ~= true then sd.popupOpen = true; return false end
    sd.abortRequested = true
    sd.abortReason = tostring(reason or "user")
    sd.status = "Stop requested. Returning to hosting safely..."
    startup.self_diag.log("ABORT_REQUESTED", sd.abortReason)
    return true
end

function startup.self_diag.prepare_hop_state(index)
    index = tonumber(index or 1) or 1
    sd.currentHop = index
    sd.hops[index] = startup.self_diag.new_hop(index)
    sd.phase = "HOP_ROUTE"
    sd.status = "Preparing public-session hop "..tostring(index).."/"..tostring(sd.hopTarget).."..."
    sd.popupOpen = false
    sd.nextActionMs = startup.now()
    startup.self_diag.log("HOP_PREPARE", "index="..tostring(index))
end

function startup.self_diag.route_hop_now()
    local index = tonumber(sd.currentHop or 1) or 1
    startup.self_diag.log("HOP_HANDOFF_BEGIN", "state-machine index="..tostring(index))
    startup.self_diag.log("SESSION_REQUEST_BEGIN", "type=Join Public Session purpose=Self Diagnostics hop "..tostring(index))
    local ok, err = startup.self_diag.set_session_type_exact("Join Public Session")
    if not ok then
        local hop = sd.hops[index]
        if hop then hop.failed=true; hop.failReason=tostring(err or "Could not select Join Public Session") end
        startup.self_diag.log("SESSION_ROUTE_FAILED", tostring(err))
        sd.phase = "HOP_FAILED_WAIT"
        sd.nextActionMs = startup.now() + 1500
        return false
    end
    startup.self_diag.log("HOP_HANDOFF_READY", "route selected; click deferred to permanent worker")
    sd.phase = "HOP_CLICK_WAIT"
    sd.nextActionMs = startup.now() + 750
    return true
end

function startup.self_diag.click_hop_now()
    local index = tonumber(sd.currentHop or 1) or 1
    startup.self_diag.log("SESSION_CLICK_BEGIN", "type=Join Public Session index="..tostring(index))
    local marker = tonumber(startup.s.lastSessionChangeMs or 0) or 0
    local ok = startup.click_start_session_feature()
    startup.self_diag.log("SESSION_CLICK_END", "type=Join Public Session index="..tostring(index).." ok="..tostring(ok))
    if ok ~= true then
        local hop=sd.hops[index]; if hop then hop.failed=true; hop.failReason="Could not click Start Session" end
        sd.phase="HOP_FAILED_WAIT"; sd.nextActionMs=startup.now()+1500
        return false
    end
    sd.sessionRequestAtMs = startup.now()
    sd.sessionRequestMarkerMs = marker
    sd.phase = "JOINING_SESSION"
    sd.status = "Joining public session "..tostring(index).."/"..tostring(sd.hopTarget).."..."
    startup.self_diag.log("SESSION_REQUEST", "type=Join Public Session purpose=Self Diagnostics hop "..tostring(index).." ok=true")
    return true
end

function startup.self_diag.begin_hop_observation_now()
    local index = tonumber(sd.currentHop or 1) or 1
    local hop = sd.hops[index]
    if not hop then return false end
    hop.sessionLoaded = true
    hop.startedAtMs = startup.now()
    hop.startPlayers = startup.get_session_player_count()
    hop.peakPlayers = hop.startPlayers
    hop.minPlayers = hop.startPlayers
    sd.phase = "HOP_OBSERVE"
    sd.nextSampleMs = 0
    sd.popupOpen = true
    sd.status = "Observing public session "..tostring(index).."/"..tostring(sd.hopTarget).." for 4 minutes."
    startup.self_diag.log("HOP_BEGIN", "index="..tostring(index).." players="..tostring(hop.startPlayers))
    return true
end

function startup.self_diag.finish_hop_now(reason)
    local index = tonumber(sd.currentHop or 1) or 1
    local hop = sd.hops[index]
    if hop then
        startup.self_diag.sample_hop(hop)
        hop.finishedAtMs = startup.now()
        hop.endPlayers = startup.get_session_player_count()
        startup.self_diag.finalize_peer_counts(hop)
        startup.self_diag.log("HOP_END", "index="..tostring(index).." reason="..tostring(reason or "window complete").." start="..tostring(hop.startPlayers).." end="..tostring(hop.endPlayers).." peak="..tostring(hop.peakPlayers).." joins="..tostring(hop.joinEvents).." direct="..tostring(hop.direct).." relay="..tostring((hop.peerRelay or 0)+(hop.relayServer or 0)))
    end
    if index < tonumber(sd.hopTarget or 3) then
        sd.phase = "HOP_NEXT_WAIT"
        sd.nextActionMs = startup.now() + 1500
        sd.status = "Hop "..tostring(index).." complete. Preparing next public session..."
        sd.popupOpen = false
    else
        sd.phase = "HOST_ROUTE"
        sd.nextActionMs = startup.now() + 1500
        sd.status = "Three hop windows complete. Returning to hosting..."
        sd.popupOpen = false
    end
end

function startup.self_diag.route_host_now(reason)
    startup.self_diag.log("RETURN_HOST_BEGIN", tostring(reason or "diagnostic hop stage complete"))
    startup.self_diag.restore_user_settings(false)
    local target = (startup.is_prime_active_edition() and startup.s.primeHostSessionsEnabled == false) and "Join Public Session" or "New Public Session"
    local ok, err = startup.self_diag.set_session_type_exact(target)
    if not ok then
        startup.self_diag.log("RETURN_HOST_ROUTE_FALLBACK", tostring(err or "exact route unavailable"))
        ok = startup.apply_session_type()
    else
        startup.s.sessionType = target
    end
    if ok ~= true then
        startup.self_diag.log("RETURN_HOST_FAILED", "Could not select host route")
        startup.self_diag.finish("Host return route failed")
        return false
    end
    sd.phase = "HOST_CLICK_WAIT"
    sd.nextActionMs = startup.now() + 750
    sd.status = "Hosting route restored. Starting fresh public session..."
    return true
end

function startup.self_diag.click_host_now()
    startup.self_diag.log("HOST_SESSION_CLICK_BEGIN", "type="..tostring(startup.s.sessionType))
    local ok = startup.click_start_session_feature()
    startup.self_diag.log("HOST_SESSION_CLICK_END", "ok="..tostring(ok))
    if ok ~= true then startup.self_diag.finish("Host session click failed"); return false end
    sd.sessionRequestAtMs = startup.now()
    sd.phase = "RETURNING_HOST"
    sd.status = "Starting fresh hosting session..."
    return true
end

function startup.self_diag.begin_host_observation_now()
    local host = startup.self_diag.new_host_observation()
    local hName,hId = startup.get_session_host_name()
    host.hostName=tostring(hName or "Unknown"); host.hostId=tonumber(hId or -1) or -1; host.isLocalHost=startup.self_diag.is_local_id(host.hostId)
    sd.hostObservation = host
    sd.phase = "HOST_OBSERVE"
    sd.nextSampleMs = 0
    sd.popupOpen = true
    if startup.s.superAdvertiseEnabled == true then
        host.advertiser="SUPER"; host.advertiseTriggered=true; startup.run_super_advertise()
    elseif startup.s.oldStartupAdvertiseEnabled == true then
        host.advertiser="OLD_V103"; host.advertiseTriggered=true; startup.run_selected_advertise_flow("Self Diagnostics host observation")
    elseif startup.s.autoAdvertiseSession == true then
        host.advertiser="CURRENT"; host.advertiseTriggered=true; startup.run_selected_advertise_flow("Self Diagnostics host observation")
    end
    startup.self_diag.log("HOST_OBSERVE_BEGIN", "host="..tostring(host.hostName).." localHost="..tostring(host.isLocalHost).." startPlayers="..tostring(host.startPlayers).." advertiser="..tostring(host.advertiser))
    return true
end

function startup.self_diag.finish_host_observation_now(reason)
    local host = sd.hostObservation
    if host then
        host.endPlayers = startup.get_session_player_count()
        host.advertiseEndStatus = tostring(startup.s.lastAdvertiseStatus or "")
        startup.self_diag.finalize_peer_counts(host)
        startup.self_diag.log("HOST_OBSERVE_END", "reason="..tostring(reason or "complete").." start="..tostring(host.startPlayers).." end="..tostring(host.endPlayers).." peak="..tostring(host.peakPlayers).." joins="..tostring(host.joinEvents).." direct="..tostring(host.direct).." relay="..tostring((host.peerRelay or 0)+(host.relayServer or 0)))
    end
    startup.self_diag.finish(reason or "Completed")
end

function startup.self_diag.start()
    sd.popupOpen = true
    if sd.active == true then startup.toast("Self Diagnosis is already running.",3000); return false end
    startup.self_diag.ensure_dir()
    sd.serial=(tonumber(sd.serial or 0) or 0)+1
    sd.active=true; sd.workerQueued=false; sd.abortRequested=false; sd.abortReason=""
    sd.phase="PREFLIGHT_PENDING"; sd.status="Starting one-button Self Diagnosis..."
    sd.currentHop=0; sd.hops={}; sd.hostObservation=nil; sd.nodeState={}; sd.findings={}
    sd.startedAtMs=startup.now(); sd.startedAtEpoch=os.time(); sd.pendingSessionSerial=0
    sd.nextActionMs=startup.now()+250; sd.nextSampleMs=0; sd.sessionRequestAtMs=0; sd.sessionRequestMarkerMs=0
    local meta=startup.get_support_runtime_metadata and startup.get_support_runtime_metadata() or {}
    local account=startup.self_diag.safe_filename(meta.localPlayerName or "ACCOUNT")
    sd.runId=account.."_"..os.date("%Y_%m_%d_%H%M%S")
    startup.self_diag.snapshot_user_settings()
    startup.self_diag.suspend_normal_automation()
    startup.self_diag.log("START", "run="..sd.runId.." build="..tostring(startup.build_number).." engine=permanent-worker-state-machine")
    return true
end

function startup.self_diag.abort_and_return(reason)
    return startup.self_diag.request_abort(reason)
end

function startup.self_diag.on_session_loaded()
    if sd.active ~= true then return false end
    local now = startup.now()
    if sd.phase == "JOINING_SESSION" then
        local index=tonumber(sd.currentHop or 1) or 1
        startup.self_diag.log("SESSION_LOADED_FOR_HOP", "index="..tostring(index))
        sd.phase="HOP_SETTLE"; sd.nextActionMs=now+1500; sd.popupOpen=true
        sd.status="Public session "..tostring(index).." loaded. Stabilizing before the 4-minute observation..."
        return true
    elseif sd.phase == "RETURNING_HOST" then
        startup.self_diag.log("SESSION_LOADED_FOR_HOST", "fresh host session")
        sd.phase="HOST_SETTLE"; sd.nextActionMs=now+10000; sd.popupOpen=true
        sd.status="Fresh host session loaded. Waiting 10 seconds to stabilize..."
        return true
    elseif sd.phase == "HOP_OBSERVE" then
        local index=tonumber(sd.currentHop or 1) or 1; local hop=sd.hops[index]
        if hop then hop.failed=true; hop.failReason="Session changed unexpectedly during 4-minute observation" end
        startup.self_diag.log("HOP_INTERRUPTED", "index="..tostring(index))
        startup.self_diag.finish_hop_now("unexpected session change")
        return true
    elseif sd.phase == "HOST_OBSERVE" or sd.phase == "HOST_SETTLE" then
        if sd.hostObservation then sd.hostObservation.interrupted=true end
        startup.self_diag.log("HOST_INTERRUPTED", "session changed during final observation")
        sd.phase="HOST_ROUTE"; sd.nextActionMs=now+1500; sd.popupOpen=false
        return true
    end
    startup.self_diag.log("SESSION_LOADED_IGNORED", "phase="..tostring(sd.phase))
    return true
end

function startup.self_diag.tick()
    if sd.active ~= true then return end
    local now=startup.now()

    if sd.abortRequested == true then
        local why=sd.abortReason ~= "" and sd.abortReason or "user"
        sd.abortRequested=false
        sd.serial=(tonumber(sd.serial or 0) or 0)+1
        sd.phase="HOST_ROUTE"; sd.nextActionMs=now; sd.status="Stopping diagnostic and returning to hosting..."; sd.popupOpen=false
        startup.self_diag.log("ABORT", why)
        sd.abortReason=why
        return
    end

    if sd.phase == "PREFLIGHT_PENDING" and now >= (sd.nextActionMs or 0) then
        sd.phase="ACCOUNT_SCAN"; sd.status="Running read-only 503-stat account scan..."
        startup.self_diag.capture_preflight()
        startup.self_diag.scan_account()
        startup.self_diag.write_account_snapshot()
        if sd.active ~= true then return end
        sd.phase="HOP_HANDOFF_WAIT"; sd.status="Account scan complete. Session-hop stage will start from Startup's permanent worker."
        sd.nextActionMs=startup.now()+2000
        startup.self_diag.log("ACCOUNT_STAGE_COMPLETE", "scanner returned to permanent worker; no nested QueueJob")
        -- Close before routing so no Self Diagnosis ImGui frame overlaps the feature mutation.
        sd.popupOpen=false
        return
    end

    if sd.phase == "HOP_HANDOFF_WAIT" and now >= (sd.nextActionMs or 0) then
        startup.self_diag.prepare_hop_state(1); return
    end
    if sd.phase == "HOP_ROUTE" and now >= (sd.nextActionMs or 0) then startup.self_diag.route_hop_now(); return end
    if sd.phase == "HOP_CLICK_WAIT" and now >= (sd.nextActionMs or 0) then startup.self_diag.click_hop_now(); return end

    if sd.phase == "JOINING_SESSION" then
        if now-(tonumber(sd.sessionRequestAtMs or now) or now) >= 60000 then
            local index=tonumber(sd.currentHop or 1) or 1; local hop=sd.hops[index]
            if hop then hop.failed=true; hop.failReason="No session-loaded event within 60 seconds" end
            startup.self_diag.log("HOP_TIMEOUT", "index="..tostring(index))
            sd.phase="HOP_FAILED_WAIT"; sd.nextActionMs=now+1500
        end
        return
    end

    if sd.phase == "HOP_SETTLE" and now >= (sd.nextActionMs or 0) then startup.self_diag.begin_hop_observation_now(); return end
    if sd.phase == "HOP_OBSERVE" then
        local index=tonumber(sd.currentHop or 1) or 1; local hop=sd.hops[index]
        if not hop then sd.phase="HOP_FAILED_WAIT"; sd.nextActionMs=now; return end
        if now >= (tonumber(sd.nextSampleMs or 0) or 0) then
            sd.nextSampleMs=now+5000
            startup.self_diag.sample_hop(hop)
            local deadline=(tonumber(hop.startedAtMs or now) or now)+(tonumber(sd.hopWindowMs or 240000) or 240000)
            sd.status="Hop "..tostring(index).."/"..tostring(sd.hopTarget).." | "..startup.self_diag.format_ms(math.max(0,deadline-now)).." left | players="..tostring(startup.get_session_player_count())
        end
        local deadline=(tonumber(hop.startedAtMs or now) or now)+(tonumber(sd.hopWindowMs or 240000) or 240000)
        if now >= deadline then startup.self_diag.finish_hop_now("4-minute window complete") end
        return
    end
    if sd.phase == "HOP_FAILED_WAIT" and now >= (sd.nextActionMs or 0) then
        local index=tonumber(sd.currentHop or 1) or 1
        if index < tonumber(sd.hopTarget or 3) then startup.self_diag.prepare_hop_state(index+1)
        else sd.phase="HOST_ROUTE"; sd.nextActionMs=now; sd.popupOpen=false end
        return
    end
    if sd.phase == "HOP_NEXT_WAIT" and now >= (sd.nextActionMs or 0) then startup.self_diag.prepare_hop_state((tonumber(sd.currentHop or 0) or 0)+1); return end

    if sd.phase == "HOST_ROUTE" and now >= (sd.nextActionMs or 0) then startup.self_diag.route_host_now(sd.abortReason ~= "" and ("abort: "..sd.abortReason) or "hop stage complete"); return end
    if sd.phase == "HOST_CLICK_WAIT" and now >= (sd.nextActionMs or 0) then startup.self_diag.click_host_now(); return end
    if sd.phase == "RETURNING_HOST" then
        if now-(tonumber(sd.sessionRequestAtMs or now) or now) >= 60000 then
            startup.self_diag.log("HOST_RETURN_TIMEOUT", "no session-loaded event in 60 seconds")
            startup.self_diag.finish("Host return timeout")
        end
        return
    end
    if sd.phase == "HOST_SETTLE" and now >= (sd.nextActionMs or 0) then
        if sd.abortReason ~= "" then
            sd.active=false; sd.phase="COMPLETE"; sd.status="Stopped early. Fresh host session restored."; sd.popupOpen=true
            startup.self_diag.write_report("Stopped early: "..sd.abortReason); startup.self_diag.write_history("Stopped early")
            startup.self_diag.log("ABORT_COMPLETE", "fresh host session restored")
            return
        end
        startup.self_diag.begin_host_observation_now(); return
    end
    if sd.phase == "HOST_OBSERVE" then
        local host=sd.hostObservation
        if not host then return end
        if now >= (tonumber(sd.nextSampleMs or 0) or 0) then
            sd.nextSampleMs=now+5000
            local count=startup.get_session_player_count(); host.peakPlayers=math.max(tonumber(host.peakPlayers or 0) or 0,count)
            local elapsed=now-(tonumber(host.startedAtMs or now) or now)
            for _,target in ipairs({5,10,15,20,25,30}) do if count>=target and host.milestones[target]==nil then host.milestones[target]=elapsed end end
            local ids=startup.get_voice_player_ids and startup.get_voice_player_ids() or {}
            for _,pid in ipairs(ids) do if not startup.self_diag.is_local_id(pid) then host.peerTypes[tostring(pid)..":"..startup.get_player_name_safe(pid)]=startup.self_diag.net_type_name(pid) end end
            local deadline=(tonumber(host.startedAtMs or now) or now)+(tonumber(sd.hostWindowMs or 600000) or 600000)
            sd.status="Host observation | "..startup.self_diag.format_ms(math.max(0,deadline-now)).." left | players="..tostring(count).." | joins="..tostring(host.joinEvents or 0)
            if count>=30 then startup.self_diag.finish_host_observation_now("Reached 30 players"); return end
        end
        local deadline=(tonumber(host.startedAtMs or now) or now)+(tonumber(sd.hostWindowMs or 600000) or 600000)
        if now >= deadline then startup.self_diag.finish_host_observation_now("Completed") end
        return
    end
end

function startup.self_diag.copy_report_path()
    local path=tostring(sd.latestReportPath or startup.s.selfDiagLastReportPath or "")
    if path=="" then startup.toast("No Self Diagnosis report has been saved yet.",3000); return false end
    local ok=startup.copy_to_clipboard(path); startup.toast(ok and "Self Diagnosis report path copied." or "Could not copy report path.",3000); return ok
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- matchmaking advertise flow
-- note: starts, scales, pauses, and resumes public-session advertising.
-- ═══════════════════════════════════════════════════════════════════════════════════

local function startup_normalize_advertise_label(value)
    return tostring(value or ""):lower():gsub("[^%w]", "")
end

-- Cherax list-returning APIs can expose numeric keys starting at either 0 or 1.
-- Convert both layouts into stable entries while preserving the real Cherax list index.
local function startup_region_list_entries(list)
    local entries, rows = {}, {}
    if type(list) ~= "table" then return entries end

    local insertion = 0
    for key, item in pairs(list) do
        if item ~= nil then
            insertion = insertion + 1
            rows[#rows + 1] = {
                rawKey = key,
                numericKey = tonumber(key),
                label = tostring(item),
                insertion = insertion
            }
        end
    end

    table.sort(rows, function(a, b)
        if a.numericKey ~= nil and b.numericKey ~= nil then
            if a.numericKey == b.numericKey then return a.insertion < b.insertion end
            return a.numericKey < b.numericKey
        end
        if a.numericKey ~= nil then return true end
        if b.numericKey ~= nil then return false end
        return a.insertion < b.insertion
    end)

    local zeroBased = false
    for _, row in ipairs(rows) do
        if row.numericKey ~= nil and math.floor(row.numericKey) == 0 then
            zeroBased = true
            break
        end
    end

    for position, row in ipairs(rows) do
        local listIndex = position - 1
        if row.numericKey ~= nil then
            local numericKey = math.floor(row.numericKey)
            listIndex = zeroBased and numericKey or (numericKey - 1)
            if listIndex < 0 then listIndex = position - 1 end
        end
        entries[#entries + 1] = {
            label = row.label,
            listIndex = listIndex,
            rawKey = row.rawKey
        }
    end
    return entries
end

local function startup_region_list_contains(list, wanted)
    local wantedNormalized = startup_normalize_advertise_label(wanted)
    local aliases = {
        northernasia = {northernasia=true, northasia=true},
        southamerica = {southamerica=true, latinamerica=true},
        usaeast = {usaeast=true, useast=true, americaeast=true, northamericaeast=true},
        usawest = {usawest=true, uswest=true, americawest=true, northamericawest=true},
        europe = {europe=true, eu=true},
        asia = {asia=true},
        australia = {australia=true, oceania=true},
        japan = {japan=true}
    }
    local wantedAliases = aliases[wantedNormalized]
    for _, entry in ipairs(startup_region_list_entries(list)) do
        local entryNormalized = startup_normalize_advertise_label(entry.label)
        if entryNormalized == wantedNormalized or (wantedAliases and wantedAliases[entryNormalized] == true) then
            return entry.listIndex, tostring(entry.label)
        end
    end
    return nil
end

local function startup_region_label_for_index(list, wantedIndex)
    wantedIndex = tonumber(wantedIndex)
    if wantedIndex == nil then return nil end
    for _, entry in ipairs(startup_region_list_entries(list)) do
        if tonumber(entry.listIndex) == wantedIndex then return tostring(entry.label) end
    end
    return nil
end

local function startup_normalize_feature_hash(value)
    local hash = tonumber(value)
    if hash == nil then return nil end
    hash = math.floor(hash)
    if hash < 0 then hash = hash + 4294967296 end
    if hash <= 0 or hash > 4294967295 then return nil end
    return hash
end

local function startup_region_feature_type(feature)
    if not feature or not feature.GetType then return nil end
    return feature:GetType()
end

local function startup_region_is_list_feature_type(featureType)
    if featureType == nil or not eFeatureType then return false end
    local names = { "Combo", "ComboToggles", "List", "ListWithInfo" }
    for _, name in ipairs(names) do
        if eFeatureType[name] ~= nil and featureType == eFeatureType[name] then return true end
    end
    return false
end

local function startup_region_known_label_for_index(index)
    index = tonumber(index)
    if index == nil then return nil end
    return (startup.advertise_region_current_names or {})[index]
end

local function startup_region_feature_snapshot(feature, expectedName)
    if not feature then return nil, "feature was nil" end

    local hash = nil
    if feature.GetHash then hash = startup_normalize_feature_hash(feature:GetHash()) end

    local expected = tostring(expectedName or "")
    local name = expected
    if feature.GetName then
        local raw = feature:GetName(false)
        if raw ~= nil and tostring(raw) ~= "" then name = tostring(raw) end
    elseif feature.Name ~= nil and tostring(feature.Name) ~= "" then
        name = tostring(feature.Name)
    end

    local featureType = startup_region_feature_type(feature)
    local listCapable = startup_region_is_list_feature_type(featureType)
    local list = nil
    if listCapable and feature.GetList then
        local rawList = feature:GetList()
        if type(rawList) == "table" then list = rawList end
    end
    local entries = startup_region_list_entries(list)

    local currentIndex = nil
    if listCapable and feature.GetListIndex then
        currentIndex = tonumber(feature:GetListIndex())
    end

    local currentString = nil
    if listCapable and hash and FeatureMgr and FeatureMgr.GetCurrentFeatureListString then
        local value = FeatureMgr.GetCurrentFeatureListString(hash)
        if value ~= nil and tostring(value) ~= "" then currentString = tostring(value) end
    end
    if (currentString == nil or currentString == "") and currentIndex ~= nil then
        currentString = startup_region_label_for_index(list, currentIndex)
            or startup_region_known_label_for_index(currentIndex)
    end

    local europeIndex = startup_region_list_contains(list, "Europe")
    local normalizedExpected = startup_normalize_advertise_label(expected)
    local exactAdvertiseName = normalizedExpected ~= ""
        and normalizedExpected:find("advertis", 1, true) ~= nil
        and normalizedExpected:find("region", 1, true) ~= nil
    local liveName = startup_normalize_advertise_label(name)
    local liveAdvertiseName = liveName:find("advertis", 1, true) ~= nil
        and liveName:find("region", 1, true) ~= nil

    if #entries >= 2 and (europeIndex ~= nil or exactAdvertiseName or liveAdvertiseName) then
        return {
            feature = feature,
            hash = hash,
            list = list,
            entries = entries,
            name = name ~= "" and name or "Advertise Region",
            featureType = featureType,
            listCapable = listCapable,
            currentIndex = currentIndex,
            currentString = currentString,
            nativeOnly = false
        }, "accepted live list with " .. tostring(#entries) .. " choices"
    end

    -- Current EE builds may expose the exact native list feature while withholding
    -- its list entries from Lua. Accept that targeted control without calling
    -- string-only feature methods. The native Cherax control remains authoritative.
    if exactAdvertiseName or liveAdvertiseName then
        return {
            feature = feature,
            hash = hash,
            list = list,
            entries = entries,
            name = name ~= "" and name or "Advertise Region",
            featureType = featureType,
            listCapable = listCapable,
            currentIndex = currentIndex,
            currentString = currentString,
            nativeOnly = true
        }, "accepted exact native control; type=" .. tostring(featureType)
            .. " choices=" .. tostring(#entries)
            .. " current=" .. tostring(currentString or "native")
    end

    return nil, "name=" .. tostring(name ~= "" and name or "unknown")
        .. " hash=" .. tostring(hash or "none")
        .. " type=" .. tostring(featureType or "unknown")
        .. " listCapable=" .. tostring(listCapable)
        .. " choices=" .. tostring(#entries)
        .. " europe=" .. tostring(europeIndex ~= nil)
        .. " current=" .. tostring(currentString or "none")
end
local function startup_region_hash_snapshot(value)
    local hash = startup_normalize_feature_hash(value)
    if not hash or not FeatureMgr or not FeatureMgr.GetFeature then return nil end

    local expectedName = nil
    for _, knownHash in ipairs(startup.advertise_region_known_hashes or {}) do
        if startup_normalize_feature_hash(knownHash) == hash then
            expectedName = "Advertise Region"
            break
        end
    end

    local feature = FeatureMgr.GetFeature(hash)
    if not feature then return nil end
    local snap = startup_region_feature_snapshot(feature, expectedName)
    if snap then
        snap.hash = snap.hash or hash
        return snap
    end
    return nil
end

local function startup_commit_advertise_region_candidate(candidate, source)
    if not candidate then return nil, nil, nil end
    local cache = startup.advertise_region_cache or {}
    startup.advertise_region_cache = cache
    cache.hash = candidate.hash
    cache.feature = candidate.feature
    cache.list = candidate.list
    cache.entries = candidate.entries or startup_region_list_entries(candidate.list)
    cache.nativeOnly = candidate.nativeOnly == true
    cache.featureType = candidate.featureType
    cache.listCapable = candidate.listCapable == true
    cache.currentIndex = candidate.currentIndex
    cache.currentString = candidate.currentString
    cache.source = tostring(source or "validated Advertise Region")
    cache.name = tostring(candidate.name or "Advertise Region")
    cache.scanRunning = false
    cache.lastScanStatus = "Resolved via " .. cache.source
    cache.nextRetryMs = 0
    startup.s.advertiseRegionHash = candidate.hash
    startup.s.advertiseRegionSource = cache.source
    startup.s.advertiseRegionResolution = "Resolved: " .. cache.name
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("ADVERTISE_REGION_RESOLVED", "name=" .. tostring(cache.name)
            .. " hash=" .. tostring(cache.hash or "unknown")
            .. " type=" .. tostring(cache.featureType or "unknown")
            .. " choices=" .. tostring(#(cache.entries or {}))
            .. " nativeOnly=" .. tostring(cache.nativeOnly)
            .. " source=" .. tostring(cache.source))
    end
    startup.print_advertise_region_summary(false)
    return cache.feature, cache.hash, cache.list
end

local function startup_validate_cached_advertise_region()
    local cache = startup.advertise_region_cache or {}
    if cache.feature then
        local snap = startup_region_feature_snapshot(cache.feature, cache.name or "Advertise Region")
        if snap then
            snap.hash = snap.hash or cache.hash
            cache.hash = snap.hash
            cache.list = snap.list
            cache.entries = snap.entries
            cache.nativeOnly = snap.nativeOnly == true
            cache.featureType = snap.featureType
            cache.listCapable = snap.listCapable == true
            cache.currentIndex = snap.currentIndex
            cache.currentString = snap.currentString
            cache.name = snap.name
            startup.s.advertiseRegionHash = cache.hash
            startup.s.advertiseRegionSource = tostring(cache.source or "cached targeted feature")
            startup.s.advertiseRegionResolution = "Resolved: " .. tostring(cache.name or "Advertise Region")
            return cache.feature, cache.hash, cache.list
        end
    end
    if cache.hash then
        local snap = startup_region_hash_snapshot(cache.hash)
        if snap then
            snap.feature = snap.feature or cache.feature
            cache.feature = snap.feature
            cache.list = snap.list
            cache.entries = snap.entries
            cache.nativeOnly = snap.nativeOnly == true
            cache.featureType = snap.featureType
            cache.listCapable = snap.listCapable == true
            cache.currentIndex = snap.currentIndex
            cache.currentString = snap.currentString
            cache.name = snap.name
            startup.s.advertiseRegionHash = cache.hash
            startup.s.advertiseRegionSource = tostring(cache.source or "cached hash")
            startup.s.advertiseRegionResolution = "Resolved: " .. tostring(cache.name or "Advertise Region")
            return cache.feature, cache.hash, cache.list
        end
    end
    cache.feature = nil
    cache.hash = nil
    cache.list = nil
    cache.entries = nil
    return nil, nil, nil
end

function startup.request_advertise_region_resolution(force, reason)
    if not startup.is_enhanced_active_edition() then return false end
    local cache = startup.advertise_region_cache or {}
    startup.advertise_region_cache = cache
    local now = startup.now()
    if force == true then cache.nextRetryMs = 0 end
    if startup.pendingAdvertiseRegionResolve == true or startup.advertiseRegionJobQueued == true then return true end
    if force ~= true and now < (tonumber(cache.nextRetryMs or 0) or 0) then return false end
    startup.pendingAdvertiseRegionResolve = true
    cache.lastScanStatus = "Queued: " .. tostring(reason or "Advertise Region requested")
    startup.s.advertiseRegionResolution = "Queued for scripting worker"
    startup.s.advertiseRegionSource = tostring(reason or "worker request")
    return true
end

function startup.run_advertise_region_resolution_now()

    if not startup.is_enhanced_active_edition() then
        startup.s.advertiseRegionResolution = "Not used on Legacy"
        startup.s.advertiseRegionSource = "Not used on Legacy"
        return
    end

    local cache = startup.advertise_region_cache or {}
    startup.advertise_region_cache = cache
    cache.scanRunning = true
    cache.scanAttempts = (tonumber(cache.scanAttempts or 0) or 0) + 1
    cache.hashesChecked = 0
    cache.lastScanStatus = "Resolving targeted Advertise Region feature"
    startup.s.advertiseCountResolution = "Not used on Enhanced"
    startup.s.advertiseRegionResolution = "Resolving targeted feature"

    -- Primary path: this is the exact documented API Build 080 used successfully.
    -- Only the named Advertise Region control is touched; the full feature tree is never enumerated.
    if FeatureMgr and FeatureMgr.GetFeatureByName then
        for _, name in ipairs(startup.advertise_region_names or {}) do
            local okFeature, feature = direct_call(function() return FeatureMgr.GetFeatureByName(name) end)
            if okFeature and feature then
                local snap, probeStatus = startup_region_feature_snapshot(feature, name)
                cache.lastTargetedProbe = tostring(name) .. ": " .. tostring(probeStatus or "no details")
                if snap then
                    cache.scanRunning = false
                    local resolvedFeature, resolvedHash, resolvedList = startup_commit_advertise_region_candidate(snap, "GetFeatureByName: " .. tostring(name))
                    if startup.s.advertiseRegionDefaultPending == true then startup.apply_ee_advertise_region_default() end
                    if startup.update_hud_cache then startup.update_hud_cache(true) end
                    return resolvedFeature, resolvedHash, resolvedList
                end
            elseif not okFeature then
                cache.lastTargetedProbe = tostring(name) .. ": GetFeatureByName raised an error"
            end
        end
    end

    local seen = {}
    local function try_hash(value, source)
        local hash = startup_normalize_feature_hash(value)
        if not hash or seen[hash] then return nil end
        seen[hash] = true
        cache.hashesChecked = cache.hashesChecked + 1
        local snap = startup_region_hash_snapshot(hash)
        if snap then return startup_commit_advertise_region_candidate(snap, source) end
        return nil
    end

    -- Known current EE hash from the previously confirmed working native control.
    for _, knownHash in ipairs(startup.advertise_region_known_hashes or {}) do
        local feature, hash, list = try_hash(knownHash, "known EE Advertise Region hash")
        if feature or hash then
            cache.scanRunning = false
            if startup.s.advertiseRegionDefaultPending == true then startup.apply_ee_advertise_region_default() end
            if startup.update_hud_cache then startup.update_hud_cache(true) end
            return feature, hash, list
        end
    end

    -- Secondary path: documented integer-hash search only.
    if FeatureMgr and FeatureMgr.SearchFeature then
        local searches = { "Advertise Region", "Advertisement Region", "Advertising Region", "Advertise", "Europe" }
        for _, query in ipairs(searches) do
            local okSearch, results = direct_call(function() return FeatureMgr.SearchFeature(query, 128, 0.0) end)
            if okSearch and type(results) == "table" then
                for key, value in pairs(results) do
                    local feature, hash, list = try_hash(value, "SearchFeature value: " .. query)
                    if feature or hash then
                        cache.scanRunning = false
                        if startup.s.advertiseRegionDefaultPending == true then startup.apply_ee_advertise_region_default() end
                        if startup.update_hud_cache then startup.update_hud_cache(true) end
                        return feature, hash, list
                    end
                    feature, hash, list = try_hash(key, "SearchFeature key: " .. query)
                    if feature or hash then
                        cache.scanRunning = false
                        if startup.s.advertiseRegionDefaultPending == true then startup.apply_ee_advertise_region_default() end
                        if startup.update_hud_cache then startup.update_hud_cache(true) end
                        return feature, hash, list
                    end
                end
            end
        end
    end


    cache.scanRunning = false
    cache.feature = nil
    cache.hash = nil
    cache.list = nil
    cache.entries = nil
    cache.nextRetryMs = startup.now() + 30000
    cache.lastScanStatus = "Targeted names failed; no valid region list found after " .. tostring(cache.hashesChecked or 0) .. " hash checks"
        .. (cache.lastTargetedProbe and (" | last probe: " .. tostring(cache.lastTargetedProbe)) or "")
    startup.s.advertiseRegionHash = nil
    startup.s.advertiseRegionSource = cache.lastScanStatus
    startup.s.advertiseRegionResolution = "Unavailable; retry queued in 30 seconds"
    return nil, nil, nil
end

function startup.process_pending_advertise_region_resolution()
    if startup.pendingAdvertiseRegionResolve ~= true or startup.advertiseRegionJobQueued == true then return end
    startup.pendingAdvertiseRegionResolve = false
    startup.advertiseRegionJobQueued = true

    local function job()
        -- Clear this before entering the resolver. A future native feature mismatch
        -- may terminate only this isolated job, while Startup's main worker continues.
        startup.advertiseRegionJobQueued = false
        startup.run_advertise_region_resolution_now()
    end

    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
end

local function startup_get_advertise_region_target(force)
    if not startup.is_enhanced_active_edition() then
        startup.s.advertiseRegionResolution = "Not used on Legacy"
        startup.s.advertiseRegionSource = "Not used on Legacy"
        return nil, nil, nil
    end
    startup.s.advertiseCountResolution = "Not used on Enhanced"

    local feature, hash, list = startup_validate_cached_advertise_region()
    if feature or hash then return feature, hash, list end

    startup.request_advertise_region_resolution(force == true, force == true and "manual refresh" or "region requested")
    return nil, nil, nil
end

function startup.get_advertise_region_hash(force)
    local _, hash, list = startup_get_advertise_region_target(force == true)
    return hash, list
end

function startup.get_advertise_region_feature(force)
    local feature, hash = startup_get_advertise_region_target(force == true)
    if feature then return feature, "targeted feature" end
    if hash and FeatureMgr and FeatureMgr.GetFeature then
        local ok, resolved = direct_call(function() return FeatureMgr.GetFeature(hash) end)
        if ok and resolved then return resolved, "hash " .. tostring(hash) end
    end
    return nil, nil
end

local function startup_get_live_advertise_region_index(feature, hash)
    local cache = startup.advertise_region_cache or {}
    local listCapable = cache.listCapable == true
    if feature and not listCapable then
        listCapable = startup_region_is_list_feature_type(startup_region_feature_type(feature))
    end
    if not listCapable then return nil end

    if feature and feature.GetListIndex then
        local value = feature:GetListIndex()
        if tonumber(value) ~= nil then
            cache.currentIndex = tonumber(value)
            return tonumber(value)
        end
    end
    if hash and FeatureMgr and FeatureMgr.GetFeatureListIndex then
        local value = FeatureMgr.GetFeatureListIndex(hash)
        if tonumber(value) ~= nil then
            cache.currentIndex = tonumber(value)
            return tonumber(value)
        end
    end
    return nil
end

function startup.get_advertise_region_label(force)
    if not startup.is_enhanced_active_edition() then return "Not used on Legacy" end
    local feature, hash, list = startup_get_advertise_region_target(force == true)
    if not feature and not hash then
        startup.s.advertiseRegionLabel = "Unknown"
        return startup.s.advertiseRegionLabel
    end

    local cache = startup.advertise_region_cache or {}
    local label = nil
    local index = startup_get_live_advertise_region_index(feature, hash)
    if index ~= nil then
        label = startup_region_label_for_index(list, index)
            or startup_region_known_label_for_index(index)
    end

    if (label == nil or tostring(label) == "")
        and cache.listCapable == true
        and hash
        and FeatureMgr
        and FeatureMgr.GetCurrentFeatureListString then
        local value = FeatureMgr.GetCurrentFeatureListString(hash)
        if value ~= nil and tostring(value) ~= "" then label = value end
    end
    if (label == nil or tostring(label) == "") and cache.currentString ~= nil and tostring(cache.currentString) ~= "" then
        label = cache.currentString
    end
    if (label == nil or tostring(label) == "") and cache.nativeOnly == true then
        label = "Native control"
    end

    label = tostring(label or "Unknown")
    if label == "" then label = "Unknown" end
    cache.currentIndex = index
    if label ~= "Unknown" and label ~= "Native control" then cache.currentString = label end
    startup.s.advertiseRegionLabel = label
    return label
end

local function startup_day_of_week_sunday_zero(year, month, day)
    year = math.floor(tonumber(year or 1970) or 1970)
    month = math.floor(tonumber(month or 1) or 1)
    day = math.floor(tonumber(day or 1) or 1)
    local offsets = {0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4}
    if month < 3 then year = year - 1 end
    return (year + math.floor(year / 4) - math.floor(year / 100) + math.floor(year / 400) + offsets[month] + day) % 7
end

local function startup_nth_sunday_of_month(year, month, nth)
    local firstWeekday = startup_day_of_week_sunday_zero(year, month, 1)
    local firstSunday = 1 + ((7 - firstWeekday) % 7)
    return firstSunday + (math.max(1, math.floor(tonumber(nth or 1) or 1)) - 1) * 7
end

function startup.get_local_clock_info(epoch)
    epoch = tonumber(epoch or os.time()) or os.time()
    local current = os.date("*t", epoch)
    if type(current) ~= "table" then
        return { hour = 0, minute = 0, totalMinutes = 0, display = "12:00 AM" }
    end
    local hour = tonumber(current.hour or 0) or 0
    local minute = tonumber(current.min or 0) or 0
    return {
        hour = hour,
        minute = minute,
        totalMinutes = (hour * 60) + minute,
        display = startup.format_clock_time_12h(hour, minute)
    }
end

function startup.normalize_advertise_region_schedule_mode(value)
    value = tostring(value or "All Regions")
    if value == "USA / Europe" then return "USA / Europe" end
    if value == "Manually Pick a Region" then return "Manually Pick a Region" end
    return "All Regions"
end

function startup.normalize_manual_advertise_region(value)
    value = tostring(value or "Europe")
    if startup.advertise_region_manual_choice_set[value] == true then return value end
    return "Europe"
end

function startup.sync_advertise_region_schedule_toggles()
    if not startup.h then return end
    local previousSync = startup.s.syncingFeatureStates == true
    startup.s.syncingFeatureStates = true
    local mode = startup.normalize_advertise_region_schedule_mode(startup.s.advertiseRegionAutoScheduleMode)
    startup.set_feature_bool_silently(startup.h.AdvertiseUsaEuropeByTime, startup.is_enhanced_active_edition() and mode == "USA / Europe")
    startup.set_feature_bool_silently(startup.h.AdvertiseAllRegionsByTime, startup.is_enhanced_active_edition() and mode == "All Regions")
    startup.set_feature_bool_silently(startup.h.AdvertiseManualRegion, startup.is_enhanced_active_edition() and mode == "Manually Pick a Region")
    startup.set_feature_list_string_silently(startup.h.AdvertiseManualRegionSelection, startup.s.advertiseRegionManualSelection or "Europe")
    startup.set_feature_bool_silently(startup.h.AutoAdvertiseRegionByTime, startup.is_enhanced_active_edition() and mode ~= "Manually Pick a Region")
    startup.set_feature_list_string_silently(startup.h.AdvertiseRegionScheduleMode, mode)
    startup.s.syncingFeatureStates = previousSync
end

function startup.select_manual_advertise_region(region, persist)
    region = startup.normalize_manual_advertise_region(region)
    startup.s.advertiseRegionManualSelection = region
    startup.set_feature_list_string_silently(startup.h and startup.h.AdvertiseManualRegionSelection, region)

    if startup.is_enhanced_active_edition()
        and startup.normalize_advertise_region_schedule_mode(startup.s.advertiseRegionAutoScheduleMode) == "Manually Pick a Region" then
        startup.s.advertiseRegionAutoScheduleEnabled = false
        startup.s.advertiseRegionAutoScheduleStatus = "Manual region: " .. region
        startup.s.advertiseRegionAutoScheduleLastRequestedRegion = ""
        startup.request_advertise_region_change(region, true)
        startup.request_advertise_region_resolution(false, "manual region selected")
    end

    if persist == true and startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
    return region
end

function startup.select_advertise_region_schedule_mode(mode, reason, persist)
    mode = startup.normalize_advertise_region_schedule_mode(mode)
    startup.s.advertiseRegionAutoScheduleMode = mode
    startup.s.advertiseRegionAutoScheduleEnabled = startup.is_enhanced_active_edition() and mode ~= "Manually Pick a Region"
    startup.s.advertiseRegionAutoScheduleDefaultVersion = startup.advertise_region_schedule_default_version
    startup.s.advertiseRegionAutoScheduleModeDefaultVersion = startup.advertise_region_schedule_mode_default_version
    startup.s.advertiseRegionAutoScheduleNextCheckMs = 0
    startup.s.advertiseRegionAutoScheduleLastRequestedRegion = ""

    if mode == "Manually Pick a Region" then
        -- Preserve the user's saved manual choice when moving between modes.
        -- This makes returning to manual mode deterministic instead of replacing
        -- their choice with whichever timed region happened to be active.
        startup.s.advertiseRegionManualSelection = startup.normalize_manual_advertise_region(startup.s.advertiseRegionManualSelection)
        startup.s.advertiseRegionAutoScheduleStatus = "Manual region: " .. tostring(startup.s.advertiseRegionManualSelection)
    else
        startup.s.advertiseRegionAutoScheduleStatus = "Using " .. mode
    end

    startup.sync_advertise_region_schedule_toggles()

    if startup.is_enhanced_active_edition() then
        if mode == "Manually Pick a Region" then
            local manualRegion = startup.normalize_manual_advertise_region(startup.s.advertiseRegionManualSelection)
            startup.request_advertise_region_change(manualRegion, true)
            startup.request_advertise_region_resolution(false, tostring(reason or "manual advertise region mode"))
        elseif startup.s.advertiseRegionAutoScheduleEnabled == true then
            local schedule = startup.get_advertise_region_time_schedule(os.time(), mode)
            startup.s.advertiseRegionAutoScheduleLastRequestedRegion = tostring(schedule.region or "")
            startup.s.advertiseRegionAutoScheduleStatus = "Queued " .. tostring(schedule.region or "scheduled region")
            startup.request_advertise_region_change(tostring(schedule.region or "Europe"), false)
            startup.request_advertise_region_resolution(false, tostring(reason or "advertise schedule changed"))
        end
    end
    if persist == true and startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
    return mode
end

function startup.get_advertise_region_time_schedule(epoch, requestedMode)
    local clock = startup.get_local_clock_info(epoch)
    local minute = tonumber(clock.totalMinutes or 0) or 0
    local mode = startup.normalize_advertise_region_schedule_mode(requestedMode or startup.s.advertiseRegionAutoScheduleMode)
    local region, window, nextMinute, nextRegion, summary

    if mode == "Manually Pick a Region" then
        region = startup.normalize_manual_advertise_region(startup.s.advertiseRegionManualSelection)
        return {
            mode = mode,
            region = region,
            window = "Manual selection",
            summary = "Manual region: " .. region,
            clock = clock,
            nextRegion = region,
            nextSwitch = "Manual",
            minutesUntilSwitch = 0
        }
    end

    if mode == "USA / Europe" then
        if minute < 540 then
            region = "Europe"
            window = "12:00 AM-8:59 AM"
            nextMinute = 540
            nextRegion = "USA East"
        elseif minute < 960 then
            region = "USA East"
            window = "9:00 AM-3:59 PM"
            nextMinute = 960
            nextRegion = "USA West"
        else
            region = "USA West"
            window = "4:00 PM-11:59 PM"
            nextMinute = 1440
            nextRegion = "Europe"
        end
        summary = "Europe 12:00 AM-8:59 AM | USA East 9:00 AM-3:59 PM | USA West 4:00 PM-11:59 PM"
    else
        if minute < 120 then
            region = "Australia"
            window = "12:00 AM-1:59 AM"
            nextMinute = 120
            nextRegion = "Japan"
        elseif minute < 240 then
            region = "Japan"
            window = "2:00 AM-3:59 AM"
            nextMinute = 240
            nextRegion = "Northern Asia"
        elseif minute < 360 then
            region = "Northern Asia"
            window = "4:00 AM-5:59 AM"
            nextMinute = 360
            nextRegion = "Asia"
        elseif minute < 540 then
            region = "Asia"
            window = "6:00 AM-8:59 AM"
            nextMinute = 540
            nextRegion = "Europe"
        elseif minute < 780 then
            region = "Europe"
            window = "9:00 AM-12:59 PM"
            nextMinute = 780
            nextRegion = "South America"
        elseif minute < 960 then
            region = "South America"
            window = "1:00 PM-3:59 PM"
            nextMinute = 960
            nextRegion = "USA East"
        elseif minute < 1140 then
            region = "USA East"
            window = "4:00 PM-6:59 PM"
            nextMinute = 1140
            nextRegion = "USA West"
        else
            region = "USA West"
            window = "7:00 PM-11:59 PM"
            nextMinute = 1440
            nextRegion = "Australia"
        end
        summary = "Australia 12:00-1:59 AM | Japan 2:00-3:59 AM | Northern Asia 4:00-5:59 AM | Asia 6:00-8:59 AM | Europe 9:00 AM-12:59 PM | South America 1:00-3:59 PM | USA East 4:00-6:59 PM | USA West 7:00-11:59 PM"
    end

    local minutesUntil = nextMinute - minute
    if minutesUntil <= 0 then minutesUntil = minutesUntil + 1440 end
    local nextClockMinute = nextMinute % 1440
    local nextHour = math.floor(nextClockMinute / 60)
    local nextMin = nextClockMinute % 60
    return {
        mode = mode,
        region = region,
        window = window,
        summary = summary,
        clock = clock,
        nextRegion = nextRegion,
        nextSwitch = startup.format_clock_time_12h(nextHour, nextMin),
        minutesUntilSwitch = minutesUntil
    }
end

function startup.update_advertise_region_auto_schedule(force, reason)
    if not startup.is_enhanced_active_edition() then
        startup.s.advertiseRegionAutoScheduleStatus = "Not used on Legacy"
        return false
    end
    if startup.s.advertiseRegionAutoScheduleEnabled ~= true then
        startup.s.advertiseRegionAutoScheduleStatus = "Manual region: "
            .. tostring(startup.normalize_manual_advertise_region(startup.s.advertiseRegionManualSelection))
        return false
    end

    local schedule = startup.get_advertise_region_time_schedule(os.time())
    local desired = tostring(schedule.region or "Europe")
    local current = tostring(startup.get_advertise_region_label(false) or "Unknown")
    local sameRegion = startup_normalize_advertise_label(current) == startup_normalize_advertise_label(desired)
    startup.s.advertiseRegionAutoScheduleLastRegion = desired

    if sameRegion and force ~= true then
        startup.s.advertiseRegionAutoScheduleLastRequestedRegion = ""
        startup.s.advertiseRegionAutoScheduleStatus = desired .. " active at " .. tostring(schedule.clock.display)
            .. "; next " .. tostring(schedule.nextRegion) .. " at " .. tostring(schedule.nextSwitch)
        return true
    end

    if startup.pendingAdvertiseRegionName ~= nil and tostring(startup.pendingAdvertiseRegionName) ~= "" then
        startup.s.advertiseRegionAutoScheduleStatus = "Waiting for pending region change to " .. tostring(startup.pendingAdvertiseRegionName)
        return false
    end

    local lastRequested = tostring(startup.s.advertiseRegionAutoScheduleLastRequestedRegion or "")
    if force ~= true and startup_normalize_advertise_label(lastRequested) == startup_normalize_advertise_label(desired) then
        startup.s.advertiseRegionAutoScheduleStatus = "Waiting for " .. desired .. " to apply"
        return false
    end

    startup.s.advertiseRegionAutoScheduleLastRequestedRegion = desired
    startup.s.advertiseRegionAutoScheduleStatus = "Queued " .. desired .. " at " .. tostring(schedule.clock.display)
    startup.request_advertise_region_change(desired, false)
    return true
end

function startup.process_advertise_region_auto_schedule()
    if startup.s.advertiseRegionAutoScheduleEnabled ~= true then return end
    local now = startup.now()
    if now < (tonumber(startup.s.advertiseRegionAutoScheduleNextCheckMs or 0) or 0) then return end
    startup.s.advertiseRegionAutoScheduleNextCheckMs = now + 30000
    startup.update_advertise_region_auto_schedule(false, "30-second schedule check")
end

local function startup_apply_advertise_region_now(wanted, markAsUserChoice)
    if not startup.is_enhanced_active_edition() then return false end
    local previousLabel = tostring(startup.get_advertise_region_label(false) or startup.s.advertiseRegionLabel or "Unknown")
    local feature, hash, list = startup_get_advertise_region_target(false)
    if not feature and not hash then return false end

    local cache = startup.advertise_region_cache or {}
    local index, actualName = startup_region_list_contains(list, wanted)
    if index == nil and cache.nativeOnly == true and cache.listCapable == true then
        local normalizedWanted = startup_normalize_advertise_label(wanted)
        local nativeIndexByLabel = {
            myregion = 0,
            northernasia = 1,
            africa = 2,
            eastamerica = 3,
            usaeast = 3,
            europe = 4,
            china = 5,
            australia = 6,
            westamerica = 7,
            usawest = 7,
            japan = 8,
            unknown = 9
        }
        index = nativeIndexByLabel[normalizedWanted]
        if index ~= nil then actualName = startup_region_known_label_for_index(index) end
    end
    if index == nil then return false end

    local okSet = direct_call(function()
        if feature and feature.SetListIndex then
            feature:SetListIndex(index)
            if feature.TriggerCallback then feature:TriggerCallback()
            elseif feature.OnClick then feature:OnClick() end
        elseif hash and FeatureMgr and FeatureMgr.SetFeatureListIndex then
            FeatureMgr.SetFeatureListIndex(hash, index)
            if FeatureMgr.TriggerFeatureCallback then FeatureMgr.TriggerFeatureCallback(hash) end
        else
            error("Advertise Region has no supported setter")
        end
    end)
    if not okSet then
        startup.s.advertiseRegionDefaultStatus = "Region callback failed for " .. tostring(actualName or wanted)
        return false
    end

    startup.s.advertiseRegionLabel = tostring(actualName or wanted)
    startup.s.advertiseRegionResolution = "Resolved: " .. tostring((startup.advertise_region_cache or {}).name or "Advertise Region")
    if startup.normalize_advertise_region_schedule_mode(startup.s.advertiseRegionAutoScheduleMode) == "Manually Pick a Region" then
        startup.s.advertiseRegionManualSelection = startup.normalize_manual_advertise_region(startup.s.advertiseRegionLabel)
        startup.s.advertiseRegionAutoScheduleStatus = "Manual region: " .. startup.s.advertiseRegionManualSelection
    end
    if startup.s.advertiseRegionAutoScheduleEnabled == true then
        startup.s.advertiseRegionAutoScheduleLastRegion = startup.s.advertiseRegionLabel
        startup.s.advertiseRegionAutoScheduleLastRequestedRegion = ""
        local activeSchedule = startup.get_advertise_region_time_schedule(os.time())
        startup.s.advertiseRegionAutoScheduleStatus = startup.s.advertiseRegionLabel .. " active at "
            .. tostring(activeSchedule.clock.display) .. "; next " .. tostring(activeSchedule.nextRegion)
            .. " at " .. tostring(activeSchedule.nextSwitch)
    end
    if markAsUserChoice == true then
        startup.s.advertiseRegionDefaultVersion = startup.advertise_region_default_version
        startup.s.advertiseRegionDefaultPending = false
        startup.s.advertiseRegionDefaultStatus = "Manual region saved: " .. startup.s.advertiseRegionLabel
        startup.save_config(false)
    end
    if startup.update_hud_cache then startup.update_hud_cache(true) end
    local previousNormalized = startup_normalize_advertise_label(previousLabel)
    local currentNormalized = startup_normalize_advertise_label(startup.s.advertiseRegionLabel)
    if previousNormalized ~= "" and previousNormalized ~= "unknown" and previousNormalized ~= currentNormalized then
        startup.log_colored("[Region] Enhanced Advertise Region changed from " .. previousLabel
            .. " to " .. startup.s.advertiseRegionLabel .. "!", "success")
    end
    return true
end

function startup.request_advertise_region_change(wanted, markAsUserChoice)
    if not startup.is_enhanced_active_edition() then return false end
    startup.pendingAdvertiseRegionName = tostring(wanted or "")
    startup.pendingAdvertiseRegionUserChoice = markAsUserChoice == true
    startup.s.advertiseRegionDefaultStatus = "Queued region change: " .. tostring(wanted or "")
    return startup.pendingAdvertiseRegionName ~= ""
end

function startup.run_advertise_region_change_now()
    local wanted = startup.pendingAdvertiseRegionName
    if wanted == nil or tostring(wanted) == "" then return end
    local markAsUserChoice = startup.pendingAdvertiseRegionUserChoice == true
    startup.pendingAdvertiseRegionName = nil
    startup.pendingAdvertiseRegionUserChoice = false

    if not startup_apply_advertise_region_now(wanted, markAsUserChoice) then
        startup.s.advertiseRegionDefaultStatus = "Region change pending; resolver is not ready for " .. tostring(wanted)
        startup.request_advertise_region_resolution(false, "queued region change")
        startup.pendingAdvertiseRegionName = tostring(wanted)
        startup.pendingAdvertiseRegionUserChoice = markAsUserChoice
    end
end

function startup.process_pending_advertise_region_change()
    if startup.pendingAdvertiseRegionName == nil or tostring(startup.pendingAdvertiseRegionName) == "" then return end
    if startup.advertiseRegionChangeJobQueued == true then return end
    startup.advertiseRegionChangeJobQueued = true

    local function job()
        startup.advertiseRegionChangeJobQueued = false
        startup.run_advertise_region_change_now()
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
end

function startup.set_advertise_region_by_name(wanted, markAsUserChoice)
    -- Internal worker calls can apply immediately. ImGui uses request_advertise_region_change below.
    return startup_apply_advertise_region_now(wanted, markAsUserChoice == true)
end

function startup.apply_ee_advertise_region_default()
    if not startup.is_enhanced_active_edition() then
        startup.s.advertiseRegionDefaultPending = false
        startup.s.advertiseRegionDefaultStatus = "Not used on Legacy"
        return true
    end
    if startup.s.advertiseRegionDefaultPending ~= true then return true end
    startup.s.advertiseRegionDefaultAttempts = (tonumber(startup.s.advertiseRegionDefaultAttempts or 0) or 0) + 1
    local desired = "Europe"
    local mode = startup.normalize_advertise_region_schedule_mode(startup.s.advertiseRegionAutoScheduleMode)
    if mode == "Manually Pick a Region" then
        desired = startup.normalize_manual_advertise_region(startup.s.advertiseRegionManualSelection)
    elseif startup.s.advertiseRegionAutoScheduleEnabled == true then
        desired = tostring(startup.get_advertise_region_time_schedule(os.time()).region or "Europe")
    end
    if startup_apply_advertise_region_now(desired, false) then
        startup.s.advertiseRegionDefaultVersion = startup.advertise_region_default_version
        startup.s.advertiseRegionDefaultPending = false
        startup.s.advertiseRegionDefaultStatus = desired .. " applied as the Enhanced startup region"
        startup.s.advertiseRegionAutoScheduleLastRegion = desired
        startup.s.advertiseRegionAutoScheduleLastRequestedRegion = ""
        startup.save_config(false)
        return true
    end
    startup.s.advertiseRegionDefaultStatus = desired .. " pending; targeted Advertise Region feature is not ready yet"
    return false
end

function startup.render_advertise_region_control()
    local mode = startup.normalize_advertise_region_schedule_mode(startup.s.advertiseRegionAutoScheduleMode)
    if mode == "Manually Pick a Region" then
        local selected = startup.normalize_manual_advertise_region(startup.s.advertiseRegionManualSelection)
        local current = tostring(startup.get_advertise_region_label(false) or startup.s.advertiseRegionLabel or "Unknown")
        startup.status_line("Selected Region", selected, 0.72, 0.42, 1.00)
        startup.status_line("Current Region", current, 0.35, 1.00, 0.45)
        startup.subtle_text("Manual region stays active until you choose another mode.")
    else
        local schedule = startup.get_advertise_region_time_schedule(os.time(), mode)
        startup.status_line("Current Region", tostring(schedule.region), 0.35, 1.00, 0.45)
        startup.subtle_text("Region changes automatically using local PC time.")
    end
end
function startup.native_advertise_count_visual_read(feature)
    if not feature then return nil end
    local ok, value = direct_call(function()
        if feature.GetIntValue then return feature:GetIntValue() end
        if feature.GetValue then return feature:GetValue() end
        return nil
    end)
    if not ok then return nil end
    return tonumber(value)
end

function startup.native_advertise_count_visual_set_limits(feature, minimum, maximum)
    if not feature then return false end
    local ok = direct_call(function()
        if feature.SetLimitValues then
            feature:SetLimitValues(minimum, maximum)
        else
            if feature.SetMinValue then feature:SetMinValue(minimum) end
            if feature.SetMaxValue then feature:SetMaxValue(maximum) end
        end
    end)
    return ok == true
end

function startup.native_advertise_count_visual_set_press_callback_disabled(feature, disabled)
    if not feature then return false end
    if feature.SetNoCallbackOnPress then
        local ok = direct_call(function() feature:SetNoCallbackOnPress(disabled == true) end)
        return ok == true
    end
    if feature.SetNoCallbackOnClick then
        local ok = direct_call(function() feature:SetNoCallbackOnClick(disabled == true) end)
        return ok == true
    end
    return false
end

function startup.native_advertise_count_visual_to_actual(displayValue)
    -- The synchronized terminal display treats 0 through 10 as the visual low
    -- range and 11 through 20 as the visual high range. Cherax still receives
    -- only its supported native values 5 or 10.
    return (tonumber(displayValue or 0) or 0) > 10 and 10 or 5
end

function startup.native_advertise_count_visual_to_display(actualValue)
    return (tonumber(actualValue or 5) or 5) >= 10 and 20 or 10
end

function startup.native_advertise_count_visual_capture_original(feature)
    local state = startup.native_advertise_count_visual
    local okLimits, minimum, maximum = direct_call(function()
        if feature.GetIntLimitValues then return feature:GetIntLimitValues() end
        local minValue = feature.GetIntMinValue and feature:GetIntMinValue() or 0
        local maxValue = feature.GetIntMaxValue and feature:GetIntMaxValue() or 10
        return minValue, maxValue
    end)
    if okLimits then
        state.originalMin = tonumber(minimum) or 0
        state.originalMax = tonumber(maximum) or 10
    end
    local okStep, step = direct_call(function()
        if feature.GetStepSize then return feature:GetStepSize() end
        return 1
    end)
    if okStep then state.originalStep = tonumber(step) or 1 end
    local okFast, fast = direct_call(function()
        if feature.GetFastStepSize then return feature:GetFastStepSize() end
        return state.originalStep or 1
    end)
    if okFast then state.originalFastStep = tonumber(fast) or state.originalStep or 1 end
end

function startup.native_advertise_count_visual_configure(force)
    local state = startup.native_advertise_count_visual
    if state.enabled ~= true or startup.is_enhanced_active_edition() then
        state.status = startup.is_enhanced_active_edition() and "Not used on Enhanced" or "Disabled"
        return false
    end
    local now = startup.now()
    if force ~= true and state.configured == true and state.feature ~= nil then return true end
    if force ~= true and now < (tonumber(state.nextResolveMs or 0) or 0) then return false end
    state.nextResolveMs = now + 3000

    local hash = startup.feature_hash and startup.feature_hash.ADVERTISE_COUNT or 4100757571
    local feature, matchedName = startup.find_int_feature_by_names(startup.advertise_count_names, hash)
    if not feature then
        state.configured = false
        state.feature = nil
        state.status = "Native Advertise Count slider unavailable"
        return false
    end

    if state.feature ~= feature or state.configured ~= true then
        startup.native_advertise_count_visual_capture_original(feature)
    end
    if not startup.native_advertise_count_visual_set_press_callback_disabled(feature, true) then
        state.configured = false
        state.feature = nil
        state.status = "Native slider callback suppression unsupported"
        return false
    end

    local rawValue = startup.native_advertise_count_visual_read(feature)
    local actual = tonumber(startup.s.advertiseCurrentCount or 0) or 0
    if actual ~= 5 and actual ~= 10 then
        if rawValue == 5 or rawValue == 10 then
            actual = rawValue
        elseif rawValue == 20 then
            actual = 10
        else
            actual = 5
        end
    end
    local requestedDisplay = tonumber(startup.s.advertiseHudNativeSliderDisplay)
    local display = requestedDisplay ~= nil
        and math.max(0, math.min(20, math.floor(requestedDisplay)))
        or startup.native_advertise_count_visual_to_display(actual)

    state.applying = true
    startup.native_advertise_count_visual_set_limits(feature, 0, 20)
    direct_call(function()
        if feature.SetStepSize then feature:SetStepSize(1) end
        if feature.SetFastStepSize then feature:SetFastStepSize(5) end
        if feature.SetIntValue then feature:SetIntValue(display) elseif feature.SetValue then feature:SetValue(display) end
    end)
    state.applying = false
    state.feature = feature
    state.featureName = tostring(matchedName or "Advertise Count")
    state.actualValue = actual
    state.displayValue = display
    state.hudDisplayValue = display
    state.configured = true
    state.status = "Visual 0 / 20 synchronized with Advertise HUD; native 5 / 10"
    return true
end

function startup.native_advertise_count_visual_write_actual(actualValue, source)
    local state = startup.native_advertise_count_visual
    actualValue = (tonumber(actualValue or 5) or 5) >= 10 and 10 or 5
    if not startup.native_advertise_count_visual_configure(false) then return nil end
    local feature = state.feature
    if not feature then return nil end

    local requestedDisplay = tonumber(startup.s.advertiseHudNativeSliderDisplay)
    local display = requestedDisplay ~= nil
        and math.max(0, math.min(20, math.floor(requestedDisplay)))
        or startup.native_advertise_count_visual_to_display(actualValue)
    state.applying = true
    local ok, err = direct_call(function()
        startup.native_advertise_count_visual_set_limits(feature, 5, 10)
        if feature.SetStepSize then feature:SetStepSize(5) end
        if feature.SetFastStepSize then feature:SetFastStepSize(5) end
        if feature.SetIntValue then feature:SetIntValue(actualValue) elseif feature.SetValue then feature:SetValue(actualValue) end
        if feature.TriggerCallback then
            feature:TriggerCallback()
        elseif feature.OnClick then
            feature:OnClick()
        end
        startup.native_advertise_count_visual_set_limits(feature, 0, 20)
        if feature.SetStepSize then feature:SetStepSize(1) end
        if feature.SetFastStepSize then feature:SetFastStepSize(5) end
        if feature.SetIntValue then feature:SetIntValue(display) elseif feature.SetValue then feature:SetValue(display) end
    end)
    state.applying = false
    if not ok then
        state.status = "Native visual mapping failed: " .. tostring(err or "unknown error")
        return false
    end

    state.actualValue = actualValue
    state.displayValue = display
    state.hudDisplayValue = display
    state.status = "HUD display " .. tostring(display) .. " → native " .. tostring(actualValue)
    startup.s.advertiseCountFeatureName = state.featureName
    startup.s.advertiseCountResolution = state.featureName .. " | visual " .. tostring(display) .. " / native " .. tostring(actualValue)
    if tostring(source or "") == "manual native slider" then
        startup.s.advertiseCurrentCount = actualValue
        startup.s.lastAdvertiseStatus = "Advertise Count " .. tostring(actualValue) .. " (Host Tool Kit displays " .. tostring(display) .. ")"
    end
    return true
end

function startup.native_advertise_count_visual_set_display(displayValue, source)
    local state = startup.native_advertise_count_visual
    if not state or state.enabled ~= true or startup.is_enhanced_active_edition() then return false end

    local display = math.max(0, math.min(20, math.floor(tonumber(displayValue or 0) or 0)))
    startup.s.advertiseHudNativeSliderDisplay = display
    state.hudDisplayValue = display

    if not startup.native_advertise_count_visual_configure(false) then return nil end
    local feature = state.feature
    if not feature then return nil end
    if tonumber(state.displayValue or -1) == display then return true end

    state.applying = true
    local ok, err = direct_call(function()
        startup.native_advertise_count_visual_set_limits(feature, 0, 20)
        if feature.SetStepSize then feature:SetStepSize(1) end
        if feature.SetFastStepSize then feature:SetFastStepSize(5) end
        if feature.SetIntValue then feature:SetIntValue(display)
        elseif feature.SetValue then feature:SetValue(display) end
    end)
    state.applying = false

    if not ok then
        state.status = "HUD slider synchronization failed: " .. tostring(err or "unknown error")
        return false
    end

    state.displayValue = display
    state.status = "HUD synchronized at " .. tostring(display) .. " | native " .. tostring(state.actualValue or 5)
    return true
end

function startup.process_native_advertise_count_visual_slider()
    local state = startup.native_advertise_count_visual
    if state.enabled ~= true or startup.is_enhanced_active_edition() then return end
    if state.configured ~= true or state.feature == nil then
        startup.native_advertise_count_visual_configure(false)
        return
    end
    if state.applying == true then return end

    local current = startup.native_advertise_count_visual_read(state.feature)
    if current == nil then
        state.configured = false
        state.feature = nil
        state.status = "Native slider lost; waiting to resolve"
        return
    end
    local expected = tonumber(state.displayValue or 0) or 0
    if current == expected then return end

    if current >= 0 and current <= 20 then
        local actual = startup.native_advertise_count_visual_to_actual(current)
        local normalizedDisplay = startup.native_advertise_count_visual_to_display(actual)
        startup.s.advertiseHudTerminalDisplayCount = normalizedDisplay
        startup.s.advertiseHudTerminalSequenceKey = ""
        startup.s.advertiseHudTerminalSequenceSteps = nil
        startup.s.advertiseHudTerminalSequenceStepIndex = 0
        startup.s.advertiseHudTerminalSequenceStepStartedAtMs = 0
        startup.s.advertiseHudTerminalSequenceFinalDisplay = 0
        startup.s.advertiseHudTerminalSequenceSyncedStepIndex = 0
        startup.s.advertiseHudNativeSliderDisplay = normalizedDisplay
        state.hudDisplayValue = normalizedDisplay
        startup.native_advertise_count_visual_write_actual(actual, "manual native slider")
    else
        state.applying = true
        direct_call(function()
            if state.feature.SetIntValue then state.feature:SetIntValue(expected)
            elseif state.feature.SetValue then state.feature:SetValue(expected) end
        end)
        state.applying = false
    end
end

function startup.restore_native_advertise_count_visual_slider()
    local state = startup.native_advertise_count_visual
    local feature = state and state.feature or nil
    if not feature then return end
    local actual = tonumber(state.actualValue or startup.s.advertiseCurrentCount or 5) or 5
    actual = actual >= 10 and 10 or 5
    state.applying = true
    direct_call(function()
        startup.native_advertise_count_visual_set_limits(feature, state.originalMin or 0, state.originalMax or 10)
        if feature.SetStepSize then feature:SetStepSize(state.originalStep or 1) end
        if feature.SetFastStepSize then feature:SetFastStepSize(state.originalFastStep or state.originalStep or 1) end
        if feature.SetIntValue then feature:SetIntValue(actual) elseif feature.SetValue then feature:SetValue(actual) end
        startup.native_advertise_count_visual_set_press_callback_disabled(feature, false)
    end)
    state.applying = false
    state.configured = false
    state.feature = nil
    state.status = "Original native slider restored"
end

-- Build 174: restore the visual 0 through 20 slider and bind its displayed
-- position to Startup's terminal Advertise HUD. Callback suppression keeps the
-- visual values cosmetic; Cherax receives only native 5 or 10 writes.
do
    local state = startup.native_advertise_count_visual
    local rememberedActual = tonumber(state and state.actualValue or startup.s.advertiseCurrentCount or 5) or 5
    rememberedActual = rememberedActual >= 10 and 10 or 5

    if state and state.feature ~= nil then
        startup.restore_native_advertise_count_visual_slider()
    end

    if state then
        state.enabled = true
        state.configured = false
        state.feature = nil
        state.actualValue = rememberedActual
        state.displayValue = math.max(0, math.min(20, math.floor(tonumber(startup.s.advertiseHudNativeSliderDisplay or 0) or 0)))
        state.hudDisplayValue = state.displayValue
        state.nextResolveMs = 0
        state.status = "Enabled; visual 0 / 20 synchronized with Advertise HUD"
    end
end

function startup.set_advertise_count(value)
    if startup.is_enhanced_active_edition() then
        startup.s.advertiseCountResolution = "Not used on Enhanced"
        return false
    end
    local adapted = startup.native_advertise_count_visual_write_actual(value, "Startup smart advertise")
    if adapted ~= nil then return adapted == true end
    local hash = startup.feature_hash and startup.feature_hash.ADVERTISE_COUNT or 4100757571
    return startup.set_int_feature_by_names(startup.advertise_count_names, value, hash)
end

function startup.get_feature_bool_state(feature)
    if not feature then return nil end
    if feature.IsToggled then
        local value = feature:IsToggled()
        if value ~= nil then return value == true end
    end
    if feature.GetBoolValue then
        local value = feature:GetBoolValue()
        if value ~= nil then return value == true end
    end
    return nil
end

function startup.set_advertise_session(enabled, force)
    enabled = enabled == true
    local feature, matchedName = startup.get_advertise_session_feature()
    if not feature then
        startup.s.advertiseFeatureUnavailable = true
        startup.s.advertiseFeatureResolution = "Unavailable"
        startup.s.lastAdvertiseStatus = "Advertise Session unavailable; smart advertise paused"
        if not startup.s.advertiseFeatureMissingLogged then
            startup.s.advertiseFeatureMissingLogged = true
            startup.log("Advertise Session control is unavailable on this Cherax layout. Smart advertise paused.")
        end
        return false
    end
    startup.s.advertiseFeatureUnavailable = false
    startup.s.advertiseFeatureMissingLogged = false
    startup.s.advertiseFeatureResolution = tostring(matchedName or "Resolved")
    local currentState = startup.get_feature_bool_state(feature)
    if not force then
        if currentState ~= nil and currentState == enabled then
            startup.s.advertiseSessionEnabled = enabled
            return true
        end
        if currentState == nil and startup.s.advertiseSessionEnabled == enabled then return true end
    end
    local ok = pcall(function()
        -- Toggle(bool) is the safest Cherax path for native toggles. Do not pair
        -- SetBoolValue with an unconditional callback, because some Cherax builds
        -- treat that callback like a second click and return the toggle to OFF.
        if feature.Toggle then
            feature:Toggle(enabled)
        elseif feature.SetBoolValue then
            feature:SetBoolValue(enabled)
        elseif currentState ~= nil and currentState ~= enabled and feature.OnClick then
            feature:OnClick()
        elseif currentState ~= nil and currentState ~= enabled and feature.TriggerCallback then
            feature:TriggerCallback()
        end
    end)
    if not ok then
        startup.s.lastAdvertiseStatus = "Advertise Session callback failed"
        return false
    end
    startup.s.advertiseSessionEnabled = enabled
    startup.s.lastAdvertiseStatus = "Advertise Session " .. (enabled and "ON" or "OFF")
    return true
end

function startup.get_advertise_session_feature()
    local hash = startup.feature_hash and startup.feature_hash.ADVERTISE_SESSION or 49959509
    local feature = startup.get_feature_by_hash_safe(hash)
    if feature and (feature.SetBoolValue or feature.Toggle or feature.TriggerCallback or feature.OnClick) then
        return feature, "hash " .. tostring(hash)
    end
    local matchedName
    feature, matchedName = startup.find_feature_by_possible_names(startup.advertise_session_names)
    if feature then return feature, matchedName end
    return nil, nil
end

function startup.request_advertise_session_sync(enabled, reason)
    startup.pendingAdvertiseSessionDesired = enabled == true
    startup.pendingAdvertiseSessionSyncReason = tostring(reason or "Startup Auto Advertise Session")
    startup.pendingAdvertiseSessionSync = true
end

function startup.process_pending_advertise_session_sync()
    if startup.pendingAdvertiseSessionSync ~= true then return end
    startup.pendingAdvertiseSessionSync = false
    local desired = startup.pendingAdvertiseSessionDesired == true
    local reason = tostring(startup.pendingAdvertiseSessionSyncReason or "Startup Auto Advertise Session")
    local ok = startup.set_advertise_session(desired, true)
    if ok then
        startup.s.lastAdvertiseStatus = "Cherax Advertise Session synchronized " .. (desired and "ON" or "OFF")
    else
        startup.s.lastAdvertiseStatus = "Could not synchronize Cherax Advertise Session " .. (desired and "ON" or "OFF")
        if startup.s.verboseStartupLogs then
            startup.log("Advertise Session synchronization failed | desired=" .. tostring(desired) .. " | reason=" .. reason)
        end
    end
end

function startup.detect_manual_advertise_off()
    if not startup.s.advertiseRunning then return false end
    if startup.s.advertiseStopRequested then return false end
    if startup.s.advertiseManualOverride then return true end
    local feature = startup.get_advertise_session_feature()
    if not feature then return false end
    local currentState = startup.get_feature_bool_state(feature)
    -- important:
    -- if Startup previously turned Advertise Session ON, but the real feature is now OFF,
    -- that almost certainly means the user manually toggled Advertise Session off.
    -- do NOT turn it back on automatically. Pause the smart advertise flow instead.
    if startup.s.advertiseSessionEnabled == true and currentState == false then
        startup.s.advertiseManualOverride = true
        startup.s.advertiseStopRequested = true
        startup.s.lastAdvertiseStatus = "Manual Advertise OFF detected; smart advertise paused"
        startup.toast("Manual Advertise OFF detected. Use Run Advertise Flow to resume.", 3500)
        return true
    end
    return false
end

function startup.reset_advertise_flow()
    if startup.advertise_benchmark_finalize then startup.advertise_benchmark_finalize("RESET", "Advertise flow reset", true) end
    startup.s.advertiseFlowSerial = (tonumber(startup.s.advertiseFlowSerial or 0) or 0) + 1
    startup.s.advertiseRunning = false
    startup.s.advertiseSmartActive = false
    startup.s.advertiseCompletedForSession = false
    startup.s.advertiseStopRequested = false
    startup.s.advertiseCountEscalated = false
    startup.s.advertiseCountdownStartedAtMs = 0
    startup.s.advertiseCountdownEndsAtMs = 0
    startup.s.advertiseActiveSinceMs = 0
    startup.s.advertiseHudIntroStartedAtMs = 0
    startup.s.advertiseHudEscalationStartedAtMs = 0
    startup.s.advertiseHudPreviousActualCount = 0
    if startup.reset_advertise_hud_terminal_state then startup.reset_advertise_hud_terminal_state() end
    startup.s.advertiseSessionEnabled = nil
    startup.s.advertiseManualOverride = false
    startup.s.advertiseFeatureUnavailable = false
    startup.s.advertiseFeatureMissingLogged = false
    startup.s.lastAdvertiseStatus = "Reset"
    startup.toast("Advertise flow reset.", 2500)
end

function startup.request_advertise_stop(reason)
    if not startup.s.advertiseRunning then
        startup.set_advertise_session(false)
        startup.s.lastAdvertiseStatus = "Stopped"
        return
    end
    startup.s.advertiseStopRequested = true
    if reason then
        startup.s.lastAdvertiseStatus = "Stop requested: " .. tostring(reason)
        startup.toast(startup.s.lastAdvertiseStatus, 3000)
    end
end

function startup.stop_advertise_now()
    if startup.advertise_benchmark_finalize then startup.advertise_benchmark_finalize("MANUAL_STOP", "Stop Advertise Session Now", true) end
    startup.s.advertiseManualOverride = true
    startup.request_advertise_stop("manual stop")
    if startup.stop_old_startup_advertise then startup.stop_old_startup_advertise("manual stop button", false) end
    if startup.stop_super_advertise and startup.s.superAdvertiseRunning == true then startup.stop_super_advertise("manual stop button") end
    startup.set_advertise_session(false, true)
    if startup.advertise_research_log then startup.advertise_research_log("ALL", "MANUAL_STOP", "players=" .. tostring(startup.get_session_player_count())) end
end

function startup.apply_advertise_count(value, label)
    value = tonumber(value or 5) or 5
    if startup.s.advertiseCurrentCount == value and startup.s.advertiseCountFeatureName then return true end
    local previousValue = tonumber(startup.s.advertiseCurrentCount or 0) or 0
    local ok = startup.set_advertise_count(value)
    if ok then
        local changedAt = startup.now()
        startup.s.advertiseHudPreviousActualCount = previousValue
        startup.s.advertiseCurrentCount = value
        if value ~= previousValue then
            local lowCount = tonumber(startup.s.advertiseLowCount or 5) or 5
            local highCount = tonumber(startup.s.advertiseHighCount or 10) or 10
            if previousValue <= 0 then
                startup.s.advertiseHudIntroStartedAtMs = changedAt
            end
            if value <= lowCount then
                startup.s.advertiseHudEscalationStartedAtMs = 0
            elseif value >= highCount and previousValue < value then
                startup.s.advertiseHudEscalationStartedAtMs = changedAt
            end
        end
        startup.s.lastAdvertiseStatus = label or ("Advertise Count " .. tostring(value))
        if value ~= previousValue and startup.advertise_research_log and startup.s.oldStartupAdvertiseRunning ~= true then
            startup.advertise_research_log("CURRENT", "COUNT_CHANGE",
                "from=" .. tostring(previousValue) ..
                " to=" .. tostring(value) ..
                " players=" .. tostring(startup.get_session_player_count()) ..
                " reason=" .. tostring(label or "smart state"))
        end
        return true
    end
    startup.s.lastAdvertiseStatus = "Advertise Session active; Advertise Count is not exposed on this Cherax layout"
    return false
end

function startup.update_advertise_smart_state(context)
    if not startup.s.advertiseRunning then return end
    if not startup.s.advertiseSmartActive then return end
    if startup.s.advertiseStopRequested then return end
    if startup.detect_manual_advertise_off() then return end
    local playerCount = startup.get_session_player_count()
    local highLimit = tonumber(startup.s.advertisePlayerTarget or 30) or 30
    local resumeBelow = tonumber(startup.s.advertiseResumeBelow or 25) or 25

    if startup.is_enhanced_active_edition() then
        local region = startup.get_advertise_region_label(false)
        -- Build 134 stability policy: once Enhanced Advertise Session is enabled,
        -- Startup never cycles it OFF merely because the lobby reached 30 players.
        -- GTA already enforces the session capacity, and repeatedly changing this
        -- native hosting control is not worth risking a full-lobby network split.
        if startup.s.advertiseSessionEnabled ~= true then
            if not startup.set_advertise_session(true) then return end
        end
        if playerCount >= highLimit then
            startup.s.lastAdvertiseStatus = "Enhanced stable hold: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players; Advertise left ON | " .. tostring(region)
            if startup.s.enhancedAdvertiseFullLogged ~= true then
                startup.s.enhancedAdvertiseFullLogged = true
                if startup.support_log_event_quiet then
                    startup.support_log_event_quiet("EE_ADVERTISE_STABLE_HOLD", "players=" .. tostring(playerCount) .. " region=" .. tostring(region) .. " action=no toggle")
                end
            end
            return
        end
        if playerCount < highLimit then startup.s.enhancedAdvertiseFullLogged = false end
        startup.s.lastAdvertiseStatus = "Enhanced advertise stable: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players | " .. tostring(region)
        return
    end

    local lowCount = tonumber(startup.s.advertiseLowCount or 5) or 5
    local highCount = tonumber(startup.s.advertiseHighCount or 10) or 10
    if playerCount >= highLimit then
        if not startup.set_advertise_session(true) then return end
        startup.apply_advertise_count(lowCount, "Soft hold at " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players")
        startup.s.lastAdvertiseStatus = "Legacy soft hold: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players, count " .. tostring(lowCount)
        return
    end
    if playerCount < resumeBelow then
        if not startup.set_advertise_session(true) then return end
        startup.apply_advertise_count(highCount, "Re-boost below " .. tostring(resumeBelow) .. " players")
        startup.s.lastAdvertiseStatus = "Legacy re-boost: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players, count " .. tostring(highCount)
        return
    end
    if not startup.set_advertise_session(true) then return end
    startup.s.lastAdvertiseStatus = "Legacy maintaining: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players, count " .. tostring(startup.s.advertiseCurrentCount or "?")
end

function startup.run_advertise_flow(reason)
    if not startup.s.autoAdvertiseSession then
        startup.s.lastAdvertiseStatus = "Auto Advertise OFF"
        startup.toast("Auto Advertise Session is OFF.", 2500)
        return
    end
    if startup.s.advertiseRunning then
        startup.toast("Advertise flow is already running.", 2500)
        return
    end
    startup.s.advertiseFlowSerial = (tonumber(startup.s.advertiseFlowSerial or 0) or 0) + 1
    local flowSerial = startup.s.advertiseFlowSerial
    startup.s.advertiseRunning = true
    startup.s.advertiseSmartActive = false
    if startup.advertise_benchmark_start then startup.advertise_benchmark_start("CURRENT", reason or "manual") end
    if startup.advertise_research_log then
        startup.advertise_research_log("CURRENT", "QUEUED", "reason=" .. tostring(reason or "manual") .. " players=" .. tostring(startup.get_session_player_count()) .. " delayMs=" .. tostring(startup.s.advertiseDelayAfterSessionMs or 120000))
    end
    startup.s.advertiseCompletedForSession = false
    startup.s.advertiseStopRequested = false
    startup.s.advertiseCountEscalated = false
    startup.s.advertiseCurrentCount = 0
    startup.s.advertiseHudIntroStartedAtMs = 0
    startup.s.advertiseHudEscalationStartedAtMs = 0
    startup.s.advertiseHudPreviousActualCount = 0
    if startup.reset_advertise_hud_terminal_state then startup.reset_advertise_hud_terminal_state() end
    startup.s.advertiseSessionEnabled = nil
    startup.s.advertiseManualOverride = false
    startup.s.advertiseFeatureUnavailable = false
    startup.s.advertiseFeatureMissingLogged = false
    Script.QueueJob(function()
        startup.s.lastAdvertiseStatus = "Queued"
        startup.s.advertiseCountdownStartedAtMs = startup.now()
        startup.s.advertiseCountdownEndsAtMs = startup.s.advertiseCountdownStartedAtMs + (tonumber(startup.s.advertiseDelayAfterSessionMs or 120000) or 120000)
        startup.s.advertiseActiveSinceMs = 0
        if startup.is_enhanced_active_edition() then
            startup.toast("EE Advertise Session enabled. Stable Enhanced advertising begins in 2 minutes; Startup will not cycle Advertise Session OFF at 30 players.", 4500)
            -- EE advertising is already slow, so keep Cherax's native Advertise Session ON
            -- while Startup waits before beginning threshold-based management.
            startup.set_advertise_session(true, true)
        else
            startup.toast("Advertise flow queued" .. (reason and (" after " .. reason) or "") .. ". Waiting 2 minutes.", 3500)
            -- Legacy keeps the prior stabilization behavior.
            startup.set_advertise_session(false)
        end
        startup.yield(startup.s.advertiseDelayAfterSessionMs)
        if flowSerial ~= startup.s.advertiseFlowSerial then return end
        if startup.s.advertiseStopRequested then
            startup.s.lastAdvertiseStatus = "Stopped before start"
            startup.s.advertiseRunning = false
            startup.s.advertiseSmartActive = false
            startup.s.advertiseCompletedForSession = true
            startup.s.advertiseCountdownStartedAtMs = 0
            startup.s.advertiseCountdownEndsAtMs = 0
            startup.s.advertiseActiveSinceMs = 0
            startup.s.advertiseHudIntroStartedAtMs = 0
            startup.s.advertiseHudEscalationStartedAtMs = 0
            startup.s.advertiseHudPreviousActualCount = 0
            if startup.reset_advertise_hud_terminal_state then startup.reset_advertise_hud_terminal_state() end
            startup.set_advertise_session(false)
            if startup.advertise_benchmark_finalize then startup.advertise_benchmark_finalize("STOPPED_BEFORE_ACTIVE", "Current flow stopped before activation") end
            return
        end
        if not startup.set_advertise_session(true) then
            startup.s.advertiseRunning = false
            startup.s.advertiseSmartActive = false
            startup.s.advertiseCompletedForSession = true
            startup.s.advertiseCountdownStartedAtMs = 0
            startup.s.advertiseCountdownEndsAtMs = 0
            startup.s.advertiseActiveSinceMs = 0
            startup.s.advertiseHudIntroStartedAtMs = 0
            startup.s.advertiseHudEscalationStartedAtMs = 0
            startup.s.advertiseHudPreviousActualCount = 0
            if startup.reset_advertise_hud_terminal_state then startup.reset_advertise_hud_terminal_state() end
            if startup.advertise_benchmark_finalize then startup.advertise_benchmark_finalize("FAILED", "Current Advertise Session could not be enabled") end
            return
        end
        startup.s.advertiseSmartActive = true
        startup.s.advertiseCountdownEndsAtMs = 0
        if startup.advertise_benchmark_mark_active then startup.advertise_benchmark_mark_active("CURRENT") end
        if startup.advertise_research_log then
            startup.advertise_research_log("CURRENT", "ACTIVATED", "players=" .. tostring(startup.get_session_player_count()) .. " edition=" .. tostring(startup.get_active_edition and startup.get_active_edition() or "Unknown"))
        end
        startup.s.advertiseActiveSinceMs = startup.now()
        if startup.is_enhanced_active_edition() then
            local region = startup.get_advertise_region_label(true)
            startup.s.lastAdvertiseStatus = "Enhanced advertise active | " .. tostring(region)
        else
            startup.apply_advertise_count(startup.s.advertiseLowCount or 5, "Initial soft start")
        end
        local elapsed = 0
        while true do
            if flowSerial ~= startup.s.advertiseFlowSerial then return end
            if startup.s.advertiseStopRequested then
                startup.s.lastAdvertiseStatus = "Stopped by request"
                break
            end
            local playerCount = startup.get_session_player_count()
            if not startup.is_enhanced_active_edition()
                and not startup.s.advertiseCountEscalated
                and elapsed >= startup.s.advertiseCount5DurationMs
                and playerCount < (startup.s.advertisePlayerTarget or 30) then
                startup.s.advertiseCountEscalated = true
                startup.apply_advertise_count(startup.s.advertiseHighCount or 10, "5 minutes passed and lobby is below high limit")
            end
            startup.update_advertise_smart_state("loop")
            startup.yield(startup.s.advertisePlayerCheckMs)
            elapsed = elapsed + startup.s.advertisePlayerCheckMs
        end
        startup.set_advertise_session(false)
        startup.s.advertiseCompletedForSession = true
        startup.s.advertiseRunning = false
        startup.s.advertiseSmartActive = false
        startup.s.advertiseStopRequested = false
        startup.s.advertiseCountEscalated = false
        startup.s.advertiseCountdownStartedAtMs = 0
        startup.s.advertiseCountdownEndsAtMs = 0
        startup.s.advertiseActiveSinceMs = 0
        startup.s.advertiseHudIntroStartedAtMs = 0
        startup.s.advertiseHudEscalationStartedAtMs = 0
        startup.s.advertiseHudPreviousActualCount = 0
        if startup.reset_advertise_hud_terminal_state then startup.reset_advertise_hud_terminal_state() end
        startup.s.lastAdvertiseStatus = "Stopped"
        if startup.advertise_benchmark_finalize then startup.advertise_benchmark_finalize("STOPPED", "Current advertising flow stopped") end
        if startup.advertise_research_log then startup.advertise_research_log("CURRENT", "STOPPED", "players=" .. tostring(startup.get_session_player_count())) end
    end)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 182 advertising mode arbitration, v1.0.3 compatibility, and timed benchmarking
-- note: milestones use startup.log so they appear in Cherax.log beside Cherax player events.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.advertise_research_log(mode, eventName, details)
    -- Build 334: Super Advertise can generate up to 100 profile milestones per run.
    -- Keep that telemetry out of Cherax.log permanently; the detailed Super Advertise
    -- report under Startup\Diagnostics remains authoritative for profile results.
    if string.upper(tostring(mode or "")) == "SUPER" then return end
    local suffix = tostring(details or "")
    if suffix ~= "" then suffix = " | " .. suffix end
    startup.log("[Advertise][" .. tostring(mode or "UNKNOWN") .. "] " .. tostring(eventName or "EVENT") .. suffix)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 182 Advertising Benchmark Timer
-- Total time starts when the selected flow is queued. Active time starts only when
-- Cherax advertising is actually enabled. Every run is retained in config and CSV/log.
-- ═══════════════════════════════════════════════════════════════════════════════════

startup.advertise_benchmark_milestone_targets = {10, 15, 20, 25, 30}

function startup.advertise_benchmark_mode_label(mode)
    mode = tostring(mode or "UNKNOWN")
    if mode == "CURRENT" then return "Current" end
    if mode == "OLD_V103" then return "Old v1.0.3" end
    if mode == "SUPER" then return "Super" end
    return mode
end

function startup.advertise_benchmark_format_ms(ms)
    ms = tonumber(ms)
    if not ms or ms < 0 then return "--:--" end
    local totalSeconds = math.floor((ms + 500) / 1000)
    local hours = math.floor(totalSeconds / 3600)
    local minutes = math.floor((totalSeconds % 3600) / 60)
    local seconds = totalSeconds % 60
    if hours > 0 then return string.format("%d:%02d:%02d", hours, minutes, seconds) end
    return string.format("%02d:%02d", minutes, seconds)
end

function startup.advertise_benchmark_csv_escape(value)
    local s = tostring(value == nil and "" or value)
    if s:find('[,\"\r\n]') then s = '"' .. s:gsub('"', '""') .. '"' end
    return s
end

function startup.advertise_benchmark_host_snapshot()
    local hostName, hostId = "Unknown", -1
    if startup.get_session_host_name then
        local ok, name, id = direct_call(startup.get_session_host_name)
        if ok then hostName, hostId = tostring(name or "Unknown"), tonumber(id or -1) or -1 end
    end
    local localHost = false
    if startup.get_local_player_id_candidates then
        for _, localId in ipairs(startup.get_local_player_id_candidates()) do
            if tonumber(localId) == hostId then localHost = true break end
        end
    end
    return hostName, hostId, localHost and "Local" or "Remote"
end

function startup.advertise_benchmark_context_snapshot()
    local editionCode, editionFamily, isPrime = "Unknown", "Unknown", false
    if startup.get_active_edition_info then
        local ok, code, family, prime = direct_call(startup.get_active_edition_info)
        if ok then editionCode, editionFamily, isPrime = tostring(code or "Unknown"), tostring(family or "Unknown"), prime == true end
    end
    local nat = "Unknown"
    if startup.get_local_nat_type then
        local ok, value = direct_call(startup.get_local_nat_type)
        if ok and value then nat = tostring(value) end
    end
    local region = startup.is_enhanced_active_edition() and tostring(
        startup.get_advertise_region_label and startup.get_advertise_region_label(false) or startup.s.advertiseRegionLabel or "Unknown"
    ) or "Legacy"
    local hostName, hostId, hostType = startup.advertise_benchmark_host_snapshot()
    return {
        editionCode = editionCode,
        editionFamily = editionFamily,
        prime = isPrime,
        nat = nat,
        region = region,
        sessionType = tostring(startup.s.sessionType or "Unknown"),
        hostName = hostName,
        hostId = hostId,
        hostType = hostType
    }
end

function startup.advertise_benchmark_ensure_csv_header()
    startup.ensure_save_dir()
    local path = tostring(startup.AdvertiseBenchmarkCsvFile or "")
    if path == "" then return false end
    local existing = io and io.open and io.open(path, "rb") or nil
    if existing then
        local size = existing:seek("end") or 0
        existing:close()
        if size > 0 then return true end
    end
    local f = io and io.open and io.open(path, "w") or nil
    if not f then return false end
    f:write(table.concat({
        "Run ID","Started","Finished","Mode","Outcome","Reason","Edition","Prime","Session Type","NAT","Region","Host Type","Host Name",
        "Start Players","Activation Players","End Players","Peak Players","Target","Total To 30 ms","Active To 30 ms","Run Duration ms","Active Duration ms","Reached Before Activation",
        "10 Total ms","10 Active ms","15 Total ms","15 Active ms","20 Total ms","20 Active ms","25 Total ms","25 Active ms","30 Total ms","30 Active ms","Super Best Method"
    }, ","), "\n")
    f:close()
    return true
end

function startup.advertise_benchmark_append_files(entry)
    startup.advertise_benchmark_ensure_csv_header()
    local path = tostring(startup.AdvertiseBenchmarkCsvFile or "")
    local f = io and io.open and io.open(path, "a") or nil
    local function milestone_value(target, key)
        local item = type(entry.milestones) == "table" and entry.milestones[tostring(target)] or nil
        return item and item[key] or ""
    end
    if f then
        local values = {
            entry.id, entry.startedAt, entry.finishedAt, entry.mode, entry.outcome, entry.reason,
            entry.edition, entry.prime and "true" or "false", entry.sessionType, entry.nat, entry.region, entry.hostType, entry.hostName,
            entry.startPlayers, entry.activationPlayers, entry.endPlayers, entry.peakPlayers, entry.target,
            entry.totalToTargetMs or "", entry.activeToTargetMs or "", entry.durationMs or "", entry.activeDurationMs or "", entry.reachedBeforeActivation and "true" or "false",
            milestone_value(10, "totalMs"), milestone_value(10, "activeMs"),
            milestone_value(15, "totalMs"), milestone_value(15, "activeMs"),
            milestone_value(20, "totalMs"), milestone_value(20, "activeMs"),
            milestone_value(25, "totalMs"), milestone_value(25, "activeMs"),
            milestone_value(30, "totalMs"), milestone_value(30, "activeMs"),
            entry.superBestMethod or ""
        }
        for i, value in ipairs(values) do values[i] = startup.advertise_benchmark_csv_escape(value) end
        f:write(table.concat(values, ","), "\n")
        f:close()
    end
    local logPath = tostring(startup.AdvertiseBenchmarkLogFile or "")
    local logFile = io and io.open and io.open(logPath, "a") or nil
    if logFile then
        logFile:write(string.format(
            "%s | %s | %s | players=%d>%d peak=%d target=%d | total=%s active=%s | outcome=%s | reason=%s | edition=%s | nat=%s | region=%s | host=%s:%s\n",
            tostring(entry.finishedAt or ""), tostring(entry.id or ""), tostring(entry.modeLabel or entry.mode or "UNKNOWN"),
            tonumber(entry.startPlayers or 0) or 0, tonumber(entry.endPlayers or 0) or 0, tonumber(entry.peakPlayers or 0) or 0, tonumber(entry.target or 30) or 30,
            tostring(entry.totalText or "--:--"), tostring(entry.activeText or "--:--"), tostring(entry.outcome or "Unknown"), tostring(entry.reason or ""),
            tostring(entry.edition or "Unknown"), tostring(entry.nat or "Unknown"), tostring(entry.region or "Unknown"), tostring(entry.hostType or "Unknown"), tostring(entry.hostName or "Unknown")
        ))
        logFile:close()
    end
    startup.s.advertiseBenchmarkLastHistoryPath = path
end

function startup.advertise_benchmark_update(nowMs, playerCount, allowFinalize)
    if startup.s.advertiseBenchmarkActive ~= true then return false end
    nowMs = tonumber(nowMs or startup.now()) or startup.now()
    playerCount = tonumber(playerCount or startup.get_session_player_count()) or 0
    startup.s.advertiseBenchmarkPeakPlayers = math.max(tonumber(startup.s.advertiseBenchmarkPeakPlayers or 0) or 0, playerCount)
    startup.s.advertiseBenchmarkMilestones = startup.s.advertiseBenchmarkMilestones or {}
    local queuedAt = tonumber(startup.s.advertiseBenchmarkQueuedAtMs or 0) or 0
    local activeAt = tonumber(startup.s.advertiseBenchmarkActivatedAtMs or 0) or 0
    for _, target in ipairs(startup.advertise_benchmark_milestone_targets) do
        local key = tostring(target)
        if playerCount >= target and startup.s.advertiseBenchmarkMilestones[key] == nil then
            local totalMs = math.max(0, nowMs - queuedAt)
            local activeMs = activeAt > 0 and math.max(0, nowMs - activeAt) or nil
            startup.s.advertiseBenchmarkMilestones[key] = {
                players = playerCount,
                totalMs = totalMs,
                activeMs = activeMs,
                reachedAt = os.date("%Y-%m-%d %H:%M:%S")
            }
            startup.advertise_research_log(startup.s.advertiseBenchmarkMode, "TIMER_MILESTONE",
                "target=" .. tostring(target) ..
                " players=" .. tostring(playerCount) ..
                " totalMs=" .. tostring(totalMs) ..
                " activeMs=" .. tostring(activeMs or "not-active"))
        end
    end
    local target = tonumber(startup.s.advertiseBenchmarkTargetPlayers or 30) or 30
    if allowFinalize ~= false and playerCount >= target then
        -- Super Advertise finishes from its profile loop after updating the winning
        -- profile metadata. The 1-second timer loop still records the exact 30-player
        -- milestone while Current and Old v1.0.3 finalize immediately.
        if tostring(startup.s.advertiseBenchmarkMode or "") ~= "SUPER" then
            startup.advertise_benchmark_finalize("REACHED_30", "30-player target reached")
            return true
        end
    end
    local totalElapsed = queuedAt > 0 and math.max(0, nowMs - queuedAt) or 0
    local activeElapsed = activeAt > 0 and math.max(0, nowMs - activeAt) or nil
    startup.s.advertiseBenchmarkLastStatus = startup.advertise_benchmark_mode_label(startup.s.advertiseBenchmarkMode)
        .. " | " .. tostring(playerCount) .. "/" .. tostring(target)
        .. " | Total " .. startup.advertise_benchmark_format_ms(totalElapsed)
        .. " | Active " .. startup.advertise_benchmark_format_ms(activeElapsed)
    return false
end

function startup.advertise_benchmark_start(mode, reason)
    if startup.s.advertiseBenchmarkEnabled == false then return false end
    mode = tostring(mode or "UNKNOWN")
    if startup.s.advertiseBenchmarkActive == true then
        startup.advertise_benchmark_finalize("MODE_SWITCH", "Replaced by " .. mode, true)
    end
    local nowMs = startup.now()
    local players = startup.get_session_player_count()
    startup.s.advertiseBenchmarkSerial = (tonumber(startup.s.advertiseBenchmarkSerial or 0) or 0) + 1
    startup.s.advertiseBenchmarkActive = true
    startup.s.advertiseBenchmarkMode = mode
    startup.s.advertiseBenchmarkReason = tostring(reason or "advertising flow")
    startup.s.advertiseBenchmarkQueuedAtMs = nowMs
    startup.s.advertiseBenchmarkActivatedAtMs = 0
    startup.s.advertiseBenchmarkStartedAtEpoch = os.time()
    startup.s.advertiseBenchmarkStartPlayers = players
    startup.s.advertiseBenchmarkActivationPlayers = 0
    startup.s.advertiseBenchmarkPeakPlayers = players
    startup.s.advertiseBenchmarkMilestones = {}
    startup.s.advertiseBenchmarkContext = startup.advertise_benchmark_context_snapshot()
    startup.s.advertiseBenchmarkNextPollMs = 0
    startup.s.advertiseBenchmarkLastStatus = startup.advertise_benchmark_mode_label(mode) .. " queued | " .. tostring(players) .. "/30"
    startup.advertise_research_log(mode, "TIMER_START",
        "run=" .. tostring(startup.s.advertiseBenchmarkSerial) ..
        " players=" .. tostring(players) ..
        " target=30 reason=" .. tostring(reason or "advertising flow"))
    startup.advertise_benchmark_update(nowMs, players, true)
    return true
end

function startup.advertise_benchmark_mark_active(mode)
    if startup.s.advertiseBenchmarkEnabled == false then return false end
    mode = tostring(mode or startup.s.advertiseBenchmarkMode or "UNKNOWN")
    if startup.s.advertiseBenchmarkActive ~= true or tostring(startup.s.advertiseBenchmarkMode or "") ~= mode then
        return false
    end
    if tonumber(startup.s.advertiseBenchmarkActivatedAtMs or 0) > 0 then return true end
    local nowMs = startup.now()
    local players = startup.get_session_player_count()
    startup.s.advertiseBenchmarkActivatedAtMs = nowMs
    startup.s.advertiseBenchmarkActivationPlayers = players
    startup.advertise_research_log(mode, "TIMER_ACTIVE",
        "players=" .. tostring(players) ..
        " queueElapsedMs=" .. tostring(math.max(0, nowMs - (tonumber(startup.s.advertiseBenchmarkQueuedAtMs or nowMs) or nowMs))))
    startup.advertise_benchmark_update(nowMs, players, true)
    return true
end

function startup.advertise_benchmark_finalize(outcome, reason, usePeakEnd)
    if startup.s.advertiseBenchmarkActive ~= true then return false end
    local nowMs = startup.now()
    local currentPlayers = startup.get_session_player_count()
    local peakPlayers = math.max(tonumber(startup.s.advertiseBenchmarkPeakPlayers or 0) or 0, tonumber(currentPlayers or 0) or 0)
    startup.s.advertiseBenchmarkPeakPlayers = peakPlayers
    startup.advertise_benchmark_update(nowMs, currentPlayers, false)
    local target = tonumber(startup.s.advertiseBenchmarkTargetPlayers or 30) or 30
    local endPlayers = usePeakEnd == true and peakPlayers or currentPlayers
    local targetMilestone = startup.s.advertiseBenchmarkMilestones and startup.s.advertiseBenchmarkMilestones[tostring(target)] or nil
    if targetMilestone or peakPlayers >= target then outcome = "REACHED_30" end
    outcome = tostring(outcome or "STOPPED")
    local queuedAt = tonumber(startup.s.advertiseBenchmarkQueuedAtMs or nowMs) or nowMs
    local activeAt = tonumber(startup.s.advertiseBenchmarkActivatedAtMs or 0) or 0
    local durationMs = math.max(0, nowMs - queuedAt)
    local activeDurationMs = activeAt > 0 and math.max(0, nowMs - activeAt) or nil
    local totalToTargetMs = targetMilestone and tonumber(targetMilestone.totalMs) or nil
    local activeToTargetMs = targetMilestone and tonumber(targetMilestone.activeMs) or nil
    local context = type(startup.s.advertiseBenchmarkContext) == "table" and startup.s.advertiseBenchmarkContext or startup.advertise_benchmark_context_snapshot()
    local runId = os.date("%Y%m%d_%H%M%S") .. "_" .. string.format("%03d", tonumber(startup.s.advertiseBenchmarkSerial or 0) or 0)
    local entry = {
        id = runId,
        startedAt = os.date("%Y-%m-%d %H:%M:%S", tonumber(startup.s.advertiseBenchmarkStartedAtEpoch or os.time()) or os.time()),
        finishedAt = os.date("%Y-%m-%d %H:%M:%S"),
        mode = tostring(startup.s.advertiseBenchmarkMode or "UNKNOWN"),
        modeLabel = startup.advertise_benchmark_mode_label(startup.s.advertiseBenchmarkMode),
        outcome = outcome,
        reason = tostring(reason or startup.s.advertiseBenchmarkReason or ""),
        edition = tostring(context.editionCode or context.editionFamily or "Unknown"),
        editionFamily = tostring(context.editionFamily or "Unknown"),
        prime = context.prime == true,
        sessionType = tostring(context.sessionType or "Unknown"),
        nat = tostring(context.nat or "Unknown"),
        region = tostring(context.region or "Unknown"),
        hostName = tostring(context.hostName or "Unknown"),
        hostId = tonumber(context.hostId or -1) or -1,
        hostType = tostring(context.hostType or "Unknown"),
        startPlayers = tonumber(startup.s.advertiseBenchmarkStartPlayers or 0) or 0,
        activationPlayers = tonumber(startup.s.advertiseBenchmarkActivationPlayers or 0) or 0,
        endPlayers = tonumber(endPlayers or 0) or 0,
        peakPlayers = peakPlayers,
        target = target,
        durationMs = durationMs,
        activeDurationMs = activeDurationMs,
        totalToTargetMs = totalToTargetMs,
        activeToTargetMs = activeToTargetMs,
        totalText = startup.advertise_benchmark_format_ms(totalToTargetMs or durationMs),
        activeText = startup.advertise_benchmark_format_ms(activeToTargetMs or activeDurationMs),
        reachedTarget = outcome == "REACHED_30",
        reachedBeforeActivation = outcome == "REACHED_30" and activeAt <= 0,
        milestones = startup.s.advertiseBenchmarkMilestones or {},
        superBestMethod = tostring(startup.s.advertiseBenchmarkMode or "") == "SUPER" and tonumber(startup.s.superAdvertiseBestMethod or 0) or nil
    }
    startup.s.advertiseBenchmarkActive = false
    startup.s.advertiseBenchmarkContext = {}
    startup.s.advertiseBenchmarkHistory = startup.s.advertiseBenchmarkHistory or {}
    table.insert(startup.s.advertiseBenchmarkHistory, 1, entry)
    local limit = startup.clamp_int(startup.s.advertiseBenchmarkHistoryLimit or 100, 10, 500)
    while #startup.s.advertiseBenchmarkHistory > limit do table.remove(startup.s.advertiseBenchmarkHistory) end
    startup.advertise_benchmark_append_files(entry)
    startup.s.advertiseBenchmarkLastResult = entry.modeLabel .. " | " .. entry.outcome
        .. " | " .. tostring(entry.startPlayers) .. ">" .. tostring(entry.endPlayers)
        .. " | Total " .. tostring(entry.totalText) .. " | Active " .. tostring(entry.activeText)
    startup.s.advertiseBenchmarkLastStatus = startup.s.advertiseBenchmarkLastResult
    startup.advertise_research_log(entry.mode, "TIMER_RESULT",
        "run=" .. tostring(entry.id) ..
        " outcome=" .. tostring(entry.outcome) ..
        " players=" .. tostring(entry.startPlayers) .. ">" .. tostring(entry.endPlayers) ..
        " peak=" .. tostring(entry.peakPlayers) ..
        " totalMs=" .. tostring(entry.totalToTargetMs or entry.durationMs) ..
        " activeMs=" .. tostring(entry.activeToTargetMs or entry.activeDurationMs or "not-active") ..
        " csv=" .. tostring(startup.AdvertiseBenchmarkCsvFile or ""))
    if startup.s.initialized then startup.save_config(false) end
    return true
end

function startup.advertise_benchmark_tick()
    if startup.s.advertiseBenchmarkActive ~= true then return end
    local nowMs = startup.now()
    if nowMs < (tonumber(startup.s.advertiseBenchmarkNextPollMs or 0) or 0) then return end
    startup.s.advertiseBenchmarkNextPollMs = nowMs + 1000
    startup.advertise_benchmark_update(nowMs, startup.get_session_player_count(), true)
end

function startup.install_advertise_benchmark_loop()
    if startup.s.advertiseBenchmarkLoopInstalled then return end
    startup.s.advertiseBenchmarkLoopInstalled = true
    if Script and Script.RegisterLooped then
        Script.RegisterLooped(function()
            if startup and startup.s and startup.s.advertiseBenchmarkActive == true then
                startup.advertise_benchmark_tick()
            end
        end)
    else
        startup.s.advertiseBenchmarkLastStatus = "Timer loop unavailable"
        startup.log("Advertising Benchmark Timer loop unavailable: Script.RegisterLooped missing.")
    end
end

function startup.advertise_benchmark_clear_history()
    if startup.s.advertiseBenchmarkActive == true then
        startup.toast("Stop the active advertising timer before clearing history.", 3500)
        return false
    end
    startup.s.advertiseBenchmarkHistory = {}
    startup.s.advertiseBenchmarkLastResult = "No timed advertising results yet"
    startup.s.advertiseBenchmarkLastStatus = "History cleared"
    if os and os.remove then
        direct_call(os.remove, tostring(startup.AdvertiseBenchmarkCsvFile or ""))
        direct_call(os.remove, tostring(startup.AdvertiseBenchmarkLogFile or ""))
    end
    startup.advertise_benchmark_ensure_csv_header()
    startup.save_config(false)
    startup.toast("Advertising timer history cleared.", 3000)
    return true
end

function startup.advertise_benchmark_copy_history_path()
    local path = tostring(startup.AdvertiseBenchmarkCsvFile or "")
    if startup.copy_to_clipboard(path) then
        startup.toast("Advertising timer CSV path copied.", 2500)
        return true
    end
    startup.toast("Could not copy path: " .. path, 4500)
    return false
end

function startup.advertise_benchmark_best(mode)
    local best = nil
    for _, item in ipairs(startup.s.advertiseBenchmarkHistory or {}) do
        if tostring(item.mode or "") == tostring(mode or "") and item.reachedTarget == true and tonumber(item.totalToTargetMs) then
            if not best or tonumber(item.totalToTargetMs) < tonumber(best.totalToTargetMs) then best = item end
        end
    end
    return best
end

function startup.advertise_benchmark_live_text()
    if startup.s.advertiseBenchmarkActive ~= true then return nil end
    local nowMs = startup.now()
    local queuedAt = tonumber(startup.s.advertiseBenchmarkQueuedAtMs or nowMs) or nowMs
    local activeAt = tonumber(startup.s.advertiseBenchmarkActivatedAtMs or 0) or 0
    local players = startup.get_session_player_count()
    local total = startup.advertise_benchmark_format_ms(math.max(0, nowMs - queuedAt))
    local active = startup.advertise_benchmark_format_ms(activeAt > 0 and math.max(0, nowMs - activeAt) or nil)
    return "30P Timer " .. startup.advertise_benchmark_mode_label(startup.s.advertiseBenchmarkMode)
        .. ": " .. total .. " total | " .. active .. " active | " .. tostring(players) .. "/30"
end

function startup.render_advertise_benchmark_compact()
    if startup.s.advertiseBenchmarkActive == true then
        startup.status_line("30P Timer", tostring(startup.advertise_benchmark_live_text() or "Running"), 0.35, 1.00, 0.45)
    else
        startup.status_line("Last Timer", tostring(startup.s.advertiseBenchmarkLastResult or "No results yet"), 0.72, 0.72, 0.72)
    end
    startup.subtle_text_wrapped("Total starts when the method is queued. Active starts when advertising actually turns on.")
end

function startup.render_advertise_benchmark_history_panel()
    if not ClickGUI.BeginCustomChildWindow("Advertising Timer History") then return end
    startup.section_title("Advertising Timer History")
    startup.subtle_text_wrapped("Every Current, Old v1.0.3, and Super Advertise run is saved. Successful runs are ranked by Total time to 30 players; Active time isolates post-activation performance.")
    ImGui.Separator()
    local history = startup.s.advertiseBenchmarkHistory or {}
    local successCount = 0
    for _, item in ipairs(history) do if item.reachedTarget == true then successCount = successCount + 1 end end
    startup.status_line("Saved runs", tostring(#history) .. " | Reached 30: " .. tostring(successCount), 0.42, 0.82, 1.00)
    for _, mode in ipairs({"CURRENT", "OLD_V103", "SUPER"}) do
        local best = startup.advertise_benchmark_best(mode)
        local label = startup.advertise_benchmark_mode_label(mode)
        if best then
            startup.status_line("Best " .. label,
                "Total " .. tostring(best.totalText or startup.advertise_benchmark_format_ms(best.totalToTargetMs))
                .. " | Active " .. tostring(best.activeText or startup.advertise_benchmark_format_ms(best.activeToTargetMs))
                .. " | " .. tostring(best.startPlayers or 0) .. ">30",
                0.35, 1.00, 0.45)
        else
            startup.status_line("Best " .. label, "No successful 30-player run yet", 0.72, 0.72, 0.72)
        end
    end
    ImGui.Separator()
    startup.subtle_text("Recent runs")
    local shown = 0
    for _, item in ipairs(history) do
        shown = shown + 1
        local line = tostring(item.startedAt or "Unknown time") .. " | " .. tostring(item.modeLabel or startup.advertise_benchmark_mode_label(item.mode))
            .. " | " .. tostring(item.outcome or "Saved")
            .. " | " .. tostring(item.startPlayers or 0) .. ">" .. tostring(item.endPlayers or 0)
            .. " | Total " .. tostring(item.totalText or startup.advertise_benchmark_format_ms(item.totalToTargetMs or item.durationMs))
            .. " | Active " .. tostring(item.activeText or startup.advertise_benchmark_format_ms(item.activeToTargetMs or item.activeDurationMs))
        if ImGui.TextWrapped then ImGui.TextWrapped(line) else ImGui.Text(line) end
        if shown >= 8 then break end
    end
    if shown == 0 then startup.subtle_text("No advertising timer history yet.") end
    ImGui.Separator()
    startup.subtle_text_wrapped("CSV: " .. tostring(startup.AdvertiseBenchmarkCsvFile or ""))
    startup.render_color_button("Copy Timer History CSV Path", "Blue", "Copies the exact CSV history path.", startup.advertise_benchmark_copy_history_path, -1)
    startup.render_color_button("Clear Timer History", "Red", "Clears saved timer history and starts a fresh CSV.", startup.advertise_benchmark_clear_history, -1)
    ClickGUI.EndCustomChildWindow()
end

function startup.old_v103_set_session(enabled)
    enabled = enabled == true
    local feature, matchedName = startup.get_advertise_session_feature()
    if not feature then
        startup.s.oldStartupAdvertiseStatus = "Advertise Session unavailable"
        startup.advertise_research_log("OLD_V103", "SESSION_WRITE_FAILED", "control=unavailable")
        return false
    end
    local before = startup.get_feature_bool_state(feature)
    if before ~= nil and before == enabled then
        startup.s.advertiseSessionEnabled = enabled
        return true
    end
    local ok = direct_call(function()
        if feature.SetBoolValue then
            feature:SetBoolValue(enabled)
            if feature.TriggerCallback then feature:TriggerCallback()
            elseif feature.OnClick then feature:OnClick() end
        elseif feature.Toggle then
            feature:Toggle(enabled)
        elseif before ~= nil and before ~= enabled and feature.OnClick then
            feature:OnClick()
        elseif before ~= nil and before ~= enabled and feature.TriggerCallback then
            feature:TriggerCallback()
        end
    end)
    local after = startup.get_feature_bool_state(feature)
    if ok and after ~= nil and after ~= enabled and feature.Toggle then
        direct_call(function() feature:Toggle(enabled) end)
        after = startup.get_feature_bool_state(feature)
    end
    startup.s.advertiseSessionEnabled = enabled
    startup.advertise_research_log("OLD_V103", "SESSION_WRITE",
        "requested=" .. tostring(enabled) ..
        " before=" .. tostring(before) ..
        " after=" .. tostring(after) ..
        " control=" .. tostring(matchedName or "resolved"))
    return ok == true and (after == nil or after == enabled)
end

function startup.old_v103_set_count(value, reason)
    value = tonumber(value or 5) or 5
    value = value >= 10 and 10 or 5
    local previous = tonumber(startup.s.oldStartupAdvertiseCurrentCount or 0) or 0
    local hash = startup.feature_hash and startup.feature_hash.ADVERTISE_COUNT or 4100757571
    local ok = startup.set_int_feature_by_names(startup.advertise_count_names, value, hash)
    if ok then
        startup.s.oldStartupAdvertiseCurrentCount = value
        startup.s.advertiseCurrentCount = value
        if value ~= previous then
            startup.advertise_research_log("OLD_V103", "COUNT_CHANGE",
                "from=" .. tostring(previous) ..
                " to=" .. tostring(value) ..
                " players=" .. tostring(startup.get_session_player_count()) ..
                " reason=" .. tostring(reason or "v1.0.3 smart state"))
        end
    else
        startup.advertise_research_log("OLD_V103", "COUNT_WRITE_FAILED", "requested=" .. tostring(value))
    end
    return ok == true
end

function startup.stop_old_startup_advertise(reason, turnSessionOff)
    startup.s.oldStartupAdvertiseSerial = (tonumber(startup.s.oldStartupAdvertiseSerial or 0) or 0) + 1
    local wasRunning = startup.s.oldStartupAdvertiseRunning == true
    startup.s.oldStartupAdvertiseRunning = false
    startup.s.oldStartupAdvertiseStartedAtMs = 0
    startup.s.oldStartupAdvertiseLastHeartbeatMs = 0
    startup.s.oldStartupAdvertiseStatus = startup.s.oldStartupAdvertiseEnabled == true
        and ("Stopped: " .. tostring(reason or "requested")) or "OFF"
    if turnSessionOff == true then startup.old_v103_set_session(false) end
    if wasRunning then
        if startup.s.advertiseBenchmarkActive == true and tostring(startup.s.advertiseBenchmarkMode or "") == "OLD_V103" and startup.advertise_benchmark_finalize then
            startup.advertise_benchmark_finalize("STOPPED", tostring(reason or "Old v1.0.3 stopped"), true)
        end
        startup.advertise_research_log("OLD_V103", "STOPPED",
            "reason=" .. tostring(reason or "requested") ..
            " players=" .. tostring(startup.get_session_player_count()))
    end
end

function startup.run_old_startup_advertise(reason)
    if startup.s.oldStartupAdvertiseEnabled ~= true then return false end
    if startup.is_enhanced_active_edition() then
        startup.s.oldStartupAdvertiseEnabled = false
        startup.s.oldStartupAdvertiseStatus = "Unavailable on Enhanced; use Current Auto Advertise"
        startup.set_feature_bool_silently(startup.h.OldStartupAdvertise, false)
        startup.advertise_research_log("OLD_V103", "REFUSED", "edition=Enhanced reason=Legacy-only v1.0.3 method")
        startup.toast("Old Startup Advertising Method is Legacy-only. Use Auto Advertise Session on Enhanced.", 6000)
        if startup.s.initialized then startup.save_config(false) end
        return false
    end
    if startup.s.oldStartupAdvertiseRunning then return false end

    startup.s.oldStartupAdvertiseSerial = (tonumber(startup.s.oldStartupAdvertiseSerial or 0) or 0) + 1
    local serial = startup.s.oldStartupAdvertiseSerial
    startup.s.oldStartupAdvertiseRunning = true
    if startup.advertise_benchmark_start then startup.advertise_benchmark_start("OLD_V103", reason or "manual") end
    startup.s.oldStartupAdvertiseCurrentCount = 0
    startup.s.oldStartupAdvertiseStartedAtMs = startup.now()
    startup.s.oldStartupAdvertiseLastHeartbeatMs = startup.s.oldStartupAdvertiseStartedAtMs
    startup.s.oldStartupAdvertiseStatus = "Queued: waiting 2 minutes"
    startup.advertise_research_log("OLD_V103", "QUEUED",
        "reason=" .. tostring(reason or "manual") ..
        " players=" .. tostring(startup.get_session_player_count()) ..
        " delayMs=" .. tostring(startup.s.advertiseDelayAfterSessionMs or 120000))

    local job = function()
        startup.old_v103_set_session(false)
        startup.yield(startup.s.advertiseDelayAfterSessionMs or 120000)
        if serial ~= startup.s.oldStartupAdvertiseSerial or startup.s.oldStartupAdvertiseEnabled ~= true then return end

        if not startup.old_v103_set_session(true) then
            startup.s.oldStartupAdvertiseRunning = false
            startup.s.oldStartupAdvertiseStatus = "Failed to enable Advertise Session"
            if startup.advertise_benchmark_finalize then startup.advertise_benchmark_finalize("FAILED", "Old v1.0.3 Advertise Session could not be enabled") end
            return
        end
        startup.old_v103_set_count(startup.s.advertiseLowCount or 5, "v1.0.3 initial soft start")
        if startup.advertise_benchmark_mark_active then startup.advertise_benchmark_mark_active("OLD_V103") end
        startup.s.oldStartupAdvertiseStatus = "Active: direct v1.0.3 smart count"
        startup.advertise_research_log("OLD_V103", "ACTIVATED",
            "players=" .. tostring(startup.get_session_player_count()) ..
            " count=" .. tostring(startup.s.oldStartupAdvertiseCurrentCount or 5))

        local elapsed = 0
        local escalated = false
        while serial == startup.s.oldStartupAdvertiseSerial and startup.s.oldStartupAdvertiseEnabled == true do
            local playerCount = startup.get_session_player_count()
            local highLimit = tonumber(startup.s.advertisePlayerTarget or 30) or 30
            local resumeBelow = tonumber(startup.s.advertiseResumeBelow or 25) or 25
            local lowCount = tonumber(startup.s.advertiseLowCount or 5) or 5
            local highCount = tonumber(startup.s.advertiseHighCount or 10) or 10

            if not escalated and elapsed >= (startup.s.advertiseCount5DurationMs or 300000) and playerCount < highLimit then
                escalated = true
                startup.old_v103_set_count(highCount, "v1.0.3 five-minute fallback below high limit")
            end
            if playerCount >= highLimit then
                startup.old_v103_set_session(true)
                startup.old_v103_set_count(lowCount, "v1.0.3 soft hold at high limit")
                startup.s.oldStartupAdvertiseStatus = "Soft hold: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " | count " .. tostring(lowCount)
            elseif playerCount < resumeBelow then
                startup.old_v103_set_session(true)
                startup.old_v103_set_count(highCount, "v1.0.3 re-boost below resume threshold")
                startup.s.oldStartupAdvertiseStatus = "Re-boost: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " | count " .. tostring(highCount)
            else
                startup.old_v103_set_session(true)
                startup.s.oldStartupAdvertiseStatus = "Maintaining: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " | count " .. tostring(startup.s.oldStartupAdvertiseCurrentCount or "?")
            end

            local nowMs = startup.now()
            if nowMs - (tonumber(startup.s.oldStartupAdvertiseLastHeartbeatMs or 0) or 0) >= 60000 then
                startup.s.oldStartupAdvertiseLastHeartbeatMs = nowMs
                startup.advertise_research_log("OLD_V103", "HEARTBEAT",
                    "players=" .. tostring(playerCount) ..
                    " count=" .. tostring(startup.s.oldStartupAdvertiseCurrentCount or "?") ..
                    " elapsedMs=" .. tostring(elapsed))
            end
            startup.yield(startup.s.advertisePlayerCheckMs or 5000)
            elapsed = elapsed + (startup.s.advertisePlayerCheckMs or 5000)
        end

        if serial == startup.s.oldStartupAdvertiseSerial then
            startup.s.oldStartupAdvertiseRunning = false
            startup.s.oldStartupAdvertiseStatus = startup.s.oldStartupAdvertiseEnabled and "Stopped" or "OFF"
        end
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
    return true
end

function startup.should_run_any_advertise_mode()
    return startup.s.oldStartupAdvertiseEnabled == true or startup.s.autoAdvertiseSession == true
end

function startup.run_selected_advertise_flow(reason)
    if startup.s.oldStartupAdvertiseEnabled == true then
        return startup.run_old_startup_advertise(reason)
    end
    if startup.s.autoAdvertiseSession == true then
        return startup.run_advertise_flow(reason)
    end
    startup.s.lastAdvertiseStatus = "All advertising modes OFF"
    startup.advertise_research_log("CURRENT", "SKIPPED", "reason=" .. tostring(reason or "session") .. " modes=off")
    return false
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- lua startup runner
-- note: discovers local scripts and applies master or per-file spacing.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.find_local_lua_files()
    local found = {}
    local folders = {
        startup.lua_content_dir,
        startup.lua_dir
    }
    for _, folderPath in ipairs(folders) do
        local files = FileMgr.FindFiles(folderPath, ".lua", false)
        if files then
            for _, path in ipairs(files) do
                if not startup.is_startup_lua(path) and not startup.path_exists_in_list(found, path) then
                    table.insert(found, path)
                end
            end
        end
    end
    table.sort(found, function(a, b)
        return string.lower(startup.get_file_name(a)) < string.lower(startup.get_file_name(b))
    end)
    return found
end

function startup.refresh_lua_file_list()
    local files = startup.find_local_lua_files()
    startup.s.luaFiles = {}
    startup.s.luaFileDelaysMs = startup.s.luaFileDelaysMs or {}
    startup.s.luaFileDelayOverrides = startup.s.luaFileDelayOverrides or {}
    local selectedFound = false
    for index, path in ipairs(files) do
        if startup.s.luaFileStates[path] == nil then startup.s.luaFileStates[path] = false end
        if tostring(startup.s.selectedLuaFilePath or "") == tostring(path) then selectedFound = true end
        table.insert(startup.s.luaFiles, {
            index = index,
            path = path,
            name = startup.get_file_name(path),
            hash = startup.hash("RUN_ON_STARTUP_" .. tostring(index) .. "_" .. startup.get_file_name(path))
        })
    end
    if not selectedFound then
        startup.s.selectedLuaFilePath = ""
        for _, entry in ipairs(startup.s.luaFiles) do
            if startup.s.luaFileStates[entry.path] == true then
                startup.s.selectedLuaFilePath = entry.path
                break
            end
        end
        if startup.s.selectedLuaFilePath == "" and startup.s.luaFiles[1] then
            startup.s.selectedLuaFilePath = startup.s.luaFiles[1].path
        end
    end
    startup.save_config(false)
    startup.s.lastLuaStatus = "Found " .. tostring(#startup.s.luaFiles) .. " Lua file(s)"
end

function startup.get_lua_file_entry(path)
    path = tostring(path or startup.s.selectedLuaFilePath or "")
    for _, entry in ipairs(startup.s.luaFiles or {}) do
        if tostring(entry.path) == path then return entry end
    end
    return nil
end

function startup.is_lua_file_delay_overridden(path)
    return startup.s.luaFileDelayOverrides and startup.s.luaFileDelayOverrides[tostring(path or "")] == true
end

function startup.get_lua_file_delay_ms(path)
    path = tostring(path or "")
    local master = startup.clamp_int(startup.s.luaDelayBetweenFilesMs or 5000, 0, 300000)
    if not startup.is_lua_file_delay_overridden(path) then return master end
    return startup.clamp_int((startup.s.luaFileDelaysMs or {})[path] or master, 0, 300000)
end

function startup.set_lua_file_delay_override(path, enabled)
    path = tostring(path or "")
    if path == "" then return end
    startup.s.luaFileDelayOverrides = startup.s.luaFileDelayOverrides or {}
    startup.s.luaFileDelaysMs = startup.s.luaFileDelaysMs or {}
    startup.s.luaFileDelayOverrides[path] = enabled == true
    if enabled and startup.s.luaFileDelaysMs[path] == nil then
        startup.s.luaFileDelaysMs[path] = startup.clamp_int(startup.s.luaDelayBetweenFilesMs or 5000, 0, 300000)
    end
    startup.save_config(false)
end

function startup.set_lua_file_delay_ms(path, delayMs)
    path = tostring(path or "")
    if path == "" then return end
    startup.s.luaFileDelaysMs = startup.s.luaFileDelaysMs or {}
    startup.s.luaFileDelayOverrides = startup.s.luaFileDelayOverrides or {}
    startup.s.luaFileDelaysMs[path] = startup.clamp_int(delayMs or 5000, 0, 300000)
    startup.s.luaFileDelayOverrides[path] = true
    startup.save_config(false)
end

function startup.execute_lua_file(path)
    if not path or path == "" then
        return false
    end
    local fileName = startup.get_file_name(path)
    startup.s.lastLuaStatus = "Running: " .. fileName
    startup.toast("Running Lua file: " .. fileName, 2500)
    local ok = Utils.ExecuteScript(path)
    if ok ~= nil then
        startup.s.lastLuaStatus = "Executed: " .. fileName
        startup.toast("Executed Lua file: " .. fileName, 2500)
        return true
    end
    startup.s.lastLuaStatus = "Failed: " .. fileName
    startup.error("Failed to execute Lua file: " .. fileName)
    return false
end

function startup.get_enabled_lua_files()
    local enabled = {}
    startup.refresh_lua_file_list()
    for _, entry in ipairs(startup.s.luaFiles) do
        if startup.s.luaFileStates[entry.path] == true then
            table.insert(enabled, entry)
        end
    end
    return enabled
end

function startup.run_enabled_lua_files()
    if not startup.s.autoRunLuaFiles then
        startup.s.lastLuaStatus = "Auto-Run Local Lua Files OFF"
        startup.toast("Auto-Run Local Lua Files is OFF.", 2500)
        return
    end
    if startup.s.luaStartupRunning then
        startup.toast("Lua startup runner is already running.", 2500)
        return
    end
    local enabled = startup.get_enabled_lua_files()
    if #enabled == 0 then
        startup.s.lastLuaStatus = "No Lua files enabled"
        startup.toast("No LuaContent files are enabled for startup yet.", 3000)
        return
    end
    startup.s.luaStartupRunning = true
    startup.s.lastLuaStartupRunMs = startup.now()
    startup.toast("Loading " .. tostring(#enabled) .. " enabled Lua file(s).", 3000)
    for index, entry in ipairs(enabled) do
        startup.s.lastLuaStatus = "Loading " .. tostring(index) .. "/" .. tostring(#enabled) .. ": " .. entry.name
        startup.execute_lua_file(entry.path)
        if index < #enabled then
            local delayMs = startup.get_lua_file_delay_ms(entry.path)
            local nextName = enabled[index + 1].name
            startup.s.lastLuaStatus = "Next: " .. tostring(nextName) .. " in " .. startup.format_seconds(delayMs)
            if delayMs > 0 then startup.yield(delayMs) end
        end
    end
    startup.s.luaStartupRunning = false
    startup.s.lastLuaStatus = "Finished loading enabled Lua files"
    startup.toast("Finished loading enabled Lua startup files.", 3000)
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- experimental cherax host diagnostic and lobby filters
-- note: all 30/50 host checks are read-only. No kick, crash, script event, entity,
-- explosion, chat injection, or forced player interaction is performed.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.cherax_host_probe = startup.cherax_host_probe or {
    busy = false,
    lastResult = nil
}
startup.lobby_filter = startup.lobby_filter or {
    sessionSerial = 0,
    running = false,
    hopRequested = false,
    forceImmediate = false
}
startup.pendingCheraxHostProbe = false
startup.pendingCheraxHostProbeMethods = 30
startup.pendingCheraxHostProbeKnownPositive = false
startup.cheraxHostProbeJobQueued = false

function startup.cherax_host_probe.raw_modder_reasons(playerId)
    local reasons = {}
    if not ModderDB or not ModderDB.GetModderDetectionsByPlayerId then return reasons end
    local detections = ModderDB.GetModderDetectionsByPlayerId(playerId)
    if type(detections) ~= "table" then return reasons end
    for _, detection in pairs(detections) do
        local reason = ""
        if type(detection) == "table" then
            reason = tostring(detection[1] or detection.name or detection.detection or detection.reason or "")
        elseif type(detection) == "string" then
            reason = detection
        end
        reason = tostring(reason or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if reason ~= "" then reasons[#reasons + 1] = reason end
    end
    table.sort(reasons, function(a, b) return string.lower(a) < string.lower(b) end)
    return reasons
end

function startup.cherax_host_probe.player_id_from_object(object)
    if not object then return nil end
    return tonumber(object.PlayerId)
end

function startup.cherax_host_probe.safe_value(fn, fallback)
    local ok, value = direct_call(fn)
    if ok then return value end
    return fallback
end

function startup.cherax_host_probe.capture_host_snapshot(label)
    local snapshot = {
        label = tostring(label or "snapshot"),
        capturedAtMs = startup.now(),
        hostName = "Unknown",
        hostId = -1,
        scriptHostName = "Unknown",
        scriptHostId = -1,
        tags = "",
        isLocal = nil,
        rid = nil,
        hostKey = nil,
        cxnId = nil,
        playerAddress = nil,
        gamerName = "",
        ipString = "",
        netType = nil,
        cpedAddress = nil,
        playerInfoAddress = nil,
        playerInfoNetRid = nil,
        playerInfoNetHostKey = nil,
        playerState = nil,
        playerTeam = nil,
        friendStatus = nil
    }

    local hostName, hostId = startup.get_session_host_name()
    snapshot.hostName = tostring(hostName or "Unknown")
    snapshot.hostId = tonumber(hostId) or -1

    local scriptHostName, scriptHostId = startup.get_script_host_name()
    snapshot.scriptHostName = tostring(scriptHostName or "Unknown")
    snapshot.scriptHostId = tonumber(scriptHostId) or -1

    if snapshot.hostId < 0 or snapshot.hostId > 31 then
        return snapshot
    end

    if Players and Players.GetTags then
        snapshot.tags = tostring(startup.cherax_host_probe.safe_value(function()
            return Players.GetTags(snapshot.hostId)
        end, "") or "")
    end

    local player = nil
    if Players and Players.GetById then
        player = startup.cherax_host_probe.safe_value(function()
            return Players.GetById(snapshot.hostId)
        end, nil)
    end
    if not player then return snapshot end

    snapshot.cxnId = tonumber(startup.cherax_host_probe.safe_value(function()
        return player.CxnId
    end, nil))

    snapshot.playerAddress = tonumber(startup.cherax_host_probe.safe_value(function()
        if player.GetAddress then return player:GetAddress() end
        return nil
    end, nil))

    snapshot.isLocal = startup.cherax_host_probe.safe_value(function()
        if player.IsLocalPlayer then return player:IsLocalPlayer() == true end
        return nil
    end, nil)

    local gamerInfo = startup.cherax_host_probe.safe_value(function()
        if player.GetGamerInfo then return player:GetGamerInfo() end
        return nil
    end, nil)

    if gamerInfo then
        snapshot.gamerName = tostring(startup.cherax_host_probe.safe_value(function()
            return gamerInfo.Name
        end, "") or "")
        snapshot.rid = tonumber(startup.cherax_host_probe.safe_value(function()
            return gamerInfo.RockstarId
        end, nil))
        local hostKey = startup.cherax_host_probe.safe_value(function()
            return gamerInfo.HostKey
        end, nil)
        if hostKey ~= nil then snapshot.hostKey = tostring(hostKey) end
    end

    if Players and Players.GetIPString then
        snapshot.ipString = tostring(startup.cherax_host_probe.safe_value(function()
            return Players.GetIPString(snapshot.hostId)
        end, "") or "")
    end

    if Players and Players.GetNetAddress then
        local netAddress = startup.cherax_host_probe.safe_value(function()
            return Players.GetNetAddress(snapshot.hostId)
        end, nil)
        if netAddress then
            snapshot.netType = startup.cherax_host_probe.safe_value(function()
                return netAddress.Type
            end, nil)
        end
    end

    if Players and Players.GetCPed then
        local cped = startup.cherax_host_probe.safe_value(function()
            return Players.GetCPed(snapshot.hostId)
        end, nil)
        if cped then
            snapshot.cpedAddress = tonumber(startup.cherax_host_probe.safe_value(function()
                if cped.GetAddress then return cped:GetAddress() end
                return nil
            end, nil))
        end
    end

    local playerInfo = startup.cherax_host_probe.safe_value(function()
        return player.PlayerInfo
    end, nil)

    if playerInfo then
        snapshot.playerState = tonumber(startup.cherax_host_probe.safe_value(function()
            return playerInfo.PlayerState
        end, nil))
        snapshot.playerTeam = tonumber(startup.cherax_host_probe.safe_value(function()
            return playerInfo.Team
        end, nil))
        snapshot.friendStatus = tonumber(startup.cherax_host_probe.safe_value(function()
            return playerInfo.FriendStatus
        end, nil))

        local playerInfoPed = startup.cherax_host_probe.safe_value(function()
            return playerInfo.PlayerPed
        end, nil)
        if playerInfoPed then
            snapshot.playerInfoAddress = tonumber(startup.cherax_host_probe.safe_value(function()
                if playerInfoPed.GetAddress then return playerInfoPed:GetAddress() end
                return nil
            end, nil))
        end

        local netData = startup.cherax_host_probe.safe_value(function()
            return playerInfo.NetData
        end, nil)
        if netData then
            snapshot.playerInfoNetRid = tonumber(startup.cherax_host_probe.safe_value(function()
                return netData.RockstarId
            end, nil))
            local netHostKey = startup.cherax_host_probe.safe_value(function()
                return netData.HostKey
            end, nil)
            if netHostKey ~= nil then snapshot.playerInfoNetHostKey = tostring(netHostKey) end
        end
    end

    return snapshot
end

function startup.cherax_host_probe.snapshot_line(snapshot)
    snapshot = type(snapshot) == "table" and snapshot or {}
    return table.concat({
        "label=" .. tostring(snapshot.label or ""),
        "host=" .. tostring(snapshot.hostName or "Unknown") .. " [" .. tostring(snapshot.hostId or -1) .. "]",
        "scriptHost=" .. tostring(snapshot.scriptHostName or "Unknown") .. " [" .. tostring(snapshot.scriptHostId or -1) .. "]",
        "rid=" .. tostring(snapshot.rid),
        "hostKey=" .. tostring(snapshot.hostKey),
        "cxn=" .. tostring(snapshot.cxnId),
        "playerAddress=" .. tostring(snapshot.playerAddress),
        "tags=" .. tostring(snapshot.tags or ""),
        "isLocal=" .. tostring(snapshot.isLocal),
        "netType=" .. tostring(snapshot.netType),
        "cpedAddress=" .. tostring(snapshot.cpedAddress),
        "playerInfoPedAddress=" .. tostring(snapshot.playerInfoAddress),
        "netDataRid=" .. tostring(snapshot.playerInfoNetRid),
        "netDataHostKey=" .. tostring(snapshot.playerInfoNetHostKey),
        "state=" .. tostring(snapshot.playerState),
        "team=" .. tostring(snapshot.playerTeam),
        "friendStatus=" .. tostring(snapshot.friendStatus),
        "connection=" .. tostring(snapshot.ipString or "")
    }, " | ")
end

function startup.cherax_host_probe.lock_matches(lockSnapshot, currentSnapshot)
    lockSnapshot = type(lockSnapshot) == "table" and lockSnapshot or {}
    currentSnapshot = type(currentSnapshot) == "table" and currentSnapshot or {}
    local changed = {}

    local function compare(field, required)
        local a = lockSnapshot[field]
        local b = currentSnapshot[field]
        if required == true or (a ~= nil and tostring(a) ~= "" and b ~= nil and tostring(b) ~= "") then
            if tostring(a) ~= tostring(b) then
                changed[#changed + 1] = tostring(field) .. ":" .. tostring(a) .. "->" .. tostring(b)
            end
        end
    end

    compare("hostId", true)
    compare("hostName", true)
    compare("rid", false)
    compare("hostKey", false)
    compare("cxnId", false)

    return #changed == 0, changed
end

function startup.cherax_host_probe.three_snapshot_stability(snapshots)
    snapshots = type(snapshots) == "table" and snapshots or {}
    if #snapshots < 3 then return 0, 0, { "fewer than three snapshots" } end

    local fields = {
        "hostId", "hostName", "rid", "hostKey", "cxnId", "playerAddress",
        "tags", "isLocal", "netType", "cpedAddress", "playerInfoAddress",
        "playerInfoNetRid", "playerInfoNetHostKey", "playerState", "playerTeam",
        "friendStatus"
    }

    local stable = 0
    local changed = {}
    for _, field in ipairs(fields) do
        local a = tostring(snapshots[1][field])
        local b = tostring(snapshots[2][field])
        local c = tostring(snapshots[3][field])
        if a == b and b == c then
            stable = stable + 1
        else
            changed[#changed + 1] = tostring(field) .. "=" .. a .. " / " .. b .. " / " .. c
        end
    end
    return stable, #fields, changed
end

function startup.cherax_host_probe.write_report(result, snapshots, reasonLabel, abortedReason)
    startup.ensure_save_dir()
    if FileMgr and FileMgr.CreateDir then
        direct_call(FileMgr.CreateDir, startup.diagnostics_dir)
    end

    result = type(result) == "table" and result or {}
    snapshots = type(snapshots) == "table" and snapshots or {}
    local hostName = tostring(result.hostName or (snapshots[1] and snapshots[1].hostName) or "Unknown")
    local safeHost = hostName:gsub("[^%w%-%._]", "_")
    if safeHost == "" then safeHost = "Unknown" end
    local stamp = os.date("%Y%m%d_%H%M%S")
    local path = tostring(startup.diagnostics_dir or startup.storage_dir or ".")
        .. "\\Cherax_Host_50_Known_Positive_" .. stamp .. "_" .. safeHost .. ".txt"

    local lines = {
        "STARTUP EE KNOWN-POSITIVE CHERAX HOST TEST",
        "==========================================",
        "",
        "Startup version: " .. tostring(startup.version or "Unknown"),
        "Startup build: " .. tostring(startup.build_number or "Unknown"),
        "Captured: " .. os.date("%Y-%m-%d %H:%M:%S"),
        "Reason: " .. tostring(reasonLabel or "manual"),
        "Expected remote menu: Cherax (user-confirmed positive control)",
        "Safety: read-only; no kick, crash, script event, entity, explosion, chat, or forced interaction",
        "Aborted: " .. tostring(result.aborted == true),
        "Abort reason: " .. tostring(abortedReason or result.abortReason or ""),
        "",
        "Host: " .. tostring(result.hostName or hostName),
        "Player ID: " .. tostring(result.hostId),
        "Rockstar ID: " .. tostring(result.rid),
        "Methods completed: " .. tostring(#(result.probes or {})) .. "/50",
        "Verdict: " .. tostring(result.verdict or "Unknown"),
        "Explicit Cherax signals: " .. tostring(result.explicitSignals or 0),
        "Brand-neutral menu signals: " .. tostring(result.menuSignals or 0),
        "Deep anomaly signals: " .. tostring(result.deepSignals or 0),
        "Three-snapshot stability: " .. tostring(result.stabilityText or "Not measured"),
        "",
        "IMPORTANT",
        "---------",
        "Host tags, HostKey, RID, network objects, player-state values, and modder detections are brand-neutral.",
        "They are useful for a stable fingerprint, but they do not prove Cherax unless a Cherax-specific token is exposed.",
        "",
        "SNAPSHOTS",
        "---------"
    }

    for index, snapshot in ipairs(snapshots) do
        lines[#lines + 1] = tostring(index) .. ". " .. startup.cherax_host_probe.snapshot_line(snapshot)
    end

    local stable, total, changed = startup.cherax_host_probe.three_snapshot_stability(snapshots)
    lines[#lines + 1] = ""
    lines[#lines + 1] = "Stable fields: " .. tostring(stable) .. "/" .. tostring(total)
    lines[#lines + 1] = "Changed fields: " .. (#changed > 0 and table.concat(changed, " | ") or "<none>")
    lines[#lines + 1] = ""
    lines[#lines + 1] = "METHOD RESULTS"
    lines[#lines + 1] = "--------------"

    for _, row in ipairs(result.probes or {}) do
        lines[#lines + 1] = string.format(
            "%02d/50 %s | %s | %s",
            tonumber(row.index or 0) or 0,
            row.passed == true and "PASS" or "MISS",
            tostring(row.label or ""),
            tostring(row.detail or "")
        )
    end

    lines[#lines + 1] = ""
    lines[#lines + 1] = "FINGERPRINT"
    lines[#lines + 1] = "-----------"
    lines[#lines + 1] = tostring(result.fingerprint or "")
    lines[#lines + 1] = ""

    if startup.try_write_file(path, table.concat(lines, "\n") .. "\n") then
        startup.s.cheraxHostProbeLastReportPath = path
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("CHERAX_HOST_POSITIVE_REPORT", "path=" .. tostring(path) .. " host=" .. tostring(hostName))
        end
        return path
    end

    startup.s.cheraxHostProbeLastReportPath = ""
    return ""
end

function startup.copy_cherax_host_probe_report_path()
    local path = tostring(startup.s.cheraxHostProbeLastReportPath or "")
    if path == "" then
        startup.toast("Run the EE known-positive 50-method test first.", 3500)
        return false
    end
    local copied = startup.copy_to_clipboard(path)
    startup.toast(copied and "Known-positive host report path copied." or "Could not copy the report path.", 3500)
    return copied
end

function startup.cherax_host_probe.run(reasonLabel, requestedMethodCount, options)
    local methodCount = tonumber(requestedMethodCount) == 50 and 50 or 30
    local opts = type(options) == "table" and options or {}
    local knownPositive = opts.knownCherax == true

    if startup.cherax_host_probe.busy == true then
        startup.s.cheraxHostProbeStatus = "A Cherax Host Test is already running."
        return startup.cherax_host_probe.lastResult
    end

    if knownPositive and not startup.is_enhanced_active_edition() then
        startup.s.cheraxHostProbeStatus = "EE is required for the known-positive 50-method test."
        startup.toast("The known-positive 50-method test is available on EE only.", 4000)
        return startup.cherax_host_probe.lastResult
    end

    startup.cherax_host_probe.busy = true

    local hostName, hostId = startup.get_session_host_name()
    hostId = tonumber(hostId) or -1
    hostName = tostring(hostName or "Unknown")
    local probes = {}
    local snapshots = {}
    local explicitSignals = 0
    local menuSignals = 0
    local tags = ""
    local player = nil
    local gamerInfo = nil
    local rid = nil
    local hostKey = nil
    local cxnId = nil
    local playerAddress = nil
    local ipAddress = nil
    local ipString = ""
    local netAddress = nil
    local netAddressType = nil
    local cped = nil
    local cpedAddress = nil
    local rawReasons = {}
    local racReasons = {}
    local playerInfo = nil
    local playerInfoNetData = nil
    local playerInfoPed = nil
    local playerInfoPedAddress = nil
    local playerState = nil
    local playerTeam = nil
    local friendStatus = nil
    local playerMaxHealth = nil
    local playerMaxArmour = nil
    local weaponDamageModifier = nil
    local meleeWeaponDamageModifier = nil
    local meleeUnarmedDamageModifier = nil
    local vehicleDamageModifier = nil
    local explosiveDamageModifier = nil
    local sprintMultiplier = nil
    local deepSignals = 0
    local stabilityText = "Not measured"
    local initialSnapshot = startup.cherax_host_probe.capture_host_snapshot("1/3 initial")
    snapshots[#snapshots + 1] = initialSnapshot

    local function finish_early(statusText, toastText)
        startup.s.cheraxHostProbeStatus = tostring(statusText or "Host test stopped.")
        startup.cherax_host_probe.busy = false
        if toastText and tostring(toastText) ~= "" then startup.toast(tostring(toastText), 4500) end
        return startup.cherax_host_probe.lastResult
    end

    if hostId < 0 or hostId > 31 or hostName == "" or hostName == "Unknown" or hostName == "Invalid" then
        return finish_early("No valid Session Host is available.", "No valid Session Host is available for testing.")
    end

    if knownPositive and startup.is_local_player_id(hostId) then
        return finish_early(
            "Known-positive test requires a remote Session Host.",
            "The current Session Host is you. Use a remote confirmed Cherax host for this test."
        )
    end

    local function host_lock_quick(stage)
        if not knownPositive then return true end
        local currentSnapshot = startup.cherax_host_probe.capture_host_snapshot(tostring(stage or "checkpoint"))
        local same, changed = startup.cherax_host_probe.lock_matches(initialSnapshot, currentSnapshot)
        if same then return true end

        local abortReason = tostring(stage or "checkpoint") .. " | " .. table.concat(changed, ", ")
        local partialResult = {
            hostName = hostName,
            hostId = hostId,
            rid = initialSnapshot.rid,
            explicitCherax = false,
            explicitSignals = explicitSignals,
            menuSignals = menuSignals,
            verdict = "ABORTED: SESSION HOST CHANGED",
            fingerprint = startup.cherax_host_probe.snapshot_line(initialSnapshot),
            probes = probes,
            methodCount = methodCount,
            deepSignals = deepSignals,
            knownPositive = true,
            aborted = true,
            abortReason = abortReason,
            stabilityText = "Aborted before three stable snapshots"
        }

        local reportPath = startup.cherax_host_probe.write_report(
            partialResult,
            snapshots,
            reasonLabel,
            abortReason
        )
        startup.cherax_host_probe.lastResult = partialResult
        startup.s.cheraxHostProbeLastVerdict = partialResult.verdict
        startup.s.cheraxHostProbeLastMethodCount = methodCount
        startup.s.cheraxHostProbeLastKnownPositive = true
        startup.s.cheraxHostProbeLastStability = partialResult.stabilityText
        startup.s.cheraxHostProbeStatus = "Known-positive test aborted because the Session Host changed."
        startup.log("[Cherax Host Test] ABORT | " .. abortReason .. " | report=" .. tostring(reportPath))
        startup.cherax_host_probe.busy = false
        startup.toast("50-method test aborted safely: Session Host changed.", 4500)
        return false
    end

    if knownPositive then
        startup.log("[Cherax Host Test] EE KNOWN-POSITIVE CONTROL | expected=Cherax | host="
            .. tostring(initialSnapshot.hostName) .. " [" .. tostring(initialSnapshot.hostId) .. "]"
            .. " | rid=" .. tostring(initialSnapshot.rid)
            .. " | safety=read-only")
        startup.log("[Cherax Host Test] SNAPSHOT 1/3 | " .. startup.cherax_host_probe.snapshot_line(initialSnapshot))
        if not host_lock_quick("before method 1") then return startup.cherax_host_probe.lastResult end
    end


    local function mark_menu_signal(condition)
        if condition == true then menuSignals = menuSignals + 1 end
    end

    local function emit(index, label, passed, detail)
        local status = passed == true and "PASS" or "MISS"
        local row = {
            index = index,
            label = tostring(label or ""),
            passed = passed == true,
            detail = tostring(detail or "")
        }
        probes[#probes + 1] = row
        startup.log(string.format("[Cherax Host Test] %02d/%02d %s | %s | %s", index, methodCount, status, row.label, row.detail))
        if Script and Script.Yield then Script.Yield(35) end
    end

    startup.s.cheraxHostProbeStatus = "Running " .. tostring(methodCount) .. " read-only methods against the current Session Host..."
    startup.s.cheraxHostProbeLastHostName = hostName
    startup.s.cheraxHostProbeLastHostId = hostId
    startup.log("[Cherax Host Test] BEGIN | methods=" .. tostring(methodCount) .. " | reason=" .. tostring(reasonLabel or "manual") .. " | host=" .. hostName .. " | playerId=" .. tostring(hostId) .. " | safety=read-only")

    emit(1, "Native Session Host index", hostId >= 0 and hostId <= 31, "playerId=" .. tostring(hostId))

    emit(2, "Session Host name", hostName ~= "" and hostName ~= "Unknown" and hostName ~= "Invalid", "name=" .. hostName)

    local directName = ""
    if hostId >= 0 and Players and Players.GetName then directName = tostring(Players.GetName(hostId) or "") end
    emit(3, "Players.GetName consistency", directName ~= "" and directName == hostName, "direct=" .. tostring(directName))

    if hostId >= 0 and Players and Players.GetTags then tags = tostring(Players.GetTags(hostId) or "") end
    emit(4, "Cherax player tags readable", tags ~= "", "tags=" .. (tags ~= "" and tags or "<empty>"))

    local hasHostTag = string.find(tags, "[H]", 1, true) ~= nil
    emit(5, "Host tag [H]", hasHostTag, "tags=" .. (tags ~= "" and tags or "<empty>"))

    local scriptHostName, scriptHostId = startup.get_script_host_name()
    local sameScriptHost = tonumber(scriptHostId) == hostId and hostId >= 0
    emit(6, "Session Host is also freemode Script Host", sameScriptHost, "scriptHost=" .. tostring(scriptHostName) .. " [" .. tostring(scriptHostId) .. "]")

    local hasScriptHostTag = string.find(tags, "[SH]", 1, true) ~= nil
    emit(7, "Script Host tag [SH]", hasScriptHostTag, "tags=" .. (tags ~= "" and tags or "<empty>"))

    local hasModderTag = string.find(tags, "[M]", 1, true) ~= nil
    mark_menu_signal(hasModderTag)
    emit(8, "Modder tag [M]", hasModderTag, "tags=" .. (tags ~= "" and tags or "<empty>"))

    local hasFriendTag = string.find(tags, "[F]", 1, true) ~= nil
    emit(9, "Friend tag [F]", hasFriendTag, "tags=" .. (tags ~= "" and tags or "<empty>"))

    if hostId >= 0 and Players and Players.GetById then player = Players.GetById(hostId) end
    emit(10, "CNetGamePlayer by player ID", player ~= nil, "object=" .. tostring(player ~= nil))
    if knownPositive and not host_lock_quick("after method 10") then return startup.cherax_host_probe.lastResult end

    local objectPlayerId = startup.cherax_host_probe.player_id_from_object(player)
    emit(11, "CNetGamePlayer.PlayerId round-trip", objectPlayerId == hostId and hostId >= 0, "objectPlayerId=" .. tostring(objectPlayerId))

    if player then cxnId = tonumber(player.CxnId) end
    emit(12, "Connection ID", cxnId ~= nil and cxnId >= 0, "cxnId=" .. tostring(cxnId))

    if player and player.GetAddress then playerAddress = tonumber(player:GetAddress()) end
    emit(13, "CNetGamePlayer native address", playerAddress ~= nil and playerAddress > 0, "address=" .. tostring(playerAddress))

    local isLocal = nil
    if player and player.IsLocalPlayer then isLocal = player:IsLocalPlayer() == true end
    emit(14, "Remote-player identity", isLocal == false, "isLocal=" .. tostring(isLocal))

    if player and player.GetGamerInfo then gamerInfo = player:GetGamerInfo() end
    emit(15, "GamerInfo object", gamerInfo ~= nil, "available=" .. tostring(gamerInfo ~= nil))

    local gamerName = ""
    if gamerInfo then gamerName = tostring(gamerInfo.Name or "") end
    emit(16, "GamerInfo name consistency", gamerName ~= "" and gamerName == hostName, "gamerName=" .. tostring(gamerName))

    if gamerInfo then rid = tonumber(gamerInfo.RockstarId) end
    emit(17, "Rockstar ID", rid ~= nil and rid > 0, "rid=" .. tostring(rid))

    if gamerInfo then hostKey = gamerInfo.HostKey end
    emit(18, "GamerInfo HostKey", hostKey ~= nil and tostring(hostKey) ~= "" and tostring(hostKey) ~= "0", "hostKey=" .. tostring(hostKey))

    local byRid = nil
    if rid and Players and Players.GetByRockstarId then byRid = Players.GetByRockstarId(rid) end
    emit(19, "Rockstar ID round-trip", startup.cherax_host_probe.player_id_from_object(byRid) == hostId and hostId >= 0, "resolvedPlayerId=" .. tostring(startup.cherax_host_probe.player_id_from_object(byRid)))

    local byCxn = nil
    if cxnId and Players and Players.GetByConId then byCxn = Players.GetByConId(cxnId) end
    emit(20, "Connection ID round-trip", startup.cherax_host_probe.player_id_from_object(byCxn) == hostId and hostId >= 0, "resolvedPlayerId=" .. tostring(startup.cherax_host_probe.player_id_from_object(byCxn)))
    if knownPositive and not host_lock_quick("after method 20") then return startup.cherax_host_probe.lastResult end

    if hostId >= 0 and Players and Players.GetIP then ipAddress = Players.GetIP(hostId) end
    local byIp = nil
    if ipAddress and Players and Players.GetByIP then byIp = Players.GetByIP(ipAddress) end
    emit(21, "Socket address round-trip", startup.cherax_host_probe.player_id_from_object(byIp) == hostId and hostId >= 0, "resolvedPlayerId=" .. tostring(startup.cherax_host_probe.player_id_from_object(byIp)))

    if hostId >= 0 and Players and Players.GetIPString then ipString = tostring(Players.GetIPString(hostId) or "") end
    emit(22, "Readable connection string", ipString ~= "", "connection=" .. (ipString ~= "" and ipString or "<empty>"))

    local country, countryCode = "", ""
    if hostId >= 0 and Players and Players.GetIPInfo then
        local info = Players.GetIPInfo(hostId)
        if info then
            country = tostring(info.country or "")
            countryCode = tostring(info.countryCode or "")
        end
    end
    emit(23, "IP metadata", country ~= "" or countryCode ~= "", "country=" .. tostring(country) .. " code=" .. tostring(countryCode))

    if hostId >= 0 and Players and Players.GetNetAddress then netAddress = Players.GetNetAddress(hostId) end
    emit(24, "NetAddress object", netAddress ~= nil, "available=" .. tostring(netAddress ~= nil))

    if netAddress then netAddressType = netAddress.Type end
    emit(25, "NetAddress type", netAddressType ~= nil, "type=" .. tostring(netAddressType))

    if hostId >= 0 and Players and Players.GetCPed then cped = Players.GetCPed(hostId) end
    emit(26, "Remote CPed object", cped ~= nil, "available=" .. tostring(cped ~= nil))

    if cped and cped.GetAddress then cpedAddress = tonumber(cped:GetAddress()) end
    emit(27, "Remote CPed native address", cpedAddress ~= nil and cpedAddress > 0, "address=" .. tostring(cpedAddress))

    local queueContainsHost = false
    local queueCount = 0
    if Players and Players.Get and ePlayerListSort and ePlayerListSort.HOST_QUEUE ~= nil then
        local rawQueue = Players.Get(ePlayerListSort.HOST_QUEUE, "")
        local queue = startup.normalize_host_queue(rawQueue)
        queueCount = #queue
        for _, entry in ipairs(queue) do
            if tonumber(entry.playerId) == hostId then queueContainsHost = true break end
        end
    end
    emit(28, "Host Queue contains Session Host", queueContainsHost, "queueCount=" .. tostring(queueCount))

    rawReasons = hostId >= 0 and startup.cherax_host_probe.raw_modder_reasons(hostId) or {}
    racReasons = hostId >= 0 and startup.rac_reasons_for_player(hostId) or {}
    local catalogKnown = 0
    local catalogHigh = 0
    local catalogAttack = 0
    local catalogLow = 0
    local catalogIgnored = 0
    for _, detectedReason in ipairs(rawReasons) do
        local category, known = startup.mod_detection.classify_reason(detectedReason)
        if known then catalogKnown = catalogKnown + 1 end
        if category == "high" or category == "battleye" then catalogHigh = catalogHigh + 1 end
        if category == "crash" or category == "kick" then catalogAttack = catalogAttack + 1 end
        if category == "low" then catalogLow = catalogLow + 1 end
        if category == "ignored" then catalogIgnored = catalogIgnored + 1 end
    end
    local hasDetectionSignals = #rawReasons > 0 or #racReasons > 0
    mark_menu_signal(hasDetectionSignals)
    emit(29, "ModderDB / RAC signals (brand-neutral)", hasDetectionSignals,
        "modderDB=" .. tostring(#rawReasons) .. " rac=" .. tostring(#racReasons) ..
        " catalogKnown=" .. tostring(catalogKnown) ..
        " high=" .. tostring(catalogHigh) ..
        " attack=" .. tostring(catalogAttack) ..
        " low=" .. tostring(catalogLow) ..
        " ignored=" .. tostring(catalogIgnored) ..
        " reasons=" .. (#rawReasons > 0 and table.concat(rawReasons, " | ") or "<none>") ..
        " racReasons=" .. (#racReasons > 0 and table.concat(racReasons, " | ") or "<none>"))

    local combined = string.lower(table.concat({ hostName, tags, table.concat(rawReasons, " "), table.concat(racReasons, " ") }, " "))
    local explicitCherax = string.find(combined, "cherax", 1, true) ~= nil
    if explicitCherax then explicitSignals = explicitSignals + 1 end
    emit(30, "Explicit Cherax token", explicitCherax, "searched=name+tags+ModderDB+RAC")

    if knownPositive then
        startup.yield(350)
        local midpointSnapshot = startup.cherax_host_probe.capture_host_snapshot("2/3 midpoint")
        snapshots[#snapshots + 1] = midpointSnapshot
        startup.log("[Cherax Host Test] SNAPSHOT 2/3 | " .. startup.cherax_host_probe.snapshot_line(midpointSnapshot))
        if not host_lock_quick("after method 30") then return startup.cherax_host_probe.lastResult end
    end

    if methodCount >= 50 then
        local objectName = ""
        if player and player.GetName then objectName = tostring(player:GetName() or "") end
        emit(31, "CNetGamePlayer.GetName consistency", objectName ~= "" and objectName == hostName, "objectName=" .. tostring(objectName))

        if player then playerInfo = player.PlayerInfo end
        emit(32, "CPlayerInfo object", playerInfo ~= nil, "available=" .. tostring(playerInfo ~= nil))

        if playerInfo then playerInfoNetData = playerInfo.NetData end
        emit(33, "CPlayerInfo NetData object", playerInfoNetData ~= nil, "available=" .. tostring(playerInfoNetData ~= nil))

        local netDataName = ""
        if playerInfoNetData then netDataName = tostring(playerInfoNetData.Name or "") end
        emit(34, "NetData name consistency", netDataName ~= "" and netDataName == hostName, "netDataName=" .. tostring(netDataName))

        local netDataRid = nil
        if playerInfoNetData then netDataRid = tonumber(playerInfoNetData.RockstarId) end
        emit(35, "NetData Rockstar ID consistency", netDataRid ~= nil and rid ~= nil and netDataRid == rid, "netDataRid=" .. tostring(netDataRid) .. " gamerInfoRid=" .. tostring(rid))

        local netDataHostKey = nil
        if playerInfoNetData then netDataHostKey = playerInfoNetData.HostKey end
        emit(36, "NetData HostKey consistency", netDataHostKey ~= nil and hostKey ~= nil and tostring(netDataHostKey) == tostring(hostKey), "netDataHostKey=" .. tostring(netDataHostKey) .. " gamerInfoHostKey=" .. tostring(hostKey))

        if playerInfo then playerInfoPed = playerInfo.PlayerPed end
        emit(37, "CPlayerInfo PlayerPed object", playerInfoPed ~= nil, "available=" .. tostring(playerInfoPed ~= nil))

        if playerInfoPed and playerInfoPed.GetAddress then playerInfoPedAddress = tonumber(playerInfoPed:GetAddress()) end
        emit(38, "PlayerPed / Players.GetCPed address consistency", playerInfoPedAddress ~= nil and cpedAddress ~= nil and playerInfoPedAddress == cpedAddress, "playerInfoPed=" .. tostring(playerInfoPedAddress) .. " playersCPed=" .. tostring(cpedAddress))

        if playerInfo then playerState = tonumber(playerInfo.PlayerState) end
        emit(39, "Player state readable", playerState ~= nil and playerState >= -1 and playerState <= 6, "playerState=" .. tostring(playerState))

        if playerInfo then playerTeam = tonumber(playerInfo.Team) end
        emit(40, "Player team readable", playerTeam ~= nil, "team=" .. tostring(playerTeam))
        if knownPositive and not host_lock_quick("after method 40") then return startup.cherax_host_probe.lastResult end

        if playerInfo then friendStatus = tonumber(playerInfo.FriendStatus) end
        emit(41, "Friend status readable", friendStatus ~= nil, "friendStatus=" .. tostring(friendStatus))

        if playerInfo then playerMaxHealth = tonumber(playerInfo.MaxHealth) end
        local extremeHealth = playerMaxHealth ~= nil and playerMaxHealth > 1000
        if extremeHealth then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(42, "Player max-health snapshot", playerMaxHealth ~= nil and playerMaxHealth > 0, "maxHealth=" .. tostring(playerMaxHealth) .. " extreme=" .. tostring(extremeHealth))

        if playerInfo then playerMaxArmour = tonumber(playerInfo.MaxArmour) end
        local extremeArmour = playerMaxArmour ~= nil and playerMaxArmour > 1000
        if extremeArmour then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(43, "Player max-armour snapshot", playerMaxArmour ~= nil and playerMaxArmour >= 0, "maxArmour=" .. tostring(playerMaxArmour) .. " extreme=" .. tostring(extremeArmour))

        if playerInfo then weaponDamageModifier = tonumber(playerInfo.WeaponDamageModifier) end
        local extremeWeaponDamage = weaponDamageModifier ~= nil and (weaponDamageModifier > 2.0 or weaponDamageModifier < 0.0)
        if extremeWeaponDamage then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(44, "Weapon-damage modifier snapshot", weaponDamageModifier ~= nil, "value=" .. tostring(weaponDamageModifier) .. " extreme=" .. tostring(extremeWeaponDamage))

        if playerInfo then meleeWeaponDamageModifier = tonumber(playerInfo.MeleeWeaponDamageModifier) end
        local extremeMeleeWeapon = meleeWeaponDamageModifier ~= nil and (meleeWeaponDamageModifier > 2.0 or meleeWeaponDamageModifier < 0.0)
        if extremeMeleeWeapon then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(45, "Melee-weapon modifier snapshot", meleeWeaponDamageModifier ~= nil, "value=" .. tostring(meleeWeaponDamageModifier) .. " extreme=" .. tostring(extremeMeleeWeapon))

        if playerInfo then meleeUnarmedDamageModifier = tonumber(playerInfo.MeleeUnarmedDamageModifier) end
        local extremeUnarmed = meleeUnarmedDamageModifier ~= nil and (meleeUnarmedDamageModifier > 2.0 or meleeUnarmedDamageModifier < 0.0)
        if extremeUnarmed then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(46, "Unarmed-damage modifier snapshot", meleeUnarmedDamageModifier ~= nil, "value=" .. tostring(meleeUnarmedDamageModifier) .. " extreme=" .. tostring(extremeUnarmed))

        if playerInfo then vehicleDamageModifier = tonumber(playerInfo.VehicleDamageModifier) end
        local extremeVehicleDamage = vehicleDamageModifier ~= nil and (vehicleDamageModifier > 2.0 or vehicleDamageModifier < 0.0)
        if extremeVehicleDamage then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(47, "Vehicle-damage modifier snapshot", vehicleDamageModifier ~= nil, "value=" .. tostring(vehicleDamageModifier) .. " extreme=" .. tostring(extremeVehicleDamage))

        if playerInfo then explosiveDamageModifier = tonumber(playerInfo.ExplosiveDamageModifier) end
        local extremeExplosiveDamage = explosiveDamageModifier ~= nil and (explosiveDamageModifier > 2.0 or explosiveDamageModifier < 0.0)
        if extremeExplosiveDamage then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(48, "Explosive-damage modifier snapshot", explosiveDamageModifier ~= nil, "value=" .. tostring(explosiveDamageModifier) .. " extreme=" .. tostring(extremeExplosiveDamage))

        if playerInfo then sprintMultiplier = tonumber(playerInfo.RunSprintSpeedMultiplier) end
        local extremeSprint = sprintMultiplier ~= nil and (sprintMultiplier > 1.5 or sprintMultiplier < 0.5)
        if extremeSprint then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(49, "Run/sprint multiplier snapshot", sprintMultiplier ~= nil, "value=" .. tostring(sprintMultiplier) .. " extreme=" .. tostring(extremeSprint))

        local pedHealth = nil
        local pedMaxHealth = nil
        local pedArmour = nil
        local pedInvincible = nil
        if cped then
            pedHealth = tonumber(cped.Health)
            pedMaxHealth = tonumber(cped.MaxHealth)
            pedArmour = tonumber(cped.Armor)
            if cped.IsInvincible then pedInvincible = cped:IsInvincible() == true end
        end
        emit(50, "Remote CPed state snapshot", cped ~= nil and pedHealth ~= nil, "health=" .. tostring(pedHealth) .. " maxHealth=" .. tostring(pedMaxHealth) .. " armour=" .. tostring(pedArmour) .. " invincible=" .. tostring(pedInvincible))
    end

    if knownPositive then
        startup.yield(750)
        local finalSnapshot = startup.cherax_host_probe.capture_host_snapshot("3/3 final")
        snapshots[#snapshots + 1] = finalSnapshot
        startup.log("[Cherax Host Test] SNAPSHOT 3/3 | " .. startup.cherax_host_probe.snapshot_line(finalSnapshot))
        if not host_lock_quick("after method 50") then return startup.cherax_host_probe.lastResult end

        local stable, total, changed = startup.cherax_host_probe.three_snapshot_stability(snapshots)
        local pct = total > 0 and math.floor((stable / total) * 100 + 0.5) or 0
        stabilityText = tostring(stable) .. "/" .. tostring(total) .. " stable (" .. tostring(pct) .. "%)"
        startup.log("[Cherax Host Test] STABILITY | " .. stabilityText
            .. " | changed=" .. (#changed > 0 and table.concat(changed, " | ") or "<none>"))
    end

    local verdict = "NO CHERAX-SPECIFIC SIGNAL"
    if knownPositive then
        if explicitSignals > 0 then
            verdict = "KNOWN CHERAX CONTROL: EXPLICIT REMOTE TOKEN FOUND"
        else
            verdict = "KNOWN CHERAX CONTROL CAPTURED: NO BRAND TOKEN EXPOSED"
        end
    elseif explicitSignals > 0 then
        verdict = "EXPLICIT CHERAX SIGNAL FOUND"
    elseif menuSignals > 0 then
        verdict = "POSSIBLE MENU USER; BRAND UNKNOWN"
    end

    local fingerprint = table.concat({
        "expectedKnownCherax=" .. tostring(knownPositive),
        "rid=" .. tostring(rid),
        "hostKey=" .. tostring(hostKey),
        "cxn=" .. tostring(cxnId),
        "tags=" .. tostring(tags),
        "netType=" .. tostring(netAddressType),
        "modderDB=" .. tostring(#rawReasons),
        "catalogKnown=" .. tostring(catalogKnown),
        "catalogHigh=" .. tostring(catalogHigh),
        "catalogAttack=" .. tostring(catalogAttack),
        "rac=" .. tostring(#racReasons),
        "methods=" .. tostring(methodCount),
        "deepSignals=" .. tostring(deepSignals),
        "stability=" .. tostring(stabilityText),
        "playerState=" .. tostring(playerState),
        "team=" .. tostring(playerTeam),
        "weaponDamage=" .. tostring(weaponDamageModifier),
        "sprintMult=" .. tostring(sprintMultiplier)
    }, " | ")

    local result = {
        hostName = hostName,
        hostId = hostId,
        rid = rid,
        explicitCherax = explicitSignals > 0,
        explicitSignals = explicitSignals,
        menuSignals = menuSignals,
        verdict = verdict,
        fingerprint = fingerprint,
        probes = probes,
        methodCount = methodCount,
        deepSignals = deepSignals,
        knownPositive = knownPositive,
        aborted = false,
        stabilityText = stabilityText
    }
    startup.cherax_host_probe.lastResult = result
    startup.s.cheraxHostProbeLastVerdict = verdict
    startup.s.cheraxHostProbeLastExplicitSignals = explicitSignals
    startup.s.cheraxHostProbeLastMenuSignals = menuSignals
    startup.s.cheraxHostProbeLastMethodCount = methodCount
    startup.s.cheraxHostProbeLastDeepSignals = deepSignals
    startup.s.cheraxHostProbeLastKnownPositive = knownPositive
    startup.s.cheraxHostProbeLastStability = stabilityText
    startup.s.cheraxHostProbeStatus = tostring(methodCount) .. " methods: " .. verdict .. " | " .. hostName
    startup.s.lobbyFinderLastVerdict = verdict
    startup.log("[Cherax Host Test] RESULT | methods=" .. tostring(methodCount)
        .. " | knownPositive=" .. tostring(knownPositive)
        .. " | host=" .. hostName
        .. " | verdict=" .. verdict
        .. " | explicit=" .. tostring(explicitSignals)
        .. " | menuSignals=" .. tostring(menuSignals)
        .. " | deepSignals=" .. tostring(deepSignals)
        .. " | stability=" .. tostring(stabilityText))
    startup.log("[Cherax Host Test] FINGERPRINT | " .. fingerprint)

    local reportPath = ""
    if knownPositive then
        reportPath = startup.cherax_host_probe.write_report(result, snapshots, reasonLabel, "")
        startup.log("[Cherax Host Test] REPORT | " .. (reportPath ~= "" and reportPath or "write failed"))
        if reportPath ~= "" then
            startup.toast("EE known-positive 50-method report saved.", 4500)
        else
            startup.toast("50-method test completed, but the report could not be saved.", 4500)
        end
    end

    startup.log("[Cherax Host Test] END | " .. tostring(methodCount) .. "/" .. tostring(methodCount)
        .. " completed | no kick/crash/script-event/entity interaction used")
    startup.cherax_host_probe.busy = false
    return result
end

function startup.request_cherax_host_probe(methodCount)
    local requested = tonumber(methodCount) == 50 and 50 or 30
    if startup.cherax_host_probe.busy == true or startup.cheraxHostProbeJobQueued == true then
        startup.toast("Cherax Host Test is already running.", 2500)
        return
    end
    startup.pendingCheraxHostProbe = true
    startup.pendingCheraxHostProbeMethods = requested
    startup.pendingCheraxHostProbeKnownPositive = false
    startup.s.cheraxHostProbeStatus = "Queued " .. tostring(requested) .. "-method test"
    startup.toast("Queued " .. tostring(requested) .. " read-only Host checks.", 3000)
end

function startup.request_cherax_host_probe_30()
    startup.request_cherax_host_probe(30)
end

function startup.request_cherax_host_probe_50()
    startup.request_cherax_host_probe(50)
end

function startup.request_cherax_host_probe_50_known_positive()
    if not startup.is_enhanced_active_edition() then
        startup.s.cheraxHostProbeStatus = "EE is required for the known-positive test."
        startup.toast("This controlled 50-method test is available on EE only.", 4000)
        return
    end

    if startup.cherax_host_probe.busy == true or startup.cheraxHostProbeJobQueued == true then
        startup.toast("Cherax Host Test is already running.", 2500)
        return
    end

    local hostName, hostId = startup.get_session_host_name()
    hostId = tonumber(hostId) or -1
    hostName = tostring(hostName or "Unknown")

    if hostId < 0 or hostId > 31 or hostName == "" or hostName == "Unknown" or hostName == "Invalid" then
        startup.s.cheraxHostProbeStatus = "No valid Session Host is available."
        startup.toast("No valid Session Host is available for the EE test.", 4000)
        return
    end

    if startup.is_local_player_id(hostId) then
        startup.s.cheraxHostProbeStatus = "Known-positive test requires a remote Session Host."
        startup.toast("The Session Host is you. Use a remote confirmed Cherax host.", 4500)
        return
    end

    startup.pendingCheraxHostProbe = true
    startup.pendingCheraxHostProbeMethods = 50
    startup.pendingCheraxHostProbeKnownPositive = true
    startup.s.cheraxHostProbeStatus = "Queued EE known-positive 50-method test for " .. hostName
    startup.toast("Queued the EE known-positive 50-method Host Test.", 3500)
end

function startup.process_pending_cherax_host_probe()
    if startup.pendingCheraxHostProbe ~= true or startup.cheraxHostProbeJobQueued == true then return end
    local requested = tonumber(startup.pendingCheraxHostProbeMethods) == 50 and 50 or 30
    local knownPositive = startup.pendingCheraxHostProbeKnownPositive == true
    startup.pendingCheraxHostProbe = false
    startup.pendingCheraxHostProbeMethods = 30
    startup.pendingCheraxHostProbeKnownPositive = false
    startup.cheraxHostProbeJobQueued = true
    Script.QueueJob(function()
        local reason = knownPositive
            and "manual EE known-positive 50-method button"
            or ("manual " .. tostring(requested) .. "-method button")
        local ok, result = direct_call(
            startup.cherax_host_probe.run,
            reason,
            requested,
            knownPositive and { knownCherax = true, positiveControl = true } or nil
        )
        startup.cheraxHostProbeJobQueued = false
        if not ok then
            startup.cherax_host_probe.busy = false
            startup.s.cheraxHostProbeStatus = "Host Test error: " .. tostring(result)
            startup.error("[Cherax Host Test] ERROR | " .. tostring(result))
            startup.toast("Host Test stopped safely after an internal error.", 4500)
        end
    end)
end

function startup.lobby_filter.mode()
    if startup.s.startupPresenceFinderEnabled == true then
        return "startup_presence"
    end
    if startup.s.cheraxHostFinderEnabled == true then
        return "cherax_host"
    end
    if startup.is_prime_active_edition() and startup.s.primeMinimumPlayersEnabled == true then
        return "prime_population"
    end
    return nil
end

function startup.lobby_filter.wait_ms(serial)
    local minMs = startup.clamp_int(startup.s.lobbyFinderWaitMinMs or 15000, 15000, 30000)
    local maxMs = startup.clamp_int(startup.s.lobbyFinderWaitMaxMs or 30000, minMs, 30000)
    local span = maxMs - minMs
    if span <= 0 then return minMs end
    return minMs + ((startup.now() + ((tonumber(serial) or 0) * 7919)) % (span + 1))
end

function startup.lobby_filter.cancel(reason)
    startup.lobby_filter.sessionSerial = (tonumber(startup.lobby_filter.sessionSerial or 0) or 0) + 1
    startup.lobby_filter.running = false
    startup.lobby_filter.hopRequested = false
    startup.s.lobbyFinderStatus = tostring(reason or "Cancelled")
end

function startup.stop_lobby_finder()
    startup.s.cheraxHostFinderEnabled = false
    startup.s.primeMinimumPlayersEnabled = false
    startup.lobby_filter.cancel("Lobby Finder stopped by user")
    startup.set_feature_bool_silently(startup.h.FindCheraxHostLobbies, false)
    startup.set_feature_bool_silently(startup.h.PrimeMinimumPlayersEnabled, false)
    startup.save_config(false)
    startup.toast("Lobby Finder automation stopped.", 3000)
end

function startup.lobby_filter.hop(reason, serial)
    if serial ~= startup.lobby_filter.sessionSerial then return false end
    startup.s.cheraxHostFinderHopCount = (tonumber(startup.s.cheraxHostFinderHopCount or 0) or 0) + 1
    startup.s.lobbyFinderStatus = "Hopping: " .. tostring(reason or "Lobby rejected")
    startup.s.cheraxHostFinderStatus = startup.s.lobbyFinderStatus
    startup.log("[Lobby Finder] " .. startup.s.lobbyFinderStatus .. " | hop=" .. tostring(startup.s.cheraxHostFinderHopCount))
    startup.apply_session_type()
    startup.yield(750)
    if serial ~= startup.lobby_filter.sessionSerial then return false end
    startup.lobby_filter.hopRequested = true
    return startup.start_session(true)
end

function startup.continue_session_loaded_after_lobby_filter()
    if startup.s.waitingForRefreshedSession then
        startup.s.waitingForRefreshedSession = false
        startup.s.lastSessionFlowStatus = "Refreshed session loaded; starting advertise"
        startup.toast("Refreshed session loaded. Starting advertise routine.", 4000)
        Script.QueueJob(function()
            startup.yield(10000)
            startup.apply_session_type()
            startup.run_selected_advertise_flow("refreshed session")
        end)
        return
    end
    if not startup.s.sessionLuaLoadCompleted then
        startup.run_session_lua_load_flow()
        return
    end
    startup.s.lastSessionFlowStatus = "Normal session loaded; starting advertise"
    Script.QueueJob(function()
        startup.yield(10000)
        startup.apply_session_type()
        startup.run_selected_advertise_flow("session change")
    end)
end

function startup.lobby_filter.begin(forceImmediate)
    local mode = startup.lobby_filter.mode()
    if not mode then
        startup.s.lobbyFinderStatus = "No lobby filter is enabled."
        return false
    end
    if startup.lobby_filter.running == true then
        startup.s.lobbyFinderStatus = "Lobby screening is already running."
        return false
    end

    startup.lobby_filter.sessionSerial = (tonumber(startup.lobby_filter.sessionSerial or 0) or 0) + 1
    local serial = startup.lobby_filter.sessionSerial
    local waitMs = forceImmediate == true and 0 or (mode == "startup_presence" and 12000 or startup.lobby_filter.wait_ms(serial))
    startup.s.lobbyFinderLastWaitMs = waitMs
    startup.lobby_filter.running = true
    startup.lobby_filter.hopRequested = false

    Script.QueueJob(function()
        if waitMs > 0 then
            startup.s.lobbyFinderStatus = "Waiting " .. startup.format_seconds(waitMs) .. " for the lobby to stabilize..."
            startup.log("[Lobby Finder] " .. startup.s.lobbyFinderStatus .. " | mode=" .. tostring(mode))
            startup.yield(waitMs)
        end
        if serial ~= startup.lobby_filter.sessionSerial then return end

        if mode == "startup_presence" then
            startup.s.startupPresenceFinderStatus = "Scanning this lobby for " .. tostring(startup.s.startupPresenceFinderTarget or "Session Host") .. "..."
            local result = startup.presence and startup.presence.scan_sync
                and startup.presence.scan_sync(startup.s.startupPresenceFinderTarget or "Session Host", "automatic session finder")
                or { count = 0, names = {}, error = "presence module unavailable" }
            if serial ~= startup.lobby_filter.sessionSerial then return end
            local count = tonumber(result and result.count or 0) or 0
            if count > 0 then
                local names = result.names or {}
                startup.lobby_filter.running = false
                startup.s.startupPresenceFinderEnabled = false
                startup.s.startupPresenceFinderStatus = "Found: " .. table.concat(names, ", ")
                startup.s.startupPresenceLastFound = table.concat(names, ", ")
                startup.s.startupPresenceLastFoundCount = count
                startup.set_feature_bool_silently(startup.h.StartupPresenceSessionFinder, false)
                startup.save_config(false)
                startup.toast("Startup user found: " .. table.concat(names, ", "), 6500)
                startup.log_colored("[Startup Network] Verified compatible Startup user: " .. table.concat(names, ", "), "success")
                startup.continue_session_loaded_after_lobby_filter()
                return
            end

            startup.s.startupPresenceFinderHopCount = (tonumber(startup.s.startupPresenceFinderHopCount or 0) or 0) + 1
            if startup.s.startupPresenceFinderHopCount >= 10 then
                startup.lobby_filter.running = false
                startup.s.startupPresenceFinderEnabled = false
                startup.s.startupPresenceFinderStatus = "Stopped after 10 sessions; no verified reply"
                startup.set_feature_bool_silently(startup.h.StartupPresenceSessionFinder, false)
                startup.save_config(false)
                startup.toast("Startup Session Finder stopped after 10 sessions with no verified reply.", 7000)
                startup.continue_session_loaded_after_lobby_filter()
                return
            end

            startup.lobby_filter.running = false
            startup.s.startupPresenceFinderStatus = "No verified reply. Hopping to session "
                .. tostring(startup.s.startupPresenceFinderHopCount + 1) .. "/10..."
            startup.lobby_filter.hop("No verified Startup presence reply", serial)
            return
        end

        if mode == "prime_population" then
            local playerCount = startup.get_session_player_count()
            local threshold = startup.clamp_int(startup.s.primeMinimumPlayersThreshold or 20, 10, 30)
            startup.s.lobbyFinderLastInitialPlayerCount = playerCount
            if playerCount >= threshold then
                startup.s.lobbyFinderStatus = "Accepted initial lobby: " .. tostring(playerCount) .. " players. Later drops are ignored."
                startup.s.lobbyFinderLastVerdict = "Accepted " .. tostring(playerCount) .. "/" .. tostring(threshold)
                startup.log("[Lobby Finder] " .. startup.s.lobbyFinderStatus)
                startup.lobby_filter.running = false
                startup.continue_session_loaded_after_lobby_filter()
                return
            end
            startup.s.lobbyFinderLastVerdict = "Rejected " .. tostring(playerCount) .. "/" .. tostring(threshold)
            startup.lobby_filter.running = false
            startup.lobby_filter.hop("Initial lobby had only " .. tostring(playerCount) .. "/" .. tostring(threshold) .. " players", serial)
            return
        end

        local testEnabled = startup.s.lobbyFinderRunHostTestEnabled ~= false
        local timedHopEnabled = startup.s.lobbyFinderFourMinuteHopEnabled ~= false
        local sessionStartMs = startup.now() - waitMs
        local deadlineMs = sessionStartMs + 240000
        local result = nil
        local lastTestedHostId = -1

        local function accept_if_cherax(testResult)
            if not testResult or testResult.explicitCherax ~= true then return false end
            startup.lobby_filter.running = false
            startup.s.cheraxHostFinderStatus = "Cherax Host found: " .. tostring(testResult.hostName)
            startup.s.lobbyFinderStatus = startup.s.cheraxHostFinderStatus
            startup.log("[Lobby Finder] " .. startup.s.cheraxHostFinderStatus)
            startup.continue_session_loaded_after_lobby_filter()
            return true
        end

        if testEnabled then
            result = startup.cherax_host_probe.run("automatic Cherax Host Finder", 30)
            if serial ~= startup.lobby_filter.sessionSerial then return end
            lastTestedHostId = tonumber(result and result.hostId) or -1
            if accept_if_cherax(result) then return end
        else
            startup.s.cheraxHostProbeStatus = "Automatic 30-method test is OFF"
        end

        if not timedHopEnabled then
            startup.lobby_filter.running = false
            if testEnabled then
                local verdict = result and result.verdict or "No diagnostic result"
                startup.lobby_filter.hop("Host test was " .. tostring(verdict), serial)
            else
                startup.s.lobbyFinderStatus = "No automatic host test or 4-minute hop is enabled."
                startup.continue_session_loaded_after_lobby_filter()
            end
            return
        end

        while serial == startup.lobby_filter.sessionSerial do
            local nowMs = startup.now()
            local remainingMs = deadlineMs - nowMs
            if remainingMs <= 0 then break end
            startup.s.lobbyFinderStatus = "No Cherax signal. Hopping in " .. startup.format_seconds(remainingMs) .. "."

            if testEnabled then
                local _, currentHostId = startup.get_session_host_name()
                currentHostId = tonumber(currentHostId) or -1
                if currentHostId >= 0 and currentHostId ~= lastTestedHostId then
                    startup.s.lobbyFinderStatus = "Session Host changed. Running host test..."
                    result = startup.cherax_host_probe.run("Session Host changed during 4-minute finder window", 30)
                    if serial ~= startup.lobby_filter.sessionSerial then return end
                    lastTestedHostId = tonumber(result and result.hostId) or currentHostId
                    if accept_if_cherax(result) then return end
                end
            end

            startup.yield(math.min(5000, math.max(250, remainingMs)))
        end

        if serial ~= startup.lobby_filter.sessionSerial then return end
        if testEnabled then
            result = startup.cherax_host_probe.run("final test before 4-minute lobby hop", 30)
            if serial ~= startup.lobby_filter.sessionSerial then return end
            if accept_if_cherax(result) then return end
        end
        startup.lobby_filter.running = false
        startup.lobby_filter.hop("4-minute window ended without a Cherax signal", serial)
    end)
    return true
end

function startup.start_lobby_finder_now()
    startup.s.cheraxHostFinderEnabled = true
    startup.s.showPrimeHostHud = true
    startup.s.sessionInfoHudEnabled = true
    startup.s.playerModUiEnabled = true
    startup.set_feature_bool_silently(startup.h.FindCheraxHostLobbies, true)
    startup.set_feature_bool_silently(startup.h.ShowPrimeHostHud, true)
    startup.set_feature_bool_silently(startup.h.SessionInfoHudToggle, true)
    startup.set_feature_bool_silently(startup.h.PlayerModUiToggle, true)
    startup.resolve_session_type()
    startup.save_config(false)
    startup.lobby_filter.cancel("Starting current-lobby evaluation")
    startup.lobby_filter.begin(false)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- session flow
-- note: routes post-join lua loading, refresh, and matchmaking actions.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.run_session_lua_load_flow()
    if not startup.s.autoLoadLuaFilesOnSession then
        startup.s.sessionLuaLoadRunning = false
        startup.s.sessionLuaLoadStartedAtMs = 0
        startup.s.sessionLuaLoadEndsAtMs = 0
        startup.s.lastSessionFlowStatus = "Session Lua loading OFF; starting advertise"
        -- Build 160: Auto Advertise must not depend on the optional LuaContent
        -- startup system. This was the reason the countdown toggle could be ON
        -- while no HUD or advertising flow ever appeared.
        if startup.should_run_any_advertise_mode() and startup.s.advertiseRunning ~= true and startup.s.oldStartupAdvertiseRunning ~= true then
            startup.run_selected_advertise_flow("session loaded")
        end
        return
    end
    if startup.s.sessionLuaLoadCompleted then
        startup.s.lastSessionFlowStatus = "Session Lua loading already completed"
        return
    end
    if startup.s.sessionLuaLoadRunning then
        startup.s.lastSessionFlowStatus = "Session Lua loading already running"
        return
    end
    startup.s.sessionLuaLoadRunning = true
    startup.s.sessionLuaLoadStartedAtMs = startup.now()
    startup.s.sessionLuaLoadEndsAtMs = startup.s.sessionLuaLoadStartedAtMs + (tonumber(startup.s.sessionLuaLoadDelayMs or 90000) or 90000)
    Script.QueueJob(function()
        startup.s.lastSessionFlowStatus = "Waiting before loading Lua files"
        startup.toast("Session loaded. Waiting " .. startup.format_seconds(startup.s.sessionLuaLoadDelayMs) .. " before loading LuaContent files.", 6000)
        startup.yield(startup.s.sessionLuaLoadDelayMs)
        startup.s.lastSessionFlowStatus = "Loading Lua files"
        startup.run_enabled_lua_files()
        startup.s.sessionLuaLoadCompleted = true
        startup.s.sessionLuaLoadRunning = false
        startup.s.sessionLuaLoadStartedAtMs = 0
        startup.s.sessionLuaLoadEndsAtMs = 0
        if startup.s.autoRefreshSessionAfterLuaLoad and not startup.s.refreshSessionAfterLuaAttempted then
            startup.s.refreshSessionAfterLuaAttempted = true
            startup.s.waitingForRefreshedSession = true
            startup.s.lastSessionFlowStatus = "Waiting 5 seconds before refreshing session"
            startup.toast("All enabled Lua files staged. Waiting 5 seconds, then starting another session because the optional second-session toggle is ON.", 5000)
            startup.yield(startup.s.delayAfterAllLuaLoadedMs)
            startup.s.lastSessionFlowStatus = "Refreshing session after Lua load"
            startup.apply_session_type()
            startup.yield(1000)
            startup.start_session(true)
        else
            startup.s.lastSessionFlowStatus = "Lua load complete; starting advertise"
            startup.run_selected_advertise_flow("session Lua load complete")
        end
    end)
end

function startup.on_session_loaded()
    if not startup.s.initialized then return end
    local now = startup.now()
    local lobbyMode = startup.lobby_filter and startup.lobby_filter.mode and startup.lobby_filter.mode() or nil
    local effectiveDebounceMs = lobbyMode and 5000 or startup.s.sessionChangeDebounceMs
    if now - startup.s.lastSessionChangeMs < effectiveDebounceMs then
        startup.s.lastSessionFlowStatus = "Ignored duplicate session event"
        startup.log("Ignored duplicate session change event due to debounce.")
        return
    end
    if startup.advertise_benchmark_finalize then startup.advertise_benchmark_finalize("SESSION_CHANGED", "New session loaded", true) end
    startup.s.lastSessionChangeMs = now
    startup.modder_hud_clear()
    startup.session_activity.knownPlayers = {}
    if startup.country_filter then
        startup.country_filter.seen = {}
        startup.country_filter.pending = {}
        startup.country_filter.joinedAt = {}
        startup.country_filter.request_rescan("session-change")
    end
    if startup.s.showNatTypeHud then
        if startup.is_prime_active_edition() then
            startup.nat_scan.autoRetryCount = 0
            startup.nat_scan.nextAutoRetryMs = startup.now() + 5000
            startup.nat_scan.localPlayerId = nil
            startup.nat_scan.localPlayerSource = "Session changed; resolving local player"
            startup.nat_scan.nextLocalPlayerProbeMs = 0
            startup.request_nat_pattern_scan("Prime session-change", true)
        else
            startup.request_nat_pattern_scan("session-change", false)
        end
    end
    startup.toast("Session change detected.", 2500)
    startup.s.advertiseFlowSerial = (tonumber(startup.s.advertiseFlowSerial or 0) or 0) + 1
    startup.s.oldStartupAdvertiseSerial = (tonumber(startup.s.oldStartupAdvertiseSerial or 0) or 0) + 1
    startup.s.oldStartupAdvertiseRunning = false
    startup.s.oldStartupAdvertiseStartedAtMs = 0
    startup.s.oldStartupAdvertiseLastHeartbeatMs = 0
    startup.s.oldStartupAdvertiseStatus = startup.s.oldStartupAdvertiseEnabled and "Session changed; waiting for selected flow" or "OFF"
    startup.s.advertiseRunning = false
    startup.s.advertiseSmartActive = false
    startup.s.advertiseCompletedForSession = false
    startup.s.advertiseStopRequested = false
    startup.s.advertiseCountEscalated = false
    startup.s.advertiseCountdownStartedAtMs = 0
    startup.s.advertiseCountdownEndsAtMs = 0
    startup.s.advertiseActiveSinceMs = 0
    startup.s.advertiseHudIntroStartedAtMs = 0
    startup.s.advertiseHudEscalationStartedAtMs = 0
    startup.s.advertiseHudPreviousActualCount = 0
    if startup.reset_advertise_hud_terminal_state then startup.reset_advertise_hud_terminal_state() end
    startup.s.sessionLuaLoadStartedAtMs = 0
    startup.s.sessionLuaLoadEndsAtMs = 0
    startup.s.lastAdvertiseStatus = "Session changed"
    if startup.self_diag and startup.self_diag.active == true then
        startup.s.lastSessionFlowStatus = "Self Diagnostics owns this session change"
        startup.self_diag.on_session_loaded()
        return
    end
    if startup.lobby_filter and startup.lobby_filter.mode and startup.lobby_filter.mode() then
        startup.s.lastSessionFlowStatus = "Lobby Finder screening new session"
        startup.lobby_filter.cancel("Session changed; restarting lobby screening")
        startup.lobby_filter.begin(false)
        return
    end
    startup.continue_session_loaded_after_lobby_filter()
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- player feature links
-- note: attaches one clean custom action beside cherax player controls.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.get_player_feature_by_name_safe(name, playerIndex)
    if not FeatureMgr or not FeatureMgr.GetFeatureByName then return nil end
    local feature = nil
    feature = FeatureMgr.GetFeatureByName(name, playerIndex)
    return feature
end

function startup.clear_render_link(anchorFeature, childFeature)
    if not anchorFeature or not childFeature then return end
    if anchorFeature.ClearRenderBefore then anchorFeature:ClearRenderBefore(childFeature) end
    if anchorFeature.ClearRenderAfter then anchorFeature:ClearRenderAfter(childFeature) end
    if anchorFeature.RemoveRenderBefore then
        for _ = 1, 12 do if anchorFeature:RemoveRenderBefore(childFeature) ~= true then break end end
    end
    if anchorFeature.RemoveRenderAfter then
        for _ = 1, 12 do if anchorFeature:RemoveRenderAfter(childFeature) ~= true then break end end
    end
end

function startup.attach_render_after_once(anchorFeature, childFeature)
    if not anchorFeature or not childFeature or not anchorFeature.AddRenderAfter then return false end
    startup.clear_render_link(anchorFeature, childFeature)
    anchorFeature:AddRenderAfter(childFeature)
    return true
end

function startup.clear_player_feature_render_links(childName, anchorNames)
    if not childName or type(anchorNames) ~= "table" then return end
    for playerIndex = 0, 31 do
        local childFeature = startup.get_player_feature_by_name_safe(childName, playerIndex)
        if childFeature then
            for _, anchorName in ipairs(anchorNames) do
                local anchorFeature = startup.get_player_feature_by_name_safe(anchorName, playerIndex)
                if anchorFeature then
                    startup.clear_render_link(anchorFeature, childFeature)
                end
            end
        end
    end
end

