startup.nuke_join_kick = startup.nuke_join_kick or {}
startup.nuke_join_kick.hash_to_player_index = {}
startup.nuke_join_kick.player_index_to_hash = {}
startup.nuke_join_kick.block_join_kick_names = {
    "Block Join & Kick",
    "Block Join and Kick",
    "Block Join + Kick",
    "Kick & Block Join",
    "Kick and Block Join",
    "Block Join Kick"
}
startup.nuke_join_kick.smart_kick_names = {
    "Smart Kick",
    "Smart kick",
    "SMART KICK"
}
startup.nuke_join_kick.placement_anchor_names = {
    "Smart Kick",
    "Smart kick",
    "SMART KICK"
}
startup.nuke_join_kick.saved_players_selector_names = {
    "Saved Players",
    "Saved Player",
    "Player Tracker",
    "Tracked Players",
    "SCAPI Saved Players"
}
startup.nuke_join_kick.block_join_names = {
    "Block Join",
    "Block Join Enabled",
    "Prevent Join",
    "Deny Join",
    "Join Block"
}
startup.nuke_join_kick.auto_kick_names = {
    "Auto Kick",
    "Auto-Kick",
    "Automatic Kick",
    "Kick On Join",
    "Kick on Join",
    "Auto Kick On Join",
    "Kick if Join",
    "Kick On Sight",
    "Kick on Sight",
    "Auto Kick Saved Player",
    "Saved Player Auto Kick",
    "Kick Player On Join"
}
startup.nuke_join_kick.reason_names = {
    "Reason Type",
    "Kick Reason Type",
    "Auto Kick Reason Type",
    "Reason",
    "Kick Reason",
    "Auto Kick Reason",
    "Block Reason",
    "Join Deny Reason"
}
startup.nuke_join_kick.reason_list_labels = {
    "Cheater",
    "Cheating",
    "Modder",
    "Hacker"
}
startup.nuke_join_kick.probe_words = {
    "saved",
    "tracker",
    "scapi",
    "block",
    "join",
    "auto",
    "kick",
    "reason",
    "cheat",
    "cheater"
}

function startup.nuke_join_kick.log(msg, force)
    if force == true or startup.s.verboseStartupLogs == true or startup.nuke_join_kick.force_log == true then
        startup.log("[Nuke Join & Kick] " .. tostring(msg))
    end
end

function startup.nuke_join_kick.error(msg)
    startup.error("[Nuke Join & Kick] " .. tostring(msg))
end

function startup.nuke_join_kick.toast(msg, ms)
    ms = ms or 4000
    if GUI and GUI.AddToast then
        GUI.AddToast("Nuke Join & Kick", tostring(msg), ms)
    end
    startup.nuke_join_kick.log(msg)
    startup.s.lastNukeStatus = tostring(msg)
end

function startup.nuke_join_kick.execute(_, fn)
    fn()
    return true
end

function startup.nuke_join_kick.call(_, fn)
    return fn()
end

function startup.nuke_join_kick.feature_name(feature)
    if not feature then return "nil" end
    local name = startup.nuke_join_kick.call("GetName", function()
        if feature.GetName then
            return feature:GetName(false)
        end
        return feature.Name
    end)
    return tostring(name or "Unknown")
end

function startup.nuke_join_kick.feature_type(feature)
    if not feature then return "nil" end
    local t = startup.nuke_join_kick.call("GetType", function()
        if feature.GetType then
            return feature:GetType()
        end
        return nil
    end)
    return tostring(t)
end

function startup.nuke_join_kick.is_actually_on(feature)
    if not feature then return false end
    local toggled = startup.nuke_join_kick.call("IsToggled", function()
        if feature.IsToggled then
            return feature:IsToggled()
        end
        return nil
    end)
    if toggled == true then return true end
    local boolValue = startup.nuke_join_kick.call("GetBoolValue", function()
        if feature.GetBoolValue then
            return feature:GetBoolValue()
        end
        return nil
    end)
    if boolValue == true then return true end
    return false
end

function startup.nuke_join_kick.is_toggle_capable(feature)
    if not feature then return false end
    local isToggle = startup.nuke_join_kick.call("IsToggleFeature", function()
        if feature.IsToggleFeature then
            return feature:IsToggleFeature()
        end
        return nil
    end)
    if isToggle == true then return true end
    if feature.SetBoolValue or feature.Toggle then return true end
    return false
end

function startup.nuke_join_kick.set_toggle_on_confirmed(feature, label)
    if not feature then return false end
    local before = startup.nuke_join_kick.is_actually_on(feature)
    if before then
        startup.nuke_join_kick.log(tostring(label) .. " already ON.")
        return true
    end
    if not startup.nuke_join_kick.is_toggle_capable(feature) then
        startup.nuke_join_kick.log(tostring(label) .. " is not toggle-capable. Skipping.")
        return false
    end
    startup.nuke_join_kick.execute("Set toggle ON " .. tostring(label), function()
        if feature.SetBoolValue then
            feature:SetBoolValue(true)
        elseif feature.Toggle then
            feature:Toggle(true)
        end
        if feature.TriggerCallback then
            feature:TriggerCallback()
        elseif feature.OnClick then
            feature:OnClick()
        end
    end)
    startup.yield(50)
    local after = startup.nuke_join_kick.is_actually_on(feature)
    startup.nuke_join_kick.log(tostring(label) .. " confirmed ON: " .. tostring(after))
    return after == true
end

function startup.nuke_join_kick.click_feature(feature, label)
    if not feature then return false end
    return startup.nuke_join_kick.execute("Click " .. tostring(label), function()
        if feature.OnClick then
            feature:OnClick()
        elseif feature.TriggerCallback then
            feature:TriggerCallback()
        elseif feature.Click then
            feature:Click()
        elseif feature.Execute then
            feature:Execute()
        end
    end)
end

function startup.nuke_join_kick.get_feature_hash(feature)
    if not feature then return nil end
    return startup.nuke_join_kick.call("feature:GetHash", function()
        if feature.GetHash then
            return feature:GetHash()
        end
        return nil
    end)
end

function startup.nuke_join_kick.resolve_player_id_from_feature(feature)
    if not feature then
        return nil, "missing feature"
    end
    local hash = startup.nuke_join_kick.get_feature_hash(feature)
    if hash and startup.nuke_join_kick.hash_to_player_index[hash] ~= nil then
        return startup.nuke_join_kick.hash_to_player_index[hash], "hash map"
    end
    local arrayIndex = startup.nuke_join_kick.call("feature:GetArrayIndex", function()
        if feature.GetArrayIndex then
            return feature:GetArrayIndex()
        end
        return nil
    end)
    if arrayIndex ~= nil then
        return arrayIndex, "array index"
    end
    local playerIndex = startup.nuke_join_kick.call("feature:GetPlayerIndex", function()
        if feature.GetPlayerIndex then
            return feature:GetPlayerIndex()
        end
        return nil
    end)
    if playerIndex ~= nil then
        return playerIndex, "player index"
    end
    return nil, "unresolved"
end

function startup.nuke_join_kick.get_player_name(playerId)
    local name = startup.nuke_join_kick.call("Players.GetName", function()
        return Players.GetName(playerId)
    end)
    if name and tostring(name) ~= "" and tostring(name) ~= "Invalid" then
        return tostring(name)
    end
    return "Player " .. tostring(playerId)
end

function startup.nuke_join_kick.find_player_feature_by_names(playerId, names)
    for _, name in ipairs(names) do
        local feature = startup.nuke_join_kick.call("FeatureMgr.GetFeatureByName player " .. tostring(name), function()
            return FeatureMgr.GetFeatureByName(name, playerId)
        end)
        if feature then
            return feature, name
        end
    end
    return nil, nil
end

function startup.nuke_join_kick.find_global_feature_by_names(names)
    for _, name in ipairs(names) do
        local feature = startup.nuke_join_kick.call("FeatureMgr.GetFeatureByName global " .. tostring(name), function()
            return FeatureMgr.GetFeatureByName(name)
        end)
        if feature then
            return feature, name
        end
    end
    return nil, nil
end

function startup.nuke_join_kick.get_list(feature, label)
    if not feature then return nil end
    return startup.nuke_join_kick.call("Get list " .. tostring(label), function()
        if feature.GetList then
            return feature:GetList()
        end
        return nil
    end)
end

function startup.nuke_join_kick.select_list_entry_by_labels(feature, label, wantedLabels)
    if not feature then return false end
    local list = startup.nuke_join_kick.get_list(feature, label)
    if type(list) ~= "table" then
        startup.nuke_join_kick.log("List not available for " .. tostring(label))
        return false
    end
    for _, wantedText in ipairs(wantedLabels) do
        local wantedLower = string.lower(tostring(wantedText))
        for index, text in ipairs(list) do
            local textLower = string.lower(tostring(text))
            if textLower == wantedLower or string.find(textLower, wantedLower, 1, true) then
                local ok = startup.nuke_join_kick.execute("Set list " .. tostring(label) .. " -> " .. tostring(text), function()
                    feature:SetListIndex(index - 1)
                    if feature.TriggerCallback then
                        feature:TriggerCallback()
                    elseif feature.OnClick then
                        feature:OnClick()
                    end
                end)
                if ok then
                    local currentIndex = startup.nuke_join_kick.call("GetListIndex " .. tostring(label), function()
                        if feature.GetListIndex then
                            return feature:GetListIndex()
                        end
                        return nil
                    end)
                    if currentIndex == nil or currentIndex == index - 1 then
                        return true
                    end
                end
            end
        end
    end
    startup.nuke_join_kick.log("Could not find requested label inside list feature " .. tostring(label))
    return false
end

function startup.nuke_join_kick.try_select_saved_player_by_name(playerName)
    local selectorFeature, selectorName = startup.nuke_join_kick.find_global_feature_by_names(startup.nuke_join_kick.saved_players_selector_names)
    if not selectorFeature then
        startup.nuke_join_kick.log("Saved Players selector not found by known names.")
        return false
    end
    local selected = startup.nuke_join_kick.select_list_entry_by_labels(selectorFeature, selectorName, { playerName })
    startup.nuke_join_kick.log("Saved Players selector attempt for " .. tostring(playerName) .. ": " .. tostring(selected))
    return selected
end

function startup.nuke_join_kick.try_apply_named_toggle_global_and_indexed(names, playerId, label)
    local applied = false
    for _, name in ipairs(names) do
        local globalFeature = startup.nuke_join_kick.call("Find global " .. tostring(name), function()
            return FeatureMgr.GetFeatureByName(name)
        end)
        if globalFeature then
            if startup.nuke_join_kick.set_toggle_on_confirmed(globalFeature, label .. " global " .. name) then
                applied = true
            end
        end
        local indexedFeature = startup.nuke_join_kick.call("Find indexed " .. tostring(name), function()
            return FeatureMgr.GetFeatureByName(name, playerId)
        end)
        if indexedFeature then
            if startup.nuke_join_kick.set_toggle_on_confirmed(indexedFeature, label .. " indexed " .. name) then
                applied = true
            end
        end
    end
    return applied
end

function startup.nuke_join_kick.try_apply_block_join(playerId)
    local applied = false
    if startup.nuke_join_kick.try_apply_named_toggle_global_and_indexed(startup.nuke_join_kick.block_join_names, playerId, "Block Join") then
        applied = true
    end
    return applied
end

function startup.nuke_join_kick.try_apply_auto_kick(playerId)
    local applied = false
    if startup.nuke_join_kick.try_apply_named_toggle_global_and_indexed(startup.nuke_join_kick.auto_kick_names, playerId, "Auto Kick") then
        applied = true
    end
    return applied
end

function startup.nuke_join_kick.try_apply_reason_cheater(playerId)
    local applied = false
    for _, name in ipairs(startup.nuke_join_kick.reason_names) do
        local globalFeature = startup.nuke_join_kick.call("Find reason global " .. tostring(name), function()
            return FeatureMgr.GetFeatureByName(name)
        end)
        if globalFeature then
            if startup.nuke_join_kick.select_list_entry_by_labels(globalFeature, name, startup.nuke_join_kick.reason_list_labels) then
                applied = true
            end
        end
        local indexedFeature = startup.nuke_join_kick.call("Find reason indexed " .. tostring(name), function()
            return FeatureMgr.GetFeatureByName(name, playerId)
        end)
        if indexedFeature then
            if startup.nuke_join_kick.select_list_entry_by_labels(indexedFeature, name .. " indexed", startup.nuke_join_kick.reason_list_labels) then
                applied = true
            end
        end
    end
    return applied
end

function startup.nuke_join_kick.apply_saved_player_options(targetName, targetPlayerId, passLabel)
    passLabel = passLabel or "pass"
    startup.s.nukeJoinKickReason = "Cheater"
    startup.nuke_join_kick.try_select_saved_player_by_name(targetName)
    local appliedBlockJoin = startup.nuke_join_kick.try_apply_block_join(targetPlayerId)
    local appliedAutoKick = startup.nuke_join_kick.try_apply_auto_kick(targetPlayerId)
    local appliedReason = startup.nuke_join_kick.try_apply_reason_cheater(targetPlayerId)
    startup.nuke_join_kick.log("Saved-player setting attempt for " .. tostring(targetName))
    startup.nuke_join_kick.log("Target player index: " .. tostring(targetPlayerId))
    startup.nuke_join_kick.log("Pass: " .. tostring(passLabel))
    startup.nuke_join_kick.log("Block Join confirmed ON: " .. tostring(appliedBlockJoin))
    startup.nuke_join_kick.log("Auto Kick confirmed ON: " .. tostring(appliedAutoKick))
    startup.nuke_join_kick.log("Reason applied: " .. tostring(appliedReason))
    startup.nuke_join_kick.log("Reason target: Cheater")
    return appliedBlockJoin, appliedAutoKick, appliedReason
end

function startup.nuke_join_kick.run_for_player_id(playerId, forceRun, sourceLabel, useHostKickFallback)
    if not forceRun and not startup.s.nukeJoinKickEnabled then
        startup.nuke_join_kick.toast("Nuke Join & Kick is disabled in Startup settings.", 4000)
        return false
    end
    if playerId == nil then
        startup.nuke_join_kick.toast("Could not resolve selected player index.", 6000)
        return false
    end
    if startup.is_local_player_id(playerId) then
        local status = "Blocked a defensive kick attempt against the local player"
        startup.nuke_join_kick.log(status .. " | source=" .. tostring(sourceLabel or "unknown"))
        startup.nuke_join_kick.toast("Startup refused to target your own player.", 5000)
        if startup.battleye_auto_block and startup.battleye_auto_block.set_status then
            startup.battleye_auto_block.set_status(status)
        end
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("SELF_KICK_BLOCKED", "path=Block Join & Kick source=" .. tostring(sourceLabel or "unknown"))
        end
        return false
    end
    startup.s.nukeJoinKickReason = "Cheater"
    startup.save_config(false)
    local targetName = startup.nuke_join_kick.get_player_name(playerId)
    if startup.rid_store and startup.rid_store.record then startup.rid_store.record(playerId, "Nuke", tostring(sourceLabel or "Manual Nuke Join & Kick"), "Block Join & Kick", true) end
    if sourceLabel and tostring(sourceLabel) ~= "" then
        startup.nuke_join_kick.toast(tostring(sourceLabel) .. ": Block Join & Kick -> " .. targetName, 3500)
    else
        startup.nuke_join_kick.toast("Adding selected player " .. targetName .. " to Saved Players via Block Join & Kick...", 3500)
    end
    local blockJoinKickFeature, matchedName = startup.nuke_join_kick.find_player_feature_by_names(
        playerId,
        startup.nuke_join_kick.block_join_kick_names
    )
    if not blockJoinKickFeature then
        startup.nuke_join_kick.toast("Could not find built-in Block Join & Kick for selected player " .. targetName .. ".", 6000)
        startup.nuke_join_kick.error("Missing player feature: Block Join & Kick for player index " .. tostring(playerId))
        if useHostKickFallback == true and startup.host_kick_bypass and startup.host_kick_bypass.run_for_player_id then
            startup.host_kick_bypass.run_for_player_id(playerId, tostring(sourceLabel or "Defense") .. ": Block Join & Kick unavailable")
        end
        return false
    end
    local clicked = startup.nuke_join_kick.click_feature(blockJoinKickFeature, matchedName)
    if not clicked then
        startup.nuke_join_kick.toast("Found " .. tostring(matchedName) .. ", but pressing it threw an error.", 6000)
        if useHostKickFallback == true and startup.host_kick_bypass and startup.host_kick_bypass.run_for_player_id then
            startup.host_kick_bypass.run_for_player_id(playerId, tostring(sourceLabel or "Defense") .. ": Block Join & Kick click failed")
        end
        return false
    end
    startup.nuke_join_kick.toast(tostring(matchedName) .. " pressed for selected player " .. targetName .. ". Waiting for Saved Players entry...", 4000)
    startup.modder_hud_remove(targetName, playerId)
    if useHostKickFallback == true and Script and Script.QueueJob then
        Script.QueueJob(function()
            startup.yield(startup.s.battleyeHostKickFallbackDelayMs or 6000)
            if not startup.battleye_auto_block or not startup.battleye_auto_block.resolve_player_by_name then return end
            if not startup.host_kick_bypass or not startup.host_kick_bypass.run_for_player_id then return end
            local stillPlayerId, stillName = startup.battleye_auto_block.resolve_player_by_name(targetName)
            if stillPlayerId ~= nil then
                local fallbackLabel = tostring(sourceLabel or "Defense")
                if startup.crash_defense and string.find(string.lower(fallbackLabel), "crash", 1, true) then
                    startup.crash_defense.set_status("Crash fallback: " .. tostring(stillName or targetName) .. " still in session -> Host Kick Bypass")
                else
                    startup.battleye_auto_block.set_status("Battleye fallback: " .. tostring(stillName or targetName) .. " still in session -> Host Kick Bypass")
                end
                startup.host_kick_bypass.run_for_player_id(stillPlayerId, fallbackLabel .. " fallback after Block Join & Kick")
            end
        end)
    end
    Script.QueueJob(function()
        startup.yield(1500)
        local block1, kick1, reason1 = startup.nuke_join_kick.apply_saved_player_options(targetName, playerId, "pass 1 / 1.5s")
        startup.yield(2500)
        local block2, kick2, reason2 = startup.nuke_join_kick.apply_saved_player_options(targetName, playerId, "pass 2 / 4.0s")
        startup.yield(3000)
        local block3, kick3, reason3 = startup.nuke_join_kick.apply_saved_player_options(targetName, playerId, "pass 3 / 7.0s")
        startup.yield(5000)
        local block4, kick4, reason4 = startup.nuke_join_kick.apply_saved_player_options(targetName, playerId, "pass 4 / 12.0s")
        local finalBlock = block1 or block2 or block3 or block4
        local finalKick = kick1 or kick2 or kick3 or kick4
        local finalReason = reason1 or reason2 or reason3 or reason4
        if finalBlock and finalKick and finalReason then
            startup.nuke_join_kick.toast("Saved-player options confirmed for " .. targetName .. ": Block Join + Auto Kick + Reason Cheater.", 6500)
        elseif finalBlock and finalKick then
            startup.nuke_join_kick.toast("Block Join + Auto Kick confirmed for " .. targetName .. ". Reason Cheater not confirmed yet.", 7000)
        elseif finalBlock then
            startup.nuke_join_kick.toast("Block Join confirmed for " .. targetName .. ", but Auto Kick / Reason were not confirmed. Use Nuke Debug dump.", 7500)
        elseif finalKick then
            startup.nuke_join_kick.toast("Auto Kick confirmed for " .. targetName .. ", but Block Join / Reason were not confirmed. Use Nuke Debug dump.", 7500)
        else
            startup.nuke_join_kick.toast("Block Join & Kick was pressed, but saved toggles were not confirmed. Use Nuke Debug dump.", 7500)
        end
    end)
    return true
end

function startup.nuke_join_kick.run(feature)
    local playerId, source = startup.nuke_join_kick.resolve_player_id_from_feature(feature)
    startup.nuke_join_kick.log("Resolved clicked Nuke feature target: playerId=" .. tostring(playerId) .. " via " .. tostring(source))
    startup.nuke_join_kick.run_for_player_id(playerId)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- battleye auto block
-- note: blocks join and kick detections and uses host kick bypass as fallback.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.battleye_auto_block = startup.battleye_auto_block or {}
startup.battleye_auto_block.state = startup.battleye_auto_block.state or {
    path = nil,
    offset = 0,
    lastScanMs = 0,
    cooldown = {}
}

function startup.battleye_auto_block.set_status(msg)
    startup.s.battleyeAutoBlockLastStatus = tostring(msg)
end

function startup.battleye_auto_block.get_candidate_paths()
    local root = startup.menu_root or (FileMgr and FileMgr.GetMenuRootPath and FileMgr.GetMenuRootPath()) or ""
    return {
        root .. "\\Cherax.log",
        root .. "\\Log.txt",
        root .. "\\log.txt",
        root .. "\\Logs\\Cherax.log",
        root .. "\\Logs\\Log.txt",
        root .. "\\Logs\\log.txt",
        root .. "\\logs\\Cherax.log",
        root .. "\\logs\\Log.txt",
        root .. "\\logs\\log.txt",
        root .. "\\debug.log"
    }
end

function startup.battleye_auto_block.can_read(path)
    if type(path) ~= "string" or path == "" then return false end
    if not io or not io.open then return false end
    local file = io.open(path, "r")
    if not file then return false end
    file:close()
    return true
end

function startup.battleye_auto_block.resolve_log_path()
    if startup.battleye_auto_block.can_read(startup.s.battleyeAutoBlockLastPath) then
        return startup.s.battleyeAutoBlockLastPath
    end
    for _, path in ipairs(startup.battleye_auto_block.get_candidate_paths()) do
        if startup.battleye_auto_block.can_read(path) then
            startup.s.battleyeAutoBlockLastPath = path
            return path
        end
    end
    return nil
end

function startup.battleye_auto_block.prime_path(path)
    local state = startup.battleye_auto_block.state
    if state.path == path then return end
    state.path = path
    state.offset = 0
    local file = io.open(path, "r")
    if file then
        state.offset = file:seek("end") or 0
        file:close()
    end
end

function startup.battleye_auto_block.read_new_text(path)
    local state = startup.battleye_auto_block.state
    startup.battleye_auto_block.prime_path(path)
    local file = io.open(path, "r")
    if not file then return "" end
    local size = file:seek("end") or 0
    if (state.offset or 0) > size then
        state.offset = 0
    end
    file:seek("set", state.offset or 0)
    local text = file:read("*a") or ""
    state.offset = file:seek() or size
    file:close()
    return text
end

function startup.battleye_auto_block.parse_modder_detection(line)
    if type(line) ~= "string" or line == "" then return nil end
    if not string.find(string.lower(line), "modder detection", 1, true) then return nil end
    local name = line:match("%[Modder Detection%]%s*(.-)%s+is%s+likely%s+modding%s*|") or line:match("%[Modder Detection%]%s*(.-)%s+is%s+modding%s*|") or line:match("%[Modder Detection%]%s*(.-)%s+is%s+.-modding%s*|")
    local reason = line:match("|%s*(.-)%s*$") or "Unknown"
    if not name or name == "" then return nil end
    name = tostring(name):gsub("^%s+", ""):gsub("%s+$", "")
    reason = tostring(reason):gsub("^%s+", ""):gsub("%s+$", "")
    if reason == "" then reason = "Unknown" end
    return name, reason
end

function startup.battleye_auto_block.is_rac_text(value)
    local lower = string.lower(tostring(value or ""))
    if string.find(lower, "rockstar anti cheat", 1, true) then return true end
    if string.find(lower, "rockstar anti-cheat", 1, true) then return true end
    return string.find(lower, "%f[%w]rac%f[%W]") ~= nil
end

function startup.battleye_auto_block.extract_name(line)
    local name, reason = startup.battleye_auto_block.parse_modder_detection(line)
    if not name then return nil end
    local lower = string.lower(tostring(reason or ""))
    if not string.find(lower, "battleye", 1, true) and not string.find(lower, "battleeye", 1, true) then return nil end
    return name, reason
end

function startup.battleye_auto_block.resolve_player_by_name(targetName)
    if not targetName or targetName == "" then return nil, nil end
    local wanted = string.lower(tostring(targetName))
    for playerId = 0, 31 do
        local playerName = startup.nuke_join_kick.get_player_name(playerId)
        if playerName and string.lower(tostring(playerName)) == wanted then
            return playerId, playerName
        end
    end
    return nil, nil
end

function startup.battleye_auto_block.handle_detection(playerName, line, reason)
    if startup.battleye_auto_block.is_rac_text(reason) or startup.battleye_auto_block.is_rac_text(line) then
        startup.battleye_auto_block.set_status("RAC tracked (display only, no kick): " .. tostring(playerName) .. " | " .. tostring(reason or "RAC"))
        return
    end
    local playerId, liveName = startup.battleye_auto_block.resolve_player_by_name(playerName)
    if playerId ~= nil and startup.is_local_player_id(playerId) then
        local status = "Ignored local-player Battleye false positive: " .. tostring(liveName or playerName)
        startup.battleye_auto_block.set_status(status)
        startup.log("[Battleye Defense] " .. status .. " | reason=" .. tostring(reason or "Battleye"))
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("BATTLEYE_SELF_FALSE_POSITIVE", "player=" .. tostring(liveName or playerName)
                .. " reason=" .. tostring(reason or "Battleye"))
        end
        return
    end
    if playerId ~= nil and startup.s.ignoreFriendsBattleye == true and startup.is_player_current_friend(playerId) then
        startup.battleye_auto_block.set_status("Ignored friend Battleye detection: " .. tostring(liveName or playerName))
        return
    end
    if playerId ~= nil and startup.s.saveRidBattleye == true and startup.rid_store and startup.rid_store.record then
        startup.rid_store.record(playerId, "Battleye Detection", tostring(reason or "Battleye"), startup.prime_conservative_auto_removal() and "Logged only" or "Block Join & Kick", not startup.prime_conservative_auto_removal())
    end
    if startup.prime_conservative_auto_removal() then
        startup.battleye_auto_block.set_status("Prime passive mode: " .. tostring(reason or "Battleye") .. " displayed only; no automatic removal.")
        if startup.support_log_event_quiet then startup.support_log_event_quiet("PRIME_MODDER_DISPLAY_ONLY", "player=" .. tostring(playerName or "Unknown") .. " reason=" .. tostring(reason or "Battleye")) end
        return
    end
    if not startup.s.battleyeAutoBlockEnabled then return end
    local state = startup.battleye_auto_block.state
    local now = startup.now()
    local key = string.lower(tostring(playerName or ""))
    if key == "" then return end
    if state.cooldown[key] and now - state.cooldown[key] < 30000 then return end
    if playerId == nil then
        startup.battleye_auto_block.set_status("Detected " .. tostring(reason or "Battleye") .. " for " .. tostring(playerName) .. ", but player was not found in the current session.")
        return
    end
    state.cooldown[key] = now
    startup.battleye_auto_block.set_status("Detected " .. tostring(reason or "Battleye") .. ": " .. tostring(liveName) .. " -> Block Join & Kick, then Host Kick Bypass if still present")
    local blocked = startup.nuke_join_kick.run_for_player_id(playerId, true, tostring(reason or "Battleye") .. " detected", true)
    if blocked then
        startup.session_activity_record("blocked", liveName or playerName, tostring(reason or "Battleye"), 10000)
        startup.modder_hud_remove(liveName or playerName, playerId)
    end
end

startup.crash_defense = startup.crash_defense or {}

function startup.crash_defense.parse_confirmed_host_kick_line(line)
    local textLine = tostring(line or "")
    local playerName, reason = string.match(textLine,
        "%[Protection%]%s+(.+)%s+host kicked you with reason%s+'(.-)'%.")
    if not playerName then return nil, nil end
    playerName = tostring(playerName):gsub("^%s+", ""):gsub("%s+$", "")
    reason = tostring(reason or "Host Kick"):gsub("^%s+", ""):gsub("%s+$", "")
    if playerName == "" then return nil, nil end
    return playerName, reason
end

function startup.crash_defense.parse_player_left_identity_line(line)
    local playerName, rid = string.match(tostring(line or ""),
        "%[Player Left%]%s+([^|]-)%s+|%s+(%d+)%s+|")
    if not playerName or not rid then return nil, nil end
    playerName = tostring(playerName):gsub("^%s+", ""):gsub("%s+$", "")
    return playerName, tostring(rid)
end

function startup.crash_defense.is_battleye_host_kick_reason(reason)
    local reasonLower = string.lower(tostring(reason or ""))
    return string.find(reasonLower, "battleye kick", 1, true) ~= nil
end

function startup.crash_defense.note_confirmed_host_kick(playerName, reason)
    local name = tostring(playerName or "Unknown")
    local reasonText = tostring(reason or "Host Kick")
    local key = string.lower(name)
    local now = startup.now()
    local informationalOnly = startup.crash_defense.is_battleye_host_kick_reason(reasonText)

    startup.crash_defense.confirmed_host_kick_total =
        (tonumber(startup.crash_defense.confirmed_host_kick_total or 0) or 0) + 1
    startup.crash_defense.confirmed_host_kick_last = name .. " | " .. reasonText
    startup.crash_defense.pending_confirmed_host_kicks[key] = {
        name = name,
        reason = reasonText,
        detectedMs = now,
        informationalOnly = informationalOnly,
    }

    if informationalOnly then
        startup.crash_defense.battleye_host_kick_informational_total =
            (tonumber(startup.crash_defense.battleye_host_kick_informational_total or 0) or 0) + 1
        startup.crash_defense.battleye_host_kick_informational_last = name .. " | " .. reasonText
        startup.crash_defense.set_status("BattlEye host kick by " .. name .. " | informational only")
        startup.log("[Kick Defense] BattlEye host kick by " .. name
            .. " recognized as a session-removal event only. The host will not be classified, saved, or blocked.")
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("BATTLEYE_HOST_KICK_INFORMATIONAL",
                "player=" .. name .. " reason=" .. reasonText
                    .. " classification=none save_rid=false block_join=false")
        end
        return
    end

    startup.crash_defense.set_status("Confirmed host kick by " .. name .. " | " .. reasonText)
    startup.log("[Kick Defense] Confirmed host kick by " .. name .. " | reason=" .. reasonText
        .. ". Waiting for the matching Player Left RID; no post-disconnect retaliation will be attempted.")
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("CONFIRMED_HOST_KICK",
            "player=" .. name .. " reason=" .. reasonText .. " action=record-only-after-disconnect")
    end
end

function startup.crash_defense.complete_confirmed_host_kick_identity(playerName, rid)
    local name = tostring(playerName or "")
    local key = string.lower(name)
    local pending = startup.crash_defense.pending_confirmed_host_kicks[key]
    if type(pending) ~= "table" then return false end
    if startup.now() - (tonumber(pending.detectedMs or 0) or 0) > startup.crash_defense.confirmed_host_kick_match_ms then
        startup.crash_defense.pending_confirmed_host_kicks[key] = nil
        return false
    end

    local informationalOnly = pending.informationalOnly == true
        or startup.crash_defense.is_battleye_host_kick_reason(pending.reason)
    if informationalOnly then
        startup.crash_defense.pending_confirmed_host_kicks[key] = nil
        startup.crash_defense.set_status("BattlEye host kick: " .. tostring(pending.name or name)
            .. " | identity observed for diagnostics only; RID not saved")
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("BATTLEYE_HOST_KICK_IDENTITY_DISCARDED",
                "player=" .. tostring(pending.name or name) .. " rid_observed=" .. tostring(rid or "Unknown")
                    .. " persisted=false classified=false blocked=false")
        end
        return true
    end

    local saved = false
    if startup.s.saveRidCrash == true and startup.rid_store and startup.rid_store.record_known_identity then
        saved = startup.rid_store.record_known_identity(
            pending.name or name,
            rid,
            "Confirmed Host Kick",
            pending.reason or "Host Kick",
            "Recorded after disconnect; block future RID join",
            true
        ) == true
    end
    startup.crash_defense.pending_confirmed_host_kicks[key] = nil
    startup.crash_defense.set_status("Confirmed host kick: " .. tostring(pending.name or name)
        .. " | RID " .. tostring(rid or "Unknown") .. (saved and " saved for future blocking" or " identified"))
    return true
end

function startup.battleye_auto_block.tick()
    if not startup.s.battleyeAutoBlockEnabled and not startup.s.showModdersHud then return end
    if not io or not io.open then
        startup.battleye_auto_block.set_status("Log watcher unavailable: io.open is missing.")
        return
    end
    local now = startup.now()
    local state = startup.battleye_auto_block.state
    if now - (state.lastScanMs or 0) < (startup.s.battleyeAutoBlockScanMs or 1000) then
        return
    end
    state.lastScanMs = now
    if startup.s.showModdersHud then startup.modder_hud_prune() end
    local path = startup.battleye_auto_block.resolve_log_path()
    if not path then
        startup.battleye_auto_block.set_status("Cherax log file not found yet.")
        return
    end
    local text = startup.battleye_auto_block.read_new_text(path)
    if text == "" then return end
    for line in string.gmatch(text, "([^\r\n]+)") do
        local hostKickName, hostKickReason = startup.crash_defense.parse_confirmed_host_kick_line(line)
        if hostKickName then
            startup.crash_defense.note_confirmed_host_kick(hostKickName, hostKickReason)
        end

        local leftName, leftRid = startup.crash_defense.parse_player_left_identity_line(line)
        if leftName and leftRid then
            startup.crash_defense.complete_confirmed_host_kick_identity(leftName, leftRid)
        end

        local detectedName, detectedReason = startup.battleye_auto_block.parse_modder_detection(line)
        if detectedName then
            local playerId = startup.battleye_auto_block.resolve_player_by_name(detectedName)
            local includeReason = startup.mod_detection.should_include_reason(detectedReason)
            if includeReason then
                startup.modder_hud_record(detectedName, detectedReason, playerId)
            end
            if playerId ~= nil and startup.mod_detection.is_crash_attack_reason(detectedReason)
                and startup.crash_defense and startup.crash_defense.handle_modder_crash_detection then
                startup.crash_defense.handle_modder_crash_detection(playerId, detectedName, detectedReason, "Cherax.log")
            end
            local reasonLower = string.lower(tostring(detectedReason or ""))
            local isRac = startup.battleye_auto_block.is_rac_text(detectedReason) or startup.battleye_auto_block.is_rac_text(line)
            if isRac then
                local _, knownRac = startup.mod_detection.classify_reason(detectedReason)
                if knownRac or startup.s.modDetectionIncludeRac == true then
                    startup.battleye_auto_block.set_status("RAC included in Mod Detection: " .. tostring(detectedName) .. " | " .. tostring(detectedReason or "RAC"))
                else
                    startup.battleye_auto_block.set_status("Unlisted RAC ignored by Mod Detection.")
                end
            elseif string.find(reasonLower, "battleye", 1, true) or string.find(reasonLower, "battleeye", 1, true) then
                startup.battleye_auto_block.handle_detection(detectedName, line, detectedReason)
            end
        end
    end
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- country defense
-- note: Cherax Players.GetIPInfo(playerId) returns IP geolocation metadata including
--       country/countryCode. This is network-IP geolocation, not nationality or identity.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.country_filter.normalize_country_name(value)
    local text = tostring(value or ""):lower()
    text = text:gsub("^%s+", ""):gsub("%s+$", "")
    text = text:gsub("[_%-]+", " "):gsub("%s+", " ")
    return text
end

function startup.country_filter.resolve_country(country, countryCode)
    local code = tostring(countryCode or ""):upper():gsub("^%s+", ""):gsub("%s+$", "")
    local rawCountry = tostring(country or ""):gsub("^%s+", ""):gsub("%s+$", "")
    local normalized = startup.country_filter.normalize_country_name(rawCountry)

    if normalized == "" or normalized == "na" or normalized == "n/a" or normalized == "unknown" or normalized == "hidden" then
        return nil, "Unknown / Hidden", code, "unknown"
    end

    if code ~= "" then
        for _, entry in ipairs(startup.country_filter_countries or {}) do
            if tostring(entry.key or ""):upper() == code then
                return entry.key, entry.label, code, "countryCode"
            end
        end
    end

    for _, entry in ipairs(startup.country_filter_countries or {}) do
        if startup.country_filter.normalize_country_name(entry.label) == normalized then
            return entry.key, entry.label, code, "country"
        end
        for _, alias in ipairs(entry.aliases or {}) do
            if startup.country_filter.normalize_country_name(alias) == normalized then
                return entry.key, entry.label, code, "country"
            end
        end
    end

    return "__OTHER__", rawCountry ~= "" and rawCountry or "Other / Unlisted", code, "country"
end

function startup.country_filter.read_player_country(playerId)
    if not Players or not Players.GetIPInfo then
        return nil, "Unknown / Hidden", "", "Players.GetIPInfo unavailable"
    end
    local ok, info = direct_call(function() return Players.GetIPInfo(playerId) end)
    if not ok or info == nil then
        return nil, "Unknown / Hidden", "", ok and "No IP info" or ("GetIPInfo error: " .. tostring(info))
    end
    local rawCountry, rawCode = nil, nil
    direct_call(function() rawCountry = info.country end)
    direct_call(function() rawCode = info.countryCode end)
    local key, label, code, source = startup.country_filter.resolve_country(rawCountry, rawCode)
    return key, label, code, source
end

function startup.country_filter.is_local_player(playerId)
    for _, localId in ipairs(startup.get_local_player_id_candidates()) do
        if tonumber(localId) == tonumber(playerId) then return true end
    end
    return false
end

function startup.country_filter.is_allowed(countryKey)
    if countryKey == nil then return startup.s.countryFilterUnknownAllowed ~= false end
    if countryKey == "__OTHER__" then return startup.s.countryFilterOtherAllowed ~= false end
    return startup.s.countryFilterAllowed and startup.s.countryFilterAllowed[countryKey] ~= false
end

function startup.country_filter.find_player_feature_by_names(playerId, names)
    if not FeatureMgr or not FeatureMgr.GetFeatureByName then return nil, nil end
    for _, name in ipairs(names or {}) do
        local ok, feature = direct_call(function() return FeatureMgr.GetFeatureByName(name, playerId) end)
        if ok and feature then return feature, name end
    end
    return nil, nil
end

function startup.country_filter.click_player_feature(feature)
    if not feature then return false end
    if feature.TriggerCallback then
        local ok = direct_call(function() feature:TriggerCallback() end)
        if ok then return true end
    end
    if feature.OnClick then
        local ok = direct_call(function() feature:OnClick() end)
        if ok then return true end
    end
    if feature.Click then
        local ok = direct_call(function() feature:Click() end)
        if ok then return true end
    end
    return false
end

function startup.country_filter.player_still_present(playerId, expectedName)
    playerId = tonumber(playerId)
    if playerId == nil then return false end

    -- Reuse Startup's normalized player enumeration. Cherax may expose PLAYER_ID
    -- as a normal table, zero-based container, or userdata-like list.
    local ids = startup.get_voice_player_ids()
    if type(ids) ~= "table" then return false end
    for _, id in ipairs(ids) do
        if tonumber(id) == playerId then
            if expectedName and tostring(expectedName) ~= "" then
                local currentName = startup.get_player_name_safe(playerId)
                if tostring(currentName) ~= tostring(expectedName) then return false end
            end
            return true
        end
    end
    return false
end

function startup.country_filter.blocked_country_labels()
    local labels = {}
    for _, entry in ipairs(startup.country_filter_countries or {}) do
        if startup.s.countryFilterAllowed and startup.s.countryFilterAllowed[entry.key] == false then
            labels[#labels + 1] = tostring(entry.label)
        end
    end
    return labels
end

function startup.country_filter.kick_player(playerId, playerName, countryLabel, countryCode)
    playerId = tonumber(playerId)
    local label = tostring(countryLabel or "Unknown / Hidden")
    local name = tostring(playerName or "Unknown")
    local reason = "Country Filter: " .. label
    if playerId == nil then return false end
    if startup.is_prime_active_edition() then
        local _, sessionHostId = startup.get_session_host_name()
        if tonumber(sessionHostId) == playerId then
            startup.s.countryFilterLastStatus = "Prime safety: Session Host was not removed by Country Filter: " .. name
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("PRIME_COUNTRY_FILTER_HOST_SKIPPED", "player=" .. name .. " [" .. tostring(playerId) .. "] country=" .. label)
            end
            return false
        end
    end
    if startup.country_filter.pending[playerId] then return true end

    startup.country_filter.pending[playerId] = { startedMs = startup.now(), name = name, country = label }
    startup.s.countryFilterLastPlayerName = name
    startup.s.countryFilterLastCountry = label
    startup.s.countryFilterLastCountryCode = tostring(countryCode or "")
    startup.s.countryFilterLastStatus = "Kicking: " .. name .. " | " .. label
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("COUNTRY_FILTER_KICK", "player=" .. name .. " [" .. tostring(playerId) .. "] country=" .. label .. " code=" .. tostring(countryCode or "") .. " method=Smart Kick")
    end
    startup.session_activity_record("kicking", name, reason, startup.s.sessionActivityHoldMs)

    local function finish(status)
        startup.s.countryFilterLastStatus = status
        startup.country_filter.pending[playerId] = nil
    end

    local function job()
        if not startup.country_filter.player_still_present(playerId, name) then
            if startup.support_log_event_quiet then startup.support_log_event_quiet("COUNTRY_FILTER_TARGET_LEFT", "player=" .. name .. " [" .. tostring(playerId) .. "] country=" .. label) end
            finish("Target already left: " .. name .. " | " .. label)
            return
        end

        -- Country filtering is only a temporary lobby rule. Use Cherax Smart Kick
        -- directly and never route through Nuke / Block Join & Kick / Saved Players.
        local smartFeature, smartName = startup.country_filter.find_player_feature_by_names(playerId, { "Smart Kick", "Smart kick", "SMART KICK" })
        local smartSent = smartFeature and startup.country_filter.click_player_feature(smartFeature) == true
        if startup.support_log_event_quiet then startup.support_log_event_quiet("COUNTRY_FILTER_SMART_KICK_SENT", "player=" .. name .. " [" .. tostring(playerId) .. "] country=" .. label .. " sent=" .. tostring(smartSent) .. " feature=" .. tostring(smartName or "not-found")) end

        if not smartSent then
            startup.log(name .. " could not be removed with Smart Kick.")
            if startup.support_log_event_quiet then startup.support_log_event_quiet("COUNTRY_FILTER_SMART_KICK_FAILED", "player=" .. name .. " [" .. tostring(playerId) .. "] country=" .. label .. " feature=" .. tostring(smartName or "not-found")) end
            finish("Smart Kick unavailable: " .. name .. " | " .. label)
            return
        end

        if Script and Script.Yield then Script.Yield(3000) end
        if not startup.country_filter.player_still_present(playerId, name) then
            startup.log(name .. " has been removed.")
            if startup.support_log_event_quiet then startup.support_log_event_quiet("COUNTRY_FILTER_REMOVED", "player=" .. name .. " [" .. tostring(playerId) .. "] country=" .. label .. " method=Smart Kick") end
            startup.session_activity_record("kicked", name, reason, math.min(5000, tonumber(startup.s.sessionActivityHoldMs or 7000) or 7000))
            finish("Removed: " .. name .. " | " .. label .. " | Smart Kick")
            return
        end

        startup.log(name .. " is still present after Smart Kick; retrying later.")
        if startup.support_log_event_quiet then startup.support_log_event_quiet("COUNTRY_FILTER_SMART_KICK_UNCONFIRMED", "player=" .. name .. " [" .. tostring(playerId) .. "] country=" .. label .. " retryAfterMs=" .. tostring(startup.s.countryFilterRetryMs or 15000)) end
        finish("Smart Kick sent; player still present. Retry queued after cooldown: " .. name .. " | " .. label)
    end

    if Script and Script.QueueJob then
        Script.QueueJob(function()
            local ok, err = direct_call(job)
            if not ok then
                startup.log("Country Filter could not process " .. name .. ".")
                if startup.support_log_event_quiet then startup.support_log_event_quiet("COUNTRY_FILTER_KICK_JOB_ERROR", "player=" .. name .. " error=" .. tostring(err)) end
                finish("Kick job error: " .. name .. " | " .. label)
            end
        end)
    else
        local ok, err = direct_call(job)
        if not ok then
            startup.log("Country Filter could not process " .. name .. ".")
            if startup.support_log_event_quiet then startup.support_log_event_quiet("COUNTRY_FILTER_KICK_JOB_ERROR", "player=" .. name .. " error=" .. tostring(err)) end
            finish("Kick job error: " .. name .. " | " .. label)
            return false
        end
    end
    return true
end

function startup.queue_country_filter_bulk_action(action)
    startup.s.pendingCountryBulkAction = tostring(action or "")
    startup.s.countryFilterLastStatus = "Applying country filter preset..."
end

function startup.process_pending_country_filter_bulk_action()
    local action = tostring(startup.s.pendingCountryBulkAction or "")
    if action == "" then return end
    startup.s.pendingCountryBulkAction = nil
    startup.s.countryFilterAllowed = startup.s.countryFilterAllowed or {}

    if action == "select_all" or action == "default" then
        for _, entry in ipairs(startup.country_filter_countries or {}) do
            startup.s.countryFilterAllowed[entry.key] = true
        end
        startup.s.countryFilterUnknownAllowed = true
        startup.s.countryFilterOtherAllowed = true
        if action == "default" then
            startup.s.countryFilterEnabled = startup.default_country_filter_enabled()
            if startup.is_prime_active_edition() then
                startup.s.countryFilterPrimeDefaultVersion = startup.prime_conservative_default_version
            end
        end
    elseif action == "deselect_all" then
        for _, entry in ipairs(startup.country_filter_countries or {}) do
            startup.s.countryFilterAllowed[entry.key] = false
        end
        startup.s.countryFilterUnknownAllowed = false
        startup.s.countryFilterOtherAllowed = false
    else
        return
    end

    startup.sync_feature_states()
    startup.country_filter.request_rescan("bulk-" .. action)
    startup.save_config(false)
    if action == "default" then
        if startup.is_prime_active_edition() then
            startup.s.countryFilterLastStatus = "Default restored: Country Filter OFF on Prime; all countries allowed."
        else
            startup.s.countryFilterLastStatus = "Default restored: all countries allowed."
        end
    elseif action == "select_all" then
        startup.s.countryFilterLastStatus = "All countries selected / allowed."
    else
        startup.s.countryFilterLastStatus = "All countries deselected / blocked."
    end
    if startup.support_log_event_quiet then startup.support_log_event_quiet("COUNTRY_FILTER_BULK", "action=" .. action) end
end

function startup.country_filter.request_rescan(reason)
    startup.s.countryFilterRescanRequested = true
    if reason and tostring(reason) ~= "" then
        startup.s.countryFilterLastStatus = "Filter changed. Refreshing connected players..."
    end
end

function startup.country_filter.tick()
    if startup.s.countryFilterEnabled ~= true then return end
    local now = startup.now()
    local forceRescan = startup.s.countryFilterRescanRequested == true
    if not forceRescan and now - (tonumber(startup.s.countryFilterLastScanMs or 0) or 0) < (tonumber(startup.s.countryFilterScanMs or 1500) or 1500) then return end
    startup.s.countryFilterLastScanMs = now
    if forceRescan then
        startup.s.countryFilterRescanRequested = false
        -- Keep joinedAt/pending timers and classification cache intact. The allow/deny
        -- decision is recalculated below, so changing a filter does not spam every allowed player.
    end
    if not Players or not Players.Get then
        startup.s.countryFilterLastStatus = "Players API unavailable."
        return
    end
    if not Players.GetIPInfo then
        startup.s.countryFilterLastStatus = "Players.GetIPInfo unavailable on this Cherax build."
        return
    end

    local playerIds = startup.get_voice_player_ids()
    if type(playerIds) ~= "table" or #playerIds == 0 then
        startup.s.countryFilterLastStatus = "No connected player IDs returned by Cherax."
        return
    end
    local present = {}
    local delayMs = tonumber(startup.s.countryFilterKickDelayMs or 10000) or 10000
    local retryMs = tonumber(startup.s.countryFilterRetryMs or 15000) or 15000

    for _, playerId in ipairs(playerIds) do
        playerId = tonumber(playerId)
        if playerId ~= nil then
            present[playerId] = true
            if not startup.country_filter.is_local_player(playerId) then
                local playerName = startup.get_player_name_safe(playerId)
                if startup.boot_diag_is_early_window and startup.boot_diag_is_early_window() then
                    startup.boot_diag_checkpoint("COUNTRY_READ_BEGIN", "player=" .. tostring(playerName) .. " [" .. tostring(playerId) .. "]", false)
                end
                local countryKey, countryLabel, countryCode, source = startup.country_filter.read_player_country(playerId)
                if startup.boot_diag_is_early_window and startup.boot_diag_is_early_window() then
                    startup.boot_diag_checkpoint("COUNTRY_READ_OK", "player=" .. tostring(playerName) .. " country=" .. tostring(countryLabel or "Unknown") .. " code=" .. tostring(countryCode or ""), false)
                end
                local signature = tostring(playerName) .. "|" .. tostring(countryKey or "unknown") .. "|" .. tostring(countryLabel or "unknown") .. "|" .. tostring(countryCode or "")
                local previous = startup.country_filter.seen[playerId]
                local allowed = startup.country_filter.is_allowed(countryKey)

                if not startup.country_filter.joinedAt[playerId] then
                    -- If Startup loaded after the player joined, first observation becomes
                    -- the conservative join timestamp so Smart Kick still receives 10 seconds.
                    startup.country_filter.joinedAt[playerId] = now
                end
                local joinedAt = tonumber(startup.country_filter.joinedAt[playerId] or now) or now
                local elapsedMs = math.max(0, now - joinedAt)
                local remainingMs = math.max(0, delayMs - elapsedMs)

                if countryKey ~= nil then
                    startup.s.countryFilterLastStatus = "Seen: " .. tostring(playerName) .. " | " .. tostring(countryLabel) .. (countryCode ~= "" and (" [" .. countryCode .. "]") or "") .. (allowed and " | allowed" or (remainingMs > 0 and (" | blocked, kick in " .. tostring(math.ceil(remainingMs / 1000)) .. "s") or " | blocked"))
                else
                    startup.s.countryFilterLastStatus = "Seen: " .. tostring(playerName) .. " | Unknown / Hidden | allowed=" .. tostring(allowed)
                end

                local decisionChanged = (not previous) or previous.signature ~= signature or previous.allowed ~= allowed
                if decisionChanged then
                    if not allowed then
                        startup.log(tostring(playerName) .. " is joining from " .. tostring(countryLabel or "Unknown / Hidden") .. "... removing...")
                        if startup.support_log_event_quiet then
                            startup.support_log_event_quiet("COUNTRY_FILTER_BLOCKED", "player=" .. tostring(playerName) .. " [" .. tostring(playerId) .. "] country=" .. tostring(countryLabel) .. " code=" .. tostring(countryCode or "") .. " source=" .. tostring(source or "") .. " delayMs=" .. tostring(delayMs))
                        end
                    elseif startup.s.verboseStartupLogs then
                        startup.log("[Country Filter] " .. tostring(playerName) .. " allowed from " .. tostring(countryLabel or "Unknown / Hidden") .. ".")
                    end
                end

                if not allowed then
                    local lastActionMs = previous and tonumber(previous.lastActionMs or 0) or 0
                    local due = remainingMs <= 0
                    local retryReady = lastActionMs <= 0 or (now - lastActionMs) >= retryMs
                    if due and retryReady and not startup.country_filter.pending[playerId] then
                        local acted = startup.country_filter.kick_player(playerId, playerName, countryLabel or "Unknown / Hidden", countryCode)
                        startup.country_filter.seen[playerId] = { signature = signature, allowed = false, lastActionMs = now, kicked = acted == true }
                    elseif decisionChanged then
                        startup.country_filter.seen[playerId] = { signature = signature, allowed = false, lastActionMs = lastActionMs, kicked = false }
                    end
                elseif decisionChanged then
                    startup.country_filter.seen[playerId] = { signature = signature, allowed = true, lastActionMs = 0, kicked = false }
                end
            end
        end
    end

    for playerId in pairs(startup.country_filter.seen) do
        if not present[playerId] then startup.country_filter.seen[playerId] = nil end
    end
    for playerId in pairs(startup.country_filter.joinedAt) do
        if not present[playerId] then startup.country_filter.joinedAt[playerId] = nil end
    end
    for playerId in pairs(startup.country_filter.pending) do
        if not present[playerId] then startup.country_filter.pending[playerId] = nil end
    end
end

-- ============================================================================
-- BUILD 445: REGIONAL WARFARE - CHERAX PLAYER LANGUAGE MODE
-- Uses the live Cherax "Player Language" player feature as the gameplay team key.
-- It does NOT use IP country/geolocation. Bounty application mirrors the stable
-- Minigames/WarGames path: built-in "Set Bounty On Player", serialized, 9k.
-- ============================================================================
startup.regional_warfare_languages = startup.regional_warfare_languages or {
    "Auto (Player Language)",
    "English",
    "French",
    "German",
    "Italian",
    "Spanish",
    "Brazilian",
    "Polish",
    "Russian",
    "Korean",
    "Chinese Traditional",
    "Japanese",
    "Mexican",
    "Chinese Simplified",
    "Unknown"
}
-- Backward-compatible alias because older save/sync code used the word factions.
startup.regional_warfare_factions = startup.regional_warfare_languages
startup.regional_warfare_language_set = startup.regional_warfare_language_set or {
    ["Auto (Player Language)"]=true,["English"]=true,["French"]=true,["German"]=true,
    ["Italian"]=true,["Spanish"]=true,["Brazilian"]=true,["Polish"]=true,["Russian"]=true,
    ["Korean"]=true,["Chinese Traditional"]=true,["Japanese"]=true,["Mexican"]=true,
    ["Chinese Simplified"]=true,["Unknown"]=true
}
startup.regional_warfare_enemy_policies = {"All Other Languages","Selected Languages"}
startup.regional_warfare_runtime = startup.regional_warfare_runtime or {}
startup.regional_warfare_runtime.lastScanMs=startup.regional_warfare_runtime.lastScanMs or 0
startup.regional_warfare_runtime.lastBountyMs=startup.regional_warfare_runtime.lastBountyMs or 0
startup.regional_warfare_runtime.lastApplied=startup.regional_warfare_runtime.lastApplied or {}
startup.regional_warfare_runtime.activeRids=startup.regional_warfare_runtime.activeRids or {}
startup.regional_warfare_runtime.lastLanguageByRid=startup.regional_warfare_runtime.lastLanguageByRid or {}
startup.regional_warfare_runtime.bountyInFlight=startup.regional_warfare_runtime.bountyInFlight==true
startup.regional_warfare_runtime.forceSweep=startup.regional_warfare_runtime.forceSweep==true
startup.regional_warfare_runtime.loopInstalled=startup.regional_warfare_runtime.loopInstalled==true

function startup.regional_warfare_feature_key(value)
    return tostring(value or ""):gsub("[^%w]", "_")
end

function startup.regional_warfare_normalize_language(value)
    local raw=tostring(value or ""):gsub("^%s+",""):gsub("%s+$","")
    if raw=="" then return "Unknown" end
    local lower=raw:lower():gsub("[_%-]+"," "):gsub("%s+"," ")
    local aliases={
        ["english"]="English",["french"]="French",["german"]="German",["italian"]="Italian",
        ["spanish"]="Spanish",["brazilian"]="Brazilian",["brazilian portuguese"]="Brazilian",
        ["portuguese brazil"]="Brazilian",["polish"]="Polish",["russian"]="Russian",
        ["korean"]="Korean",["japanese"]="Japanese",["mexican"]="Mexican",
        ["mexican spanish"]="Mexican",["chinese traditional"]="Chinese Traditional",
        ["traditional chinese"]="Chinese Traditional",["chinese simplified"]="Chinese Simplified",
        ["simplified chinese"]="Chinese Simplified",["unknown"]="Unknown"
    }
    if aliases[lower] then return aliases[lower] end
    if lower:find("traditional",1,true) and lower:find("chinese",1,true) then return "Chinese Traditional" end
    if lower:find("simplified",1,true) and lower:find("chinese",1,true) then return "Chinese Simplified" end
    -- Cherax translated list entries may include extra decoration; match canonical names conservatively.
    for _,name in ipairs(startup.regional_warfare_languages or {}) do
        if name~="Auto (Player Language)" and name~="Unknown" then
            local n=name:lower()
            if lower==n or lower:find(n,1,true) then return name end
        end
    end
    return "Unknown"
end

function startup.regional_warfare_valid_faction(value)
    value=tostring(value or "Auto (Player Language)")
    if startup.regional_warfare_language_set[value]==true then return value end
    -- B443 migration from old region/faction labels to the nearest game-language team.
    local migrate={
        ["United States"]="English",["Canada"]="English",["United Kingdom"]="English",
        ["Europe"]="Auto (Player Language)",["Germany"]="German",["France"]="French",
        ["China"]="Chinese Simplified",["East Asia"]="Auto (Player Language)",
        ["Mexico"]="Mexican",["South America"]="Spanish",["Other"]="Auto (Player Language)",
        ["Unaffiliated"]="Auto (Player Language)"
    }
    return migrate[value] or "Auto (Player Language)"
end

function startup.regional_warfare_sanitize_state()
    startup.s.regionalWarfareMyFaction=startup.regional_warfare_valid_faction(startup.s.regionalWarfareMyFaction)
    local policy=tostring(startup.s.regionalWarfareEnemyPolicy or "All Other Languages")
    if policy=="Selected Factions" then policy="Selected Languages" end
    if policy~="Selected Languages" then policy="All Other Languages" end
    startup.s.regionalWarfareEnemyPolicy=policy
    startup.s.regionalWarfareSelectedEnemies=type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies or {}
    local clean={}
    for language,value in pairs(startup.s.regionalWarfareSelectedEnemies) do
        local canonical=startup.regional_warfare_normalize_language(language)
        if canonical~="Auto (Player Language)" and value==true then clean[canonical]=true end
    end
    startup.s.regionalWarfareSelectedEnemies=clean
    startup.s.regionalWarfareAssignments={} -- B443 manual RID assignments retired.
end

function startup.regional_warfare_get_rid(playerId)
    playerId=tonumber(playerId)
    if playerId==nil then return "" end
    local rid=0
    if startup.presence and startup.presence.get_player_rid then
        local ok,v=direct_call(startup.presence.get_player_rid,playerId)
        if ok then rid=tonumber(v or 0) or 0 end
    end
    if rid<=0 and Players and Players.GetRockstarId then
        local ok,v=direct_call(Players.GetRockstarId,playerId)
        if ok then rid=tonumber(v or 0) or 0 end
    end
    if rid<=0 then return "" end
    return string.format("%.0f",rid)
end

function startup.regional_warfare_player_language(playerId)
    playerId=tonumber(playerId)
    if playerId==nil or playerId<0 or playerId>31 then return "Unknown","invalid-player" end
    if FeatureMgr and FeatureMgr.GetFeatureByName then
        local okF,feature=direct_call(FeatureMgr.GetFeatureByName,"Player Language",playerId)
        if okF and feature then
            if feature.GetStringValue then
                local ok,v=direct_call(function() return feature:GetStringValue() end)
                if ok then
                    local lang=startup.regional_warfare_normalize_language(v)
                    if lang~="Unknown" then return lang,"feature-string" end
                end
            end
            if feature.GetList and feature.GetListIndex then
                local okL,list=direct_call(function() return feature:GetList() end)
                local okI,index=direct_call(function() return feature:GetListIndex() end)
                if okL and okI and type(list)=="table" then
                    index=tonumber(index or -1) or -1
                    local v=list[index] or list[index+1]
                    local lang=startup.regional_warfare_normalize_language(v)
                    if lang~="Unknown" then return lang,"feature-list" end
                end
            end
            if FeatureMgr.GetCurrentFeatureListString and feature.GetHash then
                local okH,hash=direct_call(function() return feature:GetHash() end)
                if okH and hash then
                    local okS,v=direct_call(FeatureMgr.GetCurrentFeatureListString,hash,playerId)
                    if okS then
                        local lang=startup.regional_warfare_normalize_language(v)
                        if lang~="Unknown" then return lang,"feature-current-list" end
                    end
                end
            end
        end
    end
    -- Direct GamerInfo fallback only. Deliberately no IP-country inference here.
    if Players and Players.GetById then
        local okP,obj=direct_call(Players.GetById,playerId)
        if okP and obj then
            local info=nil
            if obj.GetGamerInfo then local okI,v=direct_call(function() return obj:GetGamerInfo() end); if okI then info=v end end
            if info and startup.live_r_language_from_gamer_info_341 then
                local lang=startup.regional_warfare_normalize_language(startup.live_r_language_from_gamer_info_341(info))
                if lang~="Unknown" then return lang,"gamer-info" end
            end
        end
    end
    return "Unknown","unavailable"
end

function startup.regional_warfare_local_player_id()
    if GTA and GTA.GetLocalPlayerId then
        local ok,v=direct_call(GTA.GetLocalPlayerId)
        if ok and tonumber(v) then return tonumber(v) end
    end
    if startup.get_local_player_id_candidates then
        local ok,list=direct_call(startup.get_local_player_id_candidates)
        if ok and type(list)=="table" and tonumber(list[1]) then return tonumber(list[1]) end
    end
    return -1
end

function startup.regional_warfare_own_language()
    local selected=startup.regional_warfare_valid_faction(startup.s.regionalWarfareMyFaction)
    if selected~="Auto (Player Language)" then return selected,"manual" end
    local pid=startup.regional_warfare_local_player_id()
    if pid>=0 then return startup.regional_warfare_player_language(pid) end
    return "Unknown","local-player-unavailable"
end

function startup.regional_warfare_is_enemy_faction(language)
    language=startup.regional_warfare_normalize_language(language)
    local own=startup.regional_warfare_own_language()
    own=startup.regional_warfare_normalize_language(own)
    if language=="Unknown" or own=="Unknown" or language==own then return false end
    if tostring(startup.s.regionalWarfareEnemyPolicy or "All Other Languages")=="Selected Languages" then
        return type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies[language]==true
    end
    return true
end

function startup.regional_warfare_roster()
    local rows={}
    for _,playerId in ipairs(startup.get_voice_player_ids()) do
        playerId=tonumber(playerId)
        if playerId~=nil and not (startup.is_local_player_id and startup.is_local_player_id(playerId)) then
            local rid=startup.regional_warfare_get_rid(playerId)
            if rid~="" then
                local name=tostring(startup.get_player_name_safe(playerId) or ("Player "..tostring(playerId)))
                local language,source=startup.regional_warfare_player_language(playerId)
                rows[#rows+1]={playerId=playerId,rid=rid,name=name,language=language,faction=language,languageSource=source,enemy=startup.regional_warfare_is_enemy_faction(language)}
            end
        end
    end
    table.sort(rows,function(a,b) return string.lower(tostring(a.name or "")) < string.lower(tostring(b.name or "")) end)
    return rows
end

function startup.regional_warfare_apply_builtin_bounty(playerId,rid,name,language)
    if not (FeatureMgr and FeatureMgr.GetFeatureByName) then return false,"FeatureMgr unavailable" end
    if tostring(startup.regional_warfare_get_rid(playerId))~=tostring(rid) then return false,"player slot changed" end
    local current=startup.regional_warfare_player_language(playerId)
    if startup.regional_warfare_normalize_language(current)~=startup.regional_warfare_normalize_language(language) then return false,"player language changed" end
    local okGet,feature=direct_call(function() return FeatureMgr.GetFeatureByName("Set Bounty On Player",playerId) end)
    if not okGet or not feature then return false,"Set Bounty On Player unavailable" end
    if not feature.TriggerCallback then return false,"TriggerCallback unavailable" end
    local okTrigger,err=direct_call(function() feature:TriggerCallback() end)
    if not okTrigger then return false,tostring(err or "TriggerCallback failed") end
    return true,"Built-in 9k"
end

function startup.regional_warfare_tick(force)
    local rw=startup.regional_warfare_runtime
    local manual=force==true or rw.forceSweep==true
    if startup.s.regionalWarfareEnabled~=true then return end
    if startup.s.regionalWarfareAutoBounty~=true and not manual then return end
    local own,ownSource=startup.regional_warfare_own_language()
    own=startup.regional_warfare_normalize_language(own)
    if own=="Unknown" then
        startup.s.regionalWarfareLastStatus="My Player Language is unavailable. Choose My Warfare Language manually."
        return
    end
    if startup.is_gta_online_session_ready and startup.is_gta_online_session_ready()~=true then return end
    local now=startup.now()
    local scanMs=math.max(500,tonumber(startup.s.regionalWarfareScanMs or 1000) or 1000)
    if not manual and now-(tonumber(rw.lastScanMs or 0) or 0)<scanMs then return end
    rw.lastScanMs=now

    local roster=startup.regional_warfare_roster()
    local current,enemies={},{}
    for _,row in ipairs(roster) do
        current[row.rid]=true
        local previous=rw.lastLanguageByRid[row.rid]
        if previous~=row.language then rw.lastApplied[row.rid]=0; rw.lastLanguageByRid[row.rid]=row.language end
        if rw.activeRids[row.rid]~=true then rw.lastApplied[row.rid]=0 end
        if row.enemy==true then enemies[#enemies+1]=row end
    end
    rw.activeRids=current
    if #enemies==0 then
        startup.s.regionalWarfareLastStatus="No enemy Player Language teams detected. My team: "..tostring(own).." ("..tostring(ownSource)..")"
        rw.forceSweep=false
        return
    end
    if rw.bountyInFlight==true then return end
    local gap=math.max(1000,tonumber(startup.s.regionalWarfareBountyGapMs or 2500) or 2500)
    if now-(tonumber(rw.lastBountyMs or 0) or 0)<gap then return end
    local refresh=math.max(60000,tonumber(startup.s.regionalWarfareBountyRefreshMs or 180000) or 180000)
    local target=nil
    for _,row in ipairs(enemies) do
        local last=tonumber(rw.lastApplied[row.rid] or 0) or 0
        if manual or last<=0 or now-last>=refresh then target=row; break end
    end
    if not target then
        startup.s.regionalWarfareLastStatus="Enemy languages present. Built-in 9k bounties maintained every 180 seconds."
        rw.forceSweep=false
        return
    end

    rw.bountyInFlight=true
    rw.lastBountyMs=now
    local function job()
        local ok,status=startup.regional_warfare_apply_builtin_bounty(target.playerId,target.rid,target.name,target.language)
        if ok then
            rw.lastApplied[target.rid]=startup.now()
            startup.s.regionalWarfareLastBountyPlayer=tostring(target.name or "")
            startup.s.regionalWarfareLastBountyFaction=tostring(target.language or "")
            startup.s.regionalWarfareBountyCount=(tonumber(startup.s.regionalWarfareBountyCount or 0) or 0)+1
            startup.s.regionalWarfareLastStatus="Bounty applied: "..tostring(target.name).." | "..tostring(target.language).." | built-in 9k"
            if startup.support_log_event_quiet then startup.support_log_event_quiet("REGIONAL_WARFARE_BOUNTY","player="..tostring(target.name).." rid="..tostring(target.rid).." language="..tostring(target.language).." method=Set Bounty On Player amount=9k") end
        else
            startup.s.regionalWarfareLastStatus="Bounty failed: "..tostring(target.name).." | "..tostring(status)
            if startup.support_log_event_quiet then startup.support_log_event_quiet("REGIONAL_WARFARE_BOUNTY_FAIL","player="..tostring(target.name).." rid="..tostring(target.rid).." language="..tostring(target.language).." error="..tostring(status)) end
        end
        rw.bountyInFlight=false
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
end

function startup.regional_warfare_force_bounty_scan()
    local rw=startup.regional_warfare_runtime
    rw.forceSweep=true
    rw.lastScanMs=0
    for rid in pairs(rw.lastApplied or {}) do rw.lastApplied[rid]=0 end
    startup.regional_warfare_tick(true)
end

function startup.install_regional_warfare_loop()
    if startup.regional_warfare_runtime.loopInstalled==true then return end
    if not (Script and Script.RegisterLooped) then return end
    startup.regional_warfare_runtime.loopInstalled=true
    Script.RegisterLooped(function()
        if ShouldUnload and ShouldUnload() then return end
        startup.regional_warfare_tick(false)
    end)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- subscribed Startup Auto Start helper
-- note: resolves Settings > Subscribed Scripts > Startup > Auto Start as aggressively as
--       Cherax exposes it, but never accepts an ambiguous generic Auto Start candidate.
--       Enabling uses set/click/verify stages so one method cannot accidentally undo another.
-- ═══════════════════════════════════════════════════════════════════════════════════

startup.subscribed_auto_start = startup.subscribed_auto_start or {}

function startup.subscribed_auto_start.state(feature)
    if not feature then return nil end
    if feature.IsToggled then
        local ok, value = direct_call(function() return feature:IsToggled() end)
        if ok and value ~= nil then return value == true end
    end
    if feature.GetBoolValue then
        local ok, value = direct_call(function() return feature:GetBoolValue() end)
        if ok and value ~= nil then return value == true end
    end
    return nil
end

function startup.subscribed_auto_start.context(feature)
    if not feature then return "" end
    local parts, seen = {}, {}
    local function add(value)
        value = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if value == "" then return end
        local key = value:lower()
        if seen[key] then return end
        seen[key] = true
        parts[#parts + 1] = value
    end
    local function try_method(obj, methodName, ...)
        if not obj or not obj[methodName] then return nil end
        local args = {...}
        local ok, value = direct_call(function() return obj[methodName](obj, table.unpack(args)) end)
        if ok then return value end
        return nil
    end

    add(try_method(feature, "GetName", false))
    add(try_method(feature, "GetName", true))
    add(feature.Name)
    for _, methodName in ipairs({ "GetPath", "GetFullPath", "GetFullName", "GetMenuPath", "GetBreadcrumb" }) do
        add(try_method(feature, methodName))
    end
    for _, fieldName in ipairs({ "Path", "FullPath", "FullName", "MenuPath", "Breadcrumb" }) do
        add(feature[fieldName])
    end

    local parent = nil
    for depth = 1, 8 do
        local nextParent = nil
        if parent == nil then
            nextParent = try_method(feature, "GetParent") or try_method(feature, "GetParentFeature") or feature.Parent
        else
            nextParent = try_method(parent, "GetParent") or try_method(parent, "GetParentFeature") or parent.Parent
        end
        if not nextParent or nextParent == parent or nextParent == feature then break end
        parent = nextParent
        add(try_method(parent, "GetName", false))
        add(try_method(parent, "GetName", true))
        add(parent.Name)
    end
    return table.concat(parts, " > ")
end

function startup.subscribed_auto_start.toggle_capable(feature)
    if not feature then return false end
    if feature.SetBoolValue or feature.Toggle or feature.Click or feature.Execute or feature.OnClick or feature.TriggerCallback then return true end
    if feature.IsToggleFeature then
        local ok, value = direct_call(function() return feature:IsToggleFeature() end)
        if ok and value == true then return true end
    end
    return false
end

function startup.subscribed_auto_start.children(container)
    local out, seen = {}, {}
    if not container then return out end
    local function add_list(value)
        if type(value) ~= "table" then return end
        for _, child in pairs(value) do
            if child and not seen[child] then seen[child] = true; out[#out + 1] = child end
        end
    end
    for _, methodName in ipairs({ "GetChildren", "GetChilds", "GetFeatures", "GetChildFeatures" }) do
        if container[methodName] then
            local ok, value = direct_call(function() return container[methodName](container) end)
            if ok then add_list(value) end
        end
    end
    for _, fieldName in ipairs({ "Children", "Childs", "Features" }) do add_list(container[fieldName]) end
    return out
end

function startup.subscribed_auto_start.find_in_startup_container()
    if not FeatureMgr or not FeatureMgr.GetFeatureByName then return nil, nil end
    local containers = { "Startup", "STARTUP", "Subscribed Scripts", "Subscribed Script" }
    for _, containerName in ipairs(containers) do
        local ok, container = direct_call(function() return FeatureMgr.GetFeatureByName(containerName) end)
        if ok and container then
            local queue = { { node = container, depth = 0 } }
            local visited = {}
            local q = 1
            while queue[q] do
                local item = queue[q]; q = q + 1
                local node, depth = item.node, item.depth
                if node and not visited[node] then
                    visited[node] = true
                    local context = startup.subscribed_auto_start.context(node)
                    local lower = context:lower()
                    local ownName = ""
                    if node.GetName then
                        local okName, value = direct_call(function() return node:GetName(false) end)
                        if okName then ownName = tostring(value or "") end
                    end
                    if ownName == "" then ownName = tostring(node.Name or "") end
                    local ownLower = ownName:lower():gsub("^%s+", ""):gsub("%s+$", "")
                    if ownLower == "auto start" and lower:find("startup", 1, true) and startup.subscribed_auto_start.toggle_capable(node) then
                        return node, context
                    end
                    if depth < 4 then
                        for _, child in ipairs(startup.subscribed_auto_start.children(node)) do
                            queue[#queue + 1] = { node = child, depth = depth + 1 }
                        end
                    end
                end
            end
        end
    end
    return nil, nil
end

function startup.subscribed_auto_start.select_startup_script()
    if not FeatureMgr then return false, "FeatureMgr unavailable" end

    local candidates = {}
    local seen = {}
    local function add(feature, context)
        if feature and not seen[feature] then
            seen[feature] = true
            candidates[#candidates + 1] = { feature = feature, context = context or startup.subscribed_auto_start.context(feature) }
        end
    end

    if FeatureMgr.GetFeatureByName then
        for _, name in ipairs({ "Subscribed Scripts", "Subscribed Script" }) do
            local ok, feature = direct_call(function() return FeatureMgr.GetFeatureByName(name) end)
            if ok then add(feature, name) end
        end
    end
    if FeatureMgr.GetAllFeatures then
        local okAll, all = direct_call(function() return FeatureMgr.GetAllFeatures() end)
        if okAll and type(all) == "table" then
            for _, feature in pairs(all) do
                if feature then
                    local context = startup.subscribed_auto_start.context(feature)
                    local lower = context:lower()
                    if lower:find("subscribed script", 1, true) then add(feature, context) end
                end
            end
        end
    end

    for _, item in ipairs(candidates) do
        local feature = item.feature
        if feature then
            local selected = false
            if feature.GetListIndexByString and feature.SetListIndexByString then
                local okIndex, index = direct_call(function() return feature:GetListIndexByString("Startup") end)
                if okIndex and index ~= nil then
                    local okSet = direct_call(function() feature:SetListIndexByString("Startup") end)
                    if okSet then selected = true end
                end
            end
            if not selected and feature.GetList and feature.SetListIndex then
                local okList, list = direct_call(function() return feature:GetList() end)
                if okList and type(list) == "table" then
                    for index, value in pairs(list) do
                        local name = startup.settings_profile_name_from_value(value)
                        if name:lower() == "startup" then
                            local numericIndex = tonumber(index)
                            if numericIndex ~= nil then
                                local okSet = direct_call(function() feature:SetListIndex(numericIndex) end)
                                if okSet then selected = true break end
                            end
                        end
                    end
                end
            end
            if selected then
                startup.yield(150)
                return true, tostring(item.context or "Subscribed Scripts")
            end
        end
    end
    return false, "Subscribed Scripts selector not exposed"
end

function startup.subscribed_auto_start.find_selected_auto_start()
    if not FeatureMgr or not FeatureMgr.GetFeatureByName then return nil, nil end
    local selected, selectorContext = startup.subscribed_auto_start.select_startup_script()
    if not selected then return nil, selectorContext end

    -- After selecting Startup in the exact dropdown shown by Cherax, the generic Auto Start
    -- control belongs to Startup and is safe to target directly.
    for _, name in ipairs({ "Auto Start", "AutoStart" }) do
        local ok, feature = direct_call(function() return FeatureMgr.GetFeatureByName(name) end)
        if ok and feature and startup.subscribed_auto_start.toggle_capable(feature) then
            return feature, tostring(selectorContext) .. " > Startup > " .. tostring(name)
        end
    end
    return nil, tostring(selectorContext) .. " > Startup > Auto Start not exposed"
end

function startup.subscribed_auto_start.find_feature()
    if not FeatureMgr then return nil, nil end

    -- Highest-confidence route: reproduce the UI sequence from the supplied screenshot.
    local selectedFeature, selectedContext = startup.subscribed_auto_start.find_selected_auto_start()
    if selectedFeature then return selectedFeature, selectedContext end

    local nested, nestedContext = startup.subscribed_auto_start.find_in_startup_container()
    if nested then return nested, nestedContext end

    local directNames = {
        "Startup Auto Start", "Auto Start Startup", "Startup - Auto Start",
        "Startup > Auto Start", "Subscribed Scripts > Startup > Auto Start",
        "Settings > Subscribed Scripts > Startup > Auto Start"
    }
    if FeatureMgr.GetFeatureByName then
        for _, name in ipairs(directNames) do
            local ok, feature = direct_call(function() return FeatureMgr.GetFeatureByName(name) end)
            if ok and feature and startup.subscribed_auto_start.toggle_capable(feature) then
                return feature, startup.subscribed_auto_start.context(feature)
            end
        end
    end

    if not FeatureMgr.GetAllFeatures then return nil, selectedContext end
    local okAll, all = direct_call(function() return FeatureMgr.GetAllFeatures() end)
    if not okAll or type(all) ~= "table" then return nil, selectedContext end

    local bestFeature, bestContext, bestScore = nil, nil, -1
    local exactGeneric = {}
    for _, feature in pairs(all) do
        if feature and startup.subscribed_auto_start.toggle_capable(feature) then
            local context = startup.subscribed_auto_start.context(feature)
            local lower = context:lower()
            local ownName = ""
            if feature.GetName then
                local okName, value = direct_call(function() return feature:GetName(false) end)
                if okName then ownName = tostring(value or "") end
            end
            if ownName == "" then ownName = tostring(feature.Name or "") end
            local ownLower = ownName:lower():gsub("^%s+", ""):gsub("%s+$", "")

            if ownLower == "auto start" then exactGeneric[#exactGeneric + 1] = { feature = feature, context = context } end

            local score = 0
            if ownLower == "auto start" then score = score + 40 end
            if lower:find("startup", 1, true) then score = score + 50 end
            if lower:find("subscribed", 1, true) then score = score + 25 end
            if lower:find("settings", 1, true) then score = score + 5 end
            if ownLower ~= "auto start" then score = math.min(score, 40) end
            if score > bestScore then bestFeature, bestContext, bestScore = feature, context, score end
        end
    end

    if bestFeature and bestScore >= 70 then return bestFeature, bestContext end
    if #exactGeneric == 1 then return exactGeneric[1].feature, exactGeneric[1].context end
    return nil, selectedContext
end

function startup.subscribed_auto_start.try_set(feature)
    if not feature then return false, "no feature" end
    local before = startup.subscribed_auto_start.state(feature)
    if before == true then return true, "already enabled" end

    local clicked = false
    local function click_once()
        if clicked then return nil end
        local clickMethods = { "Click", "Execute", "OnClick", "TriggerCallback" }
        for _, methodName in ipairs(clickMethods) do
            if feature[methodName] then
                local ok = direct_call(function() feature[methodName](feature) end)
                if ok then
                    clicked = true
                    startup.yield(150)
                    return methodName
                end
            end
        end
        return nil
    end

    -- When Cherax explicitly reports the toggle OFF, prefer one real feature click first.
    -- This mirrors the user clicking Settings > Subscribed Scripts > Startup > Auto Start.
    if before == false then
        local clickMethod = click_once()
        if clickMethod and startup.subscribed_auto_start.state(feature) == true then return true, clickMethod end
    end

    -- Setters are fallback/confirmation paths. Never pair SetBoolValue with an unconditional
    -- TriggerCallback, because that can act like a second click on some Cherax toggle builds.
    if feature.SetBoolValue then
        local ok = direct_call(function() feature:SetBoolValue(true) end)
        if ok then
            startup.yield(100)
            if startup.subscribed_auto_start.state(feature) == true then return true, "SetBoolValue" end
        end
    end
    if feature.Toggle then
        local ok = direct_call(function() feature:Toggle(true) end)
        if ok then
            startup.yield(100)
            if startup.subscribed_auto_start.state(feature) == true then return true, "Toggle(true)" end
        end
    end

    -- If state was initially unreadable and setters exposed a readable OFF state, allow exactly
    -- one click now. We never cycle through multiple click methods on the same toggle.
    if not clicked and startup.subscribed_auto_start.state(feature) == false then
        local clickMethod = click_once()
        if clickMethod and startup.subscribed_auto_start.state(feature) == true then return true, clickMethod end
    end

    return startup.subscribed_auto_start.state(feature) == true, clicked and "clicked-unconfirmed" or "unconfirmed"
end

function startup.subscribed_auto_start.enable()
    local feature, featureContext = startup.subscribed_auto_start.find_feature()
    if not feature then
        startup.s.subscribedAutoStartConfirmed = false
        startup.s.subscribedAutoStartStatus = "Could not resolve the selected Startup > Auto Start toggle. Use the guide below and enable it manually if needed."
        startup.log("[Onboarding] AUTO_START_NOT_FOUND | selected-script and Startup-scoped resolvers found no safe candidate")
        return false
    end

    local confirmed, method = startup.subscribed_auto_start.try_set(feature)
    startup.s.subscribedAutoStartConfirmed = confirmed == true
    startup.s.subscribedAutoStartLastFeatureName = tostring(featureContext or startup.read_feature_name(feature) or "Startup Auto Start")
    startup.s.subscribedAutoStartStatus = confirmed
        and ("Startup Auto Start: Enabled via " .. tostring(method or "feature"))
        or "Startup Auto Start was found, but Cherax did not confirm it as enabled. Please enable it manually."
    startup.log("[Onboarding] AUTO_START_ENABLE | confirmed=" .. tostring(confirmed) ..
        " | method=" .. tostring(method) .. " | feature=" .. tostring(startup.s.subscribedAutoStartLastFeatureName))
    if confirmed then startup.toast("Startup Auto Start enabled.", 3500) end
    return confirmed == true
end

function startup.queue_subscribed_auto_start_enable()
    startup.s.pendingSubscribedAutoStartEnable = true
    startup.s.subscribedAutoStartStatus = "Enabling Startup Auto Start..."
end

function startup.process_pending_subscribed_auto_start_enable()
    if startup.s.pendingSubscribedAutoStartEnable ~= true then return end
    startup.s.pendingSubscribedAutoStartEnable = false
    startup.subscribed_auto_start.enable()
    startup.save_config(false)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- kick / crash reaction defense
-- note: CRASH protection reactions may trigger automatic defense when Startup can
-- resolve one unique remote attacker. Generic KICK / VOTE_KICK reactions are passive
-- evidence by default and never classify a player as a modder. Experimental kick
-- auto-removal requires repeated non-duplicate reactions and is OFF by default.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.crash_defense = startup.crash_defense or {}
startup.crash_defense.cooldown = startup.crash_defense.cooldown or {}
startup.crash_defense.cooldown_ms = 15000
startup.crash_defense.responses_by_key = startup.crash_defense.responses_by_key or {}
startup.crash_defense.response_key_by_player = startup.crash_defense.response_key_by_player or {}
startup.crash_defense.response_session_serial = tonumber(startup.crash_defense.response_session_serial or 0) or 0
startup.crash_defense.response_summary_interval_ms = 60000
startup.crash_defense.unresolved_storms = startup.crash_defense.unresolved_storms or {}
startup.crash_defense.unresolved_quiet_ms = 1500
startup.crash_defense.unresolved_status_throttle_ms = 2000
startup.crash_defense.unresolved_last_status_ms = tonumber(startup.crash_defense.unresolved_last_status_ms or 0) or 0
startup.crash_defense.unresolved_total_suppressed = tonumber(startup.crash_defense.unresolved_total_suppressed or 0) or 0
startup.crash_defense.unresolved_storms_summarized = tonumber(startup.crash_defense.unresolved_storms_summarized or 0) or 0
startup.crash_defense.unresolved_last_summary = tostring(startup.crash_defense.unresolved_last_summary or "None")
startup.crash_defense.pending_kicks = startup.crash_defense.pending_kicks or {}
startup.crash_defense.pending_kick_serial = tonumber(startup.crash_defense.pending_kick_serial or 0) or 0
startup.crash_defense.gentle_vehicle_kick_until = startup.crash_defense.gentle_vehicle_kick_until or {}
startup.crash_defense.gentle_vehicle_kick_hash = -503325966
startup.crash_defense.gentle_vehicle_kick_window_ms = 2500
startup.crash_defense.kick_verify_delay_ms = 900
startup.crash_defense.gentle_vehicle_kick_ignored = tonumber(startup.crash_defense.gentle_vehicle_kick_ignored or 0) or 0
startup.crash_defense.gentle_vehicle_kick_last = tostring(startup.crash_defense.gentle_vehicle_kick_last or "None")
startup.crash_defense.kick_duplicate_cache = startup.crash_defense.kick_duplicate_cache or {}
startup.crash_defense.kick_duplicate_window_ms = 3000
startup.crash_defense.kick_duplicate_total = tonumber(startup.crash_defense.kick_duplicate_total or 0) or 0
startup.crash_defense.kick_recent_candidates = startup.crash_defense.kick_recent_candidates or {}
startup.crash_defense.kick_storm_window_ms = 3000
startup.crash_defense.kick_storm_suppress_ms = 5000
startup.crash_defense.kick_storm_until_ms = tonumber(startup.crash_defense.kick_storm_until_ms or 0) or 0
startup.crash_defense.kick_storms_suppressed = tonumber(startup.crash_defense.kick_storms_suppressed or 0) or 0
startup.crash_defense.kick_last_storm_summary = tostring(startup.crash_defense.kick_last_storm_summary or "None")
startup.crash_defense.kick_evidence = startup.crash_defense.kick_evidence or {}
startup.crash_defense.kick_evidence_window_ms = 10000
startup.crash_defense.kick_evidence_required = 2
startup.crash_defense.kick_min_repeat_gap_ms = 3000
startup.crash_defense.kick_unverified_total = tonumber(startup.crash_defense.kick_unverified_total or 0) or 0
startup.crash_defense.noncanonical_numeric_markers_suppressed = tonumber(startup.crash_defense.noncanonical_numeric_markers_suppressed or 0) or 0
startup.crash_defense.confirmed_host_kick_total = tonumber(startup.crash_defense.confirmed_host_kick_total or 0) or 0
startup.crash_defense.confirmed_host_kick_last = tostring(startup.crash_defense.confirmed_host_kick_last or "None")
startup.crash_defense.battleye_host_kick_informational_total = tonumber(startup.crash_defense.battleye_host_kick_informational_total or 0) or 0
startup.crash_defense.battleye_host_kick_informational_last = tostring(startup.crash_defense.battleye_host_kick_informational_last or "None")
startup.crash_defense.pending_confirmed_host_kicks = startup.crash_defense.pending_confirmed_host_kicks or {}
startup.crash_defense.confirmed_host_kick_match_ms = 6000

function startup.crash_defense.set_status(text)
    startup.s.crashDefenseLastStatus = tostring(text or "")
end

function startup.crash_defense.is_local_player_id(playerId)
    local wanted = tonumber(playerId)
    if wanted == nil then return false end
    for _, localId in ipairs(startup.get_local_player_id_candidates()) do
        if tonumber(localId) == wanted then return true end
    end
    return false
end

function startup.crash_defense.is_current_session_player_id(playerId)
    playerId = tonumber(playerId)
    if playerId == nil then return false end
    playerId = math.floor(playerId)
    if playerId < 0 or playerId > 31 then return false end

    -- Protection-reaction payloads may contain unrelated small integers. Only treat a
    -- numeric argument as a player id when that id is actually present in the current
    -- session roster. This prevents values such as 10 from resolving to Cherax's
    -- synthetic "Invalid" player and being mistaken for a real kick attacker.
    if startup.get_voice_player_ids then
        local ok, ids = direct_call(startup.get_voice_player_ids)
        if ok and type(ids) == "table" then
            for _, liveId in ipairs(ids) do
                if tonumber(liveId) == playerId then return true end
            end
            return false
        end
    end

    return false
end

function startup.crash_defense.is_active_remote_player_id(value)
    local playerId = tonumber(value)
    if playerId == nil then return nil, nil end
    playerId = math.floor(playerId)
    if playerId < 0 or playerId > 31 then return nil, nil end
    if startup.crash_defense.is_local_player_id(playerId) then return nil, nil end
    if not startup.crash_defense.is_current_session_player_id(playerId) then return nil, nil end

    local name = nil
    if Players and Players.GetName then
        local ok, result = direct_call(function() return Players.GetName(playerId) end)
        if ok then name = result end
    end
    name = tostring(name or "")
    if name == "" or string.lower(name) == "invalid" then return nil, nil end
    return playerId, name
end

function startup.crash_defense.is_crash_text(value)
    local text = string.lower(tostring(value or ""))
    if text == "crash" then return true end
    if string.find(text, "eprotectiontype.crash", 1, true) then return true end
    if string.find(text, "protectiontype.crash", 1, true) then return true end
    return false
end

function startup.crash_defense.is_kick_text(value)
    local raw = string.lower(tostring(value or ""))
    if startup.mod_detection and startup.mod_detection.is_drop_kick_doping_reason
        and startup.mod_detection.is_drop_kick_doping_reason(raw) then return false end
    local text = raw:gsub("[%s%-]", "_")
    if text == "kick" or text == "vote_kick" or text == "votekick" then return true end
    if string.find(text, "eprotectiontype.kick", 1, true) then return true end
    if string.find(text, "protectiontype.kick", 1, true) then return true end
    if string.find(text, "eprotectiontype.vote_kick", 1, true) then return true end
    if string.find(text, "protectiontype.vote_kick", 1, true) then return true end
    return false
end

function startup.crash_defense.numeric_marker_is_canonical(value, index, args, expectedValue)
    if expectedValue == nil or value ~= expectedValue then return false end

    -- Verified from the user's real Type Mismatch Crash capture: Cherax emits
    -- ON_REACTION(playerId, protectionType). The old compatibility path also accepted
    -- the numeric enum in argument 1, which reversed ordinary callbacks such as
    -- (2, 8) / (2, 9) and falsely accused players 8 / 9 of crashing the local user.
    if tonumber(index or 0) ~= 2 then
        if tonumber(index or 0) == 1 then
            startup.crash_defense.noncanonical_numeric_markers_suppressed =
                (tonumber(startup.crash_defense.noncanonical_numeric_markers_suppressed or 0) or 0) + 1
        end
        return false
    end

    local playerId = args and args[1] or nil
    local liveId = startup.crash_defense.is_active_remote_player_id(playerId)
    return liveId ~= nil
end

function startup.crash_defense.is_kick_marker(value, index, args)
    if type(value) == "string" and startup.crash_defense.is_kick_text(value) then return true end
    if eProtectionType then
        local matchesKick = eProtectionType.KICK ~= nil
            and startup.crash_defense.numeric_marker_is_canonical(value, index, args, eProtectionType.KICK)
        local matchesVote = eProtectionType.VOTE_KICK ~= nil
            and startup.crash_defense.numeric_marker_is_canonical(value, index, args, eProtectionType.VOTE_KICK)
        if matchesKick or matchesVote then return true end
    end
    if type(value) == "table" then
        local keys = { "protectionType", "ProtectionType", "reactionType", "ReactionType", "type", "Type" }
        for _, key in ipairs(keys) do
            local marker = value[key]
            if marker ~= nil then
                if eProtectionType and ((eProtectionType.KICK ~= nil and marker == eProtectionType.KICK) or (eProtectionType.VOTE_KICK ~= nil and marker == eProtectionType.VOTE_KICK)) then return true end
                if startup.crash_defense.is_kick_text(marker) then return true end
            end
        end
    end
    return false
end

function startup.crash_defense.is_known_protection_value(value)
    if not eProtectionType then return false end
    local keys = {
        "AIMING_AT_YOU", "BAD_SCRIPT_EVENT", "CHAT_BANNED_WORD", "CHAT_SPAM",
        "CRASH", "KICK", "REPORT", "SHOOTING_AT_YOU", "SPECTATING_YOU",
        "UNKNOWN", "VOTE_KICK"
    }
    for _, key in ipairs(keys) do
        if eProtectionType[key] ~= nil and value == eProtectionType[key] then return true end
    end
    return false
end

function startup.crash_defense.is_crash_marker(value, index, args)
    if type(value) == "string" and startup.crash_defense.is_crash_text(value) then return true end
    if eProtectionType and eProtectionType.CRASH ~= nil
        and startup.crash_defense.numeric_marker_is_canonical(value, index, args, eProtectionType.CRASH) then
        return true
    end
    if type(value) == "table" then
        local keys = { "protectionType", "ProtectionType", "reactionType", "ReactionType", "type", "Type" }
        for _, key in ipairs(keys) do
            local marker = value[key]
            if marker ~= nil then
                if eProtectionType and eProtectionType.CRASH ~= nil and marker == eProtectionType.CRASH then return true end
                if startup.crash_defense.is_crash_text(marker) then return true end
            end
        end
    end
    return false
end

function startup.crash_defense.response_identity_key(playerId, playerName)
    local id = tonumber(playerId)
    local rid = nil
    if id ~= nil and startup.rid_store and startup.rid_store.identity then
        local ident = startup.rid_store.identity(id)
        if ident and ident.rid then rid = tostring(ident.rid) end
    end
    local key
    if rid and rid ~= "" and rid ~= "0" then
        key = "rid:" .. rid
    else
        key = "slot:" .. tostring(id or -1) .. ":" .. string.lower(tostring(playerName or "unknown"))
    end
    if id ~= nil then startup.crash_defense.response_key_by_player[id] = key end
    return key, rid
end

function startup.crash_defense.clear_player_response(playerId)
    local id = tonumber(playerId)
    if id == nil then return end
    local key = startup.crash_defense.response_key_by_player[id]
    if key then startup.crash_defense.responses_by_key[key] = nil end
    startup.crash_defense.response_key_by_player[id] = nil
end

function startup.crash_defense.reset_response_incidents()
    startup.crash_defense.responses_by_key = {}
    startup.crash_defense.response_key_by_player = {}
    startup.crash_defense.response_session_serial = (tonumber(startup.crash_defense.response_session_serial or 0) or 0) + 1
end

function startup.crash_defense.note_duplicate_response(record, playerName, reason, source)
    if type(record) ~= "table" then return false end
    local now = startup.now()
    record.evidenceCount = (tonumber(record.evidenceCount or 1) or 1) + 1
    record.suppressedCount = (tonumber(record.suppressedCount or 0) or 0) + 1
    record.lastEvidenceMs = now
    record.lastReason = tostring(reason or record.lastReason or "Crash Attack")
    local lastSummary = tonumber(record.lastSummaryMs or record.startedMs or 0) or 0
    if now - lastSummary >= startup.crash_defense.response_summary_interval_ms then
        record.lastSummaryMs = now
        startup.log("[Crash Defense] Suppressed " .. tostring(record.suppressedCount)
            .. " duplicate response(s) for " .. tostring(playerName)
            .. "; the original Block Join & Kick incident remains active/completed.")
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("CRASH_RESPONSE_DUPLICATES_SUPPRESSED",
                "player=" .. tostring(playerName)
                .. " count=" .. tostring(record.suppressedCount)
                .. " state=" .. tostring(record.state)
                .. " reason=" .. tostring(record.lastReason)
                .. " source=" .. tostring(source or "unknown"))
        end
    end
    startup.crash_defense.set_status("Crash attacker already handled: " .. tostring(playerName)
        .. " | duplicate responses suppressed: " .. tostring(record.suppressedCount))
    return true
end

function startup.crash_defense.begin_one_time_crash_response(playerId, playerName, reason, source)
    local id = tonumber(playerId)
    if id == nil then return false end
    local name = tostring(playerName or "Unknown")
    local reasonText = tostring(reason or "Crash Attack")
    local key, rid = startup.crash_defense.response_identity_key(id, name)
    local currentSerial = tonumber(startup.crash_defense.response_session_serial or 0) or 0
    local existing = startup.crash_defense.responses_by_key[key]
    if type(existing) == "table" and tonumber(existing.sessionSerial or -1) == currentSerial
        and (existing.state == "pending" or existing.state == "complete" or existing.state == "exhausted") then
        startup.crash_defense.note_duplicate_response(existing, name, reasonText, source)
        return false
    end

    local _, hostId = startup.get_session_host_name()
    local now = startup.now()
    local record = {
        key = key,
        rid = rid,
        playerId = id,
        playerName = name,
        state = "pending",
        attempts = 0,
        evidenceCount = 1,
        suppressedCount = 0,
        startedMs = now,
        lastEvidenceMs = now,
        lastSummaryMs = now,
        lastReason = reasonText,
        source = tostring(source or "unknown"),
        isSessionHost = tonumber(hostId) == id,
        sessionSerial = currentSerial,
    }
    startup.crash_defense.responses_by_key[key] = record

    startup.s.crashDefenseLastPlayerId = id
    startup.s.crashDefenseLastPlayerName = name
    local hostLabel = record.isSessionHost and " (Session Host)" or ""
    startup.crash_defense.set_status("Crash detection: " .. name .. hostLabel .. " | one-time Block Join & Kick started")

    if startup.s.saveRidCrash == true and startup.rid_store and startup.rid_store.record then
        startup.rid_store.record(id, "Crash Attempt", reasonText, "One-time Block Join & Kick", true)
    end

    startup.log("[Crash Defense] " .. name .. hostLabel .. " triggered " .. reasonText
        .. "; starting one response incident. Further duplicates will be suppressed.")
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("CRASH_RESPONSE_INCIDENT_STARTED",
            "player=" .. name .. " [" .. tostring(id) .. "] rid=" .. tostring(rid or "unknown")
            .. " host=" .. tostring(record.isSessionHost)
            .. " reason=" .. reasonText .. " source=" .. tostring(source or "unknown"))
    end

    local function react_crash_detection_once()
        record.attempts = (tonumber(record.attempts or 0) or 0) + 1
        local blocked = startup.nuke_join_kick.run_for_player_id(id, true, reasonText .. " detected", true)
        if blocked then
            record.state = "complete"
            record.completedMs = startup.now()
            startup.modder_hud_record(name, reasonText, id)
            startup.session_activity_record("blocked", name, reasonText, 10000, { playerId = id, classification = "known_modder" })
            if record.isSessionHost then
                startup.crash_defense.set_status("Hostile Session Host handled once: " .. name .. " | further attempts suppressed")
            else
                startup.crash_defense.set_status("Crash attacker handled once: " .. name .. " | further attempts suppressed")
            end
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("CRASH_ATTACK_DEFENSE",
                    "player=" .. name .. " [" .. tostring(id) .. "] reason=" .. reasonText
                    .. " action=one-time-nuke state=complete host=" .. tostring(record.isSessionHost))
            end
        else
            record.state = "exhausted"
            record.completedMs = startup.now()
            startup.crash_defense.set_status("Crash attacker response exhausted: " .. name .. " | automatic retries stopped")
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("CRASH_ATTACK_DEFENSE_FAILED",
                    "player=" .. name .. " [" .. tostring(id) .. "] reason=" .. reasonText
                    .. " action=one-time-nuke state=exhausted")
            end
        end
    end
    if Script and Script.QueueJob then Script.QueueJob(react_crash_detection_once) else react_crash_detection_once() end
    return true
end

function startup.crash_defense.handle_modder_crash_detection(playerId, playerName, reason, source)
    if startup.s.autoKickCrashAttackersEnabled ~= true then return false end
    if not startup.mod_detection.is_crash_attack_reason(reason) then return false end

    playerId = tonumber(playerId)
    if playerId == nil then return false end
    playerId = math.floor(playerId)
    if playerId < 0 or playerId > 31 or startup.crash_defense.is_local_player_id(playerId) then return false end

    local liveName = nil
    if Players and Players.GetName then liveName = Players.GetName(playerId) end
    liveName = tostring(liveName or playerName or "")
    if liveName == "" or liveName == "Invalid" then return false end

    if startup.s.ignoreFriendsCrash == true and startup.is_player_current_friend(playerId) then
        startup.crash_defense.set_status("Crash detection from friend ignored: " .. liveName .. " | " .. tostring(reason))
        return false
    end

    return startup.crash_defense.begin_one_time_crash_response(playerId, liveName, reason, source or "ModderDB")
end

function startup.crash_defense.describe_args(args)
    local out = {}
    for index, value in ipairs(args or {}) do
        local kind = type(value)
        local rendered = tostring(value)
        if #rendered > 80 then rendered = string.sub(rendered, 1, 80) .. "..." end
        out[#out + 1] = tostring(index) .. ":" .. kind .. "=" .. rendered
    end
    return table.concat(out, " | ")
end

function startup.crash_defense.note_unresolved(reactionKind, reason, trace)
    local now = startup.now()
    local kind = string.upper(tostring(reactionKind or "Reaction"))
    local storm = startup.crash_defense.unresolved_storms[kind]
    if type(storm) ~= "table" then
        storm = {
            count = 0,
            firstMs = now,
            lastMs = now,
            reasons = {},
            traces = {}
        }
        startup.crash_defense.unresolved_storms[kind] = storm
    end

    storm.count = (tonumber(storm.count or 0) or 0) + 1
    storm.lastMs = now
    local reasonText = tostring(reason or "unresolved")
    storm.reasons[reasonText] = (tonumber(storm.reasons[reasonText] or 0) or 0) + 1

    local traceText = tostring(trace or "")
    if #traceText > 220 then traceText = string.sub(traceText, 1, 220) .. "..." end
    if traceText == "" then traceText = "no callback arguments" end
    storm.traces[traceText] = (tonumber(storm.traces[traceText] or 0) or 0) + 1

    -- Keep the UI status useful without rewriting it hundreds of times per second.
    if now - startup.crash_defense.unresolved_last_status_ms >= startup.crash_defense.unresolved_status_throttle_ms then
        startup.crash_defense.unresolved_last_status_ms = now
        startup.crash_defense.set_status(kind .. " reaction unresolved; duplicate callbacks are being suppressed.")
    end
end

function startup.crash_defense.summarize_count_map(values, limit)
    local items = {}
    for label, count in pairs(values or {}) do
        items[#items + 1] = { label = tostring(label), count = tonumber(count or 0) or 0 }
    end
    table.sort(items, function(a, b)
        if a.count == b.count then return a.label < b.label end
        return a.count > b.count
    end)
    local out = {}
    for index = 1, math.min(tonumber(limit or 3) or 3, #items) do
        out[#out + 1] = items[index].label .. " x" .. tostring(items[index].count)
    end
    return table.concat(out, "; ")
end

function startup.crash_defense.flush_reaction_spam(force)
    local now = startup.now()
    local remove = {}
    for kind, storm in pairs(startup.crash_defense.unresolved_storms or {}) do
        local count = tonumber(storm and storm.count or 0) or 0
        local lastMs = tonumber(storm and storm.lastMs or 0) or 0
        if count > 0 and (force == true or now - lastMs >= startup.crash_defense.unresolved_quiet_ms) then
            local firstMs = tonumber(storm.firstMs or lastMs) or lastMs
            local duration = math.max(0, lastMs - firstMs)
            local noun = count == 1 and "callback" or "callbacks"
            local summary = "Suppressed " .. tostring(count) .. " unresolved/duplicate " .. tostring(kind) .. " protection " .. noun .. "."

            startup.crash_defense.unresolved_total_suppressed = startup.crash_defense.unresolved_total_suppressed + count
            startup.crash_defense.unresolved_storms_summarized = startup.crash_defense.unresolved_storms_summarized + 1
            startup.crash_defense.unresolved_last_summary = summary
            startup.crash_defense.set_status(summary)

            -- One concise console summary replaces the entire callback flood. A single
            -- isolated unresolved callback stays silent and remains Support-only.
            if count > 1 then startup.log("[Defense] " .. summary) end
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet(
                    "PROTECTION_REACTION_SPAM_SUMMARY",
                    "kind=" .. tostring(kind) ..
                    " count=" .. tostring(count) ..
                    " durationMs=" .. tostring(duration) ..
                    " reasons=" .. startup.crash_defense.summarize_count_map(storm.reasons, 3) ..
                    " traces=" .. startup.crash_defense.summarize_count_map(storm.traces, 3)
                )
            end
            remove[#remove + 1] = kind
        end
    end
    for _, kind in ipairs(remove) do startup.crash_defense.unresolved_storms[kind] = nil end
end

function startup.crash_defense.collect_table_player_candidates(value, candidates, seen)
    if type(value) ~= "table" then return end
    local keys = {
        "playerId", "PlayerId", "player_id", "player",
        "sender", "Sender", "source", "Source", "attacker", "Attacker"
    }
    for _, key in ipairs(keys) do
        local candidate = value[key]
        local playerId, playerName = startup.crash_defense.is_active_remote_player_id(candidate)
        if playerId ~= nil and not seen[playerId] then
            seen[playerId] = true
            candidates[#candidates + 1] = { id = playerId, name = playerName, source = "table." .. key }
        end
    end
end

function startup.crash_defense.resolve_attacker(args, crash_indexes)
    local candidates = {}
    local seen = {}
    local skipped = {}
    for _, index in ipairs(crash_indexes or {}) do skipped[index] = true end

    for index, value in ipairs(args or {}) do
        if not skipped[index] then
            local playerId, playerName = startup.crash_defense.is_active_remote_player_id(value)
            if playerId ~= nil and not seen[playerId] then
                seen[playerId] = true
                candidates[#candidates + 1] = { id = playerId, name = playerName, source = "arg " .. tostring(index) }
            end
            startup.crash_defense.collect_table_player_candidates(value, candidates, seen)
        end
    end

    if #candidates == 1 then
        return candidates[1].id, candidates[1].name, candidates[1].source, 1
    end
    return nil, nil, nil, #candidates
end

function startup.crash_defense.kick_payload_fingerprint(args, markerIndexes, playerId, source)
    local markerMap = {}
    for _, index in ipairs(markerIndexes or {}) do markerMap[index] = true end

    local signature = {}
    for index, value in ipairs(args or {}) do
        if markerMap[index] then
            signature[#signature + 1] = tostring(index) .. ":marker"
        else
            local valueType = type(value)
            if valueType == "number" then
                local numberValue = tonumber(value)
                if numberValue ~= nil and numberValue >= 0 and numberValue <= 31 then
                    signature[#signature + 1] = tostring(index) .. ":slot"
                else
                    signature[#signature + 1] = tostring(index) .. ":number"
                end
            elseif valueType == "string" then
                signature[#signature + 1] = tostring(index) .. ":string"
            elseif valueType == "table" then
                signature[#signature + 1] = tostring(index) .. ":table"
            else
                signature[#signature + 1] = tostring(index) .. ":" .. valueType
            end
        end
    end

    return table.concat({
        "KICK",
        tostring(playerId or "nil"),
        tostring(source or "unknown"),
        table.concat(signature, ",")
    }, "|")
end

function startup.crash_defense.is_duplicate_kick_fingerprint(fingerprint)
    local now = startup.now()
    local cache = startup.crash_defense.kick_duplicate_cache
    local lastMs = tonumber(cache[fingerprint] or 0) or 0
    cache[fingerprint] = now

    for key, seenMs in pairs(cache) do
        if now - (tonumber(seenMs or 0) or 0) > startup.crash_defense.kick_duplicate_window_ms * 3 then
            cache[key] = nil
        end
    end

    if lastMs > 0 and now - lastMs < startup.crash_defense.kick_duplicate_window_ms then
        startup.crash_defense.kick_duplicate_total = startup.crash_defense.kick_duplicate_total + 1
        return true
    end
    return false
end

function startup.crash_defense.note_kick_candidate(playerId, playerName)
    local now = startup.now()
    if now < startup.crash_defense.kick_storm_until_ms then
        return false, "storm-cooldown"
    end

    local recent = {}
    for _, entry in ipairs(startup.crash_defense.kick_recent_candidates or {}) do
        if now - (tonumber(entry.ms or 0) or 0) <= startup.crash_defense.kick_storm_window_ms then
            recent[#recent + 1] = entry
        end
    end
    recent[#recent + 1] = { id = playerId, name = tostring(playerName or "Unknown"), ms = now }
    startup.crash_defense.kick_recent_candidates = recent

    local unique = {}
    local names = {}
    for _, entry in ipairs(recent) do
        local id = tonumber(entry.id)
        if id ~= nil and unique[id] ~= true then
            unique[id] = true
            names[#names + 1] = tostring(entry.name or "Unknown") .. " [" .. tostring(id) .. "]"
        end
    end

    if #names < 2 then return true, "single-player" end

    startup.crash_defense.pending_kicks = {}
    startup.crash_defense.kick_evidence = {}
    startup.crash_defense.kick_storm_until_ms = now + startup.crash_defense.kick_storm_suppress_ms
    startup.crash_defense.kick_storms_suppressed = startup.crash_defense.kick_storms_suppressed + 1
    local summary = "Suppressed multi-player kick reaction storm: " .. table.concat(names, ", ") .. ". No action taken."
    startup.crash_defense.kick_last_storm_summary = summary
    startup.crash_defense.set_status(summary)
    startup.log("[Kick Defense] " .. summary)
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet(
            "KICK_REACTION_STORM_SUPPRESSED",
            "players=" .. table.concat(names, "; ") .. " windowMs=" .. tostring(startup.crash_defense.kick_storm_window_ms)
        )
    end
    return false, "multi-player-storm"
end

function startup.crash_defense.record_kick_evidence(playerId, fingerprint)
    local now = startup.now()
    local evidence = startup.crash_defense.kick_evidence[playerId]
    if type(evidence) ~= "table" or now - (tonumber(evidence.lastMs or 0) or 0) > startup.crash_defense.kick_evidence_window_ms then
        evidence = { count = 0, firstMs = now, lastMs = 0, lastFingerprint = "" }
    end

    -- Duplicate callbacks are filtered before this function. A later reaction with
    -- the same payload shape may count only after the full separation window.
    if evidence.lastMs > 0 and now - evidence.lastMs < startup.crash_defense.kick_min_repeat_gap_ms then
        return tonumber(evidence.count or 0) or 0, false
    end

    evidence.count = (tonumber(evidence.count or 0) or 0) + 1
    evidence.lastMs = now
    evidence.lastFingerprint = tostring(fingerprint or "")
    startup.crash_defense.kick_evidence[playerId] = evidence
    return evidence.count, true
end

function startup.crash_defense.is_recent_gentle_vehicle_kick(playerId)
    playerId = tonumber(playerId)
    if playerId == nil then return false end
    playerId = math.floor(playerId)
    local untilMs = tonumber(startup.crash_defense.gentle_vehicle_kick_until[playerId] or 0) or 0
    local now = startup.now()
    if untilMs >= now then return true end
    if untilMs > 0 then startup.crash_defense.gentle_vehicle_kick_until[playerId] = nil end
    return false
end

function startup.crash_defense.note_scripted_game_event(_, args)
    if type(args) ~= "table" then return false end
    local eventHash = tonumber(args[1])
    if eventHash ~= startup.crash_defense.gentle_vehicle_kick_hash then return false end

    -- SCRIPT_EVENT_LEAVE_VEHICLE carries the sender slot in arg 2. Cherax may label
    -- this ordinary leave-vehicle request as "Gentle Vehicle Kick" and also emit a
    -- generic KICK reaction. It is not reliable evidence of a real kick attack.
    local playerId, playerName = startup.crash_defense.is_active_remote_player_id(args[2])
    if playerId == nil then return false end

    local now = startup.now()
    startup.crash_defense.gentle_vehicle_kick_until[playerId] = now + startup.crash_defense.gentle_vehicle_kick_window_ms
    startup.crash_defense.gentle_vehicle_kick_last = tostring(playerName) .. " [" .. tostring(playerId) .. "]"
    if startup.crash_defense.pending_kicks[playerId] ~= nil then
        startup.crash_defense.set_status("Verifying harmless Gentle Vehicle Kick event from " .. tostring(playerName) .. "...")
    end
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet(
            "GENTLE_VEHICLE_KICK_OBSERVED",
            "player=" .. tostring(playerName) .. " [" .. tostring(playerId) .. "] event=" .. tostring(eventHash)
        )
    end
    return false
end

function startup.crash_defense.confirm_kick_reaction(playerId, playerName, source, trace, token, fingerprint)
    Script.Yield(startup.crash_defense.kick_verify_delay_ms)
    if startup.crash_defense.pending_kicks[playerId] ~= token then return end
    startup.crash_defense.pending_kicks[playerId] = nil

    if startup.crash_defense.is_recent_gentle_vehicle_kick(playerId) then
        startup.crash_defense.gentle_vehicle_kick_ignored = startup.crash_defense.gentle_vehicle_kick_ignored + 1
        startup.crash_defense.set_status("Ignored harmless Gentle Vehicle Kick event from " .. tostring(playerName))
        startup.log("[Kick Defense] Ignored Gentle Vehicle Kick false positive from " .. tostring(playerName) .. " [" .. tostring(playerId) .. "]")
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet(
                "KICK_REACTION_FALSE_POSITIVE",
                "player=" .. tostring(playerName) .. " [" .. tostring(playerId) .. "] reason=gentle-vehicle-kick trace=" .. tostring(trace or "")
            )
        end
        return
    end

    if startup.now() < startup.crash_defense.kick_storm_until_ms then
        startup.crash_defense.set_status("Kick reaction ignored during multi-player storm cooldown; no action taken.")
        return
    end

    local liveId, liveName = startup.crash_defense.is_active_remote_player_id(playerId)
    if liveId == nil then
        startup.crash_defense.set_status("Kick reaction expired before review; no action taken.")
        return
    end
    playerName = tostring(liveName or playerName or "Unknown")

    if startup.s.ignoreFriendsCrash == true and startup.is_player_current_friend(liveId) then
        startup.crash_defense.set_status("Kick reaction from friend ignored: " .. playerName)
        return
    end

    local evidenceCount, added = startup.crash_defense.record_kick_evidence(liveId, tostring(fingerprint or "unknown"))
    if added then startup.crash_defense.kick_unverified_total = startup.crash_defense.kick_unverified_total + 1 end

    local threshold = tonumber(startup.crash_defense.kick_evidence_required or 2) or 2
    local strictEnabled = startup.s.autoKickKickAttackersEnabled == true
    local message
    if evidenceCount >= threshold then
        if strictEnabled then
            message = "Repeated non-duplicate kick reactions from " .. playerName .. " reached the strict threshold."
        else
            message = "Repeated kick reactions involving " .. playerName .. "; strict auto-removal is OFF, so no action was taken."
        end
    else
        message = "Unverified KICK / VOTE_KICK protection reaction involving " .. playerName .. "; no action taken."
    end

    startup.s.crashDefenseLastPlayerId = liveId
    startup.s.crashDefenseLastPlayerName = playerName
    startup.crash_defense.set_status(message)
    if startup.s.logUnverifiedKickReactions ~= false then
        startup.log("[Kick Defense] " .. message .. " Source=" .. tostring(source) .. " Evidence=" .. tostring(evidenceCount) .. "/" .. tostring(threshold))
    end
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet(
            "UNVERIFIED_KICK_REACTION",
            "player=" .. playerName .. " [" .. tostring(liveId) .. "] source=" .. tostring(source) ..
            " evidence=" .. tostring(evidenceCount) .. "/" .. tostring(threshold) ..
            " strict=" .. tostring(strictEnabled) .. " trace=" .. tostring(trace or "")
        )
    end

    if startup.browser_safety and startup.browser_safety.is_verified_peer and startup.browser_safety.is_verified_peer(liveId) == true then
        if evidenceCount >= threshold then
            local _, currentHostId = startup.get_session_host_name()
            local localIsHost = startup.browser_is_local_session_host and startup.browser_is_local_session_host() == true
            if localIsHost and tonumber(currentHostId) ~= tonumber(liveId) then
                local lastReactive = tonumber(startup.browser_safety.reactive_kick_cooldown[liveId] or 0) or 0
                if startup.now() - lastReactive > 30000 then
                    startup.browser_safety.reactive_kick_cooldown[liveId] = startup.now()
                    local sent = startup.host_kick_bypass and startup.host_kick_bypass.run_for_player_id
                        and startup.host_kick_bypass.run_for_player_id(liveId, "Verified Peer Reactive Kick") == true
                    startup.crash_defense.set_status(sent and ("Reactive Host Kick sent after repeated kick attempts: " .. playerName)
                        or ("Repeated kick attempts detected from verified peer, but reactive Host Kick was unavailable: " .. playerName))
                    if startup.support_log_event_quiet then startup.support_log_event_quiet("VERIFIED_PEER_REACTIVE_KICK",
                        "player="..playerName.." ["..tostring(liveId).."] evidence="..tostring(evidenceCount).." sent="..tostring(sent)) end
                end
            elseif tonumber(currentHostId) == tonumber(liveId) then
                startup.crash_defense.set_status("Verified Session Host kick attempts detected; Host Kick cannot target the Session Host.")
            else
                startup.crash_defense.set_status("Verified peer kick attempts detected; only the current Session Host can retaliate with Host Kick.")
            end
        end
        return
    end

    if not strictEnabled or evidenceCount < threshold then return end

    local now = startup.now()
    local last = tonumber(startup.crash_defense.cooldown[liveId] or 0) or 0
    if now - last < startup.crash_defense.cooldown_ms then return end
    startup.crash_defense.cooldown[liveId] = now

    local smartFeature, smartName = startup.country_filter.find_player_feature_by_names(liveId, { "Smart Kick", "Smart kick", "SMART KICK" })
    local sent = smartFeature and startup.country_filter.click_player_feature(smartFeature) == true
    if sent then
        if startup.s.saveRidCrash == true and startup.rid_store and startup.rid_store.record then
            startup.rid_store.record(liveId, "Repeated Kick Reactions", "Strict two-reaction threshold reached", "Smart Kick (Strict)", true)
        end
        -- Do not create a Modders HUD record. Repeated protection reactions still do
        -- not prove the player is a modder.
        startup.session_activity_record("kicking", playerName, "Strict Kick Defense", 7000)
        startup.crash_defense.set_status("Strict Kick Defense Smart Kicked: " .. playerName)
        startup.log("[Kick Defense] Strict repeated-reaction threshold met for " .. playerName .. " [" .. tostring(liveId) .. "]; Smart Kick sent.")
    else
        startup.crash_defense.set_status("Strict kick threshold reached for " .. playerName .. ", but Smart Kick was unavailable.")
    end
    startup.crash_defense.kick_evidence[liveId] = nil
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet(
            "STRICT_KICK_DEFENSE",
            "player=" .. playerName .. " [" .. tostring(liveId) .. "] sent=" .. tostring(sent) .. " feature=" .. tostring(smartName or "not-found")
        )
    end
end

function startup.crash_defense.queue_kick_verification(playerId, playerName, source, trace, fingerprint)
    if startup.crash_defense.pending_kicks[playerId] ~= nil then return end
    if not Script or not Script.QueueJob then
        startup.crash_defense.set_status("Kick reaction detected, but the review worker is unavailable; no action taken.")
        return
    end

    startup.crash_defense.pending_kick_serial = startup.crash_defense.pending_kick_serial + 1
    local token = startup.crash_defense.pending_kick_serial
    startup.crash_defense.pending_kicks[playerId] = token
    startup.crash_defense.set_status("Reviewing unverified kick reaction involving " .. tostring(playerName) .. "...")
    Script.QueueJob(function()
        startup.crash_defense.confirm_kick_reaction(playerId, playerName, source, trace, token, fingerprint)
    end)
end

function startup.crash_defense.handle_reaction(...)
    local crashAutoEnabled = startup.s.autoKickCrashAttackersEnabled == true
    local kickAutoEnabled = startup.s.autoKickKickAttackersEnabled == true
    local kickLoggingEnabled = startup.s.logUnverifiedKickReactions ~= false
    if not crashAutoEnabled and not kickAutoEnabled and not kickLoggingEnabled then return end

    local args = { ... }
    if #args == 0 then return end

    local crash_indexes, kick_indexes = {}, {}
    for index, value in ipairs(args) do
        if startup.crash_defense.is_crash_marker(value, index, args) then
            crash_indexes[#crash_indexes + 1] = index
        elseif startup.crash_defense.is_kick_marker(value, index, args) then
            kick_indexes[#kick_indexes + 1] = index
        end
    end
    if #crash_indexes == 0 and #kick_indexes == 0 then return end

    -- Crash takes priority if a reaction payload somehow contains both markers.
    local reactionKind = #crash_indexes > 0 and "Crash" or "Kick"
    local markerIndexes = #crash_indexes > 0 and crash_indexes or kick_indexes
    local trace = startup.crash_defense.describe_args(args)
    local playerId, playerName, source, candidateCount = startup.crash_defense.resolve_attacker(args, markerIndexes)
    if playerId == nil then
        local reason = candidateCount > 1 and ("ambiguous attacker (" .. tostring(candidateCount) .. " active-player candidates)") or "attacker was not exposed as a player id"
        startup.crash_defense.note_unresolved(reactionKind, reason, trace)
        return
    end

    if startup.s.ignoreFriendsCrash == true and startup.is_player_current_friend(playerId) then
        startup.crash_defense.set_status(reactionKind .. " reaction from friend ignored: " .. tostring(playerName))
        return
    end

    if reactionKind == "Kick" then
        if not kickAutoEnabled and not kickLoggingEnabled then return end

        local fingerprint = startup.crash_defense.kick_payload_fingerprint(args, markerIndexes, playerId, source)
        if startup.crash_defense.is_duplicate_kick_fingerprint(fingerprint) then
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet(
                    "DUPLICATE_KICK_REACTION_SUPPRESSED",
                    "player=" .. tostring(playerName) .. " [" .. tostring(playerId) .. "] source=" .. tostring(source)
                )
            end
            return
        end

        local accepted = startup.crash_defense.note_kick_candidate(playerId, playerName)
        if accepted ~= true then return end
        startup.crash_defense.queue_kick_verification(playerId, playerName, source, trace, fingerprint)
        return
    end

    if not crashAutoEnabled then
        startup.crash_defense.set_status("Crash reaction involving " .. tostring(playerName) .. " detected, but crash auto-removal is OFF.")
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet(
                "CRASH_REACTION_AUTO_REMOVAL_DISABLED",
                "player=" .. tostring(playerName) .. " [" .. tostring(playerId) .. "] source=" .. tostring(source) .. " trace=" .. tostring(trace)
            )
        end
        return
    end

    startup.log("[Crash Defense] CRASH reaction resolved to " .. tostring(playerName) .. " [" .. tostring(playerId) .. "] via " .. tostring(source) .. " | " .. trace)
    startup.crash_defense.begin_one_time_crash_response(playerId, playerName, "Crash Attack", "ON_REACTION:" .. tostring(source))
end

function startup.nuke_join_kick.dump_feature(feature, prefix)
    if not feature then return end
    local name = startup.nuke_join_kick.feature_name(feature)
    local hash = startup.nuke_join_kick.get_feature_hash(feature) or "nil"
    local arrayIndex = startup.nuke_join_kick.call("GetArrayIndex", function()
        if feature.GetArrayIndex then return feature:GetArrayIndex() end
        return nil
    end)
    local playerIndex = startup.nuke_join_kick.call("GetPlayerIndex", function()
        if feature.GetPlayerIndex then return feature:GetPlayerIndex() end
        return nil
    end)
    local isToggle = startup.nuke_join_kick.call("IsToggleFeature", function()
        if feature.IsToggleFeature then return feature:IsToggleFeature() end
        return nil
    end)
    local isToggled = startup.nuke_join_kick.call("IsToggled", function()
        if feature.IsToggled then return feature:IsToggled() end
        return nil
    end)
    local boolValue = startup.nuke_join_kick.call("GetBoolValue", function()
        if feature.GetBoolValue then return feature:GetBoolValue() end
        return nil
    end)
    local visible = startup.nuke_join_kick.call("IsVisible", function()
        if feature.IsVisible then return feature:IsVisible() end
        return nil
    end)
    local list = startup.nuke_join_kick.get_list(feature, name)
    startup.nuke_join_kick.log(
        tostring(prefix or "Feature") ..
        " | name=" .. tostring(name) ..
        " | hash=" .. tostring(hash) ..
        " | type=" .. tostring(startup.nuke_join_kick.feature_type(feature)) ..
        " | array=" .. tostring(arrayIndex) ..
        " | player=" .. tostring(playerIndex) ..
        " | toggleCapable=" .. tostring(isToggle) ..
        " | toggled=" .. tostring(isToggled) ..
        " | bool=" .. tostring(boolValue) ..
        " | visible=" .. tostring(visible)
    )
    if type(list) == "table" then
        for i, item in ipairs(list) do
            startup.nuke_join_kick.log("  list[" .. tostring(i - 1) .. "]=" .. tostring(item))
        end
    end
end

function startup.nuke_join_kick.name_matches_probe(name)
    local lower = string.lower(tostring(name or ""))
    for _, word in ipairs(startup.nuke_join_kick.probe_words) do
        if string.find(lower, string.lower(word), 1, true) then
            return true
        end
    end
    return false
end

function startup.nuke_join_kick.dump_scapi_matches()
    startup.nuke_join_kick.force_log = true
    startup.nuke_join_kick.toast("Dumping SCAPI / Saved Players / Auto Kick / Reason feature matches to log...", 5000)
    local all = startup.nuke_join_kick.call("FeatureMgr.GetAllFeatures", function()
        if FeatureMgr.GetAllFeatures then
            return FeatureMgr.GetAllFeatures()
        end
        return nil
    end)
    if type(all) == "table" then
        local count = 0
        for _, feature in pairs(all) do
            local name = startup.nuke_join_kick.feature_name(feature)
            if startup.nuke_join_kick.name_matches_probe(name) then
                count = count + 1
                startup.nuke_join_kick.dump_feature(feature, "GLOBAL MATCH #" .. tostring(count))
            end
        end
        startup.nuke_join_kick.log("Global match count: " .. tostring(count))
    else
        startup.nuke_join_kick.log("FeatureMgr.GetAllFeatures unavailable.")
    end
    local playerHashes = startup.nuke_join_kick.call("FeatureMgr.GetAllPlayerFeatureHashes", function()
        if FeatureMgr.GetAllPlayerFeatureHashes then
            return FeatureMgr.GetAllPlayerFeatureHashes()
        end
        return nil
    end)
    if type(playerHashes) == "table" then
        local count = 0
        for _, hash in pairs(playerHashes) do
            local feature = startup.nuke_join_kick.call("Get player feature by hash", function()
                return FeatureMgr.GetFeature(hash)
            end)
            if feature then
                local name = startup.nuke_join_kick.feature_name(feature)
                if startup.nuke_join_kick.name_matches_probe(name) then
                    count = count + 1
                    startup.nuke_join_kick.dump_feature(feature, "PLAYER MATCH #" .. tostring(count))
                end
            end
        end
        startup.nuke_join_kick.log("Player feature match count: " .. tostring(count))
    else
        startup.nuke_join_kick.log("FeatureMgr.GetAllPlayerFeatureHashes unavailable.")
    end
    startup.nuke_join_kick.force_log = false
end

function startup.nuke_join_kick.remove_player_feature_hash(hash)
    if not hash or not FeatureMgr then return false end
    local removed = false
    if FeatureMgr.RemovePlayerFeature then
        FeatureMgr.RemovePlayerFeature(hash)
        removed = true
    end
    if FeatureMgr.RemoveFeature then
        FeatureMgr.RemoveFeature(hash)
        removed = true
    end
    return removed
end

function startup.nuke_join_kick.remove_player_features_by_exact_name(wantedName)
    if not FeatureMgr or not FeatureMgr.GetAllPlayerFeatureHashes then return end
    local hashes = FeatureMgr.GetAllPlayerFeatureHashes()
    if type(hashes) ~= "table" then return end
    for _, hash in pairs(hashes) do
        local feature = FeatureMgr.GetFeature(hash)
        if feature and tostring(startup.nuke_join_kick.feature_name(feature)) == tostring(wantedName) then
            startup.nuke_join_kick.remove_player_feature_hash(hash)
        end
    end
end

function startup.nuke_join_kick.cleanup_player_feature()
    startup.clear_player_feature_render_links("Nuke Join & Kick", startup.nuke_join_kick.placement_anchor_names or startup.nuke_join_kick.smart_kick_names or {})
    if type(startup.nuke_join_kick.feature_hashes) == "table" then
        for _, hash in pairs(startup.nuke_join_kick.feature_hashes) do
            startup.nuke_join_kick.remove_player_feature_hash(hash)
        end
    end
    startup.nuke_join_kick.feature_hashes = {}
    startup.nuke_join_kick.hash_to_player_index = {}
    startup.nuke_join_kick.player_index_to_hash = {}
    startup.nuke_join_kick.remove_player_features_by_exact_name("Nuke Join & Kick")
    local oldHashes = {
        startup.hash("NUKE_JOIN_AND_KICK_SAFE_V119"),
        startup.hash("NUKE_JOIN_AND_KICK_SAFE_V120"),
        startup.hash("NUKE_JOIN_AND_KICK_SAFE_V121"),
        startup.hash("NUKE_JOIN_AND_KICK_SAFE_V122"),
        startup.hash("NUKE_JOIN_AND_KICK_SAFE_V123"),
        startup.hash("NUKE_JOIN_AND_KICK_SAFE_V124"),
        startup.hash("NUKE_JOIN_AND_KICK_SAFE"),
        startup.hash("NUKE_JOIN_AND_KICK"),
        startup.hash("NUKE_JOIN_KICK"),
        startup.hash("NUKE_JOIN_KICK_SAFE"),
        startup.hash("NUKE_BLOCK_JOIN_KICK"),
        startup.hash("BATTLEYE_NUKE_JOIN_KICK")
    }
    for _, hash in ipairs(oldHashes) do
        startup.nuke_join_kick.remove_player_feature_hash(hash)
    end
end

function startup.nuke_join_kick.register_player_feature()
    if not FeatureMgr or not FeatureMgr.AddPlayerFeature then
        startup.nuke_join_kick.error("FeatureMgr.AddPlayerFeature unavailable.")
        return
    end
    startup.nuke_join_kick.cleanup_player_feature()
    startup.nuke_join_kick.hash_to_player_index = {}
    startup.nuke_join_kick.player_index_to_hash = {}
    startup.nuke_join_kick.feature_hashes = FeatureMgr.AddPlayerFeature(
        startup.hash("NUKE_JOIN_AND_KICK_SAFE_V119"),
        "Nuke Join & Kick",
        eFeatureType.Button,
        "Defensive lockout: presses built-in Block Join & Kick for the selected player, then attempts Block Join + Auto Kick + Reason Cheater.",
        function(f)
            startup.nuke_join_kick.run(f)
        end
    )
    if not startup.nuke_join_kick.feature_hashes then
        startup.nuke_join_kick.error("Failed to create Nuke Join & Kick player feature.")
        return
    end
    for possiblePlayerId, hash in pairs(startup.nuke_join_kick.feature_hashes) do
        local nukeFeature = FeatureMgr.GetFeature(hash)
        if nukeFeature then
            nukeFeature:SetSaveable(false)
            if nukeFeature.SetSearchable then
                nukeFeature:SetSearchable(true)
            end
            local resolvedIndex = startup.nuke_join_kick.call("nukeFeature:GetArrayIndex", function()
                if nukeFeature.GetArrayIndex then
                    return nukeFeature:GetArrayIndex()
                end
                return nil
            end)
            if resolvedIndex == nil then
                resolvedIndex = possiblePlayerId
            end
            startup.nuke_join_kick.hash_to_player_index[hash] = resolvedIndex
            startup.nuke_join_kick.player_index_to_hash[resolvedIndex] = hash
            if startup.s.verboseStartupLogs then
                startup.nuke_join_kick.log("Mapped Nuke feature hash " .. tostring(hash) .. " -> player index " .. tostring(resolvedIndex))
            end
            local placed = false
            for _, smartKickName in ipairs(startup.nuke_join_kick.placement_anchor_names or startup.nuke_join_kick.smart_kick_names or {}) do
                local smartKickFeature = startup.get_player_feature_by_name_safe(smartKickName, resolvedIndex)
                if smartKickFeature then
                    placed = startup.attach_render_after_once(smartKickFeature, nukeFeature)
                    if placed then break end
                end
            end
            if not placed and startup.s.verboseStartupLogs then
                startup.nuke_join_kick.log("Nuke Join & Kick created, but Smart Kick placement anchor was not found for player index " .. tostring(resolvedIndex))
            end
        end
    end
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- host kick bypass
-- note: restores the host-side fallback player action.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.host_kick_bypass = startup.host_kick_bypass or {}
startup.host_kick_bypass.feature_hashes = startup.host_kick_bypass.feature_hashes or {}
startup.host_kick_bypass.native_hash = 0xFA8904DC5F304220
startup.host_kick_bypass.feature_hash = nil
startup.host_kick_bypass.host_kick_names = {
    "Host Kick",
    "Host kick",
    "HOST KICK"
}

function startup.host_kick_bypass.log(msg)
    if startup.s.verboseStartupLogs then
        startup.log("[Host Kick Bypass] " .. tostring(msg))
    end
end

function startup.host_kick_bypass.resolve_player_index(feature)
    if not feature then return nil end
    if feature.GetPlayerIndex then return feature:GetPlayerIndex() end
    if feature.GetArrayIndex then return feature:GetArrayIndex() end
    return nil
end

function startup.host_kick_bypass.run_for_player_id(playerIndex, sourceLabel)
    playerIndex = tonumber(playerIndex)
    if playerIndex == nil then
        startup.host_kick_bypass.log("Could not resolve player index for direct fallback.")
        return false
    end
    if startup.is_local_player_id(playerIndex) then
        startup.host_kick_bypass.log("Blocked Host Kick fallback against local player | source=" .. tostring(sourceLabel or "unknown"))
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("SELF_KICK_BLOCKED", "path=Host Kick Bypass source=" .. tostring(sourceLabel or "unknown"))
        end
        return false
    end
    local targetName = startup.session_activity_player_name(playerIndex)
    Natives.InvokeVoid(startup.host_kick_bypass.native_hash, playerIndex)
    startup.modder_hud_remove(targetName, playerIndex)
    startup.host_kick_bypass.log(tostring(sourceLabel or "Host Kick Bypass") .. " -> player index " .. tostring(playerIndex))
    return true
end

function startup.host_kick_bypass.run(feature)
    local playerIndex = startup.host_kick_bypass.resolve_player_index(feature)
    if playerIndex == nil then
        if GUI and GUI.AddToast then GUI.AddToast("Host Kick Bypass", "Could not resolve selected player index.", 3500) end
        startup.host_kick_bypass.log("Could not resolve selected player index.")
        return
    end
    if startup.is_local_player_id(playerIndex) then
        if GUI and GUI.AddToast then GUI.AddToast("Host Kick Bypass", "Startup refused to target your own player.", 4000) end
        startup.host_kick_bypass.log("Blocked manual Host Kick Bypass against local player.")
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("SELF_KICK_BLOCKED", "path=manual Host Kick Bypass")
        end
        return
    end
    local targetName = startup.session_activity_player_name(playerIndex)
    Natives.InvokeVoid(startup.host_kick_bypass.native_hash, playerIndex)
    startup.modder_hud_remove(targetName, playerIndex)
    startup.host_kick_bypass.log("Triggered for player index " .. tostring(playerIndex))
end

function startup.host_kick_bypass.remove_player_feature_hash(hash)
    if not hash or not FeatureMgr then return false end
    local removed = false
    if FeatureMgr.RemovePlayerFeature then
        FeatureMgr.RemovePlayerFeature(hash)
        removed = true
    end
    if FeatureMgr.RemoveFeature then
        FeatureMgr.RemoveFeature(hash)
        removed = true
    end
    return removed
end

function startup.host_kick_bypass.remove_player_features_by_exact_name(wantedName)
    if not FeatureMgr or not FeatureMgr.GetAllPlayerFeatureHashes then return end
    local hashes = FeatureMgr.GetAllPlayerFeatureHashes()
    if type(hashes) ~= "table" then return end
    for _, hash in pairs(hashes) do
        local feature = FeatureMgr.GetFeature(hash)
        if feature then
            local name = feature.GetName and feature:GetName(false) or feature.Name or ""
            if tostring(name) == tostring(wantedName) then startup.host_kick_bypass.remove_player_feature_hash(hash) end
        end
    end
end

function startup.host_kick_bypass.cleanup_old_feature()
    startup.clear_player_feature_render_links("Host Kick Bypass", startup.host_kick_bypass.host_kick_names or { "Host Kick" })
    if type(startup.host_kick_bypass.feature_hashes) == "table" then
        for _, hash in pairs(startup.host_kick_bypass.feature_hashes) do
            startup.host_kick_bypass.remove_player_feature_hash(hash)
        end
    end
    startup.host_kick_bypass.feature_hashes = {}
    startup.host_kick_bypass.remove_player_features_by_exact_name("Host Kick Bypass")
    local oldHashes = {}
    if Utils and Utils.Joaat then
        oldHashes[#oldHashes + 1] = Utils.Joaat("PrimeHostKick")
        oldHashes[#oldHashes + 1] = Utils.Joaat("HOST_KICK_BYPASS")
        oldHashes[#oldHashes + 1] = Utils.Joaat("HOSTKICK_BYPASS")
        oldHashes[#oldHashes + 1] = Utils.Joaat("ST_HOST_KICK_BYPASS")
        oldHashes[#oldHashes + 1] = Utils.Joaat("ST_STARTUP_HOST_KICK_BYPASS")
    end
    oldHashes[#oldHashes + 1] = startup.hash("HOST_KICK_BYPASS")
    oldHashes[#oldHashes + 1] = startup.hash("HOSTKICK_BYPASS")
    oldHashes[#oldHashes + 1] = startup.hash("PRIME_HOST_KICK")
    oldHashes[#oldHashes + 1] = startup.hash("PrimeHostKick")
    for _, hash in ipairs(oldHashes) do
        startup.host_kick_bypass.remove_player_feature_hash(hash)
    end
    startup.host_kick_bypass.feature_hash = Utils and Utils.Joaat and Utils.Joaat("PrimeHostKick") or nil
end

function startup.host_kick_bypass.register_player_feature()
    if not FeatureMgr or not FeatureMgr.AddPlayerFeature or not Utils or not Utils.Joaat then
        startup.host_kick_bypass.log("FeatureMgr.AddPlayerFeature or Utils.Joaat unavailable.")
        return
    end
    startup.host_kick_bypass.cleanup_old_feature()
    local hashes = FeatureMgr.AddPlayerFeature(
        Utils.Joaat("PrimeHostKick"),
        "Host Kick Bypass",
        eFeatureType.Button,
        "Allows you to host kick Prime users on normal Cherax versions.",
        function(feature)
            startup.host_kick_bypass.run(feature)
        end
    )
    startup.host_kick_bypass.feature_hashes = hashes or {}
    for _, hash in pairs(startup.host_kick_bypass.feature_hashes) do
        local bypassFeature = nil
        bypassFeature = FeatureMgr.GetFeature(hash)
        if bypassFeature then
            if bypassFeature.SetSaveable then
                bypassFeature:SetSaveable(false)
            end
        end
    end
    for possiblePlayerId, hash in pairs(startup.host_kick_bypass.feature_hashes) do
        local bypassFeature = nil
        bypassFeature = FeatureMgr.GetFeature(hash)
        if bypassFeature then
            local resolvedIndex = possiblePlayerId
            if bypassFeature.GetPlayerIndex then
                resolvedIndex = bypassFeature:GetPlayerIndex()
            elseif bypassFeature.GetArrayIndex then
                resolvedIndex = bypassFeature:GetArrayIndex()
            end
            local placed = false
            for _, hostKickName in ipairs(startup.host_kick_bypass.host_kick_names or { "Host Kick" }) do
                local hostKickFeature = startup.get_player_feature_by_name_safe(hostKickName, resolvedIndex)
                if hostKickFeature then
                    placed = startup.attach_render_after_once(hostKickFeature, bypassFeature)
                    if placed then break end
                end
            end
            if not placed then
                startup.host_kick_bypass.log("Host Kick Bypass created, but Host Kick placement anchor was not found for player index " .. tostring(resolvedIndex))
            end
        end
    end
end

function startup.cleanup_custom_player_features()
    if startup.nuke_join_kick and startup.nuke_join_kick.cleanup_player_feature then
        startup.nuke_join_kick.cleanup_player_feature()
    end
    if startup.host_kick_bypass and startup.host_kick_bypass.cleanup_old_feature then
        startup.host_kick_bypass.cleanup_old_feature()
    end
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- feature registration
-- note: creates the saved startup controls used by the clickgui tabs.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.add_button(key, name, desc, callback)
    startup.h[key] = startup.hash(key)
    return FeatureMgr.AddFeature(startup.h[key], name, eFeatureType.Button, desc, callback)
end

function startup.add_toggle(key, name, desc, callback, defaultValue)
    startup.h[key] = startup.hash(key)
    local feature = FeatureMgr.AddFeature(startup.h[key], name, eFeatureType.Toggle, desc, callback)
    if feature and feature.SetDefaultValue then
        feature:SetDefaultValue(defaultValue == true):Reset()
    elseif feature then
        feature:SetBoolValue(defaultValue == true)
    end
    return feature
end

function startup.add_combo(key, name, desc, items, selectedValue, callback)
    startup.h[key] = startup.hash(key)
    local list = items or {}
    local feature = FeatureMgr.AddFeature(startup.h[key], name, eFeatureType.Combo, desc, function(f)
        local index = f and f.GetListIndex and f:GetListIndex() or 0
        local selected = list[(tonumber(index) or 0) + 1] or list[1]
        if callback then callback(selected, tonumber(index) or 0, f) end
    end)
    if feature then
        if feature.SetList then feature:SetList(list) end
        local wanted = tostring(selectedValue or list[1] or "")
        for index, label in ipairs(list) do
            if tostring(label) == wanted then
                if feature.SetListIndex then feature:SetListIndex(index - 1) end
                break
            end
        end
        if feature.SetSaveable then feature:SetSaveable(false) end
    end
    return feature
end

function startup.add_input_text(key, name, desc, value, max_value, callback)
    startup.h[key] = startup.hash(key)
    local feature = FeatureMgr.AddFeature(startup.h[key], name, eFeatureType.InputText, desc, function(f)
        local next_value = value
        if f and f.GetStringValue then next_value = f:GetStringValue() end
        if callback then callback(tostring(next_value or ""), f) end
    end)
    if feature then
        if feature.SetMaxValue then feature:SetMaxValue(tonumber(max_value or 300) or 300) end
        if feature.SetStringValue then feature:SetStringValue(tostring(value or "")) end
        if feature.SetSaveable then feature:SetSaveable(false) end
    end
    return feature
end

function startup.add_int_slider(key, name, desc, value, minValue, maxValue, stepSize, callback)
    startup.h[key] = startup.hash(key)
    local feature = FeatureMgr.AddFeature(startup.h[key], name, eFeatureType.SliderInt, desc, function(f)
        local nextValue = value
        if f and f.GetIntValue then
            nextValue = f:GetIntValue()
        elseif f and f.GetFloatValue then
            nextValue = math.floor(f:GetFloatValue())
        end
        nextValue = startup.clamp_int(nextValue, minValue, maxValue)
        if callback then
            callback(nextValue, f)
        end
    end)
    if feature then
        if feature.SetLimitValues then feature:SetLimitValues(minValue, maxValue) end
        if feature.SetStepSize then feature:SetStepSize(stepSize or 1) end
        if feature.SetFastStepSize then feature:SetFastStepSize((stepSize or 1) * 5) end
        if feature.SetIntValue then feature:SetIntValue(startup.clamp_int(value, minValue, maxValue)) end
        if feature.SetSaveable then feature:SetSaveable(false) end
    end
    return feature
end

function startup.add_float_slider(key, name, desc, value, minValue, maxValue, stepSize, format, callback)
    startup.h[key] = startup.hash(key)
    local feature = FeatureMgr.AddFeature(startup.h[key], name, eFeatureType.SliderFloat, desc, function(f)
        local nextValue = value
        if f and f.GetFloatValue then
            nextValue = f:GetFloatValue()
        elseif f and f.GetIntValue then
            nextValue = f:GetIntValue()
        end
        nextValue = startup.clamp_float(nextValue, minValue, maxValue)
        if callback then
            callback(nextValue, f)
        end
    end)
    if feature then
        if feature.SetLimitValues then feature:SetLimitValues(minValue, maxValue) end
        if feature.SetStepSize then feature:SetStepSize(stepSize or 0.01) end
        if feature.SetFastStepSize then feature:SetFastStepSize((stepSize or 0.01) * 5) end
        if feature.SetFormat and format then feature:SetFormat(format) end
        if feature.SetFloatValue then feature:SetFloatValue(startup.clamp_float(value, minValue, maxValue)) end
        if feature.SetSaveable then feature:SetSaveable(false) end
    end
    return feature
end

