end, startup.s.autoLoadSettings)
local auto_load_theme_toggle = startup.add_toggle("AutoLoadTheme", "Auto-Load Theme", "Automatically loads a theme on startup. OFF by default for stability; enable only after confirming the selected theme loads correctly.", function(f)
    startup.s.autoLoadTheme = f:IsToggled()
    if startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
end, startup.s.autoLoadTheme)
if auto_load_theme_toggle and auto_load_theme_toggle.SetSaveable then
    -- Startup owns this preference in its own config. Prevent Cherax from restoring
    -- an older saved FeatureMgr toggle over the v1.0.7 Alpha stability default.
    auto_load_theme_toggle:SetSaveable(false)
end
local random_theme_toggle = startup.add_toggle("RandomThemeOnStartup", "Random Theme On Startup", "Picks a random enabled theme when a theme load is requested. OFF by default for stability.", function(f)
    startup.s.randomThemeOnStartup = f:IsToggled()
    if startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
end, startup.s.randomThemeOnStartup)
if random_theme_toggle and random_theme_toggle.SetSaveable then
    random_theme_toggle:SetSaveable(false)
end
startup.add_toggle("AutoSelectSessionType", "Auto-Select Session Type", "Automatically selects the correct public-session option.", function(f)
    startup.s.autoSelectSessionType = f:IsToggled()
    if startup.s.initialized then startup.save_config(false) end
end, startup.s.autoSelectSessionType)
startup.add_combo(
    "SessionRoutingMode",
    "Session Routing",
    "Automatic uses Cherax.GetEdition() as the source of truth: LE/EE use New Public Session. LE BE/EE BE use New Public Session while Prime: Host Public Sessions is ON, or Join Public Session when it is OFF. Manual routing modes still override edition detection.",
    { "Automatic", "Standard / Premium", "Prime" },
    startup.s.sessionRoutingMode,
    function(selected)
        startup.s.sessionRoutingMode = tostring(selected or "Automatic")
        if startup.s.initialized then
            startup.resolve_session_type()
            startup.save_config(false)
        end
    end
)
local prime_host_sessions_toggle = startup.add_toggle(
    "PrimeHostSessionsEnabled",
    "Prime: Host Public Sessions",
    "ON by default. Prime keeps New Public Session for normal Startup hosting and when returning from diagnostics instead of automatically switching back to Join Public Session. Turn this OFF if you want Startup to use Prime Join Public Session routing.",
    function(f)
        startup.s.primeHostSessionsEnabled = f:IsToggled()
        if startup.s.initialized then
            startup.resolve_session_type()
            startup.save_config(false)
        end
    end,
    startup.s.primeHostSessionsEnabled ~= false
)
if prime_host_sessions_toggle and prime_host_sessions_toggle.SetSaveable then
    -- Startup owns this preference so Cherax cannot overwrite it with an older feature state.
    prime_host_sessions_toggle:SetSaveable(false)
end
startup.add_toggle("CompactPinnedStartupTab", "Compact Pinned Startup Tab", "Uses the compact S tab label on next Startup.lua reload. Startup registers before delayed Lua scripts, keeping it leftmost among Lua-added tabs.", function(f)
    startup.s.compactPinnedTabEnabled = f:IsToggled()
    if startup.s.initialized then
        startup.save_config(false)
        startup.toast_quiet("Startup tab preference saved. Reload Startup.lua to apply the tab label and position.", 4500)
    end
end, startup.s.compactPinnedTabEnabled)

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 179: Super Advertise — dump-researched, adaptive 100-profile diagnostic
--
-- Research-backed surfaces:
--   * Cherax Advertise Session (Legacy + Enhanced)
--   * Legacy Cherax Advertise Count (real values 5 / 10)
--   * Enhanced Cherax Advertise Region (8 exposed regions)
--   * GTA session visibility, join-request acceptance, and host-only public slot refresh
--   * Read-only matchmaking-group capacity snapshots and player-growth observation
--
-- Legacy dump evidence includes MMATTR_REGION and PARAM_netMatchMakingForceRegion, but
-- Build 179 deliberately does not perform a raw Legacy region memory write. A static IDA
-- address is not a safe runtime contract: ASLR, game updates, parameter layout, value
-- encoding, and write side effects must all be validated reversibly first.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.s.superAdvertiseEnabled = startup.s.superAdvertiseEnabled == true
startup.s.superAdvertiseRunning = false
startup.s.superAdvertiseMethod = tonumber(startup.s.superAdvertiseMethod or 0) or 0
startup.s.superAdvertiseStatus = tostring(startup.s.superAdvertiseStatus or "Idle")
startup.s.superAdvertiseReportPath = tostring(startup.s.superAdvertiseReportPath or "")
startup.s.superAdvertiseTargetPlayers = 30
startup.s.superAdvertiseSerial = tonumber(startup.s.superAdvertiseSerial or 0) or 0
startup.s.superAdvertiseBestMethod = tonumber(startup.s.superAdvertiseBestMethod or 0) or 0
startup.s.superAdvertiseBestDelta = tonumber(startup.s.superAdvertiseBestDelta or 0) or 0
startup.s.superAdvertiseBestRegion = tostring(startup.s.superAdvertiseBestRegion or "")
startup.s.superAdvertiseLoop = tonumber(startup.s.superAdvertiseLoop or 0) or 0

startup.super_advertise_regions = {
    "USA East", "USA West", "Europe", "South America",
    "Asia", "Northern Asia", "Japan", "Australia"
}

startup.super_advertise_native = {
    NETWORK_SESSION_MARK_VISIBLE = 0x271CC6AB59EBF9A5,
    NETWORK_SESSION_IS_VISIBLE = 0xBA416D68C631496A,
    NETWORK_SESSION_BLOCK_JOIN_REQUESTS = 0xA73667484D7037C3,
    NETWORK_SESSION_CHANGE_SLOTS = 0xB4AB419E0D86ACAE,
    NETWORK_SESSION_GET_MATCHMAKING_GROUP_FREE = 0x56CE820830EF040B
}

startup.super_advertise_profile_names = {
    "Visible Baseline",
    "Advertise Reassert",
    "Feature Synchronize",
    "Host Slot Refresh",
    "Join Gate Refresh",
    "Edition Edge Pulse",
    "Resolver Refresh",
    "Extended Growth Window",
    "Double Advertise Reassert",
    "Full Visibility Bundle"
}

function startup.super_advertise_report_path()
    local stamp = os.date("%Y%m%d_%H%M%S")
    return tostring(startup.diagnostics_dir or startup.storage_dir or ".")
        .. "\\Super_Advertise_Loop_Build336_" .. stamp .. ".txt"
end

function startup.super_advertise_append(path, line)
    local f = io and io.open and io.open(path, "a") or nil
    if not f then return false end
    f:write(tostring(line or ""), "\n")
    f:close()
    return true
end

function startup.super_advertise_native_void(hash, ...)
    if not Natives or not Natives.InvokeVoid then return false, "InvokeVoid unavailable" end
    local ok, err = direct_call(Natives.InvokeVoid, hash, ...)
    return ok == true, ok and "ok" or tostring(err)
end

function startup.super_advertise_native_bool(hash, ...)
    if not Natives or not Natives.InvokeBool then return false, "InvokeBool unavailable" end
    local ok, value = direct_call(Natives.InvokeBool, hash, ...)
    if not ok then return false, tostring(value) end
    return value == true, "ok"
end

function startup.super_advertise_native_int(hash, ...)
    if not Natives or not Natives.InvokeInt then return nil, "InvokeInt unavailable" end
    local ok, value = direct_call(Natives.InvokeInt, hash, ...)
    if not ok then return nil, tostring(value) end
    return tonumber(value), "ok"
end

function startup.super_advertise_is_local_host()
    local _, hostId = startup.get_session_host_name()
    hostId = tonumber(hostId or -1) or -1
    for _, localId in ipairs(startup.get_local_player_id_candidates()) do
        if tonumber(localId) == hostId then return true, hostId end
    end
    return false, hostId
end

function startup.super_advertise_capacity_snapshot()
    local values = {}
    for groupId = 0, 4 do
        local value, status = startup.super_advertise_native_int(
            startup.super_advertise_native.NETWORK_SESSION_GET_MATCHMAKING_GROUP_FREE,
            groupId
        )
        values[#values + 1] = tostring(groupId) .. "=" .. (value ~= nil and tostring(value) or ("err:" .. tostring(status)))
    end
    return table.concat(values, ",")
end

function startup.super_advertise_prepare_session(refreshSlots)
    local actions = {}
    local okVisible, visibleStatus = startup.super_advertise_native_void(
        startup.super_advertise_native.NETWORK_SESSION_MARK_VISIBLE, true
    )
    actions[#actions + 1] = "visible=" .. (okVisible and "set" or ("error:" .. tostring(visibleStatus)))

    local okJoin, joinStatus = startup.super_advertise_native_void(
        startup.super_advertise_native.NETWORK_SESSION_BLOCK_JOIN_REQUESTS, false
    )
    actions[#actions + 1] = "joinRequests=" .. (okJoin and "open" or ("error:" .. tostring(joinStatus)))

    local isHost = startup.super_advertise_is_local_host()
    if refreshSlots and isHost then
        local okSlots, slotStatus = startup.super_advertise_native_void(
            startup.super_advertise_native.NETWORK_SESSION_CHANGE_SLOTS, 30, false
        )
        actions[#actions + 1] = "slots=" .. (okSlots and "30" or ("error:" .. tostring(slotStatus)))
    elseif refreshSlots then
        actions[#actions + 1] = "slots=skipped-not-host"
    end
    return table.concat(actions, ";"), isHost
end

function startup.super_advertise_build_method(method)
    method = math.max(1, math.min(100, tonumber(method or 1) or 1))
    local cycle = math.floor((method - 1) / 10) + 1
    local profile = ((method - 1) % 10) + 1
    local regionIndex = ((cycle - 1) % #startup.super_advertise_regions) + 1
    local waitMs = 4500 + (((cycle + profile - 2) % 5) * 1000)
    if profile == 8 then waitMs = waitMs + 3000 end
    return {
        method = method,
        cycle = cycle,
        profile = profile,
        profileName = startup.super_advertise_profile_names[profile] or ("Profile " .. tostring(profile)),
        region = startup.super_advertise_regions[regionIndex],
        waitMs = waitMs,
        refreshSlots = profile == 4 or profile == 10,
        reassert = profile == 2 or profile == 9 or profile == 10,
        synchronize = profile == 3 or profile == 10,
        resolve = profile == 7,
        edgePulse = profile == 6,
        extended = profile == 8
    }
end

function startup.stop_super_advertise(reason)
    local wasActive = startup.s.superAdvertiseEnabled == true or startup.s.superAdvertiseRunning == true
    startup.s.superAdvertiseEnabled = false
    startup.s.superAdvertiseRunning = false
    startup.s.superAdvertiseSerial = (tonumber(startup.s.superAdvertiseSerial or 0) or 0) + 1
    startup.s.superAdvertiseStatus = "Stopped" .. (reason and (": " .. tostring(reason)) or "")
    if wasActive and startup.s.advertiseBenchmarkActive == true and tostring(startup.s.advertiseBenchmarkMode or "") == "SUPER" and startup.advertise_benchmark_finalize then
        startup.advertise_benchmark_finalize("STOPPED", tostring(reason or "Super Advertise stopped"), true)
    end
    if wasActive and startup.advertise_research_log then startup.advertise_research_log("SUPER", "STOPPED", "reason=" .. tostring(reason or "requested") .. " players=" .. tostring(startup.get_session_player_count())) end
    startup.set_feature_bool_silently(startup.h.SuperAdvertise, false)
    if startup.s.initialized then startup.save_config(false) end
end

function startup.run_super_advertise()
    if startup.s.superAdvertiseRunning then return false end
    startup.s.superAdvertiseRunning = true
    if startup.advertise_benchmark_start then startup.advertise_benchmark_start("SUPER", "Super Advertise toggle enabled") end
    startup.s.superAdvertiseSerial = (tonumber(startup.s.superAdvertiseSerial or 0) or 0) + 1
    local serial = startup.s.superAdvertiseSerial
    local path = startup.super_advertise_report_path()
    startup.s.superAdvertiseReportPath = path
    startup.s.superAdvertiseBestMethod = 0
    startup.s.superAdvertiseBestDelta = -999
    startup.s.superAdvertiseBestRegion = ""
    startup.s.superAdvertiseLoop = 0

    startup.super_advertise_append(path, "Startup Super Advertise — Build 336 Continuous 100-Profile Loop")
    startup.super_advertise_append(path, "Research base: Build 182 / Build 179 dump-researched profiles")
    startup.super_advertise_append(path, "Edition: " .. tostring(startup.get_active_edition and startup.get_active_edition() or "Unknown"))
    startup.super_advertise_append(path, "Started: " .. os.date("%Y-%m-%d %H:%M:%S"))
    startup.super_advertise_append(path, "Target: " .. tostring(startup.s.superAdvertiseTargetPlayers or 30) .. " players")
    startup.super_advertise_append(path, "Loop mode: methods 1-100 repeat until Super Advertise is manually turned OFF")
    startup.super_advertise_append(path, "Full-lobby behavior: pause profile changes at target population; keep Advertise Session ON; resume when population drops")
    startup.super_advertise_append(path, "Safety: verified Cherax controls + stable GTA session natives; no raw dump writes")
    startup.super_advertise_append(path, "Legacy dump: MMATTR_REGION + PARAM_netMatchMakingForceRegion confirmed internally; automatic raw region write disabled")
    startup.super_advertise_append(path, "Enhanced dump: MMATTR_REGION + advertising/visibility/slot/join-request schema strings confirmed")
    startup.super_advertise_append(path, "Interpretation: 100 parameter profiles across a smaller set of defensible mechanisms")
    startup.super_advertise_append(path, "")

    local job = function()
        startup.advertise_research_log("SUPER", "START", "players=" .. tostring(startup.get_session_player_count()) .. " target=" .. tostring(startup.s.superAdvertiseTargetPlayers or 30) .. " report=" .. tostring(path))
        startup.request_advertise_session_sync(true, "Super Advertise Build 336 start")
        startup.set_advertise_session(true, true)
        startup.super_advertise_prepare_session(true)
        if startup.advertise_benchmark_mark_active then startup.advertise_benchmark_mark_active("SUPER") end

        local initialPlayers = startup.get_session_player_count()
        local bestPlayers = initialPlayers
        local target = math.max(1, math.min(30, tonumber(startup.s.superAdvertiseTargetPlayers or 30) or 30))
        local positiveMethods = 0
        local totalNetGrowth = 0
        local bestRegionScores = {}
        local lastRegion = ""
        local loopNumber = 0
        local targetRecorded = false

        while serial == startup.s.superAdvertiseSerial and startup.s.superAdvertiseEnabled == true do
            loopNumber = loopNumber + 1
            startup.s.superAdvertiseLoop = loopNumber
            startup.super_advertise_append(path, string.format("===== LOOP %03d START | %s =====", loopNumber, os.date("%Y-%m-%d %H:%M:%S")))

            for method = 1, 100 do
                if serial ~= startup.s.superAdvertiseSerial or startup.s.superAdvertiseEnabled ~= true then break end

                -- Build 336: a full lobby is success, not a reason to turn Super Advertise OFF.
                -- Hold the winning advertising state without continuously mutating region/count/slots.
                while serial == startup.s.superAdvertiseSerial
                    and startup.s.superAdvertiseEnabled == true
                    and startup.get_session_player_count() >= target do
                    local fullPlayers = startup.get_session_player_count()
                    startup.s.superAdvertiseStatus = string.format(
                        "Full lobby hold | loop %d | %d/%d players | resumes below target",
                        loopNumber, fullPlayers, target
                    )
                    startup.set_advertise_session(true, true)
                    if not targetRecorded then
                        targetRecorded = true
                        startup.super_advertise_append(path, string.format("TARGET HOLD: %d/%d players | loop=%d nextMethod=%d", fullPlayers, target, loopNumber, method))
                        if startup.s.advertiseBenchmarkActive == true
                            and tostring(startup.s.advertiseBenchmarkMode or "") == "SUPER"
                            and startup.advertise_benchmark_finalize then
                            startup.advertise_benchmark_finalize("REACHED_30", "Super Advertise reached 30 and entered continuous hold")
                        end
                    end
                    startup.yield(5000)
                end

                if serial ~= startup.s.superAdvertiseSerial or startup.s.superAdvertiseEnabled ~= true then break end
                if targetRecorded and startup.get_session_player_count() < target then
                    startup.super_advertise_append(path, string.format("TARGET RESUME: population=%d/%d | loop=%d method=%d", startup.get_session_player_count(), target, loopNumber, method))
                    targetRecorded = false
                end

                local cfg = startup.super_advertise_build_method(method)
                startup.s.superAdvertiseMethod = method
                local before = startup.get_session_player_count()
                local startedAt = startup.now()
                local actions = {}

                local prepActions, isHost = startup.super_advertise_prepare_session(cfg.refreshSlots)
                actions[#actions + 1] = prepActions

                if startup.is_enhanced_active_edition() then
                    if cfg.profile == 1 or lastRegion == "" then
                        local okRegion = startup.set_advertise_region_by_name(cfg.region, false)
                        lastRegion = cfg.region
                        actions[#actions + 1] = "region=" .. cfg.region .. ":" .. tostring(okRegion == true)
                        startup.yield(750)
                    else
                        actions[#actions + 1] = "region-hold=" .. tostring(lastRegion)
                    end
                    if cfg.resolve then
                        startup.request_advertise_region_resolution(true, "Super Advertise Build 336 method " .. tostring(method))
                        actions[#actions + 1] = "region-resolver=queued"
                    end
                else
                    if cfg.profile == 1 then
                        startup.apply_advertise_count(startup.s.advertiseHighCount or 10, "Super Advertise cycle baseline")
                        actions[#actions + 1] = "count=10"
                    elseif cfg.edgePulse then
                        startup.apply_advertise_count(startup.s.advertiseLowCount or 5, "Super Advertise edge pulse")
                        startup.yield(850)
                        startup.apply_advertise_count(startup.s.advertiseHighCount or 10, "Super Advertise edge restore")
                        actions[#actions + 1] = "count-pulse=5>10"
                    else
                        actions[#actions + 1] = "count-hold=" .. tostring(startup.s.advertiseCurrentCount or 10)
                    end
                end

                if cfg.reassert then
                    startup.set_advertise_session(true, true)
                    actions[#actions + 1] = "advertise=reasserted"
                    if cfg.profile == 9 then
                        startup.yield(500)
                        startup.set_advertise_session(true, true)
                        actions[#actions + 1] = "advertise=double"
                    end
                end
                if cfg.synchronize then
                    startup.request_advertise_session_sync(true, "Super Advertise Build 336 method " .. tostring(method))
                    actions[#actions + 1] = "feature-sync=queued"
                end
                if cfg.extended then actions[#actions + 1] = "observation=extended" end

                local visibleBefore = startup.super_advertise_native_bool(
                    startup.super_advertise_native.NETWORK_SESSION_IS_VISIBLE
                )
                local capacityBefore = startup.super_advertise_capacity_snapshot()
                startup.s.superAdvertiseStatus = string.format(
                    "Loop %d | Method %d/100 | %s | %d/%d players",
                    loopNumber, method, cfg.profileName, before, target
                )

                startup.yield(cfg.waitMs)
                local after = startup.get_session_player_count()
                local elapsed = math.max(0, startup.now() - startedAt)
                local delta = after - before
                local visibleAfter = startup.super_advertise_native_bool(
                    startup.super_advertise_native.NETWORK_SESSION_IS_VISIBLE
                )
                local capacityAfter = startup.super_advertise_capacity_snapshot()
                local activeRegion = startup.is_enhanced_active_edition()
                    and tostring(startup.get_advertise_region_label and startup.get_advertise_region_label(false) or lastRegion)
                    or "Legacy-internal-region-unwritten"

                local previousBestPlayers = bestPlayers
                if after > bestPlayers then bestPlayers = after end
                if delta > 0 then positiveMethods = positiveMethods + 1 end
                totalNetGrowth = totalNetGrowth + delta
                if startup.is_enhanced_active_edition() then
                    bestRegionScores[lastRegion] = (bestRegionScores[lastRegion] or 0) + delta
                end

                local beatsBest = delta > (tonumber(startup.s.superAdvertiseBestDelta or -999) or -999)
                    or (delta == (tonumber(startup.s.superAdvertiseBestDelta or -999) or -999) and after > previousBestPlayers)
                if beatsBest then
                    startup.s.superAdvertiseBestMethod = method
                    startup.s.superAdvertiseBestDelta = delta
                    startup.s.superAdvertiseBestRegion = startup.is_enhanced_active_edition() and lastRegion or "Legacy"
                end

                startup.super_advertise_append(path, string.format(
                    "loop=%03d %03d/100 | cycle=%02d profile=%02d %-25s | players %02d>%02d delta=%+d | wait=%dms | host=%s | visible=%s>%s | region=%s | count=%s | capacity=%s>%s | actions=%s",
                    loopNumber, method, cfg.cycle, cfg.profile, cfg.profileName,
                    before, after, delta, elapsed,
                    isHost and "local" or "remote",
                    visibleBefore and "1" or "0", visibleAfter and "1" or "0",
                    activeRegion,
                    tostring(startup.s.advertiseCurrentCount or "n/a"),
                    capacityBefore, capacityAfter,
                    table.concat(actions, ";")
                ))
                startup.advertise_research_log(
                    "SUPER", "METHOD",
                    "loop=" .. tostring(loopNumber) ..
                    " method=" .. tostring(method) .. "/100" ..
                    " profile=" .. tostring(cfg.profileName) ..
                    " players=" .. tostring(before) .. ">" .. tostring(after) ..
                    " delta=" .. string.format("%+d", delta) ..
                    " waitMs=" .. tostring(elapsed) ..
                    " host=" .. (isHost and "local" or "remote") ..
                    " region=" .. tostring(activeRegion) ..
                    " count=" .. tostring(startup.s.advertiseCurrentCount or "n/a"))

                if after >= target then
                    startup.s.superAdvertiseStatus = string.format("Target reached | loop %d method %d | %d/%d players", loopNumber, method, after, target)
                    startup.super_advertise_append(path, "SUCCESS: target reached at loop " .. tostring(loopNumber) .. " method " .. tostring(method))
                    if not targetRecorded
                        and startup.s.advertiseBenchmarkActive == true
                        and tostring(startup.s.advertiseBenchmarkMode or "") == "SUPER"
                        and startup.advertise_benchmark_finalize then
                        startup.advertise_benchmark_finalize("REACHED_30", "Super Advertise reached 30 at loop " .. tostring(loopNumber) .. " method " .. tostring(method))
                    end
                    targetRecorded = true
                end
                startup.yield(750)
            end

            if serial ~= startup.s.superAdvertiseSerial or startup.s.superAdvertiseEnabled ~= true then break end

            -- Apply the strongest supported result at each 100-profile boundary, then loop.
            if startup.is_enhanced_active_edition() then
                local bestRegion, bestScore = "", -999
                for region, score in pairs(bestRegionScores) do
                    if score > bestScore then bestRegion, bestScore = region, score end
                end
                if bestRegion ~= "" then
                    startup.set_advertise_region_by_name(bestRegion, false)
                    startup.s.superAdvertiseBestRegion = bestRegion
                end
            else
                startup.apply_advertise_count(startup.s.advertiseHighCount or 10, "Super Advertise loop boundary high count")
            end
            startup.set_advertise_session(true, true)
            startup.super_advertise_prepare_session(true)

            startup.super_advertise_append(path, string.format("===== LOOP %03d COMPLETE | bestPlayers=%d | positiveProfiles=%d | netGrowth=%+d | bestMethod=%d | bestDelta=%+d | bestRegion=%s =====",
                loopNumber,
                bestPlayers,
                positiveMethods,
                totalNetGrowth,
                tonumber(startup.s.superAdvertiseBestMethod or 0) or 0,
                tonumber(startup.s.superAdvertiseBestDelta or 0) or 0,
                tostring(startup.s.superAdvertiseBestRegion or "Legacy")
            ))
            startup.super_advertise_append(path, "Restarting at method 1/100 while Super Advertise remains ON.")
            startup.super_advertise_append(path, "")
            startup.s.superAdvertiseStatus = string.format("Loop %d complete | restarting at 1/100", loopNumber)
            startup.yield(1500)
        end

        -- Manual toggle-off is the authoritative stop. Do not auto-disable the toggle here.
        startup.s.superAdvertiseRunning = false
        startup.super_advertise_append(path, "Stopped: " .. os.date("%Y-%m-%d %H:%M:%S") .. " | loops=" .. tostring(loopNumber) .. " | players=" .. tostring(startup.get_session_player_count()))
        startup.super_advertise_append(path, "Advertise Session intentionally left ON after Super Advertise stop.")
        startup.set_advertise_session(true, true)
        if startup.s.initialized then startup.save_config(false) end
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
    return true
end

startup.add_toggle("AdvertiseBenchmarkTimer", "30-Player Benchmark Timer", "Production default: OFF. Enable only when you intentionally want to time Current, Old v1.0.3, or Super Advertise runs to 30 players. Results persist in config and CSV.", function(f)
    startup.s.advertiseBenchmarkEnabled = f:IsToggled()
    if startup.s.initialized and not startup.s.syncingFeatureStates then
        if startup.s.advertiseBenchmarkEnabled == false and startup.s.advertiseBenchmarkActive == true and startup.advertise_benchmark_finalize then
            startup.advertise_benchmark_finalize("TIMER_DISABLED", "30-Player Benchmark Timer toggled off", true)
        end
        startup.save_config(false)
    end
end, startup.s.advertiseBenchmarkEnabled == true)

startup.add_toggle("SuperAdvertise", "Super Advertise (Beta-May Cause Crash)", "Continuously loops the 100-profile Legacy/Enhanced Super Advertise sequence while this toggle stays ON. At 30 players it pauses profile changes and keeps advertising active; if population drops below 30 it resumes, and after 100/100 it restarts at 1/100. Cherax console milestones are muted; detailed profile results remain saved under Startup\\Diagnostics. No blind dump-address writes.", function(f)
    if startup.s.syncingFeatureStates then return end
    startup.s.superAdvertiseEnabled = f:IsToggled()
    if startup.s.superAdvertiseEnabled then
        startup.s.autoAdvertiseSession = false
        startup.s.oldStartupAdvertiseEnabled = false
        startup.stop_old_startup_advertise("Super Advertise enabled", false)
        startup.s.advertiseFlowSerial = (tonumber(startup.s.advertiseFlowSerial or 0) or 0) + 1
        startup.s.advertiseRunning = false
        startup.set_feature_bool_silently(startup.h.AutoAdvertiseSession, false)
        startup.set_feature_bool_silently(startup.h.OldStartupAdvertise, false)
        startup.run_super_advertise()
    else
        startup.stop_super_advertise("toggle off")
    end
    if startup.s.initialized then startup.save_config(false) end
end, startup.s.superAdvertiseEnabled)

startup.add_toggle("OldStartupAdvertise", "Old Startup Advertising Method (v1.0.3)", "Legacy-only compatibility mode. Restores v1.0.3's direct Cherax Advertise Session + Advertise Count writes: two-minute wait, direct count 5, count 10 below 25 players, count 5 at 30+, and the original five-minute fallback. Mutually exclusive with Current Auto Advertise and Super Advertise. Logs milestones to Cherax.log.", function(f)
    if startup.s.syncingFeatureStates then return end
    local enabled = f:IsToggled()
    if enabled and startup.is_enhanced_active_edition() then
        startup.s.oldStartupAdvertiseEnabled = false
        startup.set_feature_bool_silently(startup.h.OldStartupAdvertise, false)
        startup.toast("Old Startup Advertising Method is Legacy-only.", 5000)
        return
    end
    startup.s.oldStartupAdvertiseEnabled = enabled
    if enabled then
        startup.s.autoAdvertiseSession = false
        startup.s.superAdvertiseEnabled = false
        startup.s.advertiseFlowSerial = (tonumber(startup.s.advertiseFlowSerial or 0) or 0) + 1
        startup.s.advertiseRunning = false
        if startup.stop_super_advertise then startup.stop_super_advertise("Old v1.0.3 method enabled") end
        startup.set_feature_bool_silently(startup.h.AutoAdvertiseSession, false)
        startup.set_feature_bool_silently(startup.h.SuperAdvertise, false)
        startup.run_old_startup_advertise("toggle enabled in current session")
    else
        startup.stop_old_startup_advertise("toggle off", true)
    end
    if startup.s.initialized then startup.save_config(false) end
end, startup.s.oldStartupAdvertiseEnabled)

startup.add_toggle("AutoAdvertiseSession", "Auto Advertise Session", "Production default: ON. Current Cherax uses only the Advertise Session toggle; Build 368 retires all Advertise Count writes. Advertise Region is selected separately below.", function(f)
    startup.s.autoAdvertiseSession = f:IsToggled()
    if startup.s.initialized and not startup.s.syncingFeatureStates then
        startup.s.autoAdvertiseUserConfigured = true
        if startup.s.autoAdvertiseSession then
            startup.s.oldStartupAdvertiseEnabled = false
            startup.s.superAdvertiseEnabled = false
            startup.stop_old_startup_advertise("Current Auto Advertise enabled", false)
            if startup.stop_super_advertise then startup.stop_super_advertise("Current Auto Advertise enabled") end
            startup.set_feature_bool_silently(startup.h.OldStartupAdvertise, false)
            startup.set_feature_bool_silently(startup.h.SuperAdvertise, false)
        else
            if startup.s.advertiseBenchmarkActive == true and tostring(startup.s.advertiseBenchmarkMode or "") == "CURRENT" and startup.advertise_benchmark_finalize then
                startup.advertise_benchmark_finalize("TOGGLE_OFF", "Current Auto Advertise toggled off", true)
            end
            startup.s.advertiseFlowSerial = (tonumber(startup.s.advertiseFlowSerial or 0) or 0) + 1
            startup.s.advertiseRunning = false
            startup.s.advertiseSmartActive = false
            startup.s.advertiseStopRequested = true
        end
        startup.request_advertise_session_sync(startup.s.autoAdvertiseSession, "Startup Auto Advertise Session changed")
        startup.advertise_research_log("CURRENT", "TOGGLE", "enabled=" .. tostring(startup.s.autoAdvertiseSession))
        startup.save_config(false)
    end
end, startup.s.autoAdvertiseSession)
