local prime_minimum_players_toggle = startup.add_toggle("PrimeMinimumPlayersEnabled", "Only Accept 20+ Initial-Player Lobbies", "Prime only. ON by default. Waits 15-30 seconds after joining, then hops if the initial lobby has fewer than the selected minimum. It never leaves later if the lobby falls below the minimum.", function(f)
    startup.s.primeMinimumPlayersEnabled = f:IsToggled()
    if startup.s.initialized and not startup.s.syncingFeatureStates then
        if not startup.s.primeMinimumPlayersEnabled then startup.lobby_filter.cancel("Prime initial-player filter disabled") end
        startup.save_config(false)
    end
end, startup.s.primeMinimumPlayersEnabled)
if prime_minimum_players_toggle and prime_minimum_players_toggle.SetSaveable then prime_minimum_players_toggle:SetSaveable(false) end
startup.add_int_slider("PrimeMinimumPlayersThreshold", "Minimum Initial Players", "Prime initial-lobby requirement. Default: 20.", startup.s.primeMinimumPlayersThreshold, 10, 30, 1, function(value)
    startup.s.primeMinimumPlayersThreshold = startup.clamp_int(value or 20, 10, 30)
    if startup.s.initialized then startup.save_config(false) end
end)

-- ===============================================================================
-- protection control lab
-- note: cooperative local-state capture only; no remote probes or hostile events.
-- ===============================================================================

startup.protection_control = startup.protection_control or {
    active = false,
    startedAt = 0,
    deadline = 0,
    durationMs = 90000,
    events = {},
    profile = nil,
    jobQueued = false,
    reportSerial = 0,
}

startup.s.protectionControlStatus = tostring(startup.s.protectionControlStatus or "Not run")
startup.s.protectionControlLastReportPath = tostring(startup.s.protectionControlLastReportPath or "")
startup.s.protectionControlLastCandidateCount = tonumber(startup.s.protectionControlLastCandidateCount or 0) or 0
startup.s.protectionControlLastEnabledCount = tonumber(startup.s.protectionControlLastEnabledCount or 0) or 0
startup.s.protectionControlLastReactionCount = tonumber(startup.s.protectionControlLastReactionCount or 0) or 0

function startup.protection_control.safe_feature_call(feature, methodName, ...)
    if feature == nil then return nil end
    local method = feature[methodName]
    if type(method) ~= "function" then return nil end
    local args = { ... }
    local ok, a, b, c, d = direct_call(function()
        return method(feature, table.unpack(args))
    end)
    if not ok then return nil end
    if b ~= nil or c ~= nil or d ~= nil then return { a, b, c, d } end
    return a
end

function startup.protection_control.feature_name(feature)
    local name = startup.protection_control.safe_feature_call(feature, "GetName", false)
    if name == nil or tostring(name) == "" then name = feature and feature.Name or "" end
    return tostring(name or "")
end

function startup.protection_control.feature_desc(feature)
    local desc = startup.protection_control.safe_feature_call(feature, "GetDesc", false)
    if desc == nil or tostring(desc) == "" then desc = feature and feature.Desc or "" end
    return tostring(desc or "")
end

function startup.protection_control.matches_candidate(name, desc)
    local haystack = (tostring(name or "") .. " " .. tostring(desc or "")):lower()
    local strong = {
        "protection", "reaction", "kick", "crash", "report", "telemetry",
        "bad script event", "script event", "chat spam", "banned word",
        "spectating", "aiming at", "shooting at", "sync crash", "ptfx",
        "particle", "clone", "cage", "freeze", "ragdoll", "transaction error",
        "block reports", "block kick", "block crash", "block script"
    }
    for _, token in ipairs(strong) do
        if haystack:find(token, 1, true) then return true, token end
    end
    return false, ""
end

function startup.protection_control.snapshot_feature(feature)
    local name = startup.protection_control.feature_name(feature)
    local desc = startup.protection_control.feature_desc(feature)
    local isCandidate, matchedToken = startup.protection_control.matches_candidate(name, desc)
    local hash = startup.protection_control.safe_feature_call(feature, "GetHash")
    local featureType = startup.protection_control.safe_feature_call(feature, "GetType")
    local isToggle = startup.protection_control.safe_feature_call(feature, "IsToggleFeature")
    local toggled = startup.protection_control.safe_feature_call(feature, "IsToggled")
    local boolValue = startup.protection_control.safe_feature_call(feature, "GetBoolValue")
    local listIndex = startup.protection_control.safe_feature_call(feature, "GetListIndex")
    local currentList = nil
    if hash ~= nil and FeatureMgr and FeatureMgr.GetCurrentFeatureListString then
        local ok, value = direct_call(function() return FeatureMgr.GetCurrentFeatureListString(hash) end)
        if ok then currentList = value end
    end
    return {
        name = name,
        desc = desc,
        hash = hash,
        featureType = featureType,
        isToggle = isToggle == true,
        toggled = toggled == true,
        boolValue = boolValue,
        listIndex = listIndex,
        currentList = currentList,
        candidate = isCandidate == true,
        matchedToken = matchedToken,
    }
end

function startup.protection_control.is_startup_feature_hash(hash)
    if hash == nil then return false end
    for _, startupHash in pairs(startup.h or {}) do
        if tostring(startupHash) == tostring(hash) then return true end
    end
    return false
end

function startup.protection_control.capture_profile()
    local profile = {
        captured = os.date("%Y-%m-%d %H:%M:%S"),
        edition = tostring((startup.get_active_edition_info and startup.get_active_edition_info()) or "Unknown"),
        enumerationSource = "FeatureMgr.GetAllFeatures",
        totalFeatures = 0,
        toggleFeatures = 0,
        enabledToggles = 0,
        candidates = {},
        enabledNonCandidateToggles = {},
        excludedStartupFeatures = 0,
    }

    local function add_feature(feature, forceBaselineCandidate)
        if feature == nil then return end
        local row = startup.protection_control.snapshot_feature(feature)
        profile.totalFeatures = profile.totalFeatures + 1
        if startup.protection_control.is_startup_feature_hash(row.hash) then
            profile.excludedStartupFeatures = profile.excludedStartupFeatures + 1
            return
        end
        if row.isToggle then profile.toggleFeatures = profile.toggleFeatures + 1 end
        if row.toggled then profile.enabledToggles = profile.enabledToggles + 1 end
        if forceBaselineCandidate == true then
            row.candidate = true
            if tostring(row.matchedToken or "") == "" then row.matchedToken = "baseline-hash" end
        end
        if row.candidate then
            profile.candidates[#profile.candidates + 1] = row
        elseif row.isToggle and row.toggled then
            profile.enabledNonCandidateToggles[#profile.enabledNonCandidateToggles + 1] = row
        end
    end

    local features = nil
    if FeatureMgr and FeatureMgr.GetAllFeatures then
        local ok, result = direct_call(FeatureMgr.GetAllFeatures)
        if ok and type(result) == "table" and next(result) ~= nil then features = result end
    end

    if type(features) == "table" and next(features) ~= nil then
        for _, feature in pairs(features) do add_feature(feature, false) end
    else
        profile.enumerationSource = "Exact Cherax 64-method hash fallback"
        local seen = {}
        local catalog = startup.cherax_protection64 and startup.cherax_protection64.methods or {}
        for _, method in ipairs(catalog) do
            local expectedHash, expectedName = method[1], method[2]
            local key = tostring(expectedHash)
            if not seen[key] then
                seen[key] = true
                local feature = nil
                if startup.cherax_protection64 and startup.cherax_protection64.resolve then
                    feature = startup.cherax_protection64.resolve(expectedHash, expectedName)
                elseif FeatureMgr and FeatureMgr.GetFeature then
                    direct_call(function() feature = FeatureMgr.GetFeature(expectedHash) end)
                end
                add_feature(feature, true)
            end
        end
    end

    table.sort(profile.candidates, function(a, b) return tostring(a.name):lower() < tostring(b.name):lower() end)
    table.sort(profile.enabledNonCandidateToggles, function(a, b) return tostring(a.name):lower() < tostring(b.name):lower() end)

    local enabledCandidates = 0
    for _, row in ipairs(profile.candidates) do
        local enabled = row.toggled == true or row.boolValue == true
        if enabled then enabledCandidates = enabledCandidates + 1 end
    end
    profile.enabledCandidates = enabledCandidates
    startup.protection_control.profile = profile
    startup.s.protectionControlLastCandidateCount = #profile.candidates
    startup.s.protectionControlLastEnabledCount = enabledCandidates
    return profile
end

function startup.protection_control.reaction_type_name(value)
    if eProtectionType then
        for key, enumValue in pairs(eProtectionType) do
            if enumValue == value then return tostring(key) end
        end
    end
    return "UNKNOWN"
end

function startup.protection_control.serialize_value(value, depth, seen)
    depth = tonumber(depth or 0) or 0
    seen = seen or {}
    local valueType = type(value)
    if valueType == "nil" then return "nil" end
    if valueType == "boolean" or valueType == "number" then return tostring(value) end
    if valueType == "string" then
        local clean = value:gsub("[\r\n]", " ")
        if #clean > 240 then clean = clean:sub(1, 240) .. "..." end
        return string.format("%q", clean)
    end
    if valueType == "table" then
        if seen[value] then return "<cycle>" end
        if depth >= 2 then return "<table>" end
        seen[value] = true
        local parts = {}
        local count = 0
        for key, child in pairs(value) do
            count = count + 1
            if count > 24 then parts[#parts + 1] = "..."; break end
            parts[#parts + 1] = "[" .. startup.protection_control.serialize_value(key, depth + 1, seen) .. "]="
                .. startup.protection_control.serialize_value(child, depth + 1, seen)
        end
        seen[value] = nil
        return "{" .. table.concat(parts, ", ") .. "}"
    end
    local ok, converted = direct_call(tostring, value)
    return ok and tostring(converted) or ("<" .. valueType .. ">")
end

function startup.protection_control.record_reaction(...)
    if startup.protection_control.active ~= true then return end
    local args = { ... }
    local parts = {}
    local mapped = {}
    for index, value in ipairs(args) do
        parts[#parts + 1] = "arg" .. tostring(index) .. "(" .. type(value) .. ")="
            .. startup.protection_control.serialize_value(value, 0, {})
        if type(value) == "number" then
            local name = startup.protection_control.reaction_type_name(value)
            if name ~= "UNKNOWN" then mapped[#mapped + 1] = "arg" .. tostring(index) .. "=" .. name end
        end
    end
    startup.protection_control.events[#startup.protection_control.events + 1] = {
        wallTime = os.date("%Y-%m-%d %H:%M:%S"),
        elapsedMs = math.max(0, (startup.now() or 0) - (startup.protection_control.startedAt or 0)),
        mapped = #mapped > 0 and table.concat(mapped, ", ") or "<none>",
        detail = table.concat(parts, " | "),
    }
end

function startup.protection_control.feature_row_text(row)
    return "name=" .. tostring(row.name)
        .. " | hash=" .. tostring(row.hash)
        .. " | type=" .. tostring(row.featureType)
        .. " | toggle=" .. tostring(row.isToggle == true)
        .. " | toggled=" .. tostring(row.toggled == true)
        .. " | bool=" .. tostring(row.boolValue)
        .. " | listIndex=" .. tostring(row.listIndex)
        .. " | list=" .. tostring(row.currentList)
        .. " | matched=" .. tostring(row.matchedToken or "")
        .. " | desc=" .. tostring(row.desc or "")
end

function startup.protection_control.write_report(reason)
    startup.ensure_save_dir()
    if FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, startup.diagnostics_dir) end
    local profile = startup.protection_control.profile or startup.protection_control.capture_profile()
    local stamp = os.date("%Y%m%d_%H%M%S")
    startup.protection_control.reportSerial = (tonumber(startup.protection_control.reportSerial or 0) or 0) + 1
    local path = tostring(startup.diagnostics_dir or startup.storage_dir or ".")
        .. "\\Cherax_Protection_Control_" .. stamp .. "_" .. tostring(startup.protection_control.reportSerial) .. ".txt"

    local lines = {
        "STARTUP CHERAX PROTECTION CONTROL LAB",
        "====================================",
        "",
        "Startup version: " .. tostring(startup.version or "Unknown"),
        "Startup build: " .. tostring(startup.build_number or "Unknown"),
        "Captured: " .. os.date("%Y-%m-%d %H:%M:%S"),
        "Reason: " .. tostring(reason or "manual"),
        "Edition: " .. tostring(profile.edition or "Unknown"),
        "Feature enumeration source: " .. tostring(profile.enumerationSource or "Unknown"),
        "Safety: local read-only feature inspection and local ON_REACTION recording only",
        "No kick, crash, report, script event, chat, entity, explosion, or remote probe was sent.",
        "",
        "IMPORTANT",
        "---------",
        "This report shows the current local Cherax feature state, not guaranteed factory defaults.",
        "Local protection settings are not directly visible to another player and do not prove a remote user runs Cherax.",
        "The purpose is to learn which current protections and reactions exist on a confirmed Cherax control client.",
        "",
        "PROFILE SUMMARY",
        "---------------",
        "Total global features read: " .. tostring(profile.totalFeatures or 0),
        "Toggle features: " .. tostring(profile.toggleFeatures or 0),
        "Enabled toggles: " .. tostring(profile.enabledToggles or 0),
        "Startup-owned features excluded: " .. tostring(profile.excludedStartupFeatures or 0),
        "Protection-like candidates: " .. tostring(#(profile.candidates or {})),
        "Enabled protection-like candidates: " .. tostring(profile.enabledCandidates or 0),
        "Reaction events captured: " .. tostring(#(startup.protection_control.events or {})),
        "",
        "PROTECTION-LIKE FEATURE CANDIDATES",
        "----------------------------------",
    }

    if #(profile.candidates or {}) == 0 then
        lines[#lines + 1] = "<none matched by name or description>"
    else
        for index, row in ipairs(profile.candidates or {}) do
            lines[#lines + 1] = string.format("%03d. %s", index, startup.protection_control.feature_row_text(row))
        end
    end

    lines[#lines + 1] = ""
    lines[#lines + 1] = "OTHER ENABLED GLOBAL TOGGLES"
    lines[#lines + 1] = "----------------------------"
    lines[#lines + 1] = "Included for comparison because Cherax does not expose parent-tab metadata through this API."
    if #(profile.enabledNonCandidateToggles or {}) == 0 then
        lines[#lines + 1] = "<none>"
    else
        for index, row in ipairs(profile.enabledNonCandidateToggles or {}) do
            lines[#lines + 1] = string.format("%03d. %s", index, startup.protection_control.feature_row_text(row))
        end
    end

    lines[#lines + 1] = ""
    lines[#lines + 1] = "ON_REACTION EVENTS"
    lines[#lines + 1] = "------------------"
    if #(startup.protection_control.events or {}) == 0 then
        lines[#lines + 1] = "<none captured>"
    else
        for index, event in ipairs(startup.protection_control.events or {}) do
            lines[#lines + 1] = string.format(
                "%03d. time=%s | elapsedMs=%s | mapped=%s | %s",
                index,
                tostring(event.wallTime or ""),
                tostring(event.elapsedMs or 0),
                tostring(event.mapped or "<none>"),
                tostring(event.detail or "")
            )
        end
    end
    lines[#lines + 1] = ""

    if startup.try_write_file(path, table.concat(lines, "\n") .. "\n") then
        startup.s.protectionControlLastReportPath = path
        startup.s.protectionControlLastReactionCount = #(startup.protection_control.events or {})
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("PROTECTION_CONTROL_REPORT", "path=" .. tostring(path)
                .. " candidates=" .. tostring(#(profile.candidates or {}))
                .. " reactions=" .. tostring(#(startup.protection_control.events or {})))
        end
        return path
    end
    startup.s.protectionControlLastReportPath = ""
    return ""
end

function startup.protection_control.finish(reason)
    if startup.protection_control.active ~= true and reason ~= "profile-only" then return false end
    startup.protection_control.active = false
    local path = startup.protection_control.write_report(reason or "capture complete")
    if path ~= "" then
        startup.s.protectionControlStatus = "Saved: " .. tostring(#(startup.protection_control.events or {})) .. " reaction event(s)"
        startup.toast("Protection Control report saved.", 4000)
        startup.log_colored("[Protection Lab] Report saved with "
            .. tostring(#(startup.protection_control.events or {})) .. " reaction event(s).", "success")
        return true
    end
    startup.s.protectionControlStatus = "Report write failed"
    startup.toast("Protection Control report could not be saved.", 4000)
    return false
end

function startup.export_local_protection_profile()
    if startup.protection_control.jobQueued == true then
        startup.toast("Protection Control Lab is already working.", 3000)
        return false
    end
    startup.protection_control.jobQueued = true
    startup.s.protectionControlStatus = "Reading current local protection profile..."
    local job = function()
        startup.protection_control.events = {}
        local profile = startup.protection_control.capture_profile()
        local path = startup.protection_control.write_report("profile-only")
        startup.protection_control.jobQueued = false
        if path ~= "" then
            startup.s.protectionControlStatus = "Profile saved: " .. tostring(#(profile.candidates or {}))
                .. " candidate(s), " .. tostring(profile.enabledCandidates or 0) .. " enabled"
            startup.toast("Local protection profile saved.", 4000)
            startup.log_colored("[Protection Lab] Local profile saved: "
                .. tostring(#(profile.candidates or {})) .. " candidate(s), "
                .. tostring(profile.enabledCandidates or 0) .. " enabled.", "success")
            return true
        end
        startup.s.protectionControlStatus = "Profile write failed"
        startup.toast("Local protection profile could not be saved.", 4000)
        return false
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
    return true
end

function startup.start_protection_reaction_capture()
    if startup.protection_control.active == true or startup.protection_control.jobQueued == true then
        startup.toast("Protection Control capture is already active.", 3000)
        return false
    end
    startup.protection_control.jobQueued = true
    local job = function()
        startup.protection_control.profile = startup.protection_control.capture_profile()
        startup.protection_control.events = {}
        startup.protection_control.startedAt = startup.now()
        startup.protection_control.deadline = startup.protection_control.startedAt + startup.protection_control.durationMs
        startup.protection_control.active = true
        startup.protection_control.jobQueued = false
        startup.s.protectionControlStatus = "Recording local protection reactions for 90 seconds..."
        startup.toast("Protection Control capture started for 90 seconds.", 4000)
        startup.log_colored("[Protection Lab] 90-second local reaction capture started.", "info")
        while startup.protection_control.active == true and startup.now() < startup.protection_control.deadline do
            if Script and Script.Yield then Script.Yield(100) else break end
        end
        if startup.protection_control.active == true then
            startup.protection_control.finish("90-second window complete")
        end
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
    return true
end

function startup.stop_protection_reaction_capture()
    if startup.protection_control.active ~= true then
        startup.toast("No Protection Control capture is active.", 3000)
        return false
    end
    return startup.protection_control.finish("manual stop")
end

function startup.copy_protection_control_report_path()
    local path = tostring(startup.s.protectionControlLastReportPath or "")
    if path == "" then
        startup.toast("Run the Protection Control Lab first.", 3500)
        return false
    end
    local copied = startup.copy_to_clipboard(path)
    startup.toast(copied and "Protection report path copied." or "Could not copy the report path.", 3500)
    return copied
end


