function startup.cherax_protection64.u32(value)
    value = tonumber(value)
    if value == nil then return nil end
    if value < 0 then value = value + 4294967296 end
    return value % 4294967296
end

function startup.cherax_protection64.feature_call(feature, methodName, ...)
    if feature == nil then return nil end
    local method = feature[methodName]
    if type(method) ~= "function" then return nil end
    local args = { ... }
    local unpackFn = table.unpack or unpack
    local ok, value = direct_call(function() return method(feature, unpackFn(args)) end)
    if not ok then return nil end
    return value
end

function startup.cherax_protection64.resolve(hash, expectedName)
    if not FeatureMgr then return nil, "FeatureMgr unavailable" end
    local feature = nil
    if FeatureMgr.GetFeature then
        direct_call(function() feature = FeatureMgr.GetFeature(hash) end)
        if feature == nil and tonumber(hash) and tonumber(hash) > 2147483647 then
            direct_call(function() feature = FeatureMgr.GetFeature(tonumber(hash) - 4294967296) end)
        end
    end
    if feature == nil and FeatureMgr.GetFeatureByName then
        direct_call(function() feature = FeatureMgr.GetFeatureByName(expectedName) end)
    end
    return feature, feature and "resolved" or "missing"
end

function startup.cherax_protection64.bool_text(value)
    return value == true and "true" or value == false and "false" or tostring(value)
end

function startup.cherax_protection64.read_state(feature, kind, expected)
    if kind == "bool" then
        local value = startup.cherax_protection64.feature_call(feature, "GetBoolValue")
        if value == nil then value = startup.cherax_protection64.feature_call(feature, "IsToggled") end
        return value, startup.cherax_protection64.bool_text(value)
    elseif kind == "int" then
        local value = startup.cherax_protection64.feature_call(feature, "GetIntValue")
        return tonumber(value), tostring(value)
    elseif kind == "list" then
        local value = startup.cherax_protection64.feature_call(feature, "GetListIndex")
        return tonumber(value), tostring(value)
    elseif kind == "toggles" then
        local values = {}
        local bits = {}
        for index = 1, #expected do
            local value = startup.cherax_protection64.feature_call(feature, "IsListIndexToggled", index - 1)
            values[index] = value == true
            bits[index] = value == true and "1" or "0"
        end
        return values, table.concat(bits, "")
    end
    return nil, "unsupported"
end

function startup.cherax_protection64.expected_text(kind, expected)
    if kind == "toggles" then
        local bits = {}
        for index = 1, #expected do bits[index] = expected[index] == true and "1" or "0" end
        return table.concat(bits, "")
    end
    return tostring(expected)
end

function startup.cherax_protection64.state_matches(kind, current, expected)
    if kind == "toggles" then
        if type(current) ~= "table" then return false end
        for index = 1, #expected do
            if (current[index] == true) ~= (expected[index] == true) then return false end
        end
        return true
    elseif kind == "bool" then
        return (current == true) == (expected == true)
    end
    return tonumber(current) == tonumber(expected)
end

function startup.cherax_protection64.write_report(rows, summary)
    startup.ensure_save_dir()
    if FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, startup.diagnostics_dir) end
    startup.cherax_protection64.serial = (tonumber(startup.cherax_protection64.serial or 0) or 0) + 1
    local path = tostring(startup.diagnostics_dir or startup.storage_dir or ".")
        .. "\\Cherax_64_Protection_Test_" .. os.date("%Y%m%d_%H%M%S")
        .. "_" .. tostring(startup.cherax_protection64.serial) .. ".txt"
    local lines = {
        "STARTUP CHERAX 64-METHOD PROTECTION TEST",
        "Generated: " .. os.date("%Y-%m-%d %H:%M:%S"),
        "Startup version: " .. tostring(startup.version or "Unknown"),
        "Startup build: " .. tostring(startup.build_number or "Unknown"),
        "Edition: " .. tostring((startup.get_active_edition_info and startup.get_active_edition_info()) or "Unknown"),
        "Safety: local read-only feature inspection; no remote probe and no values changed",
        "",
        "Resolved: " .. tostring(summary.resolved) .. "/64",
        "Exact names: " .. tostring(summary.names) .. "/64",
        "Baseline matches: " .. tostring(summary.baseline) .. "/64",
        "Core protections resolved: " .. tostring(summary.core) .. "/16",
        "Verdict: " .. tostring(summary.verdict),
        "Baseline profile: " .. tostring(summary.baselineVerdict),
        "",
        "METHODS",
    }
    for _, row in ipairs(rows) do
        lines[#lines + 1] = string.format(
            "%02d/64 %s | %s | hash=%s | actualHash=%s | name=%s | current=%s | expected=%s",
            row.index, row.status, row.expectedName, tostring(row.expectedHash),
            tostring(row.actualHash), tostring(row.actualName), tostring(row.currentText), tostring(row.expectedText)
        )
    end
    local ok = startup.try_write_file(path, table.concat(lines, "\r\n") .. "\r\n")
    if ok then
        startup.s.cheraxProtection64ReportPath = path
        return path
    end
    return ""
end

function startup.cherax_protection64.run_sync()
    if startup.cherax_protection64.running == true then
        startup.toast("Cherax 64-method test is already running.", 3000)
        return false
    end
    if not startup.is_enhanced_active_edition() then
        startup.toast("The Cherax 64-method test is currently enabled for EE testing only.", 4500)
        return false
    end

    startup.cherax_protection64.running = true
    startup.s.cheraxProtection64Status = "Running 64 exact Cherax feature checks..."
    startup.s.cheraxProtection64Verdict = "Running"
    startup.log("[Cherax 64 Test] BEGIN | methods=64 | safety=local read-only | source=verified protection baseline")

    local rows = {}
    local resolved, exactNames, baselineMatches, coreResolved = 0, 0, 0, 0
    for index, method in ipairs(startup.cherax_protection64.methods) do
        local expectedHash, expectedName, kind, expected = method[1], method[2], method[3], method[4]
        local feature = startup.cherax_protection64.resolve(expectedHash, expectedName)
        local actualName, actualHash, current, currentText = "", nil, nil, "missing"
        local identityMatch, nameMatch, baselineMatch = false, false, false
        if feature ~= nil then
            actualName = tostring(startup.cherax_protection64.feature_call(feature, "GetName", false)
                or feature.Name or "")
            actualHash = startup.cherax_protection64.u32(
                startup.cherax_protection64.feature_call(feature, "GetHash") or expectedHash)
            identityMatch = tonumber(actualHash) == tonumber(expectedHash)
            nameMatch = actualName == expectedName
            current, currentText = startup.cherax_protection64.read_state(feature, kind, expected)
            baselineMatch = startup.cherax_protection64.state_matches(kind, current, expected)
            if identityMatch then
                resolved = resolved + 1
                if index <= 16 then coreResolved = coreResolved + 1 end
            end
            if nameMatch then exactNames = exactNames + 1 end
            if identityMatch and nameMatch and baselineMatch then baselineMatches = baselineMatches + 1 end
        end

        local status = "MISS"
        if feature ~= nil and identityMatch and nameMatch and baselineMatch then
            status = "PASS"
        elseif feature ~= nil and identityMatch and nameMatch then
            status = "MODIFIED"
        elseif feature ~= nil then
            status = "MISMATCH"
        end

        local row = {
            index = index,
            status = status,
            expectedHash = expectedHash,
            expectedName = expectedName,
            actualHash = actualHash,
            actualName = actualName ~= "" and actualName or "<missing>",
            currentText = currentText,
            expectedText = startup.cherax_protection64.expected_text(kind, expected),
        }
        rows[#rows + 1] = row
        startup.log(string.format(
            "[Cherax 64 Test] %02d/64 %s | %s | hash=%s | current=%s | expected=%s",
            index, status, expectedName, tostring(expectedHash), tostring(currentText), tostring(row.expectedText)
        ))
        startup.yield(35)
    end

    local verdict
    if resolved >= 62 and exactNames >= 60 and coreResolved >= 15 then
        verdict = "CHERAX FEATURE SET CONFIRMED"
    elseif resolved >= 56 and exactNames >= 54 and coreResolved >= 13 then
        verdict = "STRONG CHERAX FEATURE SET MATCH"
    elseif resolved >= 40 then
        verdict = "PARTIAL CHERAX FEATURE SET"
    else
        verdict = "CHERAX FEATURE SET NOT CONFIRMED"
    end

    local baselineVerdict
    if baselineMatches >= 60 then
        baselineVerdict = "DEFAULT-LIKE PROTECTION PROFILE"
    elseif baselineMatches >= 48 then
        baselineVerdict = "MOSTLY DEFAULT WITH CUSTOM CHANGES"
    else
        baselineVerdict = "CUSTOMIZED OR DIFFERENT CHERAX PROFILE"
    end

    local summary = {
        resolved = resolved,
        names = exactNames,
        baseline = baselineMatches,
        core = coreResolved,
        verdict = verdict,
        baselineVerdict = baselineVerdict,
    }
    local reportPath = startup.cherax_protection64.write_report(rows, summary)
    startup.s.cheraxProtection64Resolved = resolved
    startup.s.cheraxProtection64BaselineMatches = baselineMatches
    startup.s.cheraxProtection64Verdict = verdict
    startup.s.cheraxProtection64Status = verdict .. " | resolved " .. tostring(resolved)
        .. "/64 | baseline " .. tostring(baselineMatches) .. "/64"
    startup.cherax_protection64.running = false

    startup.log("[Cherax 64 Test] RESULT | resolved=" .. tostring(resolved)
        .. "/64 | names=" .. tostring(exactNames)
        .. "/64 | baseline=" .. tostring(baselineMatches)
        .. "/64 | core=" .. tostring(coreResolved)
        .. "/16 | verdict=" .. tostring(verdict)
        .. " | profile=" .. tostring(baselineVerdict))
    startup.log("[Cherax 64 Test] REPORT | " .. (reportPath ~= "" and reportPath or "write failed"))
    startup.toast(verdict .. " | " .. tostring(resolved) .. "/64 resolved", 6500)
    return true
end

function startup.run_cherax_protection64_test()
    if startup.cherax_protection64.running == true then
        startup.toast("Cherax 64-method test is already running.", 3000)
        return false
    end
    local job = function()
        local ok, err = direct_call(startup.cherax_protection64.run_sync)
        if not ok then
            startup.cherax_protection64.running = false
            startup.s.cheraxProtection64Status = "Test failed: " .. tostring(err)
            startup.error("[Cherax 64 Test] ERROR | " .. tostring(err))
        end
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
    startup.toast("Queued the EE 64-method Cherax protection test.", 3500)
    return true
end

function startup.copy_cherax_protection64_report_path()
    local path = tostring(startup.s.cheraxProtection64ReportPath or "")
    if path == "" then
        startup.toast("Run the 64-method Cherax test first.", 3500)
        return false
    end
    local copied = startup.copy_to_clipboard(path)
    startup.toast(copied and "64-method report path copied." or "Could not copy the report path.", 3500)
    return copied
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- startup presence network
-- note: uses rate-limited direct chat challenge/response only. no hostile probes.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.presence = startup.presence or {}
startup.presence.protocol = "STP1"
startup.presence.challenge_prefix = "~STP1Q~"
startup.presence.reply_prefix = "~STP1A~"
startup.presence.proof_salt = "StartupPresence_2026_08_03_v1"
startup.presence.scan_timeout_ms = 7000
startup.presence.send_gap_ms = 350
startup.presence.reply_cooldown_ms = 30000
startup.presence.pending = nil
startup.presence.scan_busy = false
startup.presence.recent_messages = startup.presence.recent_messages or {}
startup.presence.last_reply_by_player = startup.presence.last_reply_by_player or {}
startup.presence.verified_by_player = startup.presence.verified_by_player or {}
startup.presence.verified_by_rid = startup.presence.verified_by_rid or {}
startup.presence.target_modes = { "Session Host", "Any Startup User" }

function startup.presence.u32_text(value)
    value = tonumber(value or 0) or 0
    if value < 0 then value = value + 4294967296 end
    value = value % 4294967296
    return string.format("%08X", value)
end

function startup.presence.hash_text(text)
    text = tostring(text or "")
    if Utils and Utils.Joaat then
        local ok, value = direct_call(function() return Utils.Joaat(text) end)
        if ok and value ~= nil then return startup.presence.u32_text(value) end
    end
    local hash = 5381
    for index = 1, #text do
        hash = ((hash * 33) + string.byte(text, index)) % 4294967296
    end
    return startup.presence.u32_text(hash)
end

function startup.presence.get_player_id_from_object(playerObj)
    if playerObj == nil then return nil end
    local id = nil
    direct_call(function() id = tonumber(playerObj.PlayerId) end)
    if id == nil then direct_call(function() id = tonumber(playerObj:GetPlayerId()) end) end
    if id == nil or id < 0 or id > 31 then return nil end
    return math.floor(id)
end

function startup.presence.get_player_rid(playerId)
    playerId = tonumber(playerId)
    if playerId == nil then return 0 end
    local rid = 0
    if Players and Players.GetById then
        local ok, player = direct_call(function() return Players.GetById(playerId) end)
        if ok and player then
            direct_call(function()
                local info = player.GamerInfo
                if info then rid = tonumber(info.RockstarId or 0) or 0 end
            end)
            if rid == 0 then
                direct_call(function()
                    local info = player:GetGamerInfo()
                    if info then rid = tonumber(info.RockstarId or 0) or 0 end
                end)
            end
        end
    end
    return tonumber(rid or 0) or 0
end

function startup.presence.get_player_name_from_object(playerObj, playerId)
    local name = ""
    if playerObj then direct_call(function() name = tostring(playerObj:GetName() or "") end) end
    if name == "" and playerId ~= nil then name = startup.get_player_name_safe(playerId) end
    return tostring(name ~= "" and name or ("Player " .. tostring(playerId or "?")))
end

function startup.presence.make_nonce()
    startup.presence.serial = (tonumber(startup.presence.serial or 0) or 0) + 1
    local localId = (startup.get_local_player_id_candidates()[1] or 0)
    return startup.presence.hash_text(table.concat({
        tostring(startup.now()), tostring(os.time()), tostring(localId),
        tostring(startup.presence.serial), tostring(math.random and math.random(1, 2147483646) or 1)
    }, "|"))
end

function startup.presence.make_proof(nonce, requesterRid, responderRid, version, build)
    return startup.presence.hash_text(table.concat({
        startup.presence.proof_salt,
        tostring(nonce or ""),
        tostring(requesterRid or 0),
        tostring(responderRid or 0),
        tostring(version or ""),
        tostring(build or "")
    }, "|"))
end

function startup.presence.is_duplicate_message(playerId, message)
    local now = startup.now()
    local key = tostring(playerId or -1) .. "|" .. tostring(message or "")
    local last = tonumber(startup.presence.recent_messages[key] or 0) or 0
    startup.presence.recent_messages[key] = now
    for cacheKey, cacheTime in pairs(startup.presence.recent_messages) do
        if now - (tonumber(cacheTime or 0) or 0) > 5000 then startup.presence.recent_messages[cacheKey] = nil end
    end
    return now - last < 1500
end

function startup.presence.send_direct(playerId, message)
    playerId = tonumber(playerId)
    message = tostring(message or "")
    if playerId == nil or playerId < 0 or playerId > 31 or message == "" then return false end
    if startup.is_local_player_id(playerId) then return false end
    if not GTA or not GTA.SendChatMessageToPlayer then return false end
    local ok = direct_call(function()
        if Script and Script.ExecuteAsScript then
            Script.ExecuteAsScript("freemode", function()
                GTA.SendChatMessageToPlayer(playerId, message, false)
            end)
        else
            GTA.SendChatMessageToPlayer(playerId, message, false)
        end
    end)
    return ok == true
end

function startup.presence.challenge_message(nonce, requesterRid)
    return startup.presence.challenge_prefix .. tostring(nonce) .. "|" .. tostring(requesterRid or 0)
end

function startup.presence.reply_message(nonce, requesterRid, responderRid)
    local version = tostring(startup.version or "v1.0.18")
    local build = tostring(startup.build_number or "Unknown")
    local proof = startup.presence.make_proof(nonce, requesterRid, responderRid, version, build)
    return startup.presence.reply_prefix .. table.concat({
        tostring(nonce), tostring(responderRid or 0), version, build, proof
    }, "|")
end

function startup.presence.note_found(playerId, playerName, rid, version, build)
    local pending = startup.presence.pending
    if type(pending) ~= "table" then return false end
    local key = tostring(rid and rid ~= 0 and rid or playerId)
    if pending.found[key] then return false end

    local _, hostId = startup.get_session_host_name()
    local scriptHostId = -1
    if startup.get_script_host_name then
        local _, shid = startup.get_script_host_name()
        scriptHostId = tonumber(shid) or -1
    end
    local row = {
        playerId = tonumber(playerId) or -1,
        name = tostring(playerName or "Unknown"),
        rid = tonumber(rid or 0) or 0,
        version = tostring(version or "Unknown"),
        build = tostring(build or "Unknown"),
        isHost = tonumber(hostId) == tonumber(playerId),
        isScriptHost = tonumber(scriptHostId) == tonumber(playerId),
        receivedAt = startup.now()
    }
    pending.found[key] = row
    pending.foundOrder[#pending.foundOrder + 1] = row
    startup.presence.verified_by_player[row.playerId] = row
    if row.rid and tonumber(row.rid) and tonumber(row.rid) > 0 then
        startup.presence.verified_by_rid[tostring(math.floor(tonumber(row.rid)))] = row
    end
    if startup.session_activity_update_classification then
        startup.session_activity_update_classification(row.playerId, row.name, "startup_peer")
    end
    startup.s.startupPresenceLastFoundCount = #pending.foundOrder
    local labels = {}
    for _, found in ipairs(pending.foundOrder) do
        labels[#labels + 1] = tostring(found.name)
            .. (found.isHost and " [H]" or "")
            .. (found.isScriptHost and " [SH]" or "")
    end
    startup.s.startupPresenceLastFound = table.concat(labels, ", ")
    startup.s.startupPresenceFinderStatus = "Verified " .. tostring(#pending.foundOrder) .. " compatible Startup user(s)"
    startup.toast("Startup verified: " .. tostring(row.name)
        .. " | " .. tostring(row.version) .. " | " .. tostring(row.build), 6000)
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("STARTUP_PRESENCE_FOUND",
            "player=" .. tostring(row.name) .. " [" .. tostring(row.playerId) .. "]"
            .. " rid=" .. tostring(row.rid)
            .. " version=" .. tostring(row.version)
            .. " build=" .. tostring(row.build)
            .. " host=" .. tostring(row.isHost)
            .. " scriptHost=" .. tostring(row.isScriptHost))
    end
    return true
end

function startup.presence.handle_chat(playerObj, rawMessage)
    if type(rawMessage) ~= "string" or rawMessage == "" then return false end
    local isChallenge = rawMessage:sub(1, #startup.presence.challenge_prefix) == startup.presence.challenge_prefix
    local isReply = rawMessage:sub(1, #startup.presence.reply_prefix) == startup.presence.reply_prefix
    if not isChallenge and not isReply then return false end

    local playerId = startup.presence.get_player_id_from_object(playerObj)
    if playerId == nil or startup.is_local_player_id(playerId) then return true end
    if startup.presence.is_duplicate_message(playerId, rawMessage) then return true end
    local playerName = startup.presence.get_player_name_from_object(playerObj, playerId)
    local actualRid = startup.presence.get_player_rid(playerId)

    if isChallenge then
        local payload = rawMessage:sub(#startup.presence.challenge_prefix + 1)
        local nonce, requesterRidText = payload:match("^([^|]+)|([^|]+)$")
        local requesterRid = tonumber(requesterRidText or 0) or 0
        if not nonce or #nonce < 4 or #nonce > 16 then return true end
        if actualRid ~= 0 and requesterRid ~= 0 and actualRid ~= requesterRid then return true end
        if startup.s.startupPresenceRepliesEnabled == false then return true end

        local now = startup.now()
        local last = tonumber(startup.presence.last_reply_by_player[playerId] or 0) or 0
        if now - last < startup.presence.reply_cooldown_ms then return true end
        startup.presence.last_reply_by_player[playerId] = now
        local localId = startup.get_local_player_id_candidates()[1] or 0
        local localRid = startup.presence.get_player_rid(localId)
        local reply = startup.presence.reply_message(nonce, requesterRid, localRid)
        local sendJob = function()
            startup.yield(150 + ((playerId * 37) % 220))
            startup.presence.send_direct(playerId, reply)
        end
        if Script and Script.QueueJob then Script.QueueJob(sendJob) else sendJob() end
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("STARTUP_PRESENCE_REPLY",
                "to=" .. tostring(playerName) .. " [" .. tostring(playerId) .. "] nonce=" .. tostring(nonce))
        end
        return true
    end

    local payload = rawMessage:sub(#startup.presence.reply_prefix + 1)
    local nonce, responderRidText, version, build, proof = payload:match("^([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)$")
    local pending = startup.presence.pending
    if type(pending) ~= "table" or tostring(nonce or "") ~= tostring(pending.nonce or "") then return true end
    if pending.targets[playerId] ~= true then return true end
    local responderRid = tonumber(responderRidText or 0) or 0
    if actualRid ~= 0 and responderRid ~= 0 and actualRid ~= responderRid then return true end
    local expected = startup.presence.make_proof(nonce, pending.requesterRid, responderRid, version, build)
    if tostring(proof or "") ~= tostring(expected) then
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("STARTUP_PRESENCE_BAD_PROOF",
                "player=" .. tostring(playerName) .. " [" .. tostring(playerId) .. "]")
        end
        return true
    end
    startup.presence.note_found(playerId, playerName, responderRid, version, build)
    return true
end

function startup.presence.collect_targets(targetMode)
    targetMode = tostring(targetMode or "Session Host")
    local targets = {}
    if targetMode == "Session Host" then
        local hostName, hostId = startup.get_session_host_name()
        hostId = tonumber(hostId)
        if hostId and hostId >= 0 and hostId <= 31 and not startup.is_local_player_id(hostId) then
            targets[#targets + 1] = { id = hostId, name = tostring(hostName or startup.get_player_name_safe(hostId)) }
        end
        return targets
    end

    for _, playerId in ipairs(startup.get_voice_player_ids()) do
        if not startup.is_local_player_id(playerId) then
            targets[#targets + 1] = { id = playerId, name = startup.get_player_name_safe(playerId) }
        end
    end
    table.sort(targets, function(a, b) return tonumber(a.id or 0) < tonumber(b.id or 0) end)
    return targets
end

function startup.presence.scan_sync(targetMode, reason)
    if startup.presence.scan_busy == true then
        return { count = 0, names = {}, error = "scan already active" }
    end
    startup.presence.scan_busy = true
    targetMode = tostring(targetMode or "Session Host")
    if targetMode ~= "Any Startup User" then targetMode = "Session Host" end
    local targets = startup.presence.collect_targets(targetMode)
    if #targets == 0 then
        startup.presence.scan_busy = false
        startup.s.startupPresenceFinderStatus = targetMode == "Session Host"
            and "No remote Session Host is available to ping."
            or "No remote players are available to scan."
        return { count = 0, names = {}, error = "no targets" }
    end

    local localId = startup.get_local_player_id_candidates()[1] or 0
    local requesterRid = startup.presence.get_player_rid(localId)
    local nonce = startup.presence.make_nonce()
    local pending = {
        nonce = nonce,
        requesterRid = requesterRid,
        targetMode = targetMode,
        reason = tostring(reason or "manual"),
        targets = {},
        found = {},
        foundOrder = {},
        startedAt = startup.now(),
        deadline = 0
    }
    for _, target in ipairs(targets) do pending.targets[tonumber(target.id)] = true end
    startup.presence.pending = pending
    startup.s.startupPresenceFinderStatus = "Pinging " .. tostring(#targets) .. " target(s)..."
    startup.s.startupPresenceLastScanAt = os.time()
    startup.s.startupPresenceLastFound = "None"
    startup.s.startupPresenceLastFoundCount = 0

    local message = startup.presence.challenge_message(nonce, requesterRid)
    for index, target in ipairs(targets) do
        startup.presence.send_direct(target.id, message)
        if index < #targets then startup.yield(startup.presence.send_gap_ms) end
    end
    pending.deadline = startup.now() + startup.presence.scan_timeout_ms

    while startup.now() < pending.deadline do
        if targetMode == "Session Host" and #pending.foundOrder > 0 then break end
        startup.yield(100)
    end

    local names = {}
    for _, row in ipairs(pending.foundOrder) do
        names[#names + 1] = tostring(row.name)
            .. (row.isHost and " [H]" or "")
            .. (row.isScriptHost and " [SH]" or "")
    end
    local result = { count = #pending.foundOrder, names = names, rows = pending.foundOrder }
    startup.presence.pending = nil
    startup.presence.scan_busy = false
    if result.count > 0 then
        startup.s.startupPresenceFinderStatus = "Found " .. tostring(result.count) .. ": " .. table.concat(names, ", ")
        startup.log_colored("[Startup Network] Verified compatible Startup user(s): " .. table.concat(names, ", "), "success")
    else
        startup.s.startupPresenceFinderStatus = "No verified reply. This does not prove Startup or Cherax is absent."
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("STARTUP_PRESENCE_NO_REPLY",
                "mode=" .. tostring(targetMode) .. " targets=" .. tostring(#targets)
                .. " reason=" .. tostring(reason or "manual"))
        end
    end
    return result
end

function startup.presence.queue_scan(targetMode, reason)
    if startup.presence.scan_busy == true then
        startup.toast("A Startup Presence scan is already running.", 3000)
        return false
    end
    local job = function()
        local result = startup.presence.scan_sync(targetMode, reason)
        if result.count == 0 then
            startup.toast("No verified Startup reply. Older builds, disabled replies, or blocked text chat remain possible.", 5500)
        end
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
    return true
end

function startup.presence.ping_session_host()
    return startup.presence.queue_scan("Session Host", "manual Session Host ping")
end

function startup.presence.scan_current_lobby()
    return startup.presence.queue_scan(startup.s.startupPresenceFinderTarget or "Session Host", "manual current-lobby scan")
end

function startup.presence.start_session_finder()
    if startup.s.startupPresenceFinderEnabled == true then
        startup.toast("Startup Session Finder is already running.", 3000)
        return false
    end
    startup.s.startupPresenceFinderEnabled = true
    startup.s.startupPresenceFinderHopCount = 0
    startup.s.startupPresenceFinderStatus = "Starting with the current lobby..."
    startup.s.cheraxHostFinderEnabled = false
    startup.s.primeMinimumPlayersEnabled = false
    startup.set_feature_bool_silently(startup.h.FindCheraxHostLobbies, false)
    startup.set_feature_bool_silently(startup.h.PrimeMinimumPlayersEnabled, false)
    startup.set_feature_bool_silently(startup.h.StartupPresenceSessionFinder, true)
    startup.save_config(false)
    startup.lobby_filter.cancel("Starting Startup Presence Session Finder")
    startup.toast("Startup Session Finder started. It will stop after a verified reply or 10 sessions.", 6000)
    return startup.lobby_filter.begin(false)
end

function startup.presence.stop_session_finder()
    startup.s.startupPresenceFinderEnabled = false
    startup.s.startupPresenceFinderStatus = "Stopped by user"
    startup.set_feature_bool_silently(startup.h.StartupPresenceSessionFinder, false)
    if startup.lobby_filter and startup.lobby_filter.cancel then startup.lobby_filter.cancel("Startup Session Finder stopped") end
    startup.save_config(false)
    startup.toast("Startup Session Finder stopped.", 3000)
    return true
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- 63-method Cherax Session Host attestation
-- note: cooperative hidden private-chat challenge/response. The remote compatible
-- Startup/responder performs the exact-feature scan locally on the host machine.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.host_attest = startup.host_attest or {}
startup.host_attest.protocol = "CHX1"
startup.host_attest.challenge_prefix = "~CHX1Q~"
startup.host_attest.reply_prefix = "~CHX1A~"
startup.host_attest.proof_salt = "StartupCheraxHostAttest_2026_08_03_v1"
startup.host_attest.timeout_ms = 10000
startup.host_attest.reply_cooldown_ms = 30000
startup.host_attest.pending = nil
startup.host_attest.running = false
startup.host_attest.last_reply_by_player = startup.host_attest.last_reply_by_player or {}
startup.host_attest.methods = {}
startup.s.cheraxHostAttestStatus = tostring(startup.s.cheraxHostAttestStatus or "Not run")
startup.s.cheraxHostAttestVerdict = tostring(startup.s.cheraxHostAttestVerdict or "Not run")
startup.s.cheraxHostAttestReportPath = tostring(startup.s.cheraxHostAttestReportPath or "")
startup.s.cheraxHostAttestLastHost = tostring(startup.s.cheraxHostAttestLastHost or "None")

-- Build the verified 63-method runtime catalog by excluding the one legacy hash that
-- the active Cherax build did not expose (Block Infinite Phone Ring, 2812374956).
for _, method in ipairs(startup.cherax_protection64.methods or {}) do
    if tonumber(method[1]) ~= 2812374956 then
        startup.host_attest.methods[#startup.host_attest.methods + 1] = method
    end
end

function startup.host_attest.bits_to_hex(bits, total)
    total = tonumber(total or #bits) or #bits
    local out = {}
    local index = 1
    while index <= total do
        local value = 0
        for offset = 0, 3 do
            local bitIndex = index + offset
            value = value * 2 + ((bitIndex <= total and bits[bitIndex] == true) and 1 or 0)
        end
        out[#out + 1] = string.format("%X", value)
        index = index + 4
    end
    return table.concat(out, "")
end

function startup.host_attest.hex_count(hex)
    local pop = { ["0"]=0,["1"]=1,["2"]=1,["3"]=2,["4"]=1,["5"]=2,["6"]=2,["7"]=3,
        ["8"]=1,["9"]=2,["A"]=2,["B"]=3,["C"]=2,["D"]=3,["E"]=3,["F"]=4 }
    local count = 0
    hex = tostring(hex or ""):upper()
    for index = 1, #hex do count = count + (pop[hex:sub(index,index)] or 0) end
    return count
end

function startup.host_attest.scan_local()
    local resolvedBits, nameBits, baselineBits = {}, {}, {}
    local core = 0
    local rows = {}
    for index, method in ipairs(startup.host_attest.methods) do
        local expectedHash, expectedName, kind, expected = method[1], method[2], method[3], method[4]
        local feature = startup.cherax_protection64.resolve(expectedHash, expectedName)
        local resolved, nameMatch, baselineMatch = false, false, false
        local actualName, actualHash, currentText = "<missing>", nil, "missing"
        if feature ~= nil then
            actualName = tostring(startup.cherax_protection64.feature_call(feature, "GetName", false) or feature.Name or "")
            actualHash = startup.cherax_protection64.u32(startup.cherax_protection64.feature_call(feature, "GetHash") or expectedHash)
            resolved = tonumber(actualHash) == tonumber(expectedHash)
            nameMatch = actualName == expectedName
            local current, display = startup.cherax_protection64.read_state(feature, kind, expected)
            currentText = tostring(display)
            baselineMatch = startup.cherax_protection64.state_matches(kind, current, expected)
        end
        resolvedBits[index] = resolved
        nameBits[index] = resolved and nameMatch
        baselineBits[index] = resolved and nameMatch and baselineMatch
        if index <= 16 and resolved then core = core + 1 end
        rows[index] = {
            index=index, hash=expectedHash, expectedName=expectedName, actualHash=actualHash,
            actualName=actualName, currentText=currentText, resolved=resolved,
            nameMatch=nameMatch, baselineMatch=baselineMatch
        }
    end
    local resolvedHex = startup.host_attest.bits_to_hex(resolvedBits, 63)
    local namesHex = startup.host_attest.bits_to_hex(nameBits, 63)
    local baselineHex = startup.host_attest.bits_to_hex(baselineBits, 63)
    return {
        resolvedHex=resolvedHex, namesHex=namesHex, baselineHex=baselineHex,
        resolved=startup.host_attest.hex_count(resolvedHex),
        names=startup.host_attest.hex_count(namesHex),
        baseline=startup.host_attest.hex_count(baselineHex),
        core=core, rows=rows
    }
end

function startup.host_attest.make_proof(nonce, requesterRid, responderRid, version, build, resolvedHex, namesHex, baselineHex, core)
    return startup.presence.hash_text(table.concat({
        startup.host_attest.proof_salt, tostring(nonce or ""), tostring(requesterRid or 0),
        tostring(responderRid or 0), tostring(version or ""), tostring(build or ""),
        tostring(resolvedHex or ""), tostring(namesHex or ""), tostring(baselineHex or ""), tostring(core or 0)
    }, "|"))
end

function startup.host_attest.challenge_message(nonce, requesterRid)
    return startup.host_attest.challenge_prefix .. tostring(nonce) .. "|" .. tostring(requesterRid or 0)
end

function startup.host_attest.reply_message(nonce, requesterRid, responderRid, result)
    local version = tostring(startup.version or "v1.0.18")
    local build = tostring(startup.build_number or "Unknown")
    local proof = startup.host_attest.make_proof(nonce, requesterRid, responderRid, version, build,
        result.resolvedHex, result.namesHex, result.baselineHex, result.core)
    return startup.host_attest.reply_prefix .. table.concat({
        tostring(nonce), tostring(responderRid or 0), version, build,
        tostring(result.resolvedHex), tostring(result.namesHex), tostring(result.baselineHex),
        tostring(result.core), tostring(proof)
    }, "|")
end

function startup.host_attest.classify(resolved, names, baseline, core)
    if resolved >= 61 and names >= 60 and core >= 15 then
        return "CHERAX HOST CONFIRMED"
    elseif resolved >= 56 and names >= 54 and core >= 13 then
        return "STRONG CHERAX HOST MATCH"
    elseif resolved >= 40 then
        return "PARTIAL CHERAX HOST MATCH"
    end
    return "CHERAX HOST NOT CONFIRMED"
end

function startup.host_attest.profile_label(baseline)
    if baseline >= 60 then return "DEFAULT-LIKE PROTECTION PROFILE" end
    if baseline >= 48 then return "MOSTLY DEFAULT WITH CUSTOM CHANGES" end
    return "CUSTOMIZED OR DIFFERENT CHERAX PROFILE"
end

function startup.host_attest.write_report(pending, result)
    startup.ensure_save_dir()
    if FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, startup.diagnostics_dir) end
    startup.host_attest.serial = (tonumber(startup.host_attest.serial or 0) or 0) + 1
    local safeName = tostring(pending.hostName or "Host"):gsub("[^%w%._%-]", "_")
    local path = tostring(startup.diagnostics_dir or startup.storage_dir or ".")
        .. "\\Cherax_Host_63_Attestation_" .. os.date("%Y%m%d_%H%M%S")
        .. "_" .. safeName .. "_" .. tostring(startup.host_attest.serial) .. ".txt"
    local lines = {
        "STARTUP 63-METHOD CHERAX HOST TESTING",
        "Generated: " .. os.date("%Y-%m-%d %H:%M:%S"),
        "Startup version: " .. tostring(startup.version or "Unknown"),
        "Startup build: " .. tostring(startup.build_number or "Unknown"),
        "Safety: cooperative private challenge/response; remote host scans its own local Cherax environment",
        "No kick, crash, report, script event, entity, explosion, or hostile probe was sent.",
        "",
        "Session Host: " .. tostring(pending.hostName or "Unknown"),
        "Player ID: " .. tostring(pending.hostId or -1),
        "Rockstar ID: " .. tostring(pending.hostRid or 0),
        "Responder version: " .. tostring(result.version or "Unknown"),
        "Responder build: " .. tostring(result.build or "Unknown"),
        "",
        "Resolved exact Cherax hashes: " .. tostring(result.resolved) .. "/63",
        "Exact Cherax names: " .. tostring(result.names) .. "/63",
        "Baseline matches: " .. tostring(result.baseline) .. "/63",
        "Core protections resolved: " .. tostring(result.core) .. "/16",
        "Verdict: " .. tostring(result.verdict),
        "Protection profile: " .. tostring(result.profile),
        "",
        "Resolved mask: " .. tostring(result.resolvedHex),
        "Name mask: " .. tostring(result.namesHex),
        "Baseline mask: " .. tostring(result.baselineHex),
        "Nonce: " .. tostring(pending.nonce or ""),
        "Proof: " .. tostring(result.proof or ""),
        "",
        "IMPORTANT",
        "This confirms a compatible responder on the current Session Host returned a valid nonce-bound",
        "attestation for the expected Cherax feature catalog. The Lua protocol is not cryptographically",
        "secret and can be imitated by a deliberately modified responder. No reply is always inconclusive."
    }
    if startup.try_write_file(path, table.concat(lines, "\r\n") .. "\r\n") then
        startup.s.cheraxHostAttestReportPath = path
        return path
    end
    return ""
end

function startup.host_attest.finish_reply(playerId, playerName, actualRid, fields)
    local pending = startup.host_attest.pending
    if type(pending) ~= "table" or pending.done == true then return false end
    if tonumber(playerId) ~= tonumber(pending.hostId) then return false end
    if tostring(fields.nonce or "") ~= tostring(pending.nonce or "") then return false end
    if tonumber(pending.hostRid or 0) ~= 0 and tonumber(actualRid or 0) ~= 0
        and tonumber(pending.hostRid) ~= tonumber(actualRid) then return false end
    if tonumber(fields.responderRid or 0) ~= 0 and tonumber(actualRid or 0) ~= 0
        and tonumber(fields.responderRid) ~= tonumber(actualRid) then return false end
    if #tostring(fields.resolvedHex or "") ~= 16 or #tostring(fields.namesHex or "") ~= 16
        or #tostring(fields.baselineHex or "") ~= 16 then return false end
    local expectedProof = startup.host_attest.make_proof(fields.nonce, pending.requesterRid,
        fields.responderRid, fields.version, fields.build, fields.resolvedHex,
        fields.namesHex, fields.baselineHex, fields.core)
    if tostring(fields.proof or "") ~= tostring(expectedProof) then
        startup.error("[63 Cherax Host Testing] Invalid proof from " .. tostring(playerName))
        return false
    end
    local result = {
        version=fields.version, build=fields.build, responderRid=fields.responderRid,
        resolvedHex=fields.resolvedHex, namesHex=fields.namesHex, baselineHex=fields.baselineHex,
        core=tonumber(fields.core or 0) or 0, proof=fields.proof
    }
    result.resolved = startup.host_attest.hex_count(result.resolvedHex)
    result.names = startup.host_attest.hex_count(result.namesHex)
    result.baseline = startup.host_attest.hex_count(result.baselineHex)
    result.verdict = startup.host_attest.classify(result.resolved, result.names, result.baseline, result.core)
    result.profile = startup.host_attest.profile_label(result.baseline)
    pending.result = result
    pending.done = true
    local reportPath = startup.host_attest.write_report(pending, result)
    startup.s.cheraxHostAttestVerdict = result.verdict
    startup.s.cheraxHostAttestLastHost = tostring(pending.hostName or playerName)
    startup.s.cheraxHostAttestStatus = result.verdict .. " | " .. tostring(result.resolved)
        .. "/63 | core " .. tostring(result.core) .. "/16"
    startup.log("[63 Cherax Host Testing] RESULT | host=" .. tostring(pending.hostName)
        .. " [" .. tostring(pending.hostId) .. "] | resolved=" .. tostring(result.resolved)
        .. "/63 | names=" .. tostring(result.names) .. "/63 | baseline=" .. tostring(result.baseline)
        .. "/63 | core=" .. tostring(result.core) .. "/16 | verdict=" .. tostring(result.verdict)
        .. " | profile=" .. tostring(result.profile))
    startup.log("[63 Cherax Host Testing] REPORT | " .. (reportPath ~= "" and reportPath or "write failed"))
    startup.toast(result.verdict .. " | " .. tostring(pending.hostName) .. " | "
        .. tostring(result.resolved) .. "/63", 7500)
    return true
end

function startup.host_attest.handle_chat(playerObj, rawMessage)
    if type(rawMessage) ~= "string" or rawMessage == "" then return false end
    local isChallenge = rawMessage:sub(1, #startup.host_attest.challenge_prefix) == startup.host_attest.challenge_prefix
    local isReply = rawMessage:sub(1, #startup.host_attest.reply_prefix) == startup.host_attest.reply_prefix
    if not isChallenge and not isReply then return false end
    local playerId = startup.presence.get_player_id_from_object(playerObj)
    if playerId == nil or startup.is_local_player_id(playerId) then return true end
    local playerName = startup.presence.get_player_name_from_object(playerObj, playerId)
    local actualRid = startup.presence.get_player_rid(playerId)

    if isChallenge then
        local payload = rawMessage:sub(#startup.host_attest.challenge_prefix + 1)
        local nonce, requesterRidText = payload:match("^([^|]+)|([^|]+)$")
        local requesterRid = tonumber(requesterRidText or 0) or 0
        if not nonce or #nonce < 4 or #nonce > 16 then return true end
        if actualRid ~= 0 and requesterRid ~= 0 and actualRid ~= requesterRid then return true end
        if startup.s.startupPresenceRepliesEnabled == false then return true end
        local now = startup.now()
        local last = tonumber(startup.host_attest.last_reply_by_player[playerId] or 0) or 0
        if now - last < startup.host_attest.reply_cooldown_ms then return true end
        startup.host_attest.last_reply_by_player[playerId] = now
        local job = function()
            local localId = startup.get_local_player_id_candidates()[1] or 0
            local localRid = startup.presence.get_player_rid(localId)
            local result = startup.host_attest.scan_local()
            local reply = startup.host_attest.reply_message(nonce, requesterRid, localRid, result)
            startup.yield(150 + ((playerId * 31) % 180))
            startup.presence.send_direct(playerId, reply)
            startup.log("[63 Cherax Host Testing] Hidden attestation reply sent to "
                .. tostring(playerName) .. " [" .. tostring(playerId) .. "] | "
                .. tostring(result.resolved) .. "/63")
        end
        if Script and Script.QueueJob then Script.QueueJob(job) else job() end
        return true
    end

    local payload = rawMessage:sub(#startup.host_attest.reply_prefix + 1)
    local nonce, responderRidText, version, build, resolvedHex, namesHex, baselineHex, coreText, proof =
        payload:match("^([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)$")
    if not nonce then return true end
    startup.host_attest.finish_reply(playerId, playerName, actualRid, {
        nonce=nonce, responderRid=tonumber(responderRidText or 0) or 0,
        version=version, build=build, resolvedHex=tostring(resolvedHex or ""):upper(),
        namesHex=tostring(namesHex or ""):upper(), baselineHex=tostring(baselineHex or ""):upper(),
        core=tonumber(coreText or 0) or 0, proof=proof
    })
    return true
end

function startup.host_attest.run_sync()
    if startup.host_attest.running == true then
        startup.toast("63 Cherax Host Testing is already running.", 3000)
        return false
    end
    if not startup.is_enhanced_active_edition() then
        startup.toast("63 Cherax Host Testing is currently enabled for EE testing only.", 4500)
        return false
    end
    local hostName, hostId = startup.get_session_host_name()
    hostId = tonumber(hostId)
    if hostId == nil or hostId < 0 or hostId > 31 or startup.is_local_player_id(hostId) then
        startup.s.cheraxHostAttestStatus = "No remote Session Host available"
        startup.toast("A remote Session Host is required.", 4000)
        return false
    end
    local localId = startup.get_local_player_id_candidates()[1] or 0
    local requesterRid = startup.presence.get_player_rid(localId)
    local hostRid = startup.presence.get_player_rid(hostId)
    local nonce = startup.presence.make_nonce()
    local pending = {
        nonce=nonce, requesterRid=requesterRid, hostId=hostId, hostRid=hostRid,
        hostName=tostring(hostName or startup.get_player_name_safe(hostId)),
        startedAt=startup.now(), deadline=startup.now()+startup.host_attest.timeout_ms,
        done=false, aborted=false
    }
    startup.host_attest.pending = pending
    startup.host_attest.running = true
    startup.s.cheraxHostAttestVerdict = "Running"
    startup.s.cheraxHostAttestStatus = "Waiting for hidden attestation from " .. pending.hostName .. "..."
    startup.log("[63 Cherax Host Testing] BEGIN | host=" .. pending.hostName .. " [" .. tostring(hostId)
        .. "] | rid=" .. tostring(hostRid) .. " | protocol=CHX1 | safety=private cooperative attestation")
    local sent = startup.presence.send_direct(hostId, startup.host_attest.challenge_message(nonce, requesterRid))
    if not sent then
        startup.host_attest.running = false
        startup.host_attest.pending = nil
        startup.s.cheraxHostAttestStatus = "Could not send private challenge"
        startup.toast("Could not send the private host challenge.", 4500)
        return false
    end
    while startup.now() < pending.deadline and pending.done ~= true do
        local currentName, currentId = startup.get_session_host_name()
        local currentRid = currentId ~= nil and startup.presence.get_player_rid(currentId) or 0
        if tonumber(currentId) ~= tonumber(pending.hostId)
            or (pending.hostRid ~= 0 and currentRid ~= 0 and tonumber(currentRid) ~= tonumber(pending.hostRid)) then
            pending.aborted = true
            break
        end
        startup.yield(100)
    end
    if pending.aborted then
        startup.s.cheraxHostAttestStatus = "Aborted: Session Host changed"
        startup.s.cheraxHostAttestVerdict = "ABORTED"
        startup.log("[63 Cherax Host Testing] ABORT | Session Host identity changed during challenge")
        startup.toast("63 Cherax Host Testing aborted because the Session Host changed.", 5500)
    elseif pending.done ~= true then
        startup.s.cheraxHostAttestStatus = "No compatible reply; result inconclusive"
        startup.s.cheraxHostAttestVerdict = "INCONCLUSIVE - NO COMPATIBLE RESPONDER"
        startup.log("[63 Cherax Host Testing] NO REPLY | host=" .. pending.hostName
            .. " | result=inconclusive | possible=older Startup, helper absent, replies disabled, chat blocked")
        startup.toast("No compatible host reply. This is inconclusive, not a Cherax failure.", 6500)
    end
    startup.host_attest.running = false
    startup.host_attest.pending = nil
    return pending.done == true
end

function startup.run_cherax_host_attestation63()
    if startup.host_attest.running == true then
        startup.toast("63 Cherax Host Testing is already running.", 3000)
        return false
    end
    local job = function()
        local ok, err = direct_call(startup.host_attest.run_sync)
        if not ok then
            startup.host_attest.running = false
            startup.host_attest.pending = nil
            startup.s.cheraxHostAttestStatus = "Test failed: " .. tostring(err)
            startup.s.cheraxHostAttestVerdict = "ERROR"
            startup.error("[63 Cherax Host Testing] ERROR | " .. tostring(err))
        end
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
    startup.toast("Queued 63-Method Cherax Host Testing.", 3500)
    return true
end

function startup.copy_cherax_host_attestation_report_path()
    local path = tostring(startup.s.cheraxHostAttestReportPath or "")
    if path == "" then
        startup.toast("Run 63 Cherax Host Testing and receive a verified reply first.", 4000)
        return false
    end
    local copied = startup.copy_to_clipboard(path)
    startup.toast(copied and "63 Host Test report path copied." or "Could not copy the report path.", 3500)
    return copied
end

startup.add_toggle("StartupPresenceReplies", "Allow Hidden Startup / Cherax Host Replies", "ON by default. Privately answers valid Startup presence and 63-method Cherax Host Testing challenges. Compatible protocol messages are hidden. No kick, crash, report, script event, entity, or hostile probe is used.", function(f)
    startup.s.startupPresenceRepliesEnabled = f:IsToggled()
    if startup.s.initialized then startup.save_config(false) end
end, startup.s.startupPresenceRepliesEnabled)
startup.add_combo("StartupPresenceFinderTarget", "Presence Finder Target", "Choose whether scans ping only the Session Host or every remote player. Host-only is quieter and recommended.", startup.presence.target_modes, startup.s.startupPresenceFinderTarget, function(value)
    startup.s.startupPresenceFinderTarget = tostring(value or "Session Host")
    if startup.s.initialized then startup.save_config(false) end
end)
startup.add_button("PingStartupSessionHost", "Ping Session Host for Startup", "Sends one private, rate-limited Startup presence challenge to the current remote Session Host.", startup.presence.ping_session_host)
