function startup.install_regional_warfare_features()
    if startup.regional_warfare_runtime.featuresInstalled==true then return end
    startup.regional_warfare_runtime.featuresInstalled=true
    startup.regional_warfare_sanitize_state()

    startup.add_toggle("RegionalWarfareEnabled","Enable Regional Warfare","Private-server warfare mode. Player teams are detected from Cherax Player Language only; IP country/geolocation is not used.",function(f)
        startup.s.regionalWarfareEnabled=f:IsToggled()
        startup.regional_warfare_runtime.lastScanMs=0
        if startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
    end,startup.s.regionalWarfareEnabled==true)

    startup.add_combo("RegionalWarfareMyFaction","My Warfare Language","Auto reads your Cherax Player Language. You can manually choose your gameplay language team if local language detection is unavailable.",startup.regional_warfare_languages,startup.s.regionalWarfareMyFaction,function(selected)
        startup.s.regionalWarfareMyFaction=startup.regional_warfare_valid_faction(selected)
        startup.regional_warfare_runtime.lastApplied={}
        startup.regional_warfare_runtime.lastScanMs=0
        if startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
    end)

    startup.add_combo("RegionalWarfareEnemyPolicy","Enemy Language Policy","All Other Languages targets every detected language except your own. Selected Languages uses the enemy language toggles below.",startup.regional_warfare_enemy_policies,startup.s.regionalWarfareEnemyPolicy,function(selected)
        startup.s.regionalWarfareEnemyPolicy=tostring(selected or "All Other Languages")
        startup.regional_warfare_runtime.lastApplied={}
        startup.regional_warfare_runtime.lastScanMs=0
        if startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
    end)

    startup.add_toggle("RegionalWarfareAutoBounty","Auto Bounty Enemy Languages","Uses Minigames/WarGames confirmed Cherax built-in Set Bounty On Player. New detected enemies are eligible immediately; maintenance is serialized and refreshed every 180 seconds.",function(f)
        startup.s.regionalWarfareAutoBounty=f:IsToggled()
        startup.regional_warfare_runtime.lastScanMs=0
        if startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
    end,startup.s.regionalWarfareAutoBounty~=false)

    for _,language in ipairs(startup.regional_warfare_languages or {}) do
        if language~="Auto (Player Language)" and language~="Unknown" then
            local languageName=language
            local key="RegionalWarfareEnemy_"..startup.regional_warfare_feature_key(languageName)
            startup.add_toggle(key,"Enemy: "..languageName,"Used only when Enemy Language Policy is Selected Languages.",function(f)
                startup.s.regionalWarfareSelectedEnemies=type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies or {}
                startup.s.regionalWarfareSelectedEnemies[languageName]=f:IsToggled()
                startup.regional_warfare_runtime.lastApplied={}
                startup.regional_warfare_runtime.lastScanMs=0
                if startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
            end,startup.s.regionalWarfareSelectedEnemies and startup.s.regionalWarfareSelectedEnemies[languageName]==true)
        end
    end

    startup.add_button("RegionalWarfareBountyNow","Bounty Enemy Languages Now","Runs a serialized sweep of the currently detected enemy-language players using the built-in 9k bounty path.",function()
        startup.regional_warfare_force_bounty_scan()
    end)
    startup.install_regional_warfare_loop()
end
startup.install_regional_warfare_features()

