    startup.set_feature_float_silently(startup.h.SessionActivityBoxHeightScaleSlider, startup.s.sessionActivityBoxHeightScale or 1.15)
    startup.set_feature_float_silently(startup.h.SessionActivityTextYOffsetSlider, startup.s.sessionActivityTextYOffset)
    startup.set_feature_float_silently(startup.h.SessionActivityAccentHeightSlider, startup.s.sessionActivityAccentHeightRatio)
