-- dynamic startup controls
-- note: rebuilds lua and theme controls after each scan.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.create_dynamic_lua_features()
    startup.refresh_lua_file_list()
    for _, entry in ipairs(startup.s.luaFiles) do
        local oldRunHash = startup.hash("RUN_NOW_" .. tostring(entry.index) .. "_" .. entry.name)
        if FeatureMgr and FeatureMgr.RemoveFeature then
            FeatureMgr.RemoveFeature(oldRunHash)
            FeatureMgr.RemoveFeature(entry.hash)
        end
        if not FeatureMgr.GetFeature(entry.hash) then
            local feature = FeatureMgr.AddFeature(
                entry.hash,
                entry.name,
                eFeatureType.Toggle,
                "Run this Lua during the session startup flow. Select it to edit its delay in the left panel.",
                function(f)
                    startup.s.selectedLuaFilePath = entry.path
                    startup.s.luaFileStates[entry.path] = f:IsToggled()
                    if startup.s.initialized then startup.save_config(false) end
                end
            )
            if feature then
                feature:SetBoolValue(startup.s.luaFileStates[entry.path] == true)
                feature:SetSaveable(false)
            end
        end
    end
    startup.save_config(false)
end

function startup.create_dynamic_theme_features()
    startup.refresh_theme_file_list()
    for _, entry in ipairs(startup.s.themeFiles or {}) do
        if not FeatureMgr.GetFeature(entry.hash) then
            local key = entry.key or entry.name
            local feature = FeatureMgr.AddFeature(
                entry.hash,
                entry.displayName or entry.name,
                eFeatureType.Toggle,
                "Run on Startup Themes: allow Random Theme to choose this ClickGUI theme on next startup.",
                function(f)
                    startup.s.themeFileStates[key] = f:IsToggled()
                    if startup.s.initialized then
                        startup.save_config(false)
                    end
                end
            )
            if feature then
                feature:SetBoolValue(startup.s.themeFileStates[key] ~= false)
                feature:SetSaveable(false)
            end
        end
    end
end

function startup.render_theme_feature_list()
    if #startup.s.themeFiles == 0 then
        startup.warn_text("No theme .json files found.")
        ImGui.Text("Startup scans ClickGUI and all subfolders.")
        ImGui.Text("Refresh after adding or deleting themes.")
        return
    end
    local lastFolder = nil
    for _, entry in ipairs(startup.s.themeFiles or {}) do
        local folder = entry.folder or "ClickGUI Root"
        if folder ~= lastFolder then
            if lastFolder ~= nil and ImGui.Separator then ImGui.Separator() end
            startup.render_green_folder_header(folder)
            lastFolder = folder
        end
        if entry.hash then
            startup.render_feature_guarded_325(entry.hash)
        end
    end
end

