function startup.render_status_metric(label, value, r, g, b, tooltip)
    startup.text_colored(r or 0.72, g or 0.42, b or 1.00, 1.00, tostring(label or ""))
    startup.hover_help(tooltip)
    ImGui.TextWrapped(tostring(value or "-") )
end

function startup.refresh_cherax_tier_for_display(force)
    local now = startup.now()
    if not force and now - (startup.s.lastTierDisplayRefreshMs or 0) < 2500 then
        return startup.s.detectedCheraxTier or "Unknown"
    end
    startup.s.lastTierDisplayRefreshMs = now
    startup.resolve_session_type()
    return startup.s.detectedCheraxTier or "Unknown"
end

function startup.render_cherax_version_status()
    local tier = startup.refresh_cherax_tier_for_display(false)
    local lower = string.lower(tostring(tier or "Unknown"))
    local edition = tostring(startup.s.detectedCheraxGameEdition or "Unknown")
    local gameFamily = tostring(startup.s.detectedCheraxGameFamily or "Unknown")
    local battleye = tostring(startup.s.detectedBattleyeMode or "Unknown")

    startup.text_colored(0.42, 0.82, 1.00, 1.00, "Mode:")
    ImGui.SameLine()
    if string.find(lower, "prime", 1, true) then
        startup.text_colored(1.00, 0.52, 0.10, 1.00, tier)
    else
        startup.text_colored(0.72, 0.42, 1.00, 1.00, tier)
    end
    startup.hover_help("Automatic routing is based on the active Cherax edition, not which subscription tiers the account owns.")

    startup.text_colored(0.42, 0.82, 1.00, 1.00, "Game:")
    ImGui.SameLine()
    startup.subtle_text(gameFamily .. " (" .. edition .. ")")

    startup.text_colored(0.42, 0.82, 1.00, 1.00, "BattlEye:")
    ImGui.SameLine()
    if battleye == "ON" then
        startup.text_colored(1.00, 0.62, 0.16, 1.00, "ON")
    elseif battleye == "OFF" then
        startup.text_colored(0.30, 1.00, 0.45, 1.00, "OFF")
    else
        startup.subtle_text("Unknown")
    end

    startup.text_colored(0.42, 0.82, 1.00, 1.00, "Routing:")
    ImGui.SameLine()
    startup.subtle_text(tostring(startup.s.sessionRoutingMode or "Automatic"))
end

