function startup.render_player_population_link_buttons()
    local available = 0
    if ImGui and ImGui.GetContentRegionAvail then
        local x = ImGui.GetContentRegionAvail()
        if type(x) == "table" then
            available = tonumber(x.x or x.X or x[1] or 0) or 0
        else
            available = tonumber(x or 0) or 0
        end
    end
    local side_by_side = available >= 500
    local button_width = side_by_side and math.max(180, math.floor((available - 10) / 2)) or -1
    startup.render_color_button(
        "Enhanced SteamDB Chart",
        "Green",
        "Opens GTA V Enhanced's live one-week player chart on SteamDB.",
        function() startup.open_matchmaking_chart(startup.steamdb_enhanced_url, "Enhanced") end,
        button_width
    )
    if side_by_side then ImGui.SameLine() end
    startup.render_color_button(
        "Legacy SteamDB Chart",
        "Blue",
        "Opens GTA V Legacy's live one-week player chart on SteamDB.",
        function() startup.open_matchmaking_chart(startup.steamdb_legacy_url, "Legacy") end,
        button_width
    )
end


