function startup.render_color_button(label, scheme, tooltip, callback, width, height)
    if not ImGui or not ImGui.Button then return false end
    local colors = startup.button_colors[scheme or "Gray"] or startup.button_colors.Gray
    local pushed = 0
    if ImGui.PushStyleColor and ImGuiCol then
        local function push(key, color)
            if key ~= nil then
                ImGui.PushStyleColor(key, color[1], color[2], color[3], color[4])
                pushed = pushed + 1
            end
        end
        push(ImGuiCol.Button, colors.normal)
        push(ImGuiCol.ButtonHovered, colors.hover)
        push(ImGuiCol.ButtonActive, colors.active)
    end
    local clicked = ImGui.Button(tostring(label or "Button"), width or 0, height or 0) == true
    if pushed > 0 and ImGui.PopStyleColor then ImGui.PopStyleColor(pushed) end
    startup.hover_help(tooltip)
    if clicked and callback then callback() end
    return clicked
end

function startup.status_line(label, value, r, g, b, tooltip)
    startup.text_colored(r or 0.72, g or 0.72, b or 0.72, 1.00, tostring(label or "Status") .. ":")
    startup.hover_help(tooltip)
    ImGui.SameLine()
    if ImGui.TextWrapped then
        ImGui.TextWrapped(tostring(value or "Idle"))
    else
        ImGui.Text(tostring(value or "Idle"))
    end
end

function startup.push_minimal_tab_style()
    if not ImGui or not ImGui.PushStyleColor or not ImGuiCol then return 0 end
    local pushed = 0
    local function push(key, r, g, b, a)
        if key ~= nil then
            ImGui.PushStyleColor(key, r, g, b, a)
            pushed = pushed + 1
        end
    end
    push(ImGuiCol.Tab, 0.12, 0.10, 0.17, 0.95)
    push(ImGuiCol.TabHovered, 0.34, 0.22, 0.48, 1.00)
    push(ImGuiCol.TabActive, 0.26, 0.15, 0.40, 1.00)
    push(ImGuiCol.Header, 0.22, 0.14, 0.34, 0.90)
    push(ImGuiCol.HeaderHovered, 0.34, 0.22, 0.48, 1.00)
    push(ImGuiCol.HeaderActive, 0.40, 0.27, 0.56, 1.00)
    return pushed
end

function startup.pop_minimal_tab_style(count)
    count = tonumber(count or 0) or 0
    if count > 0 and ImGui and ImGui.PopStyleColor then ImGui.PopStyleColor(count) end
end

function startup.render_green_folder_header(label)
    startup.section_title("[Folder] " .. tostring(label or "Lua"))
end

function startup.render_lua_startup_list()
    local lastFolder = nil
    for _, entry in ipairs(startup.s.luaFiles or {}) do
        local folderLabel = startup.get_friendly_folder_label(entry.path)
        if folderLabel ~= lastFolder then
            if lastFolder ~= nil and ImGui.Separator then ImGui.Separator() end
            startup.render_green_folder_header(folderLabel)
            lastFolder = folderLabel
        end
        startup.render_feature_guarded_325(entry.hash)
        if ImGui.Button("Delay##lua_select_" .. tostring(entry.index)) then
            startup.s.selectedLuaFilePath = entry.path
            startup.save_config(false)
        end
        if tostring(startup.s.selectedLuaFilePath or "") == tostring(entry.path) then
            ImGui.SameLine()
            startup.subtle_text("Editing")
        end
    end
end

function startup.render_selected_lua_delay()
    local entry = startup.get_lua_file_entry(startup.s.selectedLuaFilePath)
    if not entry then
        startup.subtle_text("Select a Lua file from the right panel.")
        return
    end
    startup.section_title(entry.name)
    ImGui.Text("Startup: " .. startup.bool_text(startup.s.luaFileStates[entry.path] == true))
    ImGui.Text("")
    local custom = startup.is_lua_file_delay_overridden(entry.path)
    local effectiveMs = startup.get_lua_file_delay_ms(entry.path)
    ImGui.Text("Wait after this file: " .. startup.format_seconds(effectiveMs))
    if custom then
        startup.subtle_text("Using a script-specific delay")
        if ImGui.Button("Use Master Delay##lua_delay_master") then
            startup.set_lua_file_delay_override(entry.path, false)
        end
    else
        startup.subtle_text("Using the master delay")
        if ImGui.Button("Use Custom Delay##lua_delay_custom") then
            startup.set_lua_file_delay_override(entry.path, true)
        end
    end
    if startup.is_lua_file_delay_overridden(entry.path) then
        ImGui.Text("")
        if ImGui.Button("-5s##lua_delay_minus") then
            startup.set_lua_file_delay_ms(entry.path, effectiveMs - 5000)
        end
        ImGui.SameLine()
        ImGui.Text(startup.format_seconds(startup.get_lua_file_delay_ms(entry.path)))
        ImGui.SameLine()
        if ImGui.Button("+5s##lua_delay_plus") then
            startup.set_lua_file_delay_ms(entry.path, effectiveMs + 5000)
        end
    end
end

