function startup.render_regional_warfare()
    if not (ClickGUI and ImGui) then return end
    if ClickGUI.BeginCustomChildWindow("Regional Warfare") then
        startup.text_colored(1.00,0.55,0.12,1.00,"REGIONAL WARFARE")
        startup.subtle_text_wrapped("Language-based private-server warfare. Startup reads Cherax Player Language directly for each player. IP country/geolocation is not used by this mode.")
        if ImGui.Separator then ImGui.Separator() end
        startup.render_feature_guarded_325(startup.h.RegionalWarfareEnabled)
        startup.render_feature_guarded_325(startup.h.RegionalWarfareMyFaction)
        startup.render_feature_guarded_325(startup.h.RegionalWarfareEnemyPolicy)
        startup.render_feature_guarded_325(startup.h.RegionalWarfareAutoBounty)
        if startup.h.RegionalWarfareColorPlayers then
            startup.render_feature_guarded_325(startup.h.RegionalWarfareColorPlayers)
        end
        if startup.s.regionalWarfareColorPlayers ~= false and startup.regional_warfare_languages then
            if ImGui.CollapsingHeader and ImGui.CollapsingHeader("Player Marker Colors") == true then
                startup.subtle_text_wrapped("Locally recolors player minimap blips by detected Player Language. Chinese defaults to Blue. Each language can be changed independently.")
                if ImGui.BeginTable("StartupRegionalWarfareColorTable",2,ImGuiTableFlags.SizingStretchSame) then
                    local colorIndex=0
                    for _,language in ipairs(startup.regional_warfare_languages) do
                        if language ~= "Auto (Player Language)" then
                            if (colorIndex % 2) == 0 then ImGui.TableNextRow() end
                            ImGui.TableSetColumnIndex(colorIndex % 2)
                            local key="RegionalWarfareColor_"..startup.regional_warfare_feature_key(language)
                            startup.render_feature_guarded_325(startup.h[key])
                            colorIndex=colorIndex+1
                        end
                    end
                    ImGui.EndTable()
                end
            end
        end
        local own,ownSource=startup.regional_warfare_own_language()
        startup.subtle_text("My detected warfare language: "..tostring(own).." • "..tostring(ownSource))
        startup.subtle_text("Bounty engine: Cherax built-in 9k • serialized ~2.5s gap • 180s maintenance")
        startup.subtle_text_wrapped(tostring(startup.s.regionalWarfareLastStatus or "Ready."))
        if startup.s.regionalWarfareEnabled==true and startup.regional_warfare_normalize_language(own)=="Unknown" then
            startup.warn_text("Local Player Language could not be read. Choose My Warfare Language manually.")
        end
        if startup.s.regionalWarfareEnemyPolicy=="Selected Languages" then
            if ImGui.Separator then ImGui.Separator() end
            startup.text_colored(1.00,0.70,0.22,1.00,"SELECTED ENEMY LANGUAGES")
            if ImGui.BeginTable("StartupRegionalWarfareEnemyLanguageTable",3,ImGuiTableFlags.SizingStretchSame) then
                local index=0
                for _,language in ipairs(startup.regional_warfare_languages or {}) do
                    if language~="Auto (Player Language)" and language~="Unknown" then
                        if (index%3)==0 then ImGui.TableNextRow() end
                        ImGui.TableSetColumnIndex(index%3)
                        startup.render_feature_guarded_325(startup.h["RegionalWarfareEnemy_"..startup.regional_warfare_feature_key(language)])
                        index=index+1
                    end
                end
                ImGui.EndTable()
            end
        end
        ClickGUI.EndCustomChildWindow()
    end

    local open=true
    if ImGui.CollapsingHeader then open=ImGui.CollapsingHeader("Regional Warfare Language Roster")==true end
    if open and ClickGUI.BeginCustomChildWindow("Regional Warfare Language Roster") then
        startup.section_title("Live Language Roster")
        startup.subtle_text_wrapped("Read-only live view of Cherax Player Language. This is the exact team value Regional Warfare uses for automatic enemy bounties.")
        local rows=startup.regional_warfare_roster()
        if #rows==0 then
            startup.subtle_text("No remote players detected.")
        else
            local shown=0
            for _,row in ipairs(rows) do
                if shown>=32 then break end
                local status=row.language=="Unknown" and "UNKNOWN" or (row.enemy==true and "ENEMY" or "ALLY")
                if row.enemy==true then
                    startup.text_colored(1.00,0.48,0.16,1.00,tostring(row.name).." • "..tostring(row.language).." • "..status)
                elseif row.language=="Unknown" then
                    startup.subtle_text(tostring(row.name).." • Unknown • UNKNOWN")
                else
                    startup.subtle_text(tostring(row.name).." • "..tostring(row.language).." • "..status)
                end
                shown=shown+1
            end
        end
        if ImGui.Separator then ImGui.Separator() end
        startup.render_feature_guarded_325(startup.h.RegionalWarfareBountyNow)
        if tostring(startup.s.regionalWarfareLastBountyPlayer or "")~="" then
            startup.subtle_text("Last bounty: "..tostring(startup.s.regionalWarfareLastBountyPlayer).." • "..tostring(startup.s.regionalWarfareLastBountyFaction or ""))
        end
        ClickGUI.EndCustomChildWindow()
    end
end

function startup.render_defense()
    local open = false
    if ImGui.CollapsingHeader then
        open = ImGui.CollapsingHeader("Protection & Player History") == true
    elseif ImGui.Button then
        startup.s.protectionSectionOpen = startup.s.protectionSectionOpen == true
        if ImGui.Button((startup.s.protectionSectionOpen and "▼" or "▶") .. "  Protection & Player History", -1, 34) == true then startup.s.protectionSectionOpen = not startup.s.protectionSectionOpen end
        open = startup.s.protectionSectionOpen == true
    else
        open = true
    end
    if not open then return end
    if ImGui.BeginTable("StartupProtectionTable", 2, ImGuiTableFlags.SizingStretchSame) then
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0)
        if ClickGUI.BeginCustomChildWindow("Battleye Detection") then
            startup.section_title("Battleye Detection")
            startup.render_feature_guarded_325(startup.h.BattleyeAutoBlockEnabled)
            startup.render_feature_guarded_325(startup.h.BattleyeFallbackDelaySlider)
