startup.start_session_hotkey_options = startup.start_session_hotkey_options or (function()
    local options = {
        { name = "Disabled", code = 0x00 },
        { name = "Pause / Break", code = 0x13 },
        { name = "Insert", code = 0x2D },
        { name = "Delete", code = 0x2E },
        { name = "Home", code = 0x24 },
        { name = "End", code = 0x23 },
        { name = "Page Up", code = 0x21 },
        { name = "Page Down", code = 0x22 },
        { name = "Scroll Lock", code = 0x91 },
        { name = "Num Lock", code = 0x90 },
        { name = "Caps Lock", code = 0x14 },
        { name = "Escape", code = 0x1B },
        { name = "Space", code = 0x20 },
        { name = "Enter", code = 0x0D },
        { name = "Tab", code = 0x09 },
        { name = "Backspace", code = 0x08 },
        { name = "Left Shift", code = 0xA0 },
        { name = "Right Shift", code = 0xA1 },
        { name = "Left Ctrl", code = 0xA2 },
        { name = "Right Ctrl", code = 0xA3 },
        { name = "Left Alt", code = 0xA4 },
        { name = "Right Alt", code = 0xA5 },
        { name = "Left Arrow", code = 0x25 },
        { name = "Up Arrow", code = 0x26 },
        { name = "Right Arrow", code = 0x27 },
        { name = "Down Arrow", code = 0x28 },
    }
    for i = 1, 12 do options[#options + 1] = { name = "F" .. tostring(i), code = 0x6F + i } end
    for i = 0, 9 do options[#options + 1] = { name = "Numpad " .. tostring(i), code = 0x60 + i } end
    options[#options + 1] = { name = "Numpad *", code = 0x6A }
    options[#options + 1] = { name = "Numpad +", code = 0x6B }
    options[#options + 1] = { name = "Numpad -", code = 0x6D }
    options[#options + 1] = { name = "Numpad .", code = 0x6E }
    options[#options + 1] = { name = "Numpad /", code = 0x6F }
    for i = 0, 9 do options[#options + 1] = { name = tostring(i), code = 0x30 + i } end
    for i = 0, 25 do options[#options + 1] = { name = string.char(65 + i), code = 0x41 + i } end
    return options
end)()

function startup.get_start_session_hotkey_option(code)
    code = tonumber(code or 0) or 0
    for index, option in ipairs(startup.start_session_hotkey_options or {}) do
        if tonumber(option.code or -1) == code then return option, index end
    end
    return (startup.start_session_hotkey_options or {})[2], 2
end

function startup.clear_feature_hotkeys(feature, hash)
    if feature and feature.ClearHotkeys then
        feature:ClearHotkeys()
        return true
    end
    if HotKeyMgr and HotKeyMgr.GetHotKeys and HotKeyMgr.RemoveHotkey then
        local keys = HotKeyMgr.GetHotKeys(hash)
        for _, key in pairs(type(keys) == "table" and keys or {}) do HotKeyMgr.RemoveHotkey(hash, key) end
        return true
    end
    return false
end

function startup.apply_start_session_hotkey(showToast)
    if not startup.h.StartSession then return false end
    local feature = FeatureMgr and FeatureMgr.GetFeature and FeatureMgr.GetFeature(startup.h.StartSession) or nil
    if not feature then
        startup.s.startSessionHotkeyLastStatus = "Start Session feature unavailable"
        return false
    end
    startup.clear_feature_hotkeys(feature, startup.h.StartSession)
    local code = startup.clamp_int(startup.s.startSessionHotkeyKeyCode or 0x13, 0, 255)
    local option = startup.get_start_session_hotkey_option(code)
    startup.s.startSessionHotkeyName = option and option.name or tostring(code)
    if code == 0 then
        startup.s.startSessionHotkeyLastStatus = "Disabled"
        if showToast then startup.toast("Start Session hotkey disabled.", 2500) end
        return true
    end
    local applied = false
    if feature.AddHotKey then
        feature:AddHotKey(code)
        applied = true
    elseif HotKeyMgr and HotKeyMgr.AddHotkey then
        HotKeyMgr.AddHotkey(startup.h.StartSession, code)
        applied = true
    end
    if applied then
        startup.s.startSessionHotkeyLastStatus = "Start Session: " .. tostring(startup.s.startSessionHotkeyName)
        if showToast then startup.toast("Start Session hotkey: " .. tostring(startup.s.startSessionHotkeyName), 2500) end
    else
        startup.s.startSessionHotkeyLastStatus = "Could not apply " .. tostring(startup.s.startSessionHotkeyName)
        if showToast then startup.error(startup.s.startSessionHotkeyLastStatus) end
    end
    return applied
end

function startup.render_start_session_hotkey_config()
    if not ClickGUI.BeginCustomChildWindow("Start Session Hotkey") then return end
    startup.text_colored(1.00, 0.55, 0.12, 1.00, "START SESSION HOTKEY")
    startup.subtle_text("Default: Pause / Break")
    ImGui.Separator()
    local currentOption, currentIndex = startup.get_start_session_hotkey_option(startup.s.startSessionHotkeyKeyCode)
    local opened = ImGui.BeginCombo and ImGui.BeginCombo("Keyboard Key", tostring(currentOption and currentOption.name or "Pause / Break")) == true
    startup.hover_help("Choose the one keyboard key that triggers Start Session. The selection applies immediately and saves automatically.")
    if opened then
        for index, option in ipairs(startup.start_session_hotkey_options or {}) do
            if ImGui.Selectable(tostring(option.name), index == currentIndex) == true then
                startup.s.startSessionHotkeyKeyCode, startup.s.startSessionHotkeyName = option.code, option.name
                startup.apply_start_session_hotkey(false)
                startup.save_config(false)
                currentOption, currentIndex = option, index
            end
        end
        if ImGui.EndCombo then ImGui.EndCombo() end
    end
    ImGui.Text("")
    if tonumber(startup.s.startSessionHotkeyKeyCode or 0) == 0 then
        startup.warn_text("Current: Disabled")
    else
        startup.text_colored(0.30, 1.00, 0.45, 1.00, "Current: " .. tostring(startup.s.startSessionHotkeyName or "Pause / Break"))
    end
    startup.subtle_text(tostring(startup.s.startSessionHotkeyLastStatus or "Not applied yet"))
    startup.render_color_button("Reset to Pause / Break", "Gold", "Restores Pause / Break as the Start Session hotkey and saves it now.", function()
        startup.s.startSessionHotkeyKeyCode, startup.s.startSessionHotkeyName = 0x13, "Pause / Break"
        startup.apply_start_session_hotkey(true)
        startup.save_config(false)
    end, -1)
    ClickGUI.EndCustomChildWindow()
end

function startup.render_config()
    startup.render_start_session_hotkey_config()
    if startup.render_cancel_startup_hop_hotkey_config then startup.render_cancel_startup_hop_hotkey_config() end
    if ImGui.BeginTable("StartupConfigTable", 2, ImGuiTableFlags.SizingStretchSame) then
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0)
        if ClickGUI.BeginCustomChildWindow("Storage") then
            ImGui.Text("Config:")
            ImGui.TextWrapped(tostring(startup.s.activeConfigFile or startup.config_file))
            ImGui.Text("")
            ImGui.Text("Startup Folder:")
            ImGui.TextWrapped(startup.storage_dir)
            ImGui.Text("")
            ImGui.Text("Themes:")
            ImGui.TextWrapped(startup.menu_root .. "\\Theme\\ClickGUI")
            ImGui.Text("")
            startup.render_feature_guarded_325(startup.h.OpenStartupFolder)
            startup.render_feature_guarded_325(startup.h.CopyStartupFolderPath)
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.TableSetColumnIndex(1)
        if ClickGUI.BeginCustomChildWindow("Settings") then
            startup.render_feature_guarded_325(startup.h.SaveConfig)
            startup.render_feature_guarded_325(startup.h.LoadConfig)
            startup.render_feature_guarded_325(startup.h.SessionRoutingMode)
            startup.render_feature_guarded_325(startup.h.PrimeHostSessionsEnabled)
            startup.render_feature_guarded_325(startup.h.CompactPinnedStartupTab)
            startup.render_feature_guarded_325(startup.h.ShowStatusPanel)
            startup.render_feature_guarded_325(startup.h.ShowTipsPanel)
            startup.render_feature_guarded_325(startup.h.VerboseStartupLogs)
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.EndTable()
    end

    -- Build 224: Advertising Timer History is intentionally no longer shown in Config.

    -- Build 218: Public_Urinal account/services identity panel placed before Cherax Settings Profile.
    if ClickGUI.BeginCustomChildWindow("Public_Urinal Account") then
        startup.section_title("Public_Urinal Account")
        startup.subtle_text_wrapped("Startup automatically maintains a Public_Urinal account for identity, Browser services, moderation, security, and service statistics. Account history may persist across reinstalls to prevent abuse or moderation evasion.")
        ImGui.Separator()

        local bb = startup.browser_backend or {}
        local puUid = tostring(bb.startup_uid or "")
        if puUid == "" then puUid = "Connecting..." end

        local cheraxMasked = "Unavailable"
        if Cherax and Cherax.GetUID then
            local ok, value = direct_call(Cherax.GetUID)
            local raw = ok and tostring(value or "") or ""
            raw = raw:match("^(%d+)$") or ""
            if raw ~= "" then
                local suffix = #raw > 4 and raw:sub(-4) or raw
                cheraxMasked = "••••••" .. suffix
            end
        end

        local linkedRockstar = tonumber(bb.rockstar_accounts or 0) or 0
        local accountStatus = tostring(bb.account_status or "")
        if accountStatus == "" then accountStatus = bb.token and bb.token ~= "" and "Active" or "Connecting..." end
        if accountStatus == "ACTIVE" then accountStatus = "Active" end

        local termsAccepted = tostring(startup.s.browserTermsAcceptedVersion or "") == tostring(startup.browser_terms_version or "")
        local moderationState = tostring((startup.browser_effective_moderation_state and startup.browser_effective_moderation_state()) or bb.browser_moderation or "ACTIVE"):upper()
        local browserAccess = tostring(bb.product_access or "")
        if not termsAccepted then
            browserAccess = "Terms Required"
        elseif moderationState == "WARNED" then
            browserAccess = "Warned"
        elseif moderationState == "TEMP_SUSPENDED" then
            browserAccess = "Temporarily Suspended"
        elseif moderationState == "BANNED" then
            browserAccess = "Banned"
        elseif browserAccess == "ACTIVE" then browserAccess = "Active"
        elseif browserAccess == "" then browserAccess = bb.token and bb.token ~= "" and "Active" or "Connecting..." end

        startup.text_colored_wrapped(0.72, 0.42, 1.00, 1.00, "Public_Urinal UID: " .. puUid)
        startup.text_colored(0.42, 0.82, 1.00, 1.00, "Cherax UID: " .. cheraxMasked)
        if linkedRockstar > 0 then
            startup.text_colored(0.42, 0.82, 1.00, 1.00, "Rockstar Accounts: " .. tostring(linkedRockstar) .. " linked")
        else
            startup.subtle_text("Rockstar Accounts: linked identity pending")
        end
        startup.text_colored(0.35, 1.00, 0.45, 1.00, "Account Status: " .. accountStatus)
        if browserAccess == "Active" then
            startup.text_colored(0.35, 1.00, 0.45, 1.00, "Browser Access: Active")
        elseif browserAccess == "Warned" then
            startup.text_colored(1.00, 0.78, 0.25, 1.00, "Browser Access: Warned")
        elseif browserAccess == "Terms Required" then
            startup.text_colored(1.00, 0.78, 0.25, 1.00, "Browser Access: Terms Required")
        else
            startup.text_colored(1.00, 0.30, 0.30, 1.00, "Browser Access: " .. browserAccess)
        end
        if moderationState ~= "ACTIVE" and tostring(bb.browser_moderation_message or "") ~= "" then
            startup.subtle_text_wrapped("Moderation: " .. tostring(bb.browser_moderation_message))
        end
        if moderationState == "TEMP_SUSPENDED" and tostring(bb.browser_moderation_expires_at or "") ~= "" then
            startup.subtle_text_wrapped("Suspension expires: " .. tostring(bb.browser_moderation_expires_at) .. " UTC")
        end
        ImGui.Text("")
        -- Build 224: Session Safety is core Browser behavior and is no longer exposed as
        -- an ambiguous user toggle. The underlying safety/voting protections stay enabled.
        startup.s.browserSessionSafetyEnabled = true
        startup.render_color_button("VIEW TERMS & DATA NOTICE", "Purple", "Review Startup Browser's short Terms & Data Notice.", function()
            if startup.browser_request_terms_popup then startup.browser_request_terms_popup(true) end
        end, -1, 28)
        ClickGUI.EndCustomChildWindow()
    end

    if ClickGUI.BeginCustomChildWindow("Cherax Settings Profile") then
        startup.section_title("Cherax Settings Profile")
        startup.subtle_text("Choose the saved Cherax settings JSON Startup should load. No specific filename is required.")
        ImGui.Separator()
        local profiles = startup.s.settingsProfiles or {}
        local current = tostring(startup.s.settingsFile or "")
        local preview = current ~= "" and current or "Select saved settings..."
        local openedProfiles = ImGui.BeginCombo and ImGui.BeginCombo("Saved Settings", preview) == true
        if openedProfiles then
            for _, profile in ipairs(profiles) do
                local selected = startup.settings_profile_names_match(profile, current)
                if ImGui.Selectable(tostring(profile), selected) == true then
                    startup.select_settings_profile(profile, true)
                    current = tostring(profile)
                end
            end
            if ImGui.EndCombo then ImGui.EndCombo() end
        end
        if #profiles == 0 then
            if current ~= "" then
                startup.text_colored(0.35, 1.00, 0.45, 1.00, "Current profile: " .. current)
                startup.subtle_text("Startup can still load this profile even when Cherax does not provide a saved-profile list.")
            else
                startup.text_colored(1.00, 0.78, 0.25, 1.00, tostring(startup.s.settingsProfilesStatus or "No saved settings profiles found."))
            end
        else
            startup.text_colored(0.35, 1.00, 0.45, 1.00, "Selected: " .. (current ~= "" and current or "None"))
            startup.subtle_text(tostring(startup.s.settingsProfilesStatus or ""))
        end
        startup.render_feature_guarded_325(startup.h.RefreshSettingsProfiles)
        startup.render_feature_guarded_325(startup.h.ApplySettingsNow)
        ClickGUI.EndCustomChildWindow()
    end

    -- Build 224: Self Diagnosis and the Questionnaire Test Preset now live in Config.
    startup.render_self_diagnostics_panel()

    if ClickGUI.BeginCustomChildWindow("Support & Diagnostics") then
        startup.text_colored(1.00, 0.78, 0.25, 1.00, "SUPPORT & DIAGNOSTICS")
        startup.text_colored(0.35, 1.00, 0.45, 1.00, "Automatic diagnostics: Enabled")
        startup.subtle_text("Runtime state is refreshed into Startup\\Support\\SUPPORT_INFO.txt for support captures.")
        ImGui.Separator()
        startup.render_feature_guarded_325(startup.h.CreateSupportZip)
        startup.render_feature_guarded_325(startup.h.CopySupportZipPath)
        startup.render_feature_guarded_325(startup.h.OpenStartupFolder)
        startup.render_feature_guarded_325(startup.h.CopyStartupFolderPath)
        startup.render_feature_guarded_325(startup.h.OpenSupportDiscord)
        ImGui.Text("")

        local supportStatus = startup.get_compact_support_zip_status()
        if supportStatus == "Created! Path copied." or supportStatus == "Created! Path not copied." then
            startup.text_colored(0.35, 1.00, 0.45, 1.00, "Support ZIP: " .. tostring(supportStatus))
        elseif string.find(tostring(supportStatus), "Creating", 1, true) then
            startup.text_colored(1.00, 0.78, 0.25, 1.00, "Support ZIP: " .. tostring(supportStatus))
        elseif string.find(tostring(supportStatus), "Failed", 1, true) then
            startup.text_colored(1.00, 0.35, 0.25, 1.00, "Support ZIP: " .. tostring(supportStatus))
        else
            startup.text_colored(0.42, 0.82, 1.00, 1.00, "Support ZIP: " .. tostring(supportStatus))
        end

        startup.subtle_text("ZIP output: " .. tostring(startup.s.supportZipOutputMode or "Primary Startup folder"))
        startup.subtle_text("Exact path: " .. tostring(startup.s.lastSupportZipPath or startup.SupportZipPath or ""))
        if startup.support_file_exists(startup.refresh_cherax_log_path()) then
            startup.text_colored(0.35, 1.00, 0.45, 1.00, "Cherax.log: Included")
        else
            startup.text_colored(1.00, 0.78, 0.25, 1.00, "Cherax.log: Not found")
        end
        local _, dedicatedSupport = startup.get_support_discord_link()
        if dedicatedSupport then
            startup.text_colored(0.42, 0.82, 1.00, 1.00, "Discord: Dedicated Startup support")
        else
            startup.subtle_text("Discord: Community fallback")
        end

        ImGui.Text("")
        startup.text_colored(1.00, 0.78, 0.25, 1.00, "Privacy")
        if ImGui.TextWrapped then
            ImGui.TextWrapped("Support ZIPs may contain player names, Rockstar IDs, IP addresses, local file paths, and other diagnostic/session information. Upload them only to a trusted support channel.")
        else
            ImGui.Text("Support ZIPs may contain private diagnostic/session information. Upload only to trusted support.")
        end
        ClickGUI.EndCustomChildWindow()
    end

    -- Build 291: Browser trust/privacy belongs at the bottom of Config, immediately
    -- above Reset & Recovery. Whitelist is intentionally shown before Blacklist.
    if startup.render_browser_trust_config_build291 then
        startup.render_browser_trust_config_build291()
    end

    -- Keep recovery controls visually separate and at the very bottom of Config.
    if ClickGUI.BeginCustomChildWindow("Reset & Recovery") then
        startup.section_title("Reset & Recovery")
        startup.subtle_text("Restore Startup's saved configuration without deleting any scripts, themes, or Cherax settings files.")
        ImGui.Separator()
        startup.render_color_button(
            "RESET SETTINGS",
            "Gold",
            "Resets Startup toggles, routing, hotkey, HUD layout, advertising values, Lua selections/delays, and theme preferences. The completed onboarding state is preserved.",
            startup.open_reset_settings_confirmation,
            -1
        )
        if ImGui.TextWrapped then
            ImGui.TextWrapped("This overwrites Startup's saved config with defaults. It does not delete Lua files, theme files, the selected Cherax settings profile, or reset completed onboarding.")
        else
            ImGui.Text("Resets Startup config only; files and onboarding completion are preserved.")
        end
        ClickGUI.EndCustomChildWindow()
    end

end

function startup.render_tip_row(index, tip)
    if type(tip) == "function" then
        local ok, resolved = direct_call(tip)
        tip = ok and resolved or "Time-of-day estimate unavailable."
    end
    startup.text_colored(0.72, 0.42, 1.00, 1.00, tostring(index) .. ".")
    ImGui.SameLine()
    if ImGui.TextWrapped then
        ImGui.TextWrapped(tostring(tip or ""))
    else
        ImGui.Text(tostring(tip or ""))
    end
    startup.hover_help("Tip " .. tostring(index))
end

function startup.render_tips()
    if not startup.s.showTipsPanel then return end
    if ClickGUI.BeginCustomChildWindow("Tips") then
        startup.section_title("Tips")
        startup.subtle_text("Setup, matchmaking, and startup reminders")
        ImGui.Separator()
        local sections = startup.tip_sections or {}
        local globalIndex = 0
        if #sections > 0 then
            for sectionIndex, section in ipairs(sections) do
                local c = section.color or {0.72, 0.42, 1.00}
                startup.text_colored(c[1], c[2], c[3], 1.00, tostring(section.name or "Tips"))
                startup.hover_help(tostring(section.help or ""))
                ImGui.Separator()
                for _, tip in ipairs(section.tips or {}) do
                    globalIndex = globalIndex + 1
                    startup.render_tip_row(globalIndex, tip)
                    if ImGui.Spacing then ImGui.Spacing() end
                end
                if sectionIndex < #sections then
                    ImGui.Separator()
                    if ImGui.Spacing then ImGui.Spacing() end
                end
            end
        else
            for i, tip in ipairs(startup.tips or {}) do
                startup.render_tip_row(i, tip)
                if i < #(startup.tips or {}) and ImGui.Spacing then ImGui.Spacing() end
            end
        end
        ClickGUI.EndCustomChildWindow()
    end
end
