function startup.render_setup_step_settings()
    startup.section_title("Choose your saved Cherax settings")
    startup.subtle_text("Choose the Cherax settings profile Startup should load.")
    ImGui.Separator()

    local profiles = startup.s.settingsProfiles or {}
    local selected = tostring(startup.popup_flow.settingsFile or "")

    if #profiles > 0 then
        startup.text_colored(0.42, 0.82, 1.00, 1.00, "CLICK A PROFILE BELOW TO SELECT IT")
        local childOpened = true
        if ImGui.BeginChild then
            -- Build 330: keep first-run setup usable at smaller resolutions. The old
            -- fixed 170px profile box left a huge empty area for users with only one
            -- saved profile and pushed CONTINUE below the popup fold. Show up to three
            -- compact rows, then scroll if more profiles exist.
            local flags = 0
            local visibleProfileRows = math.min(#profiles, 3)
            local profileListHeight = math.min(112, math.max(68, 12 + (visibleProfileRows * 40)))
            if ImGuiWindowFlags and ImGuiWindowFlags.AlwaysVerticalScrollbar and #profiles > 3 then
                flags = ImGuiWindowFlags.AlwaysVerticalScrollbar
            end
            childOpened = ImGui.BeginChild("##Startup_Setup_Settings_Profile_List", 0, profileListHeight, true, flags) == true
        end
        if childOpened then
            for _, profile in ipairs(profiles) do
                local profileName = tostring(profile or "")
                local isSelected = startup.settings_profile_names_match(profileName, selected)
                local buttonLabel = isSelected and ("✓  " .. profileName) or profileName
                startup.render_color_button(buttonLabel, isSelected and "Green" or "Blue",
                    "Select " .. profileName .. " as the Cherax settings JSON Startup loads.", function()
                        startup.popup_flow.settingsFile = profileName
                        startup.popup_flow.autoLoadSettings = true
                    end, -1, 34)
            end
        end
        if ImGui.BeginChild and ImGui.EndChild then ImGui.EndChild() end

        selected = tostring(startup.popup_flow.settingsFile or "")
        if selected ~= "" then
            startup.text_colored(0.35, 1.00, 0.45, 1.00, "Selected: " .. selected)
        else
            startup.text_colored(1.00, 0.78, 0.25, 1.00, "No profile selected yet.")
        end
        startup.subtle_text(tostring(startup.s.settingsProfilesStatus or "Saved profiles ready."))
    else
        startup.text_colored(1.00, 0.78, 0.25, 1.00, tostring(startup.s.settingsProfilesStatus or "No saved settings profiles found."))
        if ImGui.TextWrapped then
            ImGui.TextWrapped("Save a profile in Cherax, then click Refresh List.")
        end

        local fallbackProfile = tostring(selected or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if fallbackProfile == "" then
            fallbackProfile = tostring(startup.s.settingsFile or ""):gsub("^%s+", ""):gsub("%s+$", "")
        end
        if fallbackProfile == "" then fallbackProfile = "default.json" end

        startup.render_color_button("USE " .. string.upper(fallbackProfile), "Green",
            "Use " .. fallbackProfile .. " as the saved Cherax settings profile.", function()
                startup.popup_flow.settingsFile = fallbackProfile
                startup.popup_flow.autoLoadSettings = true
            end, -1, 36)
    end

    -- Build 330: CONTINUE belongs at the action row, not below the fold. Re-read
    -- the selected profile and place the primary action directly beside REFRESH LIST.
    selected = tostring(startup.popup_flow.settingsFile or "")
    startup.render_color_button("REFRESH LIST", "Blue", "Refreshes the saved Cherax settings list.", function()
        startup.queue_settings_profile_refresh(true)
    end, 190, 36)
    if ImGui.SameLine then ImGui.SameLine() end
    if selected ~= "" then
        startup.render_color_button("CONTINUE", "Green", "Use " .. selected .. " and continue to Auto Start setup.", function()
            startup.popup_flow.autoLoadSettings = true
            startup.popup_flow.step = 3
        end, -1, 36)
    else
        startup.render_color_button("CONTINUE WITHOUT AUTO-LOAD", "Gold", "Turns Auto-Load Settings OFF. You can choose a profile later from Config.", function()
            startup.popup_flow.autoLoadSettings = false
            startup.popup_flow.settingsFile = ""
            startup.popup_flow.step = 3
        end, -1, 36)
    end

    ImGui.Text("")
    startup.render_color_button("BACK", "Blue", "Return to Cherax tier selection.", function() startup.popup_flow.step = 1 end, 130, 36)
end

