function startup.render_whats_new_popup()
    -- Full public version history. Keep this user-facing and avoid internal implementation noise.
    local popup_logo_anchor_y = startup.credits_get_cursor_pos_y()
    startup.render_popup_logo_right(popup_logo_anchor_y, 112, 112)
    startup.popup_scaled_text("WHAT'S NEW", 1.36, 0.86, 0.56, 1.00, 1.00, false)
    startup.popup_scaled_text(tostring(startup.version) .. "  •  Build " .. tostring(startup.build_number), 0.88, 0.35, 0.86, 1.00, 1.00, false)
    startup.popup_scaled_text("Version highlights  •  v1.0.0 to v1.0.12", 0.82, 0.68, 0.68, 0.70, 1.00, false)
    local current_y = startup.credits_get_cursor_pos_y()
    startup.credits_set_cursor_pos_y(math.max(current_y, popup_logo_anchor_y + 118))
    ImGui.Text("")

    local availableY = 330
    if ImGui and ImGui.GetContentRegionAvail then
        local ax, ay = ImGui.GetContentRegionAvail()
        if type(ax) == "table" then availableY = tonumber(ax.y or ax.Y or ax[2] or availableY) or availableY
        else availableY = tonumber(ay or availableY) or availableY end
    end
    local notesHeight = math.max(185, math.min(330, availableY - 78))
    local opened = startup.first_run_begin_card("##Startup_Whats_New", notesHeight, true)
    if opened then
        for i, item in ipairs(startup.whats_new_items or {}) do
            local titleR, titleG, titleB = 0.78, 0.62, 1.00
            if type(item.color) == "table" then
                titleR = tonumber(item.color[1] or titleR) or titleR
                titleG = tonumber(item.color[2] or titleG) or titleG
                titleB = tonumber(item.color[3] or titleB) or titleB
            elseif i == 1 then
                titleR, titleG, titleB = 0.35, 1.00, 0.45
            end
            startup.popup_scaled_text(tostring(item.title or "Update"), 1.04, titleR, titleG, titleB, 1.00, false)

            for _, bullet in ipairs(item.bullets or {}) do
                startup.popup_scaled_text("• " .. tostring(bullet or ""), 0.88, 0.78, 0.78, 0.80, 1.00, true)
            end

            if item.warning and tostring(item.warning) ~= "" then
                startup.popup_scaled_text(tostring(item.warning), 0.86, 1.00, 0.32, 0.32, 1.00, true)
            end

            if i < #(startup.whats_new_items or {}) then ImGui.Text("") end
        end
        startup.first_run_end_card()
    end

    ImGui.Text("")
    if startup.popup_flow.simulation == true then
        startup.popup_scaled_text("Simulation only • nothing will be saved", 0.84, 1.00, 0.78, 0.18, 1.00, false)
    else
        startup.popup_scaled_text("Scroll through every release. Continue remembers this build.", 0.82, 0.68, 0.68, 0.70, 1.00, false)
    end

    startup.render_color_button("CONTINUE", "Green", "Continue from the update notes.", function()
        local simulation = startup.popup_flow.simulation == true
        if not simulation then
            startup.queue_whats_new_acknowledgement(false)
            if startup.browser_terms_accepted and not startup.browser_terms_accepted() then
                local primeBlocked=startup.browser_prime_access_blocked and startup.browser_prime_access_blocked()==true
                local hostToolsBlocked=startup.browser_hosttools_access_blocked_326 and startup.browser_hosttools_access_blocked_326()==true
                if not primeBlocked and not hostToolsBlocked then
                    -- Same guided window, next frame: What's New -> Terms & Data Notice.
                    startup.popup_flow.stage="browser_terms"
                    startup.popup_flow.mode="update_terms"
                    startup.popup_flow.step=0
                    startup.s.updateFlowSimulation=false
                    return
                elseif hostToolsBlocked then
                    -- Browser is intentionally blocked until Host Tools unloads. Keep one
                    -- deferred auto-prompt so Terms can appear after the conflict clears.
                    startup.pending_browser_terms_online_329=true
                end
            end
        end
        startup.s.updateFlowSimulation = false
        startup.popup_flow.active = false
    end, -1, 38)
end

function startup.render_setup_popup()
    startup.render_popup_header("STARTUP SETUP", "Four quick choices, then Startup is ready.", startup.popup_flow.simulation and "SIMULATION" or (startup.popup_flow.mode == "update" and "UPDATE SETUP" or "FIRST RUN"))
    ImGui.Separator()
    startup.render_setup_progress()
    ImGui.Separator()
    if startup.popup_flow.step == 1 then startup.render_setup_step_tier()
    elseif startup.popup_flow.step == 2 then startup.render_setup_step_settings()
    elseif startup.popup_flow.step == 3 then startup.render_setup_step_auto_start()
    else startup.render_setup_step_discord() end
end

function startup.keep_first_run_welcome_active()
    if not startup.popup_flow or startup.popup_flow.active ~= true then return end
    local now = startup.now()
    if now - (tonumber(startup.s.firstRunWelcomeLastForceOpenMs or 0) or 0) < 750 then return end
    startup.s.firstRunWelcomeLastForceOpenMs = now
    if GUI and GUI.IsOpen and GUI.Toggle and GUI.IsOpen() ~= true then GUI.Toggle() end
end

function startup.render_first_run_welcome()
    if not startup.popup_flow or startup.popup_flow.active ~= true then return end
    if not ImGui or not ImGui.Begin or not ImGui.End then return end

    local screen_w, screen_h = startup.get_display_size()
    local isSetup = startup.popup_flow.stage == "setup"
    local targetScale = isSetup and (tonumber(startup.first_run_setup_dpi_scale or 1.20) or 1.20) or 1.0
    local baseWidth = math.min(880, math.max(640, screen_w - 100))
    local baseHeight = math.min(650, math.max(520, screen_h - 90))
    local unscaledWidth = baseWidth * 0.90
    local unscaledHeight = baseHeight * 0.90

    -- Build 331: B330 used a 0.80 setup scale. A 1.20 target is exactly 50%
    -- larger than that layout, but never allow the guided window to extend past
    -- an 18px safety margin on any display. On smaller resolutions the scale
    -- automatically backs down only as much as required to remain fully usable.
    local maxWidth = math.max(320, screen_w - 36)
    local maxHeight = math.max(300, screen_h - 36)
    local minWidth = math.min(500, maxWidth)
    local minHeight = math.min(410, maxHeight)
    local fitScaleW = maxWidth / math.max(1, unscaledWidth)
    local fitScaleH = maxHeight / math.max(1, unscaledHeight)
    local dpiScale = isSetup and math.min(targetScale, fitScaleW, fitScaleH) or 1.0
    if isSetup then dpiScale = math.max(0.50, dpiScale) end

    local width = math.min(maxWidth, math.max(minWidth, math.floor(unscaledWidth * dpiScale)))
    local height = math.min(maxHeight, math.max(minHeight, math.floor(unscaledHeight * dpiScale)))
    local pos_x = math.max(18, (screen_w - width) * 0.5)
    local pos_y = math.max(18, (screen_h - height) * 0.5)
    if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(pos_x, pos_y, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(width, height, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowFocus then ImGui.SetNextWindowFocus() end

    startup.popup_current_dpi_scale = dpiScale
    local colors, vars = startup.push_first_run_style(dpiScale)
    local visible = ImGui.Begin("##Startup_Guided_Popup", true, startup.first_run_window_flags())
    if visible then
        if ImGui.SetWindowFontScale then ImGui.SetWindowFontScale(dpiScale) end
        if startup.popup_flow.stage == "whats_new" then startup.render_whats_new_popup()
        elseif startup.popup_flow.stage == "browser_terms" and startup.render_browser_terms_guided_329 then startup.render_browser_terms_guided_329()
        else startup.render_setup_popup() end
        if ImGui.SetWindowFontScale then ImGui.SetWindowFontScale(1.0) end
    end
    ImGui.End()
    startup.popup_current_dpi_scale = 1.0
    startup.pop_first_run_style(colors, vars)
end

