        local bodyH=math.max(170,height-245); local flags=ImGuiWindowFlags and ImGuiWindowFlags.AlwaysVerticalScrollbar or 0; local child=true
        if ImGui.BeginChild then child=ImGui.BeginChild("##SelfDiagBody",0,bodyH,true,flags)==true end
