            startup.status_line("NAT",tostring(n.nat or "Unknown"),0.42,0.82,1.00); startup.status_line("Country",tostring(ip.country or "Unknown"),0.72,0.72,0.72); startup.status_line("City",tostring(ip.city or "Unknown"),0.72,0.72,0.72); startup.status_line("ISP",tostring(ip.isp~="" and ip.isp or "Unknown"),0.72,0.72,0.72); startup.subtle_text_wrapped("CGNAT is never guessed as confirmed: "..tostring(n.cgnat or "not tested"))
            ImGui.Separator(); startup.section_title("4-Minute Session Hops")
            for i=1,tonumber(startup.self_diag.hopTarget or 3) do local h=startup.self_diag.hops and startup.self_diag.hops[i] or nil; if h then local ratio=h.directRatio and string.format("%.0f%% direct",h.directRatio) or "direct pending"; startup.subtle_text_wrapped("Hop "..i..": start "..tostring(h.startPlayers or 0).." | peak "..tostring(h.peakPlayers or 0).." | joins "..tostring(h.joinEvents or 0).." | "..ratio..(h.failed and (" | FAILED: "..tostring(h.failReason)) or "")) else startup.subtle_text("Hop "..i..": pending") end end
            ImGui.Separator(); startup.section_title("Fresh Host Test"); local h=startup.self_diag.hostObservation; if h then startup.status_line("Host",tostring(h.hostName or "Unknown").." | local="..tostring(h.isLocalHost),0.35,1.00,0.45); startup.subtle_text_wrapped("Advertiser "..tostring(h.advertiser or "NONE").." | Players "..tostring(h.startPlayers or 0).." -> "..tostring(h.endPlayers or startup.get_session_player_count()).." | peak "..tostring(h.peakPlayers or 0).." | incoming joins "..tostring(h.joinEvents or 0)) else startup.subtle_text_wrapped("Runs after the three hop windows. Startup restores your saved hosting/advertising choices first.") end
            if startup.self_diag.synthesis and startup.self_diag.synthesis.likely then ImGui.Separator(); startup.section_title("Likely Causes / Priorities"); for i,item in ipairs(startup.self_diag.synthesis.likely) do startup.text_colored_wrapped(1.00,0.78,0.18,1.00,tostring(i)..". ["..tostring(item[1]).."] "..tostring(item[2])) end end
        end
        if ImGui.BeginChild and ImGui.EndChild then ImGui.EndChild() end
        ImGui.Separator()
        if startup.self_diag.active then
            startup.render_color_button("STOP & RETURN TO HOSTING","Red","Stop early, restore saved Startup settings, and request a fresh host session.",function() startup.self_diag.request_abort("popup stop") end,-1,38)
        else
            startup.render_color_button("RUN FULL SELF-DIAGNOSIS","Green","Starts the complete automated diagnostic.",function() startup.self_diag.start() end,-1,38)
        end
        if tostring(startup.self_diag.latestReportPath or "")~="" then startup.render_color_button("COPY REPORT PATH","Gold","Copies the latest Self Diagnosis report path.",startup.self_diag.copy_report_path,-1,34) end
        startup.render_color_button("CLOSE WINDOW","Blue","Closes this window. An active diagnostic continues in the background.",function() startup.self_diag.popupOpen=false end,-1,34)
    end
    ImGui.End(); startup.pop_first_run_style(colors,vars)
