startup.credits_state = startup.credits_state or {
    asset_version = nil,
    download_started = false,
    load_started = false,
    load_failed = false,
    texture_id = nil,
    texture_srv = nil,
    load_requested_ms = 0,
    last_texture_poll_ms = 0,
    status = "Icon not loaded yet."
}

-- Reset only the portrait cache when the bundled source changes. This prevents an
-- older missing/failed texture state from surviving a Startup update and ensures
-- the new Public_Urinal artwork is downloaded from its current repository path.
if startup.credits_state.asset_version ~= startup.public_urinal_icon_asset_version then
    startup.credits_state.asset_version = startup.public_urinal_icon_asset_version
    startup.credits_state.download_started = false
    startup.credits_state.load_started = false
    startup.credits_state.load_failed = false
    startup.credits_state.texture_id = nil
    startup.credits_state.texture_srv = nil
    startup.credits_state.load_requested_ms = 0
    startup.credits_state.last_texture_poll_ms = 0
    startup.credits_state.status = "Updated Public_Urinal icon queued."
end

-- A script reload gets one fresh allocation attempt when no texture handle survived.
-- This reset runs once during script initialization, never from the render loop.
if not startup.credits_state.texture_id and not startup.credits_state.texture_srv then
    startup.credits_state.load_started = false
    startup.credits_state.load_failed = false
    startup.credits_state.load_requested_ms = 0
    startup.credits_state.last_texture_poll_ms = 0
end

