-- Local asset pack. ZIP layout is intended to be copied directly into Cherax\\Lua.
local FLAG_SIZE = 36
local FLAG_DETAIL_SIZE = 44
local flag_texture_cache = {}
local flag_texture_count = 0
local MAX_FLAG_TEXTURES = 249

local function flag_asset_path(alpha2)
    local root = (FileMgr and FileMgr.GetMenuRootPath and FileMgr.GetMenuRootPath()) or ""
    return root .. "\\Lua\\Startup\\Assets\\browser_ui\\flags\\" .. tostring(alpha2 or "xx"):lower() .. ".png"
end

local function load_flag_texture(alpha2)
    alpha2=tostring(alpha2 or ""):lower()
    if #alpha2~=2 then return "none" end
    local cached=flag_texture_cache[alpha2]
    if cached~=nil then return cached end
    if flag_texture_count>=MAX_FLAG_TEXTURES then return "limit" end

    local path=flag_asset_path(alpha2)
    if FileMgr and FileMgr.DoesFileExist and not FileMgr.DoesFileExist(path) then
        flag_texture_cache[alpha2]="none"
        return "none"
    end
    flag_texture_cache[alpha2]="loading"

    local function do_load()
        direct_call(function()
            local texId=Texture and Texture.LoadTextureAsync and Texture.LoadTextureAsync(path) or 0
            if texId and texId~=0 then
                flag_texture_cache[alpha2]=texId
                flag_texture_count=flag_texture_count+1
            else
                flag_texture_cache[alpha2]="failed"
            end
        end)
    end
    if type(FreemodeQueueJob)=="function" then FreemodeQueueJob(do_load) else do_load() end
    return "loading"
end

local function flag_icon(alpha2,size)
    size=tonumber(size) or FLAG_SIZE
    local result=load_flag_texture(alpha2)
    if type(result)=="number" and result~=0 and Texture and Texture.IsTextureValid and Texture.IsTextureValid(result) then
        local d3d=Texture.GetTexture(result)
        if d3d then
            local gpu=d3d:GetCurrent()
            if gpu then
                local x,y=ImGui.GetCursorScreenPos()
                ImGui.AddImage(gpu,x,y,x+size,y+size)
                ImGui.Dummy(size,size)
                return true
            end
        end
    end
    -- Quiet placeholder only while the image is loading/missing.
    dim("·")
    return false
end

local function row_flag_code(row)
    if not row then return "xx" end
    return tostring(row.flag or country_flag_codes[row.code] or "xx"):lower()
end

-- Build 234 live-session presentation metadata. The backend fields are optional so
-- older servers/clients remain compatible; unknown activity data cleanly falls back
-- to GENERAL / MIC OPTIONAL until the activity backend begins publishing it.
local browser_category_asset = {
    NORMAL="b236_normal", GENERAL="b236_normal", DEFAULT="b236_normal", ALL="b234_all",
    VEHICLES="b234_vehicles", MINIGAMES="b234_minigames", ROLEPLAYING="b234_roleplaying",
    WAR="b234_war", SOCIAL="b234_social", ["ROCKSTAR JOBS"]="b242_job"
}
local function normalize_browser_category(value)
    local v=tostring(value or "NORMAL"):upper():gsub("[^A-Z ]","")
    if v=="GENERAL" or v=="DEFAULT" or v=="NORMAL" or v=="STANDARD" then return "NORMAL" end
    if v:find("CAR",1,true) or v:find("DRIFT",1,true) or v:find("RACE",1,true) or v:find("VEHICLE",1,true) then return "VEHICLES" end
    if v:find("MINIGAME",1,true) or v:find("PARKOUR",1,true) then return "MINIGAMES" end
    if v:find("ROLE",1,true) then return "ROLEPLAYING" end
    if v:find("WAR",1,true) or v:find("COMBAT",1,true) then return "WAR" end
    if v:find("SOCIAL",1,true) or v:find("HANGOUT",1,true) or v:find("CHILL",1,true) then return "SOCIAL" end
    if v:find("ROCKSTAR",1,true) or v=="R JOBS" or v=="RSTAR JOBS" then return "ROCKSTAR JOBS" end
    if browser_category_asset[v] then return v end
    return "NORMAL"
end
local function row_category_key(row)
    return normalize_browser_category(row and (row.category or row.activityCategory or row.activity_category) or "NORMAL")
end
local function row_category_label(row)
    if row and row.rockstarJobActive==true then return "ROCKSTAR JOB" end
    local k=row_category_key(row)
    if k=="NORMAL" then return "Normal" end
    if k=="ROCKSTAR JOBS" then return "R* Jobs" end
    return k:sub(1,1)..k:sub(2):lower()
end
local function row_mic_requirement(row)
    local v=tostring(row and (row.mic or row.micRequirement or row.mic_requirement) or "MIC OPTIONAL"):upper()
    if v=="NONE" or v=="NO" or v:find("NO MIC",1,true) then return "NO MIC" end
    if v:find("REQUIRED",1,true) then return "MIC REQUIRED" end
    if v:find("RECOMMENDED",1,true) then return "MIC RECOMMENDED" end
    return "MIC OPTIONAL"
end
local function browser_hover_tip(text)
    if startup and startup.hover_help then direct_call(startup.hover_help,tostring(text or "")) end
end
local function row_category_icon(row,size)
    local k=row_category_key(row); local asset=browser_category_asset[k] or "b234_all"
    if startup and startup.browser_ui_draw then startup.browser_ui_draw(asset,size or 22,size or 22,3) else dim(k:sub(1,1)) end
    browser_hover_tip(row_category_label(row))
end
local function row_mic_icon(row,size)
    local req=row_mic_requirement(row); local asset=req=="NO MIC" and "b234_mic_off" or "b234_mic"
    if startup and startup.browser_ui_draw then startup.browser_ui_draw(asset,size or 20,size or 20,3) else dim(req=="NO MIC" and "X" or "M") end
    browser_hover_tip(req)
end

