for i,r in ipairs(raw_rows) do
    local user_count = 1 + ((i*3)%6)
    local names = {r[1]}
    for j=2,user_count do
        local candidate = peer_pool[((i+j*4-2)%#peer_pool)+1]
        local dup=false
        for _,n in ipairs(names) do if n==candidate then dup=true break end end
        if not dup then names[#names+1]=candidate end
    end
    local rep=host_reputation[r[1]] or "clean"
    local reports7d, reportsAllTime
    if rep=="clean" then
        reports7d=0
        reportsAllTime=(i%9==0) and 1 or 0
    elseif rep=="recent" then
        reports7d=2+(i%2)
        reportsAllTime=reports7d+3+(i%4)
    elseif rep=="heavy" then
        reports7d=5+(i%3)
        reportsAllTime=math.max(12,reports7d+6+(i%5))
    else
        reports7d=9+(i%4)
        reportsAllTime=reports7d+18+(i%8)
    end
    browser.rows[#browser.rows+1] = {
        username=r[1], country=r[2], code=r[3], online=r[4], players=r[5], maxPlayers=30,
        ping=r[6], edition=r[7], age=r[8], cheraxNames=names,
        reputation=rep, reports7d=reports7d, reportsAllTime=reportsAllTime,
        category=({"NORMAL","VEHICLES","MINIGAMES","ROLEPLAYING","WAR","SOCIAL"})[((i-1)%6)+1],
        mic=({"MIC OPTIONAL","MIC RECOMMENDED","MIC REQUIRED","NO MIC"})[((i-1)%4)+1]
    }
