local active_browser_edition

local function country_label_from_alpha2(code)
    code=tostring(code or "XX"):upper()
    for _,entry in ipairs(startup.country_filter_countries or {}) do
        if tostring(entry.key or ""):upper()==code then return tostring(entry.label or code) end
    end
    return code=="XX" and "Unknown / Hidden" or code
end

local function format_host_age(seconds)
    seconds=math.max(0,tonumber(seconds or 0) or 0)
    if seconds<60 then return tostring(math.floor(seconds)).."s" end
    if seconds<3600 then return tostring(math.floor(seconds/60)).."m" end
    return tostring(math.floor(seconds/3600)).."h"
end

local function row_ping_value(row)
    return tonumber(row and row.ping) or 999999
end

local function active_source_rows()
    if startup.s.browserSimulate ~= false then
        -- Build 283: SIM 30 is a visual test dataset, so make all 30 rows match the
        -- currently running GTA edition. Real backend rows remain server/edition isolated.
        local simEdition=active_browser_edition and active_browser_edition() or nil
        if simEdition then
            for _,row in ipairs(browser.rows or {}) do row.edition=simEdition end
        end
        return browser.rows
    end
    return browser.liveRows or {}
end

-- Build 246: Browser HUD hover preview is intentionally temporary. Hovering a
-- Browser session/event may preview that host in the Session HUD, but the preview
-- must never replace the real GTA session context after the mouse leaves, the list
-- scrolls away, the Browser tab changes, or the Browser window is no longer rendered.
local function browser_nowms()
    if startup and startup.now then return tonumber(startup.now()) or 0 end
    if Time and Time.GetEpocheMs then return tonumber(Time.GetEpocheMs()) or 0 end
    return math.floor(os.clock()*1000)
end

local function browser_clone_hud_row(row)
    if type(row)~="table" then return nil end
    local copy={}
    for k,v in pairs(row) do
        if k=="cheraxNames" and type(v)=="table" then
            local names={}
            for i,name in ipairs(v) do names[i]=name end
            copy[k]=names
        else
            copy[k]=v
        end
    end
    copy.__startup_hover_preview=true
    return copy
end

local function browser_resolve_hover_source(row)
    if type(row)~="table" then return nil end
    local listing=tostring(row.listingId or row.listing_id or "")
    local username=tostring(row.username or row.host or "")
    local wanted=username:lower()
    for _,live in ipairs(browser.liveRows or {}) do
        if type(live)=="table" then
            local sameListing=listing~="" and tostring(live.listingId or "")==listing
            local sameHost=wanted~="" and tostring(live.username or ""):lower()==wanted
            if sameListing or sameHost then return live end
        end
    end
    return row
end

