startup.browser_set_live_hosts = function(hosts)
    local rows={}
    local edition=active_browser_edition and active_browser_edition() or nil
    for _,h in ipairs(type(hosts)=="table" and hosts or {}) do
        local cc=tostring(h.country or h.country_code or "XX"):upper()
        if not cc:match("^[A-Z][A-Z]$") then cc="XX" end
        local family=tostring(h.edition or ""):lower()
        local rowEdition=(family=="legacy" and "Legacy") or (family=="enhanced" and "Enhanced") or edition
        if rowEdition==edition then
            local username=tostring(h.username or "Unknown")
            rows[#rows+1]={
                listingId=tostring(h.listing_id or ""), username=username,
                country=country_label_from_alpha2(cc), code=cc, flag=cc:lower(),
                online=true, players=math.max(1,math.min(30,tonumber(h.players or 1) or 1)),
                maxPlayers=math.max(1,math.min(30,tonumber(h.max_players or 30) or 30)),
                ping=tonumber(h.ping_ms or h.ping),
                targetRid=(startup.browser_ping_targets_307 and startup.browser_ping_targets_307[tostring(h.listing_id or "")] and startup.browser_ping_targets_307[tostring(h.listing_id or "")].rid) or "",
                edition=rowEdition, age=format_host_age(h.host_age_seconds),
                hostAgeSeconds=tonumber(h.host_age_seconds or 0) or 0,
                cheraxNames={username}, reputation="unrated", reports7d=0,
                reportsAllTime=0, live=true, joinable=(h.joinable==true),
                blockedByYou=(h.blocked_by_you==true),
                category=normalize_browser_category(h.category or h.activity_category or h.session_category or "NORMAL"),
                activity=tostring(h.activity or h.session_activity or "GENERAL SESSION"),
                mic=tostring(h.mic_requirement or h.mic or "MIC OPTIONAL"),
                eventStart=tostring(h.event_start or "NOW"),
                eventMaxPlayers=math.max(1,math.min(30,tonumber(h.event_max_players or h.max_players or 30) or 30)),
                rockstarJobActive=(h.rockstar_job_active==true or h.rockstar_job_active==1 or tostring(h.rockstar_job_active)=="1"),
                rockstarContentId=tostring(h.rockstar_content_id or ""),
                rockstarJobName=tostring(h.rockstar_job_name or ""),
                rockstarJobType=tostring(h.rockstar_job_type or ""),
                rockstarJobStatus=tostring(h.rockstar_job_status or "")
            }
        end
    end
    browser.liveRows=rows
    startup.browser_live_rows=rows
    browser.liveUpdatedMs=startup.now and startup.now() or 0
    if startup.s.browserSimulate==false then browser.selected=math.max(1,math.min(#rows,tonumber(browser.selected) or 1)) end
end

local rep_sort_rank = {clean=1, recent=2, heavy=3, griefer=4, unrated=5}
local sort_modes = {"Recommended","Players","Ping","Flag","Reputation"}

-- Browser edition isolation is a hard rule, not a user-selectable filter.
-- LE / LE BE users only receive Legacy rows; EE / EE BE users only receive Enhanced rows.
active_browser_edition = function()
    if not (startup and startup.get_active_edition_info) then return nil end
    local _, label, _, recognized = startup.get_active_edition_info()
    if recognized ~= true then return nil end
    label = tostring(label or "")
    if label == "Legacy" or label == "Enhanced" then return label end
    return nil
end

local function row_matches_active_edition(row)
    local edition = active_browser_edition()
    if edition == nil or row == nil then return false end

    -- Build 300: Event cards use a lightweight/synthetic JOIN row. Older Startup
    -- publishers may not put an edition label on that Event row, even though the
    -- canonical live Browser host row is already correctly edition-isolated.
    -- Resolve the Event row back to the live listing before enforcing the hard
    -- Legacy/Enhanced JOIN guard.
    local rowEdition=tostring(row.edition or "")
    if rowEdition=="" then
        local listing=tostring(row.listingId or row.listing_id or "")
        if listing~="" then
            for _,liveRow in ipairs(browser.liveRows or {}) do
                if tostring(liveRow.listingId or liveRow.listing_id or "")==listing then
                    rowEdition=tostring(liveRow.edition or "")
                    if rowEdition~="" then break end
                end
            end
        end
    end

    local normalized=rowEdition:lower()
    if normalized=="legacy" or normalized=="le" or normalized=="le be" then
        rowEdition="Legacy"
    elseif normalized=="enhanced" or normalized=="ee" or normalized=="ee be" then
        rowEdition="Enhanced"
    end
    return rowEdition==edition
end

-- Publication eligibility for the future backend. A Startup user is publishable only
-- while they are the current GTA Session Host. Losing host immediately makes them
-- ineligible; the server-side heartbeat/TTL layer will remove stale listings as well.
local function local_player_is_session_host()
    if not (startup and startup.get_session_host_name and startup.is_local_player_id) then return false end
    local _, hostId = startup.get_session_host_name()
    hostId = tonumber(hostId)
    if hostId == nil or hostId < 0 or hostId > 31 then return false end
    return startup.is_local_player_id(hostId) == true
end

local function sorted_rows()
    local out={}
    local source=active_source_rows()
    for i,row in ipairs(source) do
        if row_matches_active_edition(row) and (startup.s.browserFilter=="All" or (startup.s.browserFilter=="Online" and row.online) or (startup.s.browserFilter=="Offline" and not row.online)) then
            out[#out+1]={row=row,index=i}
        end
    end

    local mode=tostring(startup.s.browserSort or "Recommended")
    table.sort(out,function(a,b)
        local ar,br=a.row,b.row
        local aping,bping=row_ping_value(ar),row_ping_value(br)

        if mode=="Flag" then
            local ac=tostring(ar.country or ar.code or ""):lower()
            local bc=tostring(br.country or br.code or ""):lower()
            if ac~=bc then return ac<bc end
            if ar.online~=br.online then return ar.online end
            if ar.players~=br.players then return ar.players>br.players end
        elseif mode=="Players" then
            if ar.online~=br.online then return ar.online end
            if ar.players~=br.players then return ar.players>br.players end
            if ar.online and br.online and aping~=bping then return aping<bping end
        elseif mode=="Ping" then
            if ar.online~=br.online then return ar.online end
            if ar.online and br.online and aping~=bping then return aping<bping end
            if ar.players~=br.players then return ar.players>br.players end
        elseif mode=="Reputation" then
            if ar.online~=br.online then return ar.online end
            local arp=rep_sort_rank[ar.reputation or "unrated"] or 99
            local brp=rep_sort_rank[br.reputation or "unrated"] or 99
            if arp~=brp then return arp<brp end
            if ar.players~=br.players then return ar.players>br.players end
            if ar.online and br.online and aping~=bping then return aping<bping end
        else
            if ar.online~=br.online then return ar.online end
            local arp=country_priority[ar.code] or 50
            local brp=country_priority[br.code] or 50
            if arp~=brp then return arp>brp end
            if ar.players~=br.players then return ar.players>br.players end
            if ar.online and br.online and aping~=bping then return aping<bping end
        end

        return tostring(ar.username):lower()<tostring(br.username):lower()
    end)
    return out
end

local function selected_row(preferOnline)
    local source=active_source_rows()
    local row=nil
    local wanted=tostring(browser.selectedStableKey or "")
    if wanted~="" and startup.browser_row_stable_key then
        for i,candidate in ipairs(source) do
            if startup.browser_row_stable_key(candidate)==wanted and row_matches_active_edition(candidate) then
                row=candidate
                browser.selected=i
                break
            end
        end
    end
    if not row then
        row=source[math.max(1,math.min(#source,tonumber(browser.selected) or 1))]
        if row and not row_matches_active_edition(row) then row=nil end
        if row and startup.browser_row_stable_key then browser.selectedStableKey=startup.browser_row_stable_key(row) end
    end

    if preferOnline then
        if row and row.online then return row end
        for _,candidate in ipairs(source) do
            if candidate.online and row_matches_active_edition(candidate) then return candidate end
        end
        return nil
    end

    if row then return row end
    for _,candidate in ipairs(source) do
        if row_matches_active_edition(candidate) then return candidate end
    end
    return nil
end

local function browser_hud_row()
    -- Build 253: Browser UI selection never drives the Session HUD.
    -- This resolver returns a Browser row only when it matches the actual
    -- current GTA Session Host. Simulation/selected/hovered rows stay inside
    -- the Browser window and have no HUD authority.
    browser.hoverHudRow=nil
    browser.hoverHudTouchedMs=0

    if not (startup.get_session_host_name and browser.liveRows) then return nil end
    local hostName = select(1, startup.get_session_host_name())
    hostName = tostring(hostName or "")
    if hostName == "" or hostName == "Unknown" then return nil end
    local wanted = hostName:lower()

    for i,row in ipairs(browser.liveRows or {}) do
        if row and row.online and row_matches_active_edition(row)
            and tostring(row.username or ""):lower() == wanted then
            -- Build 273: Session HUD resolution must never overwrite the user's Browser
            -- selection.  HUD identity follows the real GTA session independently.
            return row
        end
    end
    return nil
end

