local JOIN_POPUP_NAME = "Before You Join##SB217JoinNotice"

local function request_join_notice(row)
    if not row then return end
    -- B360: one Browser JOIN owns the transition at a time. Absorb repeat clicks
    -- before opening another confirmation popup.
    if startup.browser_join_is_active_b360 and startup.browser_join_is_active_b360() then
        if startup.toast then startup.toast("A Browser JOIN is already in progress.",3000) end
        return
    end
    if not row_matches_active_edition(row) and row.isStartupEvent~=true then
        toast("Join blocked: this Browser listing is for a different GTA edition.")
        return
    end
    if row.live==true and row.joinable~=true then
        toast("This host is online but needs the Phase 3 Browser update before JOIN is available.")
        return
    end
    browser.joinPopupTarget = row
    browser.joinPopupRequested = true
    if startup.log then
        startup.log("[Browser Join 283] NOTICE_REQUESTED | target="..tostring(row.username or "host").." | live="..tostring(row.live==true).." | sim="..tostring(startup.s.browserSimulate~=false))
    end
end

local function render_join_notice_popup()
    if not ImGui then return end
    local row=browser.joinPopupTarget
    if not row then return end
    browser.joinPopupRequested=false

    if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(660,500,ImGuiCond and ImGuiCond.FirstUseEver or 0) end
    if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(90,90,ImGuiCond and ImGuiCond.FirstUseEver or 0) end
    if ImGui.SetNextWindowBgAlpha then ImGui.SetNextWindowBgAlpha(0.98) end
    local flags=ImGuiWindowFlags and ImGuiWindowFlags.NoCollapse or 0
    local visible=ImGui.Begin("Before You Join##SB297JoinNoticeWindow",true,flags)==true
    if visible then
        red("STARTUP BROWSER — IMPORTANT")
        if row and row.username then
            dim("Joining")
            ImGui.SameLine(); white(tostring(row.username))
        end
        if row and row.isStartupEvent==true then
            local eventEdition=(startup.b432_event_edition and startup.b432_event_edition(row,row)) or tostring(row.edition or "Unknown")
            ImGui.Spacing()
            red("GTA V Version: "..tostring(eventEdition))
            white("You must be running GTA V "..tostring(eventEdition).." for this Event JOIN to work.")
            white("Events remain visible across Legacy and Enhanced so the full community can see what is being hosted.")
        end
        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()

        red("DO NOT TAKE SESSION HOST")
        white("Allow the Browser host to remain Session Host. Do not kick, crash,")
        white("remove, or force host migration against the Browser host.")
        ImGui.Spacing()

        red("DO NOT ABUSE OTHER CHERAX USERS")
        white("Trolling, bullying, harassment, malicious kicks, crash attempts, host")
        white("takeover attempts, or intentionally disrupting another Startup/Cherax")
        white("user is prohibited.")
        ImGui.Spacing()

        red("PLAY FAIR")
        white("Use Startup's Vote and Report tools when another player is causing problems.")
        white("Confirmed malicious abuse may result in suspension or a permanent Browser ban.")
        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()

        if report_button("CANCEL##SB297JoinCancel",120,30) then
            browser.joinPopupTarget=nil
            browser.joinPopupRequested=false
            if startup.log then startup.log("[Browser Join 297] NOTICE_CANCELLED") end
        end
        ImGui.SameLine()
        if purple_button("I UNDERSTAND — JOIN##SB297JoinAccept",210,30) then
            local target=browser.joinPopupTarget
            browser.joinPopupTarget=nil
            browser.joinPopupRequested=false
            local queued=false
            if target and target.live==true and type(startup.browser_execute_join)=="function" then
                queued=startup.browser_execute_join(target)==true
            end
            if startup.log then startup.log("[Browser Join 297] NOTICE_ACCEPTED | target="..tostring(target and target.username or "host").." | queued="..tostring(queued)) end
            -- B360: browser_execute_join owns user-facing failure reasons. Do not stack
            -- a generic queue-failed toast on top of an already-in-progress/specific error.
        end
    end
    ImGui.End()
end

