local function render_browser_body()
    if not ImGui then return end
    -- Each Browser render frame starts from the real session state. A row below must
    -- explicitly claim the hover preview again; otherwise the HUD restores immediately.
    if startup.browser_clear_hover_hud_row then startup.browser_clear_hover_hud_row() end
    local sorted=sorted_rows()
    local online=0
    local editionHosts=0
    for _,r in ipairs(active_source_rows()) do
        if row_matches_active_edition(r) then
            editionHosts=editionHosts+1
            if r.online then online=online+1 end
        end
    end

    -- Compact toolbar. Counts are edition-isolated too.
    green(tostring(online).." ONLINE")
    ImGui.SameLine(); dim("•")
    ImGui.SameLine(); white(tostring(editionHosts).." HOSTS")
    ImGui.SameLine(); filter_button("All")
    ImGui.SameLine(); filter_button("Online")
    ImGui.SameLine(); filter_button("Offline")
    startup.s.browserSimulate = false -- Build 295: SIM 30 is internal-only and hidden.

    -- Keep sorting on its own row so it remains visible at narrower Cherax widths.
    dim("SORT BY")
    ImGui.SameLine()
    sort_combo()
    if startup.browser_backend_render_status then startup.browser_backend_render_status() end
    ImGui.Separator()

    local leftW=470
    local totalW=900
    if ImGui.GetContentRegionAvail then
        local ok,a=direct_call(ImGui.GetContentRegionAvail)
        if ok and type(a)=="number" then totalW=a
        elseif ok and type(a)=="table" and a.x then totalW=a.x end
    end
    totalW=math.max(430,tonumber(totalW or 900) or 900)
    local paneGap=10
    if totalW<760 then
        -- 1080p / narrow Cherax windows: both panes shrink proportionally instead of
        -- forcing the old 470+270 minimums outside the visible window.
        leftW=math.max(235,math.floor(totalW*0.54))
    else
        leftW=math.max(470,math.min(590,totalW*0.61))
    end
    local rightW=math.max(185,totalW-leftW-paneGap)
    local h=520

    -- LEFT PANE: fixed column header + independently scrolling host rows.
    if ImGui.BeginChild then ImGui.BeginChild("SB217LeftPane",leftW,h,false) end
    local playersX=leftW*0.43
    local categoryX=leftW*0.59
    local micX=leftW*0.70
    local countryX=leftW*0.80
    local pingX=leftW*0.91
    dim("PLAYER")
    ImGui.SameLine(playersX); dim("PLAYERS")
    ImGui.SameLine(categoryX); dim("CATEGORY")
    ImGui.SameLine(micX); dim("MIC")
    ImGui.SameLine(countryX); dim("FLAG")
    ImGui.SameLine(pingX); dim("PING")
    ImGui.Separator()

    local nameW=math.max(82,playersX-30)
    local leftScrollStyle=push_browser_scrollbar()
    if ImGui.BeginChild then ImGui.BeginChild("SB217LeftRows",0,h-38,false) end
    if #sorted==0 then
        dim(startup.s.browserSimulate ~= false and "No simulated hosts match this filter." or "No live hosts available right now.")
    end
    for _,item in ipairs(sorted) do
        local row=item.row
        local selected=(browser.selected==item.index)
        status_dot(row.online)
        ImGui.SameLine()

        local rowNameColor=host_name_color(row)
        local pushedText=push_text_color(rowNameColor)
        local selStyle=push_selected_style()
        local clicked=false
        if ImGui.Selectable then
            clicked=ImGui.Selectable(row.username.."##SB217Row"..item.index,selected,0,nameW,22)
        else
            text_color(rowNameColor[1],rowNameColor[2],rowNameColor[3],1.0,row.username)
            if ImGui.IsItemClicked then clicked=ImGui.IsItemClicked() end
        end
        pop_color(selStyle)
        if pushedText then pop_color(1) end
        if clicked then browser.selected=item.index end
        -- Build 253: hovering/selecting Browser rows never previews them in the HUD.

        ImGui.SameLine(playersX)
        if row.online then white(tostring(row.players).."/"..tostring(row.maxPlayers)) else dim("--") end
        ImGui.SameLine(categoryX); row_category_icon(row,22)
        ImGui.SameLine(micX); row_mic_icon(row,20)
        ImGui.SameLine(countryX); flag_icon(row_flag_code(row),FLAG_SIZE); browser_hover_tip(row.country)
        ImGui.SameLine(pingX)
        if row.online and tonumber(row.ping) then dim(tostring(row.ping)) else dim("--") end
    end
    if ImGui.EndChild then ImGui.EndChild() end
    pop_browser_scrollbar(leftScrollStyle)
    if ImGui.EndChild then ImGui.EndChild() end

    ImGui.SameLine()

    -- RIGHT PANE: selected player name/status stays pinned while details scroll.
    if ImGui.BeginChild then ImGui.BeginChild("SB217RightPane",rightW,h,false) end
    local row=selected_row()
    if row then
        local selectedNameColor=host_name_color(row)
        text_color(selectedNameColor[1],selectedNameColor[2],selectedNameColor[3],1.0,row.username)
        ImGui.SameLine(); status_dot(row.online)
        ImGui.SameLine(); if row.online then green("ONLINE") else red("OFFLINE") end
        ImGui.Separator()

        local rightScrollStyle=push_browser_scrollbar()
        if ImGui.BeginChild then ImGui.BeginChild("SB217RightDetails",0,h-38,false) end

        -- Country / session summary.
        flag_icon(row_flag_code(row),FLAG_DETAIL_SIZE); browser_hover_tip(row.country)
        ImGui.SameLine(); white(row.country)
        ImGui.Spacing()
        dim("CATEGORY"); ImGui.SameLine(100); row_category_icon(row,22); ImGui.SameLine(); white(row_category_label(row))
        dim("MIC"); ImGui.SameLine(100); row_mic_icon(row,20); ImGui.SameLine(); white(row_mic_requirement(row))
        ImGui.Spacing()
        if row.rockstarJobActive==true then
            ImGui.Separator(); ImGui.Spacing(); purple("ROCKSTAR JOB")
            local rw=math.max(170,math.min(rightW-18,340)); local rh=math.floor(rw*9/16)
            if startup.browser_draw_remote_job_preview then direct_call(startup.browser_draw_remote_job_preview,row,rw,rh) end
            if tostring(row.rockstarJobName or "")~="" then white(tostring(row.rockstarJobName)) else white("Rockstar Activity") end
            if tostring(row.rockstarJobType or "")~="" then dim(tostring(row.rockstarJobType)) end
            if tostring(row.rockstarJobStatus or "")~="" then green(tostring(row.rockstarJobStatus)) else green("IN PROGRESS") end
            dim("Official Rockstar preview • detected automatically")
            ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
        end

        white(tostring(row.players).." / "..tostring(row.maxPlayers))
        ImGui.SameLine(); dim("PLAYERS")
        ImGui.SameLine()
        white((row.online and tonumber(row.ping)) and tostring(row.ping) or "--")
        ImGui.SameLine(); dim("MS")

        ImGui.Spacing()
        dim("EDITION")
        ImGui.SameLine(100); white(tostring(row.edition))
        dim(row.online and "HOST AGE" or "LAST SEEN")
        ImGui.SameLine(100); white(tostring(row.age))

        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
        dim("REPUTATION")
        draw_rep_badge(row)
        if row.live==true then
            dim("Reports are not enabled yet.")
        else
            local rc=rep_info(row).color
            text_color(rc[1],rc[2],rc[3],1.0,tostring(row.reports7d or 0).." reports")
            ImGui.SameLine(); dim("in last 7 days")
            white(tostring(row.reportsAllTime or 0))
            ImGui.SameLine(); dim("all time reports")
        end

        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
        purple("CHERAX  "..tostring(#(row.cheraxNames or {})))
        for _,name in ipairs(row.cheraxNames or {}) do
            draw_peer_name(name)
        end

        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
        local safetyOn = startup.s.browserSessionSafetyEnabled ~= false
        local inCurrentSession = startup.browser_row_in_current_session and startup.browser_row_in_current_session(row) == true
        local hasSessionContext = startup.browser_has_current_session_context and startup.browser_has_current_session_context() == true
        local selfRow = startup.browser_row_is_self and startup.browser_row_is_self(row) == true
        local localIsHost = startup.browser_is_local_session_host and startup.browser_is_local_session_host() == true
        local canVote = safetyOn and hasSessionContext and inCurrentSession and not selfRow and not localIsHost
        local canReport = safetyOn and hasSessionContext
        local canJoin = not selfRow
        local buttonCount = (canJoin and 1 or 0) + (canVote and 1 or 0) + (canReport and 1 or 0)
        local actionW=math.max(58,math.floor((rightW-16)/math.max(1,buttonCount)))
        local drewAction=false
        if canJoin then
            local joinLabel=(row.rockstarJobActive==true and "JOIN JOB##SB241JoinJob" or "JOIN##SB217Join")
            if purple_button(joinLabel,actionW,30) then
                if row.blockedByYou==true then toast("Unblock this user before joining them.") else request_join_notice(row) end
            end
            if row.rockstarJobActive==true and startup.subtle_text_wrapped then
                startup.subtle_text_wrapped("JOIN JOB uses Startup Browser's existing join-to-host path. Beta test: GTA should route you into the host's active joinable Rockstar activity when Rockstar allows it.")
            end
            drewAction=true
        end
        if canVote then
            if drewAction then ImGui.SameLine() end
            if purple_button("VOTE##SB221Vote",actionW,30) then
                if startup.browser_request_vote_popup then startup.browser_request_vote_popup() else toast("Vote UI is still loading.") end
            end
            drewAction=true
        end
        if canReport then
            if drewAction then ImGui.SameLine() end
            if report_button("REPORT##SB224Report",actionW,30) then
                if startup.browser_request_report_popup then startup.browser_request_report_popup(row) else toast("Report UI is still loading.") end
            end
            drewAction=true
        end
        local sessionActions = safetyOn and inCurrentSession and not selfRow
        if sessionActions and row.live==true and startup.browser_backend_toggle_block then
            ImGui.Spacing()
            local label=(row.blockedByYou==true and "UNBLOCK USER" or "BLOCK USER").."##SB222Block"
            if ImGui.Button(label,math.max(110,rightW-12),26) then startup.browser_backend_toggle_block(row) end
            if row.blockedByYou==true then red("BLOCKED • JOIN DISABLED") end
        elseif row.blockedByYou==true then
            ImGui.Spacing(); red("BLOCKED • JOIN DISABLED")
        elseif row.live==true and not selfRow and startup.subtle_text_wrapped then
            startup.subtle_text_wrapped("VOTE and BLOCK USER require the selected Browser user to be in your current session. REPORT opens eligible current-session Startup users and detected modders only.")
        end

        ImGui.Spacing()
        dim("● Startup")
        ImGui.SameLine(); purple("●")
        ImGui.SameLine(); dim("verified")
        ImGui.SameLine(); red("●")
        ImGui.SameLine(); dim("known modder")

        if ImGui.EndChild then ImGui.EndChild() end
        pop_browser_scrollbar(rightScrollStyle)
    end
    if ImGui.EndChild then ImGui.EndChild() end

    ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
    red("TROLLING WILL NOT BE TOLERATED. Abusive modders will be banned from Public_Urinal's scripts.")
    ImGui.Spacing()
    if startup.browser_render_session_safety then startup.browser_render_session_safety() end

    -- Build 297: JOIN policy window is rendered globally from ON_PRESENT so it
    -- cannot disappear behind/rely on a particular Browser child-window context.
    if startup.browser_render_vote_popups then startup.browser_render_vote_popups() end
end

