startup.browser_row_stable_key = function(row)
    if type(row)~="table" then return "" end
    local lid=tostring(row.listingId or row.listing_id or "")
    if lid~="" then return "L|"..lid end
    local rid=tostring(row.rid or row.rockstarId or row.rockstar_id or "")
    if rid~="" then return "R|"..rid end
    return "U|"..tostring(row.username or row.host or "").."|"..tostring(row.edition or "")
end
startup.browser_select_listing = function(listingId)
    listingId=tostring(listingId or "")
    local rows=active_source_rows()
    if listingId=="" then
        browser.selected=(#rows>0) and 1 or 1
        return false
    end
    for i,row in ipairs(rows) do
        if tostring(row and row.listingId or "")==listingId then
            browser.selected=i
            browser.selectedStableKey=startup.browser_row_stable_key and startup.browser_row_stable_key(row) or ""
            return true
        end
    end
    browser.selected=(#rows>0) and math.max(1,math.min(#rows,tonumber(browser.selected) or 1)) or 1
    return false
end
