startup.browser_should_publish_local_host = function()
    -- Hard publication gate used by the future heartbeat worker. Unknown editions and
    -- non-host users are never eligible to create/refresh a public Browser listing.
    return active_browser_edition() ~= nil and local_player_is_session_host() == true
end
