end
startup.browser_runtime_get_source_rows = function() return active_source_rows() end
startup.browser_runtime_get_selected_row = selected_row
startup.browser_runtime_get_selected_index = function() selected_row(false); return tonumber(browser.selected or 1) or 1 end
