-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 215: Browser Terms & Data Notice + mandatory Public_Urinal account enrollment
-- Online account enrollment happens whenever Startup is loaded. Browser publication,
-- browsing, voting and JOIN remain unavailable until the one-time Browser notice is accepted.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.browser_terms_runtime = startup.browser_terms_runtime or {
    requested = false,
    review = false,
    dismissed = false
}

-- Build 324: Browser terms acceptance must survive GTA/Startup restarts.
-- Keep the normal config field for compatibility, plus a tiny dedicated marker file so
-- acceptance is not lost if another config write/migration races the button callback.
function startup.browser_load_terms_acceptance_marker()
    local path=tostring(startup.browser_terms_acceptance_file or "")
    if path=="" or not startup.raw_file_exists or not startup.raw_file_exists(path) then return false end
    local chunk=loadfile(path)
    if not chunk then return false end
    local ok,data=pcall(chunk)
    if not ok or type(data)~="table" then return false end
    local version=tostring(data.version or data.browserTermsAcceptedVersion or "")
    if data.accepted==false or version~=tostring(startup.browser_terms_version or "") then return false end
    startup.s.browserTermsAcceptedVersion=version
    return true
end

function startup.browser_save_terms_acceptance_marker()
    local version=tostring(startup.browser_terms_version or "")
    if version=="" then return false end
    if startup.ensure_save_dir then startup.ensure_save_dir() end
    local acceptedAt=0
    if os and os.time then
        local okTime,value=direct_call(os.time)
        if okTime then acceptedAt=tonumber(value or 0) or 0 end
    end
    local content="return {\n    accepted = true,\n    version = "..string.format("%q",version)..",\n    acceptedAt = "..tostring(acceptedAt)..",\n}\n"
    if startup.try_write_file and startup.try_write_file(startup.browser_terms_acceptance_file,content) then return true end
    return false
end

function startup.browser_terms_accepted()
    local version=tostring(startup.browser_terms_version or "")
    if tostring(startup.s.browserTermsAcceptedVersion or "")==version then return true end
    -- Lazy restore also protects against the Browser worker starting before config load completes.
    return startup.browser_load_terms_acceptance_marker()==true
end

function startup.browser_request_terms_popup(review)
    startup.browser_terms_runtime.requested = true
    startup.browser_terms_runtime.review = review == true
    startup.browser_terms_runtime.dismissed = false
end

function startup.browser_render_terms_popup()
    if not (ImGui and ImGui.OpenPopup and ImGui.BeginPopupModal and ImGui.EndPopup) then return end
    local rt = startup.browser_terms_runtime
    local popupName = "Startup Browser - Terms & Data Notice##SB215Terms"
    if rt.requested == true then
        direct_call(ImGui.OpenPopup, popupName)
        rt.requested = false
    end
    local flags = ImGuiWindowFlags and ImGuiWindowFlags.AlwaysAutoResize or nil
    local visible = false
    direct_call(function() visible = ImGui.BeginPopupModal(popupName, true, flags) == true end)
    rt.visible = visible == true
    if not visible then return end

    startup.text_colored(0.72, 0.42, 1.00, 1.00, "STARTUP BROWSER - TERMS & DATA NOTICE")
    ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
    if ImGui.TextWrapped then
        ImGui.TextWrapped("By using Startup Browser, you agree that Public_Urinal may store persistent account identifiers, Browser activity, moderation/security events, and service statistics. Records may persist across reinstalls to prevent abuse or moderation evasion.")
    else
        ImGui.Text("Startup Browser may store persistent account, moderation, security, and service records.")
    end
    ImGui.Spacing()
    startup.text_colored(1.00, 0.24, 0.24, 1.00, "TROLLING, CRASHING, KICKING, HARASSMENT, OR OTHER ABUSE")
    startup.text_colored(1.00, 0.24, 0.24, 1.00, "MAY RESULT IN SUSPENSION OR A BAN FROM PUBLIC_URINAL SERVICES.")
    ImGui.Spacing()
    startup.subtle_text("Your Rockstar RID and Cherax UID are never shown publicly in Browser.")
    startup.subtle_text("Startup's Public_Urinal online account is maintained automatically while Startup is used.")
    ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()

    if rt.review == true or startup.browser_terms_accepted() then
        if startup.render_color_button("CLOSE##SB215TermsClose", "Gray", "Close this notice.", nil, 130, 30) then
            rt.visible = false
            if ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end
        end
    else
        if startup.render_color_button("BACK##SB215TermsBack", "Gray", "Close the notice without enabling Startup Browser.", nil, 120, 30) then
            rt.dismissed = true
            rt.visible = false
            if ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end
        end
        ImGui.SameLine()
        if startup.render_color_button("ACCEPT & CONTINUE##SB215TermsAccept", "Purple", "Accept this notice and enable Startup Browser participation.", nil, 205, 30) then
            startup.s.browserTermsAcceptedVersion = tostring(startup.browser_terms_version or "")
            rt.dismissed = false
            rt.visible = false
            local markerSaved = startup.browser_save_terms_acceptance_marker and startup.browser_save_terms_acceptance_marker()==true
            local configSaved = startup.save_config and startup.save_config(false)==true
            if startup.browser_backend then
                startup.browser_backend.next_heartbeat_ms = 0
                startup.browser_backend.next_fetch_ms = 0
            end
            if ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end
            if startup.toast then
                if markerSaved or configSaved then
                    startup.toast("Startup Browser terms accepted and remembered.", 3000)
                else
                    startup.toast("Terms accepted for this run, but Startup could not save acceptance. Check Startup\\Config write access.", 6000)
                end
            end
        end
    end
    direct_call(ImGui.EndPopup)
end

startup.browser_render_pre_terms_build215 = startup.render_browser
startup.render_browser = function()
    if startup.browser_terms_accepted() then
        return startup.browser_render_pre_terms_build215()
    end
    local rt = startup.browser_terms_runtime
    if rt.dismissed ~= true and rt.requested ~= true then startup.browser_request_terms_popup(false) end
    startup.text_colored(0.72, 0.42, 1.00, 1.00, "STARTUP BROWSER")
    startup.subtle_text("Browser access requires the short Terms & Data Notice below.")
    startup.subtle_text("Startup Users Online: "..((startup.b371_online_count_text and startup.b371_online_count_text()) or "..."))
    ImGui.Separator(); ImGui.Spacing()
    startup.text_colored(1.00, 0.24, 0.24, 1.00, "TROLLING WILL NOT BE TOLERATED.")
    startup.subtle_text("Abusive users may be suspended or banned from Public_Urinal services.")
    ImGui.Spacing()
    startup.render_color_button("VIEW TERMS & DATA NOTICE##SB215TermsGate", "Purple", "Open the Startup Browser Terms & Data Notice.", function()
        startup.browser_request_terms_popup(false)
    end, 230, 30)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 213: Browser Backend Phase 3 JOIN completion/state fixes
-- Identity + authenticated host-presence foundation. Backend is OFF by default.
-- No raw Cherax UID/RID is logged or shown in the UI. The server stores only
-- server-peppered identifier hashes and a permanent server-issued Startup UID.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.install_browser_backend_phase3_build213 = function()
    startup.browser_backend = startup.browser_backend or {}
    local bb = startup.browser_backend
    bb.api_base = "https://publicurinal.org/startup-api/v1"
    bb.status = bb.status or "OFF"
    bb.startup_uid = bb.startup_uid or ""
    bb.token = bb.token or "" -- memory only; never written to Startup config
    bb.token_expires_at = bb.token_expires_at or ""
    bb.last_error = bb.last_error or ""
    bb.next_bootstrap_ms = bb.next_bootstrap_ms or 0
    bb.next_heartbeat_ms = bb.next_heartbeat_ms or 0
    bb.published = bb.published == true
    bb.listing_id = bb.listing_id or ""
    bb.host_since_ms = bb.host_since_ms or 0
    bb.worker_installed = bb.worker_installed == true
    bb.request_busy = false
    bb.next_fetch_ms = bb.next_fetch_ms or 0
    bb.last_fetch_success_ms = bb.last_fetch_success_ms or 0
    bb.live_count = tonumber(bb.live_count or 0) or 0
    bb.join_request = bb.join_request or nil
    bb.join_pending = bb.join_pending or nil
    bb.join_last_message = bb.join_last_message or ""
    -- B360 single-flight JOIN generation. A cancelled generation may finish an HTTP
    -- request, but it is never allowed to trigger Cherax RID JOIN afterwards.
    bb.join_generation_seq = tonumber(bb.join_generation_seq or 0) or 0
    bb.active_join_generation = tonumber(bb.active_join_generation or 0) or 0
    bb.cancelled_join_generation = tonumber(bb.cancelled_join_generation or 0) or 0
    bb.join_inflight = bb.join_inflight == true
    bb.session_nonce = tostring(bb.session_nonce or "")
    bb.verified_by_player = bb.verified_by_player or {}
    bb.browser_verified_by_rid = bb.browser_verified_by_rid or {}
    bb.vote_groups = bb.vote_groups or {}
    bb.vote_status = tostring(bb.vote_status or "Ready")
    bb.vote_target_pid = tonumber(bb.vote_target_pid or -1) or -1
    bb.vote_reason = tostring(bb.vote_reason or "CRASH_ATTEMPTS")
    bb.next_vote_poll_ms = tonumber(bb.next_vote_poll_ms or 0) or 0
    bb.account_status = tostring(bb.account_status or "")
    bb.product_access = tostring(bb.product_access or "")
    bb.rockstar_accounts = tonumber(bb.rockstar_accounts or 0) or 0
    bb.next_account_ms = tonumber(bb.next_account_ms or 0) or 0
    bb.browser_moderation = tostring(bb.browser_moderation or "ACTIVE")
    bb.browser_moderation_reason = tostring(bb.browser_moderation_reason or "")
    bb.browser_moderation_message = tostring(bb.browser_moderation_message or "")
    bb.browser_moderation_expires_at = tostring(bb.browser_moderation_expires_at or "")

    local function bb_now()
        if startup.now then return tonumber(startup.now()) or 0 end
        return math.floor(os.clock()*1000)
    end

    local function bb_yield(ms)
        if startup.yield then return startup.yield(ms) end
        if Script and Script.Yield then return Script.Yield(ms or 0) end
    end

    local function bb_urlencode(value)
        return tostring(value or ""):gsub("\n","\r\n"):gsub("([^%w%-%.%_%~ ])", function(c)
            return string.format("%%%02X", string.byte(c))
        end):gsub(" ", "+")
    end

    local function bb_form(fields)
        local keys={}
        for k in pairs(fields or {}) do keys[#keys+1]=tostring(k) end
        table.sort(keys)
        local out={}
        for _,k in ipairs(keys) do out[#out+1]=bb_urlencode(k).."="..bb_urlencode(fields[k]) end
        return table.concat(out,"&")
    end

    local function bb_json_string(body,key)
        body=tostring(body or "")
        key=tostring(key or "")
        local raw=body:match('"'..key..'"%s*:%s*"(.-)"')
        if not raw then return nil end
        raw=raw:gsub('\\/','/'):gsub('\\"','"'):gsub('\\\\','\\')
        return raw
    end

    local function bb_json_bool(body,key)
        local v=tostring(body or ""):match('"'..tostring(key or "")..'"%s*:%s*(true)')
        if v=="true" then return true end
        v=tostring(body or ""):match('"'..tostring(key or "")..'"%s*:%s*(false)')
        if v=="false" then return false end
        return nil
    end

    local function bb_json_decode(text)
        local s=tostring(text or "")
        local rev={b='\b',f='\f',n='\n',r='\r',t='\t'}
        local function parse(i)
            i=s:find("%S",i) or i
            local c=s:sub(i,i)
            if c=='{' or c=='[' then
                local res={}
                local object=(c=='{')
                local close=object and '}' or ']'
                i=i+1
                local ni=s:find("%S",i)
                if ni and s:sub(ni,ni)==close then return res,ni+1 end
                while true do
                    local key,val
                    if object then
                        key,i=parse(i)
                        i=(s:find(":",i) or i)+1
                    end
                    val,i=parse(i)
                    if object then res[key]=val else res[#res+1]=val end
                    i=s:find("%S",i) or i
                    c=s:sub(i,i)
                    i=i+1
                    if c==close then break end
                    if c~=',' then error("invalid json separator") end
                end
                return res,i
            elseif c=='"' then
                local out={}
                i=i+1
                while i<=#s do
                    local ch=s:sub(i,i)
                    if ch=='"' then return table.concat(out),i+1 end
                    if ch=='\\' then
                        local e=s:sub(i+1,i+1)
                        if e=='u' then
                            local hex=s:sub(i+2,i+5)
                            local n=tonumber(hex,16)
                            if n and n<128 then out[#out+1]=string.char(n) else out[#out+1]='?' end
                            i=i+6
                        else
                            out[#out+1]=rev[e] or e
                            i=i+2
                        end
                    else
                        out[#out+1]=ch
                        i=i+1
                    end
                end
                error("unterminated json string")
            else
                local j=s:find("[%s,%]%}]",i) or (#s+1)
                local raw=s:sub(i,j-1)
                if raw=="true" then return true,j end
                if raw=="false" then return false,j end
                if raw=="null" then return nil,j end
                local n=tonumber(raw)
                if n~=nil then return n,j end
                error("invalid json value")
            end
        end
        -- Build 318: backend responses are untrusted transport data. A transient empty/HTML
        -- body must never kill a queued Browser coroutine just because the lightweight parser
        -- cannot decode it. Reject non-JSON early and contain parser errors locally.
        s=s:gsub("^\239\187\191","")
        local first=s:match("^%s*(.)")
        if first~="{" and first~="[" then return nil end
        local ok,value=pcall(function() return (parse(1)) end)
        if ok and type(value)=="table" then return value end
        return nil
    end

    local function bb_curl_setopt(curl,name,fallback,value)
        if not curl or not curl.Setopt then return false end
        local option=nil
        if eCurlOption then option=eCurlOption[name] end
        if option==nil then option=fallback end
        local ok=direct_call(function() curl:Setopt(option,value) end)
        return ok
    end

    local function bb_post(endpoint,fields,token)
        local busyNow=bb_now()
        if bb.request_busy then
            local busySince=tonumber(bb.request_busy_since_ms or 0) or 0
            if busySince>0 and busyNow-busySince>15000 then
                local transportFinished=true
                if bb.active_curl and bb.active_curl.GetFinished then
                    transportFinished=bb.active_curl:GetFinished()==true
                end
                if transportFinished then
                    bb.request_busy=false
                    bb.request_busy_since_ms=0
                    bb.active_curl=nil
                    if startup.log then startup.log("[Browser Transport 297] STALE_BUSY_RESET | endpoint="..tostring(endpoint or "")) end
                else
                    return false,"REQUEST_BUSY"
                end
            else
                return false,"REQUEST_BUSY"
            end
        end
        if not (Curl and Curl.Easy) then return false,"CURL_UNAVAILABLE" end
        bb.request_busy=true
        bb.request_busy_since_ms=bb_now()
        local ok,resultBody,resultErr=direct_call(function()
            local curl=Curl.Easy()
            bb.active_curl=curl
            local url=bb.api_base.."/"..tostring(endpoint or "")
            bb_curl_setopt(curl,"CURLOPT_URL",10002,url)
            bb_curl_setopt(curl,"CURLOPT_USERAGENT",10018,"Startup-Cherax/"..tostring(startup.version or "unknown"))
            -- RC1 network hardening: fail cleanly rather than allowing a stuck HTTP request
            -- to hold Browser state indefinitely. Numeric fallbacks are libcurl's documented
            -- CURLOPT_TIMEOUT_MS / CURLOPT_CONNECTTIMEOUT_MS values.
            bb_curl_setopt(curl,"CURLOPT_TIMEOUT_MS",155,10000)
            bb_curl_setopt(curl,"CURLOPT_CONNECTTIMEOUT_MS",156,5000)
            bb_curl_setopt(curl,"CURLOPT_CUSTOMREQUEST",10036,"POST")
            bb_curl_setopt(curl,"CURLOPT_POSTFIELDS",10015,bb_form(fields or {}))
            if curl.AddHeader then
                curl:AddHeader("Content-Type: application/x-www-form-urlencoded")
                curl:AddHeader("Accept: application/json")
                if token and token~="" then curl:AddHeader("Authorization: Bearer "..token) end
            end
            curl:Perform()
            local ticks=0
            while not curl:GetFinished() and ticks<200 do bb_yield(50); ticks=ticks+1 end
            if not curl:GetFinished() then return nil,"TIMEOUT" end
            local code,body=curl:GetResponse()
            local success=(code==0 or code==true or (eCurlCode and code==eCurlCode.CURLE_OK))
            if not success then return nil,"CURL_"..tostring(code) end
            return tostring(body or ""),nil
        end)
        bb.request_busy=false
        bb.request_busy_since_ms=0
        bb.active_curl=nil
        if not ok then return false,"REQUEST_EXCEPTION" end
        if type(resultBody)~="string" then return false,tostring(resultErr or "NO_RESPONSE") end
        return true,resultBody
    end
    bb._post=bb_post
    bb._json_decode=bb_json_decode
    bb._json_bool=bb_json_bool
    bb._json_string=bb_json_string

    local function bb_identity()
        local cheraxUid=0
        if Cherax and Cherax.GetUID then
            local ok,v=direct_call(Cherax.GetUID)
            if ok then cheraxUid=tonumber(v or 0) or 0 end
        end
        local localId=nil
        if startup.get_local_player_id_candidates then
            local ids=startup.get_local_player_id_candidates()
            if type(ids)=="table" then localId=tonumber(ids[1]) end
        end
        if localId==nil or localId<0 then return nil,"WAITING_FOR_LOCAL_PLAYER" end
        local rid=0
        if Players and Players.GetRockstarId then
            local ok,v=direct_call(Players.GetRockstarId,localId)
            if ok then rid=tonumber(v or 0) or 0 end
        end
        if rid<=0 and startup.presence and startup.presence.get_player_rid then
            local ok,v=direct_call(startup.presence.get_player_rid,localId)
            if ok then rid=tonumber(v or 0) or 0 end
        end
        local username=startup.get_player_name_safe and startup.get_player_name_safe(localId) or "Unknown"
        local edition=""
        if Cherax and Cherax.GetEdition then
            local ok,v=direct_call(Cherax.GetEdition)
            if ok then edition=tostring(v or "") end
        end
        local countryCode=""
        if startup.country_filter and startup.country_filter.read_player_country then
            local ok,_,_,cc=direct_call(startup.country_filter.read_player_country,localId)
            if ok and type(cc)=="string" and cc:upper():match("^[A-Z][A-Z]$") then countryCode=cc:upper() end
        end
        if cheraxUid<=0 then return nil,"CHERAX_UID_UNAVAILABLE" end
        if rid<=0 then return nil,"ROCKSTAR_RID_UNAVAILABLE" end
        if edition=="" then return nil,"EDITION_UNAVAILABLE" end
        return {cherax_uid=string.format("%.0f",cheraxUid),rockstar_rid=string.format("%.0f",rid),username=tostring(username),edition=edition,country_code=countryCode},nil
    end


    local function bb_new_session_nonce()
        local nonce=""
        if startup.presence and startup.presence.make_nonce then
            local ok,v=direct_call(startup.presence.make_nonce)
            if ok then nonce=tostring(v or "") end
        end
        if not nonce:match("^[A-Fa-f0-9]+$") or #nonce<8 then
            nonce=string.format("%08X%08X",math.floor((bb_now() or 0)%4294967296),math.random and math.random(0,2147483646) or 1)
        end
        bb.session_nonce=nonce:sub(1,32)
        bb.host_since_ms=0
        bb.vote_groups={}
        bb.next_vote_poll_ms=0
        return bb.session_nonce
    end

    local function bb_player_exists(pid)
        pid=tonumber(pid)
        if pid==nil or pid<0 or pid>31 or not (Players and Players.GetById) then return false end
        local ok,obj=direct_call(Players.GetById,pid)
        return ok and obj~=nil
    end

    local function bb_collect_session_roster()
        local rows={}
        for pid=0,31 do
            if bb_player_exists(pid) then
                local rid=0
                if startup.presence and startup.presence.get_player_rid then
                    local ok,v=direct_call(startup.presence.get_player_rid,pid)
                    if ok then rid=tonumber(v or 0) or 0 end
                end
                if rid>0 then
                    local name=startup.get_player_name_safe and tostring(startup.get_player_name_safe(pid) or "Unknown") or "Unknown"
                    name=name:gsub("[;,%|]","_"):gsub("[%c]","")
                    if #name>64 then name=name:sub(1,64) end
                    rows[#rows+1]=tostring(pid)..","..string.format("%.0f",rid)..","..name
                end
            end
        end
        return table.concat(rows,";")
    end

    function startup.browser_backend_new_session_nonce()
        return bb_new_session_nonce()
    end
    if bb.session_nonce=="" then bb_new_session_nonce() end

    local function bb_clear_auth(reason)
        bb.token=""; bb.token_expires_at=""; bb.startup_uid=""; bb.published=false; bb.listing_id=""; bb.live_count=0; bb.join_request=nil; bb.join_pending=nil
        bb.account_status=""; bb.product_access=""; bb.rockstar_accounts=0; bb.next_account_ms=0
        bb.browser_moderation="ACTIVE"; bb.browser_moderation_reason=""; bb.browser_moderation_message=""; bb.browser_moderation_expires_at=""
        bb.vote_groups={}; bb.verified_by_player={}
        if startup.browser_set_live_hosts then startup.browser_set_live_hosts({}) end
        bb.status=tostring(reason or "AUTH REQUIRED")
    end

    function startup.browser_backend_bootstrap()
        -- Build 215: online account enrollment is mandatory while Startup is loaded.
        startup.s.browserBackendEnabled = true
        local ident,err=bb_identity()
        if not ident then bb.status=err; bb.next_bootstrap_ms=bb_now()+5000; return false end
        bb.status="CONNECTING"
        local ok,body=bb_post("bootstrap.php",{
            cherax_uid=ident.cherax_uid,
            rockstar_rid=ident.rockstar_rid,
            username=ident.username,
            edition=ident.edition,
            client_version=tostring(startup.version or ""),
            client_build=tostring(startup.build_number or "")
        },nil)
        if not ok then bb.last_error=tostring(body); bb.status="OFFLINE"; bb.next_bootstrap_ms=bb_now()+30000; return false end
        if bb_json_bool(body,"ok")~=true then
            local apiErr=bb_json_string(body,"error") or "API_ERROR"
            bb.last_error=apiErr; bb.status=apiErr; bb.next_bootstrap_ms=bb_now()+60000
            return false
        end
        local uid=bb_json_string(body,"startup_uid")
        local token=bb_json_string(body,"token")
        if not uid or not token or #token<32 then
            bb.last_error="INVALID_BOOTSTRAP_RESPONSE"; bb.status="INVALID RESPONSE"; bb.next_bootstrap_ms=bb_now()+30000
            return false
        end
        bb.startup_uid=uid; bb.token=token; bb.token_expires_at=bb_json_string(body,"expires_at") or ""
        bb.account_status=bb_json_string(body,"status") or "ACTIVE"
        bb.product_access="ACTIVE"
        bb.browser_moderation=bb_json_string(body,"browser_moderation") or bb.browser_moderation or "ACTIVE"
        bb.browser_moderation_reason=bb_json_string(body,"browser_moderation_reason") or ""
        bb.browser_moderation_message=bb_json_string(body,"browser_moderation_message") or ""
        bb.browser_moderation_expires_at=bb_json_string(body,"browser_moderation_expires_at") or ""
        bb.last_error=""; bb.status=startup.browser_terms_accepted() and "CONNECTED" or "CONNECTED • TERMS REQUIRED"; bb.next_heartbeat_ms=0; bb.next_fetch_ms=0; bb.next_account_ms=0
        return true
    end

    function startup.browser_backend_fetch_account()
        if bb.token=="" then return false end
        local ok,body=bb_post("me.php",{},bb.token)
        if not ok then return false end
        local data=bb_json_decode(body)
        if type(data)~="table" or data.ok~=true then return false end
        bb.startup_uid=tostring(data.startup_uid or data.user_uid or bb.startup_uid or "")
        bb.account_status=tostring(data.status or bb.account_status or "ACTIVE")
        bb.product_access=tostring(data.product_access or bb.product_access or "ACTIVE")
        bb.rockstar_accounts=tonumber(data.rockstar_accounts or data.linked_rockstar_accounts or bb.rockstar_accounts or 1) or 1
        if bb.rockstar_accounts<1 then bb.rockstar_accounts=1 end
        bb.browser_moderation=tostring(data.browser_moderation or bb.browser_moderation or "ACTIVE")
        bb.browser_moderation_reason=tostring(data.browser_moderation_reason or bb.browser_moderation_reason or "")
        bb.browser_moderation_message=tostring(data.browser_moderation_message or bb.browser_moderation_message or "")
        bb.browser_moderation_expires_at=tostring(data.browser_moderation_expires_at or bb.browser_moderation_expires_at or "")
        return true
    end

    function startup.browser_backend_offline()
        if bb.token=="" then bb.published=false; bb.listing_id=""; return true end
        local ok,body=bb_post("offline.php",{},bb.token)
        bb.published=false; bb.listing_id=""; bb.host_since_ms=0
        if ok and bb_json_bool(body,"ok")==true then return true end
        return false
    end

    function startup.browser_backend_heartbeat()
        if bb.token=="" then return false end
        local ident,err=bb_identity()
        if not ident then bb.status=err; return false end
        local shouldPublish=startup.browser_terms_accepted() and startup.browser_should_publish_local_host and startup.browser_should_publish_local_host()==true
        if not shouldPublish then
            bb.host_since_ms=0
            if bb.published then startup.browser_backend_offline() end
            bb.status=startup.browser_terms_accepted() and "CONNECTED • NOT HOSTING" or "CONNECTED • TERMS REQUIRED"
            return true
        end
        if bb.host_since_ms<=0 then bb.host_since_ms=bb_now() end
        local players=startup.get_session_player_count and startup.get_session_player_count() or 1
        players=math.max(1,math.min(30,tonumber(players or 1) or 1))
        local hostAge=math.max(0,math.floor((bb_now()-bb.host_since_ms)/1000))
        local ok,body=bb_post("heartbeat.php",{
            is_host="1",
            username=ident.username,
            players=tostring(players),
            max_players="30",
            host_age_seconds=tostring(hostAge),
            country_code=tostring(ident.country_code or ""),
            rockstar_rid=ident.rockstar_rid,
            session_nonce=tostring(bb.session_nonce or ""),
            roster=bb_collect_session_roster(),
            category=tostring(startup.browser_activity_publication and startup.browser_activity_publication.category or "NORMAL"),
            activity=tostring(startup.browser_activity_publication and startup.browser_activity_publication.activity or "GENERAL SESSION"),
            mic_requirement=tostring(startup.browser_activity_publication and startup.browser_activity_publication.mic_requirement or "MIC OPTIONAL"),
            event_start=tostring(startup.browser_activity_publication and startup.browser_activity_publication.starts or "NOW"),
            event_max_players=tostring(startup.browser_activity_publication and startup.browser_activity_publication.max_players or 30),
            rockstar_job_active=(startup.rockstar_job_art and startup.rockstar_job_art.activity==true and tostring(startup.rockstar_job_art.content_id or "")~="") and "1" or "0",
            rockstar_content_id=tostring(startup.rockstar_job_art and startup.rockstar_job_art.content_id or ""),
            rockstar_job_name=tostring(startup.rockstar_job_art and startup.rockstar_job_art.job_name or ""),
            rockstar_job_type=tostring(startup.rockstar_job_art and startup.rockstar_job_art.job_type or ""),
            rockstar_job_status=tostring(startup.rockstar_job_art and startup.rockstar_job_art.job_status or ""),
            -- Build 328: presence lease hint. Older backends safely ignore unknown fields;
            -- updated backends can use this to retain a healthy host through short transport gaps.
            presence_lease_seconds="120",
            presence_client_build="330"
        },bb.token)
        if not ok then bb.status="HEARTBEAT FAILED"; bb.last_error=tostring(body); return false end
        if bb_json_bool(body,"ok")~=true then
            local apiErr=bb_json_string(body,"error") or "API_ERROR"
            if apiErr=="AUTH_EXPIRED" or apiErr=="AUTH_INVALID" or apiErr=="AUTH_REQUIRED" then
                bb_clear_auth("RECONNECTING")
                bb.next_bootstrap_ms=bb_now()+1000
            else
                bb.status=apiErr; bb.last_error=apiErr
            end
            return false
        end
        bb.published=bb_json_bool(body,"published")==true
        bb.listing_id=bb_json_string(body,"listing_id") or bb.listing_id
        local hbData=bb_json_decode(body)
        bb.verified_by_player={}
        if type(hbData)=="table" and type(hbData.verified_players)=="table" then
            local expires=bb_now()+45000
            for _,v in ipairs(hbData.verified_players) do
                local pid=tonumber(v and v.player_id)
                if pid and pid>=0 and pid<=31 then bb.verified_by_player[pid]={username=tostring(v.username or "Startup User"),expires_ms=expires} end
            end
        end
        if not bb.published then
            -- Build 328: a successful HTTP heartbeat that does not confirm publication is
            -- treated as a recoverable presence miss. The worker will retry quickly instead
            -- of waiting a full normal heartbeat interval.
            bb.status="CONNECTED • RE-PUBLISHING"
            bb.last_error="PUBLISH_NOT_CONFIRMED"
            return false
        end
        bb.status="CONNECTED • HOST PUBLISHED"
        bb.last_error=""
        bb.last_heartbeat_success_ms=bb_now()
        return true
    end

    function startup.browser_backend_fetch_hosts()
        if bb.token=="" then return false end
        if not startup.browser_terms_accepted() then
            bb.live_count=0
            if startup.browser_set_live_hosts then startup.browser_set_live_hosts({}) end
            return true
        end
        local ok,body=bb_post("browser.php",{},bb.token)
        if not ok then
            bb.last_error=tostring(body)
            if bb.last_fetch_success_ms>0 and bb_now()-bb.last_fetch_success_ms>60000 then
                bb.live_count=0
                if startup.browser_set_live_hosts then startup.browser_set_live_hosts({}) end
            end
            return false
        end
        local data=bb_json_decode(body)
        if type(data)~="table" or data.ok~=true then
            local apiErr=(type(data)=="table" and tostring(data.error or "API_ERROR")) or "INVALID_BROWSER_RESPONSE"
            if apiErr=="AUTH_EXPIRED" or apiErr=="AUTH_INVALID" or apiErr=="AUTH_REQUIRED" then
                bb_clear_auth("RECONNECTING")
                bb.next_bootstrap_ms=bb_now()+1000
            else
                bb.last_error=apiErr
            end
            return false
        end
        local hosts=type(data.hosts)=="table" and data.hosts or {}
        -- Server-side edition isolation is authoritative; this extra check prevents
        -- accidentally rendering a mismatched response if the endpoint is misconfigured.
        local expected=(startup.browser_current_edition and startup.browser_current_edition() or ""):lower()
        local responseEdition=tostring(data.edition or ""):lower()
        if expected~="" and responseEdition~="" and expected~=responseEdition then
            bb.last_error="EDITION_RESPONSE_MISMATCH"
            return false
        end
        if startup.browser_set_live_hosts then startup.browser_set_live_hosts(hosts) end
        bb.live_count=#hosts
        bb.last_fetch_success_ms=bb_now()
        bb.last_error=""
        return true
    end


    local function bb_report_join_result(joinId,result,reason)
        if bb.token=="" or not joinId or joinId=="" then return false end
        local ok,body=bb_post("join-result.php",{
            join_id=tostring(joinId),
            result=tostring(result or "FAILED"),
            reason=tostring(reason or "")
        },bb.token)
        return ok and bb_json_bool(body,"ok")==true
    end

    -- B360: strict local single-flight state. Cancellation is deliberately local and
    -- non-blocking; we do not start a second Curl request from a UI/session callback.
    local function bb_join_gen_cancelled(gen)
        gen=tonumber(gen or 0) or 0
        if gen<=0 then return true end
        if gen<=tonumber(bb.cancelled_join_generation or 0) then return true end
        return tonumber(bb.active_join_generation or 0)~=gen
    end

    local function bb_join_clear_generation(gen)
        gen=tonumber(gen or 0) or 0
        if gen>0 and tonumber(bb.active_join_generation or 0)==gen then
            bb.active_join_generation=0
        end
        bb.join_inflight=false
    end

    local function bb_join_is_active()
        return bb.join_request~=nil or bb.join_pending~=nil or bb.join_inflight==true or (tonumber(bb.active_join_generation or 0) or 0)>0
    end

    startup.browser_join_is_active_b360=function()
        return bb_join_is_active()
    end

    startup.browser_cancel_join_b360=function(reason,quiet)
        reason=tostring(reason or "USER_CANCELLED")
        local gen=tonumber(bb.active_join_generation or 0) or 0
        if gen>0 then bb.cancelled_join_generation=math.max(tonumber(bb.cancelled_join_generation or 0) or 0,gen) end
        local pending=bb.join_pending
        local request=bb.join_request
        local username=tostring((pending and pending.username) or (request and request.username) or "")
        bb.join_request=nil
        bb.join_pending=nil
        bb.join_inflight=false
        bb.active_join_generation=0
        bb.status="CONNECTED • JOIN CANCELLED"
        bb.last_error=reason
        if username~="" and startup.browser_join_restore_local_target_build335 then
            startup.browser_join_restore_local_target_build335(username,reason)
        end
        if startup.browser then
            startup.browser.joinPopupRequested=false
            startup.browser.joinPopupTarget=nil
        end
        bb.next_heartbeat_ms=bb_now()+1000
        bb.next_fetch_ms=bb_now()+1000
        if quiet~=true and startup.toast then startup.toast("Browser JOIN cancelled.",3000) end
        if startup.log then startup.log("[Browser Join 360] CANCELLED | reason="..reason.." | target="..(username~="" and username or "unknown")) end
        return true
    end

    local function bb_target_present(targetRid,targetName)
        targetRid=tostring(targetRid or "")
        targetName=tostring(targetName or "")
        local targetRidNum=tonumber(targetRid or 0) or 0

        -- Most reliable Cherax path: resolve the live player directly by Rockstar ID.
        if targetRidNum>0 and Players and Players.GetByRockstarId then
            local ok,obj=direct_call(Players.GetByRockstarId,targetRidNum)
            if ok and obj then return true,"RID_LOOKUP" end
        end

        local ids={}
        if Players and Players.Get then
            local ok,list=direct_call(Players.Get)
            if ok and type(list)=="table" then
                for _,id in pairs(list) do ids[#ids+1]=tonumber(id) end
            end
        end
        if #ids==0 then for id=0,31 do ids[#ids+1]=id end end

        for _,id in ipairs(ids) do
            if id~=nil and id>=0 and id<=31 then
                -- CNetGamePlayer:GetGamerInfo().RockstarId is available even when the
                -- convenience Players.GetRockstarId helper is temporarily unavailable.
                if targetRidNum>0 and Players and Players.GetById then
                    local okObj,obj=direct_call(Players.GetById,id)
                    if okObj and obj and obj.GetGamerInfo then
                        local okGi,gi=direct_call(function() return obj:GetGamerInfo() end)
                        local giRid=(okGi and gi) and (tonumber(gi.RockstarId or 0) or 0) or 0
                        if giRid>0 and math.floor(giRid)==math.floor(targetRidNum) then
                            return true,"GAMERINFO_RID"
                        end
                    end
                end

                if targetRidNum>0 and Players and Players.GetRockstarId then
                    local ok,rid=direct_call(Players.GetRockstarId,id)
                    if ok and rid and math.floor(tonumber(rid) or 0)==math.floor(targetRidNum) then
                        return true,"PLAYER_RID"
                    end
                end
            end
        end

        -- Browser JOIN targets are advertised Session Hosts. Exact current-host name
        -- is a safe fallback success signal when Cherax's RID helper lags during load.
        if targetName~="" and startup.get_session_host_name then
            local okHost,hostName=direct_call(function() return select(1,startup.get_session_host_name()) end)
            if okHost and tostring(hostName or ""):lower()==targetName:lower() then
                return true,"SESSION_HOST_NAME"
            end
        end

        return false,"NOT_PRESENT"
    end

    local function bb_trigger_cherax_join(rid)
        if not (FeatureMgr and FeatureMgr.GetFeatureByName) then return false,"FEATURE_MANAGER_UNAVAILABLE" end
        local ridFeature=nil
        for _,name in ipairs({"RID","Rockstar Id","Rockstar ID"}) do
            local ok,f=direct_call(FeatureMgr.GetFeatureByName,name)
            if ok and f then ridFeature=f break end
        end
        local joinFeature=nil
        for _,name in ipairs({"Join Rockstar Id","Join Rockstar ID"}) do
            local ok,f=direct_call(FeatureMgr.GetFeatureByName,name)
            if ok and f then joinFeature=f break end
        end
        if not ridFeature then return false,"RID_FEATURE_UNAVAILABLE" end
        if not joinFeature then return false,"JOIN_FEATURE_UNAVAILABLE" end
        local ridNum=tonumber(rid or 0) or 0
        if ridNum<=0 then return false,"INVALID_JOIN_RID" end
        local setOk=false
        if ridFeature.SetIntValue then setOk=direct_call(function() ridFeature:SetIntValue(ridNum) end) end
        if not setOk and ridFeature.SetValue then setOk=direct_call(function() ridFeature:SetValue(ridNum) end) end
        if not setOk and ridFeature.SetStringValue then setOk=direct_call(function() ridFeature:SetStringValue(tostring(rid)) end) end
        if not setOk then return false,"RID_SET_FAILED" end
        local clickOk=false
        if joinFeature.OnClick then clickOk=direct_call(function() joinFeature:OnClick() end) end
        if not clickOk then return false,"JOIN_CLICK_FAILED" end
        return true,nil
    end

    function startup.browser_execute_join(row)
        if not startup.browser_terms_accepted() then
            if startup.toast then startup.toast("Accept the Startup Browser Terms & Data Notice before joining.",4500) end
            return false
        end
        if not row or row.live~=true then
            if startup.toast then startup.toast("Only live Browser hosts can be joined.",3000) end
            return false
        end
        if row.blockedByYou==true then
            if startup.toast then startup.toast("This user is on your Browser personal blocklist. Unblock them before joining.",4500) end
            return false
        end
        if row.joinable~=true then
            if startup.toast then startup.toast("That host needs the current Browser update before JOIN is available.",4500) end
            return false
        end
        if bb.token=="" or startup.s.browserBackendEnabled~=true then
            if startup.toast then startup.toast("Browser backend is not connected yet.",3500) end
            return false
        end
        if bb_join_is_active() then
            if startup.toast then startup.toast("A Browser JOIN is already in progress.",3000) end
            -- B360: handled duplicate. Returning true prevents the confirmation popup
            -- from stacking a misleading generic queue-failure notification.
            return true
        end
        local listing=tostring(row.listingId or "")
        if listing=="" then
            if startup.toast then startup.toast("This Browser listing is missing its join reference.",3500) end
            return false
        end
        bb.join_generation_seq=(tonumber(bb.join_generation_seq or 0) or 0)+1
        local joinGen=bb.join_generation_seq
        bb.active_join_generation=joinGen
        bb.join_inflight=true
        bb.join_request={listing_id=listing,username=tostring(row.username or "host"),requested_ms=bb_now(),generation=joinGen}
        bb.status="JOIN REQUESTED • "..tostring(row.username or "HOST")
        if startup.toast then startup.toast("Preparing secure JOIN to "..tostring(row.username or "host").."...",3000) end
        return true
    end

    local function bb_process_join_request()
        local req=bb.join_request
        if not req or bb.token=="" then return false end
        local joinGen=tonumber(req.generation or bb.active_join_generation or 0) or 0
        if bb_join_gen_cancelled(joinGen) then bb.join_request=nil; bb.join_inflight=false; return false end
        bb.join_request=nil
        bb.join_inflight=true
        bb.status="JOINING • "..tostring(req.username or "HOST")
        -- Build 291: host-controlled Browser blacklist is checked before creating
        -- a JOIN ticket. This blocks Startup Browser JOINs cleanly without touching
        -- global Cherax Block/Redirect RID Join toggles.
        if startup.browser_trust_check_join_allowed then
            local allowed,denyReason=startup.browser_trust_check_join_allowed(tostring(req.listing_id or ""))
            if allowed==false then
                bb.status="JOIN BLOCKED BY HOST"; bb.last_error=tostring(denyReason or "BLACKLISTED_BY_HOST")
                bb_join_clear_generation(joinGen)
                if startup.toast then startup.toast("JOIN unavailable: this host has blocked Browser joins from your account.",5000) end
                return false
            end
        end
        local ok,body=false,"REQUEST_BUSY"
        for attempt=1,5 do
            ok,body=bb_post("join.php",{listing_id=tostring(req.listing_id or "")},bb.token)
            if ok or tostring(body)~="REQUEST_BUSY" then break end
            bb_yield(200+(attempt*100))
        end
        if bb_join_gen_cancelled(joinGen) then bb_join_clear_generation(joinGen); return false end
        if not ok then
            bb.status="JOIN REQUEST FAILED"; bb.last_error=tostring(body)
            bb_join_clear_generation(joinGen)
            if startup.log then startup.log("[Browser Join 297] JOIN_API_FAIL | host="..tostring(req.username or "host").." | "..tostring(body)) end
            if startup.toast then startup.toast("JOIN request failed: "..tostring(body),5000) end
            return false
        end
        local data=bb_json_decode(body)
        if type(data)~="table" or data.ok~=true then
            local apiErr=(type(data)=="table" and tostring(data.error or "API_ERROR")) or "INVALID_JOIN_RESPONSE"
            bb.status=apiErr; bb.last_error=apiErr
            bb_join_clear_generation(joinGen)
            if startup.toast then startup.toast("JOIN unavailable: "..apiErr,5000) end
            return false
        end
        local joinId=tostring(data.join_id or "")
        local rid=tostring(data.rockstar_rid or "")
        local username=tostring(data.username or req.username or "host")
        if joinId=="" or not rid:match("^%d+$") then
            bb.status="INVALID JOIN RESPONSE"; bb.last_error="INVALID_JOIN_RESPONSE"
            bb_join_clear_generation(joinGen)
            return false
        end
        if startup.browser_remember_ping_target_307 then
            startup.browser_remember_ping_target_307(tostring(req.listing_id or ""),rid,username)
        end
        if startup.log then startup.log("[Browser Join 297] JOIN_TICKET_OK | host="..username.." | joinId="..joinId.." | rid="..rid) end

        -- Build 290: if the Browser host is already in this GTA lobby, treat JOIN
        -- as successful without touching Cherax's RID Join control or leaving the session.
        local alreadyPresent,alreadyProof=bb_target_present(rid,username)
        if alreadyPresent then
            bb_report_join_result(joinId,"SUCCESS","ALREADY_IN_SESSION_"..tostring(alreadyProof or "TARGET_PRESENT"))
            bb.browser_verified_by_rid[tostring(rid or "")]={username=username,expires_ms=bb_now()+1800000}
            bb.status="CONNECTED • ALREADY IN SESSION"
            bb.last_error=""
            bb_join_clear_generation(joinGen)
            if startup.log then startup.log("[Browser Whitelist 290] ALREADY_IN_SESSION | host="..username.." | proof="..tostring(alreadyProof or "TARGET_PRESENT")) end
            if startup.toast then startup.toast("You're already in "..username.."'s GTA session.",4500) end
            bb.next_heartbeat_ms=bb_now()+1000; bb.next_fetch_ms=bb_now()+1000
            return true
        end

        -- Build 335: protect BOTH sides of an authenticated Browser JOIN. Build 290
        -- already temporarily whitelists the requester on the destination host. The
        -- joining client must also temporarily allow the selected host through its own
        -- Cherax Saved Players Block Join / Auto Kick entry, otherwise Cherax can block
        -- the host peer during the session transition and the JOIN collapses.
        if startup.browser_join_prepare_local_target_build335 then
            local localAllowed,localWhy=startup.browser_join_prepare_local_target_build335(username,rid)
            if localAllowed~=true then
                bb_report_join_result(joinId,"FAILED",tostring(localWhy or "LOCAL_SAVED_PLAYER_BLOCK"))
                bb.status="JOIN BLOCKED • LOCAL SAVED PLAYER"
                bb.last_error=tostring(localWhy or "LOCAL_SAVED_PLAYER_BLOCK")
                bb_join_clear_generation(joinGen)
                if startup.toast then startup.toast("JOIN stopped because your Cherax Saved Players entry for "..username.." could not be temporarily allowed.",6000) end
                return false
            end
        end
        if startup.browser_b335_mark_transition_quiet then startup.browser_b335_mark_transition_quiet(35000) end

        -- Build 290: join.php has now created the authenticated PENDING join ticket.
        -- Give the host's serialized whitelist worker a short window to temporarily
        -- clear Cherax Saved Players Block Join / Auto Kick for this exact requester.
        bb.status="JOIN AUTHORIZED • HOST WHITELIST"
        if startup.log then startup.log("[Browser Whitelist 290] JOIN_ALLOW_GRACE | host="..username.." | waitMs=4500") end
        local originHost=""
        if startup.get_session_host_name then
            local okOrigin,v=direct_call(function() return select(1,startup.get_session_host_name()) end)
            if okOrigin then originHost=tostring(v or "") end
        end
        bb_yield(4500)

        -- B360: a user may start a fresh session while the host whitelist grace is
        -- running. A cancelled generation must never fire the stale RID JOIN afterwards.
        if bb_join_gen_cancelled(joinGen) then
            if startup.browser_join_restore_local_target_build335 then startup.browser_join_restore_local_target_build335(username,"JOIN_CANCELLED_DURING_GRACE") end
            bb_join_clear_generation(joinGen)
            return false
        end
        if bb.published then startup.browser_backend_offline() end
        if bb_join_gen_cancelled(joinGen) then
            if startup.browser_join_restore_local_target_build335 then startup.browser_join_restore_local_target_build335(username,"JOIN_CANCELLED_BEFORE_TRIGGER") end
            bb_join_clear_generation(joinGen)
            return false
        end
        local triggered,why=bb_trigger_cherax_join(rid)
        if triggered and startup.log then startup.log("[Browser Join 297] CHERAX_JOIN_TRIGGERED | host="..username.." | rid="..rid) end
        if not triggered then
            if startup.browser_join_restore_local_target_build335 then startup.browser_join_restore_local_target_build335(username,"CHERAX_JOIN_FAILED") end
            bb_report_join_result(joinId,"FAILED",why or "CHERAX_JOIN_FAILED")
            bb.status="JOIN FAILED • "..tostring(why or "UNKNOWN")
            bb_join_clear_generation(joinGen)
            if startup.toast then startup.toast("Cherax JOIN could not start: "..tostring(why or "unknown"),5500) end
            return false
        end
        if bb_join_gen_cancelled(joinGen) then
            if startup.browser_join_restore_local_target_build335 then startup.browser_join_restore_local_target_build335(username,"JOIN_CANCELLED_AFTER_TRIGGER") end
            bb_join_clear_generation(joinGen)
            return false
        end
        bb.join_inflight=false
        bb.join_pending={join_id=joinId,target_rid=rid,username=username,started_ms=bb_now(),deadline_ms=bb_now()+90000,generation=joinGen,origin_host=originHost}
        bb.status="JOINING • "..username
        if startup.toast then startup.toast("Joining "..username.."...",3500) end
        return true
    end

    local function bb_watch_join()
        local j=bb.join_pending
        if not j then return end
        local now=bb_now()
        local joinGen=tonumber(j.generation or bb.active_join_generation or 0) or 0
        if bb_join_gen_cancelled(joinGen) then
            if startup.browser_join_restore_local_target_build335 then startup.browser_join_restore_local_target_build335(j.username,"JOIN_CANCELLED") end
            bb.join_pending=nil
            bb_join_clear_generation(joinGen)
            return
        end
        if now-(tonumber(j.started_ms or now) or now)>=2500 then
            local present,proof=bb_target_present(j.target_rid,j.username)
            if present then
                bb_report_join_result(j.join_id,"SUCCESS",tostring(proof or "TARGET_PRESENT"))
                bb.browser_verified_by_rid[tostring(j.target_rid or "")]={username=tostring(j.username or "Startup Host"),expires_ms=now+1800000}
                bb.join_pending=nil
                bb.status="CONNECTED • JOIN SUCCESS"
                bb.last_error=""
                bb_join_clear_generation(joinGen)
                if startup.log then startup.log("[Browser] JOIN confirmed via "..tostring(proof or "TARGET_PRESENT").." for "..tostring(j.username or "host")) end
                if startup.toast then startup.toast("Browser JOIN successful: "..tostring(j.username or "host"),4500) end
                bb.next_heartbeat_ms=now+1000; bb.next_fetch_ms=now+1000
                return
            end
        end
        -- B360: if RID JOIN transitions us into a settled lobby whose Session Host is
        -- neither the requested target nor the original host, the JOIN has lost ownership.
        -- Abort instead of keeping a stale 2-minute queue alive over a different session.
        if now-(tonumber(j.started_ms or now) or now)>=6000 and startup.get_session_host_name then
            local okHost,currentHost=direct_call(function() return select(1,startup.get_session_host_name()) end)
            currentHost=okHost and tostring(currentHost or "") or ""
            local target=tostring(j.username or "")
            local origin=tostring(j.origin_host or "")
            if currentHost~="" and target~="" and currentHost:lower()~=target:lower() and (origin=="" or currentHost:lower()~=origin:lower()) then
                if startup.browser_join_restore_local_target_build335 then startup.browser_join_restore_local_target_build335(j.username,"UNRELATED_SESSION") end
                bb_report_join_result(j.join_id,"FAILED","UNRELATED_SESSION")
                bb.join_pending=nil
                bb.status="CONNECTED • JOIN ABORTED"
                bb.last_error="UNRELATED_SESSION"
                bb_join_clear_generation(joinGen)
                if startup.toast then startup.toast("Browser JOIN stopped because a different session loaded.",4200) end
                bb.next_heartbeat_ms=now+1000; bb.next_fetch_ms=now+1000
                return
            end
        end
        if now>=(tonumber(j.deadline_ms or 0) or 0) then
            if startup.browser_join_restore_local_target_build335 then startup.browser_join_restore_local_target_build335(j.username,"JOIN_TIMEOUT") end
            bb_report_join_result(j.join_id,"TIMEOUT","TARGET_NOT_PRESENT")
            bb.join_pending=nil
            bb.status="CONNECTED • JOIN TIMEOUT"
            bb_join_clear_generation(joinGen)
            if startup.toast then startup.toast("JOIN timed out before the target host appeared.",5000) end
            bb.next_heartbeat_ms=now+1000; bb.next_fetch_ms=now+1000
        end
    end

    function startup.browser_backend_set_enabled(enabled)
        -- Build 215 policy: online account enrollment cannot be disabled from Startup.
        startup.s.browserBackendEnabled=true
        if bb.token=="" then bb.status="CONNECTING"; bb.next_bootstrap_ms=0 end
        return true
    end

    function startup.browser_backend_render_status()
        if not ImGui then return end
        startup.s.browserBackendEnabled=true
        local status=tostring(bb.status or "CONNECTING")
        if startup.subtle_text then startup.subtle_text("ONLINE SERVICES") else ImGui.Text("ONLINE SERVICES") end
        ImGui.SameLine()
        if status:find("CONNECTED",1,true) then
            if startup.text_colored then startup.text_colored(0.35,1.00,0.52,1.00,status) else ImGui.Text(status) end
        else
            if startup.text_colored then startup.text_colored(1.00,0.80,0.18,1.00,status) else ImGui.Text(status) end
        end
    end

    local function bb_worker()
        -- B358 Auto Start safety: let Cherax finish renderer/menu initialization before
        -- Browser Curl/bootstrap work begins. Manual loads only pay this once.
        bb_yield(2000)
        while true do
            local now=bb_now()
            startup.s.browserBackendEnabled=true
            if startup.s.browserBackendEnabled==true then
                if bb.token=="" then
                    if now>=(tonumber(bb.next_bootstrap_ms or 0) or 0) then startup.browser_backend_bootstrap() end
                else
                    -- Build 290: run the host-side whitelist poll inside the SAME
                    -- Browser backend worker as heartbeat/fetch/JOIN. This preserves
                    -- the serialized Curl ownership model and avoids creating another
                    -- parallel transport worker.
                    if startup.browser_join_whitelist_tick_build290 then
                        direct_call(startup.browser_join_whitelist_tick_build290)
                    end
                    if now>=(tonumber(bb.next_account_ms or 0) or 0) then
                        startup.browser_backend_fetch_account()
                        bb.next_account_ms=bb_now()+300000
                    end
                    if bb.join_request then bb_process_join_request() end
                    if bb.join_pending then bb_watch_join() end
                    if not bb.join_pending and not bb.join_request and now>=(tonumber(bb.next_heartbeat_ms or 0) or 0) then
                        local hbOK=startup.browser_backend_heartbeat()==true
                        if hbOK then
                            bb.b327_heartbeat_failures=0
                            bb.next_heartbeat_ms=bb_now()+10000
                        else
                            local blocked=(tostring(bb.status or "")=="HOST TOOLS DISABLED REQUIRED")
                                or (tostring(bb.status or "")=="PRIME UNSUPPORTED")
                                or (tostring(bb.status or "")=="BROWSER MAINTENANCE")
                            if blocked then
                                bb.b327_heartbeat_failures=0
                                bb.next_heartbeat_ms=bb_now()+10000
                            else
                                bb.b327_heartbeat_failures=(tonumber(bb.b327_heartbeat_failures or 0) or 0)+1
                                local retry=(bb.b327_heartbeat_failures<=1 and 2000) or (bb.b327_heartbeat_failures==2 and 5000) or 10000
                                bb.next_heartbeat_ms=bb_now()+retry
                            end
                        end
                    end
                    now=bb_now()
                    if bb.token~="" and now>=(tonumber(bb.next_fetch_ms or 0) or 0) then
                        startup.browser_backend_fetch_hosts()
                        bb.next_fetch_ms=bb_now()+8000
                    end
                end
            else
                bb.status="OFF"
            end
            bb_yield(1000)
        end
    end

    if not bb.worker_installed and Script and Script.QueueJob then
        bb.worker_installed=true
        Script.QueueJob(bb_worker)
    end
end
startup.install_browser_backend_phase3_build213()
startup.install_browser_backend_phase3_build213 = nil


-- ═══════════════════════════════════════════════════════════════════════════════════
-- tab routing
-- note: routes the minimal startup tabs from one clickgui entry.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.begin_startup_tab_item(label)
    if not ImGui or not ImGui.BeginTabItem then return false end
    return ImGui.BeginTabItem(tostring(label or "Tab")) == true
end

function startup.render_main_startup_tab()
    if startup.clickgui_render_allowed_325 and not startup.clickgui_render_allowed_325() then return end

    local startup_tab_style_count = startup.push_minimal_tab_style()
    local tab_bar_open = false
    local body_error = nil
    local body_context = nil

    local function render_tab_325(label, renderer)
        if body_error ~= nil then return end
        if not startup.begin_startup_tab_item(label) then return end
        local ok, err = pcall(renderer)
        -- Always close the tab item when BeginTabItem succeeded. This keeps the parent
        -- tab stack balanced even when a child renderer faults.
        if ImGui and ImGui.EndTabItem then pcall(ImGui.EndTabItem) end
        if not ok then
            body_error = tostring(err or "unknown renderer error")
            body_context = tostring(label or "Startup")
        end
    end

    local okFrame, frameErr = pcall(function()
        if ImGui.BeginTabBar("StartupTabs") then
            tab_bar_open = true
            render_tab_325("Main", startup.render_startup_main)
            render_tab_325("Session", startup.render_startup_flow)
            render_tab_325("Browser", startup.render_browser)
            render_tab_325("Lua", startup.render_lua_files)
            render_tab_325("Themes", startup.render_themes)
            render_tab_325("Essentials", startup.render_time_utility)
            render_tab_325("HUD", startup.render_hud_config)
            render_tab_325("Config", startup.render_config)
            render_tab_325("Guide", startup.render_guide)
            render_tab_325("Credits", startup.render_credits)
        end
    end)

    if tab_bar_open and ImGui and ImGui.EndTabBar then pcall(ImGui.EndTabBar) end

    if startup.browser_render_terms_popup then
        local okTerms, errTerms = pcall(startup.browser_render_terms_popup)
        if not okTerms and body_error == nil then
            body_error = tostring(errTerms or "terms popup render error")
            body_context = "Browser Terms"
        end
    end

    if startup.pop_minimal_tab_style then pcall(startup.pop_minimal_tab_style, startup_tab_style_count) end

    if not okFrame and body_error == nil then
        body_error = tostring(frameErr or "Startup tab frame error")
        body_context = "Startup Tab"
    end

    if body_error ~= nil then
        local rg = startup.render_guard_325
        rg.last_error = body_error
        rg.last_context = tostring(body_context or "Startup")
        rg.recovered = true
        rg.suppressed = (tonumber(rg.suppressed or 0) or 0) + 1
        local now = 0
        if Time and Time.GetEpocheMs then
            local okNow, value = direct_call(Time.GetEpocheMs)
            if okNow then now = tonumber(value or 0) or 0 end
        end
        if now <= 0 then now = math.floor((os.clock and os.clock() or 0) * 1000) end
        if (now - (tonumber(rg.last_log_ms or 0) or 0)) >= 1000 then
            rg.last_log_ms = now
            if startup.log then
                direct_call(startup.log, "[Startup 325][TAB_RENDER_RECOVERED] tab="..rg.last_context.." error="..rg.last_error)
            end
        end
        -- Critical: do NOT rethrow. Returning normally keeps Cherax's AddTab coroutine alive.
        return
    end
end

function startup.render_main_startup_tab_guarded_325()
    if startup.clickgui_render_allowed_325 and not startup.clickgui_render_allowed_325() then return end
    local ok, err = pcall(startup.render_main_startup_tab)
    if ok then return end
    local rg = startup.render_guard_325
    rg.last_error = tostring(err or "outer Startup tab render error")
    rg.last_context = "Startup AddTab callback"
    rg.recovered = true
    rg.suppressed = (tonumber(rg.suppressed or 0) or 0) + 1
    if startup.log then direct_call(startup.log, "[Startup 325][ADDTAB_CALLBACK_RECOVERED] "..rg.last_error) end
    -- Never propagate a render exception into Cherax's tab coroutine.
end

function startup.get_startup_main_tab_title()
    if startup.s.compactPinnedTabEnabled then return "S" end
    return "Startup"
end

function startup.register_startup_main_tab()
    if not ClickGUI or not ClickGUI.AddTab then return false end
    -- cherax exposes AddTab/RemoveTab but no absolute tab-index insertion API.
    -- registering Startup before delayed LuaContent scripts makes it the first
    -- Lua-added tab; compact mode uses the normal theme-controlled S label.
    if ClickGUI.RemoveTab and not startup.is_prime_active_edition() then
        local previousTitle = tostring(startup.s.registeredStartupTabTitle or "")
        if previousTitle ~= "" then direct_call(function() ClickGUI.RemoveTab(previousTitle) end) end
    end
    local title = startup.get_startup_main_tab_title()
    ClickGUI.AddTab(title, startup.render_main_startup_tab_guarded_325)
    startup.s.registeredStartupTabTitle = title
    return true
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- events and runtime
-- note: registers session, player, unload, and continuous maintenance work.
-- ═══════════════════════════════════════════════════════════════════════════════════

-- ===============================================================================
-- mass-leave stability watchdog
-- note: records a full-lobby split without making another network/session change.
-- ===============================================================================

startup.mass_leave_monitor = startup.mass_leave_monitor or { events = {}, lastTriggerMs = 0 }

function startup.reset_mass_leave_monitor(reason)
    startup.mass_leave_monitor.events = {}
    startup.mass_leave_monitor.lastTriggerMs = 0
    startup.s.massLeaveBurstLastStatus = tostring(reason or "Monitoring current session.")
end

function startup.note_mass_player_leave(playerId, playerName)
    local now = startup.now()
    local monitor = startup.mass_leave_monitor
    local kept = {}
    for _, entry in ipairs(monitor.events or {}) do
        if now - (tonumber(entry.at or 0) or 0) <= 2000 then kept[#kept + 1] = entry end
    end
    kept[#kept + 1] = { at = now, id = tonumber(playerId), name = tostring(playerName or "Unknown") }
    monitor.events = kept
    startup.s.massLeaveBurstLastCount = #kept

    if #kept < 8 or now - (tonumber(monitor.lastTriggerMs or 0) or 0) < 15000 then return false end
    monitor.lastTriggerMs = now
    startup.s.massLeaveBurstLastAtMs = now
    startup.s.massLeaveBurstLastStatus = "Detected " .. tostring(#kept) .. " remote departures inside 2 seconds."

    -- Cancel only Startup's future smart-advertise writes. Do not toggle Advertise
    -- Session, change region, start another lobby, or alter NAT during the incident.
    startup.s.advertiseFlowSerial = (tonumber(startup.s.advertiseFlowSerial or 0) or 0) + 1
    startup.s.advertiseRunning = false
    startup.s.advertiseSmartActive = false
    startup.s.advertiseStopRequested = false
    startup.s.advertiseCountdownStartedAtMs = 0
    startup.s.advertiseCountdownEndsAtMs = 0
    startup.s.advertiseActiveSinceMs = 0
    startup.s.lastAdvertiseStatus = "Paused after mass-leave burst; no network control changed"

    local names = {}
    for _, entry in ipairs(kept) do names[#names + 1] = tostring(entry.name or "Unknown") end
    local sessionHost = select(1, startup.get_session_host_name())
    local scriptHost = startup.get_script_host_name and select(1, startup.get_script_host_name()) or "Unknown"
    local detail = table.concat({
        "count=" .. tostring(#kept),
        "playersNow=" .. tostring(startup.get_session_player_count()),
        "advertiseEnabled=" .. tostring(startup.s.advertiseSessionEnabled),
        "advertiseStatus=" .. tostring(startup.s.lastAdvertiseStatus),
        "region=" .. tostring(startup.s.advertiseRegionLabel or "Unknown"),
        "nat=" .. tostring(startup.s.natOverrideLastVerified or startup.s.natOverrideMode or "Unknown"),
        "sessionHost=" .. tostring(sessionHost or "Unknown"),
        "scriptHost=" .. tostring(scriptHost or "Unknown"),
        "names=" .. table.concat(names, ",")
    }, " | ")
    if startup.support_log_event_quiet then startup.support_log_event_quiet("MASS_LEAVE_BURST", detail) end
    startup.update_support_snapshot(true, "mass-leave-burst")
    startup.toast("Startup detected a mass player timeout. Automatic advertise writes were paused and diagnostics were saved.", 8000)
    return true
end

