    EventMgr.RegisterHandler(eLuaEvent.ON_SYNC_DATA_NODE, function(nodeType, node, pEntity, isExclusive, playerId)
        if not startup.self_diag or startup.self_diag.active ~= true then return end
        if not eSyncDataNode or nodeType ~= eSyncDataNode.CPlayerGameStateDataNode or not node then return end
        local resolvedId = tonumber(playerId or -1) or -1
        if resolvedId < 0 and pEntity and pEntity.NetObject then resolvedId = tonumber(pEntity.NetObject.PlayerId or -1) or -1 end
        if not startup.self_diag.is_local_id(resolvedId) then return end
        local state = startup.self_diag.nodeState or {}
        if node.GameStateFlags then
            local flags = node.GameStateFlags
            if flags.inTutorial ~= nil then state.inTutorial = flags.inTutorial == true end
            if flags.pendingTutorialSessionChange ~= nil then state.pendingTutorialSessionChange = flags.pendingTutorialSessionChange == true end
        end
        if node.TutorialIndex ~= nil then state.tutorialIndex = tonumber(node.TutorialIndex) or node.TutorialIndex end
        if node.TutorialInstanceID ~= nil then state.tutorialInstanceId = tonumber(node.TutorialInstanceID) or node.TutorialInstanceID end
        if node.nCharacterRank ~= nil then state.characterRank = tonumber(node.nCharacterRank) or node.nCharacterRank end
        if node.nMentalState ~= nil then state.mentalState = tonumber(node.nMentalState) or node.nMentalState end
        startup.self_diag.nodeState = state
    end)
end

