-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 326: Host Tools / HostTools Browser compatibility detector
-- Host Tools is an old/outdated script that can interfere with Startup Browser sessions.
-- Detection is passive only: Startup never unloads or changes another script. We watch the
-- Cherax Lua lifecycle log in the background and, as a secondary signal, the active tab name.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.hosttools_guard_326 = startup.hosttools_guard_326 or {
    active = false,
    detected_name = "",
    source = "",
    path = nil,
    offset = 0,
    initial_scanned = false,
    last_scan_ms = 0,
    last_change_ms = 0,
}

function startup.hosttools_normalize_name_326(value)
    local name=tostring(value or ""):lower()
    name=name:gsub("%.lua$","")
    name=name:gsub("[^%w]","")
    return name
end

function startup.hosttools_name_matches_326(value)
    return startup.hosttools_normalize_name_326(value)=="hosttools"
end

function startup.hosttools_set_active_326(active,name,source)
    local hg=startup.hosttools_guard_326
    active=active==true
    local changed=hg.active~=active
    hg.active=active
    if tostring(name or "")~="" then hg.detected_name=tostring(name) end
    if tostring(source or "")~="" then hg.source=tostring(source) end
    if changed then
        hg.last_change_ms=startup.now and startup.now() or 0
        if startup.browser_backend then
            startup.browser_backend.next_heartbeat_ms=0
            startup.browser_backend.next_fetch_ms=0
        end
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet(active and "HOSTTOOLS_BROWSER_BLOCKED" or "HOSTTOOLS_BROWSER_CLEARED",
                "name="..tostring(hg.detected_name or "Host Tools").." source="..tostring(hg.source or "unknown"))
        end
    end
end

function startup.hosttools_parse_log_line_326(line)
    line=tostring(line or "")
    if line=="" then return end
    local name=line:match("%[INFO%]%s+Successfully loaded%s+'([^']+)'")
        or line:match("%[INFO%]%s+Loading%s+'([^']+)'")
    if name and startup.hosttools_name_matches_326(name) then
        startup.hosttools_set_active_326(true,name,"Cherax Lua load log")
        return
    end
    name=line:match("%[INFO%]%s+Completely unloaded%s+'([^']+)'")
        or line:match("%[INFO%]%s+Unloading%s+'([^']+)'")
    if name and startup.hosttools_name_matches_326(name) then
        startup.hosttools_set_active_326(false,name,"Cherax Lua unload log")
    end
end

function startup.hosttools_resolve_log_path_326()
    local hg=startup.hosttools_guard_326
    if hg.path and io and io.open then
        local f=io.open(hg.path,"r")
        if f then f:close(); return hg.path end
    end
    local candidates={}
    if startup.battleye_auto_block and startup.battleye_auto_block.get_candidate_paths then
        local ok,list=direct_call(startup.battleye_auto_block.get_candidate_paths)
        if ok and type(list)=="table" then candidates=list end
    end
    if #candidates==0 then
        local root=startup.menu_root or (FileMgr and FileMgr.GetMenuRootPath and FileMgr.GetMenuRootPath()) or ""
        candidates={root.."\\Cherax.log",root.."\\Logs\\Cherax.log",root.."\\logs\\Cherax.log"}
    end
    for _,path in ipairs(candidates) do
        local f=io and io.open and io.open(path,"r") or nil
        if f then f:close(); hg.path=path; hg.offset=0; hg.initial_scanned=false; return path end
    end
    return nil
end

function startup.hosttools_scan_log_326()
    if not io or not io.open then return end
    local hg=startup.hosttools_guard_326
    local path=startup.hosttools_resolve_log_path_326()
    if not path then return end
    local f=io.open(path,"r")
    if not f then return end
    local size=f:seek("end") or 0
    if hg.initial_scanned~=true or (tonumber(hg.offset or 0) or 0)>size then
        -- Reconstruct the latest HostTools load/unload state from the recent log tail so
        -- Startup still detects HostTools when it auto-started before Startup itself.
        local tailBytes=2*1024*1024
        local start=math.max(0,size-tailBytes)
        f:seek("set",start)
        local text=f:read("*a") or ""
        hg.offset=size
        hg.initial_scanned=true
        f:close()
        for line in text:gmatch("([^\r\n]+)") do startup.hosttools_parse_log_line_326(line) end
        return
    end
    f:seek("set",tonumber(hg.offset or 0) or 0)
    local text=f:read("*a") or ""
    hg.offset=f:seek() or size
    f:close()
    if text~="" then
        for line in text:gmatch("([^\r\n]+)") do startup.hosttools_parse_log_line_326(line) end
    end
end

function startup.hosttools_tick_326()
    local hg=startup.hosttools_guard_326
    local now=startup.now and startup.now() or 0
    if now-(tonumber(hg.last_scan_ms or 0) or 0)<1000 then return end
    hg.last_scan_ms=now
    -- Tab-name signal: if the user ever opens a tab named Host Tools / HostTools, that is
    -- immediate confirmation that the script is loaded. A non-matching active tab never
    -- clears the state; only a Cherax unload lifecycle line clears it.
    if ClickGUI and type(ClickGUI.GetActiveMenuTab)=="function" then
        local ok,value=direct_call(ClickGUI.GetActiveMenuTab)
        if ok and startup.hosttools_name_matches_326(value) then
            startup.hosttools_set_active_326(true,tostring(value),"active ClickGUI tab")
        end
    end
    startup.hosttools_scan_log_326()
end

function startup.browser_hosttools_access_blocked_326()
    return startup.hosttools_guard_326 and startup.hosttools_guard_326.active==true
end

