-- Print the public console identity block in its own early job. This executes
-- immediately after Cherax completes the Lua init call, before NAT, region,
-- artwork, settings, or online-start workers can delay the visible banner.
if Script and Script.QueueJob then
    Script.QueueJob(function()
        if Script.Yield then Script.Yield(50) end
        startup.print_console_banner(false)
    end)
else
    startup.print_console_banner(false)
end

Script.QueueJob(function()
    startup.boot_diag_checkpoint("MAIN_WORKER_BEGIN", "queued worker entered", true)
    -- B358 Auto Start safety: avoid native/pattern work on Cherax's first render frames.
    startup.yield(1000)
    if startup.s.pendingPrimeTabRegistration == true then
        startup.s.pendingPrimeTabRegistration = false
        startup.boot_diag_stage("REGISTER_MAIN_TAB_PRIME", startup.register_startup_main_tab)
    end
    startup.cleanBootConsoleActive = true
    startup.boot_diag_stage("CACHE_PUBLIC_URINAL_LOGO", startup.ensure_public_urinal_icon_cached)
    startup.boot_diag_stage("CACHE_STARTUP_LOGO", startup.ensure_startup_logo_cached)
    startup.boot_diag_stage("CACHE_SUBSCRIBED_SCRIPTS_ART", startup.ensure_subscribed_scripts_image_cached)
    startup.boot_diag_checkpoint("NAT_SCAN_BEGIN", "startup pattern scan", true)
    local scanOk, scanErr = direct_call(startup.run_nat_pattern_scan)
    if not scanOk then
        startup.nat_scan.lastStatus = "Pattern scan error: " .. tostring(scanErr)
        startup.boot_diag_checkpoint("NAT_SCAN_ERROR", tostring(scanErr), true)
        if startup.support_log_event_quiet then startup.support_log_event_quiet("PATTERN_SCAN_ERROR", tostring(scanErr)) end
    else
        startup.boot_diag_checkpoint("NAT_SCAN_RETURNED", tostring(startup.nat_scan and startup.nat_scan.lastStatus or "done"), true)
    end
    startup.cleanBootConsoleActive = false
    startup.yield(850)
    startup.boot_diag_checkpoint("GUI_OPEN_CHECK_SKIPPED", "Normal Startup load no longer toggles ClickGUI; guided setup retains its dedicated popup opener", true)
    startup.s.initialized = true
    startup.s.nukeJoinKickReason = "Cheater"
    startup.rid_store.load()
    startup.rid_store.migrate_build157_battleye_host_kick_records()
    startup.s.showMatchmakingRegionHud = false
    startup.s.matchmakingRegionOverrideMode = "Original"
    startup.pendingRegionOverrideApply = false
    if tostring(startup.s.natOverrideMode or "Original") ~= "Original" then
        startup.pendingNatOverrideApply = true
        startup.boot_diag_checkpoint("NAT_OVERRIDE_PENDING", "mode=" .. tostring(startup.s.natOverrideMode), true)
    end
    startup.boot_diag_stage("SAVE_CONFIG_INITIALIZED", function() return startup.save_config(false) end)
    startup.boot_diag_stage("SYNC_FEATURE_STATES_INITIALIZED", startup.sync_feature_states)
    startup.boot_diag_stage("SUPPORT_SNAPSHOT_INITIAL", function() return startup.update_support_snapshot(true, "startup-initialized") end)
    startup.boot_diag_stage("SETTINGS_PROFILE_REFRESH_INITIAL", startup.process_pending_settings_profile_refresh)
    startup.print_console_banner()
    startup.print_nat_pattern_summary(false)
    startup.print_advertise_region_summary(false)
    startup.toast_quiet("STARTUP " .. startup.version .. " initialized. Build " .. startup.build_number .. ".", 5000)
    local setupPending = startup.is_onboarding_setup_pending and startup.is_onboarding_setup_pending() or false
    startup.boot_diag_checkpoint("ONBOARDING_STATE", "pending=" .. tostring(setupPending), true)
    if setupPending then
        startup.s.lastStatus = "Waiting for Startup guided setup before loading settings or starting the online flow."
    else
        startup.boot_diag_stage("APPLY_SETTINGS_FILE", startup.apply_settings_file)
    end
    startup.yield(500)
    if startup.s.autoLoadTheme then
        startup.boot_diag_stage("APPLY_THEME_FILE", function() return startup.apply_theme_file(false) end)
        startup.yield(500)
    else
        startup.s.lastThemeStatus = "Auto-Load Theme OFF"
        startup.boot_diag_checkpoint("APPLY_THEME_SKIPPED", "Auto-Load Theme OFF", true)
    end
    if startup.is_enhanced_active_edition() then
        startup.request_advertise_region_resolution(true, "post-settings startup initialization")
        startup.s.advertiseRegionAutoScheduleNextCheckMs = 0
    end
    startup.request_advertise_session_sync(startup.s.autoAdvertiseSession == true and startup.s.oldStartupAdvertiseEnabled ~= true, "post-settings startup initialization")
    if not setupPending then
        startup.boot_diag_stage("APPLY_SESSION_TYPE", startup.apply_session_type)
        startup.yield(500)
        startup.boot_diag_stage("STARTUP_ONLINE_LAUNCH", startup.run_startup_online_launch)
    end
    startup.boot_diag_checkpoint("MAIN_LOOP_ENTER", "500ms worker loop", true)
    startup.boot_diag_status("RUNNING", "Main loop entered")
    local nextAdvertiseTickMs = 0
    while true do
        startup.yield(500)
        if startup.boot_diag_try_enable_io_359 then startup.boot_diag_try_enable_io_359(false) end
        if not startup.boot_diag.healthyMarked and not startup.boot_diag_is_early_window() then startup.boot_diag_mark_healthy() end
        startup.process_pending_reset_settings()
        startup.process_pending_nat_hud_restore()
        startup.process_pending_settings_profile_refresh()
        startup.process_pending_settings_selection_save()
        startup.process_pending_theme_load()
        startup.process_pending_cherax_host_probe()
        startup.maybe_retry_prime_nat_scan()
        startup.process_pending_nat_scan()
        startup.process_pending_advertise_region_resolution()
        startup.process_pending_advertise_region_change()
        startup.process_advertise_region_auto_schedule()
        startup.process_pending_advertise_session_sync()
        if startup.anti_afk_watchdog_tick then startup.anti_afk_watchdog_tick() end
        startup.process_native_advertise_count_visual_slider()
        startup.process_pending_subscribed_auto_start_enable()
        startup.process_pending_onboarding_commit()
        startup.process_pending_support_zip()
        if startup.self_diag and startup.self_diag.tick then startup.self_diag.tick() end
        if startup.boot_diag_is_early_window() and startup.pendingNatOverrideApply == true then
            startup.boot_diag_checkpoint("NAT_OVERRIDE_PROCESS_BEGIN", "mode=" .. tostring(startup.s.natOverrideMode or "Original"), true)
            local okNatOverride, errNatOverride = direct_call(startup.process_pending_nat_override)
            if okNatOverride then
                startup.boot_diag_checkpoint("NAT_OVERRIDE_PROCESS_OK", "status=" .. tostring(startup.s.natOverrideLastStatus or ""), true)
            else
                startup.boot_diag_checkpoint("NAT_OVERRIDE_PROCESS_ERROR", tostring(errNatOverride), true)
                if startup.support_log_event_quiet then startup.support_log_event_quiet("NAT_OVERRIDE_PROCESS_ERROR", tostring(errNatOverride)) end
            end
        else
            startup.process_pending_nat_override()
        end
        startup.process_pending_country_filter_bulk_action()
        if startup.hosttools_tick_326 then startup.hosttools_tick_326() end
        startup.maybe_start_whats_new_online()
        if startup.maybe_start_browser_terms_online_329 then startup.maybe_start_browser_terms_online_329() end
        startup.update_support_snapshot(false, "periodic")
        startup.keep_first_run_welcome_active()
        startup.battleye_auto_block.tick()
        if startup.boot_diag_is_early_window() and startup.boot_diag.countryTicksLogged < 4 then
            startup.boot_diag.countryTicksLogged = startup.boot_diag.countryTicksLogged + 1
            startup.boot_diag_checkpoint("COUNTRY_TICK_BEGIN", "tick=" .. tostring(startup.boot_diag.countryTicksLogged), true)
            local okCountry, errCountry = direct_call(startup.country_filter.tick)
            if okCountry then
                startup.boot_diag_checkpoint("COUNTRY_TICK_OK", "tick=" .. tostring(startup.boot_diag.countryTicksLogged), true)
            else
                startup.boot_diag_checkpoint("COUNTRY_TICK_ERROR", tostring(errCountry), true)
                if startup.support_log_event_quiet then startup.support_log_event_quiet("COUNTRY_TICK_ERROR", tostring(errCountry)) end
            end
        else
            startup.country_filter.tick()
        end
        startup.rid_store.tick()
        startup.crash_defense.flush_reaction_spam(false)
        startup.update_always_day()
        startup.update_always_night()
        local now = startup.now()
        if startup.s.advertiseRegionDefaultPending == true
            and (tonumber(startup.s.advertiseRegionDefaultAttempts or 0) or 0) < 24
            and now >= (tonumber(startup.s.nextAdvertiseRegionDefaultAttemptMs or 0) or 0) then
            startup.s.nextAdvertiseRegionDefaultAttemptMs = now + 5000
            direct_call(startup.apply_ee_advertise_region_default)
        end
        if startup.s.advertiseRunning and startup.s.advertiseSmartActive and now >= nextAdvertiseTickMs then
            nextAdvertiseTickMs = now + 1000
            startup.update_advertise_smart_state("main loop")
        end
    end
end)


-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 186 Self Diagnostics live-crash isolation overrides
-- Live Build 185 evidence:
--   * 503 scan completed safely.
--   * state-machine handoff completed safely.
--   * Session Type list introspection returned unavailable and skipped all three hops.
--   * fresh host Start Session succeeded and ON_SESSION_CHANGE reached
--     SESSION_LOADED_FOR_HOST.
--   * process then hard-exited before the 10-second HOST_SETTLE timer completed.
-- Build 186 therefore:
--   1) uses the same GetListIndexByString / SetListIndexByString route used by normal
--      Startup instead of enumerating the Session Type list;
--   2) keeps the custom Self Diagnosis ImGui window CLOSED for the entire active run;
--   3) uses only the normal Session tab's lightweight status panel while active;
--   4) adds host-initializer breadcrumbs so any later native crash is isolated.
-- ═══════════════════════════════════════════════════════════════════════════════════

startup.self_diag.build186NoLivePopup = true

-- Preserve Build 185 start logic, but never leave the custom window open while active.
local startup_self_diag_start_build185 = startup.self_diag.start
function startup.self_diag.start()
    local ok = startup_self_diag_start_build185()
    if ok == true and startup.self_diag.active == true then
        startup.self_diag.popupOpen = false
        startup.self_diag.log("LIVE_POPUP_DISABLED", "Build 186 active diagnostics use the Session-tab status panel only")
    end
    return ok
end

-- Exact route selection: mirror Startup's known-good normal route API and do not ask
-- Cherax to enumerate/return the underlying list table. Build 185 proved that the
-- list-return helper is unavailable on this layout even though normal Startup can
-- change Session Type successfully.
function startup.self_diag.set_session_type_exact(label)
    label = tostring(label or "")
    if label == "" then return false, "Empty Session Type label" end
    if not FeatureMgr or not startup.feature_hash or not startup.feature_hash.SESSION_TYPE then
        startup.self_diag.log("ROUTE_FEATURE_UNAVAILABLE", "label="..label)
        return false, "Session Type feature unavailable"
    end

    startup.self_diag.log("ROUTE_RESOLVE_BEGIN", "label="..label.." method=direct-string-index")
    local feature = startup.get_feature_by_hash_safe(startup.feature_hash.SESSION_TYPE)
    if not feature then
        startup.self_diag.log("ROUTE_RESOLVE_FAILED", "feature not found")
        return false, "Session Type feature not found"
    end
    if not feature.GetListIndexByString or not feature.SetListIndexByString then
        startup.self_diag.log("ROUTE_STRING_API_UNAVAILABLE", "label="..label)
        return false, "Session Type string-selection API unavailable"
    end

    startup.self_diag.log("ROUTE_INDEX_BEGIN", "label="..label)
    local okIndex, index = direct_call(function() return feature:GetListIndexByString(label) end)
    if not okIndex then
        startup.self_diag.log("ROUTE_INDEX_ERROR", "label="..label.." error="..tostring(index))
        return false, "Could not query Session Type index"
    end
    if index == nil then
        startup.self_diag.log("ROUTE_CAPABILITY_MISSING", "label="..label)
        return false, tostring(label).." is not exposed by this Cherax Session Type control"
    end
    startup.self_diag.log("ROUTE_INDEX_OK", "label="..label.." index="..tostring(index))

    startup.self_diag.log("ROUTE_SET_BEGIN", "label="..label)
    local okSet, setErr = direct_call(function()
        feature:SetListIndexByString(label)
        return true
    end)
    if not okSet or setErr ~= true then
        startup.self_diag.log("ROUTE_SET_FAILED", "label="..label.." result="..tostring(setErr))
        return false, "Could not select "..label
    end
    startup.s.sessionType = label
    startup.self_diag.log("ROUTE_SET_OK", "label="..label.." index="..tostring(index))
    return true
end

-- If Join Public Session is genuinely unavailable, do not hammer the same failed
-- capability three times. Record all hop windows as unavailable and continue to the
-- host-side portion so the one-button diagnostic still produces a useful report.
function startup.self_diag.route_hop_now()
    local sd = startup.self_diag
    local index = tonumber(sd.currentHop or 1) or 1
    startup.self_diag.log("HOP_HANDOFF_BEGIN", "state-machine index="..tostring(index))
    startup.self_diag.log("SESSION_REQUEST_BEGIN", "type=Join Public Session purpose=Self Diagnostics hop "..tostring(index))
    local ok, err = startup.self_diag.set_session_type_exact("Join Public Session")
    if not ok then
        local hop = sd.hops[index]
        if hop then hop.failed=true; hop.failReason=tostring(err or "Could not select Join Public Session") end
        startup.self_diag.log("SESSION_ROUTE_FAILED", tostring(err))
        if tostring(err or ""):find("not exposed", 1, true) or tostring(err or ""):find("unavailable", 1, true) then
            startup.self_diag.log("HOP_CAPABILITY_UNAVAILABLE", "Join Public Session unavailable; skipping hop stage after first capability test")
            for i=index+1,tonumber(sd.hopTarget or 3) do
                sd.hops[i]=startup.self_diag.new_hop(i)
                sd.hops[i].failed=true
                sd.hops[i].failReason="Join Public Session capability unavailable on this Cherax layout"
            end
            sd.phase="HOST_ROUTE"; sd.nextActionMs=startup.now()+1500; sd.popupOpen=false
            sd.status="Join Public Session is unavailable. Continuing with host-side diagnosis."
            return false
        end
        sd.phase = "HOP_FAILED_WAIT"; sd.nextActionMs = startup.now() + 1500
        return false
    end
    startup.self_diag.log("HOP_HANDOFF_READY", "route selected; click deferred to permanent worker")
    sd.phase = "HOP_CLICK_WAIT"; sd.nextActionMs = startup.now() + 750
    return true
end

-- Do not reopen the custom popup when a hopped/host session loads. This is the key
-- Build 186 crash-isolation change. All progress remains visible in Session -> Self
-- Diagnostics and is written to Cherax.log / the final report.
function startup.self_diag.on_session_loaded()
    if startup.self_diag.active ~= true then return false end
    local sd = startup.self_diag
    local now = startup.now()
    sd.popupOpen = false

    if sd.phase == "JOINING_SESSION" then
        local index=tonumber(sd.currentHop or 1) or 1
        startup.self_diag.log("SESSION_LOADED_FOR_HOP", "index="..tostring(index))
        sd.phase="HOP_SETTLE"; sd.nextActionMs=now+1500
        sd.status="Public session "..tostring(index).." loaded. Stabilizing before the 4-minute observation..."
        startup.self_diag.log("HOP_SETTLE_ARMED", "index="..tostring(index).." delayMs=1500 popup=false")
        return true
    elseif sd.phase == "RETURNING_HOST" then
        startup.self_diag.log("SESSION_LOADED_FOR_HOST", "fresh host session")
        sd.phase="HOST_SETTLE"; sd.nextActionMs=now+10000
        sd.status="Fresh host session loaded. Waiting 10 seconds to stabilize..."
        startup.self_diag.log("HOST_SETTLE_ARMED", "delayMs=10000 popup=false")
        return true
    elseif sd.phase == "HOP_OBSERVE" then
        local index=tonumber(sd.currentHop or 1) or 1; local hop=sd.hops[index]
        if hop then hop.failed=true; hop.failReason="Session changed unexpectedly during 4-minute observation" end
        startup.self_diag.log("HOP_INTERRUPTED", "index="..tostring(index))
        startup.self_diag.finish_hop_now("unexpected session change")
        sd.popupOpen=false
        return true
    elseif sd.phase == "HOST_OBSERVE" or sd.phase == "HOST_SETTLE" then
        if sd.hostObservation then sd.hostObservation.interrupted=true end
        startup.self_diag.log("HOST_INTERRUPTED", "session changed during final observation")
        sd.phase="HOST_ROUTE"; sd.nextActionMs=now+1500; sd.popupOpen=false
        return true
    end
    startup.self_diag.log("SESSION_LOADED_IGNORED", "phase="..tostring(sd.phase))
    return true
end

-- Keep popup closed when a hop observation begins too.
function startup.self_diag.begin_hop_observation_now()
    local sd = startup.self_diag
    local index = tonumber(sd.currentHop or 1) or 1
    local hop = sd.hops[index]
    if not hop then return false end
    startup.self_diag.log("HOP_INIT_BEGIN", "index="..tostring(index))
    hop.sessionLoaded = true
    hop.startedAtMs = startup.now()
    hop.startPlayers = startup.get_session_player_count()
    hop.peakPlayers = hop.startPlayers
    hop.minPlayers = hop.startPlayers
    sd.phase = "HOP_OBSERVE"
    sd.nextSampleMs = 0
    sd.popupOpen = false
    sd.status = "Observing public session "..tostring(index).."/"..tostring(sd.hopTarget).." for 4 minutes."
    startup.self_diag.log("HOP_BEGIN", "index="..tostring(index).." players="..tostring(hop.startPlayers).." popup=false")
    return true
end

-- Host initialization is deliberately breadcrumbed one operation at a time.
function startup.self_diag.begin_host_observation_now()
    local sd = startup.self_diag
    if sd.active ~= true then return false end
    sd.popupOpen = false
    startup.self_diag.log("HOST_INIT_BEGIN", "popup=false")

    startup.self_diag.log("HOST_INIT_POPULATION_BEGIN", "reading player count")
    local startPlayers = startup.get_session_player_count()
    startup.self_diag.log("HOST_INIT_POPULATION_OK", "players="..tostring(startPlayers))

    local host = {
        startedAtMs=startup.now(), startPlayers=startPlayers, peakPlayers=startPlayers, endPlayers=0,
        joinEvents=0, leaveEvents=0, peerTypes={}, direct=0, peerRelay=0, relayServer=0, unknown=0,
        milestones={}, hostName="Unknown", hostId=-1, isLocalHost=false,
        advertiser="NONE", advertiseTriggered=false, advertiseEndStatus=""
    }

    startup.self_diag.log("HOST_INIT_HOST_LOOKUP_BEGIN", "reading Session Host")
    local hName,hId = startup.get_session_host_name()
    host.hostName=tostring(hName or "Unknown")
    host.hostId=tonumber(hId or -1) or -1
    host.isLocalHost=startup.self_diag.is_local_id(host.hostId)
    startup.self_diag.log("HOST_INIT_HOST_LOOKUP_OK", "host="..host.hostName.." id="..tostring(host.hostId).." local="..tostring(host.isLocalHost))

    sd.hostObservation = host
    sd.phase = "HOST_OBSERVE"
    sd.nextSampleMs = startup.now() + 1500
    sd.status = "Host observation active | players="..tostring(startPlayers).." | waiting for first network sample..."

    startup.self_diag.log("HOST_INIT_ADVERTISE_BEGIN", "restored current="..tostring(startup.s.autoAdvertiseSession==true).." old="..tostring(startup.s.oldStartupAdvertiseEnabled==true).." super="..tostring(startup.s.superAdvertiseEnabled==true))
    if startup.s.superAdvertiseEnabled == true then
        host.advertiser="SUPER"; host.advertiseTriggered=true
        startup.run_super_advertise()
    elseif startup.s.oldStartupAdvertiseEnabled == true then
        host.advertiser="OLD_V103"; host.advertiseTriggered=true
        startup.run_selected_advertise_flow("Self Diagnostics host observation")
    elseif startup.s.autoAdvertiseSession == true then
        host.advertiser="CURRENT"; host.advertiseTriggered=true
        startup.run_selected_advertise_flow("Self Diagnostics host observation")
    end
    startup.self_diag.log("HOST_INIT_ADVERTISE_OK", "advertiser="..tostring(host.advertiser).." triggered="..tostring(host.advertiseTriggered))
    startup.self_diag.log("HOST_OBSERVE_BEGIN", "host="..host.hostName.." localHost="..tostring(host.isLocalHost).." startPlayers="..tostring(host.startPlayers).." advertiser="..tostring(host.advertiser).." popup=false")
    return true
end

-- While active the standalone window is disabled. This function only renders a very
-- small post-run results window when the user explicitly opens it after completion.
function startup.render_self_diagnostics_popup()
    local sd = startup.self_diag
    if not sd or sd.popupOpen ~= true then return end
    if sd.active == true then
        sd.popupOpen = false
        return
    end
    if not ImGui or not ImGui.Begin or not ImGui.End then return end
    local screen_w,screen_h=startup.get_display_size()
    local width=math.min(680,math.max(520,screen_w-120)); local height=math.min(460,math.max(360,screen_h-120))
    local x=math.max(18,(screen_w-width)*0.5); local y=math.max(18,(screen_h-height)*0.5)
    if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(x,y,ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(width,height,ImGuiCond and ImGuiCond.Always or 0) end
    local colors,vars=startup.push_first_run_style()
    local visible=ImGui.Begin("##Startup_Self_Diagnostics_Results_186",true,startup.first_run_window_flags())
    if visible then
        startup.render_popup_header("SELF DIAGNOSIS RESULTS", "Build 188 keeps this window closed during the deep live test for Cherax stability.", "RESULTS")
        ImGui.Separator()
        startup.status_line("Stage",tostring(sd.phase or "Idle"),0.42,0.82,1.00)
        startup.subtle_text_wrapped(tostring(sd.status or "Ready"))
        local a=sd.account or {}
        if tonumber(a.readable or 0)>0 then
            ImGui.Separator(); startup.section_title("Account")
            startup.status_line("Classification",tostring(a.classification or "Unknown"),0.72,0.42,1.00)
            startup.subtle_text_wrapped(string.format("Readable %d/503 | Repair similarity %.1f%% | Anomaly %d/100",tonumber(a.readable or 0),tonumber(a.repairNearPct or 0),tonumber(a.anomalyScore or 0)))
        end
        if tostring(sd.latestReportPath or "")~="" then
            ImGui.Separator(); startup.subtle_text_wrapped("Report: "..tostring(sd.latestReportPath))
            startup.render_color_button("COPY REPORT PATH","Gold","Copies the latest report path.",startup.self_diag.copy_report_path,-1,34)
        end
        startup.render_color_button("CLOSE","Blue","Close results window.",function() sd.popupOpen=false end,-1,34)
    end
    ImGui.End(); startup.pop_first_run_style(colors,vars)
end

-- Guard against any older state-machine branch reopening the live window.
local startup_self_diag_tick_build185 = startup.self_diag.tick
function startup.self_diag.tick()
    if startup.self_diag.active == true then startup.self_diag.popupOpen = false end
    local result = startup_self_diag_tick_build185()
    if startup.self_diag.active == true then startup.self_diag.popupOpen = false end
    return result
end

startup.self_diag.log("BUILD186_OVERRIDES_READY", "direct route strings + no live popup + host-init breadcrumbs")


-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 187 Self Diagnostics: alternating host/join + strict non-interference guard
-- Live Build 186 proved session routing is stable, but normal defensive automation
-- still acted inside joined lobbies and Cherax's Previous Session behavior recycled
-- the same lobby. Build 187 therefore alternates HOST -> JOIN -> HOST -> JOIN and
-- suppresses/removes Startup-side kick/block/save actions for the entire diagnosis.
-- Existing Cherax Saved Players Block Join / Auto Kick flags are temporarily disabled
-- and restored after the final fresh host session.
-- ═══════════════════════════════════════════════════════════════════════════════════

startup.self_diag.build187AlternatingGuard = true
local sd187 = startup.self_diag

-- Build 187 synthesis uses the alternating records rather than Build 186's
-- three-hop + one-host layout.
function startup.self_diag.synthesize()
    local out={likely={}}
    local function add(sev,msg) out.likely[#out.likely+1]={sev,msg} end
    local nat=tostring(sd187.network and sd187.network.nat or "Unknown"):upper()
    if nat:find("STRICT",1,true) then add("VERY HIGH","Strict NAT was reported by Cherax and can sharply reduce compatible P2P peers.")
    elseif nat:find("MODERATE",1,true) then add("MEDIUM","Moderate NAT was reported; compatible-peer reachability may be reduced.") end
    local h1,h2=sd187.testRecords[1],sd187.testRecords[3]
    local j1,j2=sd187.testRecords[2],sd187.testRecords[4]
    local hostJoins,hostN,hostLocal=0,0,0
    for _,r in ipairs({h1,h2}) do if r and r.loaded then hostN=hostN+1; hostJoins=hostJoins+(tonumber(r.joinEvents or 0) or 0); if r.isLocalHost then hostLocal=hostLocal+1 end end end
    local joinPeak,joinN,direct,relay=0,0,0,0
    for _,r in ipairs({j1,j2}) do if r and r.loaded then joinN=joinN+1; joinPeak=joinPeak+(tonumber(r.peakPlayers or 0) or 0); direct=direct+(tonumber(r.direct or 0) or 0); relay=relay+(tonumber(r.peerRelay or 0) or 0)+(tonumber(r.relayServer or 0) or 0) end end
    if hostN>0 and hostLocal<hostN then add("HIGH","At least one Fresh Host stage did not detect the local player as Session Host.") end
    if direct+relay>=5 then
        local pct=direct/(direct+relay)*100; out.directRatio=pct
        if pct<20 then add("HIGH",string.format("Only %.1f%% of observed joined-session peers were DIRECT.",pct))
        elseif pct<50 then add("MEDIUM",string.format("Joined-session DIRECT ratio was %.1f%%; relay use was substantial.",pct))
        else add("INFO",string.format("Joined-session peer connectivity looked healthy at %.1f%% DIRECT.",pct)) end
    end
    if joinN>0 and hostN>0 then
        local avgJoinPeak=joinPeak/joinN; local avgHostJoins=hostJoins/hostN
        if avgJoinPeak>=15 and avgHostJoins<1 then add("HIGH",string.format("Joined sessions averaged %.1f players, but hosted sessions averaged only %.1f incoming joins in four minutes; prioritize hosting/advertising/inbound reachability.",avgJoinPeak,avgHostJoins))
        elseif avgJoinPeak<8 and avgHostJoins<2 then add("MEDIUM","Both joined and hosted sessions were small/slow; broader matchmaking-pool, routing, region, ISP, or account-state factors deserve attention.") end
    end
    local extra=sd187.account and sd187.account.extra or {}
    if extra.nativeBadSport==true then add("VERY HIGH","Native Bad Sport state is active and may place the account in a separate matchmaking pool.") end
    if extra.nativeCheater==true then add("HIGH","Native Cheater state is active.") end
    local node=sd187.nodeState or {}
    if node.inTutorial==true or node.pendingTutorialSessionChange==true then add("HIGH","Tutorial/session-segmentation state was observed active.") end
    if tostring(sd187.account.classification or ""):find("Known repaired",1,true) then add("INFO","Account strongly resembles the known 503-stat repaired profile; this is correlation evidence, not a proven matchmaking cause.")
    elseif tonumber(sd187.account.anomalyScore or 0)>50 then add("RESEARCH","Account-stat relationships are substantially abnormal; keep this as a correlation variable until more runs establish an effect.") end
    if #out.likely==0 then add("INFO","No single cause was proven in this run; compare repeated alternating runs and networking metadata.") end
    sd187.synthesis=out
    return out
end
sd187.testWindowMs = 240000
sd187.testPlan = sd187.testPlan or {
    { kind="HOST", index=1, label="Fresh Host #1" },
    { kind="JOIN", index=1, label="Joined Public #1" },
    { kind="HOST", index=2, label="Fresh Host #2" },
    { kind="JOIN", index=2, label="Joined Public #2" },
}
sd187.testRecords = sd187.testRecords or {}
sd187.testPlanPos = tonumber(sd187.testPlanPos or 0) or 0
sd187.currentRecord = nil
sd187.guard = sd187.guard or { active=false, savedSettings=nil, savedPlayerStates={}, savedPlayerSelectorIndex=nil, recoveryPath="" }

function startup.self_diag.non_interference_active()
    return startup.self_diag and startup.self_diag.active == true and startup.self_diag.guard and startup.self_diag.guard.active == true
end


local function sd187_list_entries(list)
    local rows={}
    if type(list)~="table" then return rows end
    local pos=0
    for k,v in pairs(list) do if v~=nil then pos=pos+1; rows[#rows+1]={key=k,n=tonumber(k),text=tostring(v),pos=pos} end end
    table.sort(rows,function(a,b) if a.n~=nil and b.n~=nil then if a.n==b.n then return a.pos<b.pos end return a.n<b.n end if a.n~=nil then return true end if b.n~=nil then return false end return a.pos<b.pos end)
    local zeroBased=false; for _,r in ipairs(rows) do if r.n~=nil and math.floor(r.n)==0 then zeroBased=true break end end
    for i,r in ipairs(rows) do local idx=i-1; if r.n~=nil then idx=zeroBased and math.floor(r.n) or (math.floor(r.n)-1); if idx<0 then idx=i-1 end end; r.index=idx end
    return rows
end

local function sd187_set_feature_toggle(feature, wanted)
    if not feature then return false, nil end
    local before = startup.nuke_join_kick and startup.nuke_join_kick.is_actually_on and startup.nuke_join_kick.is_actually_on(feature) or false
    if before == wanted then return true, before end
    local ok = direct_call(function()
        if feature.SetBoolValue then feature:SetBoolValue(wanted == true)
        elseif feature.Toggle then feature:Toggle(wanted == true)
        else return false end
        if feature.TriggerCallback then feature:TriggerCallback() end
        return true
    end)
    local after = startup.nuke_join_kick and startup.nuke_join_kick.is_actually_on and startup.nuke_join_kick.is_actually_on(feature) or wanted
    return ok == true and after == wanted, before
end

function startup.self_diag.guard_snapshot_internal()
    local g=sd187.guard
    g.savedSettings={
        nukeJoinKickEnabled=startup.s.nukeJoinKickEnabled == true,
        battleyeAutoBlockEnabled=startup.s.battleyeAutoBlockEnabled == true,
        autoKickCrashAttackersEnabled=startup.s.autoKickCrashAttackersEnabled == true,
        autoKickKickAttackersEnabled=startup.s.autoKickKickAttackersEnabled == true,
        countryFilterEnabled=startup.s.countryFilterEnabled == true,
        blockRidJoinsEnabled=startup.s.blockRidJoinsEnabled == true,
        saveRidBattleye=startup.s.saveRidBattleye == true,
        saveRidCrash=startup.s.saveRidCrash == true,
        saveRidModder=startup.s.saveRidModder == true,
    }
end

function startup.self_diag.guard_apply_internal_off()
    startup.s.nukeJoinKickEnabled=false
    startup.s.battleyeAutoBlockEnabled=false
    startup.s.autoKickCrashAttackersEnabled=false
    startup.s.autoKickKickAttackersEnabled=false
    startup.s.countryFilterEnabled=false
    startup.s.blockRidJoinsEnabled=false
    startup.s.saveRidBattleye=false
    startup.s.saveRidCrash=false
    -- modder HUD may still display detections, but RID persistence is blocked by the
    -- record wrappers below; keep the compatibility toggle itself untouched.
    startup.set_feature_bool_silently(startup.h.NukeJoinKickEnabled,false)
    startup.set_feature_bool_silently(startup.h.AutoKickCrashAttackers,false)
    startup.set_feature_bool_silently(startup.h.AutoKickKickAttackers,false)
    startup.set_feature_bool_silently(startup.h.BattleyeAutoBlockEnabled,false)
    startup.set_feature_bool_silently(startup.h.CountryFilterEnabled,false)
