function startup.self_diag.guard_saved_players_disable()
    local g=sd187.guard
    g.savedPlayerStates={}
    if not startup.nuke_join_kick or not FeatureMgr then
        startup.self_diag.log("GUARD_SAVED_PLAYERS_UNAVAILABLE","feature helpers unavailable")
        return false
    end
    local selector,selectorName=startup.nuke_join_kick.find_global_feature_by_names(startup.nuke_join_kick.saved_players_selector_names)
    if not selector then startup.self_diag.log("GUARD_SAVED_PLAYERS_UNAVAILABLE","selector not found"); return false end
    local list=startup.nuke_join_kick.get_list(selector,selectorName)
    if type(list)~="table" then startup.self_diag.log("GUARD_SAVED_PLAYERS_UNAVAILABLE","selector list unavailable"); return false end
    if selector.GetListIndex then local ok,v=direct_call(function() return selector:GetListIndex() end); if ok then g.savedPlayerSelectorIndex=tonumber(v) end end
    local disabledBlock,disabledKick=0,0
    for _,entry in ipairs(sd187_list_entries(list)) do
        direct_call(function()
            if selector.SetListIndex then selector:SetListIndex(entry.index) end
            if selector.TriggerCallback then selector:TriggerCallback() end
        end)
        startup.yield(15)
        local blockF=startup.nuke_join_kick.find_global_feature_by_names(startup.nuke_join_kick.block_join_names)
        local kickF=startup.nuke_join_kick.find_global_feature_by_names(startup.nuke_join_kick.auto_kick_names)
        local blockOn=blockF and startup.nuke_join_kick.is_actually_on(blockF) or false
        local kickOn=kickF and startup.nuke_join_kick.is_actually_on(kickF) or false
        g.savedPlayerStates[#g.savedPlayerStates+1]={name=entry.text,listIndex=entry.index,blockJoin=blockOn,autoKick=kickOn}
        if blockOn then local ok=sd187_set_feature_toggle(blockF,false); if ok then disabledBlock=disabledBlock+1 end end
        if kickOn then local ok=sd187_set_feature_toggle(kickF,false); if ok then disabledKick=disabledKick+1 end end
    end
    if g.savedPlayerSelectorIndex~=nil then direct_call(function() selector:SetListIndex(g.savedPlayerSelectorIndex); if selector.TriggerCallback then selector:TriggerCallback() end end) end
    startup.self_diag.log("GUARD_SAVED_PLAYERS_OFF","entries="..tostring(#g.savedPlayerStates).." blockJoinDisabled="..tostring(disabledBlock).." autoKickDisabled="..tostring(disabledKick))
    return true
end

function startup.self_diag.guard_saved_players_restore()
    local g=sd187.guard
    if not startup.nuke_join_kick or not FeatureMgr or type(g.savedPlayerStates)~="table" or #g.savedPlayerStates==0 then return false end
    local selector,selectorName=startup.nuke_join_kick.find_global_feature_by_names(startup.nuke_join_kick.saved_players_selector_names)
    if not selector then return false end
    local list=startup.nuke_join_kick.get_list(selector,selectorName); if type(list)~="table" then return false end
    local map={}; for _,entry in ipairs(sd187_list_entries(list)) do map[string.lower(entry.text)]=entry.index end
    local restored=0
    for _,st in ipairs(g.savedPlayerStates) do
        local idx=map[string.lower(tostring(st.name or ""))]
        if idx~=nil then
            direct_call(function() selector:SetListIndex(idx); if selector.TriggerCallback then selector:TriggerCallback() end end)
            startup.yield(15)
            local blockF=startup.nuke_join_kick.find_global_feature_by_names(startup.nuke_join_kick.block_join_names)
            local kickF=startup.nuke_join_kick.find_global_feature_by_names(startup.nuke_join_kick.auto_kick_names)
            if blockF then sd187_set_feature_toggle(blockF,st.blockJoin==true) end
            if kickF then sd187_set_feature_toggle(kickF,st.autoKick==true) end
            restored=restored+1
        end
    end
    if g.savedPlayerSelectorIndex~=nil then direct_call(function() selector:SetListIndex(g.savedPlayerSelectorIndex); if selector.TriggerCallback then selector:TriggerCallback() end end) end
    startup.self_diag.log("GUARD_SAVED_PLAYERS_RESTORED","entries="..tostring(restored))
    return true
end

