            return
        end
        return oldHandle(playerName,line,reason)
    end
end

function startup.self_diag.set_advertising_for_test(kind)
    local hostMode=tostring(kind or "")=="HOST"
    local s=sd187.saved or {}
    startup.s.advertiseFlowSerial=(tonumber(startup.s.advertiseFlowSerial or 0) or 0)+1
    startup.s.oldStartupAdvertiseSerial=(tonumber(startup.s.oldStartupAdvertiseSerial or 0) or 0)+1
    startup.s.superAdvertiseSerial=(tonumber(startup.s.superAdvertiseSerial or 0) or 0)+1
    startup.s.advertiseRunning=false; startup.s.oldStartupAdvertiseRunning=false; startup.s.superAdvertiseRunning=false; startup.s.advertiseSmartActive=false
    startup.s.autoAdvertiseSession=hostMode and s.autoAdvertiseSession==true or false
    startup.s.oldStartupAdvertiseEnabled=hostMode and s.oldStartupAdvertiseEnabled==true or false
    startup.s.superAdvertiseEnabled=hostMode and s.superAdvertiseEnabled==true or false
    startup.set_feature_bool_silently(startup.h.AutoAdvertiseSession,startup.s.autoAdvertiseSession)
    startup.set_feature_bool_silently(startup.h.OldStartupAdvertise,startup.s.oldStartupAdvertiseEnabled)
    startup.set_feature_bool_silently(startup.h.SuperAdvertise,startup.s.superAdvertiseEnabled)
    if not hostMode then startup.set_advertise_session(false,true) end
end

function startup.self_diag.new_test_record(kind,index,label)
    return {kind=kind,index=index,label=label,loaded=false,failed=false,failReason="",startedAtMs=0,finishedAtMs=0,startPlayers=0,endPlayers=0,peakPlayers=0,minPlayers=99,joinEvents=0,leaveEvents=0,peerTypes={},direct=0,peerRelay=0,relayServer=0,unknown=0,milestones={},firstHost="Unknown",firstHostId=-1,hostChanges=0,lastHostId=nil,isLocalHost=false}
end

function startup.self_diag.sample_test_record(r)
    local count=startup.get_session_player_count(); r.peakPlayers=math.max(tonumber(r.peakPlayers or 0) or 0,count); r.minPlayers=math.min(tonumber(r.minPlayers or 99) or 99,count)
    local elapsed=startup.now()-(tonumber(r.startedAtMs or startup.now()) or startup.now())
    for _,target in ipairs({5,10,15,20,25,30}) do if count>=target and r.milestones[target]==nil then r.milestones[target]=elapsed end end
    local hName,hId=startup.get_session_host_name(); hId=tonumber(hId or -1) or -1
    if r.lastHostId==nil then r.lastHostId=hId; r.firstHostId=hId; r.firstHost=tostring(hName or "Unknown"); r.isLocalHost=startup.self_diag.is_local_id(hId)
    elseif hId>=0 and r.lastHostId>=0 and hId~=r.lastHostId then r.hostChanges=(tonumber(r.hostChanges or 0) or 0)+1; r.lastHostId=hId end
    for _,pid in ipairs(startup.get_voice_player_ids and startup.get_voice_player_ids() or {}) do if not startup.self_diag.is_local_id(pid) then r.peerTypes[tostring(pid)..":"..startup.get_player_name_safe(pid)]=startup.self_diag.net_type_name(pid) end end
end

function startup.self_diag.route_current_test()
    local spec=sd187.testPlan[sd187.testPlanPos]; if not spec then return false end
    local target=spec.kind=="HOST" and "New Public Session" or "Join Public Session"
    startup.self_diag.set_advertising_for_test(spec.kind)
    sd187.currentRecord=startup.self_diag.new_test_record(spec.kind,spec.index,spec.label)
    sd187.testRecords[sd187.testPlanPos]=sd187.currentRecord
    sd187.phase="ALT_ROUTE"; sd187.status="Routing to "..spec.label.."..."
    startup.self_diag.log("ALT_ROUTE_BEGIN","step="..tostring(sd187.testPlanPos).." kind="..spec.kind.." label="..spec.label.." target="..target)
    local ok,err=startup.self_diag.set_session_type_exact(target)
    if not ok then sd187.currentRecord.failed=true; sd187.currentRecord.failReason=tostring(err); startup.self_diag.log("ALT_ROUTE_FAILED",tostring(err)); sd187.phase="ALT_NEXT_WAIT"; sd187.nextActionMs=startup.now()+2000; return false end
    sd187.phase="ALT_CLICK_WAIT"; sd187.nextActionMs=startup.now()+750; return true
end

function startup.self_diag.click_current_test()
    local spec=sd187.testPlan[sd187.testPlanPos]; if not spec then return false end
    startup.self_diag.log("ALT_SESSION_CLICK_BEGIN",spec.label)
    local ok=startup.click_start_session_feature(); startup.self_diag.log("ALT_SESSION_CLICK_END",spec.label.." ok="..tostring(ok))
    if not ok then sd187.currentRecord.failed=true; sd187.currentRecord.failReason="Start Session click failed"; sd187.phase="ALT_NEXT_WAIT"; sd187.nextActionMs=startup.now()+2000; return false end
    sd187.phase="ALT_WAIT_LOAD"; sd187.sessionRequestAtMs=startup.now(); sd187.status="Loading "..spec.label.."..."; return true
end

function startup.self_diag.begin_current_observation()
    local r=sd187.currentRecord; local spec=sd187.testPlan[sd187.testPlanPos]; if not r or not spec then return false end
    r.loaded=true; r.startedAtMs=startup.now(); r.startPlayers=startup.get_session_player_count(); r.peakPlayers=r.startPlayers; r.minPlayers=r.startPlayers
    local hn,hid=startup.get_session_host_name(); r.firstHost=tostring(hn or "Unknown"); r.firstHostId=tonumber(hid or -1) or -1; r.lastHostId=r.firstHostId; r.isLocalHost=startup.self_diag.is_local_id(r.firstHostId)
    if spec.kind=="HOST" then local saved=sd187.saved or {}; r.advertiser=saved.superAdvertiseEnabled and "SUPER" or (saved.oldStartupAdvertiseEnabled and "OLD_V103" or (saved.autoAdvertiseSession and "CURRENT" or "NONE")) else r.advertiser="OFF_DURING_JOIN" end
    sd187.phase="ALT_OBSERVE"; sd187.nextSampleMs=0; sd187.status=spec.label.." | 04:00 remaining | players="..tostring(r.startPlayers)
    startup.self_diag.log("ALT_OBSERVE_BEGIN","step="..sd187.testPlanPos.." kind="..spec.kind.." players="..r.startPlayers.." host="..r.firstHost.." localHost="..tostring(r.isLocalHost))
    return true
end

function startup.self_diag.finish_current_observation(reason)
    local r=sd187.currentRecord; local spec=sd187.testPlan[sd187.testPlanPos]
    if r then startup.self_diag.sample_test_record(r); r.finishedAtMs=startup.now(); r.endPlayers=startup.get_session_player_count(); startup.self_diag.finalize_peer_counts(r); startup.self_diag.log("ALT_OBSERVE_END","step="..tostring(sd187.testPlanPos).." kind="..tostring(r.kind).." reason="..tostring(reason).." start="..tostring(r.startPlayers).." end="..tostring(r.endPlayers).." peak="..tostring(r.peakPlayers).." joins="..tostring(r.joinEvents).." direct="..tostring(r.direct).." relay="..tostring((r.peerRelay or 0)+(r.relayServer or 0))) end
    sd187.currentRecord=nil; sd187.phase="ALT_NEXT_WAIT"; sd187.nextActionMs=startup.now()+2000; sd187.status=(spec and spec.label or "Session").." complete. Preparing next stage..."
