function startup.self_diag.route_final_host187()
    startup.self_diag.log("FINAL_HOST_ROUTE_BEGIN","restoring Startup choices and starting fresh host")
    startup.self_diag.set_advertising_for_test("JOIN")
    -- Keep Self Diagnostics in sole control until the final fresh host actually loads.
    -- Saved finders/routing/advertising choices are restored in finish(), not before.
    local target=(startup.is_prime_active_edition() and startup.s.primeHostSessionsEnabled == false) and "Join Public Session" or "New Public Session"
    local ok,err=startup.self_diag.set_session_type_exact(target)
    if not ok then startup.self_diag.log("FINAL_HOST_ROUTE_FAILED",tostring(err)); startup.self_diag.guard_saved_players_restore(); startup.self_diag.guard_restore_internal(); sd187.guard.active=false; startup.self_diag.finish("Final host route failed"); return false end
