end

function startup.self_diag.write_report(reason)
    startup.self_diag.ensure_dir(); local path=startup.self_diag_dir.."\\"..startup.self_diag.safe_filename(sd187.runId).."_Self_Diagnosis.txt"; local f=io.open(path,"w"); if not f then return false end
    local function w(x) f:write(tostring(x or ""),"\n") end
    local a=sd187.account or {}; local n=sd187.network or {}; local ip=n.ip or {}
    w("STARTUP SELF DIAGNOSTICS"); w("========================"); w("Build: "..tostring(startup.build_number)); w("Run: "..tostring(sd187.runId)); w("Finished: "..os.date("%Y-%m-%d %H:%M:%S")); w("Reason: "..tostring(reason or "Completed")); w("")
    w("ACCOUNT"); w("-------"); w(string.format("Playtime: %.2f hours",tonumber(a.playHours or 0))); w("Rank: "..tostring(a.rank or "Unknown")); w("XP: "..tostring(a.xp or "Unknown")); w("Readable repair-template stats: "..tostring(a.readable or 0).." / 503"); w(string.format("Known repair near similarity (2%%): %.2f%%",tonumber(a.repairNearPct or 0))); w("Account classification: "..tostring(a.classification or "Unknown")); w("Organic plausibility: "..tostring(a.organicPlausibility or "?").." / 100"); w("Profile coherence: "..tostring(a.profileCoherence or "?").." / 100"); w("Account anomaly score: "..tostring(a.anomalyScore or 0).." / 100"); w("")
    w("NETWORK / LOCATION"); w("------------------"); w("NAT: "..tostring(n.nat or "Unknown")); w("CGNAT: "..tostring(n.cgnat or "Unknown")); w("Country: "..tostring(ip.country or "Unknown")); w("Region: "..tostring(ip.region or "")); w("Approximate city: "..tostring(ip.city or "")); w("ISP/Org: "..tostring(ip.isp or "")); w("ASN: "..tostring(ip.asn or "")); w("")
    w("DIAGNOSTIC NON-INTERFERENCE"); w("---------------------------"); w("Startup kick/block/RID actions suppressed: YES"); w("Saved Players Block Join / Auto Kick temporarily neutralized: "..tostring(type(sd187.guard.savedPlayerStates)=="table" and #sd187.guard.savedPlayerStates or 0).." entries inspected"); w("Detection/logging remained passive."); w("")
    w("ALTERNATING 4-MINUTE SESSION TESTS"); w("----------------------------------")
    for i,spec in ipairs(sd187.testPlan or {}) do local r=sd187.testRecords[i]; if r then w(string.format("%d. %s: loaded=%s failed=%s start=%d end=%d peak=%d joins=%d leaves=%d host=%s localHost=%s DIRECT=%d PEER_RELAY=%d RELAY_SERVER=%d directRatio=%s",i,spec.label,tostring(r.loaded==true),tostring(r.failed==true),tonumber(r.startPlayers or 0),tonumber(r.endPlayers or 0),tonumber(r.peakPlayers or 0),tonumber(r.joinEvents or 0),tonumber(r.leaveEvents or 0),tostring(r.firstHost or "Unknown"),tostring(r.isLocalHost),tonumber(r.direct or 0),tonumber(r.peerRelay or 0),tonumber(r.relayServer or 0),r.directRatio and string.format("%.1f%%",r.directRatio) or "Unknown")); if r.failReason~="" then w("   Failure: "..r.failReason) end else w(tostring(i)..". "..spec.label..": not completed") end end
    w(""); w("ACCOUNT FINDINGS"); w("----------------"); for _,item in ipairs(sd187.findings or {}) do w("["..tostring(item.severity or "INFO").."] "..tostring(item.code or "").." - "..tostring(item.text or "")) end
    local syn=startup.self_diag.synthesize(); w(""); w("LIKELY CAUSES / NEXT PRIORITIES"); w("------------------------------"); for i,item in ipairs(syn.likely or {}) do w(tostring(i)..". ["..tostring(item[1]).."] "..tostring(item[2])) end
    w(""); w("FINAL STATE"); w("-----------"); w("A fresh hosting session is requested after Joined Public #2. Saved Startup and Saved Players protection settings are restored only after that final session loads."); w(""); w("Interpretation: account/network findings are correlation evidence unless directly proven. The alternating test deliberately prevents Startup enforcement from contaminating joined-lobby behavior.")
    f:close(); sd187.latestReportPath=path; startup.s.selfDiagLastReportPath=path; return true
end

function startup.self_diag.write_history(reason)
