function startup.self_diag.start()
    if sd187.active==true then startup.toast("Self Diagnosis is already running.",3000); return false end
    startup.self_diag.ensure_dir(); sd187.serial=(tonumber(sd187.serial or 0) or 0)+1; sd187.active=true; sd187.popupOpen=false; sd187.abortRequested=false; sd187.abortReason=""; sd187.phase="PREFLIGHT_PENDING"; sd187.status="Starting Build 187 alternating diagnosis..."; sd187.startedAtMs=startup.now(); sd187.startedAtEpoch=os.time(); sd187.nextActionMs=startup.now()+250; sd187.nextSampleMs=0; sd187.testPlanPos=0; sd187.testRecords={}; sd187.currentRecord=nil; sd187.hops={}; sd187.hostObservation=nil; sd187.nodeState={}; sd187.findings={}; sd187.guard={active=false,savedSettings=nil,savedPlayerStates={},savedPlayerSelectorIndex=nil}
    local meta=startup.get_support_runtime_metadata and startup.get_support_runtime_metadata() or {}; sd187.runId=startup.self_diag.safe_filename(meta.localPlayerName or "ACCOUNT").."_"..os.date("%Y_%m_%d_%H%M%S")
    startup.self_diag.snapshot_user_settings(); startup.self_diag.suspend_normal_automation(); startup.self_diag.log("START","run="..sd187.runId.." build="..tostring(startup.build_number).." engine=alternating-host-join-guard")
    return true
end

