function startup.self_diag.on_session_loaded()
    if sd187.active~=true then return false end
    local now=startup.now(); sd187.popupOpen=false
    if sd187.phase=="ALT_WAIT_LOAD" then
        local spec=sd187.testPlan[sd187.testPlanPos]; startup.self_diag.log("ALT_SESSION_LOADED",spec and spec.label or "unknown"); sd187.phase="ALT_SETTLE"; sd187.nextActionMs=now+(spec and spec.kind=="HOST" and 5000 or 2500); sd187.status=(spec and spec.label or "Session").." loaded. Stabilizing..."; return true
    elseif sd187.phase=="ALT_OBSERVE" then
        local r=sd187.currentRecord; if r then r.failed=true; r.failReason="Session changed unexpectedly during observation" end; startup.self_diag.log("ALT_INTERRUPTED",r and r.label or "unknown"); startup.self_diag.finish_current_observation("unexpected session change"); return true
    elseif sd187.phase=="FINAL_HOST_WAIT_LOAD" then
        startup.self_diag.log("FINAL_HOST_LOADED","fresh host session"); sd187.phase="FINAL_HOST_SETTLE"; sd187.nextActionMs=now+5000; sd187.status="Final fresh host loaded. Restoring protection settings safely..."; return true
    end
    startup.self_diag.log("SESSION_LOADED_IGNORED","phase="..tostring(sd187.phase)); return true
end

function startup.self_diag.finish(reason)
    if sd187.phase=="COMPLETE" then return end
    -- Always restore both Startup defense settings and Cherax Saved Players state.
    startup.self_diag.guard_saved_players_restore(); startup.self_diag.guard_restore_internal(); sd187.guard.active=false
    startup.self_diag.restore_user_settings(true)
    sd187.active=false; sd187.phase="COMPLETE"; sd187.status="Self Diagnosis complete - fresh hosting session left running."
    startup.self_diag.write_report(reason or "Completed"); startup.self_diag.write_history(reason or "Completed")
    if startup.s.initialized and startup.save_config then startup.save_config(false) end
    startup.self_diag.log("COMPLETE","reason="..tostring(reason).." report="..tostring(sd187.latestReportPath)); startup.toast("Self Diagnosis complete. Fresh host session is running.",6000)
end

function startup.self_diag.tick()
    if sd187.active~=true then return end
    local now=startup.now()
    if sd187.abortRequested then sd187.abortRequested=false; sd187.phase="FINAL_HOST_ROUTE"; sd187.nextActionMs=now; sd187.status="Stopping test and returning to a fresh host..."; return end
    if sd187.phase=="PREFLIGHT_PENDING" and now>=sd187.nextActionMs then
        sd187.phase="ACCOUNT_SCAN"; startup.self_diag.capture_preflight(); startup.self_diag.scan_account(); startup.self_diag.write_account_snapshot(); startup.self_diag.log("ACCOUNT_STAGE_COMPLETE","Build 187 scanner complete")
        startup.self_diag.guard_snapshot_internal(); startup.self_diag.guard_apply_internal_off(); sd187.guard.active=true; startup.self_diag.log("NON_INTERFERENCE_GUARD_ON","Startup kick/block/RID actions disabled")
        startup.self_diag.guard_saved_players_disable(); startup.self_diag.set_advertising_for_test("JOIN")
        sd187.phase="ALT_NEXT_WAIT"; sd187.nextActionMs=startup.now()+1500; return
    end
    if sd187.phase=="ALT_NEXT_WAIT" and now>=sd187.nextActionMs then
        sd187.testPlanPos=sd187.testPlanPos+1
        if sd187.testPlanPos>#sd187.testPlan then sd187.phase="FINAL_HOST_ROUTE"; sd187.nextActionMs=now; return end
        startup.self_diag.route_current_test(); return
    end
    if sd187.phase=="ALT_CLICK_WAIT" and now>=sd187.nextActionMs then startup.self_diag.click_current_test(); return end
    if sd187.phase=="ALT_WAIT_LOAD" then if now-(tonumber(sd187.sessionRequestAtMs or now) or now)>=60000 then local r=sd187.currentRecord; if r then r.failed=true;r.failReason="No session-loaded event within 60 seconds" end; startup.self_diag.finish_current_observation("load timeout") end; return end
    if sd187.phase=="ALT_SETTLE" and now>=sd187.nextActionMs then startup.self_diag.begin_current_observation(); return end
    if sd187.phase=="ALT_OBSERVE" then
        local r=sd187.currentRecord; if not r then sd187.phase="ALT_NEXT_WAIT"; sd187.nextActionMs=now; return end
        if now>=tonumber(sd187.nextSampleMs or 0) then sd187.nextSampleMs=now+5000; startup.self_diag.sample_test_record(r); local deadline=r.startedAtMs+sd187.testWindowMs; sd187.status=r.label.." | "..startup.self_diag.format_ms(math.max(0,deadline-now)).." left | players="..tostring(startup.get_session_player_count()).." | joins="..tostring(r.joinEvents or 0) end
        if now>=r.startedAtMs+sd187.testWindowMs then startup.self_diag.finish_current_observation("4-minute window complete") end; return
    end
    if sd187.phase=="FINAL_HOST_ROUTE" and now>=sd187.nextActionMs then startup.self_diag.route_final_host187(); return end
    if sd187.phase=="FINAL_HOST_CLICK_WAIT" and now>=sd187.nextActionMs then
        startup.self_diag.log("FINAL_HOST_CLICK_BEGIN","type="..tostring(startup.s.sessionType)); local ok=startup.click_start_session_feature(); startup.self_diag.log("FINAL_HOST_CLICK_END","ok="..tostring(ok)); if not ok then startup.self_diag.finish("Final host click failed"); return end; sd187.phase="FINAL_HOST_WAIT_LOAD"; sd187.sessionRequestAtMs=now; sd187.status="Starting final fresh host session..."; return
    end
    if sd187.phase=="FINAL_HOST_WAIT_LOAD" then if now-(tonumber(sd187.sessionRequestAtMs or now) or now)>=60000 then startup.self_diag.finish("Final host load timeout") end; return end
    if sd187.phase=="FINAL_HOST_SETTLE" and now>=sd187.nextActionMs then startup.self_diag.finish(sd187.abortReason~="" and ("Stopped early: "..sd187.abortReason) or "Completed alternating host/join test"); return end
end

function startup.render_self_diagnostics_panel()
    if not ClickGUI.BeginCustomChildWindow("Self Diagnostics") then return end
    startup.section_title("Self Diagnostics")
    startup.subtle_text_wrapped("Build 187 alternates four controlled 4-minute windows: Fresh Host #1 -> Joined Public #1 -> Fresh Host #2 -> Joined Public #2, then returns to a final fresh host. During the entire diagnosis Startup enters strict non-interference mode: no kick, Block Join, Auto Kick, RID blocking/saving, country kick, Battleye auto-block, or crash/kick auto-removal.")
    ImGui.Separator(); startup.render_feature_guarded_325(startup.h.RunSelfDiagnostics); startup.render_feature_guarded_325(startup.h.OpenSelfDiagnostics); if startup.self_diag.active then startup.render_feature_guarded_325(startup.h.StopSelfDiagnostics) end
    startup.status_line("State",tostring(startup.self_diag.phase or "Idle"),startup.self_diag.active and 0.35 or 0.72,startup.self_diag.active and 1.00 or 0.72,startup.self_diag.active and 0.45 or 0.72); startup.subtle_text_wrapped(tostring(startup.self_diag.status or "Ready"))
    if startup.self_diag.active and startup.self_diag.guard and startup.self_diag.guard.active then startup.text_colored_wrapped(0.35,1.00,0.45,1.00,"NON-INTERFERENCE ACTIVE: Startup will only observe/log players; it will not remove or block anyone.") end
    for i,spec in ipairs(startup.self_diag.testPlan or {}) do local r=startup.self_diag.testRecords and startup.self_diag.testRecords[i] or nil; if r then local ratio=r.directRatio and string.format("%.0f%% direct",r.directRatio) or "direct pending"; startup.subtle_text_wrapped(spec.label..": start "..tostring(r.startPlayers or 0).." | peak "..tostring(r.peakPlayers or 0).." | joins "..tostring(r.joinEvents or 0).." | "..ratio..(r.failed and (" | INTERRUPTED: "..tostring(r.failReason)) or "")) else startup.subtle_text(spec.label..": pending") end end
    local a=startup.self_diag.account or {}; if tonumber(a.readable or 0)>0 then ImGui.Separator(); startup.status_line("Account",tostring(a.classification or "Unknown"),0.72,0.42,1.00); startup.subtle_text_wrapped(string.format("Readable %d/503 | Repair similarity %.1f%% | Anomaly %d/100",tonumber(a.readable or 0),tonumber(a.repairNearPct or 0),tonumber(a.anomalyScore or 0))) end
    if tostring(startup.self_diag.latestReportPath or "")~="" then startup.subtle_text_wrapped("Last report: "..tostring(startup.self_diag.latestReportPath)) end
    ClickGUI.EndCustomChildWindow()
end

startup.self_diag.log("BUILD187_OVERRIDES_READY","alternating HOST/JOIN x2 + strict non-interference + saved-player guard + nil-safe history")

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 188 Self Diagnostics: deep 4-cycle host/join study + unique-host recovery
--
-- Design goals from live Build 187:
--   * collect four real HOST samples and four JOIN samples over about one hour;
--   * a JOIN sample may last at most four minutes;
--   * any confirmed host kick / desync / unexpected session loss during JOIN immediately
--     requests a fresh New Public Session instead of allowing another Join request;
--   * after an interrupted/duplicate JOIN, hold a confirmed local-host reset session for
--     at least one minute before retrying that same JOIN sample;
--   * remember joined-session host RID/name and reject recycled hosts so "Joining Previous
--     Session" cannot silently become a new diagnostic sample;
--   * never let Startup kick/block/save RIDs while diagnosis is active.
-- ═══════════════════════════════════════════════════════════════════════════════════

startup.self_diag.build188DeepCycles = true
local sd188 = startup.self_diag

sd188.hostWindowMs = 600000       -- 10 minutes x 4 host samples = 40 minutes
sd188.joinWindowMs = 240000       -- 4 minutes x 4 joined samples = 16 minutes
sd188.resetHostWindowMs = 60000   -- minimum separation after interrupted/duplicate join
sd188.maxRuntimeMs = 4500000      -- 75 minute hard safety cap including transitions/retries
sd188.maxJoinAttemptsPerSlot = 4
sd188.sessionLoadTimeoutMs = 60000
sd188.pollLoadAfterMs = 2500
sd188.testPlan = {
    { kind="HOST", index=1, label="Hosted Session #1" },
    { kind="JOIN", index=1, label="Joined Session #1" },
    { kind="HOST", index=2, label="Hosted Session #2" },
    { kind="JOIN", index=2, label="Joined Session #2" },
    { kind="HOST", index=3, label="Hosted Session #3" },
    { kind="JOIN", index=3, label="Joined Session #3" },
    { kind="HOST", index=4, label="Hosted Session #4" },
    { kind="JOIN", index=4, label="Joined Session #4" },
}

local function sd188_host_rid(playerId)
    local pid=tonumber(playerId or -1) or -1
    if pid<0 then return 0 end
    if startup.presence and startup.presence.get_player_rid then
        local ok,v=direct_call(startup.presence.get_player_rid,pid)
        if ok then return tonumber(v or 0) or 0 end
    end
    if Players and Players.GetRockstarId then
        local ok,v=direct_call(Players.GetRockstarId,pid)
        if ok then return tonumber(v or 0) or 0 end
    end
    return 0
end

local function sd188_host_key(name,id)
    local rid=sd188_host_rid(id)
    if rid>0 then return "RID:"..tostring(math.floor(rid)),rid end
    local n=string.lower(tostring(name or "Unknown")):gsub("^%s+",""):gsub("%s+$","")
    return "NAME:"..n,0
end

local function sd188_current_host_identity()
    local name,id=startup.get_session_host_name()
    id=tonumber(id or -1) or -1
    local key,rid=sd188_host_key(name,id)
    return tostring(name or "Unknown"),id,rid,key
end

local function sd188_is_current_target_ready(spec)
    if not spec then return false,"no-spec" end
    local count=startup.get_session_player_count()
    local name,id,rid,key=sd188_current_host_identity()
    if spec.kind=="HOST" then
        if count>=1 and id>=0 and startup.self_diag.is_local_id(id) then return true,"local-host",name,id,rid,key end
        return false,"waiting-local-host",name,id,rid,key
    end
    if count>=2 and id>=0 and not startup.self_diag.is_local_id(id) then return true,"remote-host",name,id,rid,key end
    return false,"waiting-remote-host",name,id,rid,key
end

local function sd188_window_for(spec)
    return spec and spec.kind=="HOST" and sd188.hostWindowMs or sd188.joinWindowMs
end

function startup.self_diag.new_test_record(kind,index,label)
    return {
        kind=kind,index=index,label=label,loaded=false,failed=false,failReason="",
        startedAtMs=0,finishedAtMs=0,startPlayers=0,endPlayers=0,peakPlayers=0,minPlayers=99,
        joinEvents=0,leaveEvents=0,joinTimes={},peerTypes={},direct=0,peerRelay=0,relayServer=0,unknown=0,
        milestones={},firstHost="Unknown",firstHostId=-1,firstHostRid=0,firstHostKey="",hostChanges=0,lastHostId=nil,
        isLocalHost=false,advertiser="NONE",kickDetected=false,kickReason="",kickHost="",duplicateHost=false,
        completedWindow=false,attempt=1,source="MAIN"
    }
end

function startup.self_diag.sample_test_record(r)
    if not r then return end
    local count=startup.get_session_player_count()
    r.peakPlayers=math.max(tonumber(r.peakPlayers or 0) or 0,count)
    r.minPlayers=math.min(tonumber(r.minPlayers or 99) or 99,count)
    local elapsed=startup.now()-(tonumber(r.startedAtMs or startup.now()) or startup.now())
    for _,target in ipairs({2,5,10,15,20,25,30}) do
        if count>=target and r.milestones[target]==nil then r.milestones[target]=elapsed end
    end
    local hName,hId,hRid,hKey=sd188_current_host_identity()
    if r.lastHostId==nil then
        r.lastHostId=hId; r.firstHostId=hId; r.firstHost=hName; r.firstHostRid=hRid; r.firstHostKey=hKey
        r.isLocalHost=startup.self_diag.is_local_id(hId)
    elseif hId>=0 and r.lastHostId>=0 and hId~=r.lastHostId then
        r.hostChanges=(tonumber(r.hostChanges or 0) or 0)+1; r.lastHostId=hId
    end
    for _,pid in ipairs(startup.get_voice_player_ids and startup.get_voice_player_ids() or {}) do
        if not startup.self_diag.is_local_id(pid) then
            r.peerTypes[tostring(pid)..":"..startup.get_player_name_safe(pid)]=startup.self_diag.net_type_name(pid)
        end
    end
end

local function sd188_count_joins_before(r,ms)
    local n=0
    for _,v in ipairs(r and r.joinTimes or {}) do if tonumber(v or 0) and tonumber(v)<=ms then n=n+1 end end
    return n
end

local function sd188_finalize_record(r)
    if not r then return end
    startup.self_diag.sample_test_record(r)
    r.finishedAtMs=startup.now(); r.endPlayers=startup.get_session_player_count(); startup.self_diag.finalize_peer_counts(r)
    r.durationMs=math.max(0,(tonumber(r.finishedAtMs or 0) or 0)-(tonumber(r.startedAtMs or r.finishedAtMs or 0) or 0))
    r.joins1m=sd188_count_joins_before(r,60000)
    r.joins4m=sd188_count_joins_before(r,240000)
    r.joins10m=sd188_count_joins_before(r,600000)
end

local function sd188_append_join_attempt(r,reason)
    if not r then return end
    if r.durationMs==nil then sd188_finalize_record(r) end
    r.finishReason=tostring(reason or "")
    sd188.joinAttempts=sd188.joinAttempts or {}
    sd188.joinAttempts[#sd188.joinAttempts+1]=r
end

local function sd188_remember_join_host(r)
    if not r or tostring(r.firstHostKey or "")=="" then return end
    sd188.seenJoinHosts=sd188.seenJoinHosts or {}
    sd188.seenJoinHosts[r.firstHostKey]={name=r.firstHost,rid=r.firstHostRid,firstSeenMs=startup.now()}
end

function startup.self_diag.signal_join_exit(reason,hostName)
    if sd188.active~=true then return false end
    local r=sd188.currentRecord
    if sd188.phase~="ALT_OBSERVE" or not r or r.kind~="JOIN" then return false end
    if sd188.joinExitRequested then return true end
    sd188.joinExitRequested=true
    sd188.joinExitReason=tostring(reason or "joined-session interruption")
    if hostName and tostring(hostName)~="" then r.kickHost=tostring(hostName) end
    if string.find(string.lower(sd188.joinExitReason),"kick",1,true) then r.kickDetected=true; r.kickReason=sd188.joinExitReason end
    startup.self_diag.log("JOIN_EXIT_REQUESTED",sd188.joinExitReason.." host="..tostring(r.kickHost or r.firstHost or "Unknown"))
    return true
end

-- Confirmed host kicks are the fastest reliable signal that Cherax is about to recycle
-- the previous session. Record it, but never retaliate; ask the state machine to create
-- a fresh host session on its next normal tick.
if startup.crash_defense and not startup.crash_defense._selfDiag188KickSignalWrapped then
    startup.crash_defense._selfDiag188KickSignalWrapped=true
    local oldNote188=startup.crash_defense.note_confirmed_host_kick
    startup.crash_defense.note_confirmed_host_kick=function(playerName,reason)
        if startup.self_diag and startup.self_diag.active==true then
            startup.self_diag.signal_join_exit("Confirmed host kick: "..tostring(reason or "Host Kick"),playerName)
        end
        return oldNote188(playerName,reason)
    end
end

function startup.self_diag.route_current_test()
    local spec=sd188.testPlan[sd188.testPlanPos]; if not spec then return false end
    local target=spec.kind=="HOST" and "New Public Session" or "Join Public Session"
    startup.self_diag.set_advertising_for_test(spec.kind=="HOST" and "HOST" or "JOIN")
    local attempt=(sd188.joinAttemptBySlot and sd188.joinAttemptBySlot[spec.index]) or 1
    sd188.currentRecord=startup.self_diag.new_test_record(spec.kind,spec.index,spec.label)
    sd188.currentRecord.attempt=attempt
    sd188.testRecords[sd188.testPlanPos]=spec.kind=="HOST" and sd188.currentRecord or nil
    sd188.phase="ALT_ROUTE"; sd188.status="Routing to "..spec.label.."..."
    startup.self_diag.log("DEEP_ROUTE_BEGIN","step="..tostring(sd188.testPlanPos).." kind="..spec.kind.." label="..spec.label.." target="..target.." attempt="..tostring(attempt))
    local ok,err=startup.self_diag.set_session_type_exact(target)
    if not ok then
        sd188.currentRecord.failed=true; sd188.currentRecord.failReason=tostring(err); startup.self_diag.log("DEEP_ROUTE_FAILED",tostring(err))
        if spec.kind=="JOIN" then return startup.self_diag.begin_reset_host("Join route failed: "..tostring(err),true) end
        sd188.phase="ALT_NEXT_WAIT"; sd188.nextActionMs=startup.now()+2000; return false
    end
    sd188.phase="ALT_CLICK_WAIT"; sd188.nextActionMs=startup.now()+750; return true
end

function startup.self_diag.click_current_test()
    local spec=sd188.testPlan[sd188.testPlanPos]; if not spec then return false end
    startup.self_diag.log("DEEP_SESSION_CLICK_BEGIN",spec.label)
    local ok=startup.click_start_session_feature(); startup.self_diag.log("DEEP_SESSION_CLICK_END",spec.label.." ok="..tostring(ok))
    if not ok then
        sd188.currentRecord.failed=true; sd188.currentRecord.failReason="Start Session click failed"
        if spec.kind=="JOIN" then return startup.self_diag.begin_reset_host("Join click failed",true) end
        sd188.phase="ALT_NEXT_WAIT"; sd188.nextActionMs=startup.now()+2000; return false
    end
    sd188.phase="ALT_WAIT_LOAD"; sd188.sessionRequestAtMs=startup.now(); sd188.lastLoadPollReadyMs=0
    sd188.status="Loading "..spec.label.."..."; return true
end

function startup.self_diag.begin_current_observation()
    local r=sd188.currentRecord; local spec=sd188.testPlan[sd188.testPlanPos]; if not r or not spec then return false end
    local ready,why,hname,hid,hrid,hkey=sd188_is_current_target_ready(spec)
    if not ready then return false end
    if spec.kind=="JOIN" then
        sd188.seenJoinHosts=sd188.seenJoinHosts or {}
        if sd188.seenJoinHosts[hkey] then
            r.loaded=true; r.duplicateHost=true; r.failed=true; r.failReason="Duplicate joined-session host recycled: "..tostring(hname)
            r.startedAtMs=startup.now(); r.startPlayers=startup.get_session_player_count(); r.firstHost=hname; r.firstHostId=hid; r.firstHostRid=hrid; r.firstHostKey=hkey
            startup.self_diag.log("DUPLICATE_JOIN_HOST","slot="..tostring(spec.index).." host="..tostring(hname).." rid="..tostring(hrid).." key="..tostring(hkey))
            sd188_append_join_attempt(r,"duplicate host rejected")
            sd188.currentRecord=nil; sd188.testRecords[sd188.testPlanPos]=nil
            return startup.self_diag.begin_reset_host("Duplicate host rejected: "..tostring(hname),true)
        end
    end
    r.loaded=true; r.startedAtMs=startup.now(); r.startPlayers=startup.get_session_player_count(); r.peakPlayers=r.startPlayers; r.minPlayers=r.startPlayers
    r.firstHost=hname; r.firstHostId=hid; r.firstHostRid=hrid; r.firstHostKey=hkey; r.lastHostId=hid; r.isLocalHost=startup.self_diag.is_local_id(hid)
    if spec.kind=="JOIN" then sd188_remember_join_host(r); r.advertiser="OFF_DURING_JOIN" else
        local saved=sd188.saved or {}; r.advertiser=saved.superAdvertiseEnabled and "SUPER" or (saved.oldStartupAdvertiseEnabled and "OLD_V103" or (saved.autoAdvertiseSession and "CURRENT" or "NONE"))
        -- on_session_loaded is intentionally bypassed/polled during diagnostics, so start
        -- the user's selected advertiser ourselves for each confirmed local-host sample.
        if startup.run_selected_advertise_flow then
            local ok=direct_call(startup.run_selected_advertise_flow,"Self Diagnostics "..spec.label)
            startup.self_diag.log("HOST_ADVERTISE_START",spec.label.." advertiser="..tostring(r.advertiser).." ok="..tostring(ok))
        end
    end
    sd188.phase="ALT_OBSERVE"; sd188.nextSampleMs=0; sd188.joinExitRequested=false; sd188.joinExitReason=""
    local window=sd188_window_for(spec)
    sd188.status=spec.label.." | "..startup.self_diag.format_ms(window).." remaining | players="..tostring(r.startPlayers)
    startup.self_diag.log("DEEP_OBSERVE_BEGIN","step="..sd188.testPlanPos.." kind="..spec.kind.." players="..r.startPlayers.." host="..r.firstHost.." rid="..tostring(r.firstHostRid).." localHost="..tostring(r.isLocalHost).." windowMs="..tostring(window))
    return true
end

function startup.self_diag.finish_current_observation(reason,forceRetryJoin)
    local r=sd188.currentRecord; local spec=sd188.testPlan[sd188.testPlanPos]
    if not r or not spec then return false end
    sd188_finalize_record(r); r.finishReason=tostring(reason or "")
    startup.self_diag.log("DEEP_OBSERVE_END","step="..tostring(sd188.testPlanPos).." kind="..tostring(r.kind).." reason="..tostring(reason).." durationMs="..tostring(r.durationMs).." start="..tostring(r.startPlayers).." end="..tostring(r.endPlayers).." peak="..tostring(r.peakPlayers).." joins="..tostring(r.joinEvents).." joins1m="..tostring(r.joins1m).." direct="..tostring(r.direct).." relay="..tostring((r.peerRelay or 0)+(r.relayServer or 0)))
    if spec.kind=="JOIN" then
        sd188_append_join_attempt(r,reason)
        local completed=(reason=="4-minute window complete") and not r.duplicateHost
        r.completedWindow=completed
        if completed then
            sd188.testRecords[sd188.testPlanPos]=r
            sd188.joinAttemptBySlot[spec.index]=1
            sd188.currentRecord=nil; sd188.phase="ALT_NEXT_WAIT"; sd188.nextActionMs=startup.now()+250
            sd188.status=spec.label.." complete. Creating next fresh host session..."
            return true
        end
        local attempts=tonumber(sd188.joinAttemptBySlot[spec.index] or 1) or 1
        if forceRetryJoin~=false and attempts<sd188.maxJoinAttemptsPerSlot then
            sd188.joinAttemptBySlot[spec.index]=attempts+1; sd188.currentRecord=nil; sd188.testRecords[sd188.testPlanPos]=nil
            return startup.self_diag.begin_reset_host("Retry "..spec.label.." after "..tostring(reason),true)
        end
        r.failed=true; r.failReason=r.failReason~="" and r.failReason or tostring(reason)
        sd188.testRecords[sd188.testPlanPos]=r; sd188.currentRecord=nil; sd188.phase="ALT_NEXT_WAIT"; sd188.nextActionMs=startup.now()+250
        return true
    end
    -- HOST samples are always retained, including interrupted ones, because instability
    -- while we are the confirmed Session Host is itself diagnostic evidence.
    if reason~="10-minute window complete" then r.failed=true; if r.failReason=="" then r.failReason=tostring(reason) end end
    sd188.testRecords[sd188.testPlanPos]=r; sd188.currentRecord=nil; sd188.phase="ALT_NEXT_WAIT"; sd188.nextActionMs=startup.now()+250
    return true
end

function startup.self_diag.begin_reset_host(reason,retrySameJoin)
    sd188.resetReason=tostring(reason or "join separation")
    sd188.resetRetrySameJoin=retrySameJoin==true
    sd188.resetRouteAttempts=0; sd188.resetLoadedAtMs=0; sd188.resetStartPlayers=0; sd188.resetPeakPlayers=0; sd188.resetJoinEvents=0
    sd188.joinExitRequested=false; sd188.joinExitReason=""; sd188.currentRecord=nil
    startup.self_diag.set_advertising_for_test("JOIN")
    sd188.phase="RESET_HOST_ROUTE"; sd188.nextActionMs=startup.now()+250
    sd188.status="Creating one-minute fresh host reset before another joined-lobby attempt..."
    startup.self_diag.log("RESET_HOST_REQUESTED",sd188.resetReason)
    return true
end

local function sd188_route_reset_host()
    sd188.resetRouteAttempts=(tonumber(sd188.resetRouteAttempts or 0) or 0)+1
    startup.self_diag.log("RESET_HOST_ROUTE","attempt="..tostring(sd188.resetRouteAttempts).." reason="..tostring(sd188.resetReason))
    local ok,err=startup.self_diag.set_session_type_exact("New Public Session")
    if not ok then startup.self_diag.log("RESET_HOST_ROUTE_FAILED",tostring(err)); sd188.nextActionMs=startup.now()+2000; return false end
    sd188.phase="RESET_HOST_CLICK"; sd188.nextActionMs=startup.now()+750; return true
end

local function sd188_click_reset_host()
    startup.self_diag.log("RESET_HOST_CLICK_BEGIN","")
    local ok=startup.click_start_session_feature(); startup.self_diag.log("RESET_HOST_CLICK_END","ok="..tostring(ok))
    if not ok then sd188.phase="RESET_HOST_ROUTE"; sd188.nextActionMs=startup.now()+2000; return false end
    sd188.phase="RESET_HOST_WAIT_LOAD"; sd188.sessionRequestAtMs=startup.now(); return true
end

local function sd188_begin_reset_hold()
    sd188.resetLoadedAtMs=startup.now(); sd188.resetStartPlayers=startup.get_session_player_count(); sd188.resetPeakPlayers=sd188.resetStartPlayers
    sd188.phase="RESET_HOST_HOLD"; sd188.nextSampleMs=0
    startup.self_diag.log("RESET_HOST_CONFIRMED","localHost=true holdMs="..tostring(sd188.resetHostWindowMs).." startPlayers="..tostring(sd188.resetStartPlayers))
end

local function sd188_finish_reset_hold()
    startup.self_diag.log("RESET_HOST_COMPLETE","reason="..tostring(sd188.resetReason).." peak="..tostring(sd188.resetPeakPlayers or 0).." joins="..tostring(sd188.resetJoinEvents or 0))
    sd188.phase="ALT_ROUTE_RETRY_JOIN"; sd188.nextActionMs=startup.now()+250
end

local function sd188_retry_same_join()
    local spec=sd188.testPlan[sd188.testPlanPos]
    if not spec or spec.kind~="JOIN" then sd188.phase="ALT_NEXT_WAIT"; sd188.nextActionMs=startup.now(); return end
    startup.self_diag.log("JOIN_RETRY_AFTER_RESET","slot="..tostring(spec.index).." attempt="..tostring(sd188.joinAttemptBySlot[spec.index] or 1))
    startup.self_diag.route_current_test()
end

-- Build 188 does not trust the global session-event debounce to tell diagnostics that a
-- requested session is usable. Polling local/remote host identity is authoritative.
function startup.self_diag.on_session_loaded()
    if sd188.active~=true then return false end
    local now=startup.now(); sd188.popupOpen=false
    if sd188.phase=="ALT_OBSERVE" then
        local r=sd188.currentRecord
        if r and r.kind=="JOIN" then startup.self_diag.signal_join_exit("Unexpected session change during joined observation",r.firstHost) return true end
        if r and r.kind=="HOST" then r.failed=true; r.failReason="Hosted session changed unexpectedly"; startup.self_diag.finish_current_observation("hosted session changed unexpectedly",false); return true end
    end
    -- ALT_WAIT_LOAD / RESET_HOST_WAIT_LOAD are intentionally left for the polling path;
    -- duplicate session callbacks cannot prematurely accept the wrong recycled lobby.
    startup.self_diag.log("SESSION_EVENT_OBSERVED","phase="..tostring(sd188.phase).."; readiness decided by host polling")
    return true
end

function startup.self_diag.on_player_join(playerId)
    if sd188.active~=true or startup.self_diag.is_local_id(playerId) then return end
    local now=startup.now(); local r=sd188.currentRecord
    if sd188.phase=="ALT_OBSERVE" and r then
        r.joinEvents=(tonumber(r.joinEvents or 0) or 0)+1
        r.joinTimes=r.joinTimes or {}; r.joinTimes[#r.joinTimes+1]=math.max(0,now-(tonumber(r.startedAtMs or now) or now))
    elseif sd188.phase=="RESET_HOST_HOLD" then
        sd188.resetJoinEvents=(tonumber(sd188.resetJoinEvents or 0) or 0)+1
    end
end

function startup.self_diag.on_player_left(playerId)
    if sd188.active~=true or startup.self_diag.is_local_id(playerId) then return end
    local r=sd188.currentRecord
    if sd188.phase=="ALT_OBSERVE" and r then r.leaveEvents=(tonumber(r.leaveEvents or 0) or 0)+1 end
end

function startup.self_diag.start()
    if sd188.active==true then startup.toast("Self Diagnosis is already running.",3000); return false end
    startup.self_diag.ensure_dir(); sd188.serial=(tonumber(sd188.serial or 0) or 0)+1
    sd188.active=true; sd188.popupOpen=false; sd188.abortRequested=false; sd188.abortReason=""; sd188.phase="PREFLIGHT_PENDING"
    sd188.status="Starting Build 188 deep ~1-hour diagnosis..."; sd188.startedAtMs=startup.now(); sd188.startedAtEpoch=os.time(); sd188.nextActionMs=startup.now()+250; sd188.nextSampleMs=0
    sd188.testPlanPos=0; sd188.testRecords={}; sd188.currentRecord=nil; sd188.joinAttempts={}; sd188.joinAttemptBySlot={1,1,1,1}; sd188.seenJoinHosts={}; sd188.rejectedJoinHosts={}; sd188.nodeState={}; sd188.findings={}; sd188.joinExitRequested=false; sd188.joinExitReason=""
    sd188.guard={active=false,savedSettings=nil,savedPlayerStates={},savedPlayerSelectorIndex=nil}
    local meta=startup.get_support_runtime_metadata and startup.get_support_runtime_metadata() or {}; sd188.runId=startup.self_diag.safe_filename(meta.localPlayerName or "ACCOUNT").."_"..os.date("%Y_%m_%d_%H%M%S")
    startup.self_diag.snapshot_user_settings(); startup.self_diag.suspend_normal_automation(); startup.self_diag.log("START","run="..sd188.runId.." build="..tostring(startup.build_number).." engine=deep-4cycle-unique-host")
    return true
end

function startup.self_diag.finish(reason)
    if sd188.phase=="COMPLETE" then return end
    startup.self_diag.guard_saved_players_restore(); startup.self_diag.guard_restore_internal(); sd188.guard.active=false
    startup.self_diag.restore_user_settings(true)
    sd188.active=false; sd188.phase="COMPLETE"; sd188.status="Self Diagnosis complete - fresh hosting session left running."
    startup.self_diag.write_report(reason or "Completed"); startup.self_diag.write_history(reason or "Completed")
    if startup.s.initialized and startup.save_config then startup.save_config(false) end
    startup.self_diag.log("COMPLETE","reason="..tostring(reason).." report="..tostring(sd188.latestReportPath)); startup.toast("Deep Self Diagnosis complete. Fresh host session is running.",6000)
end

function startup.self_diag.synthesize()
    local out={likely={}}; local function add(sev,msg) out.likely[#out.likely+1]={sev,msg} end
    local nat=tostring(sd188.network and sd188.network.nat or "Unknown"):upper()
    if nat:find("STRICT",1,true) then add("VERY HIGH","Strict NAT was reported by Cherax and sharply narrows compatible P2P peers.") elseif nat:find("MODERATE",1,true) then add("MEDIUM","Moderate NAT was reported; compatible-peer reachability may be reduced.") end
    local hostN,hostLocal,totalHostJoins,hostWithJoin,hostPeaks=0,0,0,0,{}
    local joinN,joinPeak,direct,relay,joinKickCount=0,0,0,0,0
    for pos=1,#(sd188.testPlan or {}) do
        local r=sd188.testRecords and sd188.testRecords[pos] or nil
        if r and r.loaded then
            if r.kind=="HOST" then hostN=hostN+1; if r.isLocalHost then hostLocal=hostLocal+1 end; totalHostJoins=totalHostJoins+(tonumber(r.joinEvents or 0) or 0); if (r.joinEvents or 0)>0 then hostWithJoin=hostWithJoin+1 end; hostPeaks[#hostPeaks+1]=tonumber(r.peakPlayers or 0) or 0
            elseif r.kind=="JOIN" then joinN=joinN+1; joinPeak=joinPeak+(tonumber(r.peakPlayers or 0) or 0); direct=direct+(tonumber(r.direct or 0) or 0); relay=relay+(tonumber(r.peerRelay or 0) or 0)+(tonumber(r.relayServer or 0) or 0); if r.kickDetected then joinKickCount=joinKickCount+1 end end
        end
    end
    joinKickCount=0
    for _,r in ipairs(sd188.joinAttempts or {}) do if r.kickDetected then joinKickCount=joinKickCount+1 end end
    if hostN>0 and hostLocal<hostN then add("HIGH",tostring(hostN-hostLocal).." hosted samples did not confirm the local player as Session Host.") end
    if hostN>=3 then
        local avg=totalHostJoins/hostN
        if hostWithJoin==0 then add("HIGH","Across "..hostN.." confirmed hosted sessions, no random incoming joins were observed during the host windows.")
        elseif hostWithJoin>=3 then add("INFO",string.format("Incoming matchmaking worked in %d/%d hosted sessions (%.1f joins per host sample on average).",hostWithJoin,hostN,avg))
        else add("MEDIUM",string.format("Only %d/%d hosted sessions received random joins; hosting reachability appears inconsistent.",hostWithJoin,hostN)) end
    end
    if direct+relay>=5 then local pct=direct/(direct+relay)*100; out.directRatio=pct; if pct<20 then add("HIGH",string.format("Only %.1f%% of joined-session peer observations were DIRECT.",pct)) elseif pct<50 then add("MEDIUM",string.format("Joined-session DIRECT ratio was %.1f%%; relay dependency was substantial.",pct)) else add("INFO",string.format("Joined-session connectivity looked healthy at %.1f%% DIRECT.",pct)) end end
    if joinN>0 and hostN>0 then local avgJoinPeak=joinPeak/joinN; local avgHostJoins=totalHostJoins/hostN; if avgJoinPeak>=15 and avgHostJoins<1 then add("HIGH",string.format("Joined sessions averaged %.1f players while hosted sessions averaged %.1f incoming joins; prioritize host advertisement/inbound reachability over general ability to join GTA Online.",avgJoinPeak,avgHostJoins)) end end
    if joinKickCount>=2 then add("HIGH","Multiple joined-session host kicks/session removals occurred. The diagnostic forced fresh host resets between retries so recycled Previous Session lobbies were not treated as independent samples.") end
    local unique=0; for _ in pairs(sd188.seenJoinHosts or {}) do unique=unique+1 end
    if unique>0 then add("INFO","Observed "..tostring(unique).." unique joined-session host identities during the deep test.") end
    local extra=sd188.account and sd188.account.extra or {}; if extra.nativeBadSport==true then add("VERY HIGH","Native Bad Sport state is active and may place the account in a separate matchmaking pool.") end; if extra.nativeCheater==true then add("HIGH","Native Cheater state is active.") end
    local node=sd188.nodeState or {}; if node.inTutorial==true or node.pendingTutorialSessionChange==true then add("HIGH","Tutorial/session-segmentation state was observed active.") end
    if tostring(sd188.account.classification or ""):find("Known repaired",1,true) then add("INFO","Account strongly resembles the known 503-stat repaired profile; treat this as correlation evidence, not a proven matchmaking cause.") elseif tonumber(sd188.account.anomalyScore or 0)>50 then add("RESEARCH","Account-stat relationships are substantially abnormal; retain this as a correlation variable.") end
    local completed=hostN+joinN; out.confidence=math.min(100,math.floor((completed/8)*80 + (unique>=3 and 10 or unique*3) + ((sd188.account.readable or 0)>=400 and 10 or 5)))
    if #out.likely==0 then add("INFO","No single cause was proven. Compare the four host samples, unique joined-host samples, and network/account metadata together.") end
    sd188.synthesis=out; return out
end

local function sd188_ms(v) if v==nil then return "-" end return startup.self_diag.format_ms(tonumber(v or 0) or 0) end

function startup.self_diag.write_report(reason)
    startup.self_diag.ensure_dir(); local path=startup.self_diag_dir.."\\"..startup.self_diag.safe_filename(sd188.runId).."_Self_Diagnosis.txt"; local f=io.open(path,"w"); if not f then return false end
    local function w(x) f:write(tostring(x or ""),"\n") end; local a=sd188.account or {}; local n=sd188.network or {}; local ip=n.ip or {}; local syn=startup.self_diag.synthesize()
    w("STARTUP SELF DIAGNOSTICS - DEEP 4-CYCLE STUDY"); w("============================================"); w("Build: "..tostring(startup.build_number)); w("Run: "..tostring(sd188.runId)); w("Finished: "..os.date("%Y-%m-%d %H:%M:%S")); w("Reason: "..tostring(reason or "Completed")); w("Planned design: 4 hosted sessions x 10m + 4 unique-host joined sessions x up to 4m (~56m observation + transitions).")
    w(""); w("ACCOUNT"); w("-------"); w(string.format("Playtime: %.2f hours",tonumber(a.playHours or 0))); w("Rank: "..tostring(a.rank or "Unknown")); w("XP: "..tostring(a.xp or "Unknown")); w("Readable repair-template stats: "..tostring(a.readable or 0).." / 503"); w(string.format("Known repair near similarity (2%%): %.2f%%",tonumber(a.repairNearPct or 0))); w("Account classification: "..tostring(a.classification or "Unknown")); w("Organic plausibility: "..tostring(a.organicPlausibility or "?").." / 100"); w("Profile coherence: "..tostring(a.profileCoherence or "?").." / 100"); w("Account anomaly score: "..tostring(a.anomalyScore or 0).." / 100")
    w(""); w("NETWORK / LOCATION"); w("------------------"); w("NAT: "..tostring(n.nat or "Unknown")); w("CGNAT: "..tostring(n.cgnat or "Unknown")); w("Country: "..tostring(ip.country or "Unknown")); w("Region: "..tostring(ip.region or "")); w("Approximate city: "..tostring(ip.city or "")); w("ISP/Org: "..tostring(ip.isp or "")); w("ASN: "..tostring(ip.asn or ""))
    w(""); w("NON-INTERFERENCE"); w("----------------"); w("Startup kick/block/RID actions suppressed: YES"); w("Joined-lobby detection remained passive. Confirmed BattlEye host kicks are recorded only and trigger host-reset recovery."); w("Actual process-level GTA/Cherax crashes cannot be recovered by Lua after the process exits; surviving session-loss/desync/kick transitions are recovered automatically.")
    w(""); w("MAIN 4-CYCLE SAMPLES"); w("--------------------")
    for i,spec in ipairs(sd188.testPlan or {}) do local r=sd188.testRecords[i]; if r then
        if r.kind=="HOST" then w(string.format("%d. %s | loaded=%s localHost=%s duration=%s start=%d peak=%d end=%d joins=%d joins@1m=%d joins@4m=%d joins@10m=%d advertiser=%s failed=%s",i,spec.label,tostring(r.loaded),tostring(r.isLocalHost),sd188_ms(r.durationMs),tonumber(r.startPlayers or 0),tonumber(r.peakPlayers or 0),tonumber(r.endPlayers or 0),tonumber(r.joinEvents or 0),tonumber(r.joins1m or 0),tonumber(r.joins4m or 0),tonumber(r.joins10m or 0),tostring(r.advertiser or "NONE"),tostring(r.failed)))
        else w(string.format("%d. %s | loaded=%s completed4m=%s host=%s rid=%s duration=%s start=%d peak=%d end=%d DIRECT=%d PEER_RELAY=%d RELAY_SERVER=%d directRatio=%s kicked=%s failed=%s",i,spec.label,tostring(r.loaded),tostring(r.completedWindow),tostring(r.firstHost or "Unknown"),tostring(r.firstHostRid or 0),sd188_ms(r.durationMs),tonumber(r.startPlayers or 0),tonumber(r.peakPlayers or 0),tonumber(r.endPlayers or 0),tonumber(r.direct or 0),tonumber(r.peerRelay or 0),tonumber(r.relayServer or 0),r.directRatio and string.format("%.1f%%",r.directRatio) or "Unknown",tostring(r.kickDetected),tostring(r.failed))) end
        local mt={}
        for _,target in ipairs({2,5,10,15,20,25,30}) do if r.milestones and r.milestones[target]~=nil then mt[#mt+1]=tostring(target).."p@"..sd188_ms(r.milestones[target]) end end
        if #mt>0 then w("   Population milestones: "..table.concat(mt," | ")) end
        if tostring(r.failReason or "")~="" then w("   Failure: "..tostring(r.failReason)) end
    else w(tostring(i)..". "..spec.label..": not completed") end end
    w(""); w("ALL JOIN ATTEMPTS / RECYCLED HOSTS"); w("----------------------------------")
    for i,r in ipairs(sd188.joinAttempts or {}) do w(string.format("Attempt %d | slot=%d attempt=%d host=%s rid=%s duration=%s peak=%d kicked=%s duplicate=%s reason=%s",i,tonumber(r.index or 0),tonumber(r.attempt or 0),tostring(r.firstHost or "Unknown"),tostring(r.firstHostRid or 0),sd188_ms(r.durationMs),tonumber(r.peakPlayers or 0),tostring(r.kickDetected),tostring(r.duplicateHost),tostring(r.finishReason or r.failReason or ""))) end
    local unique=0; for _ in pairs(sd188.seenJoinHosts or {}) do unique=unique+1 end; w("Unique joined-session hosts observed: "..tostring(unique))
    w(""); w("ACCOUNT FINDINGS"); w("----------------"); for _,item in ipairs(sd188.findings or {}) do w("["..tostring(item.severity or "INFO").."] "..tostring(item.code or "").." - "..tostring(item.text or "")) end
    w(""); w("SYNTHESIS"); w("---------"); w("Diagnostic confidence: "..tostring(syn.confidence or 0).." / 100"); for i,item in ipairs(syn.likely or {}) do w(tostring(i)..". ["..tostring(item[1]).."] "..tostring(item[2])) end
    w(""); w("Interpretation: the strongest diagnosis comes from agreement between repeated hosted-session behavior, unique joined-session behavior, DIRECT/relay observations, network metadata, special matchmaking states, and the 503-stat account profile. No single account stat is declared causal by itself.")
    f:close(); sd188.latestReportPath=path; startup.s.selfDiagLastReportPath=path; return true
end

function startup.self_diag.write_history(reason)
    startup.self_diag.ensure_dir(); local path=startup.SelfDiagHistoryFile; local exists=startup.support_file_exists(path); local f=io.open(path,"a"); if not f then return false end
    if not exists then f:write("run_id,finished,reason,account_class,repair_near_pct,play_hours,nat,country,isp,host_samples,host_sessions_with_joins,total_host_joins,join_samples,unique_join_hosts,join_attempts,direct_pct,confidence,report_path\n") end
    local hostN,hostWith,totalJoins,joinN,direct,relay=0,0,0,0,0,0
    for _,r in pairs(sd188.testRecords or {}) do if r and r.loaded then if r.kind=="HOST" then hostN=hostN+1; totalJoins=totalJoins+(tonumber(r.joinEvents or 0) or 0); if (r.joinEvents or 0)>0 then hostWith=hostWith+1 end else joinN=joinN+1; direct=direct+(tonumber(r.direct or 0) or 0); relay=relay+(tonumber(r.peerRelay or 0) or 0)+(tonumber(r.relayServer or 0) or 0) end end end
    local unique=0; for _ in pairs(sd188.seenJoinHosts or {}) do unique=unique+1 end; local pct=(direct+relay)>0 and direct/(direct+relay)*100 or nil; local syn=startup.self_diag.synthesize(); local ip=sd188.network.ip or {}
    local raw={sd188.runId,os.date("%Y-%m-%d %H:%M:%S"),tostring(reason or "Completed"),tostring(sd188.account.classification or "Unknown"),string.format("%.2f",tonumber(sd188.account.repairNearPct or 0)),string.format("%.2f",tonumber(sd188.account.playHours or 0)),tostring(sd188.network.nat or "Unknown"),tostring(ip.country or "Unknown"),tostring(ip.isp or ""),hostN,hostWith,totalJoins,joinN,unique,#(sd188.joinAttempts or {}),pct and string.format("%.2f",pct) or "",tostring(syn.confidence or 0),tostring(sd188.latestReportPath or "")}
    local vals={}; for i=1,#raw do vals[i]=startup.self_diag.csv(tostring(raw[i] or "")) end; f:write(table.concat(vals,","),"\n"); f:close(); sd188.historyPath=path; startup.s.selfDiagHistoryPath=path; return true
end

local function sd188_poll_wait_load(now)
    local spec=sd188.testPlan[sd188.testPlanPos]; if not spec then return end
    local elapsed=now-(tonumber(sd188.sessionRequestAtMs or now) or now)
    if elapsed>=sd188.pollLoadAfterMs then
        local ready,why=sd188_is_current_target_ready(spec)
        if ready then
            if sd188.lastLoadPollReadyMs==0 then sd188.lastLoadPollReadyMs=now; return end
            if now-sd188.lastLoadPollReadyMs>=1000 then startup.self_diag.log("POLL_SESSION_READY",spec.label.." via="..tostring(why)); sd188.phase="ALT_SETTLE"; sd188.nextActionMs=now+(spec.kind=="HOST" and 3000 or 1500); return end
        else sd188.lastLoadPollReadyMs=0 end
    end
    if elapsed>=sd188.sessionLoadTimeoutMs then
        local r=sd188.currentRecord; if r then r.failed=true; r.failReason="No correct host state within 60 seconds" end
        if spec.kind=="HOST" then startup.self_diag.log("HOST_LOAD_RETRY","did not become local Session Host; retrying New Public Session"); sd188.phase="ALT_ROUTE"; sd188.nextActionMs=now+1000; local ok,err=startup.self_diag.set_session_type_exact("New Public Session"); if ok then sd188.phase="ALT_CLICK_WAIT"; sd188.nextActionMs=now+750; sd188.sessionRequestAtMs=now else startup.self_diag.log("HOST_LOAD_RETRY_FAILED",tostring(err)); startup.self_diag.finish_current_observation("host load failed",false) end
        else startup.self_diag.finish_current_observation("join load timeout",true) end
    end
end

function startup.self_diag.tick()
    if sd188.active~=true then return end
    local now=startup.now()
    if now-(tonumber(sd188.startedAtMs or now) or now)>=sd188.maxRuntimeMs and not sd188.abortRequested and sd188.phase~="FINAL_HOST_ROUTE" and sd188.phase~="FINAL_HOST_WAIT_LOAD" and sd188.phase~="FINAL_HOST_SETTLE" then sd188.abortRequested=true; sd188.abortReason="75-minute safety cap reached"; startup.self_diag.log("TIME_BUDGET_REACHED",sd188.abortReason) end
    if sd188.abortRequested then sd188.abortRequested=false; sd188.phase="FINAL_HOST_ROUTE"; sd188.nextActionMs=now; sd188.status="Stopping test and returning to a fresh host..."; return end
    if sd188.phase=="PREFLIGHT_PENDING" and now>=sd188.nextActionMs then
        sd188.phase="ACCOUNT_SCAN"; startup.self_diag.capture_preflight(); startup.self_diag.scan_account(); startup.self_diag.write_account_snapshot(); startup.self_diag.log("ACCOUNT_STAGE_COMPLETE","Build 188 scanner complete")
        startup.self_diag.guard_snapshot_internal(); startup.self_diag.guard_apply_internal_off(); sd188.guard.active=true; startup.self_diag.log("NON_INTERFERENCE_GUARD_ON","Startup kick/block/RID actions disabled")
        startup.self_diag.guard_saved_players_disable(); startup.self_diag.set_advertising_for_test("JOIN"); sd188.phase="ALT_NEXT_WAIT"; sd188.nextActionMs=startup.now()+1500; return
    end
    if sd188.phase=="ALT_NEXT_WAIT" and now>=sd188.nextActionMs then
        sd188.testPlanPos=sd188.testPlanPos+1
        if sd188.testPlanPos>#sd188.testPlan then sd188.phase="FINAL_HOST_ROUTE"; sd188.nextActionMs=now; return end
        startup.self_diag.route_current_test(); return
    end
    if sd188.phase=="ALT_CLICK_WAIT" and now>=sd188.nextActionMs then startup.self_diag.click_current_test(); return end
    if sd188.phase=="ALT_WAIT_LOAD" then sd188_poll_wait_load(now); return end
    if sd188.phase=="ALT_SETTLE" and now>=sd188.nextActionMs then startup.self_diag.begin_current_observation(); return end
    if sd188.phase=="ALT_OBSERVE" then
        local r=sd188.currentRecord; local spec=sd188.testPlan[sd188.testPlanPos]; if not r or not spec then sd188.phase="ALT_NEXT_WAIT"; sd188.nextActionMs=now; return end
        if r.kind=="JOIN" and sd188.joinExitRequested then local why=sd188.joinExitReason~="" and sd188.joinExitReason or "joined session interrupted"; r.failed=true; r.failReason=why; startup.self_diag.finish_current_observation(why,true); return end
        -- Identity polling catches a session loss even when Startup's global session event was debounced.
        local hname,hid=sd188_current_host_identity()
        if r.kind=="HOST" and (hid<0 or not startup.self_diag.is_local_id(hid)) and now-r.startedAtMs>5000 then startup.self_diag.finish_current_observation("lost local Session Host during host sample",false); return end
        if r.kind=="JOIN" and (hid<0 or startup.self_diag.is_local_id(hid)) and now-r.startedAtMs>3000 then startup.self_diag.signal_join_exit("joined-session host disappeared or local host takeover",r.firstHost); return end
        if now>=tonumber(sd188.nextSampleMs or 0) then sd188.nextSampleMs=now+5000; startup.self_diag.sample_test_record(r); local window=sd188_window_for(spec); local deadline=r.startedAtMs+window; sd188.status=r.label.." | "..startup.self_diag.format_ms(math.max(0,deadline-now)).." left | players="..tostring(startup.get_session_player_count()).." | joins="..tostring(r.joinEvents or 0) end
        local window=sd188_window_for(spec)
        if now>=r.startedAtMs+window then startup.self_diag.finish_current_observation(spec.kind=="HOST" and "10-minute window complete" or "4-minute window complete",false) end
        return
    end
    if sd188.phase=="RESET_HOST_ROUTE" and now>=sd188.nextActionMs then sd188_route_reset_host(); return end
    if sd188.phase=="RESET_HOST_CLICK" and now>=sd188.nextActionMs then sd188_click_reset_host(); return end
    if sd188.phase=="RESET_HOST_WAIT_LOAD" then
        local elapsed=now-(tonumber(sd188.sessionRequestAtMs or now) or now); local fakeSpec={kind="HOST"}; local ready=sd188_is_current_target_ready(fakeSpec)
        if ready and elapsed>=2500 then sd188_begin_reset_hold(); return end
        if elapsed>=30000 then if (sd188.resetRouteAttempts or 0)<5 then sd188.phase="RESET_HOST_ROUTE"; sd188.nextActionMs=now+1000; startup.self_diag.log("RESET_HOST_RETRY","still not local Session Host") else startup.self_diag.log("RESET_HOST_GIVE_UP","could not establish local host after retries"); sd188.phase="ALT_ROUTE_RETRY_JOIN"; sd188.nextActionMs=now+1000 end end
        return
    end
    if sd188.phase=="RESET_HOST_HOLD" then
        local _,hid=sd188_current_host_identity(); if hid<0 or not startup.self_diag.is_local_id(hid) then sd188.phase="RESET_HOST_ROUTE"; sd188.nextActionMs=now+1000; startup.self_diag.log("RESET_HOST_LOST","local host lost during separation minute; retrying") return end
        if now>=tonumber(sd188.nextSampleMs or 0) then sd188.nextSampleMs=now+5000; local c=startup.get_session_player_count(); sd188.resetPeakPlayers=math.max(tonumber(sd188.resetPeakPlayers or 0) or 0,c); sd188.status="Fresh host separation | "..startup.self_diag.format_ms(math.max(0,sd188.resetHostWindowMs-(now-sd188.resetLoadedAtMs))).." left | players="..tostring(c) end
        if now-sd188.resetLoadedAtMs>=sd188.resetHostWindowMs then sd188_finish_reset_hold() end; return
    end
    if sd188.phase=="ALT_ROUTE_RETRY_JOIN" and now>=sd188.nextActionMs then sd188_retry_same_join(); return end
    if sd188.phase=="FINAL_HOST_ROUTE" and now>=sd188.nextActionMs then
        startup.self_diag.log("FINAL_HOST_ROUTE_BEGIN","forcing New Public Session after deep study")
        startup.self_diag.set_advertising_for_test("HOST")
        local ok,err=startup.self_diag.set_session_type_exact("New Public Session"); if not ok then startup.self_diag.log("FINAL_HOST_ROUTE_FAILED",tostring(err)); startup.self_diag.finish("Final host route failed"); return end
        sd188.phase="FINAL_HOST_CLICK_WAIT"; sd188.nextActionMs=now+750; return
    end
    if sd188.phase=="FINAL_HOST_CLICK_WAIT" and now>=sd188.nextActionMs then local ok=startup.click_start_session_feature(); startup.self_diag.log("FINAL_HOST_CLICK","ok="..tostring(ok)); if not ok then startup.self_diag.finish("Final host click failed"); return end; sd188.phase="FINAL_HOST_WAIT_LOAD"; sd188.sessionRequestAtMs=now; return end
    if sd188.phase=="FINAL_HOST_WAIT_LOAD" then local elapsed=now-(tonumber(sd188.sessionRequestAtMs or now) or now); local ready=sd188_is_current_target_ready({kind="HOST"}); if ready and elapsed>=2500 then sd188.phase="FINAL_HOST_SETTLE"; sd188.nextActionMs=now+5000; startup.self_diag.log("FINAL_HOST_CONFIRMED","local Session Host") return end; if elapsed>=30000 then startup.self_diag.log("FINAL_HOST_RETRY","not local host yet"); sd188.phase="FINAL_HOST_ROUTE"; sd188.nextActionMs=now+1000 end; return end
    if sd188.phase=="FINAL_HOST_SETTLE" and now>=sd188.nextActionMs then startup.self_diag.finish(sd188.abortReason~="" and ("Stopped early: "..sd188.abortReason) or "Completed deep 4-cycle study") return end
end

function startup.render_self_diagnostics_panel()
    if not ClickGUI.BeginCustomChildWindow("Self Diagnostics") then return end
    startup.section_title("Self Diagnostics")
    startup.subtle_text_wrapped("Build 188 Deep Diagnosis targets about one hour: 4 confirmed hosted sessions (10 minutes each) and 4 unique-host joined sessions (up to 4 minutes each). A joined-lobby kick/session loss or recycled host triggers a fresh New Public Session, requires local Session Host, waits at least 1 minute, then retries the same JOIN slot. Startup remains passive: no kick, Block Join, Auto Kick, RID blocking/saving, country kick, Battleye auto-block, or crash/kick auto-removal.")
    ImGui.Separator(); startup.render_feature_guarded_325(startup.h.RunSelfDiagnostics); startup.render_feature_guarded_325(startup.h.OpenSelfDiagnostics); if startup.self_diag.active then startup.render_feature_guarded_325(startup.h.StopSelfDiagnostics) end
    startup.status_line("State",tostring(sd188.phase or "Idle"),sd188.active and 0.35 or 0.72,sd188.active and 1.00 or 0.72,sd188.active and 0.45 or 0.72); startup.subtle_text_wrapped(tostring(sd188.status or "Ready"))
    if sd188.active and sd188.guard and sd188.guard.active then startup.text_colored_wrapped(0.35,1.00,0.45,1.00,"NON-INTERFERENCE ACTIVE: Startup only observes/logs players during this study.") end
    local elapsed=sd188.active and math.max(0,startup.now()-(tonumber(sd188.startedAtMs or startup.now()) or startup.now())) or 0
    if sd188.active then startup.subtle_text("Elapsed: "..startup.self_diag.format_ms(elapsed).." | Planned observation: ~56 min + transitions") end
    for i,spec in ipairs(sd188.testPlan or {}) do local r=sd188.testRecords and sd188.testRecords[i] or nil; if r then local extra=r.kind=="HOST" and ("joins@1m "..tostring(r.joins1m or 0).." | joins "..tostring(r.joinEvents or 0)) or ("host "..tostring(r.firstHost or "?").." | "..(r.directRatio and string.format("%.0f%% direct",r.directRatio) or "direct pending")); startup.subtle_text_wrapped(spec.label..": peak "..tostring(r.peakPlayers or 0).." | "..extra..(r.failed and (" | INTERRUPTED: "..tostring(r.failReason)) or "")) else startup.subtle_text(spec.label..": pending") end end
    local unique=0; for _ in pairs(sd188.seenJoinHosts or {}) do unique=unique+1 end; startup.subtle_text("Unique joined hosts seen: "..tostring(unique).." | total join attempts: "..tostring(#(sd188.joinAttempts or {})))
    local a=sd188.account or {}; if tonumber(a.readable or 0)>0 then ImGui.Separator(); startup.status_line("Account",tostring(a.classification or "Unknown"),0.72,0.42,1.00); startup.subtle_text_wrapped(string.format("Readable %d/503 | Repair similarity %.1f%% | Anomaly %d/100",tonumber(a.readable or 0),tonumber(a.repairNearPct or 0),tonumber(a.anomalyScore or 0))) end
    if tostring(sd188.latestReportPath or "")~="" then startup.subtle_text_wrapped("Last report: "..tostring(sd188.latestReportPath)) end
    ClickGUI.EndCustomChildWindow()
end

startup.self_diag.log("BUILD188_OVERRIDES_READY","deep 4-cycle ~1h study + unique joined-host enforcement + 1m host reset after interrupted/recycled JOIN + polling session readiness")


-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 189 Advertising Ownership Guard
--
-- Live/user requirement:
--   * whenever Current Auto Advertise, Old v1.0.3, an ACTIVE 30-player benchmark,
--     Super Advertise, or a Self Diagnostics HOST/reset-host stage owns advertising,
--     Cherax's native "Advertise Session" must be ON even if it was OFF beforehand;
--   * while an owner remains active, an external/manual OFF is corrected back to ON;
--   * Legacy Advertise Count is kept at the value required by the active method;
--   * JOIN stages remain deliberately passive and force native advertising OFF.
--
-- This is an ownership guard only. The 30-Player Benchmark Timer toggle by itself does
-- not advertise a random session; the guard activates when a benchmark run is active.
-- ═══════════════════════════════════════════════════════════════════════════════════

startup.advertise_ownership = startup.advertise_ownership or {
    active=false, mode="", reason="", desiredCount=0, lastCheckMs=0,
    lastSessionRepairMs=0, lastCountRepairMs=0, lastLogKey=""
}

local build189_raw_set_advertise_session = startup.set_advertise_session
local build189_raw_old_v103_set_session = startup.old_v103_set_session
local build189_raw_detect_manual_advertise_off = startup.detect_manual_advertise_off
local build189_raw_process_pending_advertise_session_sync = startup.process_pending_advertise_session_sync
local build189_raw_begin_reset_host = startup.self_diag and startup.self_diag.begin_reset_host or nil

local function build189_selfdiag_phase_is_join()
    if not startup.self_diag or startup.self_diag.active ~= true then return false end
    local sd=startup.self_diag
    local r=sd.currentRecord
    if r and tostring(r.kind or "") == "JOIN" then return true end
    local spec=sd.testPlan and sd.testPlan[tonumber(sd.testPlanPos or 0) or 0] or nil
    local phase=tostring(sd.phase or "")
    if spec and tostring(spec.kind or "") == "JOIN" then
        if phase=="ALT_ROUTE" or phase=="ALT_CLICK_WAIT" or phase=="ALT_WAIT_LOAD" or phase=="ALT_SETTLE" or phase=="ALT_OBSERVE" or phase=="ALT_ROUTE_RETRY_JOIN" then
            return true
        end
    end
    return false
end

local function build189_selfdiag_phase_is_host()
    if not startup.self_diag or startup.self_diag.active ~= true then return false end
    local sd=startup.self_diag
    local phase=tostring(sd.phase or "")
    if phase=="RESET_HOST_ROUTE" or phase=="RESET_HOST_CLICK" or phase=="RESET_HOST_WAIT_LOAD" or phase=="RESET_HOST_HOLD"
        or phase=="FINAL_HOST_ROUTE" or phase=="FINAL_HOST_CLICK_WAIT" or phase=="FINAL_HOST_WAIT_LOAD" or phase=="FINAL_HOST_SETTLE" then
        return true
    end
    local r=sd.currentRecord
    if r and tostring(r.kind or "") == "HOST" then return true end
    local spec=sd.testPlan and sd.testPlan[tonumber(sd.testPlanPos or 0) or 0] or nil
    if spec and tostring(spec.kind or "") == "HOST" then
        if phase=="ALT_ROUTE" or phase=="ALT_CLICK_WAIT" or phase=="ALT_WAIT_LOAD" or phase=="ALT_SETTLE" or phase=="ALT_OBSERVE" then
            return true
        end
    end
    return false
end

local function build189_saved_selfdiag_mode()
    local sd=startup.self_diag
    local saved=sd and sd.saved or nil
    if type(saved)~="table" then return nil end
    if saved.superAdvertiseEnabled==true then return "SUPER" end
    if saved.oldStartupAdvertiseEnabled==true then return "OLD_V103" end
    if saved.autoAdvertiseSession==true then return "CURRENT" end
    return nil
end

function startup.get_advertise_ownership_mode()
    -- JOIN observation is the hard exception: never advertise somebody else's lobby.
    if build189_selfdiag_phase_is_join() then return nil,"SelfDiag JOIN" end

    -- Any diagnostic HOST, 1-minute reset host, or final host inherits the user's
    -- selected advertising method even before that method's normal delayed worker starts.
    if build189_selfdiag_phase_is_host() then
        local m=build189_saved_selfdiag_mode()
        if m then return m,"SelfDiag HOST" end
    end

    if startup.s.superAdvertiseRunning==true then return "SUPER","Super Advertise running" end
    if startup.s.oldStartupAdvertiseRunning==true and startup.s.oldStartupAdvertiseEnabled==true then return "OLD_V103","Old v1.0.3 running" end
    if startup.s.advertiseRunning==true and startup.s.autoAdvertiseSession==true and startup.s.advertiseStopRequested~=true then return "CURRENT","Current Auto Advertise running" end

    -- The benchmark is a timer, not an advertiser by itself. But if a run is active,
    -- its recorded mode owns native advertising even if another state flag momentarily
    -- falls out of sync during a transition.
    if startup.s.advertiseBenchmarkActive==true then
        local m=tostring(startup.s.advertiseBenchmarkMode or "")
        if m=="CURRENT" and startup.s.advertiseRunning==true and startup.s.advertiseStopRequested~=true then return m,"30-Player Benchmark active (Current)" end
        if m=="OLD_V103" and startup.s.oldStartupAdvertiseRunning==true and startup.s.oldStartupAdvertiseEnabled==true then return m,"30-Player Benchmark active (Old v1.0.3)" end
        if m=="SUPER" and startup.s.superAdvertiseRunning==true then return m,"30-Player Benchmark active (Super)" end
    end
    return nil,"No active advertising owner"
end

local function build189_smart_legacy_count(mode)
    local low=tonumber(startup.s.advertiseLowCount or 5) or 5
    local high=tonumber(startup.s.advertiseHighCount or 10) or 10
    low=low>=10 and 10 or 5; high=high>=10 and 10 or 5

    if mode=="SUPER" then
        -- Super Advertise intentionally pulses 5/10. Honor whichever value its active
        -- profile most recently selected rather than flattening the experiment.
        local cur=tonumber(startup.s.advertiseCurrentCount or 0) or 0
        if cur==5 or cur==10 then return cur end
        local native=startup.native_advertise_count_visual and tonumber(startup.native_advertise_count_visual.actualValue or 0) or 0
        if native==5 or native==10 then return native end
        return high
    end

    local queued=false
    if mode=="CURRENT" then
        queued=startup.s.advertiseRunning==true and startup.s.advertiseSmartActive~=true
    elseif mode=="OLD_V103" then
        queued=startup.s.oldStartupAdvertiseRunning==true and tostring(startup.s.oldStartupAdvertiseStatus or ""):find("Queued",1,true)~=nil
    end
    -- During the two-minute method delay (and during a SelfDiag reset-host minute before
    -- a worker becomes active), use the method's soft-start count rather than zero.
    if queued then return low end
    if build189_selfdiag_phase_is_host() then
        local running=(mode=="CURRENT" and startup.s.advertiseRunning==true) or (mode=="OLD_V103" and startup.s.oldStartupAdvertiseRunning==true)
        if not running then return low end
    end

    local players=tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0
    local target=tonumber(startup.s.advertisePlayerTarget or 30) or 30
    local resume=tonumber(startup.s.advertiseResumeBelow or 25) or 25
    if players>=target then return low end
    if players<resume then return high end

    local cur=mode=="OLD_V103" and tonumber(startup.s.oldStartupAdvertiseCurrentCount or 0) or tonumber(startup.s.advertiseCurrentCount or 0)
    if cur==5 or cur==10 then return cur end
    return low
end

function startup.advertise_ownership_desired_count(mode)
    if startup.is_enhanced_active_edition() then return nil end
    mode=tostring(mode or "")
    if mode~="CURRENT" and mode~="OLD_V103" and mode~="SUPER" then return nil end
    return build189_smart_legacy_count(mode)
end

local function build189_log_guard(event,details)
    if startup.advertise_research_log then
        startup.advertise_research_log("OWNER",event,details)
    elseif startup.log then
        startup.log("[Advertise][OWNER] "..tostring(event).." | "..tostring(details or ""))
    end
end

function startup.advertise_ownership_tick(force)
    local now=startup.now()
    local own=startup.advertise_ownership
    if force~=true and now-(tonumber(own.lastCheckMs or 0) or 0)<500 then return end
    own.lastCheckMs=now

    local mode,reason=startup.get_advertise_ownership_mode()
    if not mode then
        if own.active then build189_log_guard("RELEASE","previousMode="..tostring(own.mode).." reason="..tostring(reason)) end
        own.active=false; own.mode=""; own.reason=tostring(reason or ""); own.desiredCount=0
        return
    end

    local changed=(own.active~=true or tostring(own.mode)~=tostring(mode))
    own.active=true; own.mode=mode; own.reason=tostring(reason or "")
    if changed then build189_log_guard("ACQUIRE","mode="..tostring(mode).." reason="..tostring(reason)) end

    local feature=startup.get_advertise_session_feature and startup.get_advertise_session_feature() or nil
    local current=feature and startup.get_feature_bool_state(feature) or nil
    if current~=true then
        local ok=build189_raw_set_advertise_session(true,true)
        own.lastSessionRepairMs=now
        build189_log_guard("FORCE_SESSION_ON","mode="..tostring(mode).." previous="..tostring(current).." ok="..tostring(ok))
    else
        startup.s.advertiseSessionEnabled=true
    end

    local desired=startup.advertise_ownership_desired_count(mode)
    own.desiredCount=tonumber(desired or 0) or 0
    if desired~=nil and not startup.is_enhanced_active_edition() then
        local state=startup.native_advertise_count_visual
        local actual=state and tonumber(state.actualValue or 0) or 0
        local tracked=mode=="OLD_V103" and tonumber(startup.s.oldStartupAdvertiseCurrentCount or 0) or tonumber(startup.s.advertiseCurrentCount or 0)
        if actual~=desired or tracked~=desired then
            local ok
            if mode=="OLD_V103" and startup.old_v103_set_count then
                ok=startup.old_v103_set_count(desired,"Build 189 ownership guard")
            else
                ok=startup.apply_advertise_count(desired,"Build 189 ownership guard")
            end
            own.lastCountRepairMs=now
            -- Build 291: FORCE_COUNT is a high-frequency repair watchdog. Successful
            -- repairs stay silent; failures remain visible.
            if ok~=true then
                build189_log_guard("FORCE_COUNT_FAIL","mode="..tostring(mode).." desired="..tostring(desired).." actual="..tostring(actual).." tracked="..tostring(tracked).." ok="..tostring(ok))
            end
        end
    end
end

-- Make ownership immediate when a user starts any advertising method; the permanent
-- worker remains the watchdog afterward.
local build189_raw_run_advertise_flow=startup.run_advertise_flow
local build189_raw_run_old_startup_advertise=startup.run_old_startup_advertise
local build189_raw_run_super_advertise=startup.run_super_advertise
if build189_raw_run_advertise_flow then
    function startup.run_advertise_flow(reason)
        local result=build189_raw_run_advertise_flow(reason)
        startup.advertise_ownership_tick(true)
        return result
    end
end
if build189_raw_run_old_startup_advertise then
    function startup.run_old_startup_advertise(reason)
        local result=build189_raw_run_old_startup_advertise(reason)
        startup.advertise_ownership_tick(true)
        return result
    end
end
if build189_raw_run_super_advertise then
    function startup.run_super_advertise(...)
        local result=build189_raw_run_super_advertise(...)
        startup.advertise_ownership_tick(true)
        return result
    end
end

-- Never let an active owner intentionally turn the native toggle OFF. This directly fixes
-- the Legacy Current/Old queue paths that historically turned Advertise Session OFF during
-- their two-minute delay.
function startup.set_advertise_session(enabled,force)
    local mode=startup.get_advertise_ownership_mode()
    if enabled~=true and mode then enabled=true; force=true end
    return build189_raw_set_advertise_session(enabled,force)
end

if build189_raw_old_v103_set_session then
    function startup.old_v103_set_session(enabled)
        local mode=startup.get_advertise_ownership_mode()
        if enabled~=true and mode=="OLD_V103" then enabled=true end
        return build189_raw_old_v103_set_session(enabled)
    end
end

-- Manual/native OFF during an active method is no longer treated as a request to pause the
-- flow. The active method owns the toggle and repairs it back ON. Outside an active owner,
-- preserve the original manual-off behavior.
function startup.detect_manual_advertise_off()
    local mode=startup.get_advertise_ownership_mode()
    if mode then
        startup.advertise_ownership_tick(true)
        startup.s.advertiseManualOverride=false
        return false
    end
    return build189_raw_detect_manual_advertise_off()
end

-- This function is called from Startup's permanent 500-ms worker, making it a safe place
-- to enforce ownership without creating another Self Diagnostics QueueJob.
function startup.process_pending_advertise_session_sync()
    build189_raw_process_pending_advertise_session_sync()
    startup.advertise_ownership_tick(false)
end

-- Recovery host sessions are real diagnostic host sessions too: advertise during their
-- one-minute separation window, then the retry JOIN stage turns advertising back OFF.
if build189_raw_begin_reset_host then
    function startup.self_diag.begin_reset_host(reason,retrySameJoin)
        local ok=build189_raw_begin_reset_host(reason,retrySameJoin)
        startup.self_diag.set_advertising_for_test("HOST")
        startup.advertise_ownership_tick(true)
        startup.self_diag.log("RESET_HOST_ADVERTISE_ON","selected="..tostring(select(1,startup.get_advertise_ownership_mode()) or "NONE").." count="..tostring(startup.advertise_ownership.desiredCount or 0))
        return ok
    end
end

-- Make the ownership guarantee immediate when a diagnostic switches between HOST/JOIN,
-- rather than waiting up to the next 500-ms worker tick.
local build189_raw_set_advertising_for_test=startup.self_diag and startup.self_diag.set_advertising_for_test or nil
if build189_raw_set_advertising_for_test then
    function startup.self_diag.set_advertising_for_test(kind)
        local result=build189_raw_set_advertising_for_test(kind)
        if tostring(kind or "")=="HOST" then
            startup.advertise_ownership_tick(true)
        else
            -- JOIN must stay passive. The original helper already forces native OFF;
            -- release ownership after it clears method flags.
            startup.advertise_ownership.active=false; startup.advertise_ownership.mode=""; startup.advertise_ownership.desiredCount=0
            build189_raw_set_advertise_session(false,true)
            startup.self_diag.log("JOIN_ADVERTISE_OFF","Advertise Session forced OFF during remote-host observation")
        end
        return result
    end
end

startup.self_diag.log("BUILD189_OVERRIDES_READY","Advertise Session ownership guard + forced ON for Current/Old/Super/active Benchmark/SelfDiag HOST + Legacy count ownership + JOIN forced OFF")

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 190 - Unified Advertise HUD + Mode-Specific Native Slider Ranges
-- • Auto Advertise Session: below-minimap HUD + visual slider 0..10.
-- • Old Startup Advertising Method v1.0.3: below-minimap HUD + visual slider 0..10.
-- • Super Advertise: below-minimap HUD + visual slider 0..20.
-- • Self Diagnostics HOST/reset/final-host stages inherit the user's selected mode.
-- • Self Diagnostics JOIN stages remain passive: Advertise Session/HUD OFF.
-- • HUD becomes visible immediately after a fresh hosted session is created, including
--   queued/preparing/countdown states, instead of waiting for smart advertising activation.
-- ═══════════════════════════════════════════════════════════════════════════════════

startup.advertise_slider_mode_state = startup.advertise_slider_mode_state or {
    mode = "",
    max = 10,
    lastAppliedMs = 0,
    status = "Build 190 ready"
}

local build190_raw_native_visual_configure = startup.native_advertise_count_visual_configure
local build190_raw_native_visual_process = startup.process_native_advertise_count_visual_slider
local build190_raw_advertise_ownership_tick = startup.advertise_ownership_tick

local function build190_selfdiag_join_active()
    if startup.self_diag and startup.self_diag.active == true then
        local sd = startup.self_diag
        local phase = tostring(sd.phase or "")
        if phase:find("JOIN", 1, true) ~= nil then return true end
        local r = sd.currentRecord
        if r and tostring(r.kind or "") == "JOIN" then return true end
        local spec = sd.testPlan and sd.testPlan[tonumber(sd.testPlanPos or 0) or 0] or nil
        if spec and tostring(spec.kind or "") == "JOIN" then return true end
    end
    return false
end

function startup.get_advertise_hud_mode()
    -- Never draw/advertise somebody else's joined lobby during Self Diagnostics.
    if build190_selfdiag_join_active() then return nil end

    -- Build 189 ownership knows about diagnostic HOST/reset/final-host inheritance.
    if startup.get_advertise_ownership_mode then
        local mode = select(1, startup.get_advertise_ownership_mode())
        if mode == "CURRENT" or mode == "OLD_V103" or mode == "SUPER" then return mode end
    end

    -- Keep the HUD present even in the short gap immediately after a new session loads,
    -- before the method worker has moved from enabled -> queued/running.
    if startup.s.superAdvertiseEnabled == true or startup.s.superAdvertiseRunning == true then return "SUPER" end
    if startup.s.oldStartupAdvertiseEnabled == true or startup.s.oldStartupAdvertiseRunning == true then return "OLD_V103" end
    if startup.s.autoAdvertiseSession == true or startup.s.advertiseRunning == true then return "CURRENT" end

    if startup.s.advertiseBenchmarkActive == true then
        local m = tostring(startup.s.advertiseBenchmarkMode or "")
        if m == "CURRENT" or m == "OLD_V103" or m == "SUPER" then return m end
    end
    return nil
end

function startup.get_advertise_slider_visual_max(mode)
    mode = tostring(mode or startup.get_advertise_hud_mode() or "")
    if mode == "SUPER" then return 20 end
    -- Current and Old v1.0.3 are real 0..10 displays.
    return 10
end

function startup.get_advertise_status_hud_display_count(actualCount, modeOverride)
    local actual = math.max(0, math.floor(tonumber(actualCount or 0) or 0))
    local mode = tostring(modeOverride or startup.get_advertise_hud_mode() or "CURRENT")
    if mode == "SUPER" then
        -- Super keeps the research display scale (native 5/10 -> visual 10/20).
        return math.max(0, math.min(20, actual * 2))
    end
    -- Current and Old show the real logical count directly on a 0..10 scale.
    return math.max(0, math.min(10, actual))
end

local function build190_current_actual_count(mode)
    mode = tostring(mode or startup.get_advertise_hud_mode() or "")
    if mode == "OLD_V103" then
        return math.max(0, math.min(10, math.floor(tonumber(startup.s.oldStartupAdvertiseCurrentCount or 0) or 0)))
    end
    return math.max(0, math.min(10, math.floor(tonumber(startup.s.advertiseCurrentCount or 0) or 0)))
end

local function build190_expected_slider_display(mode)
    local actual = build190_current_actual_count(mode)
    return startup.get_advertise_status_hud_display_count(actual, mode)
end

local function build190_apply_slider_range_and_display(mode, displayValue, source)
    if startup.is_enhanced_active_edition and startup.is_enhanced_active_edition() then return false end
    local state = startup.native_advertise_count_visual
    if not state or state.enabled ~= true then return false end

    if state.configured ~= true or state.feature == nil then
        if not build190_raw_native_visual_configure or build190_raw_native_visual_configure(false) ~= true then
            return false
        end
    end
    local feature = state.feature
    if not feature then return false end

    local maximum = startup.get_advertise_slider_visual_max(mode)
    local display = math.max(0, math.min(maximum, math.floor(tonumber(displayValue or 0) or 0)))

    state.applying = true
    local ok = direct_call(function()
        startup.native_advertise_count_visual_set_limits(feature, 0, maximum)
        if feature.SetStepSize then feature:SetStepSize(1) end
        if feature.SetFastStepSize then feature:SetFastStepSize(5) end
        if feature.SetIntValue then feature:SetIntValue(display)
        elseif feature.SetValue then feature:SetValue(display) end
    end)
    state.applying = false

    if ok then
        state.displayValue = display
        state.hudDisplayValue = display
        startup.s.advertiseHudNativeSliderDisplay = display
        startup.advertise_slider_mode_state.mode = tostring(mode or "")
        startup.advertise_slider_mode_state.max = maximum
        startup.advertise_slider_mode_state.lastAppliedMs = startup.now()
        startup.advertise_slider_mode_state.status = tostring(mode or "NONE") .. " 0-" .. tostring(maximum) .. " | " .. tostring(source or "sync")
        return true
    end
    return false
end

function startup.sync_native_advertise_count_visual_to_hud(displayValue, source)
    local mode = startup.get_advertise_hud_mode()
    if not mode then return false end
    local maximum = startup.get_advertise_slider_visual_max(mode)
    local display = math.max(0, math.min(maximum, math.floor(tonumber(displayValue or 0) or 0)))
    return build190_apply_slider_range_and_display(mode, display, source or "Build 190 HUD")
end

function startup.process_native_advertise_count_visual_slider()
    local mode = startup.get_advertise_hud_mode()
    if not mode then
        if build190_raw_native_visual_process then return build190_raw_native_visual_process() end
        return
    end
    if startup.is_enhanced_active_edition and startup.is_enhanced_active_edition() then return end

    -- While an advertising method owns the session, the Host Tool Kit slider is a
    -- synchronized status display. The method owns the count, so manual slider drift is
    -- corrected instead of changing the active experiment underneath it.
    local expected = build190_expected_slider_display(mode)
    build190_apply_slider_range_and_display(mode, expected, "Build 190 mode watchdog")
end

local function build190_format_countdown(endAt, now)
    endAt = tonumber(endAt or 0) or 0
    if endAt <= now then return nil end
    local seconds = math.max(0, math.ceil((endAt - now) / 1000))
    return tostring(seconds) .. "s"
end

local function build190_current_countdown(now)
    if startup.s.advertiseRunning == true and startup.s.advertiseSmartActive ~= true then
        return build190_format_countdown(startup.s.advertiseCountdownEndsAtMs, now)
    end
    if startup.s.sessionLuaLoadRunning == true then
        local luaEndAt = tonumber(startup.s.sessionLuaLoadEndsAtMs or 0) or 0
        if luaEndAt > now then
            return build190_format_countdown(luaEndAt + (tonumber(startup.s.advertiseDelayAfterSessionMs or 120000) or 120000), now)
        end
    end
    return nil
end

local function build190_old_countdown(now)
    if startup.s.oldStartupAdvertiseRunning ~= true then return nil end
    local started = tonumber(startup.s.oldStartupAdvertiseStartedAtMs or 0) or 0
    if started <= 0 then return nil end
    local status = tostring(startup.s.oldStartupAdvertiseStatus or "")
    if status:find("Queued", 1, true) == nil then return nil end
    return build190_format_countdown(started + (tonumber(startup.s.advertiseDelayAfterSessionMs or 120000) or 120000), now)
end

function startup.get_advertise_status_hud_line()
    if startup.s.showAdvertiseStatusHud ~= true then return nil end

    local now = startup.now()
    local previewUntil = tonumber(startup.s.advertiseStatusHudPreviewUntilMs or 0) or 0
    if previewUntil > now then
        local seconds = math.max(0, math.ceil((previewUntil - now) / 1000))
        return "Advertise HUD: preview | " .. tostring(seconds) .. "s", {95, 205, 255}
    end

    local mode = startup.get_advertise_hud_mode()
    if not mode then return nil end
    if startup.is_gta_online_session_ready and not startup.is_gta_online_session_ready() then return nil end

    local players = math.max(0, math.floor(tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0))
    local target = math.max(1, math.floor(tonumber(startup.s.advertisePlayerTarget or 30) or 30))

    if startup.is_enhanced_active_edition and startup.is_enhanced_active_edition() then
        local region = tostring(startup.get_advertise_region_label and startup.get_advertise_region_label(false) or startup.s.advertiseRegionLabel or "Unknown")
        if mode == "SUPER" then
            local method = math.max(0, math.floor(tonumber(startup.s.superAdvertiseMethod or 0) or 0))
            if startup.s.superAdvertiseRunning == true then
                return "Super Advertise: Method " .. tostring(method) .. "/100 | Region: " .. region .. " | " .. tostring(players) .. "/" .. tostring(target), {95, 255, 125}
            end
            return "Super Advertise: Preparing | Region: " .. region, {255, 190, 65}
        end
        return "Auto Advertise: ON | Region: " .. region .. " | " .. tostring(players) .. "/" .. tostring(target), {95, 255, 125}
    end

    local actual = build190_current_actual_count(mode)
    local display = startup.get_advertise_status_hud_display_count(actual, mode)
    local maximum = startup.get_advertise_slider_visual_max(mode)
    startup.sync_native_advertise_count_visual_to_hud(display, "Build 190 below-minimap HUD")

    if mode == "CURRENT" then
        local countdown = build190_current_countdown(now)
        if countdown then
            return "Auto Advertise: ON | Count " .. tostring(display) .. "/10 | active in " .. countdown, {255, 190, 65}
        end
        if startup.s.advertiseRunning ~= true or startup.s.advertiseSmartActive ~= true then
            return "Auto Advertise: Preparing | Count " .. tostring(display) .. "/10", {255, 190, 65}
        end
        return "Auto Advertise: ON | Count " .. tostring(display) .. "/10 | " .. tostring(players) .. "/" .. tostring(target), {95, 255, 125}
    end

    if mode == "OLD_V103" then
        local countdown = build190_old_countdown(now)
        if countdown then
            return "Old v1.0.3 Advertise: ON | Count " .. tostring(display) .. "/10 | active in " .. countdown, {255, 190, 65}
        end
        if startup.s.oldStartupAdvertiseRunning ~= true or tostring(startup.s.oldStartupAdvertiseStatus or ""):find("Active", 1, true) == nil then
            return "Old v1.0.3 Advertise: Preparing | Count " .. tostring(display) .. "/10", {255, 190, 65}
        end
        return "Old v1.0.3 Advertise: ON | Count " .. tostring(display) .. "/10 | " .. tostring(players) .. "/" .. tostring(target), {95, 255, 125}
    end

    -- Super keeps its 0..20 visual research scale and method number in the common HUD.
    local method = math.max(0, math.floor(tonumber(startup.s.superAdvertiseMethod or 0) or 0))
    if startup.s.superAdvertiseRunning == true then
        return "Super Advertise: Method " .. tostring(method) .. "/100 | Count " .. tostring(display) .. "/20 | " .. tostring(players) .. "/" .. tostring(target), {95, 255, 125}
    end
    return "Super Advertise: Preparing | Count " .. tostring(display) .. "/20", {255, 190, 65}
end

-- Keep the below-minimap HUD and native slider range synchronized immediately whenever
-- Build 189's ownership watchdog runs (including every fresh Self Diagnostics HOST).
if build190_raw_advertise_ownership_tick then
    function startup.advertise_ownership_tick(force)
        local result = build190_raw_advertise_ownership_tick(force)
        local mode = startup.get_advertise_hud_mode()
        if mode and not (startup.is_enhanced_active_edition and startup.is_enhanced_active_edition()) then
            build190_apply_slider_range_and_display(mode, build190_expected_slider_display(mode), "Build 190 ownership tick")
        end
        return result
    end
end

-- Force the locked below-minimap placement and initialize the dynamic slider immediately
-- when Build 190 loads. Subsequent new sessions are handled by the ownership watchdog/HUD.
startup.enforce_locked_advertise_status_hud()
local build190_initial_mode = startup.get_advertise_hud_mode()
if build190_initial_mode and not (startup.is_enhanced_active_edition and startup.is_enhanced_active_edition()) then
    build190_apply_slider_range_and_display(build190_initial_mode, build190_expected_slider_display(build190_initial_mode), "Build 190 load")
end

startup.self_diag.log("BUILD190_OVERRIDES_READY", "Unified below-minimap HUD Current/Old/Super + Current/Old slider 0-10 + Super slider 0-20 + fresh-session HUD ownership")

-- Build 190 immediate post-write range repair. The older visual adapter restores 0..20
-- after a native write; re-apply the active mode's requested range in the same call.
local build190_raw_native_write_actual = startup.native_advertise_count_visual_write_actual
if build190_raw_native_write_actual then
    function startup.native_advertise_count_visual_write_actual(actualValue, source)
        local result = build190_raw_native_write_actual(actualValue, source)
        local mode = startup.get_advertise_hud_mode()
        if mode and not (startup.is_enhanced_active_edition and startup.is_enhanced_active_edition()) then
            build190_apply_slider_range_and_display(mode, build190_expected_slider_display(mode), "Build 190 post native write")
        end
        return result
    end
end

local build190_raw_old_v103_set_count = startup.old_v103_set_count
if build190_raw_old_v103_set_count then
    function startup.old_v103_set_count(value, reason)
        local result = build190_raw_old_v103_set_count(value, reason)
        if startup.get_advertise_hud_mode() == "OLD_V103" then
            build190_apply_slider_range_and_display("OLD_V103", build190_expected_slider_display("OLD_V103"), "Build 190 Old v1.0.3 write")
        end
        return result
    end
end


