    {id="isp_public_ipv4_option",cat="Network / Router / ISP",text="Do you know whether your ISP can provide a real public IPv4 address, static IPv4, or remove CGNAT if requested?"},
    {id="pc_admin",cat="PC / VPN / Software",text="Are you an Administrator on this Windows PC with permission to change Windows Firewall, network adapters, services, drivers, and network settings?"},
    {id="windows_firewall_allowed",cat="PC / VPN / Software",text="Have you verified GTA5.exe / Rockstar Launcher are allowed through Windows Firewall on the network profiles you actually use?"},
    {id="ethernet_tested",cat="PC / VPN / Software",text="Have you tested GTA Online over wired Ethernet (not Wi-Fi) long enough to see whether hosting/matchmaking improves?"},
    {id="security_disabled_test",cat="PC / VPN / Software",text="Have you temporarily tested with third-party firewall/security network filtering disabled to see whether matchmaking changes?"},
    {id="clean_second_account_access",cat="Matchmaking Behavior",text="Do you already have legitimate access to a clean second Rockstar/GTA account that could be used only as an A/B control on this exact PC/network?"},
}

sd191.questionnaire.questions = Q
sd191.questionnaire.pages = {
    "Account Money / Recovery", "Stats / Progression", "Unlocks / Content",
    "Enforcement / Account History", "Network / Router / ISP",
    "PC / VPN / Software", "Matchmaking Behavior"
}

local function sd191_answer_count()
    local n=0
    for _,qq in ipairs(Q) do if sd191.questionnaire.answers[qq.id] ~= nil then n=n+1 end end
    return n
end

local function sd191_answers_for_category(cat)
    local out={}
    for _,qq in ipairs(Q) do if qq.cat==cat then out[#out+1]=qq end end
    return out
end

local function sd191_set_answer(id, value)
    if value~="yes" and value~="no" and value~="unsure" then return end
    sd191.questionnaire.answers[id]=value
end

local function sd191_get_ui_answer(id)
    return tostring(sd191.questionnaire.answers[id] or "unanswered")
end

local function sd191_get_run_answer(id)
    local src=sd191.userQuestionnaireAnswers
    if type(src)=="table" and src[id]~=nil then return tostring(src[id]) end
    return tostring(sd191.questionnaire.answers[id] or "unanswered")
end

local function sd191_yes(id) return sd191_get_run_answer(id)=="yes" end
local function sd191_no(id) return sd191_get_run_answer(id)=="no" end

function startup.self_diag.open_questionnaire(reset)
    if sd191.active==true then startup.toast("Self Diagnosis is already running.",3000); return false end
    if reset==true then sd191.questionnaire.answers={}; sd191.questionnaire.completed=false; sd191.questionnaire.page=1 end
    sd191.questionnaire.open=true; sd191.results191.open=false; sd191.popupOpen=false
    if GUI and GUI.IsOpen and GUI.Toggle then local ok,v=direct_call(GUI.IsOpen); if ok and v~=true then direct_call(GUI.Toggle) end end
    startup.self_diag.log("QUESTIONNAIRE_OPEN","questions="..tostring(#Q))
    return true
end

local build191_raw_start = startup.self_diag.start
function startup.self_diag.start()
    if sd191.active==true then startup.toast("Self Diagnosis is already running.",3000); return false end
    if sd191.questionnaire.completed~=true then
        return startup.self_diag.open_questionnaire(false)
    end
    sd191.questionnaire.completed=false -- every new run asks again; answers remain attached to this run.
    local ok=build191_raw_start()
    if ok then
        sd191.questionnaire.open=false
        sd191.results191.open=false
        sd191.results191.autoPackagePending=false
        sd191.results191.autoPackagePath=""
        sd191.results191.autoPackageStatus="Waiting for diagnosis to finish"
        sd191.userQuestionnaireAnswers={}
        for _,qq in ipairs(Q) do sd191.userQuestionnaireAnswers[qq.id]=sd191.questionnaire.answers[qq.id] or "unsure" end
        sd191.userQuestionnaireCompletedAt=os.time()
        startup.self_diag.log("QUESTIONNAIRE_ATTACHED","answered="..tostring(sd191_answer_count()).."/"..tostring(#Q))
    end
    return ok
end


local function sd191_question_button(qq, value, label, scheme)
    local selected=sd191_get_ui_answer(qq.id)==value
    local prefix=selected and ("["..label.."]") or label
    startup.render_color_button(prefix.."##sdq_"..qq.id.."_"..value, selected and scheme or "Gray", "Answer: "..label, function() sd191_set_answer(qq.id,value) end, 84, 26)
end

function startup.render_self_diag_questionnaire_popup_build191()
    if sd191.questionnaire.open~=true then return end
    if not ImGui or not ImGui.Begin or not ImGui.End then return end
    local sw,sh=startup.get_display_size(); local width=math.min(960,math.max(720,sw-120)); local height=math.min(780,math.max(580,sh-80))
