    if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(px,py,ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(width,height,ImGuiCond and ImGuiCond.Always or 0) end
    local colors,vars=startup.push_first_run_style()
    local visible=ImGui.Begin("##Startup_SelfDiag_Questionnaire_191",true,startup.first_run_window_flags())
    if visible then
        local page=math.max(1,math.min(#sd191.questionnaire.pages,tonumber(sd191.questionnaire.page or 1) or 1)); sd191.questionnaire.page=page
        local cat=sd191.questionnaire.pages[page]; local items=sd191_answers_for_category(cat); local answered=sd191_answer_count()
        local sectionAnswered=0; for _,qq in ipairs(items) do if sd191.questionnaire.answers[qq.id]~=nil then sectionAnswered=sectionAnswered+1 end end
        startup.text_colored(0.35,1.00,0.52,1.00,"SELF DIAGNOSIS QUESTIONNAIRE - READ EVERY QUESTION")
        startup.text_colored_wrapped(1.00,0.45,0.20,1.00,"REQUIRED: Anti AFK Kick ON. Standard/Premium: Desync Auto Rejoin OFF. Startup configures and maintains these automatically.")
        if startup.anti_afk_status_text then
            local afkOn=startup.is_anti_afk_kick_enabled and startup.is_anti_afk_kick_enabled() or false
            startup.status_line("Anti AFK Kick",startup.anti_afk_status_text(),afkOn and 0.35 or 1.00,afkOn and 1.00 or 0.25,afkOn and 0.45 or 0.20)
        end
        if startup.desync_auto_rejoin_status_text then
            local prime=startup.is_prime_active_edition and startup.is_prime_active_edition() or false
            local safe=prime or (startup.ensure_desync_auto_rejoin_safe and startup.ensure_desync_auto_rejoin_safe(false,"Questionnaire status") == true)
            startup.status_line("Desync Auto Rejoin",startup.desync_auto_rejoin_status_text(),safe and 0.35 or 1.00,safe and 1.00 or 0.25,safe and 0.45 or 0.20)
        end
        startup.text_colored_wrapped(1.00,0.22,0.22,1.00,"PLEASE ANSWER EVERY QUESTION TRUTHFULLY. Your answers directly affect the diagnosis and recommended repair.")
        if ImGui.CollapsingHeader and ImGui.CollapsingHeader("WHY THIS MATTERS / DIAGNOSTIC DETAILS") == true then
            startup.subtle_text_wrapped("While you answer, Startup measures a verified hosted public session. The full Deep Diagnosis hosts and joins multiple sessions for about 70-80 minutes, combining your answers with account stats, network data, and repeated matchmaking tests. There is no auto-fill. Use UNSURE only when you genuinely do not know an answer.")
        end
        startup.status_line("Questionnaire",tostring(answered).." / "..tostring(#Q).." manually answered",0.42,0.82,1.00)
        startup.status_line("Section",tostring(page).." / "..tostring(#sd191.questionnaire.pages).." - "..cat.."  ("..tostring(sectionAnswered).."/"..tostring(#items)..")",1.00,0.78,0.18)
        if page==5 and ImGui.CollapsingHeader and ImGui.CollapsingHeader("NETWORK PRIVACY NOTE") == true then
            startup.subtle_text_wrapped("Startup independently measures Cherax-exposed NAT/session/peer information. Raw public IP is not written into the normal Self Diagnosis report.")
        end
        ImGui.Separator()
        startup.subtle_text_wrapped("Scroll the questions below. Navigation / Start controls stay fixed at the bottom.")
        ImGui.Spacing()
        local availableY=360
        if ImGui.GetContentRegionAvail then
            local ax,ay=ImGui.GetContentRegionAvail()
            if type(ax)=="table" then availableY=tonumber(ax.y or ax.Y or ax[2] or availableY) or availableY
            else availableY=tonumber(ay or availableY) or availableY end
        end
        local bodyH=math.max(180,math.min(500,availableY-52)); local child=true
        if ImGui.BeginChild then child=ImGui.BeginChild("##SDQ_BODY_191",0,bodyH,true,(ImGuiWindowFlags and ImGuiWindowFlags.AlwaysVerticalScrollbar) or 0)==true end
        if child then
            for i,qq in ipairs(items) do
                startup.text_colored_wrapped(0.94,0.94,0.98,1.00,tostring(i)..". "..qq.text)
                sd191_question_button(qq,"yes","YES","Green"); ImGui.SameLine(); sd191_question_button(qq,"no","NO","Red"); ImGui.SameLine(); sd191_question_button(qq,"unsure","UNSURE","Gold")
                ImGui.Separator()
            end
        end
        if ImGui.BeginChild and ImGui.EndChild then ImGui.EndChild() end
        ImGui.Spacing()
        if page>1 then startup.render_color_button("PREVIOUS SECTION","Blue","Go to the previous section.",function() sd191.questionnaire.page=page-1 end,165,32); ImGui.SameLine() end
        if page<#sd191.questionnaire.pages then
            startup.render_color_button("NEXT SECTION","Purple","Go to the next section.",function() sd191.questionnaire.page=page+1 end,165,32)
        else
            local antiAfkReady=startup.ensure_anti_afk_kick and startup.ensure_anti_afk_kick(true,"Self Diagnosis questionnaire") == true
            local prime=startup.is_prime_active_edition and startup.is_prime_active_edition() or false
            local desyncReady=prime or (startup.ensure_desync_auto_rejoin_safe and startup.ensure_desync_auto_rejoin_safe(true,"Self Diagnosis questionnaire") == true)
            local complete=answered==#Q and antiAfkReady and desyncReady
            local startLabel
            if answered~=#Q then startLabel="ANSWER ALL QUESTIONS FIRST"
            elseif not antiAfkReady then startLabel="ENABLE ANTI AFK KICK FIRST"
            elseif not desyncReady then startLabel="TURN DESYNC AUTO REJOIN OFF FIRST"
            elseif startup.self_diag and startup.self_diag.active==true then startLabel="I READ EVERY QUESTION - CONTINUE DIAGNOSIS"
            else startLabel="I READ EVERY QUESTION - START DEEP DIAGNOSIS" end
            startup.render_color_button(startLabel,complete and "Green" or "Gray",complete and "Confirms every question was manually answered and required Kick Utility safety settings are correct." or "Every question must be answered manually; Anti AFK Kick must be ON; Standard/Premium Desync Auto Rejoin must be OFF.",function()
                if sd191_answer_count()~=#Q then startup.toast("Please manually read and answer every question. Startup will not auto-fill unanswered questions.",5000); return end
                if not startup.ensure_anti_afk_kick or startup.ensure_anti_afk_kick(true,"Self Diagnosis questionnaire completion")~=true then startup.toast("Anti AFK Kick is required.",6000); return end
                if not prime and (not startup.ensure_desync_auto_rejoin_safe or startup.ensure_desync_auto_rejoin_safe(true,"Self Diagnosis questionnaire completion")~=true) then startup.toast("Standard/Premium requires Desync Auto Rejoin OFF.",7000); return end
                sd191.questionnaire.completed=true; sd191.questionnaire.completedAt=os.time(); sd191.questionnaire.open=false; startup.self_diag.start()
            end,360,34)
        end
        ImGui.SameLine(); startup.render_color_button((startup.self_diag and startup.self_diag.active==true) and "HIDE FOR NOW" or "CANCEL","Red","Hide the questionnaire. If the diagnostic is active, Startup will require completion before leaving the first measured host stage.",function() sd191.questionnaire.open=false end,120,34)
    end
    ImGui.End(); startup.pop_first_run_style(colors,vars)
end

-- Cause engine ----------------------------------------------------------------------
local function sd191_add_score(scores,evidence,cause,points,text,kind)
    scores[cause]=(tonumber(scores[cause] or 0) or 0)+(tonumber(points or 0) or 0)
    if text and text~="" then evidence[#evidence+1]={cause=cause,points=points,text=text,kind=kind or "USER-REPORTED"} end
end

local function sd191_count_yes(ids)
    local n=0
    for _,id in ipairs(ids) do if sd191_yes(id) then n=n+1 end end
    return n
end

local SD192_CONFIRMED_MODIFIED_IDS = {
    "mod_menu_account","spawned_money","money_recovery_loop","edited_cash_bank","third_party_recovery",
    "set_crew_level","set_lscm_level","set_arena_level","max_abilities","modded_run","edit_kd","edit_playtime","edit_report_commend",
    "unlock_all_weapons","unlock_media_sticks","unlock_tattoos","unlock_clothing","unlock_haircuts","unlock_camos","unlock_vehicle_mods",
    "unlock_trade_prices","unlock_achievements","unlock_property_trophies","unlock_seasonal","complete_missions","unlock_freemode_missions",
    "unlock_booty_calls","unlock_bunker_research","max_nightclub_popularity","clear_business_heat","character_cloned","tutorial_skipped"
}
local SD192_SUSPICIOUS_MODIFIED_IDS = {
    "set_rp_rank","edit_collectible_counts","edit_mental","modded_casino","modded_vehicle_sales"
}
local SD192_ACTIVITY_EXEMPT_IDS = {
    "modded_hangar","modded_heist_payout","modded_business_payout","max_salvage_payout","ceo_mc_cash_piles","edit_business_stats","unlock_heists"
}
function startup.self_diag.user_account_mod_status_192()
    local confirmed, suspicious, exempt = {}, {}, {}
    for _,id in ipairs(SD192_CONFIRMED_MODIFIED_IDS) do if sd191_yes(id) then confirmed[#confirmed+1]=id end end
    for _,id in ipairs(SD192_SUSPICIOUS_MODIFIED_IDS) do if sd191_yes(id) then suspicious[#suspicious+1]=id end end
    for _,id in ipairs(SD192_ACTIVITY_EXEMPT_IDS) do if sd191_yes(id) then exempt[#exempt+1]=id end end
    local status,label
    if #confirmed>0 then status="CONFIRMED_USER_REPORTED_MODIFIED"; label="User-reported modified account"
    elseif #suspicious>0 then status="SUSPICIOUS_USER_REPORTED"; label="Suspicious account modification history"
    else status="NO_HIGH_RISK_REPORTED"; label="No high-risk account-stat modification reported" end
    return {status=status,label=label,confirmed=confirmed,suspicious=suspicious,exempt=exempt}
end

function startup.self_diag.build_ranked_conclusion_191(base)
    local scores={ACCOUNT=0,NAT_INBOUND=0,ADVERTISING=0,ISP_ROUTING=0,VPN_TUNNEL=0,LOCAL_SECURITY=0,SPECIAL_POOL=0,STARTUP_CONFLICT=0,ROCKSTAR_VOLATILITY=0}
    local ev={}
    local modStatus=startup.self_diag.user_account_mod_status_192()
    if #modStatus.confirmed>0 then
        sd191_add_score(scores,ev,"ACCOUNT",math.min(28,12 + #modStatus.confirmed*1.8),"User directly reported "..#modStatus.confirmed.." high-confidence account-stat/unlock modifications. Account status: MODIFIED (user-reported).","USER-REPORTED")
    end
    if #modStatus.suspicious>0 then
        sd191_add_score(scores,ev,"ACCOUNT",math.min(12,#modStatus.suspicious*3),"User reported "..#modStatus.suspicious.." suspicious account edits (including RP/collectible/related history where applicable).","USER-REPORTED")
    end
    if #modStatus.exempt>0 then
        sd191_add_score(scores,ev,"ACCOUNT",0,"User reported "..#modStatus.exempt.." heist/business/cash-pile-style modifications that Build 193 records but does not automatically use to classify the account as modified.","USER-REPORTED")
    end
    if sd191_yes("problem_after_modding") then sd191_add_score(scores,ev,"ACCOUNT",10,"User reports the matchmaking issue began after account modding/recovery/stat changes.","USER-REPORTED") end
    if sd191_yes("worse_after_edit") then sd191_add_score(scores,ev,"ACCOUNT",9,"User reports matchmaking became worse immediately after a specific account edit.","USER-REPORTED") end
    if sd191_yes("clean_account_better") or sd191_yes("other_account_better_network") then sd191_add_score(scores,ev,"ACCOUNT",14,"A cleaner/different account reportedly performs better on the same PC/network, isolating the account as a strong variable.","USER-REPORTED") end

    if sd191_yes("known_cgnat") then sd191_add_score(scores,ev,"NAT_INBOUND",16,"User reports known CGNAT/shared carrier-grade IPv4.","USER-REPORTED") end
    if sd191_yes("double_nat") then sd191_add_score(scores,ev,"NAT_INBOUND",10,"User reports double NAT.","USER-REPORTED") end
    if sd191_yes("wan_private") then sd191_add_score(scores,ev,"NAT_INBOUND",12,"Router WAN address is reportedly private/shared-address space rather than the Internet-observed public IPv4.","USER-REPORTED") end
    if sd191_yes("no_public_ipv4") then sd191_add_score(scores,ev,"NAT_INBOUND",15,"ISP reportedly does not provide usable inbound/public IPv4 on this plan.","USER-REPORTED") end
    if sd191_yes("upnp_disabled") then sd191_add_score(scores,ev,"NAT_INBOUND",5,"UPnP is reportedly unavailable/disabled/broken.","USER-REPORTED") end
    if sd191_yes("second_router_mesh") then sd191_add_score(scores,ev,"NAT_INBOUND",6,"Multiple router/mesh layers may create an additional NAT boundary.","USER-REPORTED") end
    if sd191_yes("multiple_gta_devices") then sd191_add_score(scores,ev,"NAT_INBOUND",3,"Multiple GTA devices share one public connection and may compete for mappings.","USER-REPORTED") end
    if sd191_yes("router_security") then sd191_add_score(scores,ev,"LOCAL_SECURITY",7,"Router-level firewall/geo/DDoS/security filtering is reportedly enabled.","USER-REPORTED") end
    if sd191_yes("mobile_5g_home") then sd191_add_score(scores,ev,"ISP_ROUTING",8,"Connection is cellular/4G/5G home Internet.","USER-REPORTED") end
    if sd191_yes("satellite") then sd191_add_score(scores,ev,"ISP_ROUTING",9,"Connection is satellite Internet.","USER-REPORTED") end
    if sd191_yes("fixed_wireless") then sd191_add_score(scores,ev,"ISP_ROUTING",6,"Connection is fixed-wireless/WISP.","USER-REPORTED") end
    if sd191_yes("shared_property_network") then sd191_add_score(scores,ev,"ISP_ROUTING",8,"Connection is shared/managed property, campus, hotel, dorm, or corporate Internet.","USER-REPORTED") end
    if sd191_yes("rapid_public_ip") then sd191_add_score(scores,ev,"ISP_ROUTING",3,"Public IP reportedly changes frequently.","USER-REPORTED") end
    if sd191_yes("isp_gateway_locked") then sd191_add_score(scores,ev,"NAT_INBOUND",5,"ISP gateway/router is reportedly locked or provider-managed, limiting NAT/UPnP/port configuration.","USER-REPORTED") end
    if sd191_no("router_admin_access") then sd191_add_score(scores,ev,"LOCAL_SECURITY",2,"User reports no router/gateway administration access; this is primarily a remediation limitation, not proof of the root cause.","USER-REPORTED") end
    if sd191_no("pc_admin") then sd191_add_score(scores,ev,"LOCAL_SECURITY",3,"User reports no Windows Administrator access to verify firewall/adapters/network settings.","USER-REPORTED") end
    if sd191_no("windows_firewall_allowed") then sd191_add_score(scores,ev,"LOCAL_SECURITY",10,"User reports GTA/Rockstar firewall allowance has not been verified/allowed on the active Windows network profile.","USER-REPORTED") end
    if sd191_yes("ethernet_tested") and sd191_yes("wifi_connection") then sd191_add_score(scores,ev,"LOCAL_SECURITY",-1,"User has performed a wired Ethernet comparison, reducing confidence that Wi-Fi alone explains the issue.","USER-REPORTED") end

    local vpnYes=sd191_count_yes({"commercial_vpn","cloudflare_warp","wireguard_openvpn","overlay_network","route_optimizer"})
    if vpnYes>0 then sd191_add_score(scores,ev,"VPN_TUNNEL",math.min(16,vpnYes*4),"One or more VPN/tunnel/route-optimizer layers are reportedly active.","USER-REPORTED") end
    if sd191_yes("third_party_firewall") then sd191_add_score(scores,ev,"LOCAL_SECURITY",7,"Third-party firewall/security software controls GTA traffic.","USER-REPORTED") end
    if sd191_yes("virtual_adapters") then sd191_add_score(scores,ev,"LOCAL_SECURITY",4,"Multiple active virtual/network adapters may affect route selection.","USER-REPORTED") end
    if sd191_yes("wifi_connection") then sd191_add_score(scores,ev,"LOCAL_SECURITY",2,"GTA is normally played over Wi-Fi; this is a weak quality/jitter contributor, not proof of the issue.","USER-REPORTED") end

    if sd191_yes("friends_manual_join") and sd191_yes("random_fail_friends_work") then sd191_add_score(scores,ev,"ADVERTISING",14,"Friends can reportedly join manually while random matchmaking does not, strongly separating invitation reachability from public advertisement/discovery.","USER-REPORTED") end
    if sd191_no("friends_manual_join") then sd191_add_score(scores,ev,"NAT_INBOUND",10,"Friends reportedly cannot manually join newly hosted sessions either, which points beyond public advertisement alone.","USER-REPORTED") end
    if sd191_yes("hotspot_better") or sd191_yes("same_account_other_network") then sd191_add_score(scores,ev,"NAT_INBOUND",10,"The same account reportedly works better on another network/hotspot, strongly implicating the home network/ISP path.","USER-REPORTED"); sd191_add_score(scores,ev,"ISP_ROUTING",8,"Alternate-network success is evidence against an account-only explanation.","USER-REPORTED") end
    if sd191_yes("problem_without_startup") then scores.STARTUP_CONFLICT=math.max(0,(scores.STARTUP_CONFLICT or 0)-5) else if sd191_no("problem_without_startup") then sd191_add_score(scores,ev,"STARTUP_CONFLICT",9,"Problem reportedly disappears when Startup is unloaded.","USER-REPORTED") end end
    if sd191_no("problem_without_other_scripts") then sd191_add_score(scores,ev,"STARTUP_CONFLICT",7,"Problem reportedly disappears when other scripts/menus/session managers are disabled.","USER-REPORTED") end
    if sd191_yes("frequent_host_kicks") then sd191_add_score(scores,ev,"ROCKSTAR_VOLATILITY",5,"User reports frequent remote-host kicks when joining; this can contaminate joined-session sampling.","USER-REPORTED") end
    if sd191_yes("same_host_recycled") then sd191_add_score(scores,ev,"ROCKSTAR_VOLATILITY",4,"User reports frequent recycling to the same joined-session host/lobby.","USER-REPORTED") end
    if sd191_yes("time_region_sensitive") then sd191_add_score(scores,ev,"ISP_ROUTING",4,"Problem is reportedly time/region/exit-location sensitive.","USER-REPORTED") end

    -- Measured evidence -------------------------------------------------------------
    local n=sd191.network or {}; local nat=tostring(n.nat or "Unknown"):upper()
    if nat:find("STRICT",1,true) then sd191_add_score(scores,ev,"NAT_INBOUND",18,"Cherax reported Strict NAT during the diagnostic.","DETECTED")
    elseif nat:find("MODERATE",1,true) then sd191_add_score(scores,ev,"NAT_INBOUND",6,"Cherax reported Moderate NAT during the diagnostic.","DETECTED") end

    local a=sd191.account or {}; local anomaly=tonumber(a.anomalyScore or 0) or 0
    if anomaly>=60 then sd191_add_score(scores,ev,"ACCOUNT",10,"503/core account analysis produced a high anomaly score of "..tostring(anomaly).."/100.","DETECTED")
    elseif anomaly>=40 then sd191_add_score(scores,ev,"ACCOUNT",5,"Account analysis produced a moderate anomaly score of "..tostring(anomaly).."/100.","DETECTED") end
    local extra=a.extra or {}; if extra.nativeBadSport==true then sd191_add_score(scores,ev,"SPECIAL_POOL",22,"Native Bad Sport state was detected.","DETECTED") end
    if extra.nativeCheater==true then sd191_add_score(scores,ev,"SPECIAL_POOL",14,"Native Cheater state was detected.","DETECTED") end
    local node=sd191.nodeState or {}; if node.inTutorial==true or node.pendingTutorialSessionChange==true then sd191_add_score(scores,ev,"SPECIAL_POOL",18,"Tutorial/session-segmentation state was observed active.","DETECTED") end

    local hostN,hostWith,totalHostJoins,joinN,joinPeak,direct,relay=0,0,0,0,0,0,0
    for _,r in pairs(sd191.testRecords or {}) do if r and r.loaded then
        if r.kind=="HOST" then hostN=hostN+1; totalHostJoins=totalHostJoins+(tonumber(r.joinEvents or 0) or 0); if (r.joinEvents or 0)>0 then hostWith=hostWith+1 end
        elseif r.kind=="JOIN" then joinN=joinN+1; joinPeak=joinPeak+(tonumber(r.peakPlayers or 0) or 0); direct=direct+(tonumber(r.direct or 0) or 0); relay=relay+(tonumber(r.peerRelay or 0) or 0)+(tonumber(r.relayServer or 0) or 0) end
    end end
    if hostN>=3 then
        local avg=totalHostJoins/math.max(1,hostN)
        if hostWith==0 then sd191_add_score(scores,ev,"ADVERTISING",15,"No random incoming joins were measured across "..hostN.." confirmed hosted-session samples.","DETECTED"); sd191_add_score(scores,ev,"NAT_INBOUND",12,"Repeated confirmed hosting produced zero incoming joins, consistent with an inbound/reachability problem.","DETECTED")
        elseif hostWith<=1 then sd191_add_score(scores,ev,"ADVERTISING",8,"Only "..hostWith.."/"..hostN.." hosted samples received random joins.","DETECTED")
        else sd191_add_score(scores,ev,"ADVERTISING",-6,string.format("Random incoming matchmaking worked in %d/%d hosted samples (%.1f joins/sample).",hostWith,hostN,avg),"DETECTED") end
    end
    if joinN>0 and hostN>0 then
        local avgJoinPeak=joinPeak/math.max(1,joinN); local avgHost=totalHostJoins/math.max(1,hostN)
        if avgJoinPeak>=15 and avgHost<1 then sd191_add_score(scores,ev,"ADVERTISING",16,string.format("Joined sessions averaged %.1f players while hosted sessions averaged only %.1f incoming joins.",avgJoinPeak,avgHost),"DETECTED"); sd191_add_score(scores,ev,"NAT_INBOUND",10,"Ability to join populated sessions is healthy while hosting reachability is poor.","DETECTED") end
    end
    if direct+relay>=5 then
        local pct=direct/(direct+relay)*100
        if pct>=70 then scores.ISP_ROUTING=math.max(0,(scores.ISP_ROUTING or 0)-4); sd191_add_score(scores,ev,"ROCKSTAR_VOLATILITY",0,string.format("Joined-session peer connectivity was %.1f%% DIRECT, arguing against a blanket inability to establish P2P peers.",pct),"DETECTED")
        elseif pct<25 then sd191_add_score(scores,ev,"ISP_ROUTING",10,string.format("Only %.1f%% of joined-session peer observations were DIRECT.",pct),"DETECTED") end
    end
    local kickCount=0; for _,r in ipairs(sd191.joinAttempts or {}) do if r.kickDetected then kickCount=kickCount+1 end end
    if kickCount>=2 then sd191_add_score(scores,ev,"ROCKSTAR_VOLATILITY",7,"Multiple remote-host kick/session-removal events interrupted joined-session samples.","DETECTED") end

    -- Keep negative/healthy evidence from producing negative rankings.
    for k,v in pairs(scores) do scores[k]=math.max(0,tonumber(v or 0) or 0) end
    local labels={
        ACCOUNT="Account profile / modified-stat state",
        NAT_INBOUND="NAT / CGNAT / inbound hosting reachability",
        ADVERTISING="Public-session advertisement / matchmaking discovery",
        ISP_ROUTING="ISP / routing / shared-network characteristics",
        VPN_TUNNEL="VPN / tunnel / route-optimizer interference",
        LOCAL_SECURITY="Router / firewall / local network configuration",
        SPECIAL_POOL="Bad Sport / tutorial / special matchmaking pool state",
        STARTUP_CONFLICT="Startup / other script / menu interference",
        ROCKSTAR_VOLATILITY="Rockstar/Cherax session recycling or remote-host instability",
    }
    local ranked={}
    for k,v in pairs(scores) do ranked[#ranked+1]={key=k,label=labels[k] or k,score=v} end
    table.sort(ranked,function(x,y) if x.score==y.score then return x.label<y.label end return x.score>y.score end)
    local rawConfidence=tonumber(base and base.confidence or 0) or 0
    local top=ranked[1] or {score=0,label="No single cause proven",key="NONE"}; local second=ranked[2] or {score=0}
    local gap=math.max(0,top.score-second.score)
    local conclusionConfidence=math.floor(math.min(95, math.max(20, rawConfidence*0.55 + math.min(30,top.score*1.2) + math.min(20,gap*1.5))))
    if top.score<7 then top={key="UNRESOLVED",label="No single cause was proven",score=top.score}; conclusionConfidence=math.min(conclusionConfidence,55) end
    return {scores=scores,ranked=ranked,evidence=ev,primary=top,confidence=conclusionConfidence,coverageConfidence=rawConfidence,accountModStatus=modStatus}
end

local build191_raw_synthesize=startup.self_diag.synthesize
function startup.self_diag.synthesize()
    local base=build191_raw_synthesize()
    local c=startup.self_diag.build_ranked_conclusion_191(base)
    base.rank191=c.ranked; base.evidence191=c.evidence; base.primaryCause=c.primary; base.primaryConfidence=c.confidence; base.coverageConfidence=c.coverageConfidence
    sd191.results191.lastConclusion=c
    sd191.synthesis=base
    return base
end

-- Report enrichment -----------------------------------------------------------------
local build191_raw_write_report=startup.self_diag.write_report
function startup.self_diag.write_report(reason)
    local ok=build191_raw_write_report(reason)
    local path=tostring(sd191.latestReportPath or "")
    if not ok or path=="" then return ok end
    local f=io.open(path,"a"); if not f then return ok end
    local function w(x) f:write(tostring(x or ""),"\n") end
    local syn=startup.self_diag.synthesize(); local c=sd191.results191.lastConclusion or {}
    w(""); w("PRE-DIAGNOSIS QUESTIONNAIRE"); w("---------------------------")
    w("Evidence type: USER-REPORTED. These answers are not presented as detected facts.")
    w("Answered manually: "..tostring(#Q).." / "..tostring(#Q))
    local modStatus=startup.self_diag.user_account_mod_status_192()
    w("User-reported account modification status: "..tostring(modStatus.label))
    if #modStatus.confirmed>0 then w("High-confidence modified categories reported: "..tostring(#modStatus.confirmed)) end
    if #modStatus.suspicious>0 then w("Suspicious modified categories reported: "..tostring(#modStatus.suspicious)) end
    if #modStatus.exempt>0 then w("Heist/business/activity modifications recorded but exempt from automatic account-modified classification: "..tostring(#modStatus.exempt)) end
    local lastCat=""
    for _,qq in ipairs(Q) do
        if qq.cat~=lastCat then lastCat=qq.cat; w(""); w("["..lastCat.."]") end
        local value=tostring((sd191.userQuestionnaireAnswers and sd191.userQuestionnaireAnswers[qq.id]) or sd191.questionnaire.answers[qq.id] or "unsure"):upper()
        w(value.." | "..qq.text)
    end
    w(""); w("RANKED DIAGNOSIS"); w("----------------")
    if c.primary then w("MOST LIKELY ISSUE: "..tostring(c.primary.label)); w("Conclusion confidence: "..tostring(c.confidence or 0).." / 100"); w("Diagnostic coverage confidence: "..tostring(c.coverageConfidence or syn.confidence or 0).." / 100") end
    for i,item in ipairs(c.ranked or {}) do if i<=5 then w(string.format("%d. %s | evidence score %.1f",i,tostring(item.label),tonumber(item.score or 0))) end end
    w(""); w("STRONGEST COMBINED EVIDENCE"); w("---------------------------")
    table.sort(c.evidence or {},function(x,y) return (tonumber(x.points or 0) or 0)>(tonumber(y.points or 0) or 0) end)
    for i,e in ipairs(c.evidence or {}) do if i<=12 and (tonumber(e.points or 0) or 0)>0 then w("["..tostring(e.kind or "EVIDENCE").."] +"..tostring(e.points).." "..tostring(e.text)) end end
    w(""); w("Important: user-reported modding history can raise Account Profile suspicion, but the report does not claim that a modified account caused matchmaking failure unless the repeated session/network evidence supports that direction too.")
    f:close(); return true
end

-- Automatic Support ZIP -> dedicated Self Diagnosis package --------------------------
local build191_raw_create_support_zip=startup.create_support_zip
function startup.create_support_zip()
    local ok=build191_raw_create_support_zip()
    if ok and sd191.results191.autoPackagePending==true then
        local src=tostring(startup.SupportZipPath or "")
        local run=tostring(sd191.runId or "Self_Diagnosis")
        local dst=startup.self_diag_dir.."\\"..startup.self_diag.safe_filename(run).."_Self_Diagnosis_Package.zip"
        sd191.results191.autoPackageStatus="Copying validated diagnostic ZIP..."
        local copied,err=false,nil
        if src~="" and startup.support_file_exists(src) then
            if startup.support_stream_copy_file then copied,err=startup.support_stream_copy_file(src,dst,startup.now()+60000)
            else
                local inf=io.open(src,"rb"); local outf=inf and io.open(dst,"wb") or nil
                if inf and outf then while true do local d=inf:read(65536); if not d then break end; outf:write(d) end; inf:close(); outf:close(); copied=true else if inf then inf:close() end; if outf then outf:close() end; err="copy open failed" end
            end
        else err="Support ZIP source was not found" end
        if copied and startup.validate_support_zip_file then local valid,verr=startup.validate_support_zip_file(dst); if not valid then copied=false; err="validation failed: "..tostring(verr) end end
        if copied then
            sd191.results191.autoPackagePath=dst; sd191.results191.autoPackageStatus="Diagnostic ZIP ready"; startup.s.selfDiagLastZipPath=dst
            startup.self_diag.log("AUTO_DIAG_ZIP_READY",dst); startup.copy_to_clipboard(dst)
        else
            sd191.results191.autoPackageStatus="Automatic diagnostic ZIP failed: "..tostring(err or "unknown error"); startup.self_diag.log("AUTO_DIAG_ZIP_FAILED",tostring(err))
        end
        sd191.results191.autoPackagePending=false
    end
    return ok
end

local build191_raw_finish=startup.self_diag.finish
function startup.self_diag.finish(reason)
    build191_raw_finish(reason)
    local syn=startup.self_diag.synthesize(); local c=sd191.results191.lastConclusion or {}
    sd191.results191.hudUntilMs=startup.now()+60000
    sd191.results191.open=true; sd191.popupOpen=false
    sd191.results191.autoPackagePending=true; sd191.results191.autoPackageStatus="Creating automatic diagnostic ZIP..."; sd191.results191.autoPackagePath=""
    startup.queue_support_zip()
    if GUI and GUI.IsOpen and GUI.Toggle then local ok,v=direct_call(GUI.IsOpen); if ok and v~=true then direct_call(GUI.Toggle) end end
    startup.self_diag.log("RESULT_CONCLUSION","primary="..tostring(c.primary and c.primary.label or "Unresolved").." confidence="..tostring(c.confidence or syn.confidence or 0).." autoZip=queued")
end

