    Natives.InvokeVoid(0xBE6B23FFA53FB442,r,g,b,a)
    Natives.InvokeVoid(0xC02F4DBFB51D988B,true)
    Natives.InvokeVoid(0x1CA3E9EAC9D93E5E); Natives.InvokeVoid(0x2513DFB0FB8400FE)
    Natives.InvokeVoid(0x25FBB336DF1804CB,"STRING"); Natives.InvokeVoid(0x6C188BE134E074AA,tostring(text or "")); Natives.InvokeVoid(0xCD015E5BB0D96A57,x+0.0,y+0.0)
end
local function sd191_native_rect(cx,cy,w,h,r,g,b,a)
