local function sd191_phase_info()
    local phase=tostring(sd191.phase or "Idle"); local total=10
    if not sd191.active then return total,total,"Results" end
    if phase=="PREFLIGHT_PENDING" or phase=="PREFLIGHT" or phase:find("ACCOUNT",1,true) then return 1,total,"Preflight + Account/Network Scan" end
    local pos=tonumber(sd191.testPlanPos or 0) or 0
    if pos>=1 and pos<=8 then local spec=sd191.testPlan and sd191.testPlan[pos] or nil; return pos+1,total,spec and spec.label or ("Session Sample #"..tostring(pos)) end
    if phase:find("RESET_HOST",1,true) or phase=="ALT_ROUTE_RETRY_JOIN" then local spec=sd191.testPlan and sd191.testPlan[math.max(1,pos)] or nil; return math.min(9,pos+1),total,"Fresh Host Reset before "..tostring(spec and spec.label or "Join Retry") end
    if phase:find("FINAL_HOST",1,true) then return 10,total,"Final Fresh Host + Results" end
    return math.max(1,math.min(total,pos+1)),total,phase
end

local function sd191_estimated_remaining_ms(now)
    now=tonumber(now or startup.now()) or startup.now()
    if not sd191.active then return 0 end
    local pos=tonumber(sd191.testPlanPos or 0) or 0; local rem=0
    -- Future main observation windows.
    for i=math.max(1,pos+1),#(sd191.testPlan or {}) do local spec=sd191.testPlan[i]; rem=rem+(spec and spec.kind=="HOST" and (tonumber(sd191.hostWindowMs or 600000) or 600000) or (tonumber(sd191.joinWindowMs or 240000) or 240000))+12000 end
    local phase=tostring(sd191.phase or "")
    local r=sd191.currentRecord; local spec=sd191.testPlan and sd191.testPlan[math.max(1,pos)] or nil
    if phase:find("FINAL_HOST",1,true) then
        rem=15000
    elseif phase=="ALT_OBSERVE" and r and spec and tonumber(r.startedAtMs or 0)>0 then
        local win=spec.kind=="HOST" and (tonumber(sd191.hostWindowMs or 600000) or 600000) or (tonumber(sd191.joinWindowMs or 240000) or 240000)
        rem=rem+math.max(0,(r.startedAtMs+win)-now)+15000
    elseif pos>=1 and pos<=#(sd191.testPlan or {}) and spec then
        rem=rem+(spec.kind=="HOST" and (tonumber(sd191.hostWindowMs or 600000) or 600000) or (tonumber(sd191.joinWindowMs or 240000) or 240000))+15000
    else
        if pos==0 then rem=rem+30000 else rem=rem+15000 end
    end
    if phase=="RESET_HOST_HOLD" and tonumber(sd191.resetLoadedAtMs or 0)>0 then rem=rem+math.max(0,(tonumber(sd191.resetHostWindowMs or 60000) or 60000)-(now-tonumber(sd191.resetLoadedAtMs or now))) end
    local hardRemain=math.max(0,(tonumber(sd191.startedAtMs or now)+tonumber(sd191.hardCapMs or 4500000))-now)
    if hardRemain>0 then rem=math.min(rem,hardRemain) end
    return math.max(0,rem)
end

function startup.render_self_diag_hud_build191()
    local now=startup.now(); local active=sd191.active==true; local resultVisible=not active and tonumber(sd191.results191.hudUntilMs or 0)>now
    if not active and not resultVisible then return end
    local line1,line2,line3,progress="","","",0
    if active then
        local p,total,label=sd191_phase_info(); local remain=sd191_estimated_remaining_ms(now); local elapsed=math.max(0,now-(tonumber(sd191.startedAtMs or now) or now)); local denom=elapsed+remain; progress=denom>0 and math.max(0,math.min(1,elapsed/denom)) or 0
        line1="SELF DIAGNOSIS  |  Time Remaining ~"..startup.self_diag.format_ms(remain)
        line2="Phase "..tostring(p).." / "..tostring(total).."  |  "..tostring(label)
        local r=sd191.currentRecord
        if r and tostring(r.kind or "")=="HOST" then line3="HOST  |  Players "..tostring(startup.get_session_player_count()).."  |  Incoming joins +"..tostring(r.joinEvents or 0).."  |  Non-Interference ON"
        elseif r and tostring(r.kind or "")=="JOIN" then line3="JOIN  |  Remote host "..tostring(r.firstHost or "Resolving...").."  |  Players "..tostring(startup.get_session_player_count()).."  |  Passive observation"
        else line3=tostring(sd191.status or "Working...") end
    else
        local c=sd191.results191.lastConclusion or {}; local primary=c.primary or {label="No single cause proven"}; progress=1
        line1="SELF DIAGNOSIS COMPLETE  |  Confidence "..tostring(c.confidence or 0).."/100"
        line2="Most likely issue: "..tostring(primary.label or "No single cause proven")
        line3=tostring(sd191.results191.autoPackageStatus or "Results saved")
    end
    -- Build 193 compact HUD: smaller and anchored close to the bottom edge.
    sd191_native_rect(0.5,0.960,0.50,0.066,0,0,0,140)
    sd191_native_text(line1,0.5,0.936,0.265,95,255,125,235)
    sd191_native_text(line2,0.5,0.955,0.245,255,255,255,235)
    sd191_native_text(line3,0.5,0.974,0.215,170,205,255,225)
    sd191_native_rect(0.5,0.990,0.40,0.004,40,40,45,190)
    if progress>0 then sd191_native_rect(0.5-0.20+(0.40*progress)/2,0.990,0.40*progress,0.004,80,210,125,230) end
end

if Script and Script.RegisterLooped then
    Script.RegisterLooped(function() startup.render_self_diag_hud_build191() end)
end

