        local shown=0; for _,e in ipairs(evidence) do if shown<8 and (tonumber(e.points or 0) or 0)>0 then shown=shown+1; local prefix=tostring(e.kind or "EVIDENCE"); startup.subtle_text_wrapped("["..prefix.."] "..tostring(e.text)) end end
