            startup.text_colored_wrapped(0.35,1.00,0.52,1.00,"ACCOUNT RECOVERY PATH: Prefer repairing and re-testing this current account first. A clean second account is useful as an A/B control on the same PC/network. Replacing/buying another account is a last-resort alternative and does not repair the current profile.")
        end
        if tostring(sd191.latestReportPath or "")~="" then startup.render_color_button("COPY REPORT PATH","Gold","Copies the text-report path.",startup.self_diag.copy_report_path,190,34) end
        if tostring(sd191.results191.autoPackagePath or "")~="" then ImGui.SameLine(); startup.render_color_button("COPY DIAGNOSTIC ZIP PATH","Green","Copies the automatically generated Self Diagnosis package path.",function() startup.copy_to_clipboard(sd191.results191.autoPackagePath); startup.toast("Diagnostic ZIP path copied.",3000) end,240,34) end
        ImGui.SameLine(); startup.render_color_button("CLOSE","Blue","Close the results window.",function() sd191.results191.open=false end,100,34)
