-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 194: truthful pre-flight + Anti AFK Kick ownership
-- Cherax catalog reference: Anti AFK Kick hash 1351440442 under Kick Utility.
-- Startup keeps Anti AFK Kick enabled while loaded so long host/join observations are
-- not invalidated by GTA inactivity removal. The user's original toggle state is
-- restored on clean Startup unload when it could be read reliably.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.anti_afk = startup.anti_afk or {
    hash = 1351440442,
    names = {"Anti AFK Kick", "Anti-AFK Kick", "Anti AFK"},
    captured = false,
    originalState = nil,
    lastStatus = "Pending",
    lastCheckMs = 0,
    lastForceMs = 0,
}

function startup.get_anti_afk_kick_feature()
    local a=startup.anti_afk
    local feature=startup.get_feature_by_hash_safe and startup.get_feature_by_hash_safe(a.hash) or nil
    if feature then return feature,"hash "..tostring(a.hash) end
    if startup.find_feature_by_possible_names then
        local byName,matched=startup.find_feature_by_possible_names(a.names)
        if byName then return byName,tostring(matched or "name") end
    end
    return nil,nil
end

function startup.is_anti_afk_kick_enabled()
    local feature=startup.get_anti_afk_kick_feature()
    if not feature then return false end
    local state=startup.get_feature_bool_state and startup.get_feature_bool_state(feature) or nil
    return state==true
end

function startup.anti_afk_status_text()
    local a=startup.anti_afk
    local feature,source=startup.get_anti_afk_kick_feature()
    if not feature then return "UNAVAILABLE - enable manually in Kick Utility" end
    local state=startup.get_feature_bool_state and startup.get_feature_bool_state(feature) or nil
    if state==true then return "ON (required)" end
    if state==false then return "OFF - REQUIRED" end
    return "Could not verify - check Kick Utility manually"
end

function startup.ensure_anti_afk_kick(force,reason)
    local a=startup.anti_afk
    local feature,source=startup.get_anti_afk_kick_feature()
    if not feature then
        a.lastStatus="Anti AFK Kick unavailable"
        return false
    end
    local before=startup.get_feature_bool_state and startup.get_feature_bool_state(feature) or nil
    if not a.captured and before~=nil then
        a.captured=true
        a.originalState=before==true
    end
    if before==true and force~=true then
        a.lastStatus="ON"
        return true
    end
    if before==true then
        a.lastStatus="ON"
        return true
    end
    local ok=direct_call(function()
        if feature.Toggle then
            feature:Toggle(true)
        elseif feature.SetBoolValue then
            feature:SetBoolValue(true)
        elseif feature.OnClick and before==false then
            feature:OnClick()
        elseif feature.TriggerCallback and before==false then
            feature:TriggerCallback()
        end
    end)
    local after=startup.get_feature_bool_state and startup.get_feature_bool_state(feature) or nil
    if ok and after==true then
        a.lastStatus="ON"
        a.lastForceMs=startup.now and startup.now() or 0
        if startup.support_log_event_quiet then startup.support_log_event_quiet("ANTI_AFK_ON",tostring(reason or "Startup").." | "..tostring(source or "resolved")) end
        return true
    end
    a.lastStatus="Could not verify ON"
    return false
end

function startup.anti_afk_watchdog_tick()
    local a=startup.anti_afk
    local now=startup.now and startup.now() or 0
    if now < (tonumber(a.lastCheckMs or 0) or 0) then a.lastCheckMs=0 end
    if now-(tonumber(a.lastCheckMs or 0) or 0) < 15000 then return end
    a.lastCheckMs=now
    startup.ensure_anti_afk_kick(false,"Startup 15-second watchdog")
end

function startup.restore_anti_afk_kick_on_unload()
    local a=startup.anti_afk
    if not a or a.captured~=true or a.originalState==nil then return end
    local feature=startup.get_anti_afk_kick_feature()
    if not feature then return end
    local wanted=a.originalState==true
    local current=startup.get_feature_bool_state and startup.get_feature_bool_state(feature) or nil
    if current==wanted then return end
    direct_call(function()
        if feature.Toggle then feature:Toggle(wanted)
        elseif feature.SetBoolValue then feature:SetBoolValue(wanted)
        elseif feature.OnClick and current~=nil then feature:OnClick()
        elseif feature.TriggerCallback and current~=nil then feature:TriggerCallback() end
    end)
end

-- Require Anti AFK Kick immediately before an actual diagnostic run as well as in the
-- questionnaire gate. This catches external toggles between the questionnaire and start.
local startup_build194_previous_self_diag_start=startup.self_diag.start
function startup.self_diag.start()
    if sd191 and sd191.questionnaire and sd191.questionnaire.completed==true then
        if startup.ensure_anti_afk_kick(true,"Self Diagnosis launch")~=true then
            startup.toast("Anti AFK Kick is required for Self Diagnosis. Enable it in Cherax -> Kick Utility.",6000)
            sd191.questionnaire.open=true
            return false
        end
    end
    return startup_build194_previous_self_diag_start()
end

