-- Global Desync Auto Rejoin guard.
-- ────────────────────────────────────────────────────────────────────────────────
startup.desync_auto_rejoin_guard = startup.desync_auto_rejoin_guard or {
    hash = 2366926389,
    names = {"Desync Auto Rejoin", "Desync Auto-Rejoin"},
    lastCheckMs = 0,
    lastForceMs = 0,
    lastStatus = "Pending",
}

function startup.get_desync_auto_rejoin_feature()
    local g=startup.desync_auto_rejoin_guard
    local feature=startup.get_feature_by_hash_safe and startup.get_feature_by_hash_safe(g.hash) or nil
    if feature then return feature,"hash "..tostring(g.hash) end
    if startup.find_feature_by_possible_names then
        local f,n=startup.find_feature_by_possible_names(g.names)
        if f then return f,tostring(n or "name") end
    end
    return nil,nil
end

function startup.desync_auto_rejoin_status_text()
    local _,_,isPrime,recognized=startup.get_active_edition_info()
    if recognized~=true then return "Waiting for Cherax edition detection" end
    if isPrime==true then return "Prime: unchanged" end
    local f=startup.get_desync_auto_rejoin_feature()
    if not f then return "UNAVAILABLE - turn OFF manually in Kick Utility" end
    local state=startup.get_feature_bool_state and startup.get_feature_bool_state(f) or nil
    if state==false then return "OFF (required for Standard/Premium)" end
    if state==true then return "ON - MUST BE OFF" end
    return "Could not verify - check Kick Utility manually"
end

function startup.ensure_desync_auto_rejoin_safe(force,reason)
    local g=startup.desync_auto_rejoin_guard
    local _,_,isPrime,recognized=startup.get_active_edition_info()
    if recognized~=true then g.lastStatus="Waiting for edition"; return false end
    if isPrime==true then g.lastStatus="Prime untouched"; return true end
    local feature,source=startup.get_desync_auto_rejoin_feature()
    if not feature then g.lastStatus="Unavailable"; return false end
    local before=startup.get_feature_bool_state and startup.get_feature_bool_state(feature) or nil
    if before==false then g.lastStatus="OFF"; return true end
    local ok=direct_call(function()
        if feature.Toggle then feature:Toggle(false)
        elseif feature.SetBoolValue then feature:SetBoolValue(false)
        elseif feature.OnClick and before==true then feature:OnClick()
        elseif feature.TriggerCallback and before==true then feature:TriggerCallback() end
    end)
    local after=startup.get_feature_bool_state and startup.get_feature_bool_state(feature) or nil
    if ok and after==false then
        g.lastStatus="OFF"; g.lastForceMs=startup.now and startup.now() or 0
        if startup.support_log_event_quiet then startup.support_log_event_quiet("DESYNC_AUTO_REJOIN_OFF",tostring(reason or "Startup").." | "..tostring(source or "resolved")) end
        return true
    end
    g.lastStatus="Could not verify OFF"
    return false
end

function startup.desync_auto_rejoin_watchdog_tick()
    local _,_,isPrime,recognized=startup.get_active_edition_info()
    if recognized~=true or isPrime==true then return end
    local g=startup.desync_auto_rejoin_guard; local now=startup.now and startup.now() or 0
    if now < (tonumber(g.lastCheckMs or 0) or 0) then g.lastCheckMs=0 end
    if now-(tonumber(g.lastCheckMs or 0) or 0)<10000 then return end
    g.lastCheckMs=now
    startup.update_desync_baseline_for_edition()
    startup.ensure_desync_auto_rejoin_safe(false,"Startup 10-second safety watchdog")
end

local build195_prev_anti_afk_watchdog=startup.anti_afk_watchdog_tick
