-- Keep the Cherax 64-method baseline consistent with the global edition rule once the
-- edition is known; never assume a still-loading Prime instance is Standard/Premium.
function startup.update_desync_baseline_for_edition()
    local _,_,isPrime,recognized=startup.get_active_edition_info(); if recognized~=true then return false end
    for _,method in ipairs(startup.cherax_protection64 and startup.cherax_protection64.methods or {}) do
        if tonumber(method[1])==2366926389 then method[4]=isPrime==true end
    end
    return true
end
startup.update_desync_baseline_for_edition()

-- ────────────────────────────────────────────────────────────────────────────────
-- Deep 70-minute plan / method ranking.
-- ────────────────────────────────────────────────────────────────────────────────
local function sd195_plan()
    return {
        {kind="HOST",index=1,label="Hosted Session #1 - Auto Advertise",method="CURRENT"},
        {kind="JOIN",index=1,label="Joined Session #1"},
        {kind="HOST",index=2,label="Hosted Session #2 - Old v1.0.3",method="OLD_V103"},
        {kind="JOIN",index=2,label="Joined Session #2"},
        {kind="HOST",index=3,label="Hosted Session #3 - Super Advertise",method="SUPER"},
        {kind="JOIN",index=3,label="Joined Session #3"},
        {kind="HOST",index=4,label="Hosted Session #4 - Least Performer",method="DYNAMIC_WORST"},
        {kind="JOIN",index=4,label="Joined Session #4"},
        {kind="HOST",index=5,label="Hosted Session #5 - Best Performer",method="DYNAMIC_BEST"},
    }
end

local function sd195_count_map(t)
    local n=0; for _ in pairs(type(t)=="table" and t or {}) do n=n+1 end; return n
end

local function sd195_record_method(r,spec)
    return tostring((r and r.advertiser) or (spec and spec.resolvedMethod) or (spec and spec.method) or "NONE")
end

local function sd195_metric(r)
    local unique=tonumber(r and r.uniqueJoins or 0) or 0
    local net=(tonumber(r and r.endPlayers or 0) or 0)-(tonumber(r and r.startPlayers or 0) or 0)
    local peak=tonumber(r and r.peakPlayers or 0) or 0
    local t15=tonumber(r and r.milestones and r.milestones[15] or 999999999) or 999999999
    return unique,net,peak,t15
end

local function sd195_compare(a,b,best)
    local au,an,ap,at=sd195_metric(a); local bu,bn,bp,bt=sd195_metric(b)
    if au~=bu then return best and au>bu or au<bu end
    if an~=bn then return best and an>bn or an<bn end
    if ap~=bp then return best and ap>bp or ap<bp end
    if at~=bt then return best and at<bt or at>bt end
    return nil
end

local function sd195_rank_discovery_methods()
    local rows={}
    for _,pos in ipairs({1,3,5}) do
        local r=sd195.testRecords and sd195.testRecords[pos] or nil
        local spec=sd195.testPlan and sd195.testPlan[pos] or nil
        if r then
            r.uniqueJoins=tonumber(r.uniqueJoins or sd195_count_map(r.uniqueJoinKeys)) or 0
            rows[#rows+1]={method=sd195_record_method(r,spec),record=r,pos=pos}
        end
    end
    if #rows<1 then return "CURRENT","SUPER" end
    local function select_extreme(wantBest)
        local candidates={rows[1]}
        for i=2,#rows do
            local c=sd195_compare(rows[i].record,candidates[1].record,wantBest)
            if c==true then candidates={rows[i]}
            elseif c==nil then candidates[#candidates+1]=rows[i] end
        end
        return candidates[math.random(1,#candidates)]
    end
    local best=select_extreme(true); local worst=select_extreme(false)
    if best and worst and best.method==worst.method and #rows>1 then
        local alternatives={}; for _,x in ipairs(rows) do if x.method~=best.method then alternatives[#alternatives+1]=x end end
        if #alternatives>0 then worst=alternatives[math.random(1,#alternatives)] end
    end
    sd195.deep70ChosenBest=best and best.method or "CURRENT"
    sd195.deep70ChosenWorst=worst and worst.method or "SUPER"
    sd195.deep70MethodSummary=rows
    startup.self_diag.log("METHOD_RANKING","best="..tostring(sd195.deep70ChosenBest).." worst="..tostring(sd195.deep70ChosenWorst).." discoveryRows="..tostring(#rows))
    return sd195.deep70ChosenBest,sd195.deep70ChosenWorst
end

local function sd195_resolve_method(spec)
    if not spec or spec.kind~="HOST" then return nil end
    local m=tostring(spec.resolvedMethod or spec.method or "CURRENT")
    if m=="DYNAMIC_BEST" or m=="DYNAMIC_WORST" then
        if sd195.deep70ChosenBest=="" or sd195.deep70ChosenWorst=="" then sd195_rank_discovery_methods() end
        m=(m=="DYNAMIC_BEST") and sd195.deep70ChosenBest or sd195.deep70ChosenWorst
        spec.resolvedMethod=m
    end
    return m
end

local function sd195_apply_method_flags(mode)
    mode=tostring(mode or "NONE")
    -- Cancel previous method workers without restoring/changing the user's saved choices.
    startup.s.advertiseFlowSerial=(tonumber(startup.s.advertiseFlowSerial or 0) or 0)+1
    startup.s.oldStartupAdvertiseSerial=(tonumber(startup.s.oldStartupAdvertiseSerial or 0) or 0)+1
    startup.s.superAdvertiseSerial=(tonumber(startup.s.superAdvertiseSerial or 0) or 0)+1
    startup.s.advertiseRunning=false; startup.s.oldStartupAdvertiseRunning=false; startup.s.superAdvertiseRunning=false; startup.s.advertiseSmartActive=false
    startup.s.autoAdvertiseSession=(mode=="CURRENT")
    startup.s.oldStartupAdvertiseEnabled=(mode=="OLD_V103")
    startup.s.superAdvertiseEnabled=(mode=="SUPER")
    startup.set_feature_bool_silently(startup.h.AutoAdvertiseSession,startup.s.autoAdvertiseSession)
    startup.set_feature_bool_silently(startup.h.OldStartupAdvertise,startup.s.oldStartupAdvertiseEnabled)
    startup.set_feature_bool_silently(startup.h.SuperAdvertise,startup.s.superAdvertiseEnabled)
    sd195.activeHostMethod=mode
end

-- SelfDiag advertiser ownership follows the test plan, not the user's pre-test method.
local build195_prev_get_owner=startup.get_advertise_ownership_mode
function startup.get_advertise_ownership_mode()
    if sd195 and sd195.active==true then
        local r=sd195.currentRecord; local spec=sd195.testPlan and sd195.testPlan[tonumber(sd195.testPlanPos or 0) or 0] or nil
        if (r and r.kind=="JOIN") or (spec and spec.kind=="JOIN" and tostring(sd195.phase or ""):find("ALT",1,true)) then return nil,"SelfDiag JOIN" end
        if spec and spec.kind=="HOST" then
            local m=sd195_resolve_method(spec)
            if m then return m,"Build 195 planned HOST method" end
        end
        local ph=tostring(sd195.phase or "")
        if ph:find("RESET_HOST",1,true) or ph:find("FINAL_HOST",1,true) then
            local m=tostring(sd195.activeHostMethod or sd195.deep70ChosenBest or "CURRENT")
            if m=="" then m="CURRENT" end
            return m,"Build 195 recovery/final host"
        end
    end
    return build195_prev_get_owner and build195_prev_get_owner() or nil,"No owner"
end

-- Exact diagnostic mode selection. JOIN is always passive.
function startup.self_diag.set_advertising_for_test(kind)
    kind=tostring(kind or "")
    if kind=="JOIN" then
        sd195_apply_method_flags("NONE")
        startup.advertise_ownership.active=false; startup.advertise_ownership.mode=""; startup.advertise_ownership.desiredCount=0
        startup.set_advertise_session(false,true)
        startup.self_diag.log("JOIN_ADVERTISE_OFF","Build 195 remote-host observation is passive")
        return true
    end
    local spec=sd195.testPlan and sd195.testPlan[tonumber(sd195.testPlanPos or 0) or 0] or nil
    local mode=sd195_resolve_method(spec) or tostring(sd195.activeHostMethod or "CURRENT")
    sd195_apply_method_flags(mode)
    startup.set_advertise_session(true,true)
    if startup.advertise_ownership_tick then startup.advertise_ownership_tick(true) end
    startup.self_diag.log("HOST_ADVERTISE_METHOD","method="..tostring(mode).." step="..tostring(sd195.testPlanPos or 0))
    return true
end

-- The older Current/Old adapters normalize values to 5/10. Build 195 needs a real
-- diagnostic zero for the first 20 seconds, so zero bypasses those clamps and writes the
-- exposed Advertise Count integer directly. 5/10 continue through the proven adapters.
local build195_prev_apply_count=startup.apply_advertise_count
function startup.apply_advertise_count(value,label)
    value=tonumber(value or 0) or 0
    if sd195.active==true and value<=0 and not (startup.is_enhanced_active_edition and startup.is_enhanced_active_edition()) then
        local hash=startup.feature_hash and startup.feature_hash.ADVERTISE_COUNT or 4100757571
        local ok=startup.set_int_feature_by_names(startup.advertise_count_names,0,hash)
        if ok then
            startup.s.advertiseCurrentCount=0
            if startup.native_advertise_count_visual then startup.native_advertise_count_visual.actualValue=0; startup.native_advertise_count_visual.displayValue=0; startup.native_advertise_count_visual.hudDisplayValue=0 end
            local mode=startup.get_advertise_hud_mode and startup.get_advertise_hud_mode() or tostring(sd195.activeHostMethod or "CURRENT")
            if build190_apply_slider_range_and_display then build190_apply_slider_range_and_display(mode,0,"Build 195 diagnostic ramp zero") end
            startup.s.lastAdvertiseStatus=label or "Diagnostic ramp: Advertise Count 0"
        end
        return ok==true
    end
    return build195_prev_apply_count(value,label)
end

local build195_prev_old_count=startup.old_v103_set_count
function startup.old_v103_set_count(value,reason)
    value=tonumber(value or 0) or 0
    if sd195.active==true and value<=0 and not (startup.is_enhanced_active_edition and startup.is_enhanced_active_edition()) then
        local hash=startup.feature_hash and startup.feature_hash.ADVERTISE_COUNT or 4100757571
        local ok=startup.set_int_feature_by_names(startup.advertise_count_names,0,hash)
        if ok then
            startup.s.oldStartupAdvertiseCurrentCount=0; startup.s.advertiseCurrentCount=0
            if startup.native_advertise_count_visual then startup.native_advertise_count_visual.actualValue=0; startup.native_advertise_count_visual.displayValue=0; startup.native_advertise_count_visual.hudDisplayValue=0 end
            if build190_apply_slider_range_and_display then build190_apply_slider_range_and_display("OLD_V103",0,"Build 195 diagnostic ramp zero") end
        end
        return ok==true
    end
    return build195_prev_old_count(value,reason)
