-- Standardized first minute of every measured HOST: 0 -> half -> max.
local build195_prev_desired_count=startup.advertise_ownership_desired_count
function startup.advertise_ownership_desired_count(mode)
    if sd195 and sd195.active==true and sd195.phase=="ALT_OBSERVE" then
        local r=sd195.currentRecord
        if r and r.kind=="HOST" and tonumber(r.startedAtMs or 0)>0 then
            local elapsed=startup.now()-r.startedAtMs
            if elapsed<20000 then return 0 end
            if elapsed<40000 then return 5 end
            if elapsed<60000 then return 10 end
            mode=tostring(mode or r.advertiser or sd195.activeHostMethod or "")
            if mode=="CURRENT" and startup.s.advertiseSmartActive~=true then return 10 end
            if mode=="OLD_V103" and tostring(startup.s.oldStartupAdvertiseStatus or ""):find("Queued",1,true) then return 10 end
        end
    end
    return build195_prev_desired_count and build195_prev_desired_count(mode) or nil
end

