local function sd195_attach_questionnaire_answers()
    if not sd191 or not sd191.questionnaire then return false end
    sd195.userQuestionnaireAnswers={}
    for _,qq in ipairs(Q) do sd195.userQuestionnaireAnswers[qq.id]=sd191.questionnaire.answers[qq.id] or "unsure" end
    sd195.userQuestionnaireCompletedAt=os.time(); sd195.questionnaireAttached=true
    startup.self_diag.log("QUESTIONNAIRE_ATTACHED","answered="..tostring(sd191_answer_count()).."/"..tostring(#Q).." during HOST measurement")
    return true
end

local function sd195_hide_questionnaire(reason)
