    if sd191_answer_count()==#Q and sd191.questionnaire.completed==true then sd195_attach_questionnaire_answers(); return end
    sd191.questionnaire.open=true
    if GUI and GUI.IsOpen and GUI.Toggle then local ok,v=direct_call(GUI.IsOpen); if ok and v~=true then direct_call(GUI.Toggle) end end
    startup.self_diag.log("QUESTIONNAIRE_OPEN_DURING_HOST","Host session stable; session mutation paused while popup is visible")
