-- Track unique incoming players for host-method ranking.
local build195_prev_on_join=startup.self_diag.on_player_join
function startup.self_diag.on_player_join(playerId)
    if build195_prev_on_join then build195_prev_on_join(playerId) end
    if sd195.active~=true or sd195.phase~="ALT_OBSERVE" or startup.self_diag.is_local_id(playerId) then return end
    local r=sd195.currentRecord
    if r and r.kind=="HOST" then
        r.uniqueJoinKeys=r.uniqueJoinKeys or {}
        local rid=sd188_host_rid(playerId); local key
        if rid and rid>0 then key="RID:"..tostring(math.floor(rid)) else key="NAME:"..string.lower(tostring(startup.get_player_name_safe(playerId) or playerId)) end
        r.uniqueJoinKeys[key]=true; r.uniqueJoins=sd195_count_map(r.uniqueJoinKeys)
    end
end

-- JOIN acceptance: up to 3 hops to find 15+ players. All remote hosts (even rejected
-- low-population ones) are tracked so a recycled host can be recognized globally.
local build195_prev_begin_observation=startup.self_diag.begin_current_observation
function startup.self_diag.begin_current_observation()
    local spec=sd195.testPlan and sd195.testPlan[tonumber(sd195.testPlanPos or 0) or 0] or nil
    local r=sd195.currentRecord
    if not spec or not r then return build195_prev_begin_observation() end
    if spec.kind=="JOIN" then
        local ready,why,hname,hid,hrid,hkey=sd188_is_current_target_ready(spec)
        if not ready then return false end
        local seen=tonumber(sd195.joinHostSeenCounts[hkey] or 0) or 0
        if seen>=1 then
            sd195.joinHostSeenCounts[hkey]=seen+1
            r.loaded=true; r.failed=true; r.duplicateHost=true; r.failReason="Repeated remote host: "..tostring(hname); r.startedAtMs=startup.now(); r.startPlayers=startup.get_session_player_count(); r.endPlayers=r.startPlayers
            r.firstHost=hname; r.firstHostId=hid; r.firstHostRid=hrid; r.firstHostKey=hkey
            startup.self_diag.log("DUPLICATE_JOIN_HOST","host="..tostring(hname).." rid="..tostring(hrid).." seen="..tostring(seen+1).." -> fresh host reset")
            sd188_append_join_attempt(r,"duplicate host recycled")
            sd195.currentRecord=nil; sd195.testRecords[sd195.testPlanPos]=nil
            return startup.self_diag.begin_reset_host("Same remote host encountered twice during diagnosis",true)
        end
        sd195.joinHostSeenCounts[hkey]=1
        local count=startup.get_session_player_count()
        if count<sd195.joinMinimumPlayers then
            r.loaded=true; r.failed=true; r.failReason="Below 15-player acceptance threshold"; r.startedAtMs=startup.now(); r.startPlayers=count; r.endPlayers=count; r.peakPlayers=count
            r.firstHost=hname; r.firstHostId=hid; r.firstHostRid=hrid; r.firstHostKey=hkey; r.isLocalHost=false
            sd188_finalize_record(r); sd188_append_join_attempt(r,"low population rejected")
            local attempts=tonumber(sd195.joinAttemptBySlot[spec.index] or 1) or 1
            startup.self_diag.log("JOIN_POPULATION_REJECT","slot="..tostring(spec.index).." attempt="..tostring(attempts).." players="..tostring(count).." host="..tostring(hname))
            if attempts<sd195.maxJoinAttemptsPerSlot then
                sd195.joinAttemptBySlot[spec.index]=attempts+1; sd195.currentRecord=nil; sd195.testRecords[sd195.testPlanPos]=nil
                sd195.phase="ALT_ROUTE_RETRY_JOIN"; sd195.nextActionMs=startup.now()+750; sd195.status="Joined lobby had "..tostring(count).." players; searching again for 15+..."
                return false
            end
            sd195.testRecords[sd195.testPlanPos]=r; sd195.currentRecord=nil; sd195.phase="ALT_NEXT_WAIT"; sd195.nextActionMs=startup.now()+250
            return false
        end
    end
    local ok=build195_prev_begin_observation()
    if ok and spec.kind=="HOST" then
        local mode=sd195_resolve_method(spec) or "CURRENT"
        local rr=sd195.currentRecord
        if rr then rr.advertiser=mode; rr.uniqueJoinKeys=rr.uniqueJoinKeys or {}; rr.uniqueJoins=0 end
        -- Current/Old are started by the inherited begin function. Super needs its own worker.
        if mode=="SUPER" and startup.s.superAdvertiseRunning~=true and startup.run_super_advertise then
            local sok=direct_call(startup.run_super_advertise)
            startup.self_diag.log("HOST_ADVERTISE_START",spec.label.." advertiser=SUPER ok="..tostring(sok))
        end
        -- The questionnaire may exist only after host identity is confirmed and observation started.
        sd195_open_questionnaire_if_needed()
    end
    return ok
end

local function sd195_take_account_checkpoint(label)
    if sd195.active~=true then return false end

    -- scan_account() is an older reusable scanner that intentionally sets SelfDiag.phase
    -- to ACCOUNT_SCAN for the original preflight flow. Mid-run checkpoints must NOT keep
    -- that phase, otherwise the Deep70 state machine no longer matches a routing state and
    -- session hopping stalls after the scan. Preserve the post-observation state exactly.
    local resumeState = {
        phase=sd195.phase,
        status=sd195.status,
        nextActionMs=sd195.nextActionMs,
        nextSampleMs=sd195.nextSampleMs,
        testPlanPos=sd195.testPlanPos,
        currentRecord=sd195.currentRecord,
    }
    startup.self_diag.log("ACCOUNT_CHECKPOINT_STATE_SAVE",
        "label="..tostring(label or "").." phase="..tostring(resumeState.phase).." step="..tostring(resumeState.testPlanPos))

    local base=tostring(sd195.runId or "ACCOUNT"); local original=sd195.runId
    sd195.runId=base.."_"..startup.self_diag.safe_filename(tostring(label or "CHECKPOINT"))
    startup.self_diag.log("ACCOUNT_CHECKPOINT_BEGIN",tostring(label or ""))
    local okScan=direct_call(startup.self_diag.scan_account)
    local okWrite=false; if okScan then local pw,res=direct_call(startup.self_diag.write_account_snapshot); okWrite=pw and res==true end
    local path=tostring(sd195.latestSnapshotPath or "")
    sd195.runId=original

    -- Critical Build 200 fix: return to the exact Deep70 state that existed before the
    -- read-only checkpoint. Do this even when the snapshot write fails so diagnostics can
    -- continue and report the checkpoint failure instead of hanging at Phase 1/11.
    sd195.phase=resumeState.phase
    sd195.status=resumeState.status
    sd195.nextActionMs=resumeState.nextActionMs
    sd195.nextSampleMs=resumeState.nextSampleMs
    sd195.testPlanPos=resumeState.testPlanPos
    sd195.currentRecord=resumeState.currentRecord

    sd195.accountCheckpoints=sd195.accountCheckpoints or {}; sd195.accountCheckpoints[#sd195.accountCheckpoints+1]={label=tostring(label or ""),path=path,at=os.time()}
    startup.self_diag.log("ACCOUNT_CHECKPOINT_END","label="..tostring(label or "").." scan="..tostring(okScan).." write="..tostring(okWrite).." path="..path)
    startup.self_diag.log("ACCOUNT_CHECKPOINT_STATE_RESTORE",
        "label="..tostring(label or "").." phase="..tostring(sd195.phase).." step="..tostring(sd195.testPlanPos).." nextActionMs="..tostring(sd195.nextActionMs))
    return okScan and okWrite
end

local build195_prev_finish_observation=startup.self_diag.finish_current_observation
function startup.self_diag.finish_current_observation(reason,forceRetryJoin)
    local spec=sd195.testPlan and sd195.testPlan[tonumber(sd195.testPlanPos or 0) or 0] or nil
    local r=sd195.currentRecord
    if r and r.kind=="HOST" then r.uniqueJoins=sd195_count_map(r.uniqueJoinKeys) end
    local hostOneFinished=spec and spec.kind=="HOST" and spec.index==1 and tostring(reason or "")=="10-minute window complete"
    if not hostOneFinished then sd195_hide_questionnaire("observation ended; transition may follow") end
    local ok=build195_prev_finish_observation(reason,forceRetryJoin)
    if spec and spec.kind=="HOST" and sd195_resolve_method(spec)=="SUPER" and startup.s.superAdvertiseRunning==true and startup.stop_super_advertise then
        startup.stop_super_advertise("Self Diagnosis fixed 10-minute Super host sample complete")
        startup.self_diag.log("HOST_SUPER_WORKER_STOPPED","step="..tostring(sd195.testPlanPos).." reason="..tostring(reason or ""))
    end
    if spec and spec.kind=="HOST" and spec.index==3 and sd195.midpointCheckpointTaken~=true then
        sd195.midpointCheckpointTaken=true; sd195_take_account_checkpoint("MIDPOINT_AFTER_SUPER")
    end
    if hostOneFinished and sd195.questionnaireAttached~=true then
        sd195.phase="WAIT_QUESTIONNAIRE"; sd195.nextActionMs=0; sd195.questionnairePausedAfterHost1=true
        sd195.status="Host #1 measured 10:00. Finish the remaining questionnaire; matchmaking measurement is paused."
        sd195_open_questionnaire_if_needed()
        startup.self_diag.log("HOST1_MEASUREMENT_PAUSED","10-minute host result frozen; waiting for questionnaire completion")
    end
    return ok
end

-- Replace Start behavior: first click begins Host #1; questionnaire opens only after the
-- host is confirmed. Clicking the questionnaire's final button while active merely attaches
-- answers and resumes the state machine if Host #1 already finished.
function startup.self_diag.start()
    if sd195.active==true then
        if sd191 and sd191.questionnaire and sd191.questionnaire.completed==true and sd191_answer_count()==#Q then
            if startup.ensure_anti_afk_kick and startup.ensure_anti_afk_kick(true,"Questionnaire completion")~=true then startup.toast("Anti AFK Kick must remain ON.",5000); return false end
            if (not startup.is_prime_active_edition or not startup.is_prime_active_edition()) and startup.ensure_desync_auto_rejoin_safe(true,"Questionnaire completion")~=true then startup.toast("Startup could not verify Desync Auto Rejoin OFF. Search for it in the top right corner of the Cherax menu via the magnifying glass icon, turn it OFF, then try again.",9000); return false end
            sd195_attach_questionnaire_answers(); sd191.questionnaire.open=false
            if sd195.phase=="WAIT_QUESTIONNAIRE" then sd195.phase="ALT_NEXT_WAIT"; sd195.nextActionMs=startup.now()+250; sd195.status="Questionnaire complete. Continuing to Joined Session #1..." end
            return true
        end
        startup.toast("Self Diagnosis is already running.",3000); return false
    end

    if startup.ensure_anti_afk_kick and startup.ensure_anti_afk_kick(true,"Deep Diagnosis launch")~=true then startup.toast("Anti AFK Kick is required for Self Diagnosis.",6000); return false end
    if (not startup.is_prime_active_edition or not startup.is_prime_active_edition()) and startup.ensure_desync_auto_rejoin_safe(true,"Deep Diagnosis launch")~=true then
        startup.toast("Startup could not verify Desync Auto Rejoin OFF. Search for it in the top right corner of the Cherax menu via the magnifying glass icon, turn it OFF, then try again.",9000); return false
    end

    startup.self_diag.ensure_dir(); sd195.serial=(tonumber(sd195.serial or 0) or 0)+1
    sd195.testPlan=sd195_plan(); sd195.hostWindowMs=600000; sd195.joinWindowMs=300000; sd195.maxRuntimeMs=5400000; sd195.hardCapMs=5400000; sd195.maxJoinAttemptsPerSlot=3
    sd195.active=true; sd195.popupOpen=false; sd195.abortRequested=false; sd195.abortReason=""; sd195.phase="PREFLIGHT_PENDING"
    sd195.status="Starting Deep ~70-minute diagnosis; first stable HOST will open the questionnaire..."; sd195.startedAtMs=startup.now(); sd195.startedAtEpoch=os.time(); sd195.nextActionMs=startup.now()+250; sd195.nextSampleMs=0
    sd195.testPlanPos=0; sd195.testRecords={}; sd195.currentRecord=nil; sd195.joinAttempts={}; sd195.joinAttemptBySlot={1,1,1,1}; sd195.seenJoinHosts={}; sd195.rejectedJoinHosts={}; sd195.joinHostSeenCounts={}; sd195.nodeState={}; sd195.findings={}; sd195.joinExitRequested=false; sd195.joinExitReason=""
    sd195.guard={active=false,savedSettings=nil,savedPlayerStates={},savedPlayerSelectorIndex=nil}; sd195.deep70ChosenBest=""; sd195.deep70ChosenWorst=""; sd195.deep70MethodSummary={}; sd195.questionnaireAttached=false; sd195.questionnairePausedAfterHost1=false; sd195.activeHostMethod="CURRENT"; sd195.accountCheckpoints={}; sd195.midpointCheckpointTaken=false; sd195.finalCheckpointTaken=false
    if sd191 and sd191.questionnaire then sd191.questionnaire.answers={}; sd191.questionnaire.completed=false; sd191.questionnaire.page=1; sd191.questionnaire.open=false end
    sd195.userQuestionnaireAnswers={}
    local meta=startup.get_support_runtime_metadata and startup.get_support_runtime_metadata() or {}; sd195.runId=startup.self_diag.safe_filename(meta.localPlayerName or "ACCOUNT").."_"..os.date("%Y_%m_%d_%H%M%S")
    startup.self_diag.snapshot_user_settings(); sd195.savedBenchmarkEnabled=startup.s.advertiseBenchmarkEnabled~=false
    startup.s.advertiseBenchmarkEnabled=true; startup.set_feature_bool_silently(startup.h.AdvertiseBenchmarkTimer,true)
    startup.self_diag.suspend_normal_automation()
    startup.self_diag.log("START","run="..sd195.runId.." build="..tostring(startup.build_number).." engine=deep70-host-survey-current-old-super-worst-best")
    return true
end

-- Resume WAIT_QUESTIONNAIRE safely from the permanent diagnostic tick path.
local build195_prev_diag_tick=startup.self_diag.tick
function startup.self_diag.tick()
    if sd195.active==true and sd195.phase=="WAIT_QUESTIONNAIRE" then
        if sd195.questionnaireAttached==true then sd195.phase="ALT_NEXT_WAIT"; sd195.nextActionMs=startup.now()+250 end
        return
    end
    return build195_prev_diag_tick()
end

-- Ensure popup is hidden before final-host routing even if a user somehow left it open.
local build195_prev_finish=startup.self_diag.finish
function startup.self_diag.finish(reason)
    sd195_hide_questionnaire("diagnosis finishing")
    if sd195.active==true and sd195.finalCheckpointTaken~=true then sd195.finalCheckpointTaken=true; sd195_take_account_checkpoint("FINAL") end
    build195_prev_finish(reason)
    if sd195.savedBenchmarkEnabled~=nil then
        startup.s.advertiseBenchmarkEnabled=sd195.savedBenchmarkEnabled==true
        startup.set_feature_bool_silently(startup.h.AdvertiseBenchmarkTimer,startup.s.advertiseBenchmarkEnabled)
    end
end

-- Add method comparison to the human-readable report before the automatic ZIP is created.
local build195_prev_write_report=startup.self_diag.write_report
function startup.self_diag.write_report(reason)
    local ok=build195_prev_write_report(reason)
    local path=tostring(sd195.latestReportPath or ""); if not ok or path=="" then return ok end
    local f=io.open(path,"a"); if not f then return ok end
    local function w(x) f:write(tostring(x or ""),"\n") end
    if sd195.deep70ChosenBest=="" or sd195.deep70ChosenWorst=="" then sd195_rank_discovery_methods() end
    w(""); w("HOST ADVERTISING METHOD COMPARISON"); w("----------------------------------")
    w("Primary ranking metric: unique incoming players during the fixed 10-minute host window; tie-breakers are net population gain, peak population, then time to 15 players.")
    for pos,spec in ipairs(sd195.testPlan or {}) do
        local r=sd195.testRecords and sd195.testRecords[pos] or nil
        if r and r.kind=="HOST" then
            local unique=tonumber(r.uniqueJoins or sd195_count_map(r.uniqueJoinKeys)) or 0
            local net=(tonumber(r.endPlayers or 0) or 0)-(tonumber(r.startPlayers or 0) or 0)
            w(string.format("%s | method=%s | uniqueIncoming=%d | joinCallbacks=%d | start=%d | end=%d | net=%+d | peak=%d | joins@1m=%d | joins@10m=%d",tostring(spec.label),tostring(r.advertiser or sd195_resolve_method(spec) or "NONE"),unique,tonumber(r.joinEvents or 0) or 0,tonumber(r.startPlayers or 0) or 0,tonumber(r.endPlayers or 0) or 0,net,tonumber(r.peakPlayers or 0) or 0,tonumber(r.joins1m or 0) or 0,tonumber(r.joins10m or 0) or 0))
        end
    end
    w("Discovery BEST method selected for final confirmation: "..tostring(sd195.deep70ChosenBest or "Unknown"))
    w("Discovery LEAST method selected for confirmation: "..tostring(sd195.deep70ChosenWorst or "Unknown"))
    w(""); w("JOIN ACCEPTANCE POLICY"); w("----------------------")
    w("Joined-session control samples require a remote Session Host and at least 15 players. Up to 3 Join Public Session attempts are allowed per control phase. Repeated remote hosts are rejected and trigger a fresh local-host reset to break Previous Session recycling.")
    w(""); w("ACCOUNT CHECKPOINTS"); w("-------------------")
    w("Baseline: the normal <run>_Account_503_Diff.csv captured before session testing.")
    for _,cp in ipairs(sd195.accountCheckpoints or {}) do w(tostring(cp.label).." | "..tostring(cp.path)) end
    f:close(); return true
end

-- Updated compact HUD for 9 primary session samples + preflight + final results.
local function sd195_phase_info()
    local total=11; local phase=tostring(sd195.phase or "Idle")
    if not sd195.active then return total,total,"Results" end
    if phase=="PREFLIGHT_PENDING" or phase:find("ACCOUNT",1,true) then return 1,total,"Preflight + Account/Network Scan" end
    local pos=tonumber(sd195.testPlanPos or 0) or 0
    if phase=="WAIT_QUESTIONNAIRE" then return 2,total,"Host #1 complete - Finish Questionnaire" end
    if pos>=1 and pos<=#(sd195.testPlan or {}) then local spec=sd195.testPlan[pos]; return math.min(10,pos+1),total,spec and spec.label or ("Session Sample #"..tostring(pos)) end
    if phase:find("RESET_HOST",1,true) or phase=="ALT_ROUTE_RETRY_JOIN" then return math.max(2,math.min(10,pos+1)),total,"Fresh Host Reset / Join Search" end
    if phase:find("FINAL_HOST",1,true) then return 11,total,"Final Fresh Host + Results" end
    return math.max(1,math.min(total,pos+1)),total,phase
end

local function sd195_estimated_remaining_ms(now)
    now=tonumber(now or startup.now()) or startup.now(); if not sd195.active then return 0 end
    local pos=tonumber(sd195.testPlanPos or 0) or 0; local rem=0; local phase=tostring(sd195.phase or "")
    for i=math.max(1,pos+1),#(sd195.testPlan or {}) do local sp=sd195.testPlan[i]; rem=rem+(sp.kind=="HOST" and 600000 or 300000)+12000 end
    local r=sd195.currentRecord; local spec=sd195.testPlan and sd195.testPlan[math.max(1,pos)] or nil
    if phase=="WAIT_QUESTIONNAIRE" then rem=rem+15000
    elseif phase=="ALT_OBSERVE" and r and spec and tonumber(r.startedAtMs or 0)>0 then rem=rem+math.max(0,(r.startedAtMs+(spec.kind=="HOST" and 600000 or 300000))-now)+12000
    elseif pos>=1 and spec then rem=rem+(spec.kind=="HOST" and 600000 or 300000)+12000
    else rem=rem+20000 end
    if phase=="RESET_HOST_HOLD" and tonumber(sd195.resetLoadedAtMs or 0)>0 then rem=rem+math.max(0,60000-(now-tonumber(sd195.resetLoadedAtMs))) end
    return math.max(0,math.min(rem,math.max(0,(tonumber(sd195.startedAtMs or now)+5400000)-now)))
end

function startup.render_self_diag_hud_build191()
    local now=startup.now(); local active=sd195.active==true; local resultVisible=not active and sd191 and sd191.results191 and tonumber(sd191.results191.hudUntilMs or 0)>now
    if not active and not resultVisible then return end
    local line1,line2,line3,progress="","","",0
    if active then
        local p,total,label=sd195_phase_info(); local remain=sd195_estimated_remaining_ms(now); local elapsed=math.max(0,now-(tonumber(sd195.startedAtMs or now) or now)); local denom=elapsed+remain; progress=denom>0 and math.max(0,math.min(1,elapsed/denom)) or 0
        line1="SELF DIAGNOSIS  |  Time Remaining ~"..startup.self_diag.format_ms(remain)
        line2="Phase "..tostring(p).." / "..tostring(total).."  |  "..tostring(label)
        local r=sd195.currentRecord
        if sd195.phase=="WAIT_QUESTIONNAIRE" then line3="HOST #1 measurement saved  |  Finish questionnaire to continue"
        elseif r and r.kind=="HOST" then line3="HOST  |  "..tostring(r.advertiser or sd195.activeHostMethod or "").."  |  Players "..tostring(startup.get_session_player_count()).."  |  Unique incoming +"..tostring(r.uniqueJoins or 0)
        elseif r and r.kind=="JOIN" then line3="JOIN  |  Host "..tostring(r.firstHost or "Resolving...").."  |  Players "..tostring(startup.get_session_player_count()).."  |  Need 15+"
        else line3=tostring(sd195.status or "Working...") end
    else
        local c=sd191.results191.lastConclusion or {}; local primary=c.primary or {label="No single cause proven"}; progress=1
        line1="SELF DIAGNOSIS COMPLETE  |  Confidence "..tostring(c.confidence or 0).."/100"
        line2="Most likely issue: "..tostring(primary.label or "No single cause proven")
        line3=tostring(sd191.results191.autoPackageStatus or "Results saved")
    end
    sd191_native_rect(0.5,0.960,0.50,0.066,0,0,0,140)
    sd191_native_text(line1,0.5,0.936,0.265,95,255,125,235)
    sd191_native_text(line2,0.5,0.955,0.245,255,255,255,235)
    sd191_native_text(line3,0.5,0.974,0.215,170,205,255,225)
    sd191_native_rect(0.5,0.990,0.40,0.004,40,40,45,190)
    if progress>0 then sd191_native_rect(0.5-0.20+(0.40*progress)/2,0.990,0.40*progress,0.004,80,210,125,230) end
end

startup.self_diag.log("BUILD195_OVERRIDES_READY","Deep 70m CURRENT/OLD/SUPER -> least -> best + questionnaire during stable HOST only + 15-player JOIN controls + Standard/Premium Desync Auto Rejoin forced OFF; Prime untouched")


-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 196 - Desync Auto Rejoin exact-feature resolver / verification fix
--
-- Build 195 could resolve the legacy protection-catalog hash before the visible Kick
-- Utility toggle. On some Cherax layouts that can produce a stale/mismatched state:
-- the user visibly turns Desync Auto Rejoin OFF, yet Startup still reads ON/unknown.
--
-- Build 196 resolves the visible feature by exact normalized name first, then falls
-- back to a verified enumeration match, and only finally to the historical hash.
-- Every read/write is performed against the SAME resolved Feature object.
-- Prime remains untouched.
-- ═══════════════════════════════════════════════════════════════════════════════════

local function startup196_norm_feature_name(v)
    v=tostring(v or ""):lower()
    v=v:gsub("[%s%p_]+","")
    return v
end

local function startup196_feature_name(feature)
    if not feature then return "" end
    local ok,n=direct_call(function()
        if feature.GetName then return feature:GetName(false) end
        return feature.Name or ""
    end)
    if ok and n~=nil then return tostring(n) end
    return ""
end

local function startup196_is_desync_feature(feature)
    local n=startup196_norm_feature_name(startup196_feature_name(feature))
    return n=="desyncautorejoin" or n:find("desyncautorejoin",1,true)~=nil
end

function startup.get_desync_auto_rejoin_feature()
    local g=startup.desync_auto_rejoin_guard

    -- 1) Prefer the exact visible Kick Utility feature. This is what the user sees
    -- and what Cherax search opens when they type "Desync Auto Rejoin".
    if FeatureMgr and FeatureMgr.GetFeatureByName then
        for _,name in ipairs(g.names or {"Desync Auto Rejoin"}) do
            local ok,f=direct_call(function() return FeatureMgr.GetFeatureByName(name) end)
            if ok and f and startup196_is_desync_feature(f) then
                return f,"exact name: "..tostring(name)
            end
        end
    end

    -- 2) Enumerate and match normalized names. This handles small punctuation /
    -- localization-wrapper differences without accepting unrelated "desync" items.
    if FeatureMgr and FeatureMgr.GetAllFeatures then
        local ok,all=direct_call(function() return FeatureMgr.GetAllFeatures() end)
        if ok and type(all)=="table" then
            for _,f in pairs(all) do
                if f and startup196_is_desync_feature(f) then
                    return f,"enumerated: "..startup196_feature_name(f)
                end
            end
        end
    end

    -- 3) Historical hash fallback, but only trust it if the returned Feature name
    -- actually identifies Desync Auto Rejoin. This prevents a stale/colliding hash
    -- from gating diagnostics against the wrong toggle.
    if startup.get_feature_by_hash_safe then
        local f=startup.get_feature_by_hash_safe(g.hash)
        if f and startup196_is_desync_feature(f) then
            return f,"verified hash "..tostring(g.hash)
        end
    end
    return nil,nil
end

function startup.read_desync_auto_rejoin_state(feature)
    if not feature then return nil end

    -- Read the object first because it is the exact Feature object we will write.
    if feature.IsToggled then
        local ok,v=direct_call(function() return feature:IsToggled() end)
        if ok and v~=nil then return v==true end
    end
    if feature.GetBoolValue then
        local ok,v=direct_call(function() return feature:GetBoolValue() end)
        if ok and v~=nil then return v==true end
    end

    -- FeatureMgr fallback using the resolved object's own hash, not the old constant.
    if feature.GetHash and FeatureMgr then
        local okHash,h=direct_call(function() return feature:GetHash() end)
        if okHash and h then
            if FeatureMgr.IsFeatureToggled then
                local ok,v=direct_call(function() return FeatureMgr.IsFeatureToggled(h) end)
                if ok and v~=nil then return v==true end
            end
            if FeatureMgr.IsFeatureEnabled then
                local ok,v=direct_call(function() return FeatureMgr.IsFeatureEnabled(h) end)
                if ok and v~=nil then return v==true end
            end
        end
    end
    return nil
end

function startup.desync_auto_rejoin_status_text()
    local _,_,isPrime,recognized=startup.get_active_edition_info()
    if recognized~=true then return "Waiting for Cherax edition detection" end
    if isPrime==true then return "Prime: unchanged" end
    local f=startup.get_desync_auto_rejoin_feature()
    if not f then return "UNAVAILABLE - use Cherax search (magnifying glass)" end
    local state=startup.read_desync_auto_rejoin_state(f)
    if state==false then return "OFF (required for Standard/Premium)" end
    if state==true then return "ON - Startup will turn it OFF" end
    return "Could not verify - use Cherax search (magnifying glass)"
end

function startup.ensure_desync_auto_rejoin_safe(force,reason)
    local g=startup.desync_auto_rejoin_guard
    local _,_,isPrime,recognized=startup.get_active_edition_info()
    if recognized~=true then g.lastStatus="Waiting for edition"; return false end
    if isPrime==true then g.lastStatus="Prime untouched"; return true end

    local feature,source=startup.get_desync_auto_rejoin_feature()
    if not feature then
        g.lastStatus="Visible Desync Auto Rejoin feature unavailable"
        return false
    end

    local before=startup.read_desync_auto_rejoin_state(feature)
    if before==false then
        g.lastStatus="OFF"
        return true
    end

    -- Try Toggle(false) first because Cherax documents it as the toggle-state API.
    -- If that path is unavailable or does not change the value, try SetBoolValue /
    -- SetValue on the same exact Feature object. Never trigger a second callback once
    -- the desired OFF state has already been observed.
    local methods={
        function() if feature.Toggle then feature:Toggle(false); return true end return false end,
        function() if feature.SetBoolValue then feature:SetBoolValue(false); return true end return false end,
        function() if feature.SetValue then feature:SetValue(false); return true end return false end,
        function()
            local current=startup.read_desync_auto_rejoin_state(feature)
            if current==true and feature.OnClick then feature:OnClick(); return true end
            if current==true and feature.TriggerCallback then feature:TriggerCallback(); return true end
            return false
        end,
    }

    local attempted=false
    for _,writer in ipairs(methods) do
        local ok,did=direct_call(writer)
        if ok and did==true then attempted=true end
        local after=startup.read_desync_auto_rejoin_state(feature)
        if after==false then
            g.lastStatus="OFF"
            g.lastForceMs=startup.now and startup.now() or 0
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("DESYNC_AUTO_REJOIN_OFF",tostring(reason or "Startup").." | "..tostring(source or "resolved").." | build196 exact-feature")
            end
            return true
        end
    end

    -- If the feature was already manually OFF but a particular Cherax getter is
    -- temporarily unavailable, re-resolve by exact name once more before failing.
    local fresh,freshSource=startup.get_desync_auto_rejoin_feature()
    local freshState=startup.read_desync_auto_rejoin_state(fresh)
    if fresh and freshState==false then
        g.lastStatus="OFF"
        return true
    end

    g.lastStatus=attempted and "Commanded OFF but could not verify" or "Could not command OFF"
    return false
end

-- Build 196 user-facing helper used by all diagnostic gates when automation cannot
-- verify the setting. Normally users will never need this because Startup controls it.
function startup.desync_auto_rejoin_manual_help_toast()
    startup.toast("Startup could not verify Desync Auto Rejoin OFF. Search for it in the top right corner of the Cherax menu via the magnifying glass icon, turn it OFF, then try again.",9000)
end

-- Wrap the active Deep70 start function only to provide the improved fallback message.
-- The underlying Build195 start still performs the automatic OFF command using the
-- Build196 resolver above.
local startup196_previous_self_diag_start=startup.self_diag.start
function startup.self_diag.start()
    local _,_,isPrime,recognized=startup.get_active_edition_info()
    if recognized==true and isPrime~=true then
        local safe=startup.ensure_desync_auto_rejoin_safe(true,"Build 196 Run Full Self Diagnosis preflight")
        if safe~=true then
            startup.desync_auto_rejoin_manual_help_toast()
            return false
        end
    end
    return startup196_previous_self_diag_start()
end

