local function sd199_progress_bar(pct, label)
    pct = math.max(0, math.min(100, tonumber(pct or 0) or 0))
    if ImGui and ImGui.ProgressBar then
        local ok = direct_call(ImGui.ProgressBar, pct / 100, 0, 22, tostring(label or (math.floor(pct + 0.5).."%")))
        if ok then return end
    end
    local blocks = math.floor(pct / 5)
    startup.subtle_text_wrapped(string.rep("█", blocks)..string.rep("░", 20 - blocks).."  "..tostring(math.floor(pct + 0.5)).."%")
end

local function sd199_render_top3_graph(top)
    startup.section_title("Top 3 most likely causes")
    startup.subtle_text_wrapped("These bars show Startup's relative diagnostic-likelihood weights among the three strongest specific causes. They are evidence weights, not calibrated statistical probabilities.")
    ImGui.Spacing()
    for i = 1, math.min(3, #(top or {})) do
        local r = top[i]
        local pct = tonumber(r.likelihood or 0) or 0
        local label = "#"..tostring(i).."  "..tostring(r.category or "Unknown").." — "..tostring(r.title or "Unknown cause")
        if i == 1 then
            startup.text_colored_wrapped(1.00, 0.72, 0.18, 1.00, label)
        elseif i == 2 then
            startup.text_colored_wrapped(0.42, 0.82, 1.00, 1.00, label)
        else
            startup.text_colored_wrapped(0.78, 0.78, 0.82, 1.00, label)
        end
        sd199_progress_bar(pct, tostring(math.floor(pct + 0.5)).."% diagnostic likelihood")
        if i < math.min(3, #(top or {})) then ImGui.Spacing() end
    end
end

