                sd198_render_cause_card(top[i], i)
                if i < math.min(3, #top) then ImGui.Separator() end
            end
            local ms = c.accountModStatus or startup.self_diag.user_account_mod_status_192()
            ImGui.Separator()
            startup.section_title("Account modification status")
            startup.subtle_text_wrapped(tostring(ms.label or "Unknown")..". Account modification and matchmaking cause remain separate: modified-looking stats do not automatically prove matchmaking restriction, and healthy-looking stats do not rule out network/ISP/session problems.")
        end
        if ImGui.BeginChild and ImGui.EndChild then ImGui.EndChild() end

        ImGui.Spacing()
        startup.render_color_button("COPY TOP 3 FIXES", "Gold", "Copies the detailed Top 3 causes, evidence, fixes, and any ISP/support wording.", function()
            startup.copy_to_clipboard(sd198_fix_text(top))
            startup.toast("Top 3 fixes copied.", 3000)
        end, 180, 34)
        if tostring(sd195.latestReportPath or "") ~= "" then
            ImGui.SameLine()
            startup.render_color_button("COPY REPORT PATH", "Purple", "Copies the detailed text-report path.", startup.self_diag.copy_report_path, 180, 34)
        end
        if tostring(sd191.results191.autoPackagePath or "") ~= "" then
            ImGui.SameLine()
            startup.render_color_button("COPY DIAGNOSTIC ZIP PATH", "Green", "Copies the automatic Self Diagnosis ZIP path.", function()
                startup.copy_to_clipboard(sd191.results191.autoPackagePath)
                startup.toast("Diagnostic ZIP path copied.", 3000)
            end, 230, 34)
        end
        ImGui.SameLine()
        startup.render_color_button("CLOSE", "Blue", "Close results.", function() sd191.results191.open = false end, 90, 34)
    end
    ImGui.End()
    startup.pop_first_run_style(colors, vars)
end

