-- Build 201 - persistent diagnostic artifacts + independent abort/fresh-host recovery
-- ===============================================================================
startup.build_number = "2026.08.07.201"

local sd201 = sd195
sd201.artifacts = sd201.artifacts or {}
sd201.eventTimeline = sd201.eventTimeline or {}
sd201.abortForceState = sd201.abortForceState or nil
sd201.abortForceAttempts = tonumber(sd201.abortForceAttempts or 0) or 0
sd201.abortForceAtMs = tonumber(sd201.abortForceAtMs or 0) or 0

local function sd201_json_escape(s)
    s=tostring(s or "")
    s=s:gsub("\\","\\\\"):gsub('"','\\"'):gsub("\b","\\b"):gsub("\f","\\f"):gsub("\n","\\n"):gsub("\r","\\r"):gsub("\t","\\t")
    return s
end

local function sd201_is_array(t)
    if type(t)~="table" then return false,0 end
    local max,n=0,0
    for k,_ in pairs(t) do
        if type(k)~="number" or k<1 or k%1~=0 then return false,0 end
        if k>max then max=k end; n=n+1
    end
    return max==n,max
end

local function sd201_json_encode(v,depth,seen)
    depth=tonumber(depth or 0) or 0; seen=seen or {}
    if depth>8 then return '"<max-depth>"' end
    local tv=type(v)
    if tv=="nil" then return "null" end
    if tv=="boolean" then return v and "true" or "false" end
    if tv=="number" then if v~=v or v==math.huge or v==-math.huge then return "null" end; return tostring(v) end
    if tv=="string" then return '"'..sd201_json_escape(v)..'"' end
    if tv~="table" then return '"<'..sd201_json_escape(tv)..'>"' end
    if seen[v] then return '"<cycle>"' end
    seen[v]=true
    local arr,n=sd201_is_array(v); local out={}
    if arr then
        for i=1,n do out[#out+1]=sd201_json_encode(v[i],depth+1,seen) end
        seen[v]=nil; return "["..table.concat(out,",").."]"
    end
    local keys={}; for k,_ in pairs(v) do keys[#keys+1]=tostring(k) end; table.sort(keys)
    local used={}
    for _,ks in ipairs(keys) do
        local value=nil; local found=false
        if v[ks]~=nil then value=v[ks]; found=true else
            for k,val in pairs(v) do if tostring(k)==ks and not used[k] then value=val; used[k]=true; found=true; break end end
        end
        if found then out[#out+1]='"'..sd201_json_escape(ks)..'":'..sd201_json_encode(value,depth+1,seen) end
    end
    seen[v]=nil; return "{"..table.concat(out,",").."}"
end

local function sd201_write(path,data)
    local f=io and io.open and io.open(tostring(path or ""),"w") or nil
    if not f then return false end
    f:write(tostring(data or "")); f:close(); return true
end

local function sd201_append(path,line)
    local f=io and io.open and io.open(tostring(path or ""),"a") or nil
    if not f then return false end
    f:write(tostring(line or ""),"\n"); f:close(); return true
end

local function sd201_csv(v)
    local s=tostring(v==nil and "" or v):gsub('"','""')
    if s:find('[,\r\n"]') then return '"'..s..'"' end
    return s
end

local function sd201_answers_table()
    local out={}
    for _,qq in ipairs(Q or {}) do
        local v=nil
        if sd195.userQuestionnaireAnswers then v=sd195.userQuestionnaireAnswers[qq.id] end
        if v==nil and sd191 and sd191.questionnaire and sd191.questionnaire.answers then v=sd191.questionnaire.answers[qq.id] end
        if v~=nil then out[qq.id]=tostring(v) end
    end
    return out
end

local function sd201_init_paths()
    startup.self_diag.ensure_dir()
    local run=startup.self_diag.safe_filename(tostring(sd195.runId or "Self_Diagnosis"))
    if run=="" then run="Self_Diagnosis" end
    local base=startup.self_diag_dir.."\\"..run
    sd201.artifacts={
        questionnaire=base.."_Questionnaire_Answers.json",
        settings=base.."_Diagnostic_Settings.json",
        hosts=base.."_Host_Results.csv",
        joins=base.."_Join_Results.csv",
        attempts=base.."_Join_Attempts.csv",
        timeline=base.."_Player_Session_Timeline.csv",
        causes=base.."_Cause_Scores.csv",
        full=base.."_Full_Diagnostic.json",
        manifest=base.."_Diagnostic_Manifest.txt",
    }
    startup.s.selfDiagLastQuestionnairePath=sd201.artifacts.questionnaire
    startup.s.selfDiagLastSettingsPath=sd201.artifacts.settings
    startup.s.selfDiagLastHostResultsPath=sd201.artifacts.hosts
    startup.s.selfDiagLastJoinResultsPath=sd201.artifacts.joins
    startup.s.selfDiagLastJoinAttemptsPath=sd201.artifacts.attempts
    startup.s.selfDiagLastTimelinePath=sd201.artifacts.timeline
    startup.s.selfDiagLastCauseScoresPath=sd201.artifacts.causes
    startup.s.selfDiagLastFullJsonPath=sd201.artifacts.full
    startup.s.selfDiagLastManifestPath=sd201.artifacts.manifest
    if not startup.support_file_exists(sd201.artifacts.timeline) then
        sd201_write(sd201.artifacts.timeline,"epoch,elapsed_ms,phase,plan_pos,label,event,player_id,player_name,rockstar_id,connection_type,ip,country,region,city,isp,session_host,session_players")
    end
end

