local function sd201_write_questionnaire()
    if not sd201.artifacts.questionnaire then sd201_init_paths() end
    local answers=sd201_answers_table(); local rows={}
    for _,qq in ipairs(Q or {}) do rows[#rows+1]={id=qq.id,category=qq.cat,question=qq.text,answer=answers[qq.id] or nil} end
    return sd201_write(sd201.artifacts.questionnaire,sd201_json_encode({schema=1,runId=sd195.runId,savedAt=os.date("%Y-%m-%d %H:%M:%S"),answered=sd191_answer_count(),total=#(Q or {}),answers=answers,questions=rows}).."\n")
end

local function sd201_write_settings()
    if not sd201.artifacts.settings then sd201_init_paths() end
    return sd201_write(sd201.artifacts.settings,sd201_json_encode(sd201_runtime_settings()).."\n")
end

local function sd201_record_row(r,spec)
    return {
        planPos=spec and spec._planPos or nil,label=spec and spec.label or r.label,kind=r.kind,index=r.index,advertiser=r.advertiser,
        loaded=r.loaded,completedWindow=r.completedWindow,failed=r.failed,failReason=r.failReason,kickDetected=r.kickDetected,kickReason=r.kickReason,
        startedAtMs=r.startedAtMs,finishedAtMs=r.finishedAtMs,durationMs=r.durationMs,startPlayers=r.startPlayers,endPlayers=r.endPlayers,peakPlayers=r.peakPlayers,minPlayers=r.minPlayers,
        joinEvents=r.joinEvents,leaveEvents=r.leaveEvents,uniqueJoins=r.uniqueJoins,joins1m=r.joins1m,joins4m=r.joins4m,joins10m=r.joins10m,
        direct=r.direct,peerRelay=r.peerRelay,relayServer=r.relayServer,unknown=r.unknown,directRatio=r.directRatio,
        firstHost=r.firstHost,firstHostId=r.firstHostId,firstHostRid=r.firstHostRid,firstHostKey=r.firstHostKey,isLocalHost=r.isLocalHost,hostChanges=r.hostChanges,duplicateHost=r.duplicateHost,
        milestones=r.milestones,joinTimes=r.joinTimes,peerTypes=r.peerTypes,uniqueJoinKeys=r.uniqueJoinKeys,
    }
end

local function sd201_collect_records(kind)
    local out={}
    for i,spec in ipairs(sd195.testPlan or {}) do
        local r=sd195.testRecords and sd195.testRecords[i] or nil
        if r and (not kind or r.kind==kind) then local row=sd201_record_row(r,spec); row.planPos=i; out[#out+1]=row end
    end
    return out
end

local function sd201_write_result_csv(kind,path)
    local cols={"plan_pos","label","kind","advertiser","loaded","completed","failed","failure","start_players","end_players","peak_players","min_players","join_callbacks","unique_incoming","leaves","joins_1m","joins_4m","joins_10m","duration_ms","host","host_rid","host_key","local_host","host_changes","direct","peer_relay","relay_server","unknown","direct_ratio","kick_detected","kick_reason","duplicate_host"}
    local lines={table.concat(cols,",")}
    for i,spec in ipairs(sd195.testPlan or {}) do
        local r=sd195.testRecords and sd195.testRecords[i] or nil
        if r and r.kind==kind then
            local vals={i,spec.label,r.kind,r.advertiser,r.loaded,r.completedWindow,r.failed,r.failReason,r.startPlayers,r.endPlayers,r.peakPlayers,r.minPlayers,r.joinEvents,r.uniqueJoins,r.leaveEvents,r.joins1m,r.joins4m,r.joins10m,r.durationMs,r.firstHost,r.firstHostRid,r.firstHostKey,r.isLocalHost,r.hostChanges,r.direct,r.peerRelay,r.relayServer,r.unknown,r.directRatio,r.kickDetected,r.kickReason,r.duplicateHost}
            for j,v in ipairs(vals) do vals[j]=sd201_csv(v) end; lines[#lines+1]=table.concat(vals,",")
        end
    end
    return sd201_write(path,table.concat(lines,"\n").."\n")
end

local function sd201_write_attempts()
    local path=sd201.artifacts.attempts; local lines={"attempt,label,kind,host,host_rid,host_key,start_players,peak_players,end_players,duration_ms,failed,failure,kick_detected,kick_reason,direct,peer_relay,relay_server,direct_ratio,duplicate_host"}
    for i,r in ipairs(sd195.joinAttempts or {}) do
        local vals={i,r.label,r.kind,r.firstHost,r.firstHostRid,r.firstHostKey,r.startPlayers,r.peakPlayers,r.endPlayers,r.durationMs,r.failed,r.failReason,r.kickDetected,r.kickReason,r.direct,r.peerRelay,r.relayServer,r.directRatio,r.duplicateHost}
        for j,v in ipairs(vals) do vals[j]=sd201_csv(v) end; lines[#lines+1]=table.concat(vals,",")
    end
    return sd201_write(path,table.concat(lines,"\n").."\n")
end

local function sd201_cause_data()
    local c=sd191 and sd191.results191 and sd191.results191.lastConclusion or nil
    if not c then return {},{} end
    local spec=c.specific198
    if not spec and startup.self_diag.evaluate_specific_causes_198 then local ok,res=direct_call(startup.self_diag.evaluate_specific_causes_198,c); if ok then spec=res end end
    return spec and spec.top or {},spec and spec.all or {}
end

local function sd201_write_causes()
    local top,all=sd201_cause_data(); local rows=(#all>0 and all or top); local lines={"rank,id,category,title,raw_score,likelihood,evidence_count,description,fix"}
    for i,item in ipairs(rows or {}) do
        local ev=item.evidence or {}; local vals={i,item.id,item.category,item.title,item.score,item.likelihood,#ev,item.description,item.fix}
        for j,v in ipairs(vals) do vals[j]=sd201_csv(v) end; lines[#lines+1]=table.concat(vals,",")
    end
    return sd201_write(sd201.artifacts.causes,table.concat(lines,"\n").."\n")
end

local function sd201_full_payload(reason)
    local top,all=sd201_cause_data(); local syn=nil; if sd195.active~=true and startup.self_diag.synthesize then local ok,res=direct_call(startup.self_diag.synthesize); if ok then syn=res end end
    return {
        schema="Startup Self Diagnosis Full Diagnostic v1",
        runId=sd195.runId,build=startup.build_number,savedAt=os.date("%Y-%m-%d %H:%M:%S"),reason=reason,
        active=sd195.active,phase=sd195.phase,status=sd195.status,testPlanPos=sd195.testPlanPos,
        preflight=sd195.preflight,network=sd195.network,account=sd195.account,accountCheckpoints=sd195.accountCheckpoints,
