local function sd201_write_manifest(reason)
    local a=sd201.artifacts; local lines={
        "Startup Self Diagnosis - Diagnostic Manifest",
        "Run: "..tostring(sd195.runId),"Build: "..tostring(startup.build_number),"Saved: "..os.date("%Y-%m-%d %H:%M:%S"),"Reason: "..tostring(reason or "checkpoint"),"",
        "External diagnostic files:",
        "Questionnaire answers: "..tostring(a.questionnaire or ""),
