end

local function sd201_persist(reason)
    if tostring(sd195.runId or "")=="" then return false end
    if not sd201.artifacts.full then sd201_init_paths() end
    local ok1=sd201_write_questionnaire(); local ok2=sd201_write_settings()
    local ok3=sd201_write_result_csv("HOST",sd201.artifacts.hosts); local ok4=sd201_write_result_csv("JOIN",sd201.artifacts.joins); local ok5=sd201_write_attempts()
    local ok6=sd201_write_causes(); local ok7=sd201_write(sd201.artifacts.full,sd201_json_encode(sd201_full_payload(reason)).."\n"); local ok8=sd201_write_manifest(reason)
    startup.self_diag.log("PERSIST_ARTIFACTS","reason="..tostring(reason).." questionnaire="..tostring(ok1).." settings="..tostring(ok2).." hosts="..tostring(ok3).." joins="..tostring(ok4).." attempts="..tostring(ok5).." causes="..tostring(ok6).." full="..tostring(ok7).." manifest="..tostring(ok8))
    return ok1 and ok2 and ok3 and ok4 and ok5 and ok7 and ok8
end
startup.self_diag.persist_artifacts_201=sd201_persist

local function sd201_player_info(playerId)
    local out={id=tonumber(playerId) or -1,name=startup.get_player_name_safe and startup.get_player_name_safe(playerId) or tostring(playerId),rid=0,connection=startup.self_diag.net_type_name and startup.self_diag.net_type_name(playerId) or "UNKNOWN",ip="",country="",region="",city="",isp=""}
    local rid=sd188_host_rid and sd188_host_rid(playerId) or nil; if rid then out.rid=rid end
    if Players and Players.GetIPString then local ok,v=direct_call(Players.GetIPString,playerId); if ok then out.ip=tostring(v or "") end end
    if Players and Players.GetIPInfo then local ok,info=direct_call(Players.GetIPInfo,playerId); if ok and type(info)=="table" then
        local function pick(...) for i=1,select('#',...) do local k=select(i,...); if info[k]~=nil and tostring(info[k])~="" then return tostring(info[k]) end end; return "" end
        out.country=pick("Country","country","country_name","CountryName"); out.region=pick("Region","region","regionName","RegionName"); out.city=pick("City","city"); out.isp=pick("ISP","isp","Org","org","Organization")
    end end
    return out
end

local function sd201_timeline_event(eventName,playerId)
    if sd195.active~=true or tostring(sd195.runId or "")=="" then return end
    if not sd201.artifacts.timeline then sd201_init_paths() end
    local p=sd201_player_info(playerId); local hostName="Unknown"; local _,hid=sd188_current_host_identity(); if hid and hid>=0 then hostName=startup.get_player_name_safe and startup.get_player_name_safe(hid) or tostring(hid) end
    local spec=sd195.testPlan and sd195.testPlan[tonumber(sd195.testPlanPos or 0) or 0] or nil
    local vals={os.time(),math.max(0,startup.now()-(tonumber(sd195.startedAtMs or startup.now()) or startup.now())),sd195.phase,sd195.testPlanPos,spec and spec.label or "",eventName,p.id,p.name,p.rid,p.connection,p.ip,p.country,p.region,p.city,p.isp,hostName,startup.get_session_player_count()}
    for i,v in ipairs(vals) do vals[i]=sd201_csv(v) end; sd201_append(sd201.artifacts.timeline,table.concat(vals,","))
end

