startup.SelfDiagQuestionnaireTestPreset=startup.self_diag_dir.."\\Questionnaire_Test_Preset.json"
function startup.self_diag.save_questionnaire_test_preset()
    local answers=sd201_answers_table(); local count=0; for _ in pairs(answers) do count=count+1 end
    if count~=#(Q or {}) then startup.toast("Complete all questionnaire answers before saving a local test preset.",4500); return false end
    startup.self_diag.ensure_dir(); local ok=sd201_write(startup.SelfDiagQuestionnaireTestPreset,sd201_json_encode({schema=1,questionnaireCount=#(Q or {}),savedAt=os.date("%Y-%m-%d %H:%M:%S"),answers=answers}).."\n")
    startup.toast(ok and "Local questionnaire test preset saved." or "Could not save local questionnaire test preset.",4000); return ok
end
function startup.self_diag.load_questionnaire_test_preset()
    local f=io.open(startup.SelfDiagQuestionnaireTestPreset,"r"); if not f then return false end; local txt=f:read("*a") or ""; f:close()
    local parsed={}; for id,val in txt:gmatch('"([^"\\]+)"%s*:%s*"(yes|no|unsure)"') do parsed[id]=val end
    local valid=0; for _,qq in ipairs(Q or {}) do if parsed[qq.id] then sd191.questionnaire.answers[qq.id]=parsed[qq.id]; valid=valid+1 end end
    if valid==#(Q or {}) then sd191.questionnaire.completed=true; sd191.questionnaire.completedAt=os.time(); startup.toast("Loaded local questionnaire test preset: "..tostring(valid).."/"..tostring(#Q).." answers.",4000); return true end
    startup.toast("Local test preset is incomplete/outdated: "..tostring(valid).."/"..tostring(#Q).." matching answers.",5000); return false
end

function startup.self_diag.reopen_questionnaire_from_preset_panel()
    if not sd191 or not sd191.questionnaire then startup.toast("Questionnaire state is unavailable.",3500); return false end
    if sd195 and sd195.abortForceState then startup.toast("Questionnaire cannot reopen while Self Diagnosis is stopping/recovering.",4000); return false end
    sd191.questionnaire.open=true
    sd191.results191.open=false
