    if GUI and GUI.IsOpen and GUI.Toggle then local ok,v=direct_call(GUI.IsOpen); if ok and v~=true then direct_call(GUI.Toggle) end end
    startup.self_diag.log("QUESTIONNAIRE_REOPEN_FROM_PRESET_PANEL","answered="..tostring(sd191_answer_count()).."/"..tostring(#(Q or {})).." page="..tostring(sd191.questionnaire.page or 1).." active="..tostring(sd195 and sd195.active==true))
    return true
end

-- Independent Stop/Return state machine. This does not depend on the active diagnostic
-- phase, checkpoint phase restoration, or questionnaire state, so a stalled run cannot
-- trap the user on "Stopping test...".
local sd201_prev_request_abort=startup.self_diag.request_abort
function startup.self_diag.request_abort(reason)
    if sd195.active~=true then return sd201_prev_request_abort and sd201_prev_request_abort(reason) or false end
    sd195.abortReason=tostring(reason or "user stop")
    sd195.abortRequested=false
    sd195.abortForceState="ROUTE"
    sd195.abortForceAttempts=0
    sd195.abortForceAtMs=startup.now()
    sd195.status="Stopping test and returning to a fresh host..."
    if sd195_hide_questionnaire then sd195_hide_questionnaire("forced stop") end
    if startup.s.superAdvertiseRunning==true and startup.stop_super_advertise then direct_call(startup.stop_super_advertise,"Self Diagnosis stopped") end
    startup.self_diag.log("ABORT_FORCE_REQUESTED",sd195.abortReason)
    sd201_persist("ABORT_REQUESTED")
    return true
end

local function sd201_abort_tick(now)
    local state=sd195.abortForceState; if not state then return false end
    if state=="ROUTE" then
        sd195.abortForceAttempts=(tonumber(sd195.abortForceAttempts or 0) or 0)+1
        startup.self_diag.log("ABORT_FORCE_ROUTE","attempt="..tostring(sd195.abortForceAttempts))
        startup.self_diag.set_advertising_for_test("HOST")
        local ok,err=startup.self_diag.set_session_type_exact("New Public Session")
        if ok then sd195.abortForceState="CLICK"; sd195.abortForceAtMs=now+750; sd195.status="Stopping test: fresh host route selected..."
        elseif sd195.abortForceAttempts<5 then sd195.abortForceAtMs=now+1000
        else startup.self_diag.log("ABORT_FORCE_ROUTE_FAILED",tostring(err)); sd195.abortForceState="FINISH"; sd195.abortForceAtMs=now end
        return true
    end
    if state=="CLICK" then
        if now<tonumber(sd195.abortForceAtMs or 0) then return true end
        local ok=startup.click_start_session_feature(); startup.self_diag.log("ABORT_FORCE_CLICK","ok="..tostring(ok))
        if ok then sd195.abortForceState="WAIT_HOST"; sd195.abortForceAtMs=now; sd195.sessionRequestAtMs=now; sd195.status="Stopping test: creating fresh New Public Session..."
        elseif sd195.abortForceAttempts<5 then sd195.abortForceState="ROUTE"; sd195.abortForceAtMs=now+1000 else sd195.abortForceState="FINISH"; sd195.abortForceAtMs=now end
        return true
    end
    if state=="WAIT_HOST" then
        local elapsed=now-(tonumber(sd195.sessionRequestAtMs or now) or now)
        local ready=false; if sd188_is_current_target_ready then local ok=sd188_is_current_target_ready({kind="HOST"}); ready=ok==true end
        if ready and elapsed>=2500 then sd195.abortForceState="SETTLE"; sd195.abortForceAtMs=now+3000; sd195.status="Stopping test: fresh host confirmed. Saving partial results..."; startup.self_diag.log("ABORT_FORCE_HOST_CONFIRMED","elapsedMs="..tostring(elapsed)); return true end
        if elapsed>=30000 then
            if sd195.abortForceAttempts<5 then sd195.abortForceState="ROUTE"; sd195.abortForceAtMs=now+1000; startup.self_diag.log("ABORT_FORCE_RETRY","fresh local host not confirmed") else sd195.abortForceState="FINISH"; sd195.abortForceAtMs=now end
        end
        return true
    end
    if state=="SETTLE" then
        if now<tonumber(sd195.abortForceAtMs or 0) then return true end
        sd201_persist("ABORT_FRESH_HOST_CONFIRMED")
        sd195.abortForceState="FINISH"; sd195.abortForceAtMs=now; return true
    end
    if state=="FINISH" then
        sd195.abortForceState=nil
        startup.self_diag.finish("Stopped early: "..tostring(sd195.abortReason or "user stop"))
        return true
    end
    return false
end

local sd201_prev_tick=startup.self_diag.tick
function startup.self_diag.tick()
    if sd195.active==true and sd195.abortForceState then if sd201_abort_tick(startup.now()) then return end end
    return sd201_prev_tick()
end

local sd201_prev_finish=startup.self_diag.finish
function startup.self_diag.finish(reason)
    if tostring(sd195.runId or "")~="" then sd201_persist("PRE_FINISH_"..tostring(reason or "Completed")) end
    sd201_prev_finish(reason)
    if tostring(sd195.runId or "")~="" then sd201_persist("FINAL_"..tostring(reason or "Completed")) end
end

-- Ensure every diagnostic-specific external artifact is embedded in the automatic
-- Support/Self-Diagnosis ZIP, while the opt-in local test preset stays private/local.
local sd201_prev_collect_support_files=startup.collect_support_files
function startup.collect_support_files()
    local found=sd201_prev_collect_support_files() or {}; local seen={}
    for _,e in ipairs(found) do seen[tostring(e.path or ""):gsub("/","\\"):lower()]=true end
    local function add(path)
        path=tostring(path or ""); if path=="" or not startup.support_file_exists(path) then return end
        local key=path:gsub("/","\\"):lower(); if seen[key] then return end; seen[key]=true
        found[#found+1]={path=path,name="Startup/Diagnostics/SelfDiagnostics/"..startup.support_basename(path)}
    end
    for _,path in pairs(sd201.artifacts or {}) do add(path) end
    for _,cp in ipairs(sd195.accountCheckpoints or {}) do add(cp.path) end
    table.sort(found,function(a,b) return tostring(a.name):lower()<tostring(b.name):lower() end)
    return found
end

