    local answerCount=sd191_answer_count()
    startup.render_color_button("OPEN / REOPEN QUESTIONNAIRE","Blue","Reopens the questionnaire without clearing answers or changing the current page. Safe for reviewing or continuing a questionnaire you closed.",startup.self_diag.reopen_questionnaire_from_preset_panel,-1,34)
    startup.subtle_text_wrapped("Current answers: "..tostring(answerCount).." / "..tostring(#(Q or {}))..". Reopening preserves all answers and your current questionnaire section.")
    if answerCount==#(Q or {}) then
        startup.render_color_button("SAVE CURRENT ANSWERS AS LOCAL TEST PRESET","Gold","Writes the 94 current answers to Questionnaire_Test_Preset.json for repeated local testing.",startup.self_diag.save_questionnaire_test_preset,-1,34)
    end
    if presetExists then
        startup.render_color_button("LOAD LOCAL TEST PRESET","Purple","Loads the local 94-answer test preset into the questionnaire. Do not distribute the preset with public Startup packages.",startup.self_diag.load_questionnaire_test_preset,-1,34)
        startup.subtle_text_wrapped("Preset: "..tostring(startup.SelfDiagQuestionnaireTestPreset))
    else startup.subtle_text("No local test preset found. Normal users must answer every question manually.") end
    ClickGUI.EndCustomChildWindow()
end

startup.self_diag.log("BUILD201_OVERRIDES_READY","external questionnaire/settings/HOST/JOIN/attempt/timeline/cause/full JSON artifacts + automatic ZIP inclusion + independent forced Stop->New Public Session recovery state machine + optional private local questionnaire test preset")

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 202: HARD 10-MINUTE HOST LOCK / DIAGNOSTIC SESSION QUARANTINE
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.build_number = "2026.08.07.202"
sd195.hardHostTimingGuard = sd195.hardHostTimingGuard == true
sd195.maxHostAttemptsPerSlot = 3
sd195.hostRetryBySlot = sd195.hostRetryBySlot or {}
sd195.hostAttempts = sd195.hostAttempts or {}
sd195.sessionMutationBlocks = tonumber(sd195.sessionMutationBlocks or 0) or 0
sd195.luaFlowBlocks = tonumber(sd195.luaFlowBlocks or 0) or 0

function startup.self_diag.build202_session_click_allowed()
    if sd195.active~=true or sd195.hardHostTimingGuard~=true then return true end
    if sd195.abortForceState=="CLICK" then return true end
    local phase=tostring(sd195.phase or "")
    return phase=="ALT_CLICK_WAIT" or phase=="RESET_HOST_CLICK" or phase=="FINAL_HOST_CLICK_WAIT" or phase=="HOST_CLICK_WAIT"
end

function startup.self_diag.build202_log_block(kind,detail)
    sd195.sessionMutationBlocks=(tonumber(sd195.sessionMutationBlocks or 0) or 0)+1
    local now=startup.now()
    if now-(tonumber(sd195.lastSessionMutationBlockLogMs or 0) or 0)>=1000 then
        sd195.lastSessionMutationBlockLogMs=now
        startup.self_diag.log("HOST_SESSION_MUTATION_BLOCKED",tostring(kind).." | "..tostring(detail or "").." phase="..tostring(sd195.phase))
    end
end

startup._build202_prev_snapshot_user_settings=startup.self_diag.snapshot_user_settings
function startup.self_diag.snapshot_user_settings()
