    sd195.saved.autoLoadLuaFilesOnSession=startup.s.autoLoadLuaFilesOnSession==true
    sd195.saved.autoRefreshSessionAfterLuaLoad=startup.s.autoRefreshSessionAfterLuaLoad==true
    sd195.saved.sessionLuaLoadCompleted=startup.s.sessionLuaLoadCompleted==true
    sd195.saved.refreshSessionAfterLuaAttempted=startup.s.refreshSessionAfterLuaAttempted==true
end

startup._build202_prev_suspend_normal=startup.self_diag.suspend_normal_automation
function startup.self_diag.suspend_normal_automation()
    if startup._build202_prev_suspend_normal then startup._build202_prev_suspend_normal() end
    sd195.hardHostTimingGuard=true
    startup.s.autoLoadLuaFilesOnSession=false
    startup.s.autoRefreshSessionAfterLuaLoad=false
    startup.s.waitingForRefreshedSession=false
