end

startup._build202_prev_restore_user=startup.self_diag.restore_user_settings
function startup.self_diag.restore_user_settings(preserveActiveSessionType)
    if startup._build202_prev_restore_user then startup._build202_prev_restore_user(preserveActiveSessionType) end
    local s=sd195.saved or {}
    if s.autoLoadLuaFilesOnSession~=nil then startup.s.autoLoadLuaFilesOnSession=s.autoLoadLuaFilesOnSession==true end
    if s.autoRefreshSessionAfterLuaLoad~=nil then startup.s.autoRefreshSessionAfterLuaLoad=s.autoRefreshSessionAfterLuaLoad==true end
    if s.sessionLuaLoadCompleted~=nil then startup.s.sessionLuaLoadCompleted=s.sessionLuaLoadCompleted==true end
    if s.refreshSessionAfterLuaAttempted~=nil then startup.s.refreshSessionAfterLuaAttempted=s.refreshSessionAfterLuaAttempted==true end
    startup.s.waitingForRefreshedSession=false
    startup.s.sessionLuaLoadRunning=false
    startup.s.sessionLuaLoadStartedAtMs=0
