startup._build202_raw_click_start_session=startup.click_start_session_feature
function startup.click_start_session_feature(...)
    if sd195.active==true and sd195.hardHostTimingGuard==true and not startup.self_diag.build202_session_click_allowed() then
        startup.self_diag.build202_log_block("Start Session","non-diagnostic caller denied")
        return false
    end
    return startup._build202_raw_click_start_session(...)
end

startup._build202_raw_start_session=startup.start_session
function startup.start_session(...)
    -- Self Diagnosis itself never uses startup.start_session(); it routes with
    -- set_session_type_exact() and a phase-authorized direct Cherax click. Therefore
    -- every startup.start_session() call during a run is background automation and is
    -- always denied, even if it wakes during the narrow ALT_CLICK_WAIT phase.
    if sd195.active==true and sd195.hardHostTimingGuard==true then
        startup.self_diag.build202_log_block("startup.start_session","background caller denied for entire diagnostic")
        return false
    end
    return startup._build202_raw_start_session(...)
end

startup._build202_raw_apply_session_type=startup.apply_session_type
function startup.apply_session_type(...)
    if sd195.active==true and sd195.hardHostTimingGuard==true then
        startup.self_diag.build202_log_block("Apply Session Type","background route mutation denied")
        return false
    end
    return startup._build202_raw_apply_session_type(...)
end

startup._build202_prev_diag_session_loaded=startup.self_diag.on_session_loaded
function startup.self_diag.on_session_loaded()
    if sd195.active==true and tostring(sd195.phase or "")=="ALT_OBSERVE" then
        local r=sd195.currentRecord
        if r and r.kind=="HOST" and tonumber(r.startedAtMs or 0)>0 then
            startup.self_diag.log("HOST_SESSION_EVENT_IGNORED","elapsedMs="..tostring(math.max(0,startup.now()-r.startedAtMs)).."; 10-minute timer remains authoritative")
            return true
        end
    end
    return startup._build202_prev_diag_session_loaded()
end

function startup.self_diag.build202_append_host_attempt(r,reason)
    if not r then return end
    sd188_finalize_record(r)
    r.finishReason=tostring(reason or "")
    r.failed=true
    if tostring(r.failReason or "")=="" then r.failReason=tostring(reason or "HOST interrupted") end
    r.uniqueJoins=sd195_count_map(r.uniqueJoinKeys)
    sd195.hostAttempts=sd195.hostAttempts or {}
    sd195.hostAttempts[#sd195.hostAttempts+1]=r
end

startup._build202_prev_finish_observation=startup.self_diag.finish_current_observation
function startup.self_diag.finish_current_observation(reason,forceRetryJoin)
    local pos=tonumber(sd195.testPlanPos or 0) or 0
    local spec=sd195.testPlan and sd195.testPlan[pos] or nil
    local r=sd195.currentRecord
    local why=tostring(reason or "")
    if spec and spec.kind=="HOST" and r and why~="10-minute window complete" then
        local slot=tonumber(spec.index or pos) or pos
        sd195.hostRetryBySlot=sd195.hostRetryBySlot or {}
        local attempt=(tonumber(sd195.hostRetryBySlot[slot] or 0) or 0)+1
        sd195.hostRetryBySlot[slot]=attempt
        startup.self_diag.build202_append_host_attempt(r,why)
        startup.self_diag.log("HOST_SAMPLE_INTERRUPTED","slot="..tostring(slot).." attempt="..tostring(attempt).." durationMs="..tostring(r.durationMs or 0).." reason="..why)
        if sd201_persist then sd201_persist("HOST_INTERRUPTED_"..tostring(slot).."_ATTEMPT_"..tostring(attempt)) end
        if attempt < (tonumber(sd195.maxHostAttemptsPerSlot or 3) or 3) then
            if sd195_hide_questionnaire then sd195_hide_questionnaire("HOST interrupted; restarting full 10-minute sample") end
            if startup.s.superAdvertiseRunning==true and startup.stop_super_advertise then direct_call(startup.stop_super_advertise,"HOST sample interrupted; retrying from zero") end
            sd195.currentRecord=nil
            sd195.testRecords[pos]=nil
            sd195.phase="HOST_RETRY_SAME_SLOT"
            sd195.nextActionMs=startup.now()+1500
            sd195.status=spec.label.." interrupted after "..startup.self_diag.format_ms(r.durationMs or 0)..". Restarting SAME 10-minute sample from 0:00..."
            startup.self_diag.log("HOST_SAMPLE_RESTART_SCHEDULED","slot="..tostring(slot).." nextAttempt="..tostring(attempt+1).." fullWindowMs=600000")
            return true
        end
        startup.self_diag.log("HOST_SAMPLE_RETRY_EXHAUSTED","slot="..tostring(slot).." attempts="..tostring(attempt).."; retaining final failed sample and continuing")
        return startup._build202_prev_finish_observation(reason,false)
    end
    local ok=startup._build202_prev_finish_observation(reason,forceRetryJoin)
    if spec and spec.kind=="HOST" and why=="10-minute window complete" then
        local stored=sd195.testRecords and sd195.testRecords[pos] or nil
        if stored then
            stored.completedWindow=true
            startup.self_diag.log("HOST_10MIN_HARD_COMPLETE","slot="..tostring(spec.index or pos).." durationMs="..tostring(stored.durationMs or 0).." uniqueJoins="..tostring(stored.uniqueJoins or 0).." peak="..tostring(stored.peakPlayers or 0))
        end
        if sd201_persist then sd201_persist("HOST_10MIN_HARD_COMPLETE_"..tostring(spec.index or pos)) end
    end
    return ok
end

startup._build202_prev_tick=startup.self_diag.tick
function startup.self_diag.tick()
    if sd195.active==true and not sd195.abortForceState and tostring(sd195.phase or "")=="HOST_RETRY_SAME_SLOT" then
        local now=startup.now()
        if now>=tonumber(sd195.nextActionMs or 0) then
            startup.self_diag.log("HOST_SAMPLE_RESTART_BEGIN","step="..tostring(sd195.testPlanPos).." fullWindowMs=600000")
            startup.self_diag.route_current_test()
        end
        return
    end
    return startup._build202_prev_tick()
end

startup._build202_prev_start=startup.self_diag.start
function startup.self_diag.start()
    local wasActive=sd195.active==true
    local ok=startup._build202_prev_start()
    if ok and not wasActive and sd195.active==true then
        sd195.hostRetryBySlot={}
        sd195.hostAttempts={}
        sd195.sessionMutationBlocks=0
        sd195.luaFlowBlocks=0
        sd195.hardHostTimingGuard=true
        startup.self_diag.log("HOST_10MIN_LOCK_ARMED","Every HOST must complete 600000ms; early interruption restarts same slot")
        if sd201_persist then sd201_persist("BUILD202_HOST_LOCK_ARMED") end
    end
    return ok
end

startup._build202_prev_sd201_init_paths=sd201_init_paths
sd201_init_paths=function()
    startup._build202_prev_sd201_init_paths()
    local run=startup.self_diag.safe_filename(tostring(sd195.runId or "Self_Diagnosis")); if run=="" then run="Self_Diagnosis" end
    local base=startup.self_diag_dir.."\\"..run
    sd201.artifacts.hostAttempts=base.."_Host_Attempts.csv"
