function startup.self_diag.build202_write_host_attempts()
    if not sd201.artifacts.hostAttempts then sd201_init_paths() end
    local lines={"attempt,label,advertiser,start_players,end_players,peak_players,unique_incoming,join_callbacks,duration_ms,reason,host,host_rid,host_key,local_host,host_changes,direct,peer_relay,relay_server"}
    for i,r in ipairs(sd195.hostAttempts or {}) do
        local vals={i,r.label,r.advertiser,r.startPlayers,r.endPlayers,r.peakPlayers,r.uniqueJoins,r.joinEvents,r.durationMs,r.finishReason or r.failReason,r.firstHost,r.firstHostRid,r.firstHostKey,r.isLocalHost,r.hostChanges,r.direct,r.peerRelay,r.relayServer}
        for j,v in ipairs(vals) do vals[j]=sd201_csv(v) end
        lines[#lines+1]=table.concat(vals,",")
    end
    return sd201_write(sd201.artifacts.hostAttempts,table.concat(lines,"\n").."\n")
end

startup._build202_prev_sd201_persist=sd201_persist
