-- Build 203: LIVE DIAGNOSTIC MONITOR / DOWNLOAD-STYLE PROGRESS
-- UI + aggregate persistence only. Build 202 timing/session rules remain authoritative.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.build_number = "2026.08.07.203"
startup.self_diag_live203 = startup.self_diag_live203 or {lastDiskSampleMs=0,lastStatusWriteMs=0}

function startup.self_diag.live203_clamp(v,a,b)
    v=tonumber(v or 0) or 0; a=tonumber(a or 0) or 0; b=tonumber(b or 1) or 1
    if v<a then return a end; if v>b then return b end; return v
end

function startup.self_diag.live203_short_ms(ms)
    local sec,m,s,h
    ms=math.max(0,tonumber(ms or 0) or 0)
    sec=math.floor(ms/1000+0.5); m=math.floor(sec/60); s=sec%60
    if m>=60 then h=math.floor(m/60); m=m%60; return string.format("%d:%02d:%02d",h,m,s) end
    return string.format("%02d:%02d",m,s)
end

function startup.self_diag.live203_short_method(spec,r)
    local m=tostring((r and r.advertiser) or (spec and spec.method) or "")
    if m=="CURRENT" then return "Auto" end
    if m=="OLD_V103" then return "Old" end
    if m=="SUPER" then return "Super" end
    if m=="DYNAMIC_WORST" then return "Worst" end
    if m=="DYNAMIC_BEST" then return "Best" end
    if m=="" then return "None" end
    return m
end

function startup.self_diag.live203_direct_pct(r)
    local direct,total
    if not r then return 0,0 end
    direct=tonumber(r.direct or 0) or 0
    total=direct+(tonumber(r.peerRelay or 0) or 0)+(tonumber(r.relayServer or 0) or 0)+(tonumber(r.unknown or 0) or 0)
    if total<=0 then return 0,0 end
    return math.floor((direct/total)*100+0.5),total
end

function startup.self_diag.live203_host_summary()
    local parts,spec,r,unique,peak,live
    parts={}
    for _,pos in ipairs({1,3,5,7,9}) do
        spec=sd195.testPlan and sd195.testPlan[pos] or nil
        if spec then
            r=(sd195.testRecords and sd195.testRecords[pos]) or ((tonumber(sd195.testPlanPos or 0)==pos) and sd195.currentRecord or nil)
            if r then
                unique=tonumber(r.uniqueJoins or sd195_count_map(r.uniqueJoinKeys)) or 0
                peak=tonumber(r.peakPlayers or 0) or 0
                live=(sd195.active==true and tonumber(sd195.testPlanPos or 0)==pos and sd195.phase=="ALT_OBSERVE")
                parts[#parts+1]=startup.self_diag.live203_short_method(spec,r).." +"..tostring(unique).."/P"..tostring(peak)..(live and "*" or "")
            end
        end
    end
    if #parts==0 then return "No completed HOST data yet" end
    return table.concat(parts,"  |  ")
end

function startup.self_diag.live203_join_summary()
    local parts,spec,r,peak,live
    parts={}
    for _,pos in ipairs({2,4,6,8}) do
        spec=sd195.testPlan and sd195.testPlan[pos] or nil
        if spec then
            r=(sd195.testRecords and sd195.testRecords[pos]) or ((tonumber(sd195.testPlanPos or 0)==pos) and sd195.currentRecord or nil)
            if r then
                peak=tonumber(r.peakPlayers or 0) or 0
                live=(sd195.active==true and tonumber(sd195.testPlanPos or 0)==pos and sd195.phase=="ALT_OBSERVE")
                parts[#parts+1]="J"..tostring(spec.index or "?").." P"..tostring(peak)..(live and "*" or "")
            end
        end
    end
    if #parts==0 then return "No accepted JOIN data yet" end
    return table.concat(parts,"  |  ")
end

function startup.self_diag.live203_state(now)
    local phase,pos,spec,r,p,total,label,overallRemain,overallElapsed,overallDenom,overallProgress
    local sampleElapsed,sampleRemain,sampleWindow,sampleProgress,players,unique,peak,startPlayers,joins,leaves,host,rate,directPct,directN
    local nextSession,joining,nextSpec,qSuffix,live
    now=tonumber(now or startup.now()) or startup.now()
    phase=tostring(sd195.phase or "Idle"); pos=tonumber(sd195.testPlanPos or 0) or 0
    spec=sd195.testPlan and sd195.testPlan[pos] or nil; r=sd195.currentRecord
    p,total,label=sd195_phase_info(); overallRemain=sd195_estimated_remaining_ms(now)
    overallElapsed=math.max(0,now-(tonumber(sd195.startedAtMs or now) or now)); overallDenom=overallElapsed+overallRemain
    overallProgress=overallDenom>0 and startup.self_diag.live203_clamp(overallElapsed/overallDenom,0,1) or 0
    sampleElapsed=0; sampleRemain=0; sampleWindow=0; sampleProgress=0
    if phase=="ALT_OBSERVE" and r and tonumber(r.startedAtMs or 0)>0 then
        sampleWindow=(r.kind=="HOST") and (tonumber(sd195.hostWindowMs or 600000) or 600000) or (tonumber(sd195.joinWindowMs or 300000) or 300000)
        sampleElapsed=math.max(0,now-(tonumber(r.startedAtMs) or now)); sampleRemain=math.max(0,sampleWindow-sampleElapsed)
        sampleProgress=sampleWindow>0 and startup.self_diag.live203_clamp(sampleElapsed/sampleWindow,0,1) or 0
    elseif phase=="RESET_HOST_HOLD" and tonumber(sd195.resetLoadedAtMs or 0)>0 then
        sampleWindow=tonumber(sd195.resetHostWindowMs or 60000) or 60000; sampleElapsed=math.max(0,now-tonumber(sd195.resetLoadedAtMs)); sampleRemain=math.max(0,sampleWindow-sampleElapsed)
        sampleProgress=sampleWindow>0 and startup.self_diag.live203_clamp(sampleElapsed/sampleWindow,0,1) or 0
    elseif tonumber(sd195.nextActionMs or 0)>now then sampleRemain=math.max(0,tonumber(sd195.nextActionMs)-now) end

    players=startup.get_session_player_count(); unique=0; peak=0; startPlayers=0; joins=0; leaves=0; host=""; rate=0; directPct=0; directN=0
    if r then
        unique=tonumber(r.uniqueJoins or sd195_count_map(r.uniqueJoinKeys)) or 0; peak=math.max(tonumber(r.peakPlayers or 0) or 0,players); startPlayers=tonumber(r.startPlayers or 0) or 0
        joins=tonumber(r.joinEvents or 0) or 0; leaves=tonumber(r.leaveEvents or 0) or 0; host=tostring(r.firstHost or "")
        if sampleElapsed>0 and r.kind=="HOST" then rate=unique/(sampleElapsed/60000) end
        directPct,directN=startup.self_diag.live203_direct_pct(r)
    end

    nextSession="Working..."; joining=""
    if sd195.abortForceState then
        nextSession="Returning to fresh HOST | recovery attempt "..tostring(sd195.abortForceAttempt or 1).."/5"; joining="Session hopping paused during Stop recovery"
    elseif phase=="WAIT_QUESTIONNAIRE" then
        nextSession="Session hopping PAUSED until questionnaire is complete"; joining="JOIN #1 begins immediately after questionnaire completion"
    elseif phase=="ALT_OBSERVE" and r then
        nextSpec=sd195.testPlan and sd195.testPlan[pos+1] or nil
        if r.kind=="HOST" then
            nextSession="Time until next session ~"..startup.self_diag.live203_short_ms(sampleRemain)
            if nextSpec and nextSpec.kind=="JOIN" then
                qSuffix=""; if spec and spec.index==1 and sd195.questionnaireAttached~=true then qSuffix=" minimum; questionnaire must also finish" end
                joining="Time until Joining Session ~"..startup.self_diag.live203_short_ms(sampleRemain)..qSuffix
            else joining="After this HOST: final fresh host + results" end
        else
            nextSession="Time until next session ~"..startup.self_diag.live203_short_ms(sampleRemain); joining="JOIN sample active | next HOST in ~"..startup.self_diag.live203_short_ms(sampleRemain)
        end
    elseif phase=="HOST_RETRY_SAME_SLOT" then
        nextSession="Restarting same HOST sample from 10:00 in ~"..startup.self_diag.live203_short_ms(sampleRemain); joining="Interrupted HOST attempt saved; it does not count as a full result"
    elseif phase=="RESET_HOST_HOLD" then
        nextSession="Fresh-host recovery hold ~"..startup.self_diag.live203_short_ms(sampleRemain); joining="JOIN retry after recovery hold"
    elseif phase:find("ALT_WAIT_LOAD",1,true) then
        nextSession="Waiting for requested session to load and host role to verify"; joining=(spec and spec.kind=="JOIN") and "Joining Session: resolving remote host + 15+ players" or "Hosted Session: verifying local Session Host"
    elseif phase:find("ALT_",1,true) or phase:find("FINAL_HOST",1,true) then
        nextSession=tostring(sd195.status or "Preparing next session..."); joining=(spec and spec.kind=="JOIN") and "Joining Session is being prepared" or "Session transition in progress"
    else nextSession=tostring(sd195.status or "Working...") end

    if r and r.kind=="HOST" then
        live=string.format("LIVE HOST | Players %d (%d->%d) | Unique +%d | Peak %d | %.1f joins/min",players,startPlayers,players,unique,peak,rate)
    elseif r and r.kind=="JOIN" then
        live="LIVE JOIN | Players "..tostring(players).." | Host "..tostring(host~="" and host or "Resolving...").." | Peak "..tostring(peak)..(directN>0 and (" | Direct "..tostring(directPct).."%") or "")
    else live="LIVE | Players "..tostring(players).." | Questionnaire "..tostring(sd191_answer_count()).."/"..tostring(#(Q or {})) end

    return {phase=phase,pos=pos,phaseNumber=p,totalPhases=total,label=label,spec=spec,record=r,overallRemainingMs=overallRemain,overallProgress=overallProgress,
        sampleElapsedMs=sampleElapsed,sampleRemainingMs=sampleRemain,sampleWindowMs=sampleWindow,sampleProgress=sampleProgress,players=players,startPlayers=startPlayers,peakPlayers=peak,
        uniqueJoins=unique,joinEvents=joins,leaveEvents=leaves,directPct=directPct,directCount=directN,host=host,rate=rate,nextSession=nextSession,joining=joining,live=live,
        hostSummary=startup.self_diag.live203_host_summary(),joinSummary=startup.self_diag.live203_join_summary(),questionnaireAnswered=sd191_answer_count(),questionnaireTotal=#(Q or {})}
end

function startup.render_self_diag_hud_build191()
    local now,active,resultVisible,c,primary,s,line1,line2,line3,line4,line5
    now=startup.now(); active=sd195.active==true; resultVisible=not active and sd191 and sd191.results191 and tonumber(sd191.results191.hudUntilMs or 0)>now
    if not active and not resultVisible then return end
    if not active then
        c=sd191.results191.lastConclusion or {}; primary=c.primary or {label="No single cause proven"}
        sd191_native_rect(0.5,0.960,0.50,0.066,0,0,0,140)
        sd191_native_text("SELF DIAGNOSIS COMPLETE  |  Confidence "..tostring(c.confidence or 0).."/100",0.5,0.936,0.265,95,255,125,235)
        sd191_native_text("Most likely issue: "..tostring(primary.label or "No single cause proven"),0.5,0.955,0.245,255,255,255,235)
        sd191_native_text(tostring(sd191.results191.autoPackageStatus or "Results saved"),0.5,0.974,0.215,170,205,255,225)
        sd191_native_rect(0.5,0.990,0.40,0.004,80,210,125,230); return
