    line2="Phase "..tostring(s.phaseNumber).." / "..tostring(s.totalPhases).."  |  "..tostring(s.label)
    line3=s.nextSession..(s.joining~="" and ("  |  "..s.joining) or ""); line4=s.live
    line5=(s.record and s.record.kind=="JOIN") and ("JOIN RESULTS | "..s.joinSummary) or ("HOST RESULTS | "..s.hostSummary)
    sd191_native_rect(0.5,0.944,0.62,0.106,0,0,0,150)
    sd191_native_text(line1,0.5,0.902,0.255,95,255,125,240); sd191_native_text(line2,0.5,0.920,0.235,255,255,255,235)
    sd191_native_text(line3,0.5,0.938,0.195,255,215,115,235); sd191_native_text(line4,0.5,0.956,0.205,170,215,255,235); sd191_native_text(line5,0.5,0.974,0.185,205,205,215,225)
    sd191_native_rect(0.5,0.986,0.48,0.004,45,45,50,200); if s.sampleProgress>0 then sd191_native_rect(0.5-0.24+(0.48*s.sampleProgress)/2,0.986,0.48*s.sampleProgress,0.004,100,170,255,235) end
    sd191_native_rect(0.5,0.993,0.48,0.004,45,45,50,200); if s.overallProgress>0 then sd191_native_rect(0.5-0.24+(0.48*s.overallProgress)/2,0.993,0.48*s.overallProgress,0.004,80,210,125,235) end
end

startup._build203_prev_render_panel=startup.render_self_diagnostics_panel
function startup.render_self_diagnostics_panel()
    local s
    startup._build203_prev_render_panel()
