    startup.status_line("Live",s.live,0.55,0.82,1.00); startup.subtle_text_wrapped("HOST results: "..s.hostSummary); startup.subtle_text_wrapped("JOIN results: "..s.joinSummary)
    startup.subtle_text_wrapped("Blue bar = exact current sample. Green bar = estimated whole-run progress. A * marks the currently live result.")
    ClickGUI.EndCustomChildWindow()
