function startup.self_diag.live203_write_files(appendSample,reason)
    local now,s,r,spec,payload,ok,vals
    if tostring(sd195.runId or "")=="" then return false end
    if not sd201.artifacts.liveStatus then sd201_init_paths() end
    now=startup.now(); s=startup.self_diag.live203_state(now); r=s.record; spec=s.spec
    payload={schema="Startup Self Diagnosis Live Status v1",runId=sd195.runId,build=startup.build_number,savedAt=os.date("%Y-%m-%d %H:%M:%S"),reason=tostring(reason or "live"),active=sd195.active,
        phase=s.phase,planPos=s.pos,phaseNumber=s.phaseNumber,totalPhases=s.totalPhases,label=s.label,overallRemainingMs=s.overallRemainingMs,overallProgressPct=math.floor(s.overallProgress*1000+0.5)/10,
        sampleElapsedMs=s.sampleElapsedMs,sampleRemainingMs=s.sampleRemainingMs,sampleWindowMs=s.sampleWindowMs,sampleProgressPct=math.floor(s.sampleProgress*1000+0.5)/10,nextSession=s.nextSession,
        joining=s.joining,live=s.live,hostSummary=s.hostSummary,joinSummary=s.joinSummary,players=s.players,startPlayers=s.startPlayers,peakPlayers=s.peakPlayers,uniqueJoins=s.uniqueJoins,
        joinEvents=s.joinEvents,leaveEvents=s.leaveEvents,directPct=s.directPct,host=s.host,questionnaireAnswered=s.questionnaireAnswered,questionnaireTotal=s.questionnaireTotal}
    ok=sd201_write(sd201.artifacts.liveStatus,sd201_json_encode(payload).."\n")
    if appendSample then
        vals={os.time(),math.max(0,now-(tonumber(sd195.startedAtMs or now) or now)),s.phase,s.pos,s.label,r and r.kind or "",startup.self_diag.live203_short_method(spec,r),s.sampleElapsedMs,s.sampleRemainingMs,math.floor(s.sampleProgress*1000+0.5)/10,
            s.overallRemainingMs,math.floor(s.overallProgress*1000+0.5)/10,s.players,s.startPlayers,s.peakPlayers,s.uniqueJoins,s.joinEvents,s.leaveEvents,s.directPct,s.host,r and r.hostChanges or 0,s.questionnaireAnswered,s.questionnaireTotal}
        for i,v in ipairs(vals) do vals[i]=sd201_csv(v) end; sd201_append(sd201.artifacts.liveSamples,table.concat(vals,","))
    end
    return ok
end

