-- Build 204: TIMING ETA + 100-MINUTE RUN SAFETY BUDGET
-- Presentation / time-budget refinement only. Build 202 hard HOST timing remains:
--   HOST = 600000 ms (10:00), JOIN = 300000 ms (5:00).
-- Build 204 makes the three clocks explicit and raises the whole diagnostic safety
-- budget from 90:00 to 100:00 so retries/recovery have a little more truthful room.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.build_number = "2026.08.07.204"
sd195.maxRuntimeMs = 6000000
sd195.hardCapMs = 6000000
startup.self_diag_live204 = startup.self_diag_live204 or {runHardCapMs=6000000}

-- Replace Build 195's fixed-90-minute ETA clamp with the active hard-cap value.
-- The estimate is intentionally allowed to move upward after a retry/recovery because
-- a restarted 10-minute HOST really does add time to the remaining work.
sd195_estimated_remaining_ms = function(now)
    now=tonumber(now or startup.now()) or startup.now()
    if not sd195.active then return 0 end
    local pos=tonumber(sd195.testPlanPos or 0) or 0
    local rem=0
    local phase=tostring(sd195.phase or "")
    local plan=sd195.testPlan or {}
    for i=math.max(1,pos+1),#plan do
        local sp=plan[i]
        if sp then rem=rem+(sp.kind=="HOST" and (tonumber(sd195.hostWindowMs or 600000) or 600000) or (tonumber(sd195.joinWindowMs or 300000) or 300000))+12000 end
    end
    local r=sd195.currentRecord
    local spec=plan[math.max(1,pos)]
    if phase=="WAIT_QUESTIONNAIRE" then
        -- Questionnaire completion is user-paced. Keep the machine-work estimate but
        -- let the HUD mark it as a minimum rather than inventing a completion time.
        rem=rem+5000
    elseif phase=="ALT_OBSERVE" and r and spec and tonumber(r.startedAtMs or 0)>0 then
        local win=spec.kind=="HOST" and (tonumber(sd195.hostWindowMs or 600000) or 600000) or (tonumber(sd195.joinWindowMs or 300000) or 300000)
        rem=rem+math.max(0,(tonumber(r.startedAtMs)+win)-now)+12000
    elseif pos>=1 and spec then
        rem=rem+(spec.kind=="HOST" and (tonumber(sd195.hostWindowMs or 600000) or 600000) or (tonumber(sd195.joinWindowMs or 300000) or 300000))+12000
    else
        rem=rem+20000
    end
    if phase=="RESET_HOST_HOLD" and tonumber(sd195.resetLoadedAtMs or 0)>0 then
        rem=rem+math.max(0,(tonumber(sd195.resetHostWindowMs or 60000) or 60000)-(now-tonumber(sd195.resetLoadedAtMs)))
    end
    local hardCap=tonumber(sd195.hardCapMs or 6000000) or 6000000
    local started=tonumber(sd195.startedAtMs or now) or now
    local hardRemain=math.max(0,(started+hardCap)-now)
    return math.max(0,math.min(rem,hardRemain))
end

startup._build204_prev_live_state=startup.self_diag.live203_state
function startup.self_diag.live203_state(now)
    local s=startup._build204_prev_live_state(now)
    now=tonumber(now or startup.now()) or startup.now()
    local r=s.record
    local kind=r and tostring(r.kind or "") or ""
    local limit=tonumber(s.sampleWindowMs or 0) or 0
    local elapsed=tonumber(s.sampleElapsedMs or 0) or 0
    local remaining=tonumber(s.sampleRemainingMs or 0) or 0
    if limit<=0 and kind=="HOST" then limit=tonumber(sd195.hostWindowMs or 600000) or 600000 end
    if limit<=0 and kind=="JOIN" then limit=tonumber(sd195.joinWindowMs or 300000) or 300000 end
    s.currentSessionLimitMs=limit
    s.currentSessionElapsedMs=elapsed
    s.currentSessionRemainingMs=remaining
    s.runHardCapMs=tonumber(sd195.hardCapMs or 6000000) or 6000000
    s.runHardCapRemainingMs=math.max(0,(tonumber(sd195.startedAtMs or now) or now)+s.runHardCapMs-now)
    s.etaQualifier=(tostring(sd195.phase or "")=="WAIT_QUESTIONNAIRE" or (sd195.questionnaireAttached~=true and s.pos==1)) and " minimum" or ""
    s.timeRemainingLine="Time Remaining: ~"..startup.self_diag.live203_short_ms(s.overallRemainingMs)..s.etaQualifier
    if limit>0 and tostring(sd195.phase or "")=="ALT_OBSERVE" then
        s.currentSessionLine="Current Session Remaining: "..startup.self_diag.live203_short_ms(remaining).."  |  Elapsed "..startup.self_diag.live203_short_ms(elapsed).." / "..startup.self_diag.live203_short_ms(limit)
    else
        s.currentSessionLine="Current Session: transition / verification in progress"
    end
    return s
end

