-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 214: PHASE 3.1 BROWSER SAFETY + SAME-SESSION HOST-MEDIATED VOTING
-- - Verified Startup peers are exempt from Startup automatic removal paths.
-- - Repeated kick attempts from a verified peer may receive one reactive Host Kick
--   only when the local user is Session Host and the attacker is not Session Host.
-- - Crash evidence remains visible/history-capable, but automatic removal is suppressed.
-- - Browser removal votes are accepted server-side only when BOTH voter and target are
--   present in the current host's fresh roster snapshot for that exact GTA session.
-- - Votes never kick automatically. The Session Host must explicitly choose HOST KICK.
-- - Prime / Standard / Premium is never exposed in the public Browser UI.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.build_number = "2026.08.09.217"
startup.build_date = "2026-08-09"

function startup.install_browser_safety_build217()
startup.browser_safety = startup.browser_safety or {}
local bs214 = startup.browser_safety
bs214.reactive_kick_cooldown = bs214.reactive_kick_cooldown or {}
bs214.suppression_log_cooldown = bs214.suppression_log_cooldown or {}

function bs214.is_manual_exception(sourceLabel)
    local s = tostring(sourceLabel or "")
    return s:find("Browser Vote Host Decision",1,true) ~= nil
        or s:find("Verified Peer Reactive Kick",1,true) ~= nil
end

function bs214.is_verified_peer(playerId)
    local pid=tonumber(playerId)
    if pid==nil or pid<0 or pid>31 or (startup.is_local_player_id and startup.is_local_player_id(pid)) then return false end
    if startup.presence then
        local direct=startup.presence.verified_by_player and startup.presence.verified_by_player[pid] or nil
        if direct then return true end
        local rid=0
        if startup.presence.get_player_rid then
            local ok,v=direct_call(startup.presence.get_player_rid,pid)
            if ok then rid=tonumber(v or 0) or 0 end
        end
        if rid>0 and startup.presence.verified_by_rid and startup.presence.verified_by_rid[tostring(math.floor(rid))] then return true end
    end
    local bb=startup.browser_backend
    local now=startup.now and startup.now() or 0
    if bb and bb.verified_by_player then
        local row=bb.verified_by_player[pid]
        if row and now <= (tonumber(row.expires_ms or 0) or 0) then return true end
        if row then bb.verified_by_player[pid]=nil end
    end
    if bb and bb.browser_verified_by_rid and startup.presence and startup.presence.get_player_rid then
        local ok,v=direct_call(startup.presence.get_player_rid,pid)
        local rid=ok and tonumber(v or 0) or 0
        local key=rid>0 and tostring(math.floor(rid)) or ""
        local row=key~="" and bb.browser_verified_by_rid[key] or nil
        if row and now <= (tonumber(row.expires_ms or 0) or 0) then return true end
        if row and key~="" then bb.browser_verified_by_rid[key]=nil end
    end
    return false
end

function bs214.note_suppressed(playerId, action, sourceLabel)
    local pid=tonumber(playerId) or -1
    local key=tostring(pid).."|"..tostring(action or "action")
    local now=startup.now and startup.now() or 0
    local last=tonumber(bs214.suppression_log_cooldown[key] or 0) or 0
    if now-last<5000 then return end
    bs214.suppression_log_cooldown[key]=now
    local name=startup.get_player_name_safe and startup.get_player_name_safe(pid) or ("Player "..tostring(pid))
    if startup.log then startup.log("[Browser Safety] Suppressed automatic "..tostring(action).." against verified Startup peer "..tostring(name).." | source="..tostring(sourceLabel or "unknown")) end
    if startup.support_log_event_quiet then startup.support_log_event_quiet("VERIFIED_PEER_ACTION_SUPPRESSED",
        "player="..tostring(name).." ["..tostring(pid).."] action="..tostring(action).." source="..tostring(sourceLabel or "unknown")) end
end

function bs214.should_suppress(playerId, action, sourceLabel)
    if bs214.is_manual_exception(sourceLabel) then return false end
    if bs214.is_verified_peer(playerId) then
        bs214.note_suppressed(playerId,action,sourceLabel)
        return true
    end
    return false
end

-- Wrap the major Startup removal paths. Existing Self Diagnostics wrappers remain below
-- these calls in the chain and still take precedence whenever diagnostics are active.
if startup.nuke_join_kick and startup.nuke_join_kick.run_for_player_id and not bs214._wrapped_nuke_id then
    bs214._wrapped_nuke_id=true
    local old=startup.nuke_join_kick.run_for_player_id
    startup.nuke_join_kick.run_for_player_id=function(playerId,forceRun,sourceLabel,useHostKickFallback)
        if bs214.should_suppress(playerId,"Block Join & Kick",sourceLabel) then return false end
        return old(playerId,forceRun,sourceLabel,useHostKickFallback)
    end
end
if startup.nuke_join_kick and startup.nuke_join_kick.run and not bs214._wrapped_nuke_feature then
    bs214._wrapped_nuke_feature=true
    local old=startup.nuke_join_kick.run
    startup.nuke_join_kick.run=function(feature)
        local pid=startup.nuke_join_kick.resolve_player_index and startup.nuke_join_kick.resolve_player_index(feature) or nil
        if pid~=nil and bs214.should_suppress(pid,"Manual Startup Nuke","Manual Startup Nuke") then
            if startup.toast then startup.toast("Startup refused to Nuke a verified Startup peer.",4000) end
            return false
        end
        return old(feature)
    end
end
if startup.host_kick_bypass and startup.host_kick_bypass.run_for_player_id and not bs214._wrapped_hostkick_id then
    bs214._wrapped_hostkick_id=true
    local old=startup.host_kick_bypass.run_for_player_id
    startup.host_kick_bypass.run_for_player_id=function(playerId,sourceLabel)
        if bs214.should_suppress(playerId,"Host Kick",sourceLabel) then return false end
        return old(playerId,sourceLabel)
    end
end
if startup.host_kick_bypass and startup.host_kick_bypass.run and not bs214._wrapped_hostkick_feature then
    bs214._wrapped_hostkick_feature=true
    local old=startup.host_kick_bypass.run
    startup.host_kick_bypass.run=function(feature)
        local pid=startup.host_kick_bypass.resolve_player_index and startup.host_kick_bypass.resolve_player_index(feature) or nil
        if pid~=nil and bs214.should_suppress(pid,"Manual Startup Host Kick","Manual Startup Host Kick") then
            if startup.toast then startup.toast("Startup refused to Host Kick a verified Startup peer without a Browser host decision or reactive kick condition.",4500) end
            return false
        end
        return old(feature)
    end
end
if startup.country_filter and startup.country_filter.kick_player and not bs214._wrapped_country then
    bs214._wrapped_country=true
    local old=startup.country_filter.kick_player
    startup.country_filter.kick_player=function(playerId,playerName,countryLabel,countryCode)
        if bs214.should_suppress(playerId,"Country / Language Smart Kick","Country / Language Filter") then return false end
        return old(playerId,playerName,countryLabel,countryCode)
    end
end

-- Browser v1.4 API helpers.
do
    local bb=startup.browser_backend or {}
    startup.browser_backend=bb
    bb.vote_groups=bb.vote_groups or {}
    bb.vote_status=tostring(bb.vote_status or "Ready")
    bb.vote_target_pid=tonumber(bb.vote_target_pid or -1) or -1
    bb.vote_reason=tostring(bb.vote_reason or "CRASH_ATTEMPTS")
    bb.next_vote_poll_ms=tonumber(bb.next_vote_poll_ms or 0) or 0

    local voteReasons={
        {key="CRASH_ATTEMPTS",label="Crash attempts"},
        {key="KICK_ATTEMPTS",label="Kick attempts"},
        {key="HARASSMENT",label="Harassment / trolling"},
        {key="DISRUPTION",label="Session disruption"},
        {key="OTHER",label="Other"},
    }

    local function nowms() return startup.now and tonumber(startup.now()) or 0 end
    local function post(endpoint,fields)
        if not bb._post or bb.token==nil or bb.token=="" then return false,"BACKEND_NOT_CONNECTED",nil end
        local ok,body=bb._post(endpoint,fields or {},bb.token)
        local data=(ok and bb._json_decode) and bb._json_decode(body) or nil
        if not ok then return false,tostring(body),data end
        if type(data)~="table" or data.ok~=true then
            local err=type(data)=="table" and tostring(data.error or "API_ERROR") or "INVALID_RESPONSE"
            return false,err,data
        end
        return true,nil,data
    end

    local function player_exists(pid)
        pid=tonumber(pid)
        if pid==nil or pid<0 or pid>31 or not (Players and Players.GetById) then return false end
        local ok,obj=direct_call(Players.GetById,pid)
        return ok and obj~=nil
    end

    local function player_rid(pid)
        if startup.presence and startup.presence.get_player_rid then
            local ok,v=direct_call(startup.presence.get_player_rid,pid)
            if ok then return tonumber(v or 0) or 0 end
        end
        return 0
    end

    local function session_host_info()
        if not startup.get_session_host_name then return nil end
        local name,pid=startup.get_session_host_name()
        pid=tonumber(pid)
        if pid==nil or pid<0 or pid>31 then return nil end
        local rid=player_rid(pid)
        if rid<=0 then return nil end
        return {name=tostring(name or startup.get_player_name_safe(pid)),pid=pid,rid=rid}
    end

    local function remote_vote_targets()
        local host=session_host_info()
        local out={}
        for pid=0,31 do
            if player_exists(pid) and not (startup.is_local_player_id and startup.is_local_player_id(pid)) and (not host or pid~=host.pid) then
                local rid=player_rid(pid)
                if rid>0 then out[#out+1]={pid=pid,rid=rid,name=tostring(startup.get_player_name_safe and startup.get_player_name_safe(pid) or ("Player "..pid))} end
            end
        end
        table.sort(out,function(a,b) return tostring(a.name):lower()<tostring(b.name):lower() end)
        return out
    end

    function startup.browser_backend_toggle_block(row)
        if not row or row.live~=true or tostring(row.listingId or "")=="" then return false end
        local action=row.blockedByYou==true and "UNBLOCK" or "BLOCK"
        local ok,err,data=post("block.php",{listing_id=tostring(row.listingId),action=action})
        if not ok then
            bb.vote_status="Block action failed: "..tostring(err)
            if startup.toast then startup.toast("Browser "..action:lower().." failed: "..tostring(err),4500) end
            return false
        end
        row.blockedByYou=(data.blocked==true)
        if startup.toast then startup.toast(row.blockedByYou and (tostring(row.username).." added to your Browser blocklist. JOIN is disabled.") or (tostring(row.username).." removed from your Browser blocklist."),4000) end
        if startup.browser_backend_fetch_hosts then startup.browser_backend_fetch_hosts() end
        return true
    end

    function startup.browser_submit_removal_vote(targetPid,reasonKey)
        if startup.s.browserBackendEnabled~=true or bb.token=="" then
            if startup.toast then startup.toast("Browser backend must be connected before voting.",4000) end
            return false
        end
        if startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true then
            if startup.toast then startup.toast("You are Session Host. Review removal requests below instead of voting to yourself.",4500) end
            return false
        end
        local host=session_host_info()
        targetPid=tonumber(targetPid)
        if not host then bb.vote_status="Session Host identity unavailable"; return false end
        if targetPid==nil or targetPid<0 or targetPid>31 or not player_exists(targetPid) then bb.vote_status="Select a current session player"; return false end
        if targetPid==host.pid then bb.vote_status="The Session Host cannot be selected for Host Kick"; return false end
        local targetRid=player_rid(targetPid)
        if targetRid<=0 then bb.vote_status="Target Rockstar identity unavailable"; return false end
        local ok,err,data=post("vote.php",{
            session_host_rid=string.format("%.0f",host.rid),
            target_rid=string.format("%.0f",targetRid),
            target_player_id=tostring(targetPid),
            reason=tostring(reasonKey or "OTHER")
        })
        if not ok then
            local pretty={VOTER_NOT_IN_HOST_SESSION="Vote refused: your account is not in the host's current roster.",TARGET_NOT_IN_HOST_SESSION="Vote refused: target is not in the host's current roster.",SESSION_HOST_NOT_BROWSER_ACTIVE="Vote unavailable: the Session Host is not actively publishing Startup Browser.",ALREADY_VOTED="You already voted on this player in this session.",CANNOT_VOTE_SESSION_HOST="The Session Host cannot be Host Kicked.",VOTE_LIMIT_REACHED="Vote limit reached for this session."}
            bb.vote_status=pretty[err] or ("Vote failed: "..tostring(err))
            if startup.toast then startup.toast(bb.vote_status,5000) end
            return false
        end
        bb.vote_status="Vote forwarded to Session Host: "..tostring(data.target_username or startup.get_player_name_safe(targetPid)).." • "..tostring(data.votes or 1).." vote(s)"
        if startup.toast then startup.toast(bb.vote_status,5000) end
        return true
    end

    function startup.browser_poll_removal_votes()
        if startup.s.browserBackendEnabled~=true or bb.token=="" then bb.vote_groups={}; return false end
        if not (startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true) then bb.vote_groups={}; return true end
        local ok,err,data=post("votes.php",{})
        if not ok then bb.vote_status="Vote feed: "..tostring(err); return false end
        bb.vote_groups=type(data.votes)=="table" and data.votes or {}
        return true
    end

    function startup.browser_host_decide_vote(group,decision)
        if type(group)~="table" then return false end
        decision=tostring(decision or "IGNORE"):upper()
        if decision~="IGNORE" and decision~="HOST_KICK" then return false end
        if not (startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true) then
            if startup.toast then startup.toast("Only the current Session Host can decide a removal request.",4500) end
            return false
        end
        local actionResult="NOT_AVAILABLE"
        if decision=="HOST_KICK" then
            local pid=tonumber(group.target_player_id)
            local _,hostPid=startup.get_session_host_name()
            hostPid=tonumber(hostPid)
            if pid==nil or pid<0 or pid>31 or pid==hostPid or (startup.is_local_player_id and startup.is_local_player_id(pid)) or not player_exists(pid) then
                bb.vote_status="Host Kick refused: target left, changed slots, or is Session Host."
                if startup.toast then startup.toast(bb.vote_status,5000) end
                return false
            end
            local liveName=tostring(startup.get_player_name_safe and startup.get_player_name_safe(pid) or "")
            local expected=tostring(group.target_username or "")
            if liveName=="" or expected=="" or liveName:lower()~=expected:lower() then
                bb.vote_status="Host Kick refused: target identity changed. Refreshing vote feed."
                if startup.toast then startup.toast(bb.vote_status,5000) end
                startup.browser_poll_removal_votes()
                return false
            end
            local sent=startup.host_kick_bypass and startup.host_kick_bypass.run_for_player_id
                and startup.host_kick_bypass.run_for_player_id(pid,"Browser Vote Host Decision") == true
            actionResult=sent and "SENT" or "FAILED"
            bb.vote_status=sent and ("Host approved removal: "..liveName) or ("Host Kick failed: "..liveName)
        else
            actionResult="NOT_AVAILABLE"
            bb.vote_status="Removal request ignored by host."
        end
        local ok,err=post("vote-decision.php",{vote_id=tostring(group.vote_id or ""),decision=decision,action_result=actionResult})
        if not ok then
            bb.vote_status=bb.vote_status.." • server decision log failed: "..tostring(err)
        end
        startup.browser_poll_removal_votes()
        if startup.toast then startup.toast(bb.vote_status,4500) end
        return true
    end

    local function render_vote_reason_combo()
        local currentLabel="Crash attempts"
        for _,r in ipairs(voteReasons) do if r.key==bb.vote_reason then currentLabel=r.label break end end
        if ImGui.BeginCombo and ImGui.BeginCombo("Reason##SB214VoteReason",currentLabel) then
            for _,r in ipairs(voteReasons) do
                if ImGui.Selectable(r.label.."##SB214Reason"..r.key,bb.vote_reason==r.key) then bb.vote_reason=r.key end
            end
            ImGui.EndCombo()
        end
    end

    local function render_vote_target_combo(targets)
        local preview="Select player"
        for _,t in ipairs(targets) do if tonumber(t.pid)==tonumber(bb.vote_target_pid) then preview=t.name break end end
        if ImGui.BeginCombo and ImGui.BeginCombo("Player##SB214VoteTarget",preview) then
            for _,t in ipairs(targets) do
                if ImGui.Selectable(t.name.."##SB214Target"..tostring(t.pid),tonumber(bb.vote_target_pid)==tonumber(t.pid)) then bb.vote_target_pid=t.pid end
            end
            ImGui.EndCombo()
        end
    end

    function startup.browser_render_session_safety()
        if not ImGui then return end
        if startup.section_title then startup.section_title("Session Safety") else ImGui.Text("SESSION SAFETY") end
        if startup.browser_render_make_room_control then startup.browser_render_make_room_control() end
        if ImGui.Separator then ImGui.Separator() end
        if startup.subtle_text_wrapped then startup.subtle_text_wrapped("Votes are session-local requests. The server accepts a vote only when both the voter and target appear in the current Browser host's fresh session roster. Votes never kick automatically; the Session Host decides.") end
        if startup.s.browserBackendEnabled~=true or bb.token=="" then
            if startup.subtle_text then startup.subtle_text("Connect BACKEND to use Session Safety voting.") end
            return
        end

        local isHost=startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true
        if isHost then
            local groups=type(bb.vote_groups)=="table" and bb.vote_groups or {}
            if #groups==0 then
                if startup.subtle_text then startup.subtle_text("No active removal requests for this hosted session.") end
            else
                for i,g in ipairs(groups) do
                    ImGui.Separator()
                    local title=tostring(g.target_username or "Unknown").." • "..tostring(g.votes or 0).." vote(s)"
                    if startup.text_colored then startup.text_colored(1.00,0.42,0.42,1.00,title) else ImGui.Text(title) end
                    if g.verified_startup_user==true and startup.text_colored then startup.text_colored(0.74,0.45,1.00,1.00,"Verified Startup user • automatic removal remains suppressed; this is a manual host decision.") end
                    if type(g.reasons)=="table" then
                        local parts={}
                        for _,r in ipairs(g.reasons) do parts[#parts+1]=tostring(r.label or "Other").." x"..tostring(r.count or 1) end
                        if #parts>0 and startup.subtle_text_wrapped then startup.subtle_text_wrapped("Reasons: "..table.concat(parts," • ")) end
                    end
                    if type(g.voters)=="table" and #g.voters>0 and startup.subtle_text_wrapped then startup.subtle_text_wrapped("Voters: "..table.concat(g.voters,", ")) end
                    if ImGui.Button("IGNORE##SB214Ignore"..i,110,26) then startup.browser_host_decide_vote(g,"IGNORE") end
                    ImGui.SameLine()
                    if ImGui.Button("HOST KICK##SB214HostKick"..i,130,26) then startup.browser_host_decide_vote(g,"HOST_KICK") end
                end
            end
        else
            local host=session_host_info()
            if not host then
                if startup.subtle_text then startup.subtle_text("Waiting for a valid Session Host identity.") end
            else
                if startup.subtle_text then startup.subtle_text("Current host: "..tostring(host.name)) end
                local targets=remote_vote_targets()
                if #targets==0 then
                    if startup.subtle_text then startup.subtle_text("No eligible remote player to vote on.") end
                else
                    render_vote_target_combo(targets)
                    render_vote_reason_combo()
                    if ImGui.Button("VOTE TO REMOVE##SB214Vote",180,28) then startup.browser_submit_removal_vote(bb.vote_target_pid,bb.vote_reason) end
                end
            end
        end
        if tostring(bb.vote_status or "")~="" and startup.subtle_text_wrapped then startup.subtle_text_wrapped("Status: "..tostring(bb.vote_status)) end
    end

    if not bb.vote_worker_installed and Script and Script.QueueJob then
        bb.vote_worker_installed=true
        Script.QueueJob(function()
            while true do
                if startup.s.browserBackendEnabled==true and bb.token~="" and startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true then
                    local now=nowms()
                    if now >= (tonumber(bb.next_vote_poll_ms or 0) or 0) then
                        startup.browser_poll_removal_votes()
                        bb.next_vote_poll_ms=nowms()+5000
                    end
                else
                    bb.vote_groups={}
                end
                if startup.yield then startup.yield(1000) elseif Script and Script.Yield then Script.Yield(1000) end
            end
        end)
    end
end

-- Reset the Browser session nonce on every actual GTA session change. The server uses
-- this nonce to issue a new listing id and isolate vote history to one exact session.
if EventMgr and eLuaEvent and eLuaEvent.ON_SESSION_CHANGE and not bs214._session_handler_installed then
    bs214._session_handler_installed=true
    EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE,function()
        if startup.browser_backend_new_session_nonce then startup.browser_backend_new_session_nonce() end
        local bb=startup.browser_backend
        if bb then
            bb.listing_id=""
            bb.vote_groups={}
            bb.verified_by_player={}
            bb.next_heartbeat_ms=0
            bb.next_fetch_ms=0
            bb.next_vote_poll_ms=0
        end
    end)
end


-- Make Room for a Cherax User
-- ON by default. When this client is the current Session Host AND its Browser listing
-- is actively published, Startup owns Cherax's native "Block Matchmaking Joins"
-- switch at the requested threshold:
--     27 or more players -> ON  (reserve the remaining lobby room from random matchmaking)
--     26 or fewer players -> OFF (reopen normal matchmaking)
-- The native Cherax description says this stops matchmaking services from promoting the
-- lobby to random GTA Online joiners. Direct Browser JOIN remains a separate RID-join path;
-- we still validate the 27-player direct-join behavior in a later two-client test.
bs214.make_room = bs214.make_room or {
    status = "Ready",
    last_players = 0,
    last_desired = nil,
    last_apply_ms = 0,
    feature_name = "Block Matchmaking Joins",
    feature_hash = 2087764882,
    controlled = false,
}
local room214 = bs214.make_room

local function room214_feature()
    local feature=nil
    if startup.get_feature_by_hash_safe then
        feature=startup.get_feature_by_hash_safe(room214.feature_hash)
    elseif FeatureMgr and FeatureMgr.GetFeature then
        local ok,v=direct_call(FeatureMgr.GetFeature,room214.feature_hash)
        if ok then feature=v end
    end
    if not feature and FeatureMgr and FeatureMgr.GetFeatureByName then
        local ok,v=direct_call(FeatureMgr.GetFeatureByName,room214.feature_name)
        if ok then feature=v end
    end
    return feature
end

local function room214_feature_state(feature)
    if not feature then return nil end
    if startup.get_feature_bool_state then
        local ok,v=direct_call(startup.get_feature_bool_state,feature)
        if ok and v~=nil then return v==true end
    end
    if feature.GetBoolValue then
        local ok,v=direct_call(function() return feature:GetBoolValue() end)
        if ok and v~=nil then return v==true end
    end
    if feature.IsToggled then
        local ok,v=direct_call(function() return feature:IsToggled() end)
        if ok and v~=nil then return v==true end
    end
    return nil
end

local function room214_set(enabled,reason)
    enabled=enabled==true
    local feature=room214_feature()
    if not feature then
        room214.status="Block Matchmaking Joins unavailable on this Cherax build."
        return false
    end
    local current=room214_feature_state(feature)
    if current~=nil and current==enabled then
        room214.controlled=true
        room214.last_desired=enabled
        return true
    end
    local ok=direct_call(function()
        -- Match Startup's proven native-toggle handling: prefer Toggle(bool), then
        -- SetBoolValue. Never fire a second unconditional callback after setting it.
        if feature.Toggle then
            feature:Toggle(enabled)
        elseif feature.SetBoolValue then
            feature:SetBoolValue(enabled)
        elseif current~=nil and current~=enabled and feature.OnClick then
            feature:OnClick()
        elseif current~=nil and current~=enabled and feature.TriggerCallback then
            feature:TriggerCallback()
        end
    end)
    if not ok then
        room214.status="Could not change Block Matchmaking Joins."
        return false
    end
    room214.controlled=true
    room214.last_desired=enabled
    room214.last_apply_ms=startup.now and startup.now() or 0
    -- Build 299: routine 27/26 Make Room threshold transitions are intentionally quiet.
    -- Feature state/status still updates normally; only the repetitive INFO line is muted.
    return true
end

function startup.browser_make_room_release(reason)
    -- Never leave a matchmaking block behind when Browser publication/hosting stops or
    -- the automation is disabled. This only changes the native switch if this feature
    -- has actually taken control during the current Startup run.
    if room214.controlled==true then
        room214_set(false,reason or "automation released")
        room214.controlled=false
        room214.last_desired=false
    end
end

function startup.browser_make_room_tick(force)
    if startup.s.browserMakeRoomForCheraxUser~=true then
        startup.browser_make_room_release("Make Room disabled")
        room214.status="Disabled"
        return false
    end

    local isHost=startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true
    if not isHost then
        startup.browser_make_room_release("not Session Host")
        room214.status="Waiting for you to become Session Host."
        room214.last_players=startup.get_session_player_count and startup.get_session_player_count() or 0
        return false
    end

    local bb=startup.browser_backend
    local browserPublished=startup.s.browserBackendEnabled==true and bb and bb.token~="" and bb.published==true
    if not browserPublished then
        startup.browser_make_room_release("Browser host is not published")
        room214.status="Waiting for BACKEND • HOST PUBLISHED."
        room214.last_players=startup.get_session_player_count and startup.get_session_player_count() or 0
        return false
    end

    local players=startup.get_session_player_count and tonumber(startup.get_session_player_count() or 0) or 0
    room214.last_players=players
    local desired=players>=27
    local feature=room214_feature()
    if not feature then
        room214.status="Block Matchmaking Joins unavailable on this Cherax build."
        return false
    end
    local actual=room214_feature_state(feature)
    if force==true or actual==nil or actual~=desired then
        if not room214_set(desired,(tostring(players).." players")) then return false end
        actual=room214_feature_state(feature)
    end
    room214.controlled=true
    room214.last_desired=desired
    if desired then
        room214.status=tostring(players).." players • RANDOM MATCHMAKING BLOCKED • reserving room for Browser/Cherax joins"
    else
        room214.status=tostring(players).." players • RANDOM MATCHMAKING OPEN • blocks automatically at 27"
    end
    return true
end

function startup.browser_render_make_room_control()
    if not ImGui then return end
    local old=startup.s.browserMakeRoomForCheraxUser~=false
    local new=ImGui.Checkbox("MAKE ROOM FOR A CHERAX USER##SB214MakeRoom",old)
    if new~=old then
        startup.s.browserMakeRoomForCheraxUser=new==true
        if startup.s.initialized and startup.save_config then startup.save_config(false) end
        startup.browser_make_room_tick(true)
    end
    if startup.subtle_text_wrapped then
        startup.subtle_text_wrapped("ON by default. While you are a published Browser Session Host: 27+ players turns Block Matchmaking Joins ON; 26 or fewer turns it OFF.")
        startup.subtle_text_wrapped("Make Room: "..tostring(room214.status or "Ready"))
    end
end

if not room214.worker_installed and Script and Script.QueueJob then
    room214.worker_installed=true
    Script.QueueJob(function()
        while true do
            startup.browser_make_room_tick(false)
            if startup.yield then startup.yield(1000) elseif Script and Script.Yield then Script.Yield(1000) end
        end
    end)
end

if EventMgr and eLuaEvent and eLuaEvent.ON_UNLOAD and not room214.unload_handler_installed then
    room214.unload_handler_installed=true
    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD,function()
        startup.browser_make_room_release("Startup unload")
    end)
end

if startup.log then startup.log("[Browser Make Room] Ready | default ON | 27+ block matchmaking | <=26 reopen") end

if startup.log then startup.log("[Browser] Build 217 Phase 3.1 | verified-peer safety | personal blocks | same-session host-mediated removal votes | Make Room 27/26 | parser scope fix") end
end
startup.install_browser_safety_build217()
startup.install_browser_safety_build217 = nil

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 220: PHASE 3.2 MODERATION FOUNDATION
-- Server-authoritative Browser moderation states + same-session security incident log.
-- WARNED remains usable. TEMP_SUSPENDED / BANNED cannot publish, browse, JOIN, block,
-- or vote. No automatic global punishment is issued by this client layer.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.build_number = "2026.08.09.220"
startup.build_date = "2026-08-09"

function startup.install_browser_moderation_build220()
    startup.browser_moderation = startup.browser_moderation or {}
    local bm = startup.browser_moderation
    local bb = startup.browser_backend or {}
    startup.browser_backend = bb
    bm.owner_uid = "PU-B548A0968B01AB57EC8C276359F1B06F"
    bm.incident_cooldown = bm.incident_cooldown or {}
    bm.personal_blocks = bm.personal_blocks or {}
    bm.block_status = tostring(bm.block_status or "Ready")
    bm.next_blocks_ms = tonumber(bm.next_blocks_ms or 0) or 0
    bm.dev_override_state = tostring(bm.dev_override_state or "")
    bm.dev_vote_injected = bm.dev_vote_injected == true

    local function nowms()
        if startup.now then return tonumber(startup.now()) or 0 end
        return math.floor(os.clock()*1000)
    end

    local function post(endpoint,fields)
        if not bb._post or bb.token==nil or bb.token=="" then return false,"BACKEND_NOT_CONNECTED",nil end
        local ok,body=bb._post(endpoint,fields or {},bb.token)
        local data=(ok and bb._json_decode) and bb._json_decode(body) or nil
        if not ok then return false,tostring(body),data end
        if type(data)~="table" or data.ok~=true then
            return false,type(data)=="table" and tostring(data.error or "API_ERROR") or "INVALID_RESPONSE",data
        end
        return true,nil,data
    end

    function startup.browser_effective_moderation_state()
        if tostring(bm.dev_override_state or "")~="" then return tostring(bm.dev_override_state):upper() end
        local state=tostring(bb.browser_moderation or "ACTIVE"):upper()
        if state~="ACTIVE" and state~="WARNED" and state~="TEMP_SUSPENDED" and state~="BANNED" then state="ACTIVE" end
        return state
    end

    function startup.browser_moderation_allows_access()
        local state=startup.browser_effective_moderation_state()
        return state=="ACTIVE" or state=="WARNED"
    end

    local function player_exists(pid)
        pid=tonumber(pid)
        if pid==nil or pid<0 or pid>31 or not (Players and Players.GetById) then return false end
        local ok,obj=direct_call(Players.GetById,pid)
        return ok and obj~=nil
    end

    local function player_rid(pid)
        if startup.presence and startup.presence.get_player_rid then
            local ok,v=direct_call(startup.presence.get_player_rid,pid)
            if ok then return tonumber(v or 0) or 0 end
        end
        if Players and Players.GetRockstarId then
            local ok,v=direct_call(Players.GetRockstarId,pid)
            if ok then return tonumber(v or 0) or 0 end
        end
        return 0
    end

    local function session_host_info()
        if not startup.get_session_host_name then return nil end
        local name,pid=startup.get_session_host_name()
        pid=tonumber(pid)
        if pid==nil or pid<0 or pid>31 then return nil end
        local rid=player_rid(pid)
        if rid<=0 then return nil end
        return {name=tostring(name or "Session Host"),pid=pid,rid=rid}
    end

    function startup.browser_record_security_incident(targetPid,incidentType,source,confidence,summary,quiet)
        if not startup.browser_terms_accepted or not startup.browser_terms_accepted() then return false,"TERMS_REQUIRED" end
        if not startup.browser_moderation_allows_access() then return false,"BROWSER_RESTRICTED" end
        if bb.token==nil or bb.token=="" then return false,"BACKEND_NOT_CONNECTED" end
        local pid=tonumber(targetPid)
        if pid==nil or pid<0 or pid>31 or not player_exists(pid) then return false,"TARGET_NOT_PRESENT" end
        local rid=player_rid(pid)
        local host=session_host_info()
        if rid<=0 or not host then return false,"SESSION_IDENTITY_UNAVAILABLE" end
        local key=tostring(pid).."|"..tostring(incidentType or "")
        local now=nowms()
        if now-(tonumber(bm.incident_cooldown[key] or 0) or 0)<15000 then return false,"COOLDOWN" end
        bm.incident_cooldown[key]=now
        local function send()
            local ok,err,data=post("incident.php",{
                session_host_rid=string.format("%.0f",host.rid),
                target_rid=string.format("%.0f",rid),
                target_player_id=tostring(pid),
                incident_type=tostring(incidentType or "SESSION_DISRUPTION"),
                source=tostring(source or "STARTUP"),
                confidence=tostring(confidence or "LOW"),
                summary=tostring(summary or ""):sub(1,255)
            })
            if ok then
                bm.last_incident="Recorded "..tostring(data.incident_type or incidentType).." for "..tostring(data.target_username or startup.get_player_name_safe(pid)).." • "..tostring(data.incident_id or "")
                if startup.log then startup.log("[Browser Safety] "..bm.last_incident) end
            else
                bm.last_incident="Incident not recorded: "..tostring(err)
                if not quiet and startup.toast then startup.toast(bm.last_incident,4500) end
            end
        end
        if Script and Script.QueueJob then Script.QueueJob(send) else send() end
        return true,nil
    end

    -- Corroborated repeated kick-reaction evidence is recorded, but still never creates
    -- a Browser ban automatically. Existing reactive Host Kick rules remain separate.
    if startup.crash_defense and startup.crash_defense.record_kick_evidence and not bm._wrapped_kick_evidence then
        bm._wrapped_kick_evidence=true
        local old=startup.crash_defense.record_kick_evidence
        startup.crash_defense.record_kick_evidence=function(playerId,fingerprint)
            local count,added=old(playerId,fingerprint)
            local threshold=tonumber(startup.crash_defense.kick_evidence_required or 2) or 2
            if added==true and tonumber(count or 0)>=threshold then
                startup.browser_record_security_incident(playerId,"KICK_ATTEMPT","ON_REACTION","CORROBORATED","Repeated non-duplicate KICK / VOTE_KICK reactions reached Startup's strict evidence threshold.",true)
            end
            return count,added
        end
    end

    if startup.crash_defense and startup.crash_defense.begin_one_time_crash_response and not bm._wrapped_crash_incident then
        bm._wrapped_crash_incident=true
        local old=startup.crash_defense.begin_one_time_crash_response
        startup.crash_defense.begin_one_time_crash_response=function(playerId,playerName,reason,source)
            local src=tostring(source or ""):find("ON_REACTION",1,true) and "ON_REACTION" or "STARTUP"
            startup.browser_record_security_incident(playerId,"CRASH_ATTEMPT",src,"CONFIRMED",tostring(reason or "Crash Attack").." | "..tostring(source or "Startup"),true)
            return old(playerId,playerName,reason,source)
        end
    end

    function startup.browser_fetch_personal_blocks()
        if not startup.browser_moderation_allows_access() or bb.token=="" then bm.personal_blocks={}; return false end
        local ok,err,data=post("blocks.php",{})
        if not ok then bm.block_status="Blocklist: "..tostring(err); return false end
        bm.personal_blocks=type(data.blocks)=="table" and data.blocks or {}
        bm.block_status=tostring(#bm.personal_blocks).." blocked user(s)"
        return true
    end

    function startup.browser_unblock_personal_block(blockId)
        local ok,err=post("block.php",{action="UNBLOCK",listing_id="---",block_id=tostring(blockId or 0)})
        if not ok then bm.block_status="Unblock failed: "..tostring(err); return false end
        bm.block_status="User removed from personal blocklist."
        startup.browser_fetch_personal_blocks()
        if startup.browser_backend_fetch_hosts then startup.browser_backend_fetch_hosts() end
        return true
    end

    if startup.browser_backend_toggle_block and not bm._wrapped_block_refresh then
        bm._wrapped_block_refresh=true
        local old=startup.browser_backend_toggle_block
        startup.browser_backend_toggle_block=function(row)
            if not startup.browser_moderation_allows_access() then
                if startup.toast then startup.toast("Browser access is restricted by moderation status.",4000) end
                return false
            end
            local ok=old(row)
            if ok then bm.next_blocks_ms=0 end
            return ok
        end
    end

    local function render_blocklist()
        if startup.section_title then startup.section_title("Personal Browser Blocklist") else ImGui.Text("PERSONAL BROWSER BLOCKLIST") end
        if startup.subtle_text_wrapped then startup.subtle_text_wrapped("Personal blocks prevent JOINs between you and that Browser account. They do not mark the user as a modder and do not create a moderation penalty.") end
        local rows=type(bm.personal_blocks)=="table" and bm.personal_blocks or {}
        if #rows==0 then
            if startup.subtle_text then startup.subtle_text("No personally blocked Browser users.") end
        else
            for i,row in ipairs(rows) do
                local name=tostring(row.username or "Startup User")
                if startup.text_colored then startup.text_colored(0.88,0.88,0.92,1.00,name) else ImGui.Text(name) end
                ImGui.SameLine()
                if ImGui.Button("UNBLOCK##SB220Block"..tostring(i),90,24) then startup.browser_unblock_personal_block(row.block_id) end
            end
        end
        if startup.subtle_text then startup.subtle_text("Status: "..tostring(bm.block_status or "Ready")) end
    end

    -- Extend the existing host-mediated inbox without changing its enforcement semantics.
    if startup.browser_render_session_safety and not bm._wrapped_safety_render then
        bm._wrapped_safety_render=true
        local old=startup.browser_render_session_safety
        startup.browser_render_session_safety=function()
            old()
            if not ImGui then return end
            ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
            render_blocklist()
            if tostring(bm.last_incident or "")~="" and startup.subtle_text_wrapped then startup.subtle_text_wrapped("Security telemetry: "..tostring(bm.last_incident)) end

            if tostring(bb.startup_uid or "")==bm.owner_uid then
                ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
                if startup.section_title then startup.section_title("Developer Safety Simulation") else ImGui.Text("DEVELOPER SAFETY SIMULATION") end
                if startup.text_colored then startup.text_colored(1.00,0.78,0.25,1.00,"LOCAL SIMULATION ONLY • NOT SENT TO SERVER") end
                if startup.subtle_text_wrapped then startup.subtle_text_wrapped("Use these controls to verify Browser gates and moderation UI without changing your real account status or creating fake backend evidence.") end
                if ImGui.Button("ACTIVE##SB220DevActive",88,24) then bm.dev_override_state="ACTIVE" end
                ImGui.SameLine(); if ImGui.Button("WARNED##SB220DevWarned",88,24) then bm.dev_override_state="WARNED" end
                ImGui.SameLine(); if ImGui.Button("SUSPENDED##SB220DevSusp",110,24) then bm.dev_override_state="TEMP_SUSPENDED" end
                ImGui.SameLine(); if ImGui.Button("BANNED##SB220DevBan",88,24) then bm.dev_override_state="BANNED" end
                if ImGui.Button("CLEAR SIMULATION##SB220DevClear",180,24) then bm.dev_override_state=""; bm.dev_vote_injected=false end
                ImGui.SameLine()
                if ImGui.Button("SIMULATE HOST VOTE##SB220DevVote",180,24) then
                    bb.vote_groups={{vote_id="SIM-LOCAL",target_username="Simulation Target",target_player_id=-1,votes=3,voters={"TestUserA","TestUserB","TestUserC"},reasons={{label="Crash attempts",count=2},{label="Kick attempts",count=1}},verified_startup_user=true,security_events=2,confirmed_events=1}}
                    bm.dev_vote_injected=true
                    bb.vote_status="Local simulated vote injected; HOST KICK safely refuses invalid player slot."
                end
                if tostring(bm.dev_override_state or "")~="" and startup.subtle_text then startup.subtle_text("Effective simulated state: "..tostring(bm.dev_override_state)) end
            end
        end
    end

    -- Render evidence counters returned by v1.5.0 in the existing vote inbox by augmenting
    -- each group's reasons text through a lightweight status string. No vote count threshold
    -- triggers an action; HOST KICK remains an explicit host click.
    if startup.browser_poll_removal_votes and not bm._wrapped_vote_evidence then
        bm._wrapped_vote_evidence=true
        local old=startup.browser_poll_removal_votes
        startup.browser_poll_removal_votes=function()
            local ok=old()
            if ok and type(bb.vote_groups)=="table" then
                for _,g in ipairs(bb.vote_groups) do
                    local total=tonumber(g.security_events or 0) or 0
                    local confirmed=tonumber(g.confirmed_events or 0) or 0
                    if total>0 then
                        g.reasons=g.reasons or {}
                        g.reasons[#g.reasons+1]={label="Startup security evidence ("..tostring(confirmed).." confirmed)",count=total}
                    end
                end
            end
            return ok
        end
    end

    -- Client-side convenience gates. The v1.5.0 server independently enforces the same
    -- restriction on every Browser endpoint, so local edits cannot bypass moderation.
    if startup.browser_backend_heartbeat and not bm._wrapped_heartbeat then
        bm._wrapped_heartbeat=true
        local old=startup.browser_backend_heartbeat
        startup.browser_backend_heartbeat=function()
            if startup.browser_terms_accepted and startup.browser_terms_accepted() and not startup.browser_moderation_allows_access() then
                if bb.published and startup.browser_backend_offline then startup.browser_backend_offline() end
                bb.status=startup.browser_effective_moderation_state()=="BANNED" and "BROWSER BANNED" or "BROWSER SUSPENDED"
                return false
            end
            return old()
        end
    end
    if startup.browser_backend_fetch_hosts and not bm._wrapped_fetch then
        bm._wrapped_fetch=true
        local old=startup.browser_backend_fetch_hosts
        startup.browser_backend_fetch_hosts=function()
            if not startup.browser_moderation_allows_access() then
                bb.live_count=0
                if startup.browser_set_live_hosts then startup.browser_set_live_hosts({}) end
                return false
            end
            return old()
        end
    end
    if startup.browser_execute_join and not bm._wrapped_join then
        bm._wrapped_join=true
        local old=startup.browser_execute_join
        startup.browser_execute_join=function(row)
            if not startup.browser_moderation_allows_access() then
                if startup.toast then startup.toast("Startup Browser access is suspended or banned.",4500) end
                return false
            end
            return old(row)
        end
    end
    if startup.browser_submit_removal_vote and not bm._wrapped_vote_submit then
        bm._wrapped_vote_submit=true
        local old=startup.browser_submit_removal_vote
        startup.browser_submit_removal_vote=function(...)
            if not startup.browser_moderation_allows_access() then
                if startup.toast then startup.toast("Startup Browser voting is unavailable while access is restricted.",4500) end
                return false
            end
            return old(...)
        end
    end

    if startup.render_browser and not bm._wrapped_browser_render then
        bm._wrapped_browser_render=true
        local old=startup.render_browser
        startup.render_browser=function()
            if not startup.browser_terms_accepted or not startup.browser_terms_accepted() then return old() end
            local state=startup.browser_effective_moderation_state()
            if state=="TEMP_SUSPENDED" or state=="BANNED" then
                if startup.text_colored then startup.text_colored(1.00,0.25,0.25,1.00,state=="BANNED" and "STARTUP BROWSER ACCESS BANNED" or "STARTUP BROWSER TEMPORARILY SUSPENDED") end
                if startup.subtle_text_wrapped then
                    startup.subtle_text_wrapped(tostring(bb.browser_moderation_message or "Browser access has been restricted by Public_Urinal moderation."))
                    if state=="TEMP_SUSPENDED" and tostring(bb.browser_moderation_expires_at or "")~="" then startup.subtle_text_wrapped("Expires: "..tostring(bb.browser_moderation_expires_at).." UTC") end
                    startup.subtle_text_wrapped("While restricted you cannot publish a host, browse hosts, JOIN, vote, or change Browser blocks. Your Public_Urinal account remains enrolled so Startup can display the current moderation status.")
                end
                if tostring(bm.dev_override_state or "") ~= "" and tostring(bb.startup_uid or "") == tostring(bm.owner_uid or "") and ImGui then
                    ImGui.Spacing()
                    if ImGui.Button("END LOCAL SIMULATION##SB221EmergencyClear",220,28) then
                        bm.dev_override_state=""; bm.dev_vote_injected=false
                    end
                end
                return
            end
            if state=="WARNED" then
                if startup.text_colored then startup.text_colored(1.00,0.72,0.18,1.00,"ACCOUNT WARNING") end
                if startup.subtle_text_wrapped then startup.subtle_text_wrapped(tostring(bb.browser_moderation_message or "Your Browser account has an active moderation warning. Browser access remains available.")) end
                if ImGui and ImGui.Separator then ImGui.Separator() end
            end
            return old()
        end
    end

    if not bm.worker_installed and Script and Script.QueueJob then
        bm.worker_installed=true
        Script.QueueJob(function()
            while true do
                local now=nowms()
                if startup.browser_moderation_allows_access() and bb.token~="" and now>=(tonumber(bm.next_blocks_ms or 0) or 0) then
                    startup.browser_fetch_personal_blocks()
                    bm.next_blocks_ms=nowms()+30000
                end
                if startup.yield then startup.yield(1000) elseif Script and Script.Yield then Script.Yield(1000) end
            end
        end)
    end

    if startup.log then startup.log("[Browser] Build 220 Phase 3.2 | moderation states | same-session incident telemetry | personal blocklist manager | vote evidence | owner simulation") end
end
startup.install_browser_moderation_build220()
startup.install_browser_moderation_build220 = nil


-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 221: PHASE 3.2 VOTE UX + ANONYMOUS HOST INBOX + IMMUTABLE USER HISTORY
-- v1.6.0 backend adds vote messages, private vote/report history, and encounter-validated
-- reports. Vote identity is retained server-side for abuse prevention but is anonymous
-- to the Session Host. Normal UI blocks paste into 255-character optional messages.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.build_number = "2026.08.09.221"
startup.build_date = "2026-08-09"

function startup.install_browser_vote_ux_build221()
    startup.browser_moderation = startup.browser_moderation or {}
    startup.browser_backend = startup.browser_backend or {}
    startup.browser_vote_hud = startup.browser_vote_hud or {text="",until_ms=0}
    local bm = startup.browser_moderation
    local bb = startup.browser_backend
    startup.s.browserSessionSafetyEnabled = startup.s.browserSessionSafetyEnabled ~= false
    bm.vote_history = bm.vote_history or {}
    bm.report_history = bm.report_history or {}
    bm.history_status = tostring(bm.history_status or "Ready")
    bm.next_history_ms = tonumber(bm.next_history_ms or 0) or 0
    bm.vote_popup_requested = false
    bm.vote_reason_popup_requested = false
    bm.report_popup_requested = false
    bm.vote_target_pid = tonumber(bm.vote_target_pid or -1) or -1
    bm.vote_target_name = tostring(bm.vote_target_name or "")
    bm.vote_reason = tostring(bm.vote_reason or "CRASH_ATTEMPTS")
    bm.vote_message = tostring(bm.vote_message or "")
    bm.report_reason = tostring(bm.report_reason or "DISRUPTION")
    bm.report_message = tostring(bm.report_message or "")
    bm.report_target = bm.report_target or nil
    bm.input_notice = tostring(bm.input_notice or "")
    bm.last_vote_counts = bm.last_vote_counts or {}

    local reasons = {
        {key="CRASH_ATTEMPTS",label="Crash attempts"},
        {key="KICK_ATTEMPTS",label="Kick attempts"},
        {key="HARASSMENT",label="Harassment / trolling"},
        {key="DISRUPTION",label="Session disruption"},
        {key="OTHER",label="Other"},
    }

    local function nowms()
        if startup.now then return tonumber(startup.now()) or 0 end
        return math.floor(os.clock()*1000)
    end

    local function post(endpoint,fields)
        if not bb._post or bb.token==nil or bb.token=="" then return false,"BACKEND_NOT_CONNECTED",nil end
        local ok,body=bb._post(endpoint,fields or {},bb.token)
        local data=(ok and bb._json_decode) and bb._json_decode(body) or nil
        if not ok then return false,tostring(body),data end
        if type(data)~="table" or data.ok~=true then
            return false,type(data)=="table" and tostring(data.error or "API_ERROR") or "INVALID_RESPONSE",data
        end
        return true,nil,data
    end

    local function player_exists(pid)
        pid=tonumber(pid)
        if pid==nil or pid<0 or pid>31 or not (Players and Players.GetById) then return false end
        local ok,obj=direct_call(Players.GetById,pid)
        return ok and obj~=nil
    end

    local function player_rid(pid)
        if startup.presence and startup.presence.get_player_rid then
            local ok,v=direct_call(startup.presence.get_player_rid,pid)
            if ok and tonumber(v or 0) and tonumber(v or 0)>0 then return tonumber(v) end
        end
        if Players and Players.GetRockstarId then
            local ok,v=direct_call(Players.GetRockstarId,pid)
            if ok then return tonumber(v or 0) or 0 end
        end
        return 0
    end

    local function session_host_info()
        if not startup.get_session_host_name then return nil end
        local name,pid=startup.get_session_host_name()
        pid=tonumber(pid)
        if pid==nil or pid<0 or pid>31 then return nil end
        local rid=player_rid(pid)
        if rid<=0 then return nil end
        return {name=tostring(name or "Session Host"),pid=pid,rid=rid}
    end

    local function is_verified(pid)
        if startup.browser_safety and startup.browser_safety.is_verified_peer then
            local ok,v=direct_call(startup.browser_safety.is_verified_peer,pid)
            if ok then return v==true end
        end
        return false
    end

    local function set_vote_hud(text,duration)
        startup.browser_vote_hud.text=tostring(text or "")
        startup.browser_vote_hud.until_ms=nowms()+(tonumber(duration or 8000) or 8000)
    end

    local function reason_label(key)
        for _,r in ipairs(reasons) do if r.key==key then return r.label end end
        return "Other"
    end

    local function eligible_vote_targets()
        local host=session_host_info()
        local out={}
        for pid=0,31 do
            if player_exists(pid) and not (startup.is_local_player_id and startup.is_local_player_id(pid)) and (not host or pid~=host.pid) then
                local rid=player_rid(pid)
                if rid>0 then
                    out[#out+1]={pid=pid,rid=rid,name=tostring(startup.get_player_name_safe and startup.get_player_name_safe(pid) or ("Player "..pid)),verified=is_verified(pid)}
                end
            end
        end
        table.sort(out,function(a,b) return tostring(a.name):lower()<tostring(b.name):lower() end)
        return out
    end

    -- Best-effort normal-UI paste prevention. Server still enforces 255 characters.
    -- A modified Lua client cannot be trusted to honor UI restrictions, so backend
    -- abuse controls never depend on this client-side rule.
    local function typing_only_input(label,value)
        local old=tostring(value or "")
        local new,changed=ImGui.InputText(label,old,256)
        new=tostring(new or old):sub(1,255)
        if changed==true and #new>#old then
            local pasted=(#new-#old)>1
            if not pasted and ImGui.GetClipboardText then
                local ok,clip=direct_call(ImGui.GetClipboardText)
                clip=ok and tostring(clip or "") or ""
                if #clip>1 and new:find(clip,1,true) and not old:find(clip,1,true) then pasted=true end
            end
            if pasted then
                bm.input_notice="Pasting is disabled. Please type the optional message."
                return old
            end
        end
        if changed==true then bm.input_notice="" end
        return new
    end

    function startup.browser_request_vote_popup()
        if startup.s.browserSessionSafetyEnabled==false then
            if startup.toast then startup.toast("Session Safety is disabled in Config.",3500) end
            return false
        end
        if not startup.browser_moderation_allows_access or not startup.browser_moderation_allows_access() then
            if startup.toast then startup.toast("Startup Browser voting is unavailable while access is restricted.",4000) end
            return false
        end
        if startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true then
            if startup.toast then startup.toast("You are Session Host. Use the host removal inbox or your normal host controls.",4000) end
            return false
        end
        bm.vote_popup_requested=true
        return true
    end

    function startup.browser_request_report_popup(row)
        if type(row)~="table" or row.live~=true or tostring(row.listingId or "")=="" then
            if startup.toast then startup.toast("Reports are available for live Browser hosts only.",4000) end
            return false
        end
        bm.report_target=row
        bm.report_reason="DISRUPTION"
        bm.report_message=""
        bm.report_popup_requested=true
        return true
    end

    function startup.browser_submit_removal_vote(targetPid,reasonKey,message)
        if startup.s.browserSessionSafetyEnabled==false then return false end
        if not startup.browser_terms_accepted or not startup.browser_terms_accepted() then return false end
        if not startup.browser_moderation_allows_access or not startup.browser_moderation_allows_access() then return false end
        if bb.token==nil or bb.token=="" then return false end
        if startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true then
            if startup.toast then startup.toast("Session Host does not vote to itself. Review requests as host.",4000) end
            return false
        end
        local host=session_host_info()
        local pid=tonumber(targetPid)
        if not host then bb.vote_status="Session Host identity unavailable"; return false end
        if pid==nil or pid<0 or pid>31 or not player_exists(pid) then bb.vote_status="Select a current session player"; return false end
        if pid==host.pid then bb.vote_status="The Session Host cannot be selected for Host Kick"; return false end
        local rid=player_rid(pid)
        if rid<=0 then bb.vote_status="Target Rockstar identity unavailable"; return false end
        local ok,err,data=post("vote.php",{
            session_host_rid=string.format("%.0f",host.rid),
            target_rid=string.format("%.0f",rid),
            target_player_id=tostring(pid),
            reason=tostring(reasonKey or "OTHER"),
            message=tostring(message or ""):sub(1,255)
        })
        if not ok then
            local pretty={
                VOTER_NOT_IN_HOST_SESSION="Vote refused: you are not in this host's current session.",
                TARGET_NOT_IN_HOST_SESSION="Vote refused: that player is not in this host's current session.",
                SESSION_HOST_NOT_BROWSER_ACTIVE="Vote unavailable: the Session Host is not actively publishing Startup Browser.",
                ALREADY_VOTED="You already voted on this player in this session.",
                CANNOT_VOTE_SESSION_HOST="The Session Host cannot be Host Kicked.",
                CANNOT_VOTE_SELF="You cannot vote on yourself.",
                VOTE_LIMIT_REACHED="Vote limit reached for this session."
            }
            bb.vote_status=pretty[err] or ("Vote failed: "..tostring(err))
            if startup.toast then startup.toast(bb.vote_status,5000) end
            return false
        end
        bb.vote_status="Anonymous vote forwarded to Session Host: "..tostring(data.target_username or startup.get_player_name_safe(pid))
        if startup.toast then startup.toast(bb.vote_status,4500) end
        if startup.browser_fetch_history then startup.browser_fetch_history() end
        return true
    end

    function startup.browser_submit_report(row,reasonKey,message)
        if type(row)~="table" or tostring(row.listingId or "")=="" then return false end
        if not startup.browser_terms_accepted or not startup.browser_terms_accepted() then return false end
        if not startup.browser_moderation_allows_access or not startup.browser_moderation_allows_access() then return false end
        local ok,err,data=post("report.php",{
            listing_id=tostring(row.listingId),
            reason=tostring(reasonKey or "OTHER"),
            message=tostring(message or ""):sub(1,255)
        })
        if not ok then
            local pretty={
                REPORT_REQUIRES_SHARED_SESSION="Report refused: you must have shared this Browser session with the user.",
                ALREADY_REPORTED_SESSION="You already reported this user for this Browser session.",
                CANNOT_REPORT_SELF="You cannot report yourself.",
                HOST_NOT_AVAILABLE="That Browser host is no longer available."
            }
            local msg=pretty[err] or ("Report failed: "..tostring(err))
            if startup.toast then startup.toast(msg,5000) end
            return false
        end
        if startup.toast then startup.toast("Report submitted for moderation: "..tostring(data.target_username or row.username or "Startup User"),4500) end
        if startup.browser_fetch_history then startup.browser_fetch_history() end
        return true
    end

    function startup.browser_fetch_history()
        if bb.token==nil or bb.token=="" then return false end
        local ok,err,data=post("history.php",{})
        if not ok then bm.history_status="History: "..tostring(err); return false end
        bm.vote_history=type(data.votes)=="table" and data.votes or {}
        bm.report_history=type(data.reports)=="table" and data.reports or {}
        bm.history_status="Ready"
        return true
    end

    local oldPoll=startup.browser_poll_removal_votes
    if type(oldPoll)=="function" then
        startup.browser_poll_removal_votes=function()
            local ok=oldPoll()
            if ok and startup.s.browserSessionSafetyEnabled~=false and startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true then
                local nextCounts={}
                for _,g in ipairs(type(bb.vote_groups)=="table" and bb.vote_groups or {}) do
                    if type(g.reasons)=="table" then
                        local cleanReasons={}
                        for _,r in ipairs(g.reasons) do
                            if not tostring(r.label or ""):find("Startup security evidence (",1,true) then cleanReasons[#cleanReasons+1]=r end
                        end
                        g.reasons=cleanReasons
                    end
                    local key=tostring(g.target_username or "Unknown")
                    local count=tonumber(g.votes or 0) or 0
                    nextCounts[key]=count
                    local oldCount=tonumber(bm.last_vote_counts[key] or 0) or 0
                    if count>oldCount then
                        set_vote_hud("VOTE: Anonymous vote to remove "..key.." • "..tostring(count).." vote(s)",9000)
                    end
                end
                bm.last_vote_counts=nextCounts
            end
            return ok
        end
    end

    local oldDecision=startup.browser_host_decide_vote
    if type(oldDecision)=="function" then
        startup.browser_host_decide_vote=function(group,decision)
            local name=type(group)=="table" and tostring(group.target_username or "Unknown") or "Unknown"
            local ok=oldDecision(group,decision)
            if ok and tostring(decision or ""):upper()=="HOST_KICK" then
                set_vote_hud("VOTE: Host approved removal of "..name,9000)
            elseif ok and tostring(decision or ""):upper()=="IGNORE" then
                set_vote_hud("VOTE: Host dismissed removal request for "..name,6500)
            end
            return ok
        end
    end

    local function draw_reason_options(prefix,current)
        for _,r in ipairs(reasons) do
            local selected=current==r.key
            if ImGui.Selectable(r.label.."##"..prefix..r.key,selected) then current=r.key end
        end
        return current
    end

    local function render_vote_select_popup()
        local name="Vote - Select Player##SB221VoteSelect"
        if bm.vote_popup_requested then direct_call(ImGui.OpenPopup,name); bm.vote_popup_requested=false end
        local flags=(ImGuiWindowFlags and ImGuiWindowFlags.AlwaysAutoResize) or nil
        local visible=false
        direct_call(function() visible=ImGui.BeginPopupModal(name,true,flags)==true end)
        if not visible then return end
        if startup.text_colored then startup.text_colored(1.00,0.28,0.28,1.00,"VOTE TO REMOVE") end
        if startup.subtle_text_wrapped then startup.subtle_text_wrapped("Select a player who is currently in your GTA session. Startup users are purple. The Session Host cannot be selected because Host Kick cannot remove the host.") end
        ImGui.Separator()
        local targets=eligible_vote_targets()
        if #targets==0 then
            if startup.subtle_text then startup.subtle_text("No eligible players are currently in this session.") end
        else
            for _,t in ipairs(targets) do
                if t.verified and startup.text_colored then
