    local function render_host_inbox()
        local groups=type(bb.vote_groups)=="table" and bb.vote_groups or {}
        if #groups==0 then
            if startup.subtle_text then startup.subtle_text("No active removal requests.") end
            return
        end
        for i,g in ipairs(groups) do
            ImGui.Separator()
            local title=tostring(g.target_username or "Unknown").." • "..tostring(g.votes or 0).." anonymous vote(s)"
            if g.verified_startup_user==true and startup.text_colored then
                startup.text_colored(0.74,0.45,1.00,1.00,title.." • Startup user")
            elseif startup.text_colored then startup.text_colored(1.00,0.42,0.42,1.00,title) else ImGui.Text(title) end
            if type(g.reasons)=="table" then
                local parts={}
                for _,r in ipairs(g.reasons) do parts[#parts+1]=tostring(r.label or "Other").." x"..tostring(r.count or 1) end
                if #parts>0 and startup.subtle_text_wrapped then startup.subtle_text_wrapped("Reasons: "..table.concat(parts," • ")) end
            end
            if type(g.messages)=="table" then
                for _,msg in ipairs(g.messages) do if tostring(msg or "")~="" and startup.subtle_text_wrapped then startup.subtle_text_wrapped("Anonymous: "..tostring(msg)) end end
            end
            local total=tonumber(g.security_events or 0) or 0
            local confirmed=tonumber(g.confirmed_events or 0) or 0
            if total>0 and startup.subtle_text then startup.subtle_text("Startup evidence: "..tostring(total).." event(s) • "..tostring(confirmed).." confirmed") end
            if ImGui.Button("IGNORE##SB221InboxIgnore"..i,105,26) then startup.browser_host_decide_vote(g,"IGNORE") end
            ImGui.SameLine()
            if ImGui.Button("HOST KICK##SB221InboxKick"..i,125,26) then startup.browser_host_decide_vote(g,"HOST_KICK") end
        end
    end

