    function startup.browser_render_session_safety()
        if not ImGui then return end
        if startup.s.browserSessionSafetyEnabled~=false and header("Session Safety") then
            if startup.browser_render_make_room_control then startup.browser_render_make_room_control() end
            ImGui.Separator()
            local isHost=startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true
            if isHost then
                if startup.subtle_text_wrapped then startup.subtle_text_wrapped("Removal votes are anonymous to the host and never kick automatically. You decide whether to ignore or Host Kick.") end
                render_host_inbox()
            else
                if startup.subtle_text_wrapped then startup.subtle_text_wrapped("Use VOTE beside REPORT to request removal of a player in your current session. The server rejects votes unless both you and the target are in the host's fresh session roster.") end
            end
            if tostring(bb.vote_status or "")~="" and startup.subtle_text_wrapped then startup.subtle_text_wrapped("Status: "..tostring(bb.vote_status)) end
        end

        local blockedCount=#(type(bm.personal_blocks)=="table" and bm.personal_blocks or {})
        if header("Blocked Browser Users ("..tostring(blockedCount)..")") then render_blocked_users() end
        local voteCount=#(type(bm.vote_history)=="table" and bm.vote_history or {})
        if header("Voting History ("..tostring(voteCount)..")") then render_vote_history() end
        local reportCount=#(type(bm.report_history)=="table" and bm.report_history or {})
        if header("Report History ("..tostring(reportCount)..")") then render_report_history() end

        if tostring(bb.startup_uid or "")==tostring(bm.owner_uid or "") and header("Developer Simulation") then
            if startup.text_colored then startup.text_colored(1.00,0.78,0.25,1.00,"LOCAL ONLY • NEVER SENT TO SERVER") end
            if ImGui.Button("ACTIVE##SB221DevActive",80,23) then bm.dev_override_state="ACTIVE" end
            ImGui.SameLine(); if ImGui.Button("WARNED##SB221DevWarned",84,23) then bm.dev_override_state="WARNED" end
            ImGui.SameLine(); if ImGui.Button("SUSPENDED##SB221DevSusp",104,23) then bm.dev_override_state="TEMP_SUSPENDED" end
            ImGui.SameLine(); if ImGui.Button("BANNED##SB221DevBan",80,23) then bm.dev_override_state="BANNED" end
            if ImGui.Button("END SIMULATION##SB221DevClear",170,24) then bm.dev_override_state=""; bm.dev_vote_injected=false end
            ImGui.SameLine()
            if ImGui.Button("SIMULATE ANONYMOUS VOTE##SB221DevVote",220,24) then
                bb.vote_groups={{vote_id="SIM-LOCAL",target_username="Simulation Target",target_player_id=-1,votes=3,reasons={{label="Crash attempts",count=2},{label="Kick attempts",count=1}},messages={"Repeated disruption near the host."},verified_startup_user=true,security_events=2,confirmed_events=1}}
                bm.dev_vote_injected=true
                set_vote_hud("VOTE: Anonymous vote to remove Simulation Target • 3 vote(s)",9000)
            end
            if tostring(bm.dev_override_state or "")~="" and startup.subtle_text then startup.subtle_text("Simulated state: "..tostring(bm.dev_override_state).." • END SIMULATION is always available on restricted screens.") end
        end
    end

    if not bm.history_worker_221 and Script and Script.QueueJob then
        bm.history_worker_221=true
        Script.QueueJob(function()
            while true do
                local now=nowms()
                if bb.token~="" and now>=(tonumber(bm.next_history_ms or 0) or 0) then
                    startup.browser_fetch_history()
                    bm.next_history_ms=nowms()+30000
                end
                if startup.yield then startup.yield(1000) elseif Script and Script.Yield then Script.Yield(1000) end
            end
        end)
    end

    if startup.log then startup.log("[Browser] Build 221 Phase 3.2 | anonymous same-session voting | Vote button | 255-char typing-only messages | private vote/report history | collapsible safety UI") end
end
startup.install_browser_vote_ux_build221()
startup.install_browser_vote_ux_build221 = nil


-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 223: VOTE HUD NIL-GROUP HOTFIX + BUILD 222 SESSION ACTIONS
-- Backend v1.6.1 validates REPORT and BLOCK against the current host's fresh roster.
-- VOTE / REPORT / BLOCK USER are only offered while the selected Browser host is the
-- current GTA Session Host. Manual Browser blocks deliberately override the generic
-- verified-peer exemption, but never the rule that the current Session Host cannot be
-- removed. A Browser block records the target RID locally and uses Startup's existing
-- Nuke Join & Kick path on later non-host rejoins.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.build_number = "2026.08.10.243"
startup.build_date = "2026-08-09"

function startup.install_browser_session_actions_build222()
    startup.browser_backend = startup.browser_backend or {}
    startup.browser_moderation = startup.browser_moderation or {}
    local bb = startup.browser_backend
    local bm = startup.browser_moderation

    local function post(endpoint, fields)
        if not bb._post or bb.token==nil or bb.token=="" then return false,"BACKEND_NOT_CONNECTED",nil end
        local ok, body = bb._post(endpoint, fields or {}, bb.token)
        local data = (ok and bb._json_decode) and bb._json_decode(body) or nil
        if not ok then return false,tostring(body),data end
        if type(data)~="table" or data.ok~=true then
            return false,type(data)=="table" and tostring(data.error or "API_ERROR") or "INVALID_RESPONSE",data
        end
        return true,nil,data
    end

    local function player_exists(pid)
        pid=tonumber(pid)
        if pid==nil or pid<0 or pid>31 or not (Players and Players.GetById) then return false end
        local ok,obj=direct_call(Players.GetById,pid)
        return ok and obj~=nil
    end

    local function player_rid(pid)
        pid=tonumber(pid)
        if pid==nil then return 0 end
        if startup.presence and startup.presence.get_player_rid then
            local ok,v=direct_call(startup.presence.get_player_rid,pid)
            if ok and tonumber(v or 0) and tonumber(v or 0)>0 then return tonumber(v) end
        end
        if Players and Players.GetRockstarId then
            local ok,v=direct_call(Players.GetRockstarId,pid)
            if ok then return tonumber(v or 0) or 0 end
        end
        return 0
    end

    local function current_host_context()
        if not startup.get_session_host_name then return nil end
        local name,pid=startup.get_session_host_name()
        pid=tonumber(pid)
        if pid==nil or pid<0 or pid>31 or not player_exists(pid) then return nil end
        local rid=player_rid(pid)
        if rid<=0 then return nil end
        return {name=tostring(name or "Session Host"),pid=pid,rid=rid}
    end

    local function local_name()
        if startup.get_local_player_id_candidates and startup.get_player_name_safe then
            for _,pid in ipairs(startup.get_local_player_id_candidates()) do
                if startup.is_local_player_id and startup.is_local_player_id(pid) then return tostring(startup.get_player_name_safe(pid) or "") end
            end
        end
        return ""
    end

    function startup.browser_row_is_self(row)
        if type(row)~="table" then return false end
        if tostring(bb.listing_id or "")~="" and tostring(row.listingId or "")==tostring(bb.listing_id) then return true end
        local ctx=current_host_context()
        if ctx and startup.is_local_player_id and startup.is_local_player_id(ctx.pid) then
            local me=local_name()
            return me~="" and tostring(row.username or "")==me
        end
        return false
    end

    function startup.browser_row_in_current_session(row)
        if type(row)~="table" or row.live~=true then return false end
        local ctx=current_host_context()
        if not ctx then return false end
        if startup.browser_row_is_self(row) then return true end
        return tostring(row.username or "")~="" and tostring(row.username or "")==tostring(ctx.name or "")
    end

    function startup.browser_has_current_session_context()
        local ctx=current_host_context()
        if not ctx then return false end
        for _,row in ipairs(type(startup.browser_live_rows)=="table" and startup.browser_live_rows or {}) do
            if startup.browser_row_in_current_session(row) then return true end
        end
        return false
    end

    -- Browser Manual Block is an explicit user decision and therefore is one of the
    -- narrow exceptions to verified-peer automatic-removal suppression.
    if startup.browser_safety and startup.browser_safety.is_manual_exception and not bm._build222_manual_exception then
        bm._build222_manual_exception=true
        local old=startup.browser_safety.is_manual_exception
        startup.browser_safety.is_manual_exception=function(sourceLabel)
            local s=tostring(sourceLabel or "")
            if s:find("Browser Manual Block",1,true) then return true end
            return old(sourceLabel)
        end
    end

    local function manual_block_entry(pid, blockId)
        local rid=player_rid(pid)
        if rid<=0 or not startup.rid_store then return false end
        if startup.rid_store.record then
            startup.rid_store.record(pid,"Browser Manual Block","Browser Manual Block","Nuke Join & Kick",true)
        end
        local key=tostring(math.floor(rid))
        local entry=startup.rid_store.data and startup.rid_store.data[key] or nil
        if type(entry)=="table" then
            entry.flags=type(entry.flags)=="table" and entry.flags or {}
            entry.flags.browserManualBlock=true
            entry.browserBlockId=tonumber(blockId or 0) or 0
            entry.browserBlockSetAt=os.time()
            entry.blockJoin=true
            entry.flags.blockRidJoin=true
            if startup.rid_store.save then startup.rid_store.save() end
            return true
        end
        return false
    end

    local function has_other_block_evidence(entry)
        if type(entry)~="table" then return false end
        local flags=type(entry.flags)=="table" and entry.flags or {}
        if flags.modder==true or flags.crashAttacker==true or flags.kickAttacker==true or flags.battleye==true then return true end
        for _,ev in ipairs(type(entry.events)=="table" and entry.events or {}) do
            local reason=tostring(ev.reason or "")
            if not reason:find("Browser Manual Block",1,true) then
                local event=string.lower(tostring(ev.event or ""))
                if event:find("modder",1,true) or event:find("crash",1,true) or event:find("kick",1,true)
                    or event:find("battleye",1,true) or event:find("nuke",1,true) or event:find("blocked rid join",1,true) then return true end
            end
        end
        return false
    end

    local function clear_manual_block_by_id(blockId)
        blockId=tonumber(blockId or 0) or 0
        if blockId<=0 or not startup.rid_store or type(startup.rid_store.data)~="table" then return false end
        local changed=false
        for _,entry in pairs(startup.rid_store.data) do
            if type(entry)=="table" and tonumber(entry.browserBlockId or 0)==blockId then
                entry.flags=type(entry.flags)=="table" and entry.flags or {}
                entry.flags.browserManualBlock=nil
                entry.browserBlockId=nil
                entry.browserBlockSetAt=nil
                if not has_other_block_evidence(entry) then
                    entry.blockJoin=nil
                    entry.flags.blockRidJoin=nil
                    -- Browser Manual Block may have run through Nuke Join & Kick. If no
                    -- unrelated severe evidence remains, don't leave that Browser-only
                    -- nuke marker enforcing a block after the user explicitly unblocks.
                    entry.flags.nuked=nil
                end
                changed=true
            end
        end
        if changed and startup.rid_store.save then startup.rid_store.save() end
        return changed
    end

    function startup.browser_manual_block_nuke(pid, blockId)
        pid=tonumber(pid)
        if pid==nil or pid<0 or pid>31 or not player_exists(pid) then return false end
        if startup.is_local_player_id and startup.is_local_player_id(pid) then return false end
        manual_block_entry(pid,blockId)
        local _,hostPid=startup.get_session_host_name()
        if tonumber(hostPid)==pid then
            if startup.toast then startup.toast("Browser user blocked. They are Session Host, so Startup will not attempt to remove them; the RID block is armed for future non-host encounters.",6500) end
            return true
        end
        if startup.nuke_join_kick and startup.nuke_join_kick.run_for_player_id then
            return startup.nuke_join_kick.run_for_player_id(pid,true,"Browser Manual Block",false)==true
        end
        return false
    end

    -- Replace Build 221's listing-only Browser block call with a same-session validated
    -- endpoint. The server independently verifies both accounts against the host roster.
    function startup.browser_backend_toggle_block(row)
        if not startup.browser_moderation_allows_access or not startup.browser_moderation_allows_access() then
            if startup.toast then startup.toast("Browser access is restricted by moderation status.",4000) end
            return false
        end
        if type(row)~="table" or row.live~=true or tostring(row.listingId or "")=="" then return false end
        if startup.browser_row_is_self(row) then
            if startup.toast then startup.toast("You cannot block your own Public_Urinal account.",3500) end
            return false
        end
        local action=row.blockedByYou==true and "UNBLOCK" or "BLOCK"
        if action=="BLOCK" and not startup.browser_row_in_current_session(row) then
            if startup.toast then startup.toast("BLOCK USER is available only while that Browser user is in your current session.",4500) end
            return false
        end
        local fields={listing_id=tostring(row.listingId),action=action}
        local ctx=current_host_context()
        if action=="BLOCK" then
            if not ctx then return false end
            fields.session_host_rid=string.format("%.0f",ctx.rid)
        end
        local ok,err,data=post("block.php",fields)
        if not ok then
            local pretty={
                REQUESTER_NOT_IN_HOST_SESSION="Block refused: you are not in the Browser host's current session.",
                TARGET_NOT_IN_HOST_SESSION="Block refused: that Browser user is not in your current session.",
                SESSION_HOST_NOT_BROWSER_ACTIVE="Block unavailable: the current Session Host is not actively publishing Startup Browser.",
                CANNOT_BLOCK_SELF="You cannot block yourself."
            }
            local msg=pretty[err] or ("Block action failed: "..tostring(err))
            if startup.toast then startup.toast(msg,5000) end
            return false
        end
        row.blockedByYou=(data.blocked==true)
        if row.blockedByYou then
            local pid=tonumber(data.target_player_id)
            if pid==nil or pid<0 or pid>31 then
                local host=current_host_context()
                if host and tostring(host.name)==tostring(row.username or "") then pid=host.pid end
            end
            if pid and pid>=0 and pid<=31 then startup.browser_manual_block_nuke(pid,data.block_id) end
            if startup.toast then startup.toast(tostring(row.username or "Startup User").." blocked. Browser JOIN is disabled and Startup's target-specific RID block is armed.",5500) end
        else
            if tonumber(data.block_id or 0)>0 then clear_manual_block_by_id(data.block_id) end
            if startup.toast then startup.toast(tostring(row.username or "Startup User").." unblocked.",3500) end
        end
        bm.next_blocks_ms=0
        if startup.browser_fetch_personal_blocks then startup.browser_fetch_personal_blocks() end
        if startup.browser_backend_fetch_hosts then startup.browser_backend_fetch_hosts() end
        return true
    end

    -- Unblocking from the persistent dropdown also clears the Browser-only local RID
    -- enforcement marker, while preserving unrelated crash/modder/kick evidence.
    if startup.browser_unblock_personal_block and not bm._build222_unblock_wrap then
        bm._build222_unblock_wrap=true
        local oldUnblock=startup.browser_unblock_personal_block
        startup.browser_unblock_personal_block=function(blockId)
            local ok=oldUnblock(blockId)
            if ok then clear_manual_block_by_id(blockId) end
            return ok
        end
    end

    -- Report is now live-session only on both client and server.
    function startup.browser_request_report_popup(row)
        if type(row)~="table" or row.live~=true or tostring(row.listingId or "")=="" then return false end
        if startup.browser_row_is_self(row) then
            if startup.toast then startup.toast("You cannot report yourself.",3500) end
            return false
        end
        if not startup.browser_row_in_current_session(row) then
            if startup.toast then startup.toast("REPORT is available only while that Browser user is in your current session.",4500) end
            return false
        end
        bm.report_target=row
        bm.report_reason="DISRUPTION"
        bm.report_message=""
        bm.report_popup_requested=true
        return true
    end

    function startup.browser_submit_report(row,reasonKey,message)
        if type(row)~="table" or tostring(row.listingId or "")=="" then return false end
        if startup.browser_row_is_self(row) then return false end
        if not startup.browser_row_in_current_session(row) then
            if startup.toast then startup.toast("Report refused: the selected user is no longer in your current Browser session.",4500) end
            return false
        end
        if not startup.browser_terms_accepted or not startup.browser_terms_accepted() then return false end
        if not startup.browser_moderation_allows_access or not startup.browser_moderation_allows_access() then return false end
        local ctx=current_host_context()
        if not ctx then return false end
        local ok,err,data=post("report.php",{
            listing_id=tostring(row.listingId),
            session_host_rid=string.format("%.0f",ctx.rid),
            reason=tostring(reasonKey or "OTHER"),
            message=tostring(message or ""):sub(1,255)
        })
        if not ok then
            local pretty={
                REPORT_REQUIRES_SHARED_SESSION="Report refused: you and the selected user must both be in the current Browser session.",
                REQUESTER_NOT_IN_HOST_SESSION="Report refused: you are not in this Browser session's fresh roster.",
                TARGET_NOT_IN_HOST_SESSION="Report refused: the selected user is no longer in this session.",
                ALREADY_REPORTED_SESSION="You already reported this user in this session.",
                REPORT_SESSION_LIMIT_REACHED="Report limit reached: maximum 3 different users per session.",
                REPORT_DAILY_LIMIT_REACHED="Daily report limit reached. Try again later.",
                REPORT_COOLDOWN="Please wait before submitting another report.",
                CANNOT_REPORT_SELF="You cannot report yourself.",
                HOST_NOT_AVAILABLE="That Browser host is no longer available."
            }
            local msg=pretty[err] or ("Report failed: "..tostring(err))
            if startup.toast then startup.toast(msg,5000) end
            return false
        end
        if startup.toast then startup.toast("Report submitted for moderation: "..tostring(data.target_username or row.username or "Startup User"),4500) end
        if startup.browser_fetch_history then startup.browser_fetch_history() end
        return true
    end

    -- VOTE is already server-side same-session verified. Hide/refuse the UI unless the
    -- current GTA Session Host is one of the live same-edition Browser hosts.
    if startup.browser_request_vote_popup and not bm._build222_vote_gate then
        bm._build222_vote_gate=true
        local oldVotePopup=startup.browser_request_vote_popup
        startup.browser_request_vote_popup=function()
            if not startup.browser_has_current_session_context() then
                if startup.toast then startup.toast("VOTE is available only while you are in an active Startup Browser session.",4500) end
                return false
            end
            return oldVotePopup()
        end
    end

    if startup.log then startup.log("[Browser] Build 223 | Vote HUD nil-group hotfix | VOTE/REPORT/BLOCK same-session only | report spam hardening") end
end
startup.install_browser_session_actions_build222()
startup.install_browser_session_actions_build222=nil


-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 225: REMOVE DUPLICATE SESSION PLAYER POPULATION PANEL
-- Backend v1.7.0 exposes only same-session verified Startup display names/player slots;
-- raw RID/UID/tier data remains private. The HUD count intentionally INCLUDES the local
-- Startup user so "Cherax Users" means the total verified Startup users in the lobby.
-- REPORT is session-wide: verified Startup users are purple, while non-Startup players
-- appear only when Startup currently has an active modder detection for them.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.build_number = "2026.08.09.224"
startup.build_date = "2026-08-09"

function startup.install_browser_build224()
    startup.browser_backend = startup.browser_backend or {}
    startup.browser_moderation = startup.browser_moderation or {}
    local bb = startup.browser_backend
    local bm = startup.browser_moderation
    startup.s.browserSessionSafetyEnabled = true
    bb.session_verified_users = type(bb.session_verified_users)=="table" and bb.session_verified_users or {}
    bb.session_verified_expires_ms = tonumber(bb.session_verified_expires_ms or 0) or 0
    bb.next_session_peers_ms = tonumber(bb.next_session_peers_ms or 0) or 0

    local reportReasons = {
        {key="CRASH_ATTEMPTS",label="Crash attempts"},
        {key="KICK_ATTEMPTS",label="Kick attempts"},
        {key="HARASSMENT",label="Harassment / trolling"},
        {key="DISRUPTION",label="Session disruption"},
        {key="OTHER",label="Other"},
    }

    local function nowms()
        if startup.now then return tonumber(startup.now()) or 0 end
        return math.floor(os.clock()*1000)
    end

    local function post(endpoint,fields)
        if not bb._post or bb.token==nil or bb.token=="" then return false,"BACKEND_NOT_CONNECTED",nil end
        local ok,body=bb._post(endpoint,fields or {},bb.token)
        local data=(ok and bb._json_decode) and bb._json_decode(body) or nil
        if not ok then return false,tostring(body),data end
        if type(data)~="table" or data.ok~=true then
            return false,type(data)=="table" and tostring(data.error or "API_ERROR") or "INVALID_RESPONSE",data
        end
        return true,nil,data
    end

    local function player_exists(pid)
        pid=tonumber(pid)
        if pid==nil or pid<0 or pid>31 or not (Players and Players.GetById) then return false end
        local ok,obj=direct_call(Players.GetById,pid)
        return ok and obj~=nil
    end

    local function player_rid(pid)
        pid=tonumber(pid)
        if pid==nil then return 0 end
        if startup.presence and startup.presence.get_player_rid then
            local ok,v=direct_call(startup.presence.get_player_rid,pid)
            if ok and tonumber(v or 0) and tonumber(v or 0)>0 then return tonumber(v) end
        end
        if Players and Players.GetRockstarId then
            local ok,v=direct_call(Players.GetRockstarId,pid)
            if ok then return tonumber(v or 0) or 0 end
        end
        return 0
    end

    local function current_host_context()
        if not startup.get_session_host_name then return nil end
        local name,pid=startup.get_session_host_name()
        pid=tonumber(pid)
        if pid==nil or pid<0 or pid>31 or not player_exists(pid) then return nil end
        local rid=player_rid(pid)
        if rid<=0 then return nil end
        return {name=tostring(name or "Session Host"),pid=pid,rid=rid}
    end

    local function local_player_id()
        if startup.get_local_player_id_candidates then
            for _,pid in ipairs(startup.get_local_player_id_candidates()) do
                if startup.is_local_player_id and startup.is_local_player_id(pid) and player_exists(pid) then return tonumber(pid) end
            end
        end
        return nil
    end

    local function is_verified_session_user(pid)
        pid=tonumber(pid)
        if pid==nil then return false end
        if startup.is_local_player_id and startup.is_local_player_id(pid) then
            return bb.token~=nil and bb.token~=""
        end
        local row=bb.verified_by_player and bb.verified_by_player[pid] or nil
        if row and nowms()<=(tonumber(row.expires_ms or 0) or 0) then return true end
        if startup.browser_safety and startup.browser_safety.is_verified_peer then
            local ok,v=direct_call(startup.browser_safety.is_verified_peer,pid)
            if ok and v==true then return true end
        end
        return false
    end

    local function current_modder_detection_summary(pid,name)
        local out,seen={},{}
        local function add(v)
            v=tostring(v or ""):gsub("^%s+",""):gsub("%s+$","")
            if v=="" then return end
            local k=v:lower()
            if seen[k] then return end
            seen[k]=true; out[#out+1]=v
        end
        if startup.cherax_modder_reasons_for_player then
            local ok,reasons=direct_call(startup.cherax_modder_reasons_for_player,pid)
            if ok and type(reasons)=="table" then for _,r in ipairs(reasons) do add(r) end end
        end
        if startup.modder_hud and type(startup.modder_hud.entries)=="table" then
            local wanted=tonumber(pid)
            local key=tostring(name or ""):lower()
            local direct=key~="" and startup.modder_hud.entries[key] or nil
            if direct and tonumber(direct.playerId)==wanted then add(direct.reason) end
            for _,entry in pairs(startup.modder_hud.entries) do
                if tonumber(entry and entry.playerId)==wanted then add(entry.reason) end
            end
        end
        if #out==0 then return "" end
        return table.concat(out," | "):sub(1,255)
    end

    function startup.browser_refresh_session_peers()
        if bb.token==nil or bb.token=="" or not startup.browser_terms_accepted or not startup.browser_terms_accepted() then return false end
        local ctx=current_host_context()
        if not ctx then bb.session_verified_users={}; bb.session_verified_expires_ms=0; return false end
        local ok,err,data=post("session-peers.php",{session_host_rid=string.format("%.0f",ctx.rid)})
        if not ok then
            if err~="REQUEST_BUSY" then bb.session_peers_status=tostring(err) end
            return false
        end
        local users=type(data.users)=="table" and data.users or {}
        bb.session_verified_users=users
        bb.session_verified_expires_ms=nowms()+35000
        bb.session_peers_status="Ready"
        bb.verified_by_player=bb.verified_by_player or {}
        for _,u in ipairs(users) do
            local pid=tonumber(u and u.player_id)
            if pid and pid>=0 and pid<=31 then
                bb.verified_by_player[pid]={username=tostring(u.username or "Startup User"),expires_ms=nowms()+35000}
            end
        end
        return true
    end

    function startup.browser_current_verified_session_names()
        local byKey={}
        local ordered={}
        local host=current_host_context()
        local function add(name,pid,isHost)
            pid=tonumber(pid)
            if pid==nil or pid<0 or pid>31 or not player_exists(pid) then return end
            name=tostring(name or "")
            if name=="" and startup.get_player_name_safe then name=tostring(startup.get_player_name_safe(pid) or "") end
            if name=="" then return end
            local key=name:lower()
            if byKey[key] then
                if isHost then byKey[key].isHost=true end
                return
            end
            local row={name=name,pid=pid,isHost=isHost==true}
            byKey[key]=row; ordered[#ordered+1]=row
        end

        if nowms()<=(tonumber(bb.session_verified_expires_ms or 0) or 0) then
            for _,u in ipairs(type(bb.session_verified_users)=="table" and bb.session_verified_users or {}) do
                add(u.username,u.player_id,u.is_host==true)
            end
        end

        -- Local account is intentionally counted. Otherwise "Cherax Users: 2" would
        -- mean two *other* users while the label says total users, which is ambiguous.
        local me=local_player_id()
        if me~=nil and bb.token~=nil and bb.token~="" then
            add(startup.get_player_name_safe and startup.get_player_name_safe(me) or "You",me,host and host.pid==me)
        end

        -- Merge fast local proof so the HUD can update between server peer refreshes.
        for pid=0,31 do
            if player_exists(pid) and not (startup.is_local_player_id and startup.is_local_player_id(pid)) and is_verified_session_user(pid) then
                add(startup.get_player_name_safe and startup.get_player_name_safe(pid) or ("Player "..tostring(pid)),pid,host and host.pid==pid)
            end
        end

        table.sort(ordered,function(a,b)
            if a.isHost~=b.isHost then return a.isHost end
            return tostring(a.name):lower()<tostring(b.name):lower()
        end)
        local names={}
        for _,r in ipairs(ordered) do names[#names+1]=r.name end
        return names
    end

    -- Keep the Browser row + HUD synchronized with the total verified users physically
    -- in the current lobby. This also updates the right-side CHERAX list.
    if startup.browser_get_hud_row and not bm._build224_hud_wrap then
        bm._build224_hud_wrap=true
        local oldHudRow=startup.browser_get_hud_row
        startup.browser_get_hud_row=function()
            local row=oldHudRow()
            if type(row)=="table" and row.__startup_hover_preview~=true then
                local names=startup.browser_current_verified_session_names()
                if #names>0 then row.cheraxNames=names end
            end
            return row
        end
    end

    local function update_current_live_row_names()
        local ctx=current_host_context()
        if not ctx then return end
        local names=startup.browser_current_verified_session_names()
        if #names==0 then return end
        for _,row in ipairs(type(startup.browser_live_rows)=="table" and startup.browser_live_rows or {}) do
            if type(row)=="table" and tostring(row.username or ""):lower()==tostring(ctx.name or ""):lower() then
                row.cheraxNames=names
            end
        end
    end

    local function eligible_report_targets()
        local out={}
        for pid=0,31 do
            if player_exists(pid) and not (startup.is_local_player_id and startup.is_local_player_id(pid)) then
                local rid=player_rid(pid)
                if rid>0 then
                    local name=tostring(startup.get_player_name_safe and startup.get_player_name_safe(pid) or ("Player "..tostring(pid)))
                    local verified=is_verified_session_user(pid)
                    local detection=verified and "" or current_modder_detection_summary(pid,name)
                    if verified or detection~="" then
                        out[#out+1]={
                            pid=pid,rid=rid,name=name,verified=verified,
                            kind=verified and "STARTUP_USER" or "DETECTED_MODDER",
                            detection_summary=detection
                        }
                    end
                end
            end
        end
        table.sort(out,function(a,b)
            if a.verified~=b.verified then return a.verified end
            return tostring(a.name):lower()<tostring(b.name):lower()
        end)
        return out
    end

    local function typing_only_input(label,value)
        local old=tostring(value or "")
        local new,changed=ImGui.InputText(label,old,256)
        new=tostring(new or old):sub(1,255)
        if changed==true and #new>#old then
            local pasted=(#new-#old)>1
            if not pasted and ImGui.GetClipboardText then
                local ok,clip=direct_call(ImGui.GetClipboardText)
                clip=ok and tostring(clip or "") or ""
                if #clip>1 and new:find(clip,1,true) and not old:find(clip,1,true) then pasted=true end
            end
            if pasted then bm.input_notice="Pasting is disabled. Please type the optional message."; return old end
        end
        if changed==true then bm.input_notice="" end
        return new
    end

    local function draw_reason_options(current)
        for _,r in ipairs(reportReasons) do
            if ImGui.Selectable(r.label.."##SB224ReportReason"..r.key,current==r.key) then current=r.key end
        end
        return current
    end

    function startup.browser_request_report_popup(_row)
        if not startup.browser_has_current_session_context or not startup.browser_has_current_session_context() then
            if startup.toast then startup.toast("REPORT is available only while you are in an active Startup Browser session.",4500) end
            return false
        end
        if not startup.browser_moderation_allows_access or not startup.browser_moderation_allows_access() then
            if startup.toast then startup.toast("Startup Browser reporting is unavailable while access is restricted.",4000) end
            return false
        end
        bm.report_target_224=nil
        bm.report_reason_224="DISRUPTION"
        bm.report_message_224=""
        bm.report_select_224_requested=true
        bm.report_popup_requested=false
        return true
    end

    function startup.browser_submit_report_target_224(target,reasonKey,message)
        if type(target)~="table" then return false end
        if not startup.browser_has_current_session_context or not startup.browser_has_current_session_context() then return false end
        local ctx=current_host_context()
        if not ctx then return false end
        local pid=tonumber(target.pid)
        if pid==nil or not player_exists(pid) then return false end
        local liveRid=player_rid(pid)
        if liveRid<=0 or math.floor(liveRid)~=math.floor(tonumber(target.rid or 0) or 0) then
            if startup.toast then startup.toast("Report refused: target identity changed or left the session.",4500) end
            return false
        end
        local kind=is_verified_session_user(pid) and "STARTUP_USER" or "DETECTED_MODDER"
        local detection=kind=="DETECTED_MODDER" and current_modder_detection_summary(pid,target.name) or ""
        if kind=="DETECTED_MODDER" and detection=="" then
            if startup.toast then startup.toast("Report refused: Startup no longer detects this non-Startup player as a modder.",5000) end
            return false
        end
        local ok,err,data=post("report.php",{
            session_host_rid=string.format("%.0f",ctx.rid),
            target_rid=string.format("%.0f",liveRid),
            target_player_id=tostring(pid),
            target_kind=kind,
            detection_summary=detection,
            reason=tostring(reasonKey or "OTHER"),
            message=tostring(message or ""):sub(1,255)
        })
        if not ok then
            local pretty={
                REQUESTER_NOT_IN_HOST_SESSION="Report refused: you are not in this Browser session's fresh roster.",
                TARGET_NOT_IN_HOST_SESSION="Report refused: that player is no longer in this session.",
                ALREADY_REPORTED_SESSION="You already reported this player in this session.",
                ALREADY_REPORTED_TARGET_24H="You already reported this player within the last 24 hours.",
                REPORT_SESSION_LIMIT_REACHED="Report limit reached: maximum 3 different users per session.",
                REPORT_DAILY_LIMIT_REACHED="Daily report limit reached. Try again later.",
                REPORT_COOLDOWN="Please wait before submitting another report.",
                CANNOT_REPORT_SELF="You cannot report yourself.",
                NON_STARTUP_REPORT_REQUIRES_DETECTION="Non-Startup players can only be reported when Startup currently detects them as a modder.",
                DETECTION_EVIDENCE_REQUIRED="Startup modder detection evidence is required for that non-Startup player.",
                SESSION_HOST_NOT_BROWSER_ACTIVE="Reporting requires an actively published Startup Browser session."
            }
            if startup.toast then startup.toast(pretty[err] or ("Report failed: "..tostring(err)),5500) end
            return false
        end
        local suffix=tostring(data.target_kind or kind)=="DETECTED_MODDER" and " (detected modder)" or ""
        if startup.toast then startup.toast("Report submitted for moderation: "..tostring(data.target_username or target.name or "Player")..suffix,4500) end
        if startup.browser_fetch_history then startup.browser_fetch_history() end
        return true
    end

    local function render_report_select_popup()
        local popup="Report - Select Player##SB224ReportSelect"
        if bm.report_select_224_requested then direct_call(ImGui.OpenPopup,popup); bm.report_select_224_requested=false end
        local flags=(ImGuiWindowFlags and ImGuiWindowFlags.AlwaysAutoResize) or nil
        local visible=false
        direct_call(function() visible=ImGui.BeginPopupModal(popup,true,flags)==true end)
        if not visible then return end
        if startup.text_colored then startup.text_colored(1.00,0.28,0.28,1.00,"REPORT PLAYER") end
        if startup.subtle_text_wrapped then startup.subtle_text_wrapped("Only players in your current Browser session are shown. Verified Startup users are purple. Non-Startup players appear only when Startup currently detects them as a modder.") end
        ImGui.Separator()
        local targets=eligible_report_targets()
        if #targets==0 then
            if startup.subtle_text_wrapped then startup.subtle_text_wrapped("No eligible report targets right now. Normal non-Startup players are intentionally not reportable.") end
        else
            for _,t in ipairs(targets) do
                if t.verified and startup.text_colored then
                    startup.text_colored(0.74,0.45,1.00,1.00,t.name)
                    if ImGui.IsItemClicked and ImGui.IsItemClicked() then
                        bm.report_target_224=t; bm.report_reason_224="DISRUPTION"; bm.report_message_224=""
                        if ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end
                        bm.report_reason_224_requested=true
                    end
                else
                    startup.text_colored(1.00,0.28,0.30,1.00,t.name.."  •  DETECTED MODDER")
                    if ImGui.IsItemClicked and ImGui.IsItemClicked() then
                        bm.report_target_224=t; bm.report_reason_224="DISRUPTION"; bm.report_message_224=""
                        if ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end
                        bm.report_reason_224_requested=true
                    end
                    if startup.subtle_text_wrapped then startup.subtle_text_wrapped("Detection: "..tostring(t.detection_summary or "Modder detection")) end
                end
            end
        end
        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
        if ImGui.Button("CANCEL##SB224ReportSelectCancel",120,28) and ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end
        direct_call(ImGui.EndPopup)
    end

    local function render_report_reason_popup()
        local popup="Why do you want to report this player?##SB224ReportReasonPopup"
        if bm.report_reason_224_requested then direct_call(ImGui.OpenPopup,popup); bm.report_reason_224_requested=false end
        local flags=(ImGuiWindowFlags and ImGuiWindowFlags.AlwaysAutoResize) or nil
        local visible=false
        direct_call(function() visible=ImGui.BeginPopupModal(popup,true,flags)==true end)
        if not visible then return end
        local t=bm.report_target_224
        if startup.text_colored then startup.text_colored(1.00,0.28,0.28,1.00,"REPORT") end
        if startup.subtle_text then startup.subtle_text("Reporting") end
        if t and t.verified and startup.text_colored then
            startup.text_colored(0.74,0.45,1.00,1.00,tostring(t.name or "Startup User"))
        elseif t and startup.text_colored then
            startup.text_colored(1.00,0.28,0.30,1.00,tostring(t.name or "Detected Modder").."  •  DETECTED MODDER")
        end
        if startup.subtle_text_wrapped then startup.subtle_text_wrapped("Reports are accusations, not proof. One report per target per session is allowed, and the same target cannot be reported again by you for 24 hours.") end
        ImGui.Separator()
        bm.report_reason_224=draw_reason_options(tostring(bm.report_reason_224 or "DISRUPTION"))
        ImGui.Spacing()
        if startup.subtle_text then startup.subtle_text("Optional message • 255 characters max • typing only") end
        bm.report_message_224=typing_only_input("##SB224ReportMessage",bm.report_message_224)
        if startup.subtle_text then startup.subtle_text(tostring(#tostring(bm.report_message_224 or "")).." / 255") end
        if tostring(bm.input_notice or "")~="" and startup.text_colored then startup.text_colored(1.00,0.72,0.18,1.00,bm.input_notice) end
        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
        if ImGui.Button("BACK##SB224ReportBack",110,28) then
            if ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end
            bm.report_select_224_requested=true
        end
        ImGui.SameLine()
        if ImGui.Button("SUBMIT REPORT##SB224ReportSubmit",180,28) then
            local sent=startup.browser_submit_report_target_224(t,bm.report_reason_224,bm.report_message_224)
            if sent and ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end
        end
        direct_call(ImGui.EndPopup)
    end

    if startup.browser_render_vote_popups and not bm._build224_popup_wrap then
        bm._build224_popup_wrap=true
        local oldPopups=startup.browser_render_vote_popups
        startup.browser_render_vote_popups=function()
            oldPopups()
            render_report_select_popup()
            render_report_reason_popup()
        end
    end

    if not bm._build224_peer_worker and Script and Script.QueueJob then
        bm._build224_peer_worker=true
        Script.QueueJob(function()
            while true do
                local now=nowms()
                if bb.token~=nil and bb.token~="" and now>=(tonumber(bb.next_session_peers_ms or 0) or 0) then
                    startup.browser_refresh_session_peers()
                    update_current_live_row_names()
                    bb.next_session_peers_ms=nowms()+15000
                else
                    update_current_live_row_names()
                end
                if startup.yield then startup.yield(1000) elseif Script and Script.Yield then Script.Yield(1000) end
            end
        end)
    end

    if startup.log then startup.log("[Browser] Build 225 | Session Player Population panel removed; guidance remains in Guide | verified-user HUD + session reporting retained") end
end
startup.install_browser_build224()
startup.install_browser_build224=nil


-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 227: MANDATORY EVERY-JOIN POLICY NOTICE / RELEASE CANDIDATE 1
-- - Server-controlled Browser maintenance switch with a friendly maintenance screen.
-- - Preserve selected live listing across refreshes and de-duplicate accidental rows.
-- - Clear session-only peer/vote HUD state immediately on GTA session changes.
-- - Browser-specific release logging without raw RID / Cherax UID / network identifiers.
-- - Client-side maintenance gates mirror authoritative server enforcement.
-- - Existing JOIN, voting, reporting, blocklist, edition isolation and moderation rules
--   remain unchanged.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.build_number = "2026.08.09.226"
startup.build_date = "2026-08-09"

function startup.install_browser_production_hardening_build226()
    startup.browser_backend = startup.browser_backend or {}
    startup.browser_hardening = startup.browser_hardening or {}
    local bb = startup.browser_backend
    local bh = startup.browser_hardening

    bh.service_enabled = bh.service_enabled ~= false
    bh.service_message = tostring(bh.service_message or "")
    bh.service_status = tostring(bh.service_status or "CHECKING")
    bh.next_service_ms = tonumber(bh.next_service_ms or 0) or 0
    bh.last_service_ok_ms = tonumber(bh.last_service_ok_ms or 0) or 0
    bh.log_last = bh.log_last or {}
    bh.last_monitor_status = tostring(bh.last_monitor_status or "")
    bh.last_monitor_token = tostring(bh.last_monitor_token or "")
    bh.last_monitor_published = bh.last_monitor_published == true
    bh.last_monitor_live = tonumber(bh.last_monitor_live or -1) or -1
    bh.session_epoch = tonumber(bh.session_epoch or 0) or 0

    local function nowms()
        if startup.now then return tonumber(startup.now()) or 0 end
        return math.floor(os.clock()*1000)
    end

    local function blog(key,text,cooldown)
        key=tostring(key or "event")
        local now=nowms()
        local last=tonumber(bh.log_last[key] or 0) or 0
        cooldown=tonumber(cooldown or 0) or 0
        if cooldown>0 and now-last<cooldown then return end
        bh.log_last[key]=now
        if startup.log then startup.log("[Browser RC1] "..tostring(text or key)) end
    end

    function startup.browser_service_available()
        return bh.service_enabled ~= false
    end

    function startup.browser_poll_service()
        if not bb._post then return false end
        local ok,body=bb._post("service.php",{},nil)
        if not ok then
            bh.service_status="UNREACHABLE"
            blog("service_unreachable","Service-status check unavailable; retaining last known Browser service state.",30000)
            return false
        end
        local data=bb._json_decode and bb._json_decode(body) or nil
        if type(data)~="table" or data.ok~=true then
            bh.service_status="INVALID_RESPONSE"
            blog("service_invalid","Service-status endpoint returned an invalid response; retaining last known state.",30000)
            return false
        end
        local previous=bh.service_enabled ~= false
        bh.service_enabled=data.browser_enabled ~= false
        bh.service_message=tostring(data.message or "")
        bh.service_status=bh.service_enabled and "AVAILABLE" or "MAINTENANCE"
        bh.last_service_ok_ms=nowms()
        if previous~=bh.service_enabled then
            if bh.service_enabled then
                blog("service_on","Browser service is available again.")
                bb.next_heartbeat_ms=0; bb.next_fetch_ms=0
            else
                blog("service_off","Browser service entered maintenance mode.")
                if bb.published and startup.browser_backend_offline then direct_call(startup.browser_backend_offline) end
                bb.published=false; bb.listing_id=""; bb.live_count=0
                if startup.browser_set_live_hosts then startup.browser_set_live_hosts({}) end
            end
        end
        return true
    end

    -- Preserve the user's selected host across a normal 10-second feed refresh. The
    -- backend already prevents duplicate host rows, but the client also de-duplicates
    -- defensively so a malformed response cannot produce duplicate UI entries.
    if startup.browser_set_live_hosts and not bh._wrapped_live_hosts then
        bh._wrapped_live_hosts=true
        local oldSet=startup.browser_set_live_hosts
        startup.browser_set_live_hosts=function(hosts)
            local selectedId=""
            if startup.browser_get_selected_row then
                local ok,row=direct_call(startup.browser_get_selected_row,false)
                if ok and type(row)=="table" then selectedId=tostring(row.listingId or "") end
            end
            local clean,seen={},{}
            local removed=0
            for _,h in ipairs(type(hosts)=="table" and hosts or {}) do
                local lid=tostring(h and (h.listing_id or h.listingId) or "")
                local key=lid~="" and ("L|"..lid) or ("U|"..tostring(h and h.username or "").."|"..tostring(h and h.country or h and h.country_code or ""))
                if not seen[key] then seen[key]=true; clean[#clean+1]=h else removed=removed+1 end
            end
            oldSet(clean)
            if selectedId~="" and startup.browser_select_listing then
                local kept=startup.browser_select_listing(selectedId)
                if not kept then blog("selection_expired","Selected Browser host disappeared from the live feed; selection was reset.",5000) end
            end
            if removed>0 then blog("dedup","Dropped "..tostring(removed).." duplicate Browser host row(s) from one response.",10000) end
        end
    end

    -- Authoritative server maintenance is mirrored locally to avoid pointless requests.
    if startup.browser_should_publish_local_host and not bh._wrapped_publish_gate then
        bh._wrapped_publish_gate=true
        local old=startup.browser_should_publish_local_host
        startup.browser_should_publish_local_host=function()
            if bh.service_enabled==false then return false end
            return old()
        end
    end
    if startup.browser_backend_heartbeat and not bh._wrapped_heartbeat then
        bh._wrapped_heartbeat=true
        local old=startup.browser_backend_heartbeat
        startup.browser_backend_heartbeat=function()
            if bh.service_enabled==false then
                if bb.published and startup.browser_backend_offline then direct_call(startup.browser_backend_offline) end
                bb.published=false; bb.listing_id=""; bb.status="BROWSER MAINTENANCE"
                return false
            end
            return old()
        end
    end
    if startup.browser_backend_fetch_hosts and not bh._wrapped_fetch then
        bh._wrapped_fetch=true
        local old=startup.browser_backend_fetch_hosts
        startup.browser_backend_fetch_hosts=function()
            if bh.service_enabled==false then
                bb.live_count=0
                if startup.browser_set_live_hosts then startup.browser_set_live_hosts({}) end
                return false
            end
            return old()
        end
    end

    local function maintenance_refusal(action)
        local msg=bh.service_message~="" and bh.service_message or "Startup Browser is temporarily unavailable for maintenance."
        if startup.toast then startup.toast(tostring(action or "Browser action").." unavailable: "..msg,5000) end
        return false
    end

    if startup.browser_execute_join and not bh._wrapped_join then
        bh._wrapped_join=true
        local old=startup.browser_execute_join
        startup.browser_execute_join=function(row)
            if bh.service_enabled==false then return maintenance_refusal("JOIN") end
            local name=type(row)=="table" and tostring(row.username or "host") or "host"
            local ok=old(row)
            if ok then blog("join_request","JOIN requested for "..name..".",1000) end
            return ok
        end
    end
    if startup.browser_submit_removal_vote and not bh._wrapped_vote then
        bh._wrapped_vote=true
        local old=startup.browser_submit_removal_vote
        startup.browser_submit_removal_vote=function(...)
            if bh.service_enabled==false then return maintenance_refusal("VOTE") end
            local ok=old(...)
            if ok then blog("vote_submit","Removal vote submitted to the current Session Host.",1000) end
            return ok
        end
    end
    if startup.browser_submit_report_target_224 and not bh._wrapped_report then
        bh._wrapped_report=true
        local old=startup.browser_submit_report_target_224
        startup.browser_submit_report_target_224=function(target,...)
            if bh.service_enabled==false then return maintenance_refusal("REPORT") end
            local name=type(target)=="table" and tostring(target.name or "player") or "player"
            local ok=old(target,...)
            if ok then blog("report_submit","Report submitted for "..name..".",1000) end
            return ok
        end
    end
    if startup.browser_backend_toggle_block and not bh._wrapped_block then
        bh._wrapped_block=true
        local old=startup.browser_backend_toggle_block
        startup.browser_backend_toggle_block=function(row)
            if bh.service_enabled==false then return maintenance_refusal("BLOCK USER") end
            local before=type(row)=="table" and row.blockedByYou==true
            local ok=old(row)
            if ok then blog("block_change",before and "Browser user unblocked." or "Browser user blocked.",1000) end
            return ok
        end
    end
    if startup.browser_host_decide_vote and not bh._wrapped_vote_decision then
        bh._wrapped_vote_decision=true
        local old=startup.browser_host_decide_vote
        startup.browser_host_decide_vote=function(group,decision)
            if bh.service_enabled==false then return maintenance_refusal("VOTE DECISION") end
            local ok=old(group,decision)
            if ok then blog("vote_decision","Session Host recorded removal decision: "..tostring(decision or "IGNORE")..".",1000) end
            return ok
        end
    end

    -- A session transition invalidates every session-only proof immediately. Do not clear
    -- join_pending here: a legitimate Browser JOIN itself causes a session transition and
    -- the JOIN watcher still needs to confirm arrival after that transition.
    local function reset_session_only_state()
        bh.session_epoch=bh.session_epoch+1
        bb.session_verified_users={}
        bb.session_verified_expires_ms=0
        bb.next_session_peers_ms=0
        bb.verified_by_player={}
        bb.vote_groups={}
        bb.next_vote_poll_ms=0
        if startup.browser_vote_hud then startup.browser_vote_hud.text=""; startup.browser_vote_hud.until_ms=0 end
        if startup.browser_select_listing then startup.browser_select_listing("") end
        blog("session_reset","Session-only Browser caches cleared after GTA session change.",1000)
    end
    startup.browser_reset_session_only_state_rc1=reset_session_only_state
    if EventMgr and eLuaEvent and eLuaEvent.ON_SESSION_CHANGE and not bh._session_reset_handler then
        bh._session_reset_handler=true
        EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE,function()
            reset_session_only_state()
        end)
    end

    -- Friendly maintenance screen. Account enrollment and Config account information stay
    -- available; only Browser functionality is paused.
    if startup.render_browser and not bh._wrapped_render then
        bh._wrapped_render=true
        local old=startup.render_browser
        startup.render_browser=function()
            if bh.service_enabled==false then
                if startup.text_colored then startup.text_colored(0.72,0.42,1.00,1.00,"STARTUP BROWSER") else ImGui.Text("STARTUP BROWSER") end
                ImGui.Separator(); ImGui.Spacing()
                if startup.text_colored then startup.text_colored(1.00,0.28,0.28,1.00,"TEMPORARILY UNAVAILABLE") else ImGui.Text("TEMPORARILY UNAVAILABLE") end
                if startup.subtle_text_wrapped then
                    startup.subtle_text_wrapped(bh.service_message~="" and bh.service_message or "Startup Browser is temporarily unavailable for maintenance. Startup itself will continue working normally.")
                    startup.subtle_text_wrapped("Your Public_Urinal account remains connected. Host publishing, browsing, JOIN, VOTE, REPORT, and Browser block changes are paused until service is restored.")
                end
                return
            end
            return old()
        end
    end

    -- One quiet monitor gives support useful state transitions without identifiers that
    -- should remain private. It intentionally does not log RID, Cherax UID, PU UID or IP.
    if not bh._worker and Script and Script.QueueJob then
        bh._worker=true
        Script.QueueJob(function()
            while true do
                local now=nowms()
                if now>=(tonumber(bh.next_service_ms or 0) or 0) and bb.request_busy~=true then
                    startup.browser_poll_service()
                    bh.next_service_ms=nowms()+60000
                end

                local tokenNow=tostring(bb.token or "")
                if bh.last_monitor_token=="" and tokenNow~="" then blog("authenticated","Authenticated with Public_Urinal online services.") end
                if bh.last_monitor_token~="" and tokenNow=="" then blog("auth_lost","Online-services token cleared; Startup will re-authenticate automatically.",5000) end
                bh.last_monitor_token=tokenNow

                local published=bb.published==true
                if published~=bh.last_monitor_published then
                    blog("publish_state",published and "Browser host listing published." or "Browser host listing stopped.",1000)
                    bh.last_monitor_published=published
                end

                local live=tonumber(bb.live_count or 0) or 0
                if live~=bh.last_monitor_live then
                    -- Build 299: keep monitor state current without logging every
                    -- routine Browser host-count fluctuation.
                    bh.last_monitor_live=live
                end

                local st=tostring(bb.status or "")
                if st~=bh.last_monitor_status then
                    if st:find("JOIN SUCCESS",1,true) then blog("join_success","JOIN completed successfully.")
                    elseif st:find("JOIN TIMEOUT",1,true) then blog("join_timeout","JOIN attempt timed out.")
                    elseif st:find("JOIN FAILED",1,true) or st:find("JOIN REQUEST FAILED",1,true) then blog("join_failed","JOIN attempt failed: "..st,3000)
                    end
                    bh.last_monitor_status=st
                end

                if startup.yield then startup.yield(1000) elseif Script and Script.Yield then Script.Yield(1000) end
            end
        end)
    end

    blog("loaded","Build 227 RC1 loaded | mandatory every-JOIN policy notice + maintenance switch + stale-state cleanup + feed de-dup + release logging")
end
startup.install_browser_production_hardening_build226()
startup.install_browser_production_hardening_build226=nil

