    function startup.browser_ui_asset_path(key)
        local rel = startup.browser_ui_assets and startup.browser_ui_assets[key]
        if not rel and type(key)=="string" then
            local cc=key:match("^flag_([a-z][a-z])$")
            if cc then rel="flags\\"..cc..".png" end
        end
        if not rel then return nil end
        return tostring(startup.browser_ui_asset_root or asset_base) .. "\\" .. tostring(rel)
    end

    function startup.browser_ui_texture(key)
        if not Texture then return nil end
        startup.browser_ui_texture_cache = startup.browser_ui_texture_cache or {}
        local state = startup.browser_ui_texture_cache[key]
        if type(state)~="table" then state={}; startup.browser_ui_texture_cache[key]=state end
        if state.srv then return state.srv end

        local path = startup.browser_ui_asset_path(key)
        if not path then return nil end

        -- Build 294: missing files are normal during first-run asset repair.
        -- Do not invoke Cherax texture loading until the path exists.
        if FileMgr and FileMgr.DoesFileExist and FileMgr.DoesFileExist(path) ~= true then
            state.id=nil
            state.srv=nil
            return nil
        end

        local now = startup.now and startup.now() or math.floor(os.clock()*1000)
        state.last_try = tonumber(state.last_try or 0) or 0
        state.requested = tonumber(state.requested or 0) or 0

        if not state.id then
            if now-state.last_try < 500 then return nil end
            state.last_try=now
            local ok=false
            local texture_id=nil
            -- Startup's existing popup logo uses the synchronous loader first; it is
            -- the most reliable Cherax path. Async remains a fallback.
            if Texture.LoadTexture then
                ok,texture_id=direct_call(Texture.LoadTexture,path)
            end
            if (not ok or not tonumber(texture_id) or tonumber(texture_id)==0) and Texture.LoadTextureAsync then
                ok,texture_id=direct_call(Texture.LoadTextureAsync,path)
            end
            texture_id=tonumber(texture_id or 0) or 0
            if not ok or texture_id==0 then
                state.id=nil
                return nil
            end
            state.id=texture_id
            state.requested=now
        end

        local texture_id=tonumber(state.id or 0) or 0
        if texture_id==0 then return nil end
        if Texture.IsTextureValid then
            local ok_valid,valid=direct_call(Texture.IsTextureValid,texture_id)
            if ok_valid and valid~=true then
                -- Do not throw away an async allocation immediately. Give Cherax time
                -- to finish the texture, then retry from scratch if it never becomes valid.
                if now-state.requested > 3000 then state.id=nil; state.requested=0 end
                return nil
            end
        end

        local texture=nil
        if Texture.GetTexture then
            local ok_tex,v=direct_call(Texture.GetTexture,texture_id)
            if ok_tex then texture=v end
        end
        if not texture then
            if now-state.requested > 3000 then state.id=nil; state.requested=0 end
            return nil
        end

        -- Cherax Texture.GetTexture() returns a texture wrapper. ImGui needs the
        -- current shader-resource-view, exactly like Startup's proven intro logo code.
        local srv=nil
        if type(texture)=="table" or type(texture)=="userdata" then
            local ok_current=false
            if texture.GetCurrent then ok_current,srv=direct_call(function() return texture:GetCurrent() end) end
            if not ok_current then srv=nil end
        end
        if not srv then
            -- Compatibility fallback for Cherax builds where GetTexture already yields
            -- the object accepted by AddImage.
            srv=texture
        end
        if not srv then return nil end

        state.srv=srv
        state.path=path
        -- Build 291: asset loads are intentionally silent. Hundreds of successful
        -- texture loads add no diagnostic value and previously flooded Cherax.log.
        state.logged=true
        return srv
    end

    function startup.browser_ui_draw(key,width,height,rounding)
        if not ImGui or not ImGui.GetCursorScreenPos then return false end
        local srv=startup.browser_ui_texture(key)
        if not srv then return false end
        local first,second=ImGui.GetCursorScreenPos()
        local x,y=0,0
        if startup.unpack_imgui_point then x,y=startup.unpack_imgui_point(first,second)
        elseif type(first)=="number" then x,y=tonumber(first) or 0,tonumber(second) or 0
        elseif type(first)=="table" then x=tonumber(first.x or first.X or first[1] or 0) or 0; y=tonumber(first.y or first.Y or first[2] or 0) or 0 end
        width=tonumber(width or 180) or 180
        height=tonumber(height or 45) or 45
        if x<=0 or y<=0 then return false end

        -- Reserve the layout item first, then paint the texture over the reservation.
        if ImGui.Dummy then direct_call(ImGui.Dummy,width,height) end
        if ImGui.AddImage then
            local ok=direct_call(ImGui.AddImage,srv,x,y,x+width,y+height)
            if ok then return true end
        end
        if ImGui.AddImageRounded then
            local ok=direct_call(ImGui.AddImageRounded,srv,x,y,x+width,y+height,0.0,0.0,1.0,1.0,0xFFFFFFFF,tonumber(rounding or 6) or 6)
            if ok then return true end
        end
        return false
    end

