    local function avail_width(default)
        if ImGui.GetContentRegionAvail then
            local ok,v=direct_call(ImGui.GetContentRegionAvail)
            if ok and type(v)=="number" then return v end
            if ok and type(v)=="table" and tonumber(v.x) then return tonumber(v.x) end
        end
        return default or 900
    end
    local function child_no_scroll_flags()
