        if ImGuiWindowFlags then
            f=(ImGuiWindowFlags.NoScrollbar or 0)+(ImGuiWindowFlags.NoScrollWithMouse or 0)
        end
        return f
    end
    local function clamp_percent(v)
        v=tonumber(v or 0) or 0
        if v<0 then return 0 end
        if v>100 then return 100 end
        return v
    end
    local function metric_color(v)
        v=clamp_percent(v)
        if v>=90 then return 60,235,100 end
        if v>=75 then return 70,200,255 end
        if v>=60 then return 255,190,55 end
        return 255,72,78
    end
    local function reliability_label(v)
        v=clamp_percent(v)
        if v>=95 then return "VERY RELIABLE" end
        if v>=85 then return "RELIABLE" end
        if v>=70 then return "MIXED" end
        return "LOW RELIABILITY"
    end
    local function reputation_label(v)
        v=clamp_percent(v)
        if v>=95 then return "VERY POSITIVE" end
        if v>=85 then return "POSITIVE" end
        if v>=70 then return "MIXED" end
        return "POOR"
    end
    local function draw_metric_ring(percent,size,caption)
        size=tonumber(size or 100) or 100
        percent=clamp_percent(percent)
        local first,second=ImGui.GetCursorScreenPos()
        local x,y
        if type(first)=="table" then x=tonumber(first.x or first[1] or 0) or 0; y=tonumber(first.y or first[2] or 0) or 0 else x=tonumber(first or 0) or 0; y=tonumber(second or 0) or 0 end
        local aw=avail_width(size)
        local original_cursor_x=ImGui.GetCursorPosX and ImGui.GetCursorPosX() or nil
        if aw>size+4 and ImGui.GetCursorPosX and ImGui.SetCursorPosX then
            local cxp=original_cursor_x or ImGui.GetCursorPosX()
            local shift=math.max(0,(aw-size)*0.5)
            ImGui.SetCursorPosX(cxp+shift)
            first,second=ImGui.GetCursorScreenPos()
            if type(first)=="table" then x=tonumber(first.x or first[1] or 0) or 0; y=tonumber(first.y or first[2] or 0) or 0 else x=tonumber(first or 0) or 0; y=tonumber(second or 0) or 0 end
        end
        local cx=x+size*0.5; local cy=y+size*0.5; local radius=size*0.5-7
        local r,g,b=metric_color(percent)
        if ImGui.AddCircle then
            ImGui.AddCircle(cx,cy,radius,45,50,66,255,64,7.0)
            local segs=64
            local active=math.floor(segs*(percent/100)+0.5)
            local start=-math.pi*0.5
            local step=(math.pi*2)/segs
            for i=0,active-1 do
                local a1=start+i*step
                local a2=start+(i+1)*step
                ImGui.AddLine(cx+math.cos(a1)*radius,cy+math.sin(a1)*radius,cx+math.cos(a2)*radius,cy+math.sin(a2)*radius,r,g,b,255,7.0)
            end
        end
        if ImGui.AddCircleFilled then ImGui.AddCircleFilled(cx,cy,radius-10,8,10,18,238,64) end
        if ImGui.AddText then
            local pct=tostring(math.floor(percent+0.5)).."%"
            ImGui.AddText(cx-(#pct*3.5),cy-8,pct,r,g,b,255)
        end
        if ImGui.Dummy then ImGui.Dummy(size,size) end
        if original_cursor_x and ImGui.SetCursorPosX then ImGui.SetCursorPosX(original_cursor_x) end
        if caption and caption~="" then
            local cr,cg,cb=metric_color(percent)
            text(cr/255,cg/255,cb/255,1.0,caption)
        end
    end

