    local function badge(label,kind)
        local c=kind or "Purple"
        startup.render_color_button(tostring(label or "").."##SB231BADGE"..tostring(label or "")..tostring(math.random(100000,999999)),c,"",nil,math.max(80,#tostring(label or "")*7+18),22)
    end
    local function event_visible(ev)
        if ui.category~="ALL" and ev.category~=ui.category then return false end
        if ui.mic_filter~="ALL" then
            if ui.mic_filter=="REQUIRED" and ev.mic~="MIC REQUIRED" then return false end
            if ui.mic_filter=="OPTIONAL" and ev.mic~="MIC OPTIONAL" then return false end
            if ui.mic_filter=="RECOMMENDED" and ev.mic~="MIC RECOMMENDED" then return false end
        end
        return true
    end

    local function render_event_card(ev,index,width)
        if ImGui.BeginChild then ImGui.BeginChild("SB231EventCard"..index,width or 0,160,true) end
        purple(ev.category)
        ImGui.SameLine(); dim("• "..ev.activity)
        ImGui.SameLine()
        if ev.mic=="MIC REQUIRED" then amber("🎙 "..ev.mic) else cyan("🎙 "..ev.mic) end

        white(ev.title)
        if startup.subtle_text_wrapped then startup.subtle_text_wrapped(ev.desc) else wrapped(ev.desc) end

        dim(ev.starts)
        ImGui.SameLine(); dim("• "..ev.players.." PLAYERS")
        ImGui.SameLine(); dim("• Host: ")
        ImGui.SameLine(); purple(ev.host)

        if ev.script~="NONE" then
            amber("REQUIRES: "..ev.script)
            ImGui.SameLine(); cyan(ev.scope)
        else
            green("NO SCRIPT REQUIRED")
        end
        ImGui.SameLine(); green("HOST RELIABILITY "..tostring(ev.reliability).."%")
        ImGui.SameLine()
        if small_button("DETAILS","SB231EventDetails"..index,"Purple",78) then ui.selected_event=index end

        local clicked=false
        if ImGui.IsWindowHovered and ImGui.IsMouseClicked then
            local okH,h=direct_call(ImGui.IsWindowHovered)
            local okC,c=direct_call(ImGui.IsMouseClicked,0)
            clicked=okH and okC and h==true and c==true
        end
        if clicked then ui.selected_event=index end
        if ImGui.EndChild then ImGui.EndChild() end
    end

