    local function render_upcoming()
        local total=math.max(620,avail_width(1000))
        local left=total>=900 and 175 or 155
        local right=total>=1000 and 250 or 210
        local gap=10
        local center=math.max(320,total-left-right-(gap*2))

        if ImGui.BeginChild then ImGui.BeginChild("SB231Categories",left,590,true) end
        render_categories_panel()
        if ImGui.EndChild then ImGui.EndChild() end
        ImGui.SameLine()

        if ImGui.BeginChild then ImGui.BeginChild("SB231UpcomingCenter",center,590,false) end
        white("EVENTS")
        ImGui.SameLine(); dim("• CURATED STARTUP SESSIONS")
        ImGui.Separator(); ImGui.Spacing()
        dim("Search events...")
        ImGui.SameLine(); purple("SORT: STARTS SOONEST")
        ImGui.Spacing()
        local visibleCount=0
        for i,ev in ipairs(events) do
            if event_visible(ev) then
                visibleCount=visibleCount+1
                render_event_card(ev,i,0)
                ImGui.Spacing()
            end
        end
        if visibleCount==0 then dim("No events match this filter.") end
        if ImGui.EndChild then ImGui.EndChild() end
        ImGui.SameLine()

        if ImGui.BeginChild then ImGui.BeginChild("SB231Profile",right,590,true) end
        render_profile(events[ui.selected_event] or events[1])
        if ImGui.EndChild then ImGui.EndChild() end
    end

    local function cycle_value(list,current)
        local at=1
        for i,v in ipairs(list) do if v==current then at=i break end end
        at=at+1; if at>#list then at=1 end
        return list[at]
    end

    local function render_host_session()
        local total=math.max(560,avail_width(900))
        local left=math.min(520,total*0.58)
        local right=math.max(260,total-left-10)
        if ImGui.BeginChild then ImGui.BeginChild("SB231HostForm",left,580,true) end
        white("HOST THIS SESSION")
        ImGui.Separator(); ImGui.Spacing()

        dim("1. SESSION TYPE")
        if startup.render_color_button("NORMAL SESSION##SB231HostNormal",ui.host_mode=="NORMAL" and "Purple" or "Gray","",nil,155,30) then ui.host_mode="NORMAL" end
        ImGui.SameLine()
        if startup.render_color_button("CUSTOM SESSION##SB231HostCustom",ui.host_mode=="CUSTOM" and "Purple" or "Gray","",nil,155,30) then ui.host_mode="CUSTOM" end
        ImGui.Spacing()

        if ui.host_mode=="NORMAL" then
            green("NORMAL PUBLIC SESSION")
            if startup.subtle_text_wrapped then startup.subtle_text_wrapped("Minimal setup. Startup publishes your current hosted lobby as a normal Browser session.") end
            dim("Mic: Optional")
            dim("Activity: General")
        else
            dim("2. CHOOSE CATEGORY")
            for _,cat in ipairs({"VEHICLES","MINIGAMES","ROLEPLAYING","WAR","SOCIAL"}) do
                if startup.render_color_button(cat.."##SB231HC"..cat,ui.host_category==cat and "Purple" or "Gray","",nil,145,27) then
                    ui.host_category=cat
                    ui.host_activity=(host_activities[cat] or {"ALL"})[1]
                end
                if cat~="SOCIAL" then ImGui.SameLine() end
            end
            ImGui.Spacing()
            dim("3. CHOOSE ACTIVITY")
            local activityList=host_activities[ui.host_category] or {"ALL"}
            purple(ui.host_activity)
            if small_button("NEXT ACTIVITY","SB231NextActivity","Gray",135) then ui.host_activity=cycle_value(activityList,ui.host_activity) end

            ImGui.Spacing(); dim("4. SESSION SETTINGS")
            white("Mic Requirement")
            ImGui.SameLine(); cyan(ui.host_mic)
            if small_button("CHANGE MIC","SB231MicCycle","Gray",115) then ui.host_mic=cycle_value({"REQUIRED","RECOMMENDED","OPTIONAL","NO MIC"},ui.host_mic) end
            white("Starts")
            ImGui.SameLine(); purple(ui.host_start)
            if small_button("CHANGE TIME","SB231TimeCycle","Gray",115) then ui.host_start=cycle_value({"NOW","+15M","+30M","+1H","+2H","CUSTOM"},ui.host_start) end
            white("Max Players")
            ImGui.SameLine(); green(tostring(ui.host_max))
            if small_button("CHANGE MAX","SB231MaxCycle","Gray",115) then ui.host_max=({[30]=16,[16]=20,[20]=24,[24]=30})[ui.host_max] or 30 end

            ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
            dim("AUTO-DETECTED ACTIVITY REQUIREMENTS")
            if ui.host_category=="VEHICLES" and ui.host_activity=="DRIFT SESSION" then
                amber("Required Script: DriftGod")
                cyan("Required For: Everyone")
            elseif ui.host_category=="MINIGAMES" and ui.host_activity=="WARGAMES" then
                amber("Required Script: Minigames")
                cyan("Required For: Host Only")
            elseif ui.host_category=="MINIGAMES" and ui.host_activity=="PARKOUR" then
                amber("Compatibility Profile: Spawned Objects")
                cyan("Object Spam Protection: temporary adjustment")
            else
                green("No special requirements detected")
            end
        end

        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
        if startup.render_color_button("PUBLISH SESSION##SB231Publish","Purple","Visual prototype only.",nil,math.max(210,left-24),34) then
            if startup.toast then startup.toast("Build 232 visual prototype: session publishing form is not connected to the event backend yet.",4500) end
        end
        if ImGui.EndChild then ImGui.EndChild() end
        ImGui.SameLine()

        if ImGui.BeginChild then ImGui.BeginChild("SB231HostPreview",right,580,true) end
        white("SESSION PREVIEW")
        ImGui.Separator(); ImGui.Spacing()
        local preview_key="art_social_thumb"
        if ui.host_category=="VEHICLES" then preview_key="art_vehicles_thumb"
        elseif ui.host_category=="MINIGAMES" then preview_key="art_minigames_thumb"
        elseif ui.host_category=="ROLEPLAYING" then preview_key="art_roleplaying_thumb"
        elseif ui.host_category=="WAR" then preview_key="art_war_thumb" end
        startup.browser_ui_draw(preview_key,math.max(250,right-20),150,8)
        ImGui.Spacing()
        purple(ui.host_mode=="NORMAL" and "GENERAL" or ui.host_category)
        white(ui.host_mode=="NORMAL" and "NORMAL PUBLIC SESSION" or ui.host_activity)
        cyan("🎙 MIC "..(ui.host_mode=="NORMAL" and "OPTIONAL" or ui.host_mic))
        white("Starts: "..(ui.host_mode=="NORMAL" and "NOW" or ui.host_start))
        white("Capacity: "..tostring(ui.host_mode=="NORMAL" and 30 or ui.host_max))
        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
        dim("HOST RELIABILITY")
        if ImGui.BeginChild then ImGui.BeginChild("SB232HostPreviewReliability",150,132,false,child_no_scroll_flags()) end
        draw_metric_ring(96,92,reliability_label(96))
        if ImGui.EndChild then ImGui.EndChild() end
        ImGui.SameLine(); white("14/15 Events Hosted")
        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
        red("EVENT POLICY")
        wrapped("Scheduled hosts are expected to show up and run the advertised activity. Repeated verified no-shows reduce Host Reliability and may restrict event hosting.")
        if ImGui.EndChild then ImGui.EndChild() end
    end

