    local function render_feedback_popup()
        if not (ImGui.OpenPopup and ImGui.BeginPopupModal and ImGui.EndPopup) then return end
        local name="HOW WAS THIS SESSION?##SB231Feedback"
        if ui.feedback_open then direct_call(ImGui.OpenPopup,name); ui.feedback_open=false end
        local open=false
        direct_call(function() open=ImGui.BeginPopupModal(name,true,ImGuiWindowFlags and ImGuiWindowFlags.AlwaysAutoResize or nil)==true end)
        if not open then return end
        startup.browser_ui_draw("startup_rocket_mark_small",34,34,3)
        ImGui.SameLine(); white("HOW WAS THIS SESSION?")
        dim("Verified attendee feedback helps the community judge legitimate hosts and events.")
        ImGui.Separator(); ImGui.Spacing()
        startup.browser_ui_draw("modal_thumb_up",72,92,6)
        ImGui.SameLine(); startup.browser_ui_draw("modal_thumb_down",72,92,6)
        ImGui.Spacing()
        if startup.render_color_button("👍 POSITIVE##SB231Positive","Green","",nil,155,36) then
            if startup.toast then startup.toast("Positive feedback submitted (visual prototype).",3000) end
            if ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end
        end
        ImGui.SameLine()
        if startup.render_color_button("👎 NEGATIVE##SB231Negative","Red","",nil,155,36) then ui.feedback_negative=true end
        if ui.feedback_negative then
            ImGui.Spacing(); red("WHY WAS IT NEGATIVE?")
            for _,reason in ipairs({"Host did not show up","Event was not as advertised","Host abandoned early","Poor moderation","Trolling / disruptive behavior","Other"}) do
                dim("○ "..reason)
            end
            ImGui.Spacing(); dim("Optional comment • 0 / 255 • Paste disabled in final implementation")
            if startup.render_color_button("SUBMIT NEGATIVE##SB231SubmitNeg","Purple","",nil,318,30) then
                if startup.toast then startup.toast("Negative feedback submitted (visual prototype).",3000) end
                if ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end
            end
        end
        ImGui.Spacing()
        if startup.render_color_button("SKIP##SB231FeedbackSkip","Gray","",nil,100,26) then if ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end end
        direct_call(ImGui.EndPopup)
    end

    local function render_compatibility_popup()
        if not (ImGui.OpenPopup and ImGui.BeginPopupModal and ImGui.EndPopup) then return end
        local name="HOST COMPATIBILITY##SB231Compat"
        if ui.compatibility_open then direct_call(ImGui.OpenPopup,name); ui.compatibility_open=false end
        local open=false
        direct_call(function() open=ImGui.BeginPopupModal(name,true,ImGuiWindowFlags and ImGuiWindowFlags.AlwaysAutoResize or nil)==true end)
        if not open then return end
        local ev=events[ui.selected_event] or events[1]
        startup.browser_ui_draw("modal_compatibility",78,78,7)
        ImGui.SameLine(); amber("HOST COMPATIBILITY")
        wrapped("Startup will verify required scripts and temporarily apply the activity compatibility profile before joining.")
        ImGui.Separator(); ImGui.Spacing()
        if ev.script~="NONE" then amber("Required Script: "..ev.script); cyan("Requirement Scope: "..ev.scope) else green("No custom script required") end
        if ev.activity=="PARKOUR" then
            startup.browser_ui_draw("modal_warning",54,54,5)
            white("Object Spam Protection")
            ImGui.SameLine(); amber("→ TEMPORARILY ADJUST")
            white("Conflicting event protections")
            ImGui.SameLine(); red("→ LOCKED DURING EVENT")
        else
            white("Compatibility Profile")
            ImGui.SameLine(); green("READY")
        end
        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()
        if startup.render_color_button("CANCEL##SB231CompatCancel","Gray","",nil,120,30) then if ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end end
        ImGui.SameLine()
        if startup.render_color_button("APPLY & CONTINUE##SB231CompatApply","Purple","",nil,190,30) then
            if startup.toast then startup.toast("Build 232 visual prototype: compatibility profile preview complete.",3500) end
            if ImGui.CloseCurrentPopup then direct_call(ImGui.CloseCurrentPopup) end
        end
        direct_call(ImGui.EndPopup)
    end

