    local function render_upcoming_popup()
        local total=math.max(860,avail_width(1120))
        white("UPCOMING EVENTS"); ImGui.SameLine(); dim("• CURATED STARTUP SESSIONS")
        ImGui.Separator(); ImGui.Spacing()

        -- Clear category artwork at readable size. These are visual selectors, not tiny label strips.
        startup.browser_ui_draw("art_vehicles_tile",150,84,7); ImGui.SameLine()
        startup.browser_ui_draw("art_minigames_tile",150,84,7); ImGui.SameLine()
        startup.browser_ui_draw("art_roleplaying_tile",150,84,7); ImGui.SameLine()
        startup.browser_ui_draw("art_war_tile",150,84,7); ImGui.SameLine()
        startup.browser_ui_draw("art_social_tile",150,84,7)
        ImGui.Spacing()
        for i,entry in ipairs(categories) do
            if startup.render_color_button(entry.label.."##SB231CAT"..entry.key,ui.category==entry.key and "Purple" or "Gray","",nil,i==1 and 130 or 105,24) then ui.category=entry.key; ui.event_page=1 end
            if i<#categories then ImGui.SameLine() end
        end
        ImGui.Spacing()
        dim("MIC:"); ImGui.SameLine()
        for i,m in ipairs({"ALL","REQUIRED","RECOMMENDED","OPTIONAL"}) do
            if startup.render_color_button(m.."##SB231MIC"..m,ui.mic_filter==m and "Purple" or "Gray","",nil,96,22) then ui.mic_filter=m; ui.event_page=1 end
            if i<4 then ImGui.SameLine() end
        end
        ImGui.Separator(); ImGui.Spacing()

        local main_w=math.max(600,total-342)
        if ImGui.BeginChild then ImGui.BeginChild("SB232PagedEvents",main_w,540,false,child_no_scroll_flags()) end
        local visible={}
        for i,ev in ipairs(events) do if event_visible(ev) then visible[#visible+1]={i=i,ev=ev} end end
        local per_page=3
        local pages=math.max(1,math.ceil(#visible/per_page))
        if ui.event_page<1 then ui.event_page=1 end
        if ui.event_page>pages then ui.event_page=pages end
        local first=(ui.event_page-1)*per_page+1
        local last=math.min(#visible,first+per_page-1)
        if #visible==0 then dim("No events match this filter.") end
        for j=first,last do
            local item=visible[j]
            render_event_card_popup(item.ev,item.i,0)
            ImGui.Spacing()
        end
        ImGui.Separator()
        if startup.render_color_button("◀ PREV##SB231Prev","Gray","",nil,95,24) and ui.event_page>1 then ui.event_page=ui.event_page-1 end
        ImGui.SameLine(); dim("PAGE "..tostring(ui.event_page).." / "..tostring(pages))
        ImGui.SameLine(); if startup.render_color_button("NEXT ▶##SB231Next","Gray","",nil,95,24) and ui.event_page<pages then ui.event_page=ui.event_page+1 end
        if ImGui.EndChild then ImGui.EndChild() end
        ImGui.SameLine()
        if ImGui.BeginChild then ImGui.BeginChild("SB232PopupProfile",320,540,true,child_no_scroll_flags()) end
        render_profile_popup(events[ui.selected_event] or events[1])
        if ImGui.EndChild then ImGui.EndChild() end
    end

    local function render_activity_popup_window()
        if ui.popup_open~=true then return end
        local sw,sh=1280,720
        if startup.get_display_size then sw,sh=startup.get_display_size() end
        sw=tonumber(sw or 1280) or 1280; sh=tonumber(sh or 720) or 720
