function startup.live_r_edition_code_343(v)
    local x=tostring(v or "Unknown"):upper():gsub("%s+","")
    if x=="EE" or x:find("ENHANCED",1,true) then return "EE" end
    if x=="LE" or x:find("LEGACY",1,true) then return "LE" end
    return "UNKNOWN"
end

function startup.live_r_local_key_343(edition,rid)
    return startup.live_r_edition_code_343(edition).."|"..tostring(rid or "")
end

function startup.live_r_now_341()
    if startup.now then return tonumber(startup.now()) or 0 end
    if Time and Time.GetEpocheMs then return tonumber(Time.GetEpocheMs()) or 0 end
    return math.floor((os.clock and os.clock() or 0)*1000)
end
startup.live_r_now_340=startup.live_r_now_341

function startup.live_r_trim_341(v,maxlen)
    local x=tostring(v or ""):gsub("[%z\1-\31]",""):gsub("^%s+",""):gsub("%s+$","")
    maxlen=tonumber(maxlen or 96) or 96
    if #x>maxlen then x=x:sub(1,maxlen) end
    return x
end

function startup.rid347_read_text(path)
    path=tostring(path or "")
    if path=="" then return nil end
    if FileMgr and FileMgr.ReadFileContent then
        local ok,v=direct_call(FileMgr.ReadFileContent,path)
        if ok and type(v)=="string" and v~="" then return v end
    end
    local f=io.open(path,"rb")
    if not f then return nil end
    local body=f:read("*a")
    f:close()
    return body
end

function startup.rid347_recentplayers_path()
    local root=tostring(startup.menu_root or "")
    if root=="" then return "" end
    return root.."\\PlayerTracker\\RecentPlayers.json"
end

function startup.rid347_decode_json(body)
    local bb=startup.browser_backend or {}
    if type(bb._json_decode)=="function" then
        local ok,v=direct_call(bb._json_decode,tostring(body or ""))
        if ok and type(v)=="table" then return v end
    end
    return nil
end

function startup.rid347_fmt_time(epoch)
    local n=tonumber(epoch or 0) or 0
    if n<=0 then return "--" end
    if os and os.date then
        local ok,v=direct_call(os.date,"%Y-%m-%d %H:%M:%S",n)
        if ok and type(v)=="string" then return v end
    end
    return tostring(math.floor(n))
end

function startup.live_r_load_local_341()
    if startup.rid_session_local_347.local_loaded then return true end
    startup.rid_session_local_347.local_loaded=true
    local chunk=loadfile(startup.live_r_players_file_341)
    if chunk then
        local ok,data=direct_call(chunk)
        if ok and type(data)=="table" then startup.rid_session_local_347.local_data=data end
    end
    return true
end

function startup.live_r_save_local_341(force)
    if not startup.rid_session_local_347.local_dirty and force~=true then return true end
    if startup.ensure_save_dir then startup.ensure_save_dir() end
    local content="return "..startup.serialize(startup.rid_session_local_347.local_data or {},"").."\n"
    local ok=startup.try_write_file and startup.try_write_file(startup.live_r_players_file_341,content)
    if ok then startup.rid_session_local_347.local_dirty=false end
    return ok==true
end

function startup.live_r_language_from_gamer_info_341(info)
    if not info then return "Unknown" end
    local candidates={"Language","language","LanguageCode","languageCode","Locale","locale","LanguageId","languageId"}
    for _,key in ipairs(candidates) do
        local value=nil
        direct_call(function() value=info[key] end)
        if value~=nil and tostring(value)~="" then
            local txt=startup.live_r_trim_341(value,32)
            if txt~="0" and txt~="-1" then return txt end
        end
    end
    return "Unknown"
end

