-- This is display metadata only; it is not used for moderation or enforcement.
startup.rid348_country_language = startup.rid348_country_language or {
    US="English",GB="English",IE="English",AU="English",NZ="English",
    RU="Russian",BY="Russian",
    MX="Spanish",ES="Spanish",AR="Spanish",CL="Spanish",CO="Spanish",PE="Spanish",VE="Spanish",
    UY="Spanish",PY="Spanish",BO="Spanish",EC="Spanish",CR="Spanish",PA="Spanish",GT="Spanish",
    HN="Spanish",SV="Spanish",NI="Spanish",DO="Spanish",CU="Spanish",
    BR="Portuguese",PT="Portuguese",FR="French",DE="German",AT="German",CH="German",
    IT="Italian",NL="Dutch",BE="Dutch",PL="Polish",CZ="Czech",SK="Slovak",HU="Hungarian",
    RO="Romanian",BG="Bulgarian",GR="Greek",TR="Turkish",UA="Ukrainian",
    CN="Chinese",TW="Chinese",HK="Chinese",JP="Japanese",KR="Korean",
    SE="Swedish",NO="Norwegian",DK="Danish",FI="Finnish",IS="Icelandic"
}
function startup.rid348_language_from_region(countryCode,country,fallback)
    local cc=tostring(countryCode or ""):upper():gsub("[^A-Z]","")
    local mapped=startup.rid348_country_language[cc]
    if mapped then return mapped end
    local name=tostring(country or ""):lower():gsub("^%s+",""):gsub("%s+$","")
    if name=="united states" or name=="united states of america" or name=="usa" then return "English" end
    if name=="russia" or name=="russian federation" then return "Russian" end
    local fb=tostring(fallback or "Unknown")
    if fb=="" or fb=="0" or fb=="-1" then return "Unknown" end
    return fb
end

-- B350: Cherax IP info sometimes gives a country name without alpha-2.
-- Normalize common names so RID Session can reliably render the matching local flag asset.
startup.rid350_country_name_code = startup.rid350_country_name_code or {
    ["united states"]="US",["united states of america"]="US",["usa"]="US",
    ["russia"]="RU",["russian federation"]="RU",["mexico"]="MX",["canada"]="CA",
    ["united kingdom"]="GB",["great britain"]="GB",["england"]="GB",["ireland"]="IE",
    ["australia"]="AU",["new zealand"]="NZ",["brazil"]="BR",["portugal"]="PT",
    ["spain"]="ES",["france"]="FR",["germany"]="DE",["austria"]="AT",["switzerland"]="CH",
    ["italy"]="IT",["netherlands"]="NL",["belgium"]="BE",["poland"]="PL",
    ["czech republic"]="CZ",["czechia"]="CZ",["slovakia"]="SK",["hungary"]="HU",
    ["romania"]="RO",["bulgaria"]="BG",["greece"]="GR",["turkey"]="TR",["türkiye"]="TR",
    ["ukraine"]="UA",["belarus"]="BY",["china"]="CN",["taiwan"]="TW",["hong kong"]="HK",
    ["japan"]="JP",["south korea"]="KR",["republic of korea"]="KR",["korea"]="KR",
    ["sweden"]="SE",["norway"]="NO",["denmark"]="DK",["finland"]="FI",["iceland"]="IS",
    ["argentina"]="AR",["chile"]="CL",["colombia"]="CO",["peru"]="PE",["venezuela"]="VE",
    ["uruguay"]="UY",["paraguay"]="PY",["bolivia"]="BO",["ecuador"]="EC",["costa rica"]="CR",
