    ["nicaragua"]="NI",["dominican republic"]="DO",["cuba"]="CU"
}
function startup.rid350_country_code(countryCode,country)
    local cc=tostring(countryCode or ""):upper():gsub("[^A-Z]","")
    if #cc==2 then return cc end
    local name=tostring(country or ""):lower():gsub("^%s+",""):gsub("%s+$","")
    return tostring(startup.rid350_country_name_code[name] or "")
end

function startup.live_r_player_identity_341(playerId,hostPid,sessionPlayers)
    playerId=tonumber(playerId)
    if playerId==nil or playerId<0 or playerId>31 or not Players or not Players.GetById then return nil end
    local okP,player=direct_call(function() return Players.GetById(playerId) end)
    if not okP or not player then return nil end
    local name=""
    if player.GetName then direct_call(function() name=tostring(player:GetName() or "") end) end
    if name=="" and Players.GetName then local okN,v=direct_call(Players.GetName,playerId); if okN then name=tostring(v or "") end end
    name=startup.live_r_trim_341(name,64)
    if name=="" then return nil end
    local info=nil
    if player.GetGamerInfo then local okI,v=direct_call(function() return player:GetGamerInfo() end); if okI then info=v end end
    if not info then direct_call(function() info=player.GamerInfo end) end
    local rid=0
    if Players.GetRockstarId then local okR,v=direct_call(Players.GetRockstarId,playerId); if okR then rid=tonumber(v or 0) or 0 end end
    if rid<=0 and info then direct_call(function() rid=tonumber(info.RockstarId or 0) or 0 end) end
    if rid<=0 then return nil end
    local city,country,countryCode="","",""
    if Players.GetIPInfo then
        local okG,geo=direct_call(Players.GetIPInfo,playerId)
        if okG and type(geo)=="table" then
            city=startup.live_r_trim_341(geo.city or geo.cityName or geo.city_name,96)
            country=startup.live_r_trim_341(geo.country or geo.countryName or geo.country_name,96)
            countryCode=startup.live_r_trim_341(geo.countryCode or geo.country_code or geo.cc,2):upper()
            if not countryCode:match("^[A-Z][A-Z]$") then countryCode="" end
        end
    end
    countryCode=startup.rid350_country_code(countryCode,country)
    local language=startup.rid348_language_from_region(countryCode,country,startup.live_r_language_from_gamer_info_341(info))
    local edition="Unknown"
    if startup.get_active_edition_info then local _,family=startup.get_active_edition_info(); edition=tostring(family or "Unknown") end
    return {
        pid=playerId,name=name,rid=string.format("%.0f",rid),city=city,country=country,country_code=countryCode,
        language=language,is_host=(tonumber(hostPid or -1)==playerId),session_players=math.max(1,math.min(32,tonumber(sessionPlayers or 1) or 1)),edition=edition
    }
end

-- Startup users must never appear in RID Session. Use every local verified identity
-- source we already have, including the persistent B344 verified-RID whitelist.
function startup.live_r_is_protected_startup_user_342(playerId,rid)
    local pid=tonumber(playerId)
    if pid~=nil and startup.is_local_player_id and startup.is_local_player_id(pid) then return true end
    if pid~=nil and startup.browser_safety and startup.browser_safety.is_verified_peer then
        local ok,v=direct_call(startup.browser_safety.is_verified_peer,pid)
        if ok and v==true then return true end
    end
    local key=tostring(rid or "")
    if key~="" and startup.browser_verified_whitelist_contains_build344 then
        local ok,v=direct_call(startup.browser_verified_whitelist_contains_build344,key,"")
        if ok and v==true then return true end
    end
    if key~="" and startup.presence and startup.presence.verified_by_rid and startup.presence.verified_by_rid[key] then return true end
    local bb=startup.browser_backend
    local now=startup.live_r_now_341()
    if key~="" and bb and bb.browser_verified_by_rid then
        local row=bb.browser_verified_by_rid[key]
        if row and now <= (tonumber(row.expires_ms or 0) or 0) then return true end
    end
    return false
end

function startup.rid347_current_scan()
    local hostPid=-1
    if startup.get_session_host_name then local _,p=startup.get_session_host_name(); hostPid=tonumber(p or -1) or -1 end
    local sessionPlayers=math.max(1,math.min(32,tonumber(startup.get_session_player_count and startup.get_session_player_count() or 1) or 1))
    local current={}
    for pid=0,31 do
        local ident=startup.live_r_player_identity_341(pid,hostPid,sessionPlayers)
        if ident and not startup.live_r_is_protected_startup_user_342(pid,ident.rid) then current[tostring(ident.rid)]=ident end
    end
    startup.rid_session_local_347.current_by_rid=current
    return current
end

-- Read Cherax RecentPlayers.json and enrich only those RIDs (plus current lobby members).
-- This makes RID Session a local Recent Players view instead of a global/shared catalog.
function startup.live_r_scan_local_341()
    startup.live_r_load_local_341()
    local body=startup.rid347_read_text(startup.rid347_recentplayers_path())
    local recent=body and startup.rid347_decode_json(body) or nil
    if type(recent)~="table" then
        startup.rid_session_local_347.status=body and "LOCAL • RECENTPLAYERS JSON DECODE FAILED" or "LOCAL • RECENTPLAYERS.JSON NOT FOUND"
        recent={}
    end
    local current=startup.rid347_current_scan()
    local allowed={}
    for rid,row in pairs(recent) do
        local key=tostring(rid or "")
        if key:match("^%d+$") and not startup.live_r_is_protected_startup_user_342(nil,key) then
            allowed[key]=true
        end
    end
    for rid,_ in pairs(current) do allowed[tostring(rid)]=true end

    local changed=false
    -- B350: keep the local non-Startup RID history permanently. Leaving a session only
    -- changes who is eligible to be rendered; it does not erase previously encountered users.
    -- The only automatic purge here is a RID later proven to be a Startup community user.
    for rid,_ in pairs(startup.rid_session_local_347.local_data or {}) do
        local key=tostring(rid or "")
        if startup.live_r_is_protected_startup_user_342(nil,key) then
            startup.rid_session_local_347.local_data[rid]=nil
            changed=true
        end
    end

    local now=os.time()
    for rid,_ in pairs(allowed) do
        local recentRow=type(recent[rid])=="table" and recent[rid] or {}
        local cur=current[rid]
        if not startup.live_r_is_protected_startup_user_342(cur and cur.pid or nil,rid) then
            local old=type(startup.rid_session_local_347.local_data[rid])=="table" and startup.rid_session_local_347.local_data[rid] or {}
            if not old.firstSeen then old.firstSeen=now end
            local prevName=tostring(old.name or "")
            old.rid=rid
            old.name=startup.live_r_trim_341((cur and cur.name) or recentRow.name or old.name or "Unknown",64)
            local oldLastSeen=tonumber(old.lastSeen or 0) or 0
            old.lastSeen=tonumber(recentRow.last_seen or old.lastSeen or now) or now
            if old.lastSeen~=oldLastSeen then changed=true end
            if cur then
                old.lastSeen=now
                old.city=cur.city; old.country=cur.country; old.countryCode=cur.country_code
                old.language=cur.language; old.currentIsHost=cur.is_host; old.sessionPlayers=cur.session_players; old.edition=cur.edition
                old.lastObservedCurrent=now
                old.seenCount=(tonumber(old.seenCount or 0) or 0)+1
                if cur.is_host==true then
                    old.everHost=true
                    old.isHost=true -- retained only as historical compatibility; current activity is verified separately.
                    old.lastHostSeen=now
                    old.lastHostPlayers=cur.session_players
                    old.hostSeenCount=(tonumber(old.hostSeenCount or 0) or 0)+1
                end
            end
            if prevName~=old.name or cur then changed=true end
            startup.rid_session_local_347.local_data[rid]=old
        end
    end
    if changed then startup.rid_session_local_347.local_dirty=true; startup.live_r_save_local_341(false) end
    return startup.rid_session_local_347.local_data
end

