-- B352 local matchmaking discovery. These are Cherax menu features, not Startup backend APIs.
startup.rid351_feature_hashes = startup.rid351_feature_hashes or {
    find_sessions=930252067,
    filter_language=3031388890,
    filter_region=1316745301,
    filter_aim=2498350941,
    min_players=1732123379,
    max_players=2430275197,
    found_sessions=2380825073
}

function startup.rid351_get_feature(hash,names)
    if not FeatureMgr then return nil end
    if FeatureMgr.GetFeature and tonumber(hash) then
        local ok,v=direct_call(FeatureMgr.GetFeature,tonumber(hash))
        if ok and v then return v end
    end
    if FeatureMgr.GetFeatureByName then
        for _,name in ipairs(names or {}) do
            local ok,v=direct_call(FeatureMgr.GetFeatureByName,tostring(name))
            if ok and v then return v end
        end
    end
    return nil
end

function startup.rid351_get_feature_list(feature,hash)
    if feature and feature.GetList then
        local ok,v=pcall(function() return feature:GetList() end)
        if ok and type(v)=="table" then return v end
    end
    if FeatureMgr and FeatureMgr.GetFeatureList and tonumber(hash) then
        local ok,v=direct_call(FeatureMgr.GetFeatureList,tonumber(hash))
        if ok and type(v)=="table" then return v end
    end
    return {}
end

function startup.rid351_list_signature(list)
    local parts={}
    for k,v in pairs(list or {}) do parts[#parts+1]=tostring(k).."="..tostring(v) end
    table.sort(parts)
    return table.concat(parts,"\n")
end

function startup.rid351_snapshot_and_broaden_filters()
    local snaps={}
    local specs={
        {hash=startup.rid351_feature_hashes.filter_language,names={"Filter Language"},kind="list"},
        {hash=startup.rid351_feature_hashes.filter_region,names={"Filter Region"},kind="list"},
        {hash=startup.rid351_feature_hashes.filter_aim,names={"Filter Aim Type"},kind="list"},
        {hash=startup.rid351_feature_hashes.min_players,names={"Minimum Players"},kind="min"},
        {hash=startup.rid351_feature_hashes.max_players,names={"Maximum Players"},kind="max"}
    }
    for _,spec in ipairs(specs) do
        local f=startup.rid351_get_feature(spec.hash,spec.names)
        if f then
            local snap={feature=f,kind=spec.kind}
            if spec.kind=="list" and f.GetListIndex then
                local ok,idx=pcall(function() return f:GetListIndex() end)
                if ok then snap.value=tonumber(idx) end
                local list=startup.rid351_get_feature_list(f,spec.hash)
                local best=nil
                for k,label in pairs(list) do
                    local low=tostring(label or ""):lower():gsub("^%s+",""):gsub("%s+$","")
                    if low=="all" or low=="any" or low=="none" or low=="off" or low=="disabled" or low=="no filter" then
                        local nk=tonumber(k)
                        if nk~=nil then best=(nk==0) and 0 or (nk-1); break end
                    end
                end
                if best~=nil and f.SetListIndex then
                    pcall(function() f:SetListIndex(best) end)
                    if f.TriggerCallback then pcall(function() f:TriggerCallback() end) end
                end
            elseif (spec.kind=="min" or spec.kind=="max") and f.GetIntValue and f.SetIntValue then
                local ok,val=pcall(function() return f:GetIntValue() end)
                if ok then snap.value=tonumber(val) end
                local target=nil
                if spec.kind=="min" then
                    if f.GetIntMinValue then local okm,v=pcall(function() return f:GetIntMinValue() end); if okm then target=tonumber(v) end end
                    if target==nil then target=0 end
                else
                    if f.GetIntMaxValue then local okm,v=pcall(function() return f:GetIntMaxValue() end); if okm then target=tonumber(v) end end
                    if target==nil then target=32 end
                end
                pcall(function() f:SetIntValue(target) end)
                if f.TriggerCallback then pcall(function() f:TriggerCallback() end) end
            end
            snaps[#snaps+1]=snap
        end
    end
    return snaps
end

function startup.rid351_restore_filters(snaps)
    for _,snap in ipairs(snaps or {}) do
        local f=snap.feature
        if f and snap.value~=nil then
            if snap.kind=="list" and f.SetListIndex then
                pcall(function() f:SetListIndex(snap.value) end)
                if f.TriggerCallback then pcall(function() f:TriggerCallback() end) end
            elseif (snap.kind=="min" or snap.kind=="max") and f.SetIntValue then
                pcall(function() f:SetIntValue(snap.value) end)
                if f.TriggerCallback then pcall(function() f:TriggerCallback() end) end
            end
        end
    end
end

function startup.rid351_match_found_label(label)
    local text=tostring(label or "")
    local low=text:lower()
    if low=="" then return nil end
    local data=startup.rid_session_local_347.local_data or {}
    -- Prefer an explicit locally-known RID if Cherax includes one in the row label.
    for token in text:gmatch("%d+") do
        if #token>=5 and type(data[token])=="table" and not startup.live_r_is_protected_startup_user_342(nil,token) then
            return token,"RID"
        end
    end
    -- Otherwise match the longest exact local Rockstar name embedded in the result label.
    local bestRid,bestLen=nil,0
    for rid,row in pairs(data) do
        if type(row)=="table" and not startup.live_r_is_protected_startup_user_342(nil,rid) then
            local name=tostring(row.name or ""):lower():gsub("^%s+",""):gsub("%s+$","")
            if #name>=3 and #name>bestLen and low:find(name,1,true) then bestRid=tostring(rid); bestLen=#name end
        end
    end
    if bestRid then return bestRid,"NAME" end
    return nil
end

function startup.rid351_players_from_found_label(label)
    local t=tostring(label or "")
    local a,b=t:match("(%d+)%s*/%s*(%d+)")
    if a then return tonumber(a),tonumber(b) end
    local n=t:match("(%d+)%s+[Pp][Ll][Aa][Yy][Ee][Rr][Ss]")
    if n then return tonumber(n),nil end
    return nil,nil
end

function startup.rid351_build_active_matches(foundList)
    local lr=startup.rid_session_local_347
    local active={}
    local raw=0
    local samples={}
    for _,label in pairs(foundList or {}) do
        raw=raw+1
        local text=startup.live_r_trim_341(label,180)
        if #samples<3 and text~="" then samples[#samples+1]=text end
        local rid,method=startup.rid351_match_found_label(text)
        if rid and not active[rid] then
            local p,maxp=startup.rid351_players_from_found_label(text)
            active[rid]={source="MATCHMAKING",label=text,match_method=method,players=p,max_players=maxp,verified_ms=startup.live_r_now_341()}
        end
    end
    -- Current non-Startup Session Host is direct local evidence and should appear immediately.
    for rid,cur in pairs(lr.current_by_rid or {}) do
        if type(cur)=="table" and cur.is_host==true and not startup.live_r_is_protected_startup_user_342(cur.pid,rid) then
            active[tostring(rid)]={source="CURRENT SESSION",label="Current GTA Session Host",match_method="CURRENT",players=tonumber(cur.session_players),max_players=32,verified_ms=startup.live_r_now_341(),current=cur}
        end
    end
    lr.active_by_rid=active
    lr.matchmaking_raw_count=raw
    local c=0; for _ in pairs(active) do c=c+1 end
    lr.matchmaking_matched_count=c
    lr.matchmaking_sample=table.concat(samples,"  |  ")
    lr.matchmaking_last_ms=startup.live_r_now_341()
    return active
end

function startup.rid351_run_matchmaking_discovery()
    local lr=startup.rid_session_local_347
    if lr.matchmaking_busy==true then return false end
    lr.matchmaking_busy=true
    lr.matchmaking_error=""
    lr.status="LOCAL • SEARCHING CHERAX MATCHMAKING"
    startup.live_r_scan_local_341()
    local findFeature=startup.rid351_get_feature(startup.rid351_feature_hashes.find_sessions,{"Find Sessions"})
    local foundFeature=startup.rid351_get_feature(startup.rid351_feature_hashes.found_sessions,{"Found Sessions"})
    if not findFeature or not foundFeature then
        lr.matchmaking_busy=false
        lr.matchmaking_error="Cherax Find Sessions / Found Sessions feature unavailable"
        lr.status="LOCAL • FIND SESSIONS UNAVAILABLE"
        return false
    end
    local before=startup.rid351_get_feature_list(foundFeature,startup.rid351_feature_hashes.found_sessions)
    local beforeSig=startup.rid351_list_signature(before)
    local snaps=startup.rid351_snapshot_and_broaden_filters()
    local clicked=false
    if findFeature.OnClick then clicked=pcall(function() findFeature:OnClick() end) end
    if not clicked and findFeature.TriggerCallback then clicked=pcall(function() findFeature:TriggerCallback() end) end
    startup.rid351_restore_filters(snaps)
    if not clicked then
        lr.matchmaking_busy=false
        lr.matchmaking_error="Cherax Find Sessions callback failed"
        lr.status="LOCAL • FIND SESSIONS CALLBACK FAILED"
        return false
    end
    local latest={}
    local changedAt=0
    for i=1,32 do
        if startup.yield then startup.yield(250) elseif Script and Script.Yield then Script.Yield(250) end
        latest=startup.rid351_get_feature_list(foundFeature,startup.rid351_feature_hashes.found_sessions)
        local sig=startup.rid351_list_signature(latest)
        if sig~=beforeSig and changedAt==0 then changedAt=i end
        if changedAt>0 and (i-changedAt)>=3 then break end
        if i>=20 and next(latest)~=nil then break end
    end
    startup.rid351_build_active_matches(latest)
    lr.matchmaking_busy=false
    lr.matchmaking_error=""
    startup.live_r_fetch_341()
            -- B354 production: RID Session runtime log intentionally suppressed.
    return true
end

function startup.rid351_request_matchmaking_refresh(force)
    local lr=startup.rid_session_local_347
    local now=startup.live_r_now_341()
    if lr.matchmaking_busy==true then return false end
    if force~=true and now<(tonumber(lr.next_matchmaking_scan_ms or 0) or 0) then return false end
    lr.next_matchmaking_scan_ms=now+30000
    if Script and Script.QueueJob then
        Script.QueueJob(function() startup.rid351_run_matchmaking_discovery() end)
        return true
    end
    return startup.rid351_run_matchmaking_discovery()
end

function startup.live_r_fetch_341()
    startup.live_r_scan_local_341()
    local lr=startup.rid_session_local_347
    lr.search=""; lr.edition_filter="ALL"
    local logged=0
    for rid,row in pairs(lr.local_data or {}) do
        if type(row)=="table" and not startup.live_r_is_protected_startup_user_342(nil,rid) then logged=logged+1 end
    end
    local all={}
    local myEdition="UNKNOWN"
    if startup.get_active_edition_info then local _,family=startup.get_active_edition_info(); myEdition=startup.live_r_edition_code_343(family) end
    for rid,evidence in pairs(lr.active_by_rid or {}) do
        if type(evidence)=="table" and not startup.live_r_is_protected_startup_user_342(nil,rid) then
            local row=type(lr.local_data[rid])=="table" and lr.local_data[rid] or {}
            local cur=evidence.current or (lr.current_by_rid and lr.current_by_rid[rid])
            local countryCode=(cur and cur.country_code) or row.countryCode or ""
            local country=(cur and cur.country) or row.country or ""
            local language=startup.rid348_language_from_region(countryCode,country,(cur and cur.language) or row.language)
            local edition=(cur and cur.edition) or ((evidence.source=="MATCHMAKING" and myEdition~="UNKNOWN") and myEdition or row.edition) or "Unknown"
            local p=evidence.players or (cur and cur.session_players) or row.lastHostPlayers or row.sessionPlayers
            all[#all+1]={
                player_id=tostring(rid),rid=tostring(rid),username=tostring((cur and cur.name) or row.name or "Unknown"),
                online=true,current=evidence.source=="CURRENT SESSION",session_players=p or "?",max_players=evidence.max_players or 32,is_host=true,
                source=tostring(evidence.source or "MATCHMAKING"),discovery_label=tostring(evidence.label or ""),match_method=tostring(evidence.match_method or ""),
                city=(cur and cur.city) or row.city or "",country=country,country_code=countryCode,
                language=language,edition=edition,
                first_seen=startup.rid347_fmt_time(row.firstSeen),last_seen=startup.rid347_fmt_time(row.lastSeen),last_host_seen=startup.rid347_fmt_time(row.lastHostSeen),
                last_seen_epoch=tonumber(row.lastSeen or 0) or 0,seen_count=tonumber(row.seenCount or 0) or 0,host_seen_count=tonumber(row.hostSeenCount or 0) or 0
            }
        end
    end
    table.sort(all,function(a,b)
        if a.current~=b.current then return a.current==true end
        local ap=tonumber(a.session_players or -1) or -1; local bp=tonumber(b.session_players or -1) or -1
        if ap~=bp then return ap>bp end
        return tostring(a.username or ""):lower()<tostring(b.username or ""):lower()
    end)
    lr.logged_count=logged; lr.total_count=#all; lr.total_pages=1; lr.page=0; lr.rows=all; lr.count=#all; lr.last_fetch_ms=startup.live_r_now_341()
    if lr.selected_rid=="" or not lr.active_by_rid[lr.selected_rid] then lr.selected_rid=all[1] and tostring(all[1].rid) or "" end
    if lr.matchmaking_busy==true then
        lr.status="LOCAL • SEARCHING • "..tostring(logged).." USERS LOGGED"
    elseif tostring(lr.matchmaking_error or "")~="" then
        lr.status="LOCAL • DISCOVERY ERROR • "..tostring(logged).." USERS LOGGED"
    else
        lr.status="LOCAL • "..tostring(#all).." ACTIVE HOST"..(#all==1 and "" or "S").." • "..tostring(lr.matchmaking_raw_count or 0).." CHERAX SESSIONS • "..tostring(logged).." USERS LOGGED"
    end
    return true
end
startup.live_r_fetch_340=startup.live_r_fetch_341

function startup.live_r_refresh_341()
    startup.rid_session_local_347.next_scan_ms=0; startup.rid_session_local_347.next_fetch_ms=0; startup.rid_session_local_347.next_matchmaking_scan_ms=0; startup.rid_session_local_347.status="LOCAL REFRESHING ACTIVE HOSTS"
    startup.live_r_scan_local_341(); startup.live_r_fetch_341()
    if startup.rid351_request_matchmaking_refresh then startup.rid351_request_matchmaking_refresh(true) end
end
startup.live_r_refresh_340=startup.live_r_refresh_341

-- Local direct RID join. No Startup API request and no Startup-user JOIN whitelist path.
function startup.live_r_join_341(row)
    if type(row)~="table" then return false end
    local rid=tostring(row.rid or row.player_id or row.playerId or "")
    local ridNum=tonumber(rid or 0) or 0
    if ridNum<=0 then return false end
    if startup.live_r_is_protected_startup_user_342(nil,rid) then
        if startup.toast then startup.toast("Startup users are excluded from RID Session. Use Live Sessions for Startup users.",4200) end
        return false
    end
    local rowEdition=startup.live_r_edition_code_343(row.edition)
    local myEdition="UNKNOWN"
    if startup.get_active_edition_info then local _,family=startup.get_active_edition_info(); myEdition=startup.live_r_edition_code_343(family) end
    if rowEdition~="UNKNOWN" and myEdition~="UNKNOWN" and rowEdition~=myEdition then
        if startup.toast then startup.toast("That host is on "..rowEdition..". Switch GTA edition to try joining them.",4500) end
        return false
    end
    if not (FeatureMgr and FeatureMgr.GetFeatureByName) then return false end
    local ridFeature=nil
    for _,nm in ipairs({"RID","Rockstar Id","Rockstar ID"}) do
        local okf,f=direct_call(FeatureMgr.GetFeatureByName,nm)
        if okf and f then ridFeature=f break end
    end
    local joinFeature=nil
    for _,nm in ipairs({"Join Rockstar Id","Join Rockstar ID"}) do
        local okf,f=direct_call(FeatureMgr.GetFeatureByName,nm)
        if okf and f then joinFeature=f break end
    end
    if not ridFeature or not joinFeature then
        if startup.toast then startup.toast("Cherax RID Join controls are unavailable.",4000) end
        return false
    end
    local setOk=false
    if ridFeature.SetIntValue then setOk=pcall(function() ridFeature:SetIntValue(ridNum) end) end
    if not setOk and ridFeature.SetValue then setOk=pcall(function() ridFeature:SetValue(ridNum) end) end
    if not setOk and ridFeature.SetStringValue then setOk=pcall(function() ridFeature:SetStringValue(tostring(rid)) end) end
    if not setOk then
            -- B354 production: RID Session runtime log intentionally suppressed.
        if startup.toast then startup.toast("Cherax rejected the RID value. JOIN was not started.",4200) end
        return false
    end
    local clickOk=false
    if joinFeature.OnClick then clickOk=pcall(function() joinFeature:OnClick() end) end
    if not clickOk then
            -- B354 production: RID Session runtime log intentionally suppressed.
        return false
    end
    if startup.toast then startup.toast("Trying local RID join for active host "..tostring(row.username or "").."...",3000) end
    return true
end
startup.live_r_join_340=startup.live_r_join_341

