local function profile_hash_value(source)
    local s
    if type(source)=="table" then
        s=tostring(source.rid or source.username or source.host or source.host_name or source.owner_name or source.author_name or source.title or "StartupHost")
    else
        s=tostring(source or "StartupHost")
    end
    local h=2166136261
    for i=1,#s do h=(h*131 + string.byte(s,i)) % 2147483647 end
    return math.abs(h)
end
local function profile_backdrop_from_source(source)
    local explicit=type(source)=="table" and tonumber(source.profileBackdropId or source.backdrop_id or 0) or 0
    local idx=(explicit and explicit>=1 and explicit<=10) and explicit or ((profile_hash_value(source)%10)+1)
    return string.format("profile_backdrop_%02d",idx), idx
end
local function profile_role_from_source(source)
    local username=type(source)=="table" and tostring(source.profileUsername or source.username or source.host or source.host_name or "") or tostring(source or "")
    if startup.browser_developer_usernames and startup.browser_developer_usernames[username] == true then return "Developer","role_developer" end
    local raw=type(source)=="table" and tostring(source.profileRole or source.role or "") or ""
    local map={
        ["Noob"]="role_noob",["Member"]="role_member",["Regular"]="role_regular",
        ["Developer"]="role_developer",["Moderator"]="role_moderator",
        ["Contributor"]="role_contributor",["Beta Tester"]="role_beta_tester"
    }
    if map[raw] then return raw,map[raw] end
    return "Noob","role_noob"
end
local function profile_rank_from_source(source)
    local raw=type(source)=="table" and tostring(source.profileRank or source.rank or "") or ""
    local keymap={
        ["Top 10,000"]="rank_top_10000",["Top 5000"]="rank_top_5000",["Top 5,000"]="rank_top_5000",
        ["Top 3000"]="rank_top_3000",["Top 3,000"]="rank_top_3000",["Top 1000"]="rank_top_1000",["Top 1,000"]="rank_top_1000",
        ["Top 500"]="rank_top_500",["Top 300"]="rank_top_300",["Top 100"]="rank_top_100",["Top 50"]="rank_top_50",
        ["Top 25"]="rank_top_25",["Top 20"]="rank_top_20",["Top 10"]="rank_top_10",["Top 5"]="rank_top_5",
        ["Top 3"]="rank_top_3",["Top 2"]="rank_top_2",["Top 1"]="rank_top_1"
    }
    if keymap[raw] then return raw,keymap[raw] end
    return "Top 10,000","rank_top_10000"
end

    -- Build 304 Community Reputation:
    -- 1★..5★ comes directly from verified Likes vs Dislikes.
    -- Recent/all-time accepted Browser reports reduce the result, with recent reports
    -- weighted more heavily. Favorites NEVER affect Community Reputation stars.
    local function b304_community_stars(likes,dislikes,reports7d,reportsAll)
        likes=math.max(0,tonumber(likes or 0) or 0)
        dislikes=math.max(0,tonumber(dislikes or 0) or 0)
        reports7d=math.max(0,tonumber(reports7d or 0) or 0)
        reportsAll=math.max(reports7d,tonumber(reportsAll or reports7d) or reports7d)
        local ratings=likes+dislikes
        if ratings<=0 then return 0 end
        local base=1.0+4.0*(likes/ratings)
        local olderReports=math.max(0,reportsAll-reports7d)
        local reportPenalty=math.min(2.0,reports7d*0.25+olderReports*0.05)
        local stars=math.max(1.0,math.min(5.0,base-reportPenalty))
        return math.floor(stars*100+0.5)/100
    end

    local function b304_star_label(value)
        local stars=math.max(0,math.min(5,tonumber(value or 0) or 0))
        stars=math.floor(stars*100+0.5)/100
        local whole=math.floor(stars+0.00001)
        local frac=stars-whole
        if math.abs(frac)<0.001 then return string.format("%.0f",stars) end
        if math.abs(frac-0.5)<0.001 then return string.format("%.1f",stars) end
        return string.format("%.2f",stars)
    end

    local function b304_draw_star_row(value)
        local stars=math.max(0,math.min(5,tonumber(value or 0) or 0))
        for i=1,5 do
            if stars>=i then
                purple("★")
            elseif stars>(i-1) then
                -- Amber star = fractional star; the exact hundredth is printed below.
                amber("★")
            else
                dim("☆")
            end
            if i<5 and ImGui.SameLine then ImGui.SameLine() end
        end
    end
    local function ring(percent,size,mode)
        percent=clamp(percent); size=tonumber(size or 112) or 112
        local lx=ImGui.GetCursorPosX and ImGui.GetCursorPosX() or 0; local ly=ImGui.GetCursorPosY and ImGui.GetCursorPosY() or 0
        local a,b=ImGui.GetCursorScreenPos(); local x,y; if type(a)=="table" then x=tonumber(a.x or a[1] or 0) or 0; y=tonumber(a.y or a[2] or 0) or 0 else x=tonumber(a or 0) or 0; y=tonumber(b or 0) or 0 end
        local cx=x+size/2; local cy=y+size/2; local rad=size/2-8; local rr,gg,bb=56,235,93; if mode=="PURPLE" then rr,gg,bb=177,68,255 end; if percent<70 then rr,gg,bb=255,181,48 end; if percent<55 then rr,gg,bb=255,64,70 end
        if ImGui.AddCircle then ImGui.AddCircle(cx,cy,rad,44,53,70,255,64,7) end; local segs=64; local on=math.floor(segs*percent/100+.5); local st=-math.pi/2
        if ImGui.AddLine then for i=0,on-1 do local a1=st+i*2*math.pi/segs; local a2=st+(i+1)*2*math.pi/segs; ImGui.AddLine(cx+math.cos(a1)*rad,cy+math.sin(a1)*rad,cx+math.cos(a2)*rad,cy+math.sin(a2)*rad,rr,gg,bb,255,7) end end
        if ImGui.AddCircleFilled then ImGui.AddCircleFilled(cx,cy,rad-10,5,10,18,245,64) end; if ImGui.Dummy then ImGui.Dummy(size,size) end
        -- Build 273: dynamically measure the percentage string so it remains centered for 1-3 digits.
        if ImGui.SetCursorPosX and ImGui.SetCursorPosY then
            local label=tostring(math.floor(percent+.5)).."%"
            local scale=1.08
            if ImGui.SetWindowFontScale then direct_call(ImGui.SetWindowFontScale,scale) end
            local tw,th=nil,nil
            if ImGui.CalcTextSize then
                local ok,first,second=direct_call(ImGui.CalcTextSize,label)
                if ok then
