            end
            if not tw or tw<=0 then tw=#label*8.5*scale end
            if not th or th<=0 then th=16*scale end
            ImGui.SetCursorPosX(lx+math.max(0,(size-tw)*.5))
            ImGui.SetCursorPosY(ly+math.max(0,(size-th)*.5))
            white(label)
            if ImGui.SetWindowFontScale then direct_call(ImGui.SetWindowFontScale,1.056) end
            ImGui.SetCursorPosX(lx); ImGui.SetCursorPosY(ly+size)
        end
    end
