    -- Build 243: use Cherax's all-in-one ImGui.Combo binding. This is the same native
    -- widget pattern used successfully by other Cherax Lua scripts. It avoids the
    -- popup/Selectable input issue seen in this dedicated Browser child layout.
    local function combo(id,preview,items,setter,width)
        items=items or {}
        if #items==0 or not (ImGui and ImGui.Combo) then return false end
        local current=0
        for i,v in ipairs(items) do if tostring(v)==tostring(preview) then current=i-1 break end end
        if width and ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(width) end
        local label="##B243Combo_"..tostring(id)
        local ok,a,b=direct_call(ImGui.Combo,label,current,items,#items,math.min(#items,12))
        if not ok then ok,a,b=direct_call(ImGui.Combo,label,current,items) end
        if not ok then return false end
        local idx=nil
        if type(a)=="number" then idx=math.floor(a) elseif type(b)=="number" then idx=math.floor(b) end
        if idx==nil then return false end
        if idx<0 then idx=0 elseif idx>#items-1 then idx=#items-1 end
        if idx~=current then
            local value=items[idx+1]
            if value~=nil then setter(value); return true end
        end
        return false
    end
