    local function host_policy_text(category,activity)
        category=tostring(category or "NORMAL"):upper(); activity=tostring(activity or "GENERAL SESSION"):upper()
        if category=="VEHICLES" then
            if activity:find("CAR MEET",1,true) then return "YOU are the Session Host and event organizer. Pick the meet location, vehicle theme/class, meetup rules, and what happens after the meet (photos, cruise, judging, etc.). Stay in the session and actively host the meet." end
            if activity:find("DRIFT",1,true) or activity:find("TOUGE",1,true) then return "YOU are the Session Host and event organizer. Pick the drift/touge location or route, run format, vehicle rules, and any DriftGod requirement. Stay in the session and coordinate starts, resets, and fair play." end
            if activity:find("RACING",1,true) or activity:find("DRAG",1,true) then return "YOU are the Session Host and race organizer. Pick the start/finish or circuit, vehicle class, number of runs/laps, start method, and race rules before players arrive." end
            return "YOU are the Session Host and activity organizer. Pick the route/location, vehicle rules, meetup point, and clear activity format. Stay in the session and lead the event you advertised."
        elseif category=="WAR" then
            if activity:find("PVP",1,true) then return "YOU are the Session Host and PVP organizer. Pick the combat location, boundaries, teams if any, and weapon rules. Clearly state whether this is open weapons, Snipers Only, RPGs, or another restriction. Stay and moderate the match." end
            return "YOU are the Session Host and war-event organizer. Pick the battlefield, teams, objective, vehicle/weapon rules, respawn/reset rules, and win condition. Stay in the session and run the advertised mode."
        elseif category=="MINIGAMES" then
            return "YOU are the Session Host and minigame organizer. Pick the play area, explain the rules and boundaries, set teams/rounds if needed, and configure any required host-only script or protection compatibility before starting."
        elseif category=="ROLEPLAYING" then
            return "YOU are the Session Host and roleplay organizer. Pick the scenario/location, assign or explain roles, establish boundaries and conduct rules, and keep the session organized around the advertised roleplay."
        elseif category=="SOCIAL" then
            return "YOU are the Session Host and social-event organizer. Pick the meetup location and activity, set the voice-chat expectation, and keep the lobby welcoming and aligned with the advertised event."
        elseif category=="ROCKSTAR JOBS" then
            if activity:find("HEIST",1,true) then
                return "HEISTS can be posted with only you in the session. You must still be the GTA Session Host. Startup will list the Heists activity immediately so Browser users can find and join your hosted session before you launch or invite into the heist."
            end
            return "R* Rockstar Created Jobs and R* Community Jobs can be armed with only you in the session. After leaving the wizard, launch the job through ESC > Online > Jobs > Play Job > Rockstar Created / Community Jobs > Pick a Job. Startup waits for the active Rockstar Job and its Content ID, then lists your hosted job automatically."
        end
        return "YOU are the Session Host. A Normal session has no special activity requirement, but you are still responsible for remaining in the session, maintaining the advertised lobby, and following Startup Browser policy."
    end
    local function host_current_players() return math.max(0,math.floor(tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0)) end
    local function host_is_local_session_host() return startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true end
    local HOST_CUSTOM_MIN_PLAYERS_329=11
    local function host_is_solo_exception_329(category,activity)
        local cat=tostring(category or ""):upper()
        local act=tostring(activity or ""):upper()
        if cat~="ROCKSTAR JOBS" then return false end
        return act=="ROCKSTAR CREATED" or act=="COMMUNITY JOBS" or act=="HEISTS"
    end
    local function host_custom_population_ok_329(category,activity,players)
        players=math.max(0,math.floor(tonumber(players or 0) or 0))
        if host_is_solo_exception_329(category,activity) then return players>=1,1 end
        return players>=HOST_CUSTOM_MIN_PLAYERS_329,HOST_CUSTOM_MIN_PLAYERS_329
    end
    local function clear_activity_publication(reason)
        if ui.host_published~=true and startup.browser_activity_publication==nil then return end
        ui.host_published=false; ui.host_publish_started_ms=0; startup.browser_activity_publication=nil
        if startup.browser_events_unpublish then startup.browser_events_unpublish(tostring(reason or "HOST_LEFT")) end
        if startup.browser_backend then startup.browser_backend.next_heartbeat_ms=0 end
        if startup.log then startup.log("[Browser Activity] Publication removed | "..tostring(reason or "session ended")) end
    end
    local function publish_activity_session()
        local players=host_current_players()
        if ui.host_mode=="NORMAL" then if startup.browser_backend then startup.browser_backend.next_heartbeat_ms=0 end; if startup.toast then startup.toast("Normal hosted sessions are enrolled automatically in Live Session.",3500) end; return true end
        local category=tostring(ui.host_category or ""):upper()
        local activity=tostring(ui.host_activity or ""):upper()
        local soloException=host_is_solo_exception_329(category,activity)
        local populationOK,populationMinimum=host_custom_population_ok_329(category,activity,players)

        -- Build 329: every structured custom session is host-only. R* Jobs / Heists are
        -- allowed with the host alone; all other custom categories require 11+ current players.
        if category=="ROCKSTAR JOBS" and activity~="HEISTS" then
            if players<1 then if startup.toast then startup.toast("R* Jobs require at least 1 player (you) before arming the listing.",4500) end; return false end
            if ui.host_published==true or startup.browser_activity_publication~=nil then clear_activity_publication("switched to R* Jobs auto listing") end
            ui.rockstar_job_auto_armed=true
            ui.rockstar_job_auto_listed=false
            ui.rockstar_job_wait_notice=false
            ui.rockstar_job_source=tostring(ui.host_activity or "ROCKSTAR CREATED")
            startup.browser_activity_publication=nil
            if startup.browser_backend then startup.browser_backend.next_heartbeat_ms=0 end
            if startup.toast then startup.toast("R* Job auto-listing armed. 1 player is enough. Launch your Rockstar Created / Community Job when ready.",7000) end
            if startup.log then startup.log("[R* Jobs 318] AUTO_LIST_ARMED | source="..tostring(ui.rockstar_job_source)) end
            return true
        end
        if not host_is_local_session_host() then if startup.toast then startup.toast("You must be the current GTA Session Host to publish an Activity Session.",4500) end; return false end
        if not populationOK then
            if startup.toast then startup.toast("Custom Sessions require at least "..tostring(populationMinimum).." players. 10 players or fewer cannot publish this activity. Current: "..tostring(players)..". R* Jobs / Heists / Community Jobs can post with 1.",6500) end
            return false
        end

        -- HEISTS are a live Browser activity, not a Content-ID auto-detected Rockstar Job.
        -- Publish immediately with the same 1-player exception while preserving host-only safety.
        if category=="ROCKSTAR JOBS" and activity=="HEISTS" then
            local bb=startup.browser_backend
            if not bb or tostring(bb.token or "")=="" then
                local why=tostring(bb and bb.status or "BACKEND_NOT_CONNECTED")
                if startup.toast then startup.toast("Startup Browser Heists listing was NOT published: "..why,5500) end
                return false
            end
            local was=ui.host_published==true
            ui.rockstar_job_auto_armed=false; ui.rockstar_job_auto_listed=false; ui.rockstar_job_wait_notice=false
            ui.host_published=true; ui.host_publish_started_ms=Time and Time.GetEpocheMs and Time.GetEpocheMs() or math.floor(os.clock()*1000)
            startup.browser_activity_publication={category="ROCKSTAR JOBS",activity="HEISTS",mic_requirement=ui.host_mic,starts=ui.host_time,max_players=ui.host_max,published_players=players}
            bb.next_heartbeat_ms=0; bb.next_fetch_ms=0
            if startup.toast then startup.toast(was and "Heists listing updated." or "Heists listing published. You can post with only yourself in the session.",5500) end
            return true
        end

        local bb=startup.browser_backend
        if not bb or tostring(bb.token or "")=="" then
            local why=tostring(bb and bb.status or "BACKEND_NOT_CONNECTED")
            if startup.browser_events_backend then startup.browser_events_backend.status=why end
            if startup.toast then startup.toast("Startup Browser event was NOT published: "..why,5500) end
            if startup.log then startup.log("[Browser Events] PUBLISH_BLOCKED | "..why.." | localPlayers="..tostring(players)) end
            return false
        end
        local was=ui.host_published==true
        ui.host_published=true; ui.host_publish_started_ms=Time and Time.GetEpocheMs and Time.GetEpocheMs() or math.floor(os.clock()*1000)
        -- Build 267 security simplification: Custom Sessions publish catalog-defined fields only.
        -- No arbitrary location / plan / rules free text is transmitted or retained by Browser publication.
        startup.browser_activity_publication={category=ui.host_category,activity=ui.host_activity,mic_requirement=ui.host_mic,starts=ui.host_time,max_players=ui.host_max,published_players=players}
        if startup.browser_events_publish then
            startup.browser_events_publish({
                session_type=ui.host_mode, category=ui.host_category, activity=ui.host_activity,
                title=ui.host_activity,
                mic_requirement=ui.host_mic, start_mode=ui.host_time, max_players=ui.host_max
            })
        end
        if startup.browser_backend then startup.browser_backend.next_heartbeat_ms=0 end
        if startup.toast then
            startup.toast(
                was
                    and "Event updated. You remain responsible for actively running it while published."
                    or "Event published. You are responsible for actively running and managing it while it is live.",
                6000
            )
        end
        if startup.log then startup.log("[Browser Activity] "..(was and "Updated" or "Published").." | category="..tostring(ui.host_category).." | activity="..tostring(ui.host_activity).." | players="..tostring(players)) end
        return true
    end
    -- Build 241 production-beta Rockstar Job detector + artwork resolver.
    -- Build 241 retains the proven read-only native script-thread inventory so we scan the ACTUAL
    -- active GTA activity controller (for example am_mp_race) instead of assuming every
    -- Rockstar Job uses fm_mission_controller.
    -- Cherax exposes file-path texture loading, so remote artwork is fetched into one
    -- disposable cache file, loaded as a texture, and deleted when the activity ends.
    -- No Rockstar artwork is kept as a permanent Startup asset.
    local jobart=startup.rockstar_job_art or {}; startup.rockstar_job_art=jobart
    jobart.activity=jobart.activity==true; jobart.transition=jobart.transition==true
    jobart.scan_busy=jobart.scan_busy==true; jobart.fetch_busy=jobart.fetch_busy==true
    jobart.content_id=tostring(jobart.content_id or ""); jobart.job_name=tostring(jobart.job_name or "")
    jobart.cdn_base=tostring(jobart.cdn_base or ""); jobart.image_url=tostring(jobart.image_url or "")
    jobart.status=tostring(jobart.status or "Waiting for a Rockstar activity...")
    jobart.source_script=tostring(jobart.source_script or ""); jobart.source_local=tonumber(jobart.source_local or -1) or -1
    jobart.last_scan_ms=tonumber(jobart.last_scan_ms or 0) or 0; jobart.last_activity_ms=tonumber(jobart.last_activity_ms or 0) or 0
    jobart.texture_id=tonumber(jobart.texture_id or 0) or 0; jobart.texture_srv=jobart.texture_srv or nil
    jobart.texture_load_started=jobart.texture_load_started==true; jobart.loaded_texture_count=tonumber(jobart.loaded_texture_count or 0) or 0
    jobart.manual_input=tostring(jobart.manual_input or "")
    jobart.job_type=tostring(jobart.job_type or "")
    jobart.job_status=tostring(jobart.job_status or "")
    jobart.debug_visible=jobart.debug_visible==true
    jobart.preview_cache=type(jobart.preview_cache)=="table" and jobart.preview_cache or {}
    jobart.remote_cache=type(jobart.remote_cache)=="table" and jobart.remote_cache or {}
    jobart.remote_pending=type(jobart.remote_pending)=="table" and jobart.remote_pending or {}
    jobart.max_texture_cache=math.max(8,tonumber(jobart.max_texture_cache or 32) or 32)
    jobart.candidate_count=tonumber(jobart.candidate_count or 0) or 0
    jobart.active_scripts=type(jobart.active_scripts)=="table" and jobart.active_scripts or {}
    jobart.active_script_summary=tostring(jobart.active_script_summary or "")
    jobart.string_sample_count=tonumber(jobart.string_sample_count or 0) or 0
    jobart.scan_generation=tonumber(jobart.scan_generation or 0) or 0
    jobart.cache_dir=tostring(jobart.cache_dir or startup.path_join(startup.storage_dir or startup.save_dir or startup.lua_dir or ".","Cache\\RockstarJobs"))
    jobart.cache_path=tostring(jobart.cache_path or startup.path_join(jobart.cache_dir,"active_job.jpg"))

    local JOB_ACTIVITY_HASH=0x05095437424397FA
    local JOB_TRANSITION_STARTED_HASH=0x53FA83401D9C07FE
    local JOB_TRANSITION_BUSY_HASH=0x520F3282A53D26B7
    local JOB_THREADS_HASH=0x2C83A9DA6BFFC4F9
    local JOB_CONTENT_MODIFIER_HASH=0x187382F8A3E0A6C3
    -- Native script-thread iterator. Read-only and used only by the Rockstar Job lab.
    local JOB_THREAD_ITER_RESET_HASH=0xDADFADA5A20143A8
    local JOB_THREAD_ITER_NEXT_HASH=0x30B4FA1C82DD4B9F
    local JOB_THREAD_NAME_HASH=0x05A42BA9FC8DA96B

    local function job_now()
        if Time and Time.GetEpocheMs then local ok,v=direct_call(Time.GetEpocheMs); if ok then return tonumber(v or 0) or 0 end end
        if startup.now then return tonumber(startup.now() or 0) or 0 end
        return math.floor((os.clock and os.clock() or 0)*1000)
    end
    local function job_yield(ms)
        if startup.yield then startup.yield(ms or 0) elseif Script and Script.Yield then Script.Yield(ms or 0) end
    end
    local function job_log(tag,msg)
        if startup.log then startup.log("[Rockstar Job Art] "..tostring(tag or "INFO").." | "..tostring(msg or "")) end
    end
    local function job_native_bool(hash)
        if not (Natives and Natives.InvokeBool) then return false end
        local ok,v=direct_call(Natives.InvokeBool,hash)
        return ok and v==true
    end
    local function job_native_int(hash,...)
        if not (Natives and Natives.InvokeInt) then return nil end
        local ok,v=direct_call(Natives.InvokeInt,hash,...)
        if not ok then return nil end
        return tonumber(v)
    end
    local function job_native_void(hash,...)
        if not (Natives and Natives.InvokeVoid) then return false end
        local ok=direct_call(Natives.InvokeVoid,hash,...)
        return ok==true
    end
    local function job_native_string(hash,...)
        if not (Natives and Natives.InvokeString) then return nil end
        local ok,v=direct_call(Natives.InvokeString,hash,...)
        if not ok or type(v)~="string" then return nil end
        return v
    end
    local function job_file_exists(path)
        if startup.file_exists then return startup.file_exists(path) end
        if FileMgr and FileMgr.DoesFileExist then local ok,v=direct_call(FileMgr.DoesFileExist,path); if ok then return v==true end end
        local f=io and io.open and io.open(path,"rb") or nil; if f then f:close(); return true end
        return false
    end
    local function job_remove_cache()
        local path=tostring(jobart.cache_path or "")
        if path=="" then return end
        if startup.raw_remove_file then direct_call(startup.raw_remove_file,path)
        else
            if os and os.remove then direct_call(os.remove,path) end
            if FileMgr and FileMgr.DeleteFile then direct_call(FileMgr.DeleteFile,path) end
        end
    end
    local function job_reset_texture(remove_file)
        jobart.texture_srv=nil; jobart.texture_id=0; jobart.texture_load_started=false
        if remove_file~=false then job_remove_cache() end
    end
    local function job_clear(reason)
        jobart.scan_generation=(tonumber(jobart.scan_generation or 0) or 0)+1
        jobart.scan_busy=false; jobart.fetch_busy=false
        jobart.content_id=""; jobart.job_name=""; jobart.job_type=""; jobart.job_status=""; jobart.cdn_base=""; jobart.image_url=""
        jobart.source_script=""; jobart.source_local=-1; jobart.candidate_count=0
        jobart.active_scripts={}; jobart.active_script_summary=""; jobart.string_sample_count=0
        jobart.status=tostring(reason or "Waiting for a Rockstar activity...")
        job_reset_texture(true)
    end
    local function job_activity_state()
        local activity=job_native_bool(JOB_ACTIVITY_HASH)
        local transition=job_native_bool(JOB_TRANSITION_STARTED_HASH) or job_native_bool(JOB_TRANSITION_BUSY_HASH)
        jobart.activity=activity; jobart.transition=transition
        if activity then jobart.last_activity_ms=job_now() end
        return activity,transition
    end
    local function job_extract_content_id(value)
        local s=tostring(value or "")
        if s=="" then return nil end
        s=s:gsub("\\u002[fF]","/"):gsub("\\/","/")
        local id=s:match("/games/gtav/jobs/job/([%w_%-]+)") or s:match("/job/gtav/([%w_%-]+)") or s:match("/gta5mission/%d+/([%w_%-]+)")
        if id and #id>=16 and #id<=40 then return id end
        local exact=s:match("^%s*([%w_%-]+)%s*$")
        if exact and #exact>=20 and #exact<=28 then return exact end
        return nil
    end
    local function job_token_candidates(value,out,seen,script_name,local_index)
        local s=tostring(value or "")
        if s=="" then return end
        local direct=job_extract_content_id(s)
        local function add(token)
            token=tostring(token or "")
            if #token<20 or #token>28 or seen[token] then return end
            local has_upper=token:find("%u")~=nil; local has_lower=token:find("%l")~=nil; local has_digit=token:find("%d")~=nil
            if not (has_upper and has_lower and has_digit) then return end
            seen[token]=true
            out[#out+1]={id=token,script=script_name or "",local_index=tonumber(local_index or -1) or -1}
        end
        if direct then add(direct) end
        for token in s:gmatch("[%w_%-]+") do add(token) end
    end
    local function job_script_thread_count(name)
        if not (Utils and Utils.Joaat) then return 0,nil end
        local ok,h=direct_call(Utils.Joaat,tostring(name or "")); if not ok then return 0,nil end
        local hash=tonumber(h); if not hash then return 0,nil end
        local n=job_native_int(JOB_THREADS_HASH,hash)
        return math.max(0,math.floor(tonumber(n or 0) or 0)),hash
    end
    local function job_list_active_scripts()
        local out,seen={},{}
        if not (Natives and Natives.InvokeVoid and Natives.InvokeInt and Natives.InvokeString) then
            jobart.active_scripts=out; jobart.active_script_summary="iterator unavailable"; return out
        end
        if not job_native_void(JOB_THREAD_ITER_RESET_HASH) then
            jobart.active_scripts=out; jobart.active_script_summary="iterator reset failed"; return out
        end
        for _=1,160 do
            local tid=job_native_int(JOB_THREAD_ITER_NEXT_HASH)
            if not tid or tid==0 then break end
            local name=job_native_string(JOB_THREAD_NAME_HASH,tid)
            name=tostring(name or "")
            if name~="" and not seen[name] then
                seen[name]=true
                out[#out+1]={name=name,thread_id=tid}
            end
        end
        table.sort(out,function(a,b) return tostring(a.name)<tostring(b.name) end)
        jobart.active_scripts=out
        local names={}; for i,v in ipairs(out) do if i<=18 then names[#names+1]=tostring(v.name) end end
        jobart.active_script_summary=table.concat(names,", ")
        job_log("ACTIVE_SCRIPTS",(#out).." unique | "..jobart.active_script_summary)
        return out
    end
    local function job_script_scan_priority(name)
        local n=tostring(name or ""):lower()
        if n=="" then return 0 end
        if n:find("am_mp_race",1,true) then return 100 end
        if n:find("race",1,true) then return 96 end
        if n:find("deathmatch",1,true) or n:find("survival",1,true) then return 94 end
        if n:find("advers",1,true) or n:find("mission_controller",1,true) then return 92 end
        if n:find("fmmc",1,true) or n:find("launcher",1,true) then return 90 end
        if n:find("fm_content",1,true) or n:find("content",1,true) then return 88 end
        if n:find("am_mp",1,true) then return 84 end
        if n:find("mission",1,true) or n:find("activity",1,true) then return 80 end
        if n=="creator" then return 60 end
        if n=="freemode" then return 10 end
        return 0
    end
    local function job_local_limit(name)
        local n=tostring(name or ""):lower()
        if n:find("mission_controller",1,true) then return 18000 end
        if n:find("fmmc",1,true) then return 14000 end
        if n:find("am_mp",1,true) or n:find("race",1,true) or n:find("survival",1,true) or n:find("deathmatch",1,true) then return 14000 end
        if n:find("fm_content",1,true) or n:find("content",1,true) then return 12000 end
        if n=="creator" then return 8000 end
        if n=="freemode" then return 9000 end
        return 7000
    end
    local function job_string_sample(value)
        local v=tostring(value or "")
        if #v<4 or #v>120 then return nil end
        if v:find("[\r\n\t]") then return nil end
        local letters=select(2,v:gsub("[%a]",""))
        if letters<3 then return nil end
        local printable=0
        for i=1,#v do local b=v:byte(i); if b and b>=32 and b<=126 then printable=printable+1 end end
        if printable/#v<0.92 then return nil end
        return v
    end

    local function job_classify_type()
        local names={}
        for _,v in ipairs(type(jobart.active_scripts)=="table" and jobart.active_scripts or {}) do names[#names+1]=tostring(v.name or ""):lower() end
        local joined=" "..table.concat(names," ").." "
        if joined:find("race",1,true) then return "RACE" end
        if joined:find("survival",1,true) then return "SURVIVAL" end
        if joined:find("deathmatch",1,true) then return "DEATHMATCH" end
        if joined:find("advers",1,true) then return "ADVERSARY MODE" end
        if joined:find("am_arena",1,true) or joined:find("arena",1,true) then return "ARENA / ADVERSARY" end
        if joined:find("mission_controller",1,true) then return "MISSION" end
        return "ROCKSTAR JOB"
    end
    local function job_content_modifier(id)
        if not (Utils and Utils.Joaat) then return nil end
        local ok,h=direct_call(Utils.Joaat,tostring(id or "")); if not ok or not h then return nil end
        return job_native_int(JOB_CONTENT_MODIFIER_HASH,h)
    end
    local function job_curl_setopt(curl,name,fallback,value)
        if not curl or not curl.Setopt then return false end
        local opt=nil; if eCurlOption then opt=eCurlOption[name] end; if opt==nil then opt=fallback end
        return direct_call(function() curl:Setopt(opt,value) end)
    end
    local function job_http_get(url,timeout_ms)
        if not (Curl and Curl.Easy) then return nil,"CURL_UNAVAILABLE" end
        local ok,body,err=direct_call(function()
            local c=Curl.Easy()
            job_curl_setopt(c,"CURLOPT_URL",10002,tostring(url or ""))
            job_curl_setopt(c,"CURLOPT_FOLLOWLOCATION",52,1)
            job_curl_setopt(c,"CURLOPT_USERAGENT",10018,"Mozilla/5.0 Startup-Cherax RockstarJobArt/241")
            job_curl_setopt(c,"CURLOPT_TIMEOUT_MS",155,tonumber(timeout_ms or 6500) or 6500)
            job_curl_setopt(c,"CURLOPT_CONNECTTIMEOUT_MS",156,3500)
            if c.AddHeader then direct_call(function() c:AddHeader("Accept: */*") end) end
            c:Perform()
            local ticks=0; while not c:GetFinished() and ticks<160 do job_yield(50); ticks=ticks+1 end
            if not c:GetFinished() then return nil,"TIMEOUT" end
            local code,data=c:GetResponse()
            local success=(code==0 or code==true or (eCurlCode and code==eCurlCode.CURLE_OK))
            if not success then return nil,"CURL_"..tostring(code) end
            return type(data)=="string" and data or tostring(data or ""),nil
        end)
        if not ok then return nil,"REQUEST_EXCEPTION" end
        return body,err
    end
    local function job_is_jpeg(data)
        return type(data)=="string" and #data>500 and data:byte(1)==0xFF and data:byte(2)==0xD8 and data:byte(3)==0xFF
    end
    local function job_is_png(data)
        return type(data)=="string" and #data>100 and data:byte(1)==137 and data:sub(2,4)=="PNG"
    end
    local function job_write_image(data)
        if not (job_is_jpeg(data) or job_is_png(data)) then return false end
        if FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir,jobart.cache_dir) end
        job_remove_cache()
        local f=io and io.open and io.open(jobart.cache_path,"wb") or nil
        if not f then return false end
        f:write(data); f:close()
        return true
    end
    local function job_extract_cloud_url(body,content_id)
        local s=tostring(body or "")
        if s=="" then return nil,nil end
        s=s:gsub("\\u002[fF]","/"):gsub("\\/","/"):gsub("&amp;","&")
        local direct=s:match("(https://prod%.cloud%.rockstargames%.com/ugc/gta5mission/[^%s\"'<>]+%.jpg)")
        if direct then return direct,direct:match("^(.+)/[^/]+$") end
        local base=s:match("(https://prod%.cloud%.rockstargames%.com/ugc/gta5mission/[^%s\"'<>]+/"..tostring(content_id or "")..")")
        if base then return base.."/2_0.jpg",base end
        local generic=s:match("(https://prod%.cloud%.rockstargames%.com/ugc/gta5mission/%d+/[%w_%-]+)")
        if generic and (content_id==nil or content_id=="" or generic:find(tostring(content_id),1,true)) then return generic.."/2_0.jpg",generic end
        return nil,nil
    end
    local function job_extract_name(body)
        local s=tostring(body or "")
        if s=="" then return "" end
        local name=s:match('"nm"%s*:%s*"([^"\\]-)"') or s:match('"name"%s*:%s*"([^"\\]-)"')
        if not name then return "" end
        name=name:gsub("\\u0026","&"):gsub("\\/","/"):gsub('\\"','"')
        return name
    end
    local function job_try_metadata_from_base(base)
        base=tostring(base or ""); if base=="" then return "" end
        for _,suffix in ipairs({"/0_0_en.json","/0_1_en.json"}) do
            local body=job_http_get(base..suffix,4200)
            if body and body~="" and body:sub(1,1)=="{" then
                local nm=job_extract_name(body)
                if nm and nm~="" then job_log("META_READY","name="..tostring(nm)); return nm end
            end
        end
        return ""
    end
    local function job_try_image_url(url,content_id,base,name_hint)
        local cid=tostring(content_id or jobart.content_id or "")
        local cached=jobart.preview_cache[cid]
        if cached and cached.srv then
            jobart.content_id=cid; jobart.texture_srv=cached.srv; jobart.texture_id=tonumber(cached.texture_id or 0) or 0
            jobart.image_url=tostring(cached.image_url or url or ""); jobart.cdn_base=tostring(cached.cdn_base or base or "")
            jobart.job_name=tostring(cached.job_name or name_hint or ""); jobart.job_type=tostring(cached.job_type or job_classify_type())
            jobart.job_status="IN PROGRESS"; jobart.status="Official Rockstar preview ready from memory cache."
            job_log("CACHE_HIT","contentId="..cid); return true
        end
        jobart.status="Resolving official Rockstar preview..."
        local data=job_http_get(url,5500)
        if not job_is_jpeg(data) and not job_is_png(data) then return false end
        if not job_write_image(data) then return false end
        job_reset_texture(false)
        jobart.content_id=cid
        jobart.image_url=tostring(url or ""); jobart.cdn_base=tostring(base or "")
        local nm=tostring(name_hint or ""); if nm=="" then nm=job_try_metadata_from_base(base) end
        if nm~="" then jobart.job_name=nm end
        jobart.job_type=job_classify_type(); jobart.job_status="IN PROGRESS"
        jobart.preview_cache[cid]=jobart.preview_cache[cid] or {}
        local ce=jobart.preview_cache[cid]; ce.image_url=jobart.image_url; ce.cdn_base=jobart.cdn_base; ce.job_name=jobart.job_name; ce.job_type=jobart.job_type
        jobart.status="Official Rockstar preview ready."
        job_log("IMAGE_READY","contentId="..tostring(jobart.content_id).." | url="..tostring(jobart.image_url))
        return true
    end
    local function job_resolve_content(id)
        id=tostring(id or ""); if id=="" then return false end
        jobart.fetch_busy=true; jobart.status="Resolving Rockstar job "..id.."..."
        local pages={
            "https://socialclub.rockstargames.com/games/gtav/jobs/job/"..id,
            "https://socialclub.rockstargames.com/job/gtav/"..id
        }
        for _,page in ipairs(pages) do
            local body=job_http_get(page,6500)
            if body and body~="" then
                local img,base=job_extract_cloud_url(body,id)
                local nm=job_extract_name(body)
                if img and job_try_image_url(img,id,base,nm) then jobart.fetch_busy=false; return true end
            end
        end
        -- BiggerScript-compatible UGC fallback. These are not assumed to be universal;
        -- every candidate is validated by checking that Rockstar actually returns image bytes.
        local versions={6285,5131,5828,5483,3816,0,1,2,3,4,5}
        for _,ver in ipairs(versions) do
            local base="https://prod.cloud.rockstargames.com/ugc/gta5mission/"..tostring(ver).."/"..id
            if job_try_image_url(base.."/2_0.jpg",id,base,"") then jobart.fetch_busy=false; return true end
        end
        jobart.fetch_busy=false; jobart.status="Content ID found, but Rockstar preview artwork was not resolved yet."
        job_log("IMAGE_MISS","contentId="..id)
        return false
    end
    local function job_load_texture()
        if jobart.texture_srv then return jobart.texture_srv end
        if not job_file_exists(jobart.cache_path) then return nil end
        if not (Texture and Texture.GetTexture) then jobart.status="Texture API unavailable."; return nil end
        if (tonumber(jobart.texture_id or 0) or 0)==0 then
            if jobart.texture_load_started then return nil end
            if (tonumber(jobart.loaded_texture_count or 0) or 0)>=tonumber(jobart.max_texture_cache or 32) then jobart.status="Rockstar preview memory cache is full; reload Startup to load additional unique job artwork."; return nil end
            jobart.texture_load_started=true
            local ok,id=direct_call(function()
                if Texture.LoadTextureAsync then return Texture.LoadTextureAsync(jobart.cache_path) end
                if Texture.LoadTexture then return Texture.LoadTexture(jobart.cache_path) end
                return 0
            end)
            id=ok and tonumber(id or 0) or 0
            if id==0 then jobart.texture_load_started=false; jobart.status="Rockstar artwork texture allocation failed."; return nil end
            jobart.texture_id=id; jobart.loaded_texture_count=(tonumber(jobart.loaded_texture_count or 0) or 0)+1
        end
        local id=tonumber(jobart.texture_id or 0) or 0
        if Texture.IsTextureValid then local ok,v=direct_call(Texture.IsTextureValid,id); if ok and v~=true then return nil end end
        local ok,tex=direct_call(Texture.GetTexture,id); if not ok or not tex then return nil end
        local ok2,srv=direct_call(function() return tex:GetCurrent() end); if not ok2 or not srv then return nil end
        jobart.texture_srv=srv
        local cid=tostring(jobart.content_id or "")
        if cid~="" then
            jobart.preview_cache[cid]=jobart.preview_cache[cid] or {}
            local ce=jobart.preview_cache[cid]; ce.srv=srv; ce.texture_id=id; ce.image_url=jobart.image_url; ce.cdn_base=jobart.cdn_base; ce.job_name=jobart.job_name; ce.job_type=jobart.job_type
        end
        return srv
    end
    local function job_draw_image(width,height)
        local srv=job_load_texture(); if not srv or not ImGui then return false end
        local x,y=0,0; if ImGui.GetCursorScreenPos then local ok,a,b=direct_call(ImGui.GetCursorScreenPos); if ok then if type(a)=="number" then x,y=a,b elseif type(a)=="table" then x=tonumber(a.x or a[1] or 0) or 0; y=tonumber(a.y or a[2] or 0) or 0 end end end
        width=tonumber(width or 320) or 320; height=tonumber(height or 180) or 180
        if ImGui.AddImage then local ok=direct_call(ImGui.AddImage,srv,x,y,x+width,y+height); if ok then if ImGui.Dummy then ImGui.Dummy(width,height) end; return true end end
        return false
    end
    local function job_draw_srv(srv,width,height)
        if not srv or not ImGui then return false end
        local x,y=0,0; if ImGui.GetCursorScreenPos then local ok,a,b=direct_call(ImGui.GetCursorScreenPos); if ok then if type(a)=="number" then x,y=a,b elseif type(a)=="table" then x=tonumber(a.x or a[1] or 0) or 0; y=tonumber(a.y or a[2] or 0) or 0 end end end
        width=tonumber(width or 300) or 300; height=tonumber(height or 169) or 169
        if ImGui.AddImage then local ok=direct_call(ImGui.AddImage,srv,x,y,x+width,y+height); if ok then if ImGui.Dummy then ImGui.Dummy(width,height) end; return true end end
        return false
    end
    local function job_remote_path(id)
        local safe=tostring(id or ""):gsub("[^%w_%-]",""); if safe=="" then safe="unknown" end
        return startup.path_join(jobart.cache_dir,"remote_"..safe..".jpg")
    end
    local function job_remote_load(entry)
        if entry.srv then return entry.srv end
        if not entry.path or not job_file_exists(entry.path) or not (Texture and Texture.GetTexture) then return nil end
        if tonumber(entry.texture_id or 0)==0 then
            if entry.texture_load_started then return nil end
            if (tonumber(jobart.loaded_texture_count or 0) or 0)>=tonumber(jobart.max_texture_cache or 32) then return nil end
            entry.texture_load_started=true
            local ok,id=direct_call(function() if Texture.LoadTextureAsync then return Texture.LoadTextureAsync(entry.path) end; if Texture.LoadTexture then return Texture.LoadTexture(entry.path) end; return 0 end)
            id=ok and tonumber(id or 0) or 0; if id==0 then entry.texture_load_started=false; return nil end
            entry.texture_id=id; jobart.loaded_texture_count=(tonumber(jobart.loaded_texture_count or 0) or 0)+1
        end
        local id=tonumber(entry.texture_id or 0) or 0
        if Texture.IsTextureValid then local ok,v=direct_call(Texture.IsTextureValid,id); if ok and v~=true then return nil end end
        local ok,tex=direct_call(Texture.GetTexture,id); if not ok or not tex then return nil end
        local ok2,srv=direct_call(function() return tex:GetCurrent() end); if not ok2 or not srv then return nil end
        entry.srv=srv; return srv
    end
    local function job_remote_fetch(id)
        id=tostring(id or ""); if id=="" then return end
        jobart.remote_pending[id]=true
        local versions={6285,5131,5828,5483,3816,0,1,2,3,4,5}
        local found=nil
        for _,ver in ipairs(versions) do
            local base="https://prod.cloud.rockstargames.com/ugc/gta5mission/"..tostring(ver).."/"..id
            local data=job_http_get(base.."/2_0.jpg",5200)
            if job_is_jpeg(data) or job_is_png(data) then found={data=data,url=base.."/2_0.jpg",base=base}; break end
        end
        if found then
            local path=job_remote_path(id); if FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir,jobart.cache_dir) end
            local f=io and io.open and io.open(path,"wb") or nil; if f then f:write(found.data); f:close(); jobart.remote_cache[id]={path=path,image_url=found.url,cdn_base=found.base}; job_log("REMOTE_READY","contentId="..id) end
        else jobart.remote_cache[id]={failed=true}; job_log("REMOTE_MISS","contentId="..id) end
        jobart.remote_pending[id]=nil
    end
    startup.browser_draw_remote_job_preview=function(row,width,height)
        local id=tostring(row and row.rockstarContentId or ""); if id=="" then return false end
        local localCached=jobart.preview_cache[id]
        if localCached and localCached.srv then return job_draw_srv(localCached.srv,width,height) end
        local entry=jobart.remote_cache[id]
        if entry then local srv=job_remote_load(entry); if srv then return job_draw_srv(srv,width,height) end; if entry.failed then return false end end
        if not jobart.remote_pending[id] and Script and Script.QueueJob then Script.QueueJob(function() job_remote_fetch(id) end) end
        return false
    end

    local function job_scan_locals(force)
        local activity=job_activity_state()
        if not activity and force~=true then jobart.status="Not in a Rockstar activity session."; return false end
        if jobart.scan_busy or jobart.fetch_busy then return false end
        if not (ScriptLocal and ScriptLocal.GetString and Utils and Utils.Joaat) then jobart.status="ScriptLocal string scanner unavailable."; return false end
        jobart.scan_busy=true; jobart.scan_generation=(tonumber(jobart.scan_generation or 0) or 0)+1; local generation=jobart.scan_generation
        jobart.last_scan_ms=job_now(); jobart.status="Enumerating active GTA scripts and scanning the real activity controller..."; jobart.candidate_count=0; jobart.string_sample_count=0
        local candidates,seen={},{}
        local active=job_list_active_scripts()
        local scripts,added={},{}
        local function add_script(name,priority)
            name=tostring(name or ""); if name=="" or added[name] then return end
            local threads,hash=job_script_thread_count(name)
            if threads<=0 or not hash then return end
            added[name]=true; scripts[#scripts+1]={name=name,limit=job_local_limit(name),priority=tonumber(priority or job_script_scan_priority(name)) or 0,threads=threads,hash=hash}
        end
        for _,v in ipairs(active) do local p=job_script_scan_priority(v.name); if p>0 then add_script(v.name,p) end end
        -- Known job-family fallbacks are included only when GTA reports a live thread.
        for _,name in ipairs({"am_mp_race","am_mp_deathmatch","am_mp_survival","fm_mission_controller","fm_mission_controller_2020","fm_mission_controller_2025","fm_mission_controller_2026","fmmc_launcher","fmmc_launcher_2020","creator","freemode"}) do add_script(name,job_script_scan_priority(name)) end
        table.sort(scripts,function(a,b) if a.priority~=b.priority then return a.priority>b.priority end return a.name<b.name end)
        if #scripts>10 then while #scripts>10 do table.remove(scripts) end end
        local scan_names={}; for _,e in ipairs(scripts) do scan_names[#scan_names+1]=e.name.."("..e.priority..")" end
        job_log("SCAN_PLAN",table.concat(scan_names,", "))
        local sample_seen={}; local sample_limit=48
        for _,entry in ipairs(scripts) do
            if generation~=jobart.scan_generation then jobart.scan_busy=false; return false end
            local name,limit,threads,hash=entry.name,entry.limit,entry.threads,entry.hash
            if threads>0 and hash then
                job_log("SCAN_SCRIPT",name.." | priority="..tostring(entry.priority).." | threads="..tostring(threads).." | locals=0-"..tostring(limit))
                for i=0,limit do
                    local ok,value=direct_call(ScriptLocal.GetString,hash,i)
                    if ok and type(value)=="string" and value~="" then
                        job_token_candidates(value,candidates,seen,name,i)
                        if jobart.string_sample_count<sample_limit then
                            local sample=job_string_sample(value)
                            if sample and not sample_seen[sample] then
                                sample_seen[sample]=true; jobart.string_sample_count=jobart.string_sample_count+1
                                job_log("STRING_SAMPLE",name.."["..tostring(i).."]="..sample)
                            end
                        end
                    end
                    if #candidates>=32 then break end
                    if i%96==0 then job_yield(1); if generation~=jobart.scan_generation then jobart.scan_busy=false; return false end end
                end
            end
            if #candidates>=32 then break end
        end
        jobart.candidate_count=#candidates
        if #candidates==0 then
            jobart.scan_busy=false; jobart.status="Activity detected, but no Rockstar content ID was found yet. Build 240 logged the actual active GTA scripts + readable local strings for the next pass."
            job_log("SCAN_MISS","no content-id-like strings found | active="..tostring(jobart.active_script_summary).." | samples="..tostring(jobart.string_sample_count))
            return false
        end
        table.sort(candidates,function(a,b)
            local ma=job_content_modifier(a.id); local mb=job_content_modifier(b.id)
            local va=(ma~=nil and ma>=0) and 1 or 0; local vb=(mb~=nil and mb>=0) and 1 or 0
            if va~=vb then return va>vb end
            return #a.id<#b.id
        end)
        job_log("SCAN_CANDIDATES",tostring(#candidates).." candidate(s)")
        for idx,c in ipairs(candidates) do
            if generation~=jobart.scan_generation then jobart.scan_busy=false; return false end
            jobart.status="Validating Rockstar content ID candidate "..tostring(idx).." / "..tostring(#candidates).."..."
            local modifier=job_content_modifier(c.id)
            job_log("CANDIDATE",c.id.." | script="..tostring(c.script).." | local="..tostring(c.local_index).." | modifier="..tostring(modifier))
            -- A non-negative modifier is a strong local hint; HTTP image resolution is the final validation.
            if job_resolve_content(c.id) then
                jobart.source_script=tostring(c.script); jobart.source_local=tonumber(c.local_index or -1) or -1
                jobart.scan_busy=false
                return true
            end
        end
        jobart.scan_busy=false; jobart.status="Candidate content IDs were found, but none resolved to Rockstar preview artwork."
        return false
    end
    local function job_queue_scan(force)
        if jobart.scan_busy or jobart.fetch_busy then return false end
        if not (Script and Script.QueueJob) then return job_scan_locals(force) end
        Script.QueueJob(function() job_scan_locals(force) end); return true
    end
    local function job_manual_resolve(input)
        local id=job_extract_content_id(input)
        if not id then jobart.status="Test input did not contain a recognizable Rockstar content ID."; return false end
        if jobart.scan_busy or jobart.fetch_busy then return false end
        local work=function()
            jobart.content_id=id; jobart.source_script="MANUAL TEST"; jobart.source_local=-1
            if not job_resolve_content(id) then jobart.content_id=id end
        end
        if Script and Script.QueueJob then Script.QueueJob(work) else work() end
        return true
    end

    -- Build 315 Host Session Wizard --------------------------------------------------
    -- Clicking HOST SESSION or HOST AN EVENT opens this dedicated five-step window.
    -- The existing production publication/backend functions remain authoritative.
    local function open_host_wizard(reset_step)
        -- Build 420: the Browser notification overlay is rendered from ON_PRESENT.
        -- Always release any B419 event/detail overlay before opening the dedicated
        -- Host Session Wizard so a stale notification/popup can never steal input.
        if startup.b420_prepare_host_wizard then direct_call(startup.b420_prepare_host_wizard) end
        ui.host_wizard_open=true
        ui.host_wizard_focus_once=true
        if reset_step~=false then ui.host_wizard_step=1 end
        ui.host_wizard_step=math.max(1,math.min(5,tonumber(ui.host_wizard_step or 1) or 1))
        if ui.host_mode~="NORMAL" and ui.host_mode~="CUSTOM" then ui.host_mode="CUSTOM" end
        if ui.host_mode=="CUSTOM" and (ui.host_category==nil or ui.host_category=="NORMAL") then
            ui.host_category="VEHICLES"
            ui.host_activity=(activities.VEHICLES or {"CAR MEET"})[1]
        end
    end

    local function host_category_tile_key(category)
        category=tostring(category or "VEHICLES"):upper()
        if category=="VEHICLES" then return "art_vehicles_tile" end
        if category=="MINIGAMES" then return "art_minigames_tile" end
        if category=="ROLEPLAYING" then return "art_roleplaying_tile" end
        if category=="WAR" then return "art_war_tile" end
        if category=="SOCIAL" then return "art_social_tile" end
        if category=="ROCKSTAR JOBS" then return "b242_live_megaramp" end
        return "b236_normal"
    end

    local function wizard_draw_activity_art(category,activity,w,h)
        local drawn=false
        local cat=tostring(category or ""):upper()
        if cat=="ROCKSTAR JOBS" and startup.browser_ui_draw then
            local act=tostring(activity or ""):upper()
            local key=act:find("COMMUNITY",1,true) and "b242_up_air" or (act:find("HEIST",1,true) and "b242_job" or "b242_live_megaramp")
            drawn=startup.browser_ui_draw(key,w,h,5)==true
        end
        if not drawn and startup.browser_draw_subcategory_art_251 then
            local ok,v=direct_call(startup.browser_draw_subcategory_art_251,category,activity,w,h,5)
            drawn=ok and v==true
        end
        if not drawn and startup.browser_ui_draw then
            drawn=startup.browser_ui_draw(host_category_tile_key(category),w,h,5)==true
        end
        return drawn
    end

    local function host_tab(w,h)
        -- The tab itself is intentionally simple now. The actual approved UI lives in the
        -- separate Build 312 wizard window, so closing the wizard never strands the user.
        begin_panel("B318HostLauncher",w,h,false)
        local inner=math.max(420,math.min(760,w-40))
        local sx=ImGui.GetCursorPosX and ImGui.GetCursorPosX() or 0
        if ImGui.SetCursorPosX and w>inner then ImGui.SetCursorPosX(sx+math.max(0,(w-inner)/2)) end
        begin_panel("B318HostLauncherCenter",inner,math.min(h-20,520),true,true)
        if startup.browser_ui_draw then startup.browser_ui_draw("startup_rocket_logo_original",112,112,5) end
        if ImGui.SetWindowFontScale then direct_call(ImGui.SetWindowFontScale,1.28) end
        white("HOST SESSION WIZARD")
        if ImGui.SetWindowFontScale then direct_call(ImGui.SetWindowFontScale,.88) end
        purple("Create. Host. Connect.")
        ImGui.Spacing()
        if startup.subtle_text_wrapped then
            startup.subtle_text_wrapped("Use the five-step Startup Browser wizard to choose a session type, category, activity, and hosting settings, then review everything before publishing.")
        end
        ImGui.Spacing(); separator(); ImGui.Spacing()
        if ui.host_published==true then
            green("ACTIVE CUSTOM EVENT IS PUBLISHED")
            dim(tostring(ui.host_category).." • "..tostring(ui.host_activity))
        elseif ui.host_mode=="NORMAL" and host_is_local_session_host() then
            green("NORMAL SESSION AUTO-ENROLLMENT READY")
        else
            dim("No custom Event is currently published from this Host Session screen.")
        end
        ImGui.Spacing()
        if button("OPEN HOST SESSION WIZARD","b318_open_host_wizard",inner-32,48,true,false) then open_host_wizard(true) end
        end_panel()
        if ImGui.SetCursorPosX then ImGui.SetCursorPosX(sx) end
        -- Build 312 Dear ImGui fix: SetCursorPosX() must be followed by a submitted item
        -- before EndChild(), otherwise newer Dear ImGui builds assert when the launcher is hovered.
        if ImGui.Dummy then ImGui.Dummy(1,1) end
        end_panel()
    end

    local function render_host_wizard()
        if ui.host_wizard_open~=true then return end

        local sw,sh=1600,900
        if startup.get_display_size then sw,sh=startup.get_display_size() end
        sw=tonumber(sw or 1600) or 1600; sh=tonumber(sh or 900) or 900
        local width=math.min(1520,math.max(1120,sw-12))
        local height=math.min(980,math.max(835,sh-8))
        local x=math.max(6,(sw-width)/2); local y=math.max(6,(sh-height)/2)
        if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(x,y,ImGuiCond and ImGuiCond.Always or 0) end
        if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(width,height,ImGuiCond and ImGuiCond.Always or 0) end
        if ImGui.SetNextWindowBgAlpha then ImGui.SetNextWindowBgAlpha(.998) end
        if ui.host_wizard_focus_once==true and ImGui.SetNextWindowFocus then
            pcall(ImGui.SetNextWindowFocus)
        end
        ui.host_wizard_focus_once=false

        local n=0
        if ImGuiCol then
            if ImGuiCol.WindowBg then n=n+push_col(ImGuiCol.WindowBg,.003,.006,.014,.998) end
            if ImGuiCol.Border then n=n+push_col(ImGuiCol.Border,.34,.10,.56,1) end
