                if not (startup and startup.browser_ui_texture and ImGui and ImGui.GetCursorScreenPos) then return false end
                local srv=startup.browser_ui_texture(key)
                if not srv then return false end
                local a,b=ImGui.GetCursorScreenPos(); local px,py=0,0
                if startup.unpack_imgui_point then px,py=startup.unpack_imgui_point(a,b)
                elseif type(a)=="number" then px,py=tonumber(a) or 0,tonumber(b) or 0
                elseif type(a)=="table" then px=tonumber(a.x or a[1] or 0) or 0; py=tonumber(a.y or a[2] or 0) or 0 end
                width2=tonumber(width2 or 180) or 180; height2=tonumber(height2 or 45) or 45
                if ImGui.Dummy then direct_call(ImGui.Dummy,width2,height2) end
                if px<=0 or py<=0 then return false end
                if ImGui.AddImageRounded then
                    local ok=direct_call(ImGui.AddImageRounded,srv,px,py,px+width2,py+height2,tonumber(u0 or 0) or 0,tonumber(v0 or 0) or 0,tonumber(u1 or 1) or 1,tonumber(v1 or 1) or 1,0xFFFFFFFF,tonumber(rounding or 6) or 6)
                    if ok then return true end
                end
