    local function b242_kind_color(kind,text)
        if kind=="LIVE" then green(text) else cyan(text) end
    end
    local function b242_category_art(category,activity)
        -- Build 281 scope hotfix: activity_art_key is private to an earlier lexical scope.
        -- Use the public Browser bridge installed beside it so Events cannot kill the UI coroutine.
        local fn=startup.browser_activity_art_key
        if type(fn)=="function" then
            local ok,key=direct_call(fn,category or "NORMAL",activity or "GENERAL SESSION")
            if ok and type(key)=="string" and key~="" then return key end
        end
        return "b236_normal"
    end
    local function b242_live_title(row)
        if row and row.rockstarJobActive==true then
            local nm=tostring(row.rockstarJobName or "")
            if nm~="" then return nm end
            return "ROCKSTAR JOB"
        end
        local a=tostring(row and row.activity or "")
        if a~="" and a~="GENERAL SESSION" then return a end
        return tostring(row and row.username or "LIVE ACTIVITY").."'S EVENT"
    end
    local function b242_live_type(row)
        if row and row.rockstarJobActive==true then
            local jt=tostring(row.rockstarJobType or "")
            return jt~="" and jt or "ROCKSTAR JOB"
        end
        return tostring(row and row.activity or row and row.category or "ACTIVITY")
    end
