    local function b242_matches(item)
        local f=tostring(ui.events_filter or "ALL")
        if f~="ALL" and item.kind~=f then return false end
        local q=tostring(ui.events_search or ""):lower()
        if q~="" then
            local hay=(tostring(item.title).." "..tostring(item.activity).." "..tostring(item.category).." "..tostring(item.host)):lower()
            if not hay:find(q,1,true) then return false end
        end
        return true
    end
    local function b242_find_selected(items)
        for _,v in ipairs(items) do if v.key==ui.events_selected_key and b242_matches(v) then return v end end
        for _,v in ipairs(items) do if b242_matches(v) then ui.events_selected_key=v.key; return v end end
        return nil
    end
    local function b242_queue_join(item)
        if not item or not item.row or item.row.live~=true then
            if startup.toast then direct_call(startup.toast,"This preview event is not a live backend listing yet.",2600) end
            return
        end
        if item.row.joinable~=true then
            if startup.toast then direct_call(startup.toast,"This live event is not currently joinable.",2600) end
            return
        end
        if startup.browser_runtime_request_join then
            startup.browser_runtime_request_join(item.row)
        else
            ui.b242_join_target=item.row
            ui.b242_join_requested=true
        end
    end
