    local function b242_draw_item_art(item,w,h)
        if item and item.row and item.rockstar and startup.browser_draw_remote_job_preview then
            local ok,drawn=direct_call(startup.browser_draw_remote_job_preview,item.row,w,h)
            if ok and drawn==true then return true end
        end
        if item and item.rockstar~=true and startup.browser_draw_subcategory_art_251 then
            local ok251,drawn251=direct_call(startup.browser_draw_subcategory_art_251,item.category,item.activity,w,h,5)
            if ok251 and drawn251==true then return true end
        end
        if startup.browser_ui_draw then startup.browser_ui_draw(item and item.art or "event_social_hangout",w,h,5); return true end
        return false
    end
