    local function events_hub_body(w,h)
        -- Build 256: real Concept 2 runtime layout. Browser selection stays UI-only;
        -- the Session HUD remains bound to the GTA lobby actually joined by the user.
        if startup.browser_clear_hover_hud_row then startup.browser_clear_hover_hud_row() end
        ui.going_events=type(ui.going_events)=="table" and ui.going_events or {}
        ui.favorite_events=type(ui.favorite_events)=="table" and ui.favorite_events or {}
        ui.events_region=tostring(ui.events_region or "All Regions")
        ui.events_players=tostring(ui.events_players or "Any")
        ui.events_start=tostring(ui.events_start or "Anytime")
        ui.events_sort=tostring(ui.events_sort or "Starting Soonest")

        local function b269_combo(id,preview,options,width)
            if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(width or 170) end
            if not (ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo) then return preview end
            local value=preview
            if ImGui.BeginCombo(id,preview) then
                for _,opt in ipairs(options) do
                    local selected=(tostring(opt)==tostring(value))
                    local clicked=false
                    local ok,a=direct_call(ImGui.Selectable,tostring(opt).."##"..id..tostring(opt),selected)
                    if ok then clicked=a==true end
                    if clicked then value=tostring(opt) end
                end
                ImGui.EndCombo()
            end
            return value
        end
        local function b269_start_minutes(item)
            if item.kind=="LIVE" then return -1 end
            local st=tostring(item.status or ""):lower()
            local h=tonumber(st:match("(%d+)%s*h")) or 0
            local m=tonumber(st:match("(%d+)%s*m")) or 0
            if h==0 and m==0 then m=tonumber(st:match("(%d+)")) or 9999 end
            return h*60+m
        end
        local function b269_player_count(item)
            return tonumber(tostring(item.players or "0"):match("(%d+)")) or 0
        end
        local function b269_filter_ok(item)
            if ui.events_region~="All Regions" then
                local r=tostring(item.region or "All Regions")
                if r~="All Regions" and r~=ui.events_region then return false end
            end
            local pc=b269_player_count(item)
            if ui.events_players=="1 - 10" and not (pc>=1 and pc<=10) then return false end
            if ui.events_players=="11 - 20" and not (pc>=11 and pc<=20) then return false end
            if ui.events_players=="21 - 30" and not (pc>=21 and pc<=30) then return false end
            if ui.events_players=="30+" and pc<30 then return false end
            if item.kind=="UPCOMING" then
                local mins=b269_start_minutes(item)
                if ui.events_start=="Within 30m" and mins>30 then return false end
                if ui.events_start=="Within 1h" and mins>60 then return false end
                if ui.events_start=="Within 3h" and mins>180 then return false end
                if ui.events_start=="3h+" and mins<180 then return false end
            end
            return true
        end

        local items=b242_event_items()
        table.sort(items,function(a,b)
            local mode=ui.events_sort
            if mode=="People Going" then
                local av=tonumber(a.going_count or 0) or 0; local bv=tonumber(b.going_count or 0) or 0
                if av~=bv then return av>bv end
            elseif mode=="Host Reliability" then
                local av=tonumber(a.reliability or 0) or 0; local bv=tonumber(b.reliability or 0) or 0
                if av~=bv then return av>bv end
            elseif mode=="Category" then
                local av=tostring(a.category or ""); local bv=tostring(b.category or "")
                if av~=bv then return av<bv end
            else
                local av=b269_start_minutes(a); local bv=b269_start_minutes(b)
                if av~=bv then return av<bv end
            end
            return tostring(a.title or "")<tostring(b.title or "")
        end)
