    local function b260_live_sessions_body(w,h)
        -- Build 264: purple separators, fixed profile layout, Browser-asset flags, visible ping icons, and explicit default profile ranks.
        -- Data access remains entirely through the Build 258 scope-safe runtime bridge.
        if startup.browser_clear_hover_hud_row then startup.browser_clear_hover_hud_row() end

        local function get_rows()
            if startup.browser_runtime_get_rows then
                local ok,rows=direct_call(startup.browser_runtime_get_rows)
                if ok and type(rows)=="table" then return rows end
            end
            return {}
        end
        local function get_selected()
            if startup.browser_runtime_get_selected_row then
                local ok,row=direct_call(startup.browser_runtime_get_selected_row)
                if ok and type(row)=="table" then
                    startup.browser_live_profile_selected_row = row
                    return row
                end
            end
            return startup.browser_live_profile_selected_row
        end
        local function set_selected(index)
            if startup.browser_runtime_set_selected_index then direct_call(startup.browser_runtime_set_selected_index,index) end
        end
        local function host_color(row)
            if startup.browser_host_name_rgb then
                local ok,c=direct_call(startup.browser_host_name_rgb,row)
                if ok and type(c)=="table" then return {(c[1] or 190)/255,(c[2] or 115)/255,(c[3] or 255)/255} end
            end
            return {.74,.45,1.00}
        end
        local function mic_text(row)
            if startup.browser_runtime_mic_requirement then
                local ok,v=direct_call(startup.browser_runtime_mic_requirement,row)
                if ok and v then return tostring(v) end
            end
            return tostring(row and row.mic or "MIC OPTIONAL")
        end
        local function cat_text(row)
            if startup.browser_runtime_category_label then
                local ok,v=direct_call(startup.browser_runtime_category_label,row)
                if ok and v then return tostring(v) end
            end
            return tostring(row and row.category or "NORMAL")
        end
        local function code_text(row)
            if startup.browser_runtime_country_code then
                local ok,v=direct_call(startup.browser_runtime_country_code,row)
                if ok and v then return tostring(v):upper() end
            end
            return tostring(row and row.code or "XX"):upper()
        end
        local function draw_flag_only(row,size)
            local code=code_text(row):lower()
            local drawn=false
            if startup.browser_ui_draw and #code==2 then
                local ok,v=direct_call(startup.browser_ui_draw,"flag_"..code,size or 20,size or 20,4)
                drawn=ok and v==true
            end
            if not drawn then dim("·") end
            if startup.hover_help then startup.hover_help(tostring(row and row.country or code:upper())) end
        end
        local function profile_hash(row)
            local s=tostring(row and (row.rid or row.username) or "StartupHost")
            local h=2166136261
            for i=1,#s do h=(h*131 + string.byte(s,i)) % 2147483647 end
            return math.abs(h)
        end
        local function profile_backdrop_key(row)
            local explicit=tonumber(row and row.profileBackdropId or 0) or 0
            local idx=(explicit>=1 and explicit<=10) and explicit or ((profile_hash(row)%10)+1)
            return string.format("profile_backdrop_%02d",idx),idx
        end
        local function profile_role(row)
            local username=tostring(row and (row.profileUsername or row.username) or "")
            if startup.browser_developer_usernames and startup.browser_developer_usernames[username] == true then return "Developer","role_developer" end
            local raw=tostring(row and row.profileRole or "")
            local map={
                ["Noob"]="role_noob",["Member"]="role_member",["Regular"]="role_regular",
                ["Developer"]="role_developer",["Moderator"]="role_moderator",
                ["Contributor"]="role_contributor",["Beta Tester"]="role_beta_tester"
            }
            if map[raw] then return raw,map[raw] end
            return "Noob","role_noob"
        end
        local function profile_rank(row)
            local raw=tostring(row and row.profileRank or "")
            local keymap={
                ["Top 10,000"]="rank_top_10000",["Top 5000"]="rank_top_5000",["Top 5,000"]="rank_top_5000",
                ["Top 3000"]="rank_top_3000",["Top 3,000"]="rank_top_3000",["Top 1000"]="rank_top_1000",["Top 1,000"]="rank_top_1000",
                ["Top 500"]="rank_top_500",["Top 300"]="rank_top_300",["Top 100"]="rank_top_100",["Top 50"]="rank_top_50",
                ["Top 25"]="rank_top_25",["Top 20"]="rank_top_20",["Top 10"]="rank_top_10",["Top 5"]="rank_top_5",
                ["Top 3"]="rank_top_3",["Top 2"]="rank_top_2",["Top 1"]="rank_top_1"
            }
            if keymap[raw] then return raw,keymap[raw] end
            return "Top 10,000","rank_top_10000"
        end
        local function status_dot(row)
            if row and row.online then green("●") else red("●") end
        end
        local function category_icon(row,size)
            icon(category_asset(row and row.category or "NORMAL"),size or 22,"Category")
        end
        local function mic_icon(row,size)
            local m=mic_text(row):upper()
            icon(m:find("NO MIC",1,true) and "b234_mic_off" or "b234_mic",size or 20,"Microphone requirement")
        end
        local function ping_draw(row,detailed)
            local p=tonumber(row and row.ping)
            local state=""
            if startup.browser_measure_row_ping_307 and row and row.online then
                local ok,v,s=direct_call(startup.browser_measure_row_ping_307,row)
                if ok then
                    p=tonumber(v)
                    state=tostring(s or "")
                end
            end
            if not (row and row.online) then dim("--"); return end
            if not p then
                dim("--")
                if startup.hover_help then
                    startup.hover_help("GTA peer PING is measured only when this Browser host is in your active GTA session.")
                end
                return
            end
            local key,color_fn
            if p<=45 then key="ping_excellent"; color_fn=green
            elseif p<=70 then key="ping_good"; color_fn=green
            elseif p<=95 then key="ping_fair"; color_fn=amber
            else key="ping_poor"; color_fn=red end
            local drawn=false
            if startup.browser_ui_draw then
                local ok,v=direct_call(startup.browser_ui_draw,key,22,22,4)
                drawn=ok and v==true
            end
            if drawn then ImGui.SameLine() end
            color_fn(tostring(math.floor(p)).." ms")
        end
