        else amber(tostring(startup.browser_backend and startup.browser_backend.status or "CONNECTING")) end
        ImGui.Spacing()
        local refreshRt=startup.browser_presence_328 or {}
        local now327=startup.now and tonumber(startup.now()) or 0
        local last327=tonumber((startup.browser_backend and startup.browser_backend.last_fetch_success_ms) or refreshRt.last_manual_refresh_ms or 0) or 0
        local age327=(last327>0 and now327>=last327) and math.floor((now327-last327)/1000) or nil
