        local pingX=math.floor(list_w*0.90)
        dim("PLAYER"); ImGui.SameLine(playersX); dim("PLAYERS"); ImGui.SameLine(categoryX); dim("CATEGORY"); ImGui.SameLine(micX); dim("MIC"); ImGui.SameLine(flagX); dim("REGION"); ImGui.SameLine(pingX); dim("PING")
