-- Build 243 Events backend v2.0 client. Uses the existing authenticated Startup backend
-- transport and keeps the dedicated Events API state separate from normal Live Sessions.
startup.browser_events_backend=startup.browser_events_backend or {events={},my_events={},history={},active_event_id="",status="WAITING",last_fetch_ms=0,next_fetch_ms=0,next_private_fetch_ms=0}
startup.browser_events_nowms=function()
    if startup.now then return tonumber(startup.now()) or 0 end
    if Time and Time.GetEpocheMs then return tonumber(Time.GetEpocheMs()) or 0 end
    return math.floor(os.clock()*1000)
end
function startup.browser_events_yield(ms)
    ms=math.max(25,tonumber(ms or 100) or 100)
    if startup.yield then startup.yield(ms)
    elseif Script and Script.Yield then Script.Yield(ms)
    end
end

-- Build 245 transport arbitration:
-- Cherax exposes one shared Curl transport for the whole Browser backend. Core Browser
-- heartbeat/browser/account/service calls and Events calls can wake on the same tick.
-- REQUEST_BUSY is therefore transport contention, not an API/server failure. Events now
-- wait briefly for the shared transport and retry instead of poisoning the Events status.
startup.browser_events_post=function(endpoint,fields)
    local bb=startup.browser_backend
    if not bb or not bb._post or not bb.token or bb.token=="" then
        local why=tostring(bb and bb.status or "BACKEND_NOT_CONNECTED")
        if startup.log then startup.log("[Browser Events] API_BLOCKED | endpoint="..tostring(endpoint).." | "..why) end
        return false,why,nil
    end

    local wait_started=startup.browser_events_nowms()
    local wait_deadline=wait_started+18000
    while bb.request_busy==true and startup.browser_events_nowms()<wait_deadline do
        local nowWait=startup.browser_events_nowms()
        local busySince=tonumber(bb.request_busy_since_ms or 0) or 0
        if busySince>0 and nowWait-busySince>15000 then
            local transportFinished=true
            if bb.active_curl and bb.active_curl.GetFinished then
                transportFinished=bb.active_curl:GetFinished()==true
            end
            if transportFinished then
                bb.request_busy=false
                bb.request_busy_since_ms=0
                bb.active_curl=nil
                if startup.log then startup.log("[Browser Events] TRANSPORT_STALE_RESET | endpoint="..tostring(endpoint)) end
                break
            end
        end
        startup.browser_events_yield(100)
    end
    if bb.request_busy==true then
        local why="TRANSPORT_WAIT_TIMEOUT"
        if startup.log then startup.log("[Browser Events] API_TRANSPORT_FAIL | endpoint="..tostring(endpoint).." | "..why) end
        return false,why,nil
    end

    local ok,body=false,"REQUEST_BUSY"
    for attempt=1,4 do
        ok,body=bb._post(endpoint,fields or {},bb.token)
        if ok or tostring(body)~="REQUEST_BUSY" then break end
        -- Another Browser coroutine acquired the transport between our availability check
        -- and _post(). Back off cooperatively and retry; do not surface REQUEST_BUSY to UI.
        startup.browser_events_yield(100+(attempt*75))
        local retry_deadline=startup.browser_events_nowms()+3000
        while bb.request_busy==true and startup.browser_events_nowms()<retry_deadline do
            startup.browser_events_yield(100)
        end
    end

    local data=(ok and bb._json_decode) and bb._json_decode(body) or nil
    if not ok then
        local why=tostring(body or "NO_RESPONSE")
        if why=="REQUEST_BUSY" then why="TRANSPORT_CONTENTION_TIMEOUT" end
        -- Build 335: after a real Curl/network failure, pause only periodic Events/social
        -- polling for 30 seconds. Core Browser heartbeat/fetch stays alive. This prevents
        -- repeated low-priority Curl:Perform() errors while GTA is transitioning sessions.
        if startup.browser_b335_mark_transition_quiet then startup.browser_b335_mark_transition_quiet(30000) end
        if startup.log then startup.log("[Browser Events] API_TRANSPORT_FAIL | endpoint="..tostring(endpoint).." | "..why) end
        return false,why,data
    end
    if type(data)~="table" or data.ok~=true then
        local apierr=type(data)=="table" and tostring(data.error or "API_ERROR") or "INVALID_RESPONSE"
        if startup.log then startup.log("[Browser Events] API_FAIL | endpoint="..tostring(endpoint).." | "..apierr) end
        return false,apierr,data
    end
    return true,nil,data
end
function startup.browser_events_refresh()
    startup.browser_events_backend.next_fetch_ms=0
    if not (Script and Script.QueueJob) then return false end
    Script.QueueJob(function()
        local ok,err,data=startup.browser_events_post("events.php",{})
        if ok then startup.browser_events_backend.events=type(data.events)=="table" and data.events or {}; startup.browser_events_backend.last_fetch_ms=startup.browser_events_nowms(); startup.browser_events_backend.status="CONNECTED" else startup.browser_events_backend.status=tostring(err) end
    end)
    return true
end
function startup.browser_events_publish(payload)
    payload=payload or {}
    if not startup.browser_backend or not startup.browser_backend.token or startup.browser_backend.token=="" then startup.browser_events_backend.status="BACKEND_NOT_CONNECTED"; return false end
    if not (Script and Script.QueueJob) then return false end
    Script.QueueJob(function()
        local bb=startup.browser_backend
        local sessionType=tostring(payload.session_type or "NORMAL")
        local category=tostring(payload.category or "NORMAL")
        local activity=tostring(payload.activity or "GENERAL SESSION")
        local compatDescription=tostring(payload.description or "")
        local compatLocation=tostring(payload.location_area or "")
        -- Build 280: Build 267 intentionally removed user-entered Custom Session free text,
        -- but the legacy v2.0.x event-publish.php still rejects CUSTOM rows when its old
        -- description/location fields are blank. Supply deterministic catalog-only
        -- compatibility values; no user-generated location/plan/rules text is restored.
        if string.upper(sessionType)=="CUSTOM" then
            if compatDescription=="" then compatDescription="Startup catalog activity: "..activity end
            if compatLocation=="" then compatLocation="Host-selected in session" end
        end
        local fields={session_nonce=tostring(bb.session_nonce or ""),session_type=sessionType,category=category,activity=activity,title=tostring(payload.title or payload.activity or "STARTUP EVENT"),description=compatDescription,location_area=compatLocation,mic_requirement=tostring(payload.mic_requirement or "MIC OPTIONAL"),start_mode=tostring(payload.start_mode or "NOW"),max_players=tostring(payload.max_players or 30)}
        local ok,err,data=startup.browser_events_post("event-publish.php",fields)
        if ok then
            startup.browser_events_backend.active_event_id=tostring(data.event_id or "")
            startup.browser_events_backend.status="CONNECTED"
            startup.browser_events_backend.next_fetch_ms=0
            if startup.log then startup.log("[Browser Events] PUBLISH_OK | eventId="..tostring(data.event_id or "").." | status="..tostring(data.status or "").." | players="..tostring(data.players or "")) end
            if startup.toast then startup.toast("Event published to Startup Browser backend.",3500) end
        else
            startup.browser_events_backend.status=tostring(err)
            startup.browser_events_backend.active_event_id=""
            startup.browser_activity_publication=nil
            if startup.browser_activity_ui_state then startup.browser_activity_ui_state.host_published=false; startup.browser_activity_ui_state.host_publish_started_ms=0 end
            if startup.log then startup.log("[Browser Events] PUBLISH_FAIL | "..tostring(err)) end
            if startup.toast then startup.toast("Event was NOT published: "..tostring(err),5500) end
        end
    end)
    return true
end
function startup.browser_events_unpublish(reason)
