-- Build 249: RENDER-SAFE SUBCATEGORY ASSET LOADER
-- Root-cause mitigation for Cherax ClickGUI "cannot resume dead coroutine" while opening
-- Host Session with the new large subcategory artwork. The Browser render coroutine no
-- longer performs the initial Texture.LoadTexture/LoadTextureAsync allocation for these
-- files. Initial allocation is queued onto a normal Script job; the renderer only polls
-- an already-created texture id and falls back to the Normal icon until the SRV is ready.
-- The packaged subcategory PNGs are also normalized to 768x432 RGB to match the proven
-- Browser event-art size class and reduce decoded texture memory substantially.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.build_number = "2026.08.10.250"
startup.build_date = "2026-08-10"
startup.browser_texture_safety_249 = startup.browser_texture_safety_249 or {queue={},queued={},worker=false,installed=false}
startup.install_browser_texture_safety_build249 = function()
    local st=startup.browser_texture_safety_249
    if st.installed==true then return end
    st.installed=true
    local old_texture=startup.browser_ui_texture
    if type(old_texture)~="function" then return end

    local function nowms()
        if startup.now then return tonumber(startup.now()) or 0 end
        if Time and Time.GetEpocheMs then return tonumber(Time.GetEpocheMs()) or 0 end
        return math.floor(os.clock()*1000)
    end
    local function is_subcategory_rel(rel)
        rel=tostring(rel or ""):lower():gsub("/","\\")
        return rel:find("subcategory_art\\",1,true)~=nil
    end
    local function start_worker()
        if st.worker==true or not (Script and Script.QueueJob) then return end
        st.worker=true
        Script.QueueJob(function()
            while #st.queue>0 do
                local key=table.remove(st.queue,1)
                st.queued[key]=nil
                local rel=startup.browser_ui_assets and startup.browser_ui_assets[key]
                local cache=startup.browser_ui_texture_cache and startup.browser_ui_texture_cache[key]
                if type(cache)~="table" then
                    startup.browser_ui_texture_cache=startup.browser_ui_texture_cache or {}
                    cache={}
                    startup.browser_ui_texture_cache[key]=cache
                end
                if is_subcategory_rel(rel) and not cache.srv and not cache.id and Texture then
                    local path=startup.browser_ui_asset_path and startup.browser_ui_asset_path(key) or nil
                    if path then
                        local exists=true
                        if FileMgr and FileMgr.DoesFileExist then exists=(FileMgr.DoesFileExist(path)==true) end
                        if exists then
                            local ok,id=false,nil
                            if Texture.LoadTextureAsync then ok,id=direct_call(Texture.LoadTextureAsync,path) end
                            id=tonumber(id or 0) or 0
                            if (not ok or id==0) and Texture.LoadTexture then
                                ok,id=direct_call(Texture.LoadTexture,path)
                                id=tonumber(id or 0) or 0
                            end
                            if ok and id~=0 then
                                cache.id=id
                                cache.requested=nowms()
                                cache.last_try=cache.requested
                                -- Successful asset allocation logs stay muted in production.
                            else
                                cache.id=nil
                                cache.last_try=nowms()
                            end
                        else
                            cache.id=nil
                            cache.srv=nil
                            cache.last_try=nowms()
                        end
                    end
                end
                if startup.yield then startup.yield(20) elseif Script.Yield then Script.Yield(20) end
            end
            st.worker=false
        end)
    end
    local function request_texture(key)
        key=tostring(key or "")
        if key=="" or st.queued[key] then return end
        local cache=startup.browser_ui_texture_cache and startup.browser_ui_texture_cache[key]
        if type(cache)=="table" and (cache.srv or cache.id) then return end
        st.queued[key]=true
        st.queue[#st.queue+1]=key
        start_worker()
    end

    startup.browser_ui_texture=function(key)
        local rel=startup.browser_ui_assets and startup.browser_ui_assets[key]
        if is_subcategory_rel(rel) then
            startup.browser_ui_texture_cache=startup.browser_ui_texture_cache or {}
            local cache=startup.browser_ui_texture_cache[key]
            if type(cache)~="table" then cache={}; startup.browser_ui_texture_cache[key]=cache end
            if cache.srv then return cache.srv end
            if not cache.id then
                request_texture(key)
                return nil
            end
            -- The expensive allocation already happened on the Script worker. Reuse the
            -- proven Build 246 texture polling/SRV path without allocating from ClickGUI.
            return old_texture(key)
        end
        return old_texture(key)
    end

    -- Warm the full subcategory set sequentially in the background. This is intentionally
    -- non-blocking for ClickGUI; cards may show their fallback for a few frames on first load.
    for key,rel in pairs(startup.browser_ui_assets or {}) do
        if is_subcategory_rel(rel) then request_texture(key) end
    end
    if startup.log then startup.log("[Browser] Build 249 render-safe subcategory texture worker installed") end
end
