-- Build 279: PERSISTENT SOCIAL + EVENTS BACKEND
-- Additive v2.1 social layer over the proven Browser/Event transport.
-- - Server-backed profile reputation, favorites, roles/ranks, Events Hosted/Players Hosted.
-- - Server-backed RSVP with uncapped interest counts.
-- - Host-roster-backed verified attendance; RSVP alone never verifies attendance.
-- - Verified post-event thumbs feedback and mandatory attendee feedback prompt.
-- - 30m / 10m / LIVE NOW reminders with acknowledgement/retry semantics.
-- - Existing Build 245 serialized Curl transport is reused for every request.
-- - Installer-scoped locals preserve the Pluto 200-local main-chunk safety rule.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.install_browser_social_backend_build279=function()
    startup.browser_social_backend=startup.browser_social_backend or {
        profiles_by_listing={},events_by_id={},known_event_ids={},known_event_order={},
        next_feed_ms=0,next_reminder_ms=0,next_attendance_ms=0,next_feedback_poll_ms=0,
        pending_feedback=nil,pending_feedback_submitting=false,status="WAITING",installed=false
    }
    local bs=startup.browser_social_backend
    if bs.installed==true then return end
    bs.installed=true

    local function nowms()
        if startup.browser_events_nowms then return tonumber(startup.browser_events_nowms()) or 0 end
        if startup.now then return tonumber(startup.now()) or 0 end
        if Time and Time.GetEpocheMs then return tonumber(Time.GetEpocheMs()) or 0 end
        return math.floor(os.clock()*1000)
    end
    local function yieldms(ms)
        if startup.yield then startup.yield(ms)
        elseif Script and Script.Yield then Script.Yield(ms)
        end
    end
    local function post(endpoint,fields)
        if not startup.browser_events_post then return false,"EVENT_TRANSPORT_UNAVAILABLE",nil end
        return startup.browser_events_post(endpoint,fields or {})
    end
    local function remember_event(eventId)
        eventId=tostring(eventId or "")
        if eventId=="" or bs.known_event_ids[eventId] then return end
        bs.known_event_ids[eventId]=true
        bs.known_event_order[#bs.known_event_order+1]=eventId
        while #bs.known_event_order>32 do
            local old=table.remove(bs.known_event_order,1)
            if old then bs.known_event_ids[tostring(old)]=nil end
        end
    end
    local function add_unique(out,seen,value)
        value=tostring(value or "")
        if value~="" and not seen[value] then seen[value]=true; out[#out+1]=value end
    end
    local function merge_table(dst,src)
        dst=type(dst)=="table" and dst or {}
        if type(src)=="table" then for k,v in pairs(src) do dst[k]=v end end
        return dst
    end
    local function profile_for_listing(listingId)
        return bs.profiles_by_listing and bs.profiles_by_listing[tostring(listingId or "")] or nil
    end
    local function apply_profile_to_row(row,profile)
        if type(row)~="table" or type(profile)~="table" then return end
        row.profileUid=profile.profileUid
        row.profileUsername=profile.profileUsername
        row.profilePrivacyMasked=profile.profilePrivacyMasked==true
        if tostring(profile.profileUsername or "")~="" then
            row.username=tostring(profile.profileUsername)
        end
        row.profileMemberSince=profile.profileMemberSince
        row.profileRole=profile.profileRole
        row.profileRank=profile.profileRank
        row.profileBackdropId=profile.profileBackdropId
        row.profileReliability=tonumber(profile.profileReliability or 0) or 0
        row.profileRatings=tonumber(profile.profileRatings or 0) or 0
        row.profileLikes=tonumber(profile.profileLikes or 0) or 0
        row.profileDislikes=tonumber(profile.profileDislikes or 0) or 0
        row.profileFavorites=tonumber(profile.profileFavorites or 0) or 0
        row.profileStars=tonumber(profile.profileStars or 0) or 0
        row.profileReports7d=tonumber(profile.profileReports7d or 0) or 0
        row.profileReportsAllTime=tonumber(profile.profileReportsAllTime or 0) or 0
        row.profileEventsHosted=tonumber(profile.profileEventsHosted or 0) or 0
        row.profilePlayersHosted=tonumber(profile.profilePlayersHosted or 0) or 0
        row.favoritedByMe=profile.favoritedByMe==true
    end
    local function apply_live_profiles()
        for _,row in ipairs(startup.browser and startup.browser.liveRows or {}) do
            apply_profile_to_row(row,profile_for_listing(row and row.listingId))
        end
    end
    local function merge_profile_everywhere(profile)
        if type(profile)~="table" or tostring(profile.profileUid or "")=="" then return end
        local uid=tostring(profile.profileUid)
        for listing,p in pairs(bs.profiles_by_listing or {}) do
            if type(p)=="table" and tostring(p.profileUid or "")==uid then bs.profiles_by_listing[listing]=merge_table(p,profile) end
        end
        for _,meta in pairs(bs.events_by_id or {}) do
            if type(meta)=="table" and tostring(meta.profileUid or "")==uid then merge_table(meta,profile) end
        end
        apply_live_profiles()
    end

    local oldSetLive=startup.browser_set_live_hosts
    if oldSetLive and bs._wrapped_live_hosts~=true then
        bs._wrapped_live_hosts=true
        startup.browser_set_live_hosts=function(hosts)
            local ret=oldSetLive(hosts)
            apply_live_profiles()
            return ret
        end
    end

    function startup.browser_social_refresh()
        local listings,events,seenL,seenE={},{},{},{}
        for _,row in ipairs(startup.browser and startup.browser.liveRows or {}) do add_unique(listings,seenL,row and row.listingId) end
        for _,e in ipairs(startup.browser_events_backend and startup.browser_events_backend.events or {}) do
            local id=tostring(e and e.event_id or "")
            add_unique(events,seenE,id); remember_event(id)
        end
        for _,e in ipairs(startup.browser_events_backend and startup.browser_events_backend.my_events or {}) do
            local id=tostring(e and e.event_id or "")
            add_unique(events,seenE,id); remember_event(id)
        end
        for _,e in ipairs(startup.browser_events_backend and startup.browser_events_backend.history or {}) do
            local id=tostring(e and e.event_id or "")
            add_unique(events,seenE,id); remember_event(id)
        end
        for _,id in ipairs(bs.known_event_order or {}) do add_unique(events,seenE,id) end
        local ok,err,data=post("social-feed.php",{listing_ids=table.concat(listings,","),event_ids=table.concat(events,",")})
        if not ok then bs.status=tostring(err or "SOCIAL_FEED_FAILED"); return false end
        bs.profiles_by_listing=type(data.profiles_by_listing)=="table" and data.profiles_by_listing or {}
        bs.events_by_id=type(data.events)=="table" and data.events or {}
        for id,_ in pairs(bs.events_by_id) do remember_event(id) end
        apply_live_profiles()
        bs.status="CONNECTED"
        return true
    end

    function startup.browser_event_rsvp(eventId,going,itemKey)
        eventId=tostring(eventId or ""); itemKey=tostring(itemKey or "event_"..eventId)
        if eventId=="" or not (Script and Script.QueueJob) then return false end
        local ui=startup.activity_catalog_ui
        if ui then ui.going_events=type(ui.going_events)=="table" and ui.going_events or {}; ui.going_events[itemKey]=going==true end
        Script.QueueJob(function()
            local ok,err,data=post("event-rsvp.php",{event_id=eventId,going=going==true and "1" or "0"})
            if ok then
                local meta=bs.events_by_id[eventId] or {}; bs.events_by_id[eventId]=meta
                meta.going_by_me=data.going_by_me==true
                meta.going_count=tonumber(data.going_count or meta.going_count or 0) or 0
                remember_event(eventId)
                if startup.toast then startup.toast(meta.going_by_me and "You're going — RSVP saved." or "RSVP removed.",2600) end
            else
                if startup.toast then startup.toast("RSVP failed: "..tostring(err),3500) end
            end
            local state=startup.activity_catalog_ui
            if state and type(state.going_events)=="table" then state.going_events[itemKey]=nil end
            bs.next_feed_ms=0
        end)
        return true
    end

    function startup.browser_event_feedback(eventId,sentiment,fromMandatory)
        eventId=tostring(eventId or ""); sentiment=tostring(sentiment or ""):upper()
        if eventId=="" or (sentiment~="UP" and sentiment~="DOWN") or not (Script and Script.QueueJob) then return false end
        if fromMandatory and bs.pending_feedback_submitting then return false end
        if fromMandatory then bs.pending_feedback_submitting=true end
        Script.QueueJob(function()
            local ok,err,data=post("event-feedback.php",{event_id=eventId,sentiment=sentiment})
            if ok then
                local meta=bs.events_by_id[eventId] or {}; bs.events_by_id[eventId]=meta
                meta.my_feedback=tostring(data.my_feedback or sentiment)
                if type(data.profile)=="table" then merge_profile_everywhere(data.profile) end
                if bs.pending_feedback and tostring(bs.pending_feedback.event_id or "")==eventId then bs.pending_feedback=nil end
                if startup.toast then startup.toast(sentiment=="UP" and "Positive event feedback submitted." or "Negative event feedback submitted.",3000) end
                bs.next_feed_ms=0; bs.next_feedback_poll_ms=0
            else
                if startup.toast then startup.toast("Feedback was not submitted: "..tostring(err),4200) end
            end
            bs.pending_feedback_submitting=false
        end)
        return true
    end

    function startup.browser_profile_favorite(targetUid,favorite)
        targetUid=tostring(targetUid or "")
        if targetUid=="" or not (Script and Script.QueueJob) then return false end
        local ownUid=tostring(startup.browser_backend and startup.browser_backend.startup_uid or "")
        if ownUid~="" and targetUid==ownUid then
            if startup.toast then startup.toast("Your own profile cannot be added to Favorites.",2600) end
            return false
        end
        Script.QueueJob(function()
            local ok,err,data=post("profile-favorite.php",{target_uid=targetUid,favorite=favorite==true and "1" or "0"})
            if ok then
                if type(data.profile)=="table" then merge_profile_everywhere(data.profile) end
                if startup.toast then startup.toast(data.favorited_by_me==true and "Host added to Favorites." or "Host removed from Favorites.",2600) end
                bs.next_feed_ms=0
            elseif startup.toast then startup.toast("Favorite update failed: "..tostring(err),3500) end
        end)
        return true
    end

    local function local_rid()
        local localId=nil
        if startup.get_local_player_id_candidates then
            local ids=startup.get_local_player_id_candidates(); if type(ids)=="table" then localId=tonumber(ids[1]) end
        end
        if localId==nil or localId<0 then return "" end
        local rid=0
        if Players and Players.GetRockstarId then local ok,v=direct_call(Players.GetRockstarId,localId); if ok then rid=tonumber(v or 0) or 0 end end
        if rid<=0 and startup.presence and startup.presence.get_player_rid then local ok,v=direct_call(startup.presence.get_player_rid,localId); if ok then rid=tonumber(v or 0) or 0 end end
        if rid<=0 then return "" end
        return string.format("%.0f",rid)
    end
    local function player_exists(pid)
        if not (Players and Players.GetById) then return false end
        local ok,v=direct_call(Players.GetById,pid); return ok and v~=nil
    end
    local function collect_roster()
        local rows={}
        for pid=0,31 do
            if player_exists(pid) then
                local rid=0
                if startup.presence and startup.presence.get_player_rid then local ok,v=direct_call(startup.presence.get_player_rid,pid); if ok then rid=tonumber(v or 0) or 0 end end
                if rid<=0 and Players and Players.GetRockstarId then local ok,v=direct_call(Players.GetRockstarId,pid); if ok then rid=tonumber(v or 0) or 0 end end
                if rid>0 then
                    local name=startup.get_player_name_safe and tostring(startup.get_player_name_safe(pid) or "Unknown") or "Unknown"
                    name=name:gsub("[;,%|]","_"):gsub("[%c]",""); if #name>64 then name=name:sub(1,64) end
                    rows[#rows+1]=tostring(pid)..","..string.format("%.0f",rid)..","..name
                end
            end
        end
        return table.concat(rows,";")
    end
    local function event_for_listing(listingId)
        listingId=tostring(listingId or "")
        if listingId=="" then return nil,nil end
        for id,meta in pairs(bs.events_by_id or {}) do
            if type(meta)=="table" and tostring(meta.listing_id or "")==listingId and tostring(meta.status or ""):upper()=="LIVE" then return tostring(id),meta end
        end
        return nil,nil
    end

    local oldPublish=startup.browser_events_publish
    if oldPublish and bs._wrapped_publish~=true then
        bs._wrapped_publish=true
        startup.browser_events_publish=function(payload)
            payload=type(payload)=="table" and payload or {}
            local before=tostring(startup.browser_events_backend and startup.browser_events_backend.active_event_id or "")
            local copy={}
            for k,v in pairs(payload) do copy[k]=v end
            local ret=oldPublish(payload)
            if ret and Script and Script.QueueJob then
                Script.QueueJob(function()
                    local deadline=nowms()+16000
                    local id=""
                    while nowms()<deadline do
                        id=tostring(startup.browser_events_backend and startup.browser_events_backend.active_event_id or "")
                        if id~="" and (before=="" or id~=before) then break end
                        yieldms(150)
                    end
                    if id=="" then return end
                    remember_event(id)
                    local bb=startup.browser_backend or {}
                    local ok,err,data=post("event-register.php",{
                        event_id=id,session_nonce=tostring(bb.session_nonce or ""),session_type=tostring(copy.session_type or "NORMAL"),
                        category=tostring(copy.category or "NORMAL"),activity=tostring(copy.activity or "GENERAL SESSION"),
                        title=tostring(copy.title or copy.activity or "STARTUP EVENT"),mic_requirement=tostring(copy.mic_requirement or "MIC OPTIONAL"),
                        start_mode=tostring(copy.start_mode or "NOW"),max_players=tostring(copy.max_players or 30)
                    })
                    if ok then
                        local meta=bs.events_by_id[id] or {}; bs.events_by_id[id]=meta
                        meta.status=tostring(data.status or meta.status or "UPCOMING")
                        meta.scheduledStartAt=data.scheduled_start_at; meta.listing_id=data.listing_id
                        bs.next_feed_ms=0
                        -- Build 289: do not wait for the old attendance timer after a LIVE
                        -- event is registered. The worker will perform a host-roster attempt
                        -- on its next pass.
                        bs.next_attendance_ms=0
                        if startup.log then startup.log("[Browser Social 289] EVENT_REGISTER_OK | eventId="..id.." | status="..tostring(meta.status).." | rosterTick=IMMEDIATE") end
                    else
                        bs.status="EVENT_REGISTER: "..tostring(err)
                        if startup.log then startup.log("[Browser Social 279] EVENT_REGISTER_FAIL | eventId="..id.." | "..tostring(err)) end
                        if startup.toast then startup.toast("Event published, but social backend registration failed: "..tostring(err),5200) end
                    end
                end)
            end
            return ret
        end
    end

    local oldUnpublish=startup.browser_events_unpublish
    if oldUnpublish and bs._wrapped_unpublish~=true then
        bs._wrapped_unpublish=true
        startup.browser_events_unpublish=function(reason)
            local id=tostring(startup.browser_events_backend and startup.browser_events_backend.active_event_id or "")
            local ret=oldUnpublish(reason)
            if id~="" and Script and Script.QueueJob then
                Script.QueueJob(function()
                    post("event-state.php",{event_id=id,action="CANCEL",reason=tostring(reason or "HOST_LEFT")})
                    remember_event(id); bs.next_feed_ms=0; bs.next_feedback_poll_ms=0
                end)
            end
            return ret
        end
    end

    local function poll_reminders()
        local ok,err,data=post("event-reminders.php",{})
        if not ok then return false end
        local ack={}
        for _,r in ipairs(type(data.reminders)=="table" and data.reminders or {}) do
            local kind=tostring(r.kind or "")
            local title=tostring(r.title or "Startup Event")
            local host=tostring(r.host or "Startup Host")
            local msg=(kind=="30M" and "EVENT IN 30 MINUTES: " or kind=="10M" and "EVENT IN 10 MINUTES: " or "LIVE NOW: ")..title.." • Host: "..host
            if startup.toast then startup.toast(msg,kind=="LIVE" and 6500 or 5200) end
            local did=tonumber(r.delivery_id); if did and did>0 then ack[#ack+1]=tostring(math.floor(did)) end
            remember_event(r.event_id)
        end
        if #ack>0 then post("event-reminders.php",{ack_ids=table.concat(ack,",")}) end
        return true
    end
    local function poll_feedback_required()
        if bs.pending_feedback then return true end
        local ok,err,data=post("event-feedback-pending.php",{})
        if not ok then return false end
        local rows=type(data.pending)=="table" and data.pending or {}
        if rows[1] then
            bs.pending_feedback=rows[1]
            remember_event(rows[1].event_id)
            if startup.toast then startup.toast("Session feedback required — open Startup to rate the event you attended.",6000) end
        end
        return true
    end
    local function attendance_tick()
        local bb=startup.browser_backend or {}
        local activeId=tostring(startup.browser_events_backend and startup.browser_events_backend.active_event_id or "")
        if activeId~="" then
            local meta=bs.events_by_id[activeId]
            if type(meta)=="table" and tostring(meta.status or ""):upper()=="LIVE" then
                -- Build 289: do NOT gate roster submission on the cached local
                -- bb.published flag. A valid locally-active event is enough to TRY.
                -- event-attendance.php remains authoritative and rejects non-hosts or
                -- a listing/session mismatch with HOST_ONLY / HOST_SESSION_MISMATCH.
                local roster=collect_roster()
                if roster~="" then
                    local ok,err,data=post("event-attendance.php",{
                        action="HOST_ROSTER",
                        event_id=activeId,
                        roster=roster
                    })
                    if ok then
                        local seen=tonumber(data and data.roster_peers_seen or 0) or 0
                        if startup.log then
                            startup.log("[Browser Social 289] HOST_ROSTER_OK | eventId="..activeId.." | peers="..tostring(seen).." | localPublished="..tostring(bb.published==true))
                        end
                    else
                        if startup.log then
                            startup.log("[Browser Social 289] HOST_ROSTER_FAIL | eventId="..activeId.." | "..tostring(err).." | localPublished="..tostring(bb.published==true))
                        end
                    end
                else
                    if startup.log then
                        startup.log("[Browser Social 289] HOST_ROSTER_EMPTY | eventId="..activeId)
                    end
                end
            end
        end
        local actual=startup.browser_get_hud_row and startup.browser_get_hud_row() or nil
        local listing=tostring(actual and actual.listingId or "")
        local eventId,meta=event_for_listing(listing)
        if eventId and meta and meta.is_host~=true then
            local rid=local_rid()
            if rid~="" then
                local ok,err,data=post("event-attendance.php",{action="CLAIM",event_id=eventId,rockstar_rid=rid})
                if ok then meta.attendance_verified=data.attendance_verified==true; remember_event(eventId) end
            end
        end
    end

    function startup.browser_social_render_feedback_popup()
        local p=bs.pending_feedback
        if type(p)~="table" or not (ImGui and ImGui.OpenPopup and ImGui.BeginPopupModal and ImGui.EndPopup) then return end
        local name="HOW WAS THIS SESSION?##StartupBrowser279VerifiedFeedback"
        direct_call(ImGui.OpenPopup,name)
        local visible=false
        direct_call(function() visible=ImGui.BeginPopupModal(name,true,ImGuiWindowFlags and ImGuiWindowFlags.AlwaysAutoResize or nil)==true end)
        if not visible then return end
        if startup.text_colored then startup.text_colored(.72,.42,1.0,1.0,"HOW WAS THIS SESSION?") else ImGui.Text("HOW WAS THIS SESSION?") end
        ImGui.Spacing()
        ImGui.Text(tostring(p.title or "Startup Event"))
        if startup.subtle_text then startup.subtle_text("Host: "..tostring(p.host or "Startup Host")) end
        if startup.subtle_text_wrapped then startup.subtle_text_wrapped("Your attendance was verified by the event host's live session roster. This feedback updates the host's Community Reputation. Favorites remain separate from the rating.") end
        ImGui.Spacing()
        if bs.pending_feedback_submitting then
            if startup.subtle_text then startup.subtle_text("Submitting verified feedback...") end
        else
            local up=false; local down=false
            if startup.render_color_button then
                up=startup.render_color_button("👍 POSITIVE##B279MandatoryPositive","Green","Submit positive verified attendee feedback.",nil,190,42)==true
                ImGui.SameLine()
                down=startup.render_color_button("👎 NEGATIVE##B279MandatoryNegative","Red","Submit negative verified attendee feedback.",nil,190,42)==true
            elseif ImGui.Button then
                up=ImGui.Button("👍 POSITIVE",190,42); ImGui.SameLine(); down=ImGui.Button("👎 NEGATIVE",190,42)
            end
            if up then startup.browser_event_feedback(tostring(p.event_id or ""),"UP",true) end
            if down then startup.browser_event_feedback(tostring(p.event_id or ""),"DOWN",true) end
        end
        if startup.subtle_text then startup.subtle_text("Feedback is required after verified attendance; the event host cannot rate their own event.") end
        ImGui.EndPopup()
    end

    local oldRender=startup.render_browser
    if oldRender and bs._wrapped_render~=true then
        bs._wrapped_render=true
        startup.render_browser=function(...)
            local ret=oldRender(...)
            if startup.browser_social_render_feedback_popup then startup.browser_social_render_feedback_popup() end
            return ret
        end
    end

    if Script and Script.QueueJob then
        Script.QueueJob(function()
            while true do
                local bb=startup.browser_backend
                if bb and tostring(bb.token or "")~="" and (not startup.browser_moderation_allows_access or startup.browser_moderation_allows_access()) then
                    local now=nowms()
                    local b335quiet=startup.browser_b335_network_quiet_active and startup.browser_b335_network_quiet_active() or false
                    if not b335quiet and now>=tonumber(bs.next_feed_ms or 0) then startup.browser_social_refresh(); bs.next_feed_ms=now+7000 end
                    if not b335quiet and now>=tonumber(bs.next_reminder_ms or 0) then poll_reminders(); bs.next_reminder_ms=now+30000 end
                    if not b335quiet and now>=tonumber(bs.next_attendance_ms or 0) then attendance_tick(); bs.next_attendance_ms=now+15000 end
                    if not b335quiet and now>=tonumber(bs.next_feedback_poll_ms or 0) then poll_feedback_required(); bs.next_feedback_poll_ms=now+10000 end
                end
                yieldms(1000)
            end
        end)
    end
    if startup.log then startup.log("[Browser Social 280] Persistent social/events backend client installed") end
end
startup.install_browser_social_backend_build279()
startup.install_browser_social_backend_build279=nil
if startup.log then startup.log("[Startup] [Activity 284] ON_NOTIFICATION hook disabled; join/leave HUD uses player events only") end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 290: authenticated Browser JOIN -> temporary Cherax Saved Players whitelist
--
-- The whitelist is deliberately narrow:
--   * only a fresh authenticated JOIN ticket targeting THIS host/listing can trigger it;
--   * Startup Browser personal blocks are filtered server-side and remain authoritative;
--   * only Cherax Saved Players "Block Join" / "Auto Kick" admission toggles are touched;
--   * crash/script-event protections, moderation, reports, and other defenses stay active;
--   * original Cherax values are restored after the attendee leaves / timeout / unload.
--
-- Everything lives under an installer scope to avoid adding locals to the already-large
-- Startup main chunk (historical Cherax/Pluto 200-local limit).
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.install_browser_join_whitelist_build290=function()
    local bb=startup.browser_backend or {}
    local nk=startup.nuke_join_kick or {}
    local wl=startup.browser_join_whitelist_290 or {}
    startup.browser_join_whitelist_290=wl
    wl.active=wl.active or {}
    wl.seen_join_ids=wl.seen_join_ids or {}
    wl.next_poll_ms=tonumber(wl.next_poll_ms or 0) or 0
    wl.next_maintain_ms=tonumber(wl.next_maintain_ms or 0) or 0
    wl.last_poll_error=tostring(wl.last_poll_error or "")

    local function nowms()
        if startup.now then return tonumber(startup.now()) or 0 end
        return math.floor(os.clock()*1000)
    end

    local function yieldms(ms)
        if startup.yield then return startup.yield(ms or 0) end
        if Script and Script.Yield then return Script.Yield(ms or 0) end
    end

    local function log(msg)
        if startup.log then startup.log("[Browser Whitelist 290] "..tostring(msg or "")) end
    end

    local function lower(v)
        return tostring(v or ""):lower()
    end

    local function player_name_present(username)
        local wanted=lower(username)
        if wanted=="" then return false end
        local ids={}
        if Players and Players.Get then
            local ok,list=direct_call(Players.Get)
            if ok and type(list)=="table" then
                for _,id in pairs(list) do ids[#ids+1]=tonumber(id) end
            end
        end
        if #ids==0 then for id=0,31 do ids[#ids+1]=id end end
        for _,pid in ipairs(ids) do
            if pid~=nil and pid>=0 and pid<=31 then
                local name=""
                if startup.get_player_name_safe then
                    local ok,v=direct_call(startup.get_player_name_safe,pid)
                    if ok then name=tostring(v or "") end
                elseif Players and Players.GetName then
                    local ok,v=direct_call(Players.GetName,pid)
                    if ok then name=tostring(v or "") end
                end
                if name~="" and lower(name)==wanted then return true end
            end
        end
        return false
    end

    local function find_global(names)
        if nk.find_global_feature_by_names then
            return nk.find_global_feature_by_names(names or {})
        end
        if not (FeatureMgr and FeatureMgr.GetFeatureByName) then return nil,nil end
        for _,name in ipairs(names or {}) do
            local ok,f=direct_call(FeatureMgr.GetFeatureByName,name)
            if ok and f then return f,name end
        end
        return nil,nil
    end

    local function exact_select_saved_player(username)
        local selector,selectorName=find_global(nk.saved_players_selector_names or {
            "Saved Players","Saved Player","Player Tracker","Tracked Players","SCAPI Saved Players"
        })
        if not selector or not selector.GetList or not selector.SetListIndex then return false,"SELECTOR_UNAVAILABLE" end
        local ok,list=direct_call(function() return selector:GetList() end)
        if not ok or type(list)~="table" then return false,"LIST_UNAVAILABLE" end
        local wanted=lower(username)
        local index=nil
        for i,label in ipairs(list) do
            if lower(label)==wanted then index=i-1 break end
        end
        if index==nil then return false,"NOT_SAVED" end
        local setOk=direct_call(function()
            selector:SetListIndex(index)
            if selector.TriggerCallback then selector:TriggerCallback()
            elseif selector.OnClick then selector:OnClick() end
        end)
        if not setOk then return false,"SELECT_FAILED" end
        yieldms(30)
        if selector.GetListIndex then
            local vok,current=direct_call(function() return selector:GetListIndex() end)
            if vok and current~=nil and tonumber(current)~=tonumber(index) then return false,"SELECT_VERIFY_FAILED" end
        end
        return true,tostring(selectorName or "Saved Players")
    end

    local function is_on(feature)
        if not feature then return false end
        if nk.is_actually_on then
            local ok,v=direct_call(nk.is_actually_on,feature)
            if ok then return v==true end
        end
        if feature.IsToggled then
            local ok,v=direct_call(function() return feature:IsToggled() end)
            if ok then return v==true end
        end
        if feature.GetBoolValue then
            local ok,v=direct_call(function() return feature:GetBoolValue() end)
            if ok then return v==true end
        end
        return false
    end

    local function set_bool(feature,value,label)
        if not feature then return false end
        value=value==true
        local ok=direct_call(function()
            if feature.SetBoolValue then
                feature:SetBoolValue(value)
                if feature.TriggerCallback then feature:TriggerCallback() end
            elseif feature.Toggle then
                feature:Toggle(value)
                if feature.TriggerCallback then feature:TriggerCallback() end
            elseif feature.OnClick then
                if is_on(feature)~=value then feature:OnClick() end
            end
        end)
        if not ok then
            log("TOGGLE_EXCEPTION | "..tostring(label or "toggle").." | wanted="..tostring(value))
            return false
        end
        yieldms(35)
        local actual=is_on(feature)
        local good=(actual==value)
        log("TOGGLE_"..(good and "OK" or "VERIFY_FAIL").." | "..tostring(label or "toggle").." | wanted="..tostring(value).." | actual="..tostring(actual))
        return good
    end

    local function restore_name(key,reason)
        local state=wl.active[key]
        if type(state)~="table" then return true end
        local selected,why=exact_select_saved_player(state.username)
        if not selected then
            log("RESTORE_SKIPPED | user="..tostring(state.username).." | reason="..tostring(reason or "").." | selector="..tostring(why))
            wl.active[key]=nil
            return false
        end
        local blockFeature,blockName=find_global(nk.block_join_names or {"Block Join"})
        local autoFeature,autoName=find_global(nk.auto_kick_names or {"Auto Kick"})
        local blockOk=true
        local autoOk=true
        if state.changed_block==true then blockOk=set_bool(blockFeature,state.original_block==true,"restore "..tostring(blockName or "Block Join")) end
        if state.changed_auto==true then autoOk=set_bool(autoFeature,state.original_auto==true,"restore "..tostring(autoName or "Auto Kick")) end
        log("RESTORE_"..((blockOk and autoOk) and "OK" or "PARTIAL").." | user="..tostring(state.username).." | reason="..tostring(reason or "expired"))
        wl.active[key]=nil
        return blockOk and autoOk
    end

    function startup.browser_join_whitelist_restore_all_build290(reason)
        local keys={}
        for key,_ in pairs(wl.active) do keys[#keys+1]=key end
        for _,key in ipairs(keys) do restore_name(key,reason or "restore all") end
    end

    local function allow_request(req)
        if type(req)~="table" then return end
        local joinId=tostring(req.join_id or "")
        local username=tostring(req.username or "")
        if joinId=="" or username=="" or wl.seen_join_ids[joinId] then return end
        wl.seen_join_ids[joinId]=nowms()
        -- Build 419: the authenticated pending JOIN ticket is also the host-side
        -- signal for Startup Browser's top-right profile notification. The handler
        -- is presentation-only and never changes whitelist/JOIN authorization.
        if startup.b419_on_pending_browser_join then direct_call(startup.b419_on_pending_browser_join,req) end
        local key=lower(username)
        if key=="" then return end

        local existing=wl.active[key]
        if type(existing)=="table" then
            existing.never_join_deadline_ms=nowms()+90000
            log("JOIN_ALLOW_EXTENDED | user="..username.." | joinId="..joinId)
            return
        end

        log("JOIN_ALLOW_PENDING | user="..username.." | joinId="..joinId)
        local selected,why=exact_select_saved_player(username)
        if not selected then
            -- Not being in Saved Players means there is nothing for this whitelist
            -- layer to bypass. Other protections are deliberately left untouched.
            log("SAVED_PLAYER_BYPASS_NOT_NEEDED | user="..username.." | "..tostring(why))
            return
        end

        local blockFeature,blockName=find_global(nk.block_join_names or {"Block Join"})
        local autoFeature,autoName=find_global(nk.auto_kick_names or {"Auto Kick"})
        local originalBlock=is_on(blockFeature)
        local originalAuto=is_on(autoFeature)
        if originalBlock~=true and originalAuto~=true then
            log("SAVED_PLAYER_BYPASS_NOT_NEEDED | user="..username.." | BlockJoin=false | AutoKick=false")
            return
        end

        local changedBlock=false
        local changedAuto=false
        local blockOk=true
        local autoOk=true
        if originalBlock then
            blockOk=set_bool(blockFeature,false,"temporary "..tostring(blockName or "Block Join"))
            changedBlock=blockOk
        end
        if originalAuto then
            autoOk=set_bool(autoFeature,false,"temporary "..tostring(autoName or "Auto Kick"))
            changedAuto=autoOk
        end

        if changedBlock or changedAuto then
            wl.active[key]={
                username=username,
                original_block=originalBlock,
                original_auto=originalAuto,
                changed_block=changedBlock,
                changed_auto=changedAuto,
                joined=false,
                last_seen_ms=0,
                never_join_deadline_ms=nowms()+90000,
            }
            log("SAVED_PLAYER_BYPASS_"..((blockOk and autoOk) and "OK" or "PARTIAL").." | user="..username.." | BlockJoinWas="..tostring(originalBlock).." | AutoKickWas="..tostring(originalAuto))
            if startup.toast then startup.toast("Browser whitelist temporarily allowed "..username.." through Cherax Saved Players.",4200) end
        else
            log("SAVED_PLAYER_BYPASS_FAIL | user="..username.." | BlockJoinWas="..tostring(originalBlock).." | AutoKickWas="..tostring(originalAuto))
        end
    end

    local function poll_pending_joiners()
        if tostring(bb.token or "")=="" or type(bb._post)~="function" or type(bb._json_decode)~="function" then return false end
        if startup.browser_should_publish_local_host and startup.browser_should_publish_local_host()~=true then return false end
        local ok,body=bb._post("browser-join-whitelist.php",{},bb.token)
        if not ok then
            local err=tostring(body or "REQUEST_FAILED")
            if err~="REQUEST_BUSY" and err~=wl.last_poll_error then
                wl.last_poll_error=err
                log("POLL_FAIL | "..err)
            end
            return false
        end
        local data=bb._json_decode(tostring(body or ""))
        if type(data)~="table" or data.ok~=true then
            local err=type(data)=="table" and tostring(data.error or "INVALID_RESPONSE") or "INVALID_RESPONSE"
            if err~=wl.last_poll_error then wl.last_poll_error=err; log("POLL_FAIL | "..err) end
            return false
        end
        wl.last_poll_error=""
        for _,req in ipairs(type(data.requests)=="table" and data.requests or {}) do allow_request(req) end
        return true
    end

    local function maintain_active()
        local now=nowms()
        local restore={}
        for key,state in pairs(wl.active) do
            if type(state)=="table" then
                local present=player_name_present(state.username)
                if present then
                    if state.joined~=true then log("JOINER_PRESENT | user="..tostring(state.username)) end
                    state.joined=true
                    state.last_seen_ms=now
                elseif state.joined==true then
                    if now-(tonumber(state.last_seen_ms or now) or now)>=15000 then
                        restore[#restore+1]={key=key,reason="PLAYER_LEFT"}
                    end
                elseif now>=(tonumber(state.never_join_deadline_ms or 0) or 0) then
                    restore[#restore+1]={key=key,reason="JOIN_WINDOW_EXPIRED"}
                end
            else
                wl.active[key]=nil
            end
        end
        for _,item in ipairs(restore) do restore_name(item.key,item.reason) end

        -- Keep the seen-id table bounded.
        for joinId,seenAt in pairs(wl.seen_join_ids) do
            if now-(tonumber(seenAt or now) or now)>300000 then wl.seen_join_ids[joinId]=nil end
        end
    end

    if EventMgr and eLuaEvent and eLuaEvent.ON_SESSION_CHANGE and wl.session_handler_installed~=true then
        wl.session_handler_installed=true
        EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE,function()
            if startup.browser_join_whitelist_restore_all_build290 then
                startup.browser_join_whitelist_restore_all_build290("SESSION_CHANGE")
            end
        end)
    end

    if EventMgr and eLuaEvent and eLuaEvent.ON_UNLOAD and wl.unload_handler_installed~=true then
        wl.unload_handler_installed=true
        EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD,function()
            if startup.browser_join_whitelist_restore_all_build290 then
                startup.browser_join_whitelist_restore_all_build290("STARTUP_UNLOAD")
            end
        end)
    end

    function startup.browser_join_whitelist_tick_build290()
        local now=nowms()
        if now>=tonumber(wl.next_poll_ms or 0) then
            poll_pending_joiners()
            wl.next_poll_ms=nowms()+1500
        end
        if now>=tonumber(wl.next_maintain_ms or 0) then
            maintain_active()
            wl.next_maintain_ms=nowms()+1000
        end
    end

    log("INSTALLED | ticket-bound temporary Saved Players whitelist | serialized core Browser worker | personal Browser blocks preserved")
end
startup.install_browser_join_whitelist_build290()
startup.install_browser_join_whitelist_build290=nil

-- Build 290 is the current Browser beta client build.
startup.build_number="2026.08.11.268"


-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 291 Browser Trust / Privacy / Compatibility
-- Build 294 scope hotfix: this feature executes inside a named Startup installer
-- function, isolating helpers without relying on Pluto IIFE behavior.
-- note: default trust is server-authenticated Startup users; blacklist is the exception.
-- ═══════════════════════════════════════════════════════════════════════════════════

startup.install_browser_trust_build294 = function()
    startup.browser_trust_291 = startup.browser_trust_291 or {
        whitelist={},
        blacklist={},
        blacklist_by_uid={},
        blacklist_by_name={},
        blacklist_by_listing={},
        whitelist_by_listing={},
        next_refresh_ms=0,
        status="CONNECTING",
        prefs_dirty=true,
        selected_whitelist=1,
        selected_blacklist=1,
        native_guard_last={},
        playertracker_backup_status="Not checked",
    }
    local bt=startup.browser_trust_291

    local function nowms()
        if startup.now then return tonumber(startup.now()) or 0 end
        return math.floor(os.clock()*1000)
    end

    local function lower(v) return tostring(v or ""):lower() end

    local function post(fields)
        local bb=startup.browser_backend or {}
        if tostring(bb.token or "")=="" or type(bb._post)~="function" or type(bb._json_decode)~="function" then
            return false,"BACKEND_NOT_CONNECTED",nil
        end
        local ok,body=bb._post("browser-trust.php",fields or {},bb.token)
        local data=(ok and bb._json_decode) and bb._json_decode(tostring(body or "")) or nil
        if not ok then return false,tostring(body or "REQUEST_FAILED"),data end
        if type(data)~="table" or data.ok~=true then
            return false,(type(data)=="table" and tostring(data.error or "API_ERROR") or "INVALID_RESPONSE"),data
        end
        return true,nil,data
    end

    local function rebuild_maps()
        bt.blacklist_by_uid={}
        bt.blacklist_by_name={}
        bt.blacklist_by_listing={}
        bt.whitelist_by_listing={}
        for _,row in ipairs(type(bt.blacklist)=="table" and bt.blacklist or {}) do
            local uid=tostring(row.profile_uid or row.profileUid or "")
            local name=lower(row.username or row.profileUsername)
            local listing=tostring(row.listing_id or row.listingId or "")
            if uid~="" then bt.blacklist_by_uid[uid]=row end
            if name~="" then bt.blacklist_by_name[name]=row end
            if listing~="" then bt.blacklist_by_listing[listing]=row end
        end
        for _,row in ipairs(type(bt.whitelist)=="table" and bt.whitelist or {}) do
            local listing=tostring(row.listing_id or row.listingId or "")
            if listing~="" then bt.whitelist_by_listing[listing]=row end
        end
    end

    function startup.browser_trust_is_blacklisted(uid,name)
        uid=tostring(uid or "")
        name=lower(name)
        if uid~="" and bt.blacklist_by_uid[uid] then return true end
        if name~="" and bt.blacklist_by_name[name] then return true end
        return false
    end

    function startup.browser_trust_refresh_build291(force)
        local now=nowms()
        if force~=true and now<tonumber(bt.next_refresh_ms or 0) then return true end
        local ok,err,data=post({action="LIST"})
        if not ok then
            if err~="REQUEST_BUSY" then bt.status="Trust service: "..tostring(err) end
            bt.next_refresh_ms=now+5000
            return false
        end
        bt.whitelist=type(data.whitelist)=="table" and data.whitelist or {}
        bt.blacklist=type(data.blacklist)=="table" and data.blacklist or {}
        rebuild_maps()
        if type(data.preferences)=="table" then
            local remoteDisenrolled=data.preferences.disenrolled==true
            local remotePrivacy=data.preferences.privacy_alias==true
            if bt.prefs_dirty~=true then
                startup.s.browserDisenrolled=remoteDisenrolled
                startup.s.browserPrivacyAliasEnabled=remotePrivacy
            end
        end
        bt.status="CONNECTED • "..tostring(#bt.whitelist).." WHITELISTED • "..tostring(#bt.blacklist).." BLACKLISTED"
        bt.next_refresh_ms=now+15000
        return true
    end

    function startup.browser_trust_sync_prefs_build291()
        local ok,err=post({
            action="SET_PREFS",
            disenrolled=startup.s.browserDisenrolled==true and "1" or "0",
            privacy_alias=startup.s.browserPrivacyAliasEnabled==true and "1" or "0",
        })
        if ok then
            bt.prefs_dirty=false
            bt.next_refresh_ms=0
            return true
        end
        bt.status="Preference sync: "..tostring(err)
        return false
    end

    function startup.browser_trust_blacklist_build291(entry,blockJoins)
        if type(entry)~="table" then return false end
        local uid=tostring(entry.profile_uid or entry.profileUid or "")
        if uid=="" then return false end
        local ok,err=post({action="BLACKLIST",target_uid=uid,block_joins=blockJoins==true and "1" or "0"})
        if not ok then
            if startup.toast then startup.toast("Blacklist failed: "..tostring(err),4000) end
            return false
        end
        bt.next_refresh_ms=0
        startup.browser_trust_refresh_build291(true)
        if startup.browser_backend_fetch_hosts then direct_call(startup.browser_backend_fetch_hosts) end
        if startup.toast then startup.toast(tostring(entry.username or "Startup User").." added to Browser Blacklist.",3000) end
        return true
    end

    function startup.browser_trust_unblacklist_build291(entry)
        if type(entry)~="table" then return false end
        local uid=tostring(entry.profile_uid or entry.profileUid or "")
        if uid=="" then return false end
        local ok,err=post({action="UNBLACKLIST",target_uid=uid})
        if not ok then
            if startup.toast then startup.toast("Unblacklist failed: "..tostring(err),4000) end
            return false
        end
        bt.next_refresh_ms=0
        startup.browser_trust_refresh_build291(true)
        if startup.browser_backend_fetch_hosts then direct_call(startup.browser_backend_fetch_hosts) end
        if startup.toast then startup.toast(tostring(entry.username or "Startup User").." returned to the default Startup Whitelist.",3200) end
        return true
    end

    function startup.browser_trust_set_block_joins_build291(entry,value)
        if type(entry)~="table" then return false end
        local uid=tostring(entry.profile_uid or entry.profileUid or "")
        if uid=="" then return false end
        local ok,err=post({action="SET_BLOCK_JOINS",target_uid=uid,block_joins=value==true and "1" or "0"})
        if not ok then
            if startup.toast then startup.toast("Blacklist JOIN policy failed: "..tostring(err),4000) end
            return false
        end
        entry.block_joins=value==true
        bt.next_refresh_ms=0
        return true
    end

    function startup.browser_trust_check_join_allowed(listingId)
        listingId=tostring(listingId or "")
        if listingId=="" then return true,nil end
        local ok,err,data=post({action="CHECK_JOIN",listing_id=listingId})
        if not ok then
            -- Availability failure must not silently break Browser JOIN. The host-side
            -- Build 290/291 whitelist still remains server-authoritative.
            return true,nil
        end
        if data.allowed==false then return false,tostring(data.reason or "BLACKLISTED_BY_HOST") end
        return true,nil
    end

    -- Replace the old same-session Nuke-style Browser block action. Build 291 Blacklist
    -- is a trust/visibility decision, not a cheater verdict and never Nuke-kicks.
    startup.browser_backend_toggle_block=function(row)
        if type(row)~="table" then return false end
        local profileUid=tostring(row.profileUid or "")
        local entry={profile_uid=profileUid,username=tostring(row.profileUsername or row.username or "Startup User")}
        if profileUid=="" then
            if startup.toast then startup.toast("Wait for this profile to finish loading before changing Blacklist status.",3200) end
            return false
        end
        if startup.browser_trust_is_blacklisted(profileUid,row.username) then
            return startup.browser_trust_unblacklist_build291(entry)
        end
        return startup.browser_trust_blacklist_build291(entry,startup.s.browserBlacklistPreventJoinDefault==true)
    end

    -- Filter blacklisted hosts before the normal Browser row builder sees them.
    -- Build 291 privacy also resolves a server-provided listing -> public display name
    -- map so a privacy-enabled host's raw Rockstar username never needs to flash first.
    if startup.browser_set_live_hosts and bt._wrapped_live_hosts~=true then
        bt._wrapped_live_hosts=true
        local oldSet=startup.browser_set_live_hosts
        startup.browser_set_live_hosts=function(hosts)
            local filtered={}
            local social=startup.browser_social_backend and startup.browser_social_backend.profiles_by_listing or {}
            for _,row in ipairs(type(hosts)=="table" and hosts or {}) do
                local listing=tostring(row.listingId or row.listing_id or "")
                local profile=type(social)=="table" and social[listing] or nil
                local trust=type(bt.whitelist_by_listing)=="table" and bt.whitelist_by_listing[listing] or nil
                local uid=tostring((type(profile)=="table" and profile.profileUid) or (type(trust)=="table" and (trust.profile_uid or trust.profileUid)) or row.profileUid or "")
                local publicName=tostring((type(profile)=="table" and profile.profileUsername) or (type(trust)=="table" and trust.username) or "")
                local blocked=(listing~="" and bt.blacklist_by_listing[listing]~=nil) or startup.browser_trust_is_blacklisted(uid,row.username) or startup.browser_trust_is_blacklisted(uid,publicName)
                if not blocked then
                    if uid~="" then row.profileUid=uid end
                    if publicName~="" then
                        row.profileUsername=publicName
                        row.username=publicName
                        if type(profile)=="table" then row.profilePrivacyMasked=profile.profilePrivacyMasked==true
                        elseif type(trust)=="table" then row.profilePrivacyMasked=trust.privacy_masked==true end
                    end
                    filtered[#filtered+1]=row
                end
            end
            return oldSet(filtered)
        end
    end

    -- Disenroll is local publication control. Authentication remains active for profile,
    -- moderation, Favorites, RSVP and Browser viewing.
    if startup.browser_should_publish_local_host and bt._wrapped_publish_gate~=true then
        bt._wrapped_publish_gate=true
        local oldGate=startup.browser_should_publish_local_host
        startup.browser_should_publish_local_host=function(...)
            if startup.s.browserDisenrolled==true then return false end
            return oldGate(...)
        end
    end

    function startup.browser_trust_set_disenrolled_build291(value)
        startup.s.browserDisenrolled=value==true
        bt.prefs_dirty=true
        startup.save_config(false)
        if startup.s.browserDisenrolled then
            if Script and Script.QueueJob and startup.browser_backend_offline then
                Script.QueueJob(function() direct_call(startup.browser_backend_offline) end)
            elseif startup.browser_backend_offline then
                direct_call(startup.browser_backend_offline)
            end
        else
            local bb=startup.browser_backend or {}
            bb.next_heartbeat_ms=0
            bb.next_fetch_ms=0
        end
    end

    function startup.browser_trust_set_privacy_build291(value)
        startup.s.browserPrivacyAliasEnabled=value==true
        bt.prefs_dirty=true
        startup.save_config(false)
        bt.next_refresh_ms=0
    end

    -- Build the bottom-of-Config dropdowns dynamically from server relations.
    function startup.render_browser_trust_config_build291()
        if not (ClickGUI and ImGui) then return end
        local function trust_combo(label,current,items)
            if not (ImGui and ImGui.Combo) or type(items)~="table" or #items==0 then return current end
            current=math.max(0,math.min(#items-1,tonumber(current or 0) or 0))
            local ok,a,b=direct_call(ImGui.Combo,label,current,items,#items,math.min(#items,12))
            if not ok then ok,a,b=direct_call(ImGui.Combo,label,current,items) end
            if not ok then return current end
            local idx=nil
            if type(a)=="number" then idx=math.floor(a) elseif type(b)=="number" then idx=math.floor(b) end
            if idx==nil then return current end
            if idx<0 then idx=0 elseif idx>#items-1 then idx=#items-1 end
            return idx
        end
        if ClickGUI.BeginCustomChildWindow("Browser Trust & Privacy") then
            startup.section_title("Browser Trust & Privacy")
            startup.subtle_text_wrapped("Authenticated Startup users are whitelisted by default. Startup never deletes your Cherax PlayerTracker lists; Browser JOIN compatibility temporarily bypasses only the exact Saved Players Block Join / Auto Kick entry needed for an authenticated join.")
            if ImGui.Separator then ImGui.Separator() end

            startup.text_colored(0.35,1.00,0.45,1.00,"WHITELIST")
            startup.subtle_text_wrapped("Default: every registered Startup Browser account is trusted unless you explicitly blacklist it. The dropdown shows the most recently active registered accounts; the trust rule itself is not limited to this list.")
            local whiteLabels={}
            for i,row in ipairs(bt.whitelist or {}) do
                whiteLabels[i]=tostring(row.username or "Startup User")
            end
            if #whiteLabels==0 then whiteLabels[1]="No other Startup users loaded yet" end
            if ImGui.Combo then
                local idx=math.max(0,math.min(#whiteLabels-1,(tonumber(bt.selected_whitelist or 1) or 1)-1))
                bt.selected_whitelist=trust_combo("Whitelist User##SB291Whitelist",idx,whiteLabels)+1
            end
            local selectedWhite=bt.whitelist[tonumber(bt.selected_whitelist or 1) or 1]
            if selectedWhite and ImGui.Button and ImGui.Button("ADD SELECTED TO BLACKLIST##SB291Black",-1,30) then
                startup.browser_trust_blacklist_build291(selectedWhite,startup.s.browserBlacklistPreventJoinDefault==true)
            end

            if ImGui.Separator then ImGui.Separator() end
            startup.text_colored(1.00,0.32,0.42,1.00,"BLACKLIST")
            startup.subtle_text_wrapped("Blacklisted users disappear from your Startup Browser host/event views. Optional JOIN blocking applies to Startup Browser JOIN requests; it does not alter global Rockstar matchmaking.")
            local blackLabels={}
            for i,row in ipairs(bt.blacklist or {}) do
                blackLabels[i]=tostring(row.username or "Startup User")..(row.block_joins==true and "  •  Browser JOIN blocked" or "  •  Hidden only")
            end
            if #blackLabels==0 then blackLabels[1]="Blacklist is empty" end
            if ImGui.Combo then
                local idx=math.max(0,math.min(#blackLabels-1,(tonumber(bt.selected_blacklist or 1) or 1)-1))
                bt.selected_blacklist=trust_combo("Blacklist User##SB291Blacklist",idx,blackLabels)+1
            end
            local selectedBlack=bt.blacklist[tonumber(bt.selected_blacklist or 1) or 1]
            if selectedBlack then
                local current=selectedBlack.block_joins==true
                if ImGui.Checkbox then
                    local ok,v=direct_call(ImGui.Checkbox,"Prevent this user from using Startup Browser JOIN on me",current)
                    if ok and v~=current then startup.browser_trust_set_block_joins_build291(selectedBlack,v==true) end
                end
                if ImGui.Button and ImGui.Button("RETURN SELECTED TO WHITELIST##SB291Unblack",-1,30) then
                    startup.browser_trust_unblacklist_build291(selectedBlack)
                end
            end

            if ImGui.Separator then ImGui.Separator() end
            startup.text_colored(0.72,0.42,1.00,1.00,"PRIVACY & ENROLLMENT")
            if ImGui.Checkbox then
                local okD,newD=direct_call(ImGui.Checkbox,"Disenroll From Browser",startup.s.browserDisenrolled==true)
                if okD and newD~=(startup.s.browserDisenrolled==true) then startup.browser_trust_set_disenrolled_build291(newD==true) end
                local okP,newP=direct_call(ImGui.Checkbox,"Privacy Alias - hide my username until a successful Browser JOIN",startup.s.browserPrivacyAliasEnabled==true)
                if okP and newP~=(startup.s.browserPrivacyAliasEnabled==true) then startup.browser_trust_set_privacy_build291(newP==true) end
                local okB,newB=direct_call(ImGui.Checkbox,"New Blacklist entries block Browser JOIN by default",startup.s.browserBlacklistPreventJoinDefault==true)
                if okB and newB~=(startup.s.browserBlacklistPreventJoinDefault==true) then
                    startup.s.browserBlacklistPreventJoinDefault=newB==true
                    startup.save_config(false)
                end
            end
            startup.subtle_text_wrapped("Privacy Alias is presentation privacy: current Build 291 clients show a stable random-looking Startup alias until that viewer successfully joins you through Browser.")
            startup.subtle_text(tostring(bt.status or "CONNECTING"))
            startup.subtle_text("PlayerTracker safety backup: "..tostring(bt.playertracker_backup_status or "Not checked"))

            if ImGui.Separator then ImGui.Separator() end
            startup.text_colored(0.72,0.42,1.00,1.00,"STARTUP ASSETS")
            startup.subtle_text_wrapped("Startup scans the required Browser runtime pack on load. If it is missing or outdated, Startup downloads the versioned package through the private Startup delivery service, installs it, verifies critical files, and removes the temporary ZIP.")
            local aa=startup.assets291
            if aa then
                startup.subtle_text("Package: "..tostring(aa.version or "v1.0.14-B333").."  •  Status: "..tostring(aa.status or "CHECKING"))
                if tostring(aa.detail or "")~="" then startup.subtle_text_wrapped(tostring(aa.detail)) end
                if aa.busy and ImGui.ProgressBar then
                    local p=tonumber(aa.progress or 0) or 0
                    if p<0 then p=0 elseif p>1 then p=1 end
                    local label=tostring(math.floor(p*100+0.5)).."%"
                    if aa.progress_supported~=true and tostring(aa.status or "")=="DOWNLOADING" then label="Downloading..." end
                    direct_call(ImGui.ProgressBar,p,-1,18,label)
                end
                if ImGui.Checkbox then
                    local cur=startup.s.browserAssetInstallerEnabled~=false
                    local okA,newA=direct_call(ImGui.Checkbox,"Automatically install missing Startup Browser assets",cur)
                    if okA and newA~=cur then
                        startup.s.browserAssetInstallerEnabled=newA==true
                        startup.save_config(false)
                    end
                end
                if ImGui.Button and ImGui.Button("SCAN ASSETS NOW##SB292AssetScan",-1,30) then
                    if startup.assets291_check then startup.assets291_check(true) end
                end
                if ImGui.Button and ImGui.Button("REPAIR / REDOWNLOAD ASSETS##SB292AssetRepair",-1,30) then
                    if startup.assets291_install then if startup.assets291 then startup.assets291.user_hidden=false; startup.assets291.ui_visible=true end; startup.assets291_install(true) end
                end
            else
                startup.subtle_text("Asset installer is initializing...")
            end
            ClickGUI.EndCustomChildWindow()
        end
    end

    -- Keep local PlayerTracker JSON as the source of truth. Back it up once; never delete
    -- the user's SavedPlayers/Modders/RecentPlayers lists just to make Browser work.
    function startup.playertracker_backup_build291()
        if bt.playertracker_backup_done==true then return true end
        bt.playertracker_backup_done=true
        local root=tostring(startup.menu_root or "")
        if root=="" then bt.playertracker_backup_status="Menu root unavailable"; return false end
        local srcDir=root.."\\PlayerTracker"
        local dstDir=tostring(startup.storage_dir or (root.."\\Lua\\Startup")).."\\Backups\\PlayerTracker"
        direct_call(function()
            if FileMgr and FileMgr.CreateDir then
                FileMgr.CreateDir(tostring(startup.storage_dir or root.."\\Lua\\Startup").."\\Backups")
                FileMgr.CreateDir(dstDir)
            end
        end)
        local copied=0
        for _,name in ipairs({"SavedPlayers.json","Modders.json","RecentPlayers.json"}) do
            local src=srcDir.."\\"..name
            local dst=dstDir.."\\"..name..".pre_build291.json"
            local content=nil
            local f=io.open(src,"rb")
            if f then content=f:read("*a"); f:close() end
            -- FileMgr fallback only when the path is known to exist. This prevents fresh
            -- installs from emitting Failed to open PlayerTracker errors during Auto Start.
            if not content and startup.raw_file_exists and startup.raw_file_exists(src) and FileMgr and FileMgr.ReadFileContent then
                local ok,v=direct_call(FileMgr.ReadFileContent,src)
                if ok and type(v)=="string" and v~="" then content=v end
            end
            if type(content)=="string" and content~="" then
                local wrote=false
                if FileMgr and FileMgr.WriteFileContent then
                    local ok,v=direct_call(FileMgr.WriteFileContent,dst,content,false)
                    wrote=ok and v~=false
                end
                if not wrote then
                    local f=io.open(dst,"wb")
                    if f then f:write(content); f:close(); wrote=true end
                end
                if wrote then copied=copied+1 end
            end
        end
        bt.playertracker_backup_status=copied>0 and ("Backed up "..tostring(copied).." PlayerTracker JSON file(s)") or "No PlayerTracker JSON files found"
        return copied>0
    end

    -- Compatibility watchdog: Startup-owned toggles + exact known Cherax hashes/names.
    -- It changes only boolean/toggle state and stays quiet after the first correction.
    function startup.browser_compatibility_guard_build291()
        startup.s.battleyeAutoBlockEnabled=false
        startup.s.blockRidJoinsEnabled=false
        if startup.h then
            if startup.set_feature_bool_silently then
                startup.set_feature_bool_silently(startup.h.BattleyeAutoBlockEnabled,false)
                startup.set_feature_bool_silently(startup.h.BlockRidJoinsEnabled,false)
            end
        end

        local targets={
            {key="native_block_rid",hash=238683028,names={"Block RID Joins"}},
            {key="native_redirect_rid",hash=872788705,names={"Redirect RID Joins"}},
            {key="battleye_auto",hash=nil,names={"Auto Block Battleye Detection","Battleye Auto Kick","BattlEye Auto Kick","Battleye Emulator Kick","BattlEye Emulator Kick"}},
        }
        for _,target in ipairs(targets) do
            local f=nil
            if target.hash and FeatureMgr and FeatureMgr.GetFeature then
                local ok,v=direct_call(FeatureMgr.GetFeature,target.hash)
                if ok and v then f=v end
            end
            if not f and FeatureMgr and FeatureMgr.GetFeatureByName then
                for _,name in ipairs(target.names or {}) do
                    local ok,v=direct_call(FeatureMgr.GetFeatureByName,name)
                    if ok and v then f=v break end
                end
            end
            if f then
                local current=false
                local readable=false
                if f.GetBoolValue then
                    local ok,v=direct_call(function() return f:GetBoolValue() end)
                    if ok then current=v==true; readable=true end
                elseif f.IsToggled then
                    local ok,v=direct_call(function() return f:IsToggled() end)
                    if ok then current=v==true; readable=true end
                end
                if readable and current then
                    local ok=direct_call(function()
                        if f.SetBoolValue then f:SetBoolValue(false)
                        elseif f.Toggle then f:Toggle(false) end
                        if f.TriggerCallback then f:TriggerCallback() end
                    end)
                    if ok and bt.native_guard_last[target.key]~=true then
                        bt.native_guard_last[target.key]=true
                        if startup.log then startup.log("[Browser Compatibility 291] Forced OFF "..tostring((target.names or {})[1] or target.key)) end
                    end
                end
            end
        end
    end

    if Script and Script.QueueJob and bt.worker_started~=true then
        bt.worker_started=true
        Script.QueueJob(function()
            -- B358: stagger PlayerTracker/FeatureMgr work away from the first Present frames.
            if startup.yield then startup.yield(3000) elseif Script.Yield then Script.Yield(3000) end
            startup.playertracker_backup_build291()
            while true do
                startup.browser_compatibility_guard_build291()
                local bb=startup.browser_backend or {}
                if tostring(bb.token or "")~="" then
                    if bt.prefs_dirty==true then startup.browser_trust_sync_prefs_build291() end
                    startup.browser_trust_refresh_build291(false)
                end
                if startup.yield then startup.yield(500) elseif Script.Yield then Script.Yield(500) end
            end
        end)
    end
end
startup.install_browser_trust_build294()
startup.install_browser_trust_build294=nil

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 292 Startup Assets installer + real download progress UI
-- Build 294 scope hotfix: asset-installer helpers execute inside a named Startup
-- installer function, preserving the progress UI without hitting the 200-local limit.
-- note: private Startup Worker delivery, pre-download sentinel/version scan,
--       FileMgr.Unzip, verification, and quiet DriftGod-style logs.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.install_asset_manager_build294 = function()
    startup.assets291=startup.assets291 or {
        version="v1.0.14-B333",
        status="CHECKING",
        detail="Checking Startup Browser assets...",
        busy=false,
        complete=false,
        failed=false,
        started_ms=0,
        done_ms=0,
        retry_after_ms=0,
    }
    local a=startup.assets291
    a.version="v1.0.14-B333" -- v1.0.14: refresh stale in-memory installer state after Lua reloads.
    startup.browser_assets_zip_url="https://startup-assets.a-public-urinal.workers.dev"

    local function now_ms()
        return startup.now and startup.now() or math.floor((os.clock() or 0)*1000)
    end

    local function exists(path)
        local f=io.open(path,"rb")
        if f then f:close(); return true end
        return false
    end

    local function read_text(path,limit)
        local f=io.open(path,"rb")
        if not f then return nil end
        local s=f:read(limit or 4096)
        f:close()
        return s
    end

    local function fmt_bytes(n)
        n=tonumber(n or 0) or 0
        if n>=1073741824 then return string.format("%.2f GiB",n/1073741824) end
        if n>=1048576 then return string.format("%.1f MiB",n/1048576) end
        if n>=1024 then return string.format("%.1f KiB",n/1024) end
        return tostring(math.floor(n+0.5)).." B"
    end

    local function fmt_eta(sec)
        sec=math.max(0,math.floor(tonumber(sec or 0) or 0))
        if sec>=3600 then return string.format("%d:%02d:%02d",math.floor(sec/3600),math.floor((sec%3600)/60),sec%60) end
        return string.format("%02d:%02d",math.floor(sec/60),sec%60)
    end

    local function asset_log(msg)
        if startup.log then startup.log("[Assets 310] "..tostring(msg or ""))
        elseif Logger and Logger.LogInfo then Logger.LogInfo("[Startup] [Assets 310] "..tostring(msg or "")) end
    end

    local function driftgod_style_log(msg)
        if startup.log then startup.log(tostring(msg or ""))
        elseif Logger and Logger.LogInfo then Logger.LogInfo("[Startup] "..tostring(msg or "")) end
    end

    local function cleanup_obsolete_browser_assets()
        -- Removes only known development/reference trees from the old ~150 MB Browser pack.
        if not (FileMgr and FileMgr.FindFiles and FileMgr.DeleteFile) then return 0 end
        local root=tostring(startup.storage_dir or "").."\\Assets\\browser_ui"
        local folders={"concepts","source_sheets","ui_kits"}
        local removed=0
        for _,folder in ipairs(folders) do
            local path=root.."\\"..folder
            local files={}
            local ok,v=direct_call(FileMgr.FindFiles,path,"",true)
            if ok and type(v)=="table" then files=v end
            if #files==0 then
                for _,ext in ipairs({"png","jpg","jpeg","webp","txt","md","json"}) do
                    local ok2,v2=direct_call(FileMgr.FindFiles,path,ext,true)
                    if ok2 and type(v2)=="table" then for _,f in ipairs(v2) do files[#files+1]=f end end
                end
            end
            local seen={}
            for _,file in ipairs(files) do
                file=tostring(file or "")
                if file~="" and not seen[file] then
                    seen[file]=true
                    local ok3=direct_call(FileMgr.DeleteFile,file)
                    if ok3 then removed=removed+1 end
                end
            end
        end
        return removed
    end

    local function sentinel_paths()
        local base=tostring(startup.storage_dir or "").."\\Assets"
        return {
            {path=base.."\\browser_asset_manifest_b333.txt",label="asset manifest",manifest=true},
            {path=base.."\\Startup_Logo_UI.png",label="Startup logo"},
            {path=base.."\\browser_ui\\build234_icons\\all.png",label="Browser icons"},
            {path=base.."\\browser_ui\\subcategory_art\\vehicles_car_meet.png",label="event artwork"},
            {path=base.."\\browser_ui\\components\\profile_badges\\individual\\role_noob.png",label="role badges"},
            {path=base.."\\browser_ui\\components\\profile_badges\\individual\\rank_top_10000.png",label="rank badges"},
            {path=base.."\\browser_ui\\components\\profile_backdrops\\backdrop_01_alien_peaks.png",label="profile backdrops"},
            {path=base.."\\browser_ui\\flags\\us.png",label="country flags"},
        }
    end

    local function scan_sentinels()
        local rows=sentinel_paths()
        local present=0
        local missing=nil
        local manifestMissing=false
        local otherPresent=0
        for _,row in ipairs(rows) do
            local good=exists(row.path)
            if good and row.manifest then
                local manifest=read_text(row.path,1024) or ""
                good=manifest:find("Version: v1.0.14%-B333")~=nil
                if not good then missing="asset manifest version mismatch" end
            elseif row.manifest and not good then
                manifestMissing=true
            end
            if good then
                present=present+1
                if not row.manifest then otherPresent=otherPresent+1 end
            elseif not missing then
                missing=tostring(row.label or row.path)
            end
        end

        -- Build 344: if all seven real runtime sentinels are already present and the
        -- only missing check is the tiny B333 manifest, repair the manifest locally
        -- instead of downloading the ~60 MB asset package again. A manifest that exists
        -- but declares the wrong version still fails normally and requires real repair.
        if manifestMissing and otherPresent==(#rows-1) and tostring(missing or "")=="asset manifest" then
            local mf=io.open(rows[1].path,"wb")
            if mf then
                mf:write("Startup Browser Assets\nVersion: v1.0.14-B333\nBuild: 333\nRuntime-only asset pack\nGenerated: 2026-08-12\n")
                mf:close()
                local verify=read_text(rows[1].path,1024) or ""
                if verify:find("Version: v1.0.14%-B333")~=nil then
                    present=present+1
                    missing=nil
                    asset_log("MANIFEST_SELF_HEAL | package="..tostring(a.version).." | runtime_sentinels=7/7")
                end
            end
        end

        a.scan_present=present
        a.scan_total=#rows
        a.scan_missing=missing or ""
        return present==#rows,missing
    end

    local function curl_setopt(curl,enumName,numeric,value)
        if not curl or not curl.Setopt then return false end
        local opt=numeric
        if eCurlOption and eCurlOption[enumName]~=nil then opt=eCurlOption[enumName] end
        local ok=direct_call(function() curl:Setopt(opt,value) end)
        return ok
    end

    local function log_progress_milestones()
        local pct=math.floor((tonumber(a.progress or 0) or 0)*100+0.5)
        local mark=nil
        if pct>=100 then mark=100 elseif pct>=75 then mark=75 elseif pct>=50 then mark=50 elseif pct>=25 then mark=25 end
        if not mark or tonumber(a.last_progress_log or 0)>=mark then return end
        a.last_progress_log=mark
        asset_log("DOWNLOAD_"..tostring(mark).." | "..fmt_bytes(a.downloaded_bytes).." / "..fmt_bytes(a.download_total_bytes))
    end

    local function update_transfer_progress(total,done)
        total=tonumber(total or 0) or 0
        done=tonumber(done or 0) or 0
        if done<0 then done=0 end
        if total>0 and done>total then done=total end
        a.download_total_bytes=total
        a.downloaded_bytes=done
        if total>0 then
            a.progress=math.max(0,math.min(1,done/total))
            a.progress_supported=true
        end
        local elapsed=math.max(0.10,(now_ms()-tonumber(a.started_ms or now_ms()))/1000)
        if done>0 then a.speed_bps=done/elapsed end
        if total>done and tonumber(a.speed_bps or 0)>1024 then
            a.eta_seconds=(total-done)/a.speed_bps
        else
            a.eta_seconds=0
        end
        log_progress_milestones()
    end

    local function install_progress_callback(curl)
        -- Build 297: Cherax v5.48.x exposes the callback option names, but its Lua
        -- Setopt binding accepts string/int values only on affected builds. Passing a
        -- Lua function here caused both a binding exception and native fail-fast crash.
        -- Keep the progress bar honest/indeterminate until GetResponse completes.
        a.progress_supported=false
        a.progress_callback_installed=false
        a.xfer_callback=nil
        if a.safe_mode_logged~=true then
            a.safe_mode_logged=true
            asset_log("DOWNLOAD_SAFE_MODE | curl_callbacks=OFF | progress=INDETERMINATE")
        end
        return false
    end

    local function mark_failure(detail,retryMs)
        a.status="FALLBACK"
        a.detail=tostring(detail or "Asset setup failed. Browser text fallback remains available.")
        a.failed=true
        a.complete=false
        a.busy=false
        a.active_curl=nil
        a.xfer_callback=nil
        a.ui_visible=a.user_hidden~=true
        a.ui_hide_after_ms=now_ms()+12000
        a.retry_after_ms=now_ms()+tonumber(retryMs or 600000)
        asset_log("FAILED | "..a.detail)
    end

    function startup.assets291_check(manual)
        a.status="SCANNING"
        a.detail="Scanning installed Startup Browser assets..."
        local ok,missing=scan_sentinels()
        if ok then
            local removed=cleanup_obsolete_browser_assets()
            a.status="READY"
            a.detail=removed>0 and ("Startup Browser assets ready • cleaned "..tostring(removed).." obsolete asset file(s).") or "Startup Browser assets installed and verified."
            a.complete=true
            a.failed=false
            a.progress=1
            -- Build 338: a successful no-download asset scan is routine startup noise.
            -- Keep missing/download/failure diagnostics, but never print SCAN_OK to Cherax.log.
            a.last_scan_result="READY"
            return true
        end
        a.status="MISSING"
        a.detail="Missing or outdated: "..tostring(missing or "required Browser asset")
        a.complete=false
        a.progress=0
        if a.last_scan_result~="MISSING:"..tostring(missing) or manual==true then
            asset_log("SCAN_MISSING | "..tostring(missing or "required Browser asset").." | sentinels="..tostring(a.scan_present or 0).."/"..tostring(a.scan_total or 0))
        end
        a.last_scan_result="MISSING:"..tostring(missing)
        return false
    end

    function startup.assets291_install(force)
        if startup.s.browserAssetInstallerEnabled==false and force~=true then return false end
        if a.busy then return false end
        if startup.assets291_check(false) and force~=true then return true end
        local now=now_ms()
        if force~=true and now<tonumber(a.retry_after_ms or 0) then return false end
        if not (Script and Script.QueueJob and Curl and Curl.Easy) then
            mark_failure("Downloader unavailable. Browser will use text fallbacks.",600000)
            return false
        end

        a.busy=true
        a.failed=false
        a.complete=false
        a.started_ms=now
        a.done_ms=0
        a.progress=0
        a.downloaded_bytes=0
        a.download_total_bytes=0
        a.speed_bps=0
        a.eta_seconds=0
        a.last_progress_log=0
        a.progress_supported=false
        a.user_hidden=false
        a.ui_visible=true
        a.ui_hide_after_ms=0
        a.status="DOWNLOADING"
        a.detail="Downloading Startup Assets v1.0.14 through the private Startup delivery service..."
        driftgod_style_log("Downloading assets...")
        asset_log("DOWNLOAD_START | package="..tostring(a.version).." | source=STARTUP_PRIVATE_DELIVERY")

        Script.QueueJob(function()
            local downloadDir=tostring(startup.storage_dir or "").."\\Downloads"
            direct_call(function()
                if FileMgr and FileMgr.CreateDir then FileMgr.CreateDir(downloadDir) end
            end)
            local zipPath=downloadDir.."\\Startup-Assets-v1.0.14-B333.zip"
            local curl=Curl.Easy()
            a.active_curl=curl -- keep alive until GetFinished/GetResponse completes.
            curl_setopt(curl,"CURLOPT_URL",10002,startup.browser_assets_zip_url)
            curl_setopt(curl,"CURLOPT_USERAGENT",10018,"Startup-Cherax/"..tostring(startup.version or "v1.0.14"))
            curl_setopt(curl,"CURLOPT_FOLLOWLOCATION",52,1)
            curl_setopt(curl,"CURLOPT_CONNECTTIMEOUT",78,15)
            curl_setopt(curl,"CURLOPT_TIMEOUT",13,240)
            install_progress_callback(curl) -- Build 297: intentionally callback-free.
            curl:Perform()

            local waited=0
            while not curl:GetFinished() and waited<2400 do
                waited=waited+1
                if a.progress_supported~=true then
                    local elapsed=math.max(0,now_ms()-tonumber(a.started_ms or now_ms()))
                    a.indeterminate=(elapsed%1800)/1800
                end
                if startup.yield then startup.yield(100) elseif Script.Yield then Script.Yield(100) end
            end
            if not curl:GetFinished() then
                a.active_curl=nil; a.xfer_callback=nil
                mark_failure("Asset download timed out. Browser text fallback remains available.",600000)
                return
            end

            local code,body=curl:GetResponse()
            a.active_curl=nil
            a.xfer_callback=nil
            local success=false
            if eCurlCode and code==eCurlCode.CURLE_OK then success=true
            elseif tonumber(code)==0 then success=true end
            if not success or type(body)~="string" or #body<1048576 then
                body=nil
                mark_failure("Asset package download failed or returned an invalid response.",600000)
                return
            end
            if body:sub(1,2)~="PK" then
                body=nil
                mark_failure("Downloaded asset package was not a valid ZIP response.",600000)
                return
            end

            update_transfer_progress(#body,#body)
            a.progress=1
            driftgod_style_log("Downloading assets done!")
            asset_log("DOWNLOAD_DONE | bytes="..fmt_bytes(#body))

            local f=io.open(zipPath,"wb")
            if not f then
                body=nil
                mark_failure("Could not save downloaded asset package.",600000)
                return
            end
            f:write(body)
            f:close()
            body=nil
            direct_call(function() if collectgarbage then collectgarbage("collect") end end)

            a.status="INSTALLING"
            a.detail="Installing Startup Browser assets..."
            driftgod_style_log("Installing assets...")
            asset_log("INSTALL_START")
            if startup.yield then startup.yield(50) elseif Script.Yield then Script.Yield(50) end

            local unzipped=false
            if FileMgr and FileMgr.Unzip then
                local ok,v=direct_call(FileMgr.Unzip,zipPath,tostring(startup.lua_dir or ""))
                unzipped=ok and v~=false
            end
            direct_call(os.remove,zipPath)
            if not unzipped then
                mark_failure("Asset ZIP downloaded but could not be extracted.",600000)
                return
            end

            a.status="VERIFYING"
            a.detail="Verifying installed Startup Browser assets..."
            if startup.yield then startup.yield(50) elseif Script.Yield then Script.Yield(50) end
            local verified,missing=scan_sentinels()
            if not verified then
                mark_failure("Asset install incomplete: "..tostring(missing or "missing file"),600000)
                return
            end

            local removed=cleanup_obsolete_browser_assets()
            a.status="READY"
            a.detail=removed>0 and ("Startup Browser assets installed • cleaned "..tostring(removed).." obsolete asset file(s).") or "Startup Browser assets installed successfully."
            a.complete=true
            a.failed=false
            a.busy=false
            a.progress=1
            a.done_ms=now_ms()
            a.ui_visible=true
            a.ui_hide_after_ms=a.done_ms+4500
            driftgod_style_log("Installing assets done!")
            asset_log("VERIFY_OK | package="..tostring(a.version).." | sentinels="..tostring(a.scan_present).."/"..tostring(a.scan_total))
            direct_call(function() if collectgarbage then collectgarbage("collect") end end)
            if startup.toast then startup.toast(removed>0 and ("Startup Browser assets installed; cleaned "..tostring(removed).." obsolete files.") or "Startup Browser assets installed.",3000) end
        end)
        return true
    end

    local function render_progress_bar()
        if not ImGui.ProgressBar then return end
        local p=tonumber(a.progress or 0) or 0
        if tostring(a.status or "")=="DOWNLOADING" and a.progress_supported~=true then
            local wave=tonumber(a.indeterminate or 0) or 0
            p=0.10+0.78*wave
            direct_call(ImGui.ProgressBar,p,-1,20,"Downloading...")
        else
            if p<0 then p=0 elseif p>1 then p=1 end
            local label=tostring(math.floor(p*100+0.5)).."%"
            if tostring(a.status or "")=="INSTALLING" then label="Installing..."
            elseif tostring(a.status or "")=="VERIFYING" then label="Verifying..."
            elseif tostring(a.status or "")=="READY" then label="Ready"
            elseif tostring(a.status or "")=="SCANNING" then label="Scanning..." end
            direct_call(ImGui.ProgressBar,p,-1,20,label)
        end
    end

    function startup.render_assets291_overlay()
        if not ImGui then return end
        local now=now_ms()
        local show=a.ui_visible==true and a.user_hidden~=true
        if not show then return end
        if tonumber(a.ui_hide_after_ms or 0)>0 and now>=tonumber(a.ui_hide_after_ms or 0) and not a.busy then a.ui_visible=false; return end

        local w,h=570,212
        if ImGui.SetNextWindowSize then direct_call(ImGui.SetNextWindowSize,w,h,ImGuiCond and ImGuiCond.Always or 0) end
        if ImGui.SetNextWindowPos then direct_call(ImGui.SetNextWindowPos,40,70,ImGuiCond and ImGuiCond.FirstUseEver or 0) end
        if ImGui.SetNextWindowBgAlpha then direct_call(ImGui.SetNextWindowBgAlpha,0.98) end

        local opened=false
        local flags=(ImGuiWindowFlags and ImGuiWindowFlags.NoCollapse or 0)
        local ok,v=direct_call(ImGui.Begin,"Startup Assets##SB292Assets",true,flags)
        if ok then opened=v==true end
        if opened then
            startup.text_colored(0.96,0.97,1.00,1.00,"STARTUP")
            ImGui.SameLine()
            startup.text_colored(0.72,0.42,1.00,1.00,"ASSET SETUP")
            ImGui.SameLine()
            startup.subtle_text("  •  "..tostring(a.version or "v1.0.14-B333"))

            startup.subtle_text_wrapped(tostring(a.detail or a.status or "Working..."))
            render_progress_bar()

            if tostring(a.status or "")=="DOWNLOADING" then
                if a.progress_supported==true and tonumber(a.download_total_bytes or 0)>0 then
                    local line=fmt_bytes(a.downloaded_bytes).." / "..fmt_bytes(a.download_total_bytes)
                    if tonumber(a.speed_bps or 0)>0 then line=line.."  •  "..fmt_bytes(a.speed_bps).."/s" end
                    if tonumber(a.eta_seconds or 0)>0 then line=line.."  •  ETA "..fmt_eta(a.eta_seconds) end
                    startup.subtle_text(line)
                else
                    startup.subtle_text("Private Startup delivery  •  safe download mode  •  size is reported after transfer completes")
                end
            elseif tostring(a.status or "")=="SCANNING" or tostring(a.status or "")=="MISSING" or tostring(a.status or "")=="READY" then
                startup.subtle_text("Asset scan: "..tostring(a.scan_present or 0).." / "..tostring(a.scan_total or 8).." required checks passed")
            elseif tostring(a.status or "")=="INSTALLING" then
                startup.subtle_text("Download complete  •  extracting into Cherax\\Lua\\Startup...")
            elseif tostring(a.status or "")=="VERIFYING" then
                startup.subtle_text("Download complete  •  validating manifest and critical runtime artwork...")
            end

            startup.subtle_text("Source: Private Startup delivery  •  Browser remains usable with text fallbacks if setup fails.")
            if a.busy then
                if ImGui.Button and ImGui.Button("HIDE DOWNLOAD HUD##SB297HideAssets",-1,28) then
                    a.user_hidden=true
                    a.ui_visible=false
                    asset_log("HUD_HIDDEN | download continues in background")
                end
                if ImGui.Button and ImGui.Button("CONTINUE WITHOUT ASSETS##SB297DisableAssets",-1,28) then
                    startup.s.browserAssetInstallerEnabled=false
                    a.user_hidden=true
                    a.ui_visible=false
                    if startup.save_config then startup.save_config(false) end
                    asset_log("AUTO_INSTALL_DISABLED | current request may finish in background")
                end
            elseif a.failed then
                startup.warn_text("Asset setup failed. Startup remains usable. Retry now or close this window.")
                if ImGui.Button and ImGui.Button("RETRY DOWNLOAD##SB297Retry",-1,30) then a.user_hidden=false; startup.assets291_install(true) end
                if ImGui.Button and ImGui.Button("CLOSE##SB297CloseAssets",-1,28) then a.user_hidden=true; a.ui_visible=false end
            elseif a.complete then
                if ImGui.Button and ImGui.Button("CLOSE##SB297CloseAssetsReady",-1,28) then a.user_hidden=true; a.ui_visible=false end
            end
        end
        direct_call(ImGui.End)
    end

    if EventMgr and eLuaEvent and eLuaEvent.ON_PRESENT and a.present_handler~=true then
        a.present_handler=true
        EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT,function()
            if startup.render_assets291_overlay then direct_call(startup.render_assets291_overlay) end
        end)
    end

    if Script and Script.QueueJob and a.autocheck_started~=true then
        a.autocheck_started=true
        Script.QueueJob(function()
            -- B358 Auto Start safety: asset scan/download is non-critical to the first frames.
            if startup.yield then startup.yield(7000) elseif Script.Yield then Script.Yield(7000) end
            if not startup.assets291_check(false) then
                a.user_hidden=false
                a.ui_visible=true
                if startup.s.browserAssetInstallerEnabled~=false then startup.assets291_install(false) end
            end
        end)
    end
end
