-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 304: Standard/Premium low-population host assist
-- Trigger: Cherax auto-detect is LE or EE, local user remains Session Host AND
-- Startup advertising is actively running for >=10 continuous minutes, then the
-- lobby is still only 1-5 players. One popup per GTA session.
-- Prime (LE BE / EE BE) is never eligible.
-- ═══════════════════════════════════════════════════════════════════════════════════

startup.browser_low_population_assist_304 = startup.browser_low_population_assist_304 or {
    qualifying_since_ms=0,
    shown_session_key="",
    current_session_key="",
    popup_open=false,
    player_count=0
}

startup.browser_low_population_detect_standard_premium_304 = function()
    if not (Cherax and Cherax.GetEdition) then return false end
    local ok,value=direct_call(Cherax.GetEdition)
    if not ok then return false end
    local code=startup.normalize_edition_code and startup.normalize_edition_code(value) or string.upper(tostring(value or ""))
    return code=="LE" or code=="EE"
end

startup.browser_low_population_session_key_304 = function()
    local bb=startup.browser_backend or {}
    local key=tostring(bb.session_nonce or "")
    if key~="" then return key end
    local changed=tonumber(startup.s and startup.s.lastSessionChangeMs or 0) or 0
    if changed>0 then return "session_"..tostring(math.floor(changed)) end
    return "flow_"..tostring(tonumber(startup.s and startup.s.advertiseFlowSerial or 0) or 0)
end

startup.browser_low_population_tick_304 = function()
    local rt=startup.browser_low_population_assist_304
    if type(rt)~="table" then return end

    -- Automatic Cherax edition detection is the only eligibility source.
    if startup.browser_low_population_detect_standard_premium_304()~=true then
        rt.qualifying_since_ms=0
        rt.popup_open=false
        return
    end
    if startup.browser_prime_access_blocked and startup.browser_prime_access_blocked() then
        rt.qualifying_since_ms=0
        rt.popup_open=false
        return
    end

    local onlineReady=not startup.is_gta_online_session_ready or startup.is_gta_online_session_ready()==true
    local isHost=startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true
    local advertising=startup.s
        and startup.s.advertiseRunning==true
        and startup.s.advertiseSmartActive==true
        and startup.s.advertiseStopRequested~=true

    local sessionKey=startup.browser_low_population_session_key_304()
    if tostring(rt.current_session_key or "")~=sessionKey then
        rt.current_session_key=sessionKey
        rt.qualifying_since_ms=0
        rt.popup_open=false
    end

    if not onlineReady or not isHost or not advertising then
        rt.qualifying_since_ms=0
        return
    end

    local now=startup.now and tonumber(startup.now()) or 0
    if now<=0 then return end
    if tonumber(rt.qualifying_since_ms or 0)<=0 then
        rt.qualifying_since_ms=now
        return
    end

    if (now-tonumber(rt.qualifying_since_ms or now))<600000 then return end

    local players=math.max(0,math.floor(tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0))
    rt.player_count=players
    if players<1 or players>5 then return end
    if tostring(rt.shown_session_key or "")==sessionKey then return end

    rt.shown_session_key=sessionKey
    rt.popup_open=true
    if startup.log then
        startup.log("[Browser Assist 304] LOW_POPULATION_GUIDANCE | players="..tostring(players).." | hostedAdvertisingMs="..tostring(math.floor(now-tonumber(rt.qualifying_since_ms or now))))
    end
end

startup.browser_low_population_render_304 = function()
    local rt=startup.browser_low_population_assist_304
    if type(rt)~="table" or rt.popup_open~=true or not ImGui then return end
    if not startup.browser_low_population_detect_standard_premium_304() then rt.popup_open=false; return end

    if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(790,650,ImGuiCond and ImGuiCond.FirstUseEver or 0) end
    if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(110,110,ImGuiCond and ImGuiCond.FirstUseEver or 0) end
    if ImGui.SetNextWindowBgAlpha then ImGui.SetNextWindowBgAlpha(0.98) end
    local flags=ImGuiWindowFlags and ImGuiWindowFlags.NoCollapse or 0
    local visible=ImGui.Begin("Players not joining you as a host?##StartupBrowser304LowPopulation",true,flags)==true
    if visible then
        startup.text_colored(0.72,0.42,1.00,1.00,"PLAYERS NOT JOINING YOU AS A HOST?")
        ImGui.Spacing()
        startup.text_colored_wrapped(0.95,0.96,1.00,1.00,"Startup has detected that your hosted lobby is still very small after 10+ minutes of active advertising.")
        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()

        startup.text_colored(0.72,0.42,1.00,1.00,"1. CHECK THE STARTUP GUIDE")
        startup.text_colored_wrapped(0.35,0.82,1.00,1.00,"Go to Startup > Guide and read the hosting / players-not-joining guidance first. The Guide contains the quickest fixes for common Rockstar peer-to-peer matchmaking issues.")
        ImGui.Spacing()

        startup.text_colored(0.72,0.42,1.00,1.00,"2. RUN SELF DIAGNOSIS IF THE GUIDE DOES NOT FIX IT")
        startup.text_colored_wrapped(1.00,0.78,0.25,1.00,"Go to Startup > Config > Self Diagnosis > Run Full Diagnosis.")
        startup.text_colored_wrapped(0.95,0.96,1.00,1.00,"A Full Diagnosis takes roughly 1 hour, and may take slightly longer. Answer the questionnaire carefully so Startup has the information needed to investigate your issue. The questionnaire must be completed to proceed. After that, let Self Diagnosis run through the full process without interfering with it.")
        ImGui.Spacing()

        startup.text_colored(0.72,0.42,1.00,1.00,"3. TEMPORARY ALTERNATIVE — JOIN ANOTHER STARTUP USER")
        startup.text_colored_wrapped(0.35,1.00,0.55,1.00,"Go to Startup > Browser, select a Live Session, and choose JOIN. You can also use Startup > Browser > Events and JOIN a live Event.")
        startup.text_colored_wrapped(0.95,0.96,1.00,1.00,"Let the other Startup / Cherax user remain Session Host.")
        startup.text_colored_wrapped(1.00,0.30,0.30,1.00,"DO NOT KICK THE HOST.")
        startup.text_colored_wrapped(1.00,0.78,0.25,1.00,"If you attend a verified Event, do not forget to rate it afterward.")
        ImGui.Spacing()

        startup.subtle_text("Current lobby: "..tostring(rt.player_count or 0).." players after 10+ minutes of active hosting + advertising.")
        ImGui.Spacing(); ImGui.Separator(); ImGui.Spacing()

        if ImGui.Button("GOT IT##StartupBrowser304LowPopulationDismiss",180,32) then
            rt.popup_open=false
        end
    end
    ImGui.End()
end

if Script and Script.QueueJob and startup.browser_low_population_worker_304~=true then
    startup.browser_low_population_worker_304=true
    Script.QueueJob(function()
        while true do
            if startup.s and startup.s.initialized==true and startup.browser_low_population_tick_304 then
                startup.browser_low_population_tick_304()
            end
            if startup.yield then startup.yield(1000)
            elseif Script.Yield then Script.Yield(1000)
            end
        end
    end)
end

if EventMgr and eLuaEvent and eLuaEvent.ON_PRESENT and startup.browser_low_population_present_304~=true then
    startup.browser_low_population_present_304=true
    EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT,function()
        if startup.browser_low_population_render_304 then startup.browser_low_population_render_304() end
    end)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 307: truthful Startup Browser PING
--
-- GTA Online is peer-to-peer. A real peer ping is only meaningful once the target
-- Browser host is actually a player in this client's active GTA session. Startup does
-- NOT invent a region estimate and does NOT expose the host's IP address.
--
-- After an authenticated JOIN ticket reveals the target RID, Startup remembers that
-- RID only in runtime memory. Once the target appears in-session, Cherax resolves the
-- CNetGamePlayer and GTA's NETWORK_GET_AVERAGE_PING supplies the live peer measurement.
-- ═══════════════════════════════════════════════════════════════════════════════════

startup.browser_ping_targets_307=startup.browser_ping_targets_307 or {}

startup.browser_remember_ping_target_307=function(listingId,rid,username)
    listingId=tostring(listingId or "")
    rid=tostring(rid or "")
    if listingId=="" or not rid:match("^%d+$") then return false end
    startup.browser_ping_targets_307[listingId]={
        rid=rid,
        username=tostring(username or ""),
        remembered_ms=startup.now and startup.now() or 0
    }
    for _,row in ipairs(startup.browser and startup.browser.liveRows or {}) do
        if tostring(row.listingId or "")==listingId then
            row.targetRid=rid
            row._ping307_at=0
        end
    end
    return true
end

startup.browser_measure_row_ping_307=function(row)
    if type(row)~="table" or row.online~=true then return nil,"OFFLINE" end

    local now=startup.now and tonumber(startup.now()) or 0
    local last=tonumber(row._ping307_at or 0) or 0
    if last>0 and now>0 and (now-last)<1000 then
        return tonumber(row.ping),tostring(row._ping307_state or "")
    end
    row._ping307_at=now

    local listing=tostring(row.listingId or row.listing_id or "")
    local remembered=startup.browser_ping_targets_307 and startup.browser_ping_targets_307[listing] or nil
    local rid=tostring(row.targetRid or (type(remembered)=="table" and remembered.rid) or "")
    if rid=="" or not rid:match("^%d+$") then
        row.ping=nil
        row._ping307_state="JOIN_TO_MEASURE"
        return nil,row._ping307_state
    end

    if not (Players and Players.GetByRockstarId) then
        row.ping=nil
        row._ping307_state="PLAYER_LOOKUP_UNAVAILABLE"
        return nil,row._ping307_state
    end

    local okPlayer,obj=direct_call(Players.GetByRockstarId,tonumber(rid))
    if not okPlayer or not obj then
        row.ping=nil
        row._ping307_state="JOIN_TO_MEASURE"
        return nil,row._ping307_state
    end

    local pid=tonumber(obj.PlayerId)
    if not pid or pid<0 or pid>31 then
        row.ping=nil
        row._ping307_state="PLAYER_SLOT_UNAVAILABLE"
        return nil,row._ping307_state
    end

    if not (NETWORK and NETWORK.NETWORK_GET_AVERAGE_PING) then
        row.ping=nil
        row._ping307_state="PING_NATIVE_UNAVAILABLE"
        return nil,row._ping307_state
    end

    local okPing,raw=direct_call(NETWORK.NETWORK_GET_AVERAGE_PING,pid)
    local value=okPing and tonumber(raw) or nil
    if not value or value<=0 then
        row.ping=nil
        row._ping307_state="MEASURING"
        return nil,row._ping307_state
    end

    -- Native wrappers expose a float. Accept either seconds-style fractional output
    -- or already-millisecond output so the UI remains compatible across Cherax/native
    -- generator revisions.
    local ms=value
    if ms>0 and ms<2 then ms=ms*1000 end
    ms=math.max(1,math.min(5000,math.floor(ms+0.5)))

    row.ping=ms
    row._ping307_state="MEASURED"
    return ms,row._ping307_state
end

startup.browser_ping_label_307=function(row)
    local p,state=startup.browser_measure_row_ping_307(row)
    if tonumber(p) then return tostring(math.floor(tonumber(p))).." ms","MEASURED" end
    if tostring(state or "")=="MEASURING" then return "MEASURING…","MEASURING" end
    return "JOIN TO MEASURE",tostring(state or "JOIN_TO_MEASURE")
end

