startup.browser_presence_328 = startup.browser_presence_328 or {
    host_last_true_ms=0,
    host_grace_ms=20000,
    sticky_online_ms=45000,
    sticky_keep_ms=120000,
    raw_cache={},
    manual_refresh_requested=false,
    manual_refresh_cooldown_until_ms=0,
    last_manual_refresh_ms=0,
    last_log_ms=0
}

startup.browser_b328_now=function()
    if startup.now then return tonumber(startup.now()) or 0 end
    if Time and Time.GetEpocheMs then return tonumber(Time.GetEpocheMs()) or 0 end
    return math.floor(os.clock()*1000)
end

startup.browser_b328_clone_table=function(src)
    local out={}
    if type(src)=="table" then for k,v in pairs(src) do out[k]=v end end
    return out
end

startup.browser_b328_raw_key=function(row)
    if type(row)~="table" then return "" end
    -- Prefer a server-issued pseudonymous host key when the B328 backend adds it.
    -- Until then, use stable account/profile identity where available, then RID, then
    -- normalized visible host+edition. Listing ID is intentionally LAST because a new
    -- GTA session gets a new listing ID and must replace (not duplicate) the old row.
    local hostKey=tostring(row.host_key or row.hostKey or "")
    if hostKey~="" then return "H|"..hostKey end
    local uid=tostring(row.startup_uid or row.user_uid or row.profile_uid or row.profileUid or "")
    if uid~="" then return "A|"..uid end
    local rid=tostring(row.rockstar_rid or row.rid or row.targetRid or "")
    if rid~="" and rid~="0" then return "R|"..rid end
    local username=tostring(row.username or row.host or row.profileUsername or ""):lower()
    username=username:gsub("^%s+",""):gsub("%s+$","")
    local edition=tostring(row.edition or ""):lower():gsub("^%s+",""):gsub("%s+$","")
    if username~="" then return "U|"..username.."|"..edition end
    local lid=tostring(row.listing_id or row.listingId or "")
    if lid~="" then return "L|"..lid end
    return ""
end

startup.browser_b328_policy_blocks_presence=function()
    if startup.browser_prime_access_blocked and startup.browser_prime_access_blocked() then return true end
    if startup.browser_hosttools_access_blocked_326 and startup.browser_hosttools_access_blocked_326() then return true end
    if startup.browser_hardening and startup.browser_hardening.service_enabled==false then return true end
    if startup.s and startup.s.browserDisenrolled==true then return true end
    return false
end

-- Host eligibility grace: only smooth Cherax host-state flicker. All hard policy gates
-- are checked before the grace can apply.
if startup.browser_should_publish_local_host and startup.browser_presence_328._wrapped_publish_gate~=true then
    startup.browser_presence_328._wrapped_publish_gate=true
    startup.browser_presence_328.old_publish_gate=startup.browser_should_publish_local_host
    startup.browser_should_publish_local_host=function(...)
        local bp=startup.browser_presence_328
        if startup.browser_b328_policy_blocks_presence() then bp.host_last_true_ms=0; return false end
        if startup.browser_current_edition and startup.browser_current_edition()==nil then bp.host_last_true_ms=0; return false end
        local ok=bp.old_publish_gate(...)==true
        local now=startup.browser_b328_now()
        if ok then bp.host_last_true_ms=now; return true end
        local actualHost=startup.browser_is_local_session_host and startup.browser_is_local_session_host()==true
        if actualHost then
            -- If the final gate denied despite being actual host, another policy wrapper
            -- denied publication. Never override it.
            return false
        end
        local last=tonumber(bp.host_last_true_ms or 0) or 0
        if last>0 and now>=last and (now-last)<=tonumber(bp.host_grace_ms or 20000) then return true end
        return false
    end
end

-- Sticky feed snapshots. This is visual continuity only; stale rows are made non-joinable.
-- Build 328 fixes the B327 session-change duplicate: a host is keyed by stable identity,
-- not by its short-lived listing ID. A new listing for the same host replaces the old
-- generation immediately, so the previous session cannot linger as a second OFFLINE row.
if startup.browser_set_live_hosts and startup.browser_presence_328._wrapped_live_hosts~=true then
    startup.browser_presence_328._wrapped_live_hosts=true
    startup.browser_presence_328.old_set_live_hosts=startup.browser_set_live_hosts
    startup.browser_set_live_hosts=function(hosts)
        local bp=startup.browser_presence_328
        if startup.browser_b328_policy_blocks_presence() or (startup.browser_terms_accepted and not startup.browser_terms_accepted()) then
            bp.raw_cache={}
            return bp.old_set_live_hosts(hosts)
        end
        local now=startup.browser_b328_now()
        local incoming=type(hosts)=="table" and hosts or {}

        -- Collapse duplicate generations in a single server snapshot. Prefer our own
        -- currently-published listing, otherwise prefer the newest host generation
        -- (smallest host_age_seconds). This is also defensive against backend races.
        local deduped={}
        local indexByKey={}
        local ownListing=tostring(startup.browser_backend and startup.browser_backend.listing_id or "")
        local function prefer(candidate,current)
            if type(current)~="table" then return true end
            local cListing=tostring(candidate and (candidate.listing_id or candidate.listingId) or "")
            local oListing=tostring(current and (current.listing_id or current.listingId) or "")
            if ownListing~="" then
                if cListing==ownListing and oListing~=ownListing then return true end
                if oListing==ownListing and cListing~=ownListing then return false end
            end
            local cAge=tonumber(candidate and (candidate.host_age_seconds or candidate.hostAgeSeconds))
            local oAge=tonumber(current and (current.host_age_seconds or current.hostAgeSeconds))
            if cAge and oAge and cAge~=oAge then return cAge<oAge end
            if cAge and not oAge then return true end
            return false
        end
        for _,h in ipairs(incoming) do
            local key=startup.browser_b328_raw_key(h)
            if key=="" then
                deduped[#deduped+1]=h
            else
                local idx=indexByKey[key]
                if not idx then
                    deduped[#deduped+1]=h
                    indexByKey[key]=#deduped
                elseif prefer(h,deduped[idx]) then
                    deduped[idx]=h
                end
            end
        end

        local seen={}
        for _,h in ipairs(deduped) do
            local key=startup.browser_b328_raw_key(h)
            if key~="" then
                seen[key]=true
                local copy=startup.browser_b328_clone_table(h)
                copy._b328_last_seen_ms=now
                copy._b328_sticky=false
                copy._b328_sticky_age_ms=0
                bp.raw_cache[key]=copy
            end
        end

        local merged={}
        for _,h in ipairs(deduped) do merged[#merged+1]=h end
        for key,cached in pairs(bp.raw_cache) do
            if not seen[key] then
                local last=tonumber(cached._b328_last_seen_ms or 0) or 0
                local age=(last>0 and now>=last) and (now-last) or 999999999
                if age<=tonumber(bp.sticky_keep_ms or 120000) then
                    local copy=startup.browser_b328_clone_table(cached)
                    copy._b328_sticky=true
                    copy._b328_sticky_age_ms=age
                    copy.joinable=false
                    bp.raw_cache[key]=copy
                    merged[#merged+1]=startup.browser_b328_clone_table(copy)
                else
                    bp.raw_cache[key]=nil
                end
            end
        end

        local ret=bp.old_set_live_hosts(merged)
        -- Convert sticky metadata into safe display state after the existing normalizer.
        for _,row in ipairs(startup.browser and startup.browser.liveRows or {}) do
            local key=startup.browser_b328_raw_key(row)
            local raw=bp.raw_cache[key]
            if raw and raw._b328_sticky==true then
                local age=tonumber(raw._b328_sticky_age_ms or 0) or 0
                row.joinable=false
                row.live=false
                row.presenceGrace328=true
                row.age="RECONNECTING"
                row.online=age<=tonumber(bp.sticky_online_ms or 45000)
            end
        end
        return ret
    end
end

function startup.browser_request_manual_refresh_328()
    local bp=startup.browser_presence_328
    local now=startup.browser_b328_now()
    if now<(tonumber(bp.manual_refresh_cooldown_until_ms or 0) or 0) then return false end
    bp.manual_refresh_requested=true
    bp.manual_refresh_cooldown_until_ms=now+2000
    bp.last_manual_refresh_ms=now
    if startup.toast then startup.toast("Refreshing Startup Browser...",1800) end
    return true
end

-- Lightweight scheduler only. The existing serialized Browser worker remains the sole
-- owner of heartbeat/fetch Curl calls.
if Script and Script.QueueJob and startup.browser_presence_328._manual_worker_started~=true then
    startup.browser_presence_328._manual_worker_started=true
    Script.QueueJob(function()
        while true do
            local bp=startup.browser_presence_328
            if bp.manual_refresh_requested==true then
                bp.manual_refresh_requested=false
                local bb=startup.browser_backend or {}
                bb.next_heartbeat_ms=0
                bb.next_fetch_ms=0
                if startup.browser_events_backend then startup.browser_events_backend.next_fetch_ms=0 end
                if startup.browser_social_backend then startup.browser_social_backend.next_feed_ms=0 end
                if startup.log then startup.log("[Browser 328] MANUAL_REFRESH_QUEUED | heartbeat + live feed + events/social refresh scheduled") end
            end
            if startup.yield then startup.yield(250)
            elseif Script and Script.Yield then Script.Yield(250)
            end
        end
    end)
end

if startup.log then startup.log("[Browser 328] READY | quiet production logs | stable host identity | 10s heartbeat | 120s sticky lease | manual refresh") end


