startup.browser_join_local_allow_335=startup.browser_join_local_allow_335 or {active={},quiet_until_ms=0,worker_started=false,session_handler=false,unload_handler=false}

function startup.browser_b335_now()
    if startup.now then return tonumber(startup.now()) or 0 end
    if Time and Time.GetEpocheMs then return tonumber(Time.GetEpocheMs()) or 0 end
    return math.floor((os.clock and os.clock() or 0)*1000)
end

function startup.browser_b335_mark_transition_quiet(ms)
    local st=startup.browser_join_local_allow_335
    local untilMs=startup.browser_b335_now()+math.max(1000,tonumber(ms or 20000) or 20000)
    st.quiet_until_ms=math.max(tonumber(st.quiet_until_ms or 0) or 0,untilMs)
    return st.quiet_until_ms
end

function startup.browser_b335_network_quiet_active()
    local bb=startup.browser_backend or {}
    if bb.join_request or bb.join_pending then return true end
    return startup.browser_b335_now() < (tonumber(startup.browser_join_local_allow_335.quiet_until_ms or 0) or 0)
end

function startup.browser_b335_find_saved_player_exact(username)
    local nk=startup.nuke_join_kick
    if not nk or not nk.find_global_feature_by_names then return false,"SAVED_PLAYERS_API_UNAVAILABLE" end
    local selector=select(1,nk.find_global_feature_by_names(nk.saved_players_selector_names or {"Saved Players","Saved Player","Player Tracker","Tracked Players","SCAPI Saved Players"}))
    if not selector or not selector.GetList or not selector.SetListIndex then return false,"SELECTOR_UNAVAILABLE" end
    local ok,list=pcall(function() return selector:GetList() end)
    if not ok or type(list)~="table" then return false,"LIST_UNAVAILABLE" end
    local wanted=tostring(username or ""):lower()
    local index=nil
    for i,label in ipairs(list) do
        if tostring(label or ""):lower()==wanted then index=i-1 break end
    end
    if index==nil then return false,"NOT_SAVED" end
    local setok=pcall(function()
        selector:SetListIndex(index)
        if selector.TriggerCallback then selector:TriggerCallback() elseif selector.OnClick then selector:OnClick() end
    end)
    if not setok then return false,"SELECT_FAILED" end
    if startup.yield then startup.yield(35) elseif Script and Script.Yield then Script.Yield(35) end
    if selector.GetListIndex then
        local vok,current=pcall(function() return selector:GetListIndex() end)
        if vok and current~=nil and tonumber(current)~=tonumber(index) then return false,"SELECT_VERIFY_FAILED" end
    end
    return true,nil
end

function startup.browser_b335_feature_is_on(feature)
    local nk=startup.nuke_join_kick
    if nk and nk.is_actually_on then
        local ok,v=pcall(nk.is_actually_on,feature)
        if ok then return v==true end
    end
    if feature and feature.IsToggled then
        local ok,v=pcall(function() return feature:IsToggled() end)
        if ok then return v==true end
    end
    if feature and feature.GetBoolValue then
        local ok,v=pcall(function() return feature:GetBoolValue() end)
        if ok then return v==true end
    end
    return false
end

function startup.browser_b335_feature_set_bool(feature,value)
    if not feature then return false end
    value=value==true
    local ok=pcall(function()
        if feature.SetBoolValue then
            feature:SetBoolValue(value)
            if feature.TriggerCallback then feature:TriggerCallback() end
        elseif feature.Toggle then
            feature:Toggle(value)
            if feature.TriggerCallback then feature:TriggerCallback() end
        elseif feature.OnClick then
            if startup.browser_b335_feature_is_on(feature)~=value then feature:OnClick() end
        else
            error("NO_TOGGLE_METHOD")
        end
    end)
    if not ok then return false end
    if startup.yield then startup.yield(35) elseif Script and Script.Yield then Script.Yield(35) end
    return startup.browser_b335_feature_is_on(feature)==value
end

function startup.browser_join_prepare_local_target_build335(username,rid)
    local st=startup.browser_join_local_allow_335
    local key=tostring(username or ""):lower()
    if key=="" then return false,"INVALID_TARGET" end
    if type(st.active[key])=="table" then
        st.active[key].deadline_ms=startup.browser_b335_now()+120000
        return true,"ALREADY_ALLOWED"
    end

    local selected,why=startup.browser_b335_find_saved_player_exact(username)
    if not selected then
        if why=="NOT_SAVED" then return true,"NOT_SAVED" end
        -- If Saved Players itself cannot be inspected, do not pretend the compatibility
        -- bypass succeeded. Failing closed avoids triggering a JOIN we already know may be
        -- blocked locally.
        return false,why or "SAVED_PLAYER_LOOKUP_FAILED"
    end

    local nk=startup.nuke_join_kick
    local blockFeature=select(1,nk.find_global_feature_by_names(nk.block_join_names or {"Block Join"}))
    local autoFeature=select(1,nk.find_global_feature_by_names(nk.auto_kick_names or {"Auto Kick"}))
    local originalBlock=startup.browser_b335_feature_is_on(blockFeature)
    local originalAuto=startup.browser_b335_feature_is_on(autoFeature)
    if originalBlock~=true and originalAuto~=true then return true,"NO_LOCAL_BLOCK" end

    local changedBlock=false
    local changedAuto=false
    local blockOk=true
    local autoOk=true
    if originalBlock then blockOk=startup.browser_b335_feature_set_bool(blockFeature,false); changedBlock=blockOk end
    if originalAuto then autoOk=startup.browser_b335_feature_set_bool(autoFeature,false); changedAuto=autoOk end
    if (originalBlock and not blockOk) or (originalAuto and not autoOk) then
        if changedBlock then startup.browser_b335_feature_set_bool(blockFeature,true) end
        if changedAuto then startup.browser_b335_feature_set_bool(autoFeature,true) end
        return false,"LOCAL_SAVED_PLAYER_BYPASS_FAILED"
    end

    st.active[key]={username=tostring(username),rid=tostring(rid or ""),original_block=originalBlock,original_auto=originalAuto,changed_block=changedBlock,changed_auto=changedAuto,joined=false,last_seen_ms=0,deadline_ms=startup.browser_b335_now()+120000}
    if startup.support_log_event_quiet then startup.support_log_event_quiet("BROWSER_JOIN_LOCAL_SAVED_PLAYER_ALLOW","host="..tostring(username).." block_was="..tostring(originalBlock).." auto_was="..tostring(originalAuto)) end
    return true,"TEMPORARILY_ALLOWED"
end

function startup.browser_join_restore_local_target_build335(username,reason)
    local st=startup.browser_join_local_allow_335
    local key=tostring(username or ""):lower()
    local state=st.active[key]
    if type(state)~="table" then return true end
    local selected=startup.browser_b335_find_saved_player_exact(state.username)
    if selected then
        local nk=startup.nuke_join_kick
        local blockFeature=select(1,nk.find_global_feature_by_names(nk.block_join_names or {"Block Join"}))
        local autoFeature=select(1,nk.find_global_feature_by_names(nk.auto_kick_names or {"Auto Kick"}))
        if state.changed_block==true then startup.browser_b335_feature_set_bool(blockFeature,state.original_block==true) end
        if state.changed_auto==true then startup.browser_b335_feature_set_bool(autoFeature,state.original_auto==true) end
    end
    st.active[key]=nil
    if startup.support_log_event_quiet then startup.support_log_event_quiet("BROWSER_JOIN_LOCAL_SAVED_PLAYER_RESTORE","host="..tostring(state.username).." reason="..tostring(reason or "restore")) end
    return true
end

function startup.browser_b335_player_name_present(username)
    local wanted=tostring(username or ""):lower()
    if wanted=="" then return false end
    local ids={}
    if Players and Players.Get then
        local ok,list=direct_call(Players.Get)
        if ok and type(list)=="table" then for _,id in pairs(list) do ids[#ids+1]=tonumber(id) end end
    end
    if #ids==0 then for id=0,31 do ids[#ids+1]=id end end
    for _,pid in ipairs(ids) do
        if pid and pid>=0 and pid<=31 then
            local name=""
            if startup.get_player_name_safe then
                local ok,v=direct_call(startup.get_player_name_safe,pid); if ok then name=tostring(v or "") end
            elseif Players and Players.GetName then
                local ok,v=direct_call(Players.GetName,pid); if ok then name=tostring(v or "") end
            end
            if name~="" and name:lower()==wanted then return true end
        end
    end
    return false
end

function startup.browser_join_restore_all_local_targets_build335(reason)
    local keys={}
    for key,_ in pairs(startup.browser_join_local_allow_335.active) do keys[#keys+1]=key end
    for _,key in ipairs(keys) do
        local state=startup.browser_join_local_allow_335.active[key]
        if type(state)=="table" then startup.browser_join_restore_local_target_build335(state.username,reason or "restore all") end
    end
end

if Script and Script.QueueJob and startup.browser_join_local_allow_335.worker_started~=true then
    startup.browser_join_local_allow_335.worker_started=true
    Script.QueueJob(function()
        while true do
            local now=startup.browser_b335_now()
            local restore={}
            for key,state in pairs(startup.browser_join_local_allow_335.active) do
                if type(state)=="table" then
                    local present=startup.browser_b335_player_name_present(state.username)
                    if present then
                        state.joined=true
                        state.last_seen_ms=now
                    elseif state.joined==true then
                        if now-(tonumber(state.last_seen_ms or now) or now)>=15000 then restore[#restore+1]=state.username end
                    elseif now>=(tonumber(state.deadline_ms or 0) or 0) then
                        restore[#restore+1]=state.username
                    end
                else
                    startup.browser_join_local_allow_335.active[key]=nil
                end
            end
            for _,username in ipairs(restore) do startup.browser_join_restore_local_target_build335(username,"TARGET_LEFT_OR_WINDOW_EXPIRED") end
            if startup.yield then startup.yield(1000) elseif Script and Script.Yield then Script.Yield(1000) end
        end
    end)
end

if EventMgr and eLuaEvent and eLuaEvent.ON_SESSION_CHANGE and startup.browser_join_local_allow_335.session_handler~=true then
    startup.browser_join_local_allow_335.session_handler=true
    EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE,function()
        -- Do NOT restore the outbound Saved Players allow here: a Browser RID JOIN itself
        -- causes ON_SESSION_CHANGE before the destination host finishes connecting. Keep
        -- the allow alive through the transition and let the presence/deadline worker
        -- restore it safely afterward.
        startup.browser_b335_mark_transition_quiet(25000)
    end)
end

if EventMgr and eLuaEvent and eLuaEvent.ON_UNLOAD and startup.browser_join_local_allow_335.unload_handler~=true then
    startup.browser_join_local_allow_335.unload_handler=true
    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD,function() startup.browser_join_restore_all_local_targets_build335("STARTUP_UNLOAD") end)
end

