-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 344: AUTOMATIC VERIFIED STARTUP RID WHITELIST + MANIFEST SELF-HEAL
--
-- Privacy / trust model:
--   * no global RID directory is downloaded or exposed;
--   * an RID enters this local whitelist only after Startup has authenticated/verified it
--     (authenticated Browser JOIN ticket, verified Startup presence, or trusted Browser
--     service data that already includes an RID);
--   * the list is local and persistent so previously verified Startup peers remain trusted;
--   * an explicit Startup Browser personal block / Browser Manual Block always wins;
--   * the old B335 Saved Players compatibility attempt is still tried first, but inability
--     to manipulate Cherax's selector no longer hard-aborts an authenticated Startup JOIN.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.install_verified_startup_rid_whitelist_build344=function()
    startup.browser_verified_rid_whitelist_344=startup.browser_verified_rid_whitelist_344 or {
        by_rid={}, loaded=false, save_path="", additions=0,
    }
    local wl=startup.browser_verified_rid_whitelist_344

    local function norm_rid(v)
        local n=tonumber(v or 0) or 0
        if n<=0 then return "" end
        return tostring(math.floor(n))
    end

    local function clean_name(v)
        return tostring(v or ""):gsub("[\r\n\t]"," "):sub(1,64)
    end

    local function player_name(pid)
        pid=tonumber(pid)
        if pid==nil then return "" end
        if startup.get_player_name_safe then
            local ok,v=direct_call(startup.get_player_name_safe,pid)
            if ok then return tostring(v or "") end
        end
        if Players and Players.GetName then
            local ok,v=direct_call(Players.GetName,pid)
            if ok then return tostring(v or "") end
        end
        return ""
    end

    local function player_rid(pid)
        pid=tonumber(pid)
        if pid==nil then return 0 end
        if startup.presence and startup.presence.get_player_rid then
            local ok,v=direct_call(startup.presence.get_player_rid,pid)
            if ok and tonumber(v or 0) and tonumber(v or 0)>0 then return tonumber(v) end
        end
        if Players and Players.GetRockstarId then
            local ok,v=direct_call(Players.GetRockstarId,pid)
            if ok then return tonumber(v or 0) or 0 end
        end
        return 0
    end

    local function manual_blocked(key,username)
        if key~="" and startup.rid_store and type(startup.rid_store.data)=="table" then
            local entry=startup.rid_store.data[key]
            local flags=type(entry)=="table" and type(entry.flags)=="table" and entry.flags or nil
            if flags and flags.browserManualBlock==true then return true end
        end
        if tostring(username or "")~="" and startup.browser_trust_is_blacklisted then
            local ok,v=direct_call(startup.browser_trust_is_blacklisted,"",tostring(username or ""))
            if ok and v==true then return true end
        end
        return false
    end

    local function ensure_dir()
        if FileMgr and FileMgr.CreateDir and tostring(startup.players_dir or "")~="" then
            pcall(FileMgr.CreateDir,tostring(startup.players_dir))
        end
    end

    local function save_file()
        ensure_dir()
        if wl.save_path=="" then wl.save_path=tostring(startup.players_dir or startup.storage_dir or "").."\\startup_verified_rids.tsv" end
        if wl.save_path=="" then return false end
        local keys={}
        for key,_ in pairs(wl.by_rid) do keys[#keys+1]=key end
        table.sort(keys,function(a,b) return (tonumber(a) or 0)<(tonumber(b) or 0) end)
        local f=io.open(wl.save_path,"wb")
        if not f then return false end
        f:write("# Startup Verified RID Whitelist B344\n")
        f:write("# rid\tusername\tlast_seen\tsource\n")
        for _,key in ipairs(keys) do
            local row=wl.by_rid[key]
            if type(row)=="table" then
                f:write(key,"\t",clean_name(row.username),"\t",tostring(tonumber(row.last_seen or 0) or 0),"\t",clean_name(row.source),"\n")
            end
        end
        f:close()
        return true
    end

    local function load_file()
        if wl.loaded==true then return true end
        wl.loaded=true
        ensure_dir()
        wl.save_path=tostring(startup.players_dir or startup.storage_dir or "").."\\startup_verified_rids.tsv"
        local f=io.open(wl.save_path,"rb")
        if not f then return true end
        for line in f:lines() do
            if line:sub(1,1)~="#" then
                local rid,name,lastSeen,source=line:match("^(%d+)\t([^\t]*)\t([^\t]*)\t?(.*)$")
                local key=norm_rid(rid)
                if key~="" then
                    wl.by_rid[key]={username=clean_name(name),last_seen=tonumber(lastSeen or 0) or 0,source=clean_name(source)}
                end
            end
        end
        f:close()
        return true
    end

    function startup.browser_verified_whitelist_add_build344(rid,username,source)
        load_file()
        local key=norm_rid(rid)
        if key=="" then return false,"INVALID_RID" end
        username=clean_name(username)
        if manual_blocked(key,username) then return false,"EXPLICIT_BROWSER_BLOCK" end
        local now=os.time and os.time() or 0
        local row=wl.by_rid[key]
        local isNew=type(row)~="table"
        if isNew then row={}; wl.by_rid[key]=row end
        if username~="" then row.username=username end
        row.last_seen=now
        row.source=clean_name(source~="" and source or row.source or "VERIFIED_STARTUP")
        if isNew then
            wl.additions=(tonumber(wl.additions or 0) or 0)+1
            save_file()
            if startup.support_log_event_quiet then
                direct_call(startup.support_log_event_quiet,"STARTUP_RID_WHITELIST_ADD","rid="..key.." user="..tostring(row.username or "").." source="..tostring(row.source or ""))
            end
        end
        return true,"WHITELISTED"
    end

    function startup.browser_verified_whitelist_contains_build344(rid,username)
        load_file()
        local key=norm_rid(rid)
        if key=="" then return false end
        if manual_blocked(key,username) then return false end
        return type(wl.by_rid[key])=="table"
    end

    function startup.browser_verified_whitelist_count_build344()
        load_file()
        local n=0
        for _,row in pairs(wl.by_rid) do if type(row)=="table" then n=n+1 end end
        return n
    end

    load_file()

    -- Any successfully verified Startup presence becomes a persistent RID whitelist entry.
    if startup.presence and startup.presence.note_found and wl.presence_wrapped~=true then
        wl.presence_wrapped=true
        local oldNote=startup.presence.note_found
        startup.presence.note_found=function(playerId,playerName,rid,version,build)
            local ok=oldNote(playerId,playerName,rid,version,build)
            if ok==true then startup.browser_verified_whitelist_add_build344(rid,playerName,"VERIFIED_PRESENCE") end
            return ok
        end
    end

    -- Extend Startup's existing verified-peer safety gate with the persistent RID list.
    -- Explicit Browser Manual Block remains authoritative via manual_blocked().
    if startup.browser_safety and startup.browser_safety.is_verified_peer and wl.safety_wrapped~=true then
        wl.safety_wrapped=true
        local oldVerified=startup.browser_safety.is_verified_peer
        startup.browser_safety.is_verified_peer=function(playerId)
            local rid=player_rid(playerId)
            local name=player_name(playerId)
            if rid>0 and startup.browser_verified_whitelist_contains_build344(rid,name) then return true end
            return oldVerified(playerId)
        end
    end

    -- B335 still gets first chance to temporarily clear a real Saved Players Block Join /
    -- Auto Kick entry. But an authenticated Browser JOIN ticket itself is sufficient proof
    -- that the destination is a Startup user, so selector/toggle API incompatibility is no
    -- longer allowed to cancel the JOIN before Cherax even attempts it.
    if startup.browser_join_prepare_local_target_build335 and wl.b335_wrapped~=true then
        wl.b335_wrapped=true
        local oldPrepare=startup.browser_join_prepare_local_target_build335
        startup.browser_join_prepare_local_target_build335=function(username,rid)
            startup.browser_verified_whitelist_add_build344(rid,username,"AUTHENTICATED_BROWSER_JOIN")
            local ok,why=oldPrepare(username,rid)
            if ok==true then return true,why end
            if startup.browser_verified_whitelist_contains_build344(rid,username) then
                if startup.support_log_event_quiet then
                    direct_call(startup.support_log_event_quiet,"BROWSER_JOIN_VERIFIED_RID_FAIL_OPEN","host="..tostring(username or "").." rid="..tostring(rid or "").." saved_players_reason="..tostring(why or "UNKNOWN"))
                end
                return true,"VERIFIED_STARTUP_RID_WHITELIST"
            end
            return false,why
        end
    end

    -- If Browser Trust LIST ever includes an RID field, absorb it automatically without
    -- requiring a new endpoint. Current servers that omit RIDs remain fully compatible.
    if startup.browser_trust_refresh_build291 and wl.trust_refresh_wrapped~=true then
        wl.trust_refresh_wrapped=true
        local oldRefresh=startup.browser_trust_refresh_build291
        startup.browser_trust_refresh_build291=function(force)
            local ok=oldRefresh(force)
            if ok==true and startup.browser_trust_291 and type(startup.browser_trust_291.whitelist)=="table" then
                for _,row in ipairs(startup.browser_trust_291.whitelist) do
                    if type(row)=="table" then
                        local rid=row.rockstar_rid or row.rid or row.rockstarRid
                        if tonumber(rid or 0) and tonumber(rid or 0)>0 then
                            startup.browser_verified_whitelist_add_build344(rid,row.username or row.profileUsername,"BROWSER_TRUST_LIST")
                        end
                    end
                end
            end
            return ok
        end
    end

    if startup.log then
        startup.log("[Browser Whitelist 344] READY | persistent verified Startup RID whitelist="..tostring(startup.browser_verified_whitelist_count_build344()).." | explicit Browser blocks override | authenticated JOIN no longer hard-aborts on Saved Players selector incompatibility")
    end
end
startup.install_verified_startup_rid_whitelist_build344()
startup.install_verified_startup_rid_whitelist_build344=nil

