-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 345: COMMUNITY TRUST / REACTIVE-ONLY SAFETY TEST
--
-- Test goals:
--   * every locally verified Startup RID is a persistent community whitelist entry;
--   * old Cherax PlayerTracker Nuke state is repaired for verified Startup users only;
--   * SavedPlayers.json is backed up before the first repair and never deleted;
--   * verified Startup users: kick attempts are ignored, confirmed crash -> KICK ONLY;
--   * non-Startup proactive country removal is suppressed in this test build;
--   * synthetic policy buttons are DRY-RUN only and never kick/crash anyone.
--
-- This build intentionally does NOT enable retaliatory auto-crash. We first prove RID
-- verification, PlayerTracker repair, and attack attribution before expanding retaliation.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.install_community_trust_test_build345=function()
    startup.community_trust_345=startup.community_trust_345 or {
        installed=false,
        backup_done=false,
        backup_path="",
        last_status="Initializing community trust test...",
        last_repair="None",
        disk_repairs=0,
        live_repairs=0,
        batch_repairs=0,
        simulation_result="No simulation run yet.",
        last_live_repair_ms={},
        worker_started=false,
        render_wrapped=false,
    }
    local ct=startup.community_trust_345
    if ct.installed==true then return end
    ct.installed=true

    local function log(msg)
        if startup.log then startup.log("[Community Trust 345] "..tostring(msg or "")) end
    end

    local function qlog(event,detail)
        if startup.support_log_event_quiet then
            direct_call(startup.support_log_event_quiet,tostring(event or "COMMUNITY_TRUST_345"),tostring(detail or ""))
        end
    end

    local function norm_rid(v)
        local n=tonumber(v or 0) or 0
        if n<=0 then return "" end
        return tostring(math.floor(n))
    end

    local function nowms()
        if startup.now then return tonumber(startup.now()) or 0 end
        if Time and Time.GetEpocheMs then return tonumber(Time.GetEpocheMs()) or 0 end
        return math.floor((os.clock and os.clock() or 0)*1000)
    end

    local function yieldms(ms)
        if startup.yield then return startup.yield(ms or 0) end
        if Script and Script.Yield then return Script.Yield(ms or 0) end
    end

    local function clean_name(v)
        return tostring(v or ""):gsub("[\r\n\t]"," "):sub(1,64)
    end

    local function player_name(pid)
        pid=tonumber(pid)
        if pid==nil then return "" end
        if startup.get_player_name_safe then
            local ok,v=direct_call(startup.get_player_name_safe,pid)
            if ok then return tostring(v or "") end
        end
        if Players and Players.GetName then
            local ok,v=direct_call(Players.GetName,pid)
            if ok then return tostring(v or "") end
        end
        return ""
    end

    local function player_rid(pid)
        pid=tonumber(pid)
        if pid==nil then return 0 end
        if startup.presence and startup.presence.get_player_rid then
            local ok,v=direct_call(startup.presence.get_player_rid,pid)
            if ok and (tonumber(v or 0) or 0)>0 then return tonumber(v or 0) or 0 end
        end
        if Players and Players.GetRockstarId then
            local ok,v=direct_call(Players.GetRockstarId,pid)
            if ok then return tonumber(v or 0) or 0 end
        end
        return 0
    end

    local function is_verified_rid(rid,username)
        local key=norm_rid(rid)
        if key=="" then return false end
        if startup.browser_verified_whitelist_contains_build344 then
            local ok,v=direct_call(startup.browser_verified_whitelist_contains_build344,key,username)
            if ok then return v==true end
        end
        local wl=startup.browser_verified_rid_whitelist_344
        return wl and type(wl.by_rid)=="table" and type(wl.by_rid[key])=="table" or false
    end

    local function is_verified_player(pid)
        if startup.browser_safety and startup.browser_safety.is_verified_peer then
            local ok,v=direct_call(startup.browser_safety.is_verified_peer,pid)
            if ok and v==true then return true end
        end
        local rid=player_rid(pid)
        return rid>0 and is_verified_rid(rid,player_name(pid))
    end

    local function menu_root()
        return tostring(startup.menu_root or "")
    end

    local function savedplayers_path()
        local root=menu_root()
        if root=="" then return "" end
        return root.."\\PlayerTracker\\SavedPlayers.json"
    end

    local function ensure_dir(path)
        if tostring(path or "")=="" then return false end
        if FileMgr and FileMgr.CreateDir then
            local ok=pcall(FileMgr.CreateDir,path)
            return ok
        end
        return true
    end

    local function read_text(path)
        if tostring(path or "")=="" then return nil end
        if FileMgr and FileMgr.ReadFileContent then
            local ok,v=pcall(FileMgr.ReadFileContent,path)
            if ok and type(v)=="string" and v~="" then return v end
        end
        local f=io.open(path,"rb")
        if not f then return nil end
        local body=f:read("*a")
        f:close()
        return body
    end

    local function write_text(path,body)
        if tostring(path or "")=="" or type(body)~="string" then return false end
        if FileMgr and FileMgr.WriteFileContent then
            local ok,v=pcall(FileMgr.WriteFileContent,path,body,false)
            if ok and v~=false then return true end
        end
        local f=io.open(path,"wb")
        if not f then return false end
        f:write(body)
        f:close()
        return true
    end

    local function json_escape(s)
        s=tostring(s or "")
        s=s:gsub("\\","\\\\")
        s=s:gsub('"','\\"')
        s=s:gsub("\b","\\b"):gsub("\f","\\f"):gsub("\n","\\n"):gsub("\r","\\r"):gsub("\t","\\t")
        return s
    end

    local function is_array(t)
        if type(t)~="table" then return false,0 end
        local max=0
        local count=0
        for k,_ in pairs(t) do
            if type(k)~="number" or k<1 or math.floor(k)~=k then return false,0 end
            if k>max then max=k end
            count=count+1
        end
        if max~=count then return false,0 end
        return true,max
    end

    local function json_encode(v,depth,seen)
        depth=tonumber(depth or 0) or 0
        if depth>40 then return "null" end
        local tv=type(v)
        if tv=="nil" then return "null" end
        if tv=="boolean" then return v and "true" or "false" end
        if tv=="number" then
            if v~=v or v==math.huge or v==-math.huge then return "null" end
            return tostring(v)
        end
        if tv=="string" then return '"'..json_escape(v)..'"' end
        if tv~="table" then return '"'..json_escape(tostring(v))..'"' end
        seen=seen or {}
        if seen[v] then return "null" end
        seen[v]=true
        local arr,n=is_array(v)
        local out={}
        if arr then
            for i=1,n do out[#out+1]=json_encode(v[i],depth+1,seen) end
            seen[v]=nil
            return "["..table.concat(out,",").."]"
        end
        local keys={}
        for k,_ in pairs(v) do keys[#keys+1]=tostring(k) end
        table.sort(keys,function(a,b)
            local an,bn=tonumber(a),tonumber(b)
            if an and bn then return an<bn end
            return a<b
        end)
        for _,ks in ipairs(keys) do
            local value=v[ks]
            if value==nil then
                local nk=tonumber(ks)
                if nk~=nil then value=v[nk] end
            end
            if value~=nil then out[#out+1]='"'..json_escape(ks)..'":'..json_encode(value,depth+1,seen) end
        end
        seen[v]=nil
        return "{"..table.concat(out,",").."}"
    end

    local function decode_json(body)
        local bb=startup.browser_backend or {}
        if type(bb._json_decode)=="function" then
            local ok,v=pcall(bb._json_decode,tostring(body or ""))
            if ok and type(v)=="table" then return v end
        end
        return nil
    end

    local function ensure_backup()
        if ct.backup_done==true then return true end
        local src=savedplayers_path()
        local body=read_text(src)
        if not body then
            ct.last_status="PlayerTracker backup skipped: SavedPlayers.json not found."
            return false
        end
        local root=menu_root()
        if root=="" then return false end
        local dir=root.."\\PlayerTracker\\Startup_Backups"
        ensure_dir(root.."\\PlayerTracker")
        ensure_dir(dir)
        local stamp=(os.date and os.date("%Y%m%d_%H%M%S")) or tostring(math.floor(nowms()))
        local dst=dir.."\\SavedPlayers_BEFORE_STARTUP_TRUST_B345_"..stamp..".json"
        if not write_text(dst,body) then
            ct.last_status="PlayerTracker backup FAILED; repair was not written."
            log("BACKUP_FAILED | "..dst)
            return false
        end
        ct.backup_done=true
        ct.backup_path=dst
        log("BACKUP_OK | "..dst)
        qlog("STARTUP_TRUST_PLAYERTRACKER_BACKUP","path="..dst)
        return true
    end

    local function apply_safe_flags(row)
        if type(row)~="table" then return false,{} end
        local changed={}
        local fields={"block_join","auto_kick","auto_crash","rid_kick_loop"}
        for _,field in ipairs(fields) do
            if row[field]~=false then
                changed[#changed+1]=field.."="..tostring(row[field]).."->false"
                row[field]=false
            end
        end
        return #changed>0,changed
    end

    local function repair_internal_rid_store(rid,username,source)
        local key=norm_rid(rid)
        if key=="" or not is_verified_rid(key,username) then return false end
        if not startup.rid_store or type(startup.rid_store.data)~="table" then return false end
        local entry=startup.rid_store.data[key]
        if type(entry)~="table" then return false end
        local changed=false
        if entry.blockJoin==true then entry.blockJoin=false; changed=true end
        entry.flags=type(entry.flags)=="table" and entry.flags or {}
        if entry.flags.blockRidJoin==true then entry.flags.blockRidJoin=nil; changed=true end
        if changed then
            if startup.rid_store.save then pcall(startup.rid_store.save) end
            log("RID_STORE_ALLOW | rid="..key.." user="..tostring(username or "").." source="..tostring(source or ""))
            qlog("STARTUP_TRUST_RID_STORE_ALLOW","rid="..key.." user="..tostring(username or "").." source="..tostring(source or ""))
        end
        return changed
    end

    function startup.community_trust_repair_disk_build345(rid,username,source)
        local key=norm_rid(rid)
        username=clean_name(username)
        if key=="" then return false,"INVALID_RID" end
        if not is_verified_rid(key,username) then return false,"NOT_VERIFIED_OR_PERSONALLY_BLOCKED" end
        local path=savedplayers_path()
        local body=read_text(path)
        if not body then return false,"SAVEDPLAYERS_NOT_FOUND" end
        local data=decode_json(body)
        if type(data)~="table" then return false,"JSON_DECODE_FAILED" end
        local row=data[key]
        if type(row)~="table" then return true,"NOT_SAVED" end
        local changed,changes=apply_safe_flags(row)
        if not changed then return true,"ALREADY_SAFE" end
        if not ensure_backup() then return false,"BACKUP_REQUIRED" end
        local encoded=json_encode(data,0,{})
        if not write_text(path,encoded.."\n") then return false,"WRITE_FAILED" end
        local verify=decode_json(read_text(path) or "")
        local vr=type(verify)=="table" and verify[key] or nil
        if type(vr)~="table" or vr.block_join~=false or vr.auto_kick~=false or vr.auto_crash~=false or vr.rid_kick_loop~=false then
            return false,"VERIFY_FAILED"
        end
        ct.disk_repairs=(tonumber(ct.disk_repairs or 0) or 0)+1
        ct.last_repair=(username~="" and username or key).." | "..table.concat(changes,", ")
        ct.last_status="Verified Startup PlayerTracker repair OK: "..ct.last_repair
        log("PLAYERTRACKER_REPAIR | rid="..key.." user="..username.." source="..tostring(source or "").." | "..table.concat(changes," | "))
        qlog("STARTUP_TRUST_PLAYERTRACKER_REPAIR","rid="..key.." user="..username.." source="..tostring(source or "").." changes="..table.concat(changes,";"))
        return true,"REPAIRED"
    end

    local function find_feature(names)
        local nk=startup.nuke_join_kick or {}
        if nk.find_global_feature_by_names then
            local ok,f,name=pcall(nk.find_global_feature_by_names,names or {})
            if ok then return f,name end
        end
        if FeatureMgr and FeatureMgr.GetFeatureByName then
            for _,name in ipairs(names or {}) do
                local ok,f=direct_call(FeatureMgr.GetFeatureByName,name)
                if ok and f then return f,name end
            end
        end
        return nil,nil
    end

    function startup.community_trust_repair_live_build345(rid,username,source)
        local key=norm_rid(rid)
        username=clean_name(username)
        if key=="" or username=="" then return false,"INVALID_TARGET" end
        if not is_verified_rid(key,username) then return false,"NOT_VERIFIED_OR_PERSONALLY_BLOCKED" end
        if not startup.browser_b335_find_saved_player_exact then return false,"SAVED_PLAYERS_API_UNAVAILABLE" end
        local selected,why=startup.browser_b335_find_saved_player_exact(username)
        if not selected then
            if why=="NOT_SAVED" then return true,"NOT_SAVED" end
            return false,why or "SELECT_FAILED"
        end
        local groups={
            {label="Block Join",names=(startup.nuke_join_kick and startup.nuke_join_kick.block_join_names) or {"Block Join"}},
            {label="Auto Kick",names=(startup.nuke_join_kick and startup.nuke_join_kick.auto_kick_names) or {"Auto Kick"}},
            {label="Auto Crash",names={"Auto Crash","Auto-Crash","Automatic Crash","Crash On Join","Crash on Join","Auto Crash Saved Player","Saved Player Auto Crash"}},
            {label="RID Kick Loop",names={"RID Kick Loop","Rid Kick Loop","RID Kickloop","Kick Loop","RID Loop Kick"}},
        }
        local changed={}
        local unavailable={}
        for _,g in ipairs(groups) do
            local f=select(1,find_feature(g.names))
            if f then
                local on=startup.browser_b335_feature_is_on and startup.browser_b335_feature_is_on(f) or false
                if on==true then
                    local ok=startup.browser_b335_feature_set_bool and startup.browser_b335_feature_set_bool(f,false) or false
                    changed[#changed+1]=g.label.."="..(ok and "OFF" or "OFF_FAILED")
                end
            else
                unavailable[#unavailable+1]=g.label
            end
        end
        if #changed>0 then
            ct.live_repairs=(tonumber(ct.live_repairs or 0) or 0)+1
            log("LIVE_REPAIR | rid="..key.." user="..username.." source="..tostring(source or "").." | "..table.concat(changed," | "))
            qlog("STARTUP_TRUST_LIVE_REPAIR","rid="..key.." user="..username.." changes="..table.concat(changed,";"))
        end
        if #unavailable>0 then
            qlog("STARTUP_TRUST_LIVE_FEATURE_UNAVAILABLE","rid="..key.." user="..username.." features="..table.concat(unavailable,","))
        end
        return true,#changed>0 and "LIVE_REPAIRED" or "LIVE_ALREADY_SAFE_OR_UNAVAILABLE"
    end

    function startup.community_trust_repair_verified_build345(rid,username,source)
        local dOk,dWhy=startup.community_trust_repair_disk_build345(rid,username,source)
        local lOk,lWhy=startup.community_trust_repair_live_build345(rid,username,source)
        local rChanged=repair_internal_rid_store(rid,username,source)
        return dOk or lOk or rChanged,tostring(dWhy).." / "..tostring(lWhy).." / rid_store="..tostring(rChanged)
    end

    function startup.community_trust_repair_all_known_build345(source)
        local wl=startup.browser_verified_rid_whitelist_344
        if not wl or type(wl.by_rid)~="table" then ct.last_status="Verified RID whitelist not ready." return false end
        local path=savedplayers_path()
        local body=read_text(path)
        if not body then ct.last_status="SavedPlayers.json not found; live repair will still run." return false end
        local data=decode_json(body)
        if type(data)~="table" then ct.last_status="SavedPlayers.json could not be decoded." return false end
        local changedRows=0
        local changedFields=0
        local touched={}
        for rid,row in pairs(wl.by_rid) do
            local username=type(row)=="table" and tostring(row.username or "") or ""
            if is_verified_rid(rid,username) then
                repair_internal_rid_store(rid,username,"BATCH:"..tostring(source or ""))
                if type(data[tostring(rid)])=="table" then
                    local changed,changes=apply_safe_flags(data[tostring(rid)])
                    if changed then
                        changedRows=changedRows+1
                        changedFields=changedFields+#changes
                        touched[#touched+1]=tostring(rid)..":"..username
                    end
                end
            end
        end
        if changedRows==0 then
            ct.last_status="Verified Startup migration check: all known SavedPlayers entries are already safe."
            return true
        end
        if not ensure_backup() then return false end
        if not write_text(path,json_encode(data,0,{}).."\n") then ct.last_status="Verified Startup migration write FAILED." return false end
        local verify=decode_json(read_text(path) or "")
        if type(verify)~="table" then ct.last_status="Verified Startup migration verify FAILED." return false end
        ct.batch_repairs=(tonumber(ct.batch_repairs or 0) or 0)+changedRows
        ct.disk_repairs=(tonumber(ct.disk_repairs or 0) or 0)+changedRows
        ct.last_repair=tostring(changedRows).." known Startup SavedPlayers entries repaired ("..tostring(changedFields).." flags)."
        ct.last_status="One-time old-Nuke recovery complete: "..ct.last_repair
        log("BATCH_REPAIR | rows="..tostring(changedRows).." fields="..tostring(changedFields).." source="..tostring(source or "").." | "..table.concat(touched,","))
        qlog("STARTUP_TRUST_BATCH_REPAIR","rows="..tostring(changedRows).." fields="..tostring(changedFields).." source="..tostring(source or ""))
        return true
    end

    function startup.community_trust_policy_decision_build345(isStartup,attackKind)
        local kind=tostring(attackKind or "NONE"):upper()
        if isStartup==true then
            if kind=="CRASH" then return "KICK_ONLY","Verified Startup crash attempt: protect locally, reactive kick only, no auto-crash, no Nuke, no automatic blacklist." end
            if kind=="KICK" then return "NO_RETALIATION","Verified Startup kick attempt: log/diagnose only; do not retaliate." end
            return "WHITELIST","Verified Startup user: community whitelist remains active."
        end
        if kind=="CRASH" then return "RETALIATION_AUTHORIZED","Non-Startup confirmed crash attempt: defensive retaliation is authorized only after this attack evidence." end
        if kind=="KICK" then return "RETALIATION_AUTHORIZED","Non-Startup confirmed kick attempt: defensive retaliation is authorized only after this attack evidence." end
        return "NO_AUTOMATIC_ACTION","Non-Startup user with no attack evidence: no automatic retaliation."
    end

    function startup.community_trust_simulate_build345(isStartup,kind)
        local action,detail=startup.community_trust_policy_decision_build345(isStartup==true,kind)
        ct.simulation_result=(isStartup and "STARTUP" or "NON-STARTUP").." + "..tostring(kind).." => "..action.." | "..detail
        log("DRY_RUN | "..ct.simulation_result)
        qlog("STARTUP_TRUST_DRY_RUN",ct.simulation_result)
        return action
    end

    -- Every newly verified Startup RID immediately receives the PlayerTracker repair.
    if startup.browser_verified_whitelist_add_build344 and ct.whitelist_add_wrapped~=true then
        ct.whitelist_add_wrapped=true
        local oldAdd=startup.browser_verified_whitelist_add_build344
        startup.browser_verified_whitelist_add_build344=function(rid,username,source)
            local ok,why=oldAdd(rid,username,source)
            if ok==true and is_verified_rid(rid,username) then
                if Script and Script.QueueJob then
                    Script.QueueJob(function()
                        yieldms(50)
                        startup.community_trust_repair_verified_build345(rid,username,"WHITELIST_ADD:"..tostring(source or ""))
                    end)
                else
                    startup.community_trust_repair_verified_build345(rid,username,"WHITELIST_ADD:"..tostring(source or ""))
                end
            end
            return ok,why
        end
    end

    -- Verified Startup RIDs may still receive detection/history records, but those
    -- records are never allowed to recreate automatic RID-block enforcement.
    if startup.rid_store and startup.rid_store.record and ct.rid_record_wrapped~=true then
        ct.rid_record_wrapped=true
        local oldRecord=startup.rid_store.record
        startup.rid_store.record=function(playerId,eventType,reason,action,markBlock)
            if is_verified_player(playerId) then
                markBlock=false
                if tostring(action or ""):find("Block Join",1,true) then action="Logged only (Verified Startup)" end
            end
            local a,b=oldRecord(playerId,eventType,reason,action,markBlock)
            if is_verified_player(playerId) then
                local rid=player_rid(playerId)
                repair_internal_rid_store(rid,player_name(playerId),"RID_RECORD_POST")
            end
            return a,b
        end
    end
    if startup.rid_store and startup.rid_store.record_known_identity and ct.rid_known_wrapped~=true then
        ct.rid_known_wrapped=true
        local oldKnown=startup.rid_store.record_known_identity
        startup.rid_store.record_known_identity=function(name,rid,eventType,reason,action,markBlock)
            if is_verified_rid(rid,name) then
                markBlock=false
                if tostring(action or ""):find("Block Join",1,true) then action="Logged only (Verified Startup)" end
            end
            local a,b=oldKnown(name,rid,eventType,reason,action,markBlock)
            if is_verified_rid(rid,name) then repair_internal_rid_store(rid,name,"RID_KNOWN_POST") end
            return a,b
        end
    end

    -- B335 must never restore a verified Startup user back to Block Join / Auto Kick ON.
    if startup.browser_join_restore_local_target_build335 and ct.b335_restore_wrapped~=true then
        ct.b335_restore_wrapped=true
        local oldRestore=startup.browser_join_restore_local_target_build335
        startup.browser_join_restore_local_target_build335=function(username,reason)
            local st=startup.browser_join_local_allow_335
            local key=tostring(username or ""):lower()
            local state=st and st.active and st.active[key] or nil
            local rid=type(state)=="table" and state.rid or ""
            if is_verified_rid(rid,username) then
                if st and st.active then st.active[key]=nil end
                startup.community_trust_repair_verified_build345(rid,username,"B335_RESTORE_SUPPRESSED")
                qlog("STARTUP_TRUST_B335_RESTORE_SUPPRESSED","rid="..tostring(rid).." user="..tostring(username).." reason="..tostring(reason or ""))
                return true
            end
            return oldRestore(username,reason)
        end
    end

    -- Build 290's temporary incoming whitelist also must not restore an already-verified
    -- Startup member back into an old blocked state after the JOIN/session changes.
    if startup.browser_join_whitelist_restore_all_build290 and ct.b290_restore_wrapped~=true then
        ct.b290_restore_wrapped=true
        local oldRestoreAll=startup.browser_join_whitelist_restore_all_build290
        startup.browser_join_whitelist_restore_all_build290=function(reason)
            local wl290=startup.browser_join_whitelist_290
            local known=startup.browser_verified_rid_whitelist_344
            if wl290 and type(wl290.active)=="table" and known and type(known.by_rid)=="table" then
                local nameToRid={}
                for rid,row in pairs(known.by_rid) do
                    if type(row)=="table" and tostring(row.username or "")~="" then nameToRid[tostring(row.username):lower()]=tostring(rid) end
                end
                for key,state in pairs(wl290.active) do
                    local username=type(state)=="table" and tostring(state.username or "") or tostring(key or "")
                    local rid=nameToRid[username:lower()] or ""
                    if rid~="" and is_verified_rid(rid,username) then
                        wl290.active[key]=nil
                        startup.community_trust_repair_verified_build345(rid,username,"B290_RESTORE_SUPPRESSED")
                        qlog("STARTUP_TRUST_B290_RESTORE_SUPPRESSED","rid="..rid.." user="..username.." reason="..tostring(reason or ""))
                    end
                end
            end
            return oldRestoreAll(reason)
        end
    end

    -- New community rule for verified Startup users:
    -- KICK attempts never receive automatic retaliation. Crash attempts receive a one-time
    -- KICK ONLY response and remain whitelisted unless the local user explicitly blacklists.
    if startup.crash_defense and startup.crash_defense.confirm_kick_reaction and ct.kick_verify_wrapped~=true then
        ct.kick_verify_wrapped=true
