-- ============================================================================
-- B352 RID HOST WATCH: local RID sweep + previous-session host succession
-- ============================================================================
-- This layer does NOT upload RID Session data and does NOT use Startup accounts.
-- It keeps the local RecentPlayers catalog, scans all locally-known RIDs against
-- multiple Cherax Find Sessions result passes, and preserves short-lived host
-- succession evidence when the local player leaves a session.

startup.rid352 = startup.rid352 or {
    candidate_ttl_sec = 120,
    sweep_interval_ms = 60000,
    candidate_count = 0,
    sweep_passes = 0,
    sweep_rows = 0,
    last_sweep_ms = 0,
}

-- Wrap the existing local scanner so that, while the local player is Session Host,
-- Startup remembers the next player in Cherax's HOST_QUEUE. Once we leave that lobby,
-- that RID becomes a short-lived "host successor" candidate while the background
-- matchmaking sweep attempts to verify it remotely.
if startup._rid352_scan_wrapped ~= true then
    startup._rid352_scan_wrapped = true
    startup._rid352_old_scan_local_341 = startup.live_r_scan_local_341
    startup.live_r_scan_local_341 = function()
        local result = startup._rid352_old_scan_local_341 and startup._rid352_old_scan_local_341() or (startup.rid_session_local_347.local_data or {})
        local lr = startup.rid_session_local_347
        local hostPid = -1
        if startup.get_session_host_name then
            local _,p = startup.get_session_host_name()
            hostPid = tonumber(p or -1) or -1
        end
        local localPid = -1
        if GTA and GTA.GetLocalPlayerId then
            local ok,v = direct_call(GTA.GetLocalPlayerId)
            if ok then localPid = tonumber(v or -1) or -1 end
        end
        if localPid < 0 then
            for pid=0,31 do
                if startup.is_local_player_id and startup.is_local_player_id(pid) then localPid=pid break end
            end
        end

        if hostPid >= 0 and hostPid == localPid and startup.get_next_host_name then
            local _,nextPid = startup.get_next_host_name(hostPid)
            nextPid = tonumber(nextPid or -1) or -1
            if nextPid >= 0 and nextPid <= 31 and nextPid ~= localPid then
                local sessionPlayers = math.max(1,math.min(32,tonumber(startup.get_session_player_count and startup.get_session_player_count() or 1) or 1))
                local ident = startup.live_r_player_identity_341 and startup.live_r_player_identity_341(nextPid,hostPid,sessionPlayers) or nil
                if ident and ident.rid and not startup.live_r_is_protected_startup_user_342(nextPid,ident.rid) then
                    local rid=tostring(ident.rid)
                    local row=type(lr.local_data[rid])=="table" and lr.local_data[rid] or {}
                    row.rid=rid
                    row.name=tostring(ident.name or row.name or "Unknown")
                    row.city=ident.city or row.city
                    row.country=ident.country or row.country
                    row.countryCode=ident.country_code or row.countryCode
                    row.language=ident.language or row.language
                    row.edition=ident.edition or row.edition
                    row.lastNextHostSeen=os.time()
                    row.lastNextHostPlayers=sessionPlayers
                    row.nextHostSeenCount=(tonumber(row.nextHostSeenCount or 0) or 0)+1
                    row.lastNextHostSource="HOST_QUEUE"
                    lr.local_data[rid]=row
                    lr.local_dirty=true
                    if startup.live_r_save_local_341 then startup.live_r_save_local_341(false) end
                end
            end
        end
        return result
    end
end

-- Helper used by the multi-pass sweep to set a temporary player-count bucket.
function startup.rid352_set_player_bucket(minPlayers,maxPlayers)
    local minF=startup.rid351_get_feature(startup.rid351_feature_hashes.min_players,{"Minimum Players"})
    local maxF=startup.rid351_get_feature(startup.rid351_feature_hashes.max_players,{"Maximum Players"})
    if minF and minF.SetIntValue then
        pcall(function() minF:SetIntValue(tonumber(minPlayers or 1) or 1) end)
        if minF.TriggerCallback then pcall(function() minF:TriggerCallback() end) end
    end
    if maxF and maxF.SetIntValue then
        pcall(function() maxF:SetIntValue(tonumber(maxPlayers or 32) or 32) end)
        if maxF.TriggerCallback then pcall(function() maxF:TriggerCallback() end) end
    end
end

function startup.rid352_collect_find_pass(findFeature,foundFeature,beforeSig)
    local clicked=false
    if findFeature and findFeature.OnClick then clicked=pcall(function() findFeature:OnClick() end) end
    if not clicked and findFeature and findFeature.TriggerCallback then clicked=pcall(function() findFeature:TriggerCallback() end) end
    if not clicked then return false,{} end
    local latest={}
    local changedAt=0
    for i=1,20 do
        if startup.yield then startup.yield(250) elseif Script and Script.Yield then Script.Yield(250) end
        latest=startup.rid351_get_feature_list(foundFeature,startup.rid351_feature_hashes.found_sessions)
        local sig=startup.rid351_list_signature(latest)
        if sig~=beforeSig and changedAt==0 then changedAt=i end
        if changedAt>0 and (i-changedAt)>=2 then break end
        if i>=14 and next(latest)~=nil then break end
    end
    return true,latest
end

-- B352 replaces the single broad Find Sessions request with a local multi-pass sweep.
-- Each returned host row is compared against every locally logged RID/name. This is
-- still local-only; it does not submit the RID list anywhere.
function startup.rid351_run_matchmaking_discovery()
    local lr=startup.rid_session_local_347
    if lr.matchmaking_busy==true then return false end
    lr.matchmaking_busy=true
    lr.matchmaking_error=""
    lr.status="LOCAL • SCANNING LOGGED RIDS FOR HOSTS"
    startup.live_r_scan_local_341()

    local findFeature=startup.rid351_get_feature(startup.rid351_feature_hashes.find_sessions,{"Find Sessions"})
    local foundFeature=startup.rid351_get_feature(startup.rid351_feature_hashes.found_sessions,{"Found Sessions"})
    if not findFeature or not foundFeature then
        lr.matchmaking_busy=false
        lr.matchmaking_error="Cherax Find Sessions / Found Sessions feature unavailable"
        lr.status="LOCAL • HOST SCAN UNAVAILABLE"
        return false
    end

    local original=startup.rid351_snapshot_and_broaden_filters()
    local buckets={{1,32},{1,8},{9,16},{17,24},{25,32}}
    local union={}
    local unionOrder={}
    local passCount=0
    local clickedAny=false
    local previous=startup.rid351_get_feature_list(foundFeature,startup.rid351_feature_hashes.found_sessions)
    local previousSig=startup.rid351_list_signature(previous)

    for _,bucket in ipairs(buckets) do
        startup.rid352_set_player_bucket(bucket[1],bucket[2])
        local ok,rows=startup.rid352_collect_find_pass(findFeature,foundFeature,previousSig)
        if ok then clickedAny=true end
        passCount=passCount+1
        for _,label in pairs(rows or {}) do
            local text=startup.live_r_trim_341(label,180)
            if text~="" and not union[text] then union[text]=true; unionOrder[#unionOrder+1]=text end
        end
        previousSig=startup.rid351_list_signature(rows)
    end

    startup.rid351_restore_filters(original)
    if not clickedAny then
        lr.matchmaking_busy=false
        lr.matchmaking_error="Cherax Find Sessions callback failed"
        lr.status="LOCAL • HOST SCAN CALLBACK FAILED"
        return false
    end

    startup.rid351_build_active_matches(unionOrder)
    lr.matchmaking_busy=false
    lr.matchmaking_error=""
    startup.rid352.sweep_passes=passCount
    startup.rid352.sweep_rows=#unionOrder
    startup.rid352.last_sweep_ms=startup.live_r_now_341()
    startup.live_r_fetch_341()
            -- B354 production: RID Session runtime log intentionally suppressed.
    return true
end

function startup.rid351_request_matchmaking_refresh(force)
    local lr=startup.rid_session_local_347
    local now=startup.live_r_now_341()
    if lr.matchmaking_busy==true then return false end
    if force~=true and now<(tonumber(lr.next_matchmaking_scan_ms or 0) or 0) then return false end
    lr.next_matchmaking_scan_ms=now+(tonumber(startup.rid352.sweep_interval_ms or 60000) or 60000)
    if Script and Script.QueueJob then
        Script.QueueJob(function() startup.rid351_run_matchmaking_discovery() end)
        return true
    end
    return startup.rid351_run_matchmaking_discovery()
end

function startup.rid352_make_row(rid,evidence,row,cur,myEdition)
    local countryCode=(cur and cur.country_code) or row.countryCode or ""
    local country=(cur and cur.country) or row.country or ""
    local language=startup.rid348_language_from_region(countryCode,country,(cur and cur.language) or row.language)
    local verified=evidence and evidence.verified~=false and evidence.candidate~=true
    local source=tostring(evidence and evidence.source or "")
    local edition=(cur and cur.edition) or ((source=="MATCHMAKING" and myEdition~="UNKNOWN") and myEdition or row.edition) or "Unknown"
    local p=(evidence and evidence.players) or (cur and cur.session_players) or row.lastHostPlayers or row.lastNextHostPlayers or row.sessionPlayers
    return {
        player_id=tostring(rid),rid=tostring(rid),username=tostring((cur and cur.name) or row.name or "Unknown"),
        online=verified,current=(source=="CURRENT SESSION"),verified_host=verified,candidate=(evidence and evidence.candidate==true) or false,
        candidate_reason=tostring(evidence and evidence.candidate_reason or ""),
        session_players=p or "?",max_players=(evidence and evidence.max_players) or 32,is_host=true,
        source=source,discovery_label=tostring(evidence and evidence.label or ""),match_method=tostring(evidence and evidence.match_method or ""),
        city=(cur and cur.city) or row.city or "",country=country,country_code=countryCode,
        language=language,edition=edition,
        first_seen=startup.rid347_fmt_time(row.firstSeen),last_seen=startup.rid347_fmt_time(row.lastSeen),last_host_seen=startup.rid347_fmt_time(row.lastHostSeen),
        last_seen_epoch=tonumber(row.lastSeen or 0) or 0,seen_count=tonumber(row.seenCount or 0) or 0,host_seen_count=tonumber(row.hostSeenCount or 0) or 0
    }
end

-- Build the RID Session rows from verified current/matchmaking hosts plus a very short
-- host-succession window. The latter prevents the previous lobby's host from vanishing
-- instantly while Cherax's matchmaking search catches up. Candidate rows are explicitly
-- labelled VERIFYING and are never presented as verified active hosts.
function startup.live_r_fetch_341()
    startup.live_r_scan_local_341()
    local lr=startup.rid_session_local_347
    lr.search=""; lr.edition_filter="ALL"
    local logged=0
    for rid,row in pairs(lr.local_data or {}) do
        if type(row)=="table" and not startup.live_r_is_protected_startup_user_342(nil,rid) then logged=logged+1 end
    end
    local all={}
    local indexed={}
    local myEdition="UNKNOWN"
    if startup.get_active_edition_info then local _,family=startup.get_active_edition_info(); myEdition=startup.live_r_edition_code_343(family) end

    for rid,evidence in pairs(lr.active_by_rid or {}) do
        if type(evidence)=="table" and not startup.live_r_is_protected_startup_user_342(nil,rid) then
            evidence.verified=true
            local row=type(lr.local_data[rid])=="table" and lr.local_data[rid] or {}
            local cur=evidence.current or (lr.current_by_rid and lr.current_by_rid[rid])
            local out=startup.rid352_make_row(rid,evidence,row,cur,myEdition)
            all[#all+1]=out; indexed[tostring(rid)]=true
        end
    end

    local now=os.time()
    local ttl=math.max(30,tonumber(startup.rid352.candidate_ttl_sec or 120) or 120)
    local candidateCount=0
    for rid,row in pairs(lr.local_data or {}) do
        rid=tostring(rid)
        if type(row)=="table" and not indexed[rid] and not startup.live_r_is_protected_startup_user_342(nil,rid) and not (lr.current_by_rid and lr.current_by_rid[rid]) then
            local hostAge=now-(tonumber(row.lastHostSeen or 0) or 0)
            local nextAge=now-(tonumber(row.lastNextHostSeen or 0) or 0)
            local evidence=nil
            if tonumber(row.lastHostSeen or 0)>0 and hostAge>=0 and hostAge<=ttl then
                evidence={source="LAST CONFIRMED HOST",candidate=true,verified=false,candidate_reason="PREVIOUS_SESSION_HOST",players=row.lastHostPlayers,max_players=32,label="Host was directly observed locally "..tostring(hostAge).."s ago"}
            elseif tonumber(row.lastNextHostSeen or 0)>0 and nextAge>=0 and nextAge<=ttl then
                evidence={source="HOST QUEUE SUCCESSOR",candidate=true,verified=false,candidate_reason="HOST_QUEUE_SUCCESSOR",players=row.lastNextHostPlayers,max_players=32,label="Next host in previous lobby HOST_QUEUE "..tostring(nextAge).."s ago"}
            end
            if evidence then
                local out=startup.rid352_make_row(rid,evidence,row,nil,myEdition)
                all[#all+1]=out; indexed[rid]=true; candidateCount=candidateCount+1
            end
        end
    end
    startup.rid352.candidate_count=candidateCount

    table.sort(all,function(a,b)
        if a.current~=b.current then return a.current==true end
        if a.verified_host~=b.verified_host then return a.verified_host==true end
        if a.candidate~=b.candidate then return a.candidate~=true end
        local ap=tonumber(a.session_players or -1) or -1; local bp=tonumber(b.session_players or -1) or -1
        if ap~=bp then return ap>bp end
        return tostring(a.username or ""):lower()<tostring(b.username or ""):lower()
    end)

    local verifiedCount=0
    for _,r in ipairs(all) do if r.verified_host==true then verifiedCount=verifiedCount+1 end end
    lr.logged_count=logged; lr.total_count=#all; lr.total_pages=1; lr.page=0; lr.rows=all; lr.count=#all; lr.last_fetch_ms=startup.live_r_now_341()
    lr.verified_host_count=verifiedCount; lr.candidate_count=candidateCount
    if lr.selected_rid=="" or not indexed[tostring(lr.selected_rid or "")] then lr.selected_rid=all[1] and tostring(all[1].rid) or "" end
    if lr.matchmaking_busy==true then
        lr.status="LOCAL • SCANNING "..tostring(logged).." LOGGED RIDS"
    elseif tostring(lr.matchmaking_error or "")~="" then
        lr.status="LOCAL • HOST SCAN ERROR • "..tostring(logged).." RIDS LOGGED"
    else
        lr.status="LOCAL • "..tostring(verifiedCount).." VERIFIED HOST"..(verifiedCount==1 and "" or "S").." • "..tostring(candidateCount).." VERIFYING • "..tostring(logged).." RIDS LOGGED"
    end
    return true
end
startup.live_r_fetch_340=startup.live_r_fetch_341

function startup.live_r_refresh_341()
    startup.rid_session_local_347.next_scan_ms=0
    startup.rid_session_local_347.next_fetch_ms=0
    startup.rid_session_local_347.next_matchmaking_scan_ms=0
    startup.rid_session_local_347.status="LOCAL • REFRESHING RID HOST WATCH"
    startup.live_r_scan_local_341(); startup.live_r_fetch_341()
    if startup.rid351_request_matchmaking_refresh then startup.rid351_request_matchmaking_refresh(true) end
end
