startup.build_label="B352 Local RID Host Watch + Host Queue Succession"


-- ============================================================================
-- B353 FULL LOCAL RID SWEEP + PREVIOUS-SESSION ROSTER + JOINABLE CANDIDATES
-- ============================================================================
-- RID Session stays local-only. The scan pool is the UNION of:
--   1) every non-Startup RID retained in Startup's local RID cache / RecentPlayers history, and
--   2) every non-Startup RID captured from the immediately preceding populated session roster.
-- Cherax Find Sessions results are compared against this entire pool. Only current/discovered
-- host evidence is rendered. VERIFYING rows are short-lived prior-host/succession evidence.
-- No RID Session data is uploaded to Startup services.

startup.rid353 = startup.rid353 or {
    previous_roster = {},
    previous_roster_count = 0,
    last_roster = {},
    last_roster_count = 0,
    last_host_rid = "",
    scan_pool_count = 0,
    rollover_count = 0,
    last_rollover_epoch = 0,
}

function startup.rid353_count_map(t)
    local n=0
    for _ in pairs(type(t)=="table" and t or {}) do n=n+1 end
    return n
end

function startup.rid353_copy_roster(t)
    local out={}
    for rid,row in pairs(type(t)=="table" and t or {}) do
        out[tostring(rid)]={
            rid=tostring(rid),
            name=tostring(type(row)=="table" and (row.name or row.username) or "Unknown"),
            captured=os.time(),
        }
    end
    return out
end

function startup.rid353_current_roster_from_lr()
    local lr=startup.rid_session_local_347 or {}
    local out={}
    local hostRid=""
    for rid,row in pairs(lr.current_by_rid or {}) do
        rid=tostring(rid or "")
        if rid~="" and type(row)=="table" and not startup.live_r_is_protected_startup_user_342(row.pid,rid) then
            out[rid]={rid=rid,name=tostring(row.name or "Unknown"),is_host=row.is_host==true}
            if row.is_host==true then hostRid=rid end
        end
    end
    return out,hostRid
end

function startup.rid353_overlap_count(a,b)
    local n=0
    for rid in pairs(type(a)=="table" and a or {}) do if type(b)=="table" and b[rid] then n=n+1 end end
    return n
end

function startup.rid353_refresh_pool_count()
    local lr=startup.rid_session_local_347 or {}
    local seen={}
    for rid,row in pairs(lr.local_data or {}) do
        rid=tostring(rid or "")
        if rid~="" and type(row)=="table" and not startup.live_r_is_protected_startup_user_342(nil,rid) then seen[rid]=true end
    end
    for rid in pairs(startup.rid353.previous_roster or {}) do
        rid=tostring(rid or "")
        if rid~="" and not startup.live_r_is_protected_startup_user_342(nil,rid) then seen[rid]=true end
    end
    startup.rid353.scan_pool_count=startup.rid353_count_map(seen)
    return startup.rid353.scan_pool_count
end

-- Capture the immediately preceding populated roster. This is intentionally separate from
-- RecentPlayers.json so a fast session transition cannot make us depend on Cherax flushing
-- the JSON to disk before the old lobby is remembered.
if startup._rid353_scan_wrapped~=true then
    startup._rid353_scan_wrapped=true
    startup._rid353_old_scan_local_341=startup.live_r_scan_local_341
    startup.live_r_scan_local_341=function()
        local result=startup._rid353_old_scan_local_341 and startup._rid353_old_scan_local_341() or (startup.rid_session_local_347.local_data or {})
        local lr=startup.rid_session_local_347 or {}
        local current,currentHost=startup.rid353_current_roster_from_lr()
        local currentCount=startup.rid353_count_map(current)
        local prev=startup.rid353.last_roster or {}
        local prevCount=tonumber(startup.rid353.last_roster_count or 0) or 0
        local prevHost=tostring(startup.rid353.last_host_rid or "")
        local overlap=startup.rid353_overlap_count(prev,current)

        local changed=false
        if prevCount>=2 then
            if currentCount<=1 then
                changed=true
            elseif prevHost~="" and currentHost~="" and prevHost~=currentHost and overlap<=math.max(1,math.floor(math.min(prevCount,currentCount)*0.50)) then
                changed=true
            elseif prevCount>=5 and (overlap/math.max(1,prevCount))<0.35 then
                changed=true
            end
        end

        if changed then
            startup.rid353.previous_roster=startup.rid353_copy_roster(prev)
            startup.rid353.previous_roster_count=prevCount
            startup.rid353.rollover_count=(tonumber(startup.rid353.rollover_count or 0) or 0)+1
            startup.rid353.last_rollover_epoch=os.time()
            for rid,item in pairs(startup.rid353.previous_roster) do
                if not startup.live_r_is_protected_startup_user_342(nil,rid) then
                    local row=type(lr.local_data and lr.local_data[rid])=="table" and lr.local_data[rid] or {}
                    row.rid=tostring(rid)
                    if tostring(row.name or "")=="" then row.name=tostring(item.name or "Unknown") end
                    row.lastPreviousRosterSeen=os.time()
                    row.previousRosterGeneration=startup.rid353.rollover_count
                    lr.local_data[rid]=row
                    lr.local_dirty=true
                end
            end
            if lr.local_dirty and startup.live_r_save_local_341 then startup.live_r_save_local_341(false) end
            -- B354 production: RID Session runtime log intentionally suppressed.
        end

        -- Do not replace a useful populated roster with the brief zero/one-player transition
        -- state. As soon as the new session has at least two non-Startup peers, it becomes the
        -- next roster candidate.
        if currentCount>=2 then
            startup.rid353.last_roster=startup.rid353_copy_roster(current)
            startup.rid353.last_roster_count=currentCount
            startup.rid353.last_host_rid=currentHost
        end

        startup.rid353_refresh_pool_count()
        return result
    end
end

-- B352 already compares every local_data RID/name against every row collected from the
-- multi-pass Cherax Find Sessions sweep. Wrap it so B353 explicitly reports the FULL scan pool
-- (previous roster + all logged local RIDs) and refreshes the previous-roster snapshot first.
if startup._rid353_discovery_wrapped~=true then
    startup._rid353_discovery_wrapped=true
    startup._rid353_old_discovery=startup.rid351_run_matchmaking_discovery
    startup.rid351_run_matchmaking_discovery=function()
        if startup.live_r_scan_local_341 then startup.live_r_scan_local_341() end
        local pool=startup.rid353_refresh_pool_count()
        -- B354 production: RID Session full-pool scan start log intentionally suppressed.
        local ok=false
        if startup._rid353_old_discovery then ok=startup._rid353_old_discovery() else ok=false end
        local lr=startup.rid_session_local_347 or {}
        startup.rid353_refresh_pool_count()
        -- B354 production: RID Session full-pool scan completion log intentionally suppressed.
        return ok
    end
end

-- Join remains a local Cherax RID join. B353 also permits TRY JOIN RID for a short-lived
-- VERIFYING host candidate. That is an attempt, not a claim that the player is still host.
if startup._rid353_join_wrapped~=true then
    startup._rid353_join_wrapped=true
    startup._rid353_old_join=startup.live_r_join_341
    startup.live_r_join_341=function(row)
        if type(row)~="table" then return false end
        local rid=tostring(row.rid or row.player_id or "")
        if startup.live_r_is_protected_startup_user_342(nil,rid) then
            if startup.toast then startup.toast("Startup users are excluded from RID Session. Use Live Sessions for Startup users.",4200) end
            return false
        end
        local candidate=row.candidate==true and row.verified_host~=true and row.current~=true
        -- B354 production: RID Session join-attempt log intentionally suppressed.
        local ok=startup._rid353_old_join and startup._rid353_old_join(row) or false
        if ok and startup.toast and candidate then
            startup.toast("Trying local RID join for VERIFYING host candidate "..tostring(row.username or "")..". Host status may have changed.",3600)
        end
        return ok
    end
    startup.live_r_join_340=startup.live_r_join_341
end



-- B354 PRODUCTION QUIET RID SESSION
-- Keep all RID Session discovery/scan/join/renderer diagnostics out of release logs.
-- This intentionally does NOT suppress RID History, Browser whitelist, Community Trust, or security logs.
if startup._rid_session_quiet_filter_354~=true then
    startup._rid_session_quiet_filter_354=true
    if type(startup.log)=="function" then
        startup._rid_session_log_original_354=startup.log
        startup.log=function(message,...)
            local s=tostring(message or "")
            if string.find(s,"[RID Session",1,true) then return end
            return startup._rid_session_log_original_354(message,...)
        end
    end
    if type(startup.log_colored)=="function" then
        startup._rid_session_log_colored_original_354=startup.log_colored
        startup.log_colored=function(message,...)
            local s=tostring(message or "")
            if string.find(s,"[RID Session",1,true) then return end
            return startup._rid_session_log_colored_original_354(message,...)
        end
    end
    if type(startup.support_log_event_quiet)=="function" then
        startup._rid_session_support_log_original_354=startup.support_log_event_quiet
        startup.support_log_event_quiet=function(event,details,...)
            local e=tostring(event or "")
            if string.sub(e,1,11)=="RID_SESSION" then return end
            return startup._rid_session_support_log_original_354(event,details,...)
        end
    end
end

