-- ============================================================================
-- B357 FINAL v1.0.15: DISENROLLMENT UI GATE + SAFE OFF DEFAULT MIGRATION
-- ============================================================================
-- Release rule:
--   * Disenroll From Browser is an access/UI gate, not only a host-publication switch.
--   * While disenrolled, the Browser tab renders only the re-enrollment notice and the
--     dedicated Browser/policy/assist popup UI is kept closed.
--   * Public_Urinal account authentication stays alive so Config can sync the preference
--     and the user can re-enroll without reinstalling Startup.
--   * Privacy Alias, Disenroll From Browser, and the default policy for NEW blacklist
--     entries are reset OFF once for the v1.0.15/B357 release. After the migration marker
--     is saved, later manual user choices persist normally.

startup.browser_defaults_policy_357 = "v1.0.15_b357_privacy_enrollment_defaults"

startup.browser_is_disenrolled_357 = function()
    return startup.s and startup.s.browserDisenrolled==true
end

startup.browser_close_ui_for_disenroll_357 = function()
    if startup.browser_activity_ui_state then startup.browser_activity_ui_state.popup_open=false end
    if startup.browser_low_population_assist_304 then startup.browser_low_population_assist_304.popup_open=false end
    if startup.browser_terms_runtime then
        startup.browser_terms_runtime.requested=false
        startup.browser_terms_runtime.review=false
        startup.browser_terms_runtime.visible=false
    end
    startup.pending_browser_terms_online_329=false
    if startup.browser then
        startup.browser.joinPopupRequested=false
        startup.browser.joinPopupTarget=nil
    end
end

startup.browser_apply_release_defaults_357 = function()
    if not startup.s then return false end
    local marker=tostring(startup.s.browserTrustPolicyVersion or "")
    if marker==startup.browser_defaults_policy_357 then return false end

    startup.s.browserDisenrolled=false
    startup.s.browserPrivacyAliasEnabled=false
    startup.s.browserBlacklistPreventJoinDefault=false
    startup.s.browserTrustPolicyVersion=startup.browser_defaults_policy_357

    local bt=startup.browser_trust_291
    if bt then
        bt.prefs_dirty=true
        bt.next_refresh_ms=0
    end
    if startup.save_config then startup.save_config(false) end
    return true
end

-- One-time release migration. New/reset configs already begin with these values OFF.
startup.browser_apply_release_defaults_357()

startup.browser_render_disenrolled_357 = function()
    startup.browser_close_ui_for_disenroll_357()
    if startup.browser_ui_draw then startup.browser_ui_draw("b233_brand",432,84,4) end
    if ImGui and ImGui.Spacing then ImGui.Spacing() end
    if startup.text_colored then
        startup.text_colored(0.72,0.42,1.00,1.00,"STARTUP BROWSER")
    elseif ImGui and ImGui.Text then
        ImGui.Text("STARTUP BROWSER")
    end
    if ImGui and ImGui.Spacing then ImGui.Spacing() end
    local msg="Please re-enroll back into the browser in order to use Startup Browser"
    if startup.text_colored_wrapped then
        startup.text_colored_wrapped(1.00,0.78,0.25,1.00,msg)
    elseif ImGui and ImGui.TextWrapped then
        ImGui.TextWrapped(msg)
    elseif ImGui and ImGui.Text then
        ImGui.Text(msg)
    end
    if ImGui and ImGui.Spacing then ImGui.Spacing() end
    if startup.subtle_text_wrapped then
        startup.subtle_text_wrapped("Go to Config > Browser Trust & Privacy and turn OFF Disenroll From Browser to re-enroll.")
    end
end

if startup.render_browser and startup._b357_disenroll_render_wrapped~=true then
    startup._b357_disenroll_render_wrapped=true
    startup.browser_render_pre_disenroll357=startup.render_browser
    startup.render_browser=function(...)
        if startup.browser_is_disenrolled_357() then
