-- ============================================================================
-- BUILD 368 - CORE BUG FIX PHASE 1
-- Base: v1.0.15 Production Build 361
-- Scope: current Cherax Advertise Session/Region API, theme auto-load reliability,
--        HUD session-hop rearm, and truthful Browser identity-review diagnostics.
-- New Region Spoofer / Smart/Super advertising research is deliberately NOT included.
-- ============================================================================
startup.b368 = startup.b368 or {}
startup.b368.region_names = {
    [0]="My Region", [1]="Northern Asia", [2]="Africa", [3]="East America", [4]="Europe",
    [5]="China", [6]="Australia", [7]="West America", [8]="Japan", [9]="Unknown"
}
startup.b368.region_index = {
    ["My Region"]=0, ["Northern Asia"]=1, ["Africa"]=2, ["East America"]=3, ["Europe"]=4,
    ["China"]=5, ["Australia"]=6, ["West America"]=7, ["Japan"]=8, ["Unknown"]=9
}
startup.b368.region_alias = {
    ["USA East"]="East America", ["USA (East)"]="East America",
    ["USA West"]="West America", ["USA (West)"]="West America",
    ["South America"]="My Region", ["Asia"]="My Region"
}

function startup.b368_region_normalize(label)
    label=tostring(label or "My Region")
    label=startup.b368.region_alias[label] or label
    return startup.b368.region_index[label]~=nil and label or "My Region"
end

function startup.b368_region_feature()
    local f=nil
    if FeatureMgr and FeatureMgr.GetFeatureByName then
        local ok,v=direct_call(FeatureMgr.GetFeatureByName,"Advertise Region")
        if ok and v then f=v end
    end
    if not f and FeatureMgr and FeatureMgr.GetFeature then
        local ok,v=direct_call(FeatureMgr.GetFeature,3119786486)
        if ok and v then f=v end
    end
    return f
end

function startup.b368_region_read_index(f)
    if not f then return nil end
    if f.GetListIndex then
        local ok,v=pcall(function() return f:GetListIndex() end)
        if ok and tonumber(v) then return tonumber(v) end
    end
    if FeatureMgr and FeatureMgr.GetFeatureListIndex then
        local ok,v=direct_call(FeatureMgr.GetFeatureListIndex,3119786486)
        if ok and tonumber(v) then return tonumber(v) end
    end
    return nil
end

function startup.b368_resolve_advertise_region()
    local f=startup.b368_region_feature()
    if not f then startup.s.advertiseRegionResolution="Advertise Region control unavailable"; return nil end
    local idx=startup.b368_region_read_index(f)
    local label=idx~=nil and startup.b368.region_names[idx] or nil
    startup.s.advertiseRegionResolution="Resolved current Cherax Advertise Region"
    if label then startup.s.advertiseRegionLabel=label end
    return f,idx,label
end

function startup.request_advertise_region_resolution(force,reason)
    startup.pendingAdvertiseRegionResolution=true
    startup.pendingAdvertiseRegionResolutionForce=force==true
    startup.pendingAdvertiseRegionResolutionReason=tostring(reason or "Build 368 current Cherax resolver")
    return true
end

function startup.process_pending_advertise_region_resolution()
    if startup.pendingAdvertiseRegionResolution~=true then return end
    startup.pendingAdvertiseRegionResolution=false
    local f,idx,label=startup.b368_resolve_advertise_region()
    if f and startup.support_log_event_quiet then
        startup.support_log_event_quiet("ADVERTISE_REGION_B368_RESOLVED","index="..tostring(idx).." region="..tostring(label or "Unknown").." source=exact current Cherax control")
    end
end

function startup.get_advertise_region_label(force)
    local _,_,label=startup.b368_resolve_advertise_region()
    if label then return label end
    return tostring(startup.s.advertiseRegionLabel or startup.b368_region_normalize(startup.s.advertiseRegionManualSelection) or "Unknown")
end

function startup.normalize_manual_advertise_region(value)
    return startup.b368_region_normalize(value)
end

function startup.b368_apply_advertise_region(wanted,markAsUserChoice,reason)
    wanted=startup.b368_region_normalize(wanted)
    local index=startup.b368.region_index[wanted]
    local f=startup.b368_region_feature()
    if not f or index==nil then startup.s.advertiseRegionDefaultStatus="Advertise Region control unavailable; requested "..wanted; return false end
    local ok,err=pcall(function()
        if f.SetListIndex then
            f:SetListIndex(index)
            if f.TriggerCallback then f:TriggerCallback() elseif f.OnClick then f:OnClick() end
        elseif FeatureMgr and FeatureMgr.SetFeatureListIndex then
            FeatureMgr.SetFeatureListIndex(3119786486,index)
            if FeatureMgr.TriggerFeatureCallback then FeatureMgr.TriggerFeatureCallback(3119786486) end
        else error("no supported Advertise Region setter") end
    end)
    if not ok then startup.s.advertiseRegionDefaultStatus="Region change failed: "..tostring(err); return false end
    local verified=startup.b368_region_read_index(f)
    if verified~=nil and verified~=index then
        startup.s.advertiseRegionDefaultStatus="Region readback mismatch: wanted "..wanted.." index "..tostring(index).." got "..tostring(verified)
        return false
    end
    startup.s.advertiseRegionManualSelection=wanted
    startup.s.advertiseRegionLabel=startup.b368.region_names[verified~=nil and verified or index] or wanted
    startup.s.advertiseRegionDefaultStatus="Advertise Region: "..startup.s.advertiseRegionLabel
    startup.s.advertiseRegionAutoScheduleEnabled=false
    startup.s.advertiseRegionAutoScheduleMode="Manually Pick a Region"
    startup.s.advertiseRegionAutoScheduleStatus="Manual region: "..startup.s.advertiseRegionLabel
    if markAsUserChoice==true and startup.s.initialized then startup.save_config(false) end
    if startup.update_hud_cache then direct_call(startup.update_hud_cache,true) end
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("ADVERTISE_REGION_B368","region="..tostring(startup.s.advertiseRegionLabel).." index="..tostring(index).." readback="..tostring(verified).." reason="..tostring(reason or "manual"))
    end
    return true
end

