    startup.pendingAdvertiseRegionName=nil; startup.pendingAdvertiseRegionUserChoice=false
    local ok=startup.b368_apply_advertise_region(wanted,save,"queued current-region change")
    if not ok then startup.s.advertiseRegionDefaultStatus="Region change failed; use native Advertise Region or retry" end
