function startup.render_startup_flow()
    if ImGui.BeginTable("StartupSessionTopTable",2,ImGuiTableFlags.SizingStretchSame) then
        ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
        if ClickGUI.BeginCustomChildWindow("Advertise") then
            startup.section_title("Advertise")

            if startup.h.AdvertisingVariant402 then
                startup.text_colored(0.35,1.00,0.45,1.00,"PRODUCTION ADVERTISING")
                startup.render_feature_guarded_325(startup.h.AdvertisingVariant402)

                local selectedVariant=tostring(startup.s.advertisingVariant402 or "Standard Advertise")
                if selectedVariant=="Region Advertise" or selectedVariant=="Synced Region Advertise" then
                    startup.render_feature_guarded_325(startup.h.AdvertisingVariantRegion402)
                elseif selectedVariant=="Any Advertise" then
                    startup.subtle_text("Override Region: Any | Advertise Region: My Region")
                else
                    startup.subtle_text("Region: My Region")
                end

                startup.render_feature_guarded_325(startup.h.AutoAdvertiseSession)
                startup.render_feature_guarded_325(startup.h.ApplyAdvertisingVariant402)

                if startup.b402 and startup.b402.active==true and startup.h.StopAdvertisingVariant402 then
                    startup.render_feature_guarded_325(startup.h.StopAdvertisingVariant402)
                end
                startup.text_colored_wrapped(1.00,0.20,0.20,1.00,"Players still not joining? Read Guide tab.")

                -- Build 406: keep only the compact operational status.
                if startup.b402 then
                    startup.status_line(
                        "Advertising",
                        tostring(startup.b402.status or "Ready"),
                        0.35,1.00,0.45
                    )
                end
                ImGui.Separator()
            else
                startup.render_feature_guarded_325(startup.h.AutoAdvertiseSession)
                ImGui.Separator()
            end


            startup.subtle_text("Manual / current Advertise Region")
            startup.render_feature_guarded_325(startup.h.AdvertiseManualRegionSelection)
            startup.render_advertise_region_control()

            -- Build 406 intentionally hides the legacy
            -- Run Selected Advertise Method Now / Stop Advertise Session Now controls.

            ClickGUI.EndCustomChildWindow()
        end
        ImGui.TableSetColumnIndex(1)
        if ClickGUI.BeginCustomChildWindow("Matchmaking") then
            startup.section_title("Matchmaking"); local currentNat=startup.get_local_nat_type(); startup.status_line("NAT",tostring(currentNat or "Unknown"),0.42,0.82,1.00)
            if startup.is_prime_active_edition() then startup.subtle_text("Prime NAT HUD defaults ON and retries detection after GTA Online is ready.") end
            startup.render_feature_guarded_325(startup.h.ShowNatTypeHud); startup.render_feature_guarded_325(startup.h.NatTypeOverride); startup.render_feature_guarded_325(startup.h.NatTypeRescan)
            startup.strong_red_warning("NAT: OPEN = most potential players. MODERATE = some players. STRICT = fewer players."); ClickGUI.EndCustomChildWindow()
        end
        ImGui.EndTable()
    end
    -- Build 467: one compact Country Filter dropdown. Summary + Auto Kick controls
    -- live together instead of consuming a separate always-open summary panel.
    local countryOpen=false
    if ImGui.CollapsingHeader then
        local ok,v=pcall(ImGui.CollapsingHeader,"Country Filter (Auto Kick)##StartupB467CountryFilter")
        countryOpen=ok and v==true
    elseif ImGui.Button then
        startup.s.countryFilterListOpen=startup.s.countryFilterListOpen==true
        if ImGui.Button((startup.s.countryFilterListOpen and "▼" or "▶").."  Country Filter (Auto Kick)",-1,34)==true then
            startup.s.countryFilterListOpen=not startup.s.countryFilterListOpen
        end
        countryOpen=startup.s.countryFilterListOpen==true
    else
        countryOpen=true
    end
    if countryOpen then
        if startup.is_prime_active_edition() then startup.subtle_text("Prime default: OFF. Session Host is never removed by Country Filter.") end
        startup.render_feature_guarded_325(startup.h.CountryFilterEnabled)
        startup.render_color_button("Select All","Green","Allow all countries.",function() startup.queue_country_filter_bulk_action("select_all") end,115)
        ImGui.SameLine(); startup.render_color_button("Deselect All","Red","Block all listed countries.",function() startup.queue_country_filter_bulk_action("deselect_all") end,125)
        ImGui.SameLine(); startup.render_color_button("Default","Blue","Restore edition defaults and allow all countries.",function() startup.queue_country_filter_bulk_action("default") end,100)
        local blocked=startup.country_filter.blocked_country_labels()
        startup.subtle_text(#blocked==0 and "Blocked: None" or ("Blocked: "..(#blocked>8 and (tostring(#blocked).." countries") or table.concat(blocked,", "))))
        if ImGui.Separator then ImGui.Separator() end
        startup.render_feature_guarded_325(startup.h.CountryFilterUnknownAllowed)
        startup.render_feature_guarded_325(startup.h.CountryFilterOtherAllowed)
        if ImGui.BeginTable("StartupCountryFilterSessionTableB467",4,ImGuiTableFlags.SizingStretchSame) then
            for index,countryEntry in ipairs(startup.country_filter_countries or {}) do
                if ((index-1)%4)==0 then ImGui.TableNextRow() end
                ImGui.TableSetColumnIndex((index-1)%4)
                startup.render_feature_guarded_325(startup.h["CountryAllow_"..tostring(countryEntry.key)])
            end
            ImGui.EndTable()
        end
        startup.strong_red_warning("WARNING: Messing with Country Filter can cause a lot less players to join you.")
    end
    startup.render_regional_warfare()
    startup.render_defense()
end

