-- Final Build 368 metadata override.
startup.version="v1.0.18"
startup.console_version="v1.0.18"
startup.build_number="2026.08.25.368"
startup.build_date="2026-08-25"
startup.build_label="B368 Core Bug Fix Phase 1 - Current Cherax Advertising + Theme/HUD"

-- ============================================================================
-- BUILD 369: CHERAX ID PRIMARY ACCOUNT LINKING CLIENT
-- ============================================================================
-- Server contract:
--   * Cherax UID is the primary immutable Startup account identity.
--   * Rockstar RID is a secondary binding; one account may own multiple RIDs.
--   * A RID already owned by another Cherax account remains a hard conflict.
-- This client does not bypass server conflicts. It understands the v369 response
-- fields and surfaces/logs the identity model clearly.

startup.b369 = startup.b369 or {}
startup.b369.identity_primary = "CHERAX_UID"
startup.b369.identity_model = "Cherax UID primary; Rockstar RIDs secondary"
startup.b369.last_link_action = tostring(startup.b369.last_link_action or "")
startup.b369.last_identity_status = tostring(startup.b369.last_identity_status or "Waiting for backend")

function startup.b369_identity()
    local cheraxUid=0
    if Cherax and Cherax.GetUID then
        local ok,v=direct_call(Cherax.GetUID)
        if ok then cheraxUid=tonumber(v or 0) or 0 end
    end
    local localId=nil
    if startup.get_local_player_id_candidates then
        local ok,ids=direct_call(startup.get_local_player_id_candidates)
        if ok and type(ids)=="table" then localId=tonumber(ids[1]) end
    end
    if localId==nil or localId<0 then return nil,"WAITING_FOR_LOCAL_PLAYER" end
    local rid=0
    if Players and Players.GetRockstarId then
        local ok,v=direct_call(Players.GetRockstarId,localId)
        if ok then rid=tonumber(v or 0) or 0 end
    end
    if rid<=0 and startup.presence and startup.presence.get_player_rid then
        local ok,v=direct_call(startup.presence.get_player_rid,localId)
        if ok then rid=tonumber(v or 0) or 0 end
    end
    local username=startup.get_player_name_safe and tostring(startup.get_player_name_safe(localId) or "Unknown") or "Unknown"
    local edition=""
    if Cherax and Cherax.GetEdition then
        local ok,v=direct_call(Cherax.GetEdition)
        if ok then edition=tostring(v or "") end
    end
    if cheraxUid<=0 then return nil,"CHERAX_UID_UNAVAILABLE" end
    if rid<=0 then return nil,"ROCKSTAR_RID_UNAVAILABLE" end
    if edition=="" then return nil,"EDITION_UNAVAILABLE" end
    return {
        cherax_uid=string.format("%.0f",cheraxUid),
        rockstar_rid=string.format("%.0f",rid),
        username=username,
        edition=edition
    },nil
end

startup.b369_bootstrap_pre=startup.browser_backend_bootstrap
function startup.browser_backend_bootstrap()
    local bb=startup.browser_backend
    if not bb or type(bb._post)~="function" then
        return startup.b369_bootstrap_pre and startup.b369_bootstrap_pre() or false
    end
    startup.s.browserBackendEnabled=true
    local ident,err=startup.b369_identity()
    if not ident then
        bb.status=tostring(err or "IDENTITY_UNAVAILABLE")
        bb.next_bootstrap_ms=(startup.now and startup.now() or 0)+5000
        return false
    end
    bb.identity_primary="CHERAX_UID"
    bb.status="CONNECTING • CHERAX ID"
    local ok,body=bb._post("bootstrap.php",{
        cherax_uid=ident.cherax_uid,
        rockstar_rid=ident.rockstar_rid,
        username=ident.username,
        edition=ident.edition,
        client_version=tostring(startup.version or ""),
        client_build=tostring(startup.build_number or ""),
        identity_model="CHERAX_UID_PRIMARY",
        allow_secondary_rid_link="1"
    },nil)
    if not ok then
        bb.last_error=tostring(body or "OFFLINE")
        bb.status="OFFLINE"
        bb.next_bootstrap_ms=(startup.now and startup.now() or 0)+30000
        startup.b369.last_identity_status="Backend request failed"
        return false
    end
    local data=nil
    if type(bb._json_decode)=="function" then
        local okJson,v=pcall(bb._json_decode,body)
        if okJson and type(v)=="table" then data=v end
    end
    if type(data)~="table" or data.ok~=true then
        local apiErr=type(data)=="table" and tostring(data.error or "API_ERROR") or "INVALID_BOOTSTRAP_RESPONSE"
        bb.last_error=apiErr
        bb.status=apiErr
        bb.next_bootstrap_ms=(startup.now and startup.now() or 0)+60000
        startup.b369.last_identity_status=apiErr
        startup.b369.last_link_action=type(data)=="table" and tostring(data.rid_link_action or data.link_action or "") or ""
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("ACCOUNT_AUTH_B369_FAIL","status="..apiErr.." identityPrimary=CHERAX_UID linkAction="..tostring(startup.b369.last_link_action))
        end
        return false
    end
    local uid=tostring(data.startup_uid or data.user_uid or "")
    local token=tostring(data.token or "")
    if uid=="" or #token<32 then
        bb.last_error="INVALID_BOOTSTRAP_RESPONSE"; bb.status="INVALID RESPONSE"
        bb.next_bootstrap_ms=(startup.now and startup.now() or 0)+30000
        return false
    end
    bb.startup_uid=uid
    bb.token=token
    bb.token_expires_at=tostring(data.expires_at or "")
    bb.account_status=tostring(data.status or "ACTIVE")
    bb.product_access=tostring(data.product_access or "ACTIVE")
    bb.rockstar_accounts=tonumber(data.linked_rockstar_accounts or data.rockstar_accounts or bb.rockstar_accounts or 1) or 1
    if bb.rockstar_accounts<1 then bb.rockstar_accounts=1 end
    bb.browser_moderation=tostring(data.browser_moderation or bb.browser_moderation or "ACTIVE")
    bb.browser_moderation_reason=tostring(data.browser_moderation_reason or "")
    bb.browser_moderation_message=tostring(data.browser_moderation_message or "")
    bb.browser_moderation_expires_at=tostring(data.browser_moderation_expires_at or "")
    bb.identity_primary=tostring(data.identity_primary or "CHERAX_UID")
    startup.b369.last_link_action=tostring(data.rid_link_action or data.link_action or "EXISTING")
    startup.b369.last_identity_status="Connected via Cherax ID"
    bb.last_error=""
    bb.status=(startup.browser_terms_accepted and startup.browser_terms_accepted()) and "CONNECTED • CHERAX ID" or "CONNECTED • TERMS REQUIRED"
    bb.next_heartbeat_ms=0; bb.next_fetch_ms=0; bb.next_account_ms=0
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("ACCOUNT_AUTH_B369_OK","identityPrimary="..tostring(bb.identity_primary).." linkedRids="..tostring(bb.rockstar_accounts).." linkAction="..tostring(startup.b369.last_link_action))
    end
    return true
end

