-- Build 370 — BattlEye Timeout + Self-Kick Safety Hotfix
-- Production-derived from Build 369 / Build 368 bug-fix foundation.
--
-- Policy:
--   * "BattlEye Timeout" is transport/session noise, never modder/attacker evidence.
--   * It may remain visible in Cherax's own log, but Startup never saves, blocks, kicks,
--     retaliates, or adds it to Startup's Modders HUD/history as actionable evidence.
--   * Automatic removal paths revalidate the live target immediately before action.
--   * Player-feature lookups are rejected if Cherax resolves the feature to a different
--     player slot (especially the local player).
--   * Delayed Saved Players passes are cancelled when the original player identity no
--     longer occupies the target slot.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.b370 = startup.b370 or {}
startup.b370.tag = "B370_BATTLEYE_TIMEOUT_SELF_KICK_HOTFIX"
startup.b370.guard_cancel_total = startup.b370.guard_cancel_total or 0
startup.b370.timeout_suppressed_total = startup.b370.timeout_suppressed_total or 0
startup.b370.last_guard_status = startup.b370.last_guard_status or "Idle"

function startup.b370.normalize(value)
    local s = string.lower(tostring(value or ""))
    s = s:gsub("[_%-]+", " "):gsub("%s+", " ")
    s = s:gsub("^%s+", ""):gsub("%s+$", "")
    return s
end

function startup.b370.is_battleye_timeout(value)
    local s = startup.b370.normalize(value)
    if s == "" then return false end
    local hasBe = s:find("battleye", 1, true) ~= nil or s:find("battleeye", 1, true) ~= nil
    if not hasBe then return false end
    return s:find("timeout", 1, true) ~= nil
        or s:find("timed out", 1, true) ~= nil
        or s:find("time out", 1, true) ~= nil
end

function startup.b370.log_guard(eventName, detail)
    startup.b370.last_guard_status = tostring(detail or eventName or "Guard")
    if startup.log then startup.log("[Build 370 Safety] " .. tostring(detail or eventName or "Guard")) end
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet(tostring(eventName or "B370_SAFETY"), tostring(detail or ""))
    end
end

function startup.b370.player_exists(pid)
    pid = tonumber(pid)
    if pid == nil or pid < 0 or pid > 31 then return false end
    if not (Players and Players.GetById) then return true end
    local ok, obj = direct_call(Players.GetById, pid)
    return ok and obj ~= nil
end

function startup.b370.player_name(pid)
    pid = tonumber(pid)
    if pid == nil then return "" end
    if Players and Players.GetName then
        local ok, name = direct_call(Players.GetName, pid)
        if ok and name and tostring(name) ~= "" and tostring(name) ~= "Invalid" then return tostring(name) end
    end
    if startup.get_player_name_safe then
        local ok, name = direct_call(startup.get_player_name_safe, pid)
        if ok and name then return tostring(name) end
    end
    return ""
end

function startup.b370.player_rid(pid)
    pid = tonumber(pid)
    if pid == nil then return 0 end
    if startup.presence and startup.presence.get_player_rid then
        local ok, rid = direct_call(startup.presence.get_player_rid, pid)
        if ok then return tonumber(rid or 0) or 0 end
    end
    return 0
end

function startup.b370.is_generic_name(name, pid)
    local s = tostring(name or "")
    if s == "" or s == "Invalid" or s == "Unknown" or s == "You" then return true end
    if pid ~= nil and s == ("Player " .. tostring(pid)) then return true end
    return false
end

function startup.b370.capture_target(pid)
    pid = tonumber(pid)
    if pid == nil then return nil, "invalid-player-id" end
    pid = math.floor(pid)
    if pid < 0 or pid > 31 then return nil, "out-of-range-player-id" end
    if startup.is_local_player_id and startup.is_local_player_id(pid) then return nil, "local-player" end
    if not startup.b370.player_exists(pid) then return nil, "player-not-present" end
    return {pid=pid,name=startup.b370.player_name(pid),rid=startup.b370.player_rid(pid)}, nil
end

function startup.b370.validate_target(snapshot, expectedName)
    if type(snapshot) ~= "table" then return false, "missing-snapshot" end
    local pid = tonumber(snapshot.pid)
    if pid == nil or pid < 0 or pid > 31 then return false, "invalid-player-id" end
    if startup.is_local_player_id and startup.is_local_player_id(pid) then return false, "target-became-local-player" end
    if not startup.b370.player_exists(pid) then return false, "target-left-session" end
    local currentName = startup.b370.player_name(pid)
    local originalName = tostring(expectedName or snapshot.name or "")
    if not startup.b370.is_generic_name(originalName, pid)
        and not startup.b370.is_generic_name(currentName, pid)
        and string.lower(currentName) ~= string.lower(originalName) then
        return false, "player-slot-name-changed:" .. originalName .. "->" .. currentName
    end
    local originalRid = tonumber(snapshot.rid or 0) or 0
    local currentRid = startup.b370.player_rid(pid)
    if originalRid > 0 and currentRid > 0 and math.floor(originalRid) ~= math.floor(currentRid) then
        return false, "player-slot-rid-changed"
    end
    return true, "verified"
end

function startup.b370.cancel_guard(path, pid, reason, source)
    startup.b370.guard_cancel_total = (tonumber(startup.b370.guard_cancel_total or 0) or 0) + 1
    startup.b370.log_guard("KICK_TARGET_IDENTITY_GUARD_B370",
        "KICK CANCELLED — TARGET IDENTITY CHANGED | path=" .. tostring(path or "unknown")
        .. " pid=" .. tostring(pid or "nil") .. " reason=" .. tostring(reason or "unknown")
        .. " source=" .. tostring(source or "unknown"))
    return false
end

if startup.mod_detection then
    startup.mod_detection.is_battleye_timeout_reason = startup.b370.is_battleye_timeout
    if startup.mod_detection.classify_reason and not startup.b370._wrapped_classify then
        startup.b370._wrapped_classify = true
        startup.b370.old_classify = startup.mod_detection.classify_reason
        startup.mod_detection.classify_reason = function(reason)
            if startup.b370.is_battleye_timeout(reason) then return "ignored", false end
            return startup.b370.old_classify(reason)
        end
    end
    if startup.mod_detection.should_include_reason and not startup.b370._wrapped_include then
        startup.b370._wrapped_include = true
        startup.b370.old_include = startup.mod_detection.should_include_reason
        startup.mod_detection.should_include_reason = function(reason)
            if startup.b370.is_battleye_timeout(reason) then return false, "battleye-timeout-non-actionable-noise-b370" end
            return startup.b370.old_include(reason)
        end
    end
    if startup.mod_detection.is_strong_corroborating_reason and not startup.b370._wrapped_strong then
        startup.b370._wrapped_strong = true
        startup.b370.old_strong = startup.mod_detection.is_strong_corroborating_reason
        startup.mod_detection.is_strong_corroborating_reason = function(reason)
            if startup.b370.is_battleye_timeout(reason) then return false end
            return startup.b370.old_strong(reason)
        end
    end
end

if startup.battleye_auto_block and startup.battleye_auto_block.handle_detection and not startup.b370._wrapped_be_handle then
    startup.b370._wrapped_be_handle = true
    startup.b370.old_be_handle = startup.battleye_auto_block.handle_detection
    startup.battleye_auto_block.handle_detection = function(playerName, line, reason)
        if startup.b370.is_battleye_timeout(reason) or startup.b370.is_battleye_timeout(line) then
            startup.b370.timeout_suppressed_total = (tonumber(startup.b370.timeout_suppressed_total or 0) or 0) + 1
            local detail = "BattlEye Timeout ignored — no classification/save/block/kick | player=" .. tostring(playerName or "Unknown")
                .. " reason=" .. tostring(reason or "Battleye Timeout")
            if startup.battleye_auto_block.set_status then startup.battleye_auto_block.set_status(detail) end
            startup.b370.log_guard("BATTLEYE_TIMEOUT_SUPPRESSED_B370", detail)
            return false
        end
        return startup.b370.old_be_handle(playerName, line, reason)
    end
end

if startup.nuke_join_kick and startup.nuke_join_kick.find_player_feature_by_names and not startup.b370._wrapped_feature_lookup then
    startup.b370._wrapped_feature_lookup = true
    startup.b370.old_feature_lookup = startup.nuke_join_kick.find_player_feature_by_names
    startup.nuke_join_kick.find_player_feature_by_names = function(playerId, names)
        local feature, matched = startup.b370.old_feature_lookup(playerId, names)
        if not feature then return nil, nil end
        local resolved = nil
        if feature.GetPlayerIndex then
            local ok, v = pcall(function() return feature:GetPlayerIndex() end)
            if ok then resolved = tonumber(v) end
        elseif feature.GetArrayIndex then
            local ok, v = pcall(function() return feature:GetArrayIndex() end)
            if ok then resolved = tonumber(v) end
        end
        if resolved ~= nil then
            resolved = math.floor(resolved)
            if startup.is_local_player_id and startup.is_local_player_id(resolved) then
                startup.b370.cancel_guard("Player Feature Lookup", playerId, "feature-resolved-local-player", matched)
                return nil, nil
            end
            if tonumber(playerId) ~= resolved then
                startup.b370.cancel_guard("Player Feature Lookup", playerId, "feature-index-mismatch:" .. tostring(resolved), matched)
                return nil, nil
            end
        end
        return feature, matched
    end
end

if startup.nuke_join_kick and startup.nuke_join_kick.run_for_player_id and not startup.b370._wrapped_nuke_run then
    startup.b370._wrapped_nuke_run = true
    startup.b370.old_nuke_run = startup.nuke_join_kick.run_for_player_id
    startup.nuke_join_kick.run_for_player_id = function(playerId, forceRun, sourceLabel, useHostKickFallback)
        if startup.b370.is_battleye_timeout(sourceLabel) then
            startup.b370.timeout_suppressed_total = (tonumber(startup.b370.timeout_suppressed_total or 0) or 0) + 1
            startup.b370.log_guard("BATTLEYE_TIMEOUT_ACTION_BLOCKED_B370",
                "Blocked Block Join & Kick from BattlEye Timeout | pid=" .. tostring(playerId) .. " source=" .. tostring(sourceLabel or ""))
            return false
        end
        local snap, why = startup.b370.capture_target(playerId)
        if not snap then return startup.b370.cancel_guard("Block Join & Kick", playerId, why, sourceLabel) end
        local ok, verify = startup.b370.validate_target(snap)
        if not ok then return startup.b370.cancel_guard("Block Join & Kick", playerId, verify, sourceLabel) end
        return startup.b370.old_nuke_run(playerId, forceRun, sourceLabel, useHostKickFallback)
    end
end

if startup.nuke_join_kick and startup.nuke_join_kick.apply_saved_player_options and not startup.b370._wrapped_saved_pass then
    startup.b370._wrapped_saved_pass = true
    startup.b370.old_saved_pass = startup.nuke_join_kick.apply_saved_player_options
    startup.nuke_join_kick.apply_saved_player_options = function(targetName, targetPlayerId, passLabel)
        local snap, why = startup.b370.capture_target(targetPlayerId)
        if not snap then
            startup.b370.cancel_guard("Delayed Saved Players Pass", targetPlayerId, why, passLabel)
            return false, false, false
        end
        local ok, verify = startup.b370.validate_target(snap, targetName)
        if not ok then
            startup.b370.cancel_guard("Delayed Saved Players Pass", targetPlayerId, verify, passLabel)
            return false, false, false
        end
        return startup.b370.old_saved_pass(targetName, targetPlayerId, passLabel)
    end
end

if startup.host_kick_bypass and startup.host_kick_bypass.run_for_player_id and not startup.b370._wrapped_hostkick_final then
    startup.b370._wrapped_hostkick_final = true
    startup.b370.old_hostkick_final = startup.host_kick_bypass.run_for_player_id
    startup.host_kick_bypass.run_for_player_id = function(playerId, sourceLabel)
        if startup.b370.is_battleye_timeout(sourceLabel) then
            startup.b370.log_guard("BATTLEYE_TIMEOUT_HOST_KICK_BLOCKED_B370",
                "Blocked Host Kick from BattlEye Timeout | pid=" .. tostring(playerId) .. " source=" .. tostring(sourceLabel or ""))
            return false
        end
        local snap, why = startup.b370.capture_target(playerId)
        if not snap then return startup.b370.cancel_guard("Host Kick", playerId, why, sourceLabel) end
        local ok, verify = startup.b370.validate_target(snap)
        if not ok then return startup.b370.cancel_guard("Host Kick", playerId, verify, sourceLabel) end
        return startup.b370.old_hostkick_final(playerId, sourceLabel)
    end
end

