-- ============================================================================
-- BUILD 371: TRUE STARTUP USERS ONLINE (GLOBAL AUTHENTICATED PRESENCE)
-- ============================================================================
-- Purpose:
--   * Count unique authenticated Startup accounts that are actively running Startup.
--   * Independent from Startup Browser Terms, Browser host publication, Session Host state,
--     Rockstar RID count, edition, advertising, or Browser moderation participation.
--   * Public/client surface receives ONLY the aggregate count. No user list, RID, Cherax UID,
--     Startup UID, username, session, IP, or other per-user identity is returned by this endpoint.
--
-- Server endpoint: startup-presence.php
-- Presence cadence: 30 seconds. Server online TTL: 180 seconds.
-- Multi-RID Build 369 accounts count once because the server counts distinct account_id.

startup.b371 = startup.b371 or {}
startup.b371.presence_interval_ms = 30000
startup.b371.server_ttl_seconds = 180
startup.b371.next_presence_ms = tonumber(startup.b371.next_presence_ms or 0) or 0
startup.b371.last_presence_success_ms = tonumber(startup.b371.last_presence_success_ms or 0) or 0
startup.b371.last_presence_error = tostring(startup.b371.last_presence_error or "")
startup.b371.presence_ready = startup.b371.presence_ready == true

function startup.b371_online_count_text()
    local bb=startup.browser_backend or {}
    local n=tonumber(bb.startup_users_online)
    if n==nil or n<0 then return "..." end
    return tostring(math.floor(n))
end

function startup.b371_presence_tick(force)
    local bb=startup.browser_backend
    if not bb or tostring(bb.token or "")=="" or type(bb._post)~="function" then return false,"NOT_AUTHENTICATED" end
    local now=(startup.now and tonumber(startup.now())) or math.floor(os.clock()*1000)
    if force~=true and now<(tonumber(startup.b371.next_presence_ms or 0) or 0) then return true,"NOT_DUE" end

    -- Schedule before transport so a transient REQUEST_BUSY cannot create a tight retry loop.
    startup.b371.next_presence_ms=now+tonumber(startup.b371.presence_interval_ms or 30000)
    local edition=""
    if Cherax and Cherax.GetEdition then
        local ok,v=direct_call(Cherax.GetEdition)
        if ok then edition=tostring(v or "") end
    end
    local ok,body=bb._post("startup-presence.php",{
        client_version=tostring(startup.version or ""),
        client_build=tostring(startup.build_number or ""),
        edition=edition
    },bb.token)
    if not ok then
        startup.b371.last_presence_error=tostring(body or "PRESENCE_REQUEST_FAILED")
        if startup.b371.last_presence_error=="REQUEST_BUSY" then
            startup.b371.next_presence_ms=now+5000
        end
        return false,startup.b371.last_presence_error
    end

    local data=nil
    if type(bb._json_decode)=="function" then
        local okJson,v=pcall(bb._json_decode,tostring(body or ""))
        if okJson and type(v)=="table" then data=v end
    end
    if type(data)~="table" or data.ok~=true then
        startup.b371.last_presence_error="INVALID_PRESENCE_RESPONSE"
        return false,startup.b371.last_presence_error
    end

    local count=tonumber(data.online_users)
    if count==nil or count<0 then
        startup.b371.last_presence_error="INVALID_ONLINE_COUNT"
        return false,startup.b371.last_presence_error
    end
    bb.startup_users_online=math.floor(count)
    bb.startup_users_online_ttl=tonumber(data.ttl_seconds or startup.b371.server_ttl_seconds) or startup.b371.server_ttl_seconds
    startup.b371.last_presence_success_ms=now
    startup.b371.last_presence_error=""
    startup.b371.presence_ready=true
    return true,"UPDATED"
end

-- Piggyback on the existing serialized Browser transport worker. The wrapper is intentionally
-- installed LAST so Prime/HostTools/Terms publication gates cannot suppress general Startup
-- presence. The general presence request itself does not publish a Browser listing.
if startup.browser_backend_bootstrap and startup.b371._wrapped_bootstrap~=true then
    startup.b371._wrapped_bootstrap=true
    startup.b371.bootstrap_pre=startup.browser_backend_bootstrap
    startup.browser_backend_bootstrap=function(...)
        local ok=startup.b371.bootstrap_pre(...)
        if ok==true then startup.b371_presence_tick(true) end
        return ok
    end
end

if startup.browser_backend_heartbeat and startup.b371._wrapped_heartbeat~=true then
    startup.b371._wrapped_heartbeat=true
    startup.b371.heartbeat_pre=startup.browser_backend_heartbeat
    startup.browser_backend_heartbeat=function(...)
        startup.b371_presence_tick(false)
        return startup.b371.heartbeat_pre(...)
    end
end

-- If Build 371 is hot-loaded after an existing authenticated backend is already active,
-- request one immediate count without waiting for the next heartbeat window.
if startup.browser_backend and tostring(startup.browser_backend.token or "")~="" then
    startup.b371_presence_tick(true)
end

