function startup.b373_format_ms(ms)
    ms=tonumber(ms)
    if ms==nil or ms<0 then return "--:--" end
    local sec=math.floor(ms/1000)
    local min=math.floor(sec/60)
    sec=sec%60
    if min>=60 then
        local hr=math.floor(min/60); min=min%60
        return string.format("%d:%02d:%02d",hr,min,sec)
    end
    return string.format("%d:%02d",min,sec)
end

function startup.b373_override_feature()
    if startup.b373.override_feature then return startup.b373.override_feature end
    if not FeatureMgr or not FeatureMgr.GetFeatureByName then startup.b373.override_status="FeatureMgr name lookup unavailable"; return nil end
    for _,name in ipairs({"Override Region","Matchmaking Region Override","Region Override"}) do
        local ok,f=direct_call(FeatureMgr.GetFeatureByName,name)
        if ok and f then
            startup.b373.override_feature=f
            startup.b373.override_feature_name=name
            startup.b373.override_status="Resolved: "..name
            if startup.support_log_event_quiet then startup.support_log_event_quiet("B373_OVERRIDE_REGION_RESOLVED","name="..name) end
            return f
        end
    end
    startup.b373.override_status="Override Region control unavailable"
    return nil
end

function startup.b373_read_list_index(feature)
    if not feature then return nil end
    if feature.GetListIndex then
        local ok,v=pcall(function() return feature:GetListIndex() end)
        if ok and tonumber(v) then return math.floor(tonumber(v)) end
    end
    return nil
end

function startup.b373_apply_override_region(region)
    region=startup.b368_region_normalize and startup.b368_region_normalize(region) or tostring(region or "My Region")
    local idx=startup.b373.region_index[region]
    if idx==nil or region=="Unknown" then return false,"INVALID_REGION" end
    local f=startup.b373_override_feature()
    if not f then return false,"OVERRIDE_REGION_UNAVAILABLE" end
    local ok,err=pcall(function()
        if f.SetListIndex then
            f:SetListIndex(idx)
            if f.TriggerCallback then f:TriggerCallback() elseif f.OnClick then f:OnClick() end
        else error("Override Region has no SetListIndex") end
    end)
    if not ok then return false,tostring(err) end
    local got=startup.b373_read_list_index(f)
    if got~=nil and got~=idx then return false,"READBACK_MISMATCH:"..tostring(got) end
    return true,startup.b373.region_names[got~=nil and got or idx] or region
end

function startup.b373_read_override_region()
    local f=startup.b373_override_feature()
    local idx=startup.b373_read_list_index(f)
    return idx~=nil and (startup.b373.region_names[idx] or "Unknown") or "Unknown",idx
end

function startup.b373_sync_region_pair(region,reason)
    region=startup.b368_region_normalize and startup.b368_region_normalize(region) or tostring(region or "My Region")
    if region=="Unknown" then return false,"Unknown is never an advertising target" end
    local okOverride,overrideResult=startup.b373_apply_override_region(region)
    local okAdvertise=startup.b368_apply_advertise_region and startup.b368_apply_advertise_region(region,false,"Build 373: "..tostring(reason or "adaptive sync")) or false
    local overrideLabel=startup.b373_read_override_region()
    local advertiseLabel=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
    local verified=okOverride==true and okAdvertise==true and tostring(overrideLabel)==region and tostring(advertiseLabel)==region
    startup.b373.pair_status=(verified and "SYNCED" or "MISMATCH").." | Override="..tostring(overrideLabel).." | Advertise="..tostring(advertiseLabel)
    if startup.h and startup.h.AdvertiseManualRegionSelection and startup.set_feature_list_string_silently then
        direct_call(startup.set_feature_list_string_silently,startup.h.AdvertiseManualRegionSelection,region)
    end
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("B373_REGION_PAIR", "target="..region.." override="..tostring(overrideLabel).." advertise="..tostring(advertiseLabel).." verified="..tostring(verified).." reason="..tostring(reason or ""))
    end
    if not verified then return false,startup.b373.pair_status end
    return true,region
end

function startup.b373_is_local_player(id)
    id=tonumber(id)
    if id==nil then return false end
    if startup.is_local_player_id then
        local ok,v=direct_call(startup.is_local_player_id,id)
        if ok then return v==true end
    end
    if startup.get_local_player_id_candidates then
        local ok,ids=direct_call(startup.get_local_player_id_candidates)
        if ok and type(ids)=="table" then for _,v in ipairs(ids) do if tonumber(v)==id then return true end end end
    end
    return false
end

function startup.b373_current_order()
    if tostring(startup.s.advertisingMode373 or "Smart Adaptive")=="Popularity Rotation" then return startup.b373.popularity_order end
    return startup.b373.smart_order
end

function startup.b373_csv_write_header()
    startup.ensure_save_dir()
    local path=tostring(startup.b373.csv_path or "")
    if path=="" then return false end
    local r=io and io.open and io.open(path,"rb") or nil
    if r then local n=r:seek("end") or 0; r:close(); if n>0 then return true end end
    local f=io and io.open and io.open(path,"w") or nil
    if not f then return false end
    f:write("Timestamp,Mode,Region,Decision,ElapsedMs,StartPlayers,EndPlayers,PeakPlayers,Joins,Leaves,NetGrowth,JoinRatePerMin,NetRatePerMin,Score,PairStatus\\n")
    f:close(); return true
end

function startup.b373_csv_escape(v)
    local s=tostring(v==nil and "" or v)
    if s:find('[,\"\\n]') then s='\"'..s:gsub('\"','\"\"')..'\"' end
    return s
end

function startup.b373_append_region_result(metrics,decision)
    if type(metrics)~="table" then return false end
    startup.b373_csv_write_header()
    local f=io and io.open and io.open(tostring(startup.b373.csv_path or ""),"a") or nil
    if f then
        local vals={os.date("%Y-%m-%d %H:%M:%S"),startup.b373.mode,metrics.region,decision,metrics.elapsedMs,metrics.startPlayers,metrics.players,metrics.peakPlayers,metrics.joins,metrics.leaves,metrics.net, string.format("%.3f",metrics.joinRate),string.format("%.3f",metrics.netRate),string.format("%.3f",metrics.score),startup.b373.pair_status}
        for i,v in ipairs(vals) do vals[i]=startup.b373_csv_escape(v) end
        f:write(table.concat(vals,","),"\\n"); f:close()
    end
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("B373_REGION_RESULT","mode="..tostring(startup.b373.mode).." region="..tostring(metrics.region).." elapsed="..tostring(startup.b373_format_ms(metrics.elapsedMs)).." joins="..tostring(metrics.joins).." leaves="..tostring(metrics.leaves).." net="..tostring(metrics.net).." joinRate="..string.format("%.2f",metrics.joinRate).." score="..string.format("%.2f",metrics.score).." decision="..tostring(decision))
    end
    return true
end

function startup.b373_capture_milestones(now,players)
    if startup.b373.running~=true then return end
    now=tonumber(now or startup.now()) or startup.now(); players=tonumber(players or startup.get_session_player_count()) or 0
    local elapsed=math.max(0,now-(tonumber(startup.b373.overall_started_ms or now) or now))
    for _,n in ipairs({1,5,10,15,20}) do
        if startup.b373.joins>=n and startup.b373.join_milestones[tostring(n)]==nil then startup.b373.join_milestones[tostring(n)]=elapsed end
    end
    for _,n in ipairs({5,10,15,20,25,30}) do
        if players>=n and startup.b373.population_milestones[tostring(n)]==nil then startup.b373.population_milestones[tostring(n)]=elapsed end
    end
end

function startup.b373_metrics(now)
    now=tonumber(now or startup.now()) or startup.now()
    local players=math.max(0,tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0)
    local elapsed=math.max(1000,now-(tonumber(startup.b373.region_started_ms or now) or now))
    local minutes=elapsed/60000
    local joins=math.max(0,(tonumber(startup.b373.joins or 0) or 0)-(tonumber(startup.b373.region_start_joins or 0) or 0))
    local leaves=math.max(0,(tonumber(startup.b373.leaves or 0) or 0)-(tonumber(startup.b373.region_start_leaves or 0) or 0))
    local startPlayers=tonumber(startup.b373.region_start_players or players) or players
    local net=players-startPlayers
    local joinRate=joins/minutes
    local netRate=net/minutes
    local sinceLast=startup.b373.last_join_ms>0 and math.max(0,now-startup.b373.last_join_ms) or elapsed
    local score=(net*4.0)+(joins*1.5)-(leaves*1.25)+(joinRate*2.0)
    if sinceLast>=120000 then score=score-5 end
    return {region=tostring(startup.b373.active_region or "Unknown"),players=players,startPlayers=startPlayers,peakPlayers=tonumber(startup.b373.peak_players or players) or players,elapsedMs=elapsed,joins=joins,leaves=leaves,net=net,joinRate=joinRate,netRate=netRate,sinceLastJoinMs=sinceLast,score=score}
end

function startup.b373_begin_region(region,reason)
    region=tostring(region or "My Region")
    local ok,why=startup.b373_sync_region_pair(region,reason)
    if not ok then
        startup.b373.state="REGION SYNC FAILED"
        startup.b373.last_decision=tostring(why or "Region sync failed")
        startup.s.lastAdvertiseStatus="Adaptive Advertising paused: "..startup.b373.last_decision
        return false
    end
    local now=startup.now(); local players=startup.get_session_player_count()
    startup.b373.active_region=region
    startup.b373.region_started_ms=now
    startup.b373.region_start_players=players
    startup.b373.region_start_joins=startup.b373.joins
    startup.b373.region_start_leaves=startup.b373.leaves
    startup.b373.regions_tested=(tonumber(startup.b373.regions_tested or 0) or 0)+1
    startup.b373.state="TESTING"
    startup.b373.last_decision="Testing "..region
    startup.s.lastAdvertiseStatus="Testing "..region.." | "..tostring(players).." players"
    return true
end

function startup.b373_next_region(reason)
    local order=startup.b373_current_order(); if #order<=0 then return false end
    startup.b373.order_pos=(tonumber(startup.b373.order_pos or 0) or 0)+1
    if startup.b373.order_pos>#order then startup.b373.order_pos=1 end
    return startup.b373_begin_region(order[startup.b373.order_pos],reason or "next adaptive region")
end

function startup.b373_start_engine(reason)
    startup.b373.running=true
    startup.b373.mode=tostring(startup.s.advertisingMode373 or "Smart Adaptive")
    startup.b373.order_pos=0; startup.b373.regions_tested=0
    startup.b373.overall_started_ms=startup.now()
    startup.b373.overall_start_players=startup.get_session_player_count()
    startup.b373.region_started_ms=startup.b373.overall_started_ms
    startup.b373.region_start_players=startup.b373.overall_start_players
    startup.b373.joins=0; startup.b373.leaves=0
    startup.b373.region_start_joins=0; startup.b373.region_start_leaves=0
    startup.b373.first_join_ms=0; startup.b373.last_join_ms=0
    startup.b373.peak_players=startup.b373.overall_start_players
    startup.b373.best_region=""; startup.b373.best_score=-999999; startup.b373.best_summary=""
    startup.b373.join_milestones={}; startup.b373.population_milestones={}
    startup.b373.next_tick_ms=0; startup.b373.last_metrics={}
    startup.b373_capture_milestones(startup.b373.overall_started_ms,startup.b373.overall_start_players)
    if startup.b373.mode=="Manual" then
        startup.b373.order_pos=0
        return startup.b373_begin_region(startup.b368_region_normalize(startup.s.advertiseRegionManualSelection or "My Region"),"manual mode start")
    end
    return startup.b373_next_region(reason or "adaptive start")
end

function startup.b373_stop_engine(reason,record)
    if startup.b373.running==true and record~=false then
        local m=startup.b373_metrics(startup.now()); startup.b373.last_metrics=m; startup.b373_append_region_result(m,"STOP:"..tostring(reason or "stopped"))
    end
    startup.b373.running=false
    startup.b373.state="IDLE"
    startup.b373.last_decision=tostring(reason or "Stopped")
    return true
end

function startup.b373_eta_ms(now,players)
    now=tonumber(now or startup.now()) or startup.now(); players=tonumber(players or startup.get_session_player_count()) or 0
    local target=tonumber(startup.s.advertisingTargetPlayers373 or 30) or 30
    if players>=target then return 0 end
    local elapsed=math.max(1000,now-(tonumber(startup.b373.overall_started_ms or now) or now))
    local net=players-(tonumber(startup.b373.overall_start_players or players) or players)
    local rate=net/(elapsed/60000)
    if rate<=0 then return nil end
    return ((target-players)/rate)*60000
end

function startup.b373_tick()
    if startup.b373.running~=true then return end
    if startup.s.advertiseRunning~=true or startup.s.advertiseStopRequested==true or startup.s.autoAdvertiseSession~=true then startup.b373_stop_engine("advertising no longer active",false); return end
    local now=startup.now()
    if now<(tonumber(startup.b373.next_tick_ms or 0) or 0) then return end
    startup.b373.next_tick_ms=now+startup.b373.tick_ms
    local players=startup.get_session_player_count(); startup.b373.peak_players=math.max(tonumber(startup.b373.peak_players or 0) or 0,tonumber(players or 0) or 0)
    startup.b373_capture_milestones(now,players)
    local m=startup.b373_metrics(now); startup.b373.last_metrics=m
    local target=tonumber(startup.s.advertisingTargetPlayers373 or 30) or 30
    if players>=target then
        startup.b373.state="TARGET REACHED"; startup.b373.last_decision="Holding target population"
        startup.s.lastAdvertiseStatus="Target reached | "..tostring(players).."/"..tostring(target).." | "..tostring(startup.b373.active_region)
        return
    end
    if startup.b373.mode=="Manual" then
        startup.b373.state="MANUAL HOLD"; startup.b373.last_decision="Manual region hold"
        return
    end
    local testMs=(tonumber(startup.s.advertisingRegionTestMinutes373 or 3) or 3)*60000
    if startup.b373.state=="HOLDING" then
        if m.sinceLastJoinMs>=startup.b373.stagnant_ms then
            startup.b373_append_region_result(m,"STAGNANT_ROTATE")
            startup.b373_next_region("held region became stagnant")
        end
        return
    end
    if m.elapsedMs<testMs then return end
    if m.score>tonumber(startup.b373.best_score or -999999) then
        startup.b373.best_score=m.score; startup.b373.best_region=m.region
        startup.b373.best_summary=m.region.." | net "..tostring(m.net).." | "..string.format("%.2f",m.joinRate).." joins/min"
    end
    if m.net>=startup.b373.good_net_growth or m.joinRate>=startup.b373.good_join_rate then
        startup.b373.state="HOLDING"
        startup.b373.last_decision="Good growth - holding "..m.region
        startup.b373_append_region_result(m,"GOOD_GROWTH_HOLD")
        return
    end
    startup.b373_append_region_result(m,"UNDERPERFORM_ROTATE")
    local order=startup.b373_current_order()
    if startup.b373.regions_tested>=#order and tostring(startup.b373.best_region or "")~="" then
        local best=startup.b373.best_region
        startup.b373.regions_tested=0
        startup.b373.best_score=-999999
        startup.b373.best_region=""
        startup.b373_begin_region(best,"best region fallback after full cycle")
        startup.b373.state="HOLDING"
        startup.b373.last_decision="Full cycle complete - holding best region "..best
    else
        startup.b373_next_region("underperforming region")
    end
end

function startup.b373_on_join(playerId)
    if startup.b373.running~=true or startup.b373_is_local_player(playerId) then return end
    local now=startup.now()
    startup.b373.joins=(tonumber(startup.b373.joins or 0) or 0)+1
    if startup.b373.first_join_ms<=0 then startup.b373.first_join_ms=now end
    startup.b373.last_join_ms=now
    local players=startup.get_session_player_count(); startup.b373.peak_players=math.max(tonumber(startup.b373.peak_players or 0) or 0,tonumber(players or 0) or 0)
    startup.b373_capture_milestones(now,players)
end

function startup.b373_on_left(playerId)
    if startup.b373.running~=true or startup.b373_is_local_player(playerId) then return end
    startup.b373.leaves=(tonumber(startup.b373.leaves or 0) or 0)+1
end

function startup.b373_join_milestone_text()
    local parts={}
    for _,n in ipairs({1,5,10,15}) do
        local ms=startup.b373.join_milestones[tostring(n)]
        parts[#parts+1]="+"..tostring(n).." "..startup.b373_format_ms(ms)
    end
    return table.concat(parts," | ")
end

function startup.b373_population_milestone_text()
    local parts={}
    for _,n in ipairs({10,15,20,25,30}) do
        local ms=startup.b373.population_milestones[tostring(n)]
        parts[#parts+1]=tostring(n).."p "..startup.b373_format_ms(ms)
    end
    return table.concat(parts," | ")
end

function startup.b373_ui_lines()
    if startup.b373.running~=true then return {"Adaptive telemetry: idle | Mode: "..tostring(startup.s.advertisingMode373 or "Smart Adaptive")} end
    local now=startup.now(); local m=startup.b373_metrics(now); local active=math.max(0,now-(tonumber(startup.b373.overall_started_ms or now) or now)); local total=startup.b373.overall_queued_ms>0 and math.max(0,now-startup.b373.overall_queued_ms) or active
    local netOverall=m.players-(tonumber(startup.b373.overall_start_players or m.players) or m.players)
    local overallRate=active>0 and (startup.b373.joins/(active/60000)) or 0
    local eta=startup.b373_eta_ms(now,m.players)
    local first=startup.b373.first_join_ms>0 and startup.b373_format_ms(startup.b373.first_join_ms-startup.b373.overall_started_ms) or "--:--"
    return {
        "Mode: "..tostring(startup.b373.mode).." | State: "..tostring(startup.b373.state).." | Region: "..tostring(startup.b373.active_region),
        "Region result: +"..tostring(m.joins).." joins / -"..tostring(m.leaves).." leaves in "..startup.b373_format_ms(m.elapsedMs).." | Net "..(m.net>=0 and "+" or "")..tostring(m.net).." | "..string.format("%.2f",m.joinRate).." joins/min",
        "Overall: +"..tostring(startup.b373.joins).." joins in "..startup.b373_format_ms(active).." active ("..startup.b373_format_ms(total).." total) | Net "..(netOverall>=0 and "+" or "")..tostring(netOverall).." | "..string.format("%.2f",overallRate).." joins/min",
        "First join: "..first.." | ETA to "..tostring(startup.s.advertisingTargetPlayers373 or 30).." players: "..startup.b373_format_ms(eta),
        "Join milestones: "..startup.b373_join_milestone_text(),
        "Lobby milestones: "..startup.b373_population_milestone_text(),
        "Region sync: "..tostring(startup.b373.pair_status).." | Best: "..(tostring(startup.b373.best_summary or "")~="" and startup.b373.best_summary or "collecting data")
    }
end

-- B373 native feature controls.
startup.add_combo("AdvertisingMode373","Advertising Mode","Smart Adaptive starts with My Region and moves only when growth is weak. Popularity Rotation starts from the Aug 25 observed popularity order. Manual synchronizes Override Region + Advertise Region to your selected Advertise Region.",{"Smart Adaptive","Popularity Rotation","Manual"},startup.s.advertisingMode373,function(selected)
    startup.s.advertisingMode373=tostring(selected or "Smart Adaptive")
    if startup.s.initialized then startup.save_config(false) end
    if startup.b373.running==true then
        startup.b373_stop_engine("mode changed",true)
        startup.b373_start_engine("mode changed")
    end
end)
startup.add_int_slider("AdvertisingTargetPlayers373","Target Players","Target lobby population for ETA and hold logic. Smart Advertising stops rotating once this population is reached.",startup.s.advertisingTargetPlayers373,5,30,1,function(v)
    startup.s.advertisingTargetPlayers373=startup.clamp_int(v,5,30); if startup.s.initialized then startup.save_config(false) end
end)
startup.add_int_slider("AdvertisingRegionTestMinutes373","Region Test Minutes","How long a region gets to prove itself before Smart Advertising may rotate it. Minimum 2 minutes avoids noisy rapid switching.",startup.s.advertisingRegionTestMinutes373,2,10,1,function(v)
    startup.s.advertisingRegionTestMinutes373=startup.clamp_int(v,2,10); if startup.s.initialized then startup.save_config(false) end
end)

-- Existing Advertise Region selector becomes a paired manual control when Manual mode is selected.
if startup.select_manual_advertise_region and startup.b373._wrapped_manual_select~=true then
    startup.b373._wrapped_manual_select=true
    startup.b373.manual_select_pre=startup.select_manual_advertise_region
    startup.select_manual_advertise_region=function(region,persist)
        local out=startup.b373.manual_select_pre(region,persist)
        if tostring(startup.s.advertisingMode373 or "") == "Manual" then
            startup.b373_apply_override_region(startup.b368_region_normalize(region))
            startup.b373.pair_status="Manual pair requested: "..tostring(startup.b368_region_normalize(region))
        end
        return out
    end
end

-- Replace B368 toggle-only flow with timed Adaptive Advertising activation.
startup.b373.run_advertise_flow_pre=startup.run_advertise_flow
startup.run_advertise_flow=function(reason)
    if startup.s.autoAdvertiseSession~=true then startup.s.lastAdvertiseStatus="Auto Advertise OFF"; return false end
    if startup.s.advertiseRunning==true then return true end
    startup.s.advertiseFlowSerial=(tonumber(startup.s.advertiseFlowSerial or 0) or 0)+1
    local serial=startup.s.advertiseFlowSerial
    startup.s.advertiseRunning=true; startup.s.advertiseSmartActive=false; startup.s.advertiseStopRequested=false; startup.s.advertiseCompletedForSession=false
    startup.s.advertiseCountdownStartedAtMs=startup.now()
    startup.s.advertiseCountdownEndsAtMs=startup.s.advertiseCountdownStartedAtMs+(tonumber(startup.s.advertiseDelayAfterSessionMs or 120000) or 120000)
    startup.b373.overall_queued_ms=startup.s.advertiseCountdownStartedAtMs
    startup.s.lastAdvertiseStatus="Adaptive Advertising preparing"
    local function job()
        startup.yield(tonumber(startup.s.advertiseDelayAfterSessionMs or 120000) or 120000)
        if serial~=startup.s.advertiseFlowSerial or startup.s.advertiseStopRequested==true or startup.s.autoAdvertiseSession~=true then return end
        local regionReady=startup.b373_start_engine(reason or "session")
        if regionReady~=true then startup.s.advertiseRunning=false; return end
        local ok=startup.set_advertise_session(true,true)
        startup.s.advertiseSmartActive=ok==true; startup.s.advertiseCountdownStartedAtMs=0; startup.s.advertiseCountdownEndsAtMs=0; startup.s.advertiseActiveSinceMs=startup.now()
        startup.s.lastAdvertiseStatus=ok and ("Adaptive Advertising ON | "..tostring(startup.b373.active_region)) or "Advertise Session toggle unavailable"
        if ok~=true then startup.b373_stop_engine("Advertise Session unavailable",false) end
        if startup.update_hud_cache then direct_call(startup.update_hud_cache,true) end
        if startup.support_log_event_quiet then startup.support_log_event_quiet("ADVERTISE_B373_START","ok="..tostring(ok).." mode="..tostring(startup.b373.mode).." region="..tostring(startup.b373.active_region).." target="..tostring(startup.s.advertisingTargetPlayers373).." testMinutes="..tostring(startup.s.advertisingRegionTestMinutes373).." reason="..tostring(reason or "session")) end
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
    return true
end

startup.update_advertise_smart_state=function(context)
    if startup.b373.running==true then startup.b373_tick() end
    if startup.s.advertiseRunning~=true or startup.s.advertiseStopRequested==true or startup.s.autoAdvertiseSession~=true or startup.s.advertiseSmartActive~=true then return end
    local f=startup.get_advertise_session_feature and startup.get_advertise_session_feature() or nil
    local state=f and startup.get_feature_bool_state and startup.get_feature_bool_state(f) or nil
    if state~=true then startup.set_advertise_session(true,true) end
end

startup.get_advertise_status_hud_line=function()
    if startup.s.showAdvertiseStatusHud~=true then return nil end
    if startup.is_gta_online_session_ready and startup.is_gta_online_session_ready()~=true then return nil end
    if startup.s.autoAdvertiseSession~=true and startup.s.advertiseRunning~=true then return nil end
    local now=startup.now(); local ends=tonumber(startup.s.advertiseCountdownEndsAtMs or 0) or 0
    if startup.s.advertiseRunning==true and startup.s.advertiseSmartActive~=true and ends>now then
        return "Smart Advertise: preparing | "..tostring(math.max(0,math.ceil((ends-now)/1000))).."s",{255,190,65}
    end
    if startup.b373.running==true then
        local m=startup.b373_metrics(now); local target=tonumber(startup.s.advertisingTargetPlayers373 or 30) or 30
        return "Smart Advertise | "..tostring(startup.b373.active_region).." | "..tostring(m.players).."/"..tostring(target).." | +"..tostring(m.joins).." joins in "..startup.b373_format_ms(m.elapsedMs).." | "..string.format("%.2f",m.joinRate).."/min", startup.b373.state=="HOLDING" and {95,255,125} or {120,205,255}
    end
    return "Smart Advertise: idle",{255,190,65}
end

-- Manual stop also closes B373 telemetry cleanly.
