startup.version="v1.0.18"
startup.console_version="v1.0.18"
startup.build_number="2026.08.27.373"
startup.build_date="2026-08-27"
startup.build_label="B373 v1.0.16 Alpha - Adaptive Advertising + Timed Region Telemetry"
startup.b373.loaded=true
if startup.log then startup.log("[Build 373] Adaptive Advertising Alpha ready: Override Region + Advertise Region sync, timed join telemetry, adaptive hold/rotate.") end
if startup.support_log_event_quiet then startup.support_log_event_quiet("BUILD373_ADAPTIVE_ADVERTISING_READY","native_override=true native_advertise_region=true timed_join_metrics=true adaptive_rotation=true advertise_toggle_spam=false") end

-- ============================================================================
-- BUILD 374: ONE-BUTTON AUTOMATED ADVERTISING BENCHMARK
-- ============================================================================
-- Unattended protocol:
--   1) 60-second warm-up with Advertise Session ON.
--   2) MANUAL REGION SWEEP: every legal modern region gets an equal fixed window.
--   3) POPULARITY ROTATION: run the real B373 algorithm for a fixed phase window.
--   4) SMART ADAPTIVE: run the real B373 algorithm for a fixed phase window.
--   5) Save CSV + human-readable summary and automatically queue Support ZIP.
-- The benchmark never intentionally selects Unknown and never toggles Advertise Session
-- between region changes. It records joins and net lobby growth separately.

startup.b374 = startup.b374 or {}
startup.b374.active = false
startup.b374.state = tostring(startup.b374.state or "IDLE")
startup.b374.duration_label = tostring(startup.s.advertisingBenchmarkDuration374 or "90 Minutes")
startup.b374.duration_plans = {
    ["60 Minutes"]  = {manualMinutes=3, popularityMinutes=15, smartMinutes=18},
    ["90 Minutes"]  = {manualMinutes=4, popularityMinutes=27, smartMinutes=27},
    ["120 Minutes"] = {manualMinutes=5, popularityMinutes=35, smartMinutes=40}
}
startup.b374.manual_regions = {"My Region","Northern Asia","Africa","East America","Europe","China","Australia","West America","Japan"}
startup.b374.warmup_ms = 60000
startup.b374.tick_ms = 1000
startup.b374.next_tick_ms = 0
startup.b374.phase = "IDLE"
startup.b374.phase_started_ms = 0
startup.b374.phase_ends_ms = 0
startup.b374.run_started_ms = 0
startup.b374.run_id = ""
startup.b374.current_segment = nil
startup.b374.records = {}
startup.b374.manual_pos = 0
startup.b374.last_status = "Idle"
startup.b374.csv_path = ""
startup.b374.summary_path = ""
startup.b374.event_log_path = ""
startup.b374.saved = nil
startup.b374.completed = false
startup.b374.auto_zip_requested = false
startup.b374.target_players = tonumber(startup.s.advertisingTargetPlayers373 or 30) or 30
startup.s.advertisingBenchmarkDuration374 = tostring(startup.s.advertisingBenchmarkDuration374 or "90 Minutes")
if startup.b374.duration_plans[startup.s.advertisingBenchmarkDuration374] == nil then startup.s.advertisingBenchmarkDuration374="90 Minutes" end

function startup.b374_now()
    return (startup.now and tonumber(startup.now())) or math.floor((os.clock() or 0)*1000)
end

function startup.b374_safe_filename(v)
    return tostring(v or "benchmark"):gsub("[^%w%._%-]","_")
end

function startup.b374_write_line(path,line,mode)
    path=tostring(path or "")
    if path=="" or not io or not io.open then return false end
    local f=io.open(path,mode or "a")
    if not f then return false end
    f:write(tostring(line or ""),"\n"); f:close(); return true
end

function startup.b374_log(event,detail)
    local line=os.date("%Y-%m-%d %H:%M:%S").." | "..tostring(event or "EVENT").." | "..tostring(detail or "")
    startup.b374_write_line(startup.b374.event_log_path,line,"a")
    if startup.support_log_event_quiet then startup.support_log_event_quiet("B374_"..tostring(event or "EVENT"),tostring(detail or "")) end
end

function startup.b374_csv_escape(v)
    local s=tostring(v==nil and "" or v)
    if s:find('[,"\n]') then s='"'..s:gsub('"','""')..'"' end
    return s
end

function startup.b374_csv_header()
    local path=tostring(startup.b374.csv_path or "")
    if path=="" then return false end
    local f=io and io.open and io.open(path,"w") or nil
    if not f then return false end
    f:write("RunId,Timestamp,Phase,Mode,Region,PlannedSeconds,ElapsedMs,StartPlayers,EndPlayers,PeakPlayers,Joins,Leaves,NetGrowth,JoinRatePerMin,NetRatePerMin,FirstJoinMs,Plus1JoinMs,Plus5JoinMs,Plus10JoinMs,Plus15JoinMs,Players10Ms,Players15Ms,Players20Ms,Players25Ms,Players30Ms,TargetPlayers,TargetReachedMs,CapacityLimited,PairStatus,Decision\n")
    f:close(); return true
end

function startup.b374_new_segment(phase,mode,region,planned_ms)
    local now=startup.b374_now()
    local players=tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0
    return {
        phase=tostring(phase or "UNKNOWN"), mode=tostring(mode or "UNKNOWN"), region=tostring(region or "AUTO"),
        plannedMs=math.max(0,tonumber(planned_ms or 0) or 0), startedMs=now, startPlayers=players,
        peakPlayers=players, joins=0, leaves=0, firstJoinMs=0, lastJoinMs=0,
        joinMilestones={}, populationMilestones={}, targetReachedMs=nil,
        pairStatus=tostring(startup.b373 and startup.b373.pair_status or ""), decision=""
    }
end

function startup.b374_capture_segment(seg,now)
    if type(seg)~="table" then return end
    now=tonumber(now or startup.b374_now()) or startup.b374_now()
    local players=tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0
    seg.peakPlayers=math.max(tonumber(seg.peakPlayers or 0) or 0,players)
    local elapsed=math.max(0,now-(tonumber(seg.startedMs or now) or now))
    for _,n in ipairs({1,5,10,15}) do
        if (tonumber(seg.joins or 0) or 0)>=n and seg.joinMilestones[tostring(n)]==nil then seg.joinMilestones[tostring(n)]=elapsed end
    end
    for _,n in ipairs({10,15,20,25,30}) do
        if players>=n and seg.populationMilestones[tostring(n)]==nil then seg.populationMilestones[tostring(n)]=elapsed end
    end
    local target=tonumber(startup.b374.target_players or startup.s.advertisingTargetPlayers373 or 30) or 30
    if players>=target and seg.targetReachedMs==nil then seg.targetReachedMs=elapsed end
end

function startup.b374_finish_segment(decision)
    local seg=startup.b374.current_segment
    if type(seg)~="table" then return nil end
    local now=startup.b374_now(); startup.b374_capture_segment(seg,now)
    local players=tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0
    local elapsed=math.max(1000,now-(tonumber(seg.startedMs or now) or now))
    local minutes=elapsed/60000
    local net=players-(tonumber(seg.startPlayers or players) or players)
    local joins=tonumber(seg.joins or 0) or 0
    local leaves=tonumber(seg.leaves or 0) or 0
    seg.endedMs=now; seg.endPlayers=players; seg.elapsedMs=elapsed; seg.net=net
    seg.joinRate=joins/minutes; seg.netRate=net/minutes
    seg.capacityLimited=(tonumber(seg.startPlayers or 0) or 0)>=math.max(1,(tonumber(startup.b374.target_players or 30) or 30)-2) or (tonumber(seg.peakPlayers or 0) or 0)>=tonumber(startup.b374.target_players or 30)
    seg.pairStatus=tostring(startup.b373 and startup.b373.pair_status or seg.pairStatus or "")
    seg.decision=tostring(decision or "COMPLETE")
    startup.b374.records[#startup.b374.records+1]=seg

    local vals={
        startup.b374.run_id,os.date("%Y-%m-%d %H:%M:%S"),seg.phase,seg.mode,seg.region,math.floor((tonumber(seg.plannedMs or 0) or 0)/1000),elapsed,
        seg.startPlayers,seg.endPlayers,seg.peakPlayers,joins,leaves,net,string.format("%.4f",seg.joinRate),string.format("%.4f",seg.netRate),
        seg.firstJoinMs>0 and (seg.firstJoinMs-seg.startedMs) or "",
        seg.joinMilestones["1"] or "",seg.joinMilestones["5"] or "",seg.joinMilestones["10"] or "",seg.joinMilestones["15"] or "",
        seg.populationMilestones["10"] or "",seg.populationMilestones["15"] or "",seg.populationMilestones["20"] or "",seg.populationMilestones["25"] or "",seg.populationMilestones["30"] or "",
        startup.b374.target_players,seg.targetReachedMs or "",seg.capacityLimited and "YES" or "NO",seg.pairStatus,seg.decision
    }
    for i,v in ipairs(vals) do vals[i]=startup.b374_csv_escape(v) end
    local f=io and io.open and io.open(tostring(startup.b374.csv_path or ""),"a") or nil
    if f then f:write(table.concat(vals,","),"\n"); f:close() end
    startup.b374_log("SEGMENT_END",seg.phase.." | "..seg.mode.." | "..seg.region.." | +"..joins.." joins -"..leaves.." leaves | net="..(net>=0 and "+" or "")..net.." | elapsed="..startup.b373_format_ms(elapsed).." | rate="..string.format("%.2f",seg.joinRate).."/min | decision="..seg.decision)
    startup.b374.current_segment=nil
    return seg
end

function startup.b374_on_join(playerId)
    if startup.b374.active~=true then return end
    if startup.b373_is_local_player and startup.b373_is_local_player(playerId) then return end
    local seg=startup.b374.current_segment
    if type(seg)~="table" then return end
    local now=startup.b374_now(); seg.joins=(tonumber(seg.joins or 0) or 0)+1
    if tonumber(seg.firstJoinMs or 0)<=0 then seg.firstJoinMs=now end
    seg.lastJoinMs=now; startup.b374_capture_segment(seg,now)
end

function startup.b374_on_left(playerId)
    if startup.b374.active~=true then return end
    if startup.b373_is_local_player and startup.b373_is_local_player(playerId) then return end
    local seg=startup.b374.current_segment
    if type(seg)~="table" then return end
    seg.leaves=(tonumber(seg.leaves or 0) or 0)+1
    startup.b374_capture_segment(seg,startup.b374_now())
end

function startup.b374_save_user_state()
    local overrideLabel=startup.b373_read_override_region and startup.b373_read_override_region() or "My Region"
    local advertiseLabel=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "My Region"
    local advFeature=startup.get_advertise_session_feature and startup.get_advertise_session_feature() or nil
    local advState=advFeature and startup.get_feature_bool_state and startup.get_feature_bool_state(advFeature) or nil
    startup.b374.saved={
        mode=tostring(startup.s.advertisingMode373 or "Smart Adaptive"),
        testMinutes=tonumber(startup.s.advertisingRegionTestMinutes373 or 3) or 3,
        target=tonumber(startup.s.advertisingTargetPlayers373 or 30) or 30,
        manual=tostring(startup.s.advertiseRegionManualSelection or "My Region"),
        auto=startup.s.autoAdvertiseSession==true,
        nativeAdvertise=advState==true,
        override=tostring(overrideLabel or "My Region"),
        advertise=tostring(advertiseLabel or "My Region"),
        advertiseRunning=startup.s.advertiseRunning==true,
        advertiseSmartActive=startup.s.advertiseSmartActive==true
    }
end

function startup.b374_restore_user_state()
    local s=startup.b374.saved or {}
    direct_call(startup.b373_stop_engine,"B374 restore",false)
    startup.s.advertisingMode373=tostring(s.mode or "Smart Adaptive")
    startup.s.advertisingRegionTestMinutes373=startup.clamp_int(s.testMinutes or 3,2,10)
    startup.s.advertisingTargetPlayers373=startup.clamp_int(s.target or 30,5,30)
    startup.s.advertiseRegionManualSelection=tostring(s.manual or "My Region")
    startup.s.autoAdvertiseSession=s.auto==true
    if tostring(s.override or "")~="" and tostring(s.override)~="Unknown" and startup.b373_apply_override_region then startup.b373_apply_override_region(s.override) end
    if tostring(s.advertise or "")~="" and tostring(s.advertise)~="Unknown" and startup.b368_apply_advertise_region then startup.b368_apply_advertise_region(s.advertise,false,"B374 restore") end
    if startup.set_advertise_session then direct_call(startup.set_advertise_session,s.nativeAdvertise==true,true) end
    startup.s.advertiseRunning=s.advertiseRunning==true
    startup.s.advertiseSmartActive=s.advertiseSmartActive==true
    startup.s.advertiseStopRequested=false
    if startup.save_config then direct_call(startup.save_config,false) end
end

function startup.b374_begin_manual_region()
    startup.b374.manual_pos=(tonumber(startup.b374.manual_pos or 0) or 0)+1
    if startup.b374.manual_pos>#startup.b374.manual_regions then return false end
    local region=startup.b374.manual_regions[startup.b374.manual_pos]
    local plan=startup.b374.duration_plans[startup.s.advertisingBenchmarkDuration374] or startup.b374.duration_plans["90 Minutes"]
    local ms=(tonumber(plan.manualMinutes or 4) or 4)*60000
    startup.s.advertisingMode373="Manual"
    direct_call(startup.b373_stop_engine,"B374 manual sweep",false)
    local ok,why=startup.b373_sync_region_pair(region,"B374 manual benchmark")
    if ok~=true then
        startup.b374_log("REGION_SYNC_FAIL",region.." | "..tostring(why or ""))
    end
    startup.b374.current_segment=startup.b374_new_segment("MANUAL_SWEEP","Manual",region,ms)
    startup.b374.phase="MANUAL_SWEEP"; startup.b374.phase_started_ms=startup.b374_now(); startup.b374.phase_ends_ms=startup.b374.phase_started_ms+ms
    startup.b374.state="TESTING "..region
    startup.b374.last_status="Manual region "..tostring(startup.b374.manual_pos).."/"..tostring(#startup.b374.manual_regions)..": "..region
    startup.b374_log("SEGMENT_START",startup.b374.last_status.." | planned="..startup.b373_format_ms(ms).." | pair="..tostring(startup.b373.pair_status))
    return true
end

function startup.b374_begin_algorithm_phase(mode,label,minutes)
    direct_call(startup.b373_stop_engine,"B374 phase change",false)
    startup.s.advertisingMode373=tostring(mode)
    startup.s.advertisingRegionTestMinutes373=3
    local ok=startup.b373_start_engine("B374 "..tostring(label))
    if ok~=true then startup.b374_log("ENGINE_START_FAIL",tostring(label)); return false end
    local ms=(tonumber(minutes or 1) or 1)*60000
    startup.b374.current_segment=startup.b374_new_segment(tostring(label),tostring(mode),"AUTO",ms)
    startup.b374.phase=tostring(label); startup.b374.phase_started_ms=startup.b374_now(); startup.b374.phase_ends_ms=startup.b374.phase_started_ms+ms
    startup.b374.state="TESTING "..tostring(label)
    startup.b374.last_status=tostring(label).." running for "..tostring(minutes).." minutes"
    startup.b374_log("PHASE_START",startup.b374.last_status)
    return true
end

function startup.b374_start_popularity()
    local plan=startup.b374.duration_plans[startup.s.advertisingBenchmarkDuration374] or startup.b374.duration_plans["90 Minutes"]
    return startup.b374_begin_algorithm_phase("Popularity Rotation","POPULARITY_ROTATION",plan.popularityMinutes)
end

function startup.b374_start_smart()
    local plan=startup.b374.duration_plans[startup.s.advertisingBenchmarkDuration374] or startup.b374.duration_plans["90 Minutes"]
    return startup.b374_begin_algorithm_phase("Smart Adaptive","SMART_ADAPTIVE",plan.smartMinutes)
end

function startup.b374_format_milestone(ms)
    return ms and startup.b373_format_ms(ms) or "--:--"
end

function startup.b374_write_summary(reason)
    local f=io and io.open and io.open(tostring(startup.b374.summary_path or ""),"w") or nil
    if not f then return false end
    local function w(x) f:write(tostring(x or ""),"\n") end
    local ended=startup.b374_now(); local elapsed=math.max(0,ended-(tonumber(startup.b374.run_started_ms or ended) or ended))
    w("STARTUP ADVERTISING BENCHMARK — BUILD 375")
    w("========================================")
    w("Run ID: "..tostring(startup.b374.run_id))
    w("Startup build: "..tostring(startup.build_number))
    w("Duration preset: "..tostring(startup.s.advertisingBenchmarkDuration374))
    w("Started: "..tostring(startup.b374.started_clock or ""))
    w("Finished: "..os.date("%Y-%m-%d %H:%M:%S"))
    w("Wall time: "..startup.b373_format_ms(elapsed))
    w("Reason: "..tostring(reason or "Completed"))
    w("Target players: "..tostring(startup.b374.target_players or 30))
    if startup.get_local_nat_type then w("NAT observed: "..tostring(startup.get_local_nat_type() or "Unknown")) end
    if Cherax and Cherax.GetEdition then local ok,v=direct_call(Cherax.GetEdition); if ok then w("Cherax edition: "..tostring(v or "Unknown")) end end
    w("")
    w("MANUAL REGION SWEEP")
    w("-------------------")
    local manual={}
    for _,r in ipairs(startup.b374.records or {}) do if r.phase=="MANUAL_SWEEP" then manual[#manual+1]=r end end
    table.sort(manual,function(a,b) if (a.joinRate or 0)==(b.joinRate or 0) then return (a.netRate or 0)>(b.netRate or 0) end return (a.joinRate or 0)>(b.joinRate or 0) end)
    for i,r in ipairs(manual) do
        w(string.format("%d. %s | +%d joins / -%d leaves in %s | net %+d | %.2f joins/min | %.2f net/min | first join %s | +5 %s | +10 %s | 20p %s | 25p %s | 30p %s%s",
            i,tostring(r.region),tonumber(r.joins or 0),tonumber(r.leaves or 0),startup.b373_format_ms(r.elapsedMs),tonumber(r.net or 0),tonumber(r.joinRate or 0),tonumber(r.netRate or 0),
            startup.b374_format_milestone(r.firstJoinMs>0 and (r.firstJoinMs-r.startedMs) or nil),startup.b374_format_milestone(r.joinMilestones and r.joinMilestones["5"]),startup.b374_format_milestone(r.joinMilestones and r.joinMilestones["10"]),
            startup.b374_format_milestone(r.populationMilestones and r.populationMilestones["20"]),startup.b374_format_milestone(r.populationMilestones and r.populationMilestones["25"]),startup.b374_format_milestone(r.populationMilestones and r.populationMilestones["30"]),
            r.capacityLimited and " | CAPACITY-LIMITED" or ""))
    end
    w("")
    w("AUTOMATIC MODE PHASES")
    w("---------------------")
    for _,r in ipairs(startup.b374.records or {}) do
        if r.phase=="POPULARITY_ROTATION" or r.phase=="SMART_ADAPTIVE" then
            w(string.format("%s | +%d joins / -%d leaves in %s | start %d -> end %d | peak %d | net %+d | %.2f joins/min | first join %s | target %s%s",
                r.phase,tonumber(r.joins or 0),tonumber(r.leaves or 0),startup.b373_format_ms(r.elapsedMs),tonumber(r.startPlayers or 0),tonumber(r.endPlayers or 0),tonumber(r.peakPlayers or 0),tonumber(r.net or 0),tonumber(r.joinRate or 0),
                startup.b374_format_milestone(r.firstJoinMs>0 and (r.firstJoinMs-r.startedMs) or nil),startup.b374_format_milestone(r.targetReachedMs),r.capacityLimited and " | CAPACITY-LIMITED" or ""))
        end
    end
    w("")
    w("INTERPRETATION NOTES")
    w("--------------------")
    w("- Joins count raw player join events; Net Growth is end population minus start population.")
    w("- A capacity-limited segment started near the target or reached the target, so its join rate may be artificially suppressed by lack of lobby headroom.")
    w("- Manual regions are the cleanest direct region comparison because each gets an equal fixed window.")
    w("- Popularity Rotation and Smart Adaptive are strategy-level tests; B373 region-level CSV rows inside the same Support ZIP explain which regions each strategy selected/held.")
    w("- The benchmark does not intentionally select Unknown and does not pulse Advertise Session OFF/ON between region changes.")
    w("")
    w("FILES")
    w("-----")
    w("CSV: "..tostring(startup.b374.csv_path))
    w("Event log: "..tostring(startup.b374.event_log_path))
    w("B373 region telemetry: "..tostring(startup.b373 and startup.b373.csv_path or ""))
    f:close(); return true
end

function startup.b374_finish(reason,aborted)
    if startup.b374.active~=true and startup.b374.completed==true then return true end
    if startup.b374.current_segment then startup.b374_finish_segment((aborted==true and "ABORTED:" or "COMPLETE:")..tostring(reason or "finished")) end
    direct_call(startup.b373_stop_engine,"B374 finish",true)
    startup.b374.active=false; startup.b374.completed=aborted~=true; startup.b374.phase="IDLE"; startup.b374.state=aborted==true and "ABORTED" or "COMPLETE"
    startup.b374.last_status=tostring(reason or (aborted==true and "Aborted" or "Completed"))
    startup.b374_write_summary(reason)
    startup.b374_log(aborted==true and "BENCHMARK_ABORT" or "BENCHMARK_COMPLETE","records="..tostring(#(startup.b374.records or {})).." | reason="..tostring(reason or ""))
    startup.b374_restore_user_state()
    if aborted~=true then
        startup.b374.auto_zip_requested=true
        if startup.queue_support_zip then pcall(startup.queue_support_zip) end
        if startup.toast then startup.toast("Advertising benchmark complete. Support ZIP is being created automatically.",9000) end
    else
        if startup.toast then startup.toast("Advertising benchmark stopped. Partial CSV/summary were saved.",6000) end
    end
    return true
end

function startup.b374_start()
    if startup.b374.active==true then if startup.toast then startup.toast("Advertising benchmark is already running.",3000) end; return false end
    if startup.is_gta_online_session_ready and startup.is_gta_online_session_ready()~=true then
        if startup.toast then startup.toast("Enter a stable GTA Online session before starting the advertising benchmark.",5000) end
        return false
    end
    startup.b374_save_user_state()
    direct_call(startup.b373_stop_engine,"B374 start",false)
    startup.s.advertiseFlowSerial=(tonumber(startup.s.advertiseFlowSerial or 0) or 0)+1
    startup.s.autoAdvertiseSession=true; startup.s.advertiseRunning=true; startup.s.advertiseStopRequested=false; startup.s.advertiseSmartActive=true
    if startup.set_advertise_session then direct_call(startup.set_advertise_session,true,true) end
    startup.b374.active=true; startup.b374.completed=false; startup.b374.records={}; startup.b374.manual_pos=0; startup.b374.next_tick_ms=0
    startup.b374.run_started_ms=startup.b374_now(); startup.b374.started_clock=os.date("%Y-%m-%d %H:%M:%S")
    startup.b374.run_id="B374_"..os.date("%Y%m%d_%H%M%S")
    startup.b374.target_players=tonumber(startup.s.advertisingTargetPlayers373 or 30) or 30
    local base=tostring(startup.diagnostics_dir or startup.save_dir or "")
    startup.ensure_save_dir()
    startup.b374.csv_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b374.run_id)..".csv"
    startup.b374.summary_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b374.run_id)..".txt"
    startup.b374.event_log_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b374.run_id)..".log"
    startup.s.b374LastCsvPath=startup.b374.csv_path; startup.s.b374LastSummaryPath=startup.b374.summary_path; startup.s.b374LastEventLogPath=startup.b374.event_log_path
    startup.b374_csv_header(); startup.b374_write_line(startup.b374.event_log_path,"", "w")
    startup.b374.phase="WARMUP"; startup.b374.state="WARMUP"; startup.b374.phase_started_ms=startup.b374_now(); startup.b374.phase_ends_ms=startup.b374.phase_started_ms+startup.b374.warmup_ms
    startup.b374.last_status="60-second warm-up before unattended test"
    startup.b374_log("BENCHMARK_START","duration="..tostring(startup.s.advertisingBenchmarkDuration374).." | target="..tostring(startup.b374.target_players).." | players="..tostring(startup.get_session_player_count()))
    if startup.toast then startup.toast("Advertising benchmark started. You can leave the PC unattended.",7000) end
    return true
end

function startup.b374_tick()
    if startup.b374.active~=true then return end
    local now=startup.b374_now(); if now<(tonumber(startup.b374.next_tick_ms or 0) or 0) then return end
    startup.b374.next_tick_ms=now+startup.b374.tick_ms
    if startup.b374.current_segment then startup.b374_capture_segment(startup.b374.current_segment,now) end
    -- Keep native advertising alive throughout the benchmark without pulsing it.
    local af=startup.get_advertise_session_feature and startup.get_advertise_session_feature() or nil
    local av=af and startup.get_feature_bool_state and startup.get_feature_bool_state(af) or nil
    if av~=true and startup.set_advertise_session then direct_call(startup.set_advertise_session,true,true) end
    if now<(tonumber(startup.b374.phase_ends_ms or 0) or 0) then return end

    if startup.b374.phase=="WARMUP" then
        startup.b374_begin_manual_region(); return
    end
    if startup.b374.phase=="MANUAL_SWEEP" then
        startup.b374_finish_segment("TIMED_WINDOW_COMPLETE")
        if startup.b374.manual_pos<#startup.b374.manual_regions then startup.b374_begin_manual_region() else startup.b374_start_popularity() end
        return
    end
    if startup.b374.phase=="POPULARITY_ROTATION" then
        startup.b374_finish_segment("PHASE_TIME_COMPLETE"); direct_call(startup.b373_stop_engine,"B374 popularity complete",true); startup.b374_start_smart(); return
    end
    if startup.b374.phase=="SMART_ADAPTIVE" then
        startup.b374_finish_segment("PHASE_TIME_COMPLETE"); startup.b374_finish("Full unattended benchmark completed",false); return
    end
end

function startup.b374_ui_lines()
    if startup.b374.active~=true then
        local last=(tostring(startup.s.b374LastSummaryPath or "")~="") and " | Last report saved" or ""
        return {"Automated benchmark: idle | Preset: "..tostring(startup.s.advertisingBenchmarkDuration374 or "90 Minutes")..last}
    end
    local now=startup.b374_now(); local remain=math.max(0,(tonumber(startup.b374.phase_ends_ms or now) or now)-now)
    local elapsed=math.max(0,now-(tonumber(startup.b374.run_started_ms or now) or now))
    local seg=startup.b374.current_segment
    local detail=""
    if type(seg)=="table" then detail=" | +"..tostring(seg.joins or 0).." joins / -"..tostring(seg.leaves or 0).." leaves | players "..tostring(startup.get_session_player_count()) end
    return {
        "AUTOMATED BENCHMARK RUNNING | "..tostring(startup.b374.phase).." | remaining "..startup.b373_format_ms(remain),
        "Total elapsed "..startup.b373_format_ms(elapsed)..detail,
        "You may leave the PC unattended. Results + Support ZIP are generated automatically at completion."
    }
end

-- Add benchmark artifacts to the normal Startup Support ZIP automatically.
startup.b374_collect_support_pre=startup.collect_support_files
function startup.collect_support_files()
    local found=startup.b374_collect_support_pre and startup.b374_collect_support_pre() or {}
    local seen={}
    for _,e in ipairs(found) do seen[tostring(e.path or ""):gsub("/","\\"):lower()]=true end
    local function add(path,name)
        path=tostring(path or ""); if path=="" or not startup.support_file_exists(path) then return end
        local key=path:gsub("/","\\"):lower(); if seen[key] then return end; seen[key]=true
        found[#found+1]={path=path,name="Startup/Diagnostics/Advertising/"..tostring(name or startup.support_basename(path))}
    end
    add(startup.b374.csv_path,"B374_Advertising_Benchmark.csv")
    add(startup.b374.summary_path,"B374_Advertising_Benchmark_Summary.txt")
    add(startup.b374.event_log_path,"B374_Advertising_Benchmark.log")
    if startup.b373 and startup.b373.csv_path then add(startup.b373.csv_path,"B373_Adaptive_Region_Telemetry.csv") end
    table.sort(found,function(a,b) return tostring(a.name):lower()<tostring(b.name):lower() end)
    return found
end

-- Feature controls. One START button runs the full suite unattended.
