    if startup.b374.active==true then return end
    startup.s.advertisingBenchmarkDuration374=tostring(selected or "90 Minutes")
    if startup.save_config then direct_call(startup.save_config,false) end
end)
startup.add_button("RunAdvertisingBenchmark374","RUN FULL ADVERTISING BENCHMARK","One-button unattended test. Automatically tests every legal region in Manual mode, then Popularity Rotation, then Smart Adaptive; records time-to-join and population milestones and creates a Support ZIP at the end.",function() startup.b374_start() end)
startup.add_button("StopAdvertisingBenchmark374","STOP ADVERTISING BENCHMARK","Stops the unattended benchmark and saves partial CSV/summary results without discarding collected data.",function() if startup.b374.active==true then startup.b374_finish("Stopped by user",true) end end)

if EventMgr and eLuaEvent and eLuaEvent.ON_PLAYER_JOIN then EventMgr.RegisterHandler(eLuaEvent.ON_PLAYER_JOIN,function(playerId) if startup and startup.b374_on_join then pcall(startup.b374_on_join,playerId) end end) end
if EventMgr and eLuaEvent and eLuaEvent.ON_PLAYER_LEFT then EventMgr.RegisterHandler(eLuaEvent.ON_PLAYER_LEFT,function(playerId) if startup and startup.b374_on_left then pcall(startup.b374_on_left,playerId) end end) end
if Script and Script.RegisterLooped and startup.b374.loop_installed~=true then
    startup.b374.loop_installed=true
    Script.RegisterLooped(function() if startup and startup.b374_tick then pcall(startup.b374_tick) end end)
end

startup.version="v1.0.18"
startup.console_version="v1.0.18"
startup.build_number="2026.08.27.374"
startup.build_date="2026-08-27"
startup.build_label="B374 v1.0.16 Alpha - One-Button Automated Advertising Benchmark"
startup.b374.loaded=true
if startup.log then startup.log("[Build 374] Automated Advertising Benchmark ready: Manual region sweep + Popularity Rotation + Smart Adaptive + timed milestones + automatic Support ZIP.") end
if startup.support_log_event_quiet then startup.support_log_event_quiet("BUILD374_ADVERTISING_BENCHMARK_READY","one_button=true durations=60,90,120 manual_regions=9 popularity=true smart=true auto_support_zip=true") end

-- ============================================================================
-- BUILD 375: CRASH-SAFE AUTOMATED ADVERTISING BENCHMARK
-- ============================================================================
-- Safety changes over Build 374:
--   * Advertise Session is NEVER polled/forced once per second.
--   * Native region callbacks are serialized: Override Region -> settle ->
--     Advertise Region -> settle -> readback verification.
--   * Benchmark timers pause during GTA Online session transitions and resume
--     only after the session has remained continuously ready for a settle window.
--   * Join/leave telemetry is suspended while paused or while a region pair is
--     actively being changed, so transition time is not credited to a region.
--   * A small checkpoint file is refreshed during the run so partial progress
--     survives a GTA/Cherax crash and can be included in Support diagnostics.
-- ============================================================================

startup.b375 = startup.b375 or {}
startup.b375.session_settle_ms = 10000
startup.b375.native_settle_ms = 4000
startup.b375.native_retry_ms = 5000
startup.b375.max_native_attempts = 2
startup.b375.checkpoint_interval_ms = 5000
startup.b375.next_checkpoint_ms = 0
startup.b375.ready_since_ms = 0
startup.b375.session_stable = false
startup.b375.paused = false
startup.b375.pause_started_ms = 0
startup.b375.total_paused_ms = 0
startup.b375.pause_count = 0
startup.b375.region_job = nil
startup.b375.pending_advertise_restore = nil
startup.b375.advertise_initialized = false
startup.b375.last_advertise_check_ms = 0
startup.b375.last_native_action = "None"
startup.b375.last_native_action_ms = 0
startup.b375.checkpoint_path = tostring(startup.b375.checkpoint_path or "")
startup.b375.native_apply_override = startup.b375.native_apply_override or startup.b373_apply_override_region
startup.b375.native_apply_advertise = startup.b375.native_apply_advertise or startup.b368_apply_advertise_region
startup.b375.b373_tick_pre = startup.b375.b373_tick_pre or startup.b373_tick
startup.b375.b373_on_join_pre = startup.b375.b373_on_join_pre or startup.b373_on_join
startup.b375.b373_on_left_pre = startup.b375.b373_on_left_pre or startup.b373_on_left

function startup.b375_now()
    return (startup.now and tonumber(startup.now())) or math.floor((os.clock() or 0)*1000)
end

function startup.b375_raw_session_ready()
    if not startup.is_gta_online_session_ready then return false end
    local ok,v=direct_call(startup.is_gta_online_session_ready)
    return ok and v==true
end

function startup.b375_update_session_stability(now)
    now=tonumber(now or startup.b375_now()) or startup.b375_now()
    if startup.b375_raw_session_ready()~=true then
        startup.b375.ready_since_ms=0
        startup.b375.session_stable=false
        return false
    end
    if (tonumber(startup.b375.ready_since_ms or 0) or 0)<=0 then
        startup.b375.ready_since_ms=now
    end
    startup.b375.session_stable=(now-(tonumber(startup.b375.ready_since_ms or now) or now))>=startup.b375.session_settle_ms
    return startup.b375.session_stable==true
end

function startup.b375_shift_timers_after_pause(delta)
    delta=math.max(0,tonumber(delta or 0) or 0)
    if delta<=0 then return end
    if (tonumber(startup.b374.phase_started_ms or 0) or 0)>0 then startup.b374.phase_started_ms=startup.b374.phase_started_ms+delta end
    if (tonumber(startup.b374.phase_ends_ms or 0) or 0)>0 then startup.b374.phase_ends_ms=startup.b374.phase_ends_ms+delta end
    local seg=startup.b374.current_segment
    if type(seg)=="table" then
        if (tonumber(seg.startedMs or 0) or 0)>0 then seg.startedMs=seg.startedMs+delta end
        if (tonumber(seg.firstJoinMs or 0) or 0)>0 then seg.firstJoinMs=seg.firstJoinMs+delta end
        if (tonumber(seg.lastJoinMs or 0) or 0)>0 then seg.lastJoinMs=seg.lastJoinMs+delta end
    end
    if startup.b373 then
        for _,key in ipairs({"overall_started_ms","region_started_ms","first_join_ms","last_join_ms"}) do
            if (tonumber(startup.b373[key] or 0) or 0)>0 then startup.b373[key]=startup.b373[key]+delta end
        end
        if (tonumber(startup.b373.next_tick_ms or 0) or 0)>0 then startup.b373.next_tick_ms=startup.b373.next_tick_ms+delta end
    end
end

function startup.b375_pause_for_session(now,reason)
    now=tonumber(now or startup.b375_now()) or startup.b375_now()
    if startup.b375.paused==true then return end
    startup.b375.paused=true
    startup.b375.pause_started_ms=now
    startup.b375.pause_count=(tonumber(startup.b375.pause_count or 0) or 0)+1
    startup.b374.last_status="PAUSED — waiting for stable GTA Online session"
    if startup.b374_log then startup.b374_log("SESSION_PAUSE",tostring(reason or "session not stable")) end
end

function startup.b375_resume_from_session(now)
    now=tonumber(now or startup.b375_now()) or startup.b375_now()
    if startup.b375.paused~=true then return end
    local delta=math.max(0,now-(tonumber(startup.b375.pause_started_ms or now) or now))
    startup.b375.total_paused_ms=(tonumber(startup.b375.total_paused_ms or 0) or 0)+delta
    startup.b375.paused=false
    startup.b375.pause_started_ms=0
    startup.b375_shift_timers_after_pause(delta)
    startup.b374.last_status="RESUMED — GTA Online session stable"
    if startup.b374_log then startup.b374_log("SESSION_RESUME","paused="..tostring(startup.b373_format_ms and startup.b373_format_ms(delta) or delta)) end
end

function startup.b375_checkpoint_write(reason)
    local path=tostring(startup.b375.checkpoint_path or "")
    if path=="" or not io or not io.open then return false end
    local f=io.open(path,"w")
    if not f then return false end
    local now=startup.b375_now()
    local seg=startup.b374.current_segment
    local lines={
        "STARTUP ADVERTISING BENCHMARK CHECKPOINT — BUILD 375",
        "RunId="..tostring(startup.b374.run_id or ""),
        "Timestamp="..os.date("%Y-%m-%d %H:%M:%S"),
        "Reason="..tostring(reason or "periodic"),
        "Active="..tostring(startup.b374.active==true),
        "Phase="..tostring(startup.b374.phase or "IDLE"),
        "State="..tostring(startup.b374.state or ""),
        "LastStatus="..tostring(startup.b374.last_status or ""),
        "ManualPosition="..tostring(startup.b374.manual_pos or 0).."/"..tostring(#(startup.b374.manual_regions or {})),
        "CurrentRegion="..tostring(type(seg)=="table" and seg.region or (startup.b373 and startup.b373.active_region) or ""),
        "CurrentMode="..tostring(type(seg)=="table" and seg.mode or (startup.s and startup.s.advertisingMode373) or ""),
        "Players="..tostring(startup.get_session_player_count and startup.get_session_player_count() or "?"),
        "SegmentJoins="..tostring(type(seg)=="table" and seg.joins or 0),
        "SegmentLeaves="..tostring(type(seg)=="table" and seg.leaves or 0),
        "RecordsSaved="..tostring(#(startup.b374.records or {})),
        "SessionStable="..tostring(startup.b375.session_stable==true),
        "Paused="..tostring(startup.b375.paused==true),
        "PauseCount="..tostring(startup.b375.pause_count or 0),
        "TotalPausedMs="..tostring(startup.b375.total_paused_ms or 0),
        "PairStatus="..tostring(startup.b373 and startup.b373.pair_status or ""),
        "NativeJob="..tostring(startup.b375.region_job and (startup.b375.region_job.region..":"..startup.b375.region_job.step) or "None"),
        "LastNativeAction="..tostring(startup.b375.last_native_action or "None"),
        "LastNativeActionMs="..tostring(startup.b375.last_native_action_ms or 0),
        "NowMs="..tostring(now)
    }
    f:write(table.concat(lines,"\n"),"\n")
    f:close()
    return true
end

function startup.b375_native_advertise_state()
    local f=startup.get_advertise_session_feature and startup.get_advertise_session_feature() or nil
    if not f or not startup.get_feature_bool_state then return nil end
    local ok,v=direct_call(startup.get_feature_bool_state,f)
    if not ok then return nil end
    if v==true then return true end
    if v==false then return false end
    return nil
end

function startup.b375_ensure_advertise_once(reason)
    local now=startup.b375_now()
    if startup.b375.session_stable~=true then return false,"SESSION_NOT_STABLE" end
    local state=startup.b375_native_advertise_state()
    startup.b375.last_advertise_check_ms=now
    if state==true then
        startup.b375.advertise_initialized=true
        if startup.b374_log then startup.b374_log("ADVERTISE_CHECK","already ON | "..tostring(reason or "")) end
        return true,"ALREADY_ON"
    end
    if state==nil then
        -- Safety rule: UNKNOWN is not interpreted as OFF. No native callback is fired.
        startup.b375.advertise_initialized=true
        if startup.b374_log then startup.b374_log("ADVERTISE_CHECK","state UNKNOWN — no write | "..tostring(reason or "")) end
        return true,"UNKNOWN_NO_WRITE"
    end
    local ok=false
    if startup.set_advertise_session then
        local callOk,result=direct_call(startup.set_advertise_session,true,true)
        ok=callOk and result~=false
    end
    startup.b375.last_native_action="Advertise Session ON (single repair)"
    startup.b375.last_native_action_ms=now
    startup.b375.advertise_initialized=true
    if startup.b374_log then startup.b374_log("ADVERTISE_REPAIR",tostring(ok).." | explicit OFF -> ON | "..tostring(reason or "")) end
    return ok,ok and "REPAIRED_ON" or "REPAIR_FAILED"
end

function startup.b375_queue_advertise_restore(value)
    if value~=true and value~=false then return false end
    startup.b375.pending_advertise_restore={value=value,notBefore=startup.b375_now()+startup.b375.native_settle_ms}
    return true
end

function startup.b375_queue_region_pair(region,reason,callback)
    region=startup.b368_region_normalize and startup.b368_region_normalize(region) or tostring(region or "My Region")
    if region=="Unknown" then return false,"INVALID_REGION" end
    if startup.b375.region_job then
        if tostring(startup.b375.region_job.region)==region then return true,"ALREADY_QUEUED" end
        return false,"REGION_SYNC_BUSY"
    end
    startup.b375.region_job={
        region=region, reason=tostring(reason or "Build 375 serialized sync"), callback=callback,
        step="WAIT_STABLE", nextMs=startup.b375_now(), overrideAttempts=0, advertiseAttempts=0,
        startedMs=startup.b375_now()
    }
    startup.b373.pair_status="SYNCING | Target="..region
    if startup.b374_log and startup.b374.active==true then startup.b374_log("REGION_SYNC_QUEUE",region.." | "..tostring(reason or "")) end
    return true,"QUEUED"
end

function startup.b375_complete_region_job(success,detail)
    local job=startup.b375.region_job
    if not job then return end
    local cb=job.callback
    local region=job.region
    startup.b375.region_job=nil
    if startup.b374_log and startup.b374.active==true then startup.b374_log(success and "REGION_SYNC_OK" or "REGION_SYNC_FAIL",region.." | "..tostring(detail or "")) end
    if type(cb)=="function" then pcall(cb,success==true,tostring(detail or ""),region) end
end

function startup.b375_process_region_job(now)
    local job=startup.b375.region_job
    if not job then return end
    now=tonumber(now or startup.b375_now()) or startup.b375_now()
    if startup.b375.session_stable~=true or startup.b375.paused==true then return end
    if now<(tonumber(job.nextMs or 0) or 0) then return end

    if job.step=="WAIT_STABLE" then
        job.step="OVERRIDE"
        job.nextMs=now
        return
    end

    if job.step=="OVERRIDE" then
        job.overrideAttempts=(tonumber(job.overrideAttempts or 0) or 0)+1
        local ok,detail=false,"Override setter unavailable"
        if startup.b375.native_apply_override then ok,detail=startup.b375.native_apply_override(job.region) end
        startup.b375.last_native_action="Override Region -> "..job.region
        startup.b375.last_native_action_ms=now
        if ok==true then
            job.step="ADVERTISE"
            job.nextMs=now+startup.b375.native_settle_ms
        elseif job.overrideAttempts<startup.b375.max_native_attempts then
            job.nextMs=now+startup.b375.native_retry_ms
        else
            startup.b375_complete_region_job(false,"Override failed: "..tostring(detail))
        end
        return
    end

    if job.step=="ADVERTISE" then
        job.advertiseAttempts=(tonumber(job.advertiseAttempts or 0) or 0)+1
        local ok=false
        if startup.b375.native_apply_advertise then ok=startup.b375.native_apply_advertise(job.region,false,"Build 375 serialized: "..job.reason) end
        startup.b375.last_native_action="Advertise Region -> "..job.region
        startup.b375.last_native_action_ms=now
        if ok==true then
            job.step="VERIFY"
            job.nextMs=now+startup.b375.native_settle_ms
        elseif job.advertiseAttempts<startup.b375.max_native_attempts then
            job.nextMs=now+startup.b375.native_retry_ms
        else
            startup.b375_complete_region_job(false,"Advertise Region failed")
        end
        return
    end

    if job.step=="VERIFY" then
        local overrideLabel=startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
        local advertiseLabel=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
        local verified=tostring(overrideLabel)==job.region and tostring(advertiseLabel)==job.region
        startup.b373.pair_status=(verified and "SYNCED" or "MISMATCH").." | Override="..tostring(overrideLabel).." | Advertise="..tostring(advertiseLabel)
        if startup.h and startup.h.AdvertiseManualRegionSelection and startup.set_feature_list_string_silently then
            direct_call(startup.set_feature_list_string_silently,startup.h.AdvertiseManualRegionSelection,job.region)
        end
        startup.b375_complete_region_job(verified,startup.b373.pair_status)
        return
    end
end

function startup.b375_process_advertise_restore(now)
    local j=startup.b375.pending_advertise_restore
    if not j then return end
    now=tonumber(now or startup.b375_now()) or startup.b375_now()
    if startup.b375.session_stable~=true or startup.b375.paused==true or startup.b375.region_job then return end
    if now<(tonumber(j.notBefore or 0) or 0) then return end
    local current=startup.b375_native_advertise_state()
    if current==nil or current==j.value then
        startup.b375.pending_advertise_restore=nil
        return
    end
    if startup.set_advertise_session then direct_call(startup.set_advertise_session,j.value,true) end
    startup.b375.last_native_action="Advertise Session restore -> "..tostring(j.value)
    startup.b375.last_native_action_ms=now
    startup.b375.pending_advertise_restore=nil
end

-- Replace Build 373's immediate two-callback region sync with the serialized B375 worker.
function startup.b373_sync_region_pair(region,reason)
    return startup.b375_queue_region_pair(region,reason,nil)
end

-- Begin B373 region timing only after BOTH native controls have settled and verified.
function startup.b373_begin_region(region,reason)
    region=tostring(region or "My Region")
    if startup.b375.region_job then return false end
    startup.b373.state="SYNCING"
    startup.b373.last_decision="Synchronizing "..region
    startup.s.lastAdvertiseStatus="Synchronizing region controls: "..region
    local ok,why=startup.b375_queue_region_pair(region,reason,function(success,detail,target)
        if success~=true then
            startup.b373.state="REGION SYNC FAILED"
            startup.b373.last_decision=tostring(detail or "Region sync failed")
            startup.s.lastAdvertiseStatus="Adaptive Advertising stopped: "..startup.b373.last_decision
            direct_call(startup.b373_stop_engine,"Build 375 region sync failure",false)
            if startup.b374 and startup.b374.active==true then direct_call(startup.b374_finish,"Region sync failure: "..tostring(target).." | "..tostring(detail),true) end
            return
        end
        local now=startup.b375_now()
        local players=tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0
        startup.b373.active_region=tostring(target or region)
        startup.b373.region_started_ms=now
        startup.b373.region_start_players=players
        startup.b373.region_start_joins=startup.b373.joins
        startup.b373.region_start_leaves=startup.b373.leaves
        startup.b373.regions_tested=(tonumber(startup.b373.regions_tested or 0) or 0)+1
        startup.b373.state="TESTING"
        startup.b373.last_decision="Testing "..startup.b373.active_region
        startup.s.lastAdvertiseStatus="Testing "..startup.b373.active_region.." | "..tostring(players).." players"
    end)
    return ok==true,why
end

-- Do not let adaptive logic run or count events through an unstable session/native transition.
function startup.b373_tick()
    if startup.b375 and startup.b374 and startup.b374.active==true then
        if startup.b375.paused==true or startup.b375.session_stable~=true or startup.b375.region_job or tostring(startup.b373.state)=="SYNCING" then return end
    end
    if startup.b375.b373_tick_pre then return startup.b375.b373_tick_pre() end
end

function startup.b373_on_join(playerId)
    if startup.b375 and startup.b374 and startup.b374.active==true and (startup.b375.paused==true or startup.b375.region_job~=nil) then return end
    if startup.b375.b373_on_join_pre then return startup.b375.b373_on_join_pre(playerId) end
end

function startup.b373_on_left(playerId)
    if startup.b375 and startup.b374 and startup.b374.active==true and (startup.b375.paused==true or startup.b375.region_job~=nil) then return end
    if startup.b375.b373_on_left_pre then return startup.b375.b373_on_left_pre(playerId) end
end

-- Preserve nil/unknown native Advertise Session state instead of collapsing it to false.
function startup.b374_save_user_state()
    local overrideLabel=startup.b373_read_override_region and startup.b373_read_override_region() or "My Region"
    local advertiseLabel=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "My Region"
    local advState=startup.b375_native_advertise_state()
    startup.b374.saved={
        mode=tostring(startup.s.advertisingMode373 or "Smart Adaptive"),
        testMinutes=tonumber(startup.s.advertisingRegionTestMinutes373 or 3) or 3,
        target=tonumber(startup.s.advertisingTargetPlayers373 or 30) or 30,
        manual=tostring(startup.s.advertiseRegionManualSelection or "My Region"),
        auto=startup.s.autoAdvertiseSession==true,
        nativeAdvertise=advState,
        override=tostring(overrideLabel or "My Region"),
        advertise=tostring(advertiseLabel or "My Region"),
        advertiseRunning=startup.s.advertiseRunning==true,
        advertiseSmartActive=startup.s.advertiseSmartActive==true
    }
end

-- Restore settings immediately, but native callbacks are queued and serialized.
function startup.b374_restore_user_state()
    local s=startup.b374.saved or {}
    direct_call(startup.b373_stop_engine,"B375 restore",false)
    startup.s.advertisingMode373=tostring(s.mode or "Smart Adaptive")
    startup.s.advertisingRegionTestMinutes373=startup.clamp_int(s.testMinutes or 3,2,10)
    startup.s.advertisingTargetPlayers373=startup.clamp_int(s.target or 30,5,30)
    startup.s.advertiseRegionManualSelection=tostring(s.manual or "My Region")
    startup.s.autoAdvertiseSession=s.auto==true
    startup.s.advertiseRunning=s.advertiseRunning==true
    startup.s.advertiseSmartActive=s.advertiseSmartActive==true
    startup.s.advertiseStopRequested=false
    if startup.save_config then direct_call(startup.save_config,false) end
    local restoreRegion=tostring(s.override or "")
    if restoreRegion=="" or restoreRegion=="Unknown" then restoreRegion=tostring(s.advertise or "") end
    if restoreRegion~="" and restoreRegion~="Unknown" then startup.b375_queue_region_pair(restoreRegion,"B375 safe restore",nil) end
    startup.b375_queue_advertise_restore(s.nativeAdvertise)
end

-- Manual region windows do not begin until serialized readback verification completes.
function startup.b374_begin_manual_region()
    startup.b374.manual_pos=(tonumber(startup.b374.manual_pos or 0) or 0)+1
    if startup.b374.manual_pos>#startup.b374.manual_regions then return false end
    local region=startup.b374.manual_regions[startup.b374.manual_pos]
    local plan=startup.b374.duration_plans[startup.s.advertisingBenchmarkDuration374] or startup.b374.duration_plans["90 Minutes"]
    local ms=(tonumber(plan.manualMinutes or 4) or 4)*60000
    startup.s.advertisingMode373="Manual"
    direct_call(startup.b373_stop_engine,"B375 manual sweep",false)
    startup.b374.current_segment=nil
    startup.b374.phase="REGION_TRANSITION"
    startup.b374.phase_started_ms=startup.b375_now()
    startup.b374.phase_ends_ms=0
    startup.b374.state="SYNCING "..region
    startup.b374.last_status="Safe region transition "..tostring(startup.b374.manual_pos).."/"..tostring(#startup.b374.manual_regions)..": "..region
    local ok,why=startup.b375_queue_region_pair(region,"B375 manual benchmark",function(success,detail,target)
        if success~=true then
            startup.b374.last_status="Region sync failed: "..tostring(target).." | "..tostring(detail)
            direct_call(startup.b374_finish,startup.b374.last_status,true)
            return
        end
        startup.b374.current_segment=startup.b374_new_segment("MANUAL_SWEEP","Manual",target,ms)
        startup.b374.phase="MANUAL_SWEEP"
        startup.b374.phase_started_ms=startup.b375_now()
        startup.b374.phase_ends_ms=startup.b374.phase_started_ms+ms
        startup.b374.state="TESTING "..target
        startup.b374.last_status="Manual region "..tostring(startup.b374.manual_pos).."/"..tostring(#startup.b374.manual_regions)..": "..target
        startup.b374_log("SEGMENT_START",startup.b374.last_status.." | planned="..startup.b373_format_ms(ms).." | pair="..tostring(startup.b373.pair_status))
        startup.b375_checkpoint_write("manual region verified")
    end)
    if ok~=true then
        startup.b374.last_status="Unable to queue region sync: "..tostring(region).." | "..tostring(why)
        direct_call(startup.b374_finish,startup.b374.last_status,true)
        return false
    end
    return true
end

function startup.b374_begin_algorithm_phase(mode,label,minutes)
    if startup.b375.region_job then return false end
    startup.b375_ensure_advertise_once("phase start "..tostring(label))
    direct_call(startup.b373_stop_engine,"B375 phase change",false)
    startup.s.advertisingMode373=tostring(mode)
    startup.s.advertisingRegionTestMinutes373=3
    local ms=(tonumber(minutes or 1) or 1)*60000
    startup.b374.current_segment=startup.b374_new_segment(tostring(label),tostring(mode),"AUTO",ms)
    startup.b374.phase=tostring(label)
    startup.b374.phase_started_ms=startup.b375_now()
    startup.b374.phase_ends_ms=startup.b374.phase_started_ms+ms
    startup.b374.state="TESTING "..tostring(label)
    startup.b374.last_status=tostring(label).." running for "..tostring(minutes).." minutes"
    local ok=startup.b373_start_engine("B375 "..tostring(label))
    if ok~=true then
        startup.b374_log("ENGINE_START_FAIL",tostring(label))
        direct_call(startup.b374_finish,"Adaptive engine start failed: "..tostring(label),true)
        return false
    end
    startup.b374_log("PHASE_START",startup.b374.last_status)
    return true
end

function startup.b374_start()
    if startup.b374.active==true then if startup.toast then startup.toast("Advertising benchmark is already running.",3000) end; return false end
    if startup.b375_raw_session_ready()~=true then
        if startup.toast then startup.toast("Enter GTA Online before starting the crash-safe advertising benchmark.",5000) end
        return false
    end
    startup.b374_save_user_state()
    direct_call(startup.b373_stop_engine,"B375 start",false)
    startup.s.advertiseFlowSerial=(tonumber(startup.s.advertiseFlowSerial or 0) or 0)+1
    startup.s.autoAdvertiseSession=true
    startup.s.advertiseRunning=true
    startup.s.advertiseStopRequested=false
    startup.s.advertiseSmartActive=false -- B375: suppress legacy Advertise Session watchdogs during benchmark
    startup.b374.active=true
    startup.b374.completed=false
    startup.b374.records={}
    startup.b374.manual_pos=0
    startup.b374.next_tick_ms=0
    startup.b375.region_job=nil
    startup.b375.pending_advertise_restore=nil
    startup.b375.advertise_initialized=false
    startup.b375.ready_since_ms=0
    startup.b375.session_stable=false
    startup.b375.paused=false
    startup.b375.pause_started_ms=0
    startup.b375.total_paused_ms=0
    startup.b375.pause_count=0
    startup.b375.next_checkpoint_ms=0
    startup.b374.run_started_ms=startup.b375_now()
    startup.b374.started_clock=os.date("%Y-%m-%d %H:%M:%S")
    startup.b374.run_id="B375_"..os.date("%Y%m%d_%H%M%S")
    startup.b374.target_players=tonumber(startup.s.advertisingTargetPlayers373 or 30) or 30
    local base=tostring(startup.diagnostics_dir or startup.save_dir or "")
    startup.ensure_save_dir()
    startup.b374.csv_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b374.run_id)..".csv"
    startup.b374.summary_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b374.run_id)..".txt"
    startup.b374.event_log_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b374.run_id)..".log"
    startup.b375.checkpoint_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b374.run_id).."_CHECKPOINT.txt"
    startup.s.b374LastCsvPath=startup.b374.csv_path
    startup.s.b374LastSummaryPath=startup.b374.summary_path
    startup.s.b374LastEventLogPath=startup.b374.event_log_path
    startup.s.b375LastCheckpointPath=startup.b375.checkpoint_path
    startup.b374_csv_header()
    startup.b374_write_line(startup.b374.event_log_path,"","w")
    startup.b374.phase="WARMUP"
    startup.b374.state="WARMUP"
    startup.b374.phase_started_ms=startup.b375_now()
    startup.b374.phase_ends_ms=startup.b374.phase_started_ms+startup.b374.warmup_ms
    startup.b374.last_status="Crash-safe warm-up: waiting for 10 seconds of continuous GTA Online stability"
    startup.b374_log("BENCHMARK_START","BUILD375 | duration="..tostring(startup.s.advertisingBenchmarkDuration374).." | target="..tostring(startup.b374.target_players).." | players="..tostring(startup.get_session_player_count()))
    startup.b375_checkpoint_write("benchmark start")
    if startup.toast then startup.toast("Crash-safe advertising benchmark started. Session transitions will pause the timer automatically.",8000) end
    return true
end

function startup.b374_finish(reason,aborted)
    if startup.b374.active~=true and startup.b374.completed==true then return true end
    if startup.b374.current_segment then startup.b374_finish_segment((aborted==true and "ABORTED:" or "COMPLETE:")..tostring(reason or "finished")) end
    direct_call(startup.b373_stop_engine,"B375 finish",true)
    startup.b374.active=false
    startup.b374.completed=aborted~=true
    startup.b374.phase="IDLE"
    startup.b374.state=aborted==true and "ABORTED" or "COMPLETE"
    startup.b374.last_status=tostring(reason or (aborted==true and "Aborted" or "Completed"))
    startup.b375_checkpoint_write(aborted==true and "benchmark aborted" or "benchmark complete")
    startup.b374_write_summary(reason)
    startup.b374_log(aborted==true and "BENCHMARK_ABORT" or "BENCHMARK_COMPLETE","BUILD375 | records="..tostring(#(startup.b374.records or {})).." | pauses="..tostring(startup.b375.pause_count or 0).." | pausedMs="..tostring(startup.b375.total_paused_ms or 0).." | reason="..tostring(reason or ""))
    startup.b374_restore_user_state()
    if aborted~=true then
        startup.b374.auto_zip_requested=true
        if startup.queue_support_zip then pcall(startup.queue_support_zip) end
        if startup.toast then startup.toast("Advertising benchmark complete. Support ZIP is being created automatically.",9000) end
    else
        if startup.toast then startup.toast("Advertising benchmark stopped safely. Partial CSV/summary/checkpoint were saved.",7000) end
    end
    return true
end

-- The B374 loop remains installed, but calls this replacement function dynamically.
function startup.b374_tick()
    local now=startup.b375_now()
    local stable=startup.b375_update_session_stability(now)

    -- Native restore jobs may finish after the benchmark itself has ended.
    if startup.b374.active~=true then
        if stable then
            startup.b375_process_region_job(now)
            startup.b375_process_advertise_restore(now)
        end
        return
    end

    if stable~=true then
        startup.b375_pause_for_session(now,"GTA Online session not continuously stable")
        if now>=(tonumber(startup.b375.next_checkpoint_ms or 0) or 0) then
            startup.b375.next_checkpoint_ms=now+startup.b375.checkpoint_interval_ms
            startup.b375_checkpoint_write("session paused")
        end
        return
    end

    if startup.b375.paused==true then startup.b375_resume_from_session(now) end

    startup.b375_process_region_job(now)
    startup.b375_process_advertise_restore(now)

    if now>=(tonumber(startup.b375.next_checkpoint_ms or 0) or 0) then
        startup.b375.next_checkpoint_ms=now+startup.b375.checkpoint_interval_ms
        startup.b375_checkpoint_write("periodic")
    end

    if now<(tonumber(startup.b374.next_tick_ms or 0) or 0) then return end
    startup.b374.next_tick_ms=now+startup.b374.tick_ms

    if startup.b375.region_job then return end
    if startup.b374.current_segment then startup.b374_capture_segment(startup.b374.current_segment,now) end

    -- Advertise Session is checked only once after the stable warm-up, never once per second.
    if startup.b375.advertise_initialized~=true then
        local advOk,advWhy=startup.b375_ensure_advertise_once("initial stable warm-up")
        if advOk~=true and tostring(advWhy)=="REPAIR_FAILED" then
            direct_call(startup.b374_finish,"Advertise Session could not be enabled safely",true)
            return
        end
    end

    if now<(tonumber(startup.b374.phase_ends_ms or 0) or 0) then return end

    if startup.b374.phase=="WARMUP" then
        startup.b374_begin_manual_region()
        return
    end
    if startup.b374.phase=="REGION_TRANSITION" then return end
    if startup.b374.phase=="MANUAL_SWEEP" then
        startup.b374_finish_segment("TIMED_WINDOW_COMPLETE")
        if startup.b374.manual_pos<#startup.b374.manual_regions then startup.b374_begin_manual_region() else startup.b374_start_popularity() end
        return
    end
    if startup.b374.phase=="POPULARITY_ROTATION" then
        startup.b374_finish_segment("PHASE_TIME_COMPLETE")
        direct_call(startup.b373_stop_engine,"B375 popularity complete",true)
        startup.b374_start_smart()
        return
    end
    if startup.b374.phase=="SMART_ADAPTIVE" then
        startup.b374_finish_segment("PHASE_TIME_COMPLETE")
        startup.b374_finish("Full crash-safe unattended benchmark completed",false)
        return
    end
end

-- Benchmark-level join/leave counters also ignore transition/pause ambiguity.
function startup.b374_on_join(playerId)
    if startup.b374.active~=true or startup.b375.paused==true or startup.b375.region_job then return end
    if startup.b373_is_local_player and startup.b373_is_local_player(playerId) then return end
    local seg=startup.b374.current_segment
    if type(seg)~="table" then return end
    local now=startup.b375_now()
    seg.joins=(tonumber(seg.joins or 0) or 0)+1
    if tonumber(seg.firstJoinMs or 0)<=0 then seg.firstJoinMs=now end
    seg.lastJoinMs=now
    startup.b374_capture_segment(seg,now)
end

function startup.b374_on_left(playerId)
    if startup.b374.active~=true or startup.b375.paused==true or startup.b375.region_job then return end
    if startup.b373_is_local_player and startup.b373_is_local_player(playerId) then return end
    local seg=startup.b374.current_segment
    if type(seg)~="table" then return end
    seg.leaves=(tonumber(seg.leaves or 0) or 0)+1
    startup.b374_capture_segment(seg,startup.b375_now())
end

-- Add the B375 crash checkpoint to generated Support ZIPs.
startup.b375_collect_support_pre=startup.collect_support_files
function startup.collect_support_files()
    local found=startup.b375_collect_support_pre and startup.b375_collect_support_pre() or {}
    for _,e in ipairs(found) do
        if type(e)=="table" and e.name then e.name=tostring(e.name):gsub("B374_Advertising_Benchmark","B375_Advertising_Benchmark") end
    end
    local path=tostring(startup.b375.checkpoint_path or startup.s.b375LastCheckpointPath or "")
    if path~="" and startup.support_file_exists and startup.support_file_exists(path) then
        local seen=false
        for _,e in ipairs(found) do if tostring(e.path or ""):gsub("/","\\"):lower()==path:gsub("/","\\"):lower() then seen=true break end end
        if not seen then found[#found+1]={path=path,name="Startup/Diagnostics/Advertising/B375_Advertising_Benchmark_CHECKPOINT.txt"} end
    end
    table.sort(found,function(a,b) return tostring(a.name):lower()<tostring(b.name):lower() end)
    return found
end

function startup.b374_ui_lines()
    if startup.b374.active~=true then
        local last=(tostring(startup.s.b374LastSummaryPath or "")~="") and " | Last report saved" or ""
        return {"Crash-safe automated benchmark: idle | Preset: "..tostring(startup.s.advertisingBenchmarkDuration374 or "90 Minutes")..last}
    end
    local now=startup.b375_now()
    if startup.b375.paused==true or startup.b375.session_stable~=true then
        local wait=math.max(0,startup.b375.session_settle_ms-(now-(tonumber(startup.b375.ready_since_ms or now) or now)))
        return {
            "BENCHMARK PAUSED — waiting for stable GTA Online session",
            "Resume safety settle: "..startup.b373_format_ms(wait).." | pause #"..tostring(startup.b375.pause_count or 0),
            "No region or Advertise Session callbacks are fired while paused."
        }
    end
    if startup.b375.region_job then
        return {
            "SAFE REGION TRANSITION | "..tostring(startup.b375.region_job.region).." | "..tostring(startup.b375.region_job.step),
            "Native callbacks are serialized with "..tostring(math.floor(startup.b375.native_settle_ms/1000)).."s settle gaps.",
            "Checkpoint: active"
        }
    end
    local remain=math.max(0,(tonumber(startup.b374.phase_ends_ms or now) or now)-now)
    local activeElapsed=math.max(0,now-(tonumber(startup.b374.run_started_ms or now) or now)-(tonumber(startup.b375.total_paused_ms or 0) or 0))
    local seg=startup.b374.current_segment
    local detail=""
    if type(seg)=="table" then detail=" | +"..tostring(seg.joins or 0).." joins / -"..tostring(seg.leaves or 0).." leaves | players "..tostring(startup.get_session_player_count()) end
    return {
        "CRASH-SAFE BENCHMARK | "..tostring(startup.b374.phase).." | remaining "..startup.b373_format_ms(remain),
        "Active test time "..startup.b373_format_ms(activeElapsed)..detail,
        "Session stable | serialized native callbacks | checkpoint every "..tostring(math.floor(startup.b375.checkpoint_interval_ms/1000)).."s"
    }
end

