-- ============================================================================
-- BUILD 376: SINGLE-OWNER ADVERTISING BENCHMARK
-- ============================================================================
-- Crash isolation from B375 evidence:
--   * All 9 manual regions completed with serialized native callbacks.
--   * Crash occurred after entering POPULARITY_ROTATION and starting B373 engine.
-- B376 keeps ONE benchmark controller as the sole owner of region transitions.
-- It never starts the B373 adaptive worker during an unattended benchmark.
-- Popularity and Smart are reproduced as benchmark-controller strategies using
-- the same safe serialized Override Region -> Advertise Region -> verify path.
-- ============================================================================

startup.b376 = startup.b376 or {}
startup.b376.benchmark_owns_modes = false
startup.b376.strategy_window_ms = 180000
startup.b376.popularity_order = {"China","Europe","Africa","East America","West America"}
startup.b376.smart_fallback_order = {"My Region","China","Europe","Africa","East America","West America","Australia","Japan","Northern Asia"}
startup.b376.strategy = startup.b376.strategy or {
    active=false, phase="", mode="", order={}, pos=0, phase_deadline_ms=0,
    segment_end_ms=0, transition_started_ms=0, last_region="", hold_count=0,
    best_region="", best_score=-999999
}

startup.b376.run_advertise_flow_pre = startup.b376.run_advertise_flow_pre or startup.run_advertise_flow
startup.run_advertise_flow = function(reason)
    if startup.b374 and startup.b374.active==true and startup.b376 and startup.b376.benchmark_owns_modes==true then
        -- Benchmark owns advertising. Do not queue a second delayed B373 worker.
        startup.s.advertiseRunning=true
        startup.s.advertiseSmartActive=false
        startup.s.advertiseStopRequested=false
        return true
    end
    if startup.b376.run_advertise_flow_pre then return startup.b376.run_advertise_flow_pre(reason) end
    return false
end

startup.b376.update_advertise_smart_state_pre = startup.b376.update_advertise_smart_state_pre or startup.update_advertise_smart_state
startup.update_advertise_smart_state = function(context)
    if startup.b374 and startup.b374.active==true and startup.b376 and startup.b376.benchmark_owns_modes==true then
        return
    end
    if startup.b376.update_advertise_smart_state_pre then return startup.b376.update_advertise_smart_state_pre(context) end
end

startup.b376.b373_start_engine_pre = startup.b376.b373_start_engine_pre or startup.b373_start_engine
startup.b373_start_engine = function(reason)
    if startup.b374 and startup.b374.active==true and startup.b376 and startup.b376.benchmark_owns_modes==true then
        if startup.b374_log then startup.b374_log("SECOND_ENGINE_BLOCKED",tostring(reason or "benchmark ownership")) end
        return false,"B376_BENCHMARK_OWNS_MODE"
    end
    if startup.b376.b373_start_engine_pre then return startup.b376.b373_start_engine_pre(reason) end
    return false,"NO_ENGINE"
end

function startup.b376_segment_score(seg)
    if type(seg)~="table" then return -999999 end
    local net=tonumber(seg.net or 0) or 0
    local joins=tonumber(seg.joins or 0) or 0
    local leaves=tonumber(seg.leaves or 0) or 0
    local joinRate=tonumber(seg.joinRate or 0) or 0
    return (net*4.0)+(joins*1.5)-(leaves*1.25)+(joinRate*2.0)
end

function startup.b376_build_smart_order()
    local ranked={}
    for _,r in ipairs(startup.b374.records or {}) do
        if type(r)=="table" and tostring(r.phase)=="MANUAL_SWEEP" and tostring(r.region)~="Unknown" then
            ranked[#ranked+1]={region=tostring(r.region),score=startup.b376_segment_score(r)}
        end
    end
    table.sort(ranked,function(a,b) return (tonumber(a.score or -999999) or -999999)>(tonumber(b.score or -999999) or -999999) end)
    local out,seen={},{}
    for _,x in ipairs(ranked) do
        if x.region~="" and not seen[x.region] then out[#out+1]=x.region; seen[x.region]=true end
    end
    for _,region in ipairs(startup.b376.smart_fallback_order) do
        if not seen[region] then out[#out+1]=region; seen[region]=true end
    end
    return out
end

function startup.b376_strategy_remaining(now)
    now=tonumber(now or startup.b375_now()) or startup.b375_now()
    return math.max(0,(tonumber(startup.b376.strategy.phase_deadline_ms or now) or now)-now)
end

function startup.b376_start_same_region_segment(region)
    local now=startup.b375_now()
    local remain=startup.b376_strategy_remaining(now)
    if remain<=0 then return false end
    local planned=math.min(tonumber(startup.b376.strategy_window_ms or 180000) or 180000,remain)
    startup.b374.current_segment=startup.b374_new_segment(startup.b376.strategy.phase,startup.b376.strategy.mode,tostring(region),planned)
    startup.b376.strategy.segment_end_ms=now+planned
    startup.b374.state="TESTING "..tostring(startup.b376.strategy.phase).." | "..tostring(region)
    startup.b374.last_status=tostring(startup.b376.strategy.mode).." | "..tostring(region).." | safe controller-owned window "..tostring(startup.b373_format_ms(planned))
    startup.b374_log("STRATEGY_SEGMENT_START",startup.b374.last_status.." | pair="..tostring(startup.b373 and startup.b373.pair_status or ""))
    startup.b375_checkpoint_write("strategy segment start")
    return true
end

function startup.b376_queue_strategy_region(region,reason)
    if startup.b375.region_job then return false,"REGION_JOB_BUSY" end
    region=tostring(region or "My Region")
    if region=="Unknown" then return false,"UNKNOWN_BLOCKED" end
    startup.b374.current_segment=nil
    startup.b376.strategy.transition_started_ms=startup.b375_now()
    startup.b374.state="SYNCING "..region
    startup.b374.last_status="Single-owner safe transition -> "..region
    local ok,why=startup.b375_queue_region_pair(region,"B376 "..tostring(reason or "strategy"),function(success,detail,target)
        if success~=true then
            startup.b374.last_status="B376 region sync failed: "..tostring(target).." | "..tostring(detail)
            direct_call(startup.b374_finish,startup.b374.last_status,true)
            return
        end
        local now=startup.b375_now()
        local spent=math.max(0,now-(tonumber(startup.b376.strategy.transition_started_ms or now) or now))
        -- Transition time is excluded from measured strategy time.
        startup.b376.strategy.phase_deadline_ms=(tonumber(startup.b376.strategy.phase_deadline_ms or now) or now)+spent
        startup.b376.strategy.last_region=tostring(target or region)
        startup.b376_start_same_region_segment(startup.b376.strategy.last_region)
    end)
    return ok==true,why
end

function startup.b376_begin_strategy(phase,mode,minutes,order)
    direct_call(startup.b373_stop_engine,"B376 single-owner strategy",false)
    startup.s.advertisingMode373=tostring(mode)
    startup.s.advertiseRunning=true
    startup.s.advertiseSmartActive=false
    startup.s.advertiseStopRequested=false
    startup.b376.strategy={
        active=true,phase=tostring(phase),mode=tostring(mode),order=order or {},pos=0,
        phase_deadline_ms=startup.b375_now()+((tonumber(minutes or 1) or 1)*60000),
        segment_end_ms=0,transition_started_ms=0,last_region="",hold_count=0,
        best_region="",best_score=-999999
    }
    startup.b374.phase=tostring(phase)
    startup.b374.phase_started_ms=startup.b375_now()
    startup.b374.phase_ends_ms=startup.b376.strategy.phase_deadline_ms
    startup.b374.state="STARTING "..tostring(phase)
    startup.b374.last_status=tostring(phase).." single-owner controller for "..tostring(minutes).." minutes"
    startup.b374_log("PHASE_START",startup.b374.last_status.." | B373 engine=BLOCKED")
    if #(startup.b376.strategy.order or {})<=0 then return false end
    startup.b376.strategy.pos=1
    return startup.b376_queue_strategy_region(startup.b376.strategy.order[1],phase.." start")
end

function startup.b374_start_popularity()
    local plan=startup.b374.duration_plans[startup.s.advertisingBenchmarkDuration374] or startup.b374.duration_plans["90 Minutes"]
    return startup.b376_begin_strategy("POPULARITY_ROTATION","Popularity Rotation",plan.popularityMinutes,startup.b376.popularity_order)
end

function startup.b374_start_smart()
    local plan=startup.b374.duration_plans[startup.s.advertisingBenchmarkDuration374] or startup.b374.duration_plans["90 Minutes"]
    local order=startup.b376_build_smart_order()
    if startup.b374_log then startup.b374_log("SMART_ORDER","learned="..table.concat(order," > ")) end
    return startup.b376_begin_strategy("SMART_ADAPTIVE","Smart Adaptive",plan.smartMinutes,order)
end

function startup.b376_finish_popularity_segment()
    local seg=startup.b374_finish_segment("POPULARITY_WINDOW_COMPLETE")
    if startup.b376_strategy_remaining(startup.b375_now())<=0 then
        startup.b376.strategy.active=false
        startup.b374_start_smart()
        return
    end
    startup.b376.strategy.pos=(tonumber(startup.b376.strategy.pos or 0) or 0)+1
    if startup.b376.strategy.pos>#startup.b376.strategy.order then startup.b376.strategy.pos=1 end
    startup.b376_queue_strategy_region(startup.b376.strategy.order[startup.b376.strategy.pos],"popularity next window")
end

function startup.b376_finish_smart_segment()
    local seg=startup.b374_finish_segment("SMART_WINDOW_COMPLETE")
    local now=startup.b375_now()
    if startup.b376_strategy_remaining(now)<=0 then
        startup.b376.strategy.active=false
        startup.b374_finish("Full single-owner unattended benchmark completed",false)
        return
    end
    if type(seg)~="table" then
        startup.b374_finish("Smart segment missing",true)
        return
    end
    local score=startup.b376_segment_score(seg)
    if score>(tonumber(startup.b376.strategy.best_score or -999999) or -999999) then
        startup.b376.strategy.best_score=score
        startup.b376.strategy.best_region=tostring(seg.region or "")
    end
    local joins=tonumber(seg.joins or 0) or 0
    local net=tonumber(seg.net or 0) or 0
    local rate=tonumber(seg.joinRate or 0) or 0
    local good=(seg.capacityLimited==true) or (net>=3) or (rate>=1.5 and net>=0)
    if good then
        startup.b376.strategy.hold_count=(tonumber(startup.b376.strategy.hold_count or 0) or 0)+1
        startup.b374_log("SMART_DECISION","HOLD "..tostring(seg.region).." | joins="..joins.." net="..net.." rate="..string.format("%.2f",rate).." score="..string.format("%.2f",score))
        -- HOLD means no native callback at all; start another measured window on the same region.
        startup.b376_start_same_region_segment(tostring(seg.region))
        return
    end
    startup.b376.strategy.hold_count=0
    startup.b374_log("SMART_DECISION","ROTATE from "..tostring(seg.region).." | joins="..joins.." net="..net.." rate="..string.format("%.2f",rate).." score="..string.format("%.2f",score))
    startup.b376.strategy.pos=(tonumber(startup.b376.strategy.pos or 0) or 0)+1
    if startup.b376.strategy.pos>#startup.b376.strategy.order then startup.b376.strategy.pos=1 end
    startup.b376_queue_strategy_region(startup.b376.strategy.order[startup.b376.strategy.pos],"smart underperform rotate")
end

-- B376 owns the entire benchmark state machine. No B373 worker is started in automatic phases.
function startup.b374_tick()
    local now=startup.b375_now()
    local stable=startup.b375_update_session_stability(now)

    if startup.b374.active~=true then
        if stable then startup.b375_process_region_job(now); startup.b375_process_advertise_restore(now) end
        return
    end

    -- Reassert logical ownership only; no native Advertise callback here.
    startup.s.advertiseRunning=true
    startup.s.advertiseSmartActive=false
    startup.s.advertiseStopRequested=false

    if stable~=true then
        startup.b375_pause_for_session(now,"GTA Online session not continuously stable")
        if now>=(tonumber(startup.b375.next_checkpoint_ms or 0) or 0) then
            startup.b375.next_checkpoint_ms=now+startup.b375.checkpoint_interval_ms
            startup.b375_checkpoint_write("session paused")
        end
        return
    end
    if startup.b375.paused==true then startup.b375_resume_from_session(now) end

    startup.b375_process_region_job(now)
    startup.b375_process_advertise_restore(now)

    if now>=(tonumber(startup.b375.next_checkpoint_ms or 0) or 0) then
        startup.b375.next_checkpoint_ms=now+startup.b375.checkpoint_interval_ms
        startup.b375_checkpoint_write("periodic")
    end
    if now<(tonumber(startup.b374.next_tick_ms or 0) or 0) then return end
    startup.b374.next_tick_ms=now+startup.b374.tick_ms
    if startup.b375.region_job then return end
    if startup.b374.current_segment then startup.b374_capture_segment(startup.b374.current_segment,now) end

    if startup.b375.advertise_initialized~=true then
        local advOk,advWhy=startup.b375_ensure_advertise_once("initial stable warm-up")
        if advOk~=true and tostring(advWhy)=="REPAIR_FAILED" then direct_call(startup.b374_finish,"Advertise Session could not be enabled safely",true); return end
    end

    if startup.b374.phase=="WARMUP" then
        if now>=(tonumber(startup.b374.phase_ends_ms or 0) or 0) then startup.b374_begin_manual_region() end
        return
    end
    if startup.b374.phase=="REGION_TRANSITION" then return end
    if startup.b374.phase=="MANUAL_SWEEP" then
        if now<(tonumber(startup.b374.phase_ends_ms or 0) or 0) then return end
        startup.b374_finish_segment("TIMED_WINDOW_COMPLETE")
        if startup.b374.manual_pos<#startup.b374.manual_regions then startup.b374_begin_manual_region() else startup.b374_start_popularity() end
        return
    end
    if startup.b374.phase=="POPULARITY_ROTATION" then
        if startup.b374.current_segment and now>=(tonumber(startup.b376.strategy.segment_end_ms or 0) or 0) then startup.b376_finish_popularity_segment() end
        return
    end
    if startup.b374.phase=="SMART_ADAPTIVE" then
        if startup.b374.current_segment and now>=(tonumber(startup.b376.strategy.segment_end_ms or 0) or 0) then startup.b376_finish_smart_segment() end
        return
    end
end

-- B376 start: identical safety envelope, but invalidates delayed jobs and records B376 paths.
function startup.b374_start()
    if startup.b374.active==true then if startup.toast then startup.toast("Advertising benchmark is already running.",3000) end; return false end
    if startup.b375_raw_session_ready()~=true then if startup.toast then startup.toast("Enter GTA Online before starting the single-owner benchmark.",5000) end; return false end
    startup.b374_save_user_state()
    direct_call(startup.b373_stop_engine,"B376 start",false)
    startup.s.advertiseFlowSerial=(tonumber(startup.s.advertiseFlowSerial or 0) or 0)+1
    startup.s.autoAdvertiseSession=true
    startup.s.advertiseRunning=true
    startup.s.advertiseStopRequested=false
    startup.s.advertiseSmartActive=false
    startup.b376.benchmark_owns_modes=true
    startup.b376.strategy={active=false,phase="",mode="",order={},pos=0,phase_deadline_ms=0,segment_end_ms=0,transition_started_ms=0,last_region="",hold_count=0,best_region="",best_score=-999999}
    startup.b374.active=true; startup.b374.completed=false; startup.b374.records={}; startup.b374.manual_pos=0; startup.b374.next_tick_ms=0
    startup.b375.region_job=nil; startup.b375.pending_advertise_restore=nil; startup.b375.advertise_initialized=false
    startup.b375.ready_since_ms=0; startup.b375.session_stable=false; startup.b375.paused=false; startup.b375.pause_started_ms=0; startup.b375.total_paused_ms=0; startup.b375.pause_count=0; startup.b375.next_checkpoint_ms=0
    startup.b374.run_started_ms=startup.b375_now(); startup.b374.started_clock=os.date("%Y-%m-%d %H:%M:%S")
    startup.b374.run_id="B376_"..os.date("%Y%m%d_%H%M%S")
    startup.b374.target_players=tonumber(startup.s.advertisingTargetPlayers373 or 30) or 30
    local base=tostring(startup.diagnostics_dir or startup.save_dir or "")
    startup.ensure_save_dir()
    startup.b374.csv_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b374.run_id)..".csv"
    startup.b374.summary_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b374.run_id)..".txt"
    startup.b374.event_log_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b374.run_id)..".log"
    startup.b375.checkpoint_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b374.run_id).."_CHECKPOINT.txt"
    startup.s.b374LastCsvPath=startup.b374.csv_path; startup.s.b374LastSummaryPath=startup.b374.summary_path; startup.s.b374LastEventLogPath=startup.b374.event_log_path; startup.s.b375LastCheckpointPath=startup.b375.checkpoint_path
    startup.b374_csv_header(); startup.b374_write_line(startup.b374.event_log_path,"","w")
    startup.b374.phase="WARMUP"; startup.b374.state="WARMUP"; startup.b374.phase_started_ms=startup.b375_now(); startup.b374.phase_ends_ms=startup.b374.phase_started_ms+startup.b374.warmup_ms
    startup.b374.last_status="B376 single-owner warm-up: waiting for stable GTA Online"
    startup.b374_log("BENCHMARK_START","BUILD376 | duration="..tostring(startup.s.advertisingBenchmarkDuration374).." | target="..tostring(startup.b374.target_players).." | players="..tostring(startup.get_session_player_count()))
    startup.b375_checkpoint_write("benchmark start")
    if startup.toast then startup.toast("Single-owner advertising benchmark started. B373 background strategy engine is blocked during this run.",8500) end
    return true
end

startup.b376.b374_finish_pre = startup.b376.b374_finish_pre or startup.b374_finish
startup.b374_finish = function(reason,aborted)
    local wasActive=startup.b374.active==true
    -- Invalidate any delayed advertising job before releasing benchmark ownership.
    startup.s.advertiseFlowSerial=(tonumber(startup.s.advertiseFlowSerial or 0) or 0)+1
    local result=startup.b376.b374_finish_pre and startup.b376.b374_finish_pre(reason,aborted) or true
    startup.b376.benchmark_owns_modes=false
    startup.b376.strategy.active=false
    if wasActive and startup.b374_log then startup.b374_log("B376_OWNER_RELEASED",tostring(reason or "finished")) end
    return result
end

-- Upgrade checkpoint heading and include strategy-controller state.
startup.b376.checkpoint_pre = startup.b376.checkpoint_pre or startup.b375_checkpoint_write
startup.b375_checkpoint_write = function(reason)
    local path=tostring(startup.b375.checkpoint_path or "")
    if path=="" or not io or not io.open then return false end
    local f=io.open(path,"w"); if not f then return false end
    local now=startup.b375_now(); local seg=startup.b374.current_segment; local st=startup.b376.strategy or {}
    local lines={
        "STARTUP ADVERTISING BENCHMARK CHECKPOINT — BUILD 376",
        "RunId="..tostring(startup.b374.run_id or ""),"Timestamp="..os.date("%Y-%m-%d %H:%M:%S"),"Reason="..tostring(reason or "periodic"),
        "Active="..tostring(startup.b374.active==true),"SingleOwner="..tostring(startup.b376.benchmark_owns_modes==true),"B373EngineRunning="..tostring(startup.b373 and startup.b373.running==true),
        "Phase="..tostring(startup.b374.phase or "IDLE"),"State="..tostring(startup.b374.state or ""),"LastStatus="..tostring(startup.b374.last_status or ""),
        "ManualPosition="..tostring(startup.b374.manual_pos or 0).."/"..tostring(#(startup.b374.manual_regions or {})),
        "StrategyPosition="..tostring(st.pos or 0).."/"..tostring(#(st.order or {})),"StrategyLastRegion="..tostring(st.last_region or ""),"StrategyHoldCount="..tostring(st.hold_count or 0),
        "CurrentRegion="..tostring(type(seg)=="table" and seg.region or st.last_region or ""),"CurrentMode="..tostring(type(seg)=="table" and seg.mode or st.mode or ""),
        "Players="..tostring(startup.get_session_player_count and startup.get_session_player_count() or "?"),"SegmentJoins="..tostring(type(seg)=="table" and seg.joins or 0),"SegmentLeaves="..tostring(type(seg)=="table" and seg.leaves or 0),
        "RecordsSaved="..tostring(#(startup.b374.records or {})),"SessionStable="..tostring(startup.b375.session_stable==true),"Paused="..tostring(startup.b375.paused==true),
        "PauseCount="..tostring(startup.b375.pause_count or 0),"TotalPausedMs="..tostring(startup.b375.total_paused_ms or 0),"PairStatus="..tostring(startup.b373 and startup.b373.pair_status or ""),
        "NativeJob="..tostring(startup.b375.region_job and (startup.b375.region_job.region..":"..startup.b375.region_job.step) or "None"),"LastNativeAction="..tostring(startup.b375.last_native_action or "None"),
        "LastNativeActionMs="..tostring(startup.b375.last_native_action_ms or 0),"NowMs="..tostring(now)
    }
    f:write(table.concat(lines,"\n"),"\n"); f:close(); return true
end

startup.b376.summary_pre = startup.b376.summary_pre or startup.b374_write_summary
startup.b374_write_summary = function(reason)
    local ok=startup.b376.summary_pre and startup.b376.summary_pre(reason) or false
    local path=tostring(startup.b374.summary_path or "")
    if path~="" and io and io.open then
        local f=io.open(path,"r")
        if f then
            local body=f:read("*a") or ""; f:close()
            body=body:gsub("BUILD 375","BUILD 376")
            body=body:gsub("B373 region%-level CSV rows inside the same Support ZIP explain which regions each strategy selected/held%.","Build 376 strategy rows are controller-owned; no second B373 strategy engine runs during the benchmark.")
            local w=io.open(path,"w"); if w then w:write(body); w:close() end
        end
    end
    return ok
end

function startup.b374_ui_lines()
    if startup.b374.active~=true then
        local last=(tostring(startup.s.b374LastSummaryPath or "")~="") and " | Last report saved" or ""
        return {"Single-owner benchmark: idle | Preset: "..tostring(startup.s.advertisingBenchmarkDuration374 or "90 Minutes")..last}
    end
    local now=startup.b375_now(); local seg=startup.b374.current_segment; local st=startup.b376.strategy or {}
    local remain=0
    if startup.b374.phase=="POPULARITY_ROTATION" or startup.b374.phase=="SMART_ADAPTIVE" then remain=startup.b376_strategy_remaining(now) else remain=math.max(0,(tonumber(startup.b374.phase_ends_ms or now) or now)-now) end
    local detail=""
    if type(seg)=="table" then detail=" | "..tostring(seg.region).." | +"..tostring(seg.joins or 0).."/-"..tostring(seg.leaves or 0).." | "..tostring(startup.get_session_player_count()).."p" end
    return {
        "B376 SINGLE-OWNER BENCHMARK | "..tostring(startup.b374.phase).." | remaining "..startup.b373_format_ms(remain),
        "B373 strategy engine BLOCKED"..detail,
        "Serialized region callbacks | session pause/resume | checkpoint every 5s"
    }
end

