-- ============================================================================
-- BUILD 377: LOW-FREQUENCY STANDALONE ADVERTISING ISOLATION BENCHMARK
-- ============================================================================
-- B376 crash evidence showed the process died during WARMUP before any native
-- region job or B373 strategy worker was active. B377 therefore removes the
-- strategy-engine ownership layer from the test entirely and uses a throttled,
-- standalone driver. No Advertise Session write is performed by this test.
-- ============================================================================

startup.b377 = startup.b377 or {}
startup.b377.active = false
startup.b377.driver_interval_ms = 1000
startup.b377.next_driver_ms = 0
startup.b377.checkpoint_interval_ms = 30000
startup.b377.next_checkpoint_ms = 0
startup.b377.passive_warmup_ms = 120000
startup.b377.region_window_ms = 120000
startup.b377.cooldown_ms = 120000
startup.b377.phase = "IDLE"
startup.b377.phase_end_ms = 0
startup.b377.region_pos = 0
startup.b377.run_id = ""
startup.b377.saved = startup.b377.saved or {}
startup.b377.last_status = "Idle"
startup.b377.cached_players = 0
startup.b377.cached_ui = {"B377 isolation benchmark: idle"}
startup.b377.manual_regions = {"My Region","Northern Asia","Africa","East America","Europe","China","Australia","West America","Japan"}

-- Undo B376's global strategy wrappers. B377 does not replace global advertising
-- functions. Instead it disables Startup automation logically for the duration.
if startup.b376 then
    if startup.b376.run_advertise_flow_pre then startup.run_advertise_flow = startup.b376.run_advertise_flow_pre end
    if startup.b376.update_advertise_smart_state_pre then startup.update_advertise_smart_state = startup.b376.update_advertise_smart_state_pre end
    if startup.b376.b373_start_engine_pre then startup.b373_start_engine = startup.b376.b373_start_engine_pre end
    startup.b376.benchmark_owns_modes = false
    if startup.b376.strategy then startup.b376.strategy.active=false end
end

function startup.b377_log(kind,detail)
    if startup.b374_log then startup.b374_log("B377_"..tostring(kind or "EVENT"),tostring(detail or "")) end
    if startup.support_log_event_quiet then startup.support_log_event_quiet("B377_"..tostring(kind or "EVENT"),tostring(detail or "")) end
end

function startup.b377_native_advertise_is_on()
    local state=startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
    return state==true,state
end

function startup.b377_save_logical_state()
    startup.b377.saved={
        auto=startup.s.autoAdvertiseSession==true,
        running=startup.s.advertiseRunning==true,
        smart=startup.s.advertiseSmartActive==true,
        stop=startup.s.advertiseStopRequested==true,
        mode=tostring(startup.s.advertisingMode373 or "Smart Adaptive")
    }
end

function startup.b377_disable_startup_advertising_automation()
    direct_call(startup.b373_stop_engine,"B377 isolation start",false)
    startup.s.advertiseFlowSerial=(tonumber(startup.s.advertiseFlowSerial or 0) or 0)+1
    startup.s.autoAdvertiseSession=false
    startup.s.advertiseRunning=false
    startup.s.advertiseSmartActive=false
    startup.s.advertiseStopRequested=false
    if startup.h and startup.h.AutoAdvertiseSession and startup.set_feature_bool_silently then
        direct_call(startup.set_feature_bool_silently,startup.h.AutoAdvertiseSession,false)
    end
end

function startup.b377_restore_logical_ui_only()
    -- Do NOT fire any native callback or restart an advertising worker here.
    -- A normal Startup reload restores the saved config cleanly after the test.
    startup.s.autoAdvertiseSession=false
    startup.s.advertiseRunning=false
    startup.s.advertiseSmartActive=false
    startup.s.advertiseStopRequested=false
    if startup.h and startup.h.AutoAdvertiseSession and startup.set_feature_bool_silently then
        direct_call(startup.set_feature_bool_silently,startup.h.AutoAdvertiseSession,false)
    end
end

function startup.b377_checkpoint(reason)
    local path=tostring(startup.b375.checkpoint_path or "")
    if path=="" or not io or not io.open then return false end
    local f=io.open(path,"w"); if not f then return false end
    local now=startup.b375_now(); local seg=startup.b374.current_segment
    local lines={
        "STARTUP ADVERTISING ISOLATION CHECKPOINT — BUILD 377",
        "RunId="..tostring(startup.b377.run_id),
        "Timestamp="..os.date("%Y-%m-%d %H:%M:%S"),
        "Reason="..tostring(reason or "periodic"),
        "Active="..tostring(startup.b377.active==true),
        "Phase="..tostring(startup.b377.phase),
        "RegionPosition="..tostring(startup.b377.region_pos).."/"..tostring(#startup.b377.manual_regions),
        "CurrentRegion="..tostring(type(seg)=="table" and seg.region or ""),
        "Players="..tostring(startup.b377.cached_players or 0),
        "SegmentJoins="..tostring(type(seg)=="table" and seg.joins or 0),
        "SegmentLeaves="..tostring(type(seg)=="table" and seg.leaves or 0),
        "RecordsSaved="..tostring(#(startup.b374.records or {})),
        "SessionStable="..tostring(startup.b375.session_stable==true),
        "Paused="..tostring(startup.b375.paused==true),
        "NativeJob="..tostring(startup.b375.region_job and (startup.b375.region_job.region..":"..startup.b375.region_job.step) or "None"),
        "LastNativeAction="..tostring(startup.b375.last_native_action or "None"),
        "LastNativeActionMs="..tostring(startup.b375.last_native_action_ms or 0),
        "AdvertiseSessionWriteByB377=false",
        "B373EngineRunning="..tostring(startup.b373 and startup.b373.running==true),
        "NowMs="..tostring(now)
    }
    f:write(table.concat(lines,"\n"),"\n"); f:close(); return true
end

function startup.b377_refresh_ui(now)
    now=tonumber(now or startup.b375_now()) or startup.b375_now()
    local remain=math.max(0,(tonumber(startup.b377.phase_end_ms or now) or now)-now)
    local seg=startup.b374.current_segment
    local detail=""
    if type(seg)=="table" then detail=" | "..tostring(seg.region).." | +"..tostring(seg.joins or 0).."/-"..tostring(seg.leaves or 0) end
    startup.b377.cached_ui={
        "B377 LOW-FREQUENCY ISOLATION | "..tostring(startup.b377.phase).." | remaining "..tostring(startup.b373_format_ms and startup.b373_format_ms(remain) or remain),
        "Players "..tostring(startup.b377.cached_players or 0)..detail,
        "1 Hz driver | 30s checkpoint | B377 never writes Advertise Session"
    }
end

function startup.b377_start_segment_after_sync(region)
    local now=startup.b375_now()
    startup.b374.current_segment=startup.b374_new_segment("ISOLATED_REGION_SWEEP","Isolated Manual",region,startup.b377.region_window_ms)
    startup.b377.phase="REGION_TEST"
    startup.b377.phase_end_ms=now+startup.b377.region_window_ms
    startup.b374.phase="ISOLATED_REGION_SWEEP"
    startup.b374.phase_started_ms=now
    startup.b374.phase_ends_ms=startup.b377.phase_end_ms
    startup.b374.state="TESTING "..tostring(region)
    startup.b377.last_status="Testing "..tostring(region).." for 2 minutes"
    startup.b377_log("SEGMENT_START",tostring(region).." | planned=2:00 | pair="..tostring(startup.b373 and startup.b373.pair_status or ""))
    startup.b377_checkpoint("region test started")
end

function startup.b377_begin_next_region()
    startup.b377.region_pos=(tonumber(startup.b377.region_pos or 0) or 0)+1
    if startup.b377.region_pos>#startup.b377.manual_regions then
        startup.b377.phase="COOLDOWN"
        startup.b377.phase_end_ms=startup.b375_now()+startup.b377.cooldown_ms
        startup.b374.phase="B377_COOLDOWN"
        startup.b374.current_segment=nil
        startup.b377.last_status="Final passive cooldown — no native callbacks"
        startup.b377_log("COOLDOWN_START","2 minutes passive")
        return true
    end
    local region=startup.b377.manual_regions[startup.b377.region_pos]
    startup.b377.phase="REGION_TRANSITION"
    startup.b377.phase_end_ms=0
    startup.b374.phase="REGION_TRANSITION"
    startup.b374.current_segment=nil
    startup.b377.last_status="Serialized transition to "..tostring(region)

    -- If both native controls already report the target, do not fire redundant callbacks.
    local ov=startup.b373_read_override_region and startup.b373_read_override_region() or nil
    local adv=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or nil
    if tostring(ov)==tostring(region) and tostring(adv)==tostring(region) then
        startup.b377_log("REGION_ALREADY_SYNCED",region)
        startup.b377_start_segment_after_sync(region)
        return true
    end

    local ok,why=startup.b375_queue_region_pair(region,"B377 isolated region sweep",function(success,detail,target)
        if success~=true then
            startup.b377_log("REGION_SYNC_FAIL",tostring(target).." | "..tostring(detail))
            startup.b377_finish("Region sync failed: "..tostring(target),true)
            return
        end
        startup.b377_log("REGION_SYNC_OK",tostring(target).." | "..tostring(detail))
        startup.b377_start_segment_after_sync(target)
    end)
    if ok~=true then
        startup.b377_log("REGION_QUEUE_FAIL",region.." | "..tostring(why))
        startup.b377_finish("Unable to queue region: "..region,true)
        return false
    end
    return true
end

function startup.b377_write_summary(reason)
    local path=tostring(startup.b374.summary_path or "")
    if path=="" or not io or not io.open then return false end
    local f=io.open(path,"w"); if not f then return false end
    local function w(x) f:write(tostring(x or ""),"\n") end
    w("STARTUP ADVERTISING ISOLATION BENCHMARK — BUILD 377")
    w("=================================================")
    w("Run ID: "..tostring(startup.b377.run_id))
    w("Started: "..tostring(startup.b374.started_clock or ""))
    w("Finished: "..os.date("%Y-%m-%d %H:%M:%S"))
    w("Reason: "..tostring(reason or "Completed"))
    w("Safety: 1 Hz driver; 30-second checkpoint; no B377 Advertise Session writes; no Smart/Popularity worker")
    w("")
    w("REGION RESULTS")
    local ranked={}
    for _,r in ipairs(startup.b374.records or {}) do
        if r.phase=="ISOLATED_REGION_SWEEP" then ranked[#ranked+1]=r end
    end
    table.sort(ranked,function(a,b)
        if (tonumber(a.joinRate or 0) or 0)==(tonumber(b.joinRate or 0) or 0) then return (tonumber(a.net or 0) or 0)>(tonumber(b.net or 0) or 0) end
        return (tonumber(a.joinRate or 0) or 0)>(tonumber(b.joinRate or 0) or 0)
    end)
    for i,r in ipairs(ranked) do
        w(string.format("%d. %s | joins=%d leaves=%d net=%+d | %.2f joins/min | elapsed=%s",i,tostring(r.region),tonumber(r.joins or 0),tonumber(r.leaves or 0),tonumber(r.net or 0),tonumber(r.joinRate or 0),startup.b373_format_ms(tonumber(r.elapsedMs or 0))))
    end
    f:close(); return true
end

function startup.b377_finish(reason,aborted)
    if startup.b377.active~=true then return true end
    if startup.b374.current_segment then startup.b374_finish_segment((aborted==true and "ABORTED:" or "COMPLETE:")..tostring(reason or "finished")) end
    startup.b377.active=false
    startup.b374.active=false
    startup.b374.completed=aborted~=true
    startup.b377.phase="IDLE"
    startup.b374.phase="IDLE"
    startup.b375.region_job=nil
    startup.b377.last_status=tostring(reason or "Finished")
    startup.b377_restore_logical_ui_only()
    startup.b377_write_summary(reason)
    startup.b377_checkpoint(aborted==true and "aborted" or "complete")
    startup.b377_log(aborted==true and "ABORT" or "COMPLETE",tostring(reason or "finished"))
    if startup.toast then
        startup.toast((aborted==true and "B377 isolation stopped. " or "B377 isolation complete. ").."Results saved. Reload Startup before normal advertising automation.",9000)
    end
    return true
end

-- Redirect the existing benchmark stop path to the B377 isolated controller.
startup.b374_finish = function(reason,aborted)
    if startup.b377 and startup.b377.active==true then return startup.b377_finish(reason,aborted) end
    return true
end

function startup.b377_start()
    if startup.b377.active==true then if startup.toast then startup.toast("B377 isolation test is already running.",3000) end; return false end
    if startup.b375_raw_session_ready()~=true then if startup.toast then startup.toast("Enter a stable GTA Online session first.",4500) end; return false end
    local advOn,raw=startup.b377_native_advertise_is_on()
    if advOn~=true then
        if startup.toast then startup.toast("For B377 safety, turn Cherax Advertise Session ON manually before starting. B377 will not write it for you.",7500) end
        return false
    end
    startup.b377_save_logical_state()
    startup.b377_disable_startup_advertising_automation()
    startup.b377.active=true
    startup.b374.active=true
    startup.b374.completed=false
    startup.b374.records={}
    startup.b374.current_segment=nil
    startup.b377.region_pos=0
    startup.b377.next_driver_ms=0
    startup.b377.next_checkpoint_ms=0
    startup.b375.region_job=nil
    startup.b375.ready_since_ms=0
    startup.b375.session_stable=false
    startup.b375.paused=false
    startup.b375.pause_started_ms=0
    startup.b375.total_paused_ms=0
    startup.b375.pause_count=0
    startup.b375.last_native_action="None"
    startup.b375.last_native_action_ms=0
    local now=startup.b375_now()
    startup.b374.run_started_ms=now
    startup.b374.started_clock=os.date("%Y-%m-%d %H:%M:%S")
    startup.b377.run_id="B377_"..os.date("%Y%m%d_%H%M%S")
    startup.b374.run_id=startup.b377.run_id
    startup.b374.target_players=tonumber(startup.s.advertisingTargetPlayers373 or 30) or 30
    local base=tostring(startup.diagnostics_dir or startup.save_dir or "")
    startup.ensure_save_dir()
    startup.b374.csv_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b377.run_id)..".csv"
    startup.b374.summary_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b377.run_id)..".txt"
    startup.b374.event_log_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b377.run_id)..".log"
    startup.b375.checkpoint_path=base.."\\Advertising_Benchmark_"..startup.b374_safe_filename(startup.b377.run_id).."_CHECKPOINT.txt"
    startup.s.b374LastCsvPath=startup.b374.csv_path
    startup.s.b374LastSummaryPath=startup.b374.summary_path
    startup.s.b374LastEventLogPath=startup.b374.event_log_path
    startup.s.b375LastCheckpointPath=startup.b375.checkpoint_path
    startup.b374_csv_header()
    startup.b374_write_line(startup.b374.event_log_path,"","w")
    startup.b377.phase="PASSIVE_WARMUP"
    startup.b377.phase_end_ms=now+startup.b377.passive_warmup_ms
    startup.b374.phase="B377_PASSIVE_WARMUP"
    startup.b374.phase_started_ms=now
    startup.b374.phase_ends_ms=startup.b377.phase_end_ms
    startup.b377.last_status="2-minute passive warm-up — zero native advertising callbacks"
    startup.b377.cached_players=tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0
    startup.b377_log("START","passive=2m | regions=9x2m | cooldown=2m | AdvertiseSessionWrite=false | driver=1Hz | players="..tostring(startup.b377.cached_players))
    startup.b377_checkpoint("start")
    if startup.toast then startup.toast("B377 isolation started. First 2 minutes are passive; B377 will not write Advertise Session.",8000) end
    return true
end

-- Existing B374 button is redirected to B377 too, so accidentally using the old
-- label still starts the safer isolated test.
startup.b374_start = startup.b377_start

-- Low-frequency driver. The registered B374 loop can call this every frame, but
-- all actual benchmark work is throttled to once per second before any session
-- readiness/native work happens.
function startup.b374_tick()
    if startup.b377.active~=true then return end
    local now=startup.b375_now()
    if now<(tonumber(startup.b377.next_driver_ms or 0) or 0) then return end
    startup.b377.next_driver_ms=now+startup.b377.driver_interval_ms

    local stable=startup.b375_update_session_stability(now)
    startup.b377.cached_players=tonumber(startup.get_session_player_count and startup.get_session_player_count() or startup.b377.cached_players or 0) or 0

    if stable~=true then
        if startup.b375.paused~=true then
            startup.b375.paused=true
            startup.b375.pause_started_ms=now
            startup.b375.pause_count=(tonumber(startup.b375.pause_count or 0) or 0)+1
            startup.b377_log("SESSION_PAUSE","session not continuously stable")
        end
        if now>=(tonumber(startup.b377.next_checkpoint_ms or 0) or 0) then
            startup.b377.next_checkpoint_ms=now+startup.b377.checkpoint_interval_ms
            startup.b377_checkpoint("paused")
        end
        startup.b377_refresh_ui(now)
        return
    end

    if startup.b375.paused==true then
        local delta=math.max(0,now-(tonumber(startup.b375.pause_started_ms or now) or now))
        startup.b375.total_paused_ms=(tonumber(startup.b375.total_paused_ms or 0) or 0)+delta
        startup.b375.paused=false
        startup.b375.pause_started_ms=0
        if startup.b377.phase_end_ms>0 then startup.b377.phase_end_ms=startup.b377.phase_end_ms+delta end
        if startup.b374.phase_ends_ms and startup.b374.phase_ends_ms>0 then startup.b374.phase_ends_ms=startup.b374.phase_ends_ms+delta end
        local seg=startup.b374.current_segment
        if type(seg)=="table" then
            if (tonumber(seg.startedMs or 0) or 0)>0 then seg.startedMs=seg.startedMs+delta end
            if (tonumber(seg.firstJoinMs or 0) or 0)>0 then seg.firstJoinMs=seg.firstJoinMs+delta end
            if (tonumber(seg.lastJoinMs or 0) or 0)>0 then seg.lastJoinMs=seg.lastJoinMs+delta end
        end
        startup.b377_log("SESSION_RESUME","paused="..tostring(startup.b373_format_ms and startup.b373_format_ms(delta) or delta))
    end

    if startup.b375.region_job then startup.b375_process_region_job(now) end

    if now>=(tonumber(startup.b377.next_checkpoint_ms or 0) or 0) then
        startup.b377.next_checkpoint_ms=now+startup.b377.checkpoint_interval_ms
        startup.b377_checkpoint("periodic")
    end

    if startup.b374.current_segment then startup.b374_capture_segment(startup.b374.current_segment,now) end

    if startup.b377.phase=="PASSIVE_WARMUP" then
        if now>=startup.b377.phase_end_ms then startup.b377_begin_next_region() end
    elseif startup.b377.phase=="REGION_TRANSITION" then
        -- Callback from the serialized job starts the measured window.
    elseif startup.b377.phase=="REGION_TEST" then
        if now>=startup.b377.phase_end_ms then
            startup.b374_finish_segment("B377_TIMED_WINDOW_COMPLETE")
            startup.b377_begin_next_region()
        end
    elseif startup.b377.phase=="COOLDOWN" then
        if now>=startup.b377.phase_end_ms then startup.b377_finish("Low-frequency isolation benchmark completed",false) end
    end
    startup.b377_refresh_ui(now)
end

function startup.b374_ui_lines()
    if startup.b377.active~=true then
        return {
            "B377 isolation benchmark: idle",
            "~22 minutes: 2m passive + 9 regions x 2m + 2m cooldown",
            "Requires Cherax Advertise Session already ON; test never writes that toggle."
        }
    end
    return startup.b377.cached_ui or {"B377 isolation benchmark running"}
end

-- Add an explicit new button. The old RUN FULL button is also redirected to this
-- same safe test through startup.b374_start above.
if startup.add_button then
    startup.add_button("RunAdvertisingIsolation377","RUN B377 SAFE ISOLATION TEST","~22-minute crash-isolation benchmark. First 2 minutes are passive, then each modern region is tested for 2 minutes with serialized Override Region + Advertise Region changes, followed by a passive cooldown. Advertise Session must already be ON and B377 never writes that toggle.",function() startup.b377_start() end)
end

startup.version="v1.0.18"
startup.console_version="v1.0.18"
startup.build_number="2026.08.27.377"
startup.build_date="2026-08-27"
startup.build_label="B377 v1.0.16 Alpha - Low-Frequency Advertising Isolation"
startup.b377.loaded=true
if startup.log then startup.log("[Build 377] Low-frequency advertising isolation ready: 1 Hz driver, 30s checkpoints, passive warm-up/cooldown, region sweep only, no Advertise Session writes.") end
if startup.support_log_event_quiet then startup.support_log_event_quiet("BUILD377_LOW_FREQUENCY_ISOLATION_READY","driver_hz=1 checkpoint_s=30 passive_warmup=true region_sweep=true passive_cooldown=true advertise_session_writes=false smart_popularity=false") end


-- ============================================================================
-- BUILD 378: ONE-BUTTON COLD-START REGION BENCHMARK
-- ============================================================================
-- Goal: measure the real cold-start question instead of comparing regions inside
-- one already-growing lobby. Every region receives its own fresh New Public
-- Session. Override Region and Advertise Region are both serialized and verified
-- BEFORE session creation, then read-only verified after the fresh local-host session
-- appears. This prevents the first seconds of a new lobby from being exposed under
-- the previous region. The timed
-- window ends when the lobby reaches 10 total players (local player included) or
-- the selected per-region timeout expires. All native operations remain low-
-- frequency and serialized; normal Startup advertising automation stays disabled.
-- ============================================================================

startup.b378 = startup.b378 or {}
startup.b378.active=false
startup.b378.driver_interval_ms=1000
startup.b378.next_driver_ms=0
startup.b378.checkpoint_interval_ms=30000
startup.b378.next_checkpoint_ms=0
startup.b378.native_settle_ms=4000
startup.b378.route_settle_ms=1250
startup.b378.inter_region_settle_ms=10000
startup.b378.session_request_timeout_ms=60000
startup.b378.max_session_attempts=2
startup.b378.max_override_attempts=2
startup.b378.max_advertise_attempts=2
startup.b378.advertise_read_retry_ms=1000
startup.b378.advertise_read_max_attempts=10
startup.b378.target_players=10
startup.b378.phase="IDLE"
startup.b378.next_action_ms=0
startup.b378.region_pos=0
startup.b378.run_id=""
startup.b378.order={}
startup.b378.current=nil
startup.b378.results={}
startup.b378.last_status="Idle"
startup.b378.cached_ui={"B378 cold-start benchmark: idle"}
startup.b378.session_change_serial=tonumber(startup.b378.session_change_serial or 0) or 0
startup.b378.last_session_change_ms=tonumber(startup.b378.last_session_change_ms or 0) or 0
startup.b378.raw_csv_path=""
startup.b378.cold_csv_path=""
startup.b378.summary_path=""
startup.b378.event_log_path=""
startup.b378.checkpoint_path=""
startup.b378.scan_status="Not scanned"
startup.b378.regions={"My Region","Northern Asia","Africa","East America","Europe","China","Australia","West America","Japan"}

startup.s.coldStartTimeout378=tostring(startup.s.coldStartTimeout378 or "15 Minutes")
if startup.s.coldStartTimeout378~="15 Minutes" and startup.s.coldStartTimeout378~="20 Minutes" then
    startup.s.coldStartTimeout378="15 Minutes"
end

-- Persist the B378 timeout choice without disturbing earlier config fields.
if startup.b378.config_wrapped~=true then
    startup.b378.config_wrapped=true
    startup.b378.export_config_pre=startup.export_config
    function startup.export_config()
        local d=startup.b378.export_config_pre and startup.b378.export_config_pre() or {}
        if type(d)~="table" then d={} end
        d.coldStartTimeout378=tostring(startup.s.coldStartTimeout378 or "15 Minutes")
        return d
    end
    startup.b378.apply_config_pre=startup.apply_config
    function startup.apply_config(data)
        local ret=startup.b378.apply_config_pre and startup.b378.apply_config_pre(data) or nil
        if type(data)=="table" then
            local v=tostring(data.coldStartTimeout378 or startup.s.coldStartTimeout378 or "15 Minutes")
            if v=="15 Minutes" or v=="20 Minutes" then startup.s.coldStartTimeout378=v end
        end
        return ret
    end
end

function startup.b378_now()
    return startup.b375_now and startup.b375_now() or ((startup.now and tonumber(startup.now())) or math.floor((os.clock() or 0)*1000))
end

function startup.b378_timeout_ms()
    return tostring(startup.s.coldStartTimeout378 or "15 Minutes")=="20 Minutes" and 1200000 or 900000
end

function startup.b378_timeout_label()
    return tostring(startup.s.coldStartTimeout378 or "15 Minutes")
end

function startup.b378_log(kind,detail)
    local line=os.date("%Y-%m-%d %H:%M:%S").." | B378_"..tostring(kind or "EVENT").." | "..tostring(detail or "")
    if startup.b374_write_line then startup.b374_write_line(startup.b378.event_log_path,line,"a") end
    if startup.support_log_event_quiet then startup.support_log_event_quiet("B378_"..tostring(kind or "EVENT"),tostring(detail or "")) end
end

function startup.b378_local_is_session_host()
    if not startup.get_session_host_name or not startup.self_diag or not startup.self_diag.is_local_id then return false,"Unknown",-1 end
    local name,id=startup.get_session_host_name()
    return startup.self_diag.is_local_id(id)==true,tostring(name or "Unknown"),tonumber(id or -1) or -1
end

function startup.b378_lcg_shuffle(values)
    local out={}
    for i,v in ipairs(values or {}) do out[i]=v end
    local seed=((tonumber(os.time()) or 1)*1103515245 + (startup.b378_now()%2147483647))%2147483647
    if seed<=0 then seed=104729 end
    local function next_rand()
        seed=(seed*48271)%2147483647
        return seed
    end
    for i=#out,2,-1 do
        local j=(next_rand()%i)+1
        out[i],out[j]=out[j],out[i]
    end
    return out
end

function startup.b378_scan_preflight()
    local problems={}
    local details={}
    local sessionFeature=nil
    if startup.feature_hash and startup.feature_hash.SESSION_TYPE and startup.get_feature_by_hash_safe then
        sessionFeature=startup.get_feature_by_hash_safe(startup.feature_hash.SESSION_TYPE)
    end
    if not sessionFeature then
        problems[#problems+1]="Session Type control unavailable"
    elseif not sessionFeature.GetListIndexByString or not sessionFeature.SetListIndexByString then
        problems[#problems+1]="Session Type direct string API unavailable"
    else
        local ok,idx=pcall(function() return sessionFeature:GetListIndexByString("New Public Session") end)
        if not ok or idx==nil then problems[#problems+1]="New Public Session route unavailable" else details[#details+1]="New Public Session=OK" end
    end

    local startAvailable=false
    if startup.feature_hash and startup.feature_hash.START_SESSION and startup.get_feature_by_hash_safe then
        local f=startup.get_feature_by_hash_safe(startup.feature_hash.START_SESSION)
        startAvailable=f~=nil
    end
    if not startAvailable and FeatureMgr and FeatureMgr.TriggerFeatureCallback then startAvailable=true end
    if not startAvailable then problems[#problems+1]="Start Session action unavailable" else details[#details+1]="Start Session=OK" end

    local ov=startup.b373_override_feature and startup.b373_override_feature() or nil
    if not ov or not ov.SetListIndex then problems[#problems+1]="Override Region control unavailable" else details[#details+1]="Override Region=OK" end

    local adv=startup.b368_region_feature and startup.b368_region_feature() or nil
    if not adv then problems[#problems+1]="Advertise Region control unavailable" else details[#details+1]="Advertise Region=OK" end

    local advSession=startup.get_advertise_session_feature and startup.get_advertise_session_feature() or nil
    if not advSession then
        problems[#problems+1]="Advertise Session control unavailable"
    else
        local state=startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
        if state==nil then problems[#problems+1]="Advertise Session state unreadable" else details[#details+1]="Advertise Session="..(state and "ON" or "OFF") end
    end

    for _,region in ipairs(startup.b378.regions) do
        local idx=startup.b373 and startup.b373.region_index and startup.b373.region_index[region] or nil
        if idx==nil then problems[#problems+1]="Missing region index: "..tostring(region) end
    end

    if #problems>0 then
        startup.b378.scan_status="FAILED: "..table.concat(problems," | ")
        startup.b378_log("SCAN_FAIL",startup.b378.scan_status)
        return false,startup.b378.scan_status
    end
    startup.b378.scan_status="PASS | "..table.concat(details," | ")
    startup.b378_log("SCAN_OK",startup.b378.scan_status)
    return true,startup.b378.scan_status
end

function startup.b378_checkpoint(reason)
    local path=tostring(startup.b378.checkpoint_path or "")
    if path=="" or not io or not io.open then return false end
    local f=io.open(path,"w"); if not f then return false end
    local c=startup.b378.current or {}
    local seg=startup.b374.current_segment
    local advState=startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
    local isHost,hostName,hostId=startup.b378_local_is_session_host()
    local lines={
        "STARTUP COLD-START REGION BENCHMARK CHECKPOINT — BUILD 378",
        "RunId="..tostring(startup.b378.run_id),
        "Timestamp="..os.date("%Y-%m-%d %H:%M:%S"),
        "Reason="..tostring(reason or "periodic"),
        "Active="..tostring(startup.b378.active==true),
        "Phase="..tostring(startup.b378.phase),
        "ScanStatus="..tostring(startup.b378.scan_status),
        "RegionPosition="..tostring(startup.b378.region_pos).."/"..tostring(#startup.b378.order),
        "Region="..tostring(c.region or ""),
        "Order="..table.concat(startup.b378.order or {}," > "),
        "Timeout="..startup.b378_timeout_label(),
        "TargetPlayers=10",
        "Players="..tostring(startup.get_session_player_count and startup.get_session_player_count() or 0),
        "StartPlayers="..tostring(type(seg)=="table" and seg.startPlayers or c.test_start_players or ""),
        "Joins="..tostring(type(seg)=="table" and seg.joins or 0),
        "Leaves="..tostring(type(seg)=="table" and seg.leaves or 0),
        "SessionAttempts="..tostring(c.session_attempts or 0),
        "SessionChangeSerial="..tostring(startup.b378.session_change_serial),
        "ExpectedSessionSerial="..tostring(c.expected_session_serial or 0),
        "SessionClickMs="..tostring(c.session_click_ms or 0),
        "SessionEventMs="..tostring(c.session_event_ms or 0),
        "SessionReadyMs="..tostring(c.session_ready_ms or 0),
        "LocalSessionHost="..tostring(isHost).." | "..tostring(hostName).."("..tostring(hostId)..")",
        "Override="..tostring(startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"),
        "Advertise="..tostring(startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"),
        "AdvertiseSession="..tostring(advState==nil and "UNKNOWN" or (advState and "ON" or "OFF")),
        "AdvertiseRepairUsed="..tostring(c.advertise_repair_used==true),
        "LastNativeAction="..tostring(startup.b375.last_native_action or "None"),
        "LastNativeActionMs="..tostring(startup.b375.last_native_action_ms or 0),
        "B373EngineRunning="..tostring(startup.b373 and startup.b373.running==true),
        "NowMs="..tostring(startup.b378_now())
    }
    f:write(table.concat(lines,"\n"),"\n"); f:close(); return true
end

function startup.b378_write_cold_csv_header()
    local f=io and io.open and io.open(tostring(startup.b378.cold_csv_path or ""),"w") or nil
    if not f then return false end
    f:write("RunId,OrderIndex,Region,Result,TimeoutMinutes,SessionAttempts,SessionClickToEventMs,SessionEventToReadyMs,SessionClickToReadyMs,ReadyPlayers,TestStartPlayers,EndPlayers,PeakPlayers,ObservedJoins,ObservedLeaves,NetGrowth,TimeTo10PlayersMs,TimeTo10Players,TestElapsedMs,AdvertiseRepairUsed,PairStatus,ColdStartQuality\n")
    f:close(); return true
end

function startup.b378_csv_escape(v)
    return startup.b374_csv_escape and startup.b374_csv_escape(v) or tostring(v==nil and "" or v)
end

function startup.b378_record_result(seg,result)
    local c=startup.b378.current or {}
    local now=startup.b378_now()
    seg=seg or {}
    local clickToEvent=(tonumber(c.session_event_ms or 0)>0 and tonumber(c.session_click_ms or 0)>0) and math.max(0,c.session_event_ms-c.session_click_ms) or nil
    local eventToReady=(tonumber(c.session_ready_ms or 0)>0 and tonumber(c.session_event_ms or 0)>0) and math.max(0,c.session_ready_ms-c.session_event_ms) or nil
    local clickToReady=(tonumber(c.session_ready_ms or 0)>0 and tonumber(c.session_click_ms or 0)>0) and math.max(0,c.session_ready_ms-c.session_click_ms) or nil
    local startPlayers=tonumber(seg.startPlayers or c.test_start_players or 0) or 0
    local endPlayers=tonumber(seg.endPlayers or (startup.get_session_player_count and startup.get_session_player_count() or 0)) or 0
    local targetMs=tonumber(seg.targetReachedMs)
    local quality=startPlayers<=2 and "CLEAN_COLD_START" or (startPlayers<=4 and "WARMING_START" or "PRE_FILLED_START")
    local r={
        region=tostring(c.region or seg.region or "Unknown"),orderIndex=tonumber(startup.b378.region_pos or 0) or 0,result=tostring(result or "UNKNOWN"),
        timeoutMinutes=math.floor(startup.b378_timeout_ms()/60000),sessionAttempts=tonumber(c.session_attempts or 0) or 0,
        clickToEventMs=clickToEvent,eventToReadyMs=eventToReady,clickToReadyMs=clickToReady,readyPlayers=tonumber(c.ready_players or 0) or 0,
        startPlayers=startPlayers,endPlayers=endPlayers,peakPlayers=tonumber(seg.peakPlayers or endPlayers) or endPlayers,
        joins=tonumber(seg.joins or 0) or 0,leaves=tonumber(seg.leaves or 0) or 0,net=tonumber(seg.net or (endPlayers-startPlayers)) or 0,
        targetMs=targetMs,elapsedMs=tonumber(seg.elapsedMs or 0) or 0,advertiseRepair=c.advertise_repair_used==true,
        pairStatus=tostring(seg.pairStatus or (startup.b373 and startup.b373.pair_status) or ""),quality=quality,recordedMs=now
    }
    startup.b378.results[#startup.b378.results+1]=r
    local vals={
        startup.b378.run_id,r.orderIndex,r.region,r.result,r.timeoutMinutes,r.sessionAttempts,r.clickToEventMs or "",r.eventToReadyMs or "",r.clickToReadyMs or "",
        r.readyPlayers,r.startPlayers,r.endPlayers,r.peakPlayers,r.joins,r.leaves,r.net,r.targetMs or "",r.targetMs and startup.b373_format_ms(r.targetMs) or "",r.elapsedMs,
        r.advertiseRepair and "YES" or "NO",r.pairStatus,r.quality
    }
    for i,v in ipairs(vals) do vals[i]=startup.b378_csv_escape(v) end
    local f=io and io.open and io.open(tostring(startup.b378.cold_csv_path or ""),"a") or nil
    if f then f:write(table.concat(vals,","),"\n"); f:close() end
    startup.b378_log("RESULT",r.region.." | "..r.result.." | start="..r.startPlayers.." end="..r.endPlayers.." joins="..r.joins.." leaves="..r.leaves.." target="..tostring(r.targetMs and startup.b373_format_ms(r.targetMs) or "TIMEOUT").." quality="..r.quality)
    return r
end

function startup.b378_write_summary(reason)
    local f=io and io.open and io.open(tostring(startup.b378.summary_path or ""),"w") or nil
    if not f then return false end
    local function w(s) f:write(tostring(s or ""),"\n") end
    w("STARTUP BUILD 378 — ONE-BUTTON COLD-START REGION BENCHMARK")
    w("============================================================")
    w("Run ID: "..tostring(startup.b378.run_id))
    w("Finished: "..os.date("%Y-%m-%d %H:%M:%S"))
    w("Reason: "..tostring(reason or "Completed"))
    w("Target: lobby reaches 10 total players, including the local player")
    w("Per-region timeout: "..startup.b378_timeout_label())
    w("Each region: Override Region -> Advertise Region -> verify pair -> fresh New Public Session -> 5-second local Session Host readiness -> read-only pair verification -> Advertise Session verification -> timed test")
    w("Primary time-to-10 is measured from the timed test start after that readiness check; Start Session click-to-event and click-to-ready are logged separately.")
    w("Region order: "..table.concat(startup.b378.order or {}," > "))
    w("")
    local ranked={}
    for _,r in ipairs(startup.b378.results or {}) do ranked[#ranked+1]=r end
    table.sort(ranked,function(a,b)
        local at=a.targetMs or 999999999
        local bt=b.targetMs or 999999999
        if at==bt then return tostring(a.region)<tostring(b.region) end
        return at<bt
    end)
    w("RESULTS — FASTEST TO 10 PLAYERS")
    w("--------------------------------")
    for i,r in ipairs(ranked) do
        local t=r.targetMs and startup.b373_format_ms(r.targetMs) or (">"..tostring(r.timeoutMinutes)..":00")
        w(string.format("%d. %s | %s | start %d -> end %d | +%d joins / -%d leaves | %s | %s",i,tostring(r.region),tostring(t),tonumber(r.startPlayers or 0),tonumber(r.endPlayers or 0),tonumber(r.joins or 0),tonumber(r.leaves or 0),tostring(r.result),tostring(r.quality)))
    end
    w("")
    w("INTERPRETATION")
    w("--------------")
    w("This is one fresh session per region, not enough to declare a permanent region winner. Repeat the benchmark across different times/days. Prefer median time-to-10 across repeated runs.")
    w("CLEAN_COLD_START means the timed window began at 1-2 players; WARMING_START means 3-4; PRE_FILLED_START means 5+ and should be treated cautiously.")
    w("Raw per-second behavior is not written. Native control work remains 1 Hz and serialized to preserve B377's stable architecture.")
    f:close(); return true
end

function startup.b378_refresh_ui(now)
    now=tonumber(now or startup.b378_now()) or startup.b378_now()
    local c=startup.b378.current or {}
    local players=tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0
    local line1="B378 COLD START | "..tostring(startup.b378.phase).." | region "..tostring(startup.b378.region_pos).."/"..tostring(#startup.b378.order).." "..tostring(c.region or "")
    local line2="Players "..tostring(players).."/10 | timeout "..startup.b378_timeout_label()
    if startup.b378.phase=="TESTING" and tonumber(c.test_started_ms or 0)>0 then
        local elapsed=math.max(0,now-c.test_started_ms)
        local remain=math.max(0,(tonumber(c.test_deadline_ms or now) or now)-now)
        local seg=startup.b374.current_segment
        line2="Players "..tostring(players).."/10 | elapsed "..startup.b373_format_ms(elapsed).." | remaining "..startup.b373_format_ms(remain).." | +"..tostring(type(seg)=="table" and seg.joins or 0).."/-"..tostring(type(seg)=="table" and seg.leaves or 0)
    end
    startup.b378.cached_ui={line1,line2,"Fresh New Public Session for every region | region pair locked before session + read-only verified after load | 1 Hz serialized controller"}
end

function startup.b378_set_phase(phase,delay_ms,status)
    startup.b378.phase=tostring(phase or "IDLE")
    startup.b378.next_action_ms=startup.b378_now()+math.max(0,tonumber(delay_ms or 0) or 0)
    startup.b378.last_status=tostring(status or startup.b378.phase)
    startup.b378_log("PHASE",startup.b378.phase.." | "..startup.b378.last_status)
end

function startup.b378_begin_region(index,isRetry)
    index=tonumber(index or (startup.b378.region_pos+1)) or 1
    if index>#startup.b378.order then
        startup.b378_finish("Cold-start benchmark completed",false)
        return true
    end
    startup.b378.region_pos=index
    local region=startup.b378.order[index]
    local priorRetry=isRetry==true and startup.b378.current and tonumber(startup.b378.current.retry_count or 0) or 0
    startup.b378.current={
        region=region,index=index,retry_count=priorRetry,override_attempts=0,advertise_attempts=0,session_attempts=0,
        advertise_read_attempts=0,advertise_repair_used=false,session_click_ms=0,session_event_ms=0,session_ready_ms=0,
        ready_players=0,test_started_ms=0,test_deadline_ms=0,expected_session_serial=0,accepted_session_serial=0
    }
    startup.b374.current_segment=nil
    startup.b375.region_job=nil
    startup.b375.ready_since_ms=0
    startup.b375.session_stable=false
    startup.b378_set_phase("PREP_OVERRIDE",0,"Preparing Override Region for "..region)
    startup.b378_checkpoint("begin region")
    return true
end

function startup.b378_record_failure_without_segment(reason)
    local c=startup.b378.current or {}
    local players=tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0
    local seg={
        region=tostring(c.region or "Unknown"),startPlayers=tonumber(c.ready_players or 0) or 0,endPlayers=players,peakPlayers=players,
        joins=0,leaves=0,net=players-(tonumber(c.ready_players or 0) or 0),targetReachedMs=nil,elapsedMs=0,
        pairStatus=tostring(startup.b373 and startup.b373.pair_status or ""),decision=tostring(reason or "FAILED")
    }
    return startup.b378_record_result(seg,tostring(reason or "FAILED"))
end

function startup.b378_retry_or_advance(reason)
    local c=startup.b378.current or {}
    if tonumber(c.retry_count or 0)<1 then
        c.retry_count=(tonumber(c.retry_count or 0) or 0)+1
        startup.b378_log("REGION_RETRY",tostring(c.region).." | "..tostring(reason or "interrupted"))
        startup.b378.current=c
        startup.b378_set_phase("RETRY_SETTLE",15000,"Retrying same region after interruption")
        return true
    end
    startup.b378_log("REGION_GIVEUP",tostring(c.region).." | "..tostring(reason or "failed twice"))
    startup.b378_record_failure_without_segment("FAILED_AFTER_RETRY:"..tostring(reason or "unknown"))
    startup.b378_set_phase("INTER_REGION_SETTLE",startup.b378.inter_region_settle_ms,"Advancing after failed retry")
    return false
end

function startup.b378_start_test_window()
    local c=startup.b378.current or {}
    local now=startup.b378_now()
    startup.b374.target_players=startup.b378.target_players
    local seg=startup.b374_new_segment("COLD_START","Fresh New Public Session",tostring(c.region),startup.b378_timeout_ms())
    seg.pairStatus=tostring(startup.b373 and startup.b373.pair_status or "")
    startup.b374.current_segment=seg
    c.test_started_ms=now
    c.test_deadline_ms=now+startup.b378_timeout_ms()
    c.test_start_players=tonumber(seg.startPlayers or 0) or 0
    startup.b378.current=c
    startup.b378.phase="TESTING"
    startup.b378.next_action_ms=now
    startup.b378_log("TEST_START",tostring(c.region).." | players="..tostring(c.test_start_players).." | target=10 | timeout="..startup.b378_timeout_label().." | pair="..tostring(seg.pairStatus))
    startup.b378_checkpoint("test started")
end

function startup.b378_finish_current_test(decision)
    local seg=startup.b374_finish_segment and startup.b374_finish_segment(decision) or nil
    if seg then startup.b378_record_result(seg,decision) end
    startup.b378_set_phase("INTER_REGION_SETTLE",startup.b378.inter_region_settle_ms,"Saved result; preparing next fresh session")
    startup.b378_checkpoint("region complete")
end

function startup.b378_finish(reason,aborted)
    if startup.b378.active~=true then return true end
    if startup.b374.current_segment then
        local seg=startup.b374_finish_segment((aborted==true and "ABORTED:" or "STOPPED:")..tostring(reason or "finished"))
        if seg then startup.b378_record_result(seg,(aborted==true and "ABORTED" or "STOPPED")) end
    end
    startup.b378.active=false
    startup.b374.active=false
    startup.b374.completed=aborted~=true
    startup.b378.phase="IDLE"
    startup.b375.region_job=nil
    startup.b378.last_status=tostring(reason or "Finished")
    if startup.b377_restore_logical_ui_only then startup.b377_restore_logical_ui_only() end
    startup.b378_write_summary(reason)
    startup.b378_checkpoint(aborted==true and "aborted" or "complete")
    startup.b378_log(aborted==true and "ABORT" or "COMPLETE",tostring(reason or "finished"))
    if startup.toast then startup.toast((aborted and "B378 cold-start benchmark stopped. " or "B378 cold-start benchmark complete. ").."Results saved; create a Support ZIP when convenient.",9000) end
    return true
end

-- Preserve B377 isolation as a fallback/test option while routing the generic full
-- benchmark button to B378.
startup.b378.b377_tick_pre=startup.b374_tick
startup.b378.b377_ui_pre=startup.b374_ui_lines
startup.b378.b374_finish_pre=startup.b374_finish
startup.b374_finish=function(reason,aborted)
    if startup.b378 and startup.b378.active==true then return startup.b378_finish(reason,aborted) end
    if startup.b377 and startup.b377.active==true then return startup.b377_finish(reason,aborted) end
    return startup.b378.b374_finish_pre and startup.b378.b374_finish_pre(reason,aborted) or true
end

function startup.b378_start()
    if startup.b378.active==true or startup.b374.active==true or (startup.b377 and startup.b377.active==true) then
        if startup.toast then startup.toast("An advertising benchmark is already running.",3500) end
        return false
    end

    -- Set paths before scan so every preflight breadcrumb is preserved.
    local base=tostring(startup.diagnostics_dir or startup.save_dir or "")
    startup.ensure_save_dir()
    startup.b378.run_id="B378_"..os.date("%Y%m%d_%H%M%S")
    startup.b374.run_id=startup.b378.run_id
    startup.b378.raw_csv_path=base.."\\Advertising_ColdStart_B378_RAW_"..startup.b374_safe_filename(startup.b378.run_id)..".csv"
    startup.b378.cold_csv_path=base.."\\Advertising_ColdStart_B378_"..startup.b374_safe_filename(startup.b378.run_id)..".csv"
    startup.b378.summary_path=base.."\\Advertising_ColdStart_B378_"..startup.b374_safe_filename(startup.b378.run_id).."_SUMMARY.txt"
    startup.b378.event_log_path=base.."\\Advertising_ColdStart_B378_"..startup.b374_safe_filename(startup.b378.run_id)..".log"
    startup.b378.checkpoint_path=base.."\\Advertising_ColdStart_B378_"..startup.b374_safe_filename(startup.b378.run_id).."_CHECKPOINT.txt"
    startup.b374.csv_path=startup.b378.raw_csv_path
    startup.b374.summary_path=startup.b378.summary_path
    startup.b374.event_log_path=startup.b378.event_log_path
    startup.b375.checkpoint_path=startup.b378.checkpoint_path
    startup.s.b374LastCsvPath=startup.b378.raw_csv_path
    startup.s.b374LastSummaryPath=startup.b378.summary_path
    startup.s.b374LastEventLogPath=startup.b378.event_log_path
    startup.s.b375LastCheckpointPath=startup.b378.checkpoint_path
    startup.b374_csv_header()
    startup.b378_write_cold_csv_header()
    startup.b374_write_line(startup.b378.event_log_path,"","w")

    local ok,detail=startup.b378_scan_preflight()
    if ok~=true then
        if startup.toast then startup.toast("B378 preflight failed: "..tostring(detail),9000) end
        return false
    end

    if startup.b377_save_logical_state then startup.b377_save_logical_state() end
    if startup.b377_disable_startup_advertising_automation then startup.b377_disable_startup_advertising_automation() end
    startup.b378.active=true
    startup.b374.active=true
    startup.b374.completed=false
    startup.b374.records={}
    startup.b378.results={}
    startup.b378.order=startup.b378_lcg_shuffle(startup.b378.regions)
    startup.b378.region_pos=0
    startup.b378.current=nil
    startup.b378.next_driver_ms=0
    startup.b378.next_checkpoint_ms=0
    startup.b375.region_job=nil
    startup.b375.ready_since_ms=0
    startup.b375.session_stable=false
    startup.b375.last_native_action="None"
    startup.b375.last_native_action_ms=0
    startup.b374.run_started_ms=startup.b378_now()
    startup.b374.started_clock=os.date("%Y-%m-%d %H:%M:%S")
    startup.b374.target_players=startup.b378.target_players

    startup.b378_log("START","target=10 | timeout="..startup.b378_timeout_label().." | randomizedOrder="..table.concat(startup.b378.order," > ").." | driver=1Hz | sessionPerRegion=true")

    -- One-button behavior: if Advertise Session is explicitly OFF, turn it ON once.
    -- UNKNOWN was already rejected by preflight, so no blind callback can occur.
    local state=startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
    if state==false then
        local callOk,result=direct_call(startup.set_advertise_session,true,true)
        startup.b375.last_native_action="Advertise Session ON (B378 initial one-shot)"
        startup.b375.last_native_action_ms=startup.b378_now()
        startup.b378_log("ADVERTISE_INITIAL_ON","ok="..tostring(callOk and result~=false))
        if not callOk or result==false then
            startup.b378_finish("Could not enable Advertise Session during preflight",true)
            return false
        end
        startup.b378_set_phase("INITIAL_ADVERTISE_VERIFY",5000,"Verifying one-shot Advertise Session enable")
    else
        startup.b378_set_phase("BEGIN_FIRST_REGION",1000,"Preflight passed; starting randomized cold-start sweep")
    end
    startup.b378_checkpoint("start")
    if startup.toast then startup.toast("B378 cold-start benchmark started. Each region gets a fresh New Public Session; target is 10 players.",8500) end
    return true
end

startup.b374_start=startup.b378_start

function startup.b378_tick_impl()
    if startup.b378.active~=true then return end
    local now=startup.b378_now()
    if now<(tonumber(startup.b378.next_driver_ms or 0) or 0) then return end
    startup.b378.next_driver_ms=now+startup.b378.driver_interval_ms

    if now>=(tonumber(startup.b378.next_checkpoint_ms or 0) or 0) then
        startup.b378.next_checkpoint_ms=now+startup.b378.checkpoint_interval_ms
        startup.b378_checkpoint("periodic")
    end

    local c=startup.b378.current or {}
    local phase=startup.b378.phase

    -- If the measured fresh session changes unexpectedly, invalidate and retry that
    -- same region once. Normal expected session changes occur only in WAIT_SESSION_CHANGE.
    if phase=="TESTING" and tonumber(c.accepted_session_serial or 0)>0 and startup.b378.session_change_serial>c.accepted_session_serial then
        local seg=startup.b374_finish_segment("INTERRUPTED_SESSION_CHANGE")
        if seg then startup.b378_record_result(seg,"INTERRUPTED_SESSION_CHANGE") end
        startup.b378_retry_or_advance("session changed during timed window")
        startup.b378_refresh_ui(now)
        return
    end

    if now<(tonumber(startup.b378.next_action_ms or 0) or 0) then
        if phase=="TESTING" and startup.b374.current_segment then startup.b374_capture_segment(startup.b374.current_segment,now) end
        startup.b378_refresh_ui(now)
        return
    end

    if phase=="INITIAL_ADVERTISE_VERIFY" then
        local state=startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
        if state==true then
            startup.b378_set_phase("BEGIN_FIRST_REGION",500,"Advertise Session verified ON")
        else
            startup.b378_finish("Advertise Session did not verify ON after one-shot enable",true)
        end

    elseif phase=="BEGIN_FIRST_REGION" then
        startup.b378_begin_region(1,false)

    elseif phase=="PREP_OVERRIDE" then
        local region=tostring(c.region or "")
        local current=startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
        if tostring(current)==region then
            startup.b378_set_phase("PREP_ADVERTISE_PRESESSION",500,"Override already "..region.."; preparing Advertise Region")
        else
            c.override_attempts=(tonumber(c.override_attempts or 0) or 0)+1
            startup.b378.current=c
            local ok,detail=false,"setter unavailable"
            if startup.b375.native_apply_override then ok,detail=startup.b375.native_apply_override(region) end
            startup.b375.last_native_action="Override Region -> "..region
            startup.b375.last_native_action_ms=now
            startup.b378_log("OVERRIDE_WRITE",region.." | attempt="..c.override_attempts.." | ok="..tostring(ok).." | "..tostring(detail))
            if ok==true then startup.b378_set_phase("VERIFY_OVERRIDE",startup.b378.native_settle_ms,"Waiting to verify Override Region")
            elseif c.override_attempts<startup.b378.max_override_attempts then startup.b378_set_phase("PREP_OVERRIDE",5000,"Retrying Override Region")
            else startup.b378_finish("Override Region failed for "..region,true) end
        end

    elseif phase=="VERIFY_OVERRIDE" then
        local region=tostring(c.region or "")
        local current=startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
        if tostring(current)==region then
            startup.b378_log("OVERRIDE_OK",region)
            startup.b378_set_phase("PREP_ADVERTISE_PRESESSION",500,"Override verified; preparing Advertise Region before fresh session")
        elseif tonumber(c.override_attempts or 0)<startup.b378.max_override_attempts then
            startup.b378_set_phase("PREP_OVERRIDE",1000,"Override readback mismatch; retry")
        else
            startup.b378_finish("Override Region readback mismatch for "..region,true)
        end

    elseif phase=="PREP_ADVERTISE_PRESESSION" then
        local region=tostring(c.region or "")
        local adv=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
        if tostring(adv)==region then
            startup.b378_set_phase("VERIFY_PRESESSION_PAIR",500,"Advertise Region already correct; verifying pair before session creation")
        else
            c.advertise_attempts=(tonumber(c.advertise_attempts or 0) or 0)+1
            startup.b378.current=c
            local ok=false
            if startup.b375.native_apply_advertise then ok=startup.b375.native_apply_advertise(region,false,"Build 378 cold-start pre-session") end
            startup.b375.last_native_action="Advertise Region -> "..region.." (pre-session)"
            startup.b375.last_native_action_ms=now
            startup.b378_log("ADVERTISE_PRESESSION_WRITE",region.." | attempt="..c.advertise_attempts.." | ok="..tostring(ok))
            if ok==true then
                startup.b378_set_phase("VERIFY_PRESESSION_PAIR",startup.b378.native_settle_ms,"Waiting to verify region pair before New Public Session")
            elseif c.advertise_attempts<startup.b378.max_advertise_attempts then
                startup.b378_set_phase("PREP_ADVERTISE_PRESESSION",5000,"Retrying Advertise Region before session")
            else
                startup.b378_finish("Advertise Region failed before session for "..region,true)
            end
        end

    elseif phase=="VERIFY_PRESESSION_PAIR" then
        local region=tostring(c.region or "")
        local ov=startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
        local adv=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
        local ok=tostring(ov)==region and tostring(adv)==region
        startup.b373.pair_status=(ok and "SYNCED" or "MISMATCH").." | Override="..tostring(ov).." | Advertise="..tostring(adv)
        startup.b378_log("PRESESSION_PAIR_VERIFY",region.." | "..startup.b373.pair_status)
        if ok then
            startup.b378_set_phase("ROUTE_NEW_PUBLIC",500,"Region pair locked before fresh session; selecting New Public Session")
        elseif tostring(ov)~=region and c.override_attempts<startup.b378.max_override_attempts then
            startup.b378_set_phase("PREP_OVERRIDE",1000,"Override mismatch before session; retrying")
        elseif tostring(adv)~=region and c.advertise_attempts<startup.b378.max_advertise_attempts then
            startup.b378_set_phase("PREP_ADVERTISE_PRESESSION",1000,"Advertise mismatch before session; retrying")
        else
            startup.b378_retry_or_advance("could not synchronize region pair before New Public Session")
        end

    elseif phase=="ROUTE_NEW_PUBLIC" then
        local ok,err=false,"route unavailable"
        if startup.self_diag and startup.self_diag.set_session_type_exact then ok,err=startup.self_diag.set_session_type_exact("New Public Session") end
        startup.b378_log("ROUTE_NEW_PUBLIC","region="..tostring(c.region).." | ok="..tostring(ok).." | "..tostring(err or ""))
        if ok==true then startup.b378_set_phase("CLICK_NEW_PUBLIC",startup.b378.route_settle_ms,"Route selected; waiting before one Start Session click")
        else startup.b378_finish("Could not select New Public Session: "..tostring(err),true) end

    elseif phase=="CLICK_NEW_PUBLIC" then
        c.session_attempts=(tonumber(c.session_attempts or 0) or 0)+1
        c.expected_session_serial=startup.b378.session_change_serial+1
        c.session_click_ms=now
        c.session_event_ms=0
        c.session_ready_ms=0
        startup.b378.current=c
        startup.b375.ready_since_ms=0
        startup.b375.session_stable=false
        local ok=startup.click_start_session_feature and startup.click_start_session_feature() or false
        startup.b375.last_native_action="Start New Public Session for "..tostring(c.region)
        startup.b375.last_native_action_ms=now
        startup.b378_log("SESSION_CLICK","region="..tostring(c.region).." | attempt="..c.session_attempts.." | expectSerial="..c.expected_session_serial.." | ok="..tostring(ok))
        if ok==true then
            c.session_deadline_ms=now+startup.b378.session_request_timeout_ms
            startup.b378.current=c
            startup.b378_set_phase("WAIT_SESSION_CHANGE",0,"Waiting for fresh session event")
        elseif c.session_attempts<startup.b378.max_session_attempts then
            startup.b378_set_phase("ROUTE_NEW_PUBLIC",5000,"Start Session failed; retrying")
        else startup.b378_retry_or_advance("Start Session failed twice") end

    elseif phase=="WAIT_SESSION_CHANGE" then
        if startup.b378.session_change_serial>=tonumber(c.expected_session_serial or 0) then
            c.session_event_ms=tonumber(startup.b378.last_session_change_ms or now) or now
            c.host_deadline_ms=now+startup.b378.session_request_timeout_ms
            c.accepted_session_serial=startup.b378.session_change_serial
            startup.b378.current=c
            startup.b375.ready_since_ms=0
            startup.b375.session_stable=false
            startup.b378_log("SESSION_EVENT","region="..tostring(c.region).." | serial="..c.accepted_session_serial.." | clickToEvent="..tostring(math.max(0,c.session_event_ms-c.session_click_ms)).."ms")
            startup.b378_set_phase("WAIT_FRESH_HOST",0,"Fresh session event observed; confirming raw readiness + local Session Host")
        elseif now>=tonumber(c.session_deadline_ms or 0) then
            if c.session_attempts<startup.b378.max_session_attempts then startup.b378_set_phase("ROUTE_NEW_PUBLIC",5000,"No session event; retrying fresh public session")
            else startup.b378_retry_or_advance("timed out waiting for fresh session") end
        end

    elseif phase=="WAIT_FRESH_HOST" then
        local rawReady=startup.b375_raw_session_ready and startup.b375_raw_session_ready() or false
        local isHost,hostName=startup.b378_local_is_session_host()
        local eventAge=now-(tonumber(c.session_event_ms or now) or now)
        if rawReady==true and isHost==true and eventAge>=5000 then
            c.session_ready_ms=now
            c.ready_players=tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0
            -- Accept the latest serial after the 5-second load settle; duplicate load callbacks
            -- before this point are part of the same transition, not a new interruption.
            c.accepted_session_serial=startup.b378.session_change_serial
            startup.b378.current=c
            startup.b378_log("FRESH_HOST_OK",tostring(c.region).." | host="..tostring(hostName).." | readyPlayers="..c.ready_players.." | clickToReady="..tostring(math.max(0,c.session_ready_ms-c.session_click_ms)).."ms")
            startup.b378_set_phase("POSTLOAD_PAIR_READONLY",500,"Fresh local-host session ready after 5s; read-only region verification")
        elseif now>=tonumber(c.host_deadline_ms or (c.session_event_ms+startup.b378.session_request_timeout_ms)) then
            if c.session_attempts<startup.b378.max_session_attempts then
                startup.b378_set_phase("ROUTE_NEW_PUBLIC",5000,"Fresh session did not confirm local host; retrying")
            else
                startup.b378_retry_or_advance("fresh session never confirmed local Session Host")
            end
        end

    elseif phase=="POSTLOAD_PAIR_READONLY" then
        local region=tostring(c.region or "")
        local ov=startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
        local adv=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
        local ok=tostring(ov)==region and tostring(adv)==region
        startup.b373.pair_status=(ok and "SYNCED" or "MISMATCH").." | Override="..tostring(ov).." | Advertise="..tostring(adv)
        startup.b378_log("POSTLOAD_PAIR_READONLY",region.." | "..startup.b373.pair_status)
        if ok then
            startup.b378_set_phase("CHECK_ADVERTISE_SESSION",500,"Region pair survived fresh session; checking Advertise Session")
        else
            -- Do not repair region controls after the fresh session starts: that would
            -- contaminate the cold-start exposure window. Retry the region instead.
            startup.b378_retry_or_advance("region pair changed during fresh-session creation")
        end

    elseif phase=="CHECK_ADVERTISE_SESSION" then
        local state=startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
        if state==true then
            startup.b378_start_test_window()
        elseif state==false and c.advertise_repair_used~=true then
            local callOk,result=direct_call(startup.set_advertise_session,true,true)
            c.advertise_repair_used=true; startup.b378.current=c
            startup.b375.last_native_action="Advertise Session ON (B378 per-session one-shot repair)"
            startup.b375.last_native_action_ms=now
            startup.b378_log("ADVERTISE_SESSION_REPAIR",tostring(c.region).." | ok="..tostring(callOk and result~=false))
            if callOk and result~=false then startup.b378_set_phase("VERIFY_ADVERTISE_SESSION",5000,"Explicit OFF repaired once; verifying ON")
            else startup.b378_finish("Could not enable Advertise Session for "..tostring(c.region),true) end
        elseif state==nil then
            c.advertise_read_attempts=(tonumber(c.advertise_read_attempts or 0) or 0)+1; startup.b378.current=c
            if c.advertise_read_attempts<=startup.b378.advertise_read_max_attempts then startup.b378_set_phase("CHECK_ADVERTISE_SESSION",startup.b378.advertise_read_retry_ms,"Advertise Session read temporarily unknown")
            else startup.b378_finish("Advertise Session became unreadable for "..tostring(c.region),true) end
        else
            startup.b378_finish("Advertise Session remained OFF after its one allowed repair for "..tostring(c.region),true)
        end

    elseif phase=="VERIFY_ADVERTISE_SESSION" then
        local state=startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
        if state==true then startup.b378_start_test_window()
        elseif state==nil then startup.b378_set_phase("CHECK_ADVERTISE_SESSION",1000,"Advertise state unknown after repair; retrying read")
        else startup.b378_finish("Advertise Session did not stay ON for "..tostring(c.region),true) end

    elseif phase=="TESTING" then
        local seg=startup.b374.current_segment
        if type(seg)~="table" then startup.b378_finish("Internal segment missing during "..tostring(c.region),true); return end
        startup.b374_capture_segment(seg,now)
        local players=tonumber(startup.get_session_player_count and startup.get_session_player_count() or 0) or 0
        local isHost=startup.b378_local_is_session_host()
        if isHost~=true and now-(tonumber(c.test_started_ms or now) or now)>5000 then
            local finished=startup.b374_finish_segment("LOST_SESSION_HOST")
            if finished then startup.b378_record_result(finished,"LOST_SESSION_HOST") end
            startup.b378_retry_or_advance("lost local Session Host during timed window")
        elseif players>=startup.b378.target_players then
            if seg.targetReachedMs==nil then seg.targetReachedMs=math.max(0,now-(tonumber(seg.startedMs or now) or now)) end
            startup.b378_finish_current_test("TARGET_10_REACHED")
        elseif now>=tonumber(c.test_deadline_ms or 0) then
            startup.b378_finish_current_test("TIMEOUT_"..tostring(math.floor(startup.b378_timeout_ms()/60000)).."M")
        end

    elseif phase=="INTER_REGION_SETTLE" then
        startup.b378_begin_region(startup.b378.region_pos+1,false)

    elseif phase=="RETRY_SETTLE" then
        local retry=tonumber(c.retry_count or 1) or 1
        local index=startup.b378.region_pos
        startup.b378.begin_retry_count=retry
        startup.b378_begin_region(index,true)
        if startup.b378.current then startup.b378.current.retry_count=retry end
    end

    startup.b378_refresh_ui(now)
end

function startup.b374_tick()
    if startup.b378 and startup.b378.active==true then return startup.b378_tick_impl() end
    if startup.b378 and startup.b378.b377_tick_pre then return startup.b378.b377_tick_pre() end
end

function startup.b374_ui_lines()
    if startup.b378 and startup.b378.active==true then return startup.b378.cached_ui or {"B378 cold-start benchmark running"} end
    if startup.b377 and startup.b377.active==true and startup.b378 and startup.b378.b377_ui_pre then return startup.b378.b377_ui_pre() end
    local last=(tostring(startup.b378.summary_path or "")~="") and " | Last B378 report available" or ""
    return {
        "B378 cold-start benchmark: idle"..last,
        "One fresh New Public Session per region | target 10 players | timeout "..startup.b378_timeout_label(),
        "One button scans controls, randomizes region order, locks Override + Advertise Region before each fresh session, then handles session hopping and timing."
    }
end

-- Track only session-change timestamps/serials. This handler performs no feature
-- writes and lets the 1 Hz B378 state machine decide when a fresh session is usable.
if EventMgr and eLuaEvent and eLuaEvent.ON_SESSION_CHANGE and startup.b378.session_handler_installed~=true then
    startup.b378.session_handler_installed=true
    EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE,function()
        if startup and startup.b378 then
            startup.b378.session_change_serial=(tonumber(startup.b378.session_change_serial or 0) or 0)+1
            startup.b378.last_session_change_ms=startup.b378_now()
            if startup.b378.active==true then startup.b378_log("SESSION_CHANGE_EVENT","serial="..tostring(startup.b378.session_change_serial).." | phase="..tostring(startup.b378.phase)) end
        end
    end)
end

-- Include B378's dedicated cold-start CSV and checkpoint in the normal Support ZIP.
if startup.b378.support_wrapped~=true then
    startup.b378.support_wrapped=true
    startup.b378.collect_support_pre=startup.collect_support_files
    function startup.collect_support_files()
        local found=startup.b378.collect_support_pre and startup.b378.collect_support_pre() or {}
        local seen={}
        for _,e in ipairs(found or {}) do seen[(tostring(e.path or ""):gsub("/","\\"):lower()).."|"..tostring(e.name or ""):lower()]=true end
        local function add(path,name)
            path=tostring(path or ""); if path=="" or not startup.support_file_exists(path) then return end
            local outName="Startup/Diagnostics/Advertising/"..tostring(name)
            local key=path:gsub("/","\\"):lower().."|"..outName:lower(); if seen[key] then return end; seen[key]=true
            found[#found+1]={path=path,name=outName}
        end
        add(startup.b378.cold_csv_path,"B378_Cold_Start_Results.csv")
        add(startup.b378.raw_csv_path,"B378_Cold_Start_Raw.csv")
        add(startup.b378.summary_path,"B378_Cold_Start_Summary.txt")
        add(startup.b378.event_log_path,"B378_Cold_Start.log")
        add(startup.b378.checkpoint_path,"B378_Cold_Start_CHECKPOINT.txt")
        table.sort(found,function(a,b) return tostring(a.name):lower()<tostring(b.name):lower() end)
        return found
    end
end

if startup.add_combo then
    startup.add_combo("ColdStartTimeout378","Cold-Start Region Timeout","Maximum measured advertising time for each fresh region session. A region ends early as soon as the lobby reaches 10 total players.",{"15 Minutes","20 Minutes"},startup.s.coldStartTimeout378,function(selected)
        if startup.b378.active==true then return end
        local v=tostring(selected or "15 Minutes")
        if v~="15 Minutes" and v~="20 Minutes" then v="15 Minutes" end
        startup.s.coldStartTimeout378=v
        if startup.save_config then direct_call(startup.save_config,false) end
    end)
end

if startup.add_button then
    startup.add_button("RunColdStartBenchmark378","RUN B378 ONE-BUTTON COLD-START SCAN","Scans required Cherax controls, randomizes the 9 legal modern regions, serializes and verifies Override Region + Advertise Region before creating a fresh New Public Session for every region, read-only verifies the pair after load, verifies Advertise Session, and measures time to a 10-player lobby. Each region stops at 10 players or the selected 15/20-minute timeout.",function() startup.b378_start() end)
    startup.add_button("StopColdStartBenchmark378","STOP B378 COLD-START SCAN","Stops the current cold-start benchmark and preserves all completed/partial results collected so far.",function() if startup.b378.active==true then startup.b378_finish("Stopped by user",true) end end)
end

