startup.console_version="v1.0.18"
startup.build_number="2026.08.27.378"
startup.build_date="2026-08-27"
startup.build_label="B378 v1.0.16 Alpha - One-Button Cold-Start Region Benchmark"
startup.b378.loaded=true
if startup.log then startup.log("[Build 378] One-button cold-start region benchmark ready: fresh New Public Session per region, region pair locked before session creation and read-only verified after load, target 10 players, 15/20-minute timeout, randomized order, 1 Hz serialized controller.") end
if startup.support_log_event_quiet then startup.support_log_event_quiet("BUILD378_COLD_START_BENCHMARK_READY","one_button=true fresh_session_per_region=true target_players=10 timeout_min=15_or_20 override_pre_session=true advertise_pre_session=true postload_readonly_verify=true randomized_order=true driver_hz=1") end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- BUILD 379 — WRITE-ONLY ADVERTISE SESSION COMPATIBILITY
-- Cherax LE b8766 can expose Advertise Session with an explicit Toggle(bool) or
-- SetBoolValue(bool) setter while IsToggled/GetBoolValue remains unreadable.
-- B378 incorrectly rejected that valid layout. B379 treats it as a supported
-- write-only explicit control and never substitutes an OnClick/TriggerCallback.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.b379 = startup.b379 or {}
startup.b379.advertise_mode = startup.b379.advertise_mode or "UNKNOWN"
startup.b379.last_explicit_method = startup.b379.last_explicit_method or ""
startup.b379.last_explicit_ms = startup.b379.last_explicit_ms or 0
startup.b379.write_only_settle_ms = 4000

function startup.b379_resolve_advertise_capability()
    local feature, matched = startup.get_advertise_session_feature and startup.get_advertise_session_feature() or nil, nil
    if startup.get_advertise_session_feature then
        feature, matched = startup.get_advertise_session_feature()
    end
    if not feature then return nil, "UNAVAILABLE", "Advertise Session control unavailable" end

    local state = startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
    if state ~= nil then
        startup.b379.advertise_mode = "READABLE"
        return feature, "READABLE", "Advertise Session=" .. (state and "ON" or "OFF")
    end

    if feature.Toggle then
        startup.b379.advertise_mode = "WRITE_ONLY_EXPLICIT"
        startup.b379.last_explicit_method = "Toggle(true)"
        return feature, "WRITE_ONLY_EXPLICIT", "Advertise Session=WRITE_ONLY via Toggle(bool)"
    end
    if feature.SetBoolValue then
        startup.b379.advertise_mode = "WRITE_ONLY_EXPLICIT"
        startup.b379.last_explicit_method = "SetBoolValue(true)"
        return feature, "WRITE_ONLY_EXPLICIT", "Advertise Session=WRITE_ONLY via SetBoolValue(bool)"
    end

    startup.b379.advertise_mode = "UNSAFE_UNREADABLE"
    return feature, "UNSAFE_UNREADABLE", "Advertise Session unreadable and no explicit bool setter"
end

function startup.b379_explicit_advertise_on(reason)
    local feature, mode, detail = startup.b379_resolve_advertise_capability()
    if not feature then return false, detail end

    local state = startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
    if state == true then
        startup.b379.last_explicit_method = "none/already-on"
        if startup.b378_log then startup.b378_log("B379_ADVERTISE_ON", "already ON | " .. tostring(reason or "")) end
        return true, "ALREADY_ON"
    end

    local ok, err = false, nil
    if feature.Toggle then
        ok, err = pcall(function() feature:Toggle(true) end)
        startup.b379.last_explicit_method = "Toggle(true)"
    elseif feature.SetBoolValue then
        ok, err = pcall(function() feature:SetBoolValue(true) end)
        startup.b379.last_explicit_method = "SetBoolValue(true)"
    else
        -- Never blind-click an unreadable toggle. A callback-only feature is not safe.
        return false, "No explicit bool setter; callback-only write refused"
    end

    startup.b379.last_explicit_ms = startup.b378_now and startup.b378_now() or startup.now()
    if ok then
        startup.s.advertiseSessionEnabled = true
        startup.s.lastAdvertiseStatus = "Advertise Session ON (B379 explicit setter)"
        startup.b375.last_native_action = "Advertise Session ON (B379 " .. tostring(startup.b379.last_explicit_method) .. ")"
        startup.b375.last_native_action_ms = startup.b379.last_explicit_ms
    end
    if startup.b378_log then
        startup.b378_log("B379_ADVERTISE_ON", "mode=" .. tostring(mode) .. " | method=" .. tostring(startup.b379.last_explicit_method) .. " | ok=" .. tostring(ok) .. " | reason=" .. tostring(reason or "") .. (ok and "" or (" | error=" .. tostring(err))))
    end
    return ok, ok and tostring(startup.b379.last_explicit_method) or tostring(err)
end

-- Replace B378's overly strict preflight. All previous controls are still required,
-- but an unreadable Advertise Session is accepted only when Cherax exposes an
-- idempotent explicit bool setter.
function startup.b378_scan_preflight()
    local problems, details = {}, {}
    local sessionFeature = nil
    if startup.feature_hash and startup.feature_hash.SESSION_TYPE and startup.get_feature_by_hash_safe then
        sessionFeature = startup.get_feature_by_hash_safe(startup.feature_hash.SESSION_TYPE)
    end
    if not sessionFeature then
        problems[#problems+1] = "Session Type control unavailable"
    elseif not sessionFeature.GetListIndexByString or not sessionFeature.SetListIndexByString then
        problems[#problems+1] = "Session Type direct string API unavailable"
    else
        local ok, idx = pcall(function() return sessionFeature:GetListIndexByString("New Public Session") end)
        if not ok or idx == nil then problems[#problems+1] = "New Public Session route unavailable" else details[#details+1] = "New Public Session=OK" end
    end

    local startAvailable = false
    if startup.feature_hash and startup.feature_hash.START_SESSION and startup.get_feature_by_hash_safe then
        startAvailable = startup.get_feature_by_hash_safe(startup.feature_hash.START_SESSION) ~= nil
    end
    if not startAvailable and FeatureMgr and FeatureMgr.TriggerFeatureCallback then startAvailable = true end
    if not startAvailable then problems[#problems+1] = "Start Session action unavailable" else details[#details+1] = "Start Session=OK" end

    local ov = startup.b373_override_feature and startup.b373_override_feature() or nil
    if not ov or not ov.SetListIndex then problems[#problems+1] = "Override Region control unavailable" else details[#details+1] = "Override Region=OK" end

    local adv = startup.b368_region_feature and startup.b368_region_feature() or nil
    if not adv then problems[#problems+1] = "Advertise Region control unavailable" else details[#details+1] = "Advertise Region=OK" end

    local _, advMode, advDetail = startup.b379_resolve_advertise_capability()
    if advMode == "UNAVAILABLE" or advMode == "UNSAFE_UNREADABLE" then
        problems[#problems+1] = advDetail
    else
        details[#details+1] = advDetail
    end

    for _, region in ipairs(startup.b378.regions) do
        local idx = startup.b373 and startup.b373.region_index and startup.b373.region_index[region] or nil
        if idx == nil then problems[#problems+1] = "Missing region index: " .. tostring(region) end
    end

    if #problems > 0 then
        startup.b378.scan_status = "FAILED: " .. table.concat(problems, " | ")
        startup.b378_log("SCAN_FAIL", startup.b378.scan_status)
        return false, startup.b378.scan_status
    end
    startup.b378.scan_status = "PASS | " .. table.concat(details, " | ")
    startup.b378_log("SCAN_OK", startup.b378.scan_status)
    return true, startup.b378.scan_status
end

-- Wrap B378 start: in write-only mode, explicitly command Advertise Session ON once
-- before the first region. This is a true bool set, never an OnClick/callback guess.
startup.b379.b378_start_pre = startup.b378_start
function startup.b378_start()
    local result = startup.b379.b378_start_pre()
    if result ~= true then return result end

    local _, mode = startup.b379_resolve_advertise_capability()
    if mode == "WRITE_ONLY_EXPLICIT" then
        local ok, detail = startup.b379_explicit_advertise_on("initial benchmark ownership")
        if not ok then
            startup.b378_finish("Could not explicitly enable Advertise Session: " .. tostring(detail), true)
            return false
        end
        startup.b378_set_phase("B379_INITIAL_ADVERTISE_SETTLE", startup.b379.write_only_settle_ms, "Advertise Session explicitly commanded ON; settling before first region")
        startup.b378_checkpoint("B379 write-only initial advertise command")
    end
    return true
end
startup.b374_start = startup.b378_start

-- Wrap the B378 state machine only for the two new write-only compatibility phases.
-- Every other phase (region locking, New Public Session, host confirmation, timing,
-- retries, CSV/checkpoint handling) remains the proven B378 implementation.
startup.b379.b378_tick_pre = startup.b378_tick_impl
function startup.b378_tick_impl()
    if startup.b378.active ~= true then return end
    local now = startup.b378_now()
    local phase = tostring(startup.b378.phase or "")
    local _, mode = startup.b379_resolve_advertise_capability()

    if mode == "WRITE_ONLY_EXPLICIT" then
        if phase == "B379_INITIAL_ADVERTISE_SETTLE" then
            if now < (tonumber(startup.b378.next_action_ms or 0) or 0) then
                startup.b378_refresh_ui(now)
                return
            end
            startup.b378_set_phase("BEGIN_FIRST_REGION", 500, "Write-only Advertise Session command settled; starting cold-start sweep")
            startup.b378_refresh_ui(now)
            return
        end

        if phase == "CHECK_ADVERTISE_SESSION" then
            local c = startup.b378.current or {}
            if c.b379_advertise_commanded ~= true then
                local ok, detail = startup.b379_explicit_advertise_on("fresh session for " .. tostring(c.region or ""))
                c.b379_advertise_commanded = true
                c.advertise_repair_used = true
                startup.b378.current = c
                if not ok then
                    startup.b378_finish("Could not explicitly enable Advertise Session for " .. tostring(c.region or "") .. ": " .. tostring(detail), true)
                    return
                end
                startup.b378_log("B379_WRITE_ONLY_SESSION_ON", tostring(c.region or "") .. " | method=" .. tostring(detail))
                startup.b378_set_phase("B379_WRITE_ONLY_ADVERTISE_SETTLE", startup.b379.write_only_settle_ms, "Explicit Advertise Session ON sent once; settling before timer")
                startup.b378_refresh_ui(now)
                return
            end
            startup.b378_set_phase("B379_WRITE_ONLY_ADVERTISE_SETTLE", 500, "Advertise Session already explicitly commanded for this fresh session")
            startup.b378_refresh_ui(now)
            return
        end

        if phase == "B379_WRITE_ONLY_ADVERTISE_SETTLE" then
            if now < (tonumber(startup.b378.next_action_ms or 0) or 0) then
                startup.b378_refresh_ui(now)
                return
            end
            -- State is not readable on this Cherax layout. The explicit bool command
            -- was accepted and has settled; begin timing without any repeated writes.
            startup.b378_log("B379_WRITE_ONLY_SETTLED", tostring((startup.b378.current or {}).region or "") .. " | no readback available | starting timer")
            startup.b378_start_test_window()
            startup.b378_refresh_ui(now)
            return
        end
    end

    return startup.b379.b378_tick_pre()
end

-- Add compatibility facts to checkpoints without changing the existing file format.
startup.b379.checkpoint_pre = startup.b378_checkpoint
function startup.b378_checkpoint(reason)
    local ok = startup.b379.checkpoint_pre(reason)
    local path = tostring(startup.b378.checkpoint_path or "")
    if path ~= "" and io and io.open then
        local f = io.open(path, "a")
        if f then
            f:write("AdvertiseCapability=" .. tostring(startup.b379.advertise_mode or "UNKNOWN") .. "\n")
            f:write("AdvertiseExplicitMethod=" .. tostring(startup.b379.last_explicit_method or "") .. "\n")
            f:write("AdvertiseExplicitLastMs=" .. tostring(startup.b379.last_explicit_ms or 0) .. "\n")
            f:close()
        end
    end
    return ok
end

