-- ============================================================================
-- Build 380: Cold-start state-machine phase persistence + exclusive session owner
-- Fixes B379 stall when Advertise Session capability transitions from WRITE_ONLY
-- to READABLE after Toggle(true), and blocks background Start Session calls while
-- the cold-start benchmark owns session lifetime.
-- ============================================================================
startup.b380 = startup.b380 or {}
startup.b380.phase_interval_ms = 1000
startup.b380.blocked_start_calls = 0
startup.b380.last_blocked_start_ms = 0

-- Keep B379's current state machine underneath this compatibility guard.
startup.b380.tick_pre = startup.b378_tick_impl
function startup.b378_tick_impl()
    if startup.b378 and startup.b378.active == true then
        local phase = tostring(startup.b378.phase or "")
        if phase == "B379_INITIAL_ADVERTISE_SETTLE" or phase == "B379_WRITE_ONLY_ADVERTISE_SETTLE" then
            local now = startup.b378_now()
            local nextDriver = tonumber(startup.b378.next_driver_ms or 0) or 0
            if now < nextDriver then return end
            startup.b378.next_driver_ms = now + (tonumber(startup.b378.driver_interval_ms or startup.b380.phase_interval_ms) or startup.b380.phase_interval_ms)

            local nextCheckpoint = tonumber(startup.b378.next_checkpoint_ms or 0) or 0
            if now >= nextCheckpoint then
                startup.b378.next_checkpoint_ms = now + (tonumber(startup.b378.checkpoint_interval_ms or 30000) or 30000)
                startup.b378_checkpoint("B380 compatibility phase")
            end

            if now < (tonumber(startup.b378.next_action_ms or 0) or 0) then
                if startup.b378_refresh_ui then startup.b378_refresh_ui(now) end
                return
            end

            if phase == "B379_INITIAL_ADVERTISE_SETTLE" then
                -- IMPORTANT: advance by phase identity, never by the *current*
                -- Advertise Session capability. Cherax may change from unreadable
                -- to readable immediately after Toggle(true), which stalled B379.
                startup.b378_log("B380_INITIAL_SETTLE_COMPLETE", "Advertise Session command settled; capability may now be readable; beginning first region")
                startup.b378_set_phase("BEGIN_FIRST_REGION", 500, "Advertise Session settled; starting cold-start sweep")
                if startup.b378_refresh_ui then startup.b378_refresh_ui(now) end
                return
            end

            -- Per-session write-only settle. It is safe to begin the timer after
            -- the single explicit bool command even if capability changed meanwhile.
            local c = startup.b378.current or {}
            startup.b378_log("B380_SESSION_ADVERTISE_SETTLE_COMPLETE", tostring(c.region or "") .. " | proceeding after one-shot Advertise Session command")
            startup.b378_start_test_window()
            if startup.b378_refresh_ui then startup.b378_refresh_ui(now) end
            return
        end
    end
    return startup.b380.tick_pre()
end

-- Benchmark owns Start Session for its whole run. Startup's delayed Auto Start
-- Online worker and other background callers must not create an unscheduled hop.
startup.b380.start_session_pre = startup.start_session
function startup.start_session(...)
    if startup.b378 and startup.b378.active == true then
        startup.b380.blocked_start_calls = (tonumber(startup.b380.blocked_start_calls or 0) or 0) + 1
        startup.b380.last_blocked_start_ms = startup.b378_now and startup.b378_now() or 0
        if startup.b378_log then
            startup.b378_log("B380_BACKGROUND_START_BLOCKED", "startup.start_session denied while cold-start benchmark owns session lifetime | phase=" .. tostring(startup.b378.phase or ""))
        end
        return false
    end
    return startup.b380.start_session_pre(...)
end

-- Also protect the raw Start Session action. The benchmark is allowed through
-- only in its serialized CLICK_NEW_PUBLIC phase.
startup.b380.click_start_pre = startup.click_start_session_feature
function startup.click_start_session_feature(...)
    if startup.b378 and startup.b378.active == true then
        local phase = tostring(startup.b378.phase or "")
        if phase ~= "CLICK_NEW_PUBLIC" then
            startup.b380.blocked_start_calls = (tonumber(startup.b380.blocked_start_calls or 0) or 0) + 1
            startup.b380.last_blocked_start_ms = startup.b378_now and startup.b378_now() or 0
            if startup.b378_log then
                startup.b378_log("B380_RAW_START_BLOCKED", "Start Session action denied outside CLICK_NEW_PUBLIC | phase=" .. phase)
            end
            return false
        end
    end
    return startup.b380.click_start_pre(...)
end

-- Enrich checkpoint with the session-ownership guard state without changing the
-- existing B378/B379 parser-compatible fields.
startup.b380.checkpoint_pre = startup.b378_checkpoint
function startup.b378_checkpoint(reason)
    local ok = startup.b380.checkpoint_pre(reason)
    local path = tostring(startup.b378 and startup.b378.checkpoint_path or "")
    if path ~= "" and io and io.open then
        local f = io.open(path, "a")
        if f then
            f:write("B380ExclusiveSessionOwner=" .. tostring(startup.b378 and startup.b378.active == true) .. "\\n")
            f:write("B380BlockedStartCalls=" .. tostring(startup.b380.blocked_start_calls or 0) .. "\\n")
            f:write("B380LastBlockedStartMs=" .. tostring(startup.b380.last_blocked_start_ms or 0) .. "\\n")
            f:close()
        end
    end
    return ok
end

