-- Foreground mode may run from ON_POST_PRESENT with no active ImGui window.
-- Restrict it to foreground draw-list primitives only. In particular, never call
-- SetWindowFontScale/GetFontSize/CalcTextSize/AddText/AddRectFilled here; the first
-- three depend on current ImGui window/font state and can summon Debug##Default.
startup.session_activity_foreground_capable = function()
    if startup.session_activity.rendererRuntime.foregroundFaulted == true then return false end
    if not EventMgr or not eLuaEvent or not eLuaEvent.ON_POST_PRESENT then return false end
    if not ImGui or not ImGui.GetDisplaySize then return false end
    return ImGui.FgAddText ~= nil and ImGui.FgAddRectFilled ~= nil
end

startup.session_activity_foreground_rect = function(displayWidth, displayHeight, x, y, width, height, r, g, b, a)
    if not ImGui or not ImGui.FgAddRectFilled then return false end
    local x1 = (tonumber(x or 0) or 0) * displayWidth
    local y1 = (tonumber(y or 0) or 0) * displayHeight
    local x2 = x1 + ((tonumber(width or 0) or 0) * displayWidth)
    local y2 = y1 + ((tonumber(height or 0) or 0) * displayHeight)
    local ok = direct_call(ImGui.FgAddRectFilled, x1, y1, x2, y2,
        math.floor(tonumber(r or 0) or 0), math.floor(tonumber(g or 0) or 0),
        math.floor(tonumber(b or 0) or 0), math.floor(tonumber(a or 0) or 0), 0.0, 0)
    return ok == true
end

startup.session_activity_foreground_text = function(displayWidth, displayHeight, text, x, y, scale, r, g, b, a)
    if not ImGui or not ImGui.FgAddText then return false end
    local content = tostring(text or "")
    if content == "" then return true end
    local px = (tonumber(x or 0) or 0) * displayWidth
    local py = (tonumber(y or 0) or 0) * displayHeight
    local visualScale = startup.clamp_float((tonumber(scale or 0.42) or 0.42) / 0.44, 0.55, 1.60)

    -- FgAddText uses Cherax's active foreground font. Estimate vertical centering
    -- numerically rather than touching ImGui's current-window font state.
    local estimatedGlyphHeight = 16.0
    local rowHeightPx = startup.session_activity_native_slot_height(scale) * displayHeight
    py = py + math.max(0, (rowHeightPx - estimatedGlyphHeight) * 0.50)

    local alpha = math.max(0, math.min(255, math.floor(tonumber(a or 255) or 255)))
    local shadowAlpha = math.floor(alpha * 0.84)
    local function draw_at(dx, dy, rr, gg, bb, aa)
        local ok = direct_call(ImGui.FgAddText, px + dx, py + dy,
            math.floor(rr or 0), math.floor(gg or 0), math.floor(bb or 0), math.floor(aa or 0), content)
        return ok == true
    end

    local outline = startup.clamp_float(1.05 * visualScale, 0.85, 1.55)
    draw_at(outline, outline, 0, 0, 0, shadowAlpha)
    draw_at(-outline, outline, 0, 0, 0, shadowAlpha)
    draw_at(outline, -outline, 0, 0, 0, shadowAlpha)
    draw_at(-outline, -outline, 0, 0, 0, shadowAlpha)

    local rr = math.floor(tonumber(r or 255) or 255)
    local gg = math.floor(tonumber(g or 255) or 255)
    local bb = math.floor(tonumber(b or 255) or 255)
    local edge = startup.clamp_float(0.38 * visualScale, 0.25, 0.62)
    local edgeAlpha = math.floor(alpha * 0.88)
    draw_at(-edge, 0, rr, gg, bb, edgeAlpha)
    draw_at(edge, 0, rr, gg, bb, edgeAlpha)
    draw_at(0, -edge, rr, gg, bb, edgeAlpha)
    draw_at(0, edge, rr, gg, bb, edgeAlpha)
    return draw_at(0, 0, rr, gg, bb, alpha)
end

startup.session_activity_foreground_measure_text = function(displayWidth, text, scale)
    displayWidth = tonumber(displayWidth or 0) or 0
    if displayWidth <= 0 then return 0 end
    local content = tostring(text or "")
    if content == "" then return 0 end
    local visualScale = startup.clamp_float((tonumber(scale or 0.42) or 0.42) / 0.44, 0.55, 1.60)
    -- Pure numeric approximation: no current-window ImGui APIs.
    return (math.max(1, string.len(content)) * 8.2 * visualScale) / displayWidth
end

-- Keep the user-facing custom activity features enabled, but force every retired
-- native integration control OFF in both runtime state and visible feature state.
function startup.b381_apply_activity_debug_guard()
    startup.s.sessionActivityUseNativeFeed = false
    startup.s.sessionActivityFollowNativeNotifications = false
