        if ch:match("[MW@#%%&]") then units = units + 1.16
        elseif ch:match("[A-Z]") then units = units + 0.96
        elseif ch:match("[a-z]") then units = units + 0.78
        elseif ch:match("[0-9]") then units = units + 0.78
        elseif ch == "_" then units = units + 0.84
        elseif ch == " " then units = units + 0.40
        elseif ch:match("[%.:,;!|]") then units = units + 0.32
