-- ============================================================================
-- Build 384: Activity Text Centering Fix
-- Fine-tunes the foreground join/leave card message: center the blue/grey text
-- within the black box, reduce apparent font weight, and make the text slightly
-- smaller while preserving the Build 381 Debug-window fix.
-- ============================================================================
startup.b384 = startup.b384 or {}

startup.session_activity_foreground_measure_text = function(displayWidth, text, scale)
    displayWidth = tonumber(displayWidth or 0) or 0
    if displayWidth <= 0 then return 0 end
    local s = tostring(text or "")
    if s == "" then return 0 end
    local visualScale = startup.clamp_float((tonumber(scale or 0.42) or 0.42) / 0.44, 0.50, 1.50)
    local units = 0
    for i = 1, #s do
        local ch = s:sub(i, i)
        if ch:match("[MW@#%%&]") then units = units + 1.12
        elseif ch:match("[A-Z]") then units = units + 0.94
        elseif ch:match("[a-z0-9]") then units = units + 0.76
        elseif ch == "_" then units = units + 0.82
        elseif ch == " " then units = units + 0.40
        elseif ch:match("[%.:,;!|]") then units = units + 0.31
        else units = units + 0.66 end
    end
    local px = units * (7.55 * visualScale)
    return px / displayWidth
end

startup.session_activity_foreground_text = function(displayWidth, displayHeight, text, x, y, scale, r, g, b, a)
    if not ImGui or not ImGui.FgAddText then return false end
    local content = tostring(text or "")
    if content == "" then return true end
    local px = (tonumber(x or 0) or 0) * displayWidth
    local py = (tonumber(y or 0) or 0) * displayHeight
    local visualScale = startup.clamp_float((tonumber(scale or 0.42) or 0.42) / 0.44, 0.50, 1.50)

    -- Center more confidently inside the black activity card.
    local rowHeightPx = startup.session_activity_native_slot_height(scale) * displayHeight
    local estimatedGlyphHeight = 17.6 * visualScale
    py = py + math.max(0, (rowHeightPx - estimatedGlyphHeight) * 0.68)

    local alpha = math.max(0, math.min(255, math.floor(tonumber(a or 255) or 255)))
    local shadowAlpha = math.floor(alpha * 0.68)
    local function draw_at(dx, dy, rr, gg, bb, aa)
        local ok = direct_call(ImGui.FgAddText, px + dx, py + dy,
            math.floor(rr or 0), math.floor(gg or 0), math.floor(bb or 0), math.floor(aa or 0), content)
        return ok == true
    end

    local outline = startup.clamp_float(0.72 * visualScale, 0.55, 1.00)
    draw_at(outline, outline, 0, 0, 0, shadowAlpha)
    draw_at(-outline, outline, 0, 0, 0, shadowAlpha)
    draw_at(outline, -outline, 0, 0, 0, shadowAlpha)
    draw_at(-outline, -outline, 0, 0, 0, shadowAlpha)

    return draw_at(0, 0,
        math.floor(tonumber(r or 255) or 255),
        math.floor(tonumber(g or 255) or 255),
        math.floor(tonumber(b or 255) or 255),
        alpha)
end

function startup.render_session_activity_feed(x, bottomY, scale, textAlpha, forcedRenderer)
    if not startup.s.showSessionActivityHud then return 0 end
    if startup.s.sessionActivityUseNativeFeed ~= false then return 0 end
    startup.session_activity_prune()
    local entries = startup.session_activity.entries or {}
    if #entries == 0 then return 0 end

    local resolvedRenderer = startup.session_activity_resolve_renderer()
    if forcedRenderer == nil and resolvedRenderer == "foreground" then return 0 end
    if forcedRenderer ~= nil and tostring(forcedRenderer) ~= resolvedRenderer then return 0 end
    local usingForeground = resolvedRenderer == "foreground"
    local usingAfterFade = resolvedRenderer == "after_fade"
    local displayWidth, displayHeight
    if usingForeground then
        displayWidth, displayHeight = startup.session_activity_foreground_display_size()
        if not displayWidth or not displayHeight then return 0 end
    elseif usingAfterFade then
        startup.session_activity_set_gta_draw_order(8)
    end

    local function drawRect(px, py, pw, ph, r, g, b, a)
        if usingForeground then
            return startup.session_activity_foreground_rect(displayWidth, displayHeight, px, py, pw, ph, r, g, b, a)
        end
        return startup.draw_hud_rect(px, py, pw, ph, r, g, b, a)
    end
    local function drawText(text, px, py, pscale, r, g, b, a, font)
        if usingForeground then
            return startup.session_activity_foreground_text(displayWidth, displayHeight, text, px, py, pscale, r, g, b, a)
        end
        return startup.draw_hud_text(text, px, py, pscale, r, g, b, a, font)
    end

    local now = startup.now()
    local renderScale = tonumber(scale or 0.42) or 0.42
    local nativeReservedHeight = startup.session_activity_native_reserved_height(renderScale)
    local baseBottomY = math.max(0.12, tonumber(bottomY or 0.806) or 0.806)
    local enterMs = math.max(100, tonumber(startup.s.sessionActivityEnterMs or 420) or 420)
    local fadeMs = math.max(200, tonumber(startup.s.sessionActivityFadeMs or 900) or 900)
    local boxAlpha = math.max(0, math.min(190, tonumber(startup.s.sessionActivityBoxAlpha or 60) or 60))
    local animated = startup.s.sessionActivityAnimated ~= false
    local horizontalScale = startup.get_hud_horizontal_scale()
    local gap = 0.0030
    local targets = {}
    local effectiveBottomY = baseBottomY
    local cursorBottom = effectiveBottomY
    local usingNativeSlotBridge = startup.s.sessionActivityNativeSlotBridge ~= false
        and startup.s.sessionActivityPlacementMode ~= "Above Session HUD Stack"
    local trackingNativeSlots = usingNativeSlotBridge and startup.s.sessionActivityTrackNativeSlots ~= false
    if trackingNativeSlots then startup.session_activity_snap_native_feed(true) end

    if usingNativeSlotBridge and nativeReservedHeight > 0 then
        local timeline = {}
        if startup.s.sessionActivityFollowNativeNotifications ~= false then
            for index, reservation in ipairs(startup.session_activity.nativeReservations or {}) do
                timeline[#timeline + 1] = {
                    kind = "native",
                    createdMs = tonumber(reservation.createdMs or 0) or 0,
                    orderSerial = tonumber(reservation.orderSerial or 0) or 0,
                    sequence = index,
                    height = tonumber(reservation.height or 0) or 0.060
                }
            end
        end
        for index, entry in ipairs(entries) do
            local slots = math.max(1, tonumber(entry.nativeAnchorSlots or startup.session_activity_native_anchor_slot_count(entry)) or 1)
            local slotHeight = startup.session_activity_native_slot_height(renderScale)
            timeline[#timeline + 1] = {
                kind = "custom",
                createdMs = tonumber(entry.nativeAnchorCreatedMs or entry.createdMs or 0) or 0,
                orderSerial = tonumber(entry.nativeAnchorOrder or 0) or 0,
                sequence = 100000 + (tonumber(entry.id or index) or index),
                index = index,
                slots = slots,
                rowHeight = slotHeight,
                height = (slotHeight * slots) + (gap * math.max(0, slots - 1))
            }
        end
        table.sort(timeline, function(a, b)
            local aOrder = tonumber(a.orderSerial or 0) or 0
            local bOrder = tonumber(b.orderSerial or 0) or 0
            if aOrder > 0 and bOrder > 0 and aOrder ~= bOrder then return aOrder < bOrder end
            if a.createdMs == b.createdMs then return a.sequence < b.sequence end
            return a.createdMs < b.createdMs
        end)

        local totalHeight = 0
        for timelineIndex, item in ipairs(timeline) do
            totalHeight = totalHeight + item.height
            if timelineIndex < #timeline then totalHeight = totalHeight + 0.006 end
        end
        local cursorTop = math.max(0.022, baseBottomY - totalHeight)
        local stackTop = cursorTop
        for _, item in ipairs(timeline) do
            if item.kind == "custom" then
                targets[item.index] = {
                    y = stackTop,
                    h = item.height,
                    rowHeight = item.rowHeight,
                    slots = item.slots
                }
            end
            stackTop = stackTop + item.height + 0.006
        end
        effectiveBottomY = baseBottomY
        cursorBottom = stackTop
    else
        local function calculate_needed_height(testScale, testGap)
            local total = 0
            for _, entry in ipairs(entries) do
                total = total + startup.session_activity_entry_height(entry, testScale) + testGap
            end
            return total
        end

        local neededHeight = calculate_needed_height(renderScale, gap)
        local nativeStartY = 0.045
        local nativeBottomY = nativeReservedHeight > 0 and (nativeStartY + nativeReservedHeight) or 0
        if nativeBottomY > 0 then
            effectiveBottomY = math.max(baseBottomY, nativeBottomY + neededHeight + 0.011)
            effectiveBottomY = math.min(0.95, effectiveBottomY)
        end

        local availableHeight
        if nativeBottomY > 0 then
            availableHeight = math.max(0.08, 0.95 - nativeBottomY - 0.011)
        else
            availableHeight = math.max(0.10, effectiveBottomY - 0.025)
        end
        if neededHeight > availableHeight and neededHeight > 0 then
            local ratio = availableHeight / neededHeight
            renderScale = math.max(0.22, renderScale * ratio)
            gap = math.max(0.001, gap * ratio)
            neededHeight = calculate_needed_height(renderScale, gap)
            if nativeBottomY > 0 then
                effectiveBottomY = math.min(0.95, nativeBottomY + neededHeight + 0.011)
            end
        end

        cursorBottom = effectiveBottomY
        for i = #entries, 1, -1 do
            local entry = entries[i]
            local height = startup.session_activity_entry_height(entry, renderScale)
            local targetTop = cursorBottom - height
            targets[i] = { y = targetTop, h = height }
            cursorBottom = targetTop - gap
        end
    end

    local minBoxWidth = 0.090 * horizontalScale
    local maxBoxWidth = 0.166 * horizontalScale

    for i, entry in ipairs(entries) do
        local target = targets[i]
        local age = math.max(0, now - (entry.createdMs or now))
        local remain = math.max(0, (entry.expiresMs or now) - now)
        local enterT = animated and startup.ease_out_cubic(age / enterMs) or 1.0
        local fadeT = remain < fadeMs and startup.clamp01(remain / fadeMs) or 1.0
        if animated and remain < fadeMs then fadeT = 1.0 - startup.ease_in_cubic(1.0 - fadeT) end
        local opacity = math.min(enterT, fadeT)

        if entry.renderY == nil then
            entry.renderY = target.y + (animated and 0.010 or 0.0)
        end
        if animated then
            local delta = target.y - entry.renderY
            if trackingNativeSlots and math.abs(delta) > 0.075 then
                entry.renderY = target.y
            else
                entry.renderY = entry.renderY + (delta * (trackingNativeSlots and 0.48 or 0.22))
            end
        else
            entry.renderY = target.y
        end

        local primary, secondary, color = startup.session_activity_content(entry)
        local primaryScale = usingForeground and (renderScale * 0.91) or renderScale
        local secondaryScale = usingForeground and (renderScale * 0.84) or (renderScale * 0.90)
        local primaryWidth = usingForeground and startup.session_activity_foreground_measure_text(displayWidth, primary, primaryScale) or nil
        local secondaryWidth = (secondary ~= "" and usingForeground) and startup.session_activity_foreground_measure_text(displayWidth, secondary, secondaryScale) or 0
        local computedWidth = 0.016 + math.max(primaryWidth or 0.0, secondaryWidth or 0.0)
        if not usingForeground then
            local longestText = math.max(string.len(primary or ""), string.len(secondary or ""), string.len("Connected Players: 28"))
            computedWidth = 0.054 + (longestText * ((0.00285 + (renderScale * 0.00118)) * horizontalScale))
        end
        local boxWidth = math.max(minBoxWidth, math.min(maxBoxWidth, computedWidth))
        local slideX = animated and ((1.0 - enterT) * (-0.008 * horizontalScale)) or 0.0
        if animated and remain < fadeMs then slideX = slideX + ((1.0 - fadeT) * (-0.007 * horizontalScale)) end
        local boxX = x - (0.0005 * horizontalScale) + slideX
        local drawAlpha = math.floor((tonumber(textAlpha or 200) or 200) * opacity)
        local bgAlpha = math.floor(math.min(boxAlpha, 104) * opacity)
        if usingNativeSlotBridge and entry.nativeAnchorReady == true then
            bgAlpha = usingForeground and 0 or math.floor(math.min(boxAlpha, 70) * opacity)
        end

        local primaryHeight = tonumber(target.rowHeight or target.h) or target.h
        if bgAlpha > 0 then drawRect(boxX, entry.renderY, boxWidth, primaryHeight, 5, 5, 8, bgAlpha) end
        local accentRatio = startup.clamp_float(tonumber(startup.s.sessionActivityAccentHeightRatio or 1.00) or 1.00, 0.15, 1.00)
        local accentHeight = startup.clamp_float(primaryHeight * math.min(accentRatio, 0.94), 0.008, 0.034)
        local accentInset = math.max(0, (primaryHeight - accentHeight) * 0.50)
        local accentWidth = 0.00108 * horizontalScale
        drawRect(boxX, entry.renderY + accentInset, accentWidth, accentHeight, color[1], color[2], color[3], math.floor(216 * opacity))

        -- Use the box top directly; foreground_text now centers vertically.
        local primaryTextX = boxX + (0.0065 * horizontalScale)
        local primaryTextY = entry.renderY
        local boldName, regularSuffix = startup.session_activity_primary_segments(entry)
        local primaryDrawn
        if usingForeground and boldName ~= nil then
            primaryDrawn = drawText(primary, primaryTextX, primaryTextY, primaryScale,
                color[1], color[2], color[3], drawAlpha, 4)
            -- Light name emphasis only: one soft overlay instead of heavy double-bold.
            local overlayA = math.floor(math.min(255, drawAlpha) * 0.48)
            local overlay = drawText(boldName, primaryTextX, primaryTextY, primaryScale,
                color[1], color[2], color[3], overlayA, 4)
            primaryDrawn = (primaryDrawn == true) or (overlay == true)
        elseif boldName ~= nil then
            primaryDrawn = drawText("~h~" .. boldName .. "~h~" .. regularSuffix,
                primaryTextX, primaryTextY, primaryScale, color[1], color[2], color[3], drawAlpha, 4)
        else
            primaryDrawn = drawText(primary, primaryTextX, primaryTextY, primaryScale,
                color[1], color[2], color[3], drawAlpha, 4)
        end
        if usingForeground and primaryDrawn ~= true then error("Cherax foreground text draw failed") end
        if secondary ~= "" then
            if usingNativeSlotBridge then
                local secondaryY = entry.renderY + primaryHeight + gap
                if bgAlpha > 0 then drawRect(boxX, secondaryY, boxWidth, primaryHeight, 5, 5, 8, bgAlpha) end
                local secondaryAccentHeight = startup.clamp_float(primaryHeight * math.min(accentRatio, 0.94), 0.008, 0.034)
                local secondaryInset = math.max(0, (primaryHeight - secondaryAccentHeight) * 0.50)
                drawRect(boxX, secondaryY + secondaryInset, accentWidth, secondaryAccentHeight, 255, 185, 80, math.floor(216 * opacity))
                local secondaryDrawn = drawText(secondary, boxX + (0.0065 * horizontalScale), secondaryY, secondaryScale, 255, 185, 80, drawAlpha, 4)
                if usingForeground and secondaryDrawn ~= true then error("Cherax foreground secondary text draw failed") end
            else
