-- ============================================================================
-- Build 385: Scalable Activity Text
-- The Build 381 Debug-window fix revealed that Cherax FgAddText uses a fixed
-- active font size; Activity Feed Scale could no longer truly resize glyphs.
-- B385 routes activity cards through GTA's scalable text path, keeps all
-- window-scoped ImGui calls out of the activity renderer, centers text inside
-- each black row, and uses only a very light name-emphasis pass.
-- ============================================================================
startup.b385 = startup.b385 or {}

-- Force the activity feed away from the fixed-size Cherax foreground font.
-- This also guarantees the Build 381 Debug-window fix remains active.
startup.session_activity_foreground_capable = function()
    return false
end

startup.session_activity_resolve_renderer = function()
    startup.session_activity.rendererRuntime.lastResolved = "after_fade"
    return "after_fade"
end

-- Native GTA text dedicated to the activity feed. Unlike draw_hud_text(), this
-- remains available even if the Session Info HUD itself is disabled.
function startup.b385_draw_activity_text(text, x, y, scale, r, g, b, a, font, shadow)
    if not Natives or not Natives.InvokeVoid then return false end
    text = tostring(text or "")
    if text == "" then return true end
    x = tonumber(x or 0) or 0
    y = tonumber(y or 0) or 0
    scale = startup.clamp_float(tonumber(scale or 0.32) or 0.32, 0.12, 0.70)
    r = math.floor(tonumber(r or 255) or 255)
    g = math.floor(tonumber(g or 255) or 255)
    b = math.floor(tonumber(b or 255) or 255)
    a = math.floor(tonumber(a or 200) or 200)
    font = tonumber(font or 4) or 4

    local ok = direct_call(function()
        Natives.InvokeVoid(0x66E0276CC5F6B9DA, font)
        Natives.InvokeVoid(0x07C837F9A01C34C9, 0.0, scale)
        Natives.InvokeVoid(0xBE6B23FFA53FB442, r, g, b, a)
        Natives.InvokeVoid(0xC02F4DBFB51D988B, false)
        if shadow ~= false then
            Natives.InvokeVoid(0x1CA3E9EAC9D93E5E)
            Natives.InvokeVoid(0x2513DFB0FB8400FE)
        end
        Natives.InvokeVoid(0x25FBB336DF1804CB, "STRING")
        Natives.InvokeVoid(0x6C188BE134E074AA, text)
        Natives.InvokeVoid(0xCD015E5BB0D96A57, x, y)
    end)
    return ok == true
end

function startup.b385_draw_activity_rect(x, y, width, height, r, g, b, a)
    if not Natives or not Natives.InvokeVoid then return false end
    x = tonumber(x or 0) or 0
    y = tonumber(y or 0) or 0
    width = math.max(0.001, tonumber(width or 0.15) or 0.15)
    height = math.max(0.001, tonumber(height or 0.05) or 0.05)
    local ok = direct_call(function()
        Natives.InvokeVoid(0x3A618A217E5154F0,
            x + (width * 0.5), y + (height * 0.5), width, height,
            math.floor(tonumber(r or 0) or 0), math.floor(tonumber(g or 0) or 0),
            math.floor(tonumber(b or 0) or 0), math.floor(tonumber(a or 150) or 150), false)
    end)
    return ok == true
end

function startup.b385_estimate_text_width(text, scale)
    local s = tostring(text or "")
    local units = 0
    for i = 1, #s do
        local ch = s:sub(i, i)
        if ch:match("[MW@#%%&]") then units = units + 1.18
        elseif ch:match("[A-Z]") then units = units + 0.96
        elseif ch:match("[a-z0-9]") then units = units + 0.78
        elseif ch == "_" then units = units + 0.86
        elseif ch == " " then units = units + 0.43
        elseif ch:match("[%.:,;!|]") then units = units + 0.34
        else units = units + 0.70 end
    end
    return units * (tonumber(scale or 0.32) or 0.32) * 0.00240
end

function startup.render_session_activity_feed(x, bottomY, scale, textAlpha, forcedRenderer)
    if not startup.s.showSessionActivityHud then return 0 end
    if startup.s.sessionActivityUseNativeFeed ~= false then return 0 end
    if forcedRenderer ~= nil and tostring(forcedRenderer) ~= "after_fade" then return 0 end

    startup.session_activity_prune()
    local entries = startup.session_activity.entries or {}
    if #entries == 0 then return 0 end

    local now = startup.now()
    local renderScale = startup.clamp_float(tonumber(scale or 0.38) or 0.38, 0.20, 0.70)
    local primaryScale = startup.clamp_float(renderScale * 0.84, 0.17, 0.56)
    local secondaryScale = startup.clamp_float(renderScale * 0.77, 0.16, 0.52)
    local baseBottomY = math.max(0.12, tonumber(bottomY or 0.806) or 0.806)
    local enterMs = math.max(100, tonumber(startup.s.sessionActivityEnterMs or 420) or 420)
    local fadeMs = math.max(200, tonumber(startup.s.sessionActivityFadeMs or 900) or 900)
    local boxAlpha = math.max(0, math.min(230, tonumber(startup.s.sessionActivityBoxAlpha or 60) or 60))
    local animated = startup.s.sessionActivityAnimated ~= false
    local horizontalScale = startup.get_hud_horizontal_scale()
    local boxScale = startup.clamp_float(tonumber(startup.s.sessionActivityBoxScale or 0.85) or 0.85, 0.60, 1.30)
    local gap = 0.004 * boxScale
    local targets = {}
    local effectiveBottomY = baseBottomY
    local cursorBottom = effectiveBottomY

    -- B387: box geometry is independent from Activity Feed Scale. Text retains
    -- renderScale/primaryScale; only row footprint and padding follow boxScale.
    local primaryTextMinH = (primaryScale * 0.073) + 0.010
    local secondaryTextMinH = (secondaryScale * 0.073) + 0.009
    local primaryBaseH = startup.clamp_float(0.036 + (renderScale * 0.045), 0.046, 0.064)
    local secondaryBaseH = startup.clamp_float(primaryBaseH * 0.93, 0.043, 0.060)
    local primaryRowHeight = startup.clamp_float(math.max(primaryTextMinH, primaryBaseH * boxScale), 0.034, 0.080)
    local secondaryRowHeight = startup.clamp_float(math.max(secondaryTextMinH, secondaryBaseH * boxScale), 0.032, 0.076)

    for i = #entries, 1, -1 do
        local entry = entries[i]
        local _, secondary = startup.session_activity_content(entry)
        local height = primaryRowHeight
        if tostring(secondary or "") ~= "" then height = height + gap + secondaryRowHeight end
        local targetTop = cursorBottom - height
        targets[i] = {y=targetTop, h=height, primaryH=primaryRowHeight, secondaryH=secondaryRowHeight}
        cursorBottom = targetTop - gap
    end

    startup.session_activity_set_gta_draw_order(8)

    for i, entry in ipairs(entries) do
        local target = targets[i]
        local age = math.max(0, now - (entry.createdMs or now))
        local remain = math.max(0, (entry.expiresMs or now) - now)
        local enterT = animated and startup.ease_out_cubic(age / enterMs) or 1.0
        local fadeT = remain < fadeMs and startup.clamp01(remain / fadeMs) or 1.0
        if animated and remain < fadeMs then fadeT = 1.0 - startup.ease_in_cubic(1.0 - fadeT) end
        local opacity = math.min(enterT, fadeT)

        if entry.renderY == nil then entry.renderY = target.y + (animated and 0.010 or 0) end
        if animated then
            entry.renderY = entry.renderY + ((target.y - entry.renderY) * 0.22)
        else
            entry.renderY = target.y
        end

        local primary, secondary, color = startup.session_activity_content(entry)
        primary = tostring(primary or "")
        secondary = tostring(secondary or "")
        local primaryWidth = startup.b385_estimate_text_width(primary, primaryScale)
        local secondaryWidth = secondary ~= "" and startup.b385_estimate_text_width(secondary, secondaryScale) or 0
        local horizontalPadding = 0.020 * horizontalScale * boxScale
        local minBoxWidth = math.max(0.075 * horizontalScale, math.max(primaryWidth, secondaryWidth) + (0.010 * horizontalScale * boxScale))
        local maxBoxWidth = 0.230 * horizontalScale
        local boxWidth = startup.clamp_float(math.max(primaryWidth, secondaryWidth) + horizontalPadding, minBoxWidth, maxBoxWidth)
        local slideX = animated and ((1.0 - enterT) * (-0.009 * horizontalScale)) or 0
        if animated and remain < fadeMs then slideX = slideX + ((1.0 - fadeT) * (-0.007 * horizontalScale)) end
        local boxX = x + slideX
        local drawAlpha = math.floor((tonumber(textAlpha or 200) or 200) * opacity)
        local bgAlpha = math.floor(boxAlpha * opacity)
        local accentWidth = 0.00115 * horizontalScale
        local accentRatio = startup.clamp_float(tonumber(startup.s.sessionActivityAccentHeightRatio or 1.0) or 1.0, 0.15, 1.0)
        local userYOffset = startup.clamp_float(tonumber(startup.s.sessionActivityTextYOffset or 0) or 0, -0.030, 0.040)

        -- Primary black card.
        startup.b385_draw_activity_rect(boxX, entry.renderY, boxWidth, target.primaryH, 5, 5, 8, bgAlpha)
        local accentH = target.primaryH * accentRatio
        startup.b385_draw_activity_rect(boxX, entry.renderY + ((target.primaryH - accentH) * 0.5), accentWidth, accentH,
            color[1], color[2], color[3], math.floor(220 * opacity))

        -- Native GTA font height estimate. This makes the Y slider additive while
        -- keeping 0.000 visually centered by default.
        local estimatedTextH = primaryScale * 0.073
        local primaryTextY = entry.renderY + math.max(0, (target.primaryH - estimatedTextH) * 0.50) - 0.0015 + userYOffset
        local primaryTextX = boxX + (0.0075 * horizontalScale)
        local boldName = select(1, startup.session_activity_primary_segments(entry))

        startup.b385_draw_activity_text(primary, primaryTextX, primaryTextY, primaryScale,
            color[1], color[2], color[3], drawAlpha, 4, true)

        -- Very light name emphasis only. This is intentionally much weaker than
        -- GTA's ~h~ modifier and much weaker than B383/B384's double-pass bold.
        if boldName ~= nil and tostring(boldName) ~= "" then
            startup.b385_draw_activity_text(tostring(boldName), primaryTextX, primaryTextY, primaryScale,
                color[1], color[2], color[3], math.floor(drawAlpha * 0.20), 4, false)
        end

        if secondary ~= "" then
            local secondaryY = entry.renderY + target.primaryH + gap
            startup.b385_draw_activity_rect(boxX, secondaryY, boxWidth, target.secondaryH, 5, 5, 8, bgAlpha)
            local secondaryAccentH = target.secondaryH * accentRatio
            startup.b385_draw_activity_rect(boxX, secondaryY + ((target.secondaryH - secondaryAccentH) * 0.5), accentWidth, secondaryAccentH,
                255, 185, 80, math.floor(220 * opacity))
            local estimatedSecondaryH = secondaryScale * 0.073
            local secondaryTextY = secondaryY + math.max(0, (target.secondaryH - estimatedSecondaryH) * 0.50) - 0.0015 + userYOffset
            startup.b385_draw_activity_text(secondary, boxX + (0.0075 * horizontalScale), secondaryTextY, secondaryScale,
                255, 185, 80, drawAlpha, 4, true)
        end
    end

    startup.session_activity_set_gta_draw_order(0)
    return math.max(0, effectiveBottomY - cursorBottom)
end

-- Keep the user's current position/settings. Only migrate the renderer because
-- foreground FgAddText cannot honor Activity Feed Scale without reintroducing the
-- Debug-window-producing SetWindowFontScale path.
startup.s.sessionActivityRendererMode = "GTA After-Fade"
-- Activity Renderer is a Cherax combo/list feature, not a string feature.
-- B385 incorrectly called SetStringValue() here, which aborts script init on
-- Cherax v5.40.0. Sync the visible combo by list index instead, and never let
-- UI synchronization prevent the internal scalable renderer from loading.
if startup.set_feature_list_string_silently and startup.h and startup.h.SessionActivityRendererMode then
    direct_call(startup.set_feature_list_string_silently, startup.h.SessionActivityRendererMode, "GTA After-Fade")
end

startup.version = "v1.0.18"
startup.console_version = "v1.0.18"
startup.build_number = "2026.08.28.387"
startup.build_date = "2026-08-28"
startup.build_label = "B387 v1.0.16 Alpha - Independent Activity Box Scale"

if startup.log then
    startup.log("[Build 387] Added independent Activity Box Scale: black card height/padding can be resized without changing join/leave text size; default box scale 0.85; B381 Debug-window safety and B386 scalable text retained.")
