startup.version = "v1.0.18"
startup.console_version = "v1.0.18"
startup.build_number = "2026.08.28.390"
startup.build_date = "2026-08-28"
startup.build_label = "B390 v1.0.16 Alpha - Visible HUD Options UI Fix"

-- Keep Region Type ON by default unless the user has explicitly changed it.
if startup.s.advertiseRegionHudUserConfigured ~= true then
