-- ============================================================================
-- Build 391: Activity auto-anchor + live width-scale fix
-- • Activity Feed Y is always anchored directly above the live Session HUD stack
--   whenever the Session HUD is enabled. Manual Y becomes fallback-only.
-- • Activity Box Width Scale is read live from the slider at render time.
-- • Box width uses GTA's own text-width measurement when available, with a
--   conservative fallback estimator, so width changes are visible and text-safe.
-- ============================================================================
startup.b391 = startup.b391 or {}
startup.b391.width_cache = startup.b391.width_cache or {}
startup.b391.auto_gap = 0.010

-- Always keep the vertical activity stack above the current Session HUD lines.
-- X can still follow the HUD (Auto Position ON) or use the user's custom X
-- (Auto Position OFF), but Y is automatic while the Session HUD exists.
startup.session_activity_resolve_render_position = function()
    local autoX = startup.s.sessionActivityAutoPosition ~= false
    local sessionHudX = tonumber(startup.s.sessionInfoHudX or 0.169) or 0.169
    local activityX
    if autoX then
        activityX = startup.get_effective_hud_x(sessionHudX + 0.004)
    else
        activityX = startup.get_effective_hud_x(startup.s.sessionActivityX or 0.027)
    end

    if startup.s.sessionInfoHudEnabled == true then
        local layout = startup.hud_layout or {}
        local now = startup.now()
        local layoutUpdatedMs = tonumber(layout.updatedMs or 0) or 0
        local lineGap = tonumber(layout.lineGap or 0) or 0
        if lineGap <= 0 then
            local hudScale = tonumber(startup.s.sessionInfoHudScale or 0.30) or 0.30
            lineGap = math.max(0.027, hudScale * 0.100)
        end

        local stackTopY = tonumber(layout.stackTopY)
        if stackTopY ~= nil and layoutUpdatedMs > 0 and (now - layoutUpdatedMs) <= 1500 then
            return activityX, startup.clamp_float(stackTopY - startup.b391.auto_gap, 0.08, 0.95)
        end

        -- Safe first-frame fallback. Connected Players is always the bottom HUD line,
        -- so reserving one full line gap keeps the activity feed above it even before
        -- the live stack has been cached.
        local hudBottomY = tonumber(startup.s.sessionInfoHudY or 0.941) or 0.941
        local fallback = hudBottomY - lineGap - startup.b391.auto_gap
        return activityX, startup.clamp_float(fallback, 0.08, 0.95)
    end

    -- If the Session HUD is disabled there are no HUD lines to anchor above, so
    -- preserve the user's manual activity Y as a fallback.
    return activityX, startup.clamp_float(tonumber(startup.s.sessionActivityBottomY or 0.806) or 0.806, 0.08, 0.95)
end

function startup.b391_get_live_box_width_scale()
    local value = tonumber(startup.s.sessionActivityBoxWidthScale or 0.75) or 0.75
    if FeatureMgr and FeatureMgr.GetFeature and startup.h and startup.h.SessionActivityBoxScaleSlider then
        local okFeature, feature = direct_call(FeatureMgr.GetFeature, startup.h.SessionActivityBoxScaleSlider)
        if okFeature and feature and feature.GetFloatValue then
            local okValue, liveValue = pcall(function() return feature:GetFloatValue() end)
            if okValue and tonumber(liveValue) then value = tonumber(liveValue) end
        end
    end
    value = startup.clamp_float(value, 0.50, 1.80)
    startup.s.sessionActivityBoxWidthScale = value
    startup.s.sessionActivityBoxScale = value
    return value
end

function startup.b391_measure_activity_text(text, scale, font)
    local s = tostring(text or "")
    if s == "" then return 0 end
    scale = startup.clamp_float(tonumber(scale or 0.32) or 0.32, 0.12, 0.70)
    font = tonumber(font or 4) or 4
    local key = s .. "|" .. string.format("%.3f", scale) .. "|" .. tostring(font)
    local cached = startup.b391.width_cache[key]
    if cached and tonumber(cached.width) and (startup.now() - (tonumber(cached.ms or 0) or 0)) < 30000 then
        return tonumber(cached.width) or 0
    end

    local width = nil
    if Natives and Natives.InvokeVoid and Natives.InvokeFloat then
        local ok, result = pcall(function()
            Natives.InvokeVoid(0x66E0276CC5F6B9DA, font) -- SET_TEXT_FONT
            Natives.InvokeVoid(0x07C837F9A01C34C9, 0.0, scale) -- SET_TEXT_SCALE
            Natives.InvokeVoid(0x54CE8AC98E120CAB, "STRING") -- BEGIN_TEXT_COMMAND_GET_WIDTH
            Natives.InvokeVoid(0x6C188BE134E074AA, s) -- ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME
            return Natives.InvokeFloat(0x85F061DA64ED2F67, true) -- END_TEXT_COMMAND_GET_WIDTH
        end)
        if ok and tonumber(result) and tonumber(result) > 0 and tonumber(result) < 0.90 then
            width = tonumber(result)
        end
    end

    if width == nil then
        -- Fallback calibrated for GTA font 4. It intentionally errs slightly wide.
        local units = 0
        for i = 1, #s do
            local ch = s:sub(i, i)
            if ch:match("[MW@#%%&]") then units = units + 1.18
            elseif ch:match("[A-Z]") then units = units + 0.98
            elseif ch:match("[a-z0-9]") then units = units + 0.80
            elseif ch == "_" then units = units + 0.88
            elseif ch == " " then units = units + 0.44
            elseif ch:match("[%.:,;!|]") then units = units + 0.34
            else units = units + 0.72 end
        end
        width = units * scale * 0.036
    end

    width = startup.clamp_float(tonumber(width or 0.08) or 0.08, 0.015, 0.75)
    startup.b391.width_cache[key] = {width=width, ms=startup.now()}
    return width
end

-- Final activity renderer for B391. Keeps B385/B388 scalable GTA text and B389
-- backdrop colors, but fixes horizontal scaling and uses the automatic anchor above.
startup.render_session_activity_feed = function(x, bottomY, scale, textAlpha, forcedRenderer)
    if not startup.s.showSessionActivityHud then return 0 end
    if startup.s.sessionActivityUseNativeFeed ~= false then return 0 end
    if forcedRenderer ~= nil and tostring(forcedRenderer) ~= "after_fade" then return 0 end

    startup.session_activity_prune()
    local entries = startup.session_activity.entries or {}
    if #entries == 0 then return 0 end

    local now = startup.now()
    local renderScale = startup.clamp_float(tonumber(scale or 0.38) or 0.38, 0.20, 0.70)
    local primaryScale = startup.clamp_float(renderScale * 0.84, 0.17, 0.56)
    local secondaryScale = startup.clamp_float(renderScale * 0.77, 0.16, 0.52)
    local baseBottomY = startup.clamp_float(tonumber(bottomY or 0.806) or 0.806, 0.08, 0.95)
    local enterMs = math.max(100, tonumber(startup.s.sessionActivityEnterMs or 420) or 420)
    local fadeMs = math.max(200, tonumber(startup.s.sessionActivityFadeMs or 900) or 900)
    local boxAlpha = math.max(0, math.min(230, tonumber(startup.s.sessionActivityBoxAlpha or 60) or 60))
    local animated = startup.s.sessionActivityAnimated ~= false
    local horizontalScale = startup.get_hud_horizontal_scale()
    local widthScale = startup.b391_get_live_box_width_scale()
    local heightScale = startup.clamp_float(tonumber(startup.s.sessionActivityBoxHeightScale or 1.15) or 1.15, 0.70, 1.60)
    local gap = startup.clamp_float(0.0040 * heightScale, 0.0025, 0.0080)
    local targets = {}
    local effectiveBottomY = baseBottomY
    local cursorBottom = effectiveBottomY

    local primaryTextH = primaryScale * 0.073
    local secondaryTextH = secondaryScale * 0.073
    local primaryBaseH = math.max(primaryTextH + 0.015, 0.046)
    local secondaryBaseH = math.max(secondaryTextH + 0.013, 0.043)
    local primaryRowHeight = startup.clamp_float(primaryBaseH * heightScale, primaryTextH + 0.009, 0.095)
    local secondaryRowHeight = startup.clamp_float(secondaryBaseH * heightScale, secondaryTextH + 0.008, 0.090)

    -- bottomY is the hard lower boundary of the activity stack. Every activity row
    -- grows upward from it, so the feed can never drop into the Session HUD lines.
    for i = #entries, 1, -1 do
        local entry = entries[i]
        local _, secondary = startup.session_activity_content(entry)
        local height = primaryRowHeight
        if tostring(secondary or "") ~= "" then height = height + gap + secondaryRowHeight end
        local targetTop = cursorBottom - height
        targets[i] = {y=targetTop, h=height, primaryH=primaryRowHeight, secondaryH=secondaryRowHeight}
        cursorBottom = targetTop - gap
    end

    startup.session_activity_set_gta_draw_order(8)

    for i, entry in ipairs(entries) do
        local target = targets[i]
        local age = math.max(0, now - (entry.createdMs or now))
        local remain = math.max(0, (entry.expiresMs or now) - now)
        local enterT = animated and startup.ease_out_cubic(age / enterMs) or 1.0
        local fadeT = remain < fadeMs and startup.clamp01(remain / fadeMs) or 1.0
        if animated and remain < fadeMs then fadeT = 1.0 - startup.ease_in_cubic(1.0 - fadeT) end
        local opacity = math.min(enterT, fadeT)

        if entry.renderY == nil then entry.renderY = target.y + (animated and 0.010 or 0) end
        if animated then
            entry.renderY = entry.renderY + ((target.y - entry.renderY) * 0.22)
        else
            entry.renderY = target.y
        end

        local primary, secondary, color = startup.session_activity_content(entry)
        primary = tostring(primary or "")
        secondary = tostring(secondary or "")
        local primaryWidth = startup.b391_measure_activity_text(primary, primaryScale, 4)
        local secondaryWidth = secondary ~= "" and startup.b391_measure_activity_text(secondary, secondaryScale, 4) or 0
        local textWidth = math.max(primaryWidth, secondaryWidth)

        -- Width Scale now controls *extra horizontal room* around the real measured
        -- text width. 0.50 is a tight card; 1.00 is comfortable; 1.80 is wide.
        -- This avoids the old contentSafeWidth clamp swallowing slider changes.
        local t = (widthScale - 0.50) / (1.80 - 0.50)
        t = startup.clamp_float(t, 0.0, 1.0)
        local sideRoom = (0.007 + (0.055 * t)) * horizontalScale
        local boxWidth = startup.clamp_float(textWidth + sideRoom,
            math.max(0.040 * horizontalScale, textWidth + (0.004 * horizontalScale)),
            0.42 * horizontalScale)

        local slideX = animated and ((1.0 - enterT) * (-0.009 * horizontalScale)) or 0
        if animated and remain < fadeMs then slideX = slideX + ((1.0 - fadeT) * (-0.007 * horizontalScale)) end
        local boxX = x + slideX
        local drawAlpha = math.floor((tonumber(textAlpha or 200) or 200) * opacity)
        local bgAlpha = math.floor(boxAlpha * opacity)
        local backdrop = {5,5,8}
        if entry.kind == "joining" then backdrop = startup.hud_color("activityJoinBackdrop", {5,5,8})
        elseif entry.kind == "left" then backdrop = startup.hud_color("activityLeaveBackdrop", {5,5,8}) end
        local accentWidth = 0.00115 * horizontalScale
        local accentRatio = startup.clamp_float(tonumber(startup.s.sessionActivityAccentHeightRatio or 1.0) or 1.0, 0.15, 1.0)
        local userYOffset = startup.clamp_float(tonumber(startup.s.sessionActivityTextYOffset or 0) or 0, -0.030, 0.040)

        startup.b385_draw_activity_rect(boxX, entry.renderY, boxWidth, target.primaryH,
            backdrop[1], backdrop[2], backdrop[3], bgAlpha)
        local accentH = target.primaryH * accentRatio
        startup.b385_draw_activity_rect(boxX, entry.renderY + ((target.primaryH - accentH) * 0.5),
            accentWidth, accentH, color[1], color[2], color[3], math.floor(220 * opacity))

        local estimatedTextH = primaryScale * 0.073
        local primaryTextY = entry.renderY + math.max(0, (target.primaryH - estimatedTextH) * 0.50) - 0.0015 + userYOffset
        local primaryTextX = boxX + (0.0070 * horizontalScale)
        local boldName = select(1, startup.session_activity_primary_segments(entry))

        startup.b385_draw_activity_text(primary, primaryTextX, primaryTextY, primaryScale,
            color[1], color[2], color[3], drawAlpha, 4, true)
        if boldName ~= nil and tostring(boldName) ~= "" then
            startup.b385_draw_activity_text(tostring(boldName), primaryTextX, primaryTextY, primaryScale,
                color[1], color[2], color[3], math.floor(drawAlpha * 0.20), 4, false)
        end

        if secondary ~= "" then
            local secondaryY = entry.renderY + target.primaryH + gap
            startup.b385_draw_activity_rect(boxX, secondaryY, boxWidth, target.secondaryH,
                backdrop[1], backdrop[2], backdrop[3], bgAlpha)
            local secondaryAccentH = target.secondaryH * accentRatio
            startup.b385_draw_activity_rect(boxX, secondaryY + ((target.secondaryH - secondaryAccentH) * 0.5),
                accentWidth, secondaryAccentH, 255, 185, 80, math.floor(220 * opacity))
            local estimatedSecondaryH = secondaryScale * 0.073
            local secondaryTextY = secondaryY + math.max(0, (target.secondaryH - estimatedSecondaryH) * 0.50) - 0.0015 + userYOffset
            startup.b385_draw_activity_text(secondary, boxX + (0.0070 * horizontalScale), secondaryTextY, secondaryScale,
                255, 185, 80, drawAlpha, 4, true)
        end
    end

    startup.session_activity_set_gta_draw_order(0)
    return math.max(0, effectiveBottomY - cursorBottom)
end

-- Auto vertical placement is the new invariant. Save it ON so reloads immediately
-- use the live HUD anchor; manual Y remains only as a Session-HUD-disabled fallback.
startup.s.sessionActivityAutoPosition = true
startup.s.sessionActivityPlacementMode = "Above Session HUD Stack"
if startup.set_feature_bool_silently and startup.h then
    startup.set_feature_bool_silently(startup.h.SessionActivityAutoPosition, true)
end
if startup.s.initialized and startup.save_config then startup.save_config(false) end

startup.version = "v1.0.18"
startup.console_version = "v1.0.18"
startup.build_number = "2026.08.28.391"
startup.build_date = "2026-08-28"
startup.build_label = "B391 v1.0.16 Alpha - Activity Auto Anchor + Width Scale Fix"

if startup.log then
    startup.log("[Build 391] Activity Feed Y now always anchors above the live Session HUD stack; Activity Box Width Scale reads live and changes measured text padding without being swallowed by minimum-width clamps.")
end

-- ============================================================================
-- Build 394: Essentials Garage direct JSON + stable tick renderer
-- • Activity Feed X default/migration = 0.174.
-- • Renames Time & World to Essentials while preserving Day / Night / Clock.
-- • Ports the supplied standalone Trigger Bot as a contained Essentials module.
-- • Ports the DriftGod keyboard Garage HUD as a lightweight Startup module.
-- ============================================================================
function startup.install_build392_essentials()
startup.b392 = startup.b392 or {}
startup.b392.trigger = startup.b392.trigger or {
    enabled = startup.s.triggerBotEnabled == true,
    reactionDelayMs = startup.clamp_int(tonumber(startup.s.triggerBotReactionDelayMs or 20) or 20, 0, 500),
    vehicleWeapons = true,
    debugLogs = false,
    aimedEntity = 0,
    aimedSinceMs = 0,
    firing = false,
    lastLoggedEntity = 0,
    aimPointer = 0,
}
startup.b392.garage = startup.b392.garage or {
    open = false,
    scanned = false,
    scanning = false,
    items = {},
    filtered = {},
    currentFolder = nil,
    selected = 0,
    scroll = 0,
    lastKeys = {},
    inputLockUntil = 0,
    status = "Ready — first open scans Cherax saved vehicles.",
    lastLoaded = "None",
    insertHotkey = false, -- legacy B392 field; B395 uses Garage Hotkey combo instead.
    hotkeyName = "None",
    hotkeyCode = 0,
    favoriteHotkeyName = "None",
    favoriteHotkeyCode = 0,
    favoriteRel = "",
    favoriteLabel = "None",
    x = 0.085,
    y = 0.080,
    width = 0.128,
    opacity = 0.50,
}

local B392 = startup.b392
local T392 = B392.trigger
local G392 = B392.garage

local function b392_now()
    local ok,v=pcall(function() return Time and Time.GetEpocheMs and Time.GetEpocheMs() end)
    if ok and type(v)=="number" then return v end
    return math.floor((os.clock and os.clock() or 0)*1000)
end

local function b392_toast(text, ms)
    if startup.toast then direct_call(startup.toast, tostring(text or ""), tonumber(ms or 2500) or 2500)
    elseif GUI and GUI.AddToast then pcall(GUI.AddToast, "Startup", tostring(text or ""), tonumber(ms or 2500) or 2500) end
end

local function b392_log(text)
    if startup.log then direct_call(startup.log, "[Build 396] "..tostring(text or ""))
    elseif Logger and Logger.LogInfo then pcall(Logger.LogInfo, "[Startup] [Build 396] "..tostring(text or "")) end
end

-- --------------------------------------------------------------------------
-- Trigger Bot — ported from supplied Trigger v0.1.0 Alpha Build 001.
-- --------------------------------------------------------------------------
local TN = {
    PLAYER_ID                           = 0x4F8644AF03D0E0D6,
    PLAYER_PED_ID                       = 0xD80958FC74E988A6,
    GET_ENTITY_PLAYER_IS_FREE_AIMING_AT = 0x2975C866E6713290,
    DOES_ENTITY_EXIST                   = 0x7239B21A38F536BA,
    IS_ENTITY_A_PED                     = 0x524AC5ECEA15343E,
    IS_PED_A_PLAYER                     = 0x12534C348C6CB68B,
    IS_PED_DEAD_OR_DYING                = 0x3317DEDB88C95038,
    IS_PED_IN_ANY_VEHICLE               = 0x997ABD671D25CA0B,
    SET_CONTROL_VALUE_NEXT_FRAME        = 0xE8A25867FBA3B05E,
    NETWORK_GET_PLAYER_INDEX_FROM_PED   = 0x6C0E2E0125610278,
}
local TC = { ATTACK=24, ATTACK_ALT=257, VEH_ATTACK=69, VEH_ATTACK_ALT=70, VEH_FLY_ATTACK=114, VEH_FLY_ATTACK2=115, VEH_SUB_ATTACK=116 }

local function tinvoke_bool(hash,...)
    if not (Natives and Natives.InvokeBool) then return false end
    local ok,v=pcall(Natives.InvokeBool,hash,...)
    return ok and v==true
end
local function tinvoke_int(hash,...)
    if not (Natives and Natives.InvokeInt) then return 0 end
    local ok,v=pcall(Natives.InvokeInt,hash,...)
    return ok and type(v)=="number" and v or 0
end
local function trigger_reset()
    T392.aimedEntity=0; T392.aimedSinceMs=0; T392.firing=false; T392.lastLoggedEntity=0
end
local function trigger_target_name(ped)
    local pid=tinvoke_int(TN.NETWORK_GET_PLAYER_INDEX_FROM_PED,ped)
    if pid<0 then return "Player" end
    local name=nil
    pcall(function() if Players and Players.GetName then name=Players.GetName(pid) end end)
    return type(name)=="string" and name~="" and name or ("Player "..tostring(pid))
end
local function trigger_get_target()
    if tonumber(T392.aimPointer or 0)==0 then return 0 end
    local playerId=tinvoke_int(TN.PLAYER_ID)
    local localPed=tinvoke_int(TN.PLAYER_PED_ID)
    if playerId<0 or localPed==0 then return 0 end
    local wrote=pcall(Memory.WriteInt,T392.aimPointer,0)
    if not wrote then return 0 end
    if not tinvoke_bool(TN.GET_ENTITY_PLAYER_IS_FREE_AIMING_AT,playerId,T392.aimPointer) then return 0 end
    local ok,entity=pcall(Memory.ReadInt,T392.aimPointer)
    if not ok or type(entity)~="number" or entity==0 or entity==localPed then return 0 end
    if not tinvoke_bool(TN.DOES_ENTITY_EXIST,entity) then return 0 end
    if not tinvoke_bool(TN.IS_ENTITY_A_PED,entity) then return 0 end
    if not tinvoke_bool(TN.IS_PED_A_PLAYER,entity) then return 0 end
    if tinvoke_bool(TN.IS_PED_DEAD_OR_DYING,entity,true) then return 0 end
    return entity
end
local function trigger_hold(control)
    tinvoke_bool(TN.SET_CONTROL_VALUE_NEXT_FRAME,0,control,1.0)
end
local function trigger_attack()
    local ped=tinvoke_int(TN.PLAYER_PED_ID)
    if ped==0 then return false end
    if not tinvoke_bool(TN.IS_PED_IN_ANY_VEHICLE,ped,false) then
        trigger_hold(TC.ATTACK); trigger_hold(TC.ATTACK_ALT); return true
    end
    if T392.vehicleWeapons~=true then return false end
    trigger_hold(TC.VEH_ATTACK); trigger_hold(TC.VEH_ATTACK_ALT); trigger_hold(TC.VEH_FLY_ATTACK)
    trigger_hold(TC.VEH_FLY_ATTACK2); trigger_hold(TC.VEH_SUB_ATTACK); return true
end
local function trigger_tick()
    if T392.enabled~=true then if T392.firing or T392.aimedEntity~=0 then trigger_reset() end return end
    local target=trigger_get_target(); local now=b392_now()
    if target==0 then trigger_reset(); return end
    if target~=T392.aimedEntity then
        T392.aimedEntity=target; T392.aimedSinceMs=now; T392.firing=false
        if T392.debugLogs and target~=T392.lastLoggedEntity then
            T392.lastLoggedEntity=target; b392_log("Trigger acquired "..trigger_target_name(target).." | ped="..tostring(target))
        end
    end
    if now-(T392.aimedSinceMs or now)<(T392.reactionDelayMs or 0) then return end
    T392.firing=trigger_attack()==true
end

pcall(function()
    if Memory and Memory.AllocInt and tonumber(T392.aimPointer or 0)==0 then T392.aimPointer=Memory.AllocInt() or 0 end
end)

local triggerFeature=startup.add_toggle("EssentialsTriggerBot", "Trigger Bot", "While you manually aim directly at a living player, holds the normal fire control. Does not move or snap your aim. Startup remembers this toggle between loads.", function(f)
    local requested = f and f.IsToggled and f:IsToggled() == true
    T392.enabled = requested and tonumber(T392.aimPointer or 0)~=0
    startup.s.triggerBotEnabled = T392.enabled == true
    trigger_reset()
    if requested and tonumber(T392.aimPointer or 0)==0 then
        pcall(function() if f.Toggle then f:Toggle(false) elseif f.SetBoolValue then f:SetBoolValue(false) end end)
        startup.s.triggerBotEnabled = false
        b392_toast("Trigger Bot unavailable: aim pointer allocation failed.",3500)
    end
    if startup.s.initialized and startup.save_config then direct_call(startup.save_config,false) end
end, startup.s.triggerBotEnabled == true)
pcall(function() if triggerFeature and triggerFeature.SetSaveable then triggerFeature:SetSaveable(false) end end)
startup.add_int_slider("EssentialsTriggerReaction", "Reaction Delay (ms)", "Wait after a player enters the crosshair before firing. Default is 20 ms; 0 is immediate.", startup.s.triggerBotReactionDelayMs or 20, 0, 500, 5, function(v)
    T392.reactionDelayMs=v
    startup.s.triggerBotReactionDelayMs=v
    if startup.s.initialized and startup.save_config then direct_call(startup.save_config,false) end
end)
startup.add_toggle("EssentialsTriggerVehicleWeapons", "Vehicle Weapons", "Also uses standard drive-by, mounted, aircraft, and submarine attack controls.", function(f) T392.vehicleWeapons=f:IsToggled() end, true)
startup.add_toggle("EssentialsTriggerDebug", "Trigger Debug Logs", "Logs target acquisition and protected runtime errors to Cherax.log.", function(f) T392.debugLogs=f:IsToggled() end, false)

if Script and Script.RegisterLooped then
    Script.RegisterLooped(function()
        if ShouldUnload and ShouldUnload() then if Script.Yield then Script.Yield(100) end return end
        local ok,err=pcall(trigger_tick)
        if not ok then if T392.debugLogs then b392_log("Trigger runtime protected: "..tostring(err)) end; trigger_reset(); if Script.Yield then Script.Yield(100) end return end
        if Script.Yield then Script.Yield(T392.enabled and 0 or 100) end
    end)
end

