local function gnorm(p) p=tostring(p or ""):gsub("/","\\"); while #p>3 and p:sub(-1)=="\\" do p=p:sub(1,-2) end; return p end
local function gfile(p) return tostring(p or ""):match("([^\\/]+)$") or tostring(p or "") end
local function gstrip(n) return tostring(n or ""):gsub("%.[Jj][Ss][Oo][Nn]$","") end
local function garage_root()
    local root=""
    pcall(function() if FileMgr and FileMgr.GetMenuRootPath then root=gnorm(FileMgr.GetMenuRootPath() or "") end end)
    root=root:gsub("\\[Ll][Uu][Aa]$","")
    if root=="" then
        pcall(function() local p=os.getenv and os.getenv("USERPROFILE") or ""; if p~="" then root=gnorm(p.."\\Documents\\Cherax") end end)
    end
    return gnorm(root.."\\Vehicles")
end
local function collection_paths(value)
    local out,seen={},{}
    local function add(v)
        local p=nil
        if type(v)=="string" then p=v else
            pcall(function() p=v.path or v.Path or v.filename or v.FileName end)
            if type(p)~="string" then local t=tostring(v or ""); if not t:match("^userdata:") then p=t end end
        end
        p=gnorm(p or ""); if p=="" then return end
        local k=p:lower(); if seen[k] then return end; seen[k]=true; out[#out+1]=p
    end
    if type(value)=="table" then for _,v in pairs(value) do add(v) end return out end
    if type(value)=="userdata" then
        local count=-1; pcall(function() count=#value end); count=tonumber(count or -1) or -1
        if count>=0 and count<10000 then
            for i=1,count do pcall(function() if value[i]~=nil then add(value[i]) end end) end
            if #out==0 then for i=0,math.max(0,count-1) do pcall(function() if value[i]~=nil then add(value[i]) end end) end end
        end
        if #out==0 then pcall(function() for _,v in ipairs(value) do add(v) end end) end
    end
    return out
end
local function gfind(root)
    local found={}
    for _,ext in ipairs({".json","json","*.json"}) do
        local ok,res=pcall(function() return FileMgr.FindFiles(root,ext,true) end)
        if ok then found=collection_paths(res) end
        if #found>0 then break end
    end
    local abs,seen={},{}
    for _,p in ipairs(found) do
        if not p:match("^[A-Za-z]:\\") and p:sub(1,2)~="\\\\" then p=gnorm(root.."\\"..p:gsub("^\\+","")) end
        if p:lower():match("%.json$") and not seen[p:lower()] then seen[p:lower()]=true; abs[#abs+1]=p end
    end
    table.sort(abs,function(a,b) return a:lower()<b:lower() end)
    return abs
end
local function relative(root,p)
    root=gnorm(root); p=gnorm(p)
    if root~="" and p:lower():sub(1,#root)==root:lower() then return p:sub(#root+1):gsub("^\\+","") end
    return p:gsub("^\\+","")
end
local function category(rel)
    local d=gnorm(rel):match("^(.*)\\[^\\]+$")
    return d and d~="" and d or "Root"
end

local function garage_find_favorite_item()
    local wanted=tostring(startup.s.essentialsGarageFavoriteRel or G392.favoriteRel or "")
    if wanted=="" then return nil end
    local key=gnorm(wanted):lower()
    for _,it in ipairs(G392.items or {}) do
        if gnorm(it.rel or it.path or ""):lower()==key then return it end
    end
    return nil
end

local function garage_refresh_favorite_combo()
    for i=#GARAGE_FAVORITE_NAMES,1,-1 do GARAGE_FAVORITE_NAMES[i]=nil end
    for i=#GARAGE_FAVORITE_ITEMS,1,-1 do GARAGE_FAVORITE_ITEMS[i]=nil end
    GARAGE_FAVORITE_NAMES[1]="None"
    local selectedIndex=0
    local wanted=gnorm(startup.s.essentialsGarageFavoriteRel or ""):lower()
    for _,it in ipairs(G392.items or {}) do
        GARAGE_FAVORITE_ITEMS[#GARAGE_FAVORITE_ITEMS+1]=it
        GARAGE_FAVORITE_NAMES[#GARAGE_FAVORITE_NAMES+1]=tostring(it.displayLabel or it.name or "Saved Vehicle")
        if wanted~="" and gnorm(it.rel or it.path or ""):lower()==wanted then selectedIndex=#GARAGE_FAVORITE_ITEMS end
    end
    local current=garage_find_favorite_item()
    G392.favoriteLabel=current and tostring(current.displayLabel or current.name or "Saved Vehicle") or ((wanted~="") and "Missing saved favorite" or "None")
    if garageFavoriteFeature then
        garageFavoriteSyncing=true
        pcall(function() if garageFavoriteFeature.SetList then garageFavoriteFeature:SetList(GARAGE_FAVORITE_NAMES) end end)
        pcall(function() if garageFavoriteFeature.SetListIndex then garageFavoriteFeature:SetListIndex(selectedIndex) end end)
        garageFavoriteSyncing=false
    end
end

local function garage_rebuild()
    G392.filtered={}
    if G392.currentFolder then
        G392.filtered[#G392.filtered+1]={random=true,name="Random",displayLabel="Random",category=G392.currentFolder}
        for _,it in ipairs(G392.items) do if tostring(it.category):lower()==tostring(G392.currentFolder):lower() then G392.filtered[#G392.filtered+1]=it end end
    else
        if #G392.items>0 then G392.filtered[#G392.filtered+1]={random=true,name="Random",displayLabel="Random",category="All"} end
        local fs,folders={},{}
        for _,it in ipairs(G392.items) do
            local c=tostring(it.category or "Root")
            if c~="Root" and not fs[c:lower()] then fs[c:lower()]=true; folders[#folders+1]=c end
        end
        table.sort(folders,function(a,b) return a:lower()<b:lower() end)
        for _,c in ipairs(folders) do G392.filtered[#G392.filtered+1]={folder=true,name="/"..c,displayLabel="/"..c,category=c} end
        for _,it in ipairs(G392.items) do if tostring(it.category or "Root")=="Root" then G392.filtered[#G392.filtered+1]=it end end
    end
    local n=#G392.filtered
    if n<=0 then G392.selected=0; G392.scroll=0; return end
    if G392.selected<0 then G392.selected=0 end; if G392.selected>n-1 then G392.selected=n-1 end
    if G392.selected<G392.scroll then G392.scroll=G392.selected elseif G392.selected>=G392.scroll+6 then G392.scroll=G392.selected-5 end
    local maxScroll=math.max(0,n-6); if G392.scroll>maxScroll then G392.scroll=maxScroll end; if G392.scroll<0 then G392.scroll=0 end
end

local function garage_scan(reason)
    if G392.scanning then return #G392.items end
    if not (FileMgr and FileMgr.FindFiles) then G392.status="FileMgr.FindFiles unavailable"; b392_toast(G392.status,3000); return 0 end
    G392.scanning=true
    local root=garage_root(); pcall(function() if FileMgr.CreateDir then FileMgr.CreateDir(root) end end)
    local paths=gfind(root); local items={}
    for i,p in ipairs(paths) do
        local rel=relative(root,p); local cat=category(rel); local name=gstrip(gfile(p))
        items[#items+1]={name=name,path=p,rel=rel,category=cat,displayLabel=(cat~="Root" and (cat.." / "..name) or name),cheraxListIndex=i-1,cheraxListHash=GARAGE_SAVED_HASH}
    end
    G392.items=items; G392.currentFolder=nil; G392.selected=0; G392.scroll=0; G392.scanned=true; G392.scanning=false
    G392.status="Saved vehicles: "..tostring(#items); garage_rebuild(); garage_refresh_favorite_combo(); b392_log("Garage scan | reason="..tostring(reason or "manual").." | root="..root.." | count="..#items)
    return #items
end

-- Build 394 exact-file Garage loader.
-- Prime can expose the stable Saved Vehicles feature while returning an empty list to
-- FeatureMgr.GetFeatureList(). Do not block on that list and do not guess an index.
-- Load the exact selected JSON file instead, using the same saved-index normalization
-- and repeat-style strategy that stabilized the supplied DriftGod Garage.
local GD394 = G392.direct394 or {
    token = 0,
    pending = nil,
    busy = false,
    loads = 0,
    failures = 0,
}
G392.direct394 = GD394

local function garage_read_text(path)
    path=tostring(path or "")
    if path=="" then return nil,"empty path" end
    if FileMgr and FileMgr.ReadFileContent then
        local ok,body=pcall(function() return FileMgr.ReadFileContent(path) end)
        if ok and type(body)=="string" and body~="" then return body,"FileMgr.ReadFileContent" end
    end
    local f=nil
    local okOpen=pcall(function() f=io.open(path,"rb") end)
    if okOpen and f then
        local body=nil; local okRead=pcall(function() body=f:read("*a") end); pcall(function() f:close() end)
        if okRead and type(body)=="string" and body~="" then return body,"io.open" end
    end
    return nil,"file unreadable"
end

local function garage_section(text,key,maxLen)
    text=tostring(text or ""); key=tostring(key or "")
    if text=="" or key=="" then return "" end
    local keyPos=text:find('"'..key..'"',1,true); if not keyPos then return "" end
    local brace=text:find("{",keyPos,true); local bracket=text:find("[",keyPos,true)
    local startAt=brace; local openChar="{"; local closeChar="}"
    if bracket and (not brace or bracket<brace) then startAt=bracket; openChar="["; closeChar="]" end
    maxLen=tonumber(maxLen or 1800) or 1800
    if not startAt then return text:sub(keyPos,math.min(#text,keyPos+maxLen)) end
    local depth=0; local inString=false; local escaped=false
    for i=startAt,#text do
        local c=text:sub(i,i)
        if inString then
            if escaped then escaped=false elseif c=="\\" then escaped=true elseif c=='"' then inString=false end
        else
            if c=='"' then inString=true elseif c==openChar then depth=depth+1 elseif c==closeChar then depth=depth-1; if depth<=0 then return text:sub(startAt,i) end end
        end
        if i-startAt>maxLen then break end
    end
    return text:sub(keyPos,math.min(#text,keyPos+maxLen))
end

local function garage_number(text,...)
    text=tostring(text or "")
    for _,key in ipairs({...}) do
        local raw=text:match('"'..tostring(key)..'"%s*:%s*(-?%d+%.?%d*)')
        if raw~=nil then return tonumber(raw) end
    end
    return nil
end
local function garage_string(text,...)
    text=tostring(text or "")
    for _,key in ipairs({...}) do
        local raw=text:match('"'..tostring(key)..'"%s*:%s*"([^\"]*)"')
        if raw~=nil then return raw:gsub('\\"','"'):gsub('\\\\','\\') end
    end
    return nil
end
local function garage_bool(text,...)
    text=tostring(text or "")
    for _,key in ipairs({...}) do
        local raw=text:match('"'..tostring(key)..'"%s*:%s*([%a%d]+)')
        if raw~=nil then
            raw=tostring(raw):lower(); if raw=="true" or raw=="1" then return true elseif raw=="false" or raw=="0" then return false end
        end
    end
    return nil
end
local function garage_color(text,...)
    for _,key in ipairs({...}) do
        local sec=garage_section(text,key,800)
        if sec~="" then
            local r=garage_number(sec,"r","R","red","Red"); local g=garage_number(sec,"g","G","green","Green"); local b=garage_number(sec,"b","B","blue","Blue")
            if r~=nil and g~=nil and b~=nil then return {r=r,g=g,b=b} end
            local ar,ag,ab=sec:match('%[%s*(-?%d+)%s*,%s*(-?%d+)%s*,%s*(-?%d+)')
            if ar then return {r=tonumber(ar),g=tonumber(ag),b=tonumber(ab)} end
        end
    end
    return nil
end
local function garage_saved_to_native(savedIndex,cheraxFormat)
    savedIndex=tonumber(savedIndex or -1) or -1
    if cheraxFormat==true then if savedIndex<=0 then return -1 end; return savedIndex-1 end
    return savedIndex
end

local function garage_parse_saved_vehicle(text)
    text=tostring(text or ""); if text=="" then return nil,"empty JSON" end
    local format=garage_string(text,"format","Format") or ""
    local cheraxFormat=tostring(format):lower():find("cherax",1,true)~=nil or text:find('"mods"',1,true)~=nil
    local model=garage_number(text,"vehicle_model_hash","vehicleModel","VehicleModel","modelHash","ModelHash","model","Model","hash","Hash") or 0
    if model==0 then return nil,"missing model hash" end
    local snap={
        model=model, format=format, cheraxFormat=cheraxFormat, mods={}, toggleMods={}, extras={},
        wheelType=garage_number(text,"wheelType","wheel_type","WheelType") or 0,
        primaryColor=garage_number(text,"primaryColor","primary_color","PrimaryColor") or 0,
        secondaryColor=garage_number(text,"secondaryColor","secondary_color","SecondaryColor") or 0,
        pearlescentColor=garage_number(text,"pearlescentColor","pearlescent_color","PearlescentColor") or 0,
        wheelColor=garage_number(text,"wheelColor","wheel_color","WheelColor") or 0,
        windowTint=garage_number(text,"windowTint","vehicle_window_tint","WindowTint"),
        interiorColor=garage_number(text,"interiorColor","interior_color","InteriorColor"),
        dashBoardColor=garage_number(text,"dashBoardColor","dashboardColor","dashboard_color","DashboardColor"),
        plateText=garage_string(text,"plateText","plate_text","PlateText") or "",
        plateTextIndex=garage_number(text,"plateTextIndex","plate_text_index","PlateTextIndex"),
        liveryID=garage_number(text,"liveryID","liveryId","livery","Livery"),
        livery2ID=garage_number(text,"livery2ID","livery2Id","Livery2"),
        isPrimaryColorCustom=garage_bool(text,"isPrimaryColorCustom","hasCustomPrimary","customPrimaryColorEnabled"),
        isSecondaryColorCustom=garage_bool(text,"isSecondaryColorCustom","hasCustomSecondary","customSecondaryColorEnabled"),
        customPrimaryColor=garage_color(text,"customPrimaryColor","custom_primary_color"),
        customSecondaryColor=garage_color(text,"customSecondaryColor","custom_secondary_color"),
        tyreSmokeColor=garage_color(text,"tyreSmokeColor","tireSmokeColor","tyre_smoke_color"),
        disableExtras=garage_number(text,"disableExtras","DisableExtras"),
        bulletproofTyres=garage_bool(text,"bulletproofTyres","bulletproofTires"),
        driftTyres=garage_bool(text,"driftTyres","driftTires"),
        dirtLevel=garage_number(text,"dirtLevel","DirtLevel") or 0.0,
    }
    if snap.isPrimaryColorCustom==nil then snap.isPrimaryColorCustom=snap.customPrimaryColor~=nil end
    if snap.isSecondaryColorCustom==nil then snap.isSecondaryColorCustom=snap.customSecondaryColor~=nil end
    for modType=0,49 do
        local sec=garage_section(text,"mod"..tostring(modType),900)
        if sec~="" then
            local saved=garage_number(sec,"index","Index","modIndex","ModIndex")
            if saved~=nil then snap.mods[modType]={savedIndex=saved,nativeIndex=garage_saved_to_native(saved,cheraxFormat),variation=garage_bool(sec,"variation","Variation","customTires","CustomTires")==true} end
        end
    end
    for _,modType in ipairs({18,20,22}) do local m=snap.mods[modType]; if m then snap.toggleMods[modType]=(tonumber(m.savedIndex or 0) or 0)>0 end end
    local neonSec=garage_section(text,"neonKits",1100)
    snap.neon={
        left=garage_bool(neonSec,"left","neonLOn")==true or garage_bool(text,"neonLOn")==true,
        right=garage_bool(neonSec,"right","neonROn")==true or garage_bool(text,"neonROn")==true,
        front=garage_bool(neonSec,"front","neonFOn")==true or garage_bool(text,"neonFOn")==true,
        back=garage_bool(neonSec,"back","neonBOn")==true or garage_bool(text,"neonBOn")==true,
    }
    snap.neonColor=garage_color(neonSec,"color") or garage_color(text,"neonColor","neon_color") or {r=255,g=0,b=255}
    for extra=1,20 do local enabled=garage_bool(text,"extra"..tostring(extra),"Extra"..tostring(extra)); if enabled~=nil then snap.extras[extra]=enabled end end
    return snap,nil
end

local function gi_void(hash,...)
    if not (Natives and Natives.InvokeVoid) then return false end
    local ok=pcall(Natives.InvokeVoid,hash,...); return ok==true
end
local function gi_int(hash,...)
    if not (Natives and Natives.InvokeInt) then return 0 end
    local ok,v=pcall(Natives.InvokeInt,hash,...); if ok and type(v)=="number" then return v end; return 0
end
local function gi_bool(hash,...)
    if not (Natives and Natives.InvokeBool) then return false end
    local ok,v=pcall(Natives.InvokeBool,hash,...); return ok and v==true
end
local function gi_float(hash,...)
    if not (Natives and Natives.InvokeFloat) then return 0.0 end
    local ok,v=pcall(Natives.InvokeFloat,hash,...); if ok and tonumber(v) then return tonumber(v) end; return 0.0
end
local function gi_v3(hash,...)
    if not (Natives and Natives.InvokeV3) then return 0.0,0.0,0.0 end
    local ok,a,b,c=pcall(Natives.InvokeV3,hash,...); if not ok then return 0.0,0.0,0.0 end
    if type(a)=="table" then return tonumber(a.x or a.X or a[1]) or 0.0,tonumber(a.y or a.Y or a[2]) or 0.0,tonumber(a.z or a.Z or a[3]) or 0.0 end
    if type(a)=="userdata" then
        local x,y,z=0.0,0.0,0.0; pcall(function() x=tonumber(a.x or a.X) or 0.0; y=tonumber(a.y or a.Y) or 0.0; z=tonumber(a.z or a.Z) or 0.0 end); return x,y,z
    end
    return tonumber(a) or 0.0,tonumber(b) or 0.0,tonumber(c) or 0.0
end

local GN394={
    PLAYER_PED_ID=0xD80958FC74E988A6, GET_ENTITY_COORDS=0x3FEF770D40960D5A, GET_ENTITY_HEADING=0xE83D4F9BA2A38914, GET_ENTITY_MODEL=0x9F47B058362C84B5,
    DELETE_ENTITY=0xAE3CBE5BF394C9C9,
    REQUEST_MODEL=0x963D27A58DF860AC, HAS_MODEL_LOADED=0x98A4EB5D89A0C952, CREATE_VEHICLE=0xAF35D0D2583051B0, SET_MODEL_DONE=0xE532F5D78798DAAB,
    SET_MISSION=0xAD738C3085FE7E11, SET_MOD_KIT=0x1F2AA07F00B3217A, SET_WHEEL_TYPE=0x487EB21CC7295BA1, SET_MOD=0x6AF0636DDEDCB6DD,
    TOGGLE_MOD=0x2A1F4F37F95BAD08, SET_COLORS=0x4F1D4BE3A7F24601, SET_EXTRA_COLORS=0x2036F561ADD12E33,
    SET_CUSTOM_PRIMARY=0x7141766F91D15BEA, SET_CUSTOM_SECONDARY=0x36CED73BFED89754, CLEAR_CUSTOM_PRIMARY=0x55E1D2758F34E437, CLEAR_CUSTOM_SECONDARY=0x5FFBDEEC3E8E2009,
    SET_TYRE_SMOKE=0xB5BA80F839791C0F, SET_WINDOW_TINT=0x57C51E6BAD752696, SET_PLATE=0x95A88F0B409CDA47, SET_PLATE_INDEX=0x9088EB5A43FFB0A1,
    SET_NEON_ENABLED=0x2AA720E4287BF269, SET_NEON_COLOR=0x8E0A582209A62695, SET_LIVERY=0x60BF608F1B8CD1B6, SET_EXTRA=0x7EE3A3C5E4A40CC9,
    SET_TYRES_BURST=0xEB9DC3C7D8596C46, SET_DRIFT_TYRES=0x5AC79C98C5C17F05, SET_DIRT=0x79D3B596FE44EE8B, FIX=0x115722B1B9C14C1C, ENGINE=0x2497C4717C8B881E,
    SET_INTERIOR=0xF40DD601A65F7F19, SET_DASHBOARD=0x6089CDF6A57F326C, SET_VISIBLE=0xEA1C610A04DB6BBB, SET_ALPHA=0x44A0870B7E92D7C0,
    RESET_ALPHA=0x9B1E824FFBB7027A, FREEZE=0x428CA6DBD1094446,
}

local function garage_signed_hash(h) h=tonumber(h or 0) or 0; if h>2147483647 then h=h-4294967296 end; return h end
local function garage_request_model(hash)
    hash=garage_signed_hash(hash); if hash==0 then return false end
    gi_void(GN394.REQUEST_MODEL,hash)
    for _=1,120 do if gi_bool(GN394.HAS_MODEL_LOADED,hash) then return true,hash end; if Script and Script.Yield then Script.Yield(0) end end
    local unsigned=hash<0 and (hash+4294967296) or hash
    if unsigned~=hash then
        gi_void(GN394.REQUEST_MODEL,unsigned)
        for _=1,60 do if gi_bool(GN394.HAS_MODEL_LOADED,unsigned) then return true,unsigned end; if Script and Script.Yield then Script.Yield(0) end end
    end
    return false,hash
end
local function garage_u32(v)
    v=tonumber(v or 0) or 0
    v=v%4294967296
    if v<0 then v=v+4294967296 end
    return math.floor(v)
end
local function garage_spawn_model(model,label)
    local ped=gi_int(GN394.PLAYER_PED_ID); if ped==0 then return 0,"no player ped" end
    local loaded,requestedHash=garage_request_model(model); if not loaded then return 0,"model request failed" end
    local hash=tonumber(requestedHash or garage_signed_hash(model)) or garage_signed_hash(model)
    local px,py,pz=gi_v3(GN394.GET_ENTITY_COORDS,ped,true); local heading=gi_float(GN394.GET_ENTITY_HEADING,ped)
    local rad=math.rad(heading); local sx=px-math.sin(rad)*6.0; local sy=py+math.cos(rad)*6.0; local sz=pz+0.5

    -- Use CREATE_VEHICLE directly first. This path cannot accidentally select a different
    -- entry from Cherax's Saved Vehicles combo because the exact model hash came from the
    -- selected JSON file above.
    local veh=gi_int(GN394.CREATE_VEHICLE,hash,sx,sy,sz,heading,true,true,false)
    if veh==0 and GTA and GTA.SpawnVehicle then
        pcall(function() veh=tonumber(GTA.SpawnVehicle(hash,sx,sy,sz,heading,true,true) or 0) or 0 end)
    end
    if veh~=0 then gi_void(GN394.SET_MISSION,veh,true,true) end
    gi_void(GN394.SET_MODEL_DONE,hash)
    if veh==0 then return 0,"CREATE_VEHICLE returned 0" end

    -- Hard safety check: never style/reveal a model different from the selected JSON.
    local gotModel=gi_int(GN394.GET_ENTITY_MODEL,veh)
    if gotModel~=0 and garage_u32(gotModel)~=garage_u32(model) then
        local mismatch="spawned model mismatch requested="..tostring(garage_u32(model)).." got="..tostring(garage_u32(gotModel))
        b392_log("Garage DirectJSON blocked wrong model | selected="..tostring(label or "").." | "..mismatch)
        gi_void(GN394.DELETE_ENTITY,veh)
        return 0,mismatch
    end
    return veh,nil
end

local function garage_apply_colors(veh,s)
    gi_void(GN394.SET_COLORS,veh,s.primaryColor or 0,s.secondaryColor or 0); gi_void(GN394.SET_EXTRA_COLORS,veh,s.pearlescentColor or 0,s.wheelColor or 0)
    if s.isPrimaryColorCustom and type(s.customPrimaryColor)=="table" then local c=s.customPrimaryColor; gi_void(GN394.SET_CUSTOM_PRIMARY,veh,c.r or 0,c.g or 0,c.b or 0) else gi_void(GN394.CLEAR_CUSTOM_PRIMARY,veh) end
    if s.isSecondaryColorCustom and type(s.customSecondaryColor)=="table" then local c=s.customSecondaryColor; gi_void(GN394.SET_CUSTOM_SECONDARY,veh,c.r or 0,c.g or 0,c.b or 0) else gi_void(GN394.CLEAR_CUSTOM_SECONDARY,veh) end
    if type(s.tyreSmokeColor)=="table" then local c=s.tyreSmokeColor; gi_void(GN394.SET_TYRE_SMOKE,veh,c.r or 255,c.g or 255,c.b or 255) end
    if s.interiorColor~=nil then gi_void(GN394.SET_INTERIOR,veh,s.interiorColor) end
    if s.dashBoardColor~=nil then gi_void(GN394.SET_DASHBOARD,veh,s.dashBoardColor) end
end
local function garage_apply_saved(veh,s,token)
    if token~=GD394.token then return false end
    gi_void(GN394.SET_MOD_KIT,veh,0); gi_void(GN394.SET_WHEEL_TYPE,veh,s.wheelType or 0); garage_apply_colors(veh,s)
    for modType=0,49 do local m=s.mods and s.mods[modType]; if m then if modType==18 or modType==20 or modType==22 then gi_void(GN394.TOGGLE_MOD,veh,modType,s.toggleMods and s.toggleMods[modType]==true) else gi_void(GN394.SET_MOD,veh,modType,m.nativeIndex,m.variation==true) end end end
    gi_void(GN394.SET_WHEEL_TYPE,veh,s.wheelType or 0); if s.mods and s.mods[23] then local m=s.mods[23]; gi_void(GN394.SET_MOD,veh,23,m.nativeIndex,m.variation==true) end; if s.mods and s.mods[24] then local m=s.mods[24]; gi_void(GN394.SET_MOD,veh,24,m.nativeIndex,m.variation==true) end; garage_apply_colors(veh,s)
    if tonumber(s.liveryID) and tonumber(s.liveryID)>=0 then gi_void(GN394.SET_LIVERY,veh,s.liveryID) end
    if tonumber(s.livery2ID) and tonumber(s.livery2ID)>=0 then gi_void(GN394.SET_MOD,veh,48,garage_saved_to_native(s.livery2ID,s.cheraxFormat==true),false) end
    if s.windowTint~=nil then gi_void(GN394.SET_WINDOW_TINT,veh,s.windowTint) end
    if s.plateTextIndex~=nil then gi_void(GN394.SET_PLATE_INDEX,veh,s.plateTextIndex) end
    if s.plateText and s.plateText~="" then gi_void(GN394.SET_PLATE,veh,tostring(s.plateText)) end
    for extra=1,20 do local enabled=s.extras and s.extras[extra]; if enabled==nil and s.disableExtras~=nil then local bit=2^(extra-1); enabled=(math.floor((tonumber(s.disableExtras or 0) or 0)/bit)%2)==0 end; if enabled~=nil then gi_void(GN394.SET_EXTRA,veh,extra,enabled~=true) end end
    local neonMap={left=0,right=1,front=2,back=3}; for k,idx in pairs(neonMap) do gi_void(GN394.SET_NEON_ENABLED,veh,idx,s.neon and s.neon[k]==true) end
    if type(s.neonColor)=="table" then local c=s.neonColor; gi_void(GN394.SET_NEON_COLOR,veh,c.r or 255,c.g or 0,c.b or 255) end
    if s.bulletproofTyres==true then gi_void(GN394.SET_TYRES_BURST,veh,false) end
    if s.driftTyres==true then gi_void(GN394.SET_DRIFT_TYRES,veh,true) end
    gi_void(GN394.SET_DIRT,veh,s.dirtLevel or 0.0); gi_void(GN394.FIX,veh); gi_void(GN394.ENGINE,veh,true,true,false)
    return true
end
local function garage_cloak(veh) gi_void(GN394.SET_VISIBLE,veh,false,false); gi_void(GN394.SET_ALPHA,veh,0,false); gi_void(GN394.FREEZE,veh,true) end
local function garage_reveal(veh) gi_void(GN394.RESET_ALPHA,veh); gi_void(GN394.SET_VISIBLE,veh,true,false); gi_void(GN394.FREEZE,veh,false) end

local function garage_direct_load(item)
    GD394.busy=true; GD394.token=GD394.token+1; local token=GD394.token
    local label=tostring(item.displayLabel or item.name or "Saved Vehicle"); local path=tostring(item.path or "")
    local body,reader=garage_read_text(path)
    if not body then GD394.busy=false; GD394.failures=GD394.failures+1; G392.status="Vehicle JSON read failed"; b392_log("Garage DirectJSON read failed | selected="..label.." | path="..path.." | reader="..tostring(reader)); b392_toast(G392.status,3000); return false end
    local snap,parseErr=garage_parse_saved_vehicle(body)
    if not snap then GD394.busy=false; GD394.failures=GD394.failures+1; G392.status="Vehicle JSON parse failed"; b392_log("Garage DirectJSON parse failed | selected="..label.." | err="..tostring(parseErr)); b392_toast(G392.status,3000); return false end
    local veh,spawnErr=garage_spawn_model(snap.model,label)
    if veh==0 then GD394.busy=false; GD394.failures=GD394.failures+1; G392.status="Saved vehicle spawn failed"; b392_log("Garage DirectJSON spawn failed | selected="..label.." | model="..tostring(snap.model).." | err="..tostring(spawnErr)); b392_toast(G392.status,3200); return false end
    GD394.activeVehicle=veh
    garage_cloak(veh); garage_apply_saved(veh,snap,token)
    if Script and Script.Yield then Script.Yield(90) end; garage_apply_saved(veh,snap,token)
    if Script and Script.Yield then Script.Yield(160) end; garage_apply_saved(veh,snap,token); garage_reveal(veh)
    if Script and Script.Yield then Script.Yield(650) end; garage_apply_saved(veh,snap,token)
    if Script and Script.Yield then Script.Yield(1300) end; garage_apply_saved(veh,snap,token)
    GD394.activeVehicle=0
    GD394.loads=GD394.loads+1; GD394.busy=false; G392.lastLoaded=label; G392.status="Loaded "..label
    b392_log("Garage DirectJSON exact load | selected="..label.." | model="..tostring(snap.model).." | handle="..tostring(veh).." | reader="..tostring(reader)); b392_toast(G392.status,1800)
    return true
end

local function garage_load(it)
    if not it then G392.status="No vehicle selected"; return false end
    if it.folder then G392.currentFolder=it.category; G392.selected=0; G392.scroll=0; garage_rebuild(); return true end
    if it.random then
        local pool={}; for _,c in ipairs(G392.items) do if it.category=="All" or tostring(c.category):lower()==tostring(it.category):lower() then pool[#pool+1]=c end end
        if #pool==0 then G392.status="No vehicles available for Random"; return false end
        it=pool[math.random(1,#pool)]
    end
    if GD394.busy or GD394.pending then G392.status="Garage load already queued"; b392_toast(G392.status,1800); return false end
    local copy={}; for k,v in pairs(it) do copy[k]=v end
    GD394.pending={item=copy,queuedAt=b392_now()}; G392.status="Queued "..tostring(copy.displayLabel or copy.name or "vehicle")
    return true
end

local function garage_spawn_favorite(source)
    if not G392.scanned then garage_scan(tostring(source or "Favorite").." favorite") end
    local item=garage_find_favorite_item()
    if not item then
        garage_refresh_favorite_combo()
        if tostring(startup.s.essentialsGarageFavoriteRel or "")=="" then
            G392.status="Favorite vehicle not selected"
        else
            G392.status="Favorite vehicle is no longer available"
        end
        b392_toast(G392.status,2400)
        return false
    end
    local ok=garage_load(item)
    if ok then
        G392.favoriteLabel=tostring(item.displayLabel or item.name or "Saved Vehicle")
        b392_toast("Favorite queued: "..G392.favoriteLabel,1800)
    end
    return ok
end

local function gkey(vk)
    if not (Utils and Utils.IsKeyPressed) then return false end
    local ok,p=direct_call(Utils.IsKeyPressed,vk); p=ok and p==true; local was=G392.lastKeys[vk]==true; G392.lastKeys[vk]=p; return p and not was
end
local function gsound(name) pcall(function() if Natives and Natives.InvokeVoid then Natives.InvokeVoid(0xCADA5A0D0702381E,name or "SELECT","HUD_FRONTEND_DEFAULT_SOUNDSET") end end) end
local function garage_sync_toggle()
    if startup.set_feature_bool_silently then direct_call(startup.set_feature_bool_silently,startup.h.EssentialsGarageOpen,G392.open==true) end
end
local function garage_set_open(v)
    G392.open=v==true; G392.lastKeys={}; G392.currentFolder=nil; G392.selected=0; G392.scroll=0; G392.inputLockUntil=b392_now()+220
    if G392.open and not G392.scanned then garage_scan("first open") end
    garage_rebuild(); garage_sync_toggle(); gsound(G392.open and "SELECT" or "BACK")
end
local function garage_selected() garage_rebuild(); return G392.filtered[G392.selected+1] end
local function garage_input()
    if b392_now()<(G392.inputLockUntil or 0) then return end
    if gkey(GK.F5) then garage_scan("F5"); gsound("SELECT") end
    local n=#G392.filtered
    if n<=0 then if gkey(GK.DELETE) or gkey(GK.LEFT) then garage_set_open(false) end; return end
    if gkey(GK.UP) then G392.selected=G392.selected-1; if G392.selected<0 then G392.selected=n-1 end; garage_rebuild(); gsound("NAV_UP_DOWN")
    elseif gkey(GK.DOWN) then G392.selected=G392.selected+1; if G392.selected>=n then G392.selected=0 end; garage_rebuild(); gsound("NAV_UP_DOWN")
    elseif gkey(GK.ENTER) or gkey(GK.RIGHT) then garage_load(garage_selected()); gsound("SELECT")
    elseif gkey(GK.DELETE) or gkey(GK.LEFT) then if G392.currentFolder then G392.currentFolder=nil; G392.selected=0; G392.scroll=0; garage_rebuild(); gsound("BACK") else garage_set_open(false) end end
end
local GARAGE_BLOCK={27,172,173,174,175,176,177,178,179,180,181,182,183,184,185,186,199,200,201,202,24,25,69,70,92,106,114,140,141,142,257,263,264}
local function garage_block_controls()
    if not (Natives and Natives.InvokeVoid) then return end
    -- Own navigation + phone controls only while the Garage HUD is open. Once the HUD
    -- closes these calls stop, so GTA phone input becomes available again naturally.
    for pad=0,2 do
        for _,c in ipairs(GARAGE_BLOCK) do pcall(Natives.InvokeVoid,0xFE99B66D079CF6BC,pad,c,true) end
        for c=172,177 do pcall(Natives.InvokeVoid,0xEDE476E5EE29EDB1,pad,c) end
    end
    -- Close a phone that was already opening before Garage took ownership.
    pcall(Natives.InvokeVoid,0x3BC861DF703E5097)
end
local function g_rect(x,y,w,h,r,g,b,a)
    if not (Natives and Natives.InvokeVoid) then return end
    pcall(Natives.InvokeVoid,0x61BB1D9B3A95D802,7); pcall(Natives.InvokeVoid,0xC6372ECD45D73BCD,true); pcall(Natives.InvokeVoid,0x3A618A217E5154F0,x,y,w,h,r,g,b,a,0)
end
local function g_text(text,x,y,scale,r,g,b,a,justify,wrapL,wrapR,maxChars)
    if not (Natives and Natives.InvokeVoid) then return end
    text=tostring(text or "")
    -- B394: GTA text components themselves have a practical per-component limit. Keep
    -- each component short, but allow a much longer complete Garage label by sending
    -- multiple components before END_TEXT_COMMAND_DISPLAY_TEXT.
    maxChars=tonumber(maxChars or 180) or 180
    if maxChars>0 and #text>maxChars then text=text:sub(1,math.max(1,maxChars-3)).."..." end
    pcall(Natives.InvokeVoid,0x66E0276CC5F6B9DA,4); pcall(Natives.InvokeVoid,0x07C837F9A01C34C9,0.0,scale or 0.225); pcall(Natives.InvokeVoid,0xBE6B23FFA53FB442,r or 255,g or 255,b or 255,a or 255)
    pcall(Natives.InvokeVoid,0x63145D9C883A1A70,wrapL or 0.0,wrapR or 1.0); pcall(Natives.InvokeVoid,0xC02F4DBFB51D988B,justify==0); if justify==2 then pcall(Natives.InvokeVoid,0x6B3C4650BC8BEE47,true) end
    pcall(Natives.InvokeVoid,0x4E096588B13FFECA,justify or 1); pcall(Natives.InvokeVoid,0x2513DFB0FB8400FE); pcall(Natives.InvokeVoid,0x25FBB336DF1804CB,"STRING")
    local pos=1
    while pos<=#text do
        local chunk=text:sub(pos,pos+89)
        pcall(Natives.InvokeVoid,0x6C188BE134E074AA,chunk)
        pos=pos+90
    end
    if text=="" then pcall(Natives.InvokeVoid,0x6C188BE134E074AA,"") end
    pcall(Natives.InvokeVoid,0xCD015E5BB0D96A57,x,y,0)
end

local function garage_render()
    if not G392.open then return end
    garage_block_controls(); garage_input()
    -- B393: filtered rows rebuild only when input/folder/scan state changes. Recreating
    -- the list table every rendered frame caused visible HUD flashing on some Cherax builds.
    local x,y,w=tonumber(G392.x or 0.085) or 0.085,tonumber(G392.y or 0.560) or 0.560,tonumber(G392.width or 0.128) or 0.128
    local op=math.max(0.10,math.min(1.0,tonumber(G392.opacity or 0.50) or 0.50)); local rows,rowH,headerH,subH,footerH=6,0.026,0.040,0.024,0.024
    local h=headerH+subH+rows*rowH+footerH; local l,r=x-w/2,x+w/2
    g_rect(x,y+h/2,w+0.006,h+0.006,150,45,255,math.floor(85*op)); g_rect(x,y+h/2,w,h,5,5,11,math.floor(220*op)); g_rect(x,y+headerH/2,w,headerH,80,0,125,math.floor(240*op)); g_rect(x,y+headerH+subH/2,w,subH,0,0,0,math.floor(220*op))
    g_text("STARTUP GARAGE",x,y+0.006,0.245,255,255,255,255,0)
    local fl=G392.currentFolder and ("/"..tostring(G392.currentFolder)) or "Root"; g_text("[ "..fl.." ]",l+0.009,y+headerH+0.003,0.210,G392.currentFolder and 90 or 255,255,G392.currentFolder and 120 or 255,255,1,l+0.006,r-0.010,180)
    if #G392.filtered==0 then g_text("No vehicles loaded",l+0.010,y+headerH+subH+0.010,0.225,255,120,120,240,1,l+0.006,r-0.010,80)
    else
        for i=1,rows do
            local idx=G392.scroll+i; local it=G392.filtered[idx]; local ry=y+headerH+subH+((i-0.5)*rowH)
            if it then
                local sel=(idx-1)==G392.selected
                g_rect(x,ry,w-0.010,rowH-0.002,sel and 115 or 9,sel and 45 or 7,sel and 255 or 16,math.floor((sel and 220 or 205)*op))
                local cr,cg,cb=245,245,255; if it.random then cr,cg,cb=255,70,130 elseif it.folder then cr,cg,cb=90,255,120 end
                local label=tostring(it.displayLabel or it.name or "Vehicle")
                local len=#label; local labelScale=0.218
                if len>120 then labelScale=0.132 elseif len>90 then labelScale=0.145 elseif len>64 then labelScale=0.164 elseif len>50 then labelScale=0.178 elseif len>38 then labelScale=0.194 end
                g_text(label,l+0.009,ry-0.010,labelScale,cr,cg,cb,245,1,l+0.006,r-0.022,180)
                if sel then g_text(">",r-0.010,ry-0.010,0.230,255,255,255,245,2,l+0.006,r-0.006,2) end
            end
        end
    end
    local fy=y+h-footerH/2; g_rect(x,fy,w,footerH,35,0,55,math.floor(235*op)); g_text(G392.currentFolder and "ENTER | DEL BACK | F5 SCAN" or "ENTER | DEL CLOSE | F5 SCAN",x,fy-0.009,0.168,220,220,235,235,0)
end

