-- B394: render the Garage on Cherax's feature OnTick callback, matching DriftGod's
-- stable HUD timing instead of a free-running Script loop. The load worker remains
-- separate so model requests/style passes may yield without stalling the HUD callback.
local garageRuntimeFeature=nil
pcall(function()
    if FeatureMgr and FeatureMgr.AddFeature and eFeatureType and eFeatureType.Toggle and Utils and Utils.Joaat then
        local hash=Utils.Joaat("StartupEssentialsGarageRuntime394")
        if FeatureMgr.RemoveFeature then pcall(FeatureMgr.RemoveFeature,hash) end
        garageRuntimeFeature=FeatureMgr.AddFeature(hash,"Startup Garage Runtime",eFeatureType.Toggle,"Hidden stable renderer for Startup Garage HUD.",function(f)
            if f and f.IsToggled and not f:IsToggled() then return end
            local ok,err=pcall(function()
                local garageHotkeyCode=tonumber(G392.hotkeyCode or 0) or 0
                if garageHotkeyCode~=0 and gkey(garageHotkeyCode) then garage_set_open(not G392.open) end
                local favoriteHotkeyCode=tonumber(G392.favoriteHotkeyCode or 0) or 0
                if favoriteHotkeyCode~=0 and gkey(favoriteHotkeyCode) then garage_spawn_favorite("Favorite hotkey") end
                garage_render()
            end)
            if not ok then G392.status="Garage runtime protected: "..tostring(err); b392_log(G392.status) end
        end,true)
        if garageRuntimeFeature and garageRuntimeFeature.RegisterCallbackTrigger and eCallbackTrigger then
            if eCallbackTrigger.OnTick then garageRuntimeFeature:RegisterCallbackTrigger(eCallbackTrigger.OnTick)
            elseif eCallbackTrigger.ON_TICK then garageRuntimeFeature:RegisterCallbackTrigger(eCallbackTrigger.ON_TICK) end
        end
        if garageRuntimeFeature and garageRuntimeFeature.SetSaveable then garageRuntimeFeature:SetSaveable(false) end
        if garageRuntimeFeature and garageRuntimeFeature.SetDefaultValue then pcall(function() garageRuntimeFeature:SetDefaultValue(true) end) end
        if garageRuntimeFeature and garageRuntimeFeature.Reset then pcall(function() garageRuntimeFeature:Reset() end)
        elseif garageRuntimeFeature and garageRuntimeFeature.IsToggled and garageRuntimeFeature.Toggle and not garageRuntimeFeature:IsToggled() then pcall(function() garageRuntimeFeature:Toggle() end) end
    end
end)

if Script and Script.RegisterLooped then
    Script.RegisterLooped(function()
        if ShouldUnload and ShouldUnload() then if Script.Yield then Script.Yield(100) end return end
        if GD394.pending and GD394.busy~=true then
            local pending=GD394.pending; GD394.pending=nil
            local ok,err=pcall(function() return garage_direct_load(pending.item) end)
            if not ok then
                local orphan=tonumber(GD394.activeVehicle or 0) or 0
                if orphan~=0 then pcall(function() garage_reveal(orphan) end) end
                GD394.activeVehicle=0; GD394.busy=false; GD394.failures=GD394.failures+1
                G392.status="Garage load worker protected: "..tostring(err); b392_log(G392.status); b392_toast("Garage load failed safely. Check Cherax.log.",3200)
            end
            if Script.Yield then Script.Yield(50) end
        else
            if Script.Yield then Script.Yield(80) end
        end
    end)
end

