            startup.text_colored(0.72,0.42,1.00,1.00,"GARAGE HUD"); startup.render_feature_guarded_325(startup.h.EssentialsGarageOpen); startup.render_feature_guarded_325(startup.h.EssentialsGarageRandom); startup.render_feature_guarded_325(startup.h.EssentialsGarageScan); startup.render_feature_guarded_325(startup.h.EssentialsGaragePosition); startup.render_feature_guarded_325(startup.h.EssentialsGarageHotkey); startup.render_feature_guarded_325(startup.h.EssentialsGarageFavoriteVehicle); startup.render_feature_guarded_325(startup.h.EssentialsGarageFavorite); startup.render_feature_guarded_325(startup.h.EssentialsGarageFavoriteHotkey); ImGui.Separator(); startup.subtle_text("Controls: ↑ ↓ • Enter/Right load • Delete/Left back • F5 scan"); startup.subtle_text("Garage Hotkey: "..tostring(G392.hotkeyName or "None")); startup.subtle_text("Favorite: "..tostring(G392.favoriteLabel or "None")); startup.subtle_text("Favorite Hotkey: "..tostring(G392.favoriteHotkeyName or "None")); startup.subtle_text("Status: "..tostring(G392.status or "Ready")); startup.subtle_text("Last loaded: "..tostring(G392.lastLoaded or "None")); ClickGUI.EndCustomChildWindow()
