startup.install_build398_one_button=function()
-- ============================================================================
-- BUILD 398: ONE-BUTTON SMART ADVERTISE AUTO
-- ============================================================================
-- One action owns the entire adaptive workflow:
--   1) import every completed B378 cold-start result already on disk;
--   2) if no complete 9-region baseline exists, run B378 automatically once;
--   3) when learning is available, start a single 1 Hz serialized Smart Advertise
--      controller using Cold Start / Building / Momentum / Fill stages;
--   4) learn from live region segments and persist them for later sessions.
-- B398 does not revive B374/B375 high-frequency benchmark behavior and never
-- pulse-spams Advertise Session. Region writes are serialized by B375.

startup.b398 = startup.b398 or {}
local B398 = startup.b398
B398.active = false
B398.pending_benchmark = false
B398.status = "Ready — press Smart Advertise — AUTO"
B398.stage = "Idle"
B398.current_region = ""
B398.current_region_started_ms = 0
B398.segment_started_ms = 0
B398.segment_start_players = 0
B398.segment_stage = "Idle"
B398.segment_joins = 0
B398.segment_leaves = 0
B398.last_join_ms = 0
B398.last_leave_ms = 0
B398.last_switch_ms = 0
B398.next_tick_ms = 0
B398.sync_pending = false
B398.sync_target = ""
B398.sync_started_ms = 0
B398.sync_timeout_ms = 30000
B398.complete_benchmark_runs = 0
B398.total_learning_samples = 0
B398.learning = {}
B398.seen = {}
B398.loaded_learning = false
B398.target_players = startup.clamp_int(startup.s.advertisingTargetPlayers373 or 30,5,30)
B398.cold_stall_ms = 150000
B398.cold_hard_ms = 240000
B398.build_stall_ms = 180000
B398.momentum_stall_ms = 240000
B398.switch_cooldown_ms = 45000
B398.learning_csv = tostring(startup.diagnostics_dir or startup.save_dir or "") .. "\\Advertising_Smart_Learning_B398.csv"
B398.log_path = tostring(startup.diagnostics_dir or startup.save_dir or "") .. "\\Advertising_Smart_Auto_B398.log"
B398.fallback_order = {"Africa","My Region","West America","China","Japan","Europe","East America","Australia","Northern Asia"}
B398.regions = {"My Region","Northern Asia","Africa","East America","Europe","China","Australia","West America","Japan"}

local function b398_now()
    if startup.b378_now then return startup.b378_now() end
    if startup.now then return startup.now() end
    return math.floor((os.clock and os.clock() or 0) * 1000)
end

local function b398_log(kind, detail)
    local line=os.date("%Y-%m-%d %H:%M:%S").." | B398_"..tostring(kind or "EVENT").." | "..tostring(detail or "")
    if io and io.open then
        local f=io.open(B398.log_path,"a")
        if f then f:write(line,"\n"); f:close() end
    end
    if startup.support_log_event_quiet then direct_call(startup.support_log_event_quiet,"B398_"..tostring(kind or "EVENT"),tostring(detail or "")) end
end

local function b398_csv_parse(line)
    line=tostring(line or "")
    local out,buf,inQuote={},"",false
    local i=1
    while i<=#line do
        local c=line:sub(i,i)
        if c=='"' then
            if inQuote and line:sub(i+1,i+1)=='"' then buf=buf..'"'; i=i+1
            else inQuote=not inQuote end
        elseif c==',' and not inQuote then out[#out+1]=buf; buf=""
        else buf=buf..c end
        i=i+1
    end
    out[#out+1]=buf
    return out
end

local function b398_csv_escape(v)
    local s=tostring(v==nil and "" or v)
    if s:find('[,"\n]') then s='"'..s:gsub('"','""')..'"' end
    return s
end

local function b398_median(values)
    local a={}
    for _,v in ipairs(values or {}) do if tonumber(v) then a[#a+1]=tonumber(v) end end
    if #a==0 then return nil end
    table.sort(a)
    local n=#a
    if n%2==1 then return a[(n+1)/2] end
    return (a[n/2]+a[n/2+1])/2
end

local function b398_bucket(stage,region)
    stage=tostring(stage or "Cold Start")
    region=tostring(region or "Unknown")
    B398.learning[stage]=B398.learning[stage] or {}
    local b=B398.learning[stage][region]
    if not b then
        b={samples=0,positive=0,target=0,timeToTarget={},joins=0,leaves=0,net=0,elapsedMs=0}
        B398.learning[stage][region]=b
    end
    return b
end

local function b398_add_sample(stage,region,joins,leaves,elapsedMs,positive,target,timeToTarget,key)
    if key and B398.seen[key] then return false end
    if key then B398.seen[key]=true end
    local b=b398_bucket(stage,region)
    b.samples=b.samples+1
    b.joins=b.joins+(tonumber(joins or 0) or 0)
    b.leaves=b.leaves+(tonumber(leaves or 0) or 0)
    b.net=b.net+((tonumber(joins or 0) or 0)-(tonumber(leaves or 0) or 0))
    b.elapsedMs=b.elapsedMs+math.max(1,tonumber(elapsedMs or 1) or 1)
    if positive==true then b.positive=b.positive+1 end
    if target==true then b.target=b.target+1 end
    if tonumber(timeToTarget) then b.timeToTarget[#b.timeToTarget+1]=tonumber(timeToTarget) end
    B398.total_learning_samples=(tonumber(B398.total_learning_samples or 0) or 0)+1
    return true
end

local function b398_import_b378_file(path, runCounts)
    local f=io and io.open and io.open(tostring(path or ""),"r") or nil
    if not f then return 0 end
    local header=f:read("*l")
    if not header then f:close(); return 0 end
    local cols=b398_csv_parse(header)
    local map={}
    for i,name in ipairs(cols) do map[tostring(name)]=i end
    local imported=0
    for line in f:lines() do
        local r=b398_csv_parse(line)
        local run=tostring(r[map.RunId or 1] or "")
        local region=tostring(r[map.Region or 3] or "")
        local result=tostring(r[map.Result or 4] or "")
        if run~="" and region~="" and startup.b373 and startup.b373.region_index and startup.b373.region_index[region]~=nil and region~="Unknown" then
            local joins=tonumber(r[map.ObservedJoins or 14] or 0) or 0
            local leaves=tonumber(r[map.ObservedLeaves or 15] or 0) or 0
            local elapsed=tonumber(r[map.TestElapsedMs or 19] or 0) or 0
            local tt=tonumber(r[map.TimeTo10PlayersMs or 17] or "")
            local target=result=="TARGET_10_REACHED"
            local key="B378|"..run.."|"..region
            if b398_add_sample("Cold Start",region,joins,leaves,elapsed,(joins-leaves)>0,target,tt,key) then imported=imported+1 end
            runCounts[run]=runCounts[run] or {}
            runCounts[run][region]=true
        end
    end
    f:close()
    return imported
end

local function b398_import_live_learning()
    local f=io and io.open and io.open(B398.learning_csv,"r") or nil
    if not f then return 0 end
    local header=f:read("*l")
    if not header then f:close(); return 0 end
    local cols=b398_csv_parse(header); local map={}
    for i,name in ipairs(cols) do map[tostring(name)]=i end
    local n=0
    for line in f:lines() do
        local r=b398_csv_parse(line)
        local stamp=tostring(r[map.Timestamp or 1] or "")
        local stage=tostring(r[map.Stage or 3] or "")
        local region=tostring(r[map.Region or 4] or "")
        if stage~="" and region~="" and region~="Unknown" then
            local joins=tonumber(r[map.Joins or 7] or 0) or 0
            local leaves=tonumber(r[map.Leaves or 8] or 0) or 0
            local elapsed=tonumber(r[map.ElapsedMs or 9] or 0) or 0
            local decision=tostring(r[map.Decision or 10] or "")
            local key="LIVE|"..stamp.."|"..stage.."|"..region.."|"..tostring(elapsed).."|"..decision
            if b398_add_sample(stage,region,joins,leaves,elapsed,(joins-leaves)>0,false,nil,key) then n=n+1 end
        end
    end
    f:close(); return n
end

function startup.b398_reload_learning()
    B398.learning={}; B398.seen={}; B398.total_learning_samples=0; B398.complete_benchmark_runs=0
    local runCounts={}
    local imported=0
    if FileMgr and FileMgr.FindFiles then
        local ok,files=pcall(function() return FileMgr.FindFiles(tostring(startup.diagnostics_dir or startup.save_dir or ""),".csv",false) end)
        if ok and files then
            for _,path in ipairs(files) do
                local p=tostring(path or "")
                local name=p:gsub("/","\\"):match("([^\\]+)$") or p
                if name:find("Advertising_ColdStart_B378_B378_",1,true) and not name:find("_RAW_",1,true) then
                    imported=imported+b398_import_b378_file(p,runCounts)
                end
            end
        end
    end
    for _,regions in pairs(runCounts) do
        local count=0; for _ in pairs(regions) do count=count+1 end
        if count>=9 then B398.complete_benchmark_runs=B398.complete_benchmark_runs+1 end
    end
    imported=imported+b398_import_live_learning()
    B398.loaded_learning=true
    b398_log("LEARNING_LOAD","samples="..tostring(B398.total_learning_samples).." | imported="..tostring(imported).." | completeB378="..tostring(B398.complete_benchmark_runs))
    return B398.complete_benchmark_runs,B398.total_learning_samples
end

local function b398_stage(players)
    players=tonumber(players or 0) or 0
    if players<=4 then return "Cold Start" end
    if players<=9 then return "Building" end
    if players<=19 then return "Momentum" end
    return "Fill"
end

-- B400: Smart Auto must not trust the legacy table-only session count. Some Cherax
-- builds expose Players.Get(...) as indexable userdata; pairs() can then report only
-- the local player even while the lobby is full. Reuse Startup's robust player-ID
-- enumerator (which probes table + userdata slots) and take the strongest sane count.
function startup.b398_get_player_count()
    local best = 0

    if startup.get_session_player_count then
        local ok, n = direct_call(startup.get_session_player_count)
        if ok then
            n = math.floor(tonumber(n or 0) or 0)
            if n > best then best = n end
        end
    end

    if startup.get_voice_player_ids then
        local ok, ids = direct_call(startup.get_voice_player_ids)
        if ok and type(ids) == "table" then
            local n = #ids
            if n > best then best = n end
        end
    end

    -- Final direct fallback for unusual Cherax userdata containers.
    if best <= 1 and Players and Players.Get then
        local ok, players = pcall(function()
            return Players.Get(ePlayerListSort.PLAYER_ID, "")
        end)
        if ok and players then
            local seen = {}
            local function add(v)
                v = tonumber(v)
                if v ~= nil and v >= 0 and v <= 31 then seen[math.floor(v)] = true end
            end
            pcall(function() for _, v in pairs(players) do add(v) end end)
            for i = 0, 31 do
                local ok0, v0 = pcall(function() return players[i] end)
                if ok0 then add(v0) end
            end
            for i = 1, 32 do
                local ok1, v1 = pcall(function() return players[i] end)
                if ok1 then add(v1) end
            end
            local n = 0
            for _ in pairs(seen) do n = n + 1 end
            if n > best then best = n end
        end
    end

    if best < 0 then best = 0 end
    if best > 32 then best = 32 end
    B398.last_player_count = best
    return best
end

local function b398_score(region,stage)
    local function score_bucket(b,isCold)
        if not b or (tonumber(b.samples or 0) or 0)<=0 then return nil end
        local samples=math.max(1,tonumber(b.samples or 0) or 1)
        local mins=math.max(0.01,(tonumber(b.elapsedMs or 0) or 0)/60000)
        local joinRate=(tonumber(b.joins or 0) or 0)/mins
        local netRate=(tonumber(b.net or 0) or 0)/mins
        local positive=(tonumber(b.positive or 0) or 0)/samples
        local churn=(tonumber(b.leaves or 0) or 0)/math.max(1,tonumber(b.joins or 0) or 0)
        if isCold then
            local success=(tonumber(b.target or 0) or 0)/samples
            local med=b398_median(b.timeToTarget) or 900000
            return success*1000 + joinRate*30 + netRate*35 + positive*100 - (med/1000)*0.35 - churn*80
        end
        return positive*260 + netRate*110 + joinRate*24 - churn*65
    end
    local cold=B398.learning["Cold Start"] and B398.learning["Cold Start"][region] or nil
    local own=B398.learning[stage] and B398.learning[stage][region] or nil
    if stage=="Cold Start" then
        local s=score_bucket(cold,true); if s~=nil then return s end
    else
        local ownScore=score_bucket(own,false)
        local coldScore=score_bucket(cold,true)
        if ownScore~=nil and coldScore~=nil then return ownScore+coldScore*0.15 end
        if ownScore~=nil then return ownScore end
        if coldScore~=nil then return coldScore*0.20 end
    end
    for i,r in ipairs(B398.fallback_order) do if r==region then return 100-i end end
    return 0
end

local function b398_rank(stage)
    local rows={}
    for _,region in ipairs(B398.regions) do rows[#rows+1]={region=region,score=b398_score(region,stage)} end
    table.sort(rows,function(a,b) if a.score==b.score then return a.region<b.region end return a.score>b.score end)
    return rows
end

local function b398_choose(stage,avoid)
    local ranked=b398_rank(stage)
    for _,row in ipairs(ranked) do if tostring(row.region)~=tostring(avoid or "") then return row.region,row.score,ranked end end
    return ranked[1] and ranked[1].region or "My Region",ranked[1] and ranked[1].score or 0,ranked
end

local function b398_ensure_learning_header()
    local exists=false
    if FileMgr and FileMgr.DoesFileExist then pcall(function() exists=FileMgr.DoesFileExist(B398.learning_csv)==true end) end
    if not exists and io and io.open then
        local f=io.open(B398.learning_csv,"w")
        if f then f:write("Timestamp,Source,Stage,Region,StartPlayers,EndPlayers,Joins,Leaves,ElapsedMs,Decision\n"); f:close() end
    end
end

local function b398_write_live(stage,region,startPlayers,endPlayers,joins,leaves,elapsed,decision)
    b398_ensure_learning_header()
    local stamp=os.date("%Y-%m-%d %H:%M:%S")
    local vals={stamp,"SMART_AUTO",stage,region,startPlayers,endPlayers,joins,leaves,elapsed,decision}
    for i,v in ipairs(vals) do vals[i]=b398_csv_escape(v) end
    if io and io.open then local f=io.open(B398.learning_csv,"a"); if f then f:write(table.concat(vals,","),"\n"); f:close() end end
    b398_add_sample(stage,region,joins,leaves,elapsed,(joins-leaves)>0,false,nil,"RUNTIME|"..stamp.."|"..stage.."|"..region.."|"..tostring(elapsed).."|"..tostring(decision))
end

local function b398_reset_segment(stage,region,players)
    local now=b398_now()
    B398.segment_stage=tostring(stage or b398_stage(players))
    B398.segment_started_ms=now
    B398.segment_start_players=tonumber(players or 0) or 0
    B398.segment_joins=0; B398.segment_leaves=0
    B398.last_join_ms=0; B398.last_leave_ms=0
    B398.current_region_started_ms=now
end

local function b398_finalize_segment(decision)
    if B398.segment_started_ms<=0 or tostring(B398.current_region or "")=="" then return end
    local now=b398_now(); local players=startup.b398_get_player_count()
    local elapsed=math.max(1,now-B398.segment_started_ms)
    b398_write_live(B398.segment_stage,B398.current_region,B398.segment_start_players,players,B398.segment_joins,B398.segment_leaves,elapsed,decision)
    b398_log("SEGMENT",B398.segment_stage.." | "..B398.current_region.." | start="..tostring(B398.segment_start_players).." end="..tostring(players).." joins="..tostring(B398.segment_joins).." leaves="..tostring(B398.segment_leaves).." elapsedMs="..tostring(elapsed).." decision="..tostring(decision))
end

local function b398_activate_region(region,reason)
    if B398.active~=true then return false end
    region=tostring(region or "My Region")
    local now=b398_now()
    if B398.sync_pending then return false end
    local ov=startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
    local adv=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
    local function activated()
        local players=startup.b398_get_player_count()
        B398.current_region=region; B398.last_switch_ms=b398_now(); B398.stage=b398_stage(players)
        b398_reset_segment(B398.stage,region,players)
        B398.status="Active — "..B398.stage.." | "..region
        startup.s.lastAdvertiseStatus="Smart Auto | "..B398.stage.." | "..region
        b398_log("REGION_ACTIVE",region.." | stage="..B398.stage.." | reason="..tostring(reason or "auto"))
    end
    if tostring(ov)==region and tostring(adv)==region then activated(); return true end
    if not startup.b375_queue_region_pair then B398.status="Region sync unavailable"; return false end
    B398.sync_pending=true; B398.sync_target=region; B398.sync_started_ms=now
    B398.status="Sync target "..region.." | actual "..tostring(ov).."/"..tostring(adv)
    local ok,why=startup.b375_queue_region_pair(region,"B398 Smart Auto: "..tostring(reason or "adaptive"),function(success,detail,target)
        B398.sync_pending=false; B398.sync_target=""; B398.sync_started_ms=0
        if B398.active~=true then return end
        if success==true then region=tostring(target or region); activated()
        else B398.status="Region sync failed: "..tostring(detail); b398_log("REGION_SYNC_FAIL",tostring(target).." | "..tostring(detail)) end
    end)
    if ok~=true then B398.sync_pending=false; B398.sync_target=""; B398.sync_started_ms=0; B398.status="Region sync busy: "..tostring(why); return false end
    return true
end

local function b398_rotate(reason)
    if B398.active~=true or B398.sync_pending then return false end
    local now=b398_now()
    if now-(tonumber(B398.last_switch_ms or 0) or 0)<B398.switch_cooldown_ms then return false end
    local target=b398_choose(B398.stage,B398.current_region)
    if not target or target==B398.current_region then return false end
    b398_finalize_segment("ROTATE:"..tostring(reason or "adaptive"))
    B398.status="Rotating to "..target.." — "..tostring(reason or "adaptive")
    return b398_activate_region(target,reason)
end

local function b399_cancel_owned_region_job(reason)
    local j=startup.b375 and startup.b375.region_job or nil
    if type(j)=="table" and tostring(j.reason or ""):find("B398 Smart Auto:",1,true)==1 then
        if startup.b375_complete_region_job then
            direct_call(startup.b375_complete_region_job,false,tostring(reason or "B399 cancelled Smart Auto region sync"))
        else
            startup.b375.region_job=nil
        end
        return true
    end
    return false
end

function startup.b398_stop(reason)
    if B398.pending_benchmark==true and startup.b378 and startup.b378.active==true then
        B398.pending_benchmark=false
        startup.b378_finish("Smart Auto cancelled by user",true)
    end
    if B398.active~=true then b399_cancel_owned_region_job("Smart Auto stopped"); B398.sync_pending=false; B398.sync_target=""; B398.sync_started_ms=0; B398.status=tostring(reason or "Stopped"); return true end
    b398_finalize_segment("STOP:"..tostring(reason or "user"))
    b399_cancel_owned_region_job("Smart Auto stopped")
    B398.active=false; B398.sync_pending=false; B398.sync_target=""; B398.sync_started_ms=0; B398.stage="Idle"; B398.status=tostring(reason or "Stopped")
    startup.s.advertiseRunning=false; startup.s.advertiseSmartActive=false; startup.s.advertiseStopRequested=false
    startup.s.lastAdvertiseStatus="Smart Auto stopped"
    b398_log("STOP",tostring(reason or "Stopped"))
    return true
end

function startup.b398_start_smart(reason)
    if B398.active==true then B398.status="Smart Auto is already running"; return true end
    if startup.b378 and startup.b378.active==true then B398.pending_benchmark=true; B398.status="Waiting for active B378 benchmark to finish"; return true end
    if startup.b374 and startup.b374.active==true then if startup.toast then startup.toast("Wait for the active advertising benchmark to finish first.",4500) end; return false end
    if B398.loaded_learning~=true then startup.b398_reload_learning() end

    if startup.b377_save_logical_state then direct_call(startup.b377_save_logical_state) end
    if startup.b377_disable_startup_advertising_automation then direct_call(startup.b377_disable_startup_advertising_automation) end
    if startup.b373_stop_engine then direct_call(startup.b373_stop_engine,"B398 Smart Auto owns advertising",false) end

    local advOk=false
    if startup.b379_explicit_advertise_on then
        local ok,res=pcall(startup.b379_explicit_advertise_on,"B398 Smart Auto start")
        advOk=ok and res==true
    elseif startup.set_advertise_session then
        local ok,res=direct_call(startup.set_advertise_session,true,true); advOk=ok and res~=false
    end
    if not advOk then B398.status="Could not enable Advertise Session safely"; if startup.toast then startup.toast(B398.status,5500) end; return false end

    B398.active=true; B398.pending_benchmark=false; B398.stage="Selecting"; B398.current_region=""; B398.next_tick_ms=0
    B398.last_switch_ms=0; B398.segment_started_ms=0; B398.segment_joins=0; B398.segment_leaves=0
    startup.s.advertiseRunning=true; startup.s.advertiseSmartActive=false; startup.s.advertiseStopRequested=false
    local players=startup.b398_get_player_count()
    B398.target_players=startup.clamp_int(startup.s.advertisingTargetPlayers373 or B398.target_players or 30,5,30)
    B398.stage=b398_stage(players)

    -- B399: never disturb an already-full / Fill-stage lobby just to synchronize to
    -- the historical cold-start winner. At 20+ players the successful current lobby
    -- is stronger evidence than a cold-start ranking, so inherit and HOLD its region.
    if players>=B398.target_players or B398.stage=="Fill" then
        local ov=startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
        local adv=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
        local hold=tostring(adv or "Unknown")
        if not startup.b373 or not startup.b373.region_index or startup.b373.region_index[hold]==nil or hold=="Unknown" then hold=tostring(ov or "Unknown") end
        if not startup.b373 or not startup.b373.region_index or startup.b373.region_index[hold]==nil or hold=="Unknown" then hold="My Region" end
        B398.current_region=hold; B398.last_switch_ms=b398_now(); b398_reset_segment("Fill",hold,players)
        B398.status="Fill — holding existing "..hold.." at "..tostring(players).." players"
        startup.s.lastAdvertiseStatus=B398.status
        b398_log("START_HOLD_FULL","reason="..tostring(reason or "button").." | players="..tostring(players).." | target="..tostring(B398.target_players).." | region="..hold)
        if startup.toast then startup.toast("Smart Advertise AUTO: lobby is already full/filling. Holding the current region; no synchronization needed.",6500) end
        return true
    end

    local region,score=b398_choose(B398.stage,nil)
    B398.status="Starting "..B398.stage.." with "..tostring(region)
    b398_log("START","reason="..tostring(reason or "button").." | players="..tostring(players).." | stage="..B398.stage.." | best="..tostring(region).." | score="..string.format("%.2f",tonumber(score or 0) or 0).." | benchmarkRuns="..tostring(B398.complete_benchmark_runs).." | samples="..tostring(B398.total_learning_samples))
    b398_activate_region(region,"best learned region for "..B398.stage)
    if startup.toast then startup.toast("Smart Advertise AUTO started. Startup now owns region selection and learning.",6500) end
    return true
end

function startup.b398_auto_button()
    if B398.active==true then if startup.toast then startup.toast("Smart Advertise AUTO is already running.",2800) end; return true end
    local runs,samples=startup.b398_reload_learning()
    if tonumber(runs or 0)<=0 then
        B398.pending_benchmark=true
        B398.status="No complete cold-start baseline — starting B378 automatically"
        b398_log("AUTO_BENCHMARK_REQUIRED","samples="..tostring(samples or 0))
        local ok=startup.b378_start and startup.b378_start() or false
        if ok~=true then B398.pending_benchmark=false; B398.status="Automatic B378 start failed — check preflight"; return false end
        if startup.toast then startup.toast("No complete baseline found. B378 is running automatically; Smart Advertise will start when it finishes.",8500) end
        return true
    end
    return startup.b398_start_smart("one-button existing learning")
end

function startup.b398_tick()
    if B398.active~=true then return end
    local now=b398_now(); if now<(tonumber(B398.next_tick_ms or 0) or 0) then return end; B398.next_tick_ms=now+1000
    if startup.b378 and startup.b378.active==true then return end

    -- B399: B398 queues region writes through B375, so B398 must also drive B375's
    -- serialized WAIT_STABLE -> OVERRIDE -> ADVERTISE -> VERIFY state machine. The final
    -- B377 override of b374_tick intentionally sleeps when B377 is inactive, which left
    -- B398's queue parked forever at "Synchronizing <region>" in B398.
    local stable=true
    if startup.b375_update_session_stability then
        local ok,res=direct_call(startup.b375_update_session_stability,now); stable=ok and res==true
    end
    if B398.sync_pending==true then
        -- B400: if the real lobby has already reached Fill stage while an old Cold Start
        -- sync is pending, the live lobby wins. Cancel the queued change before it can
        -- disturb a successful session, inherit the actual synchronized Cherax region,
        -- and immediately transition Smart Auto to HOLD.
        local livePlayers = startup.b398_get_player_count()
        if livePlayers >= 20 then
            local ov = startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
            local adv = startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
            local hold = tostring(adv or "Unknown")
            if not startup.b373 or not startup.b373.region_index or startup.b373.region_index[hold] == nil or hold == "Unknown" then hold = tostring(ov or "Unknown") end
            if not startup.b373 or not startup.b373.region_index or startup.b373.region_index[hold] == nil or hold == "Unknown" then hold = "My Region" end

            b399_cancel_owned_region_job("B400 Fill-stage reconciliation cancelled pending Smart Auto sync")
            B398.sync_pending=false; B398.sync_target=""; B398.sync_started_ms=0
            B398.current_region=hold; B398.stage="Fill"; B398.last_switch_ms=now
            b398_reset_segment("Fill",hold,livePlayers)
            B398.status="Fill — holding actual "..hold.." at "..tostring(livePlayers).." players"
            startup.s.lastAdvertiseStatus=B398.status
            b398_log("SYNC_ABORT_FILL","players="..tostring(livePlayers).." | override="..tostring(ov).." | advertise="..tostring(adv).." | hold="..hold)
        else
            local ov = startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
            local adv = startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
            local elapsed = math.max(0, now-(tonumber(B398.sync_started_ms or now) or now))
            B398.status="Sync target "..tostring(B398.sync_target).." | actual "..tostring(ov).."/"..tostring(adv).." | "..tostring(math.floor(elapsed/1000)).."s"
        end

        if B398.sync_pending==true and stable==true and startup.b375_process_region_job then direct_call(startup.b375_process_region_job,now) end
        if B398.sync_pending==true then
            local started=tonumber(B398.sync_started_ms or 0) or 0
            if started>0 and now-started>=B398.sync_timeout_ms then
                b398_log("REGION_SYNC_TIMEOUT",tostring(B398.sync_target).." | elapsedMs="..tostring(now-started))
                b399_cancel_owned_region_job("B399 Smart Auto region sync timed out after 30 seconds")
                B398.sync_pending=false; B398.sync_target=""; B398.sync_started_ms=0
                B398.status="Region sync timed out safely — holding current session"
            else
                return
            end
        end
    end

    -- Keep legacy automation suppressed while B398 owns advertising.
    startup.s.autoAdvertiseSession=false
    startup.s.advertiseSmartActive=false
    local players=startup.b398_get_player_count()
    B398.target_players=startup.clamp_int(startup.s.advertisingTargetPlayers373 or B398.target_players or 30,5,30)
    local newStage=b398_stage(players)

    if tostring(B398.current_region or "")=="" then
        B398.stage=newStage; local region=b398_choose(newStage,nil); b398_activate_region(region,"initial selection"); return
    end

    if newStage~=B398.stage then
        b398_finalize_segment("STAGE_CHANGE:"..B398.stage.."->"..newStage)
        B398.stage=newStage; b398_reset_segment(newStage,B398.current_region,players)
        B398.status="Active — "..newStage.." | "..B398.current_region
        b398_log("STAGE",newStage.." | players="..tostring(players).." | region="..B398.current_region)
    end

    if players>=B398.target_players then
        B398.status="Target reached — holding "..B398.current_region.." at "..tostring(players).." players"
        return
    end

    local elapsed=now-(tonumber(B398.segment_started_ms or now) or now)
    local net=(tonumber(B398.segment_joins or 0) or 0)-(tonumber(B398.segment_leaves or 0) or 0)
    local sinceJoin=B398.last_join_ms>0 and (now-B398.last_join_ms) or elapsed

    if B398.stage=="Cold Start" then
        if elapsed>=B398.cold_stall_ms and net<=0 and sinceJoin>=B398.cold_stall_ms then
            b398_rotate("cold start stalled")
        elseif elapsed>=B398.cold_hard_ms and players<5 then
            b398_rotate("cold start hard limit")
        else
            B398.status="Cold Start — "..B398.current_region.." | net "..(net>=0 and "+" or "")..tostring(net).." | evaluating"
        end
    elseif B398.stage=="Building" then
        if sinceJoin>=B398.build_stall_ms and net<=0 then b398_rotate("building stalled")
        else B398.status="Building — holding "..B398.current_region.." while lobby grows" end
    elseif B398.stage=="Momentum" then
        if sinceJoin>=B398.momentum_stall_ms and net<=0 then b398_rotate("momentum stalled")
        else B398.status="Momentum — holding "..B398.current_region.."; no unnecessary switching" end
    else
        B398.status="Fill — holding "..B398.current_region.." at "..tostring(players).." players"
    end
end

-- Learn from real join/leave events without setting B373.running and therefore without
-- allowing the old B373 controller to compete with B398.
B398.b373_join_pre=startup.b373_on_join
startup.b373_on_join=function(playerId)
    if B398.active==true and not (startup.b373_is_local_player and startup.b373_is_local_player(playerId)) then
        B398.segment_joins=(tonumber(B398.segment_joins or 0) or 0)+1; B398.last_join_ms=b398_now()
    end
    if B398.b373_join_pre then return B398.b373_join_pre(playerId) end
end
B398.b373_left_pre=startup.b373_on_left
startup.b373_on_left=function(playerId)
    if B398.active==true and not (startup.b373_is_local_player and startup.b373_is_local_player(playerId)) then
        B398.segment_leaves=(tonumber(B398.segment_leaves or 0) or 0)+1; B398.last_leave_ms=b398_now()
    end
    if B398.b373_left_pre then return B398.b373_left_pre(playerId) end
end

-- B378 completion handoff: if the AUTO button had to create its own baseline, import
-- the completed results and immediately continue into Smart Advertise unattended.
B398.b378_finish_pre=startup.b378_finish
startup.b378_finish=function(reason,aborted)
    local pending=B398.pending_benchmark==true
    local ret=B398.b378_finish_pre(reason,aborted)
    if pending then
        if aborted==true then B398.pending_benchmark=false; B398.status="Automatic benchmark stopped — Smart Auto not started"
        else
            B398.status="Benchmark complete — importing learning"
            local function handoff()
                if Script and Script.Yield then Script.Yield(5000) end
                startup.b398_reload_learning(); B398.pending_benchmark=false
                startup.b398_start_smart("automatic handoff after B378")
            end
            if Script and Script.QueueJob then Script.QueueJob(handoff) else handoff() end
        end
    end
    return ret
end

-- Prevent the legacy delayed advertising worker from becoming a second writer while
-- B398 is active. This is an ownership guard only.
B398.run_advertise_flow_pre=startup.run_advertise_flow
startup.run_advertise_flow=function(reason)
    if B398.active==true or B398.pending_benchmark==true then
        startup.s.lastAdvertiseStatus="Smart Auto owns advertising"
        return false
    end
    return B398.run_advertise_flow_pre and B398.run_advertise_flow_pre(reason) or false
end

