startup.install_build401_method_test=function()
-- ============================================================================
-- BUILD 401: ONE-BUTTON ADVERTISING METHOD TEST
-- ============================================================================
-- Controlled mechanism test. Three randomized blocks, six methods per block:
--   CONTROL_OFF      My Region / My Region / Advertise Session OFF
--   SESSION_ONLY     My Region / My Region / Advertise Session ON
--   OVERRIDE_ONLY    Target / My Region / Advertise Session ON
--   ADVERTISE_ONLY   My Region / Target / Advertise Session ON
--   SYNC_PAIR_OFF    Target / Target / Advertise Session OFF
--   SYNC_PAIR_ON     Target / Target / Advertise Session ON
-- Every trial gets a fresh New Public Session, waits for local Session Host,
-- verifies the intended controls after load, then measures up to 5 minutes or
-- until 10 players. This separates the individual Cherax mechanisms instead of
-- changing them all at once.

startup.b401=startup.b401 or {}
local B401=startup.b401
B401.active=false
B401.status="Ready — one button runs 18 controlled fresh-session trials"
B401.phase="IDLE"
B401.repetitions=3
B401.timeout_ms=300000
B401.target_players=10
B401.driver_interval_ms=1000
B401.next_driver_ms=0
B401.next_action_ms=0
B401.native_settle_ms=4000
B401.route_settle_ms=1250
B401.inter_trial_settle_ms=8000
B401.session_timeout_ms=60000
B401.max_retry=1
B401.trials={}
B401.trial_index=0
B401.results={}
B401.current=nil
B401.target_region="Africa"
B401.run_id=""
B401.csv_path=""
B401.summary_path=""
B401.log_path=""
B401.checkpoint_path=""
B401.saved=nil

function startup.b401_now()
    return startup.b378_now and startup.b378_now() or ((startup.now and tonumber(startup.now())) or math.floor((os.clock() or 0)*1000))
end

function startup.b401_log(kind,detail)
    local line=os.date("%Y-%m-%d %H:%M:%S").." | B401_"..tostring(kind or "EVENT").." | "..tostring(detail or "")
    if io and io.open and tostring(B401.log_path or "")~="" then
        local f=io.open(B401.log_path,"a")
        if f then f:write(line,"\n"); f:close() end
    end
    if startup.support_log_event_quiet then direct_call(startup.support_log_event_quiet,"B401_"..tostring(kind or "EVENT"),tostring(detail or "")) end
end

function startup.b401_csv_escape(v)
    local s=tostring(v==nil and "" or v)
    if s:find('[,"\n]') then s='"'..s:gsub('"','""')..'"' end
    return s
end

function startup.b401_median(a)
    local t={}
    for _,v in ipairs(a or {}) do if tonumber(v) then t[#t+1]=tonumber(v) end end
    if #t==0 then return nil end
    table.sort(t)
    if #t%2==1 then return t[(#t+1)/2] end
    return (t[#t/2]+t[#t/2+1])/2
end

function startup.b401_choose_target_region()
    if startup.b398_reload_learning then pcall(startup.b398_reload_learning) end
    local bestRegion,bestSuccess,bestMedian,bestNet=nil,-1,math.huge,-math.huge
    local cold=startup.b398 and startup.b398.learning and startup.b398.learning["Cold Start"] or nil
    if type(cold)=="table" then
        for region,b in pairs(cold) do
            if tostring(region)~="My Region" and tostring(region)~="Unknown" and startup.b373 and startup.b373.region_index and startup.b373.region_index[region]~=nil then
                local samples=math.max(1,tonumber(b.samples or 0) or 1)
                local success=(tonumber(b.target or 0) or 0)/samples
                local med=startup.b401_median(b.timeToTarget) or math.huge
                local mins=math.max(0.01,(tonumber(b.elapsedMs or 0) or 0)/60000)
                local netRate=(tonumber(b.net or 0) or 0)/mins
                if success>bestSuccess or (success==bestSuccess and med<bestMedian) or (success==bestSuccess and med==bestMedian and netRate>bestNet) then
                    bestRegion,bestSuccess,bestMedian,bestNet=tostring(region),success,med,netRate
                end
            end
        end
    end
    if not bestRegion or bestRegion=="" then bestRegion="Africa" end
    return bestRegion
end

function startup.b401_set_advertise_session(desired,reason)
    desired=desired==true
    local feature,mode,detail=nil,"UNAVAILABLE",""
    if startup.b379_resolve_advertise_capability then feature,mode,detail=startup.b379_resolve_advertise_capability() end
    if not feature then return false,"UNAVAILABLE",tostring(detail or "Advertise Session unavailable") end
    local state=startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
    if state~=nil and state==desired then return true,"READABLE","already "..(desired and "ON" or "OFF") end

    local ok,err=false,nil
    if feature.Toggle then
        ok,err=pcall(function() feature:Toggle(desired) end)
    elseif feature.SetBoolValue then
        ok,err=pcall(function() feature:SetBoolValue(desired) end)
    else
        return false,tostring(mode),"No explicit bool setter"
    end
    if ok then
        startup.s.advertiseSessionEnabled=desired
        startup.b375.last_native_action="Advertise Session -> "..(desired and "ON" or "OFF").." (B401)"
        startup.b375.last_native_action_ms=startup.b401_now()
        startup.b401_log("ADVERTISE_SESSION_WRITE",(desired and "ON" or "OFF").." | mode="..tostring(mode).." | reason="..tostring(reason or "method"))
        return true,tostring(mode),tostring(mode)=="WRITE_ONLY_EXPLICIT" and "explicit write accepted" or "write accepted"
    end
    return false,tostring(mode),tostring(err)
end

function startup.b401_verify_advertise_session(expected)
    local state=startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
    if state~=nil then return state==expected,(state and "ON" or "OFF"),"READABLE" end
    local _,mode=startup.b379_resolve_advertise_capability()
    if mode=="WRITE_ONLY_EXPLICIT" then return true,"ASSUMED_"..(expected and "ON" or "OFF"),"WRITE_ONLY_EXPLICIT" end
    return false,"UNKNOWN",tostring(mode or "UNKNOWN")
end

function startup.b401_methods(target)
    target=tostring(target or "Africa")
    return {
        {id="CONTROL_OFF",label="Control: My/My + Session OFF",override="My Region",advertise="My Region",session=false},
        {id="SESSION_ONLY",label="Advertise Session only",override="My Region",advertise="My Region",session=true},
        {id="OVERRIDE_ONLY",label="Override only: "..target,override=target,advertise="My Region",session=true},
        {id="ADVERTISE_ONLY",label="Advertise Region only: "..target,override="My Region",advertise=target,session=true},
        {id="SYNC_PAIR_OFF",label="Synced pair "..target.." + Session OFF",override=target,advertise=target,session=false},
        {id="SYNC_PAIR_ON",label="Synced pair "..target.." + Session ON",override=target,advertise=target,session=true}
    }
end

function startup.b401_make_trials()
    B401.trials={}
    local base=startup.b401_methods(B401.target_region)
    for round=1,B401.repetitions do
        local shuffled={}
        for _,m in ipairs(base) do shuffled[#shuffled+1]=m end
        if startup.b378_lcg_shuffle then shuffled=startup.b378_lcg_shuffle(shuffled) end
        for _,m in ipairs(shuffled) do
            B401.trials[#B401.trials+1]={
                round=round,methodId=m.id,methodLabel=m.label,
                override=m.override,advertise=m.advertise,session=m.session==true
            }
        end
    end
end

function startup.b401_scan_preflight()
    local problems={}
    local sessionFeature=nil
    if startup.feature_hash and startup.feature_hash.SESSION_TYPE and startup.get_feature_by_hash_safe then sessionFeature=startup.get_feature_by_hash_safe(startup.feature_hash.SESSION_TYPE) end
    if not sessionFeature or not sessionFeature.GetListIndexByString or not sessionFeature.SetListIndexByString then
        problems[#problems+1]="New Public Session route unavailable"
    else
        local ok,idx=pcall(function() return sessionFeature:GetListIndexByString("New Public Session") end)
        if not ok or idx==nil then problems[#problems+1]="New Public Session missing" end
    end
    if not (startup.b375 and startup.b375.native_apply_override) then problems[#problems+1]="Override Region setter unavailable" end
    if not (startup.b375 and startup.b375.native_apply_advertise) then problems[#problems+1]="Advertise Region setter unavailable" end
    local feature,mode=startup.b379_resolve_advertise_capability()
    if not feature or mode=="UNSAFE_UNREADABLE" or mode=="UNAVAILABLE" then problems[#problems+1]="Advertise Session explicit bool control unavailable" end
    if not startup.click_start_session_feature then problems[#problems+1]="Start Session unavailable" end
    if #problems>0 then return false,table.concat(problems," | ") end
    return true,"PASS | route + Override + Advertise Region + explicit Advertise Session bool"
end

function startup.b401_write_header()
    if not io or not io.open then return false end
    local f=io.open(B401.csv_path,"w"); if not f then return false end
    f:write("RunId,TrialIndex,Round,MethodId,MethodLabel,TargetRegion,OverrideRegion,AdvertiseRegion,AdvertiseSession,SessionVerification,Result,RetryCount,SessionClickToEventMs,SessionEventToReadyMs,SessionClickToReadyMs,StartPlayers,EndPlayers,PeakPlayers,Joins,Leaves,NetGrowth,FirstJoinMs,TimeTo5PlayersMs,TimeTo10PlayersMs,ElapsedMs,ColdStartQuality\n")
    f:close(); return true
end

function startup.b401_checkpoint(reason)
    if not io or not io.open or tostring(B401.checkpoint_path or "")=="" then return false end
    local f=io.open(B401.checkpoint_path,"w"); if not f then return false end
    local c=B401.current or {}
    local lines={
        "STARTUP ADVERTISING METHOD TEST — BUILD 401",
        "RunId="..tostring(B401.run_id),
        "Timestamp="..os.date("%Y-%m-%d %H:%M:%S"),
        "Reason="..tostring(reason or "periodic"),
        "Active="..tostring(B401.active==true),
        "Phase="..tostring(B401.phase),
        "Trial="..tostring(B401.trial_index).."/"..tostring(#B401.trials),
        "Round="..tostring(c.round or ""),
        "Method="..tostring(c.methodId or ""),
        "TargetRegion="..tostring(B401.target_region),
        "ExpectedOverride="..tostring(c.override or ""),
        "ExpectedAdvertise="..tostring(c.advertise or ""),
        "ExpectedAdvertiseSession="..tostring(c.session==true and "ON" or "OFF"),
        "ActualOverride="..tostring(startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"),
        "ActualAdvertise="..tostring(startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"),
        "Players="..tostring(startup.b398_get_player_count and startup.b398_get_player_count() or 0),
        "Results="..tostring(#B401.results)
    }
    f:write(table.concat(lines,"\n"),"\n"); f:close(); return true
end

function startup.b401_set_phase(phase,delay,status)
    B401.phase=tostring(phase or "IDLE")
    B401.next_action_ms=startup.b401_now()+math.max(0,tonumber(delay or 0) or 0)
    B401.status=tostring(status or B401.phase)
    startup.b401_log("PHASE",B401.phase.." | "..B401.status)
end

function startup.b401_begin_trial(index,isRetry)
    index=tonumber(index or (B401.trial_index+1)) or 1
    if index>#B401.trials then return startup.b401_finish("Advertising method test completed",false) end
    B401.trial_index=index
    local t=B401.trials[index]
    local retry=isRetry==true and B401.current and tonumber(B401.current.retry_count or 0) or 0
    B401.current={
        round=t.round,methodId=t.methodId,methodLabel=t.methodLabel,override=t.override,advertise=t.advertise,session=t.session==true,
        retry_count=retry,override_attempts=0,advertise_attempts=0,session_attempts=0,
        session_click_ms=0,session_event_ms=0,session_ready_ms=0,accepted_serial=0,
        test_started_ms=0,test_deadline_ms=0,start_players=0,peak_players=0,joins=0,leaves=0,
        first_join_ms=nil,time5_ms=nil,time10_ms=nil,session_verify=""
    }
    startup.b401_set_phase("APPLY_OVERRIDE",0,"Trial "..index.."/"..#B401.trials.." — "..tostring(t.methodLabel))
    startup.b401_checkpoint("begin trial")
end

function startup.b401_retry_or_advance(reason)
    local c=B401.current or {}
    if tonumber(c.retry_count or 0)<B401.max_retry then
        c.retry_count=(tonumber(c.retry_count or 0) or 0)+1
        B401.current=c
        startup.b401_log("TRIAL_RETRY",tostring(c.methodId).." | "..tostring(reason))
        startup.b401_set_phase("RETRY_SETTLE",10000,"Retrying contaminated/interrupted trial once")
        return
    end
    startup.b401_record_result("FAILED_AFTER_RETRY:"..tostring(reason),0)
    startup.b401_set_phase("INTER_TRIAL",B401.inter_trial_settle_ms,"Trial failed twice; advancing")
end

function startup.b401_record_result(result,elapsedOverride)
    local c=B401.current or {}
    local now=startup.b401_now()
    local elapsed=tonumber(elapsedOverride)
    if elapsed==nil then elapsed=math.max(0,now-(tonumber(c.test_started_ms or now) or now)) end
    local endPlayers=startup.b398_get_player_count and startup.b398_get_player_count() or 0
    local startPlayers=tonumber(c.start_players or 0) or 0
    local quality=startPlayers<=2 and "CLEAN_COLD_START" or (startPlayers<=4 and "WARMING_START" or "PRE_FILLED_START")
    local clickToEvent=(tonumber(c.session_event_ms or 0)>0 and tonumber(c.session_click_ms or 0)>0) and math.max(0,c.session_event_ms-c.session_click_ms) or nil
    local eventToReady=(tonumber(c.session_ready_ms or 0)>0 and tonumber(c.session_event_ms or 0)>0) and math.max(0,c.session_ready_ms-c.session_event_ms) or nil
    local clickToReady=(tonumber(c.session_ready_ms or 0)>0 and tonumber(c.session_click_ms or 0)>0) and math.max(0,c.session_ready_ms-c.session_click_ms) or nil
    local r={
        trial=B401.trial_index,round=c.round,methodId=c.methodId,methodLabel=c.methodLabel,target=B401.target_region,
        override=c.override,advertise=c.advertise,session=c.session==true,sessionVerify=c.session_verify or "",
        result=tostring(result or "UNKNOWN"),retry=tonumber(c.retry_count or 0) or 0,
        clickToEvent=clickToEvent,eventToReady=eventToReady,clickToReady=clickToReady,
        startPlayers=startPlayers,endPlayers=endPlayers,peak=tonumber(c.peak_players or endPlayers) or endPlayers,
        joins=tonumber(c.joins or 0) or 0,leaves=tonumber(c.leaves or 0) or 0,
        net=(tonumber(c.joins or 0) or 0)-(tonumber(c.leaves or 0) or 0),
        firstJoin=c.first_join_ms,time5=c.time5_ms,time10=c.time10_ms,elapsed=elapsed,quality=quality
    }
    B401.results[#B401.results+1]=r
    local vals={B401.run_id,r.trial,r.round,r.methodId,r.methodLabel,r.target,r.override,r.advertise,r.session and "ON" or "OFF",r.sessionVerify,r.result,r.retry,
        r.clickToEvent or "",r.eventToReady or "",r.clickToReady or "",r.startPlayers,r.endPlayers,r.peak,r.joins,r.leaves,r.net,r.firstJoin or "",r.time5 or "",r.time10 or "",r.elapsed,r.quality}
    for i,v in ipairs(vals) do vals[i]=startup.b401_csv_escape(v) end
    if io and io.open then local f=io.open(B401.csv_path,"a"); if f then f:write(table.concat(vals,","),"\n"); f:close() end end
    startup.b401_log("RESULT",tostring(r.methodId).." | "..tostring(r.result).." | start="..r.startPlayers.." end="..r.endPlayers.." +"..r.joins.."/-"..r.leaves.." first="..tostring(r.firstJoin or "NA").." t5="..tostring(r.time5 or "NA").." t10="..tostring(r.time10 or "NA").." elapsed="..tostring(r.elapsed))
    return r
end

function startup.b401_finish_trial(result)
    local c=B401.current or {}
    local now=startup.b401_now()
    local elapsed=math.max(0,now-(tonumber(c.test_started_ms or now) or now))
    startup.b401_record_result(result,elapsed)
    startup.b401_set_phase("INTER_TRIAL",B401.inter_trial_settle_ms,"Saved "..tostring(c.methodId).." result; preparing next randomized trial")
    startup.b401_checkpoint("trial complete")
end

function startup.b401_write_summary(reason)
    if not io or not io.open then return false end
    local f=io.open(B401.summary_path,"w"); if not f then return false end
    local function w(s) f:write(tostring(s or ""),"\n") end
    w("STARTUP BUILD 401 — ONE-BUTTON ADVERTISING METHOD TEST")
    w("======================================================")
    w("Run ID: "..tostring(B401.run_id))
    w("Finished: "..os.date("%Y-%m-%d %H:%M:%S"))
    w("Reason: "..tostring(reason or "finished"))
    w("Target non-local region: "..tostring(B401.target_region))
    w("Design: 3 randomized rounds x 6 methods = 18 fresh New Public Sessions")
    w("Per trial: target 10 players, 5-minute maximum, local Session Host required")
    w("")
    w("METHODS")
    w("-------")
    for _,m in ipairs(startup.b401_methods(B401.target_region)) do
        w(m.id.." | Override="..m.override.." | Advertise="..m.advertise.." | Advertise Session="..(m.session and "ON" or "OFF"))
    end
    w("")
    w("AGGREGATE RESULTS")
    w("-----------------")
    local methods=startup.b401_methods(B401.target_region)
    local agg={}
    for _,m in ipairs(methods) do agg[m.id]={m=m,n=0,success=0,joins=0,leaves=0,elapsed=0,t10={},first={},t5={},clean=0} end
    for _,r in ipairs(B401.results) do
        local a=agg[r.methodId]
        if a then
            a.n=a.n+1; a.joins=a.joins+(r.joins or 0); a.leaves=a.leaves+(r.leaves or 0); a.elapsed=a.elapsed+(r.elapsed or 0)
            if r.result=="TARGET_10_REACHED" then a.success=a.success+1 end
            if tonumber(r.time10) then a.t10[#a.t10+1]=r.time10 end
            if tonumber(r.firstJoin) then a.first[#a.first+1]=r.firstJoin end
            if tonumber(r.time5) then a.t5[#a.t5+1]=r.time5 end
            if r.quality=="CLEAN_COLD_START" then a.clean=a.clean+1 end
        end
    end
    local rows={}
    for _,m in ipairs(methods) do
        local a=agg[m.id]
        local mins=math.max(0.01,a.elapsed/60000)
        local successRate=a.n>0 and (a.success/a.n*100) or 0
        local med10=startup.b401_median(a.t10)
        local medFirst=startup.b401_median(a.first)
        local med5=startup.b401_median(a.t5)
        local joinRate=a.joins/mins
        local netRate=(a.joins-a.leaves)/mins
        rows[#rows+1]={id=m.id,label=m.label,n=a.n,success=a.success,successRate=successRate,med10=med10,medFirst=medFirst,med5=med5,joinRate=joinRate,netRate=netRate,clean=a.clean}
    end
    table.sort(rows,function(a,b)
        if a.successRate~=b.successRate then return a.successRate>b.successRate end
        local at=a.med10 or math.huge; local bt=b.med10 or math.huge
        if at~=bt then return at<bt end
        return a.netRate>b.netRate
    end)
    for i,r in ipairs(rows) do
        w(string.format("%d. %s | n=%d clean=%d | success %d/%d (%.0f%%) | median first=%s | median to5=%s | median to10=%s | joins %.2f/min | net %.2f/min",
            i,r.id,r.n,r.clean,r.success,r.n,r.successRate,
            r.medFirst and startup.b373_format_ms(r.medFirst) or "NA",
            r.med5 and startup.b373_format_ms(r.med5) or "NA",
            r.med10 and startup.b373_format_ms(r.med10) or "TIMEOUT/NA",
            r.joinRate,r.netRate))
    end
    w("")
    w("MECHANISM COMPARISONS")
    w("---------------------")
    w("Advertise Session effect at local/default region: compare SESSION_ONLY vs CONTROL_OFF.")
    w("Override Region effect with Advertise Session ON: compare OVERRIDE_ONLY vs SESSION_ONLY.")
    w("Advertise Region effect with Advertise Session ON: compare ADVERTISE_ONLY vs SESSION_ONLY.")
    w("Synchronized region-pair effect: compare SYNC_PAIR_ON vs OVERRIDE_ONLY / ADVERTISE_ONLY / SESSION_ONLY.")
    w("Advertise Session effect with synchronized target pair: compare SYNC_PAIR_ON vs SYNC_PAIR_OFF.")
    w("")
    w("IMPORTANT")
    w("---------")
    w("Three repetitions per method are preliminary evidence, not a final statistical proof. Large, repeatable differences are useful; close results require another run or more repetitions.")
    w("All trials are randomized within each round to reduce time-of-day ordering bias.")
    f:close(); return true
end

function startup.b401_restore_saved()
    local s=B401.saved
    if type(s)~="table" then return end
    local function restore()
        if Script and Script.Yield then Script.Yield(1500) end
        if startup.b375 and startup.b375.native_apply_override and s.override then pcall(startup.b375.native_apply_override,s.override) end
        if Script and Script.Yield then Script.Yield(4500) end
        if startup.b375 and startup.b375.native_apply_advertise and s.advertise then pcall(startup.b375.native_apply_advertise,s.advertise,false,"B401 restore") end
        if Script and Script.Yield then Script.Yield(4500) end
        if s.session~=nil then pcall(startup.b401_set_advertise_session,s.session,"restore user state") end
    end
    if Script and Script.QueueJob then Script.QueueJob(restore) else restore() end
end

function startup.b401_finish(reason,aborted)
    if B401.active~=true then return true end
    if B401.phase=="TESTING" and B401.current and tonumber(B401.current.test_started_ms or 0)>0 then
        startup.b401_record_result(aborted and "ABORTED" or "STOPPED",math.max(0,startup.b401_now()-B401.current.test_started_ms))
    end
    B401.active=false
    B401.phase="IDLE"
    B401.status=tostring(reason or "Finished")
    startup.b401_write_summary(reason)
    startup.b401_checkpoint(aborted and "aborted" or "complete")
    startup.b401_log(aborted and "ABORT" or "COMPLETE",tostring(reason or "finished").." | results="..tostring(#B401.results))
    if startup.b377_restore_logical_ui_only then direct_call(startup.b377_restore_logical_ui_only) end
    startup.b401_restore_saved()
    if startup.toast then
        startup.toast((aborted and "Advertising method test stopped. " or "Advertising method test complete. ").."Results saved; create a Support ZIP when convenient.",9000)
    end
    return true
end

function startup.b401_start()
    if B401.active==true then if startup.toast then startup.toast("Advertising method test is already running.",3000) end return false end
    if startup.b378 and startup.b378.active==true then if startup.toast then startup.toast("Stop B378 before starting the method test.",4000) end return false end
    if startup.b377 and startup.b377.active==true then if startup.toast then startup.toast("Stop B377 before starting the method test.",4000) end return false end
    if startup.b398 and (startup.b398.active==true or startup.b398.pending_benchmark==true) and startup.b398_stop then startup.b398_stop("Method test taking exclusive ownership") end

    local ok,detail=startup.b401_scan_preflight()
    if ok~=true then B401.status="Preflight failed: "..tostring(detail); if startup.toast then startup.toast(B401.status,8500) end return false end

    B401.target_region=startup.b401_choose_target_region()
    B401.saved={
        override=startup.b373_read_override_region and startup.b373_read_override_region() or "My Region",
        advertise=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "My Region",
        session=startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
    }
    startup.b401_make_trials()
    B401.results={}; B401.trial_index=0; B401.current=nil
    B401.run_id="B401_"..os.date("%Y%m%d_%H%M%S")
    local base=tostring(startup.diagnostics_dir or startup.save_dir or "")
    B401.csv_path=base.."\\Advertising_MethodTest_"..B401.run_id..".csv"
    B401.summary_path=base.."\\Advertising_MethodTest_"..B401.run_id.."_SUMMARY.txt"
    B401.log_path=base.."\\Advertising_MethodTest_"..B401.run_id..".log"
    B401.checkpoint_path=base.."\\Advertising_MethodTest_"..B401.run_id.."_CHECKPOINT.txt"
    startup.b401_write_header()
    if io and io.open then local f=io.open(B401.log_path,"w"); if f then f:close() end end
    if startup.b377_save_logical_state then direct_call(startup.b377_save_logical_state) end
    if startup.b377_disable_startup_advertising_automation then direct_call(startup.b377_disable_startup_advertising_automation) end
    B401.active=true; B401.next_driver_ms=0
    startup.b401_log("START","targetRegion="..B401.target_region.." | repetitions="..B401.repetitions.." | trials="..#B401.trials.." | timeout=5m | targetPlayers=10")
    startup.b401_begin_trial(1,false)
    if startup.toast then startup.toast("B401 method test started: 18 randomized fresh sessions, 5 minutes max each (~100 minutes worst case). Leave session/region controls alone.",10000) end
    return true
end

function startup.b401_tick_impl()
    if B401.active~=true then return end
    local now=startup.b401_now()
    if now<(tonumber(B401.next_driver_ms or 0) or 0) then return end
    B401.next_driver_ms=now+B401.driver_interval_ms
    if now<(tonumber(B401.next_action_ms or 0) or 0) then
        if B401.phase=="TESTING" and B401.current then
            local p=startup.b398_get_player_count and startup.b398_get_player_count() or 0
            B401.current.peak_players=math.max(tonumber(B401.current.peak_players or 0) or 0,p)
        end
        return
    end

    local c=B401.current or {}
    local phase=B401.phase

    if phase=="APPLY_OVERRIDE" then
        c.override_attempts=(tonumber(c.override_attempts or 0) or 0)+1; B401.current=c
        local cur=startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
        if tostring(cur)==tostring(c.override) then
            startup.b401_set_phase("APPLY_ADVERTISE",500,"Override already "..tostring(c.override))
        else
            local ok,detail=startup.b375.native_apply_override(c.override)
            startup.b401_log("OVERRIDE_WRITE",tostring(c.override).." | ok="..tostring(ok).." | "..tostring(detail))
            if ok then startup.b401_set_phase("VERIFY_OVERRIDE",B401.native_settle_ms,"Verifying Override Region")
            elseif c.override_attempts<2 then startup.b401_set_phase("APPLY_OVERRIDE",4000,"Retrying Override Region")
            else startup.b401_retry_or_advance("Override write failed") end
        end

    elseif phase=="VERIFY_OVERRIDE" then
        local cur=startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
        if tostring(cur)==tostring(c.override) then startup.b401_set_phase("APPLY_ADVERTISE",500,"Override verified")
        elseif c.override_attempts<2 then startup.b401_set_phase("APPLY_OVERRIDE",1000,"Override mismatch; retry")
        else startup.b401_retry_or_advance("Override readback mismatch") end

    elseif phase=="APPLY_ADVERTISE" then
        c.advertise_attempts=(tonumber(c.advertise_attempts or 0) or 0)+1; B401.current=c
        local cur=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
        if tostring(cur)==tostring(c.advertise) then
            startup.b401_set_phase("APPLY_SESSION",500,"Advertise Region already "..tostring(c.advertise))
        else
            local ok=startup.b375.native_apply_advertise(c.advertise,false,"B401 method test")
            startup.b401_log("ADVERTISE_WRITE",tostring(c.advertise).." | ok="..tostring(ok))
            if ok then startup.b401_set_phase("VERIFY_ADVERTISE",B401.native_settle_ms,"Verifying Advertise Region")
            elseif c.advertise_attempts<2 then startup.b401_set_phase("APPLY_ADVERTISE",4000,"Retrying Advertise Region")
            else startup.b401_retry_or_advance("Advertise Region write failed") end
        end

    elseif phase=="VERIFY_ADVERTISE" then
        local cur=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
        if tostring(cur)==tostring(c.advertise) then startup.b401_set_phase("APPLY_SESSION",500,"Advertise Region verified")
        elseif c.advertise_attempts<2 then startup.b401_set_phase("APPLY_ADVERTISE",1000,"Advertise mismatch; retry")
        else startup.b401_retry_or_advance("Advertise Region readback mismatch") end

    elseif phase=="APPLY_SESSION" then
        local ok,mode,detail=startup.b401_set_advertise_session(c.session,"trial "..tostring(B401.trial_index).." "..tostring(c.methodId))
        c.session_mode=mode; B401.current=c
        if ok then startup.b401_set_phase("VERIFY_PRESESSION",B401.native_settle_ms,"Verifying complete method condition before fresh session")
        else startup.b401_retry_or_advance("Advertise Session write failed: "..tostring(detail)) end

    elseif phase=="VERIFY_PRESESSION" then
        local ov=startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
        local adv=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
        local sessionOk,sessionLabel,sessionMode=startup.b401_verify_advertise_session(c.session)
        c.session_verify=sessionLabel; c.session_mode=sessionMode; B401.current=c
        local ok=tostring(ov)==tostring(c.override) and tostring(adv)==tostring(c.advertise) and sessionOk==true
        startup.b401_log("PRESESSION_VERIFY",tostring(c.methodId).." | override="..tostring(ov).." expected="..tostring(c.override).." | advertise="..tostring(adv).." expected="..tostring(c.advertise).." | session="..tostring(sessionLabel))
        if ok then startup.b401_set_phase("ROUTE_NEW_PUBLIC",500,"Method condition locked; selecting fresh New Public Session")
        else startup.b401_retry_or_advance("Pre-session condition verification failed") end

    elseif phase=="ROUTE_NEW_PUBLIC" then
        local ok,err=false,"route unavailable"
        if startup.self_diag and startup.self_diag.set_session_type_exact then ok,err=startup.self_diag.set_session_type_exact("New Public Session") end
        if ok then startup.b401_set_phase("CLICK_NEW_PUBLIC",B401.route_settle_ms,"Route selected; waiting before one Start Session click")
        else startup.b401_retry_or_advance("Could not select New Public Session: "..tostring(err)) end

    elseif phase=="CLICK_NEW_PUBLIC" then
        c.session_attempts=(tonumber(c.session_attempts or 0) or 0)+1
        c.expected_serial=(tonumber(startup.b378 and startup.b378.session_change_serial or 0) or 0)+1
        c.session_click_ms=now; c.session_event_ms=0; c.session_ready_ms=0
        B401.current=c
        local ok=startup.click_start_session_feature and startup.click_start_session_feature() or false
        startup.b401_log("SESSION_CLICK",tostring(c.methodId).." | attempt="..c.session_attempts.." | expectedSerial="..c.expected_serial.." | ok="..tostring(ok))
        if ok then c.session_deadline_ms=now+B401.session_timeout_ms; B401.current=c; startup.b401_set_phase("WAIT_SESSION_CHANGE",0,"Waiting for fresh session event")
        elseif c.session_attempts<2 then startup.b401_set_phase("ROUTE_NEW_PUBLIC",5000,"Start Session failed; retrying")
        else startup.b401_retry_or_advance("Start Session failed twice") end

    elseif phase=="WAIT_SESSION_CHANGE" then
        local serial=tonumber(startup.b378 and startup.b378.session_change_serial or 0) or 0
        if serial>=tonumber(c.expected_serial or 0) then
            c.session_event_ms=tonumber(startup.b378 and startup.b378.last_session_change_ms or now) or now
            c.accepted_serial=serial; c.host_deadline_ms=now+B401.session_timeout_ms; B401.current=c
            startup.b401_set_phase("WAIT_FRESH_HOST",0,"Fresh session event observed; confirming local Session Host")
        elseif now>=tonumber(c.session_deadline_ms or 0) then startup.b401_retry_or_advance("Timed out waiting for fresh session") end

    elseif phase=="WAIT_FRESH_HOST" then
        local rawReady=startup.b375_raw_session_ready and startup.b375_raw_session_ready() or false
        local isHost,hostName=startup.b378_local_is_session_host()
        local eventAge=now-(tonumber(c.session_event_ms or now) or now)
        if rawReady==true and isHost==true and eventAge>=5000 then
            c.session_ready_ms=now
            c.accepted_serial=tonumber(startup.b378 and startup.b378.session_change_serial or c.accepted_serial) or c.accepted_serial
            B401.current=c
            startup.b401_log("FRESH_HOST_OK",tostring(c.methodId).." | host="..tostring(hostName).." | players="..tostring(startup.b398_get_player_count and startup.b398_get_player_count() or 0))
            startup.b401_set_phase("POSTLOAD_VERIFY",500,"Fresh local-host session ready; verifying method survived session creation")
        elseif now>=tonumber(c.host_deadline_ms or 0) then startup.b401_retry_or_advance("Fresh session never confirmed local Session Host") end

    elseif phase=="POSTLOAD_VERIFY" then
        local ov=startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown"
        local adv=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
        local sessionOk,sessionLabel=startup.b401_verify_advertise_session(c.session)
        c.session_verify=sessionLabel; B401.current=c
        local ok=tostring(ov)==tostring(c.override) and tostring(adv)==tostring(c.advertise) and sessionOk==true
        startup.b401_log("POSTLOAD_VERIFY",tostring(c.methodId).." | override="..tostring(ov).." | advertise="..tostring(adv).." | session="..tostring(sessionLabel).." | ok="..tostring(ok))
        if ok then
            local p=startup.b398_get_player_count and startup.b398_get_player_count() or 0
            c.test_started_ms=now; c.test_deadline_ms=now+B401.timeout_ms; c.start_players=p; c.peak_players=p
            c.joins=0; c.leaves=0; c.first_join_ms=nil; c.time5_ms=(p>=5 and 0 or nil); c.time10_ms=(p>=10 and 0 or nil)
            B401.current=c; B401.phase="TESTING"; B401.next_action_ms=now
            B401.status="Testing "..tostring(c.methodLabel).." | players "..tostring(p).."/10"
            startup.b401_log("TEST_START",tostring(c.methodId).." | startPlayers="..tostring(p).." | timeout=5m | override="..tostring(c.override).." | advertise="..tostring(c.advertise).." | session="..tostring(c.session))
        else
            startup.b401_retry_or_advance("Method condition changed during fresh-session creation")
        end

    elseif phase=="TESTING" then
        local serial=tonumber(startup.b378 and startup.b378.session_change_serial or 0) or 0
        if tonumber(c.accepted_serial or 0)>0 and serial>c.accepted_serial then startup.b401_retry_or_advance("Session changed during measured window"); return end
        local p=startup.b398_get_player_count and startup.b398_get_player_count() or 0
        c.peak_players=math.max(tonumber(c.peak_players or 0) or 0,p)
        local elapsed=math.max(0,now-(tonumber(c.test_started_ms or now) or now))
        if p>=5 and c.time5_ms==nil then c.time5_ms=elapsed end
        if p>=10 and c.time10_ms==nil then c.time10_ms=elapsed end
        B401.current=c
        local isHost=startup.b378_local_is_session_host()
        B401.status="Testing "..tostring(c.methodId).." | players "..tostring(p).."/10 | "..startup.b373_format_ms(elapsed).." / 5:00"
        if isHost~=true and elapsed>5000 then startup.b401_retry_or_advance("Lost local Session Host during timed window")
        elseif p>=B401.target_players then startup.b401_finish_trial("TARGET_10_REACHED")
        elseif now>=tonumber(c.test_deadline_ms or 0) then startup.b401_finish_trial("TIMEOUT_5M") end

    elseif phase=="INTER_TRIAL" then
        startup.b401_begin_trial(B401.trial_index+1,false)

    elseif phase=="RETRY_SETTLE" then
        local retry=tonumber(c.retry_count or 1) or 1
        local idx=B401.trial_index
        startup.b401_begin_trial(idx,true)
        if B401.current then B401.current.retry_count=retry end
    end
end

-- Count observed joins/leaves only during B401's timed windows.
if EventMgr and eLuaEvent and EventMgr.RegisterHandler and B401.events_installed~=true then
    B401.events_installed=true
    if eLuaEvent.ON_PLAYER_JOIN then
        EventMgr.RegisterHandler(eLuaEvent.ON_PLAYER_JOIN,function(playerId)
            if B401.active==true and B401.phase=="TESTING" and B401.current and not (startup.b373_is_local_player and startup.b373_is_local_player(playerId)) then
                local now=startup.b401_now()
                B401.current.joins=(tonumber(B401.current.joins or 0) or 0)+1
                if B401.current.first_join_ms==nil then B401.current.first_join_ms=math.max(0,now-(tonumber(B401.current.test_started_ms or now) or now)) end
            end
        end)
    end
    if eLuaEvent.ON_PLAYER_LEFT then
        EventMgr.RegisterHandler(eLuaEvent.ON_PLAYER_LEFT,function(playerId)
            if B401.active==true and B401.phase=="TESTING" and B401.current and not (startup.b373_is_local_player and startup.b373_is_local_player(playerId)) then
                B401.current.leaves=(tonumber(B401.current.leaves or 0) or 0)+1
            end
        end)
    end
end

-- Exclusive session ownership for the method test, matching B380's benchmark rule.
B401.start_session_pre=startup.start_session
startup.start_session=function(...)
    if B401.active==true then
        startup.b401_log("BACKGROUND_START_BLOCKED","startup.start_session denied | phase="..tostring(B401.phase))
        return false
    end
    return B401.start_session_pre(...)
end
B401.click_start_pre=startup.click_start_session_feature
startup.click_start_session_feature=function(...)
    if B401.active==true and tostring(B401.phase)~="CLICK_NEW_PUBLIC" then
        startup.b401_log("RAW_START_BLOCKED","Start Session denied outside CLICK_NEW_PUBLIC | phase="..tostring(B401.phase))
        return false
    end
    return B401.click_start_pre(...)
end

-- Prevent normal advertising flow from becoming a second writer.
B401.run_advertise_flow_pre=startup.run_advertise_flow
startup.run_advertise_flow=function(reason)
    if B401.active==true then
        startup.s.lastAdvertiseStatus="B401 method test owns advertising"
        return false
    end
    return B401.run_advertise_flow_pre and B401.run_advertise_flow_pre(reason) or false
end

-- Drive B401 on the same low-frequency benchmark lane.
B401.b374_tick_pre=startup.b374_tick
startup.b374_tick=function()
    if B401.active==true then return startup.b401_tick_impl() end
    return B401.b374_tick_pre and B401.b374_tick_pre() or nil
end

if startup.add_button then
    startup.add_button("MethodTest401","RUN METHOD TEST","Controlled A/B mechanism test. Automatically chooses the strongest learned non-local target region, runs 3 randomized rounds of 6 methods (18 fresh public sessions), and measures each for up to 5 minutes or until 10 players. Tests Advertise Session, Override Region, Advertise Region, synchronized pair OFF, synchronized pair ON, and a baseline. Worst case is about 100 minutes. This intentionally session-hops.",function() startup.b401_start() end)
    startup.add_button("StopMethodTest401","STOP ADVERTISING METHOD TEST","Stops the controlled method test, preserves completed results, writes the summary, and restores the prior advertising controls.",function() startup.b401_finish("Stopped by user",true) end)
end

-- Support ZIP inclusion.
if B401.support_wrapped~=true then
    B401.support_wrapped=true
    B401.collect_support_pre=startup.collect_support_files
    function startup.collect_support_files()
        local found=B401.collect_support_pre and B401.collect_support_pre() or {}
        local function add(path,name)
            path=tostring(path or ""); if path=="" or not startup.support_file_exists or not startup.support_file_exists(path) then return end
            found[#found+1]={path=path,name="Startup/Diagnostics/Advertising/"..tostring(name)}
        end
        add(B401.csv_path,"B401_Method_Test_Results.csv")
        add(B401.summary_path,"B401_Method_Test_Summary.txt")
        add(B401.log_path,"B401_Method_Test.log")
        add(B401.checkpoint_path,"B401_Method_Test_CHECKPOINT.txt")
        return found
    end
end


-- ============================================================================
-- BUILD 402: PRODUCTION ADVERTISING VARIANTS
-- Evidence-driven production controller based on B401's randomized A/B test.
--
-- Variants:
--   Standard Advertise      = Override My Region, Advertise My Region, Session ON
--   Any Advertise           = Override Any, Advertise My Region, Session ON
--   Region Advertise        = Override My Region, Advertise selected region, Session ON
--   Synced Region Advertise = Override selected region, Advertise selected region, Session ON
--
-- This controller intentionally does NOT rotate regions. It applies one method
-- once, verifies it, then holds. On a real session change it reapplies the same
-- selected method after the fresh local-host session becomes stable.
-- ============================================================================

startup.install_build402_advertising_variants=function()
startup.b402 = startup.b402 or {}
local B402 = startup.b402
B402.active = false
B402.phase = "IDLE"
B402.status = "Ready — Standard Advertise is the default"
B402.next_tick_ms = 0
B402.next_action_ms = 0
B402.driver_interval_ms = 1000
B402.native_settle_ms = 4000
B402.session_verify_ms = 2000
B402.health_check_ms = 10000
B402.next_health_ms = 0
B402.max_write_attempts = 2
B402.override_attempts = 0
B402.advertise_attempts = 0
B402.session_attempts = 0
B402.auto_owned = false
B402.last_reason = ""
B402.expected = nil
B402.last_session_serial = 0

local B402_VARIANTS = {"Standard Advertise","Any Advertise","Region Advertise","Synced Region Advertise"}
local B402_REGIONS = {"My Region","Northern Asia","Africa","East America","Europe","China","Australia","West America","Japan"}

local function b402_now()
    return startup.b401_now and startup.b401_now() or (startup.now and startup.now() or math.floor((os.clock() or 0)*1000))
end

local function b402_log(kind, detail)
    if startup.support_log_event_quiet then
        direct_call(startup.support_log_event_quiet, "B402_"..tostring(kind or "EVENT"), tostring(detail or ""))
    end
end

local function b402_valid_variant(v)
    v=tostring(v or "")
    return v=="Standard Advertise" or v=="Any Advertise" or v=="Region Advertise" or v=="Synced Region Advertise"
end

local function b402_valid_region(r)
    r=startup.b368_region_normalize and startup.b368_region_normalize(r) or tostring(r or "")
    if r=="Unknown" or r=="" then return "Africa" end
    return r
end

-- Build 413: Any Advertise must resolve the actual Matchmaking Override Region
-- control by capability, not merely reuse B373's cached region feature. A candidate
-- is accepted only when its readable native list contains the exact `Any` entry.
-- This remains a targeted-name probe only; Startup does not enumerate Cherax's full
-- feature tree, preserving the production discovery-safety rules.
local function b402_trim_lower(value)
    return string.lower(tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", ""))
end

local function b402_list_entry_index(feature,wanted)
    if not feature or not feature.GetList or not feature.SetListIndex then
        return nil,nil,"list setter unavailable"
    end
    local okList,list=pcall(function() return feature:GetList() end)
    if not okList or type(list)~="table" then
        return nil,nil,"list unreadable"
    end
    local wantedLower=b402_trim_lower(wanted)
    for i,label in ipairs(list) do
        if b402_trim_lower(label)==wantedLower then return i-1,list,nil end
    end
    -- Some Cherax list wrappers may expose entry zero directly. Only use that
    -- fallback when `Any` was not found through the normal 1-based Lua list.
    if list[0]~=nil and b402_trim_lower(list[0])==wantedLower then
        return 0,list,nil
    end
    return nil,list,"exact option '"..tostring(wanted).."' not exposed"
end

local function b402_resolve_any_override_feature()
    if B402.any_override_feature then
        local idx=b402_list_entry_index(B402.any_override_feature,"Any")
        if idx~=nil then
            B402.any_override_index=idx
            B402.any_override_resolution_mode="readable-list"
            return B402.any_override_feature,B402.any_override_feature_name or "cached"
        end
        -- Build 414: the exact Cherax Matchmaking > Override Region dropdown is
        -- visible in ClickGUI on the reported layout even though GetList() returns nil.
        -- The supplied live UI proves My Region is index 0 and Any is index 1. Only
        -- keep this fallback for the exact `Override Region` control, never aliases.
        if tostring(B402.any_override_feature_name or "")=="Override Region"
            and B402.any_override_feature.SetListIndex
            and (B402.any_override_feature.GetListIndex or (B402.any_override_feature.GetHash and FeatureMgr and FeatureMgr.GetCurrentFeatureListString)) then
            B402.any_override_index=1
            B402.any_override_resolution_mode="confirmed-ui-index"
            return B402.any_override_feature,"Override Region (confirmed UI index fallback)"
        end
        B402.any_override_feature=nil
        B402.any_override_feature_name=nil
        B402.any_override_index=nil
        B402.any_override_resolution_mode=nil
    end
    if not FeatureMgr or not FeatureMgr.GetFeatureByName then
        return nil,"FeatureMgr.GetFeatureByName unavailable"
    end
    local names={
        "Override Region", "Matchmaking Region Override", "Matchmaking Region",
        "Region Override", "Matchmaking Region Type", "Matchmaking Region Selector",
        "Matchmaking Region Selection", "Matchmaking Region Filter", "Matchmaking Region Spoof"
    }
    local foundWithoutAny={}
    for _,name in ipairs(names) do
        local okFeature,feature=pcall(function() return FeatureMgr.GetFeatureByName(name) end)
        if okFeature and feature then
            local idx,_,why=b402_list_entry_index(feature,"Any")
            if idx~=nil then
                B402.any_override_feature=feature
                B402.any_override_feature_name=name
                B402.any_override_index=idx
                B402.any_override_resolution_mode="readable-list"
                b402_log("ANY_OVERRIDE_RESOLVED","feature="..name.." | index="..tostring(idx).." | mode=readable-list")
                return feature,name
            end
            -- Exact screenshot-confirmed control fallback. Cherax may render the
            -- dropdown while withholding GetList() from Lua, but SetListIndex and
            -- GetListIndex remain usable. Do not extend index 1 to any other name.
            if name=="Override Region" and (why=="list unreadable" or why=="list setter unavailable")
                and feature.SetListIndex
                and (feature.GetListIndex or (feature.GetHash and FeatureMgr and FeatureMgr.GetCurrentFeatureListString)) then
                B402.any_override_feature=feature
                B402.any_override_feature_name=name
                B402.any_override_index=1
                B402.any_override_resolution_mode="confirmed-ui-index"
                b402_log("ANY_OVERRIDE_RESOLVED","feature=Override Region | index=1 | mode=confirmed-ui-index | GetList="..tostring(why or "unreadable"))
                return feature,"Override Region (confirmed UI index fallback)"
            end
            foundWithoutAny[#foundWithoutAny+1]=name.." ("..tostring(why or "no Any")..")"
        end
    end
    local detail="No usable targeted Matchmaking Override Region control found for 'Any'"
    if #foundWithoutAny>0 then detail=detail.." | found: "..table.concat(foundWithoutAny,", ") end
    B402.any_override_resolve_detail=detail
    return nil,detail
end

local function b402_override_feature(wanted)
    if tostring(wanted or "") == "Any" then return b402_resolve_any_override_feature() end
    return startup.b373_override_feature and startup.b373_override_feature() or nil,"B373"
end

local function b402_read_feature_list_label(feature)
    if not feature then return "Unknown",nil end
    local idx=nil
    if feature.GetListIndex then
        local ok,v=pcall(function() return feature:GetListIndex() end)
        if ok and tonumber(v)~=nil then idx=math.floor(tonumber(v)) end
    end
    local list=nil
    if feature.GetList then
        local ok,v=pcall(function() return feature:GetList() end)
        if ok and type(v)=="table" then list=v end
    end
    if idx~=nil and type(list)=="table" then
        local raw=nil
        if list[0]~=nil then raw=list[idx] else raw=list[idx+1] end
        raw=tostring(raw or "")
        if raw~="" then
            if b402_trim_lower(raw)=="any" then return "Any",idx end
            local normalized=startup.b368_region_normalize and startup.b368_region_normalize(raw) or raw
            if normalized and normalized~="" and normalized~="Unknown" then return normalized,idx end
            return raw,idx
        end
    end
    -- Build 414: when GetList() is hidden, prefer Cherax's current-list-string
    -- accessor by feature hash. This reads the rendered selection without requiring
    -- the full native list to be exposed to Lua.
    if feature.GetHash and FeatureMgr and FeatureMgr.GetCurrentFeatureListString then
        local okHash,hash=pcall(function() return feature:GetHash() end)
        if okHash and hash~=nil then
            local okText,text=pcall(function() return FeatureMgr.GetCurrentFeatureListString(hash) end)
            text=okText and tostring(text or "") or ""
            if text~="" then
                if b402_trim_lower(text)=="any" then return "Any",idx end
                local normalized=startup.b368_region_normalize and startup.b368_region_normalize(text) or text
                if normalized and normalized~="" and normalized~="Unknown" then return normalized,idx end
                return text,idx
            end
        end
    end
    -- Final narrow readback for the screenshot-confirmed exact Override Region
    -- dropdown. Index 1 is Any only for this cached exact control.
    if feature==B402.any_override_feature
        and tostring(B402.any_override_feature_name or "")=="Override Region"
        and tonumber(B402.any_override_index)==1 and tonumber(idx)==1 then
        return "Any",idx
    end
    return "Unknown",idx
end

local function b402_read_override_native()
    local wantsAny=(B402.expected and tostring(B402.expected.override)=="Any") or tostring(startup.s.advertisingVariant402 or "")=="Any Advertise"
    local f=b402_override_feature(wantsAny and "Any" or nil)
    if not f then return "Unknown",nil end
    local label,idx=b402_read_feature_list_label(f)
    if label~="Unknown" then return label,idx end
    if not wantsAny and startup.b373_read_override_region then
        local ok,fallbackLabel,fallbackIdx=pcall(startup.b373_read_override_region)
        if ok then return tostring(fallbackLabel or "Unknown"),fallbackIdx end
    end
    return label,idx
end

local function b402_apply_override_native(wanted)
    wanted=tostring(wanted or "My Region")
    if wanted~="Any" then
        if startup.b375 and startup.b375.native_apply_override then
            local ok,detail=startup.b375.native_apply_override(wanted,false,"B402 "..tostring(startup.s.advertisingVariant402 or "production"))
            return ok==true,detail
        end
        if startup.b373_apply_override_region then
            local ok,detail=startup.b373_apply_override_region(wanted)
            return ok==true,detail
        end
        return false,"normal Override Region setter unavailable"
    end

    local f,source=b402_resolve_any_override_feature()
    if not f then return false,tostring(source or B402.any_override_resolve_detail or "Any Override Region control unavailable") end
    local anyIndex,_,indexErr=b402_list_entry_index(f,"Any")
    if anyIndex==nil and tostring(B402.any_override_feature_name or "")=="Override Region" then
        anyIndex=tonumber(B402.any_override_index)
    end
    if anyIndex==nil then return false,tostring(indexErr or "Any index unavailable") end

    local okWrite,writeErr=pcall(function()
        f:SetListIndex(anyIndex)
        if f.TriggerCallback then f:TriggerCallback() elseif f.OnClick then f:OnClick() end
    end)
    if not okWrite then return false,"native write error: "..tostring(writeErr) end

    local got,gotIndex=b402_read_feature_list_label(f)
    if tostring(got)~="Any" then
        return false,"readback mismatch from "..tostring(source)..": got "..tostring(got).." (index "..tostring(gotIndex)..")"
    end
    B402.any_override_index=anyIndex
    return true,"Override Region=Any via "..tostring(source)
end

startup.b402_read_override_region=function()
    return b402_read_override_native()
end

startup.b402_apply_override_region=function(wanted)
    return b402_apply_override_native(wanted)
end

function startup.b402_get_spec()
    local variant=tostring(startup.s.advertisingVariant402 or "Standard Advertise")
    if not b402_valid_variant(variant) then variant="Standard Advertise"; startup.s.advertisingVariant402=variant end
    local target=b402_valid_region(startup.s.advertisingVariantRegion402 or "Africa")
    startup.s.advertisingVariantRegion402=target

    if variant=="Standard Advertise" then
        return {variant=variant,target=target,override="My Region",advertise="My Region",session=true}
    elseif variant=="Any Advertise" then
        return {variant=variant,target="My Region",override="Any",advertise="My Region",session=true}
    elseif variant=="Region Advertise" then
        return {variant=variant,target=target,override="My Region",advertise=target,session=true}
    end
    return {variant=variant,target=target,override=target,advertise=target,session=true}
end

local function b402_local_host()
    if startup.browser_is_local_session_host then
        local ok,res=direct_call(startup.browser_is_local_session_host)
        return ok and res==true
    end
    return true -- fallback only when host helper is unavailable
end

local function b402_stable(now)
    if startup.b375_update_session_stability then
        local ok,res=direct_call(startup.b375_update_session_stability,now)
        return ok and res==true
    end
    return true
end

local function b402_set_phase(phase, delay, status)
    B402.phase=tostring(phase or "IDLE")
    B402.next_action_ms=b402_now()+math.max(0,tonumber(delay or 0) or 0)
    if status then B402.status=tostring(status) end
    startup.s.lastAdvertiseStatus=B402.status
    b402_log("PHASE",B402.phase.." | "..tostring(B402.status))
end

local function b402_release_legacy_owners(reason)
    if startup.b398 and startup.b398.active==true and startup.b398_stop then
        direct_call(startup.b398_stop,"Build 402 production advertising took ownership")
    end
    if startup.b373 and startup.b373.running==true and startup.b373_stop_engine then
        direct_call(startup.b373_stop_engine,"Build 402 production advertising took ownership",true)
    end
    if startup.b375 and startup.b375.region_job and startup.b375.region_job.active==true then
        startup.b375.region_job.active=false
        startup.b375.region_job.phase="IDLE"
    end
    b402_log("OWNERSHIP","legacy advertising owners released | "..tostring(reason or "start"))
end

function startup.b402_stop(reason, turnSessionOff)
    local was=B402.active==true
    B402.active=false
    B402.phase="IDLE"
    B402.auto_owned=false
    B402.expected=nil
    B402.override_attempts=0
    B402.advertise_attempts=0
    B402.session_attempts=0
    B402.next_action_ms=0
    B402.next_health_ms=0
    startup.s.advertiseRunning=false
    startup.s.advertiseSmartActive=false
    startup.s.advertiseCountdownStartedAtMs=0
    startup.s.advertiseCountdownEndsAtMs=0
    if turnSessionOff==true and startup.b401_set_advertise_session then
        pcall(startup.b401_set_advertise_session,false,"B402 stop")
    end
    B402.status=tostring(reason or "Stopped")
    startup.s.lastAdvertiseStatus=B402.status
    if was then b402_log("STOP",B402.status) end
    return true
end

function startup.b402_start(reason, autoOwned, immediate)
    if startup.b401 and startup.b401.active==true then
        B402.status="Method Test owns advertising — wait for B401 to finish"
        startup.s.lastAdvertiseStatus=B402.status
        if startup.toast then startup.toast(B402.status,5000) end
        return false
    end
    if startup.b378 and startup.b378.active==true then
        B402.status="Cold-start benchmark owns advertising — wait for it to finish"
        startup.s.lastAdvertiseStatus=B402.status
        return false
    end
    if startup.b374 and startup.b374.active==true then
        B402.status="Advertising benchmark owns controls — stop it first"
        startup.s.lastAdvertiseStatus=B402.status
        return false
    end

    b402_release_legacy_owners(reason)
    B402.expected=startup.b402_get_spec()
    B402.active=true
    B402.auto_owned=autoOwned==true
    B402.last_reason=tostring(reason or "manual")
    B402.override_attempts=0
    B402.advertise_attempts=0
    B402.session_attempts=0
    B402.next_health_ms=0
    B402.next_tick_ms=0

    startup.s.advertiseFlowSerial=(tonumber(startup.s.advertiseFlowSerial or 0) or 0)+1
    startup.s.advertiseRunning=true
    startup.s.advertiseSmartActive=false
    startup.s.advertiseStopRequested=false
    startup.s.advertiseCompletedForSession=false
    startup.s.advertiseCountdownStartedAtMs=0
    startup.s.advertiseCountdownEndsAtMs=0

    -- Build 414: a deliberate user selection should visibly begin applying at once
    -- when the current GTA Online session is already ready and the local user is Host.
    -- Automatic/session-change paths retain the existing stability gate.
    if immediate==true
        and (not startup.b375_raw_session_ready or startup.b375_raw_session_ready()==true)
        and b402_local_host() then
        b402_set_phase("APPLY_OVERRIDE",0,"Applying "..B402.expected.variant.." immediately")
    else
        b402_set_phase("WAIT_STABLE",0,"Preparing "..B402.expected.variant)
    end
    b402_log("START","variant="..B402.expected.variant.." | target="..B402.expected.target.." | override="..B402.expected.override.." | advertise="..B402.expected.advertise.." | auto="..tostring(B402.auto_owned).." | immediate="..tostring(immediate==true).." | reason="..B402.last_reason)
    return true
end

function startup.b402_reapply(reason)
    if B402.active~=true then return false end
    B402.expected=startup.b402_get_spec()
    B402.override_attempts=0
    B402.advertise_attempts=0
    B402.session_attempts=0
    b402_set_phase("WAIT_STABLE",0,"Reapplying "..B402.expected.variant.." — "..tostring(reason or "settings changed"))
    return true
end

function startup.b402_tick()
    if B402.active~=true then return end
    local now=b402_now()
    if now<(tonumber(B402.next_tick_ms or 0) or 0) then return end
    B402.next_tick_ms=now+B402.driver_interval_ms

    if B402.auto_owned==true and startup.s.autoAdvertiseSession~=true then
        startup.b402_stop("Auto Advertise Session is OFF",true)
        return
    end
    if startup.b401 and startup.b401.active==true then
        startup.b402_stop("Paused — B401 method test owns advertising",false)
        return
    end
    if now<(tonumber(B402.next_action_ms or 0) or 0) then return end

    local spec=B402.expected or startup.b402_get_spec()
    B402.expected=spec
    local phase=tostring(B402.phase or "WAIT_STABLE")

    if phase=="WAIT_STABLE" then
        if not b402_stable(now) then
            B402.status="Waiting for GTA Online session stability"
            startup.s.lastAdvertiseStatus=B402.status
            return
        end
        if not b402_local_host() then
            B402.status="Waiting for local Session Host — no advertising writes"
            startup.s.lastAdvertiseStatus=B402.status
            return
        end
        b402_set_phase("APPLY_OVERRIDE",0,"Applying "..spec.variant)
        return
    end

    if phase=="APPLY_OVERRIDE" then
        local cur=startup.b402_read_override_region and startup.b402_read_override_region() or (startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown")
        if tostring(cur)==tostring(spec.override) then
            b402_set_phase("APPLY_ADVERTISE",0,"Override already "..spec.override)
            return
        end
        B402.override_attempts=B402.override_attempts+1
        local ok,detail=false,"Override setter unavailable"
        if startup.b402_apply_override_region then ok,detail=startup.b402_apply_override_region(spec.override) end
        B402.last_override_detail=tostring(detail or "")
        if ok then
            b402_set_phase("VERIFY_OVERRIDE",B402.native_settle_ms,"Verifying Override Region")
        elseif B402.override_attempts<B402.max_write_attempts then
            b402_set_phase("APPLY_OVERRIDE",4000,"Retrying Override Region — "..tostring(detail or "write failed"))
        else
            B402.status="ERROR — Override Region write failed safely: "..tostring(detail or "unknown reason")
            B402.phase="ERROR"; b402_log("ERROR",B402.status)
        end
        return
    end

    if phase=="VERIFY_OVERRIDE" then
        local cur=startup.b402_read_override_region and startup.b402_read_override_region() or (startup.b373_read_override_region and startup.b373_read_override_region() or "Unknown")
        if tostring(cur)==tostring(spec.override) then
            b402_set_phase("APPLY_ADVERTISE",0,"Override verified: "..spec.override)
        elseif B402.override_attempts<B402.max_write_attempts then
            b402_set_phase("APPLY_OVERRIDE",1000,"Override mismatch; retrying")
        else
            B402.status="ERROR — Override verification mismatch ("..tostring(cur)..")"
            B402.phase="ERROR"; b402_log("ERROR",B402.status)
        end
        return
    end

    if phase=="APPLY_ADVERTISE" then
        local cur=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
        if tostring(cur)==tostring(spec.advertise) then
            b402_set_phase("APPLY_SESSION",0,"Advertise Region already "..spec.advertise)
            return
        end
        B402.advertise_attempts=B402.advertise_attempts+1
        local ok=startup.b375 and startup.b375.native_apply_advertise and startup.b375.native_apply_advertise(spec.advertise,false,"B402 "..spec.variant)
        if ok then
            b402_set_phase("VERIFY_ADVERTISE",B402.native_settle_ms,"Verifying Advertise Region")
        elseif B402.advertise_attempts<B402.max_write_attempts then
            b402_set_phase("APPLY_ADVERTISE",4000,"Retrying Advertise Region")
        else
            B402.status="ERROR — Advertise Region write failed safely"
            B402.phase="ERROR"; b402_log("ERROR",B402.status)
        end
        return
    end

    if phase=="VERIFY_ADVERTISE" then
        local cur=startup.get_advertise_region_label and startup.get_advertise_region_label(false) or "Unknown"
        if tostring(cur)==tostring(spec.advertise) then
            b402_set_phase("APPLY_SESSION",0,"Advertise Region verified: "..spec.advertise)
        elseif B402.advertise_attempts<B402.max_write_attempts then
            b402_set_phase("APPLY_ADVERTISE",1000,"Advertise mismatch; retrying")
        else
            B402.status="ERROR — Advertise verification mismatch ("..tostring(cur)..")"
            B402.phase="ERROR"; b402_log("ERROR",B402.status)
        end
        return
    end

    if phase=="APPLY_SESSION" then
        B402.session_attempts=B402.session_attempts+1
        local ok,mode,detail=startup.b401_set_advertise_session and startup.b401_set_advertise_session(true,"B402 "..spec.variant) or false,"UNAVAILABLE",""
        if ok then
            b402_set_phase("VERIFY_SESSION",B402.session_verify_ms,"Verifying Advertise Session ON")
        elseif B402.session_attempts<B402.max_write_attempts then
            b402_set_phase("APPLY_SESSION",3000,"Retrying Advertise Session ON")
        else
            B402.status="ERROR — Advertise Session ON failed ("..tostring(mode)..")"
            B402.phase="ERROR"; b402_log("ERROR",B402.status.." | "..tostring(detail))
        end
        return
    end

    if phase=="VERIFY_SESSION" then
        local ok,label,mode=startup.b401_verify_advertise_session and startup.b401_verify_advertise_session(true) or false,"UNKNOWN","UNAVAILABLE"
        if ok then
            B402.phase="ACTIVE"
            B402.next_health_ms=now+B402.health_check_ms
            startup.s.advertiseSmartActive=true
            startup.s.advertiseSessionEnabled=true
            local players=startup.b398_get_player_count and startup.b398_get_player_count() or (startup.get_session_player_count and startup.get_session_player_count() or 0)
            B402.status=spec.variant.." ACTIVE — holding settings | "..tostring(players).." players"
            startup.s.lastAdvertiseStatus=B402.status
            b402_log("ACTIVE","variant="..spec.variant.." | override="..spec.override.." | advertise="..spec.advertise.." | session="..tostring(label).." | verifyMode="..tostring(mode))
        elseif B402.session_attempts<B402.max_write_attempts then
            b402_set_phase("APPLY_SESSION",1000,"Advertise Session not ON; retrying once")
        else
            B402.status="ERROR — Advertise Session verification failed"
            B402.phase="ERROR"; b402_log("ERROR",B402.status)
        end
        return
    end

    if phase=="ACTIVE" then
        local players=startup.b398_get_player_count and startup.b398_get_player_count() or (startup.get_session_player_count and startup.get_session_player_count() or 0)
        B402.status=spec.variant.." ACTIVE — HOLD | "..tostring(players).." players"
        startup.s.lastAdvertiseStatus=B402.status

        -- No region rotation. Only repair Advertise Session if Cherax can positively
        -- read that it became OFF. Write-only builds are intentionally left alone.
        if now>=tonumber(B402.next_health_ms or 0) then
            B402.next_health_ms=now+B402.health_check_ms
            local state=startup.b375_native_advertise_state and startup.b375_native_advertise_state() or nil
            if state==false then
                B402.session_attempts=0
                b402_set_phase("APPLY_SESSION",0,"Advertise Session became OFF; repairing once")
            end
        end
        return
    end
end

-- Production controls.
startup.s.advertisingVariant402 = tostring(startup.s.advertisingVariant402 or "Standard Advertise")
if not b402_valid_variant(startup.s.advertisingVariant402) then startup.s.advertisingVariant402="Standard Advertise" end
startup.s.advertisingVariantRegion402 = b402_valid_region(startup.s.advertisingVariantRegion402 or "Africa")

startup.add_combo("AdvertisingVariant402","Advertising Method",
    "Production advertising method. Standard Advertise uses Override My Region + Advertise My Region. Any Advertise forces Matchmaking Override Region = Any + Advertise Region = My Region. Region Advertise changes only Advertise Region. Synced Region Advertise changes both Override + Advertise Region. Every method turns Auto Advertise Session ON, keeps Advertise Session ON, and does not rotate regions.",
    B402_VARIANTS,startup.s.advertisingVariant402,function(selected)
        startup.s.advertisingVariant402=tostring(selected or "Standard Advertise")
        if startup.s.initialized then
            -- Build 415: selecting any production method means the user intends to
            -- advertise. Keep the Session-tab Auto Advertise Session toggle visibly ON
            -- and persist that intent before starting the immediate serialized apply.
            startup.s.autoAdvertiseSession=true
            startup.s.autoAdvertiseUserConfigured=true
            if startup.set_feature_bool_silently and startup.h then
                startup.set_feature_bool_silently(startup.h.AutoAdvertiseSession,true)
            end
            startup.save_config(false)
            -- Build 414: selecting a method is the Apply action. Begin the serialized
            -- native sequence immediately so Matchmaking / Host Tool Kit visibly update.
            startup.b402_start("Advertising Method selected: "..startup.s.advertisingVariant402,false,true)
        end
    end)

startup.add_combo("AdvertisingVariantRegion402","Advertising Region",
    "Used only by Region Advertise and Synced Region Advertise. Standard Advertise and Any Advertise always use Advertise Region = My Region. Any Advertise separately forces Matchmaking Override Region = Any. Production never rotates regions automatically.",
    B402_REGIONS,startup.s.advertisingVariantRegion402,function(selected)
        startup.s.advertisingVariantRegion402=b402_valid_region(selected)
        local method=tostring(startup.s.advertisingVariant402 or "Standard Advertise")
        if startup.s.initialized then
            startup.save_config(false)
            if method=="Region Advertise" or method=="Synced Region Advertise" then
                startup.b402_start("Advertising Region selected: "..startup.s.advertisingVariantRegion402,false,true)
            end
        end
    end)

startup.add_button("ApplyAdvertisingVariant402","REAPPLY SELECTED ADVERTISING NOW",
    "Advertising now applies automatically when you select a method. Use this only to reapply the current selection. Startup serializes Override Region, Advertise Region, and Advertise Session ON, verifies them, then holds.",
    function() startup.b402_start("manual Reapply Selected Advertising Now",false,true) end)

startup.add_button("StopAdvertisingVariant402","STOP ADVERTISING",
    "Stops Build 402 production advertising and explicitly turns Advertise Session OFF. Region values are left visible as-is.",
    function() startup.b402_stop("Stopped by user",true) end)

-- Auto Advertise Session now uses the selected B402 production method instead of
-- B373 adaptive rotation. No two-minute region rotation engine is started.
B402.run_advertise_flow_pre=startup.run_advertise_flow
startup.run_advertise_flow=function(reason)
    if startup.b401 and startup.b401.active==true then
        return B402.run_advertise_flow_pre and B402.run_advertise_flow_pre(reason) or false
    end
    if startup.s.autoAdvertiseSession~=true then
        startup.s.lastAdvertiseStatus="Auto Advertise OFF"
        return false
    end
    return startup.b402_start(reason or "session Auto Advertise",true)
end

B402.update_advertise_pre=startup.update_advertise_smart_state
startup.update_advertise_smart_state=function(context)
    if B402.active==true then return end
    return B402.update_advertise_pre and B402.update_advertise_pre(context) or nil
end

B402.stop_advertise_pre=startup.stop_advertise_now
startup.stop_advertise_now=function(...)
    if B402.active==true then startup.b402_stop("Manual Stop Advertise Session Now",true) end
    return B402.stop_advertise_pre and B402.stop_advertise_pre(...) or nil
end

-- If someone explicitly launches legacy Smart Auto, production ownership is released
-- first. This backend compatibility remains for diagnostics, but it is no longer shown
-- as the primary production UI.
if startup.b398_start_smart and B402.b398_start_pre==nil then
    B402.b398_start_pre=startup.b398_start_smart
    startup.b398_start_smart=function(reason)
        if B402.active==true then startup.b402_stop("Legacy Smart Auto requested",false) end
        return B402.b398_start_pre(reason)
    end
end

-- Method test owns all advertising while active.
if startup.b401_start and B402.b401_start_pre==nil then
    B402.b401_start_pre=startup.b401_start
    startup.b401_start=function(...)
        if B402.active==true then startup.b402_stop("B401 method test requested",false) end
        return B402.b401_start_pre(...)
    end
end

if EventMgr and eLuaEvent and eLuaEvent.ON_SESSION_CHANGE and EventMgr.RegisterHandler then
    EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE,function()
        if B402.active==true then
            B402.expected=startup.b402_get_spec()
            B402.override_attempts=0
            B402.advertise_attempts=0
            B402.session_attempts=0
            b402_set_phase("WAIT_STABLE",5000,"Session changed — waiting to reapply "..B402.expected.variant)
            b402_log("SESSION_CHANGE","production method will reapply after stability")
        end
    end)
end

if Script and Script.RegisterLooped then
    Script.RegisterLooped(function()
        if ShouldUnload and ShouldUnload() then if Script.Yield then Script.Yield(250) end return end
        local ok,err=pcall(startup.b402_tick)
        if not ok then
            B402.status="Protected runtime error — advertising controller paused"
            B402.phase="ERROR"
            b402_log("RUNTIME_ERROR",tostring(err))
        end
        if Script.Yield then Script.Yield(B402.active==true and 250 or 1000) end
    end)
end

-- B402 status HUD takes precedence while production advertising is active.
B402.status_hud_pre=startup.get_advertise_status_hud_line
startup.get_advertise_status_hud_line=function()
    if B402.active==true and startup.s.showAdvertiseStatusHud==true then
        local players=startup.b398_get_player_count and startup.b398_get_player_count() or (startup.get_session_player_count and startup.get_session_player_count() or 0)
        local spec=B402.expected or startup.b402_get_spec()
        return "Advertise | "..tostring(spec.variant).." | "..tostring(players).." players | "..tostring(B402.phase), {95,255,125}
    end
    return B402.status_hud_pre and B402.status_hud_pre() or nil
end

if startup.support_log_event_quiet then
    startup.support_log_event_quiet("BUILD402_PRODUCTION_ADVERTISING_VARIANTS_READY",
        "default=Standard Advertise | variants=Standard,Any,Region,Synced Region | Any Advertise=Override Any + Advertise My Region | no_rotation=true | Advertise Session ON=true | session_change_reapply=true")
end



end
startup.install_build402_advertising_variants()
startup.install_build402_advertising_variants=nil

startup.version="v1.0.18"
startup.console_version="v1.0.18"
startup.build_number="2026.08.29.412"
startup.build_date="2026-08-29"
startup.build_label="B412 v1.0.18 Production - Prime Hosting + Any Advertise"
if startup.log then startup.log("[Build 412] v1.0.18 Production ready: Prime hosting control, Any Advertise, HUD/Guide polish, and B411 local-limit repair retained.") end
if startup.support_log_event_quiet then startup.support_log_event_quiet("BUILD401_ADVERTISING_METHOD_TEST_READY","one_button=true trials=18 rounds=3 methods=6 fresh_session_each=true timeout_min=5 target_players=10 randomized_blocks=true exclusive_owner=true") end

end
