if startup.support_log_event_quiet then startup.support_log_event_quiet("BUILD412_V1017_ADVERTISING_UI_READY","default=Standard Advertise any_override=Any any_advertise=My Region controller=B402") end

-- ============================================================================
-- BUILD 404: HUD RUNTIME INSTALLATION + PRODUCTION ADVERTISING HUD
-- ============================================================================
-- Root cause:
-- Startup defines install_safe_hud_loop(), hud_renderer_tick(),
-- render_session_info_hud(), and render_advertise_status_hud(), but the final
-- merged script never invokes install_safe_hud_loop(). Therefore both the
-- Session HUD and Advertise HUD can silently never receive render frames.
--
-- B404 explicitly installs that intended safe GTA-native HUD loop and gives
-- B402 production advertising a dedicated multi-line HUD.
-- ============================================================================

startup.install_build404_hud_runtime_fix=function()
    startup.b404 = startup.b404 or {}
    local B404 = startup.b404
    B404.preview_until_ms = 0
    B404.loaded = true
    B404.hud_loop_repaired = false

    local function now404()
        return startup.now and startup.now() or math.floor((os.clock() or 0)*1000)
    end

    local function player_count404()
        if startup.b398_get_player_count then
            local ok,n=direct_call(startup.b398_get_player_count)
            if ok then return tonumber(n or 0) or 0 end
        end
        if startup.get_session_player_count then
            local ok,n=direct_call(startup.get_session_player_count)
            if ok then return tonumber(n or 0) or 0 end
        end
        return 0
    end

    local function advertise_session_label404()
        if startup.b375_native_advertise_state then
            local ok,state=pcall(startup.b375_native_advertise_state)
            if ok then
                if state==true then return "ON" end
                if state==false then return "OFF" end
            end
        end
        if startup.s and startup.s.advertiseSessionEnabled==true then return "ON" end
        return "WRITE-ONLY"
    end

    -- Dedicated B402 production advertising HUD. GTA-native draw_hud_text only:
    -- no ImGui window-scoped calls, preserving the B381 Debug-window safety rule.
    B404.render_advertise_pre = startup.render_advertise_status_hud
    startup.render_advertise_status_hud=function()
        local active = startup.b402 and startup.b402.active==true
        local preview = tonumber(B404.preview_until_ms or 0) > now404()

        if not active and not preview then
            -- Build 405: never call the captured legacy renderer here. That
            -- renderer could receive a text-only status and index color=nil.
            -- Render any legacy status directly with a guaranteed color instead.
            if startup.s.showAdvertiseStatusHud ~= true then return end

            local ok, legacyText, legacyColor = pcall(function()
                if startup.get_advertise_status_hud_line then
                    return startup.get_advertise_status_hud_line()
                end
                return nil
            end)
            if not ok or not legacyText then return end
            if type(legacyColor) ~= "table" then legacyColor = {255,255,255} end

            local lx = startup.get_effective_hud_x and
                startup.get_effective_hud_x(startup.s.advertiseStatusHudX or 0.023) or
                (startup.s.advertiseStatusHudX or 0.023)
            local ly = startup.clamp_float and
                startup.clamp_float(tonumber(startup.s.advertiseStatusHudY or 0.981) or 0.968,0.70,0.985) or
                0.968
            local lscale = startup.clamp_float and
                startup.clamp_float(tonumber(startup.s.advertiseStatusHudScale or 0.25) or 0.30,0.20,0.55) or
                0.30
            local lalpha = startup.clamp_int and
                startup.clamp_int(tonumber(startup.s.advertiseStatusHudAlpha or 200) or 200,70,255) or
                200

            startup.draw_hud_text(
                tostring(legacyText), lx, ly, lscale,
                tonumber(legacyColor[1] or 255) or 255,
                tonumber(legacyColor[2] or 255) or 255,
                tonumber(legacyColor[3] or 255) or 255,
                lalpha,4,startup.s.advertiseStatusHudShadow ~= false
            )
            return true
        end

        startup.s.showAdvertiseStatusHud = true

        local spec = startup.b402_get_spec and startup.b402_get_spec() or {
            variant=tostring(startup.s.advertisingVariant402 or "Standard Advertise"),
            override="My Region",
            advertise="My Region"
        }
        if startup.b402 and startup.b402.expected then spec=startup.b402.expected end

        local phase = active and tostring(startup.b402.phase or "ACTIVE") or "HUD PREVIEW"
        local status = active and tostring(startup.b402.status or "Active") or "Production HUD preview"
        local players = player_count404()
        local actualOv = startup.b402_read_override_region and startup.b402_read_override_region() or (startup.b373_read_override_region and startup.b373_read_override_region() or tostring(spec.override or "Unknown"))
        local actualAdv = startup.get_advertise_region_label and startup.get_advertise_region_label(false) or tostring(spec.advertise or "Unknown")
        local sess = advertise_session_label404()

        -- Keep the production advertising HUD safely above the absolute bottom edge.
        local x = startup.get_effective_hud_x and startup.get_effective_hud_x(0.023) or 0.023
        local y = 0.895
        local scale = 0.285
        local alpha = 220
        local gap = 0.024

        startup.draw_hud_text("STARTUP ADVERTISING", x, y, scale, 95,255,125,alpha,4,true)
        startup.draw_hud_text("Method: "..tostring(spec.variant or "Standard Advertise"), x, y+gap, scale, 255,255,255,alpha,4,true)
        startup.draw_hud_text("Players: "..tostring(players).." | State: "..phase, x, y+(gap*2), scale, 255,220,110,alpha,4,true)
        startup.draw_hud_text("Override: "..tostring(actualOv).." | Advertise: "..tostring(actualAdv), x, y+(gap*3), scale, 120,205,255,alpha,4,true)
        startup.draw_hud_text("Advertise Session: "..tostring(sess), x, y+(gap*4), scale,
            sess=="ON" and 95 or 255, sess=="ON" and 255 or 190, sess=="ON" and 125 or 65, alpha,4,true)

        startup.s.lastHudStatus="B404 production advertising HUD rendering"
        return true
    end

    startup.add_button("PreviewProductionAdvertisingHud404","PREVIEW ADVERTISING HUD",
        "Shows the production advertising HUD for 10 seconds without changing regions, Advertise Session, or session routing.",
        function()
            B404.preview_until_ms=now404()+10000
            startup.s.showAdvertiseStatusHud=true
            if startup.toast then startup.toast("Production Advertising HUD preview enabled for 10 seconds.",2500) end
        end)

    -- The missing call that caused the HUD to disappear.
    -- Force a fresh install flag because this merged file never called the installer.
    if startup.install_safe_hud_loop then
        startup.s.safeHudLoopInstalled=false
        local ok,err=direct_call(startup.install_safe_hud_loop)
        B404.hud_loop_repaired=ok==true and startup.s.safeHudLoopInstalled==true
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet(
                B404.hud_loop_repaired and "BUILD404_HUD_LOOP_INSTALLED" or "BUILD404_HUD_LOOP_INSTALL_FAILED",
                B404.hud_loop_repaired and "session_hud=true advertise_hud=true" or tostring(err or "unknown")
            )
        end
    end

    -- Ensure the Advertise HUD is enabled. Session Info HUD remains controlled by
    -- its existing user setting; B404 simply restores its missing renderer.
