-- ============================================================================
-- BUILD 417: IMMEDIATE GTA ONLINE ADVERTISING + GUIDE REFRESH
-- - Rising edge from Singleplayer/loading -> GTA Online immediately arms the saved
--   production advertising method and turns Auto Advertise Session ON.
-- - Advertise Session itself is requested ON immediately; sensitive region writes
--   remain serialized and keep the existing B402 stability/local-host safety gate.
-- - Guide tab is refreshed for v1.0.18 production behavior and troubleshooting.
-- ============================================================================
startup.b417 = startup.b417 or {
    online_ready_last = nil,
    pending_session_on = false,
    session_retry_count = 0,
    next_session_retry_ms = 0,
    last_arm_ms = 0,
    last_session_on_detail = "",
}

function startup.b417_now()
    return startup.now and tonumber(startup.now()) or math.floor((os.clock and os.clock() or 0) * 1000)
end

function startup.b417_sync_auto_advertise_on()
    startup.s.autoAdvertiseSession = true
    startup.s.autoAdvertiseUserConfigured = true
    if startup.set_feature_bool_silently and startup.h then
        direct_call(startup.set_feature_bool_silently, startup.h.AutoAdvertiseSession, true)
    end
end

function startup.b417_request_advertise_session_on(reason)
    local ok, mode, detail = false, "UNAVAILABLE", ""
    if startup.b401_set_advertise_session then
        ok, mode, detail = startup.b401_set_advertise_session(true, "B417 immediate Online entry | " .. tostring(reason or "GTA Online ready"))
    elseif startup.set_advertise_session then
        ok = startup.set_advertise_session(true, true) == true
        mode = ok and "LEGACY_SETTER" or "LEGACY_SETTER_FAILED"
    end
    startup.b417.last_session_on_detail = tostring(mode or "") .. " | " .. tostring(detail or "")
    if ok == true then
        startup.s.advertiseSessionEnabled = true
        startup.b417.pending_session_on = false
        startup.b417.session_retry_count = 0
        startup.b417.next_session_retry_ms = 0
        if startup.b402 and startup.b402.active == true then
            startup.s.lastAdvertiseStatus = tostring((startup.b402.expected and startup.b402.expected.variant) or startup.s.advertisingVariant402 or "Advertising") .. " | Advertise Session ON immediately; preparing region state"
        else
            startup.s.lastAdvertiseStatus = "Advertise Session ON immediately"
        end
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("BUILD417_ADVERTISE_SESSION_ON_IMMEDIATE", "mode=" .. tostring(mode or "") .. " reason=" .. tostring(reason or ""))
        end
        return true
    end
    startup.b417.pending_session_on = true
    startup.b417.session_retry_count = math.min(15, (tonumber(startup.b417.session_retry_count or 0) or 0) + 1)
    startup.b417.next_session_retry_ms = startup.b417_now() + 1000
    startup.s.lastAdvertiseStatus = "GTA Online ready; retrying immediate Advertise Session ON"
    return false
end

function startup.b417_arm_online_advertising(reason)
    if not startup.s or startup.s.initialized ~= true then return false end
    if startup.b401 and startup.b401.active == true then return false end
    if startup.b378 and startup.b378.active == true then return false end
    if startup.b374 and startup.b374.active == true then return false end

    startup.b417_sync_auto_advertise_on()
    if startup.save_config then direct_call(startup.save_config, false) end

    local started = false
    if startup.b402_start then
        -- Auto-owned + non-immediate region path: the production controller is armed
        -- now, but Override/Advertise Region still wait for the proven safe gate.
        started = startup.b402_start("GTA Online became ready — immediate advertising", true, false) == true
    end
    if not started and not startup.b402_start then
        started = true -- legacy fallback can still request Advertise Session below.
    end
    if not started then return false end

    startup.b417.last_arm_ms = startup.b417_now()
    startup.b417.session_retry_count = 0
    startup.b417.next_session_retry_ms = 0
    startup.b417_request_advertise_session_on(reason or "GTA Online ready")
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet(
            "BUILD417_ONLINE_ADVERTISING_ARMED",
            "method=" .. tostring(startup.s.advertisingVariant402 or "Standard Advertise") ..
            " auto_advertise=true immediate_session_on=true serialized_region_gate=true"
        )
    end
    return true
end

function startup.b417_online_transition_tick()
    if not startup.s or startup.s.initialized ~= true then return end
    local ready = startup.is_gta_online_session_ready and startup.is_gta_online_session_ready() == true
    if ready ~= true then
        startup.b417.online_ready_last = false
        startup.b417.pending_session_on = false
        startup.b417.session_retry_count = 0
        startup.b417.next_session_retry_ms = 0
        return
    end

    if startup.b417.online_ready_last ~= true then
        startup.b417.online_ready_last = true
        startup.b417_arm_online_advertising("Singleplayer/loading -> GTA Online")
        return
    end

    if startup.b417.pending_session_on == true
        and (tonumber(startup.b417.session_retry_count or 0) or 0) < 15
        and startup.b417_now() >= (tonumber(startup.b417.next_session_retry_ms or 0) or 0) then
        startup.b417_request_advertise_session_on("Online entry retry " .. tostring((tonumber(startup.b417.session_retry_count or 0) or 0) + 1))
    end
end

if Script and Script.RegisterLooped then
    Script.RegisterLooped(function()
        if ShouldUnload and ShouldUnload() then
            if Script.Yield then Script.Yield(250) end
            return
        end
        local ok, err = pcall(startup.b417_online_transition_tick)
        if not ok and startup.support_log_event_quiet then
            startup.support_log_event_quiet("BUILD417_ONLINE_ADVERTISING_TICK_ERROR", tostring(err or "unknown"))
        end
        if Script.Yield then Script.Yield(250) end
    end)
end

