-- ============================================================================
-- BUILD 418: ACTIVITY FEED X LIVE POSITION HOTFIX
-- Root cause: the later B391 compatibility resolver overwrote the earlier B415
-- X-position fix. While Auto Position was ON, it continued deriving Activity X
-- from Session HUD X, so moving Activity Feed X changed the slider/config but not
-- the rendered cards. B418 is the final resolver and therefore wins at runtime.
-- Auto Position owns Y only; Activity Feed X always comes from the live slider.
-- ============================================================================
function startup.b418_get_live_activity_x()
    local value = tonumber(startup.s and startup.s.sessionActivityX or 0.174) or 0.174
    if startup.h and startup.h.SessionActivityXSlider then
        local feature = nil
        if FeatureMgr and FeatureMgr.GetFeature then
            local okFeature, resolved = direct_call(FeatureMgr.GetFeature, startup.h.SessionActivityXSlider)
            if okFeature then feature = resolved end
        elseif startup.get_feature_by_hash_safe then
            local okFeature, resolved = direct_call(startup.get_feature_by_hash_safe, startup.h.SessionActivityXSlider)
            if okFeature then feature = resolved end
        end
        if feature and feature.GetFloatValue then
            local okValue, liveValue = pcall(function() return feature:GetFloatValue() end)
            if okValue and tonumber(liveValue) ~= nil then value = tonumber(liveValue) end
        elseif feature and feature.GetIntValue then
            local okValue, liveValue = pcall(function() return feature:GetIntValue() end)
            if okValue and tonumber(liveValue) ~= nil then value = tonumber(liveValue) end
        end
    end
    value = startup.clamp_float and startup.clamp_float(value, 0.005, 0.90) or math.max(0.005, math.min(0.90, value))
    startup.s.sessionActivityX = value
    return value
end

startup.session_activity_resolve_render_position = function()
    local rawX = startup.b418_get_live_activity_x()
    local activityX = startup.get_effective_hud_x and startup.get_effective_hud_x(rawX) or rawX
    local mode = tostring(startup.s.sessionActivityPlacementMode or "Above Session HUD Stack")

    if startup.s.sessionActivityAutoPosition ~= false or mode == "Above Session HUD Stack" then
        local fallbackBottomY = tonumber(startup.s.sessionActivityBottomY or 0.891) or 0.891
        local layout = startup.hud_layout or {}
        local dynamicBottomY = tonumber(layout.classicActivityBottomY)
        local layoutUpdatedMs = tonumber(layout.updatedMs or 0) or 0
        local now = startup.now and startup.now() or math.floor((os.clock and os.clock() or 0) * 1000)

        if dynamicBottomY ~= nil and layoutUpdatedMs > 0 and (now - layoutUpdatedMs) <= 1250 then
            return activityX, startup.clamp_float(dynamicBottomY, 0.12, 0.95)
        end
        return activityX, startup.clamp_float(fallbackBottomY, 0.12, 0.95)
    end

    return activityX, tonumber(startup.s.sessionActivityBottomY or 0.806) or 0.806
end

-- Keep 0.174 as the production default/current startup value unless the user has
-- already moved the live slider during this run. The resolver above continuously
-- mirrors that live slider back into startup.s.sessionActivityX.
if startup.s.sessionActivityX == nil then startup.s.sessionActivityX = 0.174 end
if startup.set_feature_float_silently and startup.h and startup.h.SessionActivityXSlider then
    direct_call(startup.set_feature_float_silently, startup.h.SessionActivityXSlider, startup.s.sessionActivityX)
end

