-- ============================================================================
-- BUILD 419: STARTUP BROWSER LIVE NOTIFICATIONS + EVENT CARDS
-- - Authenticated Startup Browser JOIN tickets can show the destination host a
--   top-right sliding Host Profile card before the requester reaches the lobby.
-- - Newly published Browser Events show a top-right clickable Event Card.
-- - Clicking an Event Card opens event details and then continues through the
--   existing mandatory Browser JOIN policy flow before any RID JOIN is started.
-- - Public_Urinal events are identified by the server-bound Developer owner UID
--   and open a dedicated Developer Event popup instead of a normal Event Card.
-- - Hosts also see their own event presentation locally for testing. This is
--   presentation-only and never creates fake RSVP/attendance/backend records.
-- - At most three notification cards are visible; additional cards queue.
-- ============================================================================
startup.b419 = startup.b419 or {
    sequence = 0,
    queue = {},
    active = {},
    dedupe = {},
    pending_join_profiles = {},
    event_seen = {},
    event_candidates = {},
    event_seeded = false,
    next_event_scan_ms = 0,
    detail_event = nil,
    developer_event = nil,
    publish_wrapped = false,
    present_installed = false,
    join_event_installed = false,
    loop_installed = false,
    max_visible = 3,
    enter_ms = 420,
    hold_ms = 5200,
    exit_ms = 420,
}

function startup.b419_now()
    if startup.now then return tonumber(startup.now()) or 0 end
    if Time and Time.GetEpocheMs then
        local ok, value = direct_call(Time.GetEpocheMs)
        if ok then return tonumber(value or 0) or 0 end
    end
    return math.floor((os.clock and os.clock() or 0) * 1000)
end

function startup.b419_lower(value)
    return tostring(value or ""):lower()
end

function startup.b419_clamp01(value)
    value = tonumber(value or 0) or 0
    if value < 0 then return 0 end
    if value > 1 then return 1 end
    return value
end

function startup.b419_ease_out_cubic(value)
    value = startup.b419_clamp01(value)
    return 1 - ((1 - value) * (1 - value) * (1 - value))
end

function startup.b419_ease_in_cubic(value)
    value = startup.b419_clamp01(value)
    return value * value * value
end

function startup.b419_developer_owner_uid()
    return tostring(startup.browser_moderation and startup.browser_moderation.owner_uid or "PU-B548A0968B01AB57EC8C276359F1B06F")
end

function startup.b419_is_local_developer()
    local bb = startup.browser_backend or {}
    return tostring(bb.startup_uid or "") ~= "" and tostring(bb.startup_uid or "") == startup.b419_developer_owner_uid()
end

function startup.b419_local_name()
    if startup.b419_is_local_developer() then return "Public_Urinal" end
    local ids = nil
    if startup.get_local_player_id_candidates then
        local ok, value = direct_call(startup.get_local_player_id_candidates)
        if ok and type(value) == "table" then ids = value end
    end
    local id = ids and tonumber(ids[1]) or nil
    if id ~= nil and startup.get_player_name_safe then
        local ok, value = direct_call(startup.get_player_name_safe, id)
        if ok and tostring(value or "") ~= "" then return tostring(value) end
    end
    return "Startup User"
end

function startup.b419_profile_hash(value)
    local text = tostring(value or "Startup User")
    local hash = 2166136261
    for i = 1, #text do hash = (hash * 131 + string.byte(text, i)) % 2147483647 end
    return math.abs(hash)
end

function startup.b419_backdrop_key(profile)
    profile = type(profile) == "table" and profile or {}
    local explicit = tonumber(profile.profileBackdropId or profile.backdrop_id or 0) or 0
    local idx = (explicit >= 1 and explicit <= 10) and explicit or ((startup.b419_profile_hash(profile.profileUsername or profile.username or profile.host or "Startup User") % 10) + 1)
    return string.format("profile_backdrop_%02d", idx)
end

function startup.b419_role_label(profile)
    profile = type(profile) == "table" and profile or {}
    local name = tostring(profile.profileUsername or profile.username or profile.host or "")
    local uid = tostring(profile.profileUid or profile.profile_uid or profile.startup_uid or "")
    if uid ~= "" and uid == startup.b419_developer_owner_uid() then return "Developer" end
    if startup.browser_developer_usernames and startup.browser_developer_usernames[name] == true then return "Developer" end
    local role = tostring(profile.profileRole or profile.profile_role or profile.role or "")
    if role ~= "" then return role end
    return "Startup User"
end

function startup.b419_rank_label(profile)
    profile = type(profile) == "table" and profile or {}
    local rank = tostring(profile.profileRank or profile.profile_rank or profile.rank or "")
    return rank ~= "" and rank or ""
end

function startup.b419_merge_profile(dst, src)
    if type(dst) ~= "table" or type(src) ~= "table" then return dst end
    local aliases = {
        profileUid={"profileUid","profile_uid","startup_uid","user_uid","requester_uid"},
        profileUsername={"profileUsername","profile_username","username","host","host_name"},
        profileRole={"profileRole","profile_role","role"},
        profileRank={"profileRank","profile_rank","rank"},
        profileBackdropId={"profileBackdropId","profile_backdrop_id","backdrop_id"},
        profileMemberSince={"profileMemberSince","profile_member_since","member_since"},
        profileReliability={"profileReliability","profile_reliability","reliability"},
        profileRatings={"profileRatings","profile_ratings","ratings"},
        profileLikes={"profileLikes","profile_likes","likes"},
        profileDislikes={"profileDislikes","profile_dislikes","dislikes"},
        profileFavorites={"profileFavorites","profile_favorites","favorites"},
        profileStars={"profileStars","profile_stars","stars"},
        profileReports7d={"profileReports7d","profile_reports_7d","reports7d","reports_7d"},
        profileReportsAllTime={"profileReportsAllTime","profile_reports_all_time","reportsAllTime","reports_all_time"},
        edition={"edition"},
    }
    for canonical, keys in pairs(aliases) do
        if dst[canonical] == nil or tostring(dst[canonical] or "") == "" then
            for _, key in ipairs(keys) do
                if src[key] ~= nil and tostring(src[key] or "") ~= "" then
                    dst[canonical] = src[key]
                    break
                end
            end
        end
    end
    return dst
end

function startup.b419_find_cached_profile(username, uid)
    local profile = {profileUsername=tostring(username or ""), profileUid=tostring(uid or "")}
    local wantedName = startup.b419_lower(username)
    local wantedUid = tostring(uid or "")
    if startup.browser_runtime_get_source_rows then
        local ok, rows = direct_call(startup.browser_runtime_get_source_rows)
        if ok and type(rows) == "table" then
            for _, row in ipairs(rows) do
                if type(row) == "table" then
                    local rowName = startup.b419_lower(row.profileUsername or row.username)
                    local rowUid = tostring(row.profileUid or row.profile_uid or row.startup_uid or "")
                    if (wantedUid ~= "" and rowUid == wantedUid) or (wantedName ~= "" and rowName == wantedName) then
                        startup.b419_merge_profile(profile, row)
                        break
                    end
                end
            end
        end
    end
    local social = startup.browser_social_backend and startup.browser_social_backend.events_by_id or nil
    if type(social) == "table" then
        for _, meta in pairs(social) do
            if type(meta) == "table" then
                local metaName = startup.b419_lower(meta.profileUsername or meta.username)
                local metaUid = tostring(meta.profileUid or meta.profile_uid or meta.startup_uid or "")
                if (wantedUid ~= "" and metaUid == wantedUid) or (wantedName ~= "" and metaName == wantedName) then
                    startup.b419_merge_profile(profile, meta)
                    break
                end
            end
        end
    end
    if tostring(profile.profileUsername or "") == "" then profile.profileUsername = tostring(username or "Startup User") end
    return profile
end

function startup.b419_profile_from_join_request(req)
    req = type(req) == "table" and req or {}
    local username = tostring(req.profileUsername or req.profile_username or req.username or "Startup User")
    local uid = tostring(req.profileUid or req.profile_uid or req.startup_uid or req.user_uid or req.requester_uid or "")
    local profile = startup.b419_find_cached_profile(username, uid)
    startup.b419_merge_profile(profile, req)
    profile.profileUsername = tostring(profile.profileUsername or username)
    return profile
end

function startup.b419_star_text(profile)
    profile = type(profile) == "table" and profile or {}
    local likes = math.max(0, tonumber(profile.profileLikes or 0) or 0)
    local dislikes = math.max(0, tonumber(profile.profileDislikes or 0) or 0)
    local ratings = math.max(0, tonumber(profile.profileRatings or 0) or (likes + dislikes))
    local stars = tonumber(profile.profileStars or 0) or 0
    if stars <= 0 and (likes + dislikes) > 0 then
        local reports7d = math.max(0, tonumber(profile.profileReports7d or 0) or 0)
        local reportsAll = math.max(reports7d, tonumber(profile.profileReportsAllTime or reports7d) or reports7d)
        local base = 1.0 + 4.0 * (likes / (likes + dislikes))
        local olderReports = math.max(0, reportsAll - reports7d)
        local penalty = math.min(2.0, reports7d * 0.25 + olderReports * 0.05)
        stars = math.max(1.0, math.min(5.0, base - penalty))
    end
    if ratings <= 0 and stars <= 0 then return "" end
    if stars <= 0 then return "" end
    local rounded = math.max(1, math.min(5, math.floor(stars + 0.5)))
    return string.rep("★", rounded) .. string.rep("☆", 5 - rounded)
end

function startup.b419_push_notification(kind, payload, dedupeKey)
    payload = type(payload) == "table" and payload or {}
    local now = startup.b419_now()
    local key = tostring(dedupeKey or "")
    if key ~= "" then
        local untilMs = tonumber(startup.b419.dedupe[key] or 0) or 0
        if untilMs > now then return false end
        startup.b419.dedupe[key] = now + 600000
    end
    startup.b419.sequence = (tonumber(startup.b419.sequence or 0) or 0) + 1
    payload.id = startup.b419.sequence
    payload.kind = tostring(kind or "info")
    payload.enter_ms = tonumber(payload.enter_ms or startup.b419.enter_ms or 420) or 420
    payload.hold_ms = tonumber(payload.hold_ms or startup.b419.hold_ms or 5200) or 5200
    payload.exit_ms = tonumber(payload.exit_ms or startup.b419.exit_ms or 420) or 420
    payload.started_ms = 0
    startup.b419.queue[#startup.b419.queue + 1] = payload
    return true
end

function startup.b419_promote_notifications()
    local now = startup.b419_now()
    for i = #startup.b419.active, 1, -1 do
        local card = startup.b419.active[i]
        local total = (tonumber(card.enter_ms or 420) or 420) + (tonumber(card.hold_ms or 5200) or 5200) + (tonumber(card.exit_ms or 420) or 420)
        if tonumber(card.started_ms or 0) > 0 and now - tonumber(card.started_ms or now) >= total then
            table.remove(startup.b419.active, i)
        end
    end
    while #startup.b419.active < math.max(1, tonumber(startup.b419.max_visible or 3) or 3) and #startup.b419.queue > 0 do
        local card = table.remove(startup.b419.queue, 1)
        card.started_ms = now
        startup.b419.active[#startup.b419.active + 1] = card
    end
    for key, untilMs in pairs(startup.b419.dedupe) do
        if tonumber(untilMs or 0) <= now then startup.b419.dedupe[key] = nil end
    end
end

function startup.b419_update_join_card(username, success, playerId)
    local key = startup.b419_lower(username)
    if key == "" then return false end
    local now = startup.b419_now()
    local changed = false
    local function update_list(list)
        for _, card in ipairs(list or {}) do
            if (card.kind == "join_request" or card.kind == "join_success") and startup.b419_lower(card.username) == key then
                card.kind = success and "join_success" or "join_request"
                card.playerId = playerId
                card.message = success and (tostring(card.username or username) .. " joined your session! ✓") or (tostring(card.username or username) .. " is Joining your session!")
                card.hold_ms = success and 3600 or card.hold_ms
                if tonumber(card.started_ms or 0) > 0 then card.started_ms = now - tonumber(card.enter_ms or 420) end
                changed = true
            end
        end
    end
    update_list(startup.b419.active)
    update_list(startup.b419.queue)
    return changed
end

function startup.b419_on_pending_browser_join(req)
    req = type(req) == "table" and req or {}
    local joinId = tostring(req.join_id or "")
    local username = tostring(req.username or req.profileUsername or req.profile_username or "Startup User")
    if joinId == "" or username == "" then return false end
    local profile = startup.b419_profile_from_join_request(req)
    local key = startup.b419_lower(username)
    startup.b419.pending_join_profiles[key] = {profile=profile, expires_ms=startup.b419_now()+90000, join_id=joinId}
    return startup.b419_push_notification("join_request", {
        username=username,
        profile=profile,
        message=username .. " is Joining your session!",
        clickable=false,
    }, "join:"..joinId)
end

function startup.b419_on_player_join(playerId)
    playerId = tonumber(playerId)
    if playerId == nil then return end
    if not Script or not Script.QueueJob then return end
    Script.QueueJob(function()
        if Script.Yield then Script.Yield(650) end
        local name = startup.get_player_name_safe and tostring(startup.get_player_name_safe(playerId) or "") or ""
        if name == "" then return end
        local key = startup.b419_lower(name)
        local pending = startup.b419.pending_join_profiles[key]
        if type(pending) ~= "table" or tonumber(pending.expires_ms or 0) < startup.b419_now() then return end
        local changed = startup.b419_update_join_card(name, true, playerId)
        if not changed then
            startup.b419_push_notification("join_success", {
                username=name,
                profile=pending.profile,
                playerId=playerId,
                message=name .. " joined your session! ✓",
                clickable=false,
                hold_ms=3600,
            }, "join-success:"..tostring(pending.join_id or key))
        end
        startup.b419.pending_join_profiles[key] = nil
    end)
end

function startup.b419_event_profile(eventRow)
    eventRow = type(eventRow) == "table" and eventRow or {}
    local eventId = tostring(eventRow.event_id or "")
    local social = startup.browser_social_backend and startup.browser_social_backend.events_by_id and startup.browser_social_backend.events_by_id[eventId] or nil
    social = type(social) == "table" and social or {}
    local uid = tostring(social.profileUid or social.profile_uid or eventRow.profile_uid or eventRow.host_uid or eventRow.owner_uid or eventRow.startup_uid or eventRow.user_uid or "")
    local name = tostring(social.profileUsername or social.profile_username or eventRow.host_name or eventRow.owner_name or eventRow.author_name or eventRow.username or "")
    if name == "" and uid ~= "" and uid == startup.b419_developer_owner_uid() then name = "Public_Urinal" end
    if name == "" then name = "Startup User" end
    local profile = startup.b419_find_cached_profile(name, uid)
    startup.b419_merge_profile(profile, social)
    startup.b419_merge_profile(profile, eventRow)
    profile.profileUid = tostring(profile.profileUid or uid)
    profile.profileUsername = tostring(profile.profileUsername or name)
    return profile, social
end

function startup.b419_category_asset(category, activity)
    if startup.browser_activity_art_key then
        local ok, key = direct_call(startup.browser_activity_art_key, category, activity)
        if ok and tostring(key or "") ~= "" then return key end
    end
    local cat = tostring(category or "NORMAL"):upper()
    if cat == "VEHICLES" then return "event_car_meet" end
    if cat == "MINIGAMES" then return "event_parkour" end
    if cat == "ROLEPLAYING" then return "event_police_rp" end
    if cat == "WAR" or cat == "ROCKSTAR JOB" or cat == "ROCKSTAR JOBS" then return "event_wargames" end
    return "event_social_hangout"
end

function startup.b419_event_from_backend(eventRow, localPayload)
    eventRow = type(eventRow) == "table" and eventRow or {}
    local profile, social = startup.b419_event_profile(eventRow)
    local bb = startup.browser_backend or {}
    local eventId = tostring(eventRow.event_id or (type(localPayload)=="table" and localPayload.event_id) or "")
    local category = tostring(eventRow.category or (type(localPayload)=="table" and localPayload.category) or "NORMAL")
    local activity = tostring(eventRow.activity or (type(localPayload)=="table" and localPayload.activity) or "GENERAL SESSION")
    local title = tostring(eventRow.title or eventRow.rockstar_job_name or (type(localPayload)=="table" and (localPayload.title or localPayload.activity)) or activity or "STARTUP EVENT")
    local description = tostring(eventRow.description or (type(localPayload)=="table" and localPayload.description) or "Startup Browser event.")
    local starts = tostring(eventRow.start_label or eventRow.start_mode or eventRow.starts_at or eventRow.scheduled_start_at or (type(localPayload)=="table" and localPayload.start_mode) or "NOW")
    local mic = tostring(eventRow.mic_requirement or (type(localPayload)=="table" and localPayload.mic_requirement) or "MIC OPTIONAL")
    local maxPlayers = math.max(1, tonumber(eventRow.max_players or (type(localPayload)=="table" and localPayload.max_players) or 30) or 30)
    local players = math.max(0, tonumber(eventRow.players or eventRow.published_players or 0) or 0)
    local listingId = tostring(eventRow.listing_id or social.listing_id or bb.listing_id or "")
    local profileUid = tostring(profile.profileUid or "")
    local ownUid = tostring(bb.startup_uid or "")
    local isSelf = (profileUid ~= "" and ownUid ~= "" and profileUid == ownUid) or social.is_host == true or (type(localPayload)=="table" and localPayload._b419_self==true)
    if isSelf and tostring(profile.profileUsername or "") == "Startup User" then profile.profileUsername = startup.b419_local_name() end
    if isSelf and profileUid == "" then profile.profileUid = ownUid; profileUid = ownUid end
    local isDeveloper = profileUid ~= "" and profileUid == startup.b419_developer_owner_uid()
    local joinable = eventRow.joinable == true or tostring(eventRow.joinable or ""):lower() == "true" or tonumber(eventRow.joinable or 0) == 1
    if isSelf then joinable = false end
    local row = {
        live=true,
        listingId=listingId,
        username=tostring(profile.profileUsername or "Startup User"),
        edition=tostring(eventRow.edition or profile.edition or ""),
        players=players,
        maxPlayers=maxPlayers,
        joinable=joinable,
        category=category,
        activity=activity,
        mic=mic,
        profileUid=profile.profileUid,
        profileUsername=profile.profileUsername,
        profileMemberSince=profile.profileMemberSince,
        profileRole=profile.profileRole,
        profileRank=profile.profileRank,
        profileBackdropId=profile.profileBackdropId,
        profileReliability=tonumber(profile.profileReliability or 0) or 0,
        profileRatings=tonumber(profile.profileRatings or 0) or 0,
        profileLikes=tonumber(profile.profileLikes or 0) or 0,
        profileDislikes=tonumber(profile.profileDislikes or 0) or 0,
        profileFavorites=tonumber(profile.profileFavorites or 0) or 0,
        profileStars=tonumber(profile.profileStars or 0) or 0,
    }
    row.isStartupEvent=true
    row.eventId=eventId
    row.eventTitle=title
    row.edition=(startup.b432_event_edition and startup.b432_event_edition(row,eventRow)) or tostring(eventRow.edition or profile.edition or "")
    return {
        event_id=eventId,
        edition=tostring(row.edition or ""),
        title=title,
        category=category,
        activity=activity,
        description=description,
        starts=starts,
        mic=mic,
        players=players,
        max_players=maxPlayers,
        listing_id=listingId,
        host=tostring(profile.profileUsername or "Startup User"),
        profile=profile,
        row=row,
        joinable=joinable,
        is_self=isSelf,
        is_developer=isDeveloper,
        region=tostring(eventRow.region or eventRow.country_region or eventRow.country or ""),
        location=tostring(eventRow.location_area or ""),
    }
end

function startup.b419_open_event(eventData, developerSpecial)
    if type(eventData) ~= "table" then return false end
    if developerSpecial == true then
        startup.b419.developer_event = eventData
        startup.b419.detail_event = nil
    else
        startup.b419.detail_event = eventData
    end
    return true
end

function startup.b419_notify_event(eventData, source)
    if type(eventData) ~= "table" then return false end
    local eventId = tostring(eventData.event_id or "")
    if eventData.is_developer == true then
        startup.b419_open_event(eventData, true)
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("BUILD419_DEVELOPER_EVENT_POPUP", "event_id="..eventId.." self="..tostring(eventData.is_self==true).." source="..tostring(source or ""))
        end
        return true
    end
    return startup.b419_push_notification("event", {
        event=eventData,
        title=eventData.title,
        host=eventData.host,
        clickable=true,
        message="Startup Event",
    }, "event:"..eventId)
end

function startup.b419_scan_events()
    local now = startup.b419_now()
    if now < tonumber(startup.b419.next_event_scan_ms or 0) then return end
    startup.b419.next_event_scan_ms = now + 750
    local eb = startup.browser_events_backend
    local bb = startup.browser_backend
    if type(eb) ~= "table" or type(bb) ~= "table" or tostring(bb.token or "") == "" then return end
    if tonumber(eb.last_fetch_ms or 0) <= 0 then return end
    local rows = type(eb.events) == "table" and eb.events or {}

    if startup.b419.event_seeded ~= true then
        for _, row in ipairs(rows) do
            local id = tostring(row.event_id or "")
            if id ~= "" then startup.b419.event_seen[id] = true end
        end
        startup.b419.event_seeded = true
        return
    end

    local current = {}
    for _, row in ipairs(rows) do
        local id = tostring(row.event_id or "")
        if id ~= "" then
            current[id] = row
            if startup.b419.event_seen[id] ~= true and startup.b419.event_candidates[id] == nil then
                startup.b419.event_candidates[id] = {first_ms=now, row=row}
            elseif startup.b419.event_candidates[id] then
                startup.b419.event_candidates[id].row = row
            end
        end
    end

    for id, candidate in pairs(startup.b419.event_candidates) do
        local row = current[id] or candidate.row
        if type(row) ~= "table" then
            startup.b419.event_candidates[id] = nil
        else
            local eventData = startup.b419_event_from_backend(row)
            local profileUid = tostring(eventData.profile and eventData.profile.profileUid or "")
            local waited = now - tonumber(candidate.first_ms or now)
            if profileUid ~= "" or waited >= 3000 then
                startup.b419.event_seen[id] = true
                startup.b419.event_candidates[id] = nil
                startup.b419_notify_event(eventData, "EVENT_FEED")
            end
        end
    end
end

