    local colors, vars = 0, 0
    if ImGui and ImGui.PushStyleColor and ImGuiCol then
        if ImGuiCol.WindowBg then ImGui.PushStyleColor(ImGuiCol.WindowBg,0.055,0.025,0.090,0.975); colors=colors+1 end
        if ImGuiCol.Border then
            if developer then ImGui.PushStyleColor(ImGuiCol.Border,0.82,0.46,1.00,1.0) else ImGui.PushStyleColor(ImGuiCol.Border,0.58,0.28,0.88,0.96) end
            colors=colors+1
        end
        if ImGuiCol.Separator then ImGui.PushStyleColor(ImGuiCol.Separator,0.44,0.20,0.70,0.90); colors=colors+1 end
    end
    if ImGui and ImGui.PushStyleVar and ImGuiStyleVar then
        if ImGuiStyleVar.WindowRounding then ImGui.PushStyleVar(ImGuiStyleVar.WindowRounding,10.0); vars=vars+1 end
        if ImGuiStyleVar.WindowPadding then ImGui.PushStyleVar(ImGuiStyleVar.WindowPadding,12.0,10.0); vars=vars+1 end
    end
    return colors, vars
end

function startup.b419_pop_window_style(colors, vars)
    if ImGui and ImGui.PopStyleVar and tonumber(vars or 0) > 0 then ImGui.PopStyleVar(vars) end
    if ImGui and ImGui.PopStyleColor and tonumber(colors or 0) > 0 then ImGui.PopStyleColor(colors) end
end

