function startup.b419_draw_profile_summary(profile, message, compact)
    profile = type(profile) == "table" and profile or {}
    local name = tostring(profile.profileUsername or profile.username or "Startup User")
    local backdrop = startup.b419_backdrop_key(profile)
    local role = startup.b419_role_label(profile)
    local rank = startup.b419_rank_label(profile)
    local reliability = tonumber(profile.profileReliability or 0) or 0
    local stars = startup.b419_star_text(profile)
    local memberSince = tostring(profile.profileMemberSince or "")
    local imageW, imageH = compact and 84 or 118, compact and 64 or 82
    local drawn = false
    if startup.browser_ui_draw then
        local ok, value = pcall(startup.browser_ui_draw, backdrop, imageW, imageH, 6)
        drawn = ok and value == true
    end
    if not drawn and startup.browser_ui_draw then pcall(startup.browser_ui_draw, "startup_rocket_mark", compact and 58 or 72, compact and 58 or 72, 5) end
    if ImGui and ImGui.SameLine then ImGui.SameLine() end
    if ImGui and ImGui.BeginGroup then ImGui.BeginGroup() end
    startup.b419_white(name)
    if message and message ~= "" then startup.b419_purple(message) end
    startup.b419_dim(role .. (rank ~= "" and (" • "..rank) or ""))
    if memberSince ~= "" then startup.b419_dim("Member since "..memberSince) end
    if stars ~= "" then
        startup.b419_amber(stars)
        if reliability > 0 and ImGui and ImGui.SameLine then ImGui.SameLine(); startup.b419_green("Reliability "..tostring(math.floor(reliability+0.5)).."%") end
    elseif reliability > 0 then
        startup.b419_green("Reliability "..tostring(math.floor(reliability+0.5)).."%")
    else
        startup.b419_dim("Authenticated Startup User")
    end
    if ImGui and ImGui.EndGroup then ImGui.EndGroup() end
end

function startup.b419_display_size()
