    if startup.get_display_size then
        local ok, w, h = pcall(startup.get_display_size)
        if ok then
            sw = tonumber(w or sw) or sw
            sh = tonumber(h or sh) or sh
        end
    end
    return sw, sh
end

function startup.b419_notification_position(card, slot, width)
    local sw, sh = startup.b419_display_size()
    local shownX = math.max(12, sw - width - 24)
    local hiddenX = sw + 20
    local y = 22 + ((math.max(1, tonumber(slot or 1) or 1) - 1) * 172)
    local now = startup.b419_now()
    local age = math.max(0, now - tonumber(card.started_ms or now))
    local enterMs = math.max(1, tonumber(card.enter_ms or 420) or 420)
    local holdMs = math.max(250, tonumber(card.hold_ms or 5200) or 5200)
    local exitMs = math.max(1, tonumber(card.exit_ms or 420) or 420)
    local x = shownX
    if age < enterMs then
        local t = startup.b419_ease_out_cubic(age / enterMs)
        x = hiddenX + ((shownX - hiddenX) * t)
    elseif age > enterMs + holdMs then
        local t = startup.b419_ease_in_cubic((age - enterMs - holdMs) / exitMs)
        x = shownX + ((hiddenX - shownX) * t)
    end
    return x, math.min(y, math.max(22, sh - 170)), sw, sh
end

function startup.b419_render_notification(card, slot)
    if not ImGui or type(card) ~= "table" then return end
    local width = 430
    local height = card.kind == "event" and 178 or 148
    local x, y = startup.b419_notification_position(card, slot, width)
    if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(x, y, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(width, height, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowBgAlpha then ImGui.SetNextWindowBgAlpha(0.97) end
    local flags = startup.first_run_window_flags and startup.first_run_window_flags() or 0
    local colors, vars = startup.b419_push_window_style(false)
    local visible = ImGui.Begin("##Startup_B419_Notification_"..tostring(card.id or slot), true, flags) == true
    if visible then
        if card.kind == "event" and card.developer_special == true then
            startup.b419_purple("💜 STARTUP DEVELOPER EVENT")
        else
            startup.b419_purple(card.kind == "event" and "🚀 STARTUP EVENT" or "🚀 STARTUP BROWSER")
        end
        if card.kind == "event" and type(card.event) == "table" then
            local ev = card.event
            local asset = startup.b419_category_asset(ev.category, ev.activity)
            local drawn = false
            if startup.browser_ui_draw then
                local ok, value = pcall(startup.browser_ui_draw, asset, 82, 64, 5)
                drawn = ok and value == true
            end
            if not drawn and startup.browser_ui_draw then pcall(startup.browser_ui_draw, "nav_upcoming", 54, 54, 4) end
            if ImGui.SameLine then ImGui.SameLine() end
            if ImGui.BeginGroup then ImGui.BeginGroup() end
            startup.b419_white(tostring(ev.title or "STARTUP EVENT"))
            startup.b419_purple(tostring(ev.category or "EVENT").." • "..tostring(ev.activity or "ACTIVITY"))
            startup.b419_dim("Hosted by "..tostring(ev.host or "Startup User"))
            startup.b419_text(1.00,0.24,0.28,1.0,"GTA V Version: "..tostring((startup.b432_event_edition and startup.b432_event_edition(ev.row,ev)) or ev.edition or "Unknown"))
            startup.b419_dim("Starts: "..tostring(ev.starts or "NOW").." • Players: "..tostring(ev.players or 0).." / "..tostring(ev.max_players or 30))
            startup.b419_amber("CLICK FOR DETAILS")
            if ImGui.EndGroup then ImGui.EndGroup() end
        else
            startup.b419_draw_profile_summary(card.profile, tostring(card.message or ""), true)
        end
        local clicked = false
        if card.clickable == true and ImGui.IsWindowHovered and ImGui.IsMouseClicked then
            local okH, hovered = pcall(ImGui.IsWindowHovered)
            local okC, pressed = pcall(ImGui.IsMouseClicked, 0)
            clicked = okH and okC and hovered == true and pressed == true
        end
        if clicked and type(card.event) == "table" then
            if card.developer_special == true then
                startup.b419.developer_event = card.event
                startup.b419.developer_event_pending = nil
                startup.b419.developer_event_due_ms = 0
                startup.b419.detail_event = nil
            else
                startup.b419.detail_event = card.event
            end
            card.hold_ms = 1
            card.exit_ms = 220
            card.started_ms = startup.b419_now() - tonumber(card.enter_ms or 420) - tonumber(card.hold_ms or 1)
        end
    end
    ImGui.End()
    startup.b419_pop_window_style(colors, vars)
end

function startup.b419_open_browser_event(eventData)
    local ui = startup.browser_activity_ui_state or startup.activity_catalog_ui
    if type(ui) ~= "table" then return false end
    ui.popup_open = true
    ui.tab = "EVENTS"
    ui.category = "ALL"
    ui.events_filter = "ALL"
    ui.events_search = ""
    ui.events_region = "All Regions"
    ui.events_players = "Any"
    ui.events_start = "Anytime"
    ui.joinable_only = false
    if type(eventData) == "table" and tostring(eventData.event_id or "") ~= "" then
        ui.events_selected_key = "event_"..tostring(eventData.event_id)
    end
    if startup.browser_events_refresh then pcall(startup.browser_events_refresh) end
    -- Bring Cherax's ClickGUI forward so View Now is visible immediately instead of
    -- only changing Browser state in the background. All calls are capability-guarded.
    pcall(function()
        if GUI and GUI.SetMode and eGuiMode and eGuiMode.ClickGUI then GUI.SetMode(eGuiMode.ClickGUI) end
        if GUI and GUI.IsOpen and GUI.Toggle and GUI.IsOpen()~=true then GUI.Toggle() end
        if ClickGUI and ClickGUI.SetActiveMenuTab and ClickTab and ClickTab.LuaTab then ClickGUI.SetActiveMenuTab(ClickTab.LuaTab) end
    end)
    if startup.log then startup.log("[Build 435] EVENT_VIEW_NOW | event_id="..tostring(type(eventData)=="table" and eventData.event_id or "").." | tab=EVENTS | gui=open") end
    return true
end

function startup.b419_continue_join(eventData)
    if type(eventData) ~= "table" then return false end
    if eventData.is_self == true then return startup.b419_open_browser_event(eventData) end
    if eventData.joinable ~= true or type(eventData.row) ~= "table" then
        if startup.toast then startup.toast("This event is not currently joinable.",3200) end
        return false
    end
    if startup.browser_runtime_request_join then
        return startup.browser_runtime_request_join(eventData.row) ~= false
    end
    return false
end

function startup.b419_render_event_popup(eventData, developerSpecial)
    if not ImGui or type(eventData) ~= "table" then return false end
    local sw, sh = startup.b419_display_size()
    local width = math.min(690, math.max(560, sw - 80))
    local height = developerSpecial and 600 or 560
    local x = math.max(20, (sw - width) * 0.5)
    local y = math.max(18, (sh - height) * 0.5)
    if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(x, y, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(width, height, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowBgAlpha then ImGui.SetNextWindowBgAlpha(0.985) end
    local flags = startup.first_run_window_flags and startup.first_run_window_flags() or 0
    local colors, vars = startup.b419_push_window_style(developerSpecial==true)
    local id = developerSpecial and "##Startup_B419_Developer_Event" or "##Startup_B419_Event_Details"
    local visible = ImGui.Begin(id, true, flags) == true
    local close = false
    if visible then
        if developerSpecial then
            startup.b419_purple("🚀 STARTUP SPECIAL EVENT")
            if ImGui.Separator then ImGui.Separator() end
            startup.b419_white("Hi, the Developer of Startup is Hosting an Event!")
            startup.b419_dim("A live Startup community event from Public_Urinal is available.")
        else
            startup.b419_purple("🚀 STARTUP EVENT")
            if ImGui.Separator then ImGui.Separator() end
        end
        if ImGui.Spacing then ImGui.Spacing() end
        startup.b419_draw_profile_summary(eventData.profile, developerSpecial and "STARTUP DEVELOPER" or "Event host", false)
        if ImGui.Spacing then ImGui.Spacing() end
        if ImGui.Separator then ImGui.Separator() end
        startup.b419_purple(tostring(eventData.category or "EVENT").." • "..tostring(eventData.activity or "ACTIVITY"))
        startup.b419_white(tostring(eventData.title or "STARTUP EVENT"))
        if startup.subtle_text_wrapped then startup.subtle_text_wrapped(tostring(eventData.description or "Startup Browser event.")) elseif ImGui.TextWrapped then ImGui.TextWrapped(tostring(eventData.description or "Startup Browser event.")) end
        if ImGui.Spacing then ImGui.Spacing() end
        startup.b419_text(1.00,0.24,0.28,1.0,"GTA V Version: "..tostring((startup.b432_event_edition and startup.b432_event_edition(eventData.row,eventData)) or eventData.edition or "Unknown"))
        startup.b419_dim("Starts: "..tostring(eventData.starts or "NOW"))
        startup.b419_dim("Players: "..tostring(eventData.players or 0).." / "..tostring(eventData.max_players or 30))
        startup.b419_dim("Mic: "..tostring(eventData.mic or "MIC OPTIONAL"))
        if tostring(eventData.region or "") ~= "" then startup.b419_dim("Region: "..tostring(eventData.region)) end
        if tostring(eventData.location or "") ~= "" then startup.b419_dim("Location: "..tostring(eventData.location)) end
        if ImGui.Spacing then ImGui.Spacing() end
        if eventData.is_self == true then
            startup.b419_amber("LOCAL HOST PREVIEW • presentation only • no fake attendance or JOIN is created")
        elseif eventData.joinable ~= true then
            startup.b419_amber("This event is currently visible but not joinable yet.")
        else
            startup.b419_green("Ready to continue through Startup Browser's normal JOIN policy.")
        end
        if ImGui.Spacing then ImGui.Spacing() end
        if ImGui.Separator then ImGui.Separator() end
        if startup.b419_button(eventData.is_self == true and "VIEW NOW" or "CONTINUE TO JOIN", "EventPrimary"..tostring(eventData.event_id or ""), "Purple", 210, 36) then
            startup.b419_continue_join(eventData)
            close = true
        end
        if ImGui.SameLine then ImGui.SameLine() end
        if startup.b419_button("NOT NOW", "EventDismiss"..tostring(eventData.event_id or ""), "Gray", 140, 36) then close = true end
    end
    ImGui.End()
    startup.b419_pop_window_style(colors, vars)
    return close
end

function startup.b419_render_present()
    startup.b419_promote_notifications()
    for index, card in ipairs(startup.b419.active or {}) do
        startup.b419_render_notification(card, index)
    end
    if type(startup.b419.developer_event) == "table" then
        if startup.b419_render_event_popup(startup.b419.developer_event, true) then startup.b419.developer_event = nil end
    elseif type(startup.b419.detail_event) == "table" then
        if startup.b419_render_event_popup(startup.b419.detail_event, false) then startup.b419.detail_event = nil end
    end
end

function startup.b419_notify_self_published_event(payload, eventId)
    payload = type(payload) == "table" and payload or {}
    local bb = startup.browser_backend or {}
    local synthetic = {
        event_id=tostring(eventId or ""),
        listing_id=tostring(bb.listing_id or ""),
        edition=tostring(payload.edition or ((startup.b432_current_edition and startup.b432_current_edition()) or "")),
        category=tostring(payload.category or "NORMAL"),
        activity=tostring(payload.activity or "GENERAL SESSION"),
        title=tostring(payload.title or payload.activity or "STARTUP EVENT"),
        description=tostring(payload.description or "Startup Browser event."),
        location_area=tostring(payload.location_area or ""),
        mic_requirement=tostring(payload.mic_requirement or "MIC OPTIONAL"),
        start_mode=tostring(payload.start_mode or "NOW"),
        max_players=tonumber(payload.max_players or 30) or 30,
        players=tonumber(startup.get_session_player_count and startup.get_session_player_count() or 1) or 1,
        profile_uid=tostring(bb.startup_uid or ""),
        host_name=startup.b419_local_name(),
    }
    local localPayload = {}
    for k,v in pairs(payload) do localPayload[k]=v end
    localPayload.event_id=tostring(eventId or "")
    localPayload._b419_self=true
    local eventData = startup.b419_event_from_backend(synthetic, localPayload)
    eventData.is_self=true
    eventData.row.joinable=false
    if tostring(eventId or "") ~= "" then startup.b419.event_seen[tostring(eventId)] = true end
    return startup.b419_notify_event(eventData, "SELF_HOST_TEST")
end

if startup.browser_events_publish and startup.b419.publish_wrapped ~= true then
    startup.b419.publish_wrapped = true
    startup.b419.publish_pre = startup.browser_events_publish
    startup.browser_events_publish = function(payload)
        local before = tostring(startup.browser_events_backend and startup.browser_events_backend.active_event_id or "")
        local copy = {}
        if type(payload) == "table" then for k,v in pairs(payload) do copy[k]=v end end
        local result = startup.b419.publish_pre(payload)
        if result and Script and Script.QueueJob then
            Script.QueueJob(function()
                local deadline = startup.b419_now() + 18000
                local eventId = ""
                while startup.b419_now() < deadline do
                    eventId = tostring(startup.browser_events_backend and startup.browser_events_backend.active_event_id or "")
                    if eventId ~= "" and (before == "" or eventId ~= before) then break end
                    if Script.Yield then Script.Yield(150) end
                end
                if eventId ~= "" then startup.b419_notify_self_published_event(copy, eventId) end
            end)
        end
        return result
    end
end

if EventMgr and eLuaEvent and eLuaEvent.ON_PLAYER_JOIN and startup.b419.join_event_installed ~= true then
    startup.b419.join_event_installed = true
    EventMgr.RegisterHandler(eLuaEvent.ON_PLAYER_JOIN, function(playerId)
