    end)
end

if EventMgr and eLuaEvent and eLuaEvent.ON_PRESENT and startup.b419.present_installed ~= true then
    startup.b419.present_installed = true
    EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
        if startup and startup.b419_render_present then
            local ok, err = pcall(startup.b419_render_present)
            if not ok and startup.support_log_event_quiet then startup.support_log_event_quiet("BUILD419_PRESENT_ERROR", tostring(err or "unknown")) end
        end
