end

if Script and Script.RegisterLooped and startup.b419.loop_installed ~= true then
    startup.b419.loop_installed = true
    Script.RegisterLooped(function()
        if ShouldUnload and ShouldUnload() then
            if Script.Yield then Script.Yield(500) end
            return
        end
        local ok, err = pcall(startup.b419_scan_events)
        if not ok and startup.support_log_event_quiet then startup.support_log_event_quiet("BUILD419_EVENT_SCAN_ERROR", tostring(err or "unknown")) end
        local now = startup.b419_now()
        for key, pending in pairs(startup.b419.pending_join_profiles or {}) do
            if type(pending) ~= "table" or tonumber(pending.expires_ms or 0) <= now then startup.b419.pending_join_profiles[key] = nil end
        end
        if Script.Yield then Script.Yield(500) end
    end)
end

