-- ============================================================================
-- BUILD 420: BROWSER NOTIFICATION INPUT HOTFIX + OWNER END EVENT + VISIBLE SLIDE
-- - Fixes the Host Session Wizard becoming non-responsive after interacting with
--   a B419 Developer/Event popup by suspending ON_PRESENT Browser overlays while
--   the wizard is open and explicitly focusing the wizard on launch.
-- - Adds owner-only END THIS EVENT above RATE THIS EVENT with a 10-second
--   confirmation step, then uses the existing authenticated Event backend paths.
-- - Makes slide-in/out motion easier to see with longer easing durations.
-- - Public_Urinal self-host testing now shows the real sliding Event Card first,
--   then opens the Developer Event popup after the animation completes. Remote
--   users still receive the Developer popup immediately as originally designed.
-- ============================================================================
startup.b420 = startup.b420 or {
    end_busy = {},
    b419_present_wrapped = false,
    b419_notify_wrapped = false,
}

function startup.b420_now()
    if startup.b419_now then return tonumber(startup.b419_now()) or 0 end
    if startup.now then return tonumber(startup.now()) or 0 end
    return math.floor((os.clock and os.clock() or 0) * 1000)
end

function startup.b420_prepare_host_wizard()
    local b = startup.b419
    if type(b) == "table" then
        -- A Browser overlay must never sit above or compete for input with the
        -- dedicated Host Session Wizard. Cards remain queued/aged normally.
        b.developer_event = nil
        b.detail_event = nil
        b.developer_event_pending = nil
        b.developer_event_due_ms = 0
        b.overlay_suspended_for_wizard = true
    end
    return true
end

function startup.b420_drop_event_overlays(eventId)
    eventId=tostring(eventId or "")
    if eventId=="" or type(startup.b419)~="table" then return end
    local b=startup.b419
    local function same_event(ev)
        return type(ev)=="table" and tostring(ev.event_id or "")==eventId
    end
    if same_event(b.developer_event) then b.developer_event=nil end
    if same_event(b.detail_event) then b.detail_event=nil end
    if same_event(b.developer_event_pending) then b.developer_event_pending=nil; b.developer_event_due_ms=0 end
    local function filter(list)
        if type(list)~="table" then return end
        for i=#list,1,-1 do
            local card=list[i]
            if type(card)=="table" and same_event(card.event) then table.remove(list,i) end
        end
    end
    filter(b.active); filter(b.queue)
end

function startup.b420_end_event(eventId)
    eventId=tostring(eventId or "")
    if eventId=="" then return false end
    startup.b420.end_busy=startup.b420.end_busy or {}
    if startup.b420.end_busy[eventId]==true then
        if startup.toast then startup.toast("Startup is already ending this Event.",2600) end
        return false
    end
    local eb=startup.browser_events_backend
    local bb=startup.browser_backend
    if type(eb)~="table" or type(bb)~="table" or tostring(bb.token or "")=="" then
        if startup.toast then startup.toast("Startup Browser is not authenticated yet.",3200) end
        return false
    end
    if not (Script and Script.QueueJob) then
        if startup.toast then startup.toast("Could not end the Event: job queue unavailable.",3500) end
        return false
    end

    startup.b420.end_busy[eventId]=true
    if startup.toast then startup.toast("Ending Startup Event...",2200) end
    startup.b420_drop_event_overlays(eventId)

    Script.QueueJob(function()
        local ok=false
        local err=""
        if startup.browser_events_post then
            -- Use the same authenticated endpoints as the existing unpublish wrapper,
            -- but do it in this already-queued job so we never nest QueueJob calls.
            local callOk,a,b=pcall(startup.browser_events_post,"event-unpublish.php",{event_id=eventId,reason="HOST_ENDED_MANUALLY"})
            if callOk then ok=a==true; err=tostring(b or "") else ok=false; err=tostring(a or "EVENT_UNPUBLISH_FAILED") end
            if ok then
                pcall(startup.browser_events_post,"event-state.php",{event_id=eventId,action="CANCEL",reason="HOST_ENDED_MANUALLY"})
            end
        else
            err="EVENT_TRANSPORT_UNAVAILABLE"
        end

        if ok then
            if tostring(eb.active_event_id or "")==eventId then eb.active_event_id="" end
            local function remove_event(rows)
                if type(rows)~="table" then return end
                for i=#rows,1,-1 do
                    if type(rows[i])=="table" and tostring(rows[i].event_id or "")==eventId then table.remove(rows,i) end
                end
            end
            remove_event(eb.events)
            remove_event(eb.my_events)
            eb.next_fetch_ms=0
            eb.next_private_fetch_ms=0
            if startup.browser_social_backend then
                startup.browser_social_backend.next_feed_ms=0
                startup.browser_social_backend.next_feedback_poll_ms=0
            end
            local ui=startup.browser_activity_ui_state or startup.activity_catalog_ui
            if type(ui)=="table" then
                ui.host_published=false
                ui.host_publish_started_ms=0
                ui.end_event_confirm_id=""
                ui.end_event_confirm_until_ms=0
                if tostring(ui.events_selected_key or "")=="event_"..eventId then ui.events_selected_key="" end
            end
            startup.browser_activity_publication=nil
            if startup.toast then startup.toast("Event ended and removed from Startup Browser.",3500) end
            if startup.support_log_event_quiet then startup.support_log_event_quiet("BUILD420_EVENT_ENDED","event_id="..eventId.." reason=HOST_ENDED_MANUALLY") end
        else
            if startup.toast then startup.toast("Event could not be ended: "..tostring(err~="" and err or "unknown error"),4500) end
            if startup.support_log_event_quiet then startup.support_log_event_quiet("BUILD420_EVENT_END_FAILED","event_id="..eventId.." error="..tostring(err)) end
        end
        startup.b420.end_busy[eventId]=nil
    end)
    return true
end

-- Slow the travel enough that the user can clearly see the card come from the
-- right edge and return there. Hold time remains long enough to read/click it.
if type(startup.b419)=="table" then
    startup.b419.enter_ms=800
    startup.b419.hold_ms=5000
    startup.b419.exit_ms=800
end

-- Public_Urinal's own client is our test exception: show the sliding Event Card
-- first, then the full Developer popup. Other clients still get the immediate
-- Developer popup exactly as specified for real announcements.
if startup.b419_notify_event and startup.b420.b419_notify_wrapped~=true then
    startup.b420.b419_notify_wrapped=true
    startup.b420.b419_notify_event_pre=startup.b419_notify_event
    startup.b419_notify_event=function(eventData,source)
        if type(eventData)=="table" and eventData.is_developer==true and eventData.is_self==true then
            local eventId=tostring(eventData.event_id or "")
            local enterMs=900
            local holdMs=5000
            local exitMs=900
            startup.b419.developer_event=nil
            startup.b419.detail_event=nil
            startup.b419.developer_event_pending=eventData
            startup.b419.developer_event_due_ms=startup.b420_now()+enterMs+holdMs+exitMs+250
            local pushed=startup.b419_push_notification("event",{
                event=eventData,
                title=eventData.title,
                host=eventData.host,
                clickable=true,
                developer_special=true,
                message="Developer Event",
                enter_ms=enterMs,
                hold_ms=holdMs,
                exit_ms=exitMs,
            },"event:"..eventId)
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("BUILD420_DEVELOPER_SELF_SLIDE_PREVIEW","event_id="..eventId.." source="..tostring(source or "").." enter_ms="..enterMs.." hold_ms="..holdMs.." exit_ms="..exitMs)
            end
            return pushed
        end
        return startup.b420.b419_notify_event_pre(eventData,source)
    end
end

-- B419's ON_PRESENT callback resolves this function dynamically, so wrapping it
-- here fixes the old handler without registering another Present handler.
if startup.b419_render_present and startup.b420.b419_present_wrapped~=true then
    startup.b420.b419_present_wrapped=true
    startup.b420.b419_render_present_pre=startup.b419_render_present
    startup.b419_render_present=function()
        local ui=startup.browser_activity_ui_state or startup.activity_catalog_ui
        if type(ui)=="table" and ui.host_wizard_open==true then
            if type(startup.b419)=="table" then startup.b419.overlay_suspended_for_wizard=true end
            return
        end
        if type(startup.b419)=="table" then
            startup.b419.overlay_suspended_for_wizard=false
            if type(startup.b419.developer_event_pending)=="table"
                and tonumber(startup.b419.developer_event_due_ms or 0)>0
                and startup.b420_now()>=tonumber(startup.b419.developer_event_due_ms or 0)
                and startup.b419.developer_event==nil
                and startup.b419.detail_event==nil then
                startup.b419.developer_event=startup.b419.developer_event_pending
                startup.b419.developer_event_pending=nil
                startup.b419.developer_event_due_ms=0
            end
        end
        return startup.b420.b419_render_present_pre()
    end
end

