-- ============================================================================
-- BUILD 422: SMART EXPANDED-MINIMAP HUD + TRIGGER BOT PERSISTENCE
-- - Session HUD / Activity Feed X automatically moves right while GTA's expanded
--   minimap is active, then returns to the user's exact saved position afterward.
-- - Build 423 compatibility: the unsupported IS_BIGMAP_ACTIVE native probe is
--   disabled. Three Z presses are the authoritative expanded-map signal.
-- - Three Z presses within four seconds arm a 10-second HUD-shift window.
-- - Trigger Bot ON/OFF now persists in Startup config; reaction delay defaults to
--   20 ms and is persisted too. Region Type HUD remains ON by default while still
--   respecting an explicit user OFF choice.
-- ============================================================================
startup.b422 = startup.b422 or {
    z_down = false,
    z_press_count = 0,
    z_window_started_ms = 0,
    fallback_until_ms = 0,
    native_was_active = false,
    hud_x_wrapped = false,
}

function startup.b422_now()
    return startup.now and tonumber(startup.now()) or math.floor((os.clock and os.clock() or 0) * 1000)
end

function startup.b422_bigmap_native_active()
    -- Build 423 compatibility fix: DO NOT invoke 0xFFF65C63 here.
    -- The supplied Cherax native table documents IS_BIGMAP_ACTIVE but this
    -- Cherax runtime does not expose a handler for it. Invoking the hash causes
    -- a visible "Failed to find native's handler" error even inside pcall.
    return false
end

function startup.b422_minimap_expanded()
    -- Build 423: stable, native-free detection. Three Z presses arm this
    -- 10-second window; no unsupported native is polled at render time.
    local now=startup.b422_now()
    return now < (tonumber(startup.b422.fallback_until_ms or 0) or 0)
end

function startup.b422_minimap_key_tick()
    local B=startup.b422
    if not (Utils and Utils.IsKeyPressed) then return end
    local ok, down=direct_call(Utils.IsKeyPressed,0x5A) -- Z
    down=ok and down==true
    local now=startup.b422_now()
    if down and B.z_down~=true then
        if (tonumber(B.z_window_started_ms or 0) or 0)<=0 or now-(tonumber(B.z_window_started_ms or 0) or 0)>4000 then
            B.z_press_count=0
            B.z_window_started_ms=now
        end
        B.z_press_count=(tonumber(B.z_press_count or 0) or 0)+1
        if B.z_press_count>=3 then
            B.z_press_count=0
            B.z_window_started_ms=0
            -- Build 423 authoritative trigger. No unsupported big-map native is called.
            -- Repeating the three-press gesture refreshes the full 10-second window.
            B.fallback_until_ms=now+10000
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("BUILD422_MINIMAP_Z3_FALLBACK","duration_ms=10000")
            end
        end
    end
    B.z_down=down
    if B.z_press_count>0 and now-(tonumber(B.z_window_started_ms or now) or now)>4000 then
        B.z_press_count=0
        B.z_window_started_ms=0
    end
end

-- Move the entire Startup bottom-left HUD family together so Connected Players,
-- Region Type, NAT, Host lines, and auto-anchored Activity Feed all clear the
-- wider GTA Online big minimap. The saved X values themselves are never changed.
if startup.get_effective_hud_x and startup.b422.hud_x_wrapped~=true then
    startup.b422.hud_x_wrapped=true
    startup.b422_get_effective_hud_x_pre=startup.get_effective_hud_x
    startup.get_effective_hud_x=function(x)
        local base=startup.b422_get_effective_hud_x_pre(x)
        if startup.b422_minimap_expanded() then
            local scale=startup.get_hud_horizontal_scale and startup.get_hud_horizontal_scale() or 1.0
            local shifted=base+(0.165*scale)
            return startup.clamp_float and startup.clamp_float(shifted,0.005,0.92) or math.max(0.005,math.min(0.92,shifted))
        end
        return base
    end
end

-- Region Type HUD is already a default-ON setting in v1.0.18. Reassert the
-- default only for users who have never explicitly configured it; manual OFF wins.
if startup.s.advertiseRegionHudUserConfigured~=true then
    startup.s.showAdvertiseRegionHud=true
    if startup.set_feature_bool_silently and startup.h and startup.h.ShowAdvertiseRegionHud then
        direct_call(startup.set_feature_bool_silently,startup.h.ShowAdvertiseRegionHud,true)
    end
end

-- Sync persisted Trigger Bot values into the already-created B392 controls/runtime.
if startup.b392 and startup.b392.trigger then
    startup.b392.trigger.reactionDelayMs=startup.clamp_int(tonumber(startup.s.triggerBotReactionDelayMs or 20) or 20,0,500)
    startup.b392.trigger.enabled=startup.s.triggerBotEnabled==true and tonumber(startup.b392.trigger.aimPointer or 0)~=0
    if startup.s.triggerBotEnabled==true and tonumber(startup.b392.trigger.aimPointer or 0)==0 then
        startup.s.triggerBotEnabled=false
        startup.b392.trigger.enabled=false
    end
    if startup.set_feature_bool_silently and startup.h and startup.h.EssentialsTriggerBot then
        direct_call(startup.set_feature_bool_silently,startup.h.EssentialsTriggerBot,startup.b392.trigger.enabled==true)
    end
    if startup.set_feature_int_silently and startup.h and startup.h.EssentialsTriggerReaction then
        direct_call(startup.set_feature_int_silently,startup.h.EssentialsTriggerReaction,startup.b392.trigger.reactionDelayMs)
    end
end

if Script and Script.RegisterLooped and startup.b422.loop_installed~=true then
    startup.b422.loop_installed=true
    Script.RegisterLooped(function()
        if ShouldUnload and ShouldUnload() then
            if Script.Yield then Script.Yield(100) end
            return
        end
        direct_call(startup.b422_minimap_key_tick)
        if Script.Yield then Script.Yield(25) end
    end)
end

