-- ============================================================================
-- BUILD 423: MINIMAP NATIVE-HANDLER COMPATIBILITY FIX
-- - Removes every runtime call to undocumented/unavailable IS_BIGMAP_ACTIVE
--   hash 0xFFF65C63 from Startup's minimap-shift path.
-- - Three Z presses within 4 seconds are now the authoritative trigger.
-- - HUD shift remains active for exactly 10 seconds from the third press.
-- - Repeating the gesture refreshes the 10-second window.
-- - Preserves B422 Trigger Bot persistence/default 20 ms and Region HUD default ON.
-- ============================================================================
startup.version="v1.0.18"
startup.console_version="v1.0.18"
startup.build_number="2026.09.30.423"
startup.build_date="2026-09-30"
startup.build_label="B423 v1.0.18 Alpha - Minimap Native Handler Compatibility Fix"
startup.changelog_version="2026.09.30.423"
startup.whats_new_version="2026.09.30.423"

if startup.log then
    startup.log("[Build 423] Minimap compatibility fix ready: removed unsupported 0xFFF65C63 native probe; 3x Z is authoritative for a 10-second HUD shift; B422 Trigger Bot + Region HUD behavior preserved.")
end
if startup.support_log_event_quiet then
    startup.support_log_event_quiet(
        "BUILD423_MINIMAP_NATIVE_HANDLER_FIX_READY",
        "is_bigmap_active_native=false hash_fff65c63_disabled=true z_press_count=3 z_window_ms=4000 shift_duration_ms=10000 trigger_persistent=true trigger_default_ms=20 region_hud_default_on=true"
    )
end


-- ============================================================================
-- BUILD 424: EXPANDED MINIMAP HUD TUNING + SMOOTH GROUP SHIFT
-- - Keeps Build 423's native-free 3x-Z detection.
-- - Moves the complete bottom-left Startup HUD family as one group using the same
--   effective-X transform, including Session HUD lines and auto-positioned Activity Feed.
-- - Adds a saved Expanded Minimap X Offset (default 0.165), configurable hold time
--   (default 10 seconds), Auto Shift toggle, manual Preview, and Restore Now controls.
-- - Smoothly eases into and out of expanded-map placement without changing any of
--   the user's saved normal HUD coordinates.
-- ============================================================================
startup.b424 = startup.b424 or {
    progress = 0.0,
    last_tick_ms = 0,
    transition_ms = 300,
    preview_until_ms = 0,
    controls_installed = false,
    render_wrapped = false,
}

startup.s.expandedMinimapHudEnabled = startup.s.expandedMinimapHudEnabled ~= false
startup.s.expandedMinimapHudOffsetX = startup.clamp_float(tonumber(startup.s.expandedMinimapHudOffsetX or 0.165) or 0.165, 0.050, 0.300)
startup.s.expandedMinimapHudHoldSeconds = startup.clamp_int(tonumber(startup.s.expandedMinimapHudHoldSeconds or 10) or 10, 5, 20)

function startup.b424_now()
    return startup.now and tonumber(startup.now()) or math.floor((os.clock and os.clock() or 0) * 1000)
end

function startup.b424_active()
    local now=startup.b424_now()
    if now < (tonumber(startup.b424.preview_until_ms or 0) or 0) then return true end
    if startup.s.expandedMinimapHudEnabled == false then return false end
    local until_ms = startup.b422 and tonumber(startup.b422.fallback_until_ms or 0) or 0
    return now < until_ms
end

function startup.b424_remaining_ms()
    local now=startup.b424_now()
    local normal_until = startup.b422 and tonumber(startup.b422.fallback_until_ms or 0) or 0
    local preview_until = tonumber(startup.b424.preview_until_ms or 0) or 0
    return math.max(0, math.max(normal_until, preview_until) - now)
end

function startup.b424_ease(v)
    v = math.max(0.0, math.min(1.0, tonumber(v or 0.0) or 0.0))
    return v * v * (3.0 - (2.0 * v))
end

function startup.b424_tick()
    local B = startup.b424
    local now = startup.b424_now()
    local last = tonumber(B.last_tick_ms or 0) or 0
    if last <= 0 then last = now end
    local dt = math.max(0, math.min(100, now - last))
    B.last_tick_ms = now

    local target = startup.b424_active() and 1.0 or 0.0
    local duration = math.max(100, tonumber(B.transition_ms or 300) or 300)
    local step = dt / duration
    local p = tonumber(B.progress or 0.0) or 0.0
    if target > p then p = math.min(target, p + step)
    elseif target < p then p = math.max(target, p - step) end
    B.progress = p
end

-- Replace B423's fixed 10-second trigger with the saved B424 hold setting.
-- This remains completely native-free.
function startup.b422_minimap_key_tick()
    local B=startup.b422
    if not (Utils and Utils.IsKeyPressed) then return end
    local ok,down=direct_call(Utils.IsKeyPressed,0x5A) -- Z
    down=ok and down==true
    local now=startup.b422_now()
    if down and B.z_down~=true then
        if (tonumber(B.z_window_started_ms or 0) or 0)<=0 or now-(tonumber(B.z_window_started_ms or 0) or 0)>4000 then
            B.z_press_count=0
            B.z_window_started_ms=now
        end
        B.z_press_count=(tonumber(B.z_press_count or 0) or 0)+1
        if B.z_press_count>=3 then
            B.z_press_count=0
            B.z_window_started_ms=0
            local hold_ms=(startup.clamp_int(tonumber(startup.s.expandedMinimapHudHoldSeconds or 10) or 10,5,20))*1000
            B.fallback_until_ms=now+hold_ms
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("BUILD424_MINIMAP_Z3_ACTIVE","duration_ms="..tostring(hold_ms).." offset_x="..string.format("%.3f",tonumber(startup.s.expandedMinimapHudOffsetX or 0.165) or 0.165))
            end
        end
    end
    B.z_down=down
    if B.z_press_count>0 and now-(tonumber(B.z_window_started_ms or now) or now)>4000 then
        B.z_press_count=0
        B.z_window_started_ms=0
    end
end

-- B422 saved the pre-shift renderer for us. Use that original base so B424 becomes
-- the single final X resolver instead of stacking a second shift on top of B422.
startup.b424_get_effective_hud_x_base = startup.b422_get_effective_hud_x_pre or startup.get_effective_hud_x
startup.get_effective_hud_x=function(x)
    local base=startup.b424_get_effective_hud_x_base(x)
    local progress=startup.b424_ease(startup.b424 and startup.b424.progress or 0.0)
    if progress<=0.0001 then return base end
    local scale=startup.get_hud_horizontal_scale and startup.get_hud_horizontal_scale() or 1.0
    local offset=startup.clamp_float(tonumber(startup.s.expandedMinimapHudOffsetX or 0.165) or 0.165,0.050,0.300)
    local shifted=base+(offset*scale*progress)
    return startup.clamp_float and startup.clamp_float(shifted,0.005,0.92) or math.max(0.005,math.min(0.92,shifted))
end

if startup.b424.controls_installed~=true then
    startup.b424.controls_installed=true
    startup.add_toggle("ExpandedMinimapHudAutoShift","Expanded Minimap HUD Auto Shift","After three Z presses within four seconds, smoothly moves Startup's bottom-left HUD clear of the enlarged minimap, then restores the exact normal position automatically.",function(f)
        startup.s.expandedMinimapHudEnabled=f:IsToggled()
        if startup.s.expandedMinimapHudEnabled~=true and startup.b422 then startup.b422.fallback_until_ms=0 end
        if startup.s.initialized and startup.save_config then startup.save_config(false) end
    end,startup.s.expandedMinimapHudEnabled~=false)

    startup.add_float_slider("ExpandedMinimapHudOffsetX","Expanded Minimap X Offset","How far right Startup moves the Session HUD and Activity Feed while expanded-minimap mode is active. Default: 0.165.",startup.s.expandedMinimapHudOffsetX or 0.165,0.050,0.300,0.005,"%.3f",function(value)
        startup.s.expandedMinimapHudOffsetX=startup.clamp_float(value,0.050,0.300)
        if startup.s.initialized and startup.save_config then startup.save_config(false) end
    end)

    startup.add_int_slider("ExpandedMinimapHudHoldSeconds","Expanded Minimap Hold Time","Seconds Startup keeps the shifted HUD position after the third Z press. Default: 10 seconds.",startup.s.expandedMinimapHudHoldSeconds or 10,5,20,1,function(value)
        startup.s.expandedMinimapHudHoldSeconds=startup.clamp_int(value,5,20)
        if startup.s.initialized and startup.save_config then startup.save_config(false) end
    end)

    startup.add_button("ExpandedMinimapHudPreview","PREVIEW EXPANDED MINIMAP HUD","Immediately previews the expanded-minimap HUD placement using the current saved offset and hold time.",function()
        local hold_ms=startup.clamp_int(tonumber(startup.s.expandedMinimapHudHoldSeconds or 10) or 10,5,20)*1000
        startup.b424.preview_until_ms=startup.b424_now()+hold_ms
        if startup.toast then startup.toast("Expanded Minimap HUD preview started.",1800) end
    end)

    startup.add_button("ExpandedMinimapHudRestore","RESTORE HUD NOW","Immediately returns Startup's HUD to the normal saved placement.",function()
        if startup.b422 then startup.b422.fallback_until_ms=0 end
        startup.b424.preview_until_ms=0
        startup.b424.progress=0.0
        if startup.toast then startup.toast("Startup HUD restored to normal placement.",1600) end
    end)
end

-- Add a dedicated tuning panel to the normal Startup HUD tab without disturbing
-- the existing three-column Session HUD / Activity configuration.
if startup.render_hud_config and startup.b424.render_wrapped~=true then
    startup.b424.render_wrapped=true
    startup.b424_render_hud_config_pre=startup.render_hud_config
    startup.render_hud_config=function()
        startup.b424_render_hud_config_pre()
        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Expanded Minimap HUD") then
            startup.section_title("Expanded Minimap HUD")
            startup.subtle_text("Native-free: press Z three times within 4 seconds, or use Preview below.")
            startup.render_feature_guarded_325(startup.h.ExpandedMinimapHudAutoShift)
            startup.render_feature_guarded_325(startup.h.ExpandedMinimapHudOffsetX)
            startup.render_feature_guarded_325(startup.h.ExpandedMinimapHudHoldSeconds)
            ImGui.Text("")
            startup.render_feature_guarded_325(startup.h.ExpandedMinimapHudPreview)
            ImGui.SameLine()
            startup.render_feature_guarded_325(startup.h.ExpandedMinimapHudRestore)
            local remaining=startup.b424_remaining_ms()
            if startup.b424_active() then
                startup.subtle_text("Status: ACTIVE | "..string.format("%.1f",remaining/1000).."s remaining | X +"..string.format("%.3f",tonumber(startup.s.expandedMinimapHudOffsetX or 0.165) or 0.165))
            else
                startup.subtle_text("Status: Normal placement | waiting for 3x Z")
            end
            ClickGUI.EndCustomChildWindow()
        end
    end
end

if Script and Script.RegisterLooped and startup.b424.loop_installed~=true then
    startup.b424.loop_installed=true
    Script.RegisterLooped(function()
        if ShouldUnload and ShouldUnload() then
            if Script.Yield then Script.Yield(100) end
            return
        end
        direct_call(startup.b424_tick)
        if Script.Yield then Script.Yield(25) end
    end)
end

startup.version="v1.0.18"
startup.console_version="v1.0.18"
startup.build_number="2026.09.30.424"
startup.build_date="2026-09-30"
startup.build_label="B424 v1.0.18 Alpha - Expanded Minimap HUD Tuning"
startup.changelog_version="2026.09.30.424"
startup.whats_new_version="2026.09.30.424"

if startup.log then
    startup.log("[Build 424] Expanded Minimap HUD tuning ready: smooth grouped HUD shift, saved X offset, configurable hold time, 3x-Z trigger, Preview + Restore controls; no unsupported big-map native calls.")
end
if startup.support_log_event_quiet then
    startup.support_log_event_quiet(
        "BUILD424_EXPANDED_MINIMAP_HUD_TUNING_READY",
        "native_free=true z_press_count=3 z_window_ms=4000 offset_default=0.165 offset_saved=true hold_default_s=10 hold_saved=true transition_ms=300 preview=true restore=true grouped_hud_shift=true"
    )
end

-- ============================================================================
-- BUILD 425: PLAYER-COUNT-AWARE MANUAL MINIMAP HUD TOGGLE
-- - Replaces B424's timed 3x-Z guess with the observed GTA Z-cycle:
--     <=16 connected players: 2x Z activates expanded-map HUD placement.
--     >=17 connected players: 3x Z activates expanded-map HUD placement.
-- - Once active, the very next Z press restores the normal HUD placement.
-- - Expanded placement remains active until that next Z press; no 10-second timer.
-- - Pulls the expanded HUD closer to the minimap (new default X offset +0.090).
-- - Preserves smooth group movement, manual Preview/Restore controls, B423's
--   native-free safety, Trigger Bot persistence, and Region HUD defaults.
-- ============================================================================
startup.b425 = startup.b425 or {
    active = false,
    required_presses = 0,
    sequence_players = 0,
    controls_installed = false,
    render_wrapped = false,
}

startup.expanded_minimap_mode_version = "b425_player_count_manual_toggle_v1"

-- One-time migration from B424's stock +0.165 offset. Preserve any value the user
-- already tuned away from that stock default.
function startup.b425_apply_offset_migration()
    local old_version=tostring(startup.s.expandedMinimapHudModeVersion or "")
    if old_version~=startup.expanded_minimap_mode_version then
        local current=tonumber(startup.s.expandedMinimapHudOffsetX or 0.165) or 0.165
        if math.abs(current-0.165)<=0.0005 then current=0.090 end
        startup.s.expandedMinimapHudOffsetX=startup.clamp_float(current,0.040,0.200)
        startup.s.expandedMinimapHudModeVersion=startup.expanded_minimap_mode_version
        if startup.s.initialized and startup.save_config then direct_call(startup.save_config,false) end
    else
        startup.s.expandedMinimapHudOffsetX=startup.clamp_float(tonumber(startup.s.expandedMinimapHudOffsetX or 0.090) or 0.090,0.040,0.200)
    end
end
startup.b425_apply_offset_migration()
startup.b425_apply_offset_migration=nil

startup.b424.transition_ms=220

function startup.b425_player_count()
    if startup.get_session_player_count then
        local ok,n=direct_call(startup.get_session_player_count)
        if ok then return math.max(0,math.floor(tonumber(n or 0) or 0)) end
    end
    return 0
end

function startup.b425_required_presses(players)
    players=math.max(0,math.floor(tonumber(players or 0) or 0))
    return players<=16 and 2 or 3
end

function startup.b425_reset_sequence()
    if startup.b422 then
        startup.b422.z_press_count=0
        startup.b422.z_window_started_ms=0
        startup.b422.fallback_until_ms=0 -- legacy B423/B424 timer stays retired.
    end
    startup.b425.required_presses=0
    startup.b425.sequence_players=0
end

function startup.b425_set_active(value,reason)
    startup.b425.active=value==true
    startup.b425_reset_sequence()
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet(
            startup.b425.active and "BUILD425_MINIMAP_MANUAL_ACTIVE" or "BUILD425_MINIMAP_MANUAL_RESTORED",
            "reason="..tostring(reason or "").." offset_x="..string.format("%.3f",tonumber(startup.s.expandedMinimapHudOffsetX or 0.090) or 0.090)
        )
    end
end

-- B424's smooth renderer asks this for the target state. Manual expanded state is
-- now indefinite; only Preview remains timed for easy visual tuning.
function startup.b424_active()
    local now=startup.b424_now()
    if now < (tonumber(startup.b424.preview_until_ms or 0) or 0) then return true end
    if startup.s.expandedMinimapHudEnabled==false then return false end
    return startup.b425 and startup.b425.active==true
end

function startup.b424_remaining_ms()
    local now=startup.b424_now()
    local preview_until=tonumber(startup.b424.preview_until_ms or 0) or 0
    return math.max(0,preview_until-now)
end

-- Final B425 Z-state machine. B422's existing loop dynamically calls this function,
-- so no second keyboard polling loop is installed.
function startup.b422_minimap_key_tick()
    local B=startup.b422
    if not (Utils and Utils.IsKeyPressed) then return end
    local ok,down=direct_call(Utils.IsKeyPressed,0x5A) -- Z
    down=ok and down==true
    local now=startup.b422_now()

    if down and B.z_down~=true then
        -- When the expanded HUD is already active, the next Z is the GTA minimap
        -- restore press. Mirror it immediately instead of starting a new sequence.
        if startup.b425.active==true then
            startup.b425_set_active(false,"next Z after expanded minimap")
        else
            local started=tonumber(B.z_window_started_ms or 0) or 0
            if started<=0 or now-started>4000 then
                B.z_press_count=0
                B.z_window_started_ms=now
                local players=startup.b425_player_count()
                startup.b425.sequence_players=players
                startup.b425.required_presses=startup.b425_required_presses(players)
            end

            B.z_press_count=(tonumber(B.z_press_count or 0) or 0)+1
            local required=tonumber(startup.b425.required_presses or 0) or 0
            if required<=0 then
                local players=startup.b425_player_count()
                startup.b425.sequence_players=players
                required=startup.b425_required_presses(players)
                startup.b425.required_presses=required
            end

            if B.z_press_count>=required then
                local players=startup.b425.sequence_players
                startup.b425_set_active(true,tostring(required).."x Z at "..tostring(players).." players")
            end
        end
    end

    B.z_down=down
    if startup.b425.active~=true and B.z_press_count>0 then
        local started=tonumber(B.z_window_started_ms or now) or now
        if now-started>4000 then startup.b425_reset_sequence() end
    end
end

-- Final X resolver: same smooth group movement as B424, but with the closer +0.090
-- production default and a tighter tuning range.
startup.get_effective_hud_x=function(x)
    local base=startup.b424_get_effective_hud_x_base(x)
    local progress=startup.b424_ease(startup.b424 and startup.b424.progress or 0.0)
    if progress<=0.0001 then return base end
    local scale=startup.get_hud_horizontal_scale and startup.get_hud_horizontal_scale() or 1.0
    local offset=startup.clamp_float(tonumber(startup.s.expandedMinimapHudOffsetX or 0.090) or 0.090,0.040,0.200)
    local shifted=base+(offset*scale*progress)
    return startup.clamp_float and startup.clamp_float(shifted,0.005,0.92) or math.max(0.005,math.min(0.92,shifted))
end

if startup.b425.controls_installed~=true then
    startup.b425.controls_installed=true

    startup.add_toggle("ExpandedMinimapHudAutoShift425","Expanded Minimap HUD Auto Shift","Matches GTA's Z-cycle without unsupported natives. 16 players or fewer: double Z. 17 players or more: triple Z. Once active, the next Z restores the HUD.",function(f)
        startup.s.expandedMinimapHudEnabled=f:IsToggled()
        if startup.s.expandedMinimapHudEnabled~=true then
            startup.b425_set_active(false,"feature disabled")
            startup.b424.preview_until_ms=0
        end
        if startup.s.initialized and startup.save_config then startup.save_config(false) end
    end,startup.s.expandedMinimapHudEnabled~=false)

    startup.add_float_slider("ExpandedMinimapHudOffsetX425","Expanded Minimap X Offset","Temporary right shift while the large minimap is open. New default: 0.090, tuned closer to the minimap edge.",startup.s.expandedMinimapHudOffsetX or 0.090,0.040,0.200,0.005,"%.3f",function(value)
        startup.s.expandedMinimapHudOffsetX=startup.clamp_float(value,0.040,0.200)
        if startup.s.initialized and startup.save_config then startup.save_config(false) end
    end)

    startup.add_button("ExpandedMinimapHudPreview425","PREVIEW EXPANDED MINIMAP HUD","Shows the expanded-map HUD placement for 8 seconds without changing the Z-toggle state.",function()
        startup.b424.preview_until_ms=startup.b424_now()+8000
        if startup.toast then startup.toast("Expanded Minimap HUD preview started for 8 seconds.",1800) end
    end)

    startup.add_button("ExpandedMinimapHudRestore425","RESTORE HUD NOW","Immediately clears Preview and returns Startup's HUD to its normal saved placement.",function()
        startup.b424.preview_until_ms=0
        startup.b425_set_active(false,"Restore HUD Now")
        startup.b424.progress=0.0
        if startup.toast then startup.toast("Startup HUD restored to normal placement.",1600) end
    end)
end

-- Replace B424's tuning panel so the obsolete 10-second Hold Time control is not
-- shown anymore. The old feature object remains registered only for compatibility.
if startup.render_hud_config and startup.b425.render_wrapped~=true then
    startup.b425.render_wrapped=true
    startup.b425_render_hud_config_base=startup.b424_render_hud_config_pre or startup.render_hud_config
    startup.render_hud_config=function()
        startup.b425_render_hud_config_base()
        if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Expanded Minimap HUD") then
            startup.section_title("Expanded Minimap HUD")
            local players=startup.b425_player_count()
            local required=startup.b425_required_presses(players)
            startup.subtle_text("Manual GTA-aware mode: "..tostring(players).." players = "..tostring(required).."x Z to expand. Next Z restores.")
            startup.render_feature_guarded_325(startup.h.ExpandedMinimapHudAutoShift425)
            startup.render_feature_guarded_325(startup.h.ExpandedMinimapHudOffsetX425)
            ImGui.Text("")
            startup.render_feature_guarded_325(startup.h.ExpandedMinimapHudPreview425)
            ImGui.SameLine()
            startup.render_feature_guarded_325(startup.h.ExpandedMinimapHudRestore425)

            if startup.b425.active==true then
                startup.subtle_text("Status: EXPANDED | Next Z restores | X +"..string.format("%.3f",tonumber(startup.s.expandedMinimapHudOffsetX or 0.090) or 0.090))
            elseif startup.b424_now() < (tonumber(startup.b424.preview_until_ms or 0) or 0) then
                startup.subtle_text("Status: PREVIEW | X +"..string.format("%.3f",tonumber(startup.s.expandedMinimapHudOffsetX or 0.090) or 0.090))
            else
                local count=tonumber(startup.b422 and startup.b422.z_press_count or 0) or 0
                if count>0 then
                    startup.subtle_text("Status: Z sequence "..tostring(count).." / "..tostring(startup.b425.required_presses or required))
                else
                    startup.subtle_text("Status: Normal placement | waiting for "..tostring(required).."x Z")
                end
            end
            ClickGUI.EndCustomChildWindow()
        end
    end
end

