-- ============================================================================
-- BUILD 426: MAIN-CHUNK LOCAL LIMIT REPAIR + ESSENTIALS DEATH LOG
-- - B425's offset migration is executed inside a function so its locals no longer
--   consume the already-full Startup main-chunk local-variable budget.
-- - Adds an Essentials Death Log toggle, ON by default and persisted in config.
-- - Detects the local player's death, resolves the killer when available, inspects
--   the reported weapon/cause and last damage bone, then produces human-readable
--   messages such as "XYZ shot you in the head" or "XYZ killed you with an explosion."
-- - Uses only Cherax-exposed natives from the supplied native table. No unsupported
--   IS_BIGMAP_ACTIVE/native polling is reintroduced.
-- ============================================================================
function startup.install_build426_death_log()
    startup.b426=startup.b426 or {}
    local D=startup.b426
    D.enabled=startup.s.deathLogEnabled~=false
    D.last_message=tostring(D.last_message or "No deaths recorded this session.")
    D.history=D.history or {}
    D.was_dead=D.was_dead
    D.last_ped=tonumber(D.last_ped or 0) or 0
    D.pending_capture_ms=tonumber(D.pending_capture_ms or 0) or 0
    D.weapon_ptr=tonumber(D.weapon_ptr or 0) or 0
    D.bone_ptr=tonumber(D.bone_ptr or 0) or 0
    D.render_wrapped=D.render_wrapped==true
    D.loop_installed=D.loop_installed==true

    if startup.s.deathLogEnabled==nil then startup.s.deathLogEnabled=true end
    D.enabled=startup.s.deathLogEnabled~=false

    local H={
        PLAYER_ID=0x4F8644AF03D0E0D6,
        PLAYER_PED_ID=0xD80958FC74E988A6,
        IS_PED_DEAD_OR_DYING=0x3317DEDB88C95038,
        GET_PED_SOURCE_OF_DEATH=0x93C8B64DEB84728C,
        GET_PED_CAUSE_OF_DEATH=0x16FFE42AB2D2DC59,
        GET_PED_LAST_DAMAGE_BONE=0xD75960F6BD9EA49C,
        CLEAR_PED_LAST_DAMAGE_BONE=0x8EF6B7AC68E2F01B,
        NETWORK_GET_ENTITY_KILLER_OF_PLAYER=0x42B2DAA6B596F5F8,
        NETWORK_GET_PLAYER_INDEX_FROM_PED=0x6C0E2E0125610278,
        DOES_ENTITY_EXIST=0x7239B21A38F536BA,
        IS_ENTITY_A_PED=0x524AC5ECEA15343E,
        IS_ENTITY_A_VEHICLE=0x6AC7003FA6E5575E,
        IS_PED_A_PLAYER=0x12534C348C6CB68B,
        GET_PED_IN_VEHICLE_SEAT=0xBB40DD2270B65366,
    }
    D.native=H

    local function now_ms()
        if startup.now then return tonumber(startup.now()) or 0 end
        if Time and Time.GetEpocheMs then
            local ok,v=direct_call(Time.GetEpocheMs); if ok then return tonumber(v or 0) or 0 end
        end
        return math.floor((os.clock and os.clock() or 0)*1000)
    end
    local function nint(hash,...)
        if not (Natives and Natives.InvokeInt) then return 0 end
        local ok,v=pcall(Natives.InvokeInt,hash,...)
        return ok and tonumber(v or 0) or 0
    end
    local function nbool(hash,...)
        if not (Natives and Natives.InvokeBool) then return false end
        local ok,v=pcall(Natives.InvokeBool,hash,...)
        return ok and v==true
    end
    local function nvoid(hash,...)
        if not (Natives and Natives.InvokeVoid) then return false end
        return pcall(Natives.InvokeVoid,hash,...)
    end
    local function u32(v)
        v=tonumber(v or 0) or 0
        if v<0 then v=v+4294967296 end
        return v%4294967296
    end
    local function j(name)
        if not (Utils and Utils.Joaat) then return 0 end
        local ok,v=direct_call(Utils.Joaat,tostring(name or ""))
        return ok and u32(v) or 0
    end
    local function make_set(names)
        local set={}
        for _,name in ipairs(names or {}) do
            local h=j(name); if h~=0 then set[h]=true end
        end
        return set
    end

    D.weapon_groups=D.weapon_groups or {
        explosion=make_set({
            "weapon_grenade","weapon_stickybomb","weapon_proximitymine","weapon_pipebomb",
            "weapon_rpg","weapon_hominglauncher","weapon_grenadelauncher","weapon_grenadelauncher_smoke",
            "weapon_compactlauncher","weapon_railgun","weapon_railgunxm3","weapon_explosion"
        }),
        machinegun=make_set({
            "weapon_mg","weapon_combatmg","weapon_combatmg_mk2","weapon_gusenberg",
            "weapon_microsmg","weapon_smg","weapon_smg_mk2","weapon_assaultsmg","weapon_combatpdw",
            "weapon_machinepistol","weapon_minismg","weapon_tecpistol"
        }),
        shotgun=make_set({
            "weapon_pumpshotgun","weapon_pumpshotgun_mk2","weapon_sawnoffshotgun","weapon_assaultshotgun",
            "weapon_bullpupshotgun","weapon_heavyshotgun","weapon_dbshotgun","weapon_autoshotgun","weapon_combatshotgun"
        }),
        sniper=make_set({
            "weapon_sniperrifle","weapon_heavysniper","weapon_heavysniper_mk2","weapon_marksmanrifle",
            "weapon_marksmanrifle_mk2","weapon_precisionrifle"
        }),
        pistol=make_set({
            "weapon_pistol","weapon_pistol_mk2","weapon_combatpistol","weapon_appistol","weapon_pistol50",
            "weapon_snspistol","weapon_snspistol_mk2","weapon_heavypistol","weapon_vintagepistol","weapon_marksmanpistol",
            "weapon_revolver","weapon_revolver_mk2","weapon_doubleaction","weapon_navyrevolver","weapon_ceramicpistol",
            "weapon_gadgetpistol","weapon_pistolxm3"
        }),
        rifle=make_set({
            "weapon_assaultrifle","weapon_assaultrifle_mk2","weapon_carbinerifle","weapon_carbinerifle_mk2",
            "weapon_advancedrifle","weapon_specialcarbine","weapon_specialcarbine_mk2","weapon_bullpuprifle",
            "weapon_bullpuprifle_mk2","weapon_compactrifle","weapon_militaryrifle","weapon_heavyrifle",
            "weapon_tacticalrifle","weapon_battlerifle"
        }),
        melee=make_set({
            "weapon_unarmed","weapon_knife","weapon_nightstick","weapon_hammer","weapon_bat","weapon_crowbar",
            "weapon_golfclub","weapon_bottle","weapon_dagger","weapon_hatchet","weapon_knuckle","weapon_machete",
            "weapon_switchblade","weapon_battleaxe","weapon_poolcue","weapon_wrench","weapon_stone_hatchet","weapon_candycane"
        }),
        fire=make_set({"weapon_molotov","weapon_fire"}),
        fall=make_set({"weapon_fall"}),
        drowning=make_set({"weapon_drowning","weapon_drowning_in_vehicle"}),
        vehicle=make_set({"weapon_ram","weapon_run_over_by_car","weapon_heli_crash"}),
    }

    local function in_group(group,hash)
        return type(D.weapon_groups[group])=="table" and D.weapon_groups[group][u32(hash)]==true
    end
    local function player_name(pid)
        pid=tonumber(pid or -1) or -1
        if pid<0 or pid>31 then return nil end
        if startup.get_player_name_safe then
            local ok,name=direct_call(startup.get_player_name_safe,pid)
            if ok and name and tostring(name)~="" and tostring(name)~="You" then return tostring(name) end
        end
        if Players and Players.GetName then
            local ok,name=direct_call(Players.GetName,pid)
            if ok and name and tostring(name)~="" then return tostring(name) end
        end
        return "Player "..tostring(pid)
    end
    local function entity_to_player(entity)
        entity=tonumber(entity or 0) or 0
        if entity==0 or not nbool(H.DOES_ENTITY_EXIST,entity) then return -1 end
        if nbool(H.IS_ENTITY_A_PED,entity) then
            if nbool(H.IS_PED_A_PLAYER,entity) then return nint(H.NETWORK_GET_PLAYER_INDEX_FROM_PED,entity) end
            return -1
        end
        if nbool(H.IS_ENTITY_A_VEHICLE,entity) then
            local driver=nint(H.GET_PED_IN_VEHICLE_SEAT,entity,-1,false)
            if driver~=0 and nbool(H.IS_PED_A_PLAYER,driver) then return nint(H.NETWORK_GET_PLAYER_INDEX_FROM_PED,driver) end
        end
        return -1
    end
    local function read_ptr(ptr)
        ptr=tonumber(ptr or 0) or 0
        if ptr==0 or not (Memory and Memory.ReadInt) then return 0 end
        local ok,v=pcall(Memory.ReadInt,ptr)
        return ok and tonumber(v or 0) or 0
    end
    local function write_ptr(ptr,value)
        ptr=tonumber(ptr or 0) or 0
        if ptr==0 or not (Memory and Memory.WriteInt) then return false end
        return pcall(Memory.WriteInt,ptr,tonumber(value or 0) or 0)
    end
    local function death_message(killerName,weaponHash,bone,sourceIsVehicle,selfKill)
        weaponHash=u32(weaponHash)
        local headshot=tonumber(bone or 0)==31086
        if selfKill then
            if in_group("explosion",weaponHash) then return "You killed yourself with an explosion." end
            if in_group("fall",weaponHash) then return "You died from a fall." end
            if in_group("drowning",weaponHash) then return "You drowned." end
            return "You died by your own hand."
        end
        if in_group("fall",weaponHash) then return "You died from a fall." end
        if in_group("drowning",weaponHash) then return "You drowned." end
        if killerName then
            if in_group("explosion",weaponHash) then return killerName.." killed you with an explosion." end
            if headshot and not in_group("melee",weaponHash) then return killerName.." shot you in the head." end
            if in_group("machinegun",weaponHash) then return killerName.." machine-gunned you." end
            if in_group("shotgun",weaponHash) then return killerName.." killed you with a shotgun." end
            if in_group("sniper",weaponHash) then return killerName.." sniped you." end
            if in_group("pistol",weaponHash) then return killerName.." shot you with a pistol." end
            if in_group("rifle",weaponHash) then return killerName.." shot you with a rifle." end
            if in_group("melee",weaponHash) then return killerName.." killed you in melee." end
            if in_group("fire",weaponHash) then return killerName.." burned you to death." end
            if sourceIsVehicle or in_group("vehicle",weaponHash) then return killerName.." ran you over." end
            return killerName.." killed you."
        end
        if in_group("explosion",weaponHash) then return "You were killed by an explosion." end
        if headshot and not in_group("melee",weaponHash) then return "You were shot in the head." end
        if in_group("machinegun",weaponHash) then return "You were killed by machine-gun fire." end
        if in_group("shotgun",weaponHash) then return "You were killed by a shotgun." end
        if in_group("sniper",weaponHash) then return "You were sniped." end
        if in_group("pistol",weaponHash) then return "You were shot with a pistol." end
        if in_group("rifle",weaponHash) then return "You were shot with a rifle." end
        if in_group("melee",weaponHash) then return "You were killed in melee." end
        if in_group("fire",weaponHash) then return "You burned to death." end
        if sourceIsVehicle or in_group("vehicle",weaponHash) then return "You were killed by a vehicle." end
        return "You died."
    end
    local function emit(message,killerPid,weaponHash,bone)
        message=tostring(message or "You died.")
        D.last_message=message
        D.history[#D.history+1]={time=os.date and os.date("%H:%M:%S") or "",text=message}
        while #D.history>8 do table.remove(D.history,1) end
        local feedAvailable=startup.session_activity_record and startup.s.playerModUiEnabled~=false and startup.s.showSessionActivityHud~=false
        if feedAvailable then
            direct_call(startup.session_activity_record,"death",message,"",8000,{playerId=tonumber(killerPid),classification="normal"})
        elseif startup.toast_colored then
            direct_call(startup.toast_colored,"Death Log: "..message,6500,"error")
        elseif startup.toast then
            direct_call(startup.toast,"Death Log: "..message,6500)
        end
        if startup.log_colored then
            direct_call(startup.log_colored,"[Death Log] "..message,"error")
        elseif startup.log then
            direct_call(startup.log,"[Death Log] "..message)
        end
        if startup.support_log_event_quiet then
            direct_call(startup.support_log_event_quiet,"BUILD426_DEATH_LOG_ENTRY","killer_pid="..tostring(killerPid or -1).." weapon="..tostring(u32(weaponHash)).." bone="..tostring(bone or 0).." text="..message)
        end
    end
    local function capture_death(ped)
        ped=tonumber(ped or 0) or 0
        if ped==0 then return end
        local localPid=nint(H.PLAYER_ID)
        local weaponHash=0
        local killerEntity=0
        if tonumber(D.weapon_ptr or 0)~=0 then
            write_ptr(D.weapon_ptr,0)
            killerEntity=nint(H.NETWORK_GET_ENTITY_KILLER_OF_PLAYER,localPid,D.weapon_ptr)
            weaponHash=read_ptr(D.weapon_ptr)
        end
        local cause=nint(H.GET_PED_CAUSE_OF_DEATH,ped)
        if weaponHash==0 then weaponHash=cause end
        local source=nint(H.GET_PED_SOURCE_OF_DEATH,ped)
        if killerEntity==0 then killerEntity=source end
        local bone=0
        if tonumber(D.bone_ptr or 0)~=0 then
            write_ptr(D.bone_ptr,0)
            if nbool(H.GET_PED_LAST_DAMAGE_BONE,ped,D.bone_ptr) then bone=read_ptr(D.bone_ptr) end
        end
        local killerPid=entity_to_player(killerEntity)
        if killerPid<0 and source~=killerEntity then killerPid=entity_to_player(source) end
        local sourceIsVehicle=(killerEntity~=0 and nbool(H.IS_ENTITY_A_VEHICLE,killerEntity)) or (source~=0 and nbool(H.IS_ENTITY_A_VEHICLE,source))
        local selfKill=killerPid>=0 and localPid>=0 and killerPid==localPid
        local killerName=(killerPid>=0 and not selfKill) and player_name(killerPid) or nil
        -- B465: feed the confirmed killer event into the independent Killed You
        -- retaliation system even when the visible Death Log is disabled. The handler
        -- is installed later in the file and is therefore optional during early boot.
        if killerPid>=0 and not selfKill and startup.killed_you_retaliation_event_build465 then
            pcall(startup.killed_you_retaliation_event_build465,killerPid,killerName,weaponHash,bone)
        end
        if D.enabled==true then
            emit(death_message(killerName,weaponHash,bone,sourceIsVehicle,selfKill),killerPid,weaponHash,bone)
        end
    end
    local function tick()
        if D.enabled~=true and startup.s.killedYouRetaliationEnabled~=true then D.was_dead=nil; D.pending_capture_ms=0; return end
        local ped=nint(H.PLAYER_PED_ID)
        if ped==0 then return end
        if ped~=D.last_ped then
            D.last_ped=ped
            D.was_dead=nbool(H.IS_PED_DEAD_OR_DYING,ped,true)
            D.pending_capture_ms=0
            return
        end
        local dead=nbool(H.IS_PED_DEAD_OR_DYING,ped,true)
        local now=now_ms()
        if D.was_dead==nil then D.was_dead=dead end
        if dead and D.was_dead~=true then
            D.pending_capture_ms=now+150
        end
        if dead and D.pending_capture_ms>0 and now>=D.pending_capture_ms then
            D.pending_capture_ms=0
            capture_death(ped)
        end
        if not dead and D.was_dead==true then
            D.pending_capture_ms=0
            nvoid(H.CLEAR_PED_LAST_DAMAGE_BONE,ped)
        end
        D.was_dead=dead
    end

    if Memory and Memory.AllocInt then
        if D.weapon_ptr==0 then pcall(function() D.weapon_ptr=Memory.AllocInt() or 0 end) end
        if D.bone_ptr==0 then pcall(function() D.bone_ptr=Memory.AllocInt() or 0 end) end
    end

    startup.add_toggle("EssentialsDeathLog","Death Log","Shows a readable notification when you die, including the killer and cause when GTA exposes enough information.",function(f)
        D.enabled=f and f.IsToggled and f:IsToggled()==true
        startup.s.deathLogEnabled=D.enabled==true
        D.was_dead=nil
        D.pending_capture_ms=0
        if startup.s.initialized and startup.save_config then direct_call(startup.save_config,false) end
    end,D.enabled==true)

    if Script and Script.RegisterLooped and D.loop_installed~=true then
        D.loop_installed=true
        Script.RegisterLooped(function()
            if ShouldUnload and ShouldUnload() then if Script.Yield then Script.Yield(100) end return end
            local ok,err=pcall(tick)
            if not ok and startup.support_log_event_quiet then direct_call(startup.support_log_event_quiet,"BUILD426_DEATH_LOG_TICK_ERROR",tostring(err or "unknown")) end
            if Script.Yield then Script.Yield(D.enabled and 75 or 250) end
        end)
    end

    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_UNLOAD and D.unload_hook~=true then
        D.unload_hook=true
        EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD,function()
            if Memory and Memory.Free then
                if tonumber(D.weapon_ptr or 0)~=0 then pcall(Memory.Free,D.weapon_ptr); D.weapon_ptr=0 end
                if tonumber(D.bone_ptr or 0)~=0 then pcall(Memory.Free,D.bone_ptr); D.bone_ptr=0 end
            end
        end)
    end
end
startup.install_build426_death_log()
startup.install_build426_death_log=nil

