startup.whats_new_version="2026.09.30.426"
if startup.log then
    startup.log("[Build 426] B425 main-chunk local limit repaired; player-count minimap toggle preserved; Essentials Death Log added ON by default with killer/cause/headshot classification and saved state.")
end
if startup.support_log_event_quiet then
    startup.support_log_event_quiet(
        "BUILD426_LOCAL_LIMIT_DEATH_LOG_READY",
        "b425_local_limit_fixed=true minimap_toggle_preserved=true death_log_default_on=true death_log_saved=true killer_resolution=true headshot_bone=true weapon_categories=true native_safe=true"
    )
end


-- ============================================================================
-- BUILD 427: RELIABLE Z / MINIMAP INPUT DETECTOR
-- - Replaces B425's Utils.IsKeyPressed-only detector with a multi-source edge
--   detector designed for fast taps.
-- - Primary: Utils.IsKeyDown(VK_Z) rising edge.
-- - Backup: GTA INPUT_MULTIPLAYER_INFO (control 20) just-pressed state.
-- - Final fallback: Utils.IsKeyPressed(VK_Z), only when the physical down state
--   is unavailable/not reporting the press.
-- - Debounces duplicate reports from different input sources into one press.
-- - Preserves <=16 players = double Z, >=17 players = triple Z, next Z restores.
-- ============================================================================
startup.b427 = startup.b427 or {
    raw_z_down = false,
    last_counted_press_ms = 0,
    last_source = "",
    detected_presses = 0,
}

function startup.b427_read_z_input()
    local B=startup.b427
    local rawDown=false
    local rawAvailable=false
    local utilityPressed=false
    local padPressed=false
    local disabledPadPressed=false

    if Utils and Utils.IsKeyDown then
        local ok,value=direct_call(Utils.IsKeyDown,0x5A)
        if ok then rawAvailable=true; rawDown=value==true end
    end

    -- INPUT_MULTIPLAYER_INFO = control 20 (default keyboard binding Z).
    -- These are exposed by the supplied Cherax native table and are used only as
    -- a backup pulse source; the physical VK edge remains authoritative.
    if Natives and Natives.InvokeBool then
        local ok,value=pcall(Natives.InvokeBool,0x580417101DDB492F,0,20)
        if ok then padPressed=value==true end
        local ok2,value2=pcall(Natives.InvokeBool,0x91AEF906BCA88877,0,20)
        if ok2 then disabledPadPressed=value2==true end
    end

    if Utils and Utils.IsKeyPressed then
        local ok,value=direct_call(Utils.IsKeyPressed,0x5A)
        if ok then utilityPressed=value==true end
    end

    local rising=rawAvailable and rawDown and B.raw_z_down~=true
    B.raw_z_down=rawDown

    if rising then return true,"VK_DOWN_EDGE" end
    if padPressed then return true,"GTA_CONTROL_20" end
    if disabledPadPressed then return true,"GTA_DISABLED_CONTROL_20" end
    if not rawAvailable and utilityPressed then return true,"VK_PRESSED_FALLBACK" end
    return false,""
end

function startup.b427_count_z_press(now,source)
    local B=startup.b427
    now=tonumber(now or startup.b422_now()) or 0

    -- Multiple sources can report the same physical Z press. Collapse anything
    -- inside this small window into one logical press.
    if now-(tonumber(B.last_counted_press_ms or 0) or 0)<90 then return false end
    B.last_counted_press_ms=now
    B.last_source=tostring(source or "")
    B.detected_presses=(tonumber(B.detected_presses or 0) or 0)+1

    if startup.b425.active==true then
        startup.b425_set_active(false,"next Z after expanded minimap via "..B.last_source)
        return true
    end

    local S=startup.b422
    local started=tonumber(S.z_window_started_ms or 0) or 0
    if started<=0 or now-started>4000 then
        S.z_press_count=0
        S.z_window_started_ms=now
        local players=startup.b425_player_count()
        startup.b425.sequence_players=players
        startup.b425.required_presses=startup.b425_required_presses(players)
    end

    S.z_press_count=(tonumber(S.z_press_count or 0) or 0)+1
    local required=tonumber(startup.b425.required_presses or 0) or 0
    if required<=0 then
        local players=startup.b425_player_count()
        startup.b425.sequence_players=players
        required=startup.b425_required_presses(players)
        startup.b425.required_presses=required
    end

    if startup.support_log_event_quiet then
        startup.support_log_event_quiet(
            "BUILD427_MINIMAP_Z_PRESS",
            "count="..tostring(S.z_press_count).." required="..tostring(required).." players="..tostring(startup.b425.sequence_players or 0).." source="..B.last_source
        )
    end

    if S.z_press_count>=required then
        local players=startup.b425.sequence_players
        startup.b425_set_active(true,tostring(required).."x Z at "..tostring(players).." players via "..B.last_source)
    end
    return true
end

-- B422's already-installed 25 ms loop dynamically calls this symbol, so replacing
-- it here upgrades input handling without registering another polling loop.
function startup.b422_minimap_key_tick()
    local now=startup.b422_now()
    local pressed,source=startup.b427_read_z_input()
    if pressed then startup.b427_count_z_press(now,source) end

    if startup.b425.active~=true and (tonumber(startup.b422.z_press_count or 0) or 0)>0 then
        local started=tonumber(startup.b422.z_window_started_ms or now) or now
        if now-started>4000 then startup.b425_reset_sequence() end
    end
end

