-- ============================================================================
-- BUILD 430: STABLE PLAYER PRE-SCAN + 10 SECOND MINIMAP AUTO-RESTORE
-- - Continuously pre-scans connected-player count before the Z sequence starts.
-- - Requires two matching scans before promoting a stable count.
-- - Freezes the pre-scanned count for the entire Z sequence so 16/17-player
--   fluctuations cannot switch the required double/triple-Z rule mid-cycle.
-- - Expanded HUD still restores immediately on the next Z press.
-- - Expanded HUD now also restores automatically after 10 seconds.
-- - Preserves B427 reliable input, B428 frame-smooth animation, B429 static
--   Advertise HUD, B426 Death Log, Trigger Bot persistence, and Region HUD.
-- ============================================================================
startup.b430 = startup.b430 or {
    scan_interval_ms = 200,
    last_scan_ms = 0,
    candidate_players = -1,
    candidate_hits = 0,
    stable_players = -1,
    stable_at_ms = 0,
    sequence_players = -1,
    sequence_required = 0,
    auto_restore_ms = 10000,
    expanded_until_ms = 0,
}

function startup.b430_scan_players(now)
    local B=startup.b430
    now=tonumber(now or startup.b422_now()) or 0
    if now-(tonumber(B.last_scan_ms or 0) or 0)<(tonumber(B.scan_interval_ms or 200) or 200) then return end
    B.last_scan_ms=now

    local players=startup.b425_player_count()
    if players==tonumber(B.candidate_players or -1) then
        B.candidate_hits=(tonumber(B.candidate_hits or 0) or 0)+1
    else
        B.candidate_players=players
        B.candidate_hits=1
    end

    if (tonumber(B.candidate_hits or 0) or 0)>=2 then
        B.stable_players=players
        B.stable_at_ms=now
    end
end

function startup.b430_sequence_snapshot(now)
    local B=startup.b430
    now=tonumber(now or startup.b422_now()) or 0
    startup.b430_scan_players(now)

    local players=tonumber(B.stable_players or -1) or -1
    local age=now-(tonumber(B.stable_at_ms or 0) or 0)
    if players<0 or age>1500 then
        players=startup.b425_player_count()
    end

    players=math.max(0,math.floor(tonumber(players or 0) or 0))
    B.sequence_players=players
    B.sequence_required=startup.b425_required_presses(players)
    startup.b425.sequence_players=players
    startup.b425.required_presses=B.sequence_required
    return players,B.sequence_required
end

startup.b430.b425_set_active_base = startup.b430.b425_set_active_base or startup.b425_set_active
function startup.b425_set_active(value,reason)
    local B=startup.b430
    local now=startup.b422_now()
    local enabled=value==true
    if enabled then
        local travel=math.max(0,tonumber(startup.b424 and startup.b424.transition_ms or 400) or 400)
        B.expanded_until_ms=now+travel+(tonumber(B.auto_restore_ms or 10000) or 10000)
    else
        B.expanded_until_ms=0
        B.sequence_players=-1
        B.sequence_required=0
    end
    return startup.b430.b425_set_active_base(enabled,reason)
end

-- Override the target-state resolver so the 10-second timeout is authoritative.
function startup.b424_active()
    local now=startup.b424_now()
    local preview_until=tonumber(startup.b424.preview_until_ms or 0) or 0
    if now<preview_until then return true end
    if startup.s.expandedMinimapHudEnabled==false then return false end

    if startup.b425 and startup.b425.active==true then
        local until_ms=tonumber(startup.b430.expanded_until_ms or 0) or 0
        if until_ms>0 and now>=until_ms then
            startup.b425_set_active(false,"10 second automatic restore")
            return false
        end
        return true
    end
    return false
end

-- Freeze the pre-scanned count at the beginning of each Z cycle. Never re-read
-- the lobby count until that sequence completes or expires.
function startup.b427_count_z_press(now,source)
    local B=startup.b427
    now=tonumber(now or startup.b422_now()) or 0

    if now-(tonumber(B.last_counted_press_ms or 0) or 0)<90 then return false end
    B.last_counted_press_ms=now
    B.last_source=tostring(source or "")
    B.detected_presses=(tonumber(B.detected_presses or 0) or 0)+1

    if startup.b425.active==true then
        startup.b425_set_active(false,"next Z after expanded minimap via "..B.last_source)
        return true
    end

    local S=startup.b422
    local started=tonumber(S.z_window_started_ms or 0) or 0
    if started<=0 or now-started>4000 then
        S.z_press_count=0
        S.z_window_started_ms=now
        startup.b430_sequence_snapshot(now)
    end

    S.z_press_count=(tonumber(S.z_press_count or 0) or 0)+1
    local required=tonumber(startup.b430.sequence_required or startup.b425.required_presses or 0) or 0
    if required<=0 then
        startup.b430_sequence_snapshot(now)
        required=tonumber(startup.b430.sequence_required or 0) or 0
    end

    if startup.support_log_event_quiet then
        startup.support_log_event_quiet(
            "BUILD430_MINIMAP_Z_PRESS",
            "count="..tostring(S.z_press_count)..
            " required="..tostring(required)..
            " prescan_players="..tostring(startup.b430.sequence_players or -1)..
            " live_players="..tostring(startup.b425_player_count())..
            " source="..B.last_source
        )
    end

    if S.z_press_count>=required then
        startup.b425_set_active(true,tostring(required).."x Z from locked pre-scan of "..tostring(startup.b430.sequence_players or -1).." players via "..B.last_source)
    end
    return true
end

-- Keep the stable player pre-scan warm even when the user is not pressing Z,
-- and enforce timeout independently of render cadence.
function startup.b422_minimap_key_tick()
    local now=startup.b422_now()
    startup.b430_scan_players(now)

    if startup.b425.active==true then
        local until_ms=tonumber(startup.b430.expanded_until_ms or 0) or 0
        if until_ms>0 and now>=until_ms then
            startup.b425_set_active(false,"10 second automatic restore")
        end
    end

    local pressed,source=startup.b427_read_z_input()
    if pressed then startup.b427_count_z_press(now,source) end

    if startup.b425.active~=true and (tonumber(startup.b422.z_press_count or 0) or 0)>0 then
        local started=tonumber(startup.b422.z_window_started_ms or now) or now
        if now-started>4000 then
            startup.b425_reset_sequence()
            startup.b430.sequence_players=-1
            startup.b430.sequence_required=0
        end
    end
end

