-- ============================================================================
-- BUILD 432: EVENT GTA VERSION LABEL + CROSS-EDITION EVENT AWARENESS
-- - Events remain visible/notified across Legacy and Enhanced.
-- - Event surfaces emphasize GTA V Version: Legacy/Enhanced in red.
-- - Event JOIN may open Before You Join across editions, but after acknowledgement
--   a wrong-edition client is stopped with a dedicated compatibility popup.
-- - Normal Live Session edition isolation remains unchanged.
-- ============================================================================
startup.b432 = startup.b432 or { platform_notice=nil, present_installed=false, publish_wrapped=false }

function startup.b432_normalize_edition(value)
    local v=tostring(value or ""):upper():gsub("^%s+",""):gsub("%s+$","")
    if v=="LE" or v=="LE BE" or v:find("LEGACY",1,true) then return "Legacy" end
    if v=="EE" or v=="EE BE" or v:find("ENHANCED",1,true) then return "Enhanced" end
    return ""
end

function startup.b432_current_edition()
    if startup.get_active_edition_info then
        local ok,a,b,c,d=direct_call(startup.get_active_edition_info)
        if ok then
            local n=startup.b432_normalize_edition(b)
            if n~="" and d==true then return n end
            if n~="" then return n end
        end
    end
    if startup.is_enhanced_active_edition then
        local ok,v=direct_call(startup.is_enhanced_active_edition)
        if ok then return v==true and "Enhanced" or "Legacy" end
    end
    return "Unknown"
end

function startup.b432_event_edition(row,eventRow)
    local function pick(v)
        local n=startup.b432_normalize_edition(v)
        if n~="" then return n end
        return nil
    end
    if type(eventRow)=="table" then
        local n=pick(eventRow.edition) or pick(eventRow.gta_version) or pick(eventRow.gtaVersion) or pick(eventRow.platform) or pick(eventRow.version)
        if n then return n end
        if type(eventRow.row)=="table" then
            n=pick(eventRow.row.edition) or pick(eventRow.row.gta_version) or pick(eventRow.row.platform)
            if n then return n end
        end
    end
    if type(row)=="table" then
        local n=pick(row.edition) or pick(row.gta_version) or pick(row.gtaVersion) or pick(row.platform) or pick(row.version)
        if n then return n end
    end
    local listing=""
    if type(row)=="table" then listing=tostring(row.listingId or row.listing_id or "") end
    if listing=="" and type(eventRow)=="table" then listing=tostring(eventRow.listingId or eventRow.listing_id or "") end
    if listing~="" and browser and type(browser.liveRows)=="table" then
        for _,liveRow in ipairs(browser.liveRows) do
            if tostring(liveRow.listingId or liveRow.listing_id or "")==listing then
                local n=pick(liveRow.edition)
                if n then return n end
            end
        end
    end
    return "Unknown"
end

function startup.b432_event_title(row)
    if type(row)~="table" then return "this Event" end
    local title=tostring(row.eventTitle or row.title or row.rockstarJobName or row.activity or "")
    if title=="" then title="this Event" end
    return title
end

function startup.b432_show_platform_notice(row)
    if type(row)~="table" then return false end
    startup.b432.platform_notice={
        title=startup.b432_event_title(row),
        host=tostring(row.username or row.profileUsername or "Startup User"),
        required=startup.b432_event_edition(row,row),
        current=startup.b432_current_edition(),
    }
    return true
end

function startup.b432_render_platform_notice()
    if not ImGui or type(startup.b432.platform_notice)~="table" then return end
    local p=startup.b432.platform_notice
    local sw,sh=1280,720
    if startup.b419_display_size then
        local ok,w,h=pcall(startup.b419_display_size)
        if ok then sw=tonumber(w or sw) or sw; sh=tonumber(h or sh) or sh end
    end
    local width=math.min(680,math.max(560,sw-80))
    local height=330
    if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(math.max(20,(sw-width)*0.5),math.max(18,(sh-height)*0.5),ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(width,height,ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowBgAlpha then ImGui.SetNextWindowBgAlpha(0.99) end
    local flags=startup.first_run_window_flags and startup.first_run_window_flags() or 0
    local colors,vars=0,0
    if startup.b419_push_window_style then colors,vars=startup.b419_push_window_style(false) end
    local visible=ImGui.Begin("GTA V Version Required##StartupB432",true,flags)==true
    if visible then
        if startup.b419_purple then startup.b419_purple("STARTUP EVENT — GTA V VERSION REQUIRED") end
        if ImGui.Separator then ImGui.Separator() end
        if ImGui.Spacing then ImGui.Spacing() end
        if startup.b419_text then
            startup.b419_text(1.00,0.24,0.28,1.0,"GTA V Version: "..tostring(p.required or "Unknown"))
            startup.b419_text(0.96,0.97,1.00,1.0,"Sorry, "..tostring(p.title or "this Event").." by "..tostring(p.host or "Startup User").." is only being hosted on GTA V "..tostring(p.required or "Unknown")..".")
            startup.b419_text(0.96,0.97,1.00,1.0,"You are currently running GTA V "..tostring(p.current or "Unknown")..".")
            startup.b419_text(1.00,0.70,0.22,1.0,"Please launch GTA V "..tostring(p.required or "Unknown").." and open Startup Browser again to join them.")
        elseif ImGui.TextWrapped then
            ImGui.TextWrapped("Sorry, this Event is only being hosted on GTA V "..tostring(p.required or "Unknown")..". Please switch GTA V versions to join it.")
        end
        if ImGui.Spacing then ImGui.Spacing() end
        if ImGui.Separator then ImGui.Separator() end
        if ImGui.Spacing then ImGui.Spacing() end
        if startup.b419_button then
            if startup.b419_button("I UNDERSTAND","B432PlatformUnderstand","Purple",180,36) then startup.b432.platform_notice=nil end
        elseif ImGui.Button and ImGui.Button("I UNDERSTAND",180,36) then
            startup.b432.platform_notice=nil
        end
    end
    ImGui.End()
    if startup.b419_pop_window_style then startup.b419_pop_window_style(colors,vars) end
end

-- Inject the local GTA version into the publication payload before B419 copies it for
-- self-host notification preview. The existing backend can continue deriving/storing its
-- canonical Event edition; this keeps client-side publication/UI consistent as well.
if startup.browser_events_publish and startup.b432.publish_wrapped~=true then
    startup.b432.publish_wrapped=true
    startup.b432.publish_pre=startup.browser_events_publish
    startup.browser_events_publish=function(payload)
        payload=type(payload)=="table" and payload or {}
        if startup.b432_normalize_edition(payload.edition)=="" then payload.edition=startup.b432_current_edition() end
        return startup.b432.publish_pre(payload)
    end
end

-- Event rows are the deliberate exception to the normal pre-popup edition rejection.
-- They may show Before You Join cross-edition, then this final execution gate blocks the
-- actual JOIN after acknowledgement and presents a clear version-switch message.
if startup.browser_runtime_request_join and startup.b432.request_join_wrapped~=true then
    startup.b432.request_join_wrapped=true
    startup.b432.request_join_pre=startup.browser_runtime_request_join
    startup.browser_runtime_request_join=function(row)
        if type(row)=="table" and row.isStartupEvent==true then
            if startup.browser_prime_access_blocked and startup.browser_prime_access_blocked() then return false end
            if startup.browser_hosttools_access_blocked_326 and startup.browser_hosttools_access_blocked_326() then return false end
            if startup.browser_join_is_active_b360 and startup.browser_join_is_active_b360() then
                if startup.toast then startup.toast("A Browser JOIN is already in progress.",3000) end
                return false
            end
            if row.live==true and row.joinable~=true then
                if startup.toast then startup.toast("This live Event is not currently joinable.",3000) end
                return false
            end
            browser.joinPopupTarget=row
            browser.joinPopupRequested=true
            if startup.log then startup.log("[Build 432] EVENT_JOIN_NOTICE | host="..tostring(row.username or "").." | required="..tostring(startup.b432_event_edition(row,row)).." | current="..tostring(startup.b432_current_edition())) end
            return true
        end
        return startup.b432.request_join_pre(row)
    end
end

if startup.browser_execute_join and startup.b432.execute_join_wrapped~=true then
    startup.b432.execute_join_wrapped=true
    startup.b432.execute_join_pre=startup.browser_execute_join
    startup.browser_execute_join=function(row)
        if type(row)=="table" and row.isStartupEvent==true then
            local required=startup.b432_event_edition(row,row)
            local current=startup.b432_current_edition()
            if required~="Unknown" and current~="Unknown" and required~=current then
                startup.b432_show_platform_notice(row)
                if startup.log then startup.log("[Build 432] EVENT_JOIN_EDITION_BLOCK | title="..startup.b432_event_title(row).." | host="..tostring(row.username or "").." | required="..required.." | current="..current) end
                return false
            end
        end
        return startup.b432.execute_join_pre(row)
    end
end

if EventMgr and eLuaEvent and eLuaEvent.ON_PRESENT and startup.b432.present_installed~=true then
    startup.b432.present_installed=true
    EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT,function()
        if startup and startup.b432_render_platform_notice then
            local ok,err=pcall(startup.b432_render_platform_notice)
            if not ok and startup.support_log_event_quiet then startup.support_log_event_quiet("BUILD432_PLATFORM_POPUP_ERROR",tostring(err or "unknown")) end
        end
    end)
end

