-- ============================================================================
-- BUILD 433: PROXIMITY / SAME-VEHICLE MOD ATTRIBUTION GUARD
-- - Prevents proximity-correlated explosion detections from falsely classifying
--   nearby passengers/players as modders when attribution is unsafe.
-- - Same-vehicle explosion flags are quarantined for that player's current
--   presence. Extremely-close explosion flags are also quarantined.
-- - If local Explosive Ammo is enabled, the proximity guard radius expands.
-- - Quarantined explosion flags cannot create Modder HUD / RID modder evidence.
-- - Independent crash/kick/BattlEye/high-confidence evidence remains unchanged.
-- ============================================================================
startup.b433 = startup.b433 or {
    quarantine = {},
    same_vehicle_radius = 6.0,
    explosive_ammo_radius = 16.0,
    wrapped_reasons = false,
    wrapped_record = false,
    suppressed_count = 0,
}

function startup.b433_trim(value)
    return tostring(value or ""):gsub("^%s+",""):gsub("%s+$","")
end

function startup.b433_reason_is_proximity_sensitive(reason)
    if not startup.mod_detection or not startup.mod_detection.classify_reason then return false end
    local ok,category=direct_call(function() return select(1,startup.mod_detection.classify_reason(reason)) end)
    if not ok then return false end
    return tostring(category or "") == "explosion"
end

function startup.b433_player_identity_key(playerId)
    local pid=tonumber(playerId)
    if pid==nil then return "" end
    local name=""
    if startup.get_player_name_safe then
        local ok,v=direct_call(startup.get_player_name_safe,pid)
        if ok then name=startup.b433_trim(v):lower() end
    end
    return tostring(math.floor(pid)).."|"..name
end

function startup.b433_vec3(hash,...)
    if not (Natives and Natives.InvokeV3) then return nil,nil,nil end
    local ok,a,b,c=pcall(Natives.InvokeV3,hash,...)
    if not ok then return nil,nil,nil end
    if type(a)=="table" then
        return tonumber(a.x or a.X or a[1]),tonumber(a.y or a.Y or a[2]),tonumber(a.z or a.Z or a[3])
    end
    if type(a)=="userdata" then
        local x,y,z=nil,nil,nil
        pcall(function() x=tonumber(a.x or a.X); y=tonumber(a.y or a.Y); z=tonumber(a.z or a.Z) end)
        return x,y,z
    end
    return tonumber(a),tonumber(b),tonumber(c)
end

function startup.b433_local_explosive_ammo_enabled()
    if not (FeatureMgr and FeatureMgr.GetFeatureByName) then return false end
    for _,name in ipairs({"Explosive Ammo","Explosive Bullets","Explosive Ammunition"}) do
        local ok,feature=direct_call(FeatureMgr.GetFeatureByName,name)
        if ok and feature then
            local value=nil
            if startup.get_feature_bool_state then
                local okState,v=direct_call(startup.get_feature_bool_state,feature)
                if okState then value=v end
            end
            if value==nil and feature.IsToggled then
                local okToggle,v=pcall(function() return feature:IsToggled() end)
                if okToggle then value=v==true end
            end
            if value==true then return true end
        end
    end
    return false
end

function startup.b433_player_context(playerId)
    local pid=tonumber(playerId)
    if pid==nil or pid<0 or pid>31 then return {valid=false,sameVehicle=false,distance=nil,explosiveAmmo=false} end
    if startup.is_local_player_id and startup.is_local_player_id(pid) then
        return {valid=false,sameVehicle=false,distance=0.0,explosiveAmmo=startup.b433_local_explosive_ammo_enabled()}
    end
    if not (Natives and Natives.InvokeInt) then return {valid=false,sameVehicle=false,distance=nil,explosiveAmmo=startup.b433_local_explosive_ammo_enabled()} end

    local okLocal,localPed=pcall(Natives.InvokeInt,0xD80958FC74E988A6)
    local okRemote,remotePed=pcall(Natives.InvokeInt,0x43A66C31C68491C0,pid)
    localPed=okLocal and tonumber(localPed) or 0
    remotePed=okRemote and tonumber(remotePed) or 0
    if not localPed or localPed==0 or not remotePed or remotePed==0 then
        return {valid=false,sameVehicle=false,distance=nil,explosiveAmmo=startup.b433_local_explosive_ammo_enabled()}
    end

    local localVehicle,remoteVehicle=0,0
    local okLV,vLV=pcall(Natives.InvokeInt,0x9A9112A0FE9A4713,localPed,false)
    local okRV,vRV=pcall(Natives.InvokeInt,0x9A9112A0FE9A4713,remotePed,false)
    if okLV then localVehicle=tonumber(vLV or 0) or 0 end
    if okRV then remoteVehicle=tonumber(vRV or 0) or 0 end
    local sameVehicle=localVehicle~=0 and remoteVehicle~=0 and localVehicle==remoteVehicle

    local lx,ly,lz=startup.b433_vec3(0x3FEF770D40960D5A,localPed,true)
    local rx,ry,rz=startup.b433_vec3(0x3FEF770D40960D5A,remotePed,true)
    local distance=nil
    if lx and ly and lz and rx and ry and rz then
        local dx,dy,dz=lx-rx,ly-ry,lz-rz
        distance=math.sqrt((dx*dx)+(dy*dy)+(dz*dz))
    end

    return {
        valid=true,
        sameVehicle=sameVehicle,
        distance=distance,
        localVehicle=localVehicle,
        remoteVehicle=remoteVehicle,
        explosiveAmmo=startup.b433_local_explosive_ammo_enabled(),
    }
end

function startup.b433_quarantine_key(playerId,reason)
    local ident=startup.b433_player_identity_key(playerId)
    if ident=="" then return "" end
    local normalized=startup.mod_detection and startup.mod_detection.normalize_flag_name and startup.mod_detection.normalize_flag_name(reason) or startup.b433_trim(reason):lower()
    return ident.."|"..tostring(normalized or "")
end

function startup.b433_is_quarantined(playerId,reason)
    local key=startup.b433_quarantine_key(playerId,reason)
    return key~="" and type(startup.b433.quarantine[key])=="table"
end

function startup.b433_mark_quarantine(playerId,reason,why,context)
    local key=startup.b433_quarantine_key(playerId,reason)
    if key=="" then return false end
    if type(startup.b433.quarantine[key])=="table" then return true end
    local pid=tonumber(playerId)
    local name=startup.get_player_name_safe and startup.get_player_name_safe(pid) or ("Player "..tostring(pid or "?"))
    startup.b433.quarantine[key]={
        playerId=pid,
        name=tostring(name or "Unknown"),
        reason=tostring(reason or ""),
        why=tostring(why or "unsafe-attribution"),
        distance=context and tonumber(context.distance) or nil,
        sameVehicle=context and context.sameVehicle==true or false,
        explosiveAmmo=context and context.explosiveAmmo==true or false,
        at=startup.now and startup.now() or 0,
    }
    startup.b433.suppressed_count=(tonumber(startup.b433.suppressed_count or 0) or 0)+1
    if startup.log then
        startup.log("[Build 433] MOD_ATTRIBUTION_SUPPRESSED | player="..tostring(name or pid).." | reason="..tostring(reason or "").." | why="..tostring(why or "").." | sameVehicle="..tostring(context and context.sameVehicle==true).." | distance="..tostring(context and context.distance or "unknown").." | localExplosiveAmmo="..tostring(context and context.explosiveAmmo==true))
    end
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("MOD_ATTRIBUTION_SUPPRESSED","player="..tostring(name or pid).." reason="..tostring(reason or "").." why="..tostring(why or "").." same_vehicle="..tostring(context and context.sameVehicle==true).." distance="..tostring(context and context.distance or "unknown").." local_explosive_ammo="..tostring(context and context.explosiveAmmo==true))
    end
    return true
end

function startup.b433_should_suppress_reason(playerId,reason)
    if not startup.b433_reason_is_proximity_sensitive(reason) then return false,nil end
    local pid=tonumber(playerId)
    if pid==nil then return false,nil end
    if startup.b433_is_quarantined(pid,reason) then return true,"session-quarantine" end

    local context=startup.b433_player_context(pid)
    if context.sameVehicle==true then
        startup.b433_mark_quarantine(pid,reason,"same-vehicle",context)
        return true,"same-vehicle"
    end
    local distance=tonumber(context.distance)
    if distance and distance<=tonumber(startup.b433.same_vehicle_radius or 6.0) then
        startup.b433_mark_quarantine(pid,reason,"very-close-proximity",context)
        return true,"very-close-proximity"
    end
    if context.explosiveAmmo==true and distance and distance<=tonumber(startup.b433.explosive_ammo_radius or 16.0) then
        startup.b433_mark_quarantine(pid,reason,"local-explosive-ammo-proximity",context)
        return true,"local-explosive-ammo-proximity"
    end
    return false,nil
end

function startup.b433_reason_parts(text)
    local out={}
    for part in tostring(text or ""):gmatch("[^|]+") do
        part=startup.b433_trim(part)
        if part~="" then out[#out+1]=part end
    end
    return out
end

function startup.b433_filter_reason_text(playerId,text)
    local kept={}
    local suppressed=false
    for _,reason in ipairs(startup.b433_reason_parts(text)) do
        local drop=startup.b433_should_suppress_reason(playerId,reason)
        if drop then suppressed=true else kept[#kept+1]=reason end
    end
    if #kept==0 then return nil,suppressed end
    return table.concat(kept," | "),suppressed
end

function startup.b433_repair_existing_false_positive(playerId,name)
    local pid=tonumber(playerId)
    name=startup.b433_trim(name)
    if pid==nil then return end

    -- Remove only quarantined explosion segments from the current HUD entry.
    if startup.modder_hud and type(startup.modder_hud.entries)=="table" then
        for key,entry in pairs(startup.modder_hud.entries) do
            local matches=tonumber(entry and entry.playerId)==pid or (name~="" and tostring(entry and entry.name or ""):lower()==name:lower())
            if matches and entry then
                local kept={}
                for _,reason in ipairs(startup.b433_reason_parts(entry.reason)) do
                    if not (startup.b433_reason_is_proximity_sensitive(reason) and startup.b433_is_quarantined(pid,reason)) then kept[#kept+1]=reason end
                end
                if #kept==0 then
                    startup.modder_hud.entries[key]=nil
                else
                    entry.reason=table.concat(kept," | ")
                end
            end
        end
        local nextOrder={}
        for _,key in ipairs(startup.modder_hud.order or {}) do
            if startup.modder_hud.entries[key] then nextOrder[#nextOrder+1]=key end
        end
        startup.modder_hud.order=nextOrder
    end

    -- Repair a prior RID 'modder' bit only when its modder evidence is exclusively
    -- quarantined explosion attribution. Crash/kick/BattlEye/block evidence is retained.
    if startup.session_activity_find_rid_entry and startup.rid_store then
        local ok,entry,rid=direct_call(startup.session_activity_find_rid_entry,pid)
        if ok and type(entry)=="table" and rid then
            entry.flags=type(entry.flags)=="table" and entry.flags or {}
            local hard=entry.blockJoin==true or entry.flags.crashAttacker==true or entry.flags.kickAttacker==true or entry.flags.battleye==true or entry.flags.blockRidJoin==true
            local otherModderEvidence=false
            for _,ev in ipairs(type(entry.events)=="table" and entry.events or {}) do
                if tostring(ev.event or ""):lower():find("modder",1,true) then
                    local evReason=tostring(ev.reason or "")
                    if not (startup.b433_reason_is_proximity_sensitive(evReason) and startup.b433_is_quarantined(pid,evReason)) then
                        otherModderEvidence=true
                        break
                    end
                end
            end
            if not otherModderEvidence and type(entry.reasons)=="table" then
                for reason in pairs(entry.reasons) do
                    local category,known="",false
                    if startup.mod_detection and startup.mod_detection.classify_reason then
                        local okClass,a,b=direct_call(startup.mod_detection.classify_reason,reason)
                        if okClass then category,known=tostring(a or ""),b==true end
                    end
                    if known and category~="explosion" and category~="ignored" then otherModderEvidence=true break end
                end
            end
            if entry.flags.modder==true and not hard and not otherModderEvidence then
                entry.flags.modder=false
                if type(entry.reasons)=="table" then
                    for reason in pairs(entry.reasons) do
                        if startup.b433_reason_is_proximity_sensitive(reason) and startup.b433_is_quarantined(pid,reason) then entry.reasons[reason]=nil end
                    end
                end
                if type(entry.events)=="table" then
                    local events={}
                    for _,ev in ipairs(entry.events) do
                        local isBad=tostring(ev.event or ""):lower():find("modder",1,true) and startup.b433_reason_is_proximity_sensitive(ev.reason) and startup.b433_is_quarantined(pid,ev.reason)
                        if not isBad then events[#events+1]=ev end
                    end
                    entry.events=events
                end
                if startup.rid_store.save then pcall(startup.rid_store.save) end
                if startup.log then startup.log("[Build 433] RID_FALSE_MODDER_REPAIRED | player="..tostring(name or pid).." | rid="..tostring(rid)) end
            end
        end
    end

    -- The old classifier only upgrades. Recalculate directly after removing false evidence.
    if startup.session_activity and type(startup.session_activity.classifications)=="table" then
        startup.session_activity.classifications[pid]=nil
        local classification="normal"
        if startup.session_activity_classify_player then
            local ok,v=direct_call(startup.session_activity_classify_player,pid,name)
            if ok and v then classification=tostring(v) end
        end
        startup.session_activity.classifications[pid]=classification
        for _,entry in ipairs(startup.session_activity.entries or {}) do
            if tonumber(entry and entry.playerId)==pid or (name~="" and tostring(entry and entry.name or ""):lower()==name:lower()) then entry.classification=classification end
        end
    end
end

-- Filter ModderDB reasons before they can feed Browser security summaries or the HUD.
if startup.cherax_modder_reasons_for_player and startup.b433.wrapped_reasons~=true then
    startup.b433.wrapped_reasons=true
    startup.b433.old_cherax_modder_reasons_for_player=startup.cherax_modder_reasons_for_player
    startup.cherax_modder_reasons_for_player=function(playerId)
        local reasons,count=startup.b433.old_cherax_modder_reasons_for_player(playerId)
        if type(reasons)~="table" then return reasons,count end
        local filtered={}
        local suppressed=false
        for _,reason in ipairs(reasons) do
            local drop=startup.b433_should_suppress_reason(playerId,reason)
            if drop then suppressed=true else filtered[#filtered+1]=reason end
        end
        if suppressed then
            local name=startup.get_player_name_safe and startup.get_player_name_safe(playerId) or ""
            startup.b433_repair_existing_false_positive(playerId,name)
        end
        return filtered,count
    end
end

-- Last-line guard for Cherax.log detections and every other path that records the
-- Modder HUD. This also prevents a quarantined explosion from setting RID flags.
if startup.modder_hud_record and startup.b433.wrapped_record~=true then
    startup.b433.wrapped_record=true
    startup.b433.old_modder_hud_record=startup.modder_hud_record
    startup.modder_hud_record=function(name,reason,playerId)
        local filtered,suppressed=startup.b433_filter_reason_text(playerId,reason)
        if suppressed then startup.b433_repair_existing_false_positive(playerId,name) end
        if filtered==nil or filtered=="" then return false end
        return startup.b433.old_modder_hud_record(name,filtered,playerId)
    end
end


