-- - Show Session Host OFF now suppresses Browser-derived and native Host lines.
-- - Event View Now opens the current EVENTS hub, clears hiding filters, selects
--   the exact event, and refreshes backend Events.
-- - Current runtime/browser branding is normalized to v1.0.18.
-- ===========================================================================


-- ===========================================================================
-- BUILD 436: v1.0.18 PRODUCTION HOTFIX - EVENT LIFECYCLE FEEDBACK
-- Verified attendees are prompted when an Event ends because the host:
--   * ends/cancels it manually;
--   * changes GTA Online sessions;
--   * stops publishing/goes offline.
-- RSVP/viewers remain ineligible. The host cannot rate their own Event.
-- ===========================================================================
startup.install_event_feedback_lifecycle_build436=function()
    startup.b436_event_feedback=startup.b436_event_feedback or {
        installed=false,
        ending={},
        attended_live={},
        last_status={},
        missing_since={},
        pending_request=false,
        last_attendance_nudge_ms=0,
    }
    local f=startup.b436_event_feedback
    if f.installed==true then return end
    f.installed=true

    local function nowms()
        if startup.browser_events_nowms then return tonumber(startup.browser_events_nowms()) or 0 end
        if startup.now then return tonumber(startup.now()) or 0 end
        if Time and Time.GetEpocheMs then return tonumber(Time.GetEpocheMs()) or 0 end
        return math.floor(os.clock()*1000)
    end
    local function yieldms(ms)
        if startup.yield then startup.yield(ms)
        elseif Script and Script.Yield then Script.Yield(ms) end
    end
    local function event_row(eventId)
        eventId=tostring(eventId or "")
        if eventId=="" then return nil end
        local eb=startup.browser_events_backend or {}
        for _,rows in ipairs({eb.events,eb.my_events,eb.history}) do
            for _,row in ipairs(type(rows)=="table" and rows or {}) do
                if type(row)=="table" and tostring(row.event_id or "")==eventId then return row end
            end
        end
        return nil
    end
    local function listing_is_live(listingId)
        listingId=tostring(listingId or "")
        if listingId=="" then return false end
        for _,row in ipairs(startup.browser and startup.browser.liveRows or {}) do
            if type(row)=="table" and tostring(row.listingId or row.listing_id or "")==listingId and row.live~=false then return true end
        end
        return false
    end
    local function clear_host_event_state(eventId)
        eventId=tostring(eventId or "")
        local eb=startup.browser_events_backend
        if type(eb)=="table" and tostring(eb.active_event_id or "")==eventId then
            eb.active_event_id=""
            eb.next_fetch_ms=0
            eb.next_private_fetch_ms=0
        end
        local ui=startup.browser_activity_ui_state or startup.activity_catalog_ui
        if type(ui)=="table" then
            ui.host_published=false
            ui.host_publish_started_ms=0
        end
        startup.browser_activity_publication=nil
        local bs=startup.browser_social_backend
        if type(bs)=="table" then
            bs.next_feed_ms=0
            bs.next_feedback_poll_ms=0
        end
    end
    local function request_pending_feedback(reason)
        local bs=startup.browser_social_backend
        local bb=startup.browser_backend
        if type(bs)~="table" or type(bb)~="table" or tostring(bb.token or "")=="" then return false end
        if type(bs.pending_feedback)=="table" or f.pending_request==true then return true end
        if not startup.browser_events_post then return false end
        f.pending_request=true
        local function run()
            local ok,err,data=startup.browser_events_post("event-feedback-pending.php",{})
            if ok then
                local rows=type(data)=="table" and type(data.pending)=="table" and data.pending or {}
                if type(rows[1])=="table" then
                    bs.pending_feedback=rows[1]
                    if startup.toast then startup.toast("Session feedback required — rate the Event you attended.",6000) end
                    if startup.log then startup.log("[Build 436] EVENT_FEEDBACK_READY | eventId="..tostring(rows[1].event_id or "").." | trigger="..tostring(reason or "EVENT_ENDED")) end
                end
            elseif startup.log then
                startup.log("[Build 436] EVENT_FEEDBACK_POLL_WAIT | trigger="..tostring(reason or "EVENT_ENDED").." | "..tostring(err or "pending not ready"))
            end
            bs.next_feedback_poll_ms=0
            f.pending_request=false
        end
        if Script and Script.QueueJob then Script.QueueJob(run) else run() end
        return true
    end
    startup.b436_request_pending_feedback=request_pending_feedback

    local function end_active_host_event(reason,synchronous)
        local eb=startup.browser_events_backend
        local bb=startup.browser_backend
        local eventId=tostring(type(eb)=="table" and eb.active_event_id or "")
        if eventId=="" or type(bb)~="table" or tostring(bb.token or "")=="" then return false end
        if f.ending[eventId]==true then return true end
        f.ending[eventId]=true
        reason=tostring(reason or "HOST_LEFT")
        local function run()
            local unpubOK,stateOK=false,false
            if startup.browser_events_post then
                local ok1,a1=pcall(startup.browser_events_post,"event-unpublish.php",{event_id=eventId,reason=reason})
                unpubOK=ok1 and a1==true
                local ok2,a2=pcall(startup.browser_events_post,"event-state.php",{event_id=eventId,action="CANCEL",reason=reason})
                stateOK=ok2 and a2==true
            end
            clear_host_event_state(eventId)
            if startup.log then startup.log("[Build 436] HOST_EVENT_ENDED | eventId="..eventId.." | reason="..reason.." | unpublish="..tostring(unpubOK).." | state="..tostring(stateOK)) end
            if startup.support_log_event_quiet then startup.support_log_event_quiet("BUILD436_HOST_EVENT_ENDED","event_id="..eventId.." reason="..reason.." unpublish="..tostring(unpubOK).." state="..tostring(stateOK)) end
            f.ending[eventId]=nil
        end
        if synchronous==true or not (Script and Script.QueueJob) then run() else Script.QueueJob(run) end
        return true
    end
    startup.b436_end_active_host_event=end_active_host_event

    -- Leaving the Browser host state is an Event-ending condition too.
    if startup.browser_backend_offline and f.offline_wrapped~=true then
        f.offline_wrapped=true
        f.old_browser_backend_offline=startup.browser_backend_offline
        startup.browser_backend_offline=function(...)
            end_active_host_event("HOST_OFFLINE",false)
            return f.old_browser_backend_offline(...)
        end
    end

    -- An actual GTA session change invalidates the old Event even if this user becomes
    -- Session Host again immediately in the next lobby.
    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_SESSION_CHANGE and f.session_hook~=true then
        f.session_hook=true
        EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE,function()
            end_active_host_event("HOST_SESSION_CHANGED",false)
        end)
    end

    -- Best-effort clean-offline fallback. Most normal unloads/offline paths are caught by
    -- browser_backend_offline above; this covers an explicit Startup unload while hosting.
    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_UNLOAD and f.unload_hook~=true then
        f.unload_hook=true
        EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD,function()
            end_active_host_event("HOST_STARTUP_UNLOADED",true)
        end)
    end

    -- Detect the attendee-side LIVE -> ended transition and ask the authoritative backend
    -- for its mandatory-feedback row immediately instead of waiting up to the normal poll.
    if startup.browser_social_refresh and f.social_refresh_wrapped~=true then
        f.social_refresh_wrapped=true
        f.old_browser_social_refresh=startup.browser_social_refresh
        startup.browser_social_refresh=function(...)
            local bs=startup.browser_social_backend or {}
            local before={}
            for id,meta in pairs(bs.events_by_id or {}) do
                if type(meta)=="table" then before[tostring(id)]={status=tostring(meta.status or ""):upper(),attendance=meta.attendance_verified==true} end
            end
            local ret=f.old_browser_social_refresh(...)
            bs=startup.browser_social_backend or bs
            local seen={}
            local n=nowms()
            for id,meta in pairs(bs.events_by_id or {}) do
                id=tostring(id); seen[id]=true
                if type(meta)=="table" then
                    local status=tostring(meta.status or ""):upper()
                    local attended=meta.attendance_verified==true
                    local isHost=meta.is_host==true
                    local rated=tostring(meta.my_feedback or "")~=""
                    local prev=before[id] and tostring(before[id].status or "") or tostring(f.last_status[id] or "")
                    if attended and not isHost and not rated then
                        if status=="LIVE" then
                            f.attended_live[id]=true
                            local listing=tostring(meta.listing_id or "")
                            if listing~="" and not listing_is_live(listing) then
                                if not f.missing_since[id] then f.missing_since[id]=n end
                                if n-tonumber(f.missing_since[id] or n)>=5000 then
                                    bs.next_feedback_poll_ms=0
                                    request_pending_feedback("HOST_LISTING_OFFLINE")
                                end
                            else
                                f.missing_since[id]=nil
                            end
                        elseif f.attended_live[id]==true or prev=="LIVE" then
                            f.missing_since[id]=nil
                            bs.next_feedback_poll_ms=0
                            request_pending_feedback("EVENT_STATUS_"..(status~="" and status or "ENDED"))
                        end
                    end
                    f.last_status[id]=status
                end
            end
            for id,old in pairs(before) do
                if old.status=="LIVE" and old.attendance==true and seen[id]~=true then
                    local meta=bs.events_by_id and bs.events_by_id[id] or nil
                    if not (type(meta)=="table" and meta.is_host==true) then
                        bs.next_feedback_poll_ms=0
                        request_pending_feedback("EVENT_REMOVED_FROM_FEED")
                    end
                end
            end
            return ret
        end
    end

    -- Keep LIVE attendance fresher than the older 15-second cadence so attendees who
    -- join near the end of an Event still become eligible before the host leaves.
    if Script and Script.QueueJob and f.worker_started~=true then
        f.worker_started=true
        Script.QueueJob(function()
            while true do
                local bs=startup.browser_social_backend
                local eb=startup.browser_events_backend
                local n=nowms()
                local activeId=tostring(type(eb)=="table" and eb.active_event_id or "")
                local attending=false
                if type(bs)=="table" then
                    for _,meta in pairs(bs.events_by_id or {}) do
                        if type(meta)=="table" and tostring(meta.status or ""):upper()=="LIVE" and (meta.attendance_verified==true or meta.going_by_me==true) then attending=true break end
                    end
                    if (activeId~="" or attending) and n-tonumber(f.last_attendance_nudge_ms or 0)>=5000 then
                        bs.next_attendance_ms=0
                        f.last_attendance_nudge_ms=n
                    end
                end
                yieldms(1000)
            end
        end)
    end

    if startup.log then startup.log("[Build 436] Event lifecycle feedback watcher installed") end
end
startup.install_event_feedback_lifecycle_build436()
startup.install_event_feedback_lifecycle_build436=nil



-- ============================================================================
-- BUILD 437: STARTUP VEHICLE SPEED HUD + DRIFTGOD AUTO-HIDE
-- - DriftGod-style plain vehicle-only speed readout directly below Connected Players.
-- - User-selectable MPH / KMH, saved in Startup config.
-- - Automatically hides Startup's speed HUD while DriftGod is running to avoid duplicates.
-- - Adds Garage HUD + Speed HUD controls to the Startup HUD tab.
-- ============================================================================
function startup.install_build437_speed_hud()
    startup.b437 = startup.b437 or {
        driftgod_running = false,
        last_driftgod_probe_ms = 0,
        render_wrapped = false,
        hud_config_wrapped = false,
    }
    local B = startup.b437

    if startup.s.speedHudEnabled == nil then startup.s.speedHudEnabled = true end
    startup.s.speedHudUnit = tostring(startup.s.speedHudUnit or "MPH"):upper()
    if startup.s.speedHudUnit ~= "MPH" and startup.s.speedHudUnit ~= "KMH" then startup.s.speedHudUnit = "MPH" end

    function startup.b437_driftgod_running(force)
        local now = startup.now and startup.now() or math.floor((os.clock and os.clock() or 0) * 1000)
        if force ~= true and (now - tonumber(B.last_driftgod_probe_ms or 0)) < 750 then
            return B.driftgod_running == true
        end
        B.last_driftgod_probe_ms = now

        local running = false
        pcall(function()
            if type(_G) == "table" then
                if type(rawget(_G, "DG")) == "table" or type(rawget(_G, "driftgod")) == "table" then running = true end
            end
        end)

        if not running and FeatureMgr and FeatureMgr.GetFeatureByName then
            local secondary_hits = 0
            local names = {"DriftGod License Plate", "Show MPH HUD", "Show Score HUD"}
            for _, name in ipairs(names) do
                local ok, feature = pcall(function() return FeatureMgr.GetFeatureByName(name) end)
                if ok and feature then
                    if name == "DriftGod License Plate" then
                        running = true
                        break
                    else
                        secondary_hits = secondary_hits + 1
                    end
                end
            end
            if not running and secondary_hits >= 2 then running = true end
        end

        B.driftgod_running = running
        return running
    end

    function startup.b437_vehicle_speed_mps()
        if not (Natives and Natives.InvokeInt and Natives.InvokeFloat) then return nil end
        local okPed, ped = pcall(Natives.InvokeInt, 0xD80958FC74E988A6) -- PLAYER_PED_ID
        if not okPed or type(ped) ~= "number" or ped == 0 then return nil end
        local okVeh, veh = pcall(Natives.InvokeInt, 0x9A9112A0FE9A4713, ped, false) -- GET_VEHICLE_PED_IS_IN
        if not okVeh or type(veh) ~= "number" or veh == 0 then return nil end
        local okSpeed, mps = pcall(Natives.InvokeFloat, 0xD5037BA82E12416F, veh) -- GET_ENTITY_SPEED
        if not okSpeed or type(mps) ~= "number" then return nil end
        if mps < 0 then mps = -mps end
        return mps
    end

    function startup.b437_render_speed_hud()
        if startup.s.speedHudEnabled == false then return end
        if startup.s.playerModUiEnabled == false or startup.s.sessionInfoHudEnabled ~= true then return end
        if startup.is_gta_online_session_ready and not startup.is_gta_online_session_ready() then return end
        if startup.b437_driftgod_running and startup.b437_driftgod_running(false) then return end

        local mps = startup.b437_vehicle_speed_mps and startup.b437_vehicle_speed_mps() or nil
        if type(mps) ~= "number" then return end

        local unit = tostring(startup.s.speedHudUnit or "MPH"):upper()
        if unit ~= "KMH" then unit = "MPH" end
        local multiplier = unit == "KMH" and 3.6 or 2.236936
        local value = math.floor((mps * multiplier) + 0.5)

        local x = tonumber(startup.hud_layout and startup.hud_layout.x or nil)
        if not x then x = startup.get_effective_hud_x(startup.s.sessionInfoHudX or 0.169) end
        local baseY = tonumber(startup.s.sessionInfoHudY or 0.941) or 0.941
        local scale = tonumber(startup.s.sessionInfoHudScale or 0.30) or 0.30
        local alpha = tonumber(startup.s.sessionInfoHudAlpha or 200) or 200
        local lineGap = tonumber(startup.hud_layout and startup.hud_layout.lineGap or nil) or math.max(0.020, scale * 0.075)
        local y = math.min(0.975, baseY + lineGap)

        startup.draw_hud_text(unit .. ": " .. tostring(value), x, y, scale, 255, 255, 255, alpha, 4)
    end

    if startup.h.SpeedHudToggle == nil then
        local speedToggle = startup.add_toggle(
            "SpeedHudToggle",
            "Speed HUD",
            "Shows vehicle speed directly below Connected Players. Automatically hidden while DriftGod is running.",
            function(f)
                startup.s.speedHudEnabled = f:IsToggled()
                if startup.s.initialized and startup.save_config then startup.save_config(false) end
            end,
            startup.s.speedHudEnabled ~= false
        )
        if speedToggle and speedToggle.SetSaveable then speedToggle:SetSaveable(false) end
    end

    if startup.h.SpeedHudUnit == nil then
        startup.add_combo(
            "SpeedHudUnit",
            "Speed Unit",
            "Choose whether Startup displays vehicle speed as MPH or KMH.",
            {"MPH", "KMH"},
            startup.s.speedHudUnit or "MPH",
            function(selected)
                selected = tostring(selected or "MPH"):upper()
                if selected ~= "KMH" then selected = "MPH" end
                startup.s.speedHudUnit = selected
                if startup.s.initialized and startup.save_config then startup.save_config(false) end
            end
        )
    end

    -- Draw after the normal Session HUD so this line sits directly below Connected Players.
    if startup.render_session_info_hud and B.render_wrapped ~= true then
        B.render_wrapped = true
        startup.b437_render_session_info_hud_base = startup.render_session_info_hud
        startup.render_session_info_hud = function(...)
            local ret = startup.b437_render_session_info_hud_base(...)
            direct_call(startup.b437_render_speed_hud)
            return ret
        end
    end

    -- HUD tab convenience panel. Garage HUD stays in Essentials too; this simply exposes
    -- its master toggle here, with the new speed controls directly underneath it.
    if startup.render_hud_config and B.hud_config_wrapped ~= true then
        B.hud_config_wrapped = true
        startup.b437_render_hud_config_base = startup.render_hud_config
        startup.render_hud_config = function(...)
            local ret = startup.b437_render_hud_config_base(...)
            if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Garage HUD / Speed HUD") then
                startup.section_title("Garage HUD")
                startup.render_feature_guarded_325(startup.h.EssentialsGarageOpen)
                ImGui.Separator()
                startup.section_title("Vehicle Speed HUD")
                startup.render_feature_guarded_325(startup.h.SpeedHudToggle)
                startup.render_feature_guarded_325(startup.h.SpeedHudUnit)
                if startup.b437_driftgod_running and startup.b437_driftgod_running(false) then
                    startup.subtle_text("DriftGod detected: Startup MPH / KMH is hidden to prevent duplicate gauges.")
                else
                    startup.subtle_text("Vehicle-only display • directly below Connected Players • no background panel")
                end
                ClickGUI.EndCustomChildWindow()
            end
            return ret
        end
    end

    if startup.log then startup.log("[Build 437] Speed HUD installed: MPH/KMH, below Connected Players, DriftGod auto-hide enabled.") end
end
startup.install_build437_speed_hud()
startup.install_build437_speed_hud=nil



-- ============================================================================
-- BUILD 438: PCALL CLEANUP / INTERNAL ERROR VISIBILITY
-- - Removes redundant pcall wrappers around trusted Startup-to-Startup calls.
-- - Keeps protected boundaries for Cherax/native/FeatureMgr/FileMgr/network/render callbacks.
-- - Preserves behavior; internal failures now surface instead of being silently swallowed.
-- ============================================================================


-- ===========================================================================
-- BUILD 439: PTFX / STUN GUN NON-MODDER POLICY
-- PTFX and Stun Gun detections remain available to Cherax protections/logging,
-- but they are never Startup modder evidence and cannot set the Modders HUD/RID
-- modder classification by themselves. Also cleans stale noise-only RID records.
-- ===========================================================================
startup.b439 = startup.b439 or {}

function startup.b439_is_noise_reason(reason)
    if startup.mod_detection and startup.mod_detection.is_non_modder_noise_reason then
        return startup.mod_detection.is_non_modder_noise_reason(reason) == true
    end
    local text = tostring(reason or ""):lower():gsub("[_%-]+", " "):gsub("%s+", " ")
    local compact = text:gsub("[^%a%d]", "")
    return text:find("ptfx", 1, true) ~= nil
        or text:find("stun gun", 1, true) ~= nil
        or compact:find("stungun", 1, true) ~= nil
end

function startup.b439_filter_reason_text(text)
    local kept = {}
    for part in tostring(text or ""):gmatch("[^|]+") do
        part = part:gsub("^%s+", ""):gsub("%s+$", "")
        if part ~= "" and not startup.b439_is_noise_reason(part) then
            kept[#kept + 1] = part
        end
    end
    return table.concat(kept, " | ")
end

-- Last-line protection for any older/direct caller that reaches the HUD recorder.
if startup.modder_hud_record and startup.b439.wrapped_record ~= true then
    startup.b439.wrapped_record = true
    startup.b439.old_modder_hud_record = startup.modder_hud_record
    startup.modder_hud_record = function(name, reason, playerId)
        local filtered = startup.b439_filter_reason_text(reason)
        if filtered == "" then
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("MODDER_REASON_SUPPRESSED", "player=" .. tostring(name or playerId or "Unknown") .. " reason=" .. tostring(reason or "") .. " policy=B439_PTFX_STUN_GUN")
            end
            return false
        end
        return startup.b439.old_modder_hud_record(name, filtered, playerId)
    end
end

-- Clean stale Startup RID records that were created only from PTFX/Stun Gun noise.
function startup.b439_cleanup_rid_noise()
    if not startup.rid_store or type(startup.rid_store.data) ~= "table" then return 0 end
    local changed = 0
    for _, entry in pairs(startup.rid_store.data) do
        if type(entry) == "table" then
            local entryChanged = false
            entry.flags = type(entry.flags) == "table" and entry.flags or {}
            entry.reasons = type(entry.reasons) == "table" and entry.reasons or {}
            entry.events = type(entry.events) == "table" and entry.events or {}

            for reason in pairs(entry.reasons) do
                if startup.b439_is_noise_reason(reason) then
                    entry.reasons[reason] = nil
                    entryChanged = true
                end
            end

            for i = #entry.events, 1, -1 do
                local ev = entry.events[i]
                if type(ev) == "table" and tostring(ev.event or ""):lower():find("modder", 1, true)
                    and startup.b439_is_noise_reason(ev.reason) then
                    table.remove(entry.events, i)
                    entryChanged = true
                end
            end

            local hard = entry.blockJoin == true
                or entry.flags.crashAttacker == true
                or entry.flags.kickAttacker == true
                or entry.flags.battleye == true
                or entry.flags.blockRidJoin == true
                or entry.flags.nuked == true

            local otherModderEvidence = false
            for _, ev in ipairs(entry.events) do
                if type(ev) == "table" and tostring(ev.event or ""):lower():find("modder", 1, true)
                    and not startup.b439_is_noise_reason(ev.reason) then
                    otherModderEvidence = true
                    break
                end
            end
            if not otherModderEvidence then
                for reason in pairs(entry.reasons) do
                    if not startup.b439_is_noise_reason(reason) then
                        local category, known = "", false
                        if startup.mod_detection and startup.mod_detection.classify_reason then
                            category, known = startup.mod_detection.classify_reason(reason)
                        end
                        if known == true and category ~= "ignored" then
                            otherModderEvidence = true
                            break
                        end
                    end
                end
            end

            if entry.flags.modder == true and not hard and not otherModderEvidence then
                entry.flags.modder = false
                entryChanged = true
            end

            if startup.b439_is_noise_reason(entry.lastReason) and tostring(entry.lastEvent or ""):lower():find("modder", 1, true) then
                local latest = entry.events[#entry.events]
                if type(latest) == "table" then
                    entry.lastEvent = tostring(latest.event or "")
                    entry.lastReason = tostring(latest.reason or "")
                    entry.lastAction = tostring(latest.action or "")
                else
                    entry.lastEvent, entry.lastReason, entry.lastAction = "", "", ""
                end
                entryChanged = true
            end

            if entryChanged then changed = changed + 1 end
        end
    end
    if changed > 0 and startup.rid_store.save then startup.rid_store.save() end
    return changed
end

function startup.b439_apply_existing_noise_cleanup()
    startup.b439.cleaned_rid_entries = startup.b439_cleanup_rid_noise()
    if startup.modder_hud and type(startup.modder_hud.entries) == "table" then
        for key, entry in pairs(startup.modder_hud.entries) do
            if type(entry) == "table" then
                local filtered = startup.b439_filter_reason_text(entry.reason)
                if filtered == "" then startup.modder_hud.entries[key] = nil else entry.reason = filtered end
            end
        end
        local order = {}
        for _, key in ipairs(startup.modder_hud.order or {}) do
            if startup.modder_hud.entries[key] then order[#order + 1] = key end
        end
        startup.modder_hud.order = order
    end
end
startup.b439_apply_existing_noise_cleanup()



