-- ============================================================================
-- BUILD 444: TRACKED PLAYER HUD RID / PLAYERTRACKER FIX
-- - Uses Cherax PlayerTracker\\SavedPlayers.json as the primary saved-player source.
-- - Matches current-session players by Rockstar RID first, normalized username second.
-- - Keeps the live Saved Players selector as a compatibility fallback.
-- - Does not use Startup's automatic RID/modder history for Tracked HUD membership.
-- ============================================================================
startup.install_tracked_hud_fix_build444=function()
    startup.b444_tracked=startup.b444_tracked or {last_source="",saved_count=0,matched_count=0,last_error=""}

    local function trim(v)
        return tostring(v or ""):gsub("^%s+",""):gsub("%s+$","")
    end

    local function lower(v)
        return trim(v):lower()
    end

    local function norm_rid(v)
        local n=tonumber(v)
        if n and n>0 then return tostring(math.floor(n)) end
        local s=trim(v):gsub("[^0-9]","")
        if s~="" and tonumber(s) and tonumber(s)>0 then return tostring(math.floor(tonumber(s))) end
        return ""
    end

    local function player_rid(pid)
        if startup.presence and startup.presence.get_player_rid then
            local ok,v=direct_call(startup.presence.get_player_rid,pid)
            if ok then
                local key=norm_rid(v)
                if key~="" then return key end
            end
        end
        if startup.regional_warfare_get_rid then
            local ok,v=direct_call(startup.regional_warfare_get_rid,pid)
            if ok then
                local key=norm_rid(v)
                if key~="" then return key end
            end
        end
        if Players and Players.GetRockstarId then
            local ok,v=direct_call(Players.GetRockstarId,pid)
            if ok then return norm_rid(v) end
        end
        if Players and Players.GetById then
            local ok,obj=direct_call(Players.GetById,pid)
            if ok and obj then
                local okInfo,info=direct_call(function()
                    if obj.GetGamerInfo then return obj:GetGamerInfo() end
                    return nil
                end)
                if okInfo and info then
                    local okRid,rid=direct_call(function() return info.RockstarId end)
                    if okRid then return norm_rid(rid) end
                end
            end
        end
        return ""
    end

    local function decode_json(body)
        local bb=startup.browser_backend or {}
        if type(bb._json_decode)=="function" then
            local ok,v=direct_call(bb._json_decode,tostring(body or ""))
            if ok and type(v)=="table" then return v end
        end
        return nil
    end

    local function read_savedplayers_disk()
        local byRid,byName={},{}
        local root=tostring(startup.menu_root or "")
        if root=="" and FileMgr and FileMgr.GetMenuRootPath then
            local ok,v=direct_call(FileMgr.GetMenuRootPath)
            if ok then root=tostring(v or "") end
        end
        if root=="" then return byRid,byName,0,"menu_root_unavailable" end
        local path=root.."\\PlayerTracker\\SavedPlayers.json"
        local body=nil
        if FileMgr and FileMgr.ReadFileContent then
            local ok,v=direct_call(FileMgr.ReadFileContent,path)
            if ok and type(v)=="string" and v~="" then body=v end
        end
        if not body then
            local ok,f=pcall(io.open,path,"rb")
            if ok and f then body=f:read("*a"); f:close() end
        end
        if type(body)~="string" or body=="" then return byRid,byName,0,"savedplayers_file_unavailable" end
        local data=decode_json(body)
        if type(data)~="table" then return byRid,byName,0,"savedplayers_json_decode_failed" end
        local count=0
        for key,row in pairs(data) do
            if type(row)=="table" then
                local rid=norm_rid(row.rid or row.rockstar_id or row.rockstarId or row.rockstar_rid or key)
                local name=trim(row.username or row.name or row.player_name or row.playerName or row.rockstar_name or row.rockstarName)
                if rid~="" then byRid[rid]=true end
                if name~="" then byName[lower(name)]=true end
                if rid~="" or name~="" then count=count+1 end
            elseif type(row)=="string" then
                local name=trim(row)
                if name~="" then byName[lower(name)]=true; count=count+1 end
            end
        end
        return byRid,byName,count,"disk"
    end

    local function add_selector_fallback(byName)
        local nk=startup.nuke_join_kick
        if not nk or not nk.find_global_feature_by_names or not nk.get_list then return 0 end
        local selector,selectorName=nk.find_global_feature_by_names(nk.saved_players_selector_names or {
            "Saved Players","Saved Player","Player Tracker","Tracked Players","SCAPI Saved Players"
        })
        if not selector then return 0 end
        local list=nk.get_list(selector,selectorName or "Saved Players")
        if type(list)~="table" then return 0 end
        local added=0
        for _,label in pairs(list) do
            local raw=trim(label)
            if raw~="" then
                local normalized=raw
                    :gsub("^%b[]%s*","")
                    :gsub("%s*%b[]$","")
                    :gsub("^%b()%s*","")
                    :gsub("%s*%b()$","")
                    :gsub("%s+%(%d+%)$","")
                    :gsub("%s+%[%d+%]$","")
                normalized=trim(normalized)
                if normalized~="" and not byName[lower(normalized)] then
                    byName[lower(normalized)]=true
                    added=added+1
                end
                -- Also retain raw label for exact-name Cherax builds.
                byName[lower(raw)]=true
            end
        end
        return added
    end

    function startup.get_tracked_players_in_gta()
        local byRid,byName,savedCount,source=read_savedplayers_disk()
        local fallbackAdded=add_selector_fallback(byName)
        if savedCount==0 and fallbackAdded>0 then source="selector" elseif fallbackAdded>0 then source="disk+selector" end

        local found,seen={},{}
        for _,playerId in ipairs(startup.get_voice_player_ids()) do
            local name=trim(startup.get_player_name_safe(playerId))
            if name~="" and name~="Invalid" then
                local rid=player_rid(playerId)
                local key=lower(name)
                local matched=(rid~="" and byRid[rid]==true) or byName[key]==true
                if matched and not seen[key] then
                    seen[key]=true
                    found[#found+1]=name
                end
            end
        end
        table.sort(found,function(a,b) return a:lower()<b:lower() end)
        startup.b444_tracked.last_source=source
        startup.b444_tracked.saved_count=savedCount+fallbackAdded
        startup.b444_tracked.matched_count=#found
        startup.b444_tracked.last_error=(source=="disk" or source=="disk+selector" or source=="selector") and "" or tostring(source or "")
        return found
    end

    -- Force a fresh cache read immediately after installing the corrected resolver.
    if startup.hud_cache then
        startup.hud_cache.lastTrackedPlayersUpdateMs=0
        startup.hud_cache.trackedPlayerNames={}
    end
    if startup.update_hud_cache then startup.update_hud_cache(true) end
end
startup.install_tracked_hud_fix_build444()
startup.install_tracked_hud_fix_build444=nil

