-- ============================================================================
-- v1.0.18 Production Build 446 - Regional Warfare Bounty Engine Fix
-- Fixes B445's over-strict NETWORK_IS_SESSION_* gate and makes bounty feature
-- resolution mirror Minigames more literally. Name lookup is primary; stable
-- Cherax player-feature hash 1613731913 is a fallback. Manual sweeps advance
-- through each enemy once instead of repeatedly selecting the first target.
-- ============================================================================
startup.regional_warfare_bounty_feature_hash = 1613731913
startup.regional_warfare_runtime = startup.regional_warfare_runtime or {}
startup.regional_warfare_runtime.forceSweepSeen = startup.regional_warfare_runtime.forceSweepSeen or {}
startup.regional_warfare_runtime.lastAttempt = startup.regional_warfare_runtime.lastAttempt or {}
startup.regional_warfare_runtime.lastFeatureSource = startup.regional_warfare_runtime.lastFeatureSource or ""
startup.regional_warfare_runtime.lastFeatureError = startup.regional_warfare_runtime.lastFeatureError or ""

function startup.regional_warfare_target_key(playerId, name, rid)
    rid = tostring(rid or "")
    if rid ~= "" then return "rid:" .. rid end
    return "slot:" .. tostring(tonumber(playerId) or -1) .. ":" .. string.lower(tostring(name or ""))
end

function startup.regional_warfare_player_present(playerId, expectedName)
    playerId = tonumber(playerId)
    if playerId == nil then return false end
    for _, id in ipairs(startup.get_voice_player_ids and startup.get_voice_player_ids() or {}) do
        if tonumber(id) == playerId then
            if expectedName and tostring(expectedName) ~= "" then
                local current = tostring(startup.get_player_name_safe(playerId) or "")
                if current ~= tostring(expectedName) then return false end
            end
            return true
        end
    end
    return false
end

function startup.regional_warfare_roster()
    local rows = {}
    for _, playerId in ipairs(startup.get_voice_player_ids and startup.get_voice_player_ids() or {}) do
        playerId = tonumber(playerId)
        if playerId ~= nil and not (startup.is_local_player_id and startup.is_local_player_id(playerId)) then
            local name = tostring(startup.get_player_name_safe(playerId) or ("Player " .. tostring(playerId)))
            local rid = startup.regional_warfare_get_rid and startup.regional_warfare_get_rid(playerId) or ""
            local language, source = startup.regional_warfare_player_language(playerId)
            local key = startup.regional_warfare_target_key(playerId, name, rid)
            rows[#rows + 1] = {
                playerId = playerId,
                rid = rid,
                key = key,
                name = name,
                language = language,
                faction = language,
                languageSource = source,
                enemy = startup.regional_warfare_is_enemy_faction(language)
            }
        end
    end
    table.sort(rows, function(a, b)
        return string.lower(tostring(a.name or "")) < string.lower(tostring(b.name or ""))
    end)
    return rows
end

function startup.regional_warfare_resolve_bounty_feature(playerId)
    if not FeatureMgr then return nil, "none", "FeatureMgr unavailable" end
    local feature = nil
    local nameErr = nil
    if FeatureMgr.GetFeatureByName then
        local ok, err = pcall(function()
            feature = FeatureMgr.GetFeatureByName("Set Bounty On Player", playerId)
        end)
        if ok and feature then return feature, "name", "" end
        nameErr = ok and "feature=nil" or tostring(err)
    else
        nameErr = "GetFeatureByName unavailable"
    end

    if FeatureMgr.GetFeature then
        local ok, err = pcall(function()
            feature = FeatureMgr.GetFeature(startup.regional_warfare_bounty_feature_hash, playerId)
        end)
        if ok and feature then return feature, "hash", "" end
        return nil, "hash", (ok and "feature=nil" or tostring(err)) .. " | name=" .. tostring(nameErr or "")
    end
    return nil, "name", tostring(nameErr or "GetFeature unavailable")
end

function startup.regional_warfare_apply_builtin_bounty(playerId, rid, name, language)
    playerId = tonumber(playerId)
    if playerId == nil or playerId < 0 or playerId > 31 then return false, "invalid player id" end
    if not startup.regional_warfare_player_present(playerId, name) then return false, "player no longer present" end

    local currentLanguage = startup.regional_warfare_player_language(playerId)
    if startup.regional_warfare_normalize_language(currentLanguage) ~= startup.regional_warfare_normalize_language(language) then
        return false, "player language changed"
    end

    -- RID is a stability check when available, but no longer a hard requirement.
    if tostring(rid or "") ~= "" and startup.regional_warfare_get_rid then
        local currentRid = tostring(startup.regional_warfare_get_rid(playerId) or "")
        if currentRid ~= "" and currentRid ~= tostring(rid) then return false, "player slot changed" end
    end

    local feature, source, resolveErr = startup.regional_warfare_resolve_bounty_feature(playerId)
    startup.regional_warfare_runtime.lastFeatureSource = tostring(source or "")
    startup.regional_warfare_runtime.lastFeatureError = tostring(resolveErr or "")
    if not feature then return false, "Set Bounty On Player unavailable: " .. tostring(resolveErr or "feature=nil") end

    -- Exact Minigames/WarGames action: call the Cherax player feature callback.
    local okTrigger, errTrigger = pcall(function()
        feature:TriggerCallback()
    end)
    if not okTrigger then return false, "TriggerCallback failed: " .. tostring(errTrigger) end
    return true, "Built-in 9k via " .. tostring(source or "feature")
end

function startup.regional_warfare_tick(force)
    local rw = startup.regional_warfare_runtime
    local manual = force == true or rw.forceSweep == true
    if startup.s.regionalWarfareEnabled ~= true then return end
    if startup.s.regionalWarfareAutoBounty ~= true and not manual then return end

    local own, ownSource = startup.regional_warfare_own_language()
    own = startup.regional_warfare_normalize_language(own)
    if own == "Unknown" then
        startup.s.regionalWarfareLastStatus = "My Player Language is unavailable. Choose My Warfare Language manually."
        return
    end

    -- B446 deliberately does not require NETWORK_IS_SESSION_ACTIVE/STARTED.
    -- A live remote roster is the readiness signal because some Cherax/GTA builds
    -- can enumerate players while those native probes still report false.
    local now = startup.now()
    local scanMs = math.max(500, tonumber(startup.s.regionalWarfareScanMs or 1000) or 1000)
    if not manual and now - (tonumber(rw.lastScanMs or 0) or 0) < scanMs then return end
    rw.lastScanMs = now

    local roster = startup.regional_warfare_roster()
    local current, enemies = {}, {}
    for _, row in ipairs(roster) do
        local key = tostring(row.key or startup.regional_warfare_target_key(row.playerId, row.name, row.rid))
        current[key] = true
        local previous = rw.lastLanguageByRid[key]
        if previous ~= row.language then
            rw.lastApplied[key] = 0
            rw.lastAttempt[key] = 0
            rw.lastLanguageByRid[key] = row.language
        end
        if rw.activeRids[key] ~= true then
            rw.lastApplied[key] = 0
            rw.lastAttempt[key] = 0
        end
        if row.enemy == true then enemies[#enemies + 1] = row end
    end
    rw.activeRids = current

    if #roster == 0 then
        startup.s.regionalWarfareLastStatus = "No remote players detected yet."
        rw.forceSweep = false
        rw.forceSweepSeen = {}
        return
    end
    if #enemies == 0 then
        startup.s.regionalWarfareLastStatus = "No enemy Player Language teams detected. My team: " .. tostring(own) .. " (" .. tostring(ownSource) .. ")"
        rw.forceSweep = false
        rw.forceSweepSeen = {}
        return
    end
    if rw.bountyInFlight == true then return end

    local gap = math.max(1000, tonumber(startup.s.regionalWarfareBountyGapMs or 2500) or 2500)
    if now - (tonumber(rw.lastBountyMs or 0) or 0) < gap then return end
    local refresh = math.max(60000, tonumber(startup.s.regionalWarfareBountyRefreshMs or 180000) or 180000)
    local retryMs = 5000
    local target = nil

    for _, row in ipairs(enemies) do
        local key = tostring(row.key or startup.regional_warfare_target_key(row.playerId, row.name, row.rid))
        local lastApplied = tonumber(rw.lastApplied[key] or 0) or 0
        local lastAttempt = tonumber(rw.lastAttempt[key] or 0) or 0
        if manual then
            if rw.forceSweepSeen[key] ~= true then target = row; break end
        elseif (lastApplied <= 0 or now - lastApplied >= refresh) and (lastAttempt <= 0 or now - lastAttempt >= retryMs) then
            target = row
            break
        end
    end

    if not target then
        if manual then
            rw.forceSweep = false
            rw.forceSweepSeen = {}
            startup.s.regionalWarfareLastStatus = "Enemy-language bounty sweep complete."
        else
            startup.s.regionalWarfareLastStatus = "Enemy languages present. Built-in 9k bounties maintained every 180 seconds."
        end
        return
    end

    local targetKey = tostring(target.key or startup.regional_warfare_target_key(target.playerId, target.name, target.rid))
    rw.bountyInFlight = true
    rw.lastBountyMs = now
    rw.lastAttempt[targetKey] = now

    local function job()
        local ok, status = startup.regional_warfare_apply_builtin_bounty(target.playerId, target.rid, target.name, target.language)
        if manual then rw.forceSweepSeen[targetKey] = true end
        if ok then
            rw.lastApplied[targetKey] = startup.now()
            startup.s.regionalWarfareLastBountyPlayer = tostring(target.name or "")
            startup.s.regionalWarfareLastBountyFaction = tostring(target.language or "")
            startup.s.regionalWarfareBountyCount = (tonumber(startup.s.regionalWarfareBountyCount or 0) or 0) + 1
            startup.s.regionalWarfareLastStatus = "Bounty applied: " .. tostring(target.name) .. " | " .. tostring(target.language) .. " | " .. tostring(status)
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("REGIONAL_WARFARE_BOUNTY", "player=" .. tostring(target.name) .. " player_id=" .. tostring(target.playerId) .. " rid=" .. tostring(target.rid) .. " language=" .. tostring(target.language) .. " method=Set_Bounty_On_Player amount=9k feature_source=" .. tostring(rw.lastFeatureSource))
            end
        else
            startup.s.regionalWarfareLastStatus = "Bounty failed: " .. tostring(target.name) .. " | " .. tostring(status)
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("REGIONAL_WARFARE_BOUNTY_FAIL", "player=" .. tostring(target.name) .. " player_id=" .. tostring(target.playerId) .. " rid=" .. tostring(target.rid) .. " language=" .. tostring(target.language) .. " error=" .. tostring(status) .. " feature_source=" .. tostring(rw.lastFeatureSource))
            end
        end
        rw.bountyInFlight = false
        rw.lastScanMs = 0
    end

    if Script and Script.QueueJob then
        local queued, queueErr = pcall(Script.QueueJob, job)
        if not queued then
            rw.bountyInFlight = false
            startup.s.regionalWarfareLastStatus = "Bounty queue failed; running direct fallback: " .. tostring(queueErr)
            job()
        end
    else
        job()
    end
end

function startup.regional_warfare_force_bounty_scan()
    local rw = startup.regional_warfare_runtime
    rw.forceSweep = true
    rw.forceSweepSeen = {}
    rw.lastScanMs = 0
    rw.lastBountyMs = 0
    startup.s.regionalWarfareLastStatus = "Starting enemy-language bounty sweep..."
    startup.regional_warfare_tick(true)
end

-- Reset potentially stuck B445 runtime state on hot-load/update.
startup.regional_warfare_runtime.bountyInFlight = false
startup.regional_warfare_runtime.forceSweep = false
startup.regional_warfare_runtime.forceSweepSeen = {}
startup.regional_warfare_runtime.lastScanMs = 0
startup.regional_warfare_runtime.lastBountyMs = 0
startup.regional_warfare_runtime.lastAttempt = {}

