-- ============================================================================
-- v1.0.18 Production Build 448 - Minigames Background Bounty Service
-- Current Minigames runs its heavy/feature scheduler inside one persistent
-- Script.QueueJob background worker rather than from Cherax's normal on-tick
-- callback. B448 gives Regional Warfare the same execution context.
-- ============================================================================
startup.regional_warfare_runtime = startup.regional_warfare_runtime or {}
startup.regional_warfare_runtime.backgroundEnabled = startup.regional_warfare_runtime.backgroundEnabled ~= false
startup.regional_warfare_runtime.backgroundRunning = false
startup.regional_warfare_runtime.inBackgroundService = false
startup.regional_warfare_runtime.backgroundLastError = ""
startup.regional_warfare_runtime.backgroundTickMs = 250

-- Preserve B447's direct one-target-per-pass engine as the background worker core.
startup.regional_warfare_tick_core_448 = startup.regional_warfare_tick

function startup.regional_warfare_background_pass_448(force)
    local rw = startup.regional_warfare_runtime
    rw.inBackgroundService = true
    local ok, err = pcall(startup.regional_warfare_tick_core_448, force == true)
    rw.inBackgroundService = false
    if not ok then
        rw.backgroundLastError = tostring(err)
        startup.s.regionalWarfareLastStatus = "Regional Warfare background error: " .. tostring(err)
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("REGIONAL_WARFARE_BACKGROUND_ERROR", tostring(err))
        end
        return false
    end
    return true
end

function startup.start_regional_warfare_background_448()
    local rw = startup.regional_warfare_runtime
    if rw.backgroundRunning == true then return true, "already-running" end
    if not (Script and Script.QueueJob) then
        rw.backgroundLastError = "Script.QueueJob unavailable"
        return false, rw.backgroundLastError
    end

    rw.backgroundEnabled = true
    rw.backgroundRunning = true
    local okQueue, queueErr = pcall(Script.QueueJob, function()
        while startup.regional_warfare_runtime and startup.regional_warfare_runtime.backgroundEnabled ~= false do
            if ShouldUnload and ShouldUnload() then break end

            startup.regional_warfare_background_pass_448(false)

            if Script and Script.Yield then
                Script.Yield(tonumber(startup.regional_warfare_runtime.backgroundTickMs or 250) or 250)
            else
                break
            end
        end
        if startup.regional_warfare_runtime then
            startup.regional_warfare_runtime.inBackgroundService = false
            startup.regional_warfare_runtime.backgroundRunning = false
        end
    end)

    if not okQueue then
        rw.backgroundRunning = false
        rw.backgroundLastError = tostring(queueErr)
        return false, tostring(queueErr)
    end
    return true, "queued"
end

-- Old B443 RegisterLooped callback still exists in the runtime and dynamically
-- calls this name. Make that callback a lightweight wake-up only. All actual
-- FeatureMgr bounty work is confined to the persistent QueueJob worker above.
function startup.regional_warfare_tick(force)
    local rw = startup.regional_warfare_runtime
    if force == true then
        rw.forceSweep = true
        rw.forceSweepSeen = {}
        rw.lastScanMs = 0
        rw.lastBountyMs = 0
        startup.s.regionalWarfareLastStatus = "Starting enemy-language bounty sweep in background service..."
    end

    if rw.inBackgroundService == true then
        return startup.regional_warfare_tick_core_448(force == true)
    end

    if rw.backgroundRunning ~= true then
        startup.start_regional_warfare_background_448()
    end
    return
end

function startup.regional_warfare_force_bounty_scan()
    local rw = startup.regional_warfare_runtime
    rw.forceSweep = true
    rw.forceSweepSeen = {}
    rw.lastScanMs = 0
    rw.lastBountyMs = 0
    rw.lastAttempt = {}
    rw.lastApplied = {}
    startup.s.regionalWarfareLastStatus = "Starting enemy-language bounty sweep in Minigames-style background service..."

    local started, err = startup.start_regional_warfare_background_448()
    if started ~= true and rw.backgroundRunning ~= true then
        startup.s.regionalWarfareLastStatus = "Regional Warfare background service unavailable: " .. tostring(err)
    end
end

-- Start the service once at load. It remains lightweight while Regional Warfare
-- is OFF because the core immediately returns before player/bounty work.
startup.regional_warfare_runtime.bountyInFlight = false
startup.regional_warfare_runtime.forceSweep = false
startup.regional_warfare_runtime.forceSweepSeen = {}
startup.regional_warfare_runtime.lastScanMs = 0
startup.regional_warfare_runtime.lastBountyMs = 0
startup.regional_warfare_runtime.lastAttempt = {}
startup.regional_warfare_runtime.lastApplied = {}
startup.start_regional_warfare_background_448()

