-- ============================================================================
-- v1.0.18 Production Build 449 - Language Marker Colors + Direct Bounty Runtime
-- B448 still wrapped the actual Cherax player-feature callback in pcall layers.
-- Current Minigames v1.0.0 intentionally uses direct runtime calls. B449 mirrors
-- that behavior, adds short retries, and adds per-language minimap blip colors.
-- ============================================================================
function startup.install_regional_warfare_build449()
    startup.regional_warfare_runtime = startup.regional_warfare_runtime or {}
    local rw = startup.regional_warfare_runtime

    startup.regional_warfare_color_names = {
        "White", "Gray", "Red", "Light Red", "Blue", "Light Blue",
        "Yellow", "Light Yellow", "Orange", "Light Orange", "Green",
        "Light Green", "Purple", "Light Purple", "Pink"
    }
    startup.regional_warfare_color_ids = {
        ["White"]=1, ["Gray"]=3, ["Red"]=6, ["Light Red"]=7,
        ["Blue"]=9, ["Light Blue"]=10, ["Yellow"]=12, ["Light Yellow"]=13,
        ["Orange"]=15, ["Light Orange"]=16, ["Green"]=18, ["Light Green"]=19,
        ["Purple"]=21, ["Light Purple"]=22, ["Pink"]=24
    }
    startup.regional_warfare_default_language_colors = {
        ["English"]="Green", ["French"]="Light Blue", ["German"]="Yellow",
        ["Italian"]="Light Green", ["Spanish"]="Orange", ["Brazilian"]="Light Green",
        ["Polish"]="Light Red", ["Russian"]="Blue", ["Korean"]="Light Blue",
        ["Japanese"]="Pink", ["Mexican"]="Orange",
        ["Chinese Traditional"]="Red", ["Chinese Simplified"]="Red", ["Unknown"]="Purple"
    }

    startup.s.regionalWarfareLanguageColors = type(startup.s.regionalWarfareLanguageColors)=="table" and startup.s.regionalWarfareLanguageColors or {}
    for language,colorName in pairs(startup.regional_warfare_default_language_colors) do
        if startup.regional_warfare_color_ids[tostring(startup.s.regionalWarfareLanguageColors[language] or "")] == nil then
            startup.s.regionalWarfareLanguageColors[language]=colorName
        end
    end
    if startup.s.regionalWarfareColorPlayers == nil then startup.s.regionalWarfareColorPlayers=true end

    function startup.regional_warfare_color_name(language)
        language=startup.regional_warfare_normalize_language(language)
        local value=tostring(startup.s.regionalWarfareLanguageColors[language] or startup.regional_warfare_default_language_colors[language] or "Gray")
        if startup.regional_warfare_color_ids[value]==nil then value="Gray" end
        return value
    end

    function startup.regional_warfare_color_id(language)
        return startup.regional_warfare_color_ids[startup.regional_warfare_color_name(language)] or 3
    end

    -- Register color controls after the base Regional Warfare features exist.
    if startup.h.RegionalWarfareColorPlayers == nil then
        startup.add_toggle("RegionalWarfareColorPlayers","Color Players By Language","Locally recolors remote-player minimap blips using each detected Player Language. Disable to restore the colors Startup observed before applying warfare colors.",function(f)
            startup.s.regionalWarfareColorPlayers=f:IsToggled()
            rw.lastBlipColorScanMs=0
            if startup.s.regionalWarfareColorPlayers~=true and startup.regional_warfare_restore_blip_colors_449 then
                startup.regional_warfare_restore_blip_colors_449()
            end
            if startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
        end,startup.s.regionalWarfareColorPlayers~=false)
    end

    for _,language in ipairs(startup.regional_warfare_languages or {}) do
        if language~="Auto (Player Language)" then
            local languageName=language
            local featureKey="RegionalWarfareColor_"..startup.regional_warfare_feature_key(languageName)
            if startup.h[featureKey]==nil then
                startup.add_combo(featureKey,languageName.." Color","Minimap/player blip color used locally for players whose Cherax Player Language is "..languageName..".",startup.regional_warfare_color_names,startup.regional_warfare_color_name(languageName),function(selected)
                    startup.s.regionalWarfareLanguageColors[languageName]=tostring(selected or "Gray")
                    rw.lastBlipColorScanMs=0
                    if startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
                end)
            end
        end
    end

    rw.blipOriginal = rw.blipOriginal or {}
    rw.blipApplied = rw.blipApplied or {}
    rw.lastBlipColorScanMs = 0

    function startup.regional_warfare_player_ped_449(playerId)
        if not (Natives and Natives.InvokeInt) then return 0 end
        return tonumber(Natives.InvokeInt(0x50FAC3A3E030A6E1, tonumber(playerId) or -1) or 0) or 0
    end

    function startup.regional_warfare_player_blip_449(playerId)
        local ped=startup.regional_warfare_player_ped_449(playerId)
        if ped==0 or not (Natives and Natives.InvokeInt) then return 0 end
        return tonumber(Natives.InvokeInt(0xBC8DBDCA2436F7E8, ped) or 0) or 0
    end

    function startup.regional_warfare_get_blip_color_449(blip)
        if tonumber(blip or 0)==0 or not (Natives and Natives.InvokeInt) then return nil end
        return tonumber(Natives.InvokeInt(0xDF729E8D20CF7327, blip))
    end

    function startup.regional_warfare_set_blip_color_449(blip,colorId)
        if tonumber(blip or 0)==0 or not (Natives and Natives.InvokeVoid) then return false end
        Natives.InvokeVoid(0x03D7FB09E75D6B7E, blip, tonumber(colorId) or 3)
        return true
    end

    function startup.regional_warfare_restore_blip_colors_449()
        for playerId,entry in pairs(rw.blipOriginal or {}) do
            if type(entry)=="table" then
                local blip=startup.regional_warfare_player_blip_449(playerId)
                if blip~=0 and tonumber(entry.blip or 0)==blip and tonumber(entry.color)~=nil then
                    startup.regional_warfare_set_blip_color_449(blip,entry.color)
                end
            end
        end
        rw.blipOriginal={}
        rw.blipApplied={}
    end

    function startup.regional_warfare_apply_blip_colors_449(force)
        local now=startup.now()
        if force~=true and now-(tonumber(rw.lastBlipColorScanMs or 0) or 0)<500 then return end
        rw.lastBlipColorScanMs=now

        if startup.s.regionalWarfareEnabled~=true or startup.s.regionalWarfareColorPlayers==false then
            if next(rw.blipOriginal or {})~=nil then startup.regional_warfare_restore_blip_colors_449() end
            return
        end

        local active={}
        for _,row in ipairs(startup.regional_warfare_roster() or {}) do
            local playerId=tonumber(row.playerId)
            if playerId~=nil then
                active[playerId]=true
                local blip=startup.regional_warfare_player_blip_449(playerId)
                if blip~=0 then
                    local original=rw.blipOriginal[playerId]
                    if type(original)~="table" or tonumber(original.blip or 0)~=blip then
                        rw.blipOriginal[playerId]={blip=blip,color=startup.regional_warfare_get_blip_color_449(blip)}
                    end
                    local desired=startup.regional_warfare_color_id(row.language)
                    if tonumber(rw.blipApplied[playerId] or -1)~=desired or force==true then
                        startup.regional_warfare_set_blip_color_449(blip,desired)
                        rw.blipApplied[playerId]=desired
                    end
                end
            end
        end

        for playerId,entry in pairs(rw.blipOriginal) do
            if active[playerId]~=true then
                rw.blipOriginal[playerId]=nil
                rw.blipApplied[playerId]=nil
            end
        end
    end

    -- Direct player-presence check. No protected wrapper around Cherax calls.
    function startup.regional_warfare_player_active_449(playerId)
        playerId=tonumber(playerId)
        if playerId==nil or playerId<0 or playerId>31 then return false end
        if Players and Players.GetById and Players.GetById(playerId)~=nil then return true end
        if NETWORK and NETWORK.NETWORK_IS_PLAYER_ACTIVE and NETWORK.NETWORK_IS_PLAYER_ACTIVE(playerId)==true then return true end
        if PLAYER and PLAYER.GET_PLAYER_NAME then
            local name=tostring(PLAYER.GET_PLAYER_NAME(playerId) or "")
            if name~="" and name~="NULL" and name~="**Invalid**" then return true end
        end
        return startup.is_local_player_id and startup.is_local_player_id(playerId) or false
    end

    function startup.regional_warfare_player_ids_449()
        local ids,seen={},{}
        local localId=startup.regional_warfare_local_player_id and startup.regional_warfare_local_player_id() or -1

        -- Match Minigames' authoritative roster refresh first. Besides giving us the
        -- same player IDs, this also asks Cherax to refresh its player list before
        -- resolving indexed player features such as Set Bounty On Player.
        if Players and Players.Get then
            local sortMode=(ePlayerListSort and ePlayerListSort.PLAYER_ID) or 0
            local players=Players.Get(sortMode,"")
            if type(players)=="table" then
                for _,playerId in pairs(players) do
                    playerId=tonumber(playerId)
                    if playerId~=nil and playerId>=0 and playerId<=31 and playerId~=localId and not seen[playerId] then
                        seen[playerId]=true; ids[#ids+1]=playerId
                    end
                end
            end
        end

        if #ids==0 then
            for playerId=0,31 do
                if playerId~=localId and startup.regional_warfare_player_active_449(playerId) and not seen[playerId] then
                    seen[playerId]=true; ids[#ids+1]=playerId
                end
            end
        end
        table.sort(ids)
        return ids
    end

    function startup.regional_warfare_roster()
        local rows={}
        for _,playerId in ipairs(startup.regional_warfare_player_ids_449()) do
            local name=tostring(startup.get_player_name_safe(playerId) or ("Player "..tostring(playerId)))
            local rid=startup.regional_warfare_get_rid and startup.regional_warfare_get_rid(playerId) or ""
            local language,source=startup.regional_warfare_player_language(playerId)
            local key=startup.regional_warfare_target_key(playerId,name,rid)
            rows[#rows+1]={playerId=playerId,rid=rid,name=name,language=language,faction=language,languageSource=source,key=key,enemy=startup.regional_warfare_is_enemy_faction(language)}
        end
        table.sort(rows,function(a,b) return string.lower(tostring(a.name or ""))<string.lower(tostring(b.name or "")) end)
        return rows
    end

    function startup.regional_warfare_apply_builtin_bounty(playerId,rid,name,language)
        playerId=tonumber(playerId)
        if playerId==nil or playerId<0 or playerId>31 then return false,"invalid player id" end
        if not startup.regional_warfare_player_active_449(playerId) then return false,"inactive player" end

        local currentLanguage=startup.regional_warfare_player_language(playerId)
        if startup.regional_warfare_normalize_language(currentLanguage)~=startup.regional_warfare_normalize_language(language) then
            return false,"player language changed"
        end
        if tostring(rid or "")~="" and startup.regional_warfare_get_rid then
            local currentRid=tostring(startup.regional_warfare_get_rid(playerId) or "")
            if currentRid~="" and currentRid~=tostring(rid) then return false,"player slot changed" end
        end

        -- If Minigames is actually loaded, use its exact production implementation first.
        local mg=_G.minigames or _G.MG
        if type(mg)=="table" and type(mg.ApplyBuiltInBounty)=="function" then
            local applied,status=mg.ApplyBuiltInBounty(playerId,true)
            if applied==true then return true,"Minigames built-in 9k" end
            rw.lastMinigamesBountyStatus=tostring(status or "failed")
        end

        if not (FeatureMgr and FeatureMgr.GetFeatureByName) then return false,"FeatureMgr unavailable" end
        local feature=FeatureMgr.GetFeatureByName("Set Bounty On Player",playerId)
        local source="name"
        if not feature and FeatureMgr.GetFeature then
            feature=FeatureMgr.GetFeature(1613731913,playerId)
            source="hash"
        end
        if not feature then return false,"Set Bounty On Player feature not found" end
        if type(feature.TriggerCallback)~="function" then return false,"TriggerCallback unavailable" end

        -- Important: do not wrap this in pcall/xpcall. Current Minigames v1.0.0
        -- executes runtime callbacks directly so Cherax callbacks can run in their
        -- normal fiber/job context.
        feature:TriggerCallback()
        return true,"Cherax built-in 9k via "..source
    end

    function startup.regional_warfare_apply_bounty_retry_449(target)
        local lastStatus="failed"
        for attempt=1,3 do
            if not startup.regional_warfare_player_active_449(target.playerId) then return false,"inactive" end
            local ok,status=startup.regional_warfare_apply_builtin_bounty(target.playerId,target.rid,target.name,target.language)
            lastStatus=tostring(status or "failed")
            if ok then return true,lastStatus.." • attempt "..tostring(attempt) end
            if attempt<3 and Script and Script.Yield then Script.Yield(450) end
        end
        return false,lastStatus
    end

    -- Preserve the B447 selector/maintenance engine, but swap the actual bounty
    -- action to the direct B449 implementation above.
    local previousCore=startup.regional_warfare_tick_core_448 or startup.regional_warfare_tick_core_448
    startup.regional_warfare_tick_core_449 = previousCore

    -- Replace only the apply function consumed dynamically by the preserved core.
    -- B447 core calls startup.regional_warfare_apply_builtin_bounty at action time.

    -- Replace B448 protected background pass with a direct pass. This is the critical
    -- difference from B448 and matches current Minigames' direct-call runtime policy.
    function startup.regional_warfare_background_pass_448(force)
        rw.inBackgroundService=true
        startup.regional_warfare_apply_blip_colors_449(false)
        startup.regional_warfare_tick_core_448(force==true)
        rw.inBackgroundService=false
        return true
    end

    -- Use retries by wrapping the action function without protecting TriggerCallback.
    local directApply=startup.regional_warfare_apply_builtin_bounty
    function startup.regional_warfare_apply_builtin_bounty(playerId,rid,name,language)
        return directApply(playerId,rid,name,language)
    end

    -- B447 core currently invokes one apply call. A direct failure due to transient
    -- feature availability should be retried. Override the core with an equivalent
    -- one-target selector that uses the retry helper and retains existing timing/state.
    function startup.regional_warfare_tick_core_448(force)
        local manual=force==true or rw.forceSweep==true
        if startup.s.regionalWarfareEnabled~=true then return end
        if startup.s.regionalWarfareAutoBounty~=true and not manual then return end

        local own,ownSource=startup.regional_warfare_own_language()
        own=startup.regional_warfare_normalize_language(own)
        if own=="Unknown" then
            startup.s.regionalWarfareLastStatus="My Player Language is unavailable. Choose My Warfare Language manually."
            return
        end

        local now=startup.now()
        local scanMs=math.max(500,tonumber(startup.s.regionalWarfareScanMs or 1000) or 1000)
        if not manual and now-(tonumber(rw.lastScanMs or 0) or 0)<scanMs then return end
        rw.lastScanMs=now

        local roster=startup.regional_warfare_roster()
        local current,enemies={},{}
        rw.lastLanguageByRid=rw.lastLanguageByRid or {}
        rw.activeRids=rw.activeRids or {}
        rw.lastApplied=rw.lastApplied or {}
        rw.lastAttempt=rw.lastAttempt or {}
        rw.forceSweepSeen=rw.forceSweepSeen or {}
        for _,row in ipairs(roster) do
            local key=tostring(row.key or startup.regional_warfare_target_key(row.playerId,row.name,row.rid))
            current[key]=true
            local previous=rw.lastLanguageByRid[key]
            if previous~=row.language then
                rw.lastApplied[key]=0; rw.lastAttempt[key]=0; rw.lastLanguageByRid[key]=row.language
            end
            if rw.activeRids[key]~=true then rw.lastApplied[key]=0; rw.lastAttempt[key]=0 end
            if row.enemy==true then enemies[#enemies+1]=row end
        end
        rw.activeRids=current

        if #roster==0 then
            startup.s.regionalWarfareLastStatus="No remote Cherax player objects detected yet."
            rw.forceSweep=false; rw.forceSweepSeen={}; return
        end
        if #enemies==0 then
            startup.s.regionalWarfareLastStatus="No enemy Player Language teams detected. My team: "..tostring(own).." ("..tostring(ownSource)..")"
            rw.forceSweep=false; rw.forceSweepSeen={}; return
        end

        local gap=math.max(1000,tonumber(startup.s.regionalWarfareBountyGapMs or 2500) or 2500)
        if now-(tonumber(rw.lastBountyMs or 0) or 0)<gap then return end
        local refresh=math.max(60000,tonumber(startup.s.regionalWarfareBountyRefreshMs or 180000) or 180000)
        local target=nil
        for _,row in ipairs(enemies) do
            local key=tostring(row.key or startup.regional_warfare_target_key(row.playerId,row.name,row.rid))
            local lastApplied=tonumber(rw.lastApplied[key] or 0) or 0
            local lastAttempt=tonumber(rw.lastAttempt[key] or 0) or 0
            if manual then
                if rw.forceSweepSeen[key]~=true then target=row; break end
            elseif (lastApplied<=0 or now-lastApplied>=refresh) and (lastAttempt<=0 or now-lastAttempt>=5000) then
                target=row; break
            end
        end

        if not target then
            if manual then
                rw.forceSweep=false; rw.forceSweepSeen={}
                startup.s.regionalWarfareLastStatus="Enemy-language bounty sweep complete."
            else
                startup.s.regionalWarfareLastStatus="Enemy languages present. Direct built-in 9k bounties maintained every 180 seconds."
            end
            return
        end

        local targetKey=tostring(target.key or startup.regional_warfare_target_key(target.playerId,target.name,target.rid))
        rw.lastBountyMs=now
        rw.lastAttempt[targetKey]=now
        local ok,status=startup.regional_warfare_apply_bounty_retry_449(target)
        if manual then rw.forceSweepSeen[targetKey]=true end
        if ok then
            rw.lastApplied[targetKey]=startup.now()
            startup.s.regionalWarfareLastBountyPlayer=tostring(target.name or "")
            startup.s.regionalWarfareLastBountyFaction=tostring(target.language or "")
            startup.s.regionalWarfareBountyCount=(tonumber(startup.s.regionalWarfareBountyCount or 0) or 0)+1
            startup.s.regionalWarfareLastStatus="Bounty callback fired: "..tostring(target.name).." | "..tostring(target.language).." | "..tostring(status)
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("REGIONAL_WARFARE_BOUNTY","player="..tostring(target.name).." player_id="..tostring(target.playerId).." rid="..tostring(target.rid).." language="..tostring(target.language).." amount=9k execution=direct_unprotected status="..tostring(status))
            end
        else
            startup.s.regionalWarfareLastStatus="Bounty failed: "..tostring(target.name).." | "..tostring(status)
            if startup.support_log_event_quiet then startup.support_log_event_quiet("REGIONAL_WARFARE_BOUNTY_FAIL","player="..tostring(target.name).." player_id="..tostring(target.playerId).." language="..tostring(target.language).." error="..tostring(status)) end
        end
        rw.lastScanMs=0
    end

    -- Re-start the B448 worker if a prior protected worker died. The loop itself is
    -- still one persistent Script.QueueJob; only its pass is now direct/unprotected.
    if rw.backgroundRunning~=true and startup.start_regional_warfare_background_448 then
        startup.start_regional_warfare_background_448()
    end

    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_UNLOAD and rw.blipUnloadHook449~=true then
        rw.blipUnloadHook449=true
        EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD,function()
            rw.backgroundEnabled=false
            startup.regional_warfare_restore_blip_colors_449()
        end)
    end
end
startup.install_regional_warfare_build449()
startup.install_regional_warfare_build449=nil

