-- ============================================================================
-- BUILD 450: RED DEATH LOG PRESENTATION
-- - Death Log activity-feed entries render vivid red instead of the generic color.
-- - Native GTA feed death messages use the ~r~ text tag.
-- - Death Log console output uses Startup's red/error logger where available.
-- - The Essentials Death Log heading uses the same stronger red treatment.
-- ============================================================================
function startup.install_red_death_logs_build450()
    if startup.b450_red_death_logs_installed == true then return end
    startup.b450_red_death_logs_installed = true

    local previousNativeText = startup.session_activity_native_text
    local previousContent = startup.session_activity_content

    function startup.session_activity_native_text(kind, name, reason)
        if tostring(kind or "") == "death" then
            return "~r~" .. tostring(name or "You died.") .. "~s~"
        end
        if previousNativeText then
            return previousNativeText(kind, name, reason)
        end
        return tostring(name or "")
    end

    function startup.session_activity_content(entry)
        if entry and tostring(entry.kind or "") == "death" then
            return tostring(entry.name or "You died."), "", {255, 55, 55}
        end
        if previousContent then
            return previousContent(entry)
        end
        return tostring(entry and entry.name or ""), tostring(entry and entry.reason or ""), {220,220,220}
    end
end
startup.install_red_death_logs_build450()
startup.install_red_death_logs_build450=nil

