-- ============================================================================
-- BUILD 451: MODDER DATABASE REPAIR + FALSE-POSITIVE HARDENING
-- - Stun Gun, Stun Vehicle Kick variants, Server Cash Wallet, PTFX, and
--   Invalid Interior Warp variants are never Startup modder evidence.
-- - Repairs historical RID records by removing only invalid modder evidence,
--   preserving independent crash/BattlEye/manual/block history.
-- - Noise-only RID records are removed entirely after a one-time backup.
-- - Adds a manual Repair Saved Modder Database button.
-- - Suspicious rank patterns are HUD-only corroborating hints and never save a
--   player as a modder by themselves.
-- - Confirmed crash attempts use Cherax Drop Kick first, with the previous
--   one-time crash response retained only as a fallback if Drop Kick is missing.
-- ============================================================================
function startup.install_modder_db_repair_build451()
    if startup.b451_modder_db_repair_installed == true then return end
    startup.b451_modder_db_repair_installed = true

    startup.b451 = startup.b451 or {}
    startup.b451.rankByPlayer = startup.b451.rankByPlayer or {}
    startup.b451.backupPath = tostring(startup.players_dir or "") .. "\\saved_players_pre_b451_backup.lua"

    function startup.b451_is_false_modder_reason(reason)
        local normalized = startup.mod_detection and startup.mod_detection.normalize_flag_name
            and startup.mod_detection.normalize_flag_name(reason)
            or tostring(reason or ""):lower():gsub("[_%-]+", " "):gsub("%s+", " ")
        local compact = tostring(normalized or ""):gsub("[^%a%d]", "")
        if normalized == "" then return false end

        if normalized:find("ptfx", 1, true) then return true end
        if normalized:find("stun gun", 1, true) or compact:find("stungun", 1, true) then return true end
        if normalized:find("stun vehicle kick", 1, true) or compact:find("stunvehiclekick", 1, true) then return true end
        if normalized:find("slight vehicle kick", 1, true) or compact:find("slightvehiclekick", 1, true) then return true end

        -- Server Cash Wallet is a RAC/account telemetry condition, not modder proof.
        if normalized:find("server cash wallet", 1, true)
            or compact:find("servercashwallet", 1, true)
            or compact:find("gameservercashwallet", 1, true)
            or compact:find("racservercashwallet", 1, true)
            or compact:find("raccashwallet", 1, true) then
            return true
        end
        if normalized:find("cash / wallet", 1, true)
            and (normalized:find("rac", 1, true) or normalized:find("server", 1, true)) then
            return true
        end

        -- Long-standing Startup policy: every Invalid Interior Warp spelling/variant is noise.
        if startup.mod_detection and startup.mod_detection.is_invalid_interior_warp_reason
            and startup.mod_detection.is_invalid_interior_warp_reason(reason) then
            return true
        end
        if compact:find("invalidinteriorwarp", 1, true) or compact:find("invaidinteriorwarp", 1, true) then
            return true
        end
        return false
    end

    -- Extend the canonical noise gate so every current caller inherits B451 policy.
    startup.b451.old_is_non_modder_noise_reason = startup.mod_detection.is_non_modder_noise_reason
    function startup.mod_detection.is_non_modder_noise_reason(reason)
        if startup.b451_is_false_modder_reason(reason) then return true end
        if startup.b451.old_is_non_modder_noise_reason then
            return startup.b451.old_is_non_modder_noise_reason(reason) == true
        end
        return false
    end

    function startup.b451_filter_modder_reason_text(text)
        local kept = {}
        local seen = {}
        for part in tostring(text or ""):gmatch("[^|]+") do
            part = part:gsub("^%s+", ""):gsub("%s+$", "")
            if part ~= "" and part ~= "Unknown" and part ~= "Cherax modder flag" then
                local falseNoise = startup.b451_is_false_modder_reason(part)
                local include = true
                if not falseNoise and startup.mod_detection and startup.mod_detection.should_include_reason then
                    local ok, result = direct_call(startup.mod_detection.should_include_reason, part)
                    if ok then include = result == true end
                end
                local key = part:lower()
                if not falseNoise and include and not seen[key] then
                    seen[key] = true
                    kept[#kept + 1] = part
                end
            end
        end
        return table.concat(kept, " | ")
    end

    function startup.b451_backup_rid_history_once()
        if not startup.rid_store or type(startup.rid_store.data) ~= "table" then return false end
        if startup.support_file_exists and startup.support_file_exists(startup.b451.backupPath) then return true end
        if not startup.try_write_file then return false end
        local content = "return " .. startup.serialize(startup.rid_store.data or {}, "") .. "\n"
        return startup.try_write_file(startup.b451.backupPath, content) == true
    end

    function startup.b451_repair_saved_modder_database(manual)
        if not startup.rid_store or type(startup.rid_store.data) ~= "table" then
            startup.s.ridHistoryLastStatus = "Modder DB repair unavailable: RID history is not loaded."
            return false
        end

        startup.b451_backup_rid_history_once()
        local data = startup.rid_store.data
        local changed, removedEntries, removedEvents, removedReasons, demoted = 0, 0, 0, 0, 0
        local removeRids = {}

        for rid, entry in pairs(data) do
            if type(entry) == "table" then
                local entryChanged = false
                entry.flags = type(entry.flags) == "table" and entry.flags or {}
                entry.reasons = type(entry.reasons) == "table" and entry.reasons or {}
                entry.events = type(entry.events) == "table" and entry.events or {}

                -- Rewrite/remove stored reason keys that came from Modder Detection.
                local rebuiltReasons = {}
                for reasonText, info in pairs(entry.reasons) do
                    local eventName = type(info) == "table" and tostring(info.event or "") or ""
                    if eventName:lower():find("modder", 1, true) then
                        local filtered = startup.b451_filter_modder_reason_text(reasonText)
                        if filtered ~= "" then
                            rebuiltReasons[filtered] = info
                            if filtered ~= tostring(reasonText) then entryChanged = true; removedReasons = removedReasons + 1 end
                        else
                            entryChanged = true
                            removedReasons = removedReasons + 1
                        end
                    else
                        rebuiltReasons[reasonText] = info
                    end
                end
                entry.reasons = rebuiltReasons

                -- Rewrite/remove Modder Detection events without touching independent evidence.
                for i = #entry.events, 1, -1 do
                    local ev = entry.events[i]
                    if type(ev) == "table" and tostring(ev.event or ""):lower():find("modder", 1, true) then
                        local filtered = startup.b451_filter_modder_reason_text(ev.reason)
                        if filtered == "" then
                            table.remove(entry.events, i)
                            entryChanged = true
                            removedEvents = removedEvents + 1
                        elseif filtered ~= tostring(ev.reason or "") then
                            ev.reason = filtered
                            entryChanged = true
                            removedReasons = removedReasons + 1
                        end
                    end
                end

                -- Recompute whether any valid Modder Detection evidence remains.
                local hasModderEvidence = false
                for _, ev in ipairs(entry.events) do
                    if type(ev) == "table" and tostring(ev.event or ""):lower():find("modder", 1, true)
                        and startup.b451_filter_modder_reason_text(ev.reason) ~= "" then
                        hasModderEvidence = true
                        break
                    end
                end
                if not hasModderEvidence then
                    for reasonText, info in pairs(entry.reasons) do
                        local eventName = type(info) == "table" and tostring(info.event or "") or ""
                        if eventName:lower():find("modder", 1, true)
                            and startup.b451_filter_modder_reason_text(reasonText) ~= "" then
                            hasModderEvidence = true
                            break
                        end
                    end
                end

                if entry.flags.modder == true and not hasModderEvidence then
                    entry.flags.modder = nil
                    entryChanged = true
                    demoted = demoted + 1
                elseif hasModderEvidence then
                    entry.flags.modder = true
                end

                -- If the latest item was removed/noised out, point last* at the latest surviving event.
                if tostring(entry.lastEvent or ""):lower():find("modder", 1, true) then
                    local filteredLast = startup.b451_filter_modder_reason_text(entry.lastReason)
                    if filteredLast == "" then
                        local latest = entry.events[#entry.events]
                        if type(latest) == "table" then
                            entry.lastEvent = latest.event
                            entry.lastReason = latest.reason
                            entry.lastAction = latest.action
                            entry.lastEventAt = latest.at
                            entry.lastEventDate = latest.date
                            entry.lastSignature = tostring(latest.event or "") .. "|" .. tostring(latest.reason or "") .. "|" .. tostring(latest.action or "")
                        else
                            entry.lastEvent, entry.lastReason, entry.lastAction = nil, nil, nil
                            entry.lastEventAt, entry.lastEventDate, entry.lastSignature = nil, nil, nil
                        end
                        entryChanged = true
                    elseif filteredLast ~= tostring(entry.lastReason or "") then
                        entry.lastReason = filteredLast
                        entryChanged = true
                    end
                end

                -- Remove records that existed only because of false Modder Detection evidence.
                local meaningfulFlags = false
                for flagName, flagValue in pairs(entry.flags) do
                    if flagValue == true and flagName ~= "modder" then meaningfulFlags = true; break end
                end
                local browserManual = entry.flags.browserManualBlock == true
                local hasHistory = #entry.events > 0 or next(entry.reasons) ~= nil
                if not hasHistory and entry.blockJoin ~= true and not meaningfulFlags and not browserManual then
                    removeRids[#removeRids + 1] = rid
                elseif entryChanged then
                    changed = changed + 1
                end
            end
        end

        for _, rid in ipairs(removeRids) do
            data[rid] = nil
            removedEntries = removedEntries + 1
        end
        changed = changed + removedEntries

        if changed > 0 and startup.rid_store.save then startup.rid_store.save() end
        if startup.modder_hud_clear then startup.modder_hud_clear() end

        local count = 0
        for _ in pairs(data) do count = count + 1 end
        startup.s.ridHistoryCount = count
        startup.b451.lastRepair = {
            changed = changed,
            removedEntries = removedEntries,
            removedEvents = removedEvents,
            removedReasons = removedReasons,
            demoted = demoted,
        }
        startup.s.ridHistoryLastStatus = "False-modder repair: " .. tostring(changed) .. " record(s) changed; "
            .. tostring(removedEntries) .. " noise-only removed; " .. tostring(demoted) .. " demoted."

        if manual == true and startup.toast then
            startup.toast(startup.s.ridHistoryLastStatus, 5500)
        end
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("MODDER_DB_REPAIR_B451",
                "changed=" .. tostring(changed)
                .. " removed_entries=" .. tostring(removedEntries)
                .. " removed_events=" .. tostring(removedEvents)
                .. " removed_reasons=" .. tostring(removedReasons)
                .. " demoted=" .. tostring(demoted)
                .. " backup=" .. tostring(startup.b451.backupPath))
        end
        return true
    end

    -- Best-effort remote rank reader. Rank hints are display-only corroboration;
    -- they never create/save a Modder Detection on their own.
    function startup.b451_read_player_rank(playerId)
        playerId = tonumber(playerId)
        if playerId == nil then return nil end
        local cached = startup.b451.rankByPlayer[playerId]
        if tonumber(cached) ~= nil then return math.floor(tonumber(cached)) end
        if not Players or not Players.GetById then return nil end
        local okP, player = direct_call(function() return Players.GetById(playerId) end)
        if not okP or not player then return nil end
        local value = nil
        direct_call(function() value = player.nCharacterRank end)
        if tonumber(value) == nil then
            direct_call(function()
                if player.PlayerInfo then value = player.PlayerInfo.nCharacterRank end
            end)
        end
        if tonumber(value) ~= nil then
            value = math.floor(tonumber(value))
            startup.b451.rankByPlayer[playerId] = value
            return value
        end
        return nil
    end

    function startup.b451_rank_hint(rank)
        rank = tonumber(rank)
        if rank == nil then return nil end
        rank = math.floor(rank)
        if rank == 0 or rank == 69 or rank == 666 or rank == 1337 or rank >= 8000 then
            return "Suspicious Rank " .. tostring(rank)
        end
        if rank == 1 then return "Rank 1 (needs combat/stat corroboration)" end
        if (rank >= 100 and rank <= 1000 and rank % 100 == 0)
            or (rank >= 1000 and rank <= 8000 and rank % 1000 == 0) then
            return "Round Rank " .. tostring(rank) .. " (soft hint)"
        end
        return nil
    end

    -- Capture the replicated character-rank node when Cherax exposes it.
    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_SYNC_DATA_NODE
        and startup.b451.rankNodeHooked ~= true then
        startup.b451.rankNodeHooked = true
        EventMgr.RegisterHandler(eLuaEvent.ON_SYNC_DATA_NODE, function(nodeType, node, pEntity, isExclusive, playerId)
            if not node or not eSyncDataNode or nodeType ~= eSyncDataNode.CPlayerGameStateDataNode then return end
            local id = tonumber(playerId or -1) or -1
            if id < 0 and pEntity and pEntity.NetObject then id = tonumber(pEntity.NetObject.PlayerId or -1) or -1 end
            if id < 0 or id > 31 then return end
            if tonumber(node.nCharacterRank) ~= nil then
                startup.b451.rankByPlayer[id] = math.floor(tonumber(node.nCharacterRank))
            end
        end)
    end

    -- Rank is appended only after a real accepted modder reason reaches the HUD recorder.
    if startup.modder_hud_record and startup.b451.rankHudWrapped ~= true then
        startup.b451.rankHudWrapped = true
        startup.b451.old_modder_hud_record = startup.modder_hud_record
        startup.modder_hud_record = function(name, reason, playerId)
            local result = startup.b451.old_modder_hud_record(name, reason, playerId)
            if result == false then return result end
            local rank = startup.b451_read_player_rank(playerId)
            local hint = startup.b451_rank_hint(rank)
            if hint and startup.modder_hud and startup.modder_hud.entries then
                local key = string.lower(tostring(name or ""))
                local entry = startup.modder_hud.entries[key]
                if entry then entry.reason = startup.modder_hud_merge_reason(entry.reason, hint) end
            end
            return result
        end
    end

    function startup.b451_drop_kick_player(playerId, reason)
        playerId = tonumber(playerId)
        if playerId == nil or playerId < 0 or playerId > 31 then return false, "invalid player" end
        if startup.crash_defense and startup.crash_defense.is_local_player_id
            and startup.crash_defense.is_local_player_id(playerId) then return false, "self blocked" end
        if not FeatureMgr then return false, "FeatureMgr unavailable" end

        local feature = nil
        if FeatureMgr.GetFeatureByName then
            local ok, value = direct_call(function() return FeatureMgr.GetFeatureByName("Drop Kick", playerId) end)
            if ok then feature = value end
        end
        if not feature and FeatureMgr.GetFeature then
            local ok, value = direct_call(function() return FeatureMgr.GetFeature(4291106761, playerId) end)
            if ok then feature = value end
        end
        if not feature then return false, "Drop Kick feature not found" end

        if feature.TriggerCallback then
            local ok, err = direct_call(function() feature:TriggerCallback() end)
            if ok then return true, "Drop Kick" end
            return false, tostring(err or "TriggerCallback failed")
        end
        if feature.OnClick then
            local ok, err = direct_call(function() feature:OnClick() end)
            if ok then return true, "Drop Kick" end
            return false, tostring(err or "OnClick failed")
        end
        return false, "Drop Kick callback unavailable"
    end

    -- Override the one-time crash response with Drop Kick as the primary defense.
    startup.b451.old_begin_one_time_crash_response = startup.crash_defense.begin_one_time_crash_response
    function startup.crash_defense.begin_one_time_crash_response(playerId, playerName, reason, source)
        local id = tonumber(playerId)
        if id == nil then return false end
        local name = tostring(playerName or "Unknown")
        local reasonText = tostring(reason or "Crash Attack")
        local key, rid = startup.crash_defense.response_identity_key(id, name)
        local currentSerial = tonumber(startup.crash_defense.response_session_serial or 0) or 0
        local existing = startup.crash_defense.responses_by_key[key]
        if type(existing) == "table" and tonumber(existing.sessionSerial or -1) == currentSerial
            and (existing.state == "pending" or existing.state == "complete" or existing.state == "exhausted") then
            startup.crash_defense.note_duplicate_response(existing, name, reasonText, source)
            return false
        end

        local _, hostId = startup.get_session_host_name()
        local now = startup.now()
        local record = {
            key=key, rid=rid, playerId=id, playerName=name, state="pending", attempts=0,
            evidenceCount=1, suppressedCount=0, startedMs=now, lastEvidenceMs=now,
            lastSummaryMs=now, lastReason=reasonText, source=tostring(source or "unknown"),
            isSessionHost=tonumber(hostId)==id, sessionSerial=currentSerial,
        }
        startup.crash_defense.responses_by_key[key] = record
        startup.s.crashDefenseLastPlayerId = id
        startup.s.crashDefenseLastPlayerName = name
        local hostLabel = record.isSessionHost and " (Session Host)" or ""
        startup.crash_defense.set_status("Crash detection: " .. name .. hostLabel .. " | Drop Kick defense started")

        if startup.s.saveRidCrash == true and startup.rid_store and startup.rid_store.record then
            startup.rid_store.record(id, "Crash Attempt", reasonText, "Drop Kick defense", true)
        end
        startup.log("[Crash Defense] " .. name .. hostLabel .. " triggered " .. reasonText .. "; attempting Drop Kick first.")

        local function job()
            record.attempts = 1
            local kicked, method = startup.b451_drop_kick_player(id, reasonText)
            if kicked then
                record.state = "complete"
                record.completedMs = startup.now()
                startup.modder_hud_record(name, reasonText, id)
                startup.session_activity_record("blocked", name, reasonText, 10000, {playerId=id, classification="known_modder"})
                startup.crash_defense.set_status("Crash attacker Drop Kicked: " .. name .. " | duplicates suppressed")
                if startup.support_log_event_quiet then
                    startup.support_log_event_quiet("CRASH_ATTACK_DROP_KICK_B451",
                        "player=" .. name .. " [" .. tostring(id) .. "] reason=" .. reasonText .. " method=" .. tostring(method))
                end
                return
            end

            -- Keep the existing proven one-time response only as a fallback when Drop Kick is unavailable.
            record.attempts = 2
            local fallback = startup.nuke_join_kick and startup.nuke_join_kick.run_for_player_id
                and startup.nuke_join_kick.run_for_player_id(id, true, reasonText .. " detected", true) == true
            if fallback then
                record.state = "complete"
                record.completedMs = startup.now()
                startup.modder_hud_record(name, reasonText, id)
                startup.session_activity_record("blocked", name, reasonText, 10000, {playerId=id, classification="known_modder"})
                startup.crash_defense.set_status("Crash attacker handled by fallback: " .. name .. " | Drop Kick unavailable")
            else
                record.state = "exhausted"
                record.completedMs = startup.now()
                startup.crash_defense.set_status("Crash response exhausted: " .. name .. " | Drop Kick/fallback unavailable")
            end
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("CRASH_ATTACK_DROP_KICK_FALLBACK_B451",
                    "player=" .. name .. " [" .. tostring(id) .. "] reason=" .. reasonText
                    .. " drop_kick=" .. tostring(method) .. " fallback=" .. tostring(fallback == true))
            end
        end
        if Script and Script.QueueJob then Script.QueueJob(job) else job() end
        return true
    end

    if startup.h.RepairSavedModderDatabase == nil and startup.add_button then
        startup.add_button(
            "RepairSavedModderDatabase",
            "Repair Saved Modder Database",
            "Creates a backup, removes stale false-positive Modder Detection evidence (PTFX, Stun Gun, Stun Vehicle Kick, Server Cash Wallet, Invalid Interior Warp and currently excluded noise), and preserves independent crash/BattlEye/manual history.",
            function() startup.b451_repair_saved_modder_database(true) end
        )
    end

    -- Run once on load; the operation is idempotent and the backup is created only once.
    startup.b451_repair_saved_modder_database(false)
end
startup.install_modder_db_repair_build451()
startup.install_modder_db_repair_build451=nil

-- Build 452: clearer social HUD colors.
-- Friends default to vivid green; manually tracked/saved players default to red.
-- Existing custom colors are preserved. Only the prior Startup defaults are migrated.
function startup.install_social_hud_colors_build452()
    startup.s.hudColors = startup.s.hudColors or {}

    local function matches(c, r, g, b)
        if type(c) ~= "table" then return false end
        return tonumber(c[1] or c["1"] or c.r) == r
            and tonumber(c[2] or c["2"] or c.g) == g
            and tonumber(c[3] or c["3"] or c.b) == b
    end

    local changed = false
    local friendColor = startup.s.hudColors.friends
    if friendColor == nil or matches(friendColor, 120, 255, 165) then
        startup.s.hudColors.friends = {70,255,95}
        changed = true
    end

    local trackedColor = startup.s.hudColors.trackedPlayers
    if trackedColor == nil or matches(trackedColor, 255, 145, 40) then
        startup.s.hudColors.trackedPlayers = {255,65,65}
        changed = true
    end

    if startup.hud_color_defaults then
        startup.hud_color_defaults.friends = {70,255,95}
        startup.hud_color_defaults.trackedPlayers = {255,65,65}
    end

    if changed and startup.s.initialized and startup.save_config then
        startup.save_config(false)
    end

    if startup.hud_color_sync_editor then startup.hud_color_sync_editor() end
end
startup.install_social_hud_colors_build452()
startup.install_social_hud_colors_build452=nil

