-- ============================================================================
-- BUILD 453: REGIONAL WARFARE BLIP COLOR PERSISTENCE
-- - B449 cached the desired color per player and skipped repeated writes.
-- - GTA/Cherax can subsequently restore player blips to their normal color.
-- - Keep a lightweight cached blip->color map and reassert it from render events.
-- - No player/language/FeatureMgr scans are performed from render callbacks.
-- ============================================================================
function startup.install_regional_warfare_blip_persistence_build453()
    startup.regional_warfare_runtime = startup.regional_warfare_runtime or {}
    local rw = startup.regional_warfare_runtime

    rw.blipFrameTargets453 = rw.blipFrameTargets453 or {}

    if startup.regional_warfare_restore_blip_colors_449 and rw.b453RestoreWrapped ~= true then
        rw.b453RestoreWrapped = true
        rw.b453PreviousRestore = startup.regional_warfare_restore_blip_colors_449
        function startup.regional_warfare_restore_blip_colors_449()
            rw.blipFrameTargets453 = {}
            local result = rw.b453PreviousRestore()
            rw.blipFrameTargets453 = {}
            return result
        end
    end

    if startup.regional_warfare_apply_blip_colors_449 and rw.b453ApplyWrapped ~= true then
        rw.b453ApplyWrapped = true
        rw.b453PreviousApply = startup.regional_warfare_apply_blip_colors_449
        function startup.regional_warfare_apply_blip_colors_449(force)
            local result = rw.b453PreviousApply(force)

            if startup.s.regionalWarfareEnabled ~= true or startup.s.regionalWarfareColorPlayers == false then
                rw.blipFrameTargets453 = {}
                return result
            end

            local frameTargets = {}
            for playerId, desired in pairs(rw.blipApplied or {}) do
                playerId = tonumber(playerId)
                desired = tonumber(desired)
                if playerId ~= nil and desired ~= nil and startup.regional_warfare_player_blip_449 then
                    local blip = tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0
                    if blip ~= 0 then
                        frameTargets[blip] = { playerId = playerId, color = desired }

                        -- B449's cache can say the right color even after GTA/Cherax
                        -- has overwritten the actual live blip. Verify live state.
                        local current = startup.regional_warfare_get_blip_color_449
                            and startup.regional_warfare_get_blip_color_449(blip) or nil
                        if tonumber(current) ~= desired and startup.regional_warfare_set_blip_color_449 then
                            startup.regional_warfare_set_blip_color_449(blip, desired)
                        end
                    end
                end
            end
            rw.blipFrameTargets453 = frameTargets
            return result
        end
    end

    function startup.regional_warfare_reassert_blip_colors_453()
        if startup.s.regionalWarfareEnabled ~= true or startup.s.regionalWarfareColorPlayers == false then return end
        if not (Natives and Natives.InvokeVoid) then return end

        -- Deliberately use only cached blip handles/colors here. Player/language
        -- discovery stays in the background Regional Warfare service.
        for blip, target in pairs(rw.blipFrameTargets453 or {}) do
            if tonumber(blip or 0) ~= 0 and type(target) == "table" and tonumber(target.color) ~= nil then
                Natives.InvokeVoid(0x03D7FB09E75D6B7E, tonumber(blip), tonumber(target.color))
            end
        end
    end

    -- ON_PRESENT runs at render cadence and is the authoritative color write.
    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_PRESENT and rw.b453PresentHook ~= true then
        rw.b453PresentHook = true
        EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
            startup.regional_warfare_reassert_blip_colors_453()
        end)
    end

    -- Reassert after presentation as well. This prevents another late render/update
    -- handler from leaving the wrong color cached into the following frame.
    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_POST_PRESENT and rw.b453PostPresentHook ~= true then
        rw.b453PostPresentHook = true
        EventMgr.RegisterHandler(eLuaEvent.ON_POST_PRESENT, function()
            startup.regional_warfare_reassert_blip_colors_453()
        end)
    end

    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_PLAYER_LEFT and rw.b453PlayerLeftHook ~= true then
        rw.b453PlayerLeftHook = true
        EventMgr.RegisterHandler(eLuaEvent.ON_PLAYER_LEFT, function(playerId)
            playerId = tonumber(playerId)
            rw.blipApplied[playerId] = nil
            rw.blipOriginal[playerId] = nil
            for blip, target in pairs(rw.blipFrameTargets453 or {}) do
                if type(target) == "table" and tonumber(target.playerId) == playerId then
                    rw.blipFrameTargets453[blip] = nil
                end
            end
        end)
    end

    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_SESSION_CHANGE and rw.b453SessionHook ~= true then
        rw.b453SessionHook = true
        EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE, function()
            rw.blipFrameTargets453 = {}
            rw.blipApplied = {}
            rw.blipOriginal = {}
            rw.lastBlipColorScanMs = 0
        end)
    end

    -- Populate the frame cache immediately when possible.
    if startup.regional_warfare_apply_blip_colors_449 then
        startup.regional_warfare_apply_blip_colors_449(true)
    end
end
startup.install_regional_warfare_blip_persistence_build453()
startup.install_regional_warfare_blip_persistence_build453=nil

