-- ============================================================================
-- v1.0.18 Production Build 454 - Custom RGB Language Blips
-- B453 used HUD-style numeric palette indexes with SET_BLIP_COLOUR. GTA Online
-- player blips attach semantic meaning to several stock color indexes, which can
-- make neutral players appear friend-blue and can conflict with CEO/MC colors.
-- B454 uses the documented custom-RGB blip path instead:
--   SET_BLIP_COLOUR(blip, 84)
--   SET_BLIP_SECONDARY_COLOUR(blip, r, g, b)
-- This changes only the visual color. It never toggles friendly/crew indicators.
-- ============================================================================
function startup.install_regional_warfare_custom_rgb_blips_build454()
    startup.regional_warfare_runtime = startup.regional_warfare_runtime or {}
    local rw = startup.regional_warfare_runtime

    startup.regional_warfare_color_rgb_454 = {
        ["White"]        = {255,255,255},
        ["Gray"]         = {165,165,175},
        ["Red"]          = {255,55,55},
        ["Light Red"]    = {255,125,125},
        ["Blue"]         = {55,135,255},
        ["Light Blue"]   = {105,205,255},
        ["Yellow"]       = {255,220,55},
        ["Light Yellow"] = {255,242,135},
        ["Orange"]       = {255,145,45},
        ["Light Orange"] = {255,190,105},
        ["Green"]        = {70,235,95},
        ["Light Green"]  = {135,255,160},
        ["Purple"]       = {175,85,255},
        ["Light Purple"] = {215,150,255},
        ["Pink"]         = {255,95,205}
    }

    function startup.regional_warfare_rgb_for_language_454(language)
        local colorName = startup.regional_warfare_color_name
            and startup.regional_warfare_color_name(language) or "Gray"
        local rgb = startup.regional_warfare_color_rgb_454[tostring(colorName)]
            or startup.regional_warfare_color_rgb_454.Gray
        return tonumber(rgb[1]) or 165, tonumber(rgb[2]) or 165, tonumber(rgb[3]) or 175, tostring(colorName)
    end

    function startup.regional_warfare_set_custom_blip_rgb_454(blip, r, g, b)
        blip = tonumber(blip or 0) or 0
        if blip == 0 or not (Natives and Natives.InvokeVoid) then return false end

        -- 84 is the GTA custom-RGB blip color path. The actual RGB is supplied
        -- through SET_BLIP_SECONDARY_COLOUR. Do not call SET_BLIP_AS_FRIENDLY,
        -- SHOW_FRIEND_INDICATOR_ON_BLIP, or SHOW_CREW_INDICATOR_ON_BLIP here.
        Natives.InvokeVoid(0x03D7FB09E75D6B7E, blip, 84)
        Natives.InvokeVoid(0x14892474891E09EB, blip,
            math.max(0, math.min(255, math.floor(tonumber(r) or 0))),
            math.max(0, math.min(255, math.floor(tonumber(g) or 0))),
            math.max(0, math.min(255, math.floor(tonumber(b) or 0))))
        return true
    end

    -- Replace B449/B453's stock-index color application. Player/language discovery
    -- remains on the slower background pass; this function only rebuilds the small
    -- cached blip target table used by the render hooks.
    function startup.regional_warfare_apply_blip_colors_449(force)
        local now = startup.now()
        if force ~= true and now - (tonumber(rw.lastBlipColorScanMs or 0) or 0) < 500 then return end
        rw.lastBlipColorScanMs = now

        if startup.s.regionalWarfareEnabled ~= true or startup.s.regionalWarfareColorPlayers == false then
            if next(rw.blipOriginal or {}) ~= nil and startup.regional_warfare_restore_blip_colors_449 then
                startup.regional_warfare_restore_blip_colors_449()
            end
            rw.blipFrameTargets453 = {}
            return
        end

        local active = {}
        local frameTargets = {}

        for _, row in ipairs(startup.regional_warfare_roster() or {}) do
            local playerId = tonumber(row.playerId)
            if playerId ~= nil then
                active[playerId] = true
                local blip = startup.regional_warfare_player_blip_449
                    and tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0

                if blip ~= 0 then
                    local original = rw.blipOriginal[playerId]
                    if type(original) ~= "table" or tonumber(original.blip or 0) ~= blip then
                        rw.blipOriginal[playerId] = {
                            blip = blip,
                            color = startup.regional_warfare_get_blip_color_449
                                and startup.regional_warfare_get_blip_color_449(blip) or nil
                        }
                    end

                    local r,g,b,colorName = startup.regional_warfare_rgb_for_language_454(row.language)
                    rw.blipApplied[playerId] = {
                        blip = blip,
                        r = r, g = g, b = b,
                        language = tostring(row.language or "Unknown"),
                        colorName = colorName
                    }
                    frameTargets[blip] = {
                        playerId = playerId,
                        r = r, g = g, b = b,
                        language = tostring(row.language or "Unknown"),
                        colorName = colorName
                    }
                    startup.regional_warfare_set_custom_blip_rgb_454(blip, r, g, b)
                end
            end
        end

        for playerId, entry in pairs(rw.blipOriginal or {}) do
            if active[playerId] ~= true then
                -- A player left or their slot changed. Do not restore a stale handle
                -- here because GTA may already have reassigned it; normal leave/session
                -- cleanup owns that lifecycle.
                rw.blipOriginal[playerId] = nil
                rw.blipApplied[playerId] = nil
            end
        end

        rw.blipFrameTargets453 = frameTargets
    end

    -- B453 already registered ON_PRESENT + ON_POST_PRESENT handlers. Override the
    -- function they call so those existing handlers now use the custom RGB path.
    function startup.regional_warfare_reassert_blip_colors_453()
        if startup.s.regionalWarfareEnabled ~= true or startup.s.regionalWarfareColorPlayers == false then return end
        if not (Natives and Natives.InvokeVoid) then return end

        for blip, target in pairs(rw.blipFrameTargets453 or {}) do
            if tonumber(blip or 0) ~= 0 and type(target) == "table" then
                startup.regional_warfare_set_custom_blip_rgb_454(
                    tonumber(blip), target.r, target.g, target.b)
            end
        end
    end

    -- Force a clean rebuild. The primary color captured by B449 is enough to
    -- restore Rockstar's normal player/CEO/MC color rules when coloring is disabled;
    -- the secondary RGB is ignored once the primary color is no longer custom 84.
    rw.blipFrameTargets453 = {}
    rw.blipApplied = {}
    rw.lastBlipColorScanMs = 0
    if startup.regional_warfare_apply_blip_colors_449 then
        startup.regional_warfare_apply_blip_colors_449(true)
    end
end
startup.install_regional_warfare_custom_rgb_blips_build454()
startup.install_regional_warfare_custom_rgb_blips_build454=nil

