-- ============================================================================
-- v1.0.18 Production Build 455 - Selected Player Auto Bounty
-- Exact selected-player bounty flow based on current Minigames v1.0.0:
-- RefreshPlayers / Players.Get -> Script.QueueJob -> ApplyBuiltInBounty(force=true)
-- -> FeatureMgr.GetFeatureByName("Set Bounty On Player", playerId)
-- -> TriggerCallback(). Auto maintenance repeats every 60 seconds.
-- ============================================================================
function startup.install_selected_player_auto_bounty_build455()
    startup.regional_warfare_runtime = startup.regional_warfare_runtime or {}
    local rw = startup.regional_warfare_runtime
    rw.b455SelectedBountyInFlight = false
    rw.b455SelectedBountyLastMs = 0
    rw.b455SelectedBountyRequestSerial = 0

    startup.s.regionalWarfareSelectedAutoBountyEnabled = startup.s.regionalWarfareSelectedAutoBountyEnabled == true
    startup.s.regionalWarfareSelectedAutoBountyPlayerId = tonumber(startup.s.regionalWarfareSelectedAutoBountyPlayerId or -1) or -1
    startup.s.regionalWarfareSelectedAutoBountyPlayerRid = tostring(startup.s.regionalWarfareSelectedAutoBountyPlayerRid or "")
    startup.s.regionalWarfareSelectedAutoBountyPlayerName = tostring(startup.s.regionalWarfareSelectedAutoBountyPlayerName or "")
    startup.s.regionalWarfareSelectedAutoBountyIntervalMs = 60000
    startup.s.regionalWarfareSelectedAutoBountyLastStatus = tostring(startup.s.regionalWarfareSelectedAutoBountyLastStatus or "Select a player to use Minigames-style auto-bounty.")

    function startup.b455_refresh_players_minigames_style()
        if Players and Players.Get then
            local sortMode = (ePlayerListSort and ePlayerListSort.PLAYER_ID) or 0
            Players.Get(sortMode, "")
        end
        local mg = _G.minigames or _G.MG
        if type(mg) == "table" and type(mg.RefreshPlayers) == "function" then
            mg.RefreshPlayers()
        end
    end

    function startup.b455_selected_bounty_rows(forceRefresh)
        local now = startup.now()
        if forceRefresh ~= true and type(rw.b455PlayerRowsCache) == "table" and now - (tonumber(rw.b455PlayerRowsCacheMs or 0) or 0) < 1000 then
            return rw.b455PlayerRowsCache
        end
        local rows = {}
        if startup.regional_warfare_roster then
            for _, row in ipairs(startup.regional_warfare_roster() or {}) do
                local playerId = tonumber(row.playerId)
                if playerId ~= nil and playerId >= 0 and playerId <= 31 then
                    rows[#rows + 1] = {
                        playerId = playerId,
                        rid = tostring(row.rid or ""),
                        name = tostring(row.name or ("Player " .. tostring(playerId))),
                        language = tostring(row.language or "Unknown")
                    }
                end
            end
        end
        table.sort(rows, function(a,b)
            return string.lower(tostring(a.name or "")) < string.lower(tostring(b.name or ""))
        end)
        rw.b455PlayerRowsCache = rows
        rw.b455PlayerRowsCacheMs = now
        return rows
    end

    function startup.b455_resolve_selected_bounty_target(forceRefresh)
        local wantedRid = tostring(startup.s.regionalWarfareSelectedAutoBountyPlayerRid or "")
        local wantedId = tonumber(startup.s.regionalWarfareSelectedAutoBountyPlayerId or -1) or -1
        local wantedName = tostring(startup.s.regionalWarfareSelectedAutoBountyPlayerName or "")
        local rows = startup.b455_selected_bounty_rows(forceRefresh == true)

        if wantedRid ~= "" then
            for _, row in ipairs(rows) do
                if tostring(row.rid or "") == wantedRid then return row end
            end
        end
        for _, row in ipairs(rows) do
            if tonumber(row.playerId) == wantedId and (wantedName == "" or tostring(row.name) == wantedName) then
                return row
            end
        end
        return nil
    end

    function startup.b455_select_bounty_target(row)
        if type(row) ~= "table" then
            startup.s.regionalWarfareSelectedAutoBountyPlayerId = -1
            startup.s.regionalWarfareSelectedAutoBountyPlayerRid = ""
            startup.s.regionalWarfareSelectedAutoBountyPlayerName = ""
            startup.s.regionalWarfareSelectedAutoBountyLastStatus = "No auto-bounty player selected."
        else
            startup.s.regionalWarfareSelectedAutoBountyPlayerId = tonumber(row.playerId or -1) or -1
            startup.s.regionalWarfareSelectedAutoBountyPlayerRid = tostring(row.rid or "")
            startup.s.regionalWarfareSelectedAutoBountyPlayerName = tostring(row.name or "")
            startup.s.regionalWarfareSelectedAutoBountyLastStatus = "Selected: " .. tostring(row.name or "Unknown") .. " | " .. tostring(row.language or "Unknown")
            rw.b455SelectedBountyLastMs = 0
        end
        if startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
    end

    function startup.b455_apply_selected_bounty_exact(playerId)
        playerId = tonumber(playerId)
        if playerId == nil or playerId < 0 or playerId > 31 then return false, "invalid player id" end

        startup.b455_refresh_players_minigames_style()

        local mg = _G.minigames or _G.MG
        if type(mg) == "table" and type(mg.ApplyBuiltInBounty) == "function" then
            local ok, status = mg.ApplyBuiltInBounty(playerId, true)
            if ok == true then return true, "Minigames ApplyBuiltInBounty(force=true)" end
            return false, "Minigames: " .. tostring(status or "failed")
        end

        local active = false
        if Players and Players.GetById then
            active = Players.GetById(playerId) ~= nil
        end
        if active ~= true and NETWORK and NETWORK.NETWORK_IS_PLAYER_ACTIVE then
            active = NETWORK.NETWORK_IS_PLAYER_ACTIVE(playerId) == true
        end
        if active ~= true then return false, "inactive player" end

        if not (FeatureMgr and FeatureMgr.GetFeatureByName) then return false, "FeatureMgr unavailable" end
        local feature = FeatureMgr.GetFeatureByName("Set Bounty On Player", playerId)
        if not feature then return false, "Set Bounty On Player feature not found" end
        if type(feature.TriggerCallback) ~= "function" then return false, "TriggerCallback unavailable" end

        feature:TriggerCallback()
        return true, "Cherax built-in 9k"
    end

    function startup.b455_queue_selected_bounty(reason)
        if rw.b455SelectedBountyInFlight == true then
            startup.s.regionalWarfareSelectedAutoBountyLastStatus = "Bounty request already running."
            return false
        end
        local target = startup.b455_resolve_selected_bounty_target(true)
        if not target then
            startup.s.regionalWarfareSelectedAutoBountyLastStatus = "Selected auto-bounty player is not currently in session."
            return false
        end
        if not (Script and Script.QueueJob) then
            startup.s.regionalWarfareSelectedAutoBountyLastStatus = "Script.QueueJob unavailable."
            return false
        end

        rw.b455SelectedBountyInFlight = true
        rw.b455SelectedBountyRequestSerial = (tonumber(rw.b455SelectedBountyRequestSerial or 0) or 0) + 1
        local serial = rw.b455SelectedBountyRequestSerial
        local queuedRid = tostring(target.rid or "")
        local queuedName = tostring(target.name or "")
        local queuedLanguage = tostring(target.language or "Unknown")

        Script.QueueJob(function()
            startup.b455_refresh_players_minigames_style()
            local liveTarget = startup.b455_resolve_selected_bounty_target(true)
            if not liveTarget then
                startup.s.regionalWarfareSelectedAutoBountyLastStatus = "Bounty skipped: selected player left the session."
                rw.b455SelectedBountyInFlight = false
                return
            end
            if queuedRid ~= "" and tostring(liveTarget.rid or "") ~= queuedRid then
                startup.s.regionalWarfareSelectedAutoBountyLastStatus = "Bounty skipped: selected RID changed."
                rw.b455SelectedBountyInFlight = false
                return
            end

            -- Release the queue lock and stamp the interval before the direct Minigames/Cherax
            -- callback. Current Minigames intentionally lets runtime callback errors surface;
            -- this prevents one surfaced error from permanently wedging or rapid-spamming auto-bounty.
            rw.b455SelectedBountyLastMs = startup.now()
            rw.b455SelectedBountyInFlight = false
            local ok, status = startup.b455_apply_selected_bounty_exact(liveTarget.playerId)
            if ok then
                startup.s.regionalWarfareSelectedAutoBountyLastStatus = "Bounty callback fired: " .. tostring(liveTarget.name) .. " | built-in 9k | " .. tostring(status)
                startup.s.regionalWarfareLastBountyPlayer = tostring(liveTarget.name or queuedName)
                startup.s.regionalWarfareLastBountyFaction = tostring(liveTarget.language or queuedLanguage)
                startup.s.regionalWarfareBountyCount = (tonumber(startup.s.regionalWarfareBountyCount or 0) or 0) + 1
                if startup.support_log_event_quiet then
                    startup.support_log_event_quiet("REGIONAL_WARFARE_SELECTED_BOUNTY","player="..tostring(liveTarget.name).." player_id="..tostring(liveTarget.playerId).." rid="..tostring(liveTarget.rid).." reason="..tostring(reason or "manual").." amount=9k source=minigames_selected_path serial="..tostring(serial))
                end
            else
                startup.s.regionalWarfareSelectedAutoBountyLastStatus = "Bounty failed: " .. tostring(liveTarget.name) .. " | " .. tostring(status)
                if startup.support_log_event_quiet then
                    startup.support_log_event_quiet("REGIONAL_WARFARE_SELECTED_BOUNTY_FAIL","player="..tostring(liveTarget.name).." player_id="..tostring(liveTarget.playerId).." reason="..tostring(reason or "manual").." error="..tostring(status))
                end
            end
        end)
        startup.s.regionalWarfareSelectedAutoBountyLastStatus = "Queued built-in 9k bounty for " .. tostring(target.name) .. "..."
        return true
    end

    function startup.b455_selected_auto_bounty_tick()
        if startup.s.regionalWarfareSelectedAutoBountyEnabled ~= true then return end
        if rw.b455SelectedBountyInFlight == true then return end
        local target = startup.b455_resolve_selected_bounty_target()
        if not target then
            startup.s.regionalWarfareSelectedAutoBountyLastStatus = "Auto-Bounty waiting: selected player is offline."
            return
        end
        local now = startup.now()
        local interval = 60000
        local last = tonumber(rw.b455SelectedBountyLastMs or 0) or 0
        if last == 0 or now - last >= interval then
            startup.b455_queue_selected_bounty("Auto selected player 60s")
        end
    end

    -- Add the controls once. This selected-player system is intentionally independent
    -- of language enemy policy and can run even when Regional Warfare itself is OFF.
    if startup.h.RegionalWarfareSelectedAutoBounty == nil then
        startup.add_toggle("RegionalWarfareSelectedAutoBounty","Auto-Bounty Selected Player","Uses the exact Minigames selected-player built-in 9k bounty path. Applies immediately, then force-refreshes the selected player every 60 seconds while they remain in session.",function(f)
            startup.s.regionalWarfareSelectedAutoBountyEnabled = f:IsToggled()
            rw.b455SelectedBountyLastMs = 0
            if startup.s.regionalWarfareSelectedAutoBountyEnabled == true then
                startup.b455_queue_selected_bounty("Auto enabled")
            end
            if startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
        end,startup.s.regionalWarfareSelectedAutoBountyEnabled==true)
    end
    if startup.h.RegionalWarfareSelectedBountyNow == nil then
        startup.add_button("RegionalWarfareSelectedBountyNow","Apply Bounty To Selected Player Now","Queues the current Minigames selected-player built-in 9k bounty path for the player chosen in the dropdown.",function()
            startup.b455_queue_selected_bounty("Manual selected player")
        end)
    end

    -- Extend the existing persistent Regional Warfare worker with the selected-player
    -- auto-bounty maintenance check. The actual bounty is still queued exactly like
    -- Minigames.ApplyBountyToSelected.
    if rw.b455BackgroundWrapped ~= true and startup.regional_warfare_background_pass_448 then
        rw.b455BackgroundWrapped = true
        rw.b455PreviousBackgroundPass = startup.regional_warfare_background_pass_448
        function startup.regional_warfare_background_pass_448(force)
            rw.b455PreviousBackgroundPass(force)
            startup.b455_selected_auto_bounty_tick()
            return true
        end
    end

    -- Append a focused selected-player panel after the existing Regional Warfare UI.
    if rw.b455RenderWrapped ~= true and startup.render_regional_warfare then
        rw.b455RenderWrapped = true
        rw.b455PreviousRenderRegionalWarfare = startup.render_regional_warfare
        function startup.render_regional_warfare()
            rw.b455PreviousRenderRegionalWarfare()
            if not (ClickGUI and ImGui) then return end
            if ClickGUI.BeginCustomChildWindow("Regional Warfare Auto-Bounty Target") then
                startup.section_title("Selected Player Auto-Bounty")
                startup.subtle_text_wrapped("Choose one current-session player. This uses Minigames' selected-player bounty flow: refresh players, queue a job, then trigger Cherax's built-in anonymous 9k bounty. Auto-Bounty refreshes every 60 seconds.")

                local rows = startup.b455_selected_bounty_rows()
                local selected = startup.b455_resolve_selected_bounty_target()
                local preview = selected and ("["..tostring(selected.playerId).."] "..tostring(selected.name).." • "..tostring(selected.language)) or "Select player"
                if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(-1) end
                if ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo and ImGui.BeginCombo("Player##StartupB455AutoBountyPlayer",preview) then
                    if ImGui.Selectable("None##StartupB455AutoBountyNone",selected==nil) then startup.b455_select_bounty_target(nil) end
                    for _, row in ipairs(rows) do
                        local isSelected = selected and tonumber(selected.playerId)==tonumber(row.playerId) and tostring(selected.rid or "")==tostring(row.rid or "")
                        local label = "["..tostring(row.playerId).."] "..tostring(row.name).." • "..tostring(row.language).."##StartupB455AutoBounty"..tostring(row.playerId)..tostring(row.rid)
                        if ImGui.Selectable(label,isSelected==true) then
                            startup.b455_select_bounty_target(row)
                            if startup.s.regionalWarfareSelectedAutoBountyEnabled==true then startup.b455_queue_selected_bounty("Target changed") end
                        end
                    end
                    ImGui.EndCombo()
                end
                startup.render_feature_guarded_325(startup.h.RegionalWarfareSelectedAutoBounty)
                startup.render_feature_guarded_325(startup.h.RegionalWarfareSelectedBountyNow)
                startup.subtle_text("Interval: 60 seconds • Amount: built-in 9k • Source: Minigames v1.0.0 selected-player path")
                startup.subtle_text_wrapped(tostring(startup.s.regionalWarfareSelectedAutoBountyLastStatus or "Ready."))
                ClickGUI.EndCustomChildWindow()
            end
        end
    end

    -- Keep feature UI state synchronized after config load/reset.
    if rw.b455SyncWrapped ~= true and startup.sync_feature_states then
        rw.b455SyncWrapped = true
        rw.b455PreviousSyncFeatureStates = startup.sync_feature_states
        function startup.sync_feature_states()
            rw.b455PreviousSyncFeatureStates()
            if startup.h.RegionalWarfareSelectedAutoBounty then
                startup.set_feature_bool_silently(startup.h.RegionalWarfareSelectedAutoBounty,startup.s.regionalWarfareSelectedAutoBountyEnabled==true)
            end
        end
    end
end
startup.install_selected_player_auto_bounty_build455()
startup.install_selected_player_auto_bounty_build455=nil

startup.version="v1.0.18"
