startup.build_label="v1.0.18 Production Build 455 - Selected Player Auto-Bounty"
startup.release_channel="Production"
if startup.log then
    startup.log("[Build 455] Added Minigames-parity selected-player Auto-Bounty: live player dropdown, manual Apply Now, and exact 60-second built-in 9k maintenance path.")
end
if startup.support_log_event_quiet then
    startup.support_log_event_quiet("BUILD455_SELECTED_PLAYER_AUTO_BOUNTY_READY","source=B454 minigames_source=v1.0.0 dropdown=live_session_players auto_interval_ms=60000 queue=Script.QueueJob feature=Set_Bounty_On_Player amount=9k")
end

-- ============================================================================
-- v1.0.18 Production Build 456 - Player Language Hash Resolver Fix
-- - Uses Cherax's stable Player Language player-feature hash 307842263 first.
-- - Reads the current player-indexed list string/index directly from FeatureMgr.
-- - Falls back through the feature object and translated feature name only after hash APIs.
-- - Unknown players are not recolored, preventing mass "Unknown" blip painting.
-- ============================================================================
startup.install_player_language_hash_fix_build456=function()
    local rw=startup.regional_warfare_runtime or {}
    startup.regional_warfare_runtime=rw
    startup.regional_warfare_player_language_hash=307842263
    startup.b456_language_index_map={
        [0]="English",
        [1]="French",
        [2]="German",
        [3]="Italian",
        [4]="Spanish",
        [5]="Brazilian",
        [6]="Polish",
        [7]="Russian",
        [8]="Korean",
        [9]="Chinese Traditional",
        [10]="Japanese",
        [11]="Mexican",
        [12]="Chinese Simplified"
    }

    function startup.regional_warfare_player_language(playerId)
        playerId=tonumber(playerId)
        if playerId==nil or playerId<0 or playerId>31 then return "Unknown","invalid-player" end
        local hash=startup.regional_warfare_player_language_hash

        -- Primary path: Cherax's stable player-feature hash + indexed list helpers.
        if FeatureMgr then
            if FeatureMgr.GetCurrentFeatureListString then
                local ok,v=pcall(FeatureMgr.GetCurrentFeatureListString,hash,playerId)
                if ok then
                    local lang=startup.regional_warfare_normalize_language(v)
                    if lang~="Unknown" then return lang,"hash-current-list-string" end
                end
            end

            if FeatureMgr.GetFeatureListIndex then
                local okI,index=pcall(FeatureMgr.GetFeatureListIndex,hash,playerId)
                index=okI and tonumber(index) or nil
                if index~=nil and index>=0 then
                    if FeatureMgr.GetFeatureList then
                        local okL,list=pcall(FeatureMgr.GetFeatureList,hash,playerId)
                        if okL and type(list)=="table" then
                            local v=list[index] or list[index+1]
                            local lang=startup.regional_warfare_normalize_language(v)
                            if lang~="Unknown" then return lang,"hash-list-index" end
                        end
                    end
                    local mapped=startup.b456_language_index_map[index]
                    if mapped then return mapped,"hash-index-map" end
                end
            end

            if FeatureMgr.GetFeatureString then
                local okS,v=pcall(FeatureMgr.GetFeatureString,hash,playerId)
                if okS then
                    local lang=startup.regional_warfare_normalize_language(v)
                    if lang~="Unknown" then return lang,"hash-feature-string" end
                end
            end

            if FeatureMgr.GetFeature then
                local okF,feature=pcall(FeatureMgr.GetFeature,hash,playerId)
                if okF and feature then
                    if feature.GetStringValue then
                        local ok,v=pcall(function() return feature:GetStringValue() end)
                        if ok then
                            local lang=startup.regional_warfare_normalize_language(v)
                            if lang~="Unknown" then return lang,"hash-object-string" end
                        end
                    end
                    if feature.GetListIndex then
                        local ok,index=pcall(function() return feature:GetListIndex() end)
                        index=ok and tonumber(index) or nil
                        if index~=nil and index>=0 then
                            if feature.GetList then
                                local okL,list=pcall(function() return feature:GetList() end)
                                if okL and type(list)=="table" then
                                    local v=list[index] or list[index+1]
                                    local lang=startup.regional_warfare_normalize_language(v)
                                    if lang~="Unknown" then return lang,"hash-object-list" end
                                end
                            end
                            local mapped=startup.b456_language_index_map[index]
                            if mapped then return mapped,"hash-object-index-map" end
                        end
                    end
                end
            end
        end

        -- Compatibility fallback for builds where name lookup still works.
        if FeatureMgr and FeatureMgr.GetFeatureByName then
            local okF,feature=pcall(FeatureMgr.GetFeatureByName,"Player Language",playerId)
            if okF and feature then
                if feature.GetStringValue then
                    local ok,v=pcall(function() return feature:GetStringValue() end)
                    if ok then
                        local lang=startup.regional_warfare_normalize_language(v)
                        if lang~="Unknown" then return lang,"name-object-string" end
                    end
                end
                if feature.GetListIndex then
                    local ok,index=pcall(function() return feature:GetListIndex() end)
                    index=ok and tonumber(index) or nil
                    if index~=nil and index>=0 then
                        local mapped=startup.b456_language_index_map[index]
                        if mapped then return mapped,"name-index-map" end
                    end
                end
            end
        end

        -- GamerInfo remains only a final non-IP fallback. Current Cherax docs expose
        -- Name/RockstarId/HostKey there, so this may legitimately remain unavailable.
        if Players and Players.GetById then
            local okP,obj=pcall(Players.GetById,playerId)
            if okP and obj and obj.GetGamerInfo and startup.live_r_language_from_gamer_info_341 then
                local okI,info=pcall(function() return obj:GetGamerInfo() end)
                if okI and info then
                    local lang=startup.regional_warfare_normalize_language(startup.live_r_language_from_gamer_info_341(info))
                    if lang~="Unknown" then return lang,"gamer-info" end
                end
            end
        end
        return "Unknown","unavailable"
    end

    -- Rebuild language colors but leave unresolved players untouched instead of
    -- applying the user-selected Unknown color to the whole lobby.
    function startup.regional_warfare_apply_blip_colors_449(force)
        local now=startup.now()
        if force~=true and now-(tonumber(rw.lastBlipColorScanMs or 0) or 0)<500 then return end
        rw.lastBlipColorScanMs=now

        if startup.s.regionalWarfareEnabled~=true or startup.s.regionalWarfareColorPlayers==false then
            if next(rw.blipOriginal or {})~=nil and startup.regional_warfare_restore_blip_colors_449 then
                startup.regional_warfare_restore_blip_colors_449()
            end
            rw.blipFrameTargets453={}
            return
        end

        local active={}
        local frameTargets={}
        for _,row in ipairs(startup.regional_warfare_roster() or {}) do
            local playerId=tonumber(row.playerId)
            if playerId~=nil then
                active[playerId]=true
                local language=startup.regional_warfare_normalize_language(row.language)
                local blip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0

                if blip~=0 then
                    local original=rw.blipOriginal[playerId]
                    if type(original)~="table" or tonumber(original.blip or 0)~=blip then
                        rw.blipOriginal[playerId]={
                            blip=blip,
                            color=startup.regional_warfare_get_blip_color_449 and startup.regional_warfare_get_blip_color_449(blip) or nil
                        }
                    end
                    local r,g,b,colorName=startup.regional_warfare_rgb_for_language_454(language)
                    rw.blipApplied[playerId]={blip=blip,r=r,g=g,b=b,language=language,colorName=colorName}
                    frameTargets[blip]={playerId=playerId,r=r,g=g,b=b,language=language,colorName=colorName}
                    startup.regional_warfare_set_custom_blip_rgb_454(blip,r,g,b)
                else
                    -- If this player was previously painted but is now unresolved, restore
                    -- their primary Rockstar color and stop reasserting custom RGB.
                    local previous=rw.blipOriginal[playerId]
                    if type(previous)=="table" and tonumber(previous.blip or 0)~=0 and previous.color~=nil and Natives and Natives.InvokeVoid then
                        Natives.InvokeVoid(0x03D7FB09E75D6B7E,tonumber(previous.blip),tonumber(previous.color))
                    end
                    rw.blipOriginal[playerId]=nil
                    rw.blipApplied[playerId]=nil
                end
            end
        end

        for playerId,_ in pairs(rw.blipOriginal or {}) do
            if active[playerId]~=true then
                rw.blipOriginal[playerId]=nil
                rw.blipApplied[playerId]=nil
            end
        end
        rw.blipFrameTargets453=frameTargets
    end

    -- Force all dependent caches to re-resolve with the stable hash immediately.
    rw.lastBlipColorScanMs=0
    rw.blipFrameTargets453={}
    rw.lastLanguageByRid={}
    rw.lastApplied={}
    rw.lastAttempt={}
    rw.b455RowsCache=nil
    rw.b455RowsCacheMs=0
    -- B463 hotfix: do not run a player-feature/color scan during init.
    -- Cherax can throw when a per-player feature instance does not yet exist.
    rw.b456DeferredInitialScan=true
end
