-- ============================================================================
-- v1.0.18 Production Build 457 - Regional Warfare Auto-Bounty ImGui Scope Fix
-- - Removes ClickGUI.RenderFeature from the selected-player auto-bounty child.
-- - Resolves player/language rows before opening the child window.
-- - Treats missing player feature/index lookups as optional instead of fatal.
-- - Guarantees the custom child is closed after its own body completes.
-- ============================================================================
startup.install_regional_warfare_imgui_fix_build457=function()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    -- B457: language lookup is optional player metadata. Missing player-feature
    -- instances are expected during joins/leaves and must never abort ClickGUI render.
    function startup.regional_warfare_player_language(playerId)
        playerId=tonumber(playerId)
        if playerId==nil or playerId<0 or playerId>31 then return "Unknown","invalid-player" end
        local hash=tonumber(startup.regional_warfare_player_language_hash or 307842263) or 307842263
        local function try(fn,...)
            if type(fn)~="function" then return false,nil end
            local ok,a,b,c=pcall(fn,...)
            if not ok then return false,nil end
            return true,a,b,c
        end
        local function normalized(v)
            local lang=startup.regional_warfare_normalize_language and startup.regional_warfare_normalize_language(v) or tostring(v or "Unknown")
            if lang==nil or lang=="" then lang="Unknown" end
            return lang
        end

        if FeatureMgr then
            if FeatureMgr.GetCurrentFeatureListString then
                local ok,v=try(FeatureMgr.GetCurrentFeatureListString,hash,playerId)
                if ok then
                    local lang=normalized(v)
                    if lang~="Unknown" then return lang,"hash-current-list-string" end
                end
            end

            if FeatureMgr.GetFeatureListIndex then
                local ok,index=try(FeatureMgr.GetFeatureListIndex,hash,playerId)
                index=ok and tonumber(index) or nil
                if index~=nil and index>=0 then
                    local mapped=startup.b456_language_index_map and startup.b456_language_index_map[index]
                    if mapped then return mapped,"hash-index-map" end
                    if FeatureMgr.GetFeatureList then
                        local okList,list=try(FeatureMgr.GetFeatureList,hash,playerId)
                        if okList and type(list)=="table" then
                            local v=list[index] or list[index+1]
                            local lang=normalized(v)
                            if lang~="Unknown" then return lang,"hash-list-index" end
                        end
                    end
                end
            end

            if FeatureMgr.GetFeatureString then
                local ok,v=try(FeatureMgr.GetFeatureString,hash,playerId)
                if ok then
                    local lang=normalized(v)
                    if lang~="Unknown" then return lang,"hash-feature-string" end
                end
            end

            if FeatureMgr.GetFeature then
                local ok,feature=try(FeatureMgr.GetFeature,hash,playerId)
                if ok and feature then
                    if feature.GetStringValue then
                        local okValue,v=pcall(function() return feature:GetStringValue() end)
                        if okValue then
                            local lang=normalized(v)
                            if lang~="Unknown" then return lang,"hash-object-string" end
                        end
                    end
                    if feature.GetListIndex then
                        local okIndex,index=pcall(function() return feature:GetListIndex() end)
                        index=okIndex and tonumber(index) or nil
                        if index~=nil and index>=0 then
                            local mapped=startup.b456_language_index_map and startup.b456_language_index_map[index]
                            if mapped then return mapped,"hash-object-index-map" end
                        end
                    end
                end
            end

            if FeatureMgr.GetFeatureByName then
                local ok,feature=try(FeatureMgr.GetFeatureByName,"Player Language",playerId)
                if ok and feature then
                    if feature.GetStringValue then
                        local okValue,v=pcall(function() return feature:GetStringValue() end)
                        if okValue then
                            local lang=normalized(v)
                            if lang~="Unknown" then return lang,"name-object-string" end
                        end
                    end
                    if feature.GetListIndex then
                        local okIndex,index=pcall(function() return feature:GetListIndex() end)
                        index=okIndex and tonumber(index) or nil
                        if index~=nil and index>=0 then
                            local mapped=startup.b456_language_index_map and startup.b456_language_index_map[index]
                            if mapped then return mapped,"name-index-map" end
                        end
                    end
                end
            end
        end

        if Players and Players.GetById then
            local okP,obj=pcall(Players.GetById,playerId)
            if okP and obj and obj.GetGamerInfo and startup.live_r_language_from_gamer_info_341 then
                local okI,info=pcall(function() return obj:GetGamerInfo() end)
                if okI and info then
                    local okL,value=pcall(startup.live_r_language_from_gamer_info_341,info)
                    if okL then
                        local lang=normalized(value)
                        if lang~="Unknown" then return lang,"gamer-info" end
                    end
                end
            end
        end
        return "Unknown","unavailable"
    end

    -- B457: build the dropdown roster independently from Regional Warfare rendering.
    -- No FeatureMgr exception is allowed to escape this function.
    function startup.b455_selected_bounty_rows(forceRefresh)
        local now=startup.now()
        if forceRefresh~=true and type(rw.b455PlayerRowsCache)=="table" and now-(tonumber(rw.b455PlayerRowsCacheMs or 0) or 0)<1000 then
            return rw.b455PlayerRowsCache
        end

        local rows,ids,seen={},{},{}
        local localId=-1
        if startup.regional_warfare_local_player_id then
            local ok,v=pcall(startup.regional_warfare_local_player_id)
            if ok then localId=tonumber(v or -1) or -1 end
        end

        if startup.regional_warfare_player_ids_449 then
            local ok,list=pcall(startup.regional_warfare_player_ids_449)
            if ok and type(list)=="table" then
                for _,pid in ipairs(list) do
                    pid=tonumber(pid)
                    if pid~=nil and pid>=0 and pid<=31 and pid~=localId and not seen[pid] then
                        seen[pid]=true
                        ids[#ids+1]=pid
                    end
                end
            end
        end

        if #ids==0 and Players and Players.GetById then
            for pid=0,31 do
                if pid~=localId then
                    local ok,obj=pcall(Players.GetById,pid)
                    if ok and obj~=nil then
                        seen[pid]=true
                        ids[#ids+1]=pid
                    end
                end
            end
        end

        table.sort(ids)
        for _,pid in ipairs(ids) do
            local name="Player "..tostring(pid)
            if startup.get_player_name_safe then
                local ok,v=pcall(startup.get_player_name_safe,pid)
                if ok and tostring(v or "")~="" then name=tostring(v) end
            elseif Players and Players.GetName then
                local ok,v=pcall(Players.GetName,pid)
                if ok and tostring(v or "")~="" then name=tostring(v) end
            end

            local rid=""
            if startup.regional_warfare_get_rid then
                local ok,v=pcall(startup.regional_warfare_get_rid,pid)
                if ok then rid=tostring(v or "") end
            end

            local language,source="Unknown","unavailable"
            local okLang,a,b=pcall(startup.regional_warfare_player_language,pid)
            if okLang then
                language=tostring(a or "Unknown")
                source=tostring(b or "")
            end

            rows[#rows+1]={playerId=pid,rid=rid,name=name,language=language,languageSource=source}
        end

        table.sort(rows,function(a,b) return string.lower(tostring(a.name or ""))<string.lower(tostring(b.name or "")) end)
        rw.b455PlayerRowsCache=rows
        rw.b455PlayerRowsCacheMs=now
        return rows
    end

    -- B457 bypasses the B455 child renderer completely. The base renderer saved by
    -- B455 contains Regional Warfare itself but not the broken selected-player panel.
    rw.b457BaseRender=rw.b455PreviousRenderRegionalWarfare or rw.b457BaseRender or startup.render_regional_warfare
    function startup.render_regional_warfare()
        if rw.b457BaseRender then
            local okBase,errBase=pcall(rw.b457BaseRender)
            if not okBase and startup.log then
                startup.log("[Build 457][REGIONAL_WARFARE_BASE_RENDER_RECOVERED] "..tostring(errBase))
            end
        end
        if not (ClickGUI and ImGui and ClickGUI.BeginCustomChildWindow and ClickGUI.EndCustomChildWindow) then return end

        -- Resolve every external/player value BEFORE BeginCustomChildWindow so a
        -- transient Cherax player-feature miss cannot leave ImGui scopes open.
        local rows={}
        local okRows,resultRows=pcall(startup.b455_selected_bounty_rows,false)
        if okRows and type(resultRows)=="table" then rows=resultRows end

        local selected=nil
        local wantedRid=tostring(startup.s.regionalWarfareSelectedAutoBountyPlayerRid or "")
        local wantedId=tonumber(startup.s.regionalWarfareSelectedAutoBountyPlayerId or -1) or -1
        local wantedName=tostring(startup.s.regionalWarfareSelectedAutoBountyPlayerName or "")
        for _,row in ipairs(rows) do
            if wantedRid~="" and tostring(row.rid or "")==wantedRid then selected=row break end
            if wantedRid=="" and tonumber(row.playerId)==wantedId and (wantedName=="" or tostring(row.name)==wantedName) then selected=row break end
        end
        local preview=selected and ("["..tostring(selected.playerId).."] "..tostring(selected.name).." • "..tostring(selected.language)) or "Select player"

        local chosenRow=nil
        local clearSelection=false
        local autoChanged=nil
        local manualClicked=false
        local childOpened=false
        local okBegin,beginResult=pcall(ClickGUI.BeginCustomChildWindow,"Regional Warfare Auto-Bounty Target")
        if okBegin and beginResult==true then childOpened=true end

        if childOpened then
            local okBody,bodyErr=pcall(function()
                startup.section_title("Selected Player Auto-Bounty")
                startup.subtle_text_wrapped("Choose one current-session player. Player/language metadata is resolved before this panel opens so transient Cherax feature misses cannot corrupt ImGui state.")

                if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(-1) end
                local comboOpen=false
                if ImGui.BeginCombo then
                    local okCombo,value=pcall(ImGui.BeginCombo,"Player##StartupB457AutoBountyPlayer",preview)
                    comboOpen=okCombo and value==true
                end
                if comboOpen then
                    if ImGui.Selectable and ImGui.Selectable("None##StartupB457AutoBountyNone",selected==nil) then
                        clearSelection=true
                    end
                    if ImGui.Selectable then
                        for _,row in ipairs(rows) do
                            local isSelected=selected and tonumber(selected.playerId)==tonumber(row.playerId) and tostring(selected.rid or "")==tostring(row.rid or "")
                            local label="["..tostring(row.playerId).."] "..tostring(row.name).." • "..tostring(row.language).."##StartupB457AutoBounty"..tostring(row.playerId)..tostring(row.rid)
                            if ImGui.Selectable(label,isSelected==true) then chosenRow=row end
                        end
                    end
                    if ImGui.EndCombo then ImGui.EndCombo() end
                end

                local oldAuto=startup.s.regionalWarfareSelectedAutoBountyEnabled==true
                if ImGui.Checkbox then
                    local newAuto=ImGui.Checkbox("Auto-Bounty Selected Player##StartupB457AutoBountyToggle",oldAuto)
                    if newAuto~=oldAuto then autoChanged=newAuto==true end
                end
                startup.hover_help("Uses the Minigames selected-player built-in 9k bounty path. Applies immediately when enabled, then refreshes the selected player every 60 seconds.")

                if ImGui.Button and ImGui.Button("Apply Bounty To Selected Player Now##StartupB457BountyNow",-1,30)==true then
                    manualClicked=true
                end
                startup.hover_help("Queues the current selected player through the Minigames-style Script.QueueJob -> Set Bounty On Player -> TriggerCallback path.")

                startup.subtle_text("Interval: 60 seconds • Amount: built-in 9k • Source: Minigames v1.0.0 selected-player path")
                startup.subtle_text_wrapped(tostring(startup.s.regionalWarfareSelectedAutoBountyLastStatus or "Ready."))
                if not okRows then startup.subtle_text_wrapped("Roster refresh recovered from a transient Cherax player-feature lookup error.") end
            end)

            -- Always close the child even if one of our own draw helpers unexpectedly fails.
            pcall(ClickGUI.EndCustomChildWindow)
            if not okBody and startup.log then
                startup.log("[Build 457][AUTO_BOUNTY_UI_RECOVERED] "..tostring(bodyErr))
            end
        end

        -- Mutations / jobs happen only AFTER all ImGui scopes are closed.
        if clearSelection==true then
            pcall(startup.b455_select_bounty_target,nil)
        elseif chosenRow then
            pcall(startup.b455_select_bounty_target,chosenRow)
            if startup.s.regionalWarfareSelectedAutoBountyEnabled==true then
                pcall(startup.b455_queue_selected_bounty,"Target changed")
            end
        end

        if autoChanged~=nil then
            startup.s.regionalWarfareSelectedAutoBountyEnabled=autoChanged==true
            rw.b455SelectedBountyLastMs=0
            if startup.h and startup.h.RegionalWarfareSelectedAutoBounty and startup.set_feature_bool_silently then
                pcall(startup.set_feature_bool_silently,startup.h.RegionalWarfareSelectedAutoBounty,autoChanged==true)
            end
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
            if autoChanged==true then pcall(startup.b455_queue_selected_bounty,"Auto enabled") end
        end

        if manualClicked==true then pcall(startup.b455_queue_selected_bounty,"Manual selected player") end
    end

    rw.b455PlayerRowsCache=nil
    rw.b455PlayerRowsCacheMs=0
end
startup.install_regional_warfare_imgui_fix_build457()
startup.install_regional_warfare_imgui_fix_build457=nil

