end


-- ============================================================================
-- Build 458 — Startup Session-Hop Cancel Hotkey + Already-Online Guard
-- ============================================================================
function startup.install_startup_hop_cancel_build458()
    startup.load_hop_cancel = startup.load_hop_cancel or {}
    local st = startup.load_hop_cancel
    st.cancelled = st.cancelled == true
    st.cancelledAtMs = tonumber(st.cancelledAtMs or 0) or 0
    st.reason = tostring(st.reason or "")
    st.keyWasDown = false
    st.workerStarted = st.workerStarted == true
    st.armedAtMs = tonumber(st.armedAtMs or 0) or 0
    st.armedUntilMs = tonumber(st.armedUntilMs or 0) or 0
    st.blockedAutoStarts = tonumber(st.blockedAutoStarts or 0) or 0
    st.alreadyOnlineSkips = tonumber(st.alreadyOnlineSkips or 0) or 0

    startup.s.cancelStartupHopHotkeyKeyCode = startup.clamp_int(startup.s.cancelStartupHopHotkeyKeyCode or 0x77,0,255)
    local opt = startup.get_start_session_hotkey_option and select(1,startup.get_start_session_hotkey_option(startup.s.cancelStartupHopHotkeyKeyCode)) or nil
    startup.s.cancelStartupHopHotkeyName = tostring((opt and opt.name) or startup.s.cancelStartupHopHotkeyName or "F8")
    startup.s.cancelStartupHopHotkeyLastStatus = st.cancelled and "Cancelled for this load" or "Armed for this load"

    function startup.cancel_startup_session_hops_build458(reason)
        local state=startup.load_hop_cancel or {}
        if state.cancelled==true then
            startup.s.cancelStartupHopHotkeyLastStatus="Already cancelled for this load"
            return true
        end
        state.cancelled=true
        state.cancelledAtMs=startup.now and startup.now() or 0
        state.reason=tostring(reason or "Startup session-hop cancel hotkey")
        startup.s.cancelStartupHopHotkeyLastStatus="Cancelled for this load"
        startup.s.startupOnlineAttempted=true
        startup.s.waitingForRefreshedSession=false
        startup.s.refreshSessionAfterLuaAttempted=true
        startup.s.lastOnlineStartStatus="Cancelled for this load by "..tostring(startup.s.cancelStartupHopHotkeyName or "F8")
        startup.s.lastSessionFlowStatus="Automatic Startup session hops cancelled for this load"

        -- Invalidate any Lobby Finder job already waiting without changing the user's
        -- saved Lobby Finder toggles. The next script load starts cleanly again.
        if startup.lobby_filter and startup.lobby_filter.cancel then
            startup.lobby_filter.cancel("Cancelled for this Startup load")
        end
        startup.s.lobbyFinderStatus="Paused for this load by session-hop cancel hotkey"
        startup.s.cheraxHostFinderStatus=startup.s.lobbyFinderStatus
        startup.s.startupPresenceFinderStatus=startup.s.lobbyFinderStatus

        if startup.toast then
            startup.toast("Startup automatic session hops CANCELLED for this load.",5500)
        end
        if startup.log then
            startup.log("[Build 458] Startup session-hop automation cancelled for this load | reason="..state.reason)
        end
        return true
    end

    -- Suppress Lobby Finder ownership for this load after the cancel hotkey is used.
    if startup.lobby_filter and startup.lobby_filter.mode and st.modeWrapped~=true then
        st.modeWrapped=true
        st.modePre=startup.lobby_filter.mode
        startup.lobby_filter.mode=function(...)
            if startup.load_hop_cancel and startup.load_hop_cancel.cancelled==true then return nil end
            return st.modePre(...)
        end
    end

    -- Replace the old auto-start worker with a generation-safe version that actually
    -- honors the feature name: it starts Online only from singleplayer/offline.
    if st.onlineLaunchWrapped~=true then
        st.onlineLaunchWrapped=true
        st.onlineLaunchPre=startup.run_startup_online_launch
        startup.run_startup_online_launch=function()
            local state=startup.load_hop_cancel or {}
            if state.cancelled==true then
                startup.s.startupOnlineAttempted=true
                startup.s.lastOnlineStartStatus="Cancelled for this load"
                return false
            end
            if startup.s.startupOnlineAttempted then
                startup.s.lastOnlineStartStatus="Skipped: already attempted this startup"
                return false
            end
            if not startup.s.autoStartOnlineFromSingleplayer then
                startup.s.lastOnlineStartStatus="Auto Start Online OFF"
                return false
            end

            -- B458 root fix: loading Startup while already in GTA Online must never
            -- schedule another Start Session just because Auto Start is enabled.
            if startup.is_gta_online_session_ready and startup.is_gta_online_session_ready() then
                startup.s.startupOnlineAttempted=true
                state.alreadyOnlineSkips=(tonumber(state.alreadyOnlineSkips or 0) or 0)+1
                startup.s.lastOnlineStartStatus="Already in GTA Online; startup session hop skipped"
                if startup.log then startup.log("[Build 458] Auto Start Online skipped because GTA Online is already active.") end
                return false
            end

            startup.s.startupOnlineAttempted=true
            state.launchSerial=(tonumber(state.launchSerial or 0) or 0)+1
            local serial=state.launchSerial
            Script.QueueJob(function()
                local targetType=startup.resolve_session_type()
                startup.s.lastOnlineStartStatus="Waiting 1 minute before starting "..tostring(targetType).." | "..tostring(startup.s.cancelStartupHopHotkeyName or "F8").." cancels"
                startup.toast_quiet("Auto Start Online armed. Press "..tostring(startup.s.cancelStartupHopHotkeyName or "F8").." to cancel the pending Startup session hop.",6000)
                startup.yield(startup.s.autoStartOnlineDelayMs)

                if startup.load_hop_cancel.cancelled==true or serial~=(tonumber(startup.load_hop_cancel.launchSerial or 0) or 0) then
                    startup.s.lastOnlineStartStatus="Cancelled before session start"
                    return
                end

                -- If the user reached Online naturally during the wait, do not hop them.
                if startup.is_gta_online_session_ready and startup.is_gta_online_session_ready() then
                    startup.s.lastOnlineStartStatus="GTA Online became active naturally; automatic session hop skipped"
                    return
                end

                while startup.regionExperimentLock==true or startup.regionRescanJobQueued==true do
                    if startup.load_hop_cancel.cancelled==true then
                        startup.s.lastOnlineStartStatus="Cancelled while waiting for region work"
                        return
                    end
                    startup.s.lastOnlineStartStatus="Waiting for the Legacy Region experiment to finish"
                    startup.yield(500)
                end
                if startup.regionExperimentSessionStarted==true then
                    startup.s.lastOnlineStartStatus="Skipped: a Region experiment already started a controlled session"
                    return
                end
                if startup.load_hop_cancel.cancelled==true then return end

                targetType=startup.resolve_session_type()
                startup.s.lastOnlineStartStatus="Applying "..tostring(targetType)
                startup.apply_session_type()
                startup.yield(1000)
                if startup.load_hop_cancel.cancelled==true then
                    startup.s.lastOnlineStartStatus="Cancelled before Start Session click"
                    return
                end
                startup.s.lastOnlineStartStatus="Starting "..tostring(targetType)
                startup.toast_quiet("Starting "..tostring(targetType).." from startup flow.",4000)
                startup.start_session(true)
            end)
            return true
        end
    end

    function startup.render_cancel_startup_hop_hotkey_config()
        if not (ClickGUI and ImGui and ClickGUI.BeginCustomChildWindow and ClickGUI.EndCustomChildWindow) then return end
        if not ClickGUI.BeginCustomChildWindow("Cancel Startup Session Hop Hotkey") then return end
        startup.section_title("Cancel Startup Session Hop Hotkey")
        startup.subtle_text_wrapped("Press this key once after Startup loads to cancel Startup-owned automatic session changes for the current script load. It does not turn off or overwrite your saved Auto Start, Lobby Finder, or Lua settings.")
        startup.text_colored(1.00,0.35,0.35,1.00,"Default: F8")
        if ImGui.Separator then ImGui.Separator() end

        local currentOption,currentIndex=startup.get_start_session_hotkey_option(startup.s.cancelStartupHopHotkeyKeyCode or 0x77)
        local opened=false
        if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(-1) end
        if ImGui.BeginCombo then opened=ImGui.BeginCombo("Cancel Key##StartupB458HopCancelKey",tostring(currentOption and currentOption.name or "F8"))==true end
        if opened then
            for index,option in ipairs(startup.start_session_hotkey_options or {}) do
                if ImGui.Selectable(tostring(option.name).."##StartupB458CancelKey"..tostring(index),index==currentIndex)==true then
                    startup.s.cancelStartupHopHotkeyKeyCode=option.code
                    startup.s.cancelStartupHopHotkeyName=option.name
                    startup.save_config(false)
                end
            end
            if ImGui.EndCombo then ImGui.EndCombo() end
        end

        local state=startup.load_hop_cancel or {}
        if state.cancelled==true then
            startup.text_colored_wrapped(1.00,0.30,0.30,1.00,"STATUS: AUTOMATIC SESSION HOPS CANCELLED FOR THIS LOAD")
        else
            startup.text_colored_wrapped(0.35,1.00,0.45,1.00,"STATUS: ARMED • Press "..string.upper(tostring(startup.s.cancelStartupHopHotkeyName or "F8")).." during the first 5 minutes after load")
        end
        startup.subtle_text_wrapped(tostring(startup.s.cancelStartupHopHotkeyLastStatus or "Armed for this load"))
        if ImGui.Button and ImGui.Button("CANCEL PENDING STARTUP SESSION HOPS NOW##StartupB458CancelNow",-1,30)==true then
            startup.cancel_startup_session_hops_build458("Config button")
        end
        ClickGUI.EndCustomChildWindow()
    end

    -- Raw key polling is intentional here. It becomes available independently of
    -- FeatureMgr hotkey registration and therefore works during Startup's boot delay.
    if st.workerStarted~=true and Script and Script.QueueJob then
        st.workerStarted=true
        Script.QueueJob(function()
            if startup.yield then startup.yield(750) elseif Script.Yield then Script.Yield(750) end
            local now=startup.now and startup.now() or 0
            st.armedAtMs=now
            st.armedUntilMs=now+300000
            if startup.toast_quiet then
                startup.toast_quiet("Session-hop guard armed: press "..string.upper(tostring(startup.s.cancelStartupHopHotkeyName or "F8")).." within 5 minutes to cancel automatic Startup hops.",6500)
            end
            while st.cancelled~=true and (startup.now and startup.now() or 0)<=st.armedUntilMs do
                local code=startup.clamp_int(startup.s.cancelStartupHopHotkeyKeyCode or 0x77,0,255)
                local down=false
                if code~=0 and Utils and Utils.IsKeyDown then
                    local ok,value=pcall(Utils.IsKeyDown,code)
                    down=ok and value==true
                end
                if down and st.keyWasDown~=true then
                    startup.cancel_startup_session_hops_build458("Hotkey "..tostring(startup.s.cancelStartupHopHotkeyName or code))
                end
                st.keyWasDown=down
                if startup.yield then startup.yield(50) elseif Script.Yield then Script.Yield(50) else break end
            end
            if st.cancelled~=true then
                startup.s.cancelStartupHopHotkeyLastStatus="5-minute startup cancel window expired"
            end
        end)
    end
end
startup.install_startup_hop_cancel_build458()
startup.install_startup_hop_cancel_build458=nil

startup.version="v1.0.18"
startup.console_version="v1.0.18"
startup.build_number="2026.10.01.458"
startup.build_date="2026-10-01"
startup.build_label="v1.0.18 Production Build 458 - Startup Session-Hop Cancel Hotkey"
startup.changelog_version="2026.10.01.458"
startup.whats_new_version="2026.10.01.458"
startup.release_channel="Production"
if startup.log then
    startup.log("[Build 458] Added F8 startup session-hop cancel guard and fixed Auto Start Online so it never starts another session when GTA Online is already active.")
end
if startup.support_log_event_quiet then
    startup.support_log_event_quiet("BUILD458_STARTUP_HOP_CANCEL_READY","hotkey=F8 window_ms=300000 already_online_skip=true lobby_filter_runtime_cancel=true lua_second_session_runtime_cancel=true settings_persist=false")
end

-- ============================================================================
-- v1.0.18 Production Build 459 - IP-first language + Self / Random Auto-Bounty
-- Language policy requested by user:
--   1) IP-country estimate first
--   2) actual per-player Cherax Player Language feature object fallback
--   3) no chat inference
-- Auto-bounty:
--   None / You (Self) / Random Player / specific live player
--   configurable interval, default 5 minutes
--   exact Minigames ApplyBuiltInBounty(playerId, true) path remains authoritative.
-- ============================================================================
function startup.install_ip_first_self_random_bounty_build459()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    startup.b459_ip_language_map={
        US="English",GB="English",IE="English",AU="English",NZ="English",CA="English",
        FR="French",
        DE="German",AT="German",CH="German",
        IT="Italian",
        ES="Spanish",AR="Spanish",CL="Spanish",CO="Spanish",PE="Spanish",VE="Spanish",
        UY="Spanish",PY="Spanish",BO="Spanish",EC="Spanish",CR="Spanish",PA="Spanish",
        GT="Spanish",HN="Spanish",SV="Spanish",NI="Spanish",DO="Spanish",CU="Spanish",
        BR="Brazilian",PT="Brazilian",
        PL="Polish",
        RU="Russian",BY="Russian",
        KR="Korean",
        TW="Chinese Traditional",HK="Chinese Traditional",MO="Chinese Traditional",
        JP="Japanese",
        MX="Mexican",
        CN="Chinese Simplified"
    }

    function startup.b459_language_from_ip(playerId)
        playerId=tonumber(playerId)
        if playerId==nil or playerId<0 or playerId>31 then return "Unknown","invalid-player" end
        if not (Players and Players.GetIPInfo) then return "Unknown","ip-unavailable" end
        local ok,info=pcall(Players.GetIPInfo,playerId)
        if not ok or type(info)~="table" then return "Unknown","ip-unavailable" end
        local country,countryCode="",""
        pcall(function() country=tostring(info.country or info.countryName or info.country_name or "") end)
        pcall(function() countryCode=tostring(info.countryCode or info.country_code or info.cc or "") end)
        if startup.rid350_country_code then
            local okCode,v=pcall(startup.rid350_country_code,countryCode,country)
            if okCode then countryCode=tostring(v or "") end
        end
        countryCode=tostring(countryCode or ""):upper():gsub("[^A-Z]","")
        local language=startup.b459_ip_language_map[countryCode]
        if language then return language,"ip-estimate:"..countryCode end
        if countryCode~="" then return "Unknown","ip-unmapped:"..countryCode end
        return "Unknown","ip-hidden"
    end

    function startup.b459_language_from_player_feature(playerId)
        playerId=tonumber(playerId)
        if playerId==nil or playerId<0 or playerId>31 then return "Unknown","invalid-player" end
        if not FeatureMgr then return "Unknown","featuremgr-unavailable" end
        local hash=tonumber(startup.regional_warfare_player_language_hash or 307842263) or 307842263
        local feature=nil

        -- Actual per-player feature object first, by stable hash.
        if FeatureMgr.GetFeature then
            local ok,v=pcall(FeatureMgr.GetFeature,hash,playerId)
            if ok and v then feature=v end
        end
        -- Name is compatibility fallback only when hash-object lookup is unavailable.
        if not feature and FeatureMgr.GetFeatureByName then
            local ok,v=pcall(FeatureMgr.GetFeatureByName,"Player Language",playerId)
            if ok and v then feature=v end
        end
        if not feature then return "Unknown","player-feature-missing" end

        if feature.GetStringValue then
            local ok,v=pcall(function() return feature:GetStringValue() end)
            if ok then
                local language=startup.regional_warfare_normalize_language(v)
                if language~="Unknown" then return language,"player-feature-string" end
            end
        end
        if feature.GetListIndex then
            local ok,index=pcall(function() return feature:GetListIndex() end)
            index=ok and tonumber(index) or nil
            if index~=nil and index>=0 then
                if feature.GetList then
                    local okList,list=pcall(function() return feature:GetList() end)
                    if okList and type(list)=="table" then
                        local value=list[index] or list[index+1]
                        local language=startup.regional_warfare_normalize_language(value)
                        if language~="Unknown" then return language,"player-feature-list" end
                    end
                end
                local mapped=startup.b456_language_index_map and startup.b456_language_index_map[index] or nil
                if mapped then return mapped,"player-feature-index" end
            end
        end
        return "Unknown","player-feature-unresolved"
    end

    function startup.regional_warfare_player_language(playerId)
        local language,source=startup.b459_language_from_ip(playerId)
        if language~="Unknown" then return language,source end
        language,source=startup.b459_language_from_player_feature(playerId)
        if language~="Unknown" then return language,source end
        return "Unknown",source or "unavailable"
    end

    -- B459 target mode migration. Existing B455 selected player remains selected.
    local existingId=tonumber(startup.s.regionalWarfareSelectedAutoBountyPlayerId or -1) or -1
    local mode=tostring(startup.s.regionalWarfareAutoBountyTargetMode or "")
    if mode~="none" and mode~="self" and mode~="random" and mode~="player" then
        mode=existingId>=0 and "player" or "none"
    end
    startup.s.regionalWarfareAutoBountyTargetMode=mode
    startup.s.regionalWarfareAutoBountyIntervalSec=math.max(30,math.min(3600,tonumber(startup.s.regionalWarfareAutoBountyIntervalSec or 300) or 300))
    startup.s.regionalWarfareSelectedAutoBountyIntervalMs=startup.s.regionalWarfareAutoBountyIntervalSec*1000
    rw.b459LastRandomKey=tostring(rw.b459LastRandomKey or "")
    rw.b459LastRandomName=tostring(rw.b459LastRandomName or "")

    function startup.b455_selected_bounty_rows(forceRefresh)
        local now=startup.now()
        if forceRefresh~=true and type(rw.b455PlayerRowsCache)=="table" and now-(tonumber(rw.b455PlayerRowsCacheMs or 0) or 0)<1000 then
            return rw.b455PlayerRowsCache
        end
        if startup.b455_refresh_players_minigames_style then pcall(startup.b455_refresh_players_minigames_style) end

        local rows,ids,seen={},{},{}
        local localId=-1
        if startup.regional_warfare_local_player_id then
            local ok,v=pcall(startup.regional_warfare_local_player_id)
            if ok then localId=tonumber(v or -1) or -1 end
        end

        if Players and Players.Get then
            local sortMode=(ePlayerListSort and ePlayerListSort.PLAYER_ID) or 0
            local ok,list=pcall(Players.Get,sortMode,"")
            if ok and type(list)=="table" then
                for _,pid in pairs(list) do
                    pid=tonumber(pid)
                    if pid~=nil and pid>=0 and pid<=31 and not seen[pid] then
                        seen[pid]=true; ids[#ids+1]=pid
                    end
                end
            end
        end
        if localId>=0 and localId<=31 and not seen[localId] then
            seen[localId]=true; ids[#ids+1]=localId
        end
        if #ids==0 and Players and Players.GetById then
            for pid=0,31 do
                local ok,obj=pcall(Players.GetById,pid)
                if ok and obj~=nil and not seen[pid] then seen[pid]=true; ids[#ids+1]=pid end
            end
        end

        table.sort(ids)
        for _,pid in ipairs(ids) do
            local name="Player "..tostring(pid)
            if startup.get_player_name_safe then
                local ok,v=pcall(startup.get_player_name_safe,pid)
                if ok and tostring(v or "")~="" then name=tostring(v) end
            elseif Players and Players.GetName then
                local ok,v=pcall(Players.GetName,pid)
                if ok and tostring(v or "")~="" then name=tostring(v) end
            end

            local rid=""
            if startup.regional_warfare_get_rid then
                local ok,v=pcall(startup.regional_warfare_get_rid,pid)
                if ok then rid=tostring(v or "") end
            end
            if rid=="" and Players and Players.GetById then
                local okP,obj=pcall(Players.GetById,pid)
                if okP and obj and obj.GetGamerInfo then
                    local okI,info=pcall(function() return obj:GetGamerInfo() end)
                    if okI and info then pcall(function() rid=tostring(info.RockstarId or "") end) end
                end
            end

            local language,source="Unknown","unavailable"
            local okLang,a,b=pcall(startup.regional_warfare_player_language,pid)
            if okLang then language=tostring(a or "Unknown"); source=tostring(b or "") end
            rows[#rows+1]={
                playerId=pid,rid=rid,name=name,language=language,languageSource=source,
                isSelf=(pid==localId)
            }
        end

        table.sort(rows,function(a,b)
            if a.isSelf~=b.isSelf then return a.isSelf==true end
            return string.lower(tostring(a.name or ""))<string.lower(tostring(b.name or ""))
        end)
        rw.b455PlayerRowsCache=rows
        rw.b455PlayerRowsCacheMs=now
        return rows
    end

    function startup.b459_self_row(forceRefresh)
        for _,row in ipairs(startup.b455_selected_bounty_rows(forceRefresh==true) or {}) do
            if row.isSelf==true then return row end
        end
        return nil
    end

    function startup.b459_find_live_row(target,forceRefresh)
        if type(target)~="table" then return nil end
        local rid=tostring(target.rid or "")
        local pid=tonumber(target.playerId or -1) or -1
        for _,row in ipairs(startup.b455_selected_bounty_rows(forceRefresh==true) or {}) do
            if rid~="" and tostring(row.rid or "")==rid then return row end
            if rid=="" and tonumber(row.playerId)==pid then return row end
        end
        return nil
    end

    function startup.b459_pick_random_bounty_target(forceRefresh)
        local candidates={}
        for _,row in ipairs(startup.b455_selected_bounty_rows(forceRefresh==true) or {}) do
            if row.isSelf~=true then candidates[#candidates+1]=row end
        end
        if #candidates==0 then return nil end
        if #candidates>1 and rw.b459LastRandomKey~="" then
            local filtered={}
            for _,row in ipairs(candidates) do
                local key=tostring(row.rid or "")~="" and ("rid:"..tostring(row.rid)) or ("pid:"..tostring(row.playerId))
                if key~=rw.b459LastRandomKey then filtered[#filtered+1]=row end
            end
            if #filtered>0 then candidates=filtered end
        end
        local row=candidates[math.random(1,#candidates)]
        rw.b459LastRandomKey=tostring(row.rid or "")~="" and ("rid:"..tostring(row.rid)) or ("pid:"..tostring(row.playerId))
        rw.b459LastRandomName=tostring(row.name or "")
        return row
    end

    function startup.b459_set_bounty_mode(newMode,row)
        newMode=tostring(newMode or "none")
        if newMode~="none" and newMode~="self" and newMode~="random" and newMode~="player" then newMode="none" end
        startup.s.regionalWarfareAutoBountyTargetMode=newMode
        if newMode=="player" and type(row)=="table" then
            startup.s.regionalWarfareSelectedAutoBountyPlayerId=tonumber(row.playerId or -1) or -1
            startup.s.regionalWarfareSelectedAutoBountyPlayerRid=tostring(row.rid or "")
            startup.s.regionalWarfareSelectedAutoBountyPlayerName=tostring(row.name or "")
        elseif newMode~="player" then
            startup.s.regionalWarfareSelectedAutoBountyPlayerId=-1
            startup.s.regionalWarfareSelectedAutoBountyPlayerRid=""
            startup.s.regionalWarfareSelectedAutoBountyPlayerName=""
        end
        rw.b455SelectedBountyLastMs=0
        if newMode=="self" then
            startup.s.regionalWarfareSelectedAutoBountyLastStatus="Selected: You / Self"
        elseif newMode=="random" then
            startup.s.regionalWarfareSelectedAutoBountyLastStatus="Selected: Random Player"
        elseif newMode=="player" and type(row)=="table" then
            startup.s.regionalWarfareSelectedAutoBountyLastStatus="Selected: "..tostring(row.name).." | "..tostring(row.language)
        else
            startup.s.regionalWarfareSelectedAutoBountyLastStatus="No auto-bounty target selected."
        end
        if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
    end

    function startup.b455_select_bounty_target(row)
        if type(row)=="table" then startup.b459_set_bounty_mode("player",row)
        else startup.b459_set_bounty_mode("none") end
    end

    function startup.b455_resolve_selected_bounty_target(forceRefresh)
        local currentMode=tostring(startup.s.regionalWarfareAutoBountyTargetMode or "none")
        if currentMode=="self" then return startup.b459_self_row(forceRefresh==true) end
        if currentMode~="player" then return nil end
        local wantedRid=tostring(startup.s.regionalWarfareSelectedAutoBountyPlayerRid or "")
        local wantedId=tonumber(startup.s.regionalWarfareSelectedAutoBountyPlayerId or -1) or -1
        local wantedName=tostring(startup.s.regionalWarfareSelectedAutoBountyPlayerName or "")
        for _,row in ipairs(startup.b455_selected_bounty_rows(forceRefresh==true) or {}) do
            if wantedRid~="" and tostring(row.rid or "")==wantedRid then return row end
            if wantedRid=="" and tonumber(row.playerId)==wantedId and (wantedName=="" or tostring(row.name)==wantedName) then return row end
        end
        return nil
    end

    function startup.b455_queue_selected_bounty(reason)
        if rw.b455SelectedBountyInFlight==true then
            startup.s.regionalWarfareSelectedAutoBountyLastStatus="Bounty request already running."
            return false
        end
        local targetMode=tostring(startup.s.regionalWarfareAutoBountyTargetMode or "none")
        local target=nil
        if targetMode=="random" then
            target=startup.b459_pick_random_bounty_target(true)
        elseif targetMode=="self" or targetMode=="player" then
            target=startup.b455_resolve_selected_bounty_target(true)
        end
        if not target then
            startup.s.regionalWarfareSelectedAutoBountyLastStatus=(targetMode=="random") and "Random Auto-Bounty waiting: no other players are available." or "Auto-Bounty target is not currently available."
            return false
        end
        if not (Script and Script.QueueJob) then
            startup.s.regionalWarfareSelectedAutoBountyLastStatus="Script.QueueJob unavailable."
            return false
        end

        rw.b455SelectedBountyInFlight=true
        rw.b455SelectedBountyRequestSerial=(tonumber(rw.b455SelectedBountyRequestSerial or 0) or 0)+1
        local serial=rw.b455SelectedBountyRequestSerial
        local queued={
            playerId=tonumber(target.playerId),rid=tostring(target.rid or ""),name=tostring(target.name or ""),
            language=tostring(target.language or "Unknown"),mode=targetMode
        }
        startup.s.regionalWarfareSelectedAutoBountyLastStatus="Queued built-in 9k bounty for "..tostring(queued.name).."..."

        Script.QueueJob(function()
            if startup.b455_refresh_players_minigames_style then startup.b455_refresh_players_minigames_style() end
            local liveTarget=startup.b459_find_live_row(queued,true)
            if not liveTarget then
                startup.s.regionalWarfareSelectedAutoBountyLastStatus="Bounty skipped: "..tostring(queued.name).." left the session."
                rw.b455SelectedBountyInFlight=false
                return
            end
            if queued.rid~="" and tostring(liveTarget.rid or "")~=queued.rid then
                startup.s.regionalWarfareSelectedAutoBountyLastStatus="Bounty skipped: target RID changed."
                rw.b455SelectedBountyInFlight=false
                return
            end

            rw.b455SelectedBountyLastMs=startup.now()
            rw.b455SelectedBountyInFlight=false
            local ok,status=startup.b455_apply_selected_bounty_exact(liveTarget.playerId)
            if ok then
                startup.s.regionalWarfareSelectedAutoBountyLastStatus="Bounty callback fired: "..tostring(liveTarget.name).." | built-in 9k | "..tostring(status)
                startup.s.regionalWarfareLastBountyPlayer=tostring(liveTarget.name or queued.name)
                startup.s.regionalWarfareLastBountyFaction=tostring(liveTarget.language or queued.language)
                startup.s.regionalWarfareBountyCount=(tonumber(startup.s.regionalWarfareBountyCount or 0) or 0)+1
                if startup.support_log_event_quiet then
                    startup.support_log_event_quiet("REGIONAL_WARFARE_B459_AUTO_BOUNTY","player="..tostring(liveTarget.name).." player_id="..tostring(liveTarget.playerId).." rid="..tostring(liveTarget.rid).." mode="..tostring(queued.mode).." reason="..tostring(reason or "manual").." amount=9k serial="..tostring(serial))
                end
            else
                startup.s.regionalWarfareSelectedAutoBountyLastStatus="Bounty failed: "..tostring(liveTarget.name).." | "..tostring(status)
            end
        end)
        return true
    end

    function startup.b455_selected_auto_bounty_tick()
        if startup.s.regionalWarfareSelectedAutoBountyEnabled~=true then return end
        if rw.b455SelectedBountyInFlight==true then return end
        local currentMode=tostring(startup.s.regionalWarfareAutoBountyTargetMode or "none")
        if currentMode=="none" then
            startup.s.regionalWarfareSelectedAutoBountyLastStatus="Auto-Bounty waiting: choose You, Random, or a player."
            return
        end
        if currentMode~="random" and not startup.b455_resolve_selected_bounty_target(false) then
            startup.s.regionalWarfareSelectedAutoBountyLastStatus="Auto-Bounty waiting: selected target is unavailable."
            return
        end
        local now=startup.now()
        local intervalMs=math.max(30000,math.min(3600000,(tonumber(startup.s.regionalWarfareAutoBountyIntervalSec or 300) or 300)*1000))
        startup.s.regionalWarfareSelectedAutoBountyIntervalMs=intervalMs
        local last=tonumber(rw.b455SelectedBountyLastMs or 0) or 0
        if last==0 or now-last>=intervalMs then
            startup.b455_queue_selected_bounty("Auto "..currentMode.." interval="..tostring(math.floor(intervalMs/1000)).."s")
        end
    end

    -- Replace B457's appended panel with a B459-safe version while preserving the
    -- underlying Regional Warfare base renderer. No FeatureMgr/player calls occur
    -- while ImGui combo scopes are open.
    rw.b459BaseRender=rw.b457BaseRender or rw.b455PreviousRenderRegionalWarfare or startup.render_regional_warfare
    function startup.render_regional_warfare()
        if rw.b459BaseRender then
            local okBase,errBase=pcall(rw.b459BaseRender)
            if not okBase and startup.log then startup.log("[Build 459][REGIONAL_WARFARE_BASE_RENDER_RECOVERED] "..tostring(errBase)) end
        end
        if not (ClickGUI and ImGui and ClickGUI.BeginCustomChildWindow and ClickGUI.EndCustomChildWindow) then return end

        -- All live data is resolved before opening the child.
        local rows={}
        local okRows,resultRows=pcall(startup.b455_selected_bounty_rows,false)
        if okRows and type(resultRows)=="table" then rows=resultRows end
        local selfRow=nil
        local playerRows={}
        for _,row in ipairs(rows) do
            if row.isSelf==true then selfRow=row else playerRows[#playerRows+1]=row end
        end

        local targetMode=tostring(startup.s.regionalWarfareAutoBountyTargetMode or "none")
        local selected=nil
        if targetMode=="self" then selected=selfRow
        elseif targetMode=="player" then
            local okSel,v=pcall(startup.b455_resolve_selected_bounty_target,false)
            if okSel then selected=v end
        end
        local preview="None"
        if targetMode=="self" then preview="You / Self"..(selfRow and (" - "..tostring(selfRow.name).." • "..tostring(selfRow.language)) or "")
        elseif targetMode=="random" then preview="Random Player"
        elseif targetMode=="player" and selected then preview="["..tostring(selected.playerId).."] "..tostring(selected.name).." • "..tostring(selected.language)
        end

        local actionMode=nil
        local actionRow=nil
        local autoChanged=nil
        local manualClicked=false
        local intervalChanged=nil
        local childOpened=false
        local okBegin,beginResult=pcall(ClickGUI.BeginCustomChildWindow,"Regional Warfare Auto-Bounty Target")
        if okBegin and beginResult==true then childOpened=true end

        if childOpened then
            local okBody,bodyErr=pcall(function()
                startup.section_title("Auto-Bounty Target")
                startup.subtle_text_wrapped("Choose You, Random Player, or one live session player. Random excludes you and avoids picking the same person twice in a row when possible. Bounties use Minigames' built-in anonymous 9k path.")

                if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(-1) end
                local comboOpen=false
                if ImGui.BeginCombo then
                    local okCombo,v=pcall(ImGui.BeginCombo,"Target##StartupB459AutoBountyTarget",preview)
                    comboOpen=okCombo and v==true
                end
                if comboOpen then
                    local okOptions,optionsErr=pcall(function()
                        if ImGui.Selectable("None##StartupB459TargetNone",targetMode=="none") then actionMode="none" end
                        if ImGui.Selectable("You / Self##StartupB459TargetSelf",targetMode=="self") then actionMode="self" end
                        if ImGui.Selectable("Random Player##StartupB459TargetRandom",targetMode=="random") then actionMode="random" end
                        for _,row in ipairs(playerRows) do
                            local isSelected=targetMode=="player" and selected and tonumber(selected.playerId)==tonumber(row.playerId) and tostring(selected.rid or "")==tostring(row.rid or "")
                            local label="["..tostring(row.playerId).."] "..tostring(row.name).." • "..tostring(row.language).."##StartupB459Target"..tostring(row.playerId)..tostring(row.rid)
                            if ImGui.Selectable(label,isSelected==true) then actionMode="player"; actionRow=row end
                        end
                    end)
                    pcall(ImGui.EndCombo)
                    if not okOptions and startup.log then startup.log("[Build 459][TARGET_COMBO_RECOVERED] "..tostring(optionsErr)) end
                end

                startup.subtle_text("Language source: IP-country estimate first, Cherax per-player feature fallback. No chat detection.")

                -- Interval presets keep the UI stable across Cherax ImGui builds.
                local intervalOptions={
                    {label="30 seconds",sec=30},{label="1 minute",sec=60},{label="2 minutes",sec=120},
                    {label="5 minutes",sec=300},{label="10 minutes",sec=600},{label="15 minutes",sec=900},
                    {label="30 minutes",sec=1800},{label="60 minutes",sec=3600}
                }
                local currentSec=tonumber(startup.s.regionalWarfareAutoBountyIntervalSec or 300) or 300
                local intervalPreview=tostring(math.floor(currentSec/60)).." minutes"
                for _,opt in ipairs(intervalOptions) do if opt.sec==currentSec then intervalPreview=opt.label break end end
                if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(-1) end
                local intervalOpen=false
                if ImGui.BeginCombo then
                    local okCombo,v=pcall(ImGui.BeginCombo,"Bounty Interval##StartupB459BountyInterval",intervalPreview)
                    intervalOpen=okCombo and v==true
                end
                if intervalOpen then
                    local okOptions,optionsErr=pcall(function()
                        for _,opt in ipairs(intervalOptions) do
                            if ImGui.Selectable(tostring(opt.label).."##StartupB459Interval"..tostring(opt.sec),currentSec==opt.sec) then intervalChanged=opt.sec end
                        end
                    end)
                    pcall(ImGui.EndCombo)
                    if not okOptions and startup.log then startup.log("[Build 459][INTERVAL_COMBO_RECOVERED] "..tostring(optionsErr)) end
                end

                local oldAuto=startup.s.regionalWarfareSelectedAutoBountyEnabled==true
                if ImGui.Checkbox then
                    local newAuto=ImGui.Checkbox("Auto-Bounty##StartupB459AutoBountyToggle",oldAuto)
                    if newAuto~=oldAuto then autoChanged=newAuto==true end
                end
                startup.hover_help("Applies immediately when enabled, then repeats using the selected interval. Random chooses a fresh remote player each cycle.")

                if ImGui.Button and ImGui.Button("Apply Bounty Now##StartupB459BountyNow",-1,30)==true then manualClicked=true end
                startup.hover_help("You/Self uses the same forced Minigames bounty path. Random picks one remote player immediately.")

                local sec=tonumber(startup.s.regionalWarfareAutoBountyIntervalSec or 300) or 300
                startup.subtle_text("Interval: "..tostring(sec<60 and (tostring(sec).." sec") or (tostring(math.floor(sec/60)).." min")).." • Amount: built-in 9k • Minigames path")
                startup.subtle_text_wrapped(tostring(startup.s.regionalWarfareSelectedAutoBountyLastStatus or "Ready."))
                if rw.b459LastRandomName~="" then startup.subtle_text("Last random target: "..tostring(rw.b459LastRandomName)) end
                if not okRows then startup.subtle_text_wrapped("Roster refresh recovered from a transient player lookup error.") end
            end)
            pcall(ClickGUI.EndCustomChildWindow)
            if not okBody and startup.log then startup.log("[Build 459][AUTO_BOUNTY_UI_RECOVERED] "..tostring(bodyErr)) end
        end

        -- State mutations happen after all ImGui scopes are closed.
        if actionMode then
            pcall(startup.b459_set_bounty_mode,actionMode,actionRow)
            if startup.s.regionalWarfareSelectedAutoBountyEnabled==true and actionMode~="none" then pcall(startup.b455_queue_selected_bounty,"Target changed") end
        end
        if intervalChanged then
            startup.s.regionalWarfareAutoBountyIntervalSec=tonumber(intervalChanged) or 300
            startup.s.regionalWarfareSelectedAutoBountyIntervalMs=startup.s.regionalWarfareAutoBountyIntervalSec*1000
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end
        if autoChanged~=nil then
            startup.s.regionalWarfareSelectedAutoBountyEnabled=autoChanged==true
            rw.b455SelectedBountyLastMs=0
            if startup.h and startup.h.RegionalWarfareSelectedAutoBounty and startup.set_feature_bool_silently then
                pcall(startup.set_feature_bool_silently,startup.h.RegionalWarfareSelectedAutoBounty,autoChanged==true)
            end
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
            if autoChanged==true then pcall(startup.b455_queue_selected_bounty,"Auto enabled") end
        end
        if manualClicked==true then pcall(startup.b455_queue_selected_bounty,"Manual") end
    end

    rw.b455PlayerRowsCache=nil
    rw.b455PlayerRowsCacheMs=0
end
