-- ============================================================================
-- v1.0.18 Production Build 460 - Staggered Regional Warfare bounty queue
-- Replaces the old 2.5-second enemy sweep with a true round-robin queue.
-- Each eligible enemy-language player is processed once per cycle before the
-- queue loops back to the first player. Default spacing: 60 seconds per player.
-- ============================================================================
function startup.install_staggered_bounty_queue_build460()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    -- B459 and older builds defaulted this to 2500 ms and never persisted it.
    -- Migrate that legacy/default value to the new one-minute production default.
    local currentGap=tonumber(startup.s.regionalWarfareBountyGapMs or 0) or 0
    if currentGap<=2500 then currentGap=60000 end
    startup.s.regionalWarfareBountyGapMs=math.max(15000,math.min(600000,currentGap))

    rw.b460Queue=type(rw.b460Queue)=="table" and rw.b460Queue or {}
    rw.b460QueueCursor=tonumber(rw.b460QueueCursor or 1) or 1
    rw.b460QueueCycle=tonumber(rw.b460QueueCycle or 0) or 0
    rw.b460LastQueueBountyMs=tonumber(rw.b460LastQueueBountyMs or 0) or 0
    rw.b460QueueManual=rw.b460QueueManual==true

    function startup.b460_target_key(row)
        if type(row)~="table" then return "" end
        local rid=tostring(row.rid or "")
        if rid~="" then return "rid:"..rid end
        return "pid:"..tostring(row.playerId or -1)..":"..tostring(row.name or "")
    end

    function startup.b460_build_enemy_queue(enemies,manual)
        local list={}
        for _,row in ipairs(enemies or {}) do list[#list+1]=row end
        table.sort(list,function(a,b)
            local ap=tonumber(a.playerId or 99) or 99
            local bp=tonumber(b.playerId or 99) or 99
            if ap~=bp then return ap<bp end
            return string.lower(tostring(a.name or ""))<string.lower(tostring(b.name or ""))
        end)
        rw.b460Queue={}
        for _,row in ipairs(list) do
            rw.b460Queue[#rw.b460Queue+1]={
                key=startup.b460_target_key(row),
                rid=tostring(row.rid or ""),
                playerId=tonumber(row.playerId or -1) or -1,
                name=tostring(row.name or ""),
                language=tostring(row.language or "Unknown")
            }
        end
        rw.b460QueueCursor=1
        rw.b460QueueCycle=(tonumber(rw.b460QueueCycle or 0) or 0)+1
        rw.b460QueueManual=manual==true
        return #rw.b460Queue
    end

    function startup.b460_find_enemy_for_queue_entry(entry,enemies)
        if type(entry)~="table" then return nil end
        local wantedKey=tostring(entry.key or "")
        for _,row in ipairs(enemies or {}) do
            if startup.b460_target_key(row)==wantedKey then return row end
        end
        return nil
    end

    function startup.b460_next_live_queue_target(enemies)
        while rw.b460QueueCursor<=#(rw.b460Queue or {}) do
            local index=rw.b460QueueCursor
            local entry=rw.b460Queue[index]
            rw.b460QueueCursor=index+1
            local row=startup.b460_find_enemy_for_queue_entry(entry,enemies)
            if row then return row,index,#rw.b460Queue end
        end
        return nil,nil,#(rw.b460Queue or {})
    end

    -- Final B460 enemy-language bounty selector. The existing B448 background
    -- worker continues to call this function, but only one queued player can be
    -- processed per configured spacing interval.
    function startup.regional_warfare_tick_core_448(force)
        local manual=force==true or rw.forceSweep==true or rw.b460QueueManual==true
        if startup.s.regionalWarfareEnabled~=true then return end
        if startup.s.regionalWarfareAutoBounty~=true and not manual then return end

        local own,ownSource=startup.regional_warfare_own_language()
        own=startup.regional_warfare_normalize_language(own)
        if own=="Unknown" then
            startup.s.regionalWarfareLastStatus="My Player Language is unavailable. Choose My Warfare Language manually."
            return
        end

        local now=startup.now()
        local scanMs=math.max(500,tonumber(startup.s.regionalWarfareScanMs or 1000) or 1000)
        if not manual and now-(tonumber(rw.lastScanMs or 0) or 0)<scanMs then return end
        rw.lastScanMs=now

        local roster=startup.regional_warfare_roster()
        local enemies={}
        for _,row in ipairs(roster or {}) do
            if row.enemy==true then enemies[#enemies+1]=row end
        end

        if #roster==0 then
            startup.s.regionalWarfareLastStatus="No remote Cherax player objects detected yet."
            return
        end
        if #enemies==0 then
            startup.s.regionalWarfareLastStatus="No enemy Player Language teams detected. My team: "..tostring(own).." ("..tostring(ownSource)..")"
            rw.b460Queue={}; rw.b460QueueCursor=1
            if rw.forceSweep==true then rw.forceSweep=false; rw.b460QueueManual=false end
            return
        end

        -- Build a fresh snapshot only when a cycle is empty/complete. New players
        -- join the next cycle, which keeps the current A -> B -> C ordering stable.
        if type(rw.b460Queue)~="table" or #rw.b460Queue==0 or rw.b460QueueCursor>#rw.b460Queue then
            if rw.b460QueueManual==true and rw.b460QueueCursor>#(rw.b460Queue or {}) and #(rw.b460Queue or {})>0 then
                rw.b460Queue={}; rw.b460QueueCursor=1; rw.b460QueueManual=false; rw.forceSweep=false
                startup.s.regionalWarfareLastStatus="Enemy-language bounty queue complete."
                if startup.s.regionalWarfareAutoBounty~=true then return end
                manual=false
            end
            startup.b460_build_enemy_queue(enemies,manual)
        end

        local gap=math.max(15000,math.min(600000,tonumber(startup.s.regionalWarfareBountyGapMs or 60000) or 60000))
        startup.s.regionalWarfareBountyGapMs=gap
        local elapsed=now-(tonumber(rw.b460LastQueueBountyMs or 0) or 0)
        if rw.b460LastQueueBountyMs>0 and elapsed<gap then
            local remaining=math.max(0,math.ceil((gap-elapsed)/1000))
            local nextEntry=(rw.b460Queue or {})[rw.b460QueueCursor]
            startup.s.regionalWarfareLastStatus="Bounty queue "..tostring(math.max(0,rw.b460QueueCursor-1)).."/"..tostring(#rw.b460Queue).." complete • next in "..tostring(remaining).."s"..(nextEntry and (" • "..tostring(nextEntry.name)) or "")
            return
        end

        local target,queueIndex,queueCount=startup.b460_next_live_queue_target(enemies)
        if not target then
            -- Remaining snapshot entries left the session or stopped being enemies.
            -- End this cycle and let the next tick rebuild from the live roster.
            if rw.b460QueueManual==true then
                rw.forceSweep=false; rw.b460QueueManual=false
                startup.s.regionalWarfareLastStatus="Enemy-language bounty queue complete."
            end
            rw.b460Queue={}; rw.b460QueueCursor=1
            return
        end

        rw.b460LastQueueBountyMs=now
        rw.lastBountyMs=now
        local targetKey=startup.b460_target_key(target)
        rw.lastAttempt=rw.lastAttempt or {}
        rw.lastApplied=rw.lastApplied or {}
        rw.lastAttempt[targetKey]=now

        local ok,status=startup.regional_warfare_apply_bounty_retry_449(target)
        if ok then
            rw.lastApplied[targetKey]=startup.now()
            startup.s.regionalWarfareLastBountyPlayer=tostring(target.name or "")
            startup.s.regionalWarfareLastBountyFaction=tostring(target.language or "")
            startup.s.regionalWarfareBountyCount=(tonumber(startup.s.regionalWarfareBountyCount or 0) or 0)+1
            startup.s.regionalWarfareLastStatus="Bounty queue "..tostring(queueIndex).."/"..tostring(queueCount)..": "..tostring(target.name).." | "..tostring(target.language).." | next in "..tostring(math.floor(gap/1000)).."s"
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("REGIONAL_WARFARE_B460_STAGGERED_BOUNTY","player="..tostring(target.name).." player_id="..tostring(target.playerId).." rid="..tostring(target.rid).." language="..tostring(target.language).." queue_index="..tostring(queueIndex).." queue_count="..tostring(queueCount).." gap_ms="..tostring(gap).." status="..tostring(status))
            end
        else
            startup.s.regionalWarfareLastStatus="Bounty queue "..tostring(queueIndex).."/"..tostring(queueCount).." failed: "..tostring(target.name).." | "..tostring(status).." • continuing in "..tostring(math.floor(gap/1000)).."s"
        end
        rw.lastScanMs=0
    end

    -- Manual sweep now starts the same serialized queue instead of rapidly
    -- walking all players. First target fires immediately; later targets respect spacing.
    function startup.regional_warfare_force_bounty_scan()
        rw.forceSweep=true
        rw.b460QueueManual=true
        rw.b460Queue={}
        rw.b460QueueCursor=1
        rw.b460LastQueueBountyMs=0
        rw.lastScanMs=0
        startup.s.regionalWarfareLastStatus="Starting staggered enemy-language bounty queue..."
        if startup.start_regional_warfare_background_448 then startup.start_regional_warfare_background_448() end
    end

    -- Add a small independent config panel after B459's target panel. Plain ImGui
    -- only, preserving the balanced-scope fix from B457.
    rw.b460BaseRender=startup.render_regional_warfare
    function startup.render_regional_warfare()
        if rw.b460BaseRender then
            local ok,err=pcall(rw.b460BaseRender)
            if not ok and startup.log then startup.log("[Build 460][REGIONAL_WARFARE_RENDER_RECOVERED] "..tostring(err)) end
        end
        if not (ClickGUI and ImGui and ClickGUI.BeginCustomChildWindow and ClickGUI.EndCustomChildWindow) then return end

        local spacingChanged=nil
        local opened=false
        local okBegin,v=pcall(ClickGUI.BeginCustomChildWindow,"Regional Warfare Bounty Queue")
        if okBegin and v==true then opened=true end
        if opened then
            local okBody,bodyErr=pcall(function()
                startup.section_title("Enemy Auto-Bounty Queue")
                startup.subtle_text_wrapped("Enemy-language Auto Bounty is round-robin: every eligible player gets one turn before the queue loops. The first player is immediate, then Startup waits the configured spacing before each next player.")
                local options={
                    {label="15 seconds",ms=15000},{label="30 seconds",ms=30000},{label="1 minute",ms=60000},
                    {label="2 minutes",ms=120000},{label="5 minutes",ms=300000},{label="10 minutes",ms=600000}
                }
                local current=math.max(15000,math.min(600000,tonumber(startup.s.regionalWarfareBountyGapMs or 60000) or 60000))
                local preview="1 minute"
                for _,opt in ipairs(options) do if opt.ms==current then preview=opt.label break end end
                if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(-1) end
                local combo=false
                if ImGui.BeginCombo then
                    local okCombo,result=pcall(ImGui.BeginCombo,"Per-Player Bounty Spacing##StartupB460BountySpacing",preview)
                    combo=okCombo and result==true
                end
                if combo then
                    local okOptions,optionsErr=pcall(function()
                        for _,opt in ipairs(options) do
                            if ImGui.Selectable(tostring(opt.label).."##StartupB460Gap"..tostring(opt.ms),current==opt.ms) then spacingChanged=opt.ms end
                        end
                    end)
                    pcall(ImGui.EndCombo)
                    if not okOptions and startup.log then startup.log("[Build 460][BOUNTY_SPACING_COMBO_RECOVERED] "..tostring(optionsErr)) end
                end
                local count=type(rw.b460Queue)=="table" and #rw.b460Queue or 0
                local done=math.max(0,(tonumber(rw.b460QueueCursor or 1) or 1)-1)
                if done>count then done=count end
                startup.subtle_text("Queue progress: "..tostring(done).." / "..tostring(count).." • Cycle: "..tostring(tonumber(rw.b460QueueCycle or 0) or 0))
                local nextEntry=type(rw.b460Queue)=="table" and rw.b460Queue[rw.b460QueueCursor] or nil
                if nextEntry then startup.subtle_text("Next: "..tostring(nextEntry.name).." • "..tostring(nextEntry.language)) end
            end)
            pcall(ClickGUI.EndCustomChildWindow)
            if not okBody and startup.log then startup.log("[Build 460][BOUNTY_QUEUE_UI_RECOVERED] "..tostring(bodyErr)) end
        end
        if spacingChanged then
            startup.s.regionalWarfareBountyGapMs=tonumber(spacingChanged) or 60000
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end
    end

    -- Start a clean queue on this build so legacy 2.5-second timing cannot leak in.
    rw.b460Queue={}
    rw.b460QueueCursor=1
    rw.b460LastQueueBountyMs=0
end
startup.install_staggered_bounty_queue_build460()
startup.install_staggered_bounty_queue_build460=nil

