-- ============================================================================
-- v1.0.18 Production Build 461 - IP-authoritative Regional Warfare colors
-- - Minimap color identity is resolved directly from Players.GetIPInfo each scan.
-- - Clear country-code mappings are authoritative for color selection.
-- - Ambiguous/hidden/unmapped IP results fall back to the actual per-player
--   Cherax Player Language feature object.
-- - No chat inference. Unknown players keep Rockstar's original blip color.
-- ============================================================================
function startup.install_ip_authoritative_colors_build461()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    -- Only map country codes where the existing Cherax language bucket is a
    -- sensible direct fit. Multilingual/ambiguous countries intentionally fall
    -- through to the per-player Cherax feature instead of being guessed.
    startup.b461_ip_language_map={
        US="English",GB="English",IE="English",AU="English",NZ="English",
        FR="French",
        DE="German",AT="German",
        IT="Italian",
        ES="Spanish",AR="Spanish",CL="Spanish",CO="Spanish",PE="Spanish",VE="Spanish",
        UY="Spanish",PY="Spanish",BO="Spanish",EC="Spanish",CR="Spanish",PA="Spanish",
        GT="Spanish",HN="Spanish",SV="Spanish",NI="Spanish",DO="Spanish",CU="Spanish",
        PR="Spanish",
        BR="Brazilian",PT="Brazilian",
        PL="Polish",
        RU="Russian",BY="Russian",
        KR="Korean",
        TW="Chinese Traditional",HK="Chinese Traditional",MO="Chinese Traditional",
        JP="Japanese",
        MX="Mexican",
        CN="Chinese Simplified"
    }

    rw.b461ColorSource=rw.b461ColorSource or {}

    function startup.b461_country_code_from_ip(playerId)
        playerId=tonumber(playerId)
        if playerId==nil or playerId<0 or playerId>31 then return "","","invalid-player" end
        if not (Players and Players.GetIPInfo) then return "","","ip-unavailable" end
        local ok,info=pcall(Players.GetIPInfo,playerId)
        if not ok or type(info)~="table" then return "","","ip-unavailable" end
        local country,countryCode="",""
        pcall(function() country=tostring(info.country or info.countryName or info.country_name or "") end)
        pcall(function() countryCode=tostring(info.countryCode or info.country_code or info.cc or "") end)
        if startup.rid350_country_code then
            local okCode,v=pcall(startup.rid350_country_code,countryCode,country)
            if okCode then countryCode=tostring(v or "") end
        end
        countryCode=tostring(countryCode or ""):upper():gsub("[^A-Z]","")
        if #countryCode~=2 then countryCode="" end
        return countryCode,country,countryCode~="" and "ip" or "ip-hidden"
    end

    function startup.b461_color_identity(playerId)
        local countryCode,country,ipStatus=startup.b461_country_code_from_ip(playerId)
        local language=countryCode~="" and startup.b461_ip_language_map[countryCode] or nil
        if language then
            return language,"ip-country:"..countryCode,countryCode,country
        end

        -- IP exists but is intentionally unmapped/ambiguous, or IP is hidden.
        -- Fall back to the actual indexed Cherax player feature object only.
        if startup.b459_language_from_player_feature then
            local ok,a,b=pcall(startup.b459_language_from_player_feature,playerId)
            if ok then
                local fallback=startup.regional_warfare_normalize_language and startup.regional_warfare_normalize_language(a) or tostring(a or "Unknown")
                if fallback~="Unknown" and fallback~="" then
                    local reason=countryCode~="" and ("cherax-fallback:ip-"..countryCode..":"..tostring(b or "feature")) or ("cherax-fallback:"..tostring(b or ipStatus or "feature"))
                    return fallback,reason,countryCode,country
                end
            end
        end
        return "Unknown",countryCode~="" and ("ip-unmapped:"..countryCode) or tostring(ipStatus or "unavailable"),countryCode,country
    end

    -- Keep all other Regional Warfare consumers aligned with the same identity
    -- source so roster text, enemy policy, and color diagnostics agree.
    function startup.regional_warfare_player_language(playerId)
        local language,source=startup.b461_color_identity(playerId)
        return language,source
    end

    -- B461 bypasses row.language when painting blips. Every color scan performs
    -- its own IP-country lookup, then stores only the lightweight RGB result for
    -- the existing ON_PRESENT / ON_POST_PRESENT reassertion hooks.
    function startup.regional_warfare_apply_blip_colors_449(force)
        local now=startup.now()
        if force~=true and now-(tonumber(rw.lastBlipColorScanMs or 0) or 0)<750 then return end
        rw.lastBlipColorScanMs=now

        if startup.s.regionalWarfareEnabled~=true or startup.s.regionalWarfareColorPlayers==false then
            if next(rw.blipOriginal or {})~=nil and startup.regional_warfare_restore_blip_colors_449 then
                startup.regional_warfare_restore_blip_colors_449()
            end
            rw.blipFrameTargets453={}
            rw.b461ColorSource={}
            return
        end

        local active={}
        local frameTargets={}
        local ids=startup.regional_warfare_player_ids_449 and startup.regional_warfare_player_ids_449() or {}

        for _,playerId in ipairs(ids or {}) do
            playerId=tonumber(playerId)
            if playerId~=nil and not (startup.is_local_player_id and startup.is_local_player_id(playerId)) then
                active[playerId]=true
                local language,source,countryCode,country=startup.b461_color_identity(playerId)
                language=startup.regional_warfare_normalize_language and startup.regional_warfare_normalize_language(language) or tostring(language or "Unknown")
                rw.b461ColorSource[playerId]={language=language,source=source,countryCode=countryCode,country=country}

                local blip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0
                if blip~=0 then
                    local original=rw.blipOriginal[playerId]
                    if type(original)~="table" or tonumber(original.blip or 0)~=blip then
                        rw.blipOriginal[playerId]={
                            blip=blip,
                            color=startup.regional_warfare_get_blip_color_449 and startup.regional_warfare_get_blip_color_449(blip) or nil
                        }
                    end
                    local r,g,b,colorName=startup.regional_warfare_rgb_for_language_454(language)
                    rw.blipApplied[playerId]={
                        blip=blip,r=r,g=g,b=b,language=language,colorName=colorName,
                        source=source,countryCode=countryCode,country=country
                    }
                    frameTargets[blip]={
                        playerId=playerId,r=r,g=g,b=b,language=language,colorName=colorName,
                        source=source,countryCode=countryCode,country=country
                    }
                    startup.regional_warfare_set_custom_blip_rgb_454(blip,r,g,b)
                else
                    -- No usable player blip exists. Clear any stale Startup color state
                    -- for this slot. Unknown is painted Purple whenever a blip exists.
                    local previous=rw.blipOriginal[playerId]
                    if type(previous)=="table" and tonumber(previous.blip or 0)~=0 and previous.color~=nil and Natives and Natives.InvokeVoid then
                        Natives.InvokeVoid(0x03D7FB09E75D6B7E,tonumber(previous.blip),tonumber(previous.color))
                    end
                    rw.blipOriginal[playerId]=nil
                    rw.blipApplied[playerId]=nil
                end
            end
        end

        for playerId,_ in pairs(rw.blipOriginal or {}) do
            if active[playerId]~=true then
                rw.blipOriginal[playerId]=nil
                rw.blipApplied[playerId]=nil
                rw.b461ColorSource[playerId]=nil
            end
        end
        rw.blipFrameTargets453=frameTargets
    end

    -- Surface the current source in the existing roster UI without adding a new
    -- heavy diagnostics window. This wrapper only appends one subtle explanation.
    if rw.b461RenderWrapped~=true then
        rw.b461RenderWrapped=true
        rw.b461BaseRender=startup.render_regional_warfare
        function startup.render_regional_warfare()
            if rw.b461BaseRender then rw.b461BaseRender() end
            if startup.subtle_text then
                startup.subtle_text("Player marker colors: IP country first -> Cherax Player Language fallback. Unknown = Purple.")
            end
        end
    end

    rw.lastBlipColorScanMs=0
    rw.blipFrameTargets453={}
    rw.blipApplied={}
    rw.b461ColorSource={}
    rw.b455RowsCache=nil
    rw.b455RowsCacheMs=0
    if startup.regional_warfare_apply_blip_colors_449 then startup.regional_warfare_apply_blip_colors_449(true) end
end
