-- ============================================================================
-- BUILD 462: IP PLAYER COLOR PALETTE
-- Requested palette:
--   English = Green
--   Spanish / Mexican = Orange
--   Unknown = Purple
--   Chinese Traditional / Simplified = Red
--   Russian = Blue
-- Remaining languages use distinct complementary colors.
-- Existing custom selections are preserved. Only prior Startup defaults migrate.
-- ============================================================================
function startup.install_ip_color_palette_build462()
    startup.s.regionalWarfareLanguageColors = type(startup.s.regionalWarfareLanguageColors)=="table" and startup.s.regionalWarfareLanguageColors or {}

    startup.regional_warfare_default_language_colors = {
        ["English"]="Green",
        ["French"]="Light Blue",
        ["German"]="Yellow",
        ["Italian"]="Light Green",
        ["Spanish"]="Orange",
        ["Brazilian"]="Light Green",
        ["Polish"]="Light Red",
        ["Russian"]="Blue",
        ["Korean"]="Light Blue",
        ["Japanese"]="Pink",
        ["Mexican"]="Orange",
        ["Chinese Traditional"]="Red",
        ["Chinese Simplified"]="Red",
        ["Unknown"]="Purple"
    }

    -- Migrate only values that still match Startup's previous B449/B461 defaults.
    -- A value changed by the user is left untouched.
    local previousDefaults = {
        ["English"]="Green",
        ["French"]="Light Blue",
        ["German"]="Yellow",
        ["Italian"]="Light Green",
        ["Spanish"]="Orange",
        ["Brazilian"]="Green",
        ["Polish"]="Purple",
        ["Russian"]="Red",
        ["Korean"]="Light Blue",
        ["Japanese"]="Pink",
        ["Mexican"]="Light Orange",
        ["Chinese Traditional"]="Blue",
        ["Chinese Simplified"]="Blue",
        ["Unknown"]="Gray"
    }

    local changed=false
    for language,newColor in pairs(startup.regional_warfare_default_language_colors) do
        local current=tostring(startup.s.regionalWarfareLanguageColors[language] or "")
        if current=="" or current==tostring(previousDefaults[language] or "") then
            if current~=newColor then changed=true end
            startup.s.regionalWarfareLanguageColors[language]=newColor
        end
    end

    -- B461 intentionally left Unknown untouched. B462 makes Unknown a visible
    -- Purple category now that IP-first identification keeps it uncommon.
    if startup.regional_warfare_runtime then
        startup.regional_warfare_runtime.lastBlipColorScanMs=0
        startup.regional_warfare_runtime.blipApplied={}
        startup.regional_warfare_runtime.blipFrameTargets453={}
        startup.regional_warfare_runtime.b461ColorSource={}
    end

    if changed and startup.s.initialized and startup.save_config then
        pcall(startup.save_config,false)
    end
    if startup.regional_warfare_apply_blip_colors_449 then
        pcall(startup.regional_warfare_apply_blip_colors_449,true)
    end
end
