-- ============================================================================
-- BUILD 464: STABLE PLAYER MARKERS + SOCIAL OVERRIDES + DROPDOWN UI
-- - Fixes custom-RGB white flashing by writing secondary RGB before enabling custom 84.
-- - Avoids re-writing SET_BLIP_COLOUR(84) when the live blip is already custom RGB.
-- - Adds None as the first marker-color choice.
-- - Adds Friends and Tracked marker overrides (Friends Dark Green, Tracked Red).
-- - Replaces the three always-open Regional Warfare panels with collapsible headers.
-- ============================================================================
function startup.install_stable_social_markers_dropdowns_build464()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    -- B464 palette. "None" is intentionally first and means no language marker
    -- override. Social overrides can also be set to None, in which case the
    -- language/IP color is allowed to continue underneath them.
    startup.regional_warfare_color_names={
        "None",
        "White","Gray","Red","Light Red","Blue","Light Blue",
        "Yellow","Light Yellow","Orange","Light Orange","Green","Dark Green",
        "Light Green","Purple","Light Purple","Pink"
    }
    startup.regional_warfare_color_ids=startup.regional_warfare_color_ids or {}
    startup.regional_warfare_color_ids["None"]=0
    startup.regional_warfare_color_ids["Dark Green"]=18
    startup.regional_warfare_color_rgb_454=startup.regional_warfare_color_rgb_454 or {}
    startup.regional_warfare_color_rgb_454["Dark Green"]={28,145,58}

    startup.s.regionalWarfareLanguageColors=type(startup.s.regionalWarfareLanguageColors)=="table" and startup.s.regionalWarfareLanguageColors or {}
    if tostring(startup.s.regionalWarfareLanguageColors.__Friends or "")=="" then startup.s.regionalWarfareLanguageColors.__Friends="Dark Green" end
    if tostring(startup.s.regionalWarfareLanguageColors.__Tracked or "")=="" then startup.s.regionalWarfareLanguageColors.__Tracked="Red" end

    function startup.regional_warfare_color_name(language)
        language=startup.regional_warfare_normalize_language and startup.regional_warfare_normalize_language(language) or tostring(language or "Unknown")
        local value=tostring(startup.s.regionalWarfareLanguageColors[language] or startup.regional_warfare_default_language_colors[language] or "Gray")
        if startup.regional_warfare_color_ids[value]==nil then value="Gray" end
        return value
    end

    function startup.regional_warfare_rgb_for_language_454(language)
        local colorName=startup.regional_warfare_color_name(language)
        if colorName=="None" then return nil,nil,nil,"None" end
        local rgb=startup.regional_warfare_color_rgb_454[colorName] or startup.regional_warfare_color_rgb_454.Gray or {165,165,175}
        return tonumber(rgb[1]) or 165,tonumber(rgb[2]) or 165,tonumber(rgb[3]) or 175,colorName
    end

    -- B454 used primary/custom mode first, then secondary RGB. When GTA reset a
    -- player blip between frames this could expose the stock white/custom value for
    -- a render instant. B464 primes RGB first and only switches primary to 84 when
    -- the live blip is not already custom-RGB.
    function startup.regional_warfare_set_custom_blip_rgb_454(blip,r,g,b)
        blip=tonumber(blip or 0) or 0
        if blip==0 or not (Natives and Natives.InvokeVoid) then return false end
        r=math.max(0,math.min(255,math.floor(tonumber(r) or 0)))
        g=math.max(0,math.min(255,math.floor(tonumber(g) or 0)))
        b=math.max(0,math.min(255,math.floor(tonumber(b) or 0)))

        -- Prime the custom RGB before turning custom-color mode on.
        Natives.InvokeVoid(0x14892474891E09EB,blip,r,g,b)
        local current=nil
        if startup.regional_warfare_get_blip_color_449 then
            local ok,v=pcall(startup.regional_warfare_get_blip_color_449,blip)
            if ok then current=tonumber(v) end
        end
        if current~=84 then
            Natives.InvokeVoid(0x03D7FB09E75D6B7E,blip,84)
        end
        return true
    end

    rw.b464SocialCache=rw.b464SocialCache or {at=0,friends={},tracked={}}
    function startup.b464_refresh_social_marker_cache(force)
        local cache=rw.b464SocialCache
        local now=startup.now()
        if force~=true and now-(tonumber(cache.at or 0) or 0)<5000 then return cache end
        local friends,tracked={},{}
        if startup.get_rockstar_friends_in_gta then
            local ok,list=pcall(startup.get_rockstar_friends_in_gta)
            if ok and type(list)=="table" then
                for _,name in ipairs(list) do friends[string.lower(tostring(name or ""))]=true end
            end
        end
        if startup.get_tracked_players_in_gta then
            local ok,list=pcall(startup.get_tracked_players_in_gta)
            if ok and type(list)=="table" then
                for _,name in ipairs(list) do tracked[string.lower(tostring(name or ""))]=true end
            end
        end
        cache.friends=friends
        cache.tracked=tracked
        cache.at=now
        return cache
    end

    function startup.b464_social_marker_color(playerId,name)
        local cache=startup.b464_refresh_social_marker_cache(false)
        local key=string.lower(tostring(name or (startup.get_player_name_safe and startup.get_player_name_safe(playerId)) or ""))
        if key~="" and cache.friends[key]==true then
            local color=tostring(startup.s.regionalWarfareLanguageColors.__Friends or "Dark Green")
            if color~="None" and startup.regional_warfare_color_ids[color]~=nil then return color,"Friend" end
        end
        if key~="" and cache.tracked[key]==true then
            local color=tostring(startup.s.regionalWarfareLanguageColors.__Tracked or "Red")
            if color~="None" and startup.regional_warfare_color_ids[color]~=nil then return color,"Tracked" end
        end
        return nil,nil
    end

    function startup.b464_restore_one_marker(playerId,blip)
        playerId=tonumber(playerId)
        blip=tonumber(blip or 0) or 0
        local original=playerId~=nil and rw.blipOriginal[playerId] or nil
        if type(original)=="table" and blip~=0 and tonumber(original.blip or 0)==blip and tonumber(original.color)~=nil and Natives and Natives.InvokeVoid then
            Natives.InvokeVoid(0x03D7FB09E75D6B7E,blip,tonumber(original.color))
        end
        if playerId~=nil then
            rw.blipOriginal[playerId]=nil
            rw.blipApplied[playerId]=nil
        end
    end

    -- Final B464 painter. Social markers override IP/language colors. Friend wins
    -- over Tracked when the same live player belongs to both lists. Selecting None
    -- on a language restores that player's normal Rockstar/CEO/MC marker.
    function startup.regional_warfare_apply_blip_colors_449(force)
        local now=startup.now()
        if force~=true and now-(tonumber(rw.lastBlipColorScanMs or 0) or 0)<750 then return end
        rw.lastBlipColorScanMs=now

        if startup.s.regionalWarfareEnabled~=true or startup.s.regionalWarfareColorPlayers==false then
            if next(rw.blipOriginal or {})~=nil and startup.regional_warfare_restore_blip_colors_449 then pcall(startup.regional_warfare_restore_blip_colors_449) end
            rw.blipFrameTargets453={}
            rw.b461ColorSource={}
            return
        end

        startup.b464_refresh_social_marker_cache(false)
        local active={}
        local frameTargets={}
        local ids=startup.regional_warfare_player_ids_449 and startup.regional_warfare_player_ids_449() or {}

        for _,playerId in ipairs(ids or {}) do
            playerId=tonumber(playerId)
            if playerId~=nil and not (startup.is_local_player_id and startup.is_local_player_id(playerId)) then
                active[playerId]=true
                local name=tostring((startup.get_player_name_safe and startup.get_player_name_safe(playerId)) or ("Player "..tostring(playerId)))
                local language,source,countryCode,country="Unknown","unavailable","",""
                if startup.b461_color_identity then
                    local ok,a,b,c,d=pcall(startup.b461_color_identity,playerId)
                    if ok then language,source,countryCode,country=a,b,c,d end
                end
                language=startup.regional_warfare_normalize_language and startup.regional_warfare_normalize_language(language) or tostring(language or "Unknown")
                local socialColor,socialKind=startup.b464_social_marker_color(playerId,name)
                local colorName=socialColor or startup.regional_warfare_color_name(language)
                rw.b461ColorSource[playerId]={language=language,source=source,countryCode=countryCode,country=country,social=socialKind or "",colorName=colorName}

                local blip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0
                if blip~=0 then
                    if colorName=="None" then
                        startup.b464_restore_one_marker(playerId,blip)
                    else
                        local original=rw.blipOriginal[playerId]
                        if type(original)~="table" or tonumber(original.blip or 0)~=blip then
                            rw.blipOriginal[playerId]={
                                blip=blip,
                                color=startup.regional_warfare_get_blip_color_449 and startup.regional_warfare_get_blip_color_449(blip) or nil
                            }
                        end
                        local rgb=startup.regional_warfare_color_rgb_454[colorName] or startup.regional_warfare_color_rgb_454.Gray or {165,165,175}
                        local r,g,b=tonumber(rgb[1]) or 165,tonumber(rgb[2]) or 165,tonumber(rgb[3]) or 175
                        rw.blipApplied[playerId]={blip=blip,r=r,g=g,b=b,language=language,colorName=colorName,source=source,countryCode=countryCode,country=country,social=socialKind}
                        frameTargets[blip]={playerId=playerId,r=r,g=g,b=b,language=language,colorName=colorName,source=source,countryCode=countryCode,country=country,social=socialKind}
                        startup.regional_warfare_set_custom_blip_rgb_454(blip,r,g,b)
                    end
                else
                    rw.blipOriginal[playerId]=nil
                    rw.blipApplied[playerId]=nil
                end
            end
        end

        for playerId,_ in pairs(rw.blipOriginal or {}) do
            if active[playerId]~=true then
                rw.blipOriginal[playerId]=nil
                rw.blipApplied[playerId]=nil
                if rw.b461ColorSource then rw.b461ColorSource[playerId]=nil end
            end
        end
        rw.blipFrameTargets453=frameTargets
    end

    -- Render-cadence persistence with the same anti-flash order. The RGB write is
    -- cheap and keeps custom color primed; primary 84 is only written if GTA reset it.
    function startup.regional_warfare_reassert_blip_colors_453()
        if startup.s.regionalWarfareEnabled~=true or startup.s.regionalWarfareColorPlayers==false then return end
        for blip,target in pairs(rw.blipFrameTargets453 or {}) do
            if tonumber(blip or 0)~=0 and type(target)=="table" and target.colorName~="None" then
                startup.regional_warfare_set_custom_blip_rgb_454(tonumber(blip),target.r,target.g,target.b)
            end
        end
    end

    function startup.b464_color_combo(label,key,defaultValue)
        if not (ImGui and ImGui.BeginCombo and ImGui.Selectable) then return nil end
        local current=tostring(startup.s.regionalWarfareLanguageColors[key] or defaultValue or "None")
        if startup.regional_warfare_color_ids[current]==nil then current=tostring(defaultValue or "None") end
        if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(-1) end
        local changed=nil
        local opened=false
        local okOpen,v=pcall(ImGui.BeginCombo,tostring(label).."##StartupB464Color_"..tostring(key),current)
        opened=okOpen and v==true
        if opened then
            local okBody,err=pcall(function()
                for _,colorName in ipairs(startup.regional_warfare_color_names or {}) do
                    if ImGui.Selectable(tostring(colorName).."##StartupB464ColorOpt_"..tostring(key).."_"..tostring(colorName),current==colorName) then changed=colorName end
                end
            end)
            pcall(ImGui.EndCombo)
            if not okBody and startup.log then startup.log("[Build 464][COLOR_COMBO_RECOVERED] "..tostring(err)) end
        end
        return changed
    end

    function startup.b464_render_main_regional_warfare()
        startup.text_colored(1.00,0.55,0.12,1.00,"REGIONAL WARFARE")
        startup.subtle_text_wrapped("Private-server warfare with IP-country player marker colors first and Cherax Player Language fallback. Friends and Tracked players can override regional colors.")
        if ImGui.Separator then ImGui.Separator() end
        startup.render_feature_guarded_325(startup.h.RegionalWarfareEnabled)
        startup.render_feature_guarded_325(startup.h.RegionalWarfareMyFaction)
        startup.render_feature_guarded_325(startup.h.RegionalWarfareEnemyPolicy)
        startup.render_feature_guarded_325(startup.h.RegionalWarfareAutoBounty)

        local oldMarkers=startup.s.regionalWarfareColorPlayers~=false
        local markerChanged=nil
        if ImGui.Checkbox then
            local newMarkers=ImGui.Checkbox("Color Player Markers##StartupB464ColorPlayers",oldMarkers)
            if newMarkers~=oldMarkers then markerChanged=newMarkers==true end
        end
        startup.hover_help("Uses IP country first. Friends override to their configured social color, then Tracked players, then the IP/language color.")
        if markerChanged~=nil then
            startup.s.regionalWarfareColorPlayers=markerChanged==true
            rw.lastBlipColorScanMs=0
            if startup.h and startup.h.RegionalWarfareColorPlayers and startup.set_feature_bool_silently then pcall(startup.set_feature_bool_silently,startup.h.RegionalWarfareColorPlayers,markerChanged==true) end
            if markerChanged~=true and startup.regional_warfare_restore_blip_colors_449 then pcall(startup.regional_warfare_restore_blip_colors_449) end
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end

        local sigPartsBefore={}
        sigPartsBefore[#sigPartsBefore+1]=tostring(startup.s.regionalWarfareLanguageColors.__Friends or "")
        sigPartsBefore[#sigPartsBefore+1]=tostring(startup.s.regionalWarfareLanguageColors.__Tracked or "")
        for _,language in ipairs(startup.regional_warfare_languages or {}) do
            if language~="Auto (Player Language)" then sigPartsBefore[#sigPartsBefore+1]=tostring(startup.s.regionalWarfareLanguageColors[language] or "") end
        end
        local beforeSig=table.concat(sigPartsBefore,"|")

        local colorsOpen=true
        if ImGui.CollapsingHeader then
            local ok,v=pcall(ImGui.CollapsingHeader,"Player Marker Colors##StartupB464MarkerColors")
            colorsOpen=ok and v==true
        end
        if colorsOpen and startup.s.regionalWarfareColorPlayers~=false then
            startup.subtle_text_wrapped("None leaves that language on its normal Rockstar marker. Social overrides: Friend takes priority over Tracked; setting a social override to None falls back to the IP/language color.")
            local changed=startup.b464_color_combo("Friends Marker","__Friends","Dark Green")
            if changed then startup.s.regionalWarfareLanguageColors.__Friends=changed end
            changed=startup.b464_color_combo("Tracked Marker","__Tracked","Red")
            if changed then startup.s.regionalWarfareLanguageColors.__Tracked=changed end
            for _,language in ipairs(startup.regional_warfare_languages or {}) do
                if language~="Auto (Player Language)" then
                    changed=startup.b464_color_combo(tostring(language).." Marker",language,startup.regional_warfare_default_language_colors[language] or "Gray")
                    if changed then startup.s.regionalWarfareLanguageColors[language]=changed end
                end
            end
        end

        local sigPartsAfter={}
        sigPartsAfter[#sigPartsAfter+1]=tostring(startup.s.regionalWarfareLanguageColors.__Friends or "")
        sigPartsAfter[#sigPartsAfter+1]=tostring(startup.s.regionalWarfareLanguageColors.__Tracked or "")
        for _,language in ipairs(startup.regional_warfare_languages or {}) do
            if language~="Auto (Player Language)" then sigPartsAfter[#sigPartsAfter+1]=tostring(startup.s.regionalWarfareLanguageColors[language] or "") end
        end
        local afterSig=table.concat(sigPartsAfter,"|")
        rw.b464ColorSignature=afterSig
        if beforeSig~=afterSig then
            rw.lastBlipColorScanMs=0
            rw.b464SocialCache.at=0
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end

        local own,ownSource="Unknown","unavailable"
        if startup.regional_warfare_own_language then
            local ok,a,b=pcall(startup.regional_warfare_own_language)
            if ok then own=tostring(a or "Unknown"); ownSource=tostring(b or "") end
        end
        startup.subtle_text("My detected warfare language: "..own.." • "..ownSource)
        startup.subtle_text_wrapped(tostring(startup.s.regionalWarfareLastStatus or "Ready."))

        if startup.s.regionalWarfareEnemyPolicy=="Selected Languages" then
            local enemyOpen=true
            if ImGui.CollapsingHeader then
                local ok,v=pcall(ImGui.CollapsingHeader,"Selected Enemy Languages##StartupB464EnemyLanguages")
                enemyOpen=ok and v==true
            end
            if enemyOpen then
                for _,language in ipairs(startup.regional_warfare_languages or {}) do
                    if language~="Auto (Player Language)" and language~="Unknown" then
                        startup.render_feature_guarded_325(startup.h["RegionalWarfareEnemy_"..startup.regional_warfare_feature_key(language)])
                    end
                end
            end
        end

        local rosterOpen=false
        if ImGui.CollapsingHeader then
            local ok,v=pcall(ImGui.CollapsingHeader,"Live IP / Language Roster##StartupB464Roster")
            rosterOpen=ok and v==true
        end
        if rosterOpen then
            local rows={}
            local ok,v=pcall(startup.regional_warfare_roster)
            if ok and type(v)=="table" then rows=v end
            if #rows==0 then startup.subtle_text("No remote players detected.") else
                for index,row in ipairs(rows) do
                    if index>32 then break end
                    local src=tostring(row.languageSource or "")
                    startup.subtle_text(tostring(row.name).." • "..tostring(row.language)..(src~="" and (" • "..src) or ""))
                end
            end
        end
        startup.render_feature_guarded_325(startup.h.RegionalWarfareBountyNow)
        if tostring(startup.s.regionalWarfareLastBountyPlayer or "")~="" then
            startup.subtle_text("Last bounty: "..tostring(startup.s.regionalWarfareLastBountyPlayer).." • "..tostring(startup.s.regionalWarfareLastBountyFaction or ""))
        end
    end

    function startup.b464_render_auto_bounty_target()
        local rows={}
        local okRows,resultRows=pcall(startup.b455_selected_bounty_rows,false)
        if okRows and type(resultRows)=="table" then rows=resultRows end
        local selfRow=nil
        local playerRows={}
        for _,row in ipairs(rows) do if row.isSelf==true then selfRow=row else playerRows[#playerRows+1]=row end end

        local targetMode=tostring(startup.s.regionalWarfareAutoBountyTargetMode or "none")
        local selected=nil
        if targetMode=="self" then selected=selfRow
        elseif targetMode=="player" then local ok,v=pcall(startup.b455_resolve_selected_bounty_target,false); if ok then selected=v end end
        local preview="None"
        if targetMode=="self" then preview="You / Self"..(selfRow and (" - "..tostring(selfRow.name).." • "..tostring(selfRow.language)) or "")
        elseif targetMode=="random" then preview="Random Player"
        elseif targetMode=="player" and selected then preview="["..tostring(selected.playerId).."] "..tostring(selected.name).." • "..tostring(selected.language) end

        local actionMode=nil
        local actionRow=nil
        local autoChanged=nil
        local manualClicked=false
        local intervalChanged=nil

        startup.subtle_text_wrapped("Choose You, Random Player, or one live session player. Random excludes you and avoids repeating the same player when possible.")
        if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(-1) end
        local comboOpen=false
        if ImGui.BeginCombo then local ok,v=pcall(ImGui.BeginCombo,"Target##StartupB464AutoBountyTarget",preview); comboOpen=ok and v==true end
        if comboOpen then
            local okBody,err=pcall(function()
                if ImGui.Selectable("None##StartupB464TargetNone",targetMode=="none") then actionMode="none" end
                if ImGui.Selectable("You / Self"..(selfRow and (" - "..tostring(selfRow.name)) or "").."##StartupB464TargetSelf",targetMode=="self") then actionMode="self" end
                if ImGui.Selectable("Random Player##StartupB464TargetRandom",targetMode=="random") then actionMode="random" end
                for _,row in ipairs(playerRows) do
                    local isSelected=targetMode=="player" and selected and tonumber(selected.playerId)==tonumber(row.playerId) and tostring(selected.rid or "")==tostring(row.rid or "")
                    local label="["..tostring(row.playerId).."] "..tostring(row.name).." • "..tostring(row.language).."##StartupB464Target"..tostring(row.playerId)..tostring(row.rid)
                    if ImGui.Selectable(label,isSelected==true) then actionMode="player"; actionRow=row end
                end
            end)
            pcall(ImGui.EndCombo)
            if not okBody and startup.log then startup.log("[Build 464][TARGET_COMBO_RECOVERED] "..tostring(err)) end
        end

        local intervalOptions={{label="30 seconds",sec=30},{label="1 minute",sec=60},{label="2 minutes",sec=120},{label="5 minutes",sec=300},{label="10 minutes",sec=600},{label="15 minutes",sec=900},{label="30 minutes",sec=1800},{label="60 minutes",sec=3600}}
        local currentSec=tonumber(startup.s.regionalWarfareAutoBountyIntervalSec or 300) or 300
        local intervalPreview=tostring(math.floor(currentSec/60)).." minutes"
        for _,opt in ipairs(intervalOptions) do if opt.sec==currentSec then intervalPreview=opt.label break end end
        if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(-1) end
        local intervalOpen=false
        if ImGui.BeginCombo then local ok,v=pcall(ImGui.BeginCombo,"Bounty Interval##StartupB464BountyInterval",intervalPreview); intervalOpen=ok and v==true end
        if intervalOpen then
            local okBody,err=pcall(function()
                for _,opt in ipairs(intervalOptions) do if ImGui.Selectable(tostring(opt.label).."##StartupB464Interval"..tostring(opt.sec),currentSec==opt.sec) then intervalChanged=opt.sec end end
            end)
            pcall(ImGui.EndCombo)
            if not okBody and startup.log then startup.log("[Build 464][INTERVAL_COMBO_RECOVERED] "..tostring(err)) end
        end

        local oldAuto=startup.s.regionalWarfareSelectedAutoBountyEnabled==true
        if ImGui.Checkbox then local newAuto=ImGui.Checkbox("Auto-Bounty##StartupB464AutoBountyToggle",oldAuto); if newAuto~=oldAuto then autoChanged=newAuto==true end end
        if ImGui.Button and ImGui.Button("Apply Bounty Now##StartupB464BountyNow",-1,30)==true then manualClicked=true end
        local sec=tonumber(startup.s.regionalWarfareAutoBountyIntervalSec or 300) or 300
        startup.subtle_text("Interval: "..tostring(sec<60 and (tostring(sec).." sec") or (tostring(math.floor(sec/60)).." min")).." • Amount: built-in 9k")
        startup.subtle_text_wrapped(tostring(startup.s.regionalWarfareSelectedAutoBountyLastStatus or "Ready."))
        if rw.b459LastRandomName~="" then startup.subtle_text("Last random target: "..tostring(rw.b459LastRandomName)) end
        if not okRows then startup.subtle_text("Roster refresh recovered from a transient lookup error.") end

        if actionMode then
            pcall(startup.b459_set_bounty_mode,actionMode,actionRow)
            if startup.s.regionalWarfareSelectedAutoBountyEnabled==true and actionMode~="none" then pcall(startup.b455_queue_selected_bounty,"Target changed") end
        end
        if intervalChanged then
            startup.s.regionalWarfareAutoBountyIntervalSec=tonumber(intervalChanged) or 300
            startup.s.regionalWarfareSelectedAutoBountyIntervalMs=startup.s.regionalWarfareAutoBountyIntervalSec*1000
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end
        if autoChanged~=nil then
            startup.s.regionalWarfareSelectedAutoBountyEnabled=autoChanged==true
            rw.b455SelectedBountyLastMs=0
            if startup.h and startup.h.RegionalWarfareSelectedAutoBounty and startup.set_feature_bool_silently then pcall(startup.set_feature_bool_silently,startup.h.RegionalWarfareSelectedAutoBounty,autoChanged==true) end
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
            if autoChanged==true then pcall(startup.b455_queue_selected_bounty,"Auto enabled") end
        end
        if manualClicked==true then pcall(startup.b455_queue_selected_bounty,"Manual") end
    end

    function startup.b464_render_bounty_queue()
        startup.subtle_text_wrapped("Enemy-language Auto-Bounty is round-robin. Every eligible player receives one turn before the queue loops back to the beginning.")
        local options={{label="15 seconds",ms=15000},{label="30 seconds",ms=30000},{label="1 minute",ms=60000},{label="2 minutes",ms=120000},{label="5 minutes",ms=300000},{label="10 minutes",ms=600000}}
        local current=math.max(15000,math.min(600000,tonumber(startup.s.regionalWarfareBountyGapMs or 60000) or 60000))
        local preview="1 minute"
        for _,opt in ipairs(options) do if opt.ms==current then preview=opt.label break end end
        local changed=nil
        if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(-1) end
        local combo=false
        if ImGui.BeginCombo then local ok,v=pcall(ImGui.BeginCombo,"Per-Player Bounty Spacing##StartupB464BountySpacing",preview); combo=ok and v==true end
        if combo then
            local okBody,err=pcall(function()
                for _,opt in ipairs(options) do if ImGui.Selectable(tostring(opt.label).."##StartupB464Gap"..tostring(opt.ms),current==opt.ms) then changed=opt.ms end end
            end)
            pcall(ImGui.EndCombo)
            if not okBody and startup.log then startup.log("[Build 464][QUEUE_COMBO_RECOVERED] "..tostring(err)) end
        end
        local count=type(rw.b460Queue)=="table" and #rw.b460Queue or 0
        local done=math.max(0,(tonumber(rw.b460QueueCursor or 1) or 1)-1)
        if done>count then done=count end
        startup.subtle_text("Queue progress: "..tostring(done).." / "..tostring(count).." • Cycle: "..tostring(tonumber(rw.b460QueueCycle or 0) or 0))
        local nextEntry=type(rw.b460Queue)=="table" and rw.b460Queue[rw.b460QueueCursor] or nil
        if nextEntry then startup.subtle_text("Next: "..tostring(nextEntry.name).." • "..tostring(nextEntry.language)) end
        if changed then
            startup.s.regionalWarfareBountyGapMs=tonumber(changed) or 60000
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end
    end

    -- Final renderer: no BeginCustomChildWindow / EndCustomChildWindow pairs. Each
    -- major section is a true collapsible dropdown, which also removes the old
    -- always-open panels that contributed to ImGui recovery complexity.
    function startup.render_regional_warfare()
        if not (ImGui and ClickGUI) then return end
        local mainOpen=true
        if ImGui.CollapsingHeader then local ok,v=pcall(ImGui.CollapsingHeader,"Regional Warfare##StartupB464Main"); mainOpen=ok and v==true end
        if mainOpen then local ok,err=pcall(startup.b464_render_main_regional_warfare); if not ok and startup.log then startup.log("[Build 464][MAIN_DROPDOWN_RECOVERED] "..tostring(err)) end end

        local targetOpen=false
        if ImGui.CollapsingHeader then local ok,v=pcall(ImGui.CollapsingHeader,"Regional Warfare Auto-Bounty Target##StartupB464TargetHeader"); targetOpen=ok and v==true end
        if targetOpen then local ok,err=pcall(startup.b464_render_auto_bounty_target); if not ok and startup.log then startup.log("[Build 464][TARGET_DROPDOWN_RECOVERED] "..tostring(err)) end end

        local queueOpen=false
        if ImGui.CollapsingHeader then local ok,v=pcall(ImGui.CollapsingHeader,"Regional Warfare Bounty Queue##StartupB464QueueHeader"); queueOpen=ok and v==true end
        if queueOpen then local ok,err=pcall(startup.b464_render_bounty_queue); if not ok and startup.log then startup.log("[Build 464][QUEUE_DROPDOWN_RECOVERED] "..tostring(err)) end end
    end

