-- ============================================================================
-- BUILD 465: KILLED YOU RETALIATION
-- - Reuses B426's confirmed local-death killer resolution; no second death detector.
-- - Configurable trigger rules: one kill anytime or repeated kills inside a window.
-- - Friends are always immune: never marked and never auto-bountied by this system.
-- - Triggered non-friends receive a Dark Red marker override and optional built-in 9k bounty.
-- - Marker override is independent of Regional Warfare language coloring and therefore
--   remains available even when the regional marker layer itself is disabled.
-- ============================================================================
function startup.install_killed_you_retaliation_build465()
    startup.killed_you_b465=startup.killed_you_b465 or {}
    local R=startup.killed_you_b465
    local rw=startup.regional_warfare_runtime or {}
    startup.regional_warfare_runtime=rw

    R.records=type(R.records)=="table" and R.records or {}
    R.markerOriginal=type(R.markerOriginal)=="table" and R.markerOriginal or {}
    R.bountyQueue=type(R.bountyQueue)=="table" and R.bountyQueue or {}
    R.bountyInFlight=R.bountyInFlight==true
    R.presentInstalled=R.presentInstalled==true
    R.postPresentInstalled=R.postPresentInstalled==true
    R.playerLeftInstalled=R.playerLeftInstalled==true

    if startup.s.killedYouRetaliationEnabled==nil then startup.s.killedYouRetaliationEnabled=true end
    if tostring(startup.s.killedYouRetaliationRule or "")=="" then startup.s.killedYouRetaliationRule="once_anytime" end
    if tostring(startup.s.killedYouRetaliationColor or "")=="" then startup.s.killedYouRetaliationColor="Dark Red" end
    if startup.s.killedYouRetaliationAutoBounty==nil then startup.s.killedYouRetaliationAutoBounty=false end
    if startup.s.killedYouRetaliationNotify==nil then startup.s.killedYouRetaliationNotify=true end
    if tostring(startup.s.killedYouRetaliationMarkDuration or "")=="" then startup.s.killedYouRetaliationMarkDuration="session" end
    startup.s.killedYouRetaliationLastStatus=tostring(startup.s.killedYouRetaliationLastStatus or "Ready. Friends are immune.")

    -- Add the requested Dark Red to the shared marker palette.
    startup.regional_warfare_color_names=startup.regional_warfare_color_names or {"None"}
    local hasDarkRed=false
    for _,v in ipairs(startup.regional_warfare_color_names) do if tostring(v)=="Dark Red" then hasDarkRed=true break end end
    if not hasDarkRed then
        local inserted=false
        for i,v in ipairs(startup.regional_warfare_color_names) do
            if tostring(v)=="Red" then table.insert(startup.regional_warfare_color_names,i+1,"Dark Red"); inserted=true; break end
        end
        if not inserted then table.insert(startup.regional_warfare_color_names,"Dark Red") end
    end
    startup.regional_warfare_color_ids=startup.regional_warfare_color_ids or {}
    startup.regional_warfare_color_ids["Dark Red"]=6
    startup.regional_warfare_color_rgb_454=startup.regional_warfare_color_rgb_454 or {}
    startup.regional_warfare_color_rgb_454["Dark Red"]={150,18,28}

    function startup.killed_you_now_b465()
        if startup.now then return tonumber(startup.now()) or 0 end
        if Time and Time.GetEpocheMs then local ok,v=pcall(Time.GetEpocheMs); if ok then return tonumber(v or 0) or 0 end end
        return math.floor((os.clock and os.clock() or 0)*1000)
    end

    function startup.killed_you_rule_b465()
        local rules={
            once_anytime={label="1 kill • anytime this session",threshold=1,windowMs=0},
            two_5m={label="2 kills • within 5 minutes",threshold=2,windowMs=300000},
            three_5m={label="3 kills • within 5 minutes",threshold=3,windowMs=300000},
            three_10m={label="3 kills • within 10 minutes",threshold=3,windowMs=600000},
            five_10m={label="5 kills • within 10 minutes",threshold=5,windowMs=600000},
        }
        local key=tostring(startup.s.killedYouRetaliationRule or "once_anytime")
        return rules[key] or rules.once_anytime,key,rules
    end

    function startup.killed_you_mark_duration_ms_b465()
        local key=tostring(startup.s.killedYouRetaliationMarkDuration or "session")
        if key=="5m" then return 300000 end
        if key=="15m" then return 900000 end
        if key=="30m" then return 1800000 end
        return 0
    end

    function startup.killed_you_name_b465(playerId)
        playerId=tonumber(playerId or -1) or -1
        if startup.get_player_name_safe then local ok,v=pcall(startup.get_player_name_safe,playerId); if ok and tostring(v or "")~="" then return tostring(v) end end
        if Players and Players.GetName then local ok,v=pcall(Players.GetName,playerId); if ok and tostring(v or "")~="" then return tostring(v) end end
        return "Player "..tostring(playerId)
    end

    function startup.killed_you_rid_b465(playerId)
        playerId=tonumber(playerId or -1) or -1
        if startup.regional_warfare_get_rid then local ok,v=pcall(startup.regional_warfare_get_rid,playerId); if ok and tostring(v or "")~="" and tostring(v)~="0" then return tostring(v) end end
        if Players and Players.GetById then
            local okP,p=pcall(Players.GetById,playerId)
            if okP and p and p.GetGamerInfo then
                local okI,info=pcall(function() return p:GetGamerInfo() end)
                if okI and info and tonumber(info.RockstarId or 0) and tonumber(info.RockstarId or 0)>0 then return string.format("%.0f",tonumber(info.RockstarId)) end
            end
        end
        return ""
    end

    function startup.killed_you_is_friend_b465(playerId,name)
        playerId=tonumber(playerId or -1) or -1
        if startup.is_player_current_friend then local ok,v=pcall(startup.is_player_current_friend,playerId); if ok and v==true then return true end end
        if startup.is_name_current_friend then local ok,v=pcall(startup.is_name_current_friend,tostring(name or "")); if ok and v==true then return true end end
        if startup.b464_refresh_social_marker_cache then
            local ok,cache=pcall(startup.b464_refresh_social_marker_cache,false)
            if ok and type(cache)=="table" then
                local key=string.lower(tostring(name or startup.killed_you_name_b465(playerId) or ""))
                if key~="" and type(cache.friends)=="table" and cache.friends[key]==true then return true end
            end
        end
        return false
    end

    function startup.killed_you_record_for_player_b465(playerId,name,create)
        playerId=tonumber(playerId or -1) or -1
        name=tostring(name or startup.killed_you_name_b465(playerId))
        local rid=startup.killed_you_rid_b465(playerId)
        local key=(rid~="" and ("rid:"..rid)) or ("pid:"..tostring(playerId)..":"..string.lower(name))
        local rec=R.records[key]
        if not rec then
            for oldKey,row in pairs(R.records) do
                if type(row)=="table" and tonumber(row.playerId or -2)==playerId and string.lower(tostring(row.name or ""))==string.lower(name) then
                    rec=row
                    if oldKey~=key and rid~="" then R.records[oldKey]=nil; R.records[key]=rec end
                    break
                end
            end
        end
        if not rec and create==true then
            rec={key=key,rid=rid,playerId=playerId,name=name,times={},active=false,triggeredOnce=false,triggeredAtMs=0,markUntilMs=0,lastBountyMs=0}
            R.records[key]=rec
        end
        if rec then rec.key=key; rec.rid=rid~="" and rid or tostring(rec.rid or ""); rec.playerId=playerId; rec.name=name end
        return rec,key,rid
    end

    function startup.killed_you_record_active_b465(rec)
        if type(rec)~="table" or rec.active~=true then return false end
        local untilMs=tonumber(rec.markUntilMs or 0) or 0
        if untilMs>0 and startup.killed_you_now_b465()>=untilMs then rec.active=false; return false end
        return true
    end

    function startup.killed_you_marker_color_b465(playerId,name)
        if startup.s.killedYouRetaliationEnabled~=true then return nil,nil end
        if startup.killed_you_is_friend_b465(playerId,name) then return nil,nil end
        local rec=startup.killed_you_record_for_player_b465(playerId,name,false)
        if not startup.killed_you_record_active_b465(rec) then return nil,nil end
        local color=tostring(startup.s.killedYouRetaliationColor or "Dark Red")
        if color=="None" or startup.regional_warfare_color_ids[color]==nil then return nil,rec end
        return color,rec
    end

    function startup.killed_you_validate_live_target_b465(item)
        if type(item)~="table" then return nil,"invalid" end
        local pid=tonumber(item.playerId or -1) or -1
        if pid<0 or pid>31 then return nil,"invalid player" end
        local active=true
        if Players and Players.GetById then local ok,p=pcall(Players.GetById,pid); active=ok and p~=nil end
        if active~=true then return nil,"left session" end
        local name=startup.killed_you_name_b465(pid)
        local rid=startup.killed_you_rid_b465(pid)
        if tostring(item.rid or "")~="" and rid~="" and tostring(item.rid)~=rid then return nil,"RID changed" end
        if startup.killed_you_is_friend_b465(pid,name) then return nil,"friend immunity" end
        return {playerId=pid,name=name,rid=rid},"ok"
    end

    function startup.killed_you_process_bounty_queue_b465()
        if R.bountyInFlight==true or #R.bountyQueue==0 then return end
        if not (Script and Script.QueueJob) then startup.s.killedYouRetaliationLastStatus="Bounty queue unavailable: Script.QueueJob missing."; return end
        R.bountyInFlight=true
        Script.QueueJob(function()
            local item=table.remove(R.bountyQueue,1)
            local live,why=startup.killed_you_validate_live_target_b465(item)
            if live then
                local okCall,okBounty,status=pcall(startup.b455_apply_selected_bounty_exact,live.playerId)
                if okCall and okBounty==true then
                    startup.s.killedYouRetaliationLastStatus="Retaliation bounty applied to "..tostring(live.name).." • built-in 9k."
                    local rec=startup.killed_you_record_for_player_b465(live.playerId,live.name,false)
                    if rec then rec.lastBountyMs=startup.killed_you_now_b465() end
                    if startup.support_log_event_quiet then pcall(startup.support_log_event_quiet,"BUILD465_KILLED_YOU_BOUNTY","player="..tostring(live.name).." pid="..tostring(live.playerId).." rid="..tostring(live.rid).." status="..tostring(status)) end
                else
                    startup.s.killedYouRetaliationLastStatus="Retaliation bounty failed for "..tostring(live.name).." • "..tostring(okCall and status or okBounty)
                end
            else
                startup.s.killedYouRetaliationLastStatus="Retaliation bounty skipped • "..tostring(why)
            end
            R.bountyInFlight=false
            if #R.bountyQueue>0 then startup.killed_you_process_bounty_queue_b465() end
        end)
    end

    function startup.killed_you_queue_bounty_b465(playerId,name,rid)
        if startup.s.killedYouRetaliationAutoBounty~=true then return false end
        if startup.killed_you_is_friend_b465(playerId,name) then return false end
        for _,q in ipairs(R.bountyQueue) do
            if tostring(rid or "")~="" and tostring(q.rid or "")==tostring(rid) then return false end
            if tostring(rid or "")=="" and tonumber(q.playerId)==tonumber(playerId) then return false end
        end
        R.bountyQueue[#R.bountyQueue+1]={playerId=tonumber(playerId),name=tostring(name or ""),rid=tostring(rid or "")}
        startup.killed_you_process_bounty_queue_b465()
        return true
    end

    function startup.killed_you_retaliation_event_build465(playerId,killerName,weaponHash,bone)
        if startup.s.killedYouRetaliationEnabled~=true then return false end
        playerId=tonumber(playerId or -1) or -1
        if playerId<0 or playerId>31 or (startup.is_local_player_id and startup.is_local_player_id(playerId)) then return false end
        local name=tostring(killerName or startup.killed_you_name_b465(playerId))
        if startup.killed_you_is_friend_b465(playerId,name) then
            startup.s.killedYouRetaliationLastStatus="Ignored friend who killed you: "..name
            if startup.support_log_event_quiet then pcall(startup.support_log_event_quiet,"BUILD465_KILLED_YOU_FRIEND_IGNORED","player="..name.." pid="..tostring(playerId)) end
            return false
        end

        local now=startup.killed_you_now_b465()
        local rec,key,rid=startup.killed_you_record_for_player_b465(playerId,name,true)
        rec.times=type(rec.times)=="table" and rec.times or {}
        rec.times[#rec.times+1]=now

        local rule,ruleKey=startup.killed_you_rule_b465()
        if tonumber(rule.windowMs or 0)>0 then
            local keep={}
            for _,t in ipairs(rec.times) do if now-(tonumber(t or 0) or 0)<=rule.windowMs then keep[#keep+1]=t end end
            rec.times=keep
        end
        local count=#rec.times
        local meets=count>=tonumber(rule.threshold or 1)
        if ruleKey=="once_anytime" and rec.triggeredOnce==true then meets=false end

        if not meets then
            startup.s.killedYouRetaliationLastStatus=name.." killed you • "..tostring(count).." / "..tostring(rule.threshold).." toward "..tostring(rule.label).."."
            return false
        end
        if startup.killed_you_record_active_b465(rec) then
            startup.s.killedYouRetaliationLastStatus=name.." killed you again • already marked for retaliation."
            return false
        end

        rec.active=true
        rec.triggeredAtMs=now
        if ruleKey=="once_anytime" then rec.triggeredOnce=true else rec.times={} end
        local duration=startup.killed_you_mark_duration_ms_b465()
        rec.markUntilMs=duration>0 and (now+duration) or 0
        rw.lastBlipColorScanMs=0

        local color=tostring(startup.s.killedYouRetaliationColor or "Dark Red")
        local bountyQueued=startup.killed_you_queue_bounty_b465(playerId,name,rid)
        startup.s.killedYouRetaliationLastStatus="Triggered: "..name.." • marker="..color.." • bounty="..tostring(bountyQueued and "queued" or (startup.s.killedYouRetaliationAutoBounty==true and "not queued" or "off"))
        if startup.s.killedYouRetaliationNotify==true then
            local msg="Killed You: "..name.." marked "..color
            if bountyQueued then msg=msg.." + 9k bounty queued" end
            if startup.toast_colored then pcall(startup.toast_colored,msg,5500,"error") elseif startup.toast then pcall(startup.toast,msg,5500) end
        end
        if startup.support_log_event_quiet then pcall(startup.support_log_event_quiet,"BUILD465_KILLED_YOU_TRIGGER","player="..name.." pid="..tostring(playerId).." rid="..tostring(rid).." rule="..tostring(ruleKey).." count="..tostring(count).." color="..color.." bounty="..tostring(bountyQueued).." weapon="..tostring(weaponHash or 0).." bone="..tostring(bone or 0)) end
        return true
    end

    function startup.killed_you_restore_marker_b465(playerId,entry)
        playerId=tonumber(playerId)
        entry=type(entry)=="table" and entry or nil
        if not entry then return end
        local blip=tonumber(entry.blip or 0) or 0
        local baseRegional=startup.s.regionalWarfareEnabled==true and startup.s.regionalWarfareColorPlayers~=false
        if baseRegional then
            rw.lastBlipColorScanMs=0
        elseif blip~=0 and tonumber(entry.color)~=nil and Natives and Natives.InvokeVoid then
            pcall(Natives.InvokeVoid,0x03D7FB09E75D6B7E,blip,tonumber(entry.color))
        end
        R.markerOriginal[playerId]=nil
    end

    function startup.killed_you_reassert_markers_b465()
        local enabled=startup.s.killedYouRetaliationEnabled==true
        local color=tostring(startup.s.killedYouRetaliationColor or "Dark Red")
        local rgb=startup.regional_warfare_color_rgb_454 and startup.regional_warfare_color_rgb_454[color] or nil
        if not enabled or color=="None" or type(rgb)~="table" then
            for pid,entry in pairs(R.markerOriginal) do startup.killed_you_restore_marker_b465(pid,entry) end
            return
        end
        local ids={}
        if startup.regional_warfare_player_ids_449 then local ok,v=pcall(startup.regional_warfare_player_ids_449); if ok and type(v)=="table" then ids=v end end
        local active={}
        local baseRegional=startup.s.regionalWarfareEnabled==true and startup.s.regionalWarfareColorPlayers~=false
        for _,pid in ipairs(ids or {}) do
            pid=tonumber(pid)
            if pid and not (startup.is_local_player_id and startup.is_local_player_id(pid)) then
                local name=startup.killed_you_name_b465(pid)
                local markerColor=startup.killed_you_marker_color_b465(pid,name)
                if markerColor and markerColor~="None" then
                    local blip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(pid) or 0) or 0
                    if blip~=0 then
                        active[pid]=true
                        if not baseRegional and type(R.markerOriginal[pid])~="table" then
                            local current=nil
                            if startup.regional_warfare_get_blip_color_449 then local ok,v=pcall(startup.regional_warfare_get_blip_color_449,blip); if ok then current=tonumber(v) end end
                            R.markerOriginal[pid]={blip=blip,color=current}
                        end
                        if startup.regional_warfare_set_custom_blip_rgb_454 then pcall(startup.regional_warfare_set_custom_blip_rgb_454,blip,tonumber(rgb[1]) or 150,tonumber(rgb[2]) or 18,tonumber(rgb[3]) or 28) end
                    end
                end
            end
        end
        for pid,entry in pairs(R.markerOriginal) do if active[pid]~=true then startup.killed_you_restore_marker_b465(pid,entry) end end
    end

    function startup.killed_you_clear_b465()
        R.records={}
        R.bountyQueue={}
        R.bountyInFlight=false
        for pid,entry in pairs(R.markerOriginal) do startup.killed_you_restore_marker_b465(pid,entry) end
        R.markerOriginal={}
        rw.lastBlipColorScanMs=0
        startup.s.killedYouRetaliationLastStatus="Killed You history and marks cleared."
    end

    function startup.render_killed_you_retaliation_b465()
        local dirty=false
        startup.text_colored(0.72,0.10,0.13,1.00,"KILLED YOU RETALIATION")
        startup.subtle_text_wrapped("When a non-friend kills you enough times to match the selected rule, Startup can mark them Dark Red and queue the same built-in 9k bounty path used by Minigames. Friends are always ignored.")
        if ImGui.Separator then ImGui.Separator() end

        local oldEnabled=startup.s.killedYouRetaliationEnabled==true
        if ImGui.Checkbox then
            local v=ImGui.Checkbox("Enable Killed You Retaliation##StartupB465Enabled",oldEnabled)
            if v~=oldEnabled then startup.s.killedYouRetaliationEnabled=v==true; rw.lastBlipColorScanMs=0; dirty=true end
        end

        local rule,currentKey,rules=startup.killed_you_rule_b465()
        if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(-1) end
        local open=false
        if ImGui.BeginCombo then local ok,v=pcall(ImGui.BeginCombo,"Trigger Rule##StartupB465Rule",tostring(rule.label)); open=ok and v==true end
        if open then
            local okBody,err=pcall(function()
                local order={"once_anytime","two_5m","three_5m","three_10m","five_10m"}
                for _,key in ipairs(order) do local opt=rules[key]; if opt and ImGui.Selectable(tostring(opt.label).."##StartupB465Rule_"..key,currentKey==key) then startup.s.killedYouRetaliationRule=key; dirty=true end end
            end)
            pcall(ImGui.EndCombo)
            if not okBody and startup.log then startup.log("[Build 465][RULE_COMBO_RECOVERED] "..tostring(err)) end
        end

        if startup.b464_color_combo then
            local changed=startup.b464_color_combo("Killed You Marker","__KilledYou",tostring(startup.s.killedYouRetaliationColor or "Dark Red"))
            if changed then startup.s.killedYouRetaliationColor=changed; dirty=true end
        end

        local durationKey=tostring(startup.s.killedYouRetaliationMarkDuration or "session")
        local durations={session="Session / until script unload",["5m"]="5 minutes",["15m"]="15 minutes",["30m"]="30 minutes"}
        local durationLabel=durations[durationKey] or durations.session
        if ImGui.SetNextItemWidth then ImGui.SetNextItemWidth(-1) end
        local durationOpen=false
        if ImGui.BeginCombo then local ok,v=pcall(ImGui.BeginCombo,"Mark Duration##StartupB465Duration",durationLabel); durationOpen=ok and v==true end
        if durationOpen then
            local okBody,err=pcall(function()
                for _,key in ipairs({"session","5m","15m","30m"}) do if ImGui.Selectable(tostring(durations[key]).."##StartupB465Dur_"..key,durationKey==key) then startup.s.killedYouRetaliationMarkDuration=key; dirty=true end end
            end)
            pcall(ImGui.EndCombo)
            if not okBody and startup.log then startup.log("[Build 465][DURATION_COMBO_RECOVERED] "..tostring(err)) end
        end

        local oldBounty=startup.s.killedYouRetaliationAutoBounty==true
        if ImGui.Checkbox then local v=ImGui.Checkbox("Auto-Bounty Triggered Killer##StartupB465Bounty",oldBounty); if v~=oldBounty then startup.s.killedYouRetaliationAutoBounty=v==true; dirty=true end end
        local oldNotify=startup.s.killedYouRetaliationNotify==true
        if ImGui.Checkbox then local v=ImGui.Checkbox("Notify On Trigger##StartupB465Notify",oldNotify); if v~=oldNotify then startup.s.killedYouRetaliationNotify=v==true; dirty=true end end

        startup.subtle_text_wrapped("Friend immunity: ALWAYS ON. Friends do not count toward the trigger, are never marked by Killed You, and never receive its automatic bounty.")
        local activeCount=0
        for _,rec in pairs(R.records) do if startup.killed_you_record_active_b465(rec) then activeCount=activeCount+1 end end
        startup.subtle_text("Currently marked: "..tostring(activeCount).." • Pending retaliation bounties: "..tostring(#R.bountyQueue))
        startup.subtle_text_wrapped(tostring(startup.s.killedYouRetaliationLastStatus or "Ready."))
        if ImGui.Button and ImGui.Button("Clear Killed You History / Marks##StartupB465Clear",-1,30)==true then startup.killed_you_clear_b465() end

        if dirty and startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
    end

    -- Add a fourth collapsible Regional Warfare section without reintroducing child windows.
    rw.b465BaseRenderRegionalWarfare=startup.render_regional_warfare
    function startup.render_regional_warfare()
        if rw.b465BaseRenderRegionalWarfare then rw.b465BaseRenderRegionalWarfare() end
        if not ImGui then return end
        local open=false
        if ImGui.CollapsingHeader then local ok,v=pcall(ImGui.CollapsingHeader,"Killed You Retaliation##StartupB465KilledYouHeader"); open=ok and v==true end
        if open then local ok,err=pcall(startup.render_killed_you_retaliation_b465); if not ok and startup.log then startup.log("[Build 465][KILLED_YOU_DROPDOWN_RECOVERED] "..tostring(err)) end end
    end

    -- Registered after B453/B464, so this late marker pass wins over the normal
    -- IP/Friend/Tracked color layer for non-friend retaliation targets.
    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_PRESENT and R.presentInstalled~=true then
        R.presentInstalled=true
        EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT,function() startup.killed_you_reassert_markers_b465() end)
    end
    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_POST_PRESENT and R.postPresentInstalled~=true then
        R.postPresentInstalled=true
        EventMgr.RegisterHandler(eLuaEvent.ON_POST_PRESENT,function() startup.killed_you_reassert_markers_b465() end)
    end
    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_PLAYER_LEFT and R.playerLeftInstalled~=true then
        R.playerLeftInstalled=true
        EventMgr.RegisterHandler(eLuaEvent.ON_PLAYER_LEFT,function(playerId)
            playerId=tonumber(playerId)
            if playerId~=nil and R.markerOriginal[playerId] then startup.killed_you_restore_marker_b465(playerId,R.markerOriginal[playerId]) end
        end)
    end
end
startup.install_killed_you_retaliation_build465()
startup.install_killed_you_retaliation_build465=nil

startup.version="v1.0.18"
startup.console_version="v1.0.18"
startup.build_number="2026.10.01.465"
startup.build_date="2026-10-01"
startup.build_label="v1.0.18 Production Build 465 - Killed You Retaliation"
startup.changelog_version="2026.10.01.465"
startup.whats_new_version="2026.10.01.465"
startup.release_channel="Production"
if startup.log then
    startup.log("[Build 465] Added configurable Killed You retaliation: friend immunity, Dark Red target marker, one-kill or timed multi-kill rules, mark duration, and optional Minigames-style 9k bounty.")
end
if startup.support_log_event_quiet then
    startup.support_log_event_quiet("BUILD465_KILLED_YOU_RETALIATION_READY","base=B464 default_rule=once_anytime default_color=dark_red default_bounty=true friends_always_immune=true rules=1_anytime,2_5m,3_5m,3_10m,5_10m marker_independent=true")
end

-- ============================================================================
-- BUILD 466: COMPACT REGIONAL WARFARE UI
-- - Combines Player Marker Colors, Selected Enemy Languages, and the live
--   IP/language roster under one Player Classification & Colors dropdown.
-- - Combines selected-target auto-bounty and the staggered bounty queue under
--   one Bounty Automation dropdown.
-- - Keeps Killed You Retaliation separate because it is an independent trigger.
-- - Uses only collapsing headers/standard controls. No ImGui tables or nested
--   custom child windows are introduced by this layout.
-- ============================================================================
function startup.install_compact_regional_warfare_ui_build466()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    function startup.b466_render_core_regional_warfare()
        startup.text_colored(1.00,0.55,0.12,1.00,"REGIONAL WARFARE")
        startup.subtle_text_wrapped("Private-server warfare using IP-country identity first with a safe Cherax Player Language fallback.")
        if ImGui.Separator then ImGui.Separator() end

        startup.render_feature_guarded_325(startup.h.RegionalWarfareEnabled)
        startup.render_feature_guarded_325(startup.h.RegionalWarfareMyFaction)
        startup.render_feature_guarded_325(startup.h.RegionalWarfareEnemyPolicy)

        local own,ownSource="Unknown","unavailable"
        if startup.regional_warfare_own_language then
            local ok,a,b=pcall(startup.regional_warfare_own_language)
            if ok then own=tostring(a or "Unknown"); ownSource=tostring(b or "") end
        end
        startup.subtle_text("My detected warfare language: "..own..(ownSource~="" and (" • "..ownSource) or ""))
        startup.subtle_text_wrapped(tostring(startup.s.regionalWarfareLastStatus or "Ready."))
    end

    function startup.b466_render_marker_color_controls()
        startup.subtle_text_wrapped("Marker priority: Friend → Killed You → Tracked → IP/language. Selecting None leaves the normal Rockstar/CEO/MC marker underneath.")

        local oldMarkers=startup.s.regionalWarfareColorPlayers~=false
        local markerChanged=nil
        if ImGui.Checkbox then
            local newMarkers=ImGui.Checkbox("Color Player Markers##StartupB466ColorPlayers",oldMarkers)
            if newMarkers~=oldMarkers then markerChanged=newMarkers==true end
        end
        startup.hover_help("Uses IP country first. Friend and Tracked markers can override the regional color. Killed You retaliation is handled by its own rule.")
        if markerChanged~=nil then
            startup.s.regionalWarfareColorPlayers=markerChanged==true
            rw.lastBlipColorScanMs=0
            if startup.h and startup.h.RegionalWarfareColorPlayers and startup.set_feature_bool_silently then
                pcall(startup.set_feature_bool_silently,startup.h.RegionalWarfareColorPlayers,markerChanged==true)
            end
            if markerChanged~=true and startup.regional_warfare_restore_blip_colors_449 then pcall(startup.regional_warfare_restore_blip_colors_449) end
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end

        if startup.s.regionalWarfareColorPlayers==false then
            startup.subtle_text("Player marker coloring is disabled.")
            return
        end

        local sigPartsBefore={}
        sigPartsBefore[#sigPartsBefore+1]=tostring(startup.s.regionalWarfareLanguageColors.__Friends or "")
        sigPartsBefore[#sigPartsBefore+1]=tostring(startup.s.regionalWarfareLanguageColors.__Tracked or "")
        for _,language in ipairs(startup.regional_warfare_languages or {}) do
            if language~="Auto (Player Language)" then sigPartsBefore[#sigPartsBefore+1]=tostring(startup.s.regionalWarfareLanguageColors[language] or "") end
        end
        local beforeSig=table.concat(sigPartsBefore,"|")

        local changed=startup.b464_color_combo and startup.b464_color_combo("Friends Marker","__Friends","Dark Green") or nil
        if changed then startup.s.regionalWarfareLanguageColors.__Friends=changed end
        changed=startup.b464_color_combo and startup.b464_color_combo("Tracked Marker","__Tracked","Red") or nil
        if changed then startup.s.regionalWarfareLanguageColors.__Tracked=changed end

        for _,language in ipairs(startup.regional_warfare_languages or {}) do
            if language~="Auto (Player Language)" then
                changed=startup.b464_color_combo and startup.b464_color_combo(tostring(language).." Marker",language,startup.regional_warfare_default_language_colors[language] or "Gray") or nil
                if changed then startup.s.regionalWarfareLanguageColors[language]=changed end
            end
        end

        local sigPartsAfter={}
        sigPartsAfter[#sigPartsAfter+1]=tostring(startup.s.regionalWarfareLanguageColors.__Friends or "")
        sigPartsAfter[#sigPartsAfter+1]=tostring(startup.s.regionalWarfareLanguageColors.__Tracked or "")
        for _,language in ipairs(startup.regional_warfare_languages or {}) do
            if language~="Auto (Player Language)" then sigPartsAfter[#sigPartsAfter+1]=tostring(startup.s.regionalWarfareLanguageColors[language] or "") end
        end
        local afterSig=table.concat(sigPartsAfter,"|")
        rw.b464ColorSignature=afterSig
        if beforeSig~=afterSig then
            rw.lastBlipColorScanMs=0
            if rw.b464SocialCache then rw.b464SocialCache.at=0 end
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end
    end

    function startup.b466_render_enemy_language_controls()
        if tostring(startup.s.regionalWarfareEnemyPolicy or "")~="Selected Languages" then
            startup.subtle_text("Enemy Policy is not set to Selected Languages.")
            return
        end
        startup.subtle_text_wrapped("Choose which detected language groups count as enemies for Regional Warfare automation.")
        for _,language in ipairs(startup.regional_warfare_languages or {}) do
            if language~="Auto (Player Language)" and language~="Unknown" then
                startup.render_feature_guarded_325(startup.h["RegionalWarfareEnemy_"..startup.regional_warfare_feature_key(language)])
            end
        end
    end

    function startup.b466_render_live_roster()
        local rows={}
        local ok,v=pcall(startup.regional_warfare_roster)
        if ok and type(v)=="table" then rows=v end
        if #rows==0 then
            startup.subtle_text("No remote players detected.")
            return
        end
        startup.subtle_text_wrapped("Live player identity used by marker coloring and warfare classification. IP-derived results are estimates; fallback results identify their source.")
        for index,row in ipairs(rows) do
            if index>32 then break end
            local src=tostring(row.languageSource or "")
            startup.subtle_text(tostring(row.name).." • "..tostring(row.language)..(src~="" and (" • "..src) or ""))
        end
    end

    function startup.b466_render_player_classification_colors()
        local colorOpen=false
        if ImGui.CollapsingHeader then
            local ok,v=pcall(ImGui.CollapsingHeader,"Marker Colors & Social Overrides##StartupB466MarkerColors")
            colorOpen=ok and v==true
        end
        if colorOpen then
            local ok,err=pcall(startup.b466_render_marker_color_controls)
            if not ok and startup.log then startup.log("[Build 466][MARKER_COLORS_RECOVERED] "..tostring(err)) end
        end

        local enemyOpen=false
        if ImGui.CollapsingHeader then
            local ok,v=pcall(ImGui.CollapsingHeader,"Selected Enemy Languages##StartupB466EnemyLanguages")
            enemyOpen=ok and v==true
        end
        if enemyOpen then
            local ok,err=pcall(startup.b466_render_enemy_language_controls)
            if not ok and startup.log then startup.log("[Build 466][ENEMY_LANGUAGES_RECOVERED] "..tostring(err)) end
        end

        local rosterOpen=false
        if ImGui.CollapsingHeader then
            local ok,v=pcall(ImGui.CollapsingHeader,"Live IP / Language Roster##StartupB466LiveRoster")
            rosterOpen=ok and v==true
        end
        if rosterOpen then
            local ok,err=pcall(startup.b466_render_live_roster)
            if not ok and startup.log then startup.log("[Build 466][LIVE_ROSTER_RECOVERED] "..tostring(err)) end
        end
    end

    function startup.b466_render_bounty_automation()
        startup.subtle_text_wrapped("All Regional Warfare bounty controls are grouped here: enemy-language automation, selected target/Self/Random, and the staggered round-robin queue.")

        startup.render_feature_guarded_325(startup.h.RegionalWarfareAutoBounty)

        local targetOpen=false
        if ImGui.CollapsingHeader then
            local ok,v=pcall(ImGui.CollapsingHeader,"Selected Target / Self / Random##StartupB466Target")
            targetOpen=ok and v==true
        end
        if targetOpen and startup.b464_render_auto_bounty_target then
            local ok,err=pcall(startup.b464_render_auto_bounty_target)
            if not ok and startup.log then startup.log("[Build 466][TARGET_RECOVERED] "..tostring(err)) end
        end

        local queueOpen=false
        if ImGui.CollapsingHeader then
            local ok,v=pcall(ImGui.CollapsingHeader,"Round-Robin Queue & Timing##StartupB466Queue")
            queueOpen=ok and v==true
        end
        if queueOpen and startup.b464_render_bounty_queue then
            local ok,err=pcall(startup.b464_render_bounty_queue)
            if not ok and startup.log then startup.log("[Build 466][QUEUE_RECOVERED] "..tostring(err)) end
        end

        startup.render_feature_guarded_325(startup.h.RegionalWarfareBountyNow)
        if tostring(startup.s.regionalWarfareLastBountyPlayer or "")~="" then
            startup.subtle_text("Last bounty: "..tostring(startup.s.regionalWarfareLastBountyPlayer).." • "..tostring(startup.s.regionalWarfareLastBountyFaction or ""))
        end
    end

    -- Final B466 renderer. Related controls are grouped into four short top-level
    -- dropdowns instead of scattering classification and bounty controls across the page.
    function startup.render_regional_warfare()
        if not (ImGui and ClickGUI) then return end

        local coreOpen=true
        if ImGui.CollapsingHeader then
            local ok,v=pcall(ImGui.CollapsingHeader,"Regional Warfare##StartupB466Core")
            coreOpen=ok and v==true
        end
        if coreOpen then
            local ok,err=pcall(startup.b466_render_core_regional_warfare)
            if not ok and startup.log then startup.log("[Build 466][CORE_RECOVERED] "..tostring(err)) end
        end

        local classifyOpen=false
        if ImGui.CollapsingHeader then
            local ok,v=pcall(ImGui.CollapsingHeader,"Player Classification & Colors##StartupB466Classify")
            classifyOpen=ok and v==true
        end
        if classifyOpen then
            local ok,err=pcall(startup.b466_render_player_classification_colors)
            if not ok and startup.log then startup.log("[Build 466][CLASSIFICATION_RECOVERED] "..tostring(err)) end
        end

        local bountyOpen=false
        if ImGui.CollapsingHeader then
            local ok,v=pcall(ImGui.CollapsingHeader,"Bounty Automation##StartupB466Bounty")
            bountyOpen=ok and v==true
        end
        if bountyOpen then
            local ok,err=pcall(startup.b466_render_bounty_automation)
            if not ok and startup.log then startup.log("[Build 466][BOUNTY_AUTOMATION_RECOVERED] "..tostring(err)) end
        end

        local retaliationOpen=false
        if ImGui.CollapsingHeader then
            local ok,v=pcall(ImGui.CollapsingHeader,"Killed You Retaliation##StartupB466KilledYou")
            retaliationOpen=ok and v==true
        end
        if retaliationOpen and startup.render_killed_you_retaliation_b465 then
            local ok,err=pcall(startup.render_killed_you_retaliation_b465)
            if not ok and startup.log then startup.log("[Build 466][KILLED_YOU_RECOVERED] "..tostring(err)) end
        end
    end
end
startup.install_compact_regional_warfare_ui_build466()
startup.install_compact_regional_warfare_ui_build466=nil

