end


-- ============================================================================
-- BUILD 467: COMPACT COUNTRY / CLASSIFICATION / BOUNTY UI + COLOR GATING
-- - Country Filter Summary is merged into Country Filter (Auto Kick).
-- - Marker colors, selected enemy languages, and live IP/language roster are one
--   unified classification section with one compact language row per group.
-- - Bounty target + selected-target timing + round-robin timing/status are one
--   Bounty Automation section with no nested dropdowns.
-- - When Enemy Policy = Selected Languages, a known language only receives its
--   regional/IP marker color when that language is enabled as an enemy.
--   Friend / Tracked / Killed You social overrides remain independent.
-- ============================================================================
function startup.install_compact_regional_warfare_ui_build467()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    rw.b467RawRegionalColorName=rw.b467RawRegionalColorName or startup.regional_warfare_color_name

    function startup.b467_language_marker_allowed(language)
        language=startup.regional_warfare_normalize_language and startup.regional_warfare_normalize_language(language) or tostring(language or "Unknown")
        -- Unknown keeps its configured Purple/None behavior because there is no
        -- Enemy: Unknown toggle and it is useful as an unresolved-identity marker.
        if language=="Unknown" then return true end
        if tostring(startup.s.regionalWarfareEnemyPolicy or "All Other Languages")=="Selected Languages" then
            return type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies[language]==true
        end
        return true
    end

    function startup.regional_warfare_color_name(language)
        if startup.b467_language_marker_allowed(language)~=true then return "None" end
        if rw.b467RawRegionalColorName then return rw.b467RawRegionalColorName(language) end
        language=startup.regional_warfare_normalize_language and startup.regional_warfare_normalize_language(language) or tostring(language or "Unknown")
        return tostring((startup.s.regionalWarfareLanguageColors or {})[language] or "None")
    end

    function startup.b467_set_enemy_language(language,value)
        language=tostring(language or "")
        startup.s.regionalWarfareSelectedEnemies=type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies or {}
        startup.s.regionalWarfareSelectedEnemies[language]=value==true
        rw.lastApplied={}
        rw.lastScanMs=0
        rw.lastBlipColorScanMs=0
        local hash=startup.h and startup.h["RegionalWarfareEnemy_"..startup.regional_warfare_feature_key(language)] or nil
        if hash and startup.set_feature_bool_silently then pcall(startup.set_feature_bool_silently,hash,value==true) end
        if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        if startup.regional_warfare_apply_blip_colors_449 then pcall(startup.regional_warfare_apply_blip_colors_449,true) end
    end

    function startup.b467_render_language_row(language,liveCount)
        local languageLabel=tostring(language or "Unknown")
        local isUnknown=languageLabel=="Unknown"
        local liveSuffix=((tonumber(liveCount or 0) or 0)>0 and ("  ["..tostring(liveCount).." live]") or "")

        -- Build 468: keep the language/region visible on every control. B467 used
        -- an ImGui-hidden checkbox label (##...), which made it impossible to tell
        -- which Enemy checkbox belonged to which language.
        startup.subtle_text("Language / Region: "..languageLabel..liveSuffix)

        if not isUnknown then
            local old=type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies[language]==true
            if ImGui.Checkbox then
                local new=ImGui.Checkbox("Enemy: "..languageLabel.."##StartupB468Enemy_"..startup.regional_warfare_feature_key(language),old)
                if new~=old then startup.b467_set_enemy_language(language,new==true) end
            end
        else
            startup.subtle_text("Enemy: Unknown is not selectable")
        end

        local changed=startup.b464_color_combo and startup.b464_color_combo(
            "Marker Color: "..languageLabel,
            language,
            startup.regional_warfare_default_language_colors[language] or (isUnknown and "Purple" or "Gray")
        ) or nil
        if changed then
            startup.s.regionalWarfareLanguageColors=startup.s.regionalWarfareLanguageColors or {}
            startup.s.regionalWarfareLanguageColors[language]=changed
            rw.lastBlipColorScanMs=0
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end

        if ImGui.Separator then ImGui.Separator() end
    end

    function startup.b467_render_player_classification_colors()
        startup.subtle_text_wrapped("One place for social marker overrides, enemy-language selection, IP-derived colors, and the live roster. Under Selected Languages, turning a language OFF also removes its regional marker color.")

        local oldMarkers=startup.s.regionalWarfareColorPlayers~=false
        if ImGui.Checkbox then
            local newMarkers=ImGui.Checkbox("Color Player Markers (Language / Region)##StartupB468ColorPlayers",oldMarkers)
            if newMarkers~=oldMarkers then
                startup.s.regionalWarfareColorPlayers=newMarkers==true
                rw.lastBlipColorScanMs=0
                if startup.h and startup.h.RegionalWarfareColorPlayers and startup.set_feature_bool_silently then pcall(startup.set_feature_bool_silently,startup.h.RegionalWarfareColorPlayers,newMarkers==true) end
                if newMarkers~=true and startup.regional_warfare_restore_blip_colors_449 then pcall(startup.regional_warfare_restore_blip_colors_449) end
                if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
            end
        end

        startup.s.regionalWarfareLanguageColors=startup.s.regionalWarfareLanguageColors or {}
        local changed=startup.b464_color_combo and startup.b464_color_combo("Friends Marker","__Friends","Dark Green") or nil
        if changed then startup.s.regionalWarfareLanguageColors.__Friends=changed; rw.lastBlipColorScanMs=0 end
        changed=startup.b464_color_combo and startup.b464_color_combo("Tracked Marker","__Tracked","Red") or nil
        if changed then startup.s.regionalWarfareLanguageColors.__Tracked=changed; rw.lastBlipColorScanMs=0 end

        if ImGui.Separator then ImGui.Separator() end
        local rows={}
        local okRows,v=pcall(startup.regional_warfare_roster)
        if okRows and type(v)=="table" then rows=v end
        local counts={}
        for _,row in ipairs(rows) do counts[tostring(row.language or "Unknown")]=(counts[tostring(row.language or "Unknown")] or 0)+1 end

        startup.subtle_text("Language / Region controls")
        for _,language in ipairs(startup.regional_warfare_languages or {}) do
            if language~="Auto (Player Language)" then startup.b467_render_language_row(language,counts[tostring(language)] or 0) end
        end

        if ImGui.Separator then ImGui.Separator() end
        startup.subtle_text("Live IP / language roster")
        if #rows==0 then
            startup.subtle_text("No remote players detected.")
        else
            for index,row in ipairs(rows) do
                if index>32 then break end
                local src=tostring(row.languageSource or "")
                local sourceInfo=rw.b461ColorSource and rw.b461ColorSource[tonumber(row.playerId)] or nil
                local countryCode=type(sourceInfo)=="table" and tostring(sourceInfo.countryCode or "") or ""
                local country=type(sourceInfo)=="table" and tostring(sourceInfo.country or "") or ""
                local ipPart=""
                if countryCode~="" then ipPart=" • "..countryCode elseif country~="" then ipPart=" • "..country end
                startup.subtle_text(tostring(row.name).." • "..tostring(row.language)..ipPart..(src~="" and (" • "..src) or ""))
            end
        end
    end

    function startup.b467_render_bounty_automation()
        startup.subtle_text_wrapped("Enemy-language Auto-Bounty, named target/Self/Random selection, selected-target interval, and round-robin queue timing are all configured here.")
        startup.render_feature_guarded_325(startup.h.RegionalWarfareAutoBounty)
        if startup.b464_render_auto_bounty_target then
            local ok,err=pcall(startup.b464_render_auto_bounty_target)
            if not ok and startup.log then startup.log("[Build 467][TARGET_TIMING_RECOVERED] "..tostring(err)) end
        end
        if ImGui.Separator then ImGui.Separator() end
        if startup.b464_render_bounty_queue then
            local ok,err=pcall(startup.b464_render_bounty_queue)
            if not ok and startup.log then startup.log("[Build 467][QUEUE_TIMING_RECOVERED] "..tostring(err)) end
        end
        startup.render_feature_guarded_325(startup.h.RegionalWarfareBountyNow)
        if tostring(startup.s.regionalWarfareLastBountyPlayer or "")~="" then
            startup.subtle_text("Last enemy-language bounty: "..tostring(startup.s.regionalWarfareLastBountyPlayer).." • "..tostring(startup.s.regionalWarfareLastBountyFaction or ""))
        end
    end

    function startup.render_regional_warfare()
        if not (ImGui and ClickGUI) then return end

        local coreOpen=true
        if ImGui.CollapsingHeader then local ok,v=pcall(ImGui.CollapsingHeader,"Regional Warfare##StartupB467Core"); coreOpen=ok and v==true end
        if coreOpen then
            local ok,err=pcall(startup.b466_render_core_regional_warfare)
            if not ok and startup.log then startup.log("[Build 467][CORE_RECOVERED] "..tostring(err)) end
        end

        local classifyOpen=false
        if ImGui.CollapsingHeader then local ok,v=pcall(ImGui.CollapsingHeader,"Player Classification & Colors##StartupB467Classify"); classifyOpen=ok and v==true end
        if classifyOpen then
            local ok,err=pcall(startup.b467_render_player_classification_colors)
            if not ok and startup.log then startup.log("[Build 467][CLASSIFICATION_RECOVERED] "..tostring(err)) end
        end

        local bountyOpen=false
        if ImGui.CollapsingHeader then local ok,v=pcall(ImGui.CollapsingHeader,"Bounty Automation##StartupB467Bounty"); bountyOpen=ok and v==true end
        if bountyOpen then
            local ok,err=pcall(startup.b467_render_bounty_automation)
            if not ok and startup.log then startup.log("[Build 467][BOUNTY_RECOVERED] "..tostring(err)) end
        end

        local retaliationOpen=false
        if ImGui.CollapsingHeader then local ok,v=pcall(ImGui.CollapsingHeader,"Killed You Retaliation##StartupB467KilledYou"); retaliationOpen=ok and v==true end
        if retaliationOpen and startup.render_killed_you_retaliation_b465 then
            local ok,err=pcall(startup.render_killed_you_retaliation_b465)
            if not ok and startup.log then startup.log("[Build 467][KILLED_YOU_RECOVERED] "..tostring(err)) end
        end
    end
end
startup.install_compact_regional_warfare_ui_build467()
startup.install_compact_regional_warfare_ui_build467=nil

