-- ============================================================================
-- BUILD 469: THREE-COLUMN LANGUAGE / ENEMY / MARKER COLOR LAYOUT
-- - Renders each regional language row as three aligned visual columns without
--   BeginTable/EndTable, avoiding the table-scope instability seen previously.
-- - Column 1: Region / Language + live count.
-- - Column 2: Enemy checkbox.
-- - Column 3: Marker Color dropdown.
-- ============================================================================
function startup.install_three_column_language_markers_build469()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    function startup.b469_content_width()
        if not (ImGui and ImGui.GetContentRegionAvail) then return 760 end
        local ok,a=pcall(ImGui.GetContentRegionAvail)
        if not ok then return 760 end
        if type(a)=="number" then return math.max(tonumber(a) or 0,320) end
        if type(a)=="table" then return math.max(tonumber(a.x or a.X or a[1] or 0) or 0,320) end
        return 760
    end

    function startup.b469_color_combo_cell(language,width)
        if not (ImGui and ImGui.BeginCombo and ImGui.Selectable) then return nil end
        startup.s.regionalWarfareLanguageColors=startup.s.regionalWarfareLanguageColors or {}
        local isUnknown=tostring(language or "Unknown")=="Unknown"
        local defaultValue=startup.regional_warfare_default_language_colors[language] or (isUnknown and "Purple" or "Gray")
        local current=tostring(startup.s.regionalWarfareLanguageColors[language] or defaultValue or "None")
        if startup.regional_warfare_color_ids[current]==nil then current=tostring(defaultValue or "None") end
        if ImGui.SetNextItemWidth then pcall(ImGui.SetNextItemWidth,math.max(120,tonumber(width or 220) or 220)) end
        local changed=nil
        local opened=false
        local okOpen,v=pcall(ImGui.BeginCombo,"##StartupB469MarkerColor_"..startup.regional_warfare_feature_key(language),current)
        opened=okOpen and v==true
        if opened then
            local okBody,err=pcall(function()
                for _,colorName in ipairs(startup.regional_warfare_color_names or {}) do
                    if ImGui.Selectable(tostring(colorName).."##StartupB469MarkerColorOpt_"..startup.regional_warfare_feature_key(language).."_"..tostring(colorName),current==colorName) then
                        changed=colorName
                    end
                end
            end)
            pcall(ImGui.EndCombo)
            if not okBody and startup.log then startup.log("[Build 469][COLOR_COMBO_RECOVERED] "..tostring(err)) end
        end
        return changed
    end

    function startup.b469_language_columns()
        local startX=(ImGui and ImGui.GetCursorPosX and tonumber(ImGui.GetCursorPosX())) or 0
        local width=startup.b469_content_width()
        local languageWidth=math.max(185,width*0.43)
        local enemyWidth=math.max(82,width*0.14)
        local gap=10
        local enemyX=startX+languageWidth
        local colorX=enemyX+enemyWidth
        local colorWidth=math.max(140,width-(colorX-startX)-gap)
        return startX,enemyX,colorX,colorWidth
    end

    function startup.b469_render_language_headers()
        local startX,enemyX,colorX=startup.b469_language_columns()
        if ImGui and ImGui.SetCursorPosX then pcall(ImGui.SetCursorPosX,startX) end
        startup.subtle_text("Region / Language")
        if ImGui and ImGui.SameLine then pcall(ImGui.SameLine,enemyX) end
        startup.subtle_text("Enemy")
        if ImGui and ImGui.SameLine then pcall(ImGui.SameLine,colorX) end
        startup.subtle_text("Marker Color")
        if ImGui and ImGui.Separator then ImGui.Separator() end
    end

    function startup.b467_render_language_row(language,liveCount)
        local languageLabel=tostring(language or "Unknown")
        local isUnknown=languageLabel=="Unknown"
        local liveSuffix=((tonumber(liveCount or 0) or 0)>0 and ("  ["..tostring(liveCount).." live]") or "")
        local startX,enemyX,colorX,colorWidth=startup.b469_language_columns()

        if ImGui and ImGui.SetCursorPosX then pcall(ImGui.SetCursorPosX,startX) end
        startup.subtle_text(languageLabel..liveSuffix)

        if ImGui and ImGui.SameLine then pcall(ImGui.SameLine,enemyX) end
        if not isUnknown then
            local old=type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies[language]==true
            if ImGui.Checkbox then
                local new=ImGui.Checkbox("##StartupB469Enemy_"..startup.regional_warfare_feature_key(language),old)
                if new~=old then startup.b467_set_enemy_language(language,new==true) end
            end
        else
            startup.subtle_text("-")
        end

        if ImGui and ImGui.SameLine then pcall(ImGui.SameLine,colorX) end
        local changed=startup.b469_color_combo_cell(language,colorWidth)
        if changed then
            startup.s.regionalWarfareLanguageColors=startup.s.regionalWarfareLanguageColors or {}
            startup.s.regionalWarfareLanguageColors[language]=changed
            rw.lastBlipColorScanMs=0
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end
    end

    function startup.b467_render_player_classification_colors()
        startup.subtle_text_wrapped("One place for social marker overrides, enemy-language selection, IP-derived colors, and the live roster. Under Selected Languages, turning a language OFF also removes its regional marker color.")

        local oldMarkers=startup.s.regionalWarfareColorPlayers~=false
        if ImGui.Checkbox then
            local newMarkers=ImGui.Checkbox("Color Player Markers (Language / Region)##StartupB469ColorPlayers",oldMarkers)
            if newMarkers~=oldMarkers then
                startup.s.regionalWarfareColorPlayers=newMarkers==true
                rw.lastBlipColorScanMs=0
                if startup.h and startup.h.RegionalWarfareColorPlayers and startup.set_feature_bool_silently then pcall(startup.set_feature_bool_silently,startup.h.RegionalWarfareColorPlayers,newMarkers==true) end
                if newMarkers~=true and startup.regional_warfare_restore_blip_colors_449 then pcall(startup.regional_warfare_restore_blip_colors_449) end
                if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
            end
        end

        startup.s.regionalWarfareLanguageColors=startup.s.regionalWarfareLanguageColors or {}
        local changed=startup.b464_color_combo and startup.b464_color_combo("Friends Marker","__Friends","Dark Green") or nil
        if changed then startup.s.regionalWarfareLanguageColors.__Friends=changed; rw.lastBlipColorScanMs=0 end
        changed=startup.b464_color_combo and startup.b464_color_combo("Tracked Marker","__Tracked","Red") or nil
        if changed then startup.s.regionalWarfareLanguageColors.__Tracked=changed; rw.lastBlipColorScanMs=0 end

        if ImGui.Separator then ImGui.Separator() end
        local rows={}
        local okRows,v=pcall(startup.regional_warfare_roster)
        if okRows and type(v)=="table" then rows=v end
        local counts={}
        for _,row in ipairs(rows) do counts[tostring(row.language or "Unknown")]=(counts[tostring(row.language or "Unknown")] or 0)+1 end

        startup.b469_render_language_headers()
        for _,language in ipairs(startup.regional_warfare_languages or {}) do
            if language~="Auto (Player Language)" then
                startup.b467_render_language_row(language,counts[tostring(language)] or 0)
            end
        end

        if ImGui.Separator then ImGui.Separator() end
        startup.subtle_text("Live IP / language roster")
        if #rows==0 then
            startup.subtle_text("No remote players detected.")
        else
            for index,row in ipairs(rows) do
                if index>32 then break end
                local src=tostring(row.languageSource or "")
                local sourceInfo=rw.b461ColorSource and rw.b461ColorSource[tonumber(row.playerId)] or nil
                local countryCode=type(sourceInfo)=="table" and tostring(sourceInfo.countryCode or "") or ""
                local country=type(sourceInfo)=="table" and tostring(sourceInfo.country or "") or ""
                local ipPart=""
                if countryCode~="" then ipPart=" • "..countryCode elseif country~="" then ipPart=" • "..country end
                startup.subtle_text(tostring(row.name).." • "..tostring(row.language)..ipPart..(src~="" and (" • "..src) or ""))
            end
        end
    end
end
startup.install_three_column_language_markers_build469()
startup.install_three_column_language_markers_build469=nil

