-- ============================================================================
-- BUILD 470: RELIABLE COLOR SELECTION
-- - Build 469's BeginCombo + Selectable cells could render but fail to commit
--   selections under Cherax. Use the proven all-in-one ImGui.Combo binding.
-- - Keeps the B469 three-column layout unchanged.
-- - Synchronizes the custom UI selection to the underlying Regional Warfare
--   feature, reapplies marker colors immediately, and persists the config.
-- ============================================================================
function startup.install_color_selection_fix_build470()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    function startup.b470_color_current(key,defaultValue)
        startup.s.regionalWarfareLanguageColors=type(startup.s.regionalWarfareLanguageColors)=="table" and startup.s.regionalWarfareLanguageColors or {}
        local value=tostring(startup.s.regionalWarfareLanguageColors[key] or defaultValue or "None")
        if startup.regional_warfare_color_ids[value]==nil then value=tostring(defaultValue or "None") end
        if startup.regional_warfare_color_ids[value]==nil then value="None" end
        return value
    end

    function startup.b470_color_combo(id,current,width)
        local items=startup.regional_warfare_color_names or {}
        if not (ImGui and ImGui.Combo) or type(items)~="table" or #items==0 then return nil end
        current=tostring(current or "None")
        local currentIndex=0
        for i,v in ipairs(items) do
            if tostring(v)==current then currentIndex=i-1 break end
        end
        if ImGui.SetNextItemWidth then pcall(ImGui.SetNextItemWidth,math.max(120,tonumber(width or 220) or 220)) end
        local label="##StartupB470Color_"..tostring(id or "Color")
        local ok,a,b=pcall(ImGui.Combo,label,currentIndex,items,#items,math.min(#items,12))
        if not ok then ok,a,b=pcall(ImGui.Combo,label,currentIndex,items) end
        if not ok then
            if startup.log then startup.log("[Build 470][COLOR_COMBO_RECOVERED] "..tostring(a)) end
            return nil
        end
        local idx=nil
        if type(a)=="number" then idx=math.floor(a) elseif type(b)=="number" then idx=math.floor(b) end
        if idx==nil then return nil end
        if idx<0 then idx=0 elseif idx>#items-1 then idx=#items-1 end
        if idx~=currentIndex then return tostring(items[idx+1] or current) end
        return nil
    end

    function startup.b470_sync_language_feature(language,colorName)
        if tostring(language or ""):sub(1,2)=="__" then return end
        if not (startup.h and startup.regional_warfare_feature_key and startup.set_feature_list_string_silently) then return end
        local featureKey="RegionalWarfareColor_"..startup.regional_warfare_feature_key(language)
        local feature=startup.h[featureKey]
        if feature then pcall(startup.set_feature_list_string_silently,feature,tostring(colorName or "None")) end
    end

    function startup.b470_commit_marker_color(key,colorName)
        key=tostring(key or "")
        colorName=tostring(colorName or "None")
        if key=="" or startup.regional_warfare_color_ids[colorName]==nil then return false end
        startup.s.regionalWarfareLanguageColors=type(startup.s.regionalWarfareLanguageColors)=="table" and startup.s.regionalWarfareLanguageColors or {}
        startup.s.regionalWarfareLanguageColors[key]=colorName
        startup.b470_sync_language_feature(key,colorName)
        rw.lastBlipColorScanMs=0
        rw.lastScanMs=0
        rw.lastApplied={}
        if startup.regional_warfare_apply_blip_colors_449 then pcall(startup.regional_warfare_apply_blip_colors_449,true) end
        if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        return true
    end

    -- Used by the B469 third column.
    function startup.b469_color_combo_cell(language,width)
        local isUnknown=tostring(language or "Unknown")=="Unknown"
        local defaultValue=startup.regional_warfare_default_language_colors[language] or (isUnknown and "Purple" or "Gray")
        local current=startup.b470_color_current(language,defaultValue)
        return startup.b470_color_combo("Language_"..startup.regional_warfare_feature_key(language),current,width)
    end

    -- Also move Friend / Tracked marker selectors onto the same reliable Combo
    -- implementation so every color selector behaves consistently.
    function startup.b464_color_combo(label,key,defaultValue)
        local current=startup.b470_color_current(key,defaultValue)
        if ImGui and ImGui.Text then pcall(ImGui.Text,tostring(label or "Marker Color")) end
        return startup.b470_color_combo("Social_"..tostring(key),current,-1)
    end

    -- Override the B469 row so a successful Combo change is committed through a
    -- single path that updates state, Cherax's backing feature, live blips, and config.
    function startup.b467_render_language_row(language,liveCount)
        local languageLabel=tostring(language or "Unknown")
        local isUnknown=languageLabel=="Unknown"
        local liveSuffix=((tonumber(liveCount or 0) or 0)>0 and ("  ["..tostring(liveCount).." live]") or "")
        local startX,enemyX,colorX,colorWidth=startup.b469_language_columns()

        if ImGui and ImGui.SetCursorPosX then pcall(ImGui.SetCursorPosX,startX) end
        startup.subtle_text(languageLabel..liveSuffix)

        if ImGui and ImGui.SameLine then pcall(ImGui.SameLine,enemyX) end
        if not isUnknown then
            local old=type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies[language]==true
            if ImGui.Checkbox then
                local new=ImGui.Checkbox("##StartupB470Enemy_"..startup.regional_warfare_feature_key(language),old)
                if new~=old then startup.b467_set_enemy_language(language,new==true) end
            end
        else
            startup.subtle_text("-")
        end

        if ImGui and ImGui.SameLine then pcall(ImGui.SameLine,colorX) end
        local changed=startup.b469_color_combo_cell(language,colorWidth)
        if changed then startup.b470_commit_marker_color(language,changed) end
    end

    -- B467's combined classification renderer updates Friend / Tracked itself.
    -- Wrap it so social changes are persisted and immediately reapplied too.
    local previousClassification=startup.b467_render_player_classification_colors
    function startup.b467_render_player_classification_colors()
        local beforeFriends=startup.b470_color_current("__Friends","Dark Green")
        local beforeTracked=startup.b470_color_current("__Tracked","Red")
        previousClassification()
        local afterFriends=startup.b470_color_current("__Friends","Dark Green")
        local afterTracked=startup.b470_color_current("__Tracked","Red")
        if afterFriends~=beforeFriends then startup.b470_commit_marker_color("__Friends",afterFriends) end
        if afterTracked~=beforeTracked then startup.b470_commit_marker_color("__Tracked",afterTracked) end
    end
end
