-- ============================================================================
-- BUILD 471: LIVE PLAYER AUTO-BOUNTY TARGET DROPDOWN
-- - The Auto-Bounty target Combo is built from Cherax's live player list,
--   independent of Regional Warfare/IP/language roster availability.
-- - Order: None / You-Self / Random Player / every current remote player.
-- - Uses ImGui.Combo rather than BeginCombo + Selectable for reliable selection.
-- ============================================================================
function startup.install_live_player_bounty_targets_build471()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    function startup.b471_live_bounty_target_rows()
        local rows={}
        local ids={}
        local seen={}
        local localId=-1
        if startup.regional_warfare_local_player_id then
            local ok,v=pcall(startup.regional_warfare_local_player_id)
            if ok then localId=tonumber(v or -1) or -1 end
        end

        if Players and Players.Get then
            local sortMode=(ePlayerListSort and ePlayerListSort.PLAYER_ID) or 0
            local ok,list=pcall(Players.Get,sortMode,"")
            if ok and type(list)=="table" then
                for _,pid in pairs(list) do
                    pid=tonumber(pid)
                    if pid~=nil and pid>=0 and pid<=31 and not seen[pid] then
                        seen[pid]=true
                        ids[#ids+1]=pid
                    end
                end
            end
        end

        -- Fallback scan if Cherax's sorted list is temporarily unavailable.
        if #ids==0 and Players and Players.GetById then
            for pid=0,31 do
                local ok,obj=pcall(Players.GetById,pid)
                if ok and obj~=nil and not seen[pid] then
                    seen[pid]=true
                    ids[#ids+1]=pid
                    local isLocal=false
                    pcall(function() if obj.IsLocalPlayer then isLocal=obj:IsLocalPlayer()==true end end)
                    if isLocal then localId=pid end
                end
            end
        end

        if localId>=0 and localId<=31 and not seen[localId] then
            seen[localId]=true
            ids[#ids+1]=localId
        end

        table.sort(ids)
        for _,pid in ipairs(ids) do
            local name="Player "..tostring(pid)
            if startup.get_player_name_safe then
                local ok,v=pcall(startup.get_player_name_safe,pid)
                if ok and tostring(v or "")~="" then name=tostring(v) end
            elseif Players and Players.GetName then
                local ok,v=pcall(Players.GetName,pid)
                if ok and tostring(v or "")~="" then name=tostring(v) end
            end

            local rid=""
            if startup.regional_warfare_get_rid then
                local ok,v=pcall(startup.regional_warfare_get_rid,pid)
                if ok then rid=tostring(v or "") end
            end
            if rid=="" and Players and Players.GetById then
                local okP,obj=pcall(Players.GetById,pid)
                if okP and obj and obj.GetGamerInfo then
                    local okI,info=pcall(function() return obj:GetGamerInfo() end)
                    if okI and info then pcall(function() rid=tostring(info.RockstarId or "") end) end
                end
            end

            rows[#rows+1]={
                playerId=pid,
                rid=rid,
                name=name,
                language="Unknown",
                isSelf=(pid==localId)
            }
        end

        table.sort(rows,function(a,b)
            if a.isSelf~=b.isSelf then return a.isSelf==true end
            return string.lower(tostring(a.name or ""))<string.lower(tostring(b.name or ""))
        end)
        return rows
    end

    function startup.b471_target_combo(rows)
        rows=type(rows)=="table" and rows or {}
        local selfRow=nil
        local remoteRows={}
        for _,row in ipairs(rows) do
            if row.isSelf==true then selfRow=row else remoteRows[#remoteRows+1]=row end
        end

        local items={"None","You / Self"..(selfRow and (" - "..tostring(selfRow.name)) or ""),"Random Player"}
        local mappings={{mode="none"},{mode="self",row=selfRow},{mode="random"}}
        for _,row in ipairs(remoteRows) do
            items[#items+1]="["..tostring(row.playerId).."] "..tostring(row.name)
            mappings[#mappings+1]={mode="player",row=row}
        end

        local mode=tostring(startup.s.regionalWarfareAutoBountyTargetMode or "none")
        local wantedRid=tostring(startup.s.regionalWarfareSelectedAutoBountyPlayerRid or "")
        local wantedId=tonumber(startup.s.regionalWarfareSelectedAutoBountyPlayerId or -1) or -1
        local currentIndex=0
        if mode=="self" then currentIndex=1
        elseif mode=="random" then currentIndex=2
        elseif mode=="player" then
            for i=4,#mappings do
                local row=mappings[i] and mappings[i].row or nil
                if row then
                    local ridMatch=wantedRid~="" and tostring(row.rid or "")==wantedRid
                    local idMatch=wantedRid=="" and tonumber(row.playerId)==wantedId
                    if ridMatch or idMatch then currentIndex=i-1 break end
                end
            end
        end

        if not (ImGui and ImGui.Combo) then return nil,nil,#remoteRows end
        if ImGui.SetNextItemWidth then pcall(ImGui.SetNextItemWidth,-1) end
        local ok,a,b=pcall(ImGui.Combo,"Auto-Bounty Target##StartupB471LiveTarget",currentIndex,items,#items,math.min(#items,18))
        if not ok then ok,a,b=pcall(ImGui.Combo,"Auto-Bounty Target##StartupB471LiveTarget",currentIndex,items) end
        if not ok then
            if startup.log then startup.log("[Build 471][TARGET_COMBO_RECOVERED] "..tostring(a)) end
            return nil,nil,#remoteRows
        end
        local idx=nil
        if type(a)=="number" then idx=math.floor(a) elseif type(b)=="number" then idx=math.floor(b) end
        if idx==nil then return nil,nil,#remoteRows end
        if idx<0 then idx=0 elseif idx>#items-1 then idx=#items-1 end
        if idx==currentIndex then return nil,nil,#remoteRows end
        local mapping=mappings[idx+1]
        if not mapping then return nil,nil,#remoteRows end
        return mapping.mode,mapping.row,#remoteRows
    end

    function startup.b464_render_auto_bounty_target()
        local rows={}
        local okRows,resultRows=pcall(startup.b471_live_bounty_target_rows)
        if okRows and type(resultRows)=="table" then rows=resultRows end

        startup.subtle_text_wrapped("Choose None, You / Self, Random Player, or any currently connected player. This list comes directly from Cherax's live player list and does not depend on IP/language detection.")
        local actionMode,actionRow,remoteCount=startup.b471_target_combo(rows)

        local intervalOptions={{label="30 seconds",sec=30},{label="1 minute",sec=60},{label="2 minutes",sec=120},{label="5 minutes",sec=300},{label="10 minutes",sec=600},{label="15 minutes",sec=900},{label="30 minutes",sec=1800},{label="60 minutes",sec=3600}}
        local currentSec=tonumber(startup.s.regionalWarfareAutoBountyIntervalSec or 300) or 300
        local intervalPreview=tostring(math.floor(currentSec/60)).." minutes"
        for _,opt in ipairs(intervalOptions) do if opt.sec==currentSec then intervalPreview=opt.label break end end
        local intervalChanged=nil
        if ImGui.SetNextItemWidth then pcall(ImGui.SetNextItemWidth,-1) end
        if ImGui and ImGui.Combo then
            local labels={}
            local currentIndex=0
            for i,opt in ipairs(intervalOptions) do
                labels[#labels+1]=opt.label
                if opt.sec==currentSec then currentIndex=i-1 end
            end
            local ok,a,b=pcall(ImGui.Combo,"Bounty Interval##StartupB471BountyInterval",currentIndex,labels,#labels,#labels)
            if not ok then ok,a,b=pcall(ImGui.Combo,"Bounty Interval##StartupB471BountyInterval",currentIndex,labels) end
            if ok then
                local idx=nil
                if type(a)=="number" then idx=math.floor(a) elseif type(b)=="number" then idx=math.floor(b) end
                if idx~=nil then
                    if idx<0 then idx=0 elseif idx>#intervalOptions-1 then idx=#intervalOptions-1 end
                    if idx~=currentIndex then intervalChanged=intervalOptions[idx+1].sec end
                end
            end
        end

        local oldAuto=startup.s.regionalWarfareSelectedAutoBountyEnabled==true
        local autoChanged=nil
        if ImGui and ImGui.Checkbox then
            local newAuto=ImGui.Checkbox("Auto-Bounty Selected Target##StartupB471AutoBountyToggle",oldAuto)
            if newAuto~=oldAuto then autoChanged=newAuto==true end
        end
        local manualClicked=false
        if ImGui and ImGui.Button and ImGui.Button("Apply Bounty Now##StartupB471BountyNow",-1,30)==true then manualClicked=true end

        local sec=tonumber(startup.s.regionalWarfareAutoBountyIntervalSec or 300) or 300
        startup.subtle_text("Live selectable players: "..tostring(tonumber(remoteCount or 0) or 0).." • Interval: "..tostring(sec<60 and (tostring(sec).." sec") or (tostring(math.floor(sec/60)).." min")).." • Amount: built-in 9k")
        startup.subtle_text_wrapped(tostring(startup.s.regionalWarfareSelectedAutoBountyLastStatus or "Ready."))
        if rw.b459LastRandomName~="" then startup.subtle_text("Last random target: "..tostring(rw.b459LastRandomName)) end
        if not okRows then startup.subtle_text("Live player list recovered from a transient Cherax lookup error.") end

        if actionMode then
            pcall(startup.b459_set_bounty_mode,actionMode,actionRow)
            rw.b455PlayerRowsCache=nil
            rw.b455PlayerRowsCacheMs=0
            if startup.s.regionalWarfareSelectedAutoBountyEnabled==true and actionMode~="none" then pcall(startup.b455_queue_selected_bounty,"Target changed") end
        end
        if intervalChanged then
            startup.s.regionalWarfareAutoBountyIntervalSec=tonumber(intervalChanged) or 300
            startup.s.regionalWarfareSelectedAutoBountyIntervalMs=startup.s.regionalWarfareAutoBountyIntervalSec*1000
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end
        if autoChanged~=nil then
            startup.s.regionalWarfareSelectedAutoBountyEnabled=autoChanged==true
            rw.b455SelectedBountyLastMs=0
            if startup.h and startup.h.RegionalWarfareSelectedAutoBounty and startup.set_feature_bool_silently then pcall(startup.set_feature_bool_silently,startup.h.RegionalWarfareSelectedAutoBounty,autoChanged==true) end
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
            if autoChanged==true then pcall(startup.b455_queue_selected_bounty,"Auto enabled") end
        end
        if manualClicked==true then pcall(startup.b455_queue_selected_bounty,"Manual") end
    end
end
startup.install_live_player_bounty_targets_build471()
startup.install_live_player_bounty_targets_build471=nil

