-- ============================================================================
-- BUILD 472: LIVE TARGET RESOLVER FIX
-- - B471 rendered targets from the direct Cherax live player list, but the older
--   B459 execution path re-resolved them through the IP/language roster.
-- - Selection, Self, Random, queued verification, and execution now all resolve
--   from the same B471 live player list.
-- - PID + RID/name checks protect against stale/reused player slots.
-- ============================================================================
function startup.install_live_target_resolver_fix_build472()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    function startup.b472_normalize_rid(value)
        local rid=tostring(value or ""):gsub("^%s+",""):gsub("%s+$","")
        local lower=string.lower(rid)
        if rid=="" or rid=="0" or rid=="-1" or lower=="nil" or lower=="none" or lower=="unknown" then return "" end
        return rid
    end

    function startup.b472_live_target_rows()
        if not startup.b471_live_bounty_target_rows then return {} end
        local ok,rows=pcall(startup.b471_live_bounty_target_rows)
        if not ok or type(rows)~="table" then return {} end
        return rows
    end

    function startup.b472_enrich_target_row(row)
        if type(row)~="table" then return nil end
        row.rid=startup.b472_normalize_rid(row.rid)
        if tostring(row.language or "Unknown")=="Unknown" and startup.regional_warfare_player_language then
            local ok,language,source=pcall(startup.regional_warfare_player_language,tonumber(row.playerId or -1) or -1)
            if ok and tostring(language or "")~="" then
                row.language=tostring(language)
                row.languageSource=tostring(source or "")
            end
        end
        return row
    end

    function startup.b472_find_live_target(target)
        if type(target)~="table" then return nil end
        local wantedPid=tonumber(target.playerId or -1) or -1
        local wantedRid=startup.b472_normalize_rid(target.rid)
        local wantedName=tostring(target.name or "")
        local rows=startup.b472_live_target_rows()

        -- Strongest match: current slot + RID.
        if wantedPid>=0 and wantedRid~="" then
            for _,row in ipairs(rows) do
                if tonumber(row.playerId)==wantedPid and startup.b472_normalize_rid(row.rid)==wantedRid then
                    return startup.b472_enrich_target_row(row)
                end
            end
        end

        -- RID survives a slot move across a session transition.
        if wantedRid~="" then
            for _,row in ipairs(rows) do
                if startup.b472_normalize_rid(row.rid)==wantedRid then
                    return startup.b472_enrich_target_row(row)
                end
            end
        end

        -- Cherax may temporarily fail to expose RID. PID + same name is safe for
        -- the current live session and avoids the false "target unavailable" state.
        if wantedPid>=0 then
            for _,row in ipairs(rows) do
                if tonumber(row.playerId)==wantedPid then
                    local liveName=tostring(row.name or "")
                    if wantedName=="" or liveName==wantedName then
                        return startup.b472_enrich_target_row(row)
                    end
                end
            end
        end

        -- Last safe recovery: unique exact name match.
        if wantedName~="" then
            local match=nil
            local count=0
            for _,row in ipairs(rows) do
                if tostring(row.name or "")==wantedName then
                    match=row
                    count=count+1
                end
            end
            if count==1 then return startup.b472_enrich_target_row(match) end
        end
        return nil
    end

    function startup.b459_self_row(forceRefresh)
        for _,row in ipairs(startup.b472_live_target_rows()) do
            if row.isSelf==true then return startup.b472_enrich_target_row(row) end
        end
        return nil
    end

    function startup.b455_resolve_selected_bounty_target(forceRefresh)
        local mode=tostring(startup.s.regionalWarfareAutoBountyTargetMode or "none")
        if mode=="self" then return startup.b459_self_row(true) end
        if mode~="player" then return nil end
        return startup.b472_find_live_target({
            playerId=tonumber(startup.s.regionalWarfareSelectedAutoBountyPlayerId or -1) or -1,
            rid=startup.b472_normalize_rid(startup.s.regionalWarfareSelectedAutoBountyPlayerRid),
            name=tostring(startup.s.regionalWarfareSelectedAutoBountyPlayerName or "")
        })
    end

    function startup.b459_find_live_row(target,forceRefresh)
        return startup.b472_find_live_target(target)
    end

    function startup.b459_pick_random_bounty_target(forceRefresh)
        local candidates={}
        for _,row in ipairs(startup.b472_live_target_rows()) do
            if row.isSelf~=true then candidates[#candidates+1]=row end
        end
        if #candidates==0 then return nil end
        if #candidates>1 and tostring(rw.b459LastRandomKey or "")~="" then
            local filtered={}
            for _,row in ipairs(candidates) do
                local rid=startup.b472_normalize_rid(row.rid)
                local key=rid~="" and ("rid:"..rid) or ("pid:"..tostring(row.playerId)..":"..tostring(row.name or ""))
                if key~=tostring(rw.b459LastRandomKey or "") then filtered[#filtered+1]=row end
            end
            if #filtered>0 then candidates=filtered end
        end
        local row=candidates[math.random(1,#candidates)]
        row=startup.b472_enrich_target_row(row)
        local rid=startup.b472_normalize_rid(row and row.rid or "")
        rw.b459LastRandomKey=rid~="" and ("rid:"..rid) or ("pid:"..tostring(row and row.playerId or -1)..":"..tostring(row and row.name or ""))
        rw.b459LastRandomName=tostring(row and row.name or "")
        return row
    end

    -- Normalize a player selection immediately so invalid RID sentinel values
    -- cannot make a perfectly live PID/name target look unavailable.
    local previousSetMode=startup.b459_set_bounty_mode
    function startup.b459_set_bounty_mode(newMode,row)
        if tostring(newMode or "none")=="player" and type(row)=="table" then
            row.rid=startup.b472_normalize_rid(row.rid)
        end
        return previousSetMode(newMode,row)
    end

    rw.b455PlayerRowsCache=nil
    rw.b455PlayerRowsCacheMs=0
end
startup.install_live_target_resolver_fix_build472()
startup.install_live_target_resolver_fix_build472=nil

