end


-- ============================================================================
-- BUILD 473: COMPACT REGIONAL WARFARE UI + UNKNOWN TOGGLE
-- - Removes the visible Live IP / Language Roster from Player Classification.
-- - Unknown now has the same checkbox + marker-color row as other languages.
-- - Unknown is an enemy only when explicitly selected under Selected Languages.
-- - Shortens Regional Warfare, Bounty Automation, and Kill Retaliation copy.
-- ============================================================================
function startup.install_compact_warfare_copy_unknown_toggle_build473()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    function startup.b473_combo_index(label,currentIndex,items,maxHeight)
        if not (ImGui and ImGui.Combo) then return currentIndex,false end
        currentIndex=math.max(0,math.min(#items-1,tonumber(currentIndex or 0) or 0))
        if ImGui.SetNextItemWidth then pcall(ImGui.SetNextItemWidth,-1) end
        local ok,a,b=pcall(ImGui.Combo,label,currentIndex,items,#items,tonumber(maxHeight or #items) or #items)
        if not ok then ok,a,b=pcall(ImGui.Combo,label,currentIndex,items) end
        if not ok then return currentIndex,false end
        local idx=nil
        if type(a)=="number" then idx=math.floor(a) elseif type(b)=="number" then idx=math.floor(b) end
        if idx==nil then return currentIndex,false end
        idx=math.max(0,math.min(#items-1,idx))
        return idx,idx~=currentIndex
    end

    -- Unknown is no longer stripped from Selected Languages state.
    rw.b473BaseSanitize=rw.b473BaseSanitize or startup.regional_warfare_sanitize_state
    function startup.regional_warfare_sanitize_state()
        local unknownSelected=type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies.Unknown==true
        if rw.b473BaseSanitize then rw.b473BaseSanitize() end
        startup.s.regionalWarfareSelectedEnemies=type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies or {}
        if unknownSelected then startup.s.regionalWarfareSelectedEnemies.Unknown=true end
    end

    -- Unknown remains conservative under All Other Languages. It becomes an
    -- enemy only when the user explicitly checks it under Selected Languages.
    function startup.regional_warfare_is_enemy_faction(language)
        language=startup.regional_warfare_normalize_language(language)
        local own=startup.regional_warfare_own_language()
        own=startup.regional_warfare_normalize_language(own)
        if own=="Unknown" or language==own then return false end
        if tostring(startup.s.regionalWarfareEnemyPolicy or "All Other Languages")=="Selected Languages" then
            return type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies[language]==true
        end
        if language=="Unknown" then return false end
        return true
    end

    -- Marker gating follows the checkbox directly. This keeps an unchecked
    -- language from remaining colored even when a broader enemy policy is used.
    function startup.b467_language_marker_allowed(language)
        language=startup.regional_warfare_normalize_language and startup.regional_warfare_normalize_language(language) or tostring(language or "Unknown")
        if tostring(startup.s.regionalWarfareEnemyPolicy or "All Other Languages")=="Selected Languages" then
            return type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies[language]==true
        end
        return true
    end

    function startup.b467_render_language_row(language,liveCount)
        local languageLabel=tostring(language or "Unknown")
        local liveSuffix=((tonumber(liveCount or 0) or 0)>0 and ("  ["..tostring(liveCount).." live]") or "")
        local startX,enemyX,colorX,colorWidth=startup.b469_language_columns()

        if ImGui and ImGui.SetCursorPosX then pcall(ImGui.SetCursorPosX,startX) end
        startup.subtle_text(languageLabel..liveSuffix)

        if ImGui and ImGui.SameLine then pcall(ImGui.SameLine,enemyX) end
        local old=type(startup.s.regionalWarfareSelectedEnemies)=="table" and startup.s.regionalWarfareSelectedEnemies[language]==true
        if ImGui and ImGui.Checkbox then
            local new=ImGui.Checkbox("##StartupB473Enemy_"..startup.regional_warfare_feature_key(language),old)
            if new~=old then startup.b467_set_enemy_language(language,new==true) end
        end

        if ImGui and ImGui.SameLine then pcall(ImGui.SameLine,colorX) end
        local changed=startup.b469_color_combo_cell(language,colorWidth)
        if changed then startup.b470_commit_marker_color(language,changed) end
    end

    function startup.b466_render_core_regional_warfare()
        startup.subtle_text("Classify players by IP, with Cherax fallback.")
        startup.render_feature_guarded_325(startup.h.RegionalWarfareEnabled)
        startup.render_feature_guarded_325(startup.h.RegionalWarfareMyFaction)
        startup.render_feature_guarded_325(startup.h.RegionalWarfareEnemyPolicy)
        local own,source="Unknown",""
        if startup.regional_warfare_own_language then
            local ok,a,b=pcall(startup.regional_warfare_own_language)
            if ok then own=tostring(a or "Unknown"); source=tostring(b or "") end
        end
        startup.subtle_text("Detected: "..own..(source~="" and (" • "..source) or ""))
    end

    function startup.b467_render_player_classification_colors()
        startup.subtle_text("Set enemy groups and marker colors.")

        local oldMarkers=startup.s.regionalWarfareColorPlayers~=false
        if ImGui and ImGui.Checkbox then
            local newMarkers=ImGui.Checkbox("Color Player Markers##StartupB473ColorPlayers",oldMarkers)
            if newMarkers~=oldMarkers then
                startup.s.regionalWarfareColorPlayers=newMarkers==true
                rw.lastBlipColorScanMs=0
                if startup.h and startup.h.RegionalWarfareColorPlayers and startup.set_feature_bool_silently then
                    pcall(startup.set_feature_bool_silently,startup.h.RegionalWarfareColorPlayers,newMarkers==true)
                end
                if newMarkers~=true and startup.regional_warfare_restore_blip_colors_449 then pcall(startup.regional_warfare_restore_blip_colors_449) end
                if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
            end
        end

        startup.s.regionalWarfareLanguageColors=type(startup.s.regionalWarfareLanguageColors)=="table" and startup.s.regionalWarfareLanguageColors or {}
        local changed=startup.b464_color_combo and startup.b464_color_combo("Friends Marker","__Friends","Dark Green") or nil
        if changed then startup.b470_commit_marker_color("__Friends",changed) end
        changed=startup.b464_color_combo and startup.b464_color_combo("Tracked Marker","__Tracked","Red") or nil
        if changed then startup.b470_commit_marker_color("__Tracked",changed) end

        if ImGui and ImGui.Separator then ImGui.Separator() end
        local counts={}
        local okRows,rows=pcall(startup.regional_warfare_roster)
        if okRows and type(rows)=="table" then
            for _,row in ipairs(rows) do
                local language=tostring(row.language or "Unknown")
                counts[language]=(counts[language] or 0)+1
            end
        end

        startup.b469_render_language_headers()
        for _,language in ipairs(startup.regional_warfare_languages or {}) do
            if language~="Auto (Player Language)" then startup.b467_render_language_row(language,counts[tostring(language)] or 0) end
        end
    end

    function startup.b473_render_selected_target_compact()
        local rows={}
        local okRows,resultRows=pcall(startup.b471_live_bounty_target_rows)
        if okRows and type(resultRows)=="table" then rows=resultRows end
        local actionMode,actionRow=startup.b471_target_combo(rows)

        local intervalOptions={{label="30 seconds",sec=30},{label="1 minute",sec=60},{label="2 minutes",sec=120},{label="5 minutes",sec=300},{label="10 minutes",sec=600},{label="15 minutes",sec=900},{label="30 minutes",sec=1800},{label="60 minutes",sec=3600}}
        local labels={}
        local currentSec=tonumber(startup.s.regionalWarfareAutoBountyIntervalSec or 300) or 300
        local currentIndex=0
        for i,opt in ipairs(intervalOptions) do labels[i]=opt.label; if opt.sec==currentSec then currentIndex=i-1 end end
        local newIndex,intervalChanged=startup.b473_combo_index("Bounty Interval##StartupB473TargetInterval",currentIndex,labels,#labels)

        local oldAuto=startup.s.regionalWarfareSelectedAutoBountyEnabled==true
        local autoChanged=nil
        if ImGui and ImGui.Checkbox then
            local newAuto=ImGui.Checkbox("Auto-Bounty Selected Target##StartupB473TargetAuto",oldAuto)
            if newAuto~=oldAuto then autoChanged=newAuto==true end
        end
        local manualClicked=ImGui and ImGui.Button and ImGui.Button("Apply Bounty Now##StartupB473TargetNow",-1,30)==true

        if actionMode then
            pcall(startup.b459_set_bounty_mode,actionMode,actionRow)
            rw.b455PlayerRowsCache=nil
            rw.b455PlayerRowsCacheMs=0
            if startup.s.regionalWarfareSelectedAutoBountyEnabled==true and actionMode~="none" then pcall(startup.b455_queue_selected_bounty,"Target changed") end
        end
        if intervalChanged then
            startup.s.regionalWarfareAutoBountyIntervalSec=intervalOptions[newIndex+1].sec
            startup.s.regionalWarfareSelectedAutoBountyIntervalMs=startup.s.regionalWarfareAutoBountyIntervalSec*1000
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end
        if autoChanged~=nil then
            startup.s.regionalWarfareSelectedAutoBountyEnabled=autoChanged==true
            rw.b455SelectedBountyLastMs=0
            if startup.h and startup.h.RegionalWarfareSelectedAutoBounty and startup.set_feature_bool_silently then
                pcall(startup.set_feature_bool_silently,startup.h.RegionalWarfareSelectedAutoBounty,autoChanged==true)
            end
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
            if autoChanged==true then pcall(startup.b455_queue_selected_bounty,"Auto enabled") end
        end
        if manualClicked then pcall(startup.b455_queue_selected_bounty,"Manual") end

    end

    function startup.b473_render_round_robin_compact()
        local options={{label="15 seconds",ms=15000},{label="30 seconds",ms=30000},{label="1 minute",ms=60000},{label="2 minutes",ms=120000},{label="5 minutes",ms=300000},{label="10 minutes",ms=600000}}
        local labels={}
        local current=math.max(15000,math.min(600000,tonumber(startup.s.regionalWarfareBountyGapMs or 60000) or 60000))
        local currentIndex=2
        for i,opt in ipairs(options) do labels[i]=opt.label; if opt.ms==current then currentIndex=i-1 end end
        local newIndex,changed=startup.b473_combo_index("Enemy Queue Spacing##StartupB473QueueSpacing",currentIndex,labels,#labels)
        if changed then
            startup.s.regionalWarfareBountyGapMs=options[newIndex+1].ms
            if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
        end
        local count=type(rw.b460Queue)=="table" and #rw.b460Queue or 0
        local done=math.max(0,(tonumber(rw.b460QueueCursor or 1) or 1)-1)
        if done>count then done=count end
        local nextEntry=type(rw.b460Queue)=="table" and rw.b460Queue[rw.b460QueueCursor] or nil
        startup.subtle_text("Queue: "..tostring(done).."/"..tostring(count).." • Cycle "..tostring(tonumber(rw.b460QueueCycle or 0) or 0))
        if nextEntry then startup.subtle_text("Next: "..tostring(nextEntry.name)) end
    end

    function startup.b467_render_bounty_automation()
        startup.subtle_text("Choose targets, timing, and automatic bounty behavior.")
        startup.render_feature_guarded_325(startup.h.RegionalWarfareAutoBounty)
        startup.b473_render_selected_target_compact()
        if ImGui and ImGui.Separator then ImGui.Separator() end
        startup.b473_render_round_robin_compact()
        startup.render_feature_guarded_325(startup.h.RegionalWarfareBountyNow)
        if tostring(startup.s.regionalWarfareLastBountyPlayer or "")~="" then
            startup.subtle_text("Last: "..tostring(startup.s.regionalWarfareLastBountyPlayer))
        end
    end

    function startup.render_killed_you_retaliation_b465()
        local dirty=false
        startup.subtle_text("Mark and bounty non-friends who repeatedly kill you.")

        local oldEnabled=startup.s.killedYouRetaliationEnabled==true
        if ImGui and ImGui.Checkbox then
            local v=ImGui.Checkbox("Enable Kill Retaliation##StartupB473KillEnabled",oldEnabled)
            if v~=oldEnabled then startup.s.killedYouRetaliationEnabled=v==true; rw.lastBlipColorScanMs=0; dirty=true end
        end

        local rule,currentKey,rules=startup.killed_you_rule_b465()
        local ruleOrder={"once_anytime","two_5m","three_5m","three_10m","five_10m"}
        local ruleLabels={}
        local ruleIndex=0
        for i,key in ipairs(ruleOrder) do
            ruleLabels[i]=tostring(rules[key] and rules[key].label or key)
            if key==currentKey then ruleIndex=i-1 end
        end
        local newRuleIndex,ruleChanged=startup.b473_combo_index("Trigger Rule##StartupB473KillRule",ruleIndex,ruleLabels,#ruleLabels)
        if ruleChanged then startup.s.killedYouRetaliationRule=ruleOrder[newRuleIndex+1]; dirty=true end

        if startup.b464_color_combo then
            local changed=startup.b464_color_combo("Killed You Marker","__KilledYou",tostring(startup.s.killedYouRetaliationColor or "Dark Red"))
            if changed then startup.s.killedYouRetaliationColor=changed; dirty=true end
        end

        local durationKeys={"session","5m","15m","30m"}
        local durationLabels={"Session","5 minutes","15 minutes","30 minutes"}
        local durationKey=tostring(startup.s.killedYouRetaliationMarkDuration or "session")
        local durationIndex=0
        for i,key in ipairs(durationKeys) do if key==durationKey then durationIndex=i-1 end end
        local newDurationIndex,durationChanged=startup.b473_combo_index("Mark Duration##StartupB473KillDuration",durationIndex,durationLabels,#durationLabels)
        if durationChanged then startup.s.killedYouRetaliationMarkDuration=durationKeys[newDurationIndex+1]; dirty=true end

        local oldBounty=startup.s.killedYouRetaliationAutoBounty==true
        if ImGui and ImGui.Checkbox then
            local v=ImGui.Checkbox("Auto-Bounty Killer##StartupB473KillBounty",oldBounty)
            if v~=oldBounty then startup.s.killedYouRetaliationAutoBounty=v==true; dirty=true end
        end
        local oldNotify=startup.s.killedYouRetaliationNotify==true
        if ImGui and ImGui.Checkbox then
            local v=ImGui.Checkbox("Notify On Trigger##StartupB473KillNotify",oldNotify)
            if v~=oldNotify then startup.s.killedYouRetaliationNotify=v==true; dirty=true end
        end

        local activeCount=0
        for _,rec in pairs((startup.killed_you_b465 and startup.killed_you_b465.records) or {}) do
            if startup.killed_you_record_active_b465(rec) then activeCount=activeCount+1 end
        end
        local queue=(startup.killed_you_b465 and startup.killed_you_b465.bountyQueue) or {}
        startup.subtle_text("Friends ignored • Marked: "..tostring(activeCount).." • Queued: "..tostring(#queue))
        if ImGui and ImGui.Button and ImGui.Button("Clear Kill History / Marks##StartupB473KillClear",-1,30)==true then startup.killed_you_clear_b465() end

        if dirty and startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
    end

    -- Keep B467's four-section layout, but shorten the final section label.
    function startup.render_regional_warfare()
        if not (ImGui and ClickGUI) then return end

        local coreOpen=true
        if ImGui.CollapsingHeader then local ok,v=pcall(ImGui.CollapsingHeader,"Regional Warfare##StartupB473Core"); coreOpen=ok and v==true end
        if coreOpen then
            local ok,err=pcall(startup.b466_render_core_regional_warfare)
            if not ok and startup.log then startup.log("[Build 473][CORE_RECOVERED] "..tostring(err)) end
        end

        local classifyOpen=false
        if ImGui.CollapsingHeader then local ok,v=pcall(ImGui.CollapsingHeader,"Player Classification & Colors##StartupB473Classify"); classifyOpen=ok and v==true end
        if classifyOpen then
            local ok,err=pcall(startup.b467_render_player_classification_colors)
            if not ok and startup.log then startup.log("[Build 473][CLASSIFICATION_RECOVERED] "..tostring(err)) end
        end

        local bountyOpen=false
        if ImGui.CollapsingHeader then local ok,v=pcall(ImGui.CollapsingHeader,"Bounty Automation##StartupB473Bounty"); bountyOpen=ok and v==true end
        if bountyOpen then
            local ok,err=pcall(startup.b467_render_bounty_automation)
            if not ok and startup.log then startup.log("[Build 473][BOUNTY_RECOVERED] "..tostring(err)) end
        end

        local retaliationOpen=false
        if ImGui.CollapsingHeader then local ok,v=pcall(ImGui.CollapsingHeader,"Kill Retaliation##StartupB473KilledYou"); retaliationOpen=ok and v==true end
        if retaliationOpen then
            local ok,err=pcall(startup.render_killed_you_retaliation_b465)
            if not ok and startup.log then startup.log("[Build 473][KILL_RETALIATION_RECOVERED] "..tostring(err)) end
        end
    end

    rw.lastBlipColorScanMs=0
    rw.lastScanMs=0
end
startup.install_compact_warfare_copy_unknown_toggle_build473()
startup.install_compact_warfare_copy_unknown_toggle_build473=nil

