if startup.support_log_event_quiet then
    startup.support_log_event_quiet("BUILD473_COMPACT_WARFARE_UNKNOWN_READY","base=B472 live_roster_removed=true unknown_checkbox=true bounty_copy_short=true retaliation_copy_short=true three_columns_preserved=true")
