-- ============================================================================
-- BUILD 474: GLOBAL RELATIONSHIP MARKER OVERRIDES
-- - Adds mutually-exclusive Friends with Everyone and Enemy toggles directly
--   below Kill Retaliation.
-- - Friends with Everyone: every remote player is classified Friend and painted
--   Lime Green. Kill Retaliation treats all remote players as friends/immune.
-- - Enemy: every remote player is classified Enemy and painted Red.
-- - Turning both modes off restores the normal B473 marker/classification stack.
-- ============================================================================
function startup.install_global_relationship_markers_build474()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    if startup.s.friendsWithEveryoneEnabled==nil then startup.s.friendsWithEveryoneEnabled=false end
    if startup.s.enemyEveryoneEnabled==nil then startup.s.enemyEveryoneEnabled=false end
    if startup.s.friendsWithEveryoneEnabled==true and startup.s.enemyEveryoneEnabled==true then
        startup.s.enemyEveryoneEnabled=false
    end

    startup.regional_warfare_color_names=startup.regional_warfare_color_names or {"None"}
    local hasLime=false
    for _,name in ipairs(startup.regional_warfare_color_names) do
        if tostring(name)=="Lime Green" then hasLime=true break end
    end
    if not hasLime then
        local inserted=false
        for i,name in ipairs(startup.regional_warfare_color_names) do
            if tostring(name)=="Green" then
                table.insert(startup.regional_warfare_color_names,i+1,"Lime Green")
                inserted=true
                break
            end
        end
        if not inserted then table.insert(startup.regional_warfare_color_names,"Lime Green") end
    end
    startup.regional_warfare_color_ids=startup.regional_warfare_color_ids or {}
    startup.regional_warfare_color_ids["Lime Green"]=18
    startup.regional_warfare_color_rgb_454=startup.regional_warfare_color_rgb_454 or {}
    startup.regional_warfare_color_rgb_454["Lime Green"]={50,255,50}

    function startup.b474_relationship_mode()
        if startup.s.friendsWithEveryoneEnabled==true then return "friend" end
        if startup.s.enemyEveryoneEnabled==true then return "enemy" end
        return nil
    end

    function startup.b474_relationship_color()
        local mode=startup.b474_relationship_mode()
        if mode=="friend" then return "Lime Green","Friend" end
        if mode=="enemy" then return "Red","Enemy" end
        return nil,nil
    end

    function startup.b474_force_marker_refresh()
        rw.lastBlipColorScanMs=0
        rw.lastScanMs=0
        rw.lastApplied={}
        if rw.b464SocialCache then rw.b464SocialCache.at=0 end
        if startup.regional_warfare_apply_blip_colors_449 then
            pcall(startup.regional_warfare_apply_blip_colors_449,true)
        end
    end

    -- Persist the two global relationship modes without altering older config.
    if rw.b474ConfigWrapped~=true then
        rw.b474ConfigWrapped=true
        rw.b474ExportPre=startup.export_config
        function startup.export_config()
            local data=rw.b474ExportPre and rw.b474ExportPre() or {}
            if type(data)~="table" then data={} end
            data.friendsWithEveryoneEnabled=startup.s.friendsWithEveryoneEnabled==true
            data.enemyEveryoneEnabled=startup.s.enemyEveryoneEnabled==true
            return data
        end
        rw.b474ApplyPre=startup.apply_config
        function startup.apply_config(data)
            local ret=rw.b474ApplyPre and rw.b474ApplyPre(data) or nil
            if type(data)=="table" then
                startup.s.friendsWithEveryoneEnabled=data.friendsWithEveryoneEnabled==true
                startup.s.enemyEveryoneEnabled=data.enemyEveryoneEnabled==true
                if startup.s.friendsWithEveryoneEnabled==true and startup.s.enemyEveryoneEnabled==true then
                    startup.s.enemyEveryoneEnabled=false
                end
            end
            return ret
        end
    end

    -- Highest-priority relationship classification in the normal painter.
    if rw.b474SocialWrapped~=true then
        rw.b474SocialWrapped=true
        rw.b474SocialPre=startup.b464_social_marker_color
        function startup.b464_social_marker_color(playerId,name)
            local color,kind=startup.b474_relationship_color()
            if color then return color,kind end
            if rw.b474SocialPre then return rw.b474SocialPre(playerId,name) end
            return nil,nil
        end
    end

    -- Friends with Everyone truly behaves as friendship for retaliation immunity.
    if rw.b474KilledFriendWrapped~=true then
        rw.b474KilledFriendWrapped=true
        rw.b474KilledFriendPre=startup.killed_you_is_friend_b465
        function startup.killed_you_is_friend_b465(playerId,name)
            if startup.s.friendsWithEveryoneEnabled==true then return true end
            if rw.b474KilledFriendPre then return rw.b474KilledFriendPre(playerId,name) end
            return false
        end
    end

    function startup.b474_reassert_global_relationship_markers()
        local colorName,kind=startup.b474_relationship_color()
        if not colorName then return end
        if startup.s.regionalWarfareColorPlayers==false then return end
        local rgb=startup.regional_warfare_color_rgb_454[colorName]
        if type(rgb)~="table" then return end
        local ids=startup.regional_warfare_player_ids_449 and startup.regional_warfare_player_ids_449() or {}
        for _,playerId in ipairs(ids or {}) do
            playerId=tonumber(playerId)
            if playerId~=nil and not (startup.is_local_player_id and startup.is_local_player_id(playerId)) then
                local blip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0
                if blip~=0 then
                    startup.regional_warfare_set_custom_blip_rgb_454(blip,tonumber(rgb[1]) or 0,tonumber(rgb[2]) or 0,tonumber(rgb[3]) or 0)
                    rw.b461ColorSource=rw.b461ColorSource or {}
                    rw.b461ColorSource[playerId]=rw.b461ColorSource[playerId] or {}
                    rw.b461ColorSource[playerId].social=kind
                    rw.b461ColorSource[playerId].colorName=colorName
                end
            end
        end
    end

    -- Registered last so the global relationship mode wins over Kill Retaliation
    -- and any GTA blip reset during the same render frame.
    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_PRESENT and rw.b474PresentInstalled~=true then
        rw.b474PresentInstalled=true
        EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT,function() startup.b474_reassert_global_relationship_markers() end)
    end
    if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_POST_PRESENT and rw.b474PostPresentInstalled~=true then
        rw.b474PostPresentInstalled=true
        EventMgr.RegisterHandler(eLuaEvent.ON_POST_PRESENT,function() startup.b474_reassert_global_relationship_markers() end)
    end

    function startup.b474_set_relationship_mode(mode,enabled)
        enabled=enabled==true
        if mode=="friend" then
            startup.s.friendsWithEveryoneEnabled=enabled
            if enabled then startup.s.enemyEveryoneEnabled=false end
        elseif mode=="enemy" then
            startup.s.enemyEveryoneEnabled=enabled
            if enabled then startup.s.friendsWithEveryoneEnabled=false end
        end
        startup.b474_force_marker_refresh()
        if startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
    end

    function startup.b474_render_relationship_toggles()
        if not ImGui then return end
        local friendOld=startup.s.friendsWithEveryoneEnabled==true
        if ImGui.Checkbox then
            local friendNew=ImGui.Checkbox("Friends with Everyone##StartupB474FriendsEveryone",friendOld)
            if friendNew~=friendOld then startup.b474_set_relationship_mode("friend",friendNew==true) end
        end
        startup.hover_help("Everyone appears as a lime-green Friend.")

        local enemyOld=startup.s.enemyEveryoneEnabled==true
        if ImGui.Checkbox then
            local enemyNew=ImGui.Checkbox("Enemy##StartupB474EnemyEveryone",enemyOld)
            if enemyNew~=enemyOld then startup.b474_set_relationship_mode("enemy",enemyNew==true) end
        end
        startup.hover_help("Everyone appears as a red Enemy.")
    end

    -- Place the two compact toggles immediately after Kill Retaliation.
    rw.b474RenderPre=startup.render_regional_warfare
    function startup.render_regional_warfare()
        if rw.b474RenderPre then rw.b474RenderPre() end
        if ImGui and ImGui.Separator then pcall(ImGui.Separator) end
        startup.b474_render_relationship_toggles()
    end

    startup.b474_force_marker_refresh()
end
startup.install_global_relationship_markers_build474()
startup.install_global_relationship_markers_build474=nil

