-- ============================================================================
-- BUILD 475: GLOBAL FRIEND / ENEMY BLIP LABELS
-- - Friends with Everyone renames each remote player blip to "Friend".
-- - Enemy renames each remote player blip to "Enemy".
-- - Turning both modes off restores Rockstar's normal player name on the blip.
-- - Label state is tracked per player/blip so we avoid rewriting unchanged names.
-- ============================================================================
function startup.install_global_relationship_blip_labels_build475()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime
    rw.b475LabelState=rw.b475LabelState or {}

    function startup.b475_set_blip_relationship_label(blip,label)
        blip=tonumber(blip or 0) or 0
        label=tostring(label or "")
        if blip==0 or label=="" or not Natives or not Natives.InvokeVoid then return false end
        local ok=pcall(function()
            -- BEGIN_TEXT_COMMAND_SET_BLIP_NAME("STRING")
            Natives.InvokeVoid(0xF9113A30DE5C6670,"STRING")
            -- ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME(label)
            Natives.InvokeVoid(0x6C188BE134E074AA,label)
            -- END_TEXT_COMMAND_SET_BLIP_NAME(blip)
            Natives.InvokeVoid(0xBC38B49BCB83BC9B,blip)
        end)
        return ok==true
    end

    function startup.b475_restore_blip_player_name(blip,playerId)
        blip=tonumber(blip or 0) or 0
        playerId=tonumber(playerId)
        if blip==0 or playerId==nil or not Natives or not Natives.InvokeVoid then return false end
        -- SET_BLIP_NAME_TO_PLAYER_NAME(blip, player)
        return pcall(function() Natives.InvokeVoid(0x127DE7B20C60A6A3,blip,playerId) end)==true
    end

    function startup.b475_relationship_label_mode()
        local mode=startup.b474_relationship_mode and startup.b474_relationship_mode() or nil
        if mode=="friend" then return "Friend","friend" end
        if mode=="enemy" then return "Enemy","enemy" end
        return nil,nil
    end

    function startup.b475_restore_relationship_labels()
        for playerId,state in pairs(rw.b475LabelState or {}) do
            playerId=tonumber(playerId)
            if playerId~=nil and type(state)=="table" then
                local blip=tonumber(state.blip or 0) or 0
                local currentBlip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0
                if currentBlip~=0 then blip=currentBlip end
                if blip~=0 then startup.b475_restore_blip_player_name(blip,playerId) end
            end
        end
        rw.b475LabelState={}
    end

    function startup.b475_reassert_relationship_labels()
        local label,mode=startup.b475_relationship_label_mode()
        if not label then
            if next(rw.b475LabelState or {})~=nil then startup.b475_restore_relationship_labels() end
            return
        end

        local seen={}
        local ids=startup.regional_warfare_player_ids_449 and startup.regional_warfare_player_ids_449() or {}
        for _,playerId in ipairs(ids or {}) do
            playerId=tonumber(playerId)
            if playerId~=nil and not (startup.is_local_player_id and startup.is_local_player_id(playerId)) then
                seen[playerId]=true
                local blip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0
                if blip~=0 then
                    local old=rw.b475LabelState[playerId]
                    if type(old)~="table" or tonumber(old.blip or 0)~=blip or tostring(old.mode or "")~=mode then
                        if startup.b475_set_blip_relationship_label(blip,label) then
                            rw.b475LabelState[playerId]={blip=blip,mode=mode,label=label}
                        end
                    end
                end
            end
        end

        -- Restore stale entries when a player leaves or their blip is replaced.
        for playerId,state in pairs(rw.b475LabelState or {}) do
            if not seen[tonumber(playerId)] then
                rw.b475LabelState[playerId]=nil
            elseif type(state)=="table" then
                local currentBlip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(tonumber(playerId)) or 0) or 0
                if currentBlip~=0 and tonumber(state.blip or 0)~=currentBlip then
                    startup.b475_set_blip_relationship_label(currentBlip,label)
                    rw.b475LabelState[playerId]={blip=currentBlip,mode=mode,label=label}
                end
            end
        end
    end

    -- B474's present handlers call this function dynamically. Wrap it so label
    -- updates follow the same highest-priority relationship marker pass.
    if rw.b475ReassertWrapped~=true then
        rw.b475ReassertWrapped=true
        rw.b475ReassertPre=startup.b474_reassert_global_relationship_markers
        function startup.b474_reassert_global_relationship_markers()
            if rw.b475ReassertPre then rw.b475ReassertPre() end
            startup.b475_reassert_relationship_labels()
        end
    end

    -- Restore actual names immediately when the mode is disabled, and update the
    -- label immediately when switching Friend <-> Enemy.
    if rw.b475ModeWrapped~=true then
        rw.b475ModeWrapped=true
        rw.b475ModePre=startup.b474_set_relationship_mode
        function startup.b474_set_relationship_mode(mode,enabled)
            local ret=rw.b475ModePre and rw.b475ModePre(mode,enabled) or nil
            if startup.b474_relationship_mode and startup.b474_relationship_mode() then
                startup.b475_reassert_relationship_labels()
            else
                startup.b475_restore_relationship_labels()
            end
            return ret
        end
    end

    -- Apply the label immediately if a global mode was loaded from config.
    startup.b475_reassert_relationship_labels()
end
startup.install_global_relationship_blip_labels_build475()
startup.install_global_relationship_blip_labels_build475=nil

