-- ============================================================================
-- BUILD 476: B453-STYLE SEMANTIC FRIEND / ENEMY PLAYER BLIPS
-- - Replaces B475's literal custom blip-name rewrite with the same stock-color
--   technique that produced GTA's Friend-blue player treatment in Build 453.
-- - Friend mode uses stock blip color 3 (blue / friend-style player treatment).
-- - Enemy mode uses stock blip color 1 (red / enemy-style player treatment).
-- - Reasserted by B474's already-registered ON_PRESENT + ON_POST_PRESENT hooks,
--   preserving B453's persistent-write behavior without touching neutral mode.
-- - When both global modes are OFF, the normal B454+ custom RGB/social/IP painter
--   remains authoritative again on the next render pass.
-- ============================================================================
function startup.install_b453_style_relationship_blips_build476()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime

    rw.b476FriendStockColor=3
    rw.b476EnemyStockColor=1

    -- Remove any literal Friend/Enemy names that B475 may already have applied
    -- before this installer reached the end of the file.
    if startup.b475_restore_relationship_labels then
        pcall(startup.b475_restore_relationship_labels)
    end
    rw.b475LabelState={}

    function startup.b476_relationship_stock_state()
        local mode=startup.b474_relationship_mode and startup.b474_relationship_mode() or nil
        if mode=="friend" then return tonumber(rw.b476FriendStockColor) or 3,"Friend","Blue" end
        if mode=="enemy" then return tonumber(rw.b476EnemyStockColor) or 1,"Enemy","Red" end
        return nil,nil,nil
    end

    -- Keep internal social status aligned with the visible B453-style result.
    function startup.b474_relationship_color()
        local _,kind,colorName=startup.b476_relationship_stock_state()
        if kind then return colorName,kind end
        return nil,nil
    end

    function startup.b476_reassert_relationship_stock_blips()
        local stockColor,kind,colorName=startup.b476_relationship_stock_state()
        if stockColor==nil then return end
        if startup.s.regionalWarfareColorPlayers==false then return end
        if not (Natives and Natives.InvokeVoid) then return end

        local ids=startup.regional_warfare_player_ids_449 and startup.regional_warfare_player_ids_449() or {}
        for _,playerId in ipairs(ids or {}) do
            playerId=tonumber(playerId)
            if playerId~=nil and not (startup.is_local_player_id and startup.is_local_player_id(playerId)) then
                local blip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0
                if blip~=0 then
                    -- Exact B453-style persistence primitive: SET_BLIP_COLOUR.
                    -- Stock indices intentionally retain GTA's semantic player-blip
                    -- treatment instead of switching to custom RGB color 84.
                    Natives.InvokeVoid(0x03D7FB09E75D6B7E,blip,stockColor)

                    rw.b461ColorSource=rw.b461ColorSource or {}
                    rw.b461ColorSource[playerId]=rw.b461ColorSource[playerId] or {}
                    rw.b461ColorSource[playerId].social=kind
                    rw.b461ColorSource[playerId].colorName=colorName
                    rw.b461ColorSource[playerId].source="B453 stock semantic"
                end
            end
        end
    end

    -- B474 already registered these callbacks after B453/B454. Replacing the
    -- dynamic function makes this stock semantic write the final player-blip
    -- operation on both ON_PRESENT and ON_POST_PRESENT.
    function startup.b474_reassert_global_relationship_markers()
        startup.b476_reassert_relationship_stock_blips()
    end

    -- B475's mode wrapper calls these dynamically. Redirect the old custom text
    -- path to the stock semantic painter and never rewrite player names again.
    function startup.b475_reassert_relationship_labels()
        startup.b476_reassert_relationship_stock_blips()
    end
    function startup.b475_restore_relationship_labels()
        rw.b475LabelState={}
        if startup.b474_force_marker_refresh then startup.b474_force_marker_refresh() end
    end

    -- Keep the compact toggle copy accurate: Friend is now GTA stock blue,
    -- matching the B453 behavior the user selected.
    function startup.b474_render_relationship_toggles()
        if not ImGui then return end
        local friendOld=startup.s.friendsWithEveryoneEnabled==true
        if ImGui.Checkbox then
            local friendNew=ImGui.Checkbox("Friends with Everyone##StartupB476FriendsEveryone",friendOld)
            if friendNew~=friendOld then startup.b474_set_relationship_mode("friend",friendNew==true) end
        end
        startup.hover_help("Everyone appears as a blue GTA Friend.")

        local enemyOld=startup.s.enemyEveryoneEnabled==true
        if ImGui.Checkbox then
            local enemyNew=ImGui.Checkbox("Enemy##StartupB476EnemyEveryone",enemyOld)
            if enemyNew~=enemyOld then startup.b474_set_relationship_mode("enemy",enemyNew==true) end
        end
        startup.hover_help("Everyone appears as a red GTA Enemy.")
    end

    -- Apply immediately when a saved global mode is already active.
    startup.b476_reassert_relationship_stock_blips()
end
startup.install_b453_style_relationship_blips_build476()
startup.install_b453_style_relationship_blips_build476=nil

