-- ============================================================================
-- BUILD 477: ENEMY BLIP LABEL FIX
-- - Preserve the user-confirmed B476 blue Friend behavior unchanged.
-- - Enemy keeps the B453-style persistent stock-red marker, but also receives
--   an explicit "Enemy" blip label because GTA does not expose the same visible
--   relationship label from stock red alone on these player blips.
-- - Switching to Friend or disabling both global relationship modes restores
--   the real player names before the normal marker stack resumes.
-- ============================================================================
function startup.install_enemy_blip_label_fix_build477()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime
    rw.b477EnemyLabelState=rw.b477EnemyLabelState or {}

    function startup.b477_restore_enemy_labels()
        if next(rw.b477EnemyLabelState or {})==nil then return end
        for playerId,state in pairs(rw.b477EnemyLabelState or {}) do
            playerId=tonumber(playerId)
            if playerId~=nil then
                local blip=type(state)=="table" and (tonumber(state.blip or 0) or 0) or 0
                local currentBlip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0
                if currentBlip~=0 then blip=currentBlip end
                if blip~=0 and startup.b475_restore_blip_player_name then
                    pcall(startup.b475_restore_blip_player_name,blip,playerId)
                end
            end
        end
        rw.b477EnemyLabelState={}
    end

    function startup.b477_reassert_enemy_labels()
        local mode=startup.b474_relationship_mode and startup.b474_relationship_mode() or nil
        if mode~="enemy" then
            startup.b477_restore_enemy_labels()
            return
        end

        local seen={}
        local ids=startup.regional_warfare_player_ids_449 and startup.regional_warfare_player_ids_449() or {}
        for _,playerId in ipairs(ids or {}) do
            playerId=tonumber(playerId)
            if playerId~=nil and not (startup.is_local_player_id and startup.is_local_player_id(playerId)) then
                seen[playerId]=true
                local blip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0
                if blip~=0 then
                    local old=rw.b477EnemyLabelState[playerId]
                    if type(old)~="table" or tonumber(old.blip or 0)~=blip then
                        if startup.b475_set_blip_relationship_label and pcall(startup.b475_set_blip_relationship_label,blip,"Enemy") then
                            rw.b477EnemyLabelState[playerId]={blip=blip}
                        end
                    end
                end
            end
        end

        for playerId,state in pairs(rw.b477EnemyLabelState or {}) do
            local pid=tonumber(playerId)
            if pid==nil or not seen[pid] then
                rw.b477EnemyLabelState[playerId]=nil
            elseif type(state)=="table" then
                local currentBlip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(pid) or 0) or 0
                if currentBlip~=0 and tonumber(state.blip or 0)~=currentBlip then
                    if startup.b475_set_blip_relationship_label then
                        pcall(startup.b475_set_blip_relationship_label,currentBlip,"Enemy")
                    end
                    rw.b477EnemyLabelState[playerId]={blip=currentBlip}
                end
            end
        end
    end

    function startup.b477_reassert_relationship_blips()
        local mode=startup.b474_relationship_mode and startup.b474_relationship_mode() or nil
        if mode=="friend" then
            -- Remove any explicit Enemy names first; B476's confirmed stock-blue
            -- Friend behavior remains responsible for the visible Friend state.
            startup.b477_restore_enemy_labels()
            if startup.b476_reassert_relationship_stock_blips then
                startup.b476_reassert_relationship_stock_blips()
            end
            return
        end
        if mode=="enemy" then
            if startup.b476_reassert_relationship_stock_blips then
                startup.b476_reassert_relationship_stock_blips()
            end
            startup.b477_reassert_enemy_labels()
            return
        end

        startup.b477_restore_enemy_labels()
    end

    -- B474's already-registered ON_PRESENT and ON_POST_PRESENT handlers resolve
    -- this function dynamically, so the B477 combined pass remains last.
    function startup.b474_reassert_global_relationship_markers()
        startup.b477_reassert_relationship_blips()
    end

    -- B475's mode wrapper also calls these dynamically. Keep its switch/off
    -- behavior aligned with the B477 hybrid Friend/Enemy implementation.
    function startup.b475_reassert_relationship_labels()
        startup.b477_reassert_relationship_blips()
    end
    function startup.b475_restore_relationship_labels()
        startup.b477_restore_enemy_labels()
        rw.b475LabelState={}
        if startup.b474_force_marker_refresh then startup.b474_force_marker_refresh() end
    end

    -- Apply immediately when Enemy was restored from config.
    startup.b477_reassert_relationship_blips()
end
