-- ============================================================================
-- BUILD 478: PERSISTENT ENEMY SEMANTIC LABEL
-- - B477 only wrote the literal Enemy blip name when a blip was first seen or
--   replaced. GTA Online can restore the player name after that write, leaving
--   the red marker but losing the Enemy label.
-- - Keep the user-confirmed Friend path unchanged.
-- - Enemy now uses GTA's dedicated HUD_COLOUR_ENEMY (119), explicitly clears
--   friendly state, and reasserts the literal Enemy name on every relationship
--   render pass instead of trusting a one-time cached write.
-- ============================================================================
function startup.install_persistent_enemy_semantic_label_build478()
    startup.regional_warfare_runtime=startup.regional_warfare_runtime or {}
    local rw=startup.regional_warfare_runtime
    rw.b478EnemyHudColor=119 -- HUD_COLOUR_ENEMY from GTA's HUD colour enum.

    -- Preserve the confirmed Friend result exactly. Only the Enemy stock colour
    -- changes to GTA's dedicated semantic enemy HUD colour.
    function startup.b476_relationship_stock_state()
        local mode=startup.b474_relationship_mode and startup.b474_relationship_mode() or nil
        if mode=="friend" then return tonumber(rw.b476FriendStockColor) or 3,"Friend","Blue" end
        if mode=="enemy" then return tonumber(rw.b478EnemyHudColor) or 119,"Enemy","Red" end
        return nil,nil,nil
    end

    -- Reassert the semantic enemy state together with the stock colour. Friend
    -- deliberately remains on the already-confirmed B476/B453-style path.
    function startup.b476_reassert_relationship_stock_blips()
        local stockColor,kind,colorName=startup.b476_relationship_stock_state()
        if stockColor==nil then return end
        if startup.s.regionalWarfareColorPlayers==false then return end
        if not (Natives and Natives.InvokeVoid) then return end

        local mode=startup.b474_relationship_mode and startup.b474_relationship_mode() or nil
        local ids=startup.regional_warfare_player_ids_449 and startup.regional_warfare_player_ids_449() or {}
        for _,playerId in ipairs(ids or {}) do
            playerId=tonumber(playerId)
            if playerId~=nil and not (startup.is_local_player_id and startup.is_local_player_id(playerId)) then
                local blip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0
                if blip~=0 then
                    if mode=="enemy" then
                        -- SET_BLIP_AS_FRIENDLY(blip, false): force the GTA enemy
                        -- relationship state rather than relying on red colour alone.
                        pcall(function() Natives.InvokeVoid(0x6F6F290102C02AB4,blip,false) end)
                        -- Remove the friend half-circle if GTA carried it over from
                        -- a previous Friend mode before painting the Enemy state.
                        pcall(function() Natives.InvokeVoid(0x23C3EB807312F01A,blip,false) end)
                    end

                    -- B453 persistence primitive, now using HUD_COLOUR_ENEMY=119
                    -- for Enemy. Friend retains its confirmed stock colour value.
                    pcall(function() Natives.InvokeVoid(0x03D7FB09E75D6B7E,blip,stockColor) end)

                    rw.b461ColorSource=rw.b461ColorSource or {}
                    rw.b461ColorSource[playerId]=rw.b461ColorSource[playerId] or {}
                    rw.b461ColorSource[playerId].social=kind
                    rw.b461ColorSource[playerId].colorName=colorName
                    rw.b461ColorSource[playerId].source=mode=="enemy" and "B478 HUD_COLOUR_ENEMY" or "B453 stock semantic"
                end
            end
        end
    end

    -- Do not cache a successful Enemy-name write. GTA may replace the player-blip
    -- name after our previous frame, so the label must be asserted again whenever
    -- the global relationship marker pass runs.
    function startup.b477_reassert_enemy_labels()
        local mode=startup.b474_relationship_mode and startup.b474_relationship_mode() or nil
        if mode~="enemy" then
            if startup.b477_restore_enemy_labels then startup.b477_restore_enemy_labels() end
            return
        end

        local seen={}
        local ids=startup.regional_warfare_player_ids_449 and startup.regional_warfare_player_ids_449() or {}
        for _,playerId in ipairs(ids or {}) do
            playerId=tonumber(playerId)
            if playerId~=nil and not (startup.is_local_player_id and startup.is_local_player_id(playerId)) then
                seen[playerId]=true
                local blip=startup.regional_warfare_player_blip_449 and tonumber(startup.regional_warfare_player_blip_449(playerId) or 0) or 0
                if blip~=0 then
                    -- Reassert the literal label every relationship pass. B477's
                    -- one-time cache is retained only for restore bookkeeping.
                    if startup.b475_set_blip_relationship_label then
                        pcall(startup.b475_set_blip_relationship_label,blip,"Enemy")
                    end
                    rw.b477EnemyLabelState[playerId]={blip=blip}
                end
            end
        end

        for playerId,_ in pairs(rw.b477EnemyLabelState or {}) do
            local pid=tonumber(playerId)
            if pid==nil or not seen[pid] then rw.b477EnemyLabelState[playerId]=nil end
        end
    end

    -- Keep the existing dynamic present/post-present dispatch, but guarantee the
    -- semantic state is applied before the persistent text label every pass.
    function startup.b477_reassert_relationship_blips()
        local mode=startup.b474_relationship_mode and startup.b474_relationship_mode() or nil
        if mode=="friend" then
            if startup.b477_restore_enemy_labels then startup.b477_restore_enemy_labels() end
            startup.b476_reassert_relationship_stock_blips()
            return
        end
        if mode=="enemy" then
            startup.b476_reassert_relationship_stock_blips()
            startup.b477_reassert_enemy_labels()
            return
        end
        if startup.b477_restore_enemy_labels then startup.b477_restore_enemy_labels() end
    end

    function startup.b474_reassert_global_relationship_markers()
        startup.b477_reassert_relationship_blips()
    end
    function startup.b475_reassert_relationship_labels()
        startup.b477_reassert_relationship_blips()
    end

    startup.b477_reassert_relationship_blips()
end
startup.install_persistent_enemy_semantic_label_build478()
startup.install_persistent_enemy_semantic_label_build478=nil

