-- ============================================================================
-- BUILD 479: KILL RETALIATION AUTO-BOUNTY DELAY
-- - Adds a persisted delay dropdown directly below Auto-Bounty Killer.
-- - Choices: Instant, 10 Seconds, 30 Seconds, 1 Minute, 3 Minutes,
--   5 Minutes, and 10 Minutes. Default: 1 Minute.
-- - Delayed targets remain in the queue until due, so Clear Kill History / Marks
--   and disabling Auto-Bounty can cancel pending retaliation bounties cleanly.
-- - Revalidates the live player / RID / friend immunity immediately before the
--   existing built-in 9k bounty path runs.
-- ============================================================================
function startup.install_kill_retaliation_bounty_delay_build479()
    startup.killed_you_b465=startup.killed_you_b465 or {}
    local R=startup.killed_you_b465
    local rw=startup.regional_warfare_runtime or {}
    startup.regional_warfare_runtime=rw

    local delayKeys={"instant","10s","30s","60s","180s","300s","600s"}
    local delayLabels={"Instant","10 Seconds","30 Seconds","1 Minute","3 Minutes","5 Minutes","10 Minutes"}
    local delayMs={instant=0,["10s"]=10000,["30s"]=30000,["60s"]=60000,["180s"]=180000,["300s"]=300000,["600s"]=600000}
    local validDelay={}
    for _,key in ipairs(delayKeys) do validDelay[key]=true end

    -- Because Startup's initial config load occurs before this late production
    -- patch is installed, hydrate this one new field directly once at install.
    local persistedDelay=nil
    if startup.load_table and startup.config_file then
        local ok,data=pcall(startup.load_table,startup.config_file)
        if ok and type(data)=="table" then
            local candidate=tostring(data.killedYouRetaliationBountyDelay or "")
            if validDelay[candidate] then persistedDelay=candidate end
        end
    end
    local currentDelay=tostring(persistedDelay or startup.s.killedYouRetaliationBountyDelay or "60s")
    if not validDelay[currentDelay] then currentDelay="60s" end
    startup.s.killedYouRetaliationBountyDelay=currentDelay

    R.bountyWorkerToken=tonumber(R.bountyWorkerToken or 0) or 0

    function startup.killed_you_bounty_delay_key_b479()
        local key=tostring(startup.s.killedYouRetaliationBountyDelay or "60s")
        if not validDelay[key] then key="60s"; startup.s.killedYouRetaliationBountyDelay=key end
        return key
    end

    function startup.killed_you_bounty_delay_ms_b479()
        return tonumber(delayMs[startup.killed_you_bounty_delay_key_b479()] or 60000) or 60000
    end

    function startup.killed_you_bounty_delay_label_b479()
        local key=startup.killed_you_bounty_delay_key_b479()
        for i,k in ipairs(delayKeys) do if k==key then return delayLabels[i] end end
        return "1 Minute"
    end

    function startup.killed_you_cancel_bounty_queue_b479(reason)
        R.bountyWorkerToken=(tonumber(R.bountyWorkerToken or 0) or 0)+1
        R.bountyQueue={}
        R.bountyInFlight=false
        if reason and tostring(reason)~="" then
            startup.s.killedYouRetaliationLastStatus=tostring(reason)
        end
    end

    -- Persist only the new field without disturbing the existing config chain.
    if R.b479ConfigWrapped~=true then
        R.b479ConfigWrapped=true
        R.b479ExportPre=startup.export_config
        function startup.export_config()
            local data=R.b479ExportPre and R.b479ExportPre() or {}
            if type(data)~="table" then data={} end
            data.killedYouRetaliationBountyDelay=startup.killed_you_bounty_delay_key_b479()
            return data
        end

        R.b479ApplyPre=startup.apply_config
        function startup.apply_config(data)
            local ret=R.b479ApplyPre and R.b479ApplyPre(data) or nil
            if type(data)=="table" then
                local candidate=tostring(data.killedYouRetaliationBountyDelay or startup.s.killedYouRetaliationBountyDelay or "60s")
                if validDelay[candidate] then startup.s.killedYouRetaliationBountyDelay=candidate end
            end
            return ret
        end
    end

    -- Delayed queue worker. The item stays at queue[1] while waiting, which
    -- makes clear/disable cancellation observable to the worker before payout.
    function startup.killed_you_process_bounty_queue_b465()
        if R.bountyInFlight==true or #R.bountyQueue==0 then return end
        if not (Script and Script.QueueJob) then
            startup.s.killedYouRetaliationLastStatus="Bounty queue unavailable: Script.QueueJob missing."
            return
        end

        R.bountyInFlight=true
        R.bountyWorkerToken=(tonumber(R.bountyWorkerToken or 0) or 0)+1
        local token=R.bountyWorkerToken

        Script.QueueJob(function()
            local item=R.bountyQueue[1]
            if type(item)~="table" then
                if R.bountyWorkerToken==token then R.bountyInFlight=false end
                return
            end

            while R.bountyWorkerToken==token do
                if R.bountyQueue[1]~=item then
                    if R.bountyWorkerToken==token then
                        R.bountyInFlight=false
                        if #R.bountyQueue>0 then startup.killed_you_process_bounty_queue_b465() end
                    end
                    return
                end
                if startup.s.killedYouRetaliationAutoBounty~=true then
                    startup.killed_you_cancel_bounty_queue_b479("Pending retaliation bounty cancelled • Auto-Bounty Killer is off.")
                    return
                end

                local now=startup.killed_you_now_b465()
                local dueAt=tonumber(item.dueAtMs or item.queuedAtMs or now) or now
                if now>=dueAt then break end
                local remain=math.max(1,dueAt-now)
                Script.Yield(math.min(250,remain))
            end

            if R.bountyWorkerToken~=token or R.bountyQueue[1]~=item then return end
            table.remove(R.bountyQueue,1)

            local live,why=startup.killed_you_validate_live_target_b465(item)
            if live then
                local okCall,okBounty,status=pcall(startup.b455_apply_selected_bounty_exact,live.playerId)
                if okCall and okBounty==true then
                    startup.s.killedYouRetaliationLastStatus="Retaliation bounty applied to "..tostring(live.name).." • built-in 9k."
                    local rec=startup.killed_you_record_for_player_b465(live.playerId,live.name,false)
                    if rec then rec.lastBountyMs=startup.killed_you_now_b465() end
                    if startup.support_log_event_quiet then
                        pcall(startup.support_log_event_quiet,"BUILD479_KILLED_YOU_BOUNTY_DELAYED","player="..tostring(live.name).." pid="..tostring(live.playerId).." rid="..tostring(live.rid).." delay="..tostring(item.delayKey or "60s").." status="..tostring(status))
                    end
                else
                    startup.s.killedYouRetaliationLastStatus="Retaliation bounty failed for "..tostring(live.name).." • "..tostring(okCall and status or okBounty)
                end
            else
                startup.s.killedYouRetaliationLastStatus="Retaliation bounty skipped • "..tostring(why)
            end

            if R.bountyWorkerToken==token then
                R.bountyInFlight=false
                if #R.bountyQueue>0 then startup.killed_you_process_bounty_queue_b465() end
            end
        end)
    end

    function startup.killed_you_queue_bounty_b465(playerId,name,rid)
        if startup.s.killedYouRetaliationAutoBounty~=true then return false end
        if startup.killed_you_is_friend_b465(playerId,name) then return false end
        for _,q in ipairs(R.bountyQueue) do
            if tostring(rid or "")~="" and tostring(q.rid or "")==tostring(rid) then return false end
            if tostring(rid or "")=="" and tonumber(q.playerId)==tonumber(playerId) then return false end
        end

        local now=startup.killed_you_now_b465()
        local key=startup.killed_you_bounty_delay_key_b479()
        local waitMs=startup.killed_you_bounty_delay_ms_b479()
        R.bountyQueue[#R.bountyQueue+1]={
            playerId=tonumber(playerId),
            name=tostring(name or ""),
            rid=tostring(rid or ""),
            queuedAtMs=now,
            dueAtMs=now+waitMs,
            delayKey=key,
        }
        startup.killed_you_process_bounty_queue_b465()
        return true
    end

    -- Ensure the existing clear action also cancels a delayed worker that may be
    -- sleeping inside Script.Yield when the user presses Clear.
    if R.b479ClearWrapped~=true then
        R.b479ClearWrapped=true
        R.b479ClearPre=startup.killed_you_clear_b465
        function startup.killed_you_clear_b465()
            R.bountyWorkerToken=(tonumber(R.bountyWorkerToken or 0) or 0)+1
            R.bountyInFlight=false
            return R.b479ClearPre and R.b479ClearPre() or nil
        end
    end

    -- B473 compact renderer retained, with the requested delay dropdown placed
    -- immediately beneath Auto-Bounty Killer.
    function startup.render_killed_you_retaliation_b465()
        local dirty=false
        startup.subtle_text("Mark and bounty non-friends who repeatedly kill you.")

        local oldEnabled=startup.s.killedYouRetaliationEnabled==true
        if ImGui and ImGui.Checkbox then
            local v=ImGui.Checkbox("Enable Kill Retaliation##StartupB473KillEnabled",oldEnabled)
            if v~=oldEnabled then startup.s.killedYouRetaliationEnabled=v==true; rw.lastBlipColorScanMs=0; dirty=true end
        end

        local rule,currentKey,rules=startup.killed_you_rule_b465()
        local ruleOrder={"once_anytime","two_5m","three_5m","three_10m","five_10m"}
        local ruleLabels={}
        local ruleIndex=0
        for i,key in ipairs(ruleOrder) do
            ruleLabels[i]=tostring(rules[key] and rules[key].label or key)
            if key==currentKey then ruleIndex=i-1 end
        end
        local newRuleIndex,ruleChanged=startup.b473_combo_index("Trigger Rule##StartupB473KillRule",ruleIndex,ruleLabels,#ruleLabels)
        if ruleChanged then startup.s.killedYouRetaliationRule=ruleOrder[newRuleIndex+1]; dirty=true end

        if startup.b464_color_combo then
            local changed=startup.b464_color_combo("Killed You Marker","__KilledYou",tostring(startup.s.killedYouRetaliationColor or "Dark Red"))
            if changed then startup.s.killedYouRetaliationColor=changed; dirty=true end
        end

        local durationKeys={"session","5m","15m","30m"}
        local durationLabels={"Session","5 minutes","15 minutes","30 minutes"}
        local durationKey=tostring(startup.s.killedYouRetaliationMarkDuration or "session")
        local durationIndex=0
        for i,key in ipairs(durationKeys) do if key==durationKey then durationIndex=i-1 end end
        local newDurationIndex,durationChanged=startup.b473_combo_index("Mark Duration##StartupB473KillDuration",durationIndex,durationLabels,#durationLabels)
        if durationChanged then startup.s.killedYouRetaliationMarkDuration=durationKeys[newDurationIndex+1]; dirty=true end

        local oldBounty=startup.s.killedYouRetaliationAutoBounty==true
        if ImGui and ImGui.Checkbox then
            local v=ImGui.Checkbox("Auto-Bounty Killer##StartupB473KillBounty",oldBounty)
            if v~=oldBounty then
                startup.s.killedYouRetaliationAutoBounty=v==true
                if v~=true and #R.bountyQueue>0 then startup.killed_you_cancel_bounty_queue_b479("Pending retaliation bounties cancelled • Auto-Bounty Killer is off.") end
                dirty=true
                -- Build 481: persist this safety-sensitive toggle immediately.
                -- The final dirty save below is retained for the rest of the panel.
                if startup.save_config then pcall(startup.save_config,false) end
            end
        end

        local delayKey=startup.killed_you_bounty_delay_key_b479()
        local delayIndex=0
        for i,key in ipairs(delayKeys) do if key==delayKey then delayIndex=i-1 end end
        local newDelayIndex,delayChanged=startup.b473_combo_index("Bounty Delay##StartupB479KillBountyDelay",delayIndex,delayLabels,#delayLabels)
        if delayChanged then
            local newKey=delayKeys[newDelayIndex+1] or "60s"
            startup.s.killedYouRetaliationBountyDelay=newKey
            local now=startup.killed_you_now_b465()
            local newWait=tonumber(delayMs[newKey] or 60000) or 60000
            for _,item in ipairs(R.bountyQueue) do
                if type(item)=="table" then
                    item.queuedAtMs=tonumber(item.queuedAtMs or now) or now
                    item.delayKey=newKey
                    item.dueAtMs=item.queuedAtMs+newWait
                end
            end
            dirty=true
        end
        if startup.hover_help then startup.hover_help("Delay after retaliation triggers before Startup applies the automatic built-in 9k bounty. Default: 1 Minute.") end

        local oldNotify=startup.s.killedYouRetaliationNotify==true
        if ImGui and ImGui.Checkbox then
            local v=ImGui.Checkbox("Notify On Trigger##StartupB473KillNotify",oldNotify)
            if v~=oldNotify then startup.s.killedYouRetaliationNotify=v==true; dirty=true end
        end

        local activeCount=0
        for _,rec in pairs((startup.killed_you_b465 and startup.killed_you_b465.records) or {}) do
            if startup.killed_you_record_active_b465(rec) then activeCount=activeCount+1 end
        end
        local queue=R.bountyQueue or {}
        startup.subtle_text("Friends ignored • Marked: "..tostring(activeCount).." • Queued: "..tostring(#queue).." • Delay: "..startup.killed_you_bounty_delay_label_b479())
        if ImGui and ImGui.Button and ImGui.Button("Clear Kill History / Marks##StartupB473KillClear",-1,30)==true then startup.killed_you_clear_b465() end

        if dirty and startup.s.initialized and startup.save_config then pcall(startup.save_config,false) end
    end
end
startup.install_kill_retaliation_bounty_delay_build479()
startup.install_kill_retaliation_bounty_delay_build479=nil

