-- ============================================================================
-- BUILD 480: SAFE KILL RETALIATION DEFAULTS + PERSISTENCE
-- - Kill Retaliation remains enabled by default so marking/history still works.
-- - Auto-Bounty Killer now defaults OFF and requires explicit user opt-in.
-- - The B479 bounty delay remains 1 Minute by default whenever Auto-Bounty is used.
-- - Persists the Kill Retaliation controls that already call save_config so the
--   user's choices survive Startup restarts instead of silently resetting.
-- ============================================================================
function startup.install_kill_retaliation_safe_defaults_build480()
    startup.killed_you_b465=startup.killed_you_b465 or {}
    local R=startup.killed_you_b465

    local validRules={once_anytime=true,two_5m=true,three_5m=true,three_10m=true,five_10m=true}
    local validDurations={session=true,["5m"]=true,["15m"]=true,["30m"]=true}

    -- B465 is intentionally default-on for the retaliation/marker system.
    if startup.s.killedYouRetaliationEnabled==nil then startup.s.killedYouRetaliationEnabled=true end
    -- Safety default: never spend an automatic retaliation bounty until the user
    -- has explicitly enabled Auto-Bounty Killer.
    if startup.s.killedYouRetaliationAutoBounty==nil then startup.s.killedYouRetaliationAutoBounty=false end

    -- Startup's main config load happens before this late production patch, so
    -- hydrate these fields directly once here. Older configs simply lack them and
    -- therefore receive the safe defaults above.
    if startup.load_table and startup.config_file then
        local ok,data=pcall(startup.load_table,startup.config_file)
        if ok and type(data)=="table" then
            if data.killedYouRetaliationEnabled~=nil then
                startup.s.killedYouRetaliationEnabled=data.killedYouRetaliationEnabled==true
            end
            if data.killedYouRetaliationAutoBounty~=nil then
                startup.s.killedYouRetaliationAutoBounty=data.killedYouRetaliationAutoBounty==true
            else
                startup.s.killedYouRetaliationAutoBounty=false
            end

            local rule=tostring(data.killedYouRetaliationRule or "")
            if validRules[rule] then startup.s.killedYouRetaliationRule=rule end

            local color=tostring(data.killedYouRetaliationColor or "")
            if color~="" then startup.s.killedYouRetaliationColor=color end

            if data.killedYouRetaliationNotify~=nil then
                startup.s.killedYouRetaliationNotify=data.killedYouRetaliationNotify==true
            end

            local duration=tostring(data.killedYouRetaliationMarkDuration or "")
            if validDurations[duration] then startup.s.killedYouRetaliationMarkDuration=duration end
        else
            startup.s.killedYouRetaliationAutoBounty=false
        end
    end

    -- If this is an upgrade from B479 with no saved Auto-Bounty preference, make
    -- sure no already-created queue can survive the new opt-in default.
    if startup.s.killedYouRetaliationAutoBounty~=true and #((R and R.bountyQueue) or {})>0 then
        if startup.killed_you_cancel_bounty_queue_b479 then
            startup.killed_you_cancel_bounty_queue_b479("Pending retaliation bounties cancelled • Auto-Bounty Killer defaults OFF in Build 480.")
        else
            R.bountyQueue={}
            R.bountyInFlight=false
        end
    end

    -- Extend the existing config chain with the retaliation controls. B479 keeps
    -- ownership of killedYouRetaliationBountyDelay, so this wrapper does not
    -- duplicate that field.
    if R.b480ConfigWrapped~=true then
        R.b480ConfigWrapped=true
        R.b480ExportPre=startup.export_config
        function startup.export_config()
            local data=R.b480ExportPre and R.b480ExportPre() or {}
            if type(data)~="table" then data={} end
            data.killedYouRetaliationEnabled=startup.s.killedYouRetaliationEnabled==true
            data.killedYouRetaliationAutoBounty=startup.s.killedYouRetaliationAutoBounty==true
            data.killedYouRetaliationRule=tostring(startup.s.killedYouRetaliationRule or "once_anytime")
            data.killedYouRetaliationColor=tostring(startup.s.killedYouRetaliationColor or "Dark Red")
            data.killedYouRetaliationNotify=startup.s.killedYouRetaliationNotify==true
            data.killedYouRetaliationMarkDuration=tostring(startup.s.killedYouRetaliationMarkDuration or "session")
            return data
        end

        R.b480ApplyPre=startup.apply_config
        function startup.apply_config(data)
            local ret=R.b480ApplyPre and R.b480ApplyPre(data) or nil
            if type(data)=="table" then
                if data.killedYouRetaliationEnabled~=nil then
                    startup.s.killedYouRetaliationEnabled=data.killedYouRetaliationEnabled==true
                end
                if data.killedYouRetaliationAutoBounty~=nil then
                    startup.s.killedYouRetaliationAutoBounty=data.killedYouRetaliationAutoBounty==true
                end
                local rule=tostring(data.killedYouRetaliationRule or "")
                if validRules[rule] then startup.s.killedYouRetaliationRule=rule end
                local color=tostring(data.killedYouRetaliationColor or "")
                if color~="" then startup.s.killedYouRetaliationColor=color end
                if data.killedYouRetaliationNotify~=nil then
                    startup.s.killedYouRetaliationNotify=data.killedYouRetaliationNotify==true
                end
                local duration=tostring(data.killedYouRetaliationMarkDuration or "")
                if validDurations[duration] then startup.s.killedYouRetaliationMarkDuration=duration end
            end
            return ret
        end
    end
end
